public double squaredEuclideanDistance(Tuple t0, Tuple t1) throws IllegalArgumentException {
    if (t0.getSize() != t1.getSize()) {
        throw new IllegalArgumentException("Tuple sizes do not match.");
    }

    double distance = 0.0;

    for (int i = 0; i < t0.getSize(); i++) {
        double diff = t0.get(i) - t1.get(i);
        distance += diff * diff;
    }

    return distance;
}
