import java.util.*;

public class DFA {

     public CompactDFA minimizeDFA(DFA dfa, Set<Character> alphabet){

        // Initialize partition with two sets: accepting and non-accepting states.
        Set<Set<State>> partition = new HashSet<>();
        Set<State> accepting = new HashSet<>();
        Set<State> nonAccepting = new HashSet<>();

        for(State state : dfa.states()) {
            if(state.isAccepting()) {
                accepting.add(state);
            }else {
                nonAccepting.add(state);
            }
        }

        partition.add(accepting);
        partition.add(nonAccepting);

        boolean partitioned = true;

        while(partitioned) {
            partitioned = false;
            Set<Set<State>> newPartition = new HashSet<>();
            for(Set<State> set : partition) {
                Map<Character, Set<State>> transitions = new HashMap<>();
                for(State state : set) {
                    for(Transition transition : state.getTransitions()) {
                        if(!transitions.containsKey(transition.getInput())) {
                            transitions.put(transition.getInput(), new HashSet<State>());
                        }
                        transitions.get(transition.getInput()).add(transition.getDestination());
                    }
                }
                for(Set<State> subSet : transitions.values()) {
                    if(subSet.size() > 1) {
                        for(Set<State> prevSet : newPartition) {
                            if(prevSet.containsAll(subSet)) {
                                Set<State> others = new HashSet<>(set);
                                others.removeAll(subSet);
                                newPartition.add(subSet);
                                newPartition.add(others);
                                partitioned = true;
                                break;
                            }
                        }
                    } else {
                        newPartition.add(set);
                    }
                }
            }
            partition = newPartition;
        }

        Map<State, Integer> stateMapping = new HashMap<>();
        int i = 0;
        for(Set<State> set : partition) {
            for(State state : set) {
                stateMapping.put(state, i);
            }
            i++;
        }

        // create CompactDFA
        CompactDFA compactDFA = new CompactDFA(partition.size(), alphabet);
        for(State state : dfa.states()) {
            for(Character input : alphabet) {
                compactDFA.addTransition(stateMapping.get(state), input, 
                        stateMapping.get(state.transition(input)));
            }
            compactDFA.setStateAcceptance(stateMapping.get(state), state.isAccepting());
        }

        // prune CompactDFA
        compactDFA.prune();

        return compactDFA;
     }
}
