public void writeStringArrayToByteArray(String[] stringArray) throws IOException {
    ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
    DataOutputStream dataOutputStream = new DataOutputStream(byteArrayOutputStream);

    // Write length of array as an integer to the byte array
    int length = (stringArray == null) ? 0 : stringArray.length;
    dataOutputStream.writeInt(length);

    // Write each string in the array to the byte array as byte array strings
    for (int i = 0; i < length; i++) {
        byte[] stringBytes = (stringArray[i] == null) ? new byte[0] : stringArray[i].getBytes("UTF-8");
        dataOutputStream.writeInt(stringBytes.length);
        dataOutputStream.write(stringBytes);
    }

    dataOutputStream.flush();
    dataOutputStream.close();
    byteArrayOutputStream.flush();
    byteArrayOutputStream.close();

    byte[] byteArray = byteArrayOutputStream.toByteArray();
    // do something with the byteArray
}
