public boolean hasCycle(Node node) {
    Set<Node> visited = new HashSet<Node>();
    Stack<Node> stack = new Stack<Node>();
    stack.push(node);
    while (!stack.isEmpty()) {
        Node current = stack.pop();
        if (visited.contains(current)) {
            return true;
        }
        visited.add(current);
        for (Node neighbor : current.getNeighbors()) {
            stack.push(neighbor);
        }
    }
    return false;
}
