public String insertArgumentsIntoSignature(int index, String[] names, String[] types, String signature) {
    StringBuilder newSignature = new StringBuilder(signature);

    for (int i = 0; i < names.length; i++) {
        newSignature.insert(index, types[i] + " " + names[i] + ", ");
        index += types[i].length() + names[i].length() + 2;
    }

    return newSignature.toString();
}
