import com.google.inject.binder.LinkedBindingBuilder;
import com.google.inject.spi.BindingTargetVisitor;
import com.google.inject.spi.DefaultBindingTargetVisitor;
import org.glassfish.hk2.api.ServiceLocator;
import org.glassfish.hk2.utilities.binding.AbstractBinder;

import java.lang.annotation.Annotation;

public class GuiceToHK2Binder extends AbstractBinder {

  private final Iterable<com.google.inject.Binding> guiceBindings;

  public GuiceToHK2Binder(final Iterable<com.google.inject.Binding> guiceBindings) {
    this.guiceBindings = guiceBindings;
  }

  @Override public void configure() {
    for (final com.google.inject.Binding<?> binding : guiceBindings) {
      final BindingTargetVisitor<Object, Object> realVisitor = new DefaultBindingTargetVisitor() {
        @Override public Object visit(final LinkedBindingBuilder<?> linkedBindingBuilder) {
          // Transpose Guice's LinkedBindingBuilder API onto HK2's Binder API.
          for (final Annotation annotation : linkedBindingBuilder.getAnnotations()) {
            linkedBindingBuilderAnnotatedWith(annotation);
          }
          return to(linkedBindingBuilder.getLinkedKey().getTypeLiteral().getRawType());
        }
      };
      binding.acceptTargetVisitor(realVisitor);
    }
  }

  private <T> LinkedBindingBuilder<T> linkedBindingBuilderAnnotatedWith(
      final Annotation annotation) {
    return bind((Class<T>) annotation.annotationType()).to((Class<T>) annotation.annotationType());
  }

  private <T> LinkedBindingBuilder<T> to(final Class<T> implementation) {
    return bind(implementation).to(implementation);
  }

  @SuppressWarnings("unchecked") <T> LinkedBindingBuilder<T> to(final Class<T> implementation,
      final Class<? extends T> asSubclass) {
    return bind((Class<T>) asSubclass).to(implementation);
  }

  public static void installGuiceBindingsIntoHK2(
      final ServiceLocator serviceLocator,
      final Iterable<com.google.inject.Binding<?>> guiceBindings) {

    final AbstractBinder hk2Binder = new GuiceToHK2Binder(guiceBindings);
    serviceLocator.getService(AbstractBinder.class, hk2Binder);
  }

}
