public void waitForLoadToFinish() throws LionEngineException {
    if (!isLoadingStarted) {
        throw new LionEngineException("Loader has not been started.");
    }
    if (isLoadSkipped) {
        throw new LionEngineException("Loading has been skipped.");
    }
    while (!isLoadFinished) {
        try {
            Thread.sleep(100);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new LionEngineException(e.getMessage());
        }
    }
}
