public static Optional<Type> parseMultipleTypes(String typeComment) {
    if (typeComment == null || typeComment.isEmpty()) {
        return Optional.empty();
    }
    String[] typeAlternatives = typeComment.split(" or ");
    List<Type> types = new ArrayList<>();
    for (String typeAlternative : typeAlternatives) {
        Optional<Type> parsedType = parseType(typeAlternative.trim());
        if (parsedType.isPresent()) {
            types.add(parsedType.get());
        } else {
            return Optional.empty();
        }
    }
    return Optional.of(new OrType(types));
}

