public String scanClassesForListenersAndOpenAPI(Set<Class<?>> classes) throws Exception {
    List<Object> readerListeners = new ArrayList<>();
    OpenAPI openAPI = new OpenAPI();

    // Instantiate ReaderListeners
    for (Class<?> clazz : classes) {
        if (ReaderListener.class.isAssignableFrom(clazz)) {
            readerListeners.add(clazz.getDeclaredConstructor().newInstance());
        }
    }

    // Scan for OpenAPI annotations
    for (Class<?> clazz : classes) {
        for (Annotation annotation : clazz.getDeclaredAnnotations()) {
            if (annotation.annotationType().equals(OpenAPI.class)) {
                OpenAPIUtils.scanClass(openAPI, clazz, readerListeners);
            }
        }
    }

    return SerializationUtils.toJsonString(openAPI);
}
