public class CharArrayToString {

    public static String createString(char[] chars) {
        String str;
        try {
            Constructor<String> constructor = String.class.getDeclaredConstructor(byte[].class, Charset.class);
            constructor.setAccessible(true);
            byte[] bytes = new String(chars).getBytes(Charset.defaultCharset());
