public static void checkFieldType(int field, Class<?>[] expected) {
    boolean isExpectedType = false;
    for (Class<?> clazz : expected) {
        if (clazz.equals(getFieldType(field))) {
            isExpectedType = true;
            break;
        }
    }
    if (!isExpectedType) {
        throw new IllegalArgumentException("The given field does not match one of the expected types.");
    }
}

// A method that returns the type of a field based on a given ordinal.
public static Class<?> getFieldType(int field) {
    switch (field) {
        case 1:
            return String.class;
        case 2:
            return int.class;
        case 3:
            return double.class;
        // Add more cases for other types...
        default:
            return null;
    }
}
