import java.io.File;

public File findFile(String name, String basedir) {
    File file = new File(name);
    if (file.exists()) {
        return file;
    }

    if (basedir != null) {
        file = new File(basedir, name);
        if (file.exists()) {
            return file;
        }
    }

    String[] path = System.getenv("PATH").split(File.pathSeparator);
    for (String dir : path) {
        file = new File(dir, name);
        if (file.exists()) {
            return file;
        }
    }

    return null;
}
