public List<ModelMetrics> fetchAllModelMetrics() {
    List<ModelMetrics> modelMetricsList = new ArrayList<>();

    try (Connection conn = DriverManager.getConnection(DB_URL, DB_USERNAME, DB_PASSWORD);
         PreparedStatement stmt = conn.prepareStatement("SELECT * FROM ModelMetrics")) {

        ResultSet rs = stmt.executeQuery();

        while (rs.next()) {
            ModelMetrics modelMetrics = new ModelMetrics();
            modelMetrics.setModelName(rs.getString("ModelName"));
            modelMetrics.setAccuracy(rs.getFloat("Accuracy"));
            modelMetrics.setPrecision(rs.getFloat("Precision"));
            modelMetrics.setRecall(rs.getFloat("Recall"));
            modelMetricsList.add(modelMetrics);
        }

    } catch (SQLException e) {
        e.printStackTrace();
    }

    return modelMetricsList;
}
