public static String buildPrefixSearchParameter(String input) {
    String[] specialSymbols = { "_", "%" }; // define special symbols
    StringBuilder sb = new StringBuilder(input); // create StringBuilder object from input
    for (int i = 0; i < sb.length(); i++) {
        if (Arrays.asList(specialSymbols).contains(Character.toString(sb.charAt(i)))) { // check if character is a special symbol
            sb.insert(i, "\\"); // insert escape character before special symbol
            i++; // increment index to avoid adding escape character twice
        }
    }
    sb.append("%"); // add '%' at the end
    return sb.toString(); // return prefix search parameter
}
