public void filterStackTrace(Throwable t) {
    StackTraceElement[] stackTrace = t.getStackTrace();
    List<StackTraceElement> filteredStackTrace = new ArrayList<>();
    for (StackTraceElement stackTraceElement : stackTrace) {
        if (!stackTraceElement.getClassName().contains("Reflection") &&
                !stackTraceElement.getClassName().equals(newThrowable.getClass().getName())) {
            filteredStackTrace.add(stackTraceElement);
        }
    }
    t.setStackTrace(filteredStackTrace.toArray(new StackTraceElement[0]));
}
