public static String preciseDuration(Date ref, Date then, int precision) {
    if (ref == null || then == null) {
        return "";
    }

    long durationInMillis = then.getTime() - ref.getTime();
    if (durationInMillis < 0) {
        return "";
    }

    String[] units = {"", "ms", "s", "m", "h", "d"};

    long[] unitValues = new long[]{1L, 1000L, 60L * 1000L, 60L * 60L * 1000L, 24L * 60L * 60L * 1000L};

    StringBuilder result = new StringBuilder();
    int i = units.length - 1, j = 0;

    for (; i > 0 && j < precision; i--) {
        long unitValue = unitValues[i];
        if (durationInMillis >= unitValue) {
            long qty = durationInMillis / unitValue;
            durationInMillis -= qty * unitValue;
            result.append(qty).append(units[i]).append(" ");

            j++;
        }
    }

    return result.toString().trim();
}
