public ViewGroup splitOnColumns(List<String> columnNames, Table originalTable) {
    // Create a new LinearLayout as the parent ViewGroup
    LinearLayout parentView = new LinearLayout(getContext());
    parentView.setOrientation(LinearLayout.HORIZONTAL);

    // Loop through each column name given
    for (String columnName : columnNames) {
        // Make sure the column is a CategoricalColumn
        Column column = originalTable.getColumn(columnName);
        if (!(column instanceof CategoricalColumn)) {
            throw new IllegalArgumentException("Column must be categorical");
        }
        CategoricalColumn categoricalColumn = (CategoricalColumn) column;

        // Create a new ListView for the categorical values in this column
        ListView listView = new ListView(getContext());
        ArrayAdapter<String> adapter = new ArrayAdapter<>(getContext(),
                android.R.layout.simple_list_item_1, categoricalColumn.getValues());
        listView.setAdapter(adapter);

        // Add the ListView to the parent ViewGroup
        parentView.addView(listView);
    }

    return parentView;
}
