public JSONObject incrementProperty(String key) throws JSONException {
    if (!this.has(key)) {
        this.put(key, 1);
    } else {
        Object value = this.get(key);
        if (value instanceof Integer || value instanceof Long || value instanceof Double || value instanceof Float) {
            double newValue = ((Number) value).doubleValue() + 1;
            this.put(key, newValue);
        } else {
            throw new JSONException("Property " + key + " is not a numeric type");
        }
    }
    return this;
}
