    EventNotification eventNotification = parseEventNotification(httpRequest);

    // retrieve the registered handler for the event category and type
    EventHandler eventHandler = retrieveEventHandler(eventNotification);

    // dispatch the event to the registered handler
    try {
        eventHandler.handleEvent(eventNotification);
        return new Response(200, "Event dispatched successfully");
    } catch (EventHandlerException ex) {
        return new Response(500, ex.getMessage());
    }
}

