@Override
public int read(byte[] b, int off, int len) throws IOException {
    int bytesRead = super.read(b, off, len);
    if (bytesRead > 0) {
        totalBytesRead += bytesRead;
        if (totalBytesRead > entrySize) {
            int adjustment = Math.min(bytesRead, (int)(entrySize - (totalBytesRead - bytesRead)));
            if (adjustment > 0) {
                totalBytesRead -= adjustment;
                return adjustment;
            }
        }
    }
    return bytesRead;
}
