public HttpHeaders getResponseHeaders(HttpEntity entity) throws ODataEdmException {
    HttpHeaders responseHeaders = new HttpHeaders();
    if (entity != null) {
        try {
            responseHeaders.setContentLength(entity.getContentLength());
            responseHeaders.setContentType(entity.getContentType().getValue());
            responseHeaders.setETag(entity.getETag());
            responseHeaders.setLastModified(entity.getLastModified());
            responseHeaders.setCacheControl(entity.getCacheControl().toString());
        } catch (IOException e) {
            throw new ODataEdmException("Error building response headers", e);
        }
    }
    return responseHeaders;
} 
