import java.util.Random;

public static long[] generateRandomLongValues(long start, long end, int size) {
    long[] result = new long[size];
    Random random = new Random();
    for (int i = 0; i < size; ++i) {
        result[i] = random.nextLong() % (end - start + 1) + start;
    }
    return result;
}
