import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.Date;
import java.util.Random;

public class RandomDateUtils {

    private static final Instant MAX_INSTANT = Instant.parse("1000000000-12-31T23:59:59.999999999Z");

    public static Date getRandomDateAfter(Date after) {
        if (after == null || after.toInstant().isAfter(MAX_INSTANT)) {
            throw new IllegalArgumentException();
        }
        Instant afterInstant = after.toInstant();
        Instant randomInstant = afterInstant.plus(new Random().nextInt(365), ChronoUnit.DAYS);
        return Date.from(randomInstant);
    }
}
