import java.lang.annotation.Annotation;
import java.lang.reflect.Field;
import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;

import org.openqa.selenium.By;
import org.openqa.selenium.support.FindAll;
import org.openqa.selenium.support.FindBy;
import org.openqa.selenium.support.FindBys;

public static By getByAnnotation(Field field) throws IllegalArgumentException {
    List<Annotation> annotations = Arrays.asList(field.getAnnotations());
    List<Annotation> byAnnotations = annotations.stream()
            .filter(annotation -> annotation instanceof FindBy
                    || annotation instanceof FindBys
                    || annotation instanceof FindAll)
            .collect(Collectors.toList());
    if (byAnnotations.isEmpty()) {
        return By.id(field.getName()).or(By.name(field.getName()));
    } else if (byAnnotations.size() > 1) {
        throw new IllegalArgumentException("More than one annotation on field provided.");
    } else {
        Annotation byAnnotation = byAnnotations.get(0);
        if (byAnnotation instanceof FindBy) {
            FindBy findBy = (FindBy) byAnnotation;
            if (!findBy.id().isEmpty()) {
                return By.id(findBy.id());
            } else if (!findBy.name().isEmpty()) {
                return By.name(findBy.name());
            } else if (!findBy.className().isEmpty()) {
                return By.className(findBy.className());
            } else if (!findBy.css().isEmpty()) {
                return By.cssSelector(findBy.css());
            } else if (!findBy.linkText().isEmpty()) {
                return By.linkText(findBy.linkText());
            } else if (!findBy.partialLinkText().isEmpty()) {
                return By.partialLinkText(findBy.partialLinkText());
            } else if (!findBy.tagName().isEmpty()) {
                return By.tagName(findBy.tagName());
            } else if (!findBy.xpath().isEmpty()) {
                return By.xpath(findBy.xpath());
            }
        } else if (byAnnotation instanceof FindBys) {
            FindBys findBys = (FindBys) byAnnotation;
            return new ByChained(Arrays.asList(findBys.value())
                    .stream()
                    .map(by -> getBy(findBy))
                    .collect(Collectors.toList()));
        } else if (byAnnotation instanceof FindAll) {
            FindAll findAll = (FindAll) byAnnotation;
            return new ByAll(Arrays.asList(findAll.value())
                    .stream()
                    .map(by -> getBy(findAll))
                    .collect(Collectors.toList()));
        }
    }
}
