public static Map<String, FieldDescriptor> inspectFields(Object obj) {
    Map<String, FieldDescriptor> fieldDescriptors = new HashMap<>();
    Class clazz = obj.getClass();
    Field[] fields = clazz.getDeclaredFields();
    for (Field field : fields) {
        String name = field.getName();
        Class<?> type = field.getType();
        boolean isAccessible = field.isAccessible();
        field.setAccessible(true);
        Object value = null;
        try {
            value = field.get(obj);
        } catch (IllegalAccessException e) {
            // Handle exception
        }
        field.setAccessible(isAccessible);
        FieldDescriptor descriptor = new FieldDescriptor(name, type, value);
        fieldDescriptors.put(name, descriptor);
    }
    return fieldDescriptors;
}
