public boolean renderCode(Container component, Writer rw) throws IOException {
   boolean hasRendered = false;
   Component[] children = component.getComponents();
   for (Component child : children) {
      if (child instanceof Container) {
         hasRendered |= renderCode((Container) child, rw);
      } else if (child instanceof JTextComponent) {
         ((JTextComponent) child).setEditable(false);
         rw.write(child.toString());
         hasRendered = true;
      } else if (child instanceof AbstractButton) {
         ((AbstractButton) child).setEnabled(false);
         rw.write(child.toString());
         hasRendered = true;
      } else {
         rw.write(child.toString());
      }
   }
   return hasRendered;
}
