import java.util.Collections;
import java.util.List;
import java.util.stream.Collectors;

import com.sun.tools.javac.tree.JCTree.*;

public List<List<JCTree>> findDisjointMatches(JCTree tree) {
    if (tree instanceof JCBlock) {
        JCBlock block = (JCBlock) tree;
        List<JCTree> templateStatements = block.stats.stream()
                .filter(stat -> isTemplateStatement(stat)) // let's assume there's a helper method isTemplateStatement
                .collect(Collectors.toList());

        List<List<JCTree>> disjointMatches = new ArrayList<>();

        for (int i=0; i<templateStatements.size(); i++) {
            JCTree startStatement = templateStatements.get(i);
            List<JCTree> match = new ArrayList<>();
            match.add(startStatement);

            for (int j=i+1; j<templateStatements.size(); j++) {
                JCTree next = templateStatements.get(j);
                if (next.getStartPosition() != ((JCTree) match.get(match.size()-1)).getStartPosition() + ((JCTree) match.get(match.size()-1)).getEndPosition()) {
                    break;
                } else {
                    match.add(next);
                    i++;
                }
            }

            disjointMatches.add(Collections.unmodifiableList(match));
        }

        return Collections.unmodifiableList(disjointMatches);
    } else {
        return Collections.emptyList();
    }
}
