public Node copyNode(Document owner, short operation, Node node, boolean deep){
    Node copiedNode = null;
    if(node != null){
        copiedNode = owner.adoptNode(node.cloneNode(false));
        if(deep){
            NodeList nodeList = node.getChildNodes();
            for(int i = 0; i < nodeList.getLength(); i++){
                Node child = nodeList.item(i);
                Node copiedChild = copyNode(owner, operation, child, deep);
                copiedNode.appendChild(copiedChild);
            }
        }
    }
    return copiedNode;
}
