public void cancelHadoopTokens(Logger logger) {
  try {
    // Get the current user's credentials
    UserGroupInformation ugi = UserGroupInformation.getCurrentUser();

    // Get the tokens for the current user
    Collection<Token<? extends TokenIdentifier>> tokens = ugi.getCredentials().getAllTokens();

    // Cancel each token
    for (Token<? extends TokenIdentifier> token : tokens) {
      token.cancel();
      logger.info("Cancelled token: " + token);
    }
  } catch (IOException e) {
    logger.error("Error cancelling Hadoop tokens: " + e.getMessage());
  }
}
