import org.bouncycastle.openpgp.PGPSecretKey;
import org.bouncycastle.openpgp.PGPSecretKeyRingCollection;
import org.bouncycastle.openpgp.PGPException;
import org.bouncycastle.openpgp.PGPKeyRingCollection;

public PGPSecretKey retrieveSecretKey(PGPSecretKeyRingCollection secretKeyRingCollection, 
                                      String keyFilter) throws PGPException {
    for (PGPSecretKeyRing secretKeyRing : secretKeyRingCollection) {
        for (PGPSecretKey secretKey : secretKeyRing.getSecretKeys()) {
            if (secretKey.isSigningKey() && secretKey.toString().contains(keyFilter)) {
                return secretKey;
            }
        }
    }
    return null;
}
