public double getMaxDistance(Stack<DistanceNode> v) {
    double maxDistance = Double.MIN_VALUE;
    DistanceNode parent = v.pop();
    while (!v.isEmpty()) {
        DistanceNode child = v.pop();
        double distance = Math.sqrt(Math.pow(parent.getX() - child.getX(), 2) + Math.pow(parent.getY() - child.getY(), 2));
        if (distance > maxDistance) {
            maxDistance = distance;
        }
    }
    return maxDistance;
}
