public List<Notification> fetchNotificationsFromPrefs(SharedPreferences sharedPreferences) {
    int notificationCount = sharedPreferences.getInt("PREFS_NOTIFICATION_COUNT", 0);
    List<Notification> notifications = new ArrayList<>();
    for (int i = 0; i < notificationCount; i++) {
        String notificationString = sharedPreferences.getString("PREFS_NOTIFICATION_" + i, "");
        if (!notificationString.isEmpty()) {
            Notification notification = Notification.fromString(notificationString);
            if (notification != null) {
                notifications.add(notification);
            }
        }
    }
    return notifications;
}
