public void addNodeFieldsToDoc(Document doc, String namespaceURI, String localName) throws RepositoryException {
    if (indexFormatVersion == 1) {
        doc.add(new StringField("nodeName", localName, Field.Store.YES));
    } else if (indexFormatVersion == 2) {
        doc.add(new StringField("namespaceURI", namespaceURI, Field.Store.YES));
        doc.add(new StringField("localName", localName, Field.Store.YES));
    } else {
        throw new RepositoryException("Unsupported index format version: " + indexFormatVersion);
    }
}
