public double percentOverlap(Location other) throws IllegalArgumentException {
    if (!strand.equals(other.strand)) {
        throw new IllegalArgumentException("Locations are on opposite strands.");
    }
    int intersectionLength = intersection(other).length();
    int thisLength = length();
    return 100.0 * intersectionLength / thisLength;
}
