public List<Sequence> readGenbankFile(File file, boolean lazySequenceLoad) throws Exception {
    List<Sequence> sequences = new ArrayList<>();
    BufferedReader reader = new BufferedReader(new FileReader(file));
    String line;
    Sequence currentSequence = null;
    while ((line = reader.readLine()) != null) {
        if (line.startsWith("LOCUS")) {
            if (currentSequence != null) {
                sequences.add(currentSequence);
            }
            currentSequence = new Sequence();
            String[] locusParts = line.split(" +");
            currentSequence.setAccessionId(locusParts[1]);
            currentSequence.setLength(Integer.parseInt(locusParts[2]));
        } else if (line.startsWith("ORIGIN")) {
            StringBuilder sequenceBuilder = new StringBuilder();
            while ((line = reader.readLine()) != null && !line.startsWith("//")) {
                sequenceBuilder.append(line.replaceAll("[0-9 ]", ""));
            }
            currentSequence.setSequence(sequenceBuilder.toString());
            if (lazySequenceLoad) {
                long offset = reader.getFilePointer();
                currentSequence.setOffset(offset);
            }
        }
    }
    reader.close();
    if (currentSequence != null) {
        sequences.add(currentSequence);
    }
    return sequences;
}
