public boolean isListOlderThan(int seconds, List<?> list) {
    long currentTime = System.currentTimeMillis();
    long oldestTime = currentTime - (seconds * 1000);
    if (!list.isEmpty()) {
        Object oldestObject = list.get(0);
        for (Object object : list) {
            if (object != null && object instanceof Date) {
                Date objectDate = (Date) object;
                if (objectDate.getTime() < oldestObject.getTime()) {
                    oldestObject = objectDate;
                }
            }
        }
        return oldestObject.getTime() < oldestTime;
    }
    return true;
}
