public void decreaseKey(Node n, int newKey) {
    if (newKey > n.key) {
        throw new IllegalArgumentException("New key is greater than current key");
    }
    n.key = newKey;
    // Perform heap operations to maintain heap property
    while (n.parent != null && n.key < n.parent.key) {
        // Swap node with its parent
        int temp = n.key;
        n.key = n.parent.key;
        n.parent.key = temp;
        n = n.parent;
    }
}
