public List<ImageDTO> extractImageData(Cursor cursor, int offset, int limit) {
    // First, move the cursor to the initial position
    cursor.moveToPosition(offset);

    List<ImageDTO> imageDTOList = new ArrayList<>();
    int i = 0;
    while (cursor.moveToNext() && i++ < limit) {
        // Extract the image data from the cursor and create an ImageDTO object
        ImageDTO imageDTO = new ImageDTO();
        imageDTO.setImageUrl(cursor.getString(cursor.getColumnIndexOrThrow("imageUrl")));
        imageDTO.setImageTitle(cursor.getString(cursor.getColumnIndexOrThrow("imageTitle")));
        imageDTO.setImageDescription(cursor.getString(cursor.getColumnIndexOrThrow("imageDescription")));

        // Add the ImageDTO object to the list
        imageDTOList.add(imageDTO);
    }

    return imageDTOList;
}
