public class MyObject implements Comparable<MyObject> {

    private double networkCost;
    private double diskCost;
    private double cpuCost;

    public MyObject(double networkCost, double diskCost, double cpuCost) {
        this.networkCost = networkCost;
        this.diskCost = diskCost;
        this.cpuCost = cpuCost;
    }

    @Override
    public int compareTo(MyObject other) {
        int result = 0;

        // Compare by network cost first
        if (this.networkCost < other.networkCost) {
            result = -1;
        } else if (this.networkCost > other.networkCost) {
            result = 1;
        }

        // If network cost is tied, compare by disk cost
        if (result == 0) {
            if (this.diskCost < other.diskCost) {
                result = -1;
            } else if (this.diskCost > other.diskCost) {
                result = 1;
            }
        }

        // If disk cost is tied, compare by CPU cost
        if (result == 0) {
            if (this.cpuCost < other.cpuCost) {
                result = -1;
            } else if (this.cpuCost > other.cpuCost) {
                result = 1;
            }
        }

        return result;
    }
}
