@Override
public int distanceSquared(int x1, int y1, int z1, int w1) {
    int dx = this.x - x1;
    int dy = this.y - y1;
    int dz = this.z - z1;
    int dw = this.w - w1;
    return dx * dx + dy * dy + dz * dz + dw * dw;
}
