public String fetchAppfwprofileCookieConsistencyBinding(String name) {
    // Assuming the API endpoint is http://example.com/api/appfwprofile_cookieconsistency_binding
    String apiUrl = "http://example.com/api/appfwprofile_cookieconsistency_binding?name=" + name;

    try {
        URL url = new URL(apiUrl);
        HttpURLConnection con = (HttpURLConnection) url.openConnection();
        con.setRequestMethod("GET");

        BufferedReader in = new BufferedReader(new InputStreamReader(con.getInputStream()));
        String inputLine;
        StringBuffer response = new StringBuffer();

        while ((inputLine = in.readLine()) != null) {
            response.append(inputLine);
        }
        in.close();
        return response.toString();
    } catch (Exception e) {
        e.printStackTrace();
        return null;
    }
}
