public String getSubstitutedProperty(String value, Function<String, String> propertyAccessor) {
    if (value != null && !value.isEmpty()) {
        int startIndex = value.indexOf("${");
        while (startIndex >= 0) {
            int endIndex = value.indexOf("}", startIndex);
            if (endIndex > startIndex) {
                String propertyName = value.substring(startIndex + 2, endIndex);
                String propertyValue = propertyAccessor.apply(propertyName);
                if (propertyValue != null) {
                    value = value.substring(0, startIndex) + propertyValue + value.substring(endIndex + 1);
                    startIndex = value.indexOf("${", startIndex + propertyValue.length());
                } else {
                    startIndex = value.indexOf("${", endIndex + 1);
                }
            } else {
                startIndex = -1;
            }
        }
    }
    return value;
}
