public WebElement findElement(String place) {
    List<WebElement> elements = new ArrayList<>();
    elements.add(driver.findElement(By.id(place)));
    elements.add(driver.findElement(By.name(place)));
    elements.add(driver.findElement(By.xpath("//*[@id='" + place + "']")));
    elements.add(driver.findElement(By.xpath("//*[@name='" + place + "']")));

    for (WebElement element : elements) {
        if (element.isDisplayed() && element.isEnabled()) {
            return element;
        }
    }

    return elements.get(0);
}
