import org.apache.logging.log4j.Level;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;
import org.apache.logging.log4j.core.LoggerContext;
import org.apache.logging.log4j.core.appender.ConsoleAppender;
import org.apache.logging.log4j.core.appender.SyslogAppender;
import org.apache.logging.log4j.core.config.Configuration;
import org.apache.logging.log4j.core.config.ConfigurationFactory;
import org.apache.logging.log4j.core.config.ConfigurationSource;
import org.apache.logging.log4j.core.config.builder.api.ConfigurationBuilder;
import org.apache.logging.log4j.core.config.builder.impl.BuiltConfiguration;
import org.apache.logging.log4j.core.config.builder.impl.DefaultConfigurationBuilderFactory;

import java.io.IOException;
import java.net.InetSocketAddress;

public class LoggingConfigurator {

    public static void configure(String ident, Level level, boolean replaceNewLines)
            throws IOException {

        final LoggerContext loggerContext = (LoggerContext) LogManager.getContext(false);
        final Configuration configuration = loggerContext.getConfiguration();

        final ConfigurationBuilder<BuiltConfiguration> builder =
                new DefaultConfigurationBuilderFactory().newConfigurationBuilder();

        builder.setStatusLevel(Level.ERROR);
        builder.setConfigurationName("default");
        builder.add(builder.newFilter("ThresholdFilter", Filter.Result.ACCEPT, Filter.Result.NEUTRAL)
                .addAttribute("level", Level.DEBUG));

        final ConsoleAppender.Builder consoleAppender = builder.newAppender("Stdout", "CONSOLE")
                .addAttribute("target", ConsoleAppender.Target.SYSTEM_ERR);
        builder.add(consoleAppender);

        if(System.getenv("SPOTIFY_SYSLOG_HOST") != null && System.getenv("SPOTIFY_SYSLOG_PORT") != null){
            final String syslogHost = System.getenv("SPOTIFY_SYSLOG_HOST");
            final int syslogPort = Integer.parseInt(System.getenv("SPOTIFY_SYSLOG_PORT"));

            final SyslogAppender.Builder syslogAppenderBuilder = builder.newAppender("Syslog",
                    "SYSLOG").addAttribute("host", syslogHost)
                    .addAttribute("port", syslogPort)
                    .addAttribute("protocol", "TCP")
                    .addAttribute("ignoreExceptions", true)
                    .addAttribute("localhost", "localhost")
                    .addAttribute("facility", "LOCAL0");

            builder.add(syslogAppenderBuilder);
        }
        else{
            builder.add(consoleAppender);
        }

        builder.add(builder.newLogger(ident, level)
                .add(builder.newAppenderRef("Stdout"))
                .add(builder.newAppenderRef("Syslog"))
                .addAttribute("additivity", false));

        builder.add(builder.newRootLogger(level)
                .add(builder.newAppenderRef("Stdout"))
                .add(builder.newAppenderRef("Syslog")));

        final Configuration sourceConfig = builder.build();
        loggerContext.start(sourceConfig);

        final Logger logger = LogManager.getLogger(ident);
        logger.info("Logging configured with config {}",
                sourceConfig.getConfigurationSource().getLocation());

    }
}
