public void listenForMessages(ConnectionContext context, MessageListener listener) throws JMSException {
    Connection connection = ConnectionContextFactory.createConsumerConnectionContext(context).getConnection();
    Session session = connection.createSession(false, Session.AUTO_ACKNOWLEDGE);
    Destination destination = session.createQueue(context.getDestinationName());
    MessageConsumer consumer = session.createConsumer(destination);
    consumer.setMessageListener(listener);
    connection.start();
}
