public static Method getImplementingMethod(Class<?> clazz, Method intfMethod) {
    if (clazz == null || intfMethod == null) {
        return null;
    }
    Method[] methods = clazz.getDeclaredMethods();
    for (Method method : methods) {
        if (method.getName().equals(intfMethod.getName()) && Arrays.equals(method.getParameterTypes(), intfMethod.getParameterTypes())) {
            return method;
        }
    }
    Class<?> superClazz = clazz.getSuperclass();
    if (superClazz != null) {
        return getImplementingMethod(superClazz, intfMethod);
    }
    return null;
}
