public void insertNode(Tree root, Interval interval, int value) {
   if (root == null) {
      root = new Tree(interval, value);
   } else if (interval.start < root.interval.start) {
      insertNode(root.left, interval, value);
   } else if (interval.start > root.interval.start) {
      insertNode(root.right, interval, value);
   } else {
      root.value = value;
   }
}
