public static double getSkewnessUsingSampleVariance(double[] array) {
    double mean = getMean(array);
    double variance = getSampleVariance(array);
    double skewness = 0.0;
    int n = array.length;
    for (int i = 0; i < n; i++) {
        skewness += Math.pow((array[i] - mean), 3);
    }
    skewness = (skewness / n) / Math.pow(variance, 1.5);
    return skewness;
}

private static double getMean(double[] array) {
    double sum = 0.0;
    int n = array.length;
    for (int i = 0; i < n; i++) {
        sum += array[i];
    }
    return sum / n;
}

private static double getSampleVariance(double[] array) {
    double mean = getMean(array);
    double variance = 0.0;
    int n = array.length;
    for (int i = 0; i < n; i++) {
        variance += Math.pow((array[i] - mean), 2);
    }
    variance /= (n - 1);
    return variance;
}
