public void dumpStream(InputStream inputStream) throws IOException {
    byte[] buffer = new byte[1024];
    int bytesRead;
    while ((bytesRead = inputStream.read(buffer)) != -1) {
        System.out.write(buffer, 0, bytesRead);
    }
    inputStream.close();
}
