public void parseCommands(String[] args) throws Exception {
    List<String> nonGroupedCommands = new ArrayList<>();
    Map<String, List<String>> groupedCommands = new HashMap<>();
    String currentGroup = null;

    for (String arg : args) {
        if (arg.startsWith("--")) {
            if (currentGroup != null) {
                groupedCommands.computeIfAbsent(currentGroup, k -> new ArrayList<>()).add(arg);
            } else {
                nonGroupedCommands.add(arg);
            }
        } else if (arg.startsWith("-")) {
            currentGroup = arg.substring(1);
        } else {
            if (currentGroup != null) {
                groupedCommands.computeIfAbsent(currentGroup, k -> new ArrayList<>()).add(arg);
                currentGroup = null;
            } else {
                nonGroupedCommands.add(arg);
            }
        }
    }

    if (!groupedCommands.isEmpty()) {
        // handle grouped commands
        for (Map.Entry<String, List<String>> entry : groupedCommands.entrySet()) {
            String group = entry.getKey();
            List<String> subCommands = entry.getValue();

            switch (group) {
                case "group1":
                    handleGroup1(subCommands);
                    break;
                case "group2":
                    handleGroup2(subCommands);
                    break;
                // add more groups as needed
                default:
                    throw new Exception("Unknown command group: " + group);
            }
        }
    } else {
        // handle non-grouped commands
        handleNonGroupedCommands(nonGroupedCommands);
    }
}

private void handleGroup1(List<String> subCommands) {
