public static String convertDnaToProtein(String dnaSequence) {
    final int CODON_LENGTH = 3;
    Map<String, String> codonTable = getCodonTable();

    StringBuilder proteinSequence = new StringBuilder();

    for (int i = 0; i < dnaSequence.length(); i += CODON_LENGTH) {
        String codon = dnaSequence.substring(i, i + CODON_LENGTH);

        if (codonTable.containsKey(codon)) {
            proteinSequence.append(codonTable.get(codon));
        }
    }

    return proteinSequence.toString();
}

