public static double[][] choleskyDecomposition(double[][] A) {

    int n = A.length;
    double[][] L = new double[n][n];

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < (i+1); j++) {
            double sum = 0.0;
            for (int k = 0; k < j; k++) {
                sum += L[i][k] * L[j][k];
            }
            if (i == j) {
                L[i][j] = Math.sqrt(A[i][i] - sum);
            } else {
                L[i][j] = (1.0 / L[j][j] * (A[i][j] - sum));
            }
        }
    }
    return L;
}
