public static String getDescriptor(Class<?> returnType, Class<?>... argumentTypes) {
    StringBuilder descriptorBuilder = new StringBuilder("(");
    for (Class<?> argType : argumentTypes) {
        descriptorBuilder.append(getTypeDescriptor(argType));
    }
    descriptorBuilder.append(')');
    descriptorBuilder.append(getTypeDescriptor(returnType));
    return descriptorBuilder.toString();
}

private static String getTypeDescriptor(Class<?> type) {
    if (type.isPrimitive()) {
        if (type == void.class) {
            return "V";
        } else if (type == int.class) {
            return "I";
        } else if (type == long.class) {
            return "J";
        } else if (type == float.class) {
            return "F";
        } else if (type == double.class) {
            return "D";
        } else if (type == boolean.class) {
            return "Z";
        } else if (type == byte.class) {
            return "B";
        } else if (type == char.class) {
            return "C";
        } else {
            return "S";
        }
    } else if (type.isArray()) {
        return "[" + getTypeDescriptor(type.getComponentType());
    } else {
        return "L" + type.getName().replace('.', '/') + ";";
    }
}
