public static int convertWavelengthToRGB(double wavelength) {
    int R = 0, G = 0, B = 0;
    if (wavelength >= 380 && wavelength < 440) {
        R = -(int) ((wavelength - 440) / (440 - 380) * 255);
        B = 255;
    } else if (wavelength >= 440 && wavelength < 490) {
        G = (int) ((wavelength - 440) / (490 - 440) * 255);
        B = 255;
    } else if (wavelength >= 490 && wavelength < 510) {
        G = 255;
        B = -(int) ((wavelength - 510) / (510 - 490) * 255);
    } else if (wavelength >= 510 && wavelength < 580) {
        R = (int) ((wavelength - 510) / (580 - 510) * 255);
        G = 255;
    } else if (wavelength >= 580 && wavelength < 645) {
        R = 255;
        G = -(int) ((wavelength - 645) / (645 - 580) * 255);
    } else if (wavelength >= 645 && wavelength <= 780) {
        R = 255;
    }
    int color = (R << 16) | (G << 8) | B;
    return color;
}
