public long safeToNanos(TimeUnit unit, long time) {
    long nanos = unit.toNanos(time);
    if (nanos <= 0) {
        return 0;
    } else if (nanos >= (Long.MAX_VALUE / 4) * 3) {
        return (Long.MAX_VALUE / 4) * 3;
    } else {
        return nanos;
    }
}
