public static ProductPartitionNode copyCustomParameters(BiddableAdGroupCriterion biddableCriterion, ProductPartitionNode node) {
    if (biddableCriterion == null || node == null) {
        return node;
    }
    List<CustomParameter> customParameters = biddableCriterion.getCustomParameters();
    if (customParameters != null && !customParameters.isEmpty()) {
        List<CustomParameter> nodeCustomParameters = new ArrayList<>();
        for (CustomParameter customParameter : customParameters) {
            nodeCustomParameters.add(customParameter);
        }
        node.setCustomParameters(nodeCustomParameters);
    }
    return node;
}
