import java.util.Comparator;

public class JobIdComparator implements Comparator<String> {
    @Override
    public int compare(String jobId1, String jobId2) {
        String[] parts1 = jobId1.split("_");
        String[] parts2 = jobId2.split("_");
        int compare = parts1[0].compareTo(parts2[0]);
        if (compare != 0) {
            return compare;
        }
        int jobNumber1 = Integer.parseInt(parts1[1]);
        int jobNumber2 = Integer.parseInt(parts2[1]);
        return Integer.compare(jobNumber1, jobNumber2);
    }
}
