public Constructor<?> findInnerClassConstructor(Class<?> klazz, Class<?> declaringClass) {
    if (klazz == null || declaringClass == null) {
        throw new IllegalArgumentException("Both klazz and declaringClass must not be null.");
    }

    Constructor<?>[] constructors = klazz.getDeclaredConstructors();
    for (Constructor<?> constructor : constructors) {
        if (constructor.getDeclaringClass().equals(declaringClass)) {
            constructor.setAccessible(true);
            return constructor;
        }
    }

    throw new IllegalArgumentException("Constructor for inner class not found.");
}
