import javax.tools.*;
import java.lang.reflect.*;
import java.util.*;

public class Evaluator<T> {

    private final Expression expression;

    private final Map<String, Class> parameterTypes;

    private final Map<String, Object> constants;

    public static <T> Evaluator<T> create(String source, Class<T> projection, String[] names, Class[] types,
                                          Map<String, Object> constants) throws Exception {
        JavaCompiler compiler = ToolProvider.getSystemJavaCompiler();

        DiagnosticCollector<JavaFileObject> diagnosticsCollector = new DiagnosticCollector<>();
        StandardJavaFileManager fileManager = compiler.getStandardFileManager(diagnosticsCollector, null, null);

        String className = UUID.randomUUID().toString().replace("-", "");
        Iterable<? extends JavaFileObject> compilationUnits = prepareCompilationUnits(className, source);

        CompilationTask task = compiler.getTask(null, fileManager, diagnosticsCollector, null, null, compilationUnits);
        boolean success = task.call();

        if (!success) {
            throw new Exception("Unable to compile expression: " + source);
        }

        fileManager.close();

        Class<?> generatedClass = Class.forName(className);
        Class<?>[] parameterTypes = buildParameterTypes(names, types);

        Map<String, Object> constantsWitCorrectTypes = new HashMap<>();
        for (String key : constants.keySet()) {
            Object value = constants.get(key);
            if (value != null) {
                constantsWitCorrectTypes.put(key, convertToCorrectType(value, value.getClass()));
            } else {
                constantsWitCorrectTypes.put(key, null);
            }
        }

        Expression expression = new Expression(generatedClass.getDeclaredMethod("eval", parameterTypes),
                new HashSet<>(constants.keySet()));

        return new Evaluator<>(expression, buildParameterTypeMap(names, types), constantsWitCorrectTypes);
    }

    private static Iterable<? extends JavaFileObject> prepareCompilationUnits(String className, String source) {
        StringBuilder stringBuilder = new StringBuilder();
        stringBuilder.append("public class ").append(className).append(" {\n");
        stringBuilder.append("\tpublic Object eval(");

        // generate parameters
        String[] paramsArray = source.substring(0, source.indexOf(')') + 1).split(",");
        String parameters = String.join(",", Arrays.copyOfRange(paramsArray, 0, paramsArray.length - 1)) + ")";
        stringBuilder.append(parameters).append(" {\n");

        // generate expression source
        String expression = source.substring(source.indexOf('{') + 1, source.lastIndexOf('}')).trim();
        stringBuilder.append(expression);

        stringBuilder.append("\n\t}\n}");

        List<JavaFileObject> compilationUnits = new ArrayList<>();
        compilationUnits.add(new JavaSourceFromString(className, stringBuilder.toString()));
        return compilationUnits;
    }

    private static Class<?>[] buildParameterTypes(String[] names, Class[] types) {
        Class<?>[] parameterTypes = new Class[names.length];
        for (int i = 0; i < names.length; i++) {
            parameterTypes[i] = types[i];
        }
        return parameterTypes;
    }

    private static Map<String, Class> buildParameterTypeMap(String[] names, Class[] types) {
        Map<String, Class> parameterTypeMap = new HashMap<>();
        for (int i = 0; i < names.length; i++) {
            parameterTypeMap.put(names[i], types[i]);
        }
        return parameterTypeMap;
    }

    private static Object convertToCorrectType(Object value, Class<?> expectedType) {
        if (expectedType == int.class || expectedType == Integer.class) {
            return Integer.parseInt(value.toString());
        } else if (expectedType == long.class || expectedType == Long.class) {
            return Long.parseLong(value.toString());
        } else if (expectedType == float.class || expectedType == Float.class) {
            return Float.parseFloat(value.toString());
        } else if (expectedType == double.class || expectedType == Double.class) {
            return Double.parseDouble(value.toString());
        } else if (expectedType == boolean.class || expectedType == Boolean.class) {
            return Boolean.parseBoolean(value.toString());
        } else if (expectedType == String.class) {
            return value.toString();
        } else {
            return value;
        }
    }

    private Evaluator(Expression expression, Map<String, Class> parameterTypes, Map<String, Object> constants) {
        this.expression = expression;
        this.parameterTypes = parameterTypes;
        this.constants = constants;
    }

    public T evaluate(Object... parameters) throws Exception {
        if (parameters.length != parameterTypes.size()) {
            throw new IllegalArgumentException("Invalid number of parameters. Expected " + parameterTypes.size() +
                    " but found " + parameters.length);
        }

        for (int i = 0; i < parameters.length; i++) {
            String paramName = getKeyForIndex(i);
            Class<?> paramType = parameterTypes.get(paramName);
            Object value = parameters[i];

            if (!paramType.isInstance(value)) {
                throw new IllegalArgumentException("Invalid parameter type for " + paramName + ". Expected " +
                        paramType + " but found " + value.getClass());
            }
        }

        Map<String, Object> evaluatedConstants = new HashMap<>();
        for (String key : constants.keySet()) {
            Object value = constants.get(key);

            if (value instanceof String) {
                evaluatedConstants.put(key, parameterTypes.get(key).cast(value));
            } else {
                evaluatedConstants.put(key, value);
            }
        }

        return (T) expression.invoke(parameters, evaluatedConstants);
    }

    private String getKeyForIndex(int index) {
        int i = 0;
        for (String key : parameterTypes.keySet()) {
            if (i == index) {
                return key;
            }
            i++;
        }

        throw new IllegalArgumentException("Invalid parameter index: " + index);
    }

    private static class Expression {
        private final Method method;
        private final Set<String> constants;

        public Expression(Method method, Set<String> constants) {
            this.method = method;
            this.constants = constants;
        }

        public Object invoke(Object[] params, Map<String, Object> constants) throws Exception {
            try {
                Object[] args = new Object[params.length + constants.size()];

                int i = 0;
                for (String key : constants.keySet()) {
                    args[i++] = constants.get(key);
                }

                for (Object param : params) {
                    args[i++] = param;
                }

                return method.invoke(null, args);
            } catch (InvocationTargetException e) {
                Throwable cause = e.getCause();
                throw cause != null ? new RuntimeException("Error evaluating expression", cause) :
                        new RuntimeException("Error evaluating expression", e);
            }
        }

        public Set<String> getConstants() {
            return constants;
        }
    }

    private static class JavaSourceFromString extends SimpleJavaFileObject {
        final String code;

        JavaSourceFromString(String name, String code) {
            super(URI.create("string:///" + name.replace('.', '/') + Kind.SOURCE.extension), Kind.SOURCE);
            this.code = code;
        }

        @Override
        public CharSequence getCharContent(boolean ignoreEncodingErrors) {
            return code;
        }
    }
}
