public static String assemblePath(String... paths) {
    StringBuilder sb = new StringBuilder();
    for (String path : paths) {
        if (path != null) {
            if (!path.startsWith("/") && sb.length() > 0 && sb.charAt(sb.length() - 1) != '/') {
                sb.append('/');
            }
            sb.append(path.replaceAll("/$", ""));
        }
    }
    return sb.toString();
}
