public static void submitJob(Configuration conf) throws IOException {
    // create a new Job object with the provided configuration
    Job job = Job.getInstance(conf);

    // modify the job to use MapReduce pipes
    job.getConfiguration().set("mapreduce.framework.name", "yarn");
    job.getConfiguration().set("mapreduce.job.mapper.class", "org.apache.hadoop.mapred.pipes.PipesMapper");
    job.getConfiguration().set("mapreduce.job.reducer.class", "org.apache.hadoop.mapred.pipes.PipesReducer");
    job.getConfiguration().set("mapreduce.job.jar", "pipe.jar");

    // submit the job to the cluster and wait for it to complete
    job.submit();
    job.waitForCompletion(true);
}
