import java.io.File;
import java.nio.file.FileAlreadyExistsException;

public void renameDirectory(String oldName, String newName) throws PageException {
    File directoryToRename = new File(oldName);
    if (!directoryToRename.exists()) {
        throw new PageException("Directory does not exist.");
    }
    File renamedDirectory = new File(newName);
    if (renamedDirectory.exists()) {
        throw new PageException("Directory already exists with the given name.");
    }
    boolean success = directoryToRename.renameTo(renamedDirectory);
    if (!success) {
        throw new PageException("Failed to rename directory.");
    }
}
