public List<String> processScannerMatches(List<String> matches, IHttpRequestResponse baseRequestResponse) {
    List<String> reportableIssues = new ArrayList<String>();

    if(matches != null && baseRequestResponse != null) {
        for (String match : matches) {
            if(match != null && !match.isEmpty()) {
                reportableIssues.add(match);
            }
        }

        if(reportableIssues.isEmpty()) {
            reportableIssues = null;
        }
    }

    return reportableIssues;
}
