public Geometry getLatLongGeometry(WorldWindow wwd, double x1, double y1, double x2, double y2) {
    View view = wwd.getView();
    Globe globe = wwd.getModel().getGlobe();

    // Convert the screen coordinates to geographic coordinates
    Position pos1 = view.computePositionFromScreenPoint(x1, y1);
    Position pos2 = view.computePositionFromScreenPoint(x2, y2);

    // Create a line between the two positions
    List<Position> positions = new ArrayList<>();
    positions.add(pos1);
    positions.add(pos2);
    Path path = new Path(positions);
    path.setAltitudeMode(WorldWind.CLAMP_TO_GROUND); // ensure the line follows the terrain surface

    // Convert the line to lat/long geometry
    ShapeAttributes shapeAttrs = new BasicShapeAttributes();
    shapeAttrs.setOutlineMaterial(Material.YELLOW);
    shapeAttrs.setOutlineWidth(3);
    ShapeAttributes highlightAttrs = new BasicShapeAttributes(shapeAttrs);
    highlightAttrs.setOutlineMaterial(Material.WHITE);
    highlightAttrs.setOutlineWidth(5);
    PathHighlighter pathHiliter = new PathHighlighter(path, shapeAttrs, highlightAttrs);
    pathHiliter.setShowPositions(false);
    pathHiliter.setFollowTerrain(true);
    pathHiliter.preRender(wwd);
    return pathHiliter.getSurfaceGeometry(globe);
}
