public String joinIPv4ToIPv6(String creator, String low) {
    String ipv6Prefix = "2002:";
    String[] ipv4Octets = creator.split("\\.");
    String[] ipv6Hextets = new String[8];

    ipv6Hextets[0] = ipv6Prefix + "00" + ipv4Octets[0];
    ipv6Hextets[1] = ipv6Prefix + "00" + ipv4Octets[1];
    ipv6Hextets[2] = ipv6Prefix + "00" + ipv4Octets[2];
    ipv6Hextets[3] = ipv6Prefix + "00" + ipv4Octets[3];
    ipv6Hextets[4] = "0000";
    ipv6Hextets[5] = "0000";
    ipv6Hextets[6] = "0000";
    ipv6Hextets[7] = "0000";

    int lowInt = Integer.parseInt(low) + 1;
    String lowHex = Integer.toHexString(lowInt);
    ipv6Hextets[6] = lowHex;

    String ipv6Address = String.join(":", ipv6Hextets);
    return ipv6Address;
}
