public BoundingBox getMinimumBoundingBox(Page page) {
    List<TextElement> textElements = page.getTextElements();
    double minX = Double.MAX_VALUE;
    double minY = Double.MAX_VALUE;
    double maxX = Double.MIN_VALUE;
    double maxY = Double.MIN_VALUE;
    for (TextElement element : textElements) {
        BoundingBox bbox = element.getBoundingBox();
        if (bbox.getMinX() < minX) {
            minX = bbox.getMinX();
        }
        if (bbox.getMinY() < minY) {
            minY = bbox.getMinY();
        }
        if (bbox.getMaxX() > maxX) {
            maxX = bbox.getMaxX();
        }
        if (bbox.getMaxY() > maxY) {
            maxY = bbox.getMaxY();
        }
    }
    return new BoundingBox(minX, minY, maxX - minX, maxY - minY);
}
