public List<File> uploadDirectory(String bucketName, String virtualDirectoryKeyPrefix, File directory, boolean includeSubdirectories) {
    List<File> files = new ArrayList<>();
    for (File file : directory.listFiles()) {
        if (file.isDirectory() && includeSubdirectories) {
            files.addAll(uploadDirectory(bucketName, virtualDirectoryKeyPrefix + "/" + file.getName(), file, includeSubdirectories));
        } else {
            files.add(file);
        }
    }
    return files;
}
