import net.named_data.jndn.security.KeyChain;
import net.named_data.jndn.security.SecurityException;
import net.named_data.jndn.security.securityconf.KeyChainFile;
import net.named_data.jndn.util.Blob;

public KeyChain buildAndConfigureKeyChain(String deviceName) throws SecurityException {
    String ndnFolderPath = System.getProperty("user.home") + "/.ndn";

    KeyChainFile keyChainFile = new KeyChainFile(ndnFolderPath, "sqlite3", "file", true);
    KeyChain keyChain = KeyChain.create(keyChainFile);

    Blob defaultKeyName = new Blob(deviceName);
    keyChain.getDefaultKeyStorage().setKeyNameForIdentity(defaultKeyName, deviceName);

    return keyChain;
}
