public void initializeBundleAdjustmentParams(Structure structure, List<Observation> observations) {
    // Triangulate points using camera position and pixel observations
    for (Observation observation : observations) {
        Pixel pixel = observation.getPixel();
        Camera camera = observation.getCamera();
        Point3D point3D = structure.getPoints().get(observation.getPointIndex());

        // Triangulate the point and update its position
        Triangulator triangulator = new Triangulator(camera);
        double[] point3DCoordinates = triangulator.triangulate(pixel.getCoordinates(), point3D, 1e-6);
        point3D.setPosition(point3DCoordinates);
    }
}
