import java.io.IOException;
import java.nio.file.Path;
import java.util.logging.Logger;

public class UpdaterFactory {
  private static final Logger logger = Logger.getLogger(UpdaterFactory.class.getName());

  public static Updater create(Path gcloudPath) {
    logger.fine("Creating new Cloud SDK updater");

    CloudSdk cloudSdk = new CloudSdk.Builder().sdkPath(gcloudPath).build();
    UpdateOptions options = new UpdateOptions.Builder().checkForUpdates(true).build();
    UpdateProcessor processorChain =
        UpdateProcessorChain.builder()
            .addProcessor(logger::info)
            .addProcessor(output -> System.out.printf("  %s%n", output))
            .build();
    Update update =
        new Update.Builder()
            .updater(
                new UpdateChecker.Builder()
                    .cloudSdk(cloudSdk)
                    .updateOptions(options)
                    .build())
            .outputLineListener(
                new ProcessOutputLineListener() {
                  @Override public void onOutputLine(String line) {
                    processorChain.process(line);
                  }
                })
            .build();

    try {
      return new Updater(cloudSdk, new ProcessRunner(cloudSdk), update);
    } catch (IOException exception) {
      logger.warning("Could not create new Cloud SDK updater: " + exception.getMessage());
      throw new RuntimeException(exception);
    }
  }
}
