public Map<String, String> readLineAndSplit(Scanner input) throws IllegalArgumentException {
    if (!input.hasNextLine()) {
        throw new IllegalArgumentException("There are no more lines to read.");
    }
    String line = input.nextLine();
    String[] cols = line.split("\\s+");
    Map<String, String> colValuePairs = new HashMap<>();
    for (String col : cols) {
        String[] colValue = col.split("=");
        if (colValue.length == 2) {
            colValuePairs.put(colValue[0], colValue[1]);
        }
    }
    return colValuePairs;
}
