public void backpropagate(Instance inst) {
    // Feed forward to compute output
    double[] output = feedForward(inst.getInput());

    // Compute error for each output node
    double[] outputError = new double[numOutputNodes];
    for (int i = 0; i < numOutputNodes; i++) {
        outputError[i] = (inst.getOutput()[i] - output[i]) * output[i] * (1 - output[i]);
    }

    // Compute error for each hidden node
    double[] hiddenError = new double[numHiddenNodes];
    for (int i = 0; i < numHiddenNodes; i++) {
        double sum = 0;
        for (int j = 0; j < numOutputNodes; j++) {
            sum += outputError[j] * outputWeights[i][j];
        }
        hiddenError[i] = sum * hiddenOutput[i] * (1 - hiddenOutput[i]);
    }

    // Update output weights
    for (int i = 0; i < numHiddenNodes; i++) {
        for (int j = 0; j < numOutputNodes; j++) {
            outputWeights[i][j] += learningRate * outputError[j] * hiddenOutput[i];
        }
    }

    // Update hidden weights
    for (int i = 0; i < numInputNodes; i++) {
        for (int j = 0; j < numHiddenNodes; j++) {
            hiddenWeights[i][j] += learningRate * hiddenError[j] * inst.getInput()[i];
        }
    }
}
