import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.jar.JarEntry;
import java.util.jar.JarFile;

public class ClassFileReporter {

  public static void report(String... packages) throws IOException {
    List<String> classNames = new ArrayList<>();
    for (String packageName : packages) {
      String packagePath = packageName.replace(".", "/");
      for (File file : getClassPathEntries()) {
        if (file.isDirectory()) {
          File packageDir = new File(file, packagePath);
          if (packageDir.exists()) {
            classNames.addAll(getClassNames(packageDir, packagePath));
          }
        } else if (file.getName().endsWith(".jar")) {
          JarFile jarFile = new JarFile(file);
          try {
            classNames.addAll(getClassNames(jarFile, packagePath));
          } finally {
            jarFile.close();
          }
        }
      }
    }
    for (String className : classNames) {
      System.out.println(className);
    }
  }

  private static List<File> getClassPathEntries() {
    String classPath = System.getProperty("java.class.path");
    String[] classPathEntries = classPath.split(File.pathSeparator);
    List<File> result = new ArrayList<File>(classPathEntries.length);
    for (String entry : classPathEntries) {
      result.add(new File(entry));
    }
    return result;
  }

  private static List<String> getClassNames(File directory, String packagePath) {
    List<String> result = new ArrayList<>();
    for (File file : directory.listFiles()) {
      if (file.isDirectory()) {
        result.addAll(getClassNames(file, packagePath + "/" + file.getName()));
      } else if (file.getName().endsWith(".class")) {
        String className = packagePath + "/" + file.getName().substring(0, file.getName().length() - 6);
        result.add(className.replace("/", "."));
      }
    }
    return result;
  }

  private static List<String> getClassNames(JarFile jarFile, String packagePath) {
    List<String> result = new ArrayList<>();
    for (JarEntry entry : Collections.list(jarFile.entries())) {
      if (entry.getName().startsWith(packagePath) && entry.getName().endsWith(".class")) {
        String className = entry.getName().substring(0, entry.getName().length() - 6);
        result.add(className.replace("/", "."));
      }
    }
    return result;
  }

}
