public List<Node> loadYamlNodes(Reader yaml) {
    Yaml yamlParser = new Yaml();
    Iterable<Object> yamlObjects = yamlParser.loadAll(yaml);
    List<Node> nodes = new ArrayList<>();
    for (Object obj : yamlObjects) {
        if (obj instanceof Node) {
            nodes.add((Node) obj);
        }
    }
    return nodes;
}
