public Destination createDestination(String name, String type, boolean fTransacted, int ackMode) throws MessagingException {
    ConnectionFactory connectionFactory = new ActiveMQConnectionFactory();
    Connection connection = null;
    Session session = null;
    Destination destination = null;
    try {
        connection = connectionFactory.createConnection();
        connection.start();
        session = connection.createSession(fTransacted, ackMode);
        if (type.equalsIgnoreCase("topic")) {
            destination = session.createTopic(name);
        } else if (type.equalsIgnoreCase("queue")) {
            destination = session.createQueue(name);
        } else {
            throw new IllegalArgumentException("Invalid destination type: " + type);
        }
    } catch (JMSException ex) {
        throw new MessagingException("Error creating destination " + name, ex);
    } finally {
        if (session != null) {
            try {
                session.close();
            } catch (JMSException ex) {}
        }
        if (connection != null) {
            try {
                connection.close();
            } catch (JMSException ex) {}
        }
    }
    return destination;
}
