    if (!dirPath.exists()) {
        dirPath.mkdirs();
    }
    File file = new File(dirPath, filename);
    OutputStream os = new FileOutputStream(file);
    bitmap.compress(format, quality, os);
    os.flush();
    os.close();
    return file;
}
