public static <T> double initializeWeightList(List<Double> weights, List<T> ids, BiFunction<T, T, Double> relation, T first, T second, DoubleUnaryOperator distQ) {
    double weightSum = 0.0;
    for(T id : ids) {
        double firstDist = relation.apply(first, id);
        double secondDist = relation.apply(second, id);
        double distDiff = Math.abs(firstDist - secondDist);
        double weight = distQ.applyAsDouble(distDiff);
        weights.add(weight);
        weightSum += weight;
    }
    return weightSum;
}
