public static <K, V> Marshaller<Map.Entry<K, V>> marshallerForKeyValuePairs(Marshaller<K> keyMarshaller, Marshaller<V> valueMarshaller) {
    return new Marshaller<Map.Entry<K, V>>() {
        @Override
        public void marshall(Map.Entry<K, V> entry, ByteSink sink) {
            keyMarshaller.marshall(entry.getKey(), sink);
            valueMarshaller.marshall(entry.getValue(), sink);
        }

        @Override
        public Map.Entry<K, V> unmarshall(ByteSource source) {
            K key = keyMarshaller.unmarshall(source);
            V value = valueMarshaller.unmarshall(source);
            return new AbstractMap.SimpleEntry<>(key, value);
        }
    };
}
