public String readDWGLine(byte[] data, int offset) throws Exception {
    int size = Byte.toUnsignedInt(data[offset]) | Byte.toUnsignedInt(data[offset + 1]) << 8;
    offset += 2;
    if (size == 0) {
        return "";
    }
    int endIndex = offset + size;
    StringBuilder sb = new StringBuilder();
    while (offset < endIndex) {
        int c1 = Byte.toUnsignedInt(data[offset]);
        if (c1 < 128) {
            sb.append((char) c1);
            offset++;
        } else if (c1 >= 192 && c1 <= 223) {
            if (offset + 1 >= endIndex) {
                throw new Exception("Unexpected bit value found in DWG file");
            }
            int c2 = Byte.toUnsignedInt(data[offset + 1]);
            sb.append((char) ((c1 - 192) * 64 + (c2 - 128)));
            offset += 2;
        } else if (c1 >= 224 && c1 <= 239) {
            if (offset + 2 >= endIndex) {
                throw new Exception("Unexpected bit value found in DWG file");
            }
            int c2 = Byte.toUnsignedInt(data[offset + 1]);
            int c3 = Byte.toUnsignedInt(data[offset + 2]);
            sb.append((char) ((c1 - 224) * 4096 + (c2 - 128) * 64 + (c3 - 128)));
            offset += 3;
        } else {
            throw new Exception("Unexpected bit value found in DWG file");
        }
    }
    return sb.toString();
}
