public boolean validateUserCredentials(String userID, String password) {
   // Check if userID and password are not empty
   if (userID.isEmpty() || password.isEmpty()) {
        return false;
   }

   // Check if userID and password meet minimum length requirements
   if (userID.length() < 8 || password.length() < 8) {
        return false;
   }

   // Check if userID and password contain only alphanumeric characters
   if (!userID.matches("^[a-zA-Z0-9]+$") || !password.matches("^[a-zA-Z0-9]+$")) {
        return false;
   }

   // Check if userID and password are not equal
   if (userID.equals(password)) {
        return false;
   }

   // If all above checks pass, then return true
   return true;
}
