public static String replace(String input, String oldWord, String newWord) {
    if (input == null || input.isEmpty())
        return "";

    String[] words = input.split(oldWord);
    StringBuilder sb = new StringBuilder();

    int i = 0;
    for (i = 0; i < words.length - 1; i++)
        sb.append(words[i]).append(newWord);

    sb.append(words[i]);
    return sb.toString();
}
