public void writeStatistics(List<String> fileList) {
    for (String file: fileList) {
        try {
            // Open the BAM index file
            SamReader reader = SamReaderFactory.makeDefault().open(new File(file));
            // Get statistics about the file
            SAMFileHeader header = reader.getFileHeader();
            long numRecords = reader.getFileHeader().getSortOrder() == SAMFileHeader.SortOrder.coordinate ?
                    header.getStatistic().getNumReads() : header.getStatistic().getNumSequences();
            System.out.println("File: " + file);
            System.out.println("Number of records: " + numRecords);
            System.out.println("Number of reference sequences: " + header.getSequenceDictionary().size());
            System.out.println("Reference sequences: " + header.getSequenceDictionary().getSequences());
            reader.close();
        } catch (IOException e) {
            System.out.println("Error opening BAM index file: " + file);
        }
    }
}
