public String changeLogLevel(String loggerName, Level level) {
    Logger logger = LoggerFactory.getLogger(loggerName);
    if(logger != null) {
        LoggerFactoryBinder loggerFactoryBinder = LoggerFactory.getILoggerFactory();
        List<Logger> loggerList = loggerFactoryBinder.getLoggerList();
        logger.setLevel(level);
        return toJson(loggerList);
    } else {
        return "not found";
    }
}

