public static String getDescriptor(Class<?> returnType, Class<?>... argumentTypes) {
    StringBuilder descriptorBuilder = new StringBuilder();
    descriptorBuilder.append("(");
    for (Class<?> argumentType : argumentTypes) {
        descriptorBuilder.append(getDescriptor(argumentType));
    }
    descriptorBuilder.append(")");
    descriptorBuilder.append(getDescriptor(returnType));
    return descriptorBuilder.toString();
}

private static String getDescriptor(Class<?> type) {
    if (type.isPrimitive()) {
        if (type == void.class) {
            return "V";
        } else if (type == int.class) {
            return "I";
        } else if (type == long.class) {
            return "J";
        } else if (type == float.class) {
            return "F";
        } else if (type == double.class) {
            return "D";
        } else if (type == byte.class) {
            return "B";
        } else if (type == char.class) {
            return "C";
        } else if (type == short.class) {
            return "S";
        } else if (type == boolean.class) {
            return "Z";
        } else {
            throw new IllegalArgumentException("Unknown primitive type: " + type);
        }
    } else if (type.isArray()) {
        return "[" + getDescriptor(type.getComponentType());
    } else {
        return "L" + type.getName().replace(".", "/") + ";";
    }
}
