import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;

public class MyCSVUtility {

    public static List<String> getQuotedQualityCSV(Map<String, String> header, String fieldName) {

        List<String> fieldValues = new ArrayList<>();
        for (Map.Entry<String, String> entry : header.entrySet()) {
            String key = entry.getKey();
            String value = entry.getValue();

            // Check if field name matches
            if (key.equalsIgnoreCase(fieldName)) {

                // Split values by comma
                String[] values = value.split(",");

                // Sort values by quality parameter
                List<String> sortedValues = new ArrayList<>();
                for (String val : values) {
                    String strippedVal = val.trim().replaceAll("\"", "");

                    // Check if quality parameter exists
                    if (strippedVal.contains(";q=")) {
                        String[] qVal = strippedVal.split(";q=");
                        sortedValues.add(qVal[0].replaceAll("\\s", ""));
                    } else {
                        sortedValues.add(strippedVal.replaceAll("\\s", ""));
                    }
                }
                Collections.sort(sortedValues, Collections.reverseOrder());
                fieldValues.addAll(sortedValues);
            }
        }
        return fieldValues;
    }
}
