public String joinScopeCodes(String[] scopeCodes, String[] parentScopeCodes) {
    StringBuilder sb = new StringBuilder();
    Set<String> uniqueScopeCodes = new HashSet<>(Arrays.asList(scopeCodes));
    Set<String> uniqueParentScopeCodes = new HashSet<>(Arrays.asList(parentScopeCodes));

    uniqueScopeCodes.addAll(uniqueParentScopeCodes);

    for (String scopeCode : uniqueScopeCodes) {
        sb.append(scopeCode);
        sb.append(",");
    }
    sb.deleteCharAt(sb.length() - 1); // remove the last comma
    return sb.toString();
}
