public CommerceShipment updateCommerceShipment(CommerceShipment commerceShipment) throws SystemException {
        if (commerceShipment == null) {
            throw new IllegalArgumentException("Commerce shipment is null");
        }

        CommerceShipment updatedCommerceShipment = null;

        try {
            if (commerceShipment.getCommerceShipmentId() > 0) {
                updatedCommerceShipment =
                    commerceShipmentPersistence.update(commerceShipment);
            }
            else {
                long commerceShipmentId =
                    counterLocalService.increment(CommerceShipment.class.getName());

                commerceShipment.setCommerceShipmentId(commerceShipmentId);

                updatedCommerceShipment =
                    commerceShipmentPersistence.update(commerceShipment);
            }
        }
        catch (SystemException e) {
            throw e;
        }

        return updatedCommerceShipment;
    }
