import com.amazonaws.waiters.*;
import com.amazonaws.waiters.PollingStrategy.WaiterState;

public Waiter buildCustomWaiter(PollingStrategy customStrategy, WaiterParameters waiterParameters) {
    WaiterExecution.Builder executorBuilder = BucketNotExists.builder();
    executorBuilder.waiterParameters(waiterParameters);
    executorBuilder.pollingStrategy(customStrategy);

    return executorBuilder.build();
}

public boolean waitForBucketNotExists(AmazonS3 s3, String bucketName) throws AmazonServiceException, AmazonClientException, InterruptedException {
    WaiterParameters waiterParameters = new WaiterParameters(new DescribeBucketsRequest().withBucketName(bucketName));
    PollingStrategy customStrategy = new PollingStrategy(new MaxAttemptsRetryStrategy(10), new FixedDelayStrategy(5));

    Waiter bucketNotExistsWaiter = buildCustomWaiter(customStrategy, waiterParameters);
    try {
        WaiterState state = bucketNotExistsWaiter.run(new SdkFunction<DescribeBucketsRequest, Bucket>() {
            @Override
            public Bucket apply(final DescribeBucketsRequest request) {
                return s3.describeBuckets(request).getBuckets().stream()
                       .filter(bucket -> bucketName.equals(bucket.getName()))
                       .findFirst().orElse(null);
            }
        });

        return state == WaiterState.SUCCESS;
    } catch (WaiterUnrecoverableException e) {
        return false;
    }
}
