public void waitForThread(String name, long time, TimeUnit unit) throws TimeoutException, InterruptedException {
    Thread thread = null;
    for (Thread t : Thread.getAllStackTraces().keySet()) {
        if (t.getName().equals(name)) {
            thread = t;
            break;
        }
    }
    if (thread == null) {
        throw new IllegalArgumentException("No thread with name " + name + " found");
    }
    long endTime = System.currentTimeMillis() + unit.toMillis(time);
    long remaining = time;
    synchronized (thread) {
        while (remaining > 0 && thread.isAlive()) {
            thread.wait(remaining);
            remaining = endTime - System.currentTimeMillis();
        }
        if (thread.isAlive()) {
            throw new TimeoutException("Timeout waiting for thread " + name);
        }
    }
}
