public String[] relativeRequestMethods(String[] requestMethods, String baseMethod) {
    List<String> relativeMethods = new ArrayList<>();

    for (String method : requestMethods) {
        if (method.equals(baseMethod)) {
            relativeMethods.add("");
        } else if (method.startsWith(baseMethod)) {
            relativeMethods.add(method.substring(baseMethod.length()));
        } else {
            relativeMethods.add(null);
        }
    }

    return relativeMethods.toArray(new String[0]);
}
