public boolean isExpired(long ttl, Instant cacheStartTime){
    Duration expirationDuration = Duration.ofMinutes(ttl);
    Instant expirationTime = cacheStartTime.plus(expirationDuration);
    Instant currentTime = Instant.now();
    return currentTime.isAfter(expirationTime);
}
