public static OmsEpanetParametersTime createOmsEpanetParametersTimeFromMap(HashMap<TimeParameterCodes, String> options) throws Exception {
    OmsEpanetParametersTime parameters = new OmsEpanetParametersTime();
    for (TimeParameterCodes key : options.keySet()) {
        String value = options.get(key);
        switch (key) {
            case DURATION:
                parameters.setDuration(value);
                break;
            case HYDRAULIC_TIMESTEP:
                parameters.setHydraulicTimestep(value);
                break;
            case QUALITY_TIMESTEP:
                parameters.setQualityTimestep(value);
                break;
            case PATTERN_TIMESTEP:
                parameters.setPatternTimestep(value);
                break;
            case PATTERN_ENDTIME:
                parameters.setPatternEndTime(value);
                break;
            case REPORT_TIMESTEP:
                parameters.setReportTimestep(value);
                break;
            case REPORT_STARTTIME:
                parameters.setReportStartTime(value);
                break;
            case REPORT_ENDTIME:
                parameters.setReportEndTime(value);
                break;
            case RULE_TIMESTEP:
                parameters.setRuleTimestep(value);
                break;
            case STARTTIME:
                parameters.setStartTime(value);
                break;
            default:
                throw new Exception("Invalid parameter code");
        }
    }
    return parameters;
}
