public BufferedImage regularToIntegral(BufferedImage input, BufferedImage transformed) {
    int width = input.getWidth();
    int height = input.getHeight();

    if (transformed == null) {
        transformed = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
    }

    int[] pixelsInput = input.getRGB(0, 0, width, height, null, 0, width);
    int[] pixelsResult = new int[width * height];

    for (int i = 0; i < width; i++) {
        pixelsResult[i] = pixelsInput[i];
    }

    for (int j = 1; j < height; j++) {
        int index = j*width;
        int[] perRowSum = new int[] {pixelsInput[index]};

        for (int i = 1; i < width; i++) {
            int pixel = pixelsInput[index+i];
            perRowSum[i] = perRowSum[i-1] + (pixel>>16&0xFF) + (pixel>>8&0xFF) + (pixel&0xFF);
            pixelsResult[index+i] = perRowSum[i] + pixelsResult[index-width+i];
        }
    }

    transformed.setRGB(0, 0, width, height, pixelsResult, 0, width);

    return transformed;
}
