public void updateSeries(String seriesName, List<Number> newXData, List<Number> newYData, List<Number> newErrorBarData) {
    XYSeries series = dataset.getSeries(seriesName);

    if (newXData == null) {
        newXData = new ArrayList<>();
        for (int i = 0; i < newYData.size(); i++) {
            newXData.add(i + 1);
        }
    }

    for (int i = 0; i < newYData.size(); i++) {
        double x = newXData.get(i).doubleValue();
        double y = newYData.get(i).doubleValue();
        double errorBar = (newErrorBarData == null) ? 0 : newErrorBarData.get(i).doubleValue();

        XYSeriesDataItem existingItem = series.getDataItem(i);
        if (existingItem != null) {
            existingItem.setX(x);
            existingItem.setY(y);
            existingItem.setExtraValue(errorBar);
        } else {
            series.add(x, y, errorBar);
        }
    }
}
