import javax.xml.stream.XMLStreamException;

public long convertXmlElemToLong(StaxReader reader, String key, String[] expressions) throws XMLStreamException, ParserException {
    while (reader.hasNext()) {
        int eventType = reader.next();
        if (eventType == XMLStreamConstants.START_ELEMENT) {
            String currentElem = reader.getLocalName();
            if (currentElem.equals(key)) {
                String elementText = reader.getElementText();
                try {
                    return Long.parseLong(elementText);
                } catch (NumberFormatException e) {
                    throw new ParserException("Element is not a valid number");
                }
            } else if (Arrays.asList(expressions).contains(currentElem)) {
                // skip elements, they're not important for this function
            } else {
                throw new ParserException("Element not found");
            }
        }
    }
    throw new ParserException("Element not found");
}
