public boolean isValidPermutation(char[] chromosome, char[] validAlleles) {
    Set<Character> set = new HashSet<>();
    for (char c : validAlleles) {
        set.add(c);
    }
    for (char c : chromosome) {
        if (!set.contains(c)) {
            return false;
        }
        set.remove(c);
    }
    return true;
}
