public BufferedImage getPostImage(int WIDTH, List<Double> POSITIONS, BufferedImage image) {
    int height = image.getHeight();
    int width = image.getWidth();
    BufferedImage postImage = new BufferedImage(WIDTH, height, image.getType());

    Graphics2D graphics = postImage.createGraphics();
    for (double position : POSITIONS) {
        int xPosition = (int) (width * position) - (WIDTH / 2);
        graphics.drawImage(image.getSubimage(xPosition, 0, WIDTH, height), null, xPosition, 0);
    }
    graphics.dispose();
    return postImage;
}
