public GitLabApiForm addArrayHashParameter(String name, Map<?, ?>[] variables, boolean required) throws IllegalArgumentException {
    if (StringUtils.isBlank(name) || variables == null) {
        throw new IllegalArgumentException("Name or variables cannot be null or empty.");
    }
    if (required && variables.length == 0) {
        throw new IllegalArgumentException("At least one variable is required for " + name);
    }
    for (Map<?, ?> variable : variables) {
        if (variable == null || variable.isEmpty()) {
            throw new IllegalArgumentException("Variable cannot be null or empty.");
        }
        for (Map.Entry<?, ?> entry : variable.entrySet()) {
            Object entryKey = entry.getKey();
            Object entryValue = entry.getValue();

            if (entryKey == null || StringUtils.isBlank(entryKey.toString())) {
                throw new IllegalArgumentException("Entry key cannot be null or empty.");
            }
            if (entryValue == null || StringUtils.isBlank(entryValue.toString())) {
                throw new IllegalArgumentException("Entry value cannot be null or empty.");
            }

            addParameter(String.format("%s[%s][%s]", name, variables.indexOf(variable), entryKey), entryValue.toString(), false);
        }
    }
    return this;
}
