import java.lang.reflect.*;
import java.util.Map;

public class ReturnTypeFinder {
    public static Type getReturnType(Method method, Map<String, Type> typeParamBindings) {
        Type returnType = method.getGenericReturnType();
        if (returnType instanceof TypeVariable) {
            TypeVariable<?> typeVar = (TypeVariable<?>) returnType;
            return typeParamBindings.get(typeVar.getName());
        } else if (returnType instanceof ParameterizedType) {
            ParameterizedType paramType = (ParameterizedType) returnType;
            Type[] actualTypeArgs = paramType.getActualTypeArguments();
            for (int i = 0; i < actualTypeArgs.length; i++) {
                if (actualTypeArgs[i] instanceof TypeVariable) {
                    TypeVariable<?> typeVar = (TypeVariable<?>) actualTypeArgs[i];
                    actualTypeArgs[i] = typeParamBindings.get(typeVar.getName());
                }
            }
            return paramType;
        } else {
            return returnType;
        }
    }
}
