import javax.persistence.*;

public Query applyOrderByHint(Query namedQuery) {
    Object hint = namedQuery.getHints().get("query");

    if (hint != null && hint instanceof String) {
        String queryString = namedQuery.unwrap(org.hibernate.query.Query.class).getQueryString();
        String orderByClause = " ORDER BY /* some column name */ ASC"; // replace with the actual column name

        Query orderByQuery = namedQuery.getEntityManager()
                .createQuery((String) hint + queryString + orderByClause);

        orderByQuery.setHints(namedQuery.getHints());
        return orderByQuery;
    }

    return namedQuery; // the named query doesn't have the "query" hint, just return it
}
