public String buildTable(ResultSet results) throws SQLException {
    ResultSetMetaData metaData = results.getMetaData();
    int columnCount = metaData.getColumnCount();
    StringBuilder tableBuilder = new StringBuilder();

    // Build the header row
    StringBuilder headerBuilder = new StringBuilder("|");
    for (int i = 1; i <= columnCount; i++) {
        headerBuilder.append(" ").append(metaData.getColumnName(i)).append(" |");
    }
    tableBuilder.append(headerBuilder).append("\n");

    // Build separator row
    StringBuilder separatorBuilder = new StringBuilder("|");
    for (int i = 1; i <= columnCount; i++) {
        separatorBuilder.append(" ").append("-".repeat(metaData.getColumnDisplaySize(i))).append(" |");
    }
    tableBuilder.append(separatorBuilder).append("\n");

    // Build data rows
    while (results.next()) {
        StringBuilder rowBuilder = new StringBuilder("|");
        for (int i = 1; i <= columnCount; i++) {
            Object value = results.getObject(i);
            String formattedValue = (value == null) ? "NULL" : value.toString();
            rowBuilder.append(" ").append(formattedValue).append(" |");
        }
        tableBuilder.append(rowBuilder).append("\n");
    }

    return tableBuilder.toString();
}
