import com.nimbusds.jose.jwk.JWK;
import com.nimbusds.jose.jwk.JWKSet;
import com.nimbusds.jose.jwk.KeyUse;
import com.nimbusds.jose.jws.JWSAlgorithm;
import com.nimbusds.jose.jws.JWSHeader;
import com.nimbusds.jose.util.Base64URL;

public JWSHeader constructJWSHeader(String base64) {
    // Decode the base64 url string
    Base64URL header = new Base64URL(base64);

    // Parse the header as a JSON Web Key Set
    JWKSet jwkSet = JWKSet.parse(header.toString());

    // Extract the first key in the set
    JWK jwk = jwkSet.getKeys().get(0);

    // Create a new JWS header using the extracted key details
    JWSHeader header = new JWSHeader.Builder(JWSAlgorithm.parse(jwk.getAlgorithm().getName()))
            .keyID(jwk.getKeyID())
            .keyUse(jwk.getKeyUse() == null ? KeyUse.SIGNATURE : jwk.getKeyUse())
            .build();

    // Return the constructed JWS header
    return header;
}
