import java.util.Iterator;
import java.util.List;

public class GeneratorIterator implements Iterator<Generator> {

    private List<Generator> generatorList;
    private int currentIndex;

    public GeneratorIterator(List<Generator> generatorList) {
        this.generatorList = generatorList;
        this.currentIndex = 0;
    }

    @Override
    public boolean hasNext() {
        return currentIndex < generatorList.size();
    }

    @Override
    public Generator next() {
        Generator nextGenerator = generatorList.get(currentIndex);
        currentIndex++;
        return nextGenerator;
    }

    @Override
    public void remove() {
        throw new UnsupportedOperationException();
    }

}
