public static String escapeXmlAttribute(String in) {
    if (in == null || in.isEmpty()) {
        return "";
    }
    StringBuilder out = new StringBuilder();
    for (int i = 0; i < in.length(); i++) {
        char c = in.charAt(i);
        switch (c) {
            case '\"':
                out.append("&quot;");
                break;
            case '\'':
                out.append("&apos;");
                break;
            case '&':
                out.append("&amp;");
                break;
            case '<':
                out.append("&lt;");
                break;
            case '>':
                out.append("&gt;");
                break;
            default:
                out.append(c);
                break;
        }
    }
    return out.toString(); 
}
