public int evaluateNearestType(Type from, Type a, Type b) {
    int aDiff = Math.abs(from.value() - a.value());
    int bDiff = Math.abs(from.value() - b.value());

    if (aDiff < bDiff) {
        return -1;
    } else if (aDiff == bDiff) {
        return 0;
    } else {
        return 1;
    }
}
