public static void findMinimumBoundingRectangle(Point[] quad, Point[] rectangle) {
    double angle = 0;
    double minArea = Double.POSITIVE_INFINITY;

    for(int i = 0; i < 4; i++) {
        angle = -Math.atan2(quad[i].y - quad[(i + 1) % 4].y, quad[i].x - quad[(i + 1) % 4].x) + Math.PI / 2;
        Point[] temp = new Point[4];

        for(int j = 0; j < 4; j++) {
            temp[j] = new Point((int) ((quad[j].x - quad[i].x) * Math.cos(angle) - (quad[j].y - quad[i].y) * Math.sin(angle)), (int) ((quad[j].x - quad[i].x) * Math.sin(angle) + (quad[j].y - quad[i].y) * Math.cos(angle)));
        }

        double minX = Double.POSITIVE_INFINITY;
        double maxX = Double.NEGATIVE_INFINITY;
        double minY = Double.POSITIVE_INFINITY;
        double maxY = Double.NEGATIVE_INFINITY;

        for(int j = 0; j < 4; j++) {
            if(temp[j].x < minX) {
                minX = temp[j].x;
            }
            if(temp[j].x > maxX) {
                maxX = temp[j].x;
            }
            if(temp[j].y < minY) {
                minY = temp[j].y;
            }
            if(temp[j].y > maxY) {
                maxY = temp[j].y;
            }
        }

        double area = (maxX - minX) * (maxY - minY);
        if(area < minArea) {
            minArea = area;
            for(int j = 0; j < 4; j++) {
                rectangle[j].x = (int) (temp[j].x * Math.cos(-angle) - temp[j].y * Math.sin(-angle) + quad[i].x);
                rectangle[j].y = (int) (temp[j].x * Math.sin(-angle) + temp[j].y * Math.cos(-angle) + quad[i].y);
            }
        }
    }
}
