public Object getPredecessor(Object currentElement) {
    if (currentElement == null) {
        throw new NullPointerException("Current element cannot be null");
    }
    if (head == null) {
        return null;
    }
    if (head.getValue().equals(currentElement)) {
        return null;
    }
    Node currentNode = head;
    Node previousNode = null;
    while (currentNode != null) {
        if (currentNode.getValue().equals(currentElement)) {
            return previousNode.getValue();
        }
        previousNode = currentNode;
        currentNode = currentNode.getNext();
    }
    return null;
}
