public String transformToRuleScript(String name, List<String> types, String version) {
    StringBuilder sb = new StringBuilder();

    sb.append("// Rule script for ").append(name).append("\n");
    if(version != null) {
        sb.append("// Version ").append(version).append("\n");
    }
    sb.append("RULE {\n");

    for(String type : types) {
        sb.append("    INSTRUMENTATION ").append(type).append(";\n");
    }

    sb.append("}\n");

    return sb.toString();
}
