public List<Node> collectChangesOfDirectChildren(String rootIdentifier, List<Node> forNodes) {
    List<Node> result = new ArrayList<>();
    // find the root node based on the root identifier
    Node rootNode = findNodeByIdentifier(rootIdentifier);
    if (rootNode != null) {
        // add the root node to the result set if it needs to be returned
        if (forNodes.contains(rootNode)) {
            result.add(rootNode);
        }
        // loop over the direct children of the root node
        for (Node child : rootNode.getChildren()) {
            // add the child node to the result set if it needs to be returned
            if (forNodes.contains(child)) {
                result.add(child);
            }
            // check if the child node has any changes
            if (child.hasChanged()) {
                // add the child node to the result set
                result.add(child);
            }
        }
    }
    return result;
