public Font replaceNullAttributes(Font font) {
    if (font == null) {
        throw new IllegalArgumentException("Font cannot be null");
    }

    if (font.getName() == null || font.getSize() == 0) {
        throw new IllegalArgumentException("Font name and size cannot be null or 0");
    }

    if (font.getStyle() < 0 || font.getStyle() > 3) {
        throw new IllegalArgumentException("Font style should be either PLAIN, BOLD, ITALIC or BOTH");
    }

    // Assumes that the attributes to be replaced are name, size and style
    // Initialize with default values
    String name = "Arial";
    int size = 12;
    int style = Font.PLAIN;

    if (getName() != null) {
        name = getName();
    }

    if (getSize() != 0) {
        size = getSize();
    }

    if (getStyle() >= 0 && getStyle() <= 3) {
        style = getStyle();
    }

    return new Font(name, style, size);
}
