public static boolean isBoxedType(Class<?> primitive, Class<?> boxed) {
  if (primitive.equals(boolean.class)) {
    return boxed.equals(Boolean.class);
  } else if (primitive.equals(byte.class)) {
    return boxed.equals(Byte.class);
  } else if (primitive.equals(short.class)) {
    return boxed.equals(Short.class);
  } else if (primitive.equals(int.class)) {
    return boxed.equals(Integer.class);
  } else if (primitive.equals(long.class)) {
    return boxed.equals(Long.class);
  } else if (primitive.equals(float.class)) {
      return boxed.equals(Float.class);
  } else if (primitive.equals(double.class)) {
      return boxed.equals(Double.class);
  } else if (primitive.equals(char.class)) {
      return boxed.equals(Character.class);
  } else {
      return false;
  }
}
