public int initPL110LData(InputStream is, boolean parseDoA) throws KNXFormatException {
    int len = 0;
    try {
        int ctrl = is.read();
        if (ctrl != CTRL_FIELD) {
            throw new KNXFormatException(String.format("Wrong control field: %02x", ctrl));
        }
        len = is.read();
        if (len > MAX_DATA_LENGTH) {
            throw new KNXFormatException(String.format("Too long L_Data frame, %d > %d", len, MAX_DATA_LENGTH));
        }
        if (parseDoA) {
            is.skip(2);
        } else {
            is.skip(1);
        }
    } catch (IOException e) {
        throw new KNXFormatException("EOF reached or I/O error", e);
    }
    return len;
}
