import org.apache.spark.api.java.JavaRDD;
import scala.Tuple2;

import java.util.List;
import java.util.Random;

public static Tuple2<JavaRDD<T>, JavaRDD<T>> balancedRandomSplitWithSeed(int seed, int numPartitions,
                                                                          JavaRDD<T> input) {
    List<Integer> partitions = input.context().parallelize(
            java.util.stream.IntStream.range(0, numPartitions).boxed().toArray(Integer[]::new), numPartitions)
            .mapPartitions(partitionIndices -> {
                Random rng = new Random(seed);
                List<Integer> indices = new java.util.ArrayList<>();
                while (partitionIndices.hasNext()) {
                    indices.add(partitionIndices.next());
                }
                Collections.shuffle(indices, rng);
                return indices.iterator();
            }, true).collect();

    if (partitions.size() == 1) {
        return new Tuple2<>(input, input.context().emptyRDD());
    } else {
        JavaRDD<T>[] split = input.randomSplit(partitions.stream().mapToDouble(w -> 1.0 / partitions.size()).toArray());
        return new Tuple2<>(input.context().union(split), input.context().emptyRDD());
    }
}
