public List<String> getMatchingRelations(String baseTable, String baseColumn, String relatedTable, String relatedColumn, String relation, String mappingTable) throws SQLException {
    List<String> relations = new ArrayList<>();
    String query = "SELECT * FROM " + mappingTable + " WHERE " + baseColumn + " IS NOT NULL AND " + relatedColumn + " IS NOT NULL";
    Connection conn = getConnection(); // assume getConnection() method returns a Connection object
    Statement stmt = conn.createStatement();
    ResultSet rs = stmt.executeQuery(query);
    while (rs.next()) {
        String baseValue = rs.getString(baseColumn);
        String relatedValue = rs.getString(relatedColumn);
        String relationType = rs.getString(relation);
        if (baseValue != null && relatedValue != null && relationType != null) {
            String result = baseTable + "." + baseColumn + " -> " + relationType + "(" + mappingTable + ")" + " -> " + relatedTable + "." + relatedColumn;
            relations.add(result);
        }
    }
    rs.close();
    stmt.close();
    conn.close();
    return relations;
}
