public static ExecutorService createThreadPool(int threads, String groupName, int queueSize) {
    return new ThreadPoolExecutor(threads, threads, 0L, TimeUnit.MILLISECONDS, new ArrayBlockingQueue<>(queueSize), new ThreadFactory() {
        private final AtomicLong counter = new AtomicLong(0L);

        @Override
        public Thread newThread(Runnable r) {
            Thread t = new Thread(r);
            t.setName(groupName + "-thread-" + counter.incrementAndGet());
            t.setDaemon(false);
            return t;
        }
    });
}
