public int calculateOffset(int totalSize, String layoutOrientation, String gravity) {
    int offset = 0;

    if (layoutOrientation.equals("horizontal")) {
        if (gravity.equals("start")) {
            offset = 0;
        } else if (gravity.equals("center")) {
            offset = (totalSize / 2);
        } else if (gravity.equals("end")) {
            offset = totalSize;
        }
    } else if (layoutOrientation.equals("vertical")) {
        if (gravity.equals("top")) {
            offset = 0;
        } else if (gravity.equals("center")) {
            offset = (totalSize / 2);
        } else if (gravity.equals("bottom")) {
            offset = totalSize;
        }
    }

    return offset;
}
