@Override
public String sendMMS(String CorpNum, String Sender, String Receiver, String Subject, String Content, Message[] Messages, File file, Date ReserveDT, Boolean ADSendType, String UserID) throws PopbillException {
    String Response = "";
    String PostData = "";
    String Boundary = "";
    String tmpGUID = UUID.randomUUID().toString().replaceAll("-", "");
    String fileName = "";

    if (file != null) {
        try {
            fileName = new String(file.getName().getBytes(), "UTF-8");
        } catch (UnsupportedEncodingException e) {
            throw new PopbillException(-99999999, "전송실패", e.getMessage());
        }
    }

    if (ADSendType == null) ADSendType = false;

    List<NameValuePair> MMSData = new ArrayList<NameValuePair>();

    MMSData.add(new BasicNameValuePair("snd", Sender));
    MMSData.add(new BasicNameValuePair("rcv", Receiver));
    MMSData.add(new BasicNameValuePair("sjt", Subject));
    MMSData.add(new BasicNameValuePair("cont", Content));
    MMSData.add(new BasicNameValuePair("adsYN", ADSendType.toString()));

    if (ReserveDT != null) {
        SimpleDateFormat formatter = new SimpleDateFormat("yyyyMMddHHmmss");
        String ReserveDTString = formatter.format(ReserveDT);
        MMSData.add(new BasicNameValuePair("sndDT", ReserveDTString));
    }

    if (UserID != null)
        MMSData.add(new BasicNameValuePair("userId", UserID));

    PostData = makePostData(MMSData, Messages, file, tmpGUID);

    Boundary = "---------------------" + tmpGUID;
    String CertFile = getCertificateFileName(CorpNum);

    Response = httpPostMultipart(null, URL + "/MMS", CorpNum, Boundary, CertFile, PostData.getBytes("UTF-8"), fileName);

    return Response;
