import java.util.HashSet;
import java.util.Set;

public Set<Class<? extends Throwable>> getThrownExceptions(BasicBlock basicBlock) {
    Set<Class<? extends Throwable>> thrownExceptions = new HashSet<>();
    for (Instruction instruction : basicBlock.getInstructions()) {
        try {
            instruction.execute();
        } catch (Throwable t) {
            thrownExceptions.add(t.getClass());
        }
    }
    return thrownExceptions;
}
