public KeyManager[] createKeyManagers(String keyStoreFile, String pass) throws InitializationException {
        try {
            KeyStore keyStore = KeyStore.getInstance("JKS");
            FileInputStream fis = new FileInputStream(keyStoreFile);
            keyStore.load(fis, pass.toCharArray());
            fis.close();

            KeyManagerFactory kmf = KeyManagerFactory.getInstance(KeyManagerFactory.getDefaultAlgorithm());
            kmf.init(keyStore, pass.toCharArray());
            return kmf.getKeyManagers();
        } catch (IOException | NoSuchAlgorithmException | KeyStoreException | UnrecoverableKeyException | NullPointerException e) {
            throw new InitializationException("Unable to create Key Manager",e);
        }
    }
