public static Document signXmlDocument(Document document, PublicKey publicKey, PrivateKey privateKey) throws Exception {

    DOMSignContext domSignContext = new DOMSignContext(privateKey, document.getDocumentElement());           

    Element rootElement = document.getDocumentElement();
    rootElement.normalize();       

    XMLSignatureFactory xmlSignatureFactory = XMLSignatureFactory.getInstance("DOM");
    List<Transform> transformList = new ArrayList<Transform>();
    transformList.add(xmlSignatureFactory.newTransform(Transform.ENVELOPED, (TransformParameterSpec) null));

    Reference reference = xmlSignatureFactory.newReference("", xmlSignatureFactory.newDigestMethod(DigestMethod.SHA1, null),
            transformList, null, null);

    SignedInfo signedInfo = xmlSignatureFactory.newSignedInfo(xmlSignatureFactory.newCanonicalizationMethod
            (CanonicalizationMethod.INCLUSIVE, (C14NMethodParameterSpec) null),
            xmlSignatureFactory.newSignatureMethod(SignatureMethod.RSA_SHA1, null),
            Collections.singletonList(reference));

    KeyInfoFactory keyInfoFactory = xmlSignatureFactory.getKeyInfoFactory();
    X509Certificate x509Certificate = (X509Certificate) publicKey;
    List<X509Certificate> x509CertificateList = new ArrayList<X509Certificate>();
    x509CertificateList.add(x509Certificate);
    X509Data x509Data = keyInfoFactory.newX509Data(x509CertificateList);
    KeyInfo keyInfo = keyInfoFactory.newKeyInfo(Collections.singletonList(x509Data));

    XMLSignature xmlSignature = xmlSignatureFactory.newXMLSignature(signedInfo, keyInfo);
    xmlSignature.sign(domSignContext);

    return document;
}
