public void copy(File src, File trg, FileFilter filter) throws IOException {

    if (src.isDirectory()) {
        // if source is directory, create the target directory if not already exists
        if (! trg.exists()) {
            trg.mkdirs();
        }

        // list all files and directories in the source directory
        String[] files = src.list();

        for (String file : files) {
            // call the function recursively for all files and directories in the source directory
            File srcFile = new File(src, file);
            File trgFile = new File(trg, file);
            copy(srcFile, trgFile, filter);
        }
    } else {
        // if source is a file, copy the file
        FileInputStream in = new FileInputStream(src);
        FileOutputStream out = new FileOutputStream(trg);
        byte[] buffer = new byte[1024];
        int length;

        while ((length = in.read(buffer)) > 0) {
            out.write(buffer, 0, length);
        }

        in.close();
        out.close();
    }
}
