import java.util.concurrent.atomic.AtomicLong;

public class UniqueIDGenerator {
   private static final int LENGTH = 15;
   private static final char[] ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789".toCharArray();
   private static final AtomicLong LAST_TIME_MS = new AtomicLong();
   private static final int[] DIGITS = new int[LENGTH];

   static {
      for (int i = 0; i < LENGTH; i++) {
         DIGITS[i] = ALPHABET.length - i - 1;
      }
   }

   public static byte[] getNextID() {
      long currentTimeMS = System.currentTimeMillis();
      long lastTimeMS;
      int[] digits = new int[LENGTH];
      synchronized (UniqueIDGenerator.class) {
         lastTimeMS = LAST_TIME_MS.get();
         if (currentTimeMS == lastTimeMS) {
            try {
               UniqueIDGenerator.class.wait(1);
            } catch (InterruptedException e) {
            }
            currentTimeMS = System.currentTimeMillis();
         }
         if (currentTimeMS < lastTimeMS) {
            throw new RuntimeException("Time is running backwards! Please fix your system clock.");
         }
         LAST_TIME_MS.set(currentTimeMS);
         for (int i = LENGTH - 1; i >= 0; i--) {
            digits[i] = DIGITS[i] + (int) (currentTimeMS % ALPHABET.length);
            if (digits[i] >= ALPHABET.length) {
               digits[i] -= ALPHABET.length;
            }
            currentTimeMS /= ALPHABET.length;
         }
      }
      byte[] id = new byte[LENGTH];
      for (int i = 0; i < LENGTH; i++) {
         id[i] = (byte) ALPHABET[digits[i]];
      }
      return id;
   }
} 
