public static boolean isAssignable(Class<?> destination, Class<?> source) {
    if (destination.isAssignableFrom(source)) {
        return true;
    } else if (destination.isPrimitive()) {
        Class<?> boxedDestination = getBoxedClass(destination);
        return boxedDestination != null && boxedDestination.isAssignableFrom(source);
    } else {
        Class<?> boxedSource = getBoxedClass(source);
        return boxedSource != null && destination.isAssignableFrom(boxedSource);
    }
}

private static Class<?> getBoxedClass(Class<?> c) {
    if (c == int.class) {
        return Integer.class;
    } else if (c == boolean.class) {
        return Boolean.class;
    } else if (c == long.class) {
        return Long.class;
    } else if (c == float.class) {
        return Float.class;
    } else if (c == double.class) {
        return Double.class;
    } else if (c == char.class) {
        return Character.class;
    } else if (c == byte.class) {
        return Byte.class;
    } else if (c == short.class) {
        return Short.class;
    } else {
        return null;
    }
}
