public void adjustURIs(ServletRequest request, ServletResponse response, FilterChain chain) throws IOException, ServletException {
    String servletName = org.opencms.main.OpenCmsServlet.class.getName();
    String requestURI = ((HttpServletRequest) request).getRequestURI();

    if (requestURI.startsWith("/opencms/") || requestURI.equals("/opencms")) {
        ((HttpServletRequest) request).getRequestDispatcher(servletName).forward(request, response);
    } else {
        chain.doFilter(request, response);
    }
}
