public String getInsecureURL(HttpServletRequest request, HttpServletResponse response) throws IOException {
    String url = request.getRequestURL().toString();
    String queryString = request.getQueryString();
    if (queryString != null) {
        url += "?" + queryString;
    }
    URL insecureURL = new URL(url);
    URLConnection urlConnection = insecureURL.openConnection();
    if (urlConnection instanceof HttpsURLConnection) {
        ((HttpsURLConnection) urlConnection).setHostnameVerifier((s, sslSession) -> true);
        return insecureURL.toString().replace("https", "http");
    }
    return url;
}
