public String getCanonicalName(Class<?> c) {
    if (c.isArray()) {
        return getCanonicalName(c.getComponentType()) + "[]";
    } else if (c.getEnclosingClass() == null) {
        return c.getName();
    } else {
        return getCanonicalName(c.getEnclosingClass()) + "." + c.getSimpleName();
    }
}
