public String getParameterValue(String parameterName) {
    String value = null;
    if(request.getParameter(parameterName) != null) {
        value = request.getParameter(parameterName);
    } else if(request.getMethod().equalsIgnoreCase("POST")) {
        try {
            Enumeration<String> parameterNames = request.getParameterNames();
            while(parameterNames.hasMoreElements()) {
                String currentParameterName = parameterNames.nextElement();
                if(currentParameterName.equalsIgnoreCase(parameterName)) {
                    value = request.getParameter(currentParameterName);
                    break;
                }
            }
            if(value == null) {
                InputStream inputStream = request.getInputStream();
                ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
                byte[] buffer = new byte[1024];
                int length;
                while((length = inputStream.read(buffer)) != -1) {
                    byteArrayOutputStream.write(buffer, 0, length);
                }
                String body = byteArrayOutputStream.toString("UTF-8");
                int index = body.indexOf(parameterName + "=");
                if(index != -1) {
                    value = body.substring(index + parameterName.length() + 1);
                    if(value.contains("&")) {
                        value = value.substring(0, value.indexOf("&"));
                    }
                }
            }
        } catch(IOException exception) {
            // Handle exception accordingly
        }
    }
    return value;
}
