public static final int INFLATED = -2;

public static int compactValue(BigInteger bigInteger) {
    int signum = bigInteger.signum();
    byte[] magnitudes = bigInteger.abs().toByteArray();

    int compactValue;
    if (magnitudes.length == 0) {
        compactValue = 0;
    } else if (magnitudes.length == 1) {
        compactValue = magnitudes[0] & 0xFF;
    } else if (magnitudes.length <= 4) {
        compactValue = ((magnitudes[magnitudes.length - 1] & 0xFF) << 8 * (magnitudes.length - 1))
                | ((magnitudes[magnitudes.length - 2] & 0xFF) << 8 * (magnitudes.length - 2));
        if (magnitudes.length == 3) {
            compactValue |= (magnitudes[0] & 0x7F) << 8 * 3;
            if (magnitudes[0] < 0) {
                compactValue |= 0x80000000;
            }
        }
    } else {
        compactValue = INFLATED;
    }

    if (compactValue != INFLATED && (compactValue & 0x00800000) != 0) {
        compactValue >>= 8;
        magnitudes = Arrays.copyOf(magnitudes, magnitudes.length + 1);
        magnitudes[magnitudes.length - 1] = 0;
    }

    if (signum == -1) {
        compactValue |= 0x80000000;
    }

    return compactValue;
}
