import javax.servlet.http.HttpServletRequest;
import java.util.HashMap;
import java.util.Map;

public class ParametersUtils {

    public static Map<String, String> getAllParameters(HttpServletRequest request) {
        Map<String, String> allParams = new HashMap<>();

        // retrieve query parameters
        Map<String, String[]> queryParams = request.getParameterMap();
        for (Map.Entry<String, String[]> param : queryParams.entrySet()) {
            String[] values = param.getValue();
            if (values.length > 0) {
                allParams.put(param.getKey(), values[0]);
            }
        }

        // retrieve post parameters
        Map<String, String[]> postParams = request.getParameterMap();
        for (Map.Entry<String, String[]> param : postParams.entrySet()) {
            String[] values = param.getValue();
            if (values.length > 0) {
                allParams.put(param.getKey(), values[0]);
            }
        }

        // retrieve request parameters
        Object[] requestParams = request.getParameterMap().values().toArray();
        for (Object o : requestParams) {
            String[] values = (String[]) o;
            for (String value : values) {
                allParams.put(value, "");
            }
        }

        return allParams;
    }
}
