public void commitBatch(boolean force) throws SQLException {
    try {
        conn.executeBatch();
        conn.commit();
    } catch (SQLException e) {
        conn.rollback();
        throw e;
    } finally {
        if (force) {
            conn.commit();
        }
    }
}
