import java.util.Arrays;

public InputType getLayerOutputType(InputType[] inputType) throws InvalidKerasConfigurationException {
    if (inputType == null || inputType.length == 0) {
        throw new InvalidKerasConfigurationException("Invalid input types");
    }
    InputType outputType;
    if (inputType.length == 1) {
        outputType = inputType[0];
    } else if (Arrays.stream(inputType).allMatch(t -> t instanceof InputType.InputTypeFeedForward)) {
        outputType = InputType.feedForward(((InputType.InputTypeFeedForward[])inputType));
    } else {
        throw new InvalidKerasConfigurationException("Input types cannot be merged: " + Arrays.toString(inputType));
    }
    return outputType;
}
