public String formatOutputFile(List<String> columns, List<String> lines) throws IOException {
    StringBuilder sb = new StringBuilder();
    int numCols = columns.size();

    // add column headers
    for (int i = 0; i < numCols; i++) {
        sb.append(columns.get(i));
        if (i < numCols - 1) {
            sb.append("\t");
        }
    }
    sb.append("\n");

    // add lines
    for (String line : lines) {
        String[] values = line.split(",");
        for (int i = 0; i < numCols; i++) {
            sb.append(values[i]);
            if (i < numCols - 1) {
                sb.append("\t");
            }
        }
        sb.append("\n");
    }
    return sb.toString();
}
