public void determineQualities(Object bean, Object visitor) throws IllegalAccessException {
    Class<?> clazz = bean.getClass();
    Field[] fields = clazz.getDeclaredFields();
    for(Field field : fields) {
        field.setAccessible(true);
        Object value = field.get(bean);
        String name = field.getName();
        Class<?> type = field.getType();
        // Call the appropriate visitor method based on field type
        if(type == int.class) {
            ((Visitor)visitor).visitInt(name, (int)value);
        } else if(type == double.class) {
            ((Visitor)visitor).visitDouble(name, (double)value);
        } else if(type == String.class) {
            ((Visitor)visitor).visitString(name, (String)value);
        } else {
            // Throw an error if the type is not supported by the visitor
            throw new IllegalArgumentException("Unsupported field type: " + type.getName());
        }
    }
}
