public void setInverse(double[][] inv) {
    int n = inv.length;
    double[][] identity = new double[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            identity[i][j] = i == j ? 1 : 0;
        }
    }

    for (int j = 0; j < n; j++) {
        double[] col = new double[n];
        for (int i = 0; i < n; i++) {
            col[i] = identity[i][j];
        }

        for (int k = 0; k < n; k++) {
            double[] row = inv[k];
            double dotProduct = 0;
            for (int m = 0; m < n; m++) {
                dotProduct += row[m] * col[m];
            }
            identity[k][j] = dotProduct;
        }
    }

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            inv[i][j] = identity[i][j];
        }
    }
}
