import java.util.*;

public class Main {

    public static <T extends Comparable<? super T>> List<T> getMaxElements(Iterable<? extends T> iterable) throws NoSuchElementException {
        Iterator<? extends T> iterator = iterable.iterator();
        if (!iterator.hasNext()) {
            throw new NoSuchElementException();
        }
        List<T> result = new ArrayList<>();
        T max = iterator.next();
        result.add(max);
        while (iterator.hasNext()) {
            T element = iterator.next();
            int cmp = element.compareTo(max);
            if (cmp > 0) {
                max = element;
                result.clear();
                result.add(max);
            } else if (cmp == 0) {
                result.add(element);
            }
        }
        return result;
    }

}
