public void findClassLoaderDelegationOrder(ClassLoader classLoader, ClassLoaderOrder classLoaderOrder) {
    if (classLoader == null || classLoaderOrder == null) {
        throw new IllegalArgumentException("ClassLoader and ClassLoaderOrder must not be null");
    }

    List<ClassLoader> delegationOrder = new ArrayList<>();
    ClassLoader currentClassLoader = classLoader;

    while (currentClassLoader != null) {
        delegationOrder.add(currentClassLoader);
        currentClassLoader = currentClassLoader.getParent();
    }

    Collections.reverse(delegationOrder);
    classLoaderOrder.setDelegationOrder(delegationOrder);
}
