public Set<String> removeEntriesBelowThreshold(Map<String, Integer> counter, int countThreshold) {
    Set<String> removedEntries = new HashSet<>();
    counter.entrySet().removeIf(entry -> {
        if (entry.getValue() < countThreshold) {
            removedEntries.add(entry.getKey());
            return true;
        }
        return false;
    });
    return removedEntries;
}
