public int[][] addColumn(int[][] matrix, int j) {
    int rows = matrix.length;
    int cols = matrix[0].length;
    int[][] result = new int[rows][cols+1];

    for (int i = 0; i < rows; i++) {
        for (int k = 0; k < j; k++) {
           result[i][k] = matrix[i][k];    
        }
        result[i][j] = 0;
        for (int k = j+1; k <= cols; k++) {
            result[i][k] = matrix[i][k-1];    
        }
    }
    return result;
}
