public Collection<Epics> getEpics(Member member, Filter filter) {
    // Assuming there is an Epics class with relevant fields and methods
    Collection<Epics> epicsOwned = new ArrayList<>();
    // iterate through all the epics
    for (Epics epic : member.getOwnedEpics()) {
        if (filter == null || filter.shouldInclude(epic)) {
            // add epic to the collection if it passes the filter
            epicsOwned.add(epic);
        }
    }
    return epicsOwned;
}
