public Duration parseDuration(Properties properties, double value, TimeUnit targetTimeUnit, double factor) {
    double totalMinutes = value / factor;
    long minutes = (long) totalMinutes;
    long seconds = (long) ((totalMinutes - minutes) * 60);
    long milliseconds = (long) ((totalMinutes - minutes - (double) seconds / 60) * 60 * 1000);

    long durationInMilliseconds = TimeUnit.MILLISECONDS.convert(minutes, TimeUnit.MINUTES)
            + TimeUnit.MILLISECONDS.convert(seconds, TimeUnit.SECONDS)
            + milliseconds;

    return Duration.of(durationInMilliseconds, targetTimeUnit);
}
