import java.io.*;
import java.util.zip.*;

public static void compressToZip(String format, String source, String target, boolean includeBaseFolder, String mode) throws IOException {
    final int BUFFER_SIZE = 1024;
    FileOutputStream fos = null;
    ZipOutputStream zos = null;
    try {
        fos = new FileOutputStream(target);
        zos = new ZipOutputStream(fos);
        byte[] bytes = new byte[BUFFER_SIZE];

        File sourceFile = new File(source);
        if (sourceFile.isFile()) {
            addFileToZip(zos, sourceFile, sourceFile.getName(), includeBaseFolder, bytes);
        } else if (sourceFile.isDirectory()) {
            for (File file : sourceFile.listFiles()) {
                addFileToZip(zos, file, file.getName(), includeBaseFolder, bytes);
            }
        }
    } finally {
        if (zos != null) {
            zos.close();
        }
        if (fos != null) {
            fos.close();
        }
    }
}

private static void addFileToZip(ZipOutputStream zos, File fileToZip, String fileName, boolean includeBaseFolder, byte[] bytes) throws IOException {
    if (!fileToZip.canRead()) {
        return;
    }
    FileInputStream fis = null;
    try {
        fis = new FileInputStream(fileToZip);
        ZipEntry zipEntry = new ZipEntry(includeBaseFolder ? fileName : fileToZip.getName());
        zos.putNextEntry(zipEntry);
        int length;
        while ((length = fis.read(bytes)) >= 0) {
            zos.write(bytes, 0, length);
        }
        zos.closeEntry();
    } finally {
        if (fis != null) {
            fis.close();
        }
    }
}
