import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public String hashString(String iInput, boolean iIncludeAlgorithm) {
    try {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        byte[] hash = digest.digest(iInput.getBytes("UTF-8"));
        StringBuilder hashedString = new StringBuilder();
        for (byte b : hash) {
            hashedString.append(String.format("%02x", b));
        }
        if (iIncludeAlgorithm) {
            return "SHA-256: " + hashedString.toString();
        } else {
            return hashedString.toString();
        }
    } catch (NoSuchAlgorithmException | UnsupportedEncodingException ex) {
        System.out.println("Error occurred while hashing: " + ex.getMessage());
        return null;
    }
}
