public void createRRD() {
    try {
        // path to the rrdtool binary
        String rrdToolPath = "/usr/bin/rrdtool";
        // command to create rrd database file
        String[] command = {rrdToolPath, "create", "/path/to/rrd/file.rrd", "--start", "now", "--step", "60", "DS:temperature:GAUGE:120:U:U", "RRA:AVERAGE:0.5:1:120", "RRA:AVERAGE:0.5:5:720", "RRA:AVERAGE:0.5:15:1440"};
        // execute the command
        Process process = Runtime.getRuntime().exec(command);
        // print any output or error messages from the command
        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        String line;
        while ((line = reader.readLine()) != null) {
            System.out.println(line);
        }
        reader.close();
        reader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
        while ((line = reader.readLine()) != null) {
            System.out.println(line);
        }
        reader.close();
        // wait for the command to finish
        int exitCode = process.waitFor();
        if (exitCode != 0) {
            System.out.println("Error creating RRD database file!");
        } else {
            System.out.println("RRD database file created successfully.");
        }
    } catch (Exception e) {
        e.printStackTrace();
    }
}
