public String getGenre() throws ID3v2FormatException {
    if (genre == null) {
        return "";
    }
    if (genre.length() > 1 && genre.charAt(0) == '(') {
        try {
            String numberString = genre.substring(1, 3);
            int number = Integer.parseInt(numberString);
            String genreName = ID3v1Tag.GENRES[number];
            return genreName;
        } catch (NumberFormatException e) {
            throw new ID3v2FormatException("Invalid genre format: " + genre);
        }
    }
    return genre;
}
