public class ConcurrentRequestLimiter implements Client {
    private final Client client;
    private final Semaphore semaphore;

    public ConcurrentRequestLimiter(Client client, int maxConcurrentRequests) {
        this.client = client;
        this.semaphore = new Semaphore(maxConcurrentRequests);
    }

    @Override
    public Response execute(Request request) throws IOException {
        try {
            semaphore.acquire();
            return client.execute(request);
        } catch (InterruptedException e) {
            throw new IOException("Interrupted while waiting for permit", e);
        } finally {
            semaphore.release();
        }
    }
}
