public static Object invokeMethod(
            final ELContext context, final Object base, final Object method,
            final Class<?>[] paramTypes, final Object[] params) throws MethodNotFoundException,
            ELException {
        if (base == null || method == null) {
            throw new MethodNotFoundException(MessageFactory.get("error.method.notfound", String.valueOf(base), method));
        }

        final Class<?> clazz = base.getClass();
        final String methodName = (String) method;

        if (paramTypes == null) {
            // treat it like a no-arg method
            for (final Method m : clazz.getMethods()) {
                if (m.getParameterTypes().length == 0 && m.getName().equals(methodName)) {
                    return invokeMethod(context, base, m.getName(), null, params);
                }
            }
        } else {
            try {
                final Method m = clazz.getMethod(methodName, paramTypes);
                // If invoke will fail we need to error before the coercion attempts
                final SecurityManager sm = System.getSecurityManager();
                if (sm != null) {
                    sm.checkPermission(new ReflectPermission("suppressAccessChecks"));
                }
                return m.invoke(base, params);
            } catch (final NoSuchMethodException e) {
                // ignore
            } catch (final SecurityException se) {
                throw new ELException(se);
            } catch (final IllegalArgumentException e) {
                throw new ELException(e);
            } catch (final IllegalAccessException e) {
                throw new ELException(e);
            } catch (final InvocationTargetException e) {
                Throwable cause = e.getCause();
                if (cause instanceof ThreadDeath) {
                    throw (ThreadDeath) cause;
                }
                throw new ELException(cause);
            }
        }

        throw new MethodNotFoundException(MessageFactory.get("error.method.notfound", clazz.getName(), methodName, Arrays.toString(paramTypes)));
    }
