import org.apache.logging.log4j.Level;

public class TangoToLog4j {

    public static Level convertToLog4jLevel(String tangoLevel) {
        switch (tangoLevel) {
            case "TRACE":
                return Level.TRACE;
            case "DEBUG":
                return Level.DEBUG;
            case "INFO":
                return Level.INFO;
            case "WARN":
                return Level.WARN;
            case "ERROR":
                return Level.ERROR;
            case "FATAL":
                return Level.FATAL;
            default:
                throw new IllegalArgumentException("Invalid TANGO logging level: " + tangoLevel);
        }
    }
}
