public List<Requirement> getMergedRequirements(List<Config> configs) {
    List<Requirement> mergedRequirements = new ArrayList<>();

    for (Config config : configs) {
        for (Requirement requirement : config.getRequirements()) {
            if (requirement.getExtends() != null) {
                // Find the rule with the same id as the 'extends' value
                Requirement baseRequirement = config.getRequirements()
                        .stream()
                        .filter(r -> requirement.getExtends().equals(r.getRuleId()))
                        .findFirst()
                        .orElse(null);

                if (baseRequirement != null) {
                    // Merge the base requirement's whitelist with the current requirement's whitelist
                    Set<String> mergedWhitelist = new HashSet<>(baseRequirement.getWhitelist());
                    mergedWhitelist.addAll(requirement.getWhitelist());

                    // Create a new requirement with the merged whitelist and add it to the list of merged requirements
                    Requirement mergedRequirement = new Requirement(requirement.getRuleId(), mergedWhitelist, requirement.getExtends());
                    mergedRequirements.add(mergedRequirement);
                }
            } else {
                // If the requirement doesn't 'extend' another rule, add it to the list of merged requirements as is
                mergedRequirements.add(requirement);
            }
        }
    }

    return mergedRequirements;
}
