public String buildHtmlTag(String tag, String clazz, String content) {
    String htmlOpeningTag = "<" + tag;
    if (clazz != null && !clazz.isEmpty()) {
        htmlOpeningTag += " class=\"" + clazz + "\"";
    }
    htmlOpeningTag += ">";
    String htmlClosingTag = "</" + tag + ">";
    return htmlOpeningTag + content + htmlClosingTag;
}
