import org.jsoup.nodes.Element;
import org.jsoup.nodes.Node;
import org.jsoup.nodes.TextNode;
import org.jsoup.select.NodeVisitor;

import org.apache.commons.lang3.StringUtils;

public class DOMNodeConverter {

    public static String buildNode(Node node){

        StringBuilder builder = new StringBuilder();

        node.traverse(new NodeVisitor() {

            public void head(Node node, int depth) {

                // If it's a text node, append its text content to the builder
                if (node instanceof TextNode) {
                    builder.append(((TextNode) node).getWholeText());
                }

                // If it's an element node, append its corresponding MessageML symbol
                if (node instanceof Element) {
                    Element el = (Element) node;
                    switch (el.tagName()) {
                        case "b":
                            builder.append("*");
                            break;
                        case "i":
                            builder.append("_");
                            break;
                        case "a":
                            builder.append("[");
                            builder.append(el.attr("href"));
                            builder.append("]");
                            break;
                        // Add more cases as needed
                        default:
                            // Do nothing
                            break;
                    }
                }
            }

            public void tail(Node node, int depth) {

                // If it's an element node, append its closing MessageML symbol
                if (node instanceof Element) {
                    Element el = (Element) node;
                    switch (el.tagName()) {
                        case "b":
                            builder.append("*");
                            break;
                        case "i":
                            builder.append("_");
                            break;
                        case "a":
                            builder.append("(");
                            builder.append(StringUtils.substringBetween(el.outerHtml(), ">", "</a>"));
                            builder.append(")");
                            break;
                        // Add more cases as needed
                        default:
                            // Do nothing
                            break;
                    }
                }
            }
        });

        return builder.toString();
    }
}
