private void lazyInitForReading() throws JMSException {
    if (!this.initialisedForReading) {
        this.initialisedForReading = true;

        ByteBuffer buffer = ByteBuffer.wrap(this.bytes);

        // Read the JMS header
        buffer.get(this.jmsHeaderBytes, 0, JMS_HEADER_SIZE);

        // Read the JMS properties
        this.propertiesSize = this.propertyDecoder.decodeProperties(buffer, this.properties);

        // Calculate JMS message body offset
        this.bodyOffset = this.jmsHeaderBytes.length + this.propertiesSize;

        // Calculate JMS message body length
        this.bodyLength = this.getLength() - this.bodyOffset;
    }
}
