import java.lang.reflect.Method;
import java.util.Random;

public static <T> void fillEntityWithRandomValues(Class<T> entityClass, int count, T entity) throws Exception {
    Random random = new Random();
    for (int i = 0; i < count; i++) {
        for (Method method : entityClass.getMethods()) {
            if (isSetterMethod(method)) {
                Class<?> parameterType = method.getParameterTypes()[0];
                if (isValidParameterType(parameterType)) {
                    Object value = generateRandomValue(parameterType, random);
                    method.invoke(entity, value);
                }
            }
        }
    }
}

private static boolean isSetterMethod(Method method) {
    return method.getName().startsWith("set")
            && method.getParameterCount() == 1
            && !void.class.equals(method.getReturnType());
}

private static boolean isValidParameterType(Class<?> parameterType) {
    return parameterType.equals(Boolean.class) ||
            parameterType.equals(Byte.class) ||
            parameterType.equals(Short.class) ||
            parameterType.equals(Integer.class) ||
            parameterType.equals(Long.class) ||
            parameterType.equals(Float.class) ||
            parameterType.equals(Double.class) ||
            parameterType.equals(String.class);
}

private static Object generateRandomValue(Class<?> parameterType, Random random) {
    if (parameterType.equals(Boolean.class)) {
        return random.nextBoolean();
    } else if (parameterType.equals(Byte.class)) {
        return (byte) random.nextInt();
    } else if (parameterType.equals(Short.class)) {
        return (short) random.nextInt();
    } else if (parameterType.equals(Integer.class)) {
        return random.nextInt();
    } else if (parameterType.equals(Long.class)) {
        return random.nextLong();
    } else if (parameterType.equals(Float.class)) {
        return random.nextFloat();
    } else if (parameterType.equals(Double.class)) {
        return random.nextDouble();
    } else if (parameterType.equals(String.class)) {
        byte[] array = new byte[7];
        random.nextBytes(array);
        return new String(array);
    } else {
        return null;
    }
}
