public BigDecimal getBigDecimalFromRawBinaryFormat(Column columnInfo) throws SQLException {
    if (columnInfo.getSqlType() != Types.NUMERIC && columnInfo.getSqlType() != Types.DECIMAL) {
        throw new SQLException("Column is not numeric");
    }

    byte[] rawBytes = columnInfo.getRawBytes();
    BigInteger unscaledValue = new BigInteger(rawBytes);
    int scale = columnInfo.getScale();
    return new BigDecimal(unscaledValue, scale);
}
