public String changeTimestampFormat(String isoTimestamp, String newFormat) {
    SimpleDateFormat isoFormatter = new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'");
    SimpleDateFormat newFormatter = new SimpleDateFormat(newFormat);

    try {
        Date date = isoFormatter.parse(isoTimestamp);
        return newFormatter.format(date);
    } catch (Exception e) {
        System.out.println("An exception occurred: " + e.getMessage());
        return null;
    }
}
