public int guessFluffedDataSize(List<?> payloadData) {
    if (payloadData == null || payloadData.isEmpty()) {
        return 0;
    }

    int size = 0;
    for (Object obj : payloadData) {
        if (obj instanceof String) {
            size += ((String) obj).length() * 2;
        } else if (obj instanceof Integer) {
            size += Integer.BYTES;
        } else if (obj instanceof Long) {
            size += Long.BYTES;
        } else if (obj instanceof Double) {
            size += Double.BYTES;
        } else if (obj instanceof Float) {
            size += Float.BYTES;
        } else if (obj instanceof Boolean) {
            size += Integer.BYTES; // Assuming that Boolean is represented as an Integer (4 bytes)
        } else if (obj instanceof Character) {
            size += Character.BYTES;
        } else if (obj instanceof byte[]) {
            size += ((byte[]) obj).length;
        } else if (obj instanceof short[]) {
            size += ((short[]) obj).length * Short.BYTES;
        } else if (obj instanceof int[]) {
            size += ((int[]) obj).length * Integer.BYTES;
        } else if (obj instanceof long[]) {
            size += ((long[]) obj).length * Long.BYTES;
        } else if (obj instanceof float[]) {
            size += ((float[]) obj).length * Float.BYTES;
        } else if (obj instanceof double[]) {
            size += ((double[]) obj).length * Double.BYTES;
        } else if (obj instanceof char[]) {
            size += ((char[]) obj).length * Character.BYTES;
        } else if (obj instanceof boolean[]) {
            size += ((boolean[]) obj).length * Integer.BYTES; // Assuming that boolean is represented as an Integer (4 bytes)
        } else {
            // For any other type of Object which is not a primitive array or one of the
            // known primitive types, we use reflection to estimate the size
            try {
                Field field = obj.getClass().getDeclaredField("BYTES");
                if (field != null) {
                    size += (int) field.get(null);
                }
            } catch (NoSuchFieldException | IllegalAccessException ignored) {
            }
        }
    }

    return size;
}
