import java.nio.channels.FileChannel;
import java.nio.file.Path;
import reactor.core.publisher.Flux;
import reactor.netty.ByteBufFlux;
import reactor.netty.resources.LoopResources;

public class MyClass {
    public static ByteBufFlux openFileChannelAndStream(Path path, int maxChunkSize) throws IOException {
        FileChannel channel = FileChannel.open(path);
        return ByteBufFlux.fromInbound(Flux.using(
                () -> channel,
                ch -> {
                    // allocate a ByteBuf with a capacity of maxChunkSize, and read the data from FileChannel into it
                    return ByteBufAllocator.DEFAULT.buffer(maxChunkSize).writeBytes(ch.map(ByteBuffer::wrap).orElse(ByteBuffer.allocate(0)));
                },
                // close the FileChannel when we're done
                ch -> ch.close(),
                // we want an infinite stream, so we just return true to indicate that we haven't reached the end of the stream yet
                ch -> true
        ), LoopResources.create("my-group"));
    }
}
