public static String getContainerNameFromUri(String resourceAddress, boolean usePathStyleUris) throws IllegalArgumentException {
    if (resourceAddress == null || resourceAddress.isEmpty()) {
        throw new IllegalArgumentException("Resource address cannot be null or empty");
    }

    String[] parts = resourceAddress.split("/");
    String containerName;

    if (usePathStyleUris) {
        if (parts.length < 2) {
            throw new IllegalArgumentException("Invalid resource address for path-style uri");
        }
        containerName = parts[1];
    } else {
        if (parts.length < 1) {
            throw new IllegalArgumentException("Invalid resource address for non-path-style uri");
        }
        containerName = parts[0];
    }

    return containerName;
}
