public void setFileAttributes(File res, String attributes) throws PageException, IOException {
    try {
        Path file = res.toPath();
        DosFileAttributes dosAttrs = Files.readAttributes(file, DosFileAttributes.class);

        String[] attributeList = attributes.split(" ");
        for (String attr : attributeList) {
            switch (attr) {
                case "r":
                    dosAttrs = dosAttrs.toBuilder().setReadOnly(true).build();
                    break;
                case "h":
                    dosAttrs = dosAttrs.toBuilder().setHidden(true).build();
                    break;
                case "a":
                    dosAttrs = dosAttrs.toBuilder().setArchive(true).build();
                    break;
                case "s":
                    dosAttrs = dosAttrs.toBuilder().setSystem(true).build();
                    break;
                default:
                    throw new PageException("Invalid attribute: " + attr);
            }
        }

        Files.setAttribute(file, "dos:attributes", dosAttrs);
    } catch (UnsupportedOperationException | IllegalArgumentException | FileSystemException e) {
        throw new PageException("Failed to set file attributes", e);
    }
}
