public Collection<Object> decorateQuery(JDOQuery<?> query) {
    if (query == null) {
        throw new IllegalArgumentException("JDO query object cannot be null");
    }

    // Pagination
    int limit = 10; // default limit
    Integer offset = 0;
    query.setRange(offset, limit);

    // Ordering
    String orderBy = "defaultProperty"; // default property to sort by
    QueryUtils.checkOrdering(query.getCandidateClass(), orderBy); // check if property is valid for ordering
    query.setOrdering(orderBy);

    // Sort direction
    boolean ascending = true; // default sort direction
    QueryUtils.checkSortDirection(query.getCandidateClass(), orderBy, ascending); // check if sorting direction is valid
    query.setOrdering(orderBy + (ascending ? " asc" : " desc"));

    return query.execute();
}
