public static <T> Collection<SyncThread<T>> getSyncThreads(int num, Callable<T> callable) throws InterruptedException {
    if (num <= 0) {
        throw new IllegalArgumentException("Invalid number of threads: " + num);
    }
    Collection<SyncThread<T>> threads = new ArrayList<>(num);
    final CountDownLatch startGate = new CountDownLatch(1);
    final CountDownLatch endGate = new CountDownLatch(num);
    for (int i = 0; i < num; i++) {
        SyncThread<T> syncThread = new SyncThread<>(callable, startGate, endGate);
        threads.add(syncThread);
        syncThread.start();
    }
    startGate.countDown();
    endGate.await();
    return threads.stream().filter(SyncThread<T>::isDone).collect(Collectors.toList());
}
