public static boolean solve(int order, double[] A, double[] b) {
    int n = 0; // Dimension of matrix
    double[] y = new double[n];
    double sum;

    // Find dimension of matrix
    for (int i = 0; i < A.length; i++) {
        if (A[i] != 0.0) {
            int temp = i / (n + 1);
            if ((i - temp * (n + 1)) == 0) {
                n = temp + 1;
            }
        }
    }

    // Cholesky Decomposition
    for (int j = 0; j < n; j++) {
        for (int i = j; i < n; i++) {
            sum = A[i * n + j];
            for (int k = 0; k < j; k++) {
                sum -= A[j * n + k] * A[i * n + k];
            }
            if (i == j) {
                if (sum <= 0.0) {
                    return false;
                }
                A[i * n + j] = Math.sqrt(sum);
            } else {
                A[i * n + j] = sum / A[j * n + j];
            }
        }
    }

    // Solve Ly=b
    for (int i = 0; i < n; i++) {
        sum = 0.0;
        for (int j = 0; j < i; j++) {
            sum += A[i * n + j] * y[j];
        }
        y[i] = (b[i] - sum) / A[i * n + i];
    }

    // Solve L^T x = y
    for (int i = n - 1; i >= 0; i--) {
        sum = 0.0;
        for (int j = i + 1; j < n; j++) {
            sum += A[j * n + i] * b[j];
        }
        b[i] = (y[i] - sum) / A[i * n + i];
    }

    return true;
}
