import java.lang.reflect.Field;
import java.util.HashSet;
import java.util.Set;

public class MyClass {
    public static Set<Field> getAllFields(Class<?> classs) {
        Set<Field> fields = new HashSet<>();

        // gets fields from the current class
        for (Field field : classs.getDeclaredFields()) {
            fields.add(field);
        }

        // gets fields from the super class recursively
        Class<?> superClass = classs.getSuperclass();
        if (superClass != null) {
            fields.addAll(getAllFields(superClass));
        }

        return fields;
    }
}
