public boolean findEntity(EntityContainer container, int id) {
    EntityVisitor visitor = new EntityVisitor() {
        @Override
        public boolean visit(Entity entity) {
            if (entity.getId() == id) {
                return true;
            }
            return false;
        }
    };
    return walkEntityTree(container, visitor);
}

public boolean walkEntityTree(EntityContainer container, EntityVisitor visitor) {
    for (Entity entity : container.getEntities()) {
        if (visitor.visit(entity)) {
            return true;
        }
        if (entity instanceof EntityContainer) {
            if (walkEntityTree((EntityContainer) entity, visitor)) {
                return true;
            }
        }
    }
    return false;
}
