public void processAllRules(List<Highlight> highlights) {
    // iterate through all the highlights
    for (int i = 0; i < highlights.size(); i++) {
        Highlight currentHighlight = highlights.get(i);

        // process each rule for the current highlight
        for (int j = 0; j < currentHighlight.getRules().size(); j++) {
            Rule currentRule = currentHighlight.getRules().get(j);

            // apply the rule to the current highlight
            if (currentRule.matches(currentHighlight)) {
                currentHighlight.applyRule(currentRule);
            }
        }
    }
}
