public static char advanceChar(String json, int index) throws JSONException {
    char c = json.charAt(index);

    switch (c) {
        case '\"':
        case '/':
        case '\\':
            return c;
        case 'b':
            return '\b';
        case 'f':
            return '\f';
        case 'n':
            return '\n';
        case 'r':
            return '\r';
        case 't':
            return '\t';
        case 'u':
            if (index + 4 > json.length()) {
                throw new JSONException("Invalid unicode sequence at " + index);
            }
            String unicode = json.substring(index + 1, index + 5);
            try {
                return (char) Integer.parseInt(unicode, 16);
            } catch (NumberFormatException e) {
                throw new JSONException("Invalid hex in unicode sequence at " + index, e);
            }
        default:
            throw new JSONException("Illegal escape sequence at " + index);
    }
}
