public List<Event> getMoreEvents(Calendar day) {
   List<Event> events = new ArrayList<>();

   // Get the previous month
   Calendar previousMonth = (Calendar) day.clone();
   previousMonth.add(Calendar.MONTH, -1);

   // Get the next month
   Calendar nextMonth = (Calendar) day.clone();
   nextMonth.add(Calendar.MONTH, 1);

   // Add events from the previous month
   List<Event> previousMonthEvents = getEventsForMonth(previousMonth);
   events.addAll(previousMonthEvents);

   // Add events from the current month
   List<Event> currentMonthEvents = getEventsForMonth(day);
   events.addAll(currentMonthEvents);

   // Add events from the next month
   List<Event> nextMonthEvents = getEventsForMonth(nextMonth);
   events.addAll(nextMonthEvents);

   return events;
}

