public static List<Class<?>> scanClasses(String persistenceUnitRoot) throws IOException, ClassNotFoundException {

    List<Class<?>> classes = new ArrayList<>();

    // Scan the specified directory for classes
    File root = new File(persistenceUnitRoot);
    if (root.exists()) {
        File[] files = root.listFiles();
        for (File file : files) {
            if (file.getName().endsWith(".class")) {
                String className = file.getName().substring(0, file.getName().length() - 6);
                Class<?> cls = Class.forName(className);
                classes.add(cls);
            }
        }
    }

    // Scan referenced jar files for classes
    ClassLoader classLoader = Thread.currentThread().getContextClassLoader();
    Enumeration<URL> urls = classLoader.getResources("");
    while (urls.hasMoreElements()) {
        URL url = urls.nextElement();
        if (url.getProtocol().equals("jar")) {
            JarURLConnection jarConn = (JarURLConnection) url.openConnection();
            JarFile jarFile = jarConn.getJarFile();
            Enumeration<JarEntry> entries = jarFile.entries();
            while (entries.hasMoreElements()) {
                JarEntry jarEntry = entries.nextElement();
                if (jarEntry.getName().endsWith(".class")) {
                    String className = jarEntry.getName().replace("/", ".").substring(0, jarEntry.getName().length() - 6);
                    Class<?> cls = classLoader.loadClass(className);
                    classes.add(cls);
                }
            }
        }
    }

    return classes;
}
