public static <T extends Number> T multiply(T value, T multiplier) {
    if (multiplier == null) {
        throw new IllegalArgumentException("Multiplier must not be null");
    }
    BigDecimal result = new BigDecimal(value.toString()).multiply(new BigDecimal(multiplier.toString()));
    if (value instanceof Integer) {
        return (T) Integer.valueOf(result.intValue());
    } else if (value instanceof Long) {
        return (T) Long.valueOf(result.longValue());
    } else if (value instanceof Float) {
        return (T) Float.valueOf(result.floatValue());
    } else if (value instanceof Double) {
        return (T) Double.valueOf(result.doubleValue());
    } else if (value instanceof BigDecimal) {
        return (T) result;
    } else {
        throw new IllegalArgumentException("Unsupported number type: " + value.getClass());
    }
}
