import java.util.List;

public List<ProjectJob> getProjectJobs(int projectId, int pipelineId) {
    List<ProjectJob> projectJobs = new ArrayList<>();

    // Retrieve the Gitlab API client
    GitlabApiClient client = new GitlabApiClient();

    // Use the client to query project jobs based on projectId and pipelineId
    GitlabProjectJobs jobs = client.getJobs(projectId, pipelineId);

    // Convert the retrieved jobs to project jobs and add them to the list
    for (GitlabJob job : jobs.getJobs()) {
        ProjectJob projectJob = new ProjectJob(job.getId(), job.getName(), job.getStatus());
        projectJobs.add(projectJob);
    }

    return projectJobs;
}
