import java.io.File;
import java.io.FileInputStream;
import java.io.FileNotFoundException;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.util.ArrayList;
import java.util.List;

public class FileConverter {

    public List<OutputStream> convertToListOfOutputStreams(List<File> files) throws FileNotFoundException {
        List<OutputStream> outputStreams = new ArrayList<>();

        for(File file : files) {
            InputStream inputStream = new FileInputStream(file);
            OutputStream outputStream = System.out; // replace with desired output stream
            convertToOutputStream(inputStream, outputStream);

            outputStreams.add(outputStream);
        }

        return outputStreams;
    }

    private void convertToOutputStream(InputStream inputStream, OutputStream outputStream) {
        try {
            byte[] buffer = new byte[1024];
            int length;
            while ((length = inputStream.read(buffer)) != -1) {
                outputStream.write(buffer, 0, length);
            }
            inputStream.close();
            outputStream.flush();
            outputStream.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
