public static void serializeJson(Object jsonVal, Map<Object, Integer> jsonReferenceToId, boolean includeNullValuedFields, int depth, int indentWidth, StringBuilder buf) {
    if (jsonVal == null) {
        if (includeNullValuedFields) {
            buf.append("null");
        }
        return;
    }

    if (jsonVal instanceof JSONObject) {
        JSONObject obj = (JSONObject) jsonVal;
        serializeJsonObject(obj, jsonReferenceToId, includeNullValuedFields, depth, indentWidth, buf);
    } else if (jsonVal instanceof JSONArray) {
        JSONArray arr = (JSONArray) jsonVal;
        serializeJsonArray(arr, jsonReferenceToId, includeNullValuedFields, depth, indentWidth, buf);
    } else {
        buf.append(jsonVal.toString());
    }
}

private static void serializeJsonObject(JSONObject obj, Map<Object, Integer> jsonReferenceToId, boolean includeNullValuedFields, int depth, int indentWidth, StringBuilder buf) {
    buf.append("{");

    List<String> keys = new ArrayList<String>(obj.keySet());
    Collections.sort(keys);

    boolean first = true;
    for (String key : keys) {
        Object val = obj.get(key);

        if (val == null && !includeNullValuedFields) {
            continue;
        }

        if (!first) {
            buf.append(",");
        }
        first = false;

        buf.append("\n");
        addIndent(depth, indentWidth, buf);

        buf.append("\"");
        buf.append(key);
        buf.append("\": ");

        serializeJson(val, jsonReferenceToId, includeNullValuedFields, depth + 1, indentWidth, buf);
    }

    if (!first) {
        buf.append("\n");
        addIndent(depth - 1, indentWidth, buf);
    }

    buf.append("}");
}

private static void serializeJsonArray(JSONArray arr, Map<Object, Integer> jsonReferenceToId, boolean includeNullValuedFields, int depth, int indentWidth, StringBuilder buf) {
    buf.append("[");

    boolean first = true;
    for (int i = 0; i < arr.length(); i++) {
        Object val = arr.get(i);

        if (val == null && !includeNullValuedFields) {
            continue;
        }

        if (!first) {
            buf.append(",");
        }
        first = false;

        buf.append("\n");
        addIndent(depth, indentWidth, buf);

        serializeJson(val, jsonReferenceToId, includeNullValuedFields, depth + 1, indentWidth, buf);
    }

    if (!first) {
        buf.append("\n");
        addIndent(depth - 1, indentWidth, buf);
    }

    buf.append("]");
}

private static void addIndent(int depth, int indentWidth, StringBuilder buf) {
    for (int i = 0; i < depth * indentWidth; i++) {
        buf.append(" ");
    }
}
