public String removeAdditionalQuotes(String value) {
    if(value == null || value.isEmpty()) { // Check if the value is null or empty
        return value;
    }
    if(value.startsWith("\"") && value.endsWith("\"")) { // Check if the value already has quotes
        value = value.substring(1, value.length() - 1); // Remove the quotes
    }
    return value;
}
