public List<BlockingState> sortedCopy(List<BlockingState> blockingStates) {
    List<BlockingState> sortedList = new ArrayList<>(blockingStates);
    sortedList.sort((bs1, bs2) -> {
        if (bs1.getEntitlementId().equals(bs2.getEntitlementId())) {
            return bs1.getBlockedAt().compareTo(bs2.getBlockedAt());
        }
        return bs1.getEntitlementId().compareTo(bs2.getEntitlementId());
    });
    return sortedList;
}
