public List<Note> getFilteredNotes(NoteHandler handler, QueryNotesFilters filters) throws OsmAuthorizationException {
    if (!loggedIn) {
        throw new OsmAuthorizationException("Not logged in!");
    }
    List<Note> notes = handler.getNotes();
    final int MAX_NOTES = filters.getLimit();
    int count = 0;
    List<Note> filteredNotes = new ArrayList<>();

    for(Note note : notes) {
        if(filters.byUser(note.getUserID())) {
            filteredNotes.add(note);
            count++;
        }
        if(count >= MAX_NOTES) {
            break;
        }
    }

    return filteredNotes;
}
