import java.util.function.Function;

public interface HList<Head, Tail extends HList<?, ?>> {

    <T> Lens<HList<Head, Tail>, T, HList<Head, HList<?, ?>>> tail() {
        Function<HList<Head, Tail>, T> getter = (HList<Head, Tail> list) -> (T) list.tail;
        Function<T, Function<HList<Head, Tail>, HList<Head, HList<?, ?>>>> setter =
          (T newValue) -> (HList<Head, Tail> list) -> new HCons<>(list.head, (HList) newValue);
        return Lens.of(getter, setter);
    };

}

public interface Lens<S, T, A, B> {

    S set(T newValue);

    B get(A a);

    InvariantLens<S, T, A, B> invariant();

    <U> Lens<S, U, A, B> andThen(Lens<T, U, A, B> other);

    static <X, Y, A, B> Lens<X, Y, A, B> of(
            Function<X, A> getter,
            Function<Y, Function<X, B>> setter
    ) {
        return new SimpleLens<>(setter::apply, getter);
    }

}

public static class SimpleLens<S, T, A, B> implements Lens<S, T, A, B> {

    private final Function<A, S> setter;
    private final Function<T, B> getter;

    public SimpleLens(Function<A, S> setter, Function<T, B> getter) {
        this.setter = setter;
        this.getter = getter;
    }

    @Override
    public S set(T newValue) {
        return setter.apply(newValue);
    }

    @Override
    public B get(A a) {
        return getter.apply(a);
    }

    @Override
    public InvariantLens<S, T, A, B> invariant() {
        return new InvariantLens<S, T, A, B>() {
            @Override
            public S set(T newValue) {
                return SimpleLens.this.set(newValue);
            }

            @Override
            public B get(A a) {
                return SimpleLens.this.get(a);
            }
        };
    }

    @Override
    public <U> Lens<S, U, A, B> andThen(Lens<T, U, A, B> other) {
        return of(
                a -> other.get(getter.apply(a)),
                u -> a -> setter.apply(other.set(newValue -> setter.apply(newValue)).apply(getter.apply(a)))
        );
    }

}

public interface InvariantLens<S, T, A, B> extends Lens<S, T, A, B> {

    @Override
    InvariantLens<S, T, A, B> invariant();

}
