public Entry<K, V> ceilingEntry(K key) {
    if (isEmpty()) return null;
    Entry<K, V> entry = ceilingEntry(root, key);
    return entry != null && compare(entry.getKey(), key) >= 0 ? entry : null;
}

protected Entry<K, V> ceilingEntry(Node<K, V> node, K key) {
    if (node == null) return null;
    int cmp = compare(key, node.getKey());
    if (cmp == 0) return node;
    if (cmp > 0) return ceilingEntry(node.getRight(), key);
    Entry<K, V> left = ceilingEntry(node.getLeft(), key);
    return left != null ? left : node;
}
