public Optional<Thread> startStdoutConsumer(Process process) {
  Optional<Thread> maybeThread = Optional.empty();
  InputStream stdout = process.getInputStream();
  if (stdout != null) {
    maybeThread = Optional.of(new Thread(() -> {
      try (BufferedReader reader = new BufferedReader(new InputStreamReader(stdout))) {
        String line;
        while ((line = reader.readLine()) != null) {
          // do something with the stdout line
        }
      } catch (Exception e) {
        e.printStackTrace();
      }
    }));
    maybeThread.get().start();
  }
  return maybeThread;
}
