import java.util.Spliterator;
import java.util.function.Consumer;

public class MySpliterator<T> implements Spliterator<T> {

    private final T root;
    private final T[] edges;
    private int index;

    public MySpliterator(T root, T[] edges) {
        this.root = root;
        this.edges = edges;
        this.index = 0;
    }

    @Override
    public boolean tryAdvance(Consumer<? super T> action) {
        if (index == 0) {
            action.accept(root);
            index++;
            return true;
        }
        if (index < edges.length) {
            action.accept(edges[index]);
            index++;
            return true;
        }
        return false;
    }

    @Override
    public Spliterator<T> trySplit() {
        return null; // not implemented
    }

    @Override
    public long estimateSize() {
        return edges.length + 1;
    }

    @Override
    public int characteristics() {
        return NONNULL | ORDERED;
    }

    public static <T> Spliterator<T> createSpliterator(T root, T[] edges) {
        return new MySpliterator<>(root, edges);
    }
}
