public Bundle getWiredBundle(String symbolicName) {
    BundleContext bundleContext = FrameworkUtil.getBundle(getClass()).getBundleContext();
    Bundle[] bundles = bundleContext.getBundles();
    for (Bundle bundle : bundles) {
        if (bundle.getSymbolicName().equals(symbolicName)) {
            BundleWiring bundleWiring = bundle.adapt(BundleWiring.class);
            if (bundleWiring != null) {
                List<BundleWire> bundleWires = bundleWiring.getRequiredWires(null);
                for (BundleWire bundleWire : bundleWires) {
                    if (bundleWire.getProviderWiring().getBundle().getSymbolicName().equals(bundle.getSymbolicName())) {
                        return bundleWire.getProviderWiring().getBundle();
                    }
                }
            }
            return bundle;
        }
    }
    return null;
}
