    if (maskArrays != null) {
        for (int i = 0; i < maskArrays[output].length; i++) {
            maskArrays[output][i] = (maskArrays[output][i] * outputNormalization.get(output).getScale()) + outputNormalization.get(output).getMean();
        }
    }
}
