public String getS3Pairtree(String aBucket, String aBucketPath) throws PairtreeException {
    String pairtreeRoot = "";
    try {
        S3Client s3 = S3Client.builder().region(Region.US_EAST_1).build();

        // Creating Pairtree root directory
        CreateBucketRequest createBucketRequest = CreateBucketRequest
                .builder()
                .bucket(aBucket)
                .createBucketConfiguration(CreateBucketConfiguration.builder()
                        .build()).build();
        s3.createBucket(createBucketRequest);

        String pairtreePath = aBucketPath + "/pairtree_root";

        PutObjectRequest putObjectRequest = PutObjectRequest.builder()
                .bucket(aBucket).key(pairtreePath).build();

        s3.putObject(putObjectRequest);

        pairtreeRoot = "s3://" + aBucket + "/" + pairtreePath;

    } catch (AwsServiceException e) {
        throw new PairtreeException(e.getMessage());
    } catch (SdkClientException e) {
        throw new PairtreeException(e.getMessage());
    }
    return pairtreeRoot;
}
