import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;

public boolean hasSymlink(Path basePath, Path path) {
    Path relativePath = basePath.relativize(path);
    Path currentPath = basePath;
    for (Path element : relativePath) {
        try {
            Path targetPath = currentPath.resolve(element).toRealPath();
            if (!targetPath.startsWith(basePath)) {
                // The symlink points outside the base path
                return true;
            }
            if (!targetPath.equals(currentPath.resolve(element))) {
                // The element is a symlink
                return true;
            }
            currentPath = targetPath;
        } catch (IOException e) {
            // Failed to resolve element path
            return false;
        }
    }
    return false;
}
