        frame.setVisible(true);
        System.out.println(getContentTree(frame));
    }

    public static String getContentTree(JFrame frame) {
        String content = "";
        content += "Frame Size: " + frame.getSize() + "\n";
        content += "Frame Content: \n" + getComponents(frame.getContentPane(), "|");
        return content;
    }

    private static String getComponents(Container container, String prefix) {
        String components = "";
        Component[] children = container.getComponents();
        for (Component child : children) {
            String className = child.getClass().getSimpleName();
            if (child instanceof Container) {
                components += prefix + className + "\n";
                components += getComponents((Container) child, "|" + prefix);
            } else {
                components += prefix + className + "\n";
            }
        }
        return components;
    }
}
