import futures.FastFuture;
import java.util.concurrent.CompletableFuture;

public class FastFutureConverter {

    public static <T> FastFuture<T> toFastFuture(CompletableFuture<T> completableFuture) {
        FastFuture<T> fastFuture = new FastFuture<>();
        completableFuture.whenComplete((result, error) -> {
            if (error != null) {
                fastFuture.completeExceptionally(error);
            } else {
                fastFuture.complete(result);
            }
        });
        return fastFuture;
    }
}
