public int deleteTree(TSDB tsdb, String tree_id, boolean delete_definition) {
  try {
    // Delete branches
    tsdb.delete(tree_id, new String[] { "branch" }, null);

    // Delete leaves
    tsdb.delete(tree_id, new String[] { "leaf" }, null);

    // Delete collisions
    tsdb.delete(tree_id, new String[] { "collision" }, null);

    // Delete not-matched entries
    tsdb.delete(tree_id, new String[] { "notmatched" }, null);

    // Delete tree definition, if requested
    if (delete_definition) {
        tsdb.delete(tree_id, new String[] { "definition" }, null);
    }

    return 0;
  } catch (Exception e) {
    return 1;
  }
}
