public Field[] getColumnFields(int columnIndex) throws SQLException {
    ResultSetMetaData metaData = resultSet.getMetaData();
    int columnCount = metaData.getColumnCount();

    if (columnIndex < 1 || columnIndex > columnCount) {
        throw new SQLException("Invalid column index");
    }

    Field[] fields = new Field[1];
    fields[0] = new Field(metaData.getColumnName(columnIndex), metaData.getColumnTypeName(columnIndex), metaData.getPrecision(columnIndex), metaData.getScale(columnIndex));

    return fields;
}
