public static String decodeGeometry(Geometry geometry, double scale) {
    StringBuilder dAttribute = new StringBuilder();
    for (int i = 0; i < geometry.getNumGeometries(); i++) {
        Geometry childGeometry = geometry.getGeometryN(i);
        if (childGeometry != null) {
            if (childGeometry instanceof LineString) {
                LineString line = (LineString) childGeometry;
                for (int j = 0; j < line.getNumPoints(); j++) {
                    Coordinate coordinate = line.getCoordinateN(j);
                    dAttribute.append(j == 0 ? "M" : "L")
                            .append(coordinate.getX() * scale)
                            .append(",")
                            .append(coordinate.getY() * scale);
                }
            } else if (childGeometry instanceof Polygon) {
                Polygon polygon = (Polygon) childGeometry;
                for (int j = 0; j < polygon.getNumInteriorRing() + 1; j++) {
                    LineString ring = j == 0 ? polygon.getExteriorRing() : polygon.getInteriorRingN(j - 1);
                    for (int k = 0; k < ring.getNumPoints(); k++) {
                        Coordinate coordinate = ring.getCoordinateN(k);
                        dAttribute.append(k == 0 ? "M" : "L")
                                .append(coordinate.getX() * scale)
                                .append(",")
                                .append(coordinate.getY() * scale);
                    }
                    dAttribute.append("Z");
                }
            }
        }
    }
    return dAttribute.toString();
}
