public PhysicalPlan getPhysicalPlan(Topology topology) {
    // create container info for fake stream mgr/container
    ContainerInfo containerInfo = new ContainerInfo();
    containerInfo.setId(1);
    containerInfo.setName("FakeStreamMgrContainer");

    // create list of container instances for the given topology
    List<Instance> instances = new ArrayList<>();
    for (Bolt bolt : topology.getBolts()) {
        Instance instance = new Instance();
        instance.setId(bolt.getId());
        instance.setComponentType(bolt.getComponentType());
        instance.setContainerInfo(containerInfo);
        instances.add(instance);
    }
    for (Spout spout : topology.getSpouts()) {
        Instance instance = new Instance();
        instance.setId(spout.getId());
        instance.setComponentType(spout.getComponentType());
        instance.setContainerInfo(containerInfo);
        instances.add(instance);
    }

    // create physical plan containing the given topology
    PhysicalPlan physicalPlan = new PhysicalPlan();
    physicalPlan.setTopology(topology);
    physicalPlan.setInstances(instances);
    return physicalPlan;
}
