public Segment getNextSegment(int index) {
    // Code to retrieve the segment list
    List<Segment> segments = getSegmentList();

    // Look for the segment with the given index
    for (int i = 0; i < segments.size() - 1; i++) {
        if (segments.get(i).getId() == index) {
            // Return the next segment
            return segments.get(i + 1);
        }
    }

    // Return null if no segment with the given index is found
    return null;
}
