public String normalizeMultiPeriod(String line) {
    // remove any comma that's not after a number
    line = line.replaceAll("(?<![0-9]),", "");

    // remove any duplicate period
    line = line.replaceAll("\\.{2,}", ".");

    // remove any period that's not after a number or before a number
    line = line.replaceAll("(?<!(?: |^)\\d)\\.(?!(?: |$)\\d)", "");

    return line;
}
