public void parseTypeComment(String typeComment) {
    // Regular expression pattern for matching valid types
    String pattern = "(int|long|float|double|boolean|char|byte|short|" +
                     "string|map<\\w+,\\s*\\w+>|list<\\w+>|set<\\w+>|\\w+|" +
                     "\\(\\w+(,\\s*\\w+)*\\)|\\w+\\|\\w+(\\|\\w+)*|\\w+\\s*\\[\\s*\\])";

    Pattern regex = Pattern.compile(pattern);
    Matcher matcher = regex.matcher(typeComment);

    while (matcher.find()) {
        String match = matcher.group();
        System.out.println("Match found: " + match);
    }
}
