public static byte[] longToVarNum(long value) {
    if (value < 0) {
        throw new IllegalArgumentException("Value must be non-negative");
    }

    int numBytes = 0;
    long temp = value;

    while (temp > 0) {
        numBytes++;
        temp >>>= 7;
    }

    if (numBytes == 0) {
        numBytes = 1;
    }

    byte[] varNum = new byte[numBytes];

    for (int i = numBytes - 1; i >= 0; i--) {
        byte b = (byte) (value & 0x7F);

        if (i != numBytes - 1) {
            b |= 0x80;
        }

        varNum[i] = b;
        value >>>= 7;
    }

    return varNum;
}
