public void sendErrorResponse(ChannelHandlerContext channelHandlerContext, HttpRequest httpRequest, String errorMessage, HttpResponseStatus statusCode, Map<String, String> headers) {
    FullHttpResponse response = new DefaultFullHttpResponse(httpRequest.protocolVersion(), statusCode, Unpooled.copiedBuffer(errorMessage, CharsetUtil.UTF_8));
    response.headers().set(HttpHeaderNames.CONTENT_TYPE, "text/plain; charset=UTF-8");
    response.headers().set(HttpHeaderNames.CACHE_CONTROL, HttpHeaderValues.NO_CACHE);
    response.headers().set(HttpHeaderNames.CONTENT_LENGTH, response.content().readableBytes());
    for (Map.Entry<String, String> header : headers.entrySet()) {
        response.headers().set(header.getKey(), header.getValue());
    }
    channelHandlerContext.writeAndFlush(response).addListener(ChannelFutureListener.CLOSE);
}
