public void mergeTracker(List<List<Integer>> tracker) {
    List<List<Integer>> currentTracker = getCurrentTracker(); // assuming there's a method to get the current tracker
    int i = 0;
    int j = 0;
    List<List<Integer>> mergedTracker = new ArrayList<>();

    while (i < currentTracker.size() && j < tracker.size()) {
        if (currentTracker.get(i).get(1) < tracker.get(j).get(0)) {
            mergedTracker.add(currentTracker.get(i));
            i++;
        } else if (currentTracker.get(i).get(0) > tracker.get(j).get(1)) {
            mergedTracker.add(tracker.get(j));
            j++;
        } else {
            int start = Math.min(currentTracker.get(i).get(0), tracker.get(j).get(0));
            int end = Math.max(currentTracker.get(i).get(1), tracker.get(j).get(1));
            mergedTracker.add(Arrays.asList(start, end));
            i++;
            j++;
        }
    }

    while (i < currentTracker.size()) {
        mergedTracker.add(currentTracker.get(i));
        i++;
    }

    while (j < tracker.size()) {
        mergedTracker.add(tracker.get(j));
        j++;
    }

    int maxSafePoint = 0;
    for (List<Integer> range : mergedTracker) {
        if (range.get(1) > maxSafePoint) {
            maxSafePoint = range.get(1);
        }
    }

    setCurrentTracker(mergedTracker); // assuming there's a method to set the current tracker
    setMaxSafePoint(maxSafePoint); // assuming there's a method to set the max safe point
}
