public StreamObserver<Request> executeBidirectionalCall(ManagedChannel channel, MethodDescriptor<Request, Response> method) {
    // Create a call using the channel and method descriptor provided
    // The call should be composed of Request and Response objects
    final ClientCallImpl<Request, Response> call = new ClientCallImpl<>(method, channel.newCall(method, CallOptions.DEFAULT));

    // Create a request stream observer for the call
    // The observer should handle request messages and write them to the stream
    final ClientCallImpl.ClientStream<Request> clientStream = call.createClientStream(new ClientCallImpl.NoopClientStreamListener<Request>());
    final StreamObserver<Request> requestObserver = new StreamObserver<Request>() {
        @Override
        public void onNext(Request request) {
            clientStream.writeMessage(request);
        }

        @Override
        public void onError(Throwable throwable) {
            clientStream.cancel(throwable);
        }

        @Override
        public void onCompleted() {
            clientStream.halfClose();
        }
    };

    // Start the call
    call.start(new ClientCallImpl.ClientCallListener<Response>() {
        // Implementation of the client call listener's methods
        // which handle response messages
    }, new Metadata());

    // Return the request stream observer for the call
    return requestObserver;
}
