public MultivaluedMap<String, String> initMetricMap(List<Agreement> agreements) {
    MultivaluedMap<String, String> metricMap = new MultivaluedHashMap<>();

    for(Agreement agreement: agreements) {
        String metricKey = agreement.getMetricKey();
        String term = agreement.evaluateMetric();
        metricMap.add(metricKey, term);
    }

    return metricMap;
}
