public static CharMatcher inRange(char startInclusive, char endInclusive) {
    if (endInclusive < startInclusive) {
        throw new IllegalArgumentException();
    }
    return new RangedMatcher(startInclusive, endInclusive);
}

private static final class RangedMatcher extends CharMatcher {
    private final char startInclusive;
    private final char endInclusive;

    RangedMatcher(char startInclusive, char endInclusive) {
        this.startInclusive = startInclusive;
        this.endInclusive   = endInclusive;
    }

    @Override
    public boolean matches(char c) {
        return startInclusive <= c && c <= endInclusive;
    }

    @Override
    public String toString() {
        return "CharMatcher.inRange('" + CharMatcher.showCharacter(startInclusive) + "', '" + CharMatcher.showCharacter(endInclusive) + "')";
    }
}
