import java.util.Calendar;
import java.util.TimeZone;

public class SunPosition {

    public static double[] getPosition(Calendar time) {

        double[] position = new double[2];

        double days = julianDate(time) - 2451545.0;
        double jStar = julianCentury(days);
        double meanSolarNoon = meanSolarNoon(jStar);
        double solarMeanAnomaly = solarMeanAnomaly(meanSolarNoon);
        double equationOfCenter = equationOfCenter(solarMeanAnomaly);
        double eclipticLongitude = eclipticLongitude(meanSolarNoon, equationOfCenter);
        double decimalHours = getDecimalHours(time);
        double solarAltitude = calculateSolarAltitude(decimalHours, eclipticLongitude);

        position[0] = solarAltitude;
        position[1] = eclipticLongitude;

        return position;
    }

    private static double julianDate(Calendar time) {
        TimeZone.setDefault(TimeZone.getTimeZone("UTC"));
        long millis = time.getTimeInMillis();
        return ((double) millis / 86400000.0) + 2440587.5;
    }

    private static double julianCentury(double days) {
        return days / 36525.0;
    }

    private static double meanSolarNoon(double jStar) {
        return (357.5291 + (0.98560028 * jStar)) % 360.0;
    }

    private static double solarMeanAnomaly(double meanSolarNoon) {
        return 280.460 + (0.9856474 * meanSolarNoon);
    }

    private static double equationOfCenter(double solarMeanAnomaly) {
        double sinSolarMeanAnomaly = Math.sin(Math.toRadians(solarMeanAnomaly));
        double firstPart = 1.9148 * sinSolarMeanAnomaly;

        double sin2MeanAnomaly = Math.sin(Math.toRadians(2.0 * solarMeanAnomaly));
        double secondPart = 0.0200 * sin2MeanAnomaly;

        double sin3MeanAnomaly = Math.sin(Math.toRadians(3.0 * solarMeanAnomaly));
        double thirdPart = 0.0003 * sin3MeanAnomaly;

        return firstPart + secondPart + thirdPart;
    }

    private static double eclipticLongitude(double meanSolarNoon, double equationOfCenter) {
        return (meanSolarNoon + equationOfCenter + 180.0) % 360;
    }

    private static double getDecimalHours(Calendar time) {
        int hours = time.get(Calendar.HOUR_OF_DAY);
        int minutes = time.get(Calendar.MINUTE);
        int seconds = time.get(Calendar.SECOND);

        return hours + (minutes / 60.0) + (seconds / 3600.0);
    }

    private static double calculateSolarAltitude(double decimalHours, double eclipticLongitude) {
        double sinLatitude = 0.39779 * Math.sin(Math.toRadians(eclipticLongitude));
        double cosLatitude = Math.sqrt(1 - (sinLatitude * sinLatitude));
        double hourAngle = (decimalHours - 12.0) * 15.0;
        double solarAltitude = Math.asin((sinLatitude * Math.sin(Math.toRadians(23.44))) + (cosLatitude * Math.cos(Math.toRadians(23.44)) * Math.cos(Math.toRadians(hourAngle))));

        return Math.toDegrees(solarAltitude);
    }
}
