public void evictEntries(int maxSize){
    if (maxSize == -1) {
        entries.clear();
    } else if (entries.size() > maxSize) {
        int entriesToRemove = entries.size() - maxSize;
        Iterator<Map.Entry<K,V>> iterator = entries.entrySet().iterator();
        while (iterator.hasNext() && entriesToRemove > 0) {
            iterator.next();
            iterator.remove();
            entriesToRemove--;
        }
    }
}
