import java.awt.AWTException;
import java.awt.Rectangle;
import java.awt.Robot;
import java.awt.Toolkit;
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import javax.imageio.ImageIO;

public void takeScreenshot(String screenshotName) {
    try {
        // Creating a Robot class object
        Robot robotClassObject = new Robot();

        // Get screen size
        Rectangle screenSize = new Rectangle(Toolkit.getDefaultToolkit().getScreenSize());

        // Capturing screenshot
        BufferedImage screenshot = robotClassObject.createScreenCapture(screenSize);

        // defining the directory path
        String dirPath = System.getProperty("user.dir") + "\\screenshots\\";

        // Create the directory if it's not present
        File directory = new File(dirPath);
        if (!directory.exists()) {
            directory.mkdir();
        }

        // Naming the Screenshot file
        String fileName = String.format("%04d_%s.png", Integer.parseInt(counter), screenshotName);

        // Writing screenshot to a file
        ImageIO.write(screenshot, "png", new File(dirPath + fileName);

        System.out.println("Screenshot captured and saved in \"" + dirPath + fileName+ "\"");
    } catch (AWTException | IOException exception) {
        System.out.println(exception.getMessage());
    }
}
