public Predicate delegatePredicateCreation(Root root, CriteriaQuery query, String propertyName, String operator, Object argument, SomeContextObject context) {
    CriteriaBuilder builder = context.getCriteriaBuilder();
    Path path = root.get(propertyName);
    switch(operator) {
        case "=":
            return builder.equal(path, argument);
        case "!=":
            return builder.notEqual(path, argument);
        case ">":
            return builder.greaterThan(path, (Comparable) argument);
        case ">=":
            return builder.greaterThanOrEqualTo(path, (Comparable) argument);
        case "<":
            return builder.lessThan(path, (Comparable) argument);
        case "<=":
            return builder.lessThanOrEqualTo(path, (Comparable) argument);
        case "LIKE":
            return builder.like(path, "%" + argument.toString() + "%");
        case "NOT LIKE":
            return builder.notLike(path, "%" + argument.toString() + "%");
        case "IS NULL":
            return builder.isNull(path);
        case "IS NOT NULL":
            return builder.isNotNull(path);
        default:
            throw new IllegalArgumentException("Invalid operator: " + operator);
    }
}
