@Override
void addAll(final Collection<? extends E> elementsToAdd) {
    final Map<E, Count> map = ((AbstractMapBasedMultiset<E>) backingMap()).backingMap;
    if (map.isEmpty()) {
        super.addAll(elementsToAdd);
        return;
    }
    for (final E element : elementsToAdd) {
        final Count count = map.get(element);
        if (count != null) {
            count.addAndGet(1);
        } else {
            map.put(element, new Count(1));
        }
    }
    sizeAdd(elementsToAdd.size());
}
