 * @see moa.classifiers.rules.RuleActiveLearningNodeInterface#computeProbability(double, double, double)
 */
public double computeProbability(double featureValue, double min, double max) {
    if (featureValue <= min) {
        return 0.0;
    }
    else if (featureValue >= max) {
        return 1.0;
    }
    else {
        return (featureValue - min) / (max - min);
    }
}
