public boolean checkArgumentType(String funcName, String[] args, int line) throws TransformerException {
    boolean foundNamedArg = false;
    boolean foundRegularArg = false;

    // Check if each argument starts with the character '-' - named argument
    // If not, then it's a regular argument
    for (String arg : args) {
        if (arg.startsWith("-")) {
            foundNamedArg = true;
        } else {
            foundRegularArg = true;
        }
    }

    // If there are both named and regular arguments, throw an exception
    if (foundNamedArg && foundRegularArg) {
        throw new TransformerException("Line " + line + ": Cannot mix named and regular arguments for function " + funcName);
    }

    // Return true if all arguments are either named or regular
    return true;
}
