public void checkIndexConsistency() {
    boolean isSuspended = isIndexSuspended();

    try {
        if (isSuspended) {
            resumeIndex();
        }

        Iterator<Document> docIterator = getIndexIterator();

        while (docIterator.hasNext()) {
            Document doc = docIterator.next();

            if (!hasJcrNode(doc)) {
                log.error("Index inconsistency found for document with id: " + doc.getId());
            }
        }
    } finally {
        if (isSuspended) {
            suspendIndex();
        }
    }
}
