import org.apache.beam.sdk.transforms.windowing.*;

public class CountEvictorFn implements Evictor<SomeElement> {
    private final int maxCount;
    private final boolean doEvictAfter;

    public CountEvictorFn(int maxCount, boolean doEvictAfter) {
        this.maxCount = maxCount;
        this.doEvictAfter = doEvictAfter;
    }

    @Override
    public void onElement(OnElementContext<SomeElement> c) {
        // Do nothing.
    }

    @Override
    public void onMerge(OnMergeContext<SomeElement> c) {
        // The following line is to prevent eviction from running multiple times in subsequent window.
        if (!doEvictAfter && c.trigger().isFinished()) {
            c.window().setNonMerging();
        }
        if (maxCount <= 0) {
            // Just clear the pane.
            c.window().pane().clear();
            return;
        }
        int count = 0;
        for (SomeElement element : c.window().pane()) {
            ++count;
            if (count > maxCount) {
                c.window().pane().remove(element);
            }
        }
    }

    @Override
    public void onEviction(EvictionContext<SomeElement> c) {
        // Do nothing.
    }
}
