public String convertCoordsToGeoJSON(double[][] coords, StringBuilder sb) {
    sb.append("[");
    for (int i = 0; i < coords.length; i++) {
        double x = coords[i][0];
        double y = coords[i][1];
        sb.append("[").append(x).append(",").append(y).append("]");
        if (i < coords.length - 1) {
            sb.append(",");
        }
    }
    sb.append("]");
    return sb.toString();
}
