            String decoded = Utils.base64ToString(authString.substring("basic ".length()));
            int inx = decoded.indexOf(':');
            if (inx < 0) {
                userID.append(decoded);
            } else {
                userID.append(decoded.substring(0, inx));
                password.append(decoded.substring(inx + 1));
            }
        }
