public static List<LabelFragment> expandLabelFragmentSet(LabelFragmentSet fragmentSet, KB kb) {
    if (fragmentSet == null || kb == null) {
        return null;
    }
    List<LabelFragment> expandedFragments = new ArrayList<>();
    if (fragmentSet.getLabelFragments().isEmpty()) {
        return expandedFragments;
    }
    if (fragmentSet.size() > 1) {
        return null;
    }
    LabelFragment labelFragment = fragmentSet.iterator().next();
    Label label = labelFragment.getLabel();
    if (!kb.containsLabel(label)) {
        return null;
    }
    List<LabelFragment> subConcepts = kb.getSubConcepts(label);
    if (subConcepts == null) {
        return null;
    }
    expandedFragments.addAll(subConcepts);
    return expandedFragments;
}
