public boolean isDisjoint(String scl) {
   // First, split the input string scl based on the comma delimiter.
   String[] elements = scl.split(",");

   // Verify if there are any duplicate elements.
   for (int i = 0; i < elements.length - 1; i++) {
      for (int j = i+1; j < elements.length; j++) {
         if (elements[i].equals(elements[j])) {
            return false;
         }
      }
   }

   // If no duplicate elements are found, the given string is disjoint.
   return true;
}
