public String buildControlMessage(Object payload) {
    // Assuming payload is either a file resource or a String data

    // Check if payload is a file resource
    if (payload instanceof File) {
        // Read the contents of the file into a String
        try {
            payload = new String(Files.readAllBytes(((File) payload).toPath()));
        } catch (IOException e) {
            // Handle the exception appropriately
            e.printStackTrace();
            return null;
        }
    }

    // Check if payload is a String
    if (payload instanceof String) {
        // Build the control message using the String data
        String controlMessage = "CONTROL MESSAGE: " + (String) payload;
        return controlMessage;
    } else {
        // Handle invalid payload input
        return null;
    }
}
