public class SampleClass {
  private static final char[] CHARSET = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789".toCharArray();

  public static boolean containsChar(String str, char ch) {
    if (str == null || str.isEmpty()) {
      return false;
    }

    int len = str.length();
    if (len == 1) {
      return str.charAt(0) == ch;
    }

    if (containsOnlyChar(str)) {
      return false;
    }

    if (ch < ' ' || ch > '~') {
      return false;
    }

    for (int i = 0; i < len; i++) {
      if (str.charAt(i) == ch) return true;
    }
    return false;
  }

  private static boolean containsOnlyChar(String str) {
    for (int i = 0; i < str.length(); i++) {
      char ch = str.charAt(i);
      if (ch < ' ' || ch > '~') {
        return false;
      }
      if (indexOfChar(ch) == -1) {
        return false;
      }
    }
    return true;
  }

  private static int indexOfChar(char ch) {
    for (int i = 0; i < CHARSET.length; i++) {
      if (CHARSET[i] == ch) {
        return i;
      }
    }
    return -1;
  }
}
