public boolean createTableWithDefinition(String tableDefinition) throws DBException {
    // SQL query to create a new table using the provided definition
    String query = "CREATE TABLE " + tableDefinition;
    try {
        // Execute the SQL query to create the table
        Connection connection = getDBConnection();
        Statement statement = connection.createStatement();
        statement.executeUpdate(query);
        // Close the database connection and return true to indicate success
        closeConnection(connection);
        return true;
    } catch (SQLException e) {
        // Throw a DBException if there was an error creating the table
        throw new DBException("Error creating table: " + e.getMessage());
    }
}
