public void moveRow(String rowKey, int newRowIndex) {
    // Get the index of the row to be moved
    int rowIndex = getIndexForRow(rowKey);

    if (rowIndex != -1 && rowIndex != newRowIndex) {
        // Remove the row from current position
        Object[] removedRow = data.remove(rowIndex);

        // Adjust the index of new position if necessary
        if (newRowIndex > rowIndex) {
            newRowIndex--;
        }

        // Add the row to new position
        data.add(newRowIndex, removedRow);
    }
}
