import org.eclipse.core.resources.IMarker;
import org.eclipse.jface.text.IDocument;
import org.eclipse.jface.text.contentassist.ICompletionProposal;
import org.eclipse.jface.text.quickassist.IQuickFixableAnnotation;
import org.eclipse.swt.graphics.Image;
import org.eclipse.ui.IMarkerResolutionGenerator;
import org.eclipse.ui.IMarkerResolution;

public class QuickFixForCapacity implements IMarkerResolutionGenerator{

    public IMarkerResolution[] getResolutions(IMarker marker) {
        return new IMarkerResolution[] { new CapacityFix(marker.getResource()) };
    }

    public class CapacityFix implements IMarkerResolution, IQuickFixableAnnotation {

        private Image image;
        private String label;
        private IDocument document;

        public CapacityFix(IResource resource) {
            label = "Change to initialCapacity()";
            image = Activator.getImageDescriptor("icons/sample.gif").createImage();
            try {
            document = new Document(resource.getLocation().toFile());
            } catch (MalformedURLException e) {
                // TODO Auto-generated catch block
                e.printStackTrace();
            } catch (CoreException e) {
                // TODO Auto-generated catch block
                e.printStackTrace();
            }
        }

        public void apply(IDocument document) {
            try {
                String text = document.get();
                int index = text.indexOf("new HashMap(");
                if (index != -1) {
                    int end = text.indexOf(");", index);
                    document.replace(index + 5, end - index - 4, "initialCapacity(16)");
                }
            } catch (BadLocationException e) {
                // TODO Auto-generated catch block
                e.printStackTrace();
            }
        }

        public String getAdditionalProposalInfo() {
            return "Change the HashMap constructor to use the initialCapacity() method.";
        }

        public Image getImage() {
            return image;
        }

        public String getLabel() {
            return label;
        }

        public void run(IMarker marker) {
            try {
                apply(document);
            } catch (BadLocationException e) {
                // TODO Auto-generated catch block
                e.printStackTrace();
            }
        }

        public boolean isQuickFixableStateSet(int state) {
            return (state & IAnnotationAccessExtension.DEFAULT_QUICK_FIXABLE) != 0;
        }

    }
}
