public static double[] getRangeAroundMedian(double[] values, double percent) {
    Arrays.sort(values);
    double median = values[values.length / 2];
    double range = (percent / 2) * values.length / 100;

    int lowerIndex = (int) Math.floor(values.length / 2 - range);
    int upperIndex = (int) Math.ceil(values.length / 2 + range);

    return Arrays.copyOfRange(values, lowerIndex, upperIndex);
}
