public <V> Map<String, V> convertKeysToSnakeCase(Map<String, V> hash) {
    Map<String, V> snakeCaseHash = new HashMap<>();
    for (Map.Entry<String, V> entry : hash.entrySet()) {
        String snakeCaseKey = entry.getKey().replaceAll("([a-z])([A-Z])", "$1_$2").toLowerCase();
        snakeCaseHash.put(snakeCaseKey, entry.getValue());
    }
    return snakeCaseHash;
}
