public static double[][] generateGaussianMatrix(int n, Random rng) {
    double[][] matrix = new double[n][n];
    double variance = 1.0 / n;

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            matrix[i][j] = rng.nextGaussian() * Math.sqrt(variance);
        }
    }

    return matrix;
}
