import io.github.classgraph.ClassGraph;
import io.github.classgraph.ClassInfo;
import io.github.classgraph.ScanResult;
import java.util.ArrayList;
import java.util.List;

public List<Class<?>> getAllInterfaceOrAnnotationClassesFound(List<Class<?>> classes, ScanSpec scanSpec) {
    List<Class<?>> whitelistInterfaces = new ArrayList<>();
    try (ScanResult scanResult = new ClassGraph()
            .acceptPackages(scanSpec.getPackageToScan())
            .enableAllInfo()
            .scan()) {
        for (Class<?> aClass : classes) {
            if (aClass.isInterface() && scanSpec.isClassWhitelisted(aClass.getName())) {
                whitelistInterfaces.add(aClass);
            }
            for (ClassInfo implementer : scanResult.getClassesImplementing(aClass.getName())) {
                if (implementer.isAnnotation() && scanSpec.isClassWhitelisted(implementer.getName())) {
                    whitelistInterfaces.add(implementer.loadClass());
                }
            }
        }
    }
    return whitelistInterfaces;
}
