public void updateJobState(Job job, List<Job> dependingJobs) {
    // Get the current state of the job.
    JobState currentState = job.getState();

    // Determine the state based on the current state and the states of the depending jobs.
    JobState newState = currentState;
    for (Job dependingJob : dependingJobs) {
        JobState dependingJobState = dependingJob.getState();
        if (dependingJobState == JobState.FAILED || dependingJobState == JobState.CANCELLED) {
            newState = JobState.FAILED;
            break;
        } else if (dependingJobState == JobState.RUNNING || dependingJobState == JobState.PENDING) {
            newState = JobState.PENDING;
        }
    }

    // Update the state of the job if it has changed.
    if (newState != currentState) {
        job.setState(newState);
    }
}
