public Set<Synset> getSemanticRelations(WordNetNode node, String relation) {
   Set<Synset> synsetsWithRelation = new HashSet<>();
   if (node == null || relation == null) {
      return synsetsWithRelation;
   }
   for (PointerType pointerType : PointerType.values()) {
      if (pointerType.getName().equals(relation)) {
         for (Pointer pointer : node.getPointers(pointerType)) {
            Synset synset = pointer.getSynset();
            if (synset != null) {
               synsetsWithRelation.add(synset);
            }
         }
         break;
      }
   }
   return synsetsWithRelation;
}
