public void setSequentialAnimation(List<Animation> items) {
    AnimatorSet animatorSet = new AnimatorSet();
    List<Animator> animators = new ArrayList<>();
    long duration = 0;

    // Add all animations to the list of animators and calculate total duration
    for (Animation animation : items) {
        Animator animator = animation.createAnimator();
        animators.add(animator);
        duration += animator.getDuration();
    }

    // Play animations sequentially
    for (int i = 0; i < animators.size() - 1; i++) {
        Animator currentAnimator = animators.get(i);
        Animator nextAnimator = animators.get(i + 1);
        currentAnimator.addListener(new AnimatorListenerAdapter() {
            @Override
            public void onAnimationEnd(Animator animation) {
                nextAnimator.start();
            }
        });
    }

    // Set duration of AnimatorSet
    animatorSet.setDuration(duration);

    // Start the animation set
    animatorSet.play(animators.get(0));
    animatorSet.start();
}
