public void readFromStream(int bytesRequired, InputStream inputStream) throws IOException {
    byte[] buffer = new byte[bytesRequired];
    int bytesRead = 0;
    int offset = 0;

    while (bytesRead < bytesRequired) {
        int remaining = bytesRequired - bytesRead;
        int count = inputStream.read(buffer, offset, remaining);
        if (count == -1) {
            throw new IOException("End of stream reached before reading required bytes");
        }
        offset += count;
        bytesRead += count;
    }
}
