import org.jfree.chart.ChartFactory;
import org.jfree.chart.ChartPanel;
import org.jfree.chart.JFreeChart;
import org.jfree.chart.plot.ContourPlot;
import org.jfree.data.contour.DefaultContourDataset;
import org.jfree.data.xy.DefaultXYZDataset;
import javax.swing.*;

public class PlotCanvas {

    // function definition
    public static void createPlotCanvas(double[][] z) {

        // create dataset
        DefaultXYZDataset dataset = new DefaultXYZDataset();
        dataset.addSeries("data", z);

        // create contour data
        DefaultContourDataset contourData = new DefaultContourDataset("data");
        contourData.setContourValues(dataset.getZValues());
        contourData.setAxisRange(dataset.getDomainBounds(true), dataset.getRangeBounds(true));
        contourData.setContourInterval(10.0);

        // create contour plot
        ContourPlot plot = new ContourPlot(contourData);

        // create chart and set plot
        JFreeChart chart = ChartFactory.createContourChart("Contour Plot", "X", "Y", plot);

        // create chart panel and set it to frame
        ChartPanel chartPanel = new ChartPanel(chart);
        JFrame frame = new JFrame("Contour Plot");
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.getContentPane().add(chartPanel);
        frame.pack();
        frame.setVisible(true);
    }
}
