public boolean checkTaxIdentificationNumber(String ptaxNumber) {
    int[] weights = { 10, 9, 8, 7, 6, 5, 4, 3, 2 };
    int sum = 0;

    for (int i = 0; i < weights.length; i++) {
        sum += Integer.parseInt(String.valueOf(ptaxNumber.charAt(i))) * weights[i];
    }

    int expectedChecksum = 11 - (sum % 11);
    if (expectedChecksum == 10) {
        expectedChecksum = 0;
    }

    return Integer.parseInt(String.valueOf(ptaxNumber.charAt(weights.length))) == expectedChecksum;
}
