public double calculateProbesPerSecond() {
   // Assuming probes are stored in an ArrayList called 'probes'
   int size = probes.size();
   if (size < 2) {
       return 0;
   }
   long elapsed = probes.get(size - 1).getTime() - probes.get(size - 1000).getTime();
   return 1000.0 / elapsed;
}
