public List<VirtualNetworkInterface> getServerVirtualNetworkInterfaces(String name, String vrack, String mode, String serviceName) {
    String apiUrl = "/dedicated/server/" + serviceName + "/virtualNetworkInterface";

    UriComponentsBuilder builder = UriComponentsBuilder.fromUriString(apiUrl)
            .queryParam("name", name)
            .queryParam("vrack", vrack)
            .queryParam("mode", mode);

    ResponseEntity<VirtualNetworkInterface[]> responseEntity = restTemplate.getForEntity(builder.toUriString(), VirtualNetworkInterface[].class);

    if (responseEntity.getStatusCode() == HttpStatus.OK) {
        VirtualNetworkInterface[] virtualNetworkInterfaces = responseEntity.getBody();
        return Arrays.asList(virtualNetworkInterfaces);
    } else {
        throw new RuntimeException("Failed to retrieve server Virtual Network Interfaces: " + responseEntity.getStatusCode());
    }
}
