public static Object[] convertMapToArray(Map<String, Object> values, String[] nameMapping) {
    if (values == null || nameMapping == null) {
        throw new NullPointerException("values and nameMapping must not be null");
    }

    Object[] result = new Object[nameMapping.length];
    int index = 0;

    for (String name : nameMapping) {
        if (values.containsKey(name)) {
            result[index++] = values.get(name);
        }
    }

    if (index < nameMapping.length) {
        Object[] trimmedResult = new Object[index];
        System.arraycopy(result, 0, trimmedResult, 0, index);
        result = trimmedResult;
    }

    return result;
}
