public List<Boolean> parseBooleanList(JsonParser parser) throws IOException, JsonFormatException {
    List<Boolean> list = new ArrayList<>();
    JsonToken token = parser.getCurrentToken();

    if (token != JsonToken.START_ARRAY) {
        throw new JsonFormatException("Expected start of array but found " + token);
    }

    while (parser.nextToken() != JsonToken.END_ARRAY) {
        token = parser.getCurrentToken();

        if (token == JsonToken.VALUE_TRUE) {
            list.add(true);
        } else if (token == JsonToken.VALUE_FALSE) {
            list.add(false);
        } else {
            throw new JsonFormatException("Expected boolean but found " + token);
        }
    }

    return list;
}
