public static List<String> tokenize(String input, char separator, char delimiter) {
    List<String> tokens = new ArrayList<>();

    StringBuilder sb = new StringBuilder();
    boolean inDelimiter = false;

    for (char c : input.toCharArray()) {
        if (c == delimiter) {
            inDelimiter = !inDelimiter;
        } else if (inDelimiter || c != separator) {
            sb.append(c);
        } else {
            String token = sb.toString().trim();
            if (!token.isEmpty()) {
                tokens.add(token);
            }
            sb.setLength(0);
        }
    }

    String lastToken = sb.toString().trim();
    if (!lastToken.isEmpty()) {
        tokens.add(lastToken);
    }

    return tokens;
}
