public static Thread getProcessErrorStream(final Process self, final OutputStream err) {
    Thread thread = new Thread(() -> {
        try (InputStream input = self.getErrorStream()) {
            byte[] buffer = new byte[1024];
            int length;
            while ((length = input.read(buffer)) != -1) {
                err.write(buffer, 0, length);
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    });
    thread.start();
    return thread;
}
