public String substituteConfigVariables(Map<String, String> config, String pathString) {
    Pattern pattern = Pattern.compile("\\$\\{HERON_[^}]*\\}");
    Matcher matcher = pattern.matcher(pathString);
    StringBuffer buffer = new StringBuffer();
    while (matcher.find()) {
        String key = matcher.group().replaceAll("\\$\\{HERON_|\\}", "");
        String value = config.get(key);
        if (value == null) {
            throw new IllegalArgumentException("Invalid configuration value for key " + key);
        }
        matcher.appendReplacement(buffer, value);
    }
    matcher.appendTail(buffer);
    return buffer.toString();
}
