public static boolean isMethodImplemented(Class<?> cls, String methodName, String methodSig) throws ClassNotFoundException {
    if (cls.equals(Object.class))
        return false;

    try {
        Method[] methods = cls.getDeclaredMethods();
        for (Method method : methods) {
            if (method.getName().equals(methodName) && method.toString().equals(methodSig))
                return true;
        }
    } catch (Exception e) {}

    return isMethodImplemented(cls.getSuperclass(), methodName, methodSig);
}
