public Locale searchLocale(String language, String country, String variant) {
    Locale[] locales = Locale.getAvailableLocales();
    for (Locale locale : locales) {
        if (locale.getLanguage().equalsIgnoreCase(language) &&
            locale.getCountry().equalsIgnoreCase(country) &&
            locale.getVariant().equalsIgnoreCase(variant)) {
            return locale;
        }
    }
    return null;
}
