public static int[] removeElementFromArray(int[] array, int index) {
    if (array == null || index < 0 || index >= array.length) {
        return array;
    }
    int[] newArray = new int[array.length - 1];
    for (int i = 0, k = 0; i < array.length; i++) {
        if (i == index) {
            continue;
        }
        newArray[k++] = array[i];
    }
