public boolean validateContentSpec(ContentSpec contentSpec) {
    Set<String> ids = new HashSet<String>();
    for (Topic topic : contentSpec.getTopics()) {
        String id = topic.getId();
        String revision = topic.getRevision();
        if (ids.contains(id) && !contentSpec.containsTopic(id, revision)) {
            return false;
        }
        ids.add(id);
    }
    return true;
}
