public static String getProgramProperty(String property) {
    String value = null;
    // checking if the property exists in the system properties
    if (System.getProperty(property) != null) {
        value = System.getProperty(property);
    } else {
        // loading the properties file
        Properties properties = new Properties();
        try {
            InputStream input = getClass().getClassLoader().getResourceAsStream("program.properties");
            properties.load(input);
        } catch (IOException e) {
            e.printStackTrace();
        }
        // checking if the property exists in the properties file
        if (properties.getProperty(property) != null) {
            value = properties.getProperty(property);
        }
    }
    return value;
}
