public static Complex raiseComplexToPower(Complex num, int power) {
    if (power == 0) {
        return new Complex(1, 0);
    } else if (power == 1) {
        return num;
    } else {
        Complex result = raiseComplexToPower(num, power / 2);
        result = result.multiply(result);
        if (power % 2 == 1) {
            result = result.multiply(num);
        }
        return result;
    }
}
