public UserProfile readUserProfile(Node profileNode) throws RepositoryException {
    final String ATTRIBUTE_PREFIX = "profile_"; // prefix for profile attributes
    UserProfile userProfile = new UserProfile();

    // loop through all properties of profile node
    PropertyIterator props = profileNode.getProperties();
    while (props.hasNext()) {
        Property prop = props.nextProperty();
        String propName = prop.getName();

        // check if property has the right prefix
        if (propName.startsWith(ATTRIBUTE_PREFIX)) {
            String attrName = propName.substring(ATTRIBUTE_PREFIX.length()); // remove prefix from attribute name
            String attrValue = prop.getString();
            userProfile.setAttribute(attrName, attrValue); // set attribute for user profile
        }
    }
    return userProfile;
}
