public boolean printAndCheckSlaveHealth(InputStream standardOutput, InputStream errorOutput, Process process) {
    try {
        BufferedReader standardReader = new BufferedReader(new InputStreamReader(standardOutput));
        BufferedReader errorReader = new BufferedReader(new InputStreamReader(errorOutput));

        String line = "";
        while ((line = standardReader.readLine()) != null) {
            System.out.println(line);
        }

        while ((line = errorReader.readLine()) != null) {
            System.err.println(line);
        }

        if (!process.isAlive()) {
            return true;
        } else if (process.getErrorStream().available() <= 0 && process.getInputStream().available() <= 0) {
            return false;
        }

        return true;
    } catch (IOException e) {
        e.printStackTrace();
        return false;
    }
}
