public Object setPropertiesFromConfig(Object object) {
  // assume config object exists and contains properties to set
  Config config = getConfig();

  // retrieve all fields from object and its superclasses
  List<Field> fields = new ArrayList<Field>();
  Class<?> currentClass = object.getClass();
  while (currentClass != null) {
    fields.addAll(Arrays.asList(currentClass.getDeclaredFields()));
    currentClass = currentClass.getSuperclass();
  }

  // iterate through all fields and set values from config
  for (Field field : fields) {
    String fieldName = field.getName();
    if (config.containsKey(fieldName)) {
      try {
        field.setAccessible(true);
        field.set(object, config.get(fieldName));
      } catch (IllegalAccessException e) {
        e.printStackTrace();
      }
    }
  }
  return object;
}
