public Map<String, Double> divideCounts(Map<String, Integer> c1, Map<String, Integer> c2) {
    Map<String, Double> result = new HashMap<>();
    for (Map.Entry<String, Integer> entry : c1.entrySet()) {
        String key = entry.getKey();
        int count1 = entry.getValue();
        int count2 = c2.getOrDefault(key, 0);
        double division = (count2 == 0) ? Double.NaN : ((double) count1) / count2;
        result.put(key, division);
    }
    return result;
}
