public double fMeasure(int numLeft, int numRight) {
    int truePositives = 0; // Number of correctly classified positives
    int falsePositives = numRight - numLeft + 1; // Number of incorrectly classified positives
    int falseNegatives = numLeft; // Number of incorrectly classified negatives
    double precision, recall, fMeasure;

    // Calculate precision and recall
    precision = (double) truePositives / (truePositives + falsePositives);
    recall = (double) truePositives / (truePositives + falseNegatives);

    // Calculate f-measure
    fMeasure = 2 * ((precision * recall) / (precision + recall));

    return fMeasure;
}
