public static Number parseNumber(String text){
    Number parsed = null;
    Pattern integerPattern = NumericPrompt.INTEGER_PATTERN;
    Pattern doublePattern = NumericPrompt.DOUBLE_PATTERN;
    Pattern floatPattern = NumericPrompt.FLOAT_PATTERN;
    if (integerPattern.matcher(text).matches()){
        parsed = Integer.parseInt(text);
    } else if (doublePattern.matcher(text).matches()){
        parsed = Double.parseDouble(text);
    } else if (floatPattern.matcher(text).matches()){
        parsed = Float.parseFloat(text);
    }
    return parsed;
}
