public static double[] realToRotated(double longitude, double latitude, double angle) {

    double[] rotatedCoordinates = new double[2];

    double radianAngle = Math.toRadians(angle);

    double x = longitude * Math.cos(radianAngle) - latitude * Math.sin(radianAngle);
    double y = longitude * Math.sin(radianAngle) + latitude * Math.cos(radianAngle);

    rotatedCoordinates[0] = x;
    rotatedCoordinates[1] = y;

    return rotatedCoordinates;
}
