import java.io.IOException;
import java.nio.channels.FileChannel;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.HashMap;
import java.util.Map;

public class FileChannelUtil {
    private static Map<String, FileChannel> fileChannelMap = new HashMap<>();

    public static FileChannel getFileChannel(String fileName) throws IOException {
        FileChannel fileChannel;
        if (fileChannelMap.containsKey(fileName)) {
            fileChannel = fileChannelMap.get(fileName);
        } else {
            Path path = Path.of(fileName);
            if (Files.notExists(path)) {
                throw new IOException("File does not exist.");
            }
            fileChannel = FileChannel.open(path, StandardOpenOption.WRITE, StandardOpenOption.READ);
            fileChannelMap.put(fileName, fileChannel);
        }
        return fileChannel;
    }
}
