public static <A extends Annotation> A findAnnotation(Class<?> from, Class<A> annotationType) {
    A annotation = from.getAnnotation(annotationType);
    if (annotation != null) {
        return annotation;
    }
    for (Annotation metaAnnotation : from.getAnnotations()) {
        annotation = metaAnnotation.annotationType().getAnnotation(annotationType);
        if (annotation != null) {
            return annotation;
        }
    }
    return null;
}
