@Override
public List<SearchParameter> extractSearchParamQuantity(ResourceTable theEntity, IBaseResource theResource) {
    List<SearchParameter> retVal = new ArrayList<>();

    List<ResourceIndexedSearchParamQuantity> params = theEntity.getParamsQuantity();

    for (ResourceIndexedSearchParamQuantity next : params) {
        if (next.getParamName().equals(SearchParameterTypeEnum.QUANTITY.getCode())) {
            QuantityDt nextValue = new QuantityDt(next.getValue(), next.getSystemValue()).setCode(StringUtils.defaultIfBlank(next.getUnits(), null));
            SearchParameter param = new SearchParameter(SearchParameterTypeEnum.QUANTITY, next.getParamName()).setResource(theResource).setValue(nextValue);
            retVal.add(param);
        }
    }

    return retVal;
}
