import com.vividsolutions.jts.geom.*;
import com.vividsolutions.jts.geom.util.*;

public Geometry computeOffsetCurve(List<Geometry> list, Geometry geometry, double offset, BufferParameters bufferParameters) {
    PrecisionModel precisionModel = geometry.getPrecisionModel();
    GeometryFactory geometryFactory = geometry.getFactory();
    OffsetCurveBuilder offsetCurveBuilder = new OffsetCurveBuilder(precisionModel, bufferParameters);
    Geometry offsetCurve = offsetCurveBuilder.getOffsetCurve(geometry, offset);
    for (Geometry geom : list) {
        Geometry nodedGeom = OffsetCurveBuilder.copyWithSamePrecision(geom);
        Geometry union = null;
        try {
            union = unaryUnion(nodedGeom);
        } catch (TopologyException ex) {
            // if cannot compute union then skip geometry
            continue;
        }
        Geometry positive = offsetCurve.intersection(union);
        Geometry negative = offsetCurve.intersection(union);
        offsetCurve = geometryFactory.createGeometryCollection(GeometryFactory.toGeometryArray(
            OffsetCurveBuilder.simplify(positive), OffsetCurveBuilder.simplify(negative)));
    }
    return offsetCurve;
}
