public static boolean useDevURandom() {
    String osName = System.getProperty("os.name").toLowerCase();
    String osArch = System.getProperty("os.arch").toLowerCase();
    if (osName.contains("linux") || osName.contains("freebsd") || osName.contains("openbsd")
            || osName.contains("netbsd") || osName.contains("darwin")) {
        if (osArch.contains("arm") || osArch.contains("aarch64")) {
            return false;
        } else {
            return true;
        }
    } else {
        return false;
    }
}
