public boolean containsPoint(int x, int y) {
    int i;
    int j;
    boolean result = false;
    for (i = 0, j = getXPoints().size() - 1; i < getXPoints().size(); j = i++) {
          if ((getYPoints().get(i) > y) != (getYPoints().get(j) > y) &&
              (x < (getXPoints().get(j) - getXPoints().get(i)) * (y - getYPoints().get(i)) / (getYPoints().get(j) - getYPoints().get(i)) + getXPoints().get(i))) {
              result = !result;
          }
    }
    return result;
}
