public static String join(Collection<?> objects, String separator) {
  StringBuilder sb = new StringBuilder();
  boolean first = true;
  for (Object obj : objects) {
    if (!first) {
      sb.append(separator);
    } else {
      first = false;
    }
    sb.append(obj.toString());
  }
  return sb.toString();
}
