public List<String> searchAndAddAddOns(String directoryPath) {
    List<String> addOnList = new ArrayList<>();

    try (Stream<Path> walk = Files.walk(Paths.get(directoryPath))) {

        List<String> addOnDirs = walk.map(x -> x.toString())
                .filter(f -> f.contains("/lib") && f.endsWith(".jar"))
                .collect(Collectors.toList());

        for (String addOnDir : addOnDirs) {
            addOnList.add(addOnDir);
        }

    } catch (IOException e) {
        e.printStackTrace();
    }

    return addOnList;
}
