public static boolean isMatchingMetaData(XSSFWorkbook workbook, Map<String, String> metadataFilters) {
    if (metadataFilters == null) {
        return true; // if no filters are provided, everything matches
    }

    POIXMLProperties props = workbook.getProperties();
    if (props == null) {
        return false; // no properties found, so it can't match
    }

    for (Map.Entry<String, String> filter : metadataFilters.entrySet()) {
        String property = props.getExtendedProperties().getUnderlyingProperties().get(filter.getKey());
        if (property == null || !property.equals(filter.getValue())) {
            return false; // filters are not matching
        }
    }

    return true; // metadata filters match
}
