public static String convertNameIdentifier(String id) {
    String[] parts = id.split("::"); // Split the identifier parts by "::"

    StringBuilder result = new StringBuilder();
    for (int i = 0; i < parts.length; i++) {
        if (i > 0) {
            result.append("_");
        }
        result.append(parts[i]);
    }

