import java.beans.BeanInfo;
import java.beans.IntrospectionException;
import java.beans.Introspector;
import java.beans.PropertyDescriptor;
import java.lang.reflect.InvocationTargetException;
import java.util.ArrayList;
import java.util.List;

public class BeanUtil {

    public static List<String> getAllBeanFields(Object bean) throws IntrospectionException, InvocationTargetException, IllegalAccessException {
        List<String> fields = new ArrayList<>();

        BeanInfo beanInfo = Introspector.getBeanInfo(bean.getClass());
        PropertyDescriptor[] propertyDescriptors = beanInfo.getPropertyDescriptors();

        for (PropertyDescriptor propertyDescriptor : propertyDescriptors) {
            String fieldName = propertyDescriptor.getName();
            if (fieldName.equals("class")) {
                continue;
            }
            Object fieldValue = propertyDescriptor.getReadMethod().invoke(bean);
            if (fieldValue == null) {
                continue;
            }

            if (isSimple(fieldValue.getClass())) {
                fields.add(fieldName);
            } else {
                fields.addAll(getAllBeanFields(fieldValue));
            }
        }

        return fields;
    }

    private static boolean isSimple(Class clazz) {
        return clazz.isPrimitive() || clazz == String.class || clazz == Integer.class ||
                clazz == Long.class || clazz == Double.class || clazz == Float.class ||
                clazz == Boolean.class || clazz == Short.class || clazz == Byte.class;
    }
}
