import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.transform.stream.StreamSource;
import javax.xml.validation.Schema;
import javax.xml.validation.SchemaFactory;
import org.w3c.dom.Document;
import org.xml.sax.InputSource;

public Document parseAndValidateXML(InputSource input) throws Exception {
    // create a new instance of DocumentBuilderFactory
    DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
    // enable validation checking
    factory.setValidating(true);

    // create a new instance of DocumentBuilder
    DocumentBuilder builder = factory.newDocumentBuilder();

    // parse the input stream into a Document object
    Document xmlDoc = builder.parse(input);

    // create a new instance of SchemaFactory and get the Schema object from the available XML schema
    SchemaFactory schemaFactory = SchemaFactory.newInstance("http://www.w3.org/2001/XMLSchema");
    Schema schema = schemaFactory.newSchema(new StreamSource(getClass().getResourceAsStream("schema.xsd")));

    // validate the parsed XML against the schema
    schema.newValidator().validate(new StreamSource(new StringReader(xmlDoc.getTextContent())));

    return xmlDoc;
}
