public List<Integer> getAdjacentFactorsIndices(int factorNum, List<List<Integer>> factors) {
    List<Integer> adjacentFactorsIndices = new ArrayList<>();

    List<Integer> factor = factors.get(factorNum);
    for (int i = 0; i < factors.size(); i++) {
        if (i == factorNum) {
            continue;
        }
        List<Integer> otherFactor = factors.get(i);
        for (int variable : factor) {
            if (otherFactor.contains(variable)) {
                adjacentFactorsIndices.add(i);
                break;
            }
        }
    }

    return adjacentFactorsIndices;
}
