public static void instrumentCode(MethodNode methodNode) {
    AbstractInsnNode currentNode = methodNode.instructions.getFirst();
    while (currentNode != null) {
        if (currentNode instanceof TypeInsnNode && currentNode.getOpcode() == Opcodes.NEW) {
            // Inject probe before new object creation instruction
            methodNode.instructions.insertBefore(currentNode, new MethodInsnNode(Opcodes.INVOKESTATIC,
                    "com/example/ProbingCode",
                    "fireProbe",
                    "()V",
                    false));
        } else if (currentNode instanceof MethodInsnNode && currentNode.getOpcode() == Opcodes.INVOKESTATIC) {
            MethodInsnNode methodInsn = (MethodInsnNode) currentNode;
            if (methodInsn.owner.equals(Type.getInternalName(RuntimeException.class)) &&
                    methodInsn.name.equals("throw") && methodInsn.desc.equals("(Ljava/lang/Throwable;)V")) {
                // Inject probe before throw instruction
                methodNode.instructions.insertBefore(currentNode, new MethodInsnNode(Opcodes.INVOKESTATIC,
                        "com/example/ProbingCode",
                        "fireProbe",
                        "()V",
                        false));
            }
        }
        currentNode = currentNode.getNext();
    }
}
