private Map<String, String> getChangePatchsetPairs(GerritQueryHandler gerritQueryHandler) {
    Map<String, String> changePatchsetPairs = new HashMap<>();

    // Check if data is already cached
    if (changePatchsetPairsCache.containsKey(gerritQueryHandler.getTopic())) {
        return changePatchsetPairsCache.get(gerritQueryHandler.getTopic());
    }

    // If not cached, fetch data
    String changeIdQuery = "status:merged topic:" + gerritQueryHandler.getTopic();
    List<String> changeIds = gerritQueryHandler.query(changeIdQuery);

    for (String changeId : changeIds) {
        String patchsetNumberQuery = "change:" + changeId;
        List<String> patchsetNumbers = gerritQueryHandler.query(patchsetNumberQuery);
        for (String patchsetNumber : patchsetNumbers) {
            changePatchsetPairs.put(changeId, patchsetNumber);
        }
    }

    changePatchsetPairsCache.put(gerritQueryHandler.getTopic(), changePatchsetPairs);
    return changePatchsetPairs;
}
