public boolean evaluateCondition(Map<String, String> valueMap, String condition) {
    String[] conditionArr = condition.split(" ");
    String key = conditionArr[0];
    String operator = conditionArr[1];
    int value = Integer.parseInt(conditionArr[2]);
    int actualValue = Integer.parseInt(valueMap.get(key));

    switch (operator) {
        case ">":
            return actualValue > value;
        case ">=":
            return actualValue >= value;
        case "<":
            return actualValue < value;
        case "<=":
            return actualValue <= value;
        case "==":
            return actualValue == value;
        case "!=":
            return actualValue != value;
        default:
            throw new IllegalArgumentException("Invalid operator: " + operator);
    }
}
