import java.util.*;

public class AHashMapInitializer {

    public static <K, V> HashMap<K, V> initializeAHashMap(Collection<K> keys, Collection<V> values) {
        if (keys.size() != values.size()) {
            throw new IllegalArgumentException("The keys and values collections have different sizes.");
        }

        HashMap<K, V> aHashMap = new HashMap<>(keys.size());

        Iterator<K> keyIterator = keys.iterator();
        Iterator<V> valueIterator = values.iterator();

        while (keyIterator.hasNext()) {
            K key = keyIterator.next();
            V value = valueIterator.next();
            aHashMap.put(key, value);
        }

        return aHashMap;
    }
}
