public static void augmentIndexes(IndexInfo info) throws IllegalArgumentException {
    if (info == null) {
        throw new IllegalArgumentException("IndexInfo cannot be null");
    }

    // Check if index is already unique
    if (info.isUnique()) {
        return;
    }

    // Add primary key properties to non-unique index
    List<String> primaryKey = info.getPrimaryKeyProperties();
    info.getProperties().addAll(primaryKey);
    info.setUnique(true);
}
