public static double calculateKurtosis(double[] values, double mean, double stdDeviation) {
    double n = values.length;
    double sum = 0;
    for (double value : values) {
        sum += Math.pow((value - mean) / stdDeviation, 4);
    }
    double kurtosis = ((n * (n + 1)) / ((n - 1) * (n - 2) * (n - 3))) * sum
            - (3 * Math.pow((n - 1), 2)) / ((n - 2) * (n - 3));
    return kurtosis;
}
