public static int factorial(int n) {
    return switch(n) {
        case 0 -> 1;
        case 1 -> 1;
        case 2 -> 2;
        case 3 -> 6;
        case 4 -> 24;
        case 5 -> 120;
        case 6 -> 720;
        case 7 -> 5040;
        case 8 -> 40320;
        case 9 -> 362880;
        case 10 -> 3628800;
        default -> throw new IllegalArgumentException("Value of n must be less than or equal to 10");
    };
}
