public Node createQualifiedNameNode(String name) {
    String[] parts = name.split("\\.");
    Node node;
    if (parts.length == 1) {
        node = new Node(Token.NAME);
    } else {
        node = new Node(Token.ASSIGN);
    }
    int index = 0;
    for (String part : parts) {
        Node child;
        if (index == 0 && parts.length == 1) {
            child = new Node(Token.NAME, name);
        } else if (index == 0) {
            child = new Node(Token.GETPROP, new Node(Token.NAME, part), new Node(Token.STRING, part));
        } else if (index == parts.length - 1) {
            child = new Node(Token.NAME, part);
        } else {
            child = new Node(Token.GETPROP, node.getFirstChild(), new Node(Token.STRING, part));
        }
        node.addChildToBack(child);
        index++;
    }
    if (node.getType() == Token.ASSIGN) {
        Node exprResult = new Node(Token.EXPR_RESULT, node);
        return exprResult;
    } else {
        return node;
    }
}
