import de.tudarmstadt.ukp.wikipedia.api.*;

public class DiscussionPageGetter {
    public static Wikipedia wiki;

    /*
    * Initializes the Wikipedia API
    * You can modify this function according to your needs or pass a configuration 
    * object instead of lang, database, and path as parameters.
    */
    public DiscussionPageGetter(String lang, String database, String path) throws WikiInitializationException {
        wiki = new Wikipedia(lang, database, path);
    }

    /*
    * Gets the discussion page for the given article page
    * The provided page must not be a discussion page
    * @param articlePage the article page for which a discussion page should be retrieved
    * @return The discussion page object for the given article page object
    * @throws WikiApiException If no page or redirect with this title exists 
    * or title could not be properly parsed.
    */
    public DiscussionPage getDiscussionPage(Article articlePage) throws WikiApiException {
        if (articlePage.isDiscussionPage()) {
            throw new InvalidArgumentException("Provided page is already a discussion page");
        }
        String discussionPageTitle = articlePage.getTitle() + "/Diskussion";
        Page discussionPage = wiki.getPage(discussionPageTitle);
        if (!(discussionPage instanceof DiscussionPage)) {
            throw new WikiApiException("Could not retrieve discussion page for article page: " + articlePage.getTitle());
        }
        return (DiscussionPage) discussionPage;
    }
}
