public void generateTsigRecord(Message m, int error, TSIG old) throws IOException {
    TSIGRecord tsig = null;
    if (old != null) {
        tsig = old.generate(m, error);
    } else {
        tsig = new TSIG(m.getTSIG());
    }
    byte[] signature = tsig.generate(m, error);
    tsig.setSignature(signature);
    m.addRecord(tsig, Section.ADDITIONAL);
}
