public double[][] createWeights(Random rand, int numInputs, int numHiddenLayers, int[] numNodes) {
    int numOutputs = numNodes[numHiddenLayers];
    double[][] weights = new double[numHiddenLayers+1][];
    weights[0] = new double[numNodes[0] * numInputs];
    for (int i = 1; i < numHiddenLayers; i++) {
        int prevNumNodes = numNodes[i-1];
        int thisNumNodes = numNodes[i];
        weights[i] = new double[prevNumNodes * thisNumNodes];
    }
    weights[numHiddenLayers] = new double[numNodes[numHiddenLayers-1] * numOutputs];

    for (double[] layerWeights : weights) {
        for (int i = 0; i < layerWeights.length; i++) {
            layerWeights[i] = rand.nextGaussian();
        }
    }

    return weights;
}
