public static Object sqlToJava(Object sqlValue) {
    if (sqlValue == null)
        return null;
    if (sqlValue instanceof java.sql.Timestamp) {
        java.sql.Timestamp ts = (java.sql.Timestamp) sqlValue;
        return new java.util.Date(ts.getTime());
    }
    else if (sqlValue instanceof java.sql.Date) {
        java.sql.Date date = (java.sql.Date) sqlValue;
        return new java.util.Date(date.getTime());
    }
    else if (sqlValue instanceof java.sql.Time) {
        java.sql.Time time = (java.sql.Time) sqlValue;
        return new java.util.Date(time.getTime());
    }
    else {
        return sqlValue;
    }
}
