public <T> List<T> executeQuery(Class<T> entityClass, String statement, Object... values) {
    List<T> results = new ArrayList<>();

    try (Connection conn = DriverManager.getConnection(url, username, password);
         PreparedStatement pstmt = conn.prepareStatement(statement)) {

        // Set values in statement
        for (int i = 0; i < values.length; i++) {
            pstmt.setObject(i+1, values[i]);
        }

        // Execute query
        try (ResultSet rs = pstmt.executeQuery()) {
            // Map result to entityClass
            while (rs.next()) {
                T entity = entityClass.newInstance();

                // Map each column to its corresponding field in entityClass
                ResultSetMetaData rsmd = rs.getMetaData();
                int columnCount = rsmd.getColumnCount();
                for (int i = 1; i <= columnCount; i++) {
                    String columnName = rsmd.getColumnName(i);
                    Object columnValue = rs.getObject(i);
                    Field field = entityClass.getDeclaredField(columnName);
                    field.setAccessible(true);
                    field.set(entity, columnValue);
                }

                results.add(entity);
            }
        }

    } catch (SQLException | InstantiationException | IllegalAccessException | NoSuchFieldException | SecurityException ex) {
        ex.printStackTrace();
    }

    return results;
}
