public static long hashDataWithRounds(String key, String data, int c, int d) {
   long hash = 0L;
   // perform C rounds of compression
   for(int i = 0; i < c; i++) {
      hash += compressionRound(hash, key, data);
   }
   // perform D rounds of compression
   for(int i = 0; i < d; i++) {
      hash += compressionRound(hash, data, key);
   }
   return hash;
}

// Helper function to perform one round of compression.
private static long compressionRound(long hash, String key, String data) {
   long result = 0L;
   for(int i = 0; i < key.length(); i++) {
      result ^= key.charAt(i) + hash + i;
   }
   for(int i = 0; i < data.length(); i++) {
      result ^= data.charAt(i) + hash + i;
   }
   return result;
}
