import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class GraphQLUtil {

    public static Map<String, Object> collectSubFields(List<String> parameters, List<Object> selectionSet) {
        Map<String, Object> subFields = new HashMap<>();

        for (Object selection : selectionSet) {
            if (selection instanceof String) {
                String fieldName = (String) selection;
                if (parameters.isEmpty() || parameters.contains(fieldName)) {
                    subFields.put(fieldName, true);
                }
            } else if (selection instanceof Map) {
                Map<String, Object> selectionMap = (Map<String, Object>) selection;
                for (Map.Entry<String, Object> entry : selectionMap.entrySet()) {
                    String subFieldName = entry.getKey();
                    List<Object> subSelectionSet = (List<Object>) entry.getValue();
                    if (subSelectionSet.isEmpty()) {
                        subFields.put(subFieldName, true);
                    } else {
                        Map<String, Object> subSubFields = collectSubFields(parameters, subSelectionSet);
                        if (!subSubFields.isEmpty()) {
                            subFields.put(subFieldName, subSubFields);
                        }
                    }
                }
            }
        }

        return subFields;
    }

}
