public static <T> ListenableFuture<T> toListenableFuture(final Single<T> single) {
    return new ListenableFuture<T>() {
        @Override
        public void addListener(Runnable runnable, Executor executor) {
            single.subscribe(new SingleObserver<T>() {
                @Override
                public void onSubscribe(Disposable disposable) {
                }

                @Override
                public void onSuccess(T t) {
                    executor.execute(runnable);
                }

                @Override
                public void onError(Throwable throwable) {
                    executor.execute(runnable);
                }
            });
        }

        @Override
        public boolean cancel(boolean b) {
            return false;
        }

        @Override
        public boolean isCancelled() {
            return false;
        }

        @Override
        public boolean isDone() {
            return false;
        }

        @Override
        public T get() throws InterruptedException, ExecutionException {
            throw new UnsupportedOperationException("This operation is not supported by ListenableFuture.");
        }

        @Override
        public T get(long l, TimeUnit timeUnit) throws InterruptedException, ExecutionException, TimeoutException {
            throw new UnsupportedOperationException("This operation is not supported by ListenableFuture.");
        }
    };
