public double hypervolume(double[][] front, double[][] referenceFront) {
    double[] refPoint = new double[referenceFront[0].length];
    for (int i = 0; i < refPoint.length; i++) {
        refPoint[i] = Double.POSITIVE_INFINITY;
        for (double[] point : referenceFront) {
            refPoint[i] = Math.min(refPoint[i], point[i]);
        }
    }

    double volume = 0;
    for (double[] point : front) {
        boolean pointIsDominated = false;
        for (double[] ref : referenceFront) {
            boolean refDominates = true;
            for (int i = 0; i < point.length && refDominates; i++) {
                if (point[i] > ref[i]) {
                    refDominates = false;
                }
            }
            if (refDominates) {
                pointIsDominated = true;
                break;
            }
        }
        if (!pointIsDominated) {
            volume += hypercubeVolume(point, refPoint);
        }
    }

    return volume;
}

private double hypercubeVolume(double[] point1, double[] point2) {
    double volume = 1;
    for (int i = 0; i < point1.length; i++) {
        volume *= point2[i] - point1[i];
    }
    return volume;
}
