public static Geometry scaleGeometry(Geometry geom, double xFactor, double yFactor, double zFactor){
    Geometry scaledGeom = geom.copy(); //create a copy of the input geometry

    //scaling the coordinates of the geometry by the given factors
    for (Coordinate coord : scaledGeom.getCoordinates()){
        coord.x *= xFactor;
        coord.y *= yFactor;
        coord.z *= zFactor;
    }

    return scaledGeom; //return the scaled geometry
}
