import java.io.File;
import java.io.IOException;

public static void createDirectoryIfNotExists(String path) throws IOException {
    File directory = new File(path);
    if(directory.exists()) {
        if(directory.isDirectory()) {
            return;
        } else {
            throw new IOException("The path already exists and it is not a directory.");
        }
    } else {
        boolean created = directory.mkdirs();
        if(!created) {
            throw new IOException("Could not create directory.");
        }
        String parent = directory.getParent();
        if(parent != null) {
            File parentDirectory = new File(parent);
            parentDirectory.getCanonicalFile().equals(parentDirectory.getAbsolutePath());
        }
    }
}
