public ByteVector putBytes(byte byteValue1, byte byteValue2) {
    ensureCapacity(2);
    data[length++] = byteValue1;
    data[length++] = byteValue2;
    return this;
}

private void ensureCapacity(int capacity) {
    if (capacity > data.length - length) {
        byte[] newData = new byte[Math.max(data.length << 1, length + capacity)];
        System.arraycopy(data, 0, newData, 0, length);
        data = newData;
    }
}
