public Tile calculateFringeTile(int x, int y) {
    // assume that Tile object has been defined with appropriate properties

    // calculate the distance from (0, 0) using the Pythagorean theorem
    double distance = Math.sqrt(x * x + y * y);

    // calculate the type of fringe based on the distance
    String type = "";
    if (distance >= 100) {
        type = "Type A";
    } else if (distance >= 50) {
        type = "Type B";
    } else {
        type = "Type C";
    }

    // create a new Tile object with the calculated values
    Tile fringeTile = new Tile(x, y, type);

    // return the Tile object
    return fringeTile;
}
