public Calendar getCalciteStyleCalendar(LocalDateTime dateTime, DateTimeZone timeZone) {
    Calendar calciteCalendar = Calendar.getInstance();
    calciteCalendar.setTimeZone(TimeZone.getTimeZone(timeZone.getID()));
    calciteCalendar.set(dateTime.getYear(), dateTime.getMonthOfYear() - 1, dateTime.getDayOfMonth(), dateTime.getHourOfDay(), dateTime.getMinuteOfHour(), dateTime.getSecondOfMinute());
    calciteCalendar.set(Calendar.MILLISECOND, dateTime.getMillisOfSecond());
    return calciteCalendar;
}
