import javax.smartcardio.*;

public class CardReader {

    public static CardTerminal getCardReader() throws CardException {
        TerminalFactory factory = TerminalFactory.getDefault();
        CardTerminals terminals = factory.terminals();
        if (terminals.list().size() == 1) {
            CardTerminal terminal = terminals.list().get(0);
            if (terminal.isCardPresent()) {
                return terminal;
            } else {
                throw new CardException("No card in the reader!");
            }
        } else {
            throw new CardException("Multiple card readers found! Insert card in one reader.");
        }
    }

}
