                    nextErr[x + 1][1] += diff[1] * 5;
                    nextErr[x + 1][2] += diff[2] * 5;




                    nextErr[x][0] += diff[0];  
                    nextErr[x][1] += diff[1];  
                    nextErr[x][2] += diff[2];  


                    x--;


                    if (x <= limit) {
                        break;
                    }
                }
            }


            int[][] temperr;
            temperr = currErr;
            currErr = nextErr;
            nextErr = temperr;


            if (alternateScans) {
