public void calculatePositions(List<EventWrapper> eventRects) {
    // sort events by start time
    Collections.sort(eventRects, new Comparator<EventWrapper>() {
        @Override
        public int compare(EventWrapper o1, EventWrapper o2) {
            return (int) (o1.getStartTime() - o2.getStartTime());
        }
    });

    // iterate through sorted events to calculate positions
    int maxEnd = 0;
    for (EventWrapper event : eventRects) {
        // check if this event overlaps with previous events
        if (event.getStartTime() < maxEnd) {
            // adjust left and right position based on previous event's end time
            event.setLeftPosition(event.getLeftPosition() + (maxEnd - event.getStartTime()));
        }
        // update max end time
        maxEnd = Math.max(maxEnd, event.getEndTime());
        // set right position based on max end time
        event.setRightPosition(event.getLeftPosition() + (event.getEndTime() - event.getStartTime()));
    }
}
