public class GraphicCreator {

  public static BufferedImage createGraphic(String mark, int size) {
    BufferedImage graphic = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
    Graphics g = graphic.getGraphics();
    g.drawString(mark, size/2 - mark.length()/2, size/2);
    g.dispose();
    return graphic;
  }

}
