public DirectoryResourceImpl getChildDirectoryResource(String childDirectoryName) throws ResourceException {
    Resource childResource = getResource(childDirectoryName);
    if (childResource == null) {
        // child resource does not exist, create a new instance
        return new DirectoryResourceImpl(this, childDirectoryName);
    }
    else if (childResource instanceof DirectoryResourceImpl) {
        // child resource exists and is of the correct type
        return (DirectoryResourceImpl) childResource;
    }
    else {
        // child resource exists but is of the wrong type
        throw new ResourceException("Child resource is not a DirectoryResourceImpl");
    }
}
