    if (numCoords >= 2 && !isClosed() && !isMoveTo(currentSegment)) {
        // add a line segment from the current point back to the last moveTo point
        addSegment(new PathSegment(PathIterator.SEG_LINETO, new double[] {
            lastMoveX, lastMoveY
        }));
        // mark the path as closed
        setClosed(true);
    }
}
