public int readGroup(InputStream input) throws IOException {
    // Read four bytes from input stream
    byte[] bytes = new byte[4];
    int bytesRead = input.read(bytes, 0, 4);

    // Convert bytes to integer value
    if (bytesRead == 4) {
        int value = ((bytes[0] & 0xff) << 24) |
                    ((bytes[1] & 0xff) << 16) |
                    ((bytes[2] & 0xff) << 8) |
                    (bytes[3] & 0xff);
        return value;
    } else {
        throw new IOException("Unexpected end of input stream");
    }
}
