public static String appendSequenceWord(int length, String fillType, String text) {
    // Split the text into words
    String[] words = text.split("\\s+");

    // Get the last word in the text
    String lastWord = words[words.length - 1];

    // Create the sequence word with the specified length and fill type
    StringBuilder sequenceWord = new StringBuilder();
    for (int i = 0; i < length; i++) {
        sequenceWord.append(fillType);
    }

    // Append the sequence word after the last word in the text
    return text + " " + sequenceWord.toString();
}
