public int getComponentCount(Components countcode) throws EpanetException {
    int count = 0;
    try {
        int networkSize = ENgetcount(EN_NODECOUNT);
        for (int i = 1; i <= networkSize; i++) {
            int componentType = ENgetnodevalue(i, EN_NODETYPE);
            if (componentType == countcode.getValue()) {
                count++;
            }
        }
    } catch (Exception e) {
        throw new EpanetException(e.getMessage());
    }
    return count;
}
