import java.util.*;

public static ArrayList<String> getOrderOfJoins(JoinGraph joinGraph) {
    ArrayList<String> joinOrder = new ArrayList<>();
    PriorityQueue<String> processingQueue = new PriorityQueue<>(joinGraph.getVertices().size(), new JoinOrderComparator(joinGraph));
    HashSet<String> visited = new HashSet<>();

    // push all vertices with no dependencies into the processing queue
    for (String vertex : joinGraph.getVertices()) {
        if (joinGraph.getDependencies(vertex).isEmpty()) {
            processingQueue.add(vertex);
        }
    }

    // while there are vertices left to process, add next in order to joinOrder and add dependencies to processing queue
    while (!processingQueue.isEmpty()) {
        String vertex = processingQueue.poll();
        if (visited.contains(vertex)) {
            continue;
        }
        visited.add(vertex);
        joinOrder.add(vertex);
        for (String dependent : joinGraph.getDependents(vertex)) {
            if (!visited.contains(dependent) && visited.containsAll(joinGraph.getDependencies(dependent))) {
                processingQueue.add(dependent);
            }
        }
    }

    return joinOrder;
}

private static class JoinOrderComparator implements Comparator<String> {
    private final JoinGraph joinGraph;

    public JoinOrderComparator(JoinGraph joinGraph) {
        this.joinGraph = joinGraph;
    }

    @Override
    public int compare(String vertex1, String vertex2) {
        Integer index1 = joinGraph.getJoinOrder().indexOf(vertex1);
        Integer index2 = joinGraph.getJoinOrder().indexOf(vertex2);
        return index1.compareTo(index2);
    }
}
