import java.util.function.Consumer;

public static <T1, T2, T3, T4> Consumer<Tuple4<T1, T2, T3, T4>> wrapConsumer(Consumer<? super T1> c1, Consumer<? super T2> c2, Consumer<? super T3> c3, Consumer<? super T4> c4) {
    return t -> {
        c1.accept(t.get1());
        c2.accept(t.get2());
        c3.accept(t.get3());
        c4.accept(t.get4());
