public Object invokeOnClass(Object instance, BeanManager manager) {
    Class<?> clazz = instance.getClass();
    Set<Bean<?>> beans = manager.getBeans(clazz);
    Bean<?> bean = manager.resolve(beans);
    Class<?> beanClass = bean.getBeanClass();
    Set<Method> methods = ReflectionUtils.getAllDeclaredMethods(beanClass);
    for (Method method : methods) {
        if (method.getName().equals(method.getName())) {
            return method.invoke(instance);
        }
    }
    return null;
}
