public boolean containsExclusive(Envelope other) {
    double thisMinX = this.getMinX();
    double thisMaxX = this.getMaxX();
    double thisMinY = this.getMinY();
    double thisMaxY = this.getMaxY();
    double otherMinX = other.getMinX();
    double otherMaxX = other.getMaxX();
    double otherMinY = other.getMinY();
    double otherMaxY = other.getMaxY();

    return (thisMinX < otherMinX && thisMaxX > otherMaxX
            && thisMinY < otherMinY && thisMaxY > otherMaxY);
}
