public void transformPosition(Vector3dc v, Vector3d dest) {
    double rx, ry;
    if (properties == PROPERTY_IDENTITY || v.z() == 0.0d) {
        dest.set(v);
        return;
    }
    if (properties == PROPERTY_TRANSLATION) {
        dest.set(v.x() + m30, v.y() + m31, v.z() + m32);
        return;
    }
    rx = m20 * v.x() + m21 * v.y() + m22 * v.z() + m23;
    ry = m10 * v.x() + m11 * v.y() + m12 * v.z() + m13;
    dest.set(m00 * v.x() + m01 * v.y() + m02 * v.z() + m03,
             m10 * v.x() + m11 * v.y() + m12 * v.z() + m13,
             m20 * v.x() + m21 * v.y() + m22 * v.z() + m23);
    double one = 1.0 / (rx + m20 * dest.x() + m21 * dest.y() + m22 * dest.z() + m23);
    dest.set(dest.x() * one, dest.y() * one, dest.z() * one);
}
