public class VisibleFieldsFinder {
    public static List<Field> getVisibleFields(Class<?> targetClass) {
        List<Field> visibleFields = new ArrayList<>();

        // Add declared fields
        visibleFields.addAll(Arrays.asList(targetClass.getDeclaredFields()));

        // Add inherited fields
        Class<?> superClass = targetClass.getSuperclass();
        if (superClass != null) {
            visibleFields.addAll(getVisibleFields(superClass));
        }

        return visibleFields;
    }
}
