    try {
        int hours = Integer.parseInt(text.substring(0, 3));
        int minutes = Integer.parseInt(text.substring(3));
        return ZoneOffset.ofHoursMinutes(hours, minutes);
    } catch (Exception e) {
        throw new IllegalArgumentException("Invalid UTC offset: " + text);
    }
}
