import java.io.File;
import java.nio.file.FileAlreadyExistsException;

public class FileManager {

    public static File createNewFile(Transaction txn, String path) throws FileAlreadyExistsException {
        File file = new File(txn.getTransactionDirectory() + "/" + path);

        if (file.exists()) {
            throw new FileAlreadyExistsException(file.getAbsolutePath());
        }

        try {
            file.createNewFile();
        } catch (IOException e) {
            e.printStackTrace();
        }

        return file;
    }

}
