public String generateAuthorizationHeader(String endpointUrl, Map<String, String> parameters) {
    // Compute the signature
    String signature = computeSignature(endpointUrl, parameters);

    // Add the signature to the parameters
    parameters.put("signature", signature);

    // Build the Authorization header string
    StringBuilder sb = new StringBuilder();
    sb.append("Authorization: ");
    sb.append("signature=");
    sb.append(signature);
    sb.append(", ");
    for (Map.Entry<String, String> entry : parameters.entrySet()) {
        sb.append(entry.getKey());
        sb.append("=");
        sb.append(entry.getValue());
        sb.append(", ");
    }
    sb.delete(sb.length() - 2, sb.length()); // Remove the trailing comma and space

    return sb.toString();
}

