public static String replaceAllMemoryOptimized(String original, String regex, String replacement) {
    int index = original.indexOf(regex);
    if (index == -1) {
        return original;
    }
    int len = regex.length();
    int replacementLen = replacement.length();
    StringBuilder result = new StringBuilder();
    int lastIndex = 0;
    while (index != -1) {
        result.append(original.substring(lastIndex, index));
        result.append(replacement);
        lastIndex = index + len;
        index = original.indexOf(regex, lastIndex);
    }
    result.append(original.substring(lastIndex));
    return result.toString();
}
