public void checkAcceptanceInfo(int[] stateVector) throws FSMParseException {
    // find the index of the acceptance information in the state vector
    int acceptanceInfoIndex = -1;
    for (int i = 0; i < stateVector.length; i++) {
        if (stateVector[i] == 1) {
            acceptanceInfoIndex = i;
            break;
        }
    }
    // throw an exception if the acceptance information is not found
    if (acceptanceInfoIndex == -1) {
        throw new FSMParseException("Could not find acceptance information in state vector.");
    }
}
