    // Converting the hour to 12-hour format
    int hourValue = Integer.parseInt(hour);
    int twelveHourValue = hourValue % 12 == 0 ? 12 : hourValue % 12;

    // Appending the result to the buffer
    buf.append(String.format("%02d:00 %s", twelveHourValue, hourValue < 12 ? "AM" : "PM"));
}
