public boolean areEquivalentComparisons(String e1, String e2) {
    boolean areComparisons = (e1.contains("<") || e1.contains(">")) && (e2.contains("<") || e2.contains(">"));
    boolean areEquivalent = false;
    if (areComparisons) {
        String op1 = e1.contains("<") ? "<" : ">";
        String op2 = e2.contains("<") ? "<" : ">";
        String[] e1parts = e1.split(op1);
        String[] e2parts = e2.split(op2);
        if (e1parts.length == 2 && e2parts.length == 2) {
            areEquivalent = e1parts[0].trim().equals(e2parts[1].trim()) && e1parts[1].trim().equals(e2parts[0].trim());
        }
    }
    return areComparisons && areEquivalent;
}
