public void invalidateXgboostObjects(List<Object> xgbObjects) throws IllegalStateException {
    Exception cause = null;
    for (Object obj : xgbObjects) {
        try {
            if (obj instanceof Booster) {
                ((Booster) obj).dispose();
            } else if (obj instanceof DMatrix) {
                ((DMatrix) obj).dispose();
            }
        } catch (XGBoostError e) {
            if (cause == null) {
                cause = new IllegalStateException(e.getMessage());
            }
        }
    }
    if (cause != null) {
        throw new IllegalStateException("Object invalidation failed", cause);
    }
}
