public int iterateTasks(int id, Task task, int outlineLevel) {
    task.setOutlineLevel(outlineLevel);
    task.setId(id);

    int nextId = id + 1;
    for(Task child : task.getChildren()) {
        nextId = iterateTasks(nextId, child, outlineLevel + 1);
    }

    return nextId;
}
