public void updateTimers(Map<String, Timer> contacts, int newTimeout) {
    for (Map.Entry<String, Timer> entry : contacts.entrySet()) {
        Timer timer = entry.getValue();
        if (timer == null) {
            timer = new Timer(newTimeout);
            timer.setActivity(null);
            contacts.put(entry.getKey(), timer);
        } else {
            timer.reset(newTimeout);
        }
    }
}
