        Class<?> superClass = extension.getSuperclass();
        if (superClass != null) {
            superTypes.add(superClass);
        }
        Class<?>[] interfaces = extension.getInterfaces();
        if (interfaces != null && interfaces.length > 0) {
            superTypes.addAll(Arrays.asList(interfaces));
        }
    }
    return superTypes;
}
