public List<String> extractSearchParamStrings(ResourceTable theEntity, IBaseResource theResource) {
    List<String> retVal = new ArrayList<>();

    SearchParamExtractorService extractorService = myValidationSettings.getResourceValidator().getSearchParamExtractorService();
    Set<String> have = new HashSet<>();
    List<JpaRuntimeSearchParam> allParams = extractorService.extractSearchParamHandlers(myContext, theResource.getClass());

    for (JpaRuntimeSearchParam nextParam : allParams) {
        List<BinderUtil.SearchParamSet<PathAndRef>> paramSetList = extractorService.extractHandledSearchParamSets(theEntity, theResource, nextParam, true, "extractSearchParamStrings");

        for (BinderUtil.SearchParamSet<PathAndRef> nextSearchParamSet : paramSetList) {
            String nextValue = nextSearchParamSet.toQueryParameter(myContext, myResourceIndexedSearchParamUriDao);
            if (isNotBlank(nextValue)) {
                if (have.add(nextValue)) {
                    retVal.add(nextValue);
                }
            }
        }
    }

    return retVal;
