            break;
        case FILE:
            logsContainer = "$log";
            break;
        default:
            throw new IllegalArgumentException(String.format("The specified service \"%s\" does not support logging.", service.toString()));
    }
    CloudBlobContainer container = this.getContainerReference(logsContainer);
    return container.getDirectoryReference("");
}
