public void highlightComments(String[] fileLines, String commentDelimiter) {
    boolean isComment = false;
    for (String line : fileLines) {
        if (line.contains(commentDelimiter)) {
            isComment = true;
        }
        if (isComment) {
            // highlight the comment line
            System.out.println("Highlighted Comment: " + line);
        }
        if (line.contains(commentDelimiter + ";")) {
            isComment = false;
        }
    }
}
