public static void normalizeMatrix(Matrix m) {
    double sum = 0.0;
    for (int i = 0; i < m.getRowDimension(); i++) {
        for (int j = 0; j < m.getColumnDimension(); j++) {
            sum += Math.pow(m.get(i, j), 2);
        }
    }
    double norm = Math.sqrt(sum);
    for (int i = 0; i < m.getRowDimension(); i++) {
        for (int j = 0; j < m.getColumnDimension(); j++) {
            m.set(i, j, m.get(i, j) / norm);
        }
    }
}
