public static <T> T convertObject(Object source, Class<T> targetType) {
    if (source == null) {
        return null;
    }
    if (!targetType.isAssignableFrom(source.getClass())) {
        throw new IllegalArgumentException("Cannot convert object of type " + source.getClass().getName() + " to " + targetType.getName());
    }
    return (T) source;
}
