public static String extractTagValueId(TSDB tsdb, byte[] row, String tag_id) {
  try {
    final UniqueId uid = tsdb.getRegistry().getUniqueId(tag_id, true);
    if (uid == null) {
      throw new RuntimeException("Unable to get or create an ID for the tag");
    }

    final Iterator<Pair<byte[], ByteStream>> iterator = UniqueId.uidIterator(row);
    while (iterator.hasNext()) {
      final Pair<byte[], ByteStream> next = iterator.next();
      if (uid.equals(next.right.streamToUniqueId())) {
        final byte[] value = next.left;
        if (value == null) {
          continue;
        }
        return tsdb.getRegistry().resolveName(value, true);
      }
    }
    return null;
  } catch (final RuntimeException e) {
    throw new RuntimeException("Unable to extract value ID for tag", e);
  }
}
