public void findMinimumBoundingRectangle(Polygon polygon, Rectangle2D rectangle) {
    double[] x = polygon.xpoints;
    double[] y = polygon.ypoints;
    double mu_x = 0.0, mu_y = 0.0;
    for (int i = 0; i < polygon.npoints; ++i) {
        mu_x += x[i];
        mu_y += y[i];
    }
    mu_x /= polygon.npoints;
    mu_y /= polygon.npoints;
    double[] X = new double[polygon.npoints];
    double[] Y = new double[polygon.npoints];
    for (int i = 0; i < polygon.npoints; ++i) {
        X[i] = x[i] - mu_x;
        Y[i] = y[i] - mu_y;
    }
    double[] C = new double[4], S = new double[4];
    double[] D = new double[4];
    double[][] A = {{0, 0}, {0, 0}};
    for (int i = 0; i < polygon.npoints; ++i) {
        A[0][0] += X[i] * X[i];
        A[0][1] += X[i] * Y[i];
        A[1][0] += X[i] * Y[i];
        A[1][1] += Y[i] * Y[i];
    }
    EigenDecomposition ed = new EigenDecomposition(new Array2DRowRealMatrix(A));
    RealVector evals = ed.getRealEigenvalues();
    RealMatrix evecs = ed.getV();
    double maxEig = 0;
    int k = 0;
    for (int i = 0; i < 2; i++) {
        if (evals.getEntry(i) > maxEig) {
            maxEig = evals.getEntry(i);
            k = i;
        }
        C[i] = evecs.getEntry(i, k);
        S[i] = evecs.getEntry(i, k ^ 1);
        D[i] = 0.0;
    }
    for (int i = 0; i < polygon.npoints; ++i) {
        double xd = X[i], yd = Y[i];
        D[0] += xd * C[0] + yd * S[0];
        D[1] += xd * C[1] + yd * S[1];
    }
    double xmin = D[0], xmax = D[0], ymin = D[1], ymax = D[1];
    for(int i=1; i < polygon.npoints; ++i) {
        double xd = X[i], yd = Y[i];
        double xnew = xd * C[0] + yd * S[0];
        double ynew = xd * C[1] + yd * S[1];
        if (xnew < xmin) xmin = xnew;
        if (xnew > xmax) xmax = xnew;
        if (ynew < ymin) ymin = ynew;
        if (ynew > ymax) ymax = ynew;
    }
    rectangle.setRect(mu_x + C[0] * xmin + S[0] * ymin, mu_y + C[1] * xmin + S[1] * ymin, xmax - xmin, ymax - ymin);
}
