    }
    // Check if any step of the iterator is dependent on the context node
    while (iterator.getPredicateCount() > 0) {
        if (iterator.isDocOrdered()) {
            return false;
        }
        iterator = iterator.getLocPathIterator();
    }
    int otherStep = iterator.getAxis();
    if (otherStep == Axis.SELF || otherStep == Axis.ROOT) {
        return true;
    }
    return false;
}
