public static BoundedPoolConfig convertConfig(GenericObjectPoolConfig config) {
    Objects.requireNonNull(config, "Config must not be null");

    int maxTotal = config.getMaxTotal();
    int maxIdle = config.getMaxIdle();
    int minIdle = config.getMinIdle();
    long maxWaitMillis = config.getMaxWaitMillis();
    boolean testOnBorrow = config.getTestOnBorrow();
    boolean testOnCreate = config.getTestOnCreate();
    boolean testOnReturn = config.getTestOnReturn();

    return new BoundedPoolConfig.Builder()
            .setMaxTotal(maxTotal)
            .setMaxIdle(maxIdle)
            .setMinIdle(minIdle)
            .setMaxWaitMillis(maxWaitMillis)
            .setTestOnBorrow(testOnBorrow)
            .setTestOnCreate(testOnCreate)
            .setTestOnReturn(testOnReturn)
            .build();
}
