public String createExactMatchFilter(String name, String value) {
  return "(" + name + "=" + escapeSpecialChars(value) + ")";
}

private String escapeSpecialChars(String value) {
  value = value.replaceAll("\\\\", "\\\\\\\\");
  value = value.replaceAll("\\(", "\\\\(");
  value = value.replaceAll("\\)", "\\\\)");
  value = value.replaceAll("\\*", "\\\\*");
  value = value.replaceAll("/", "\\\\/");
  value = value.replaceAll("\\[", "\\\\[");
  value = value.replaceAll("\\]", "\\\\]");
  value = value.replaceAll("\\{", "\\\\{");
  value = value.replaceAll("\\}", "\\\\}");
  value = value.replaceAll("\\|", "\\\\|");
  value = value.replaceAll("\\+", "\\\\+");
  value = value.replaceAll("\\?", "\\\\?");
  value = value.replaceAll("\\.", "\\\\.");
  value = value.replaceAll("\\^", "\\\\^");
  return value;
}
