public void scaleAllWidgets(Parent parent, double scale) {
    for (Node node : parent.getChildrenUnmodifiable()) {
        if (node instanceof Parent) {
            scaleAllWidgets((Parent) node, scale);  // recursively scale children
        }
        node.setScaleX(scale);
        node.setScaleY(scale);
    }
}
