public int getDocumentFrequency(String term, List<String> collection, Set<String> filteredTerms) {
    if (filteredTerms.contains(term)) {
        return 0;
    }

    int documentFrequency = 0;
    for (String document : collection) {
        if (document.contains(term)) {
            documentFrequency++;
        }
    }

    return documentFrequency;
}
