public File getFileAndEnsureDirExists(String name) throws IOException {
    // set the cache directory
    File cacheDir = new File("cache");

    // create the cache directory if it does not exist
    if (!cacheDir.exists()) {
        cacheDir.mkdir();
    }

    // create a new file in the cache directory with the provided filename
    File file = new File(cacheDir, name);

    // create the file if it does not exist
    if (!file.exists()) {
        file.createNewFile();
    }

    return file;
}
