public List<List<Pair<Integer, Integer>>> reverseEdges(List<List<Pair<Integer, Integer>>> graph) {
    int n = graph.size();
    List<List<Pair<Integer, Integer>>> reversedGraph = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        reversedGraph.add(new ArrayList<>());
    }
    for (int i = 0; i < n; i++) {
        for (Pair<Integer, Integer> edge : graph.get(i)) {
            int dest = edge.first;
            int weight = edge.second;
            reversedGraph.get(dest).add(new Pair<>(i, weight));
        }
    }
    return reversedGraph;
}
