public String stripDefaultPort(String url) {
    String[] parts = url.split(":");
    if (parts.length < 2) {
        return url;
    }
    String scheme = parts[0].toLowerCase();
    int portIndex = parts[1].indexOf("/");
    if (portIndex == -1) {
        portIndex = parts[1].length();
    }
    int port;
    try {
        port = Integer.parseInt(parts[1].substring(0, portIndex));
    } catch (NumberFormatException e) {
        return url;
    }
    if (port < 0 || port > 65535) {
        return url;
    }
    String defaultPort = null;
    switch (scheme) {
        case "http":
            defaultPort = "80";
            break;
        case "https":
            defaultPort = "443";
            break;
        case "ftp":
            defaultPort = "21";
            break;
        case "sftp":
            defaultPort = "22";
            break;
    }
    if (defaultPort != null && Integer.toString(port).equals(defaultPort)) {
        return parts[0] + ":" + parts[1].substring(portIndex);
    }
    return url;
}
