import org.apache.solr.client.solrj.SolrClient;
import org.springframework.dao.DataAccessResourceFailureException;

public class SolrUtil {
    public static void closeSolrClient(SolrClient solrClient) throws DataAccessResourceFailureException {
        if (solrClient == null) {
            throw new DataAccessResourceFailureException("SolrClient cannot be null");
        }
        try {
            // Check for the Solr version and call the respective method to close
            if (solrClient instanceof org.apache.solr.client.solrj.impl.CloudSolrClient) {
                org.apache.solr.client.solrj.impl.CloudSolrClient cloudSolrClient = (org.apache.solr.client.solrj.impl.CloudSolrClient) solrClient;
                cloudSolrClient.close();
            } else if (solrClient instanceof org.apache.solr.client.solrj.impl.HttpSolrClient ||
                    solrClient instanceof org.apache.solr.client.solrj.impl.LBHttpSolrClient ||
                    solrClient instanceof org.apache.solr.client.solrj.impl.BinaryRequestWriter ||
                    solrClient instanceof org.apache.solr.client.solrj.impl.HttpClientUtil) {
                solrClient.close();
            } else if (solrClient instanceof org.apache.solr.client.solrj.impl.ConcurrentUpdateSolrClient) {
                org.apache.solr.client.solrj.impl.ConcurrentUpdateSolrClient concurrentUpdateSolrClient = (org.apache.solr.client.solrj.impl.ConcurrentUpdateSolrClient) solrClient;
                concurrentUpdateSolrClient.shutdown();
            } else {
                // In case the Solr version is not recognizable
                throw new DataAccessResourceFailureException("Unknown SolrClient library. Cannot close it.");
            }
        } catch (Exception e) {
            throw new DataAccessResourceFailureException("Error occurred while closing the SolrClient.", e);
        }
    }
}
