public static String unescape(String str) {
    StringBuilder sb = new StringBuilder(str.length());
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i < str.length() - 1) {
                char nextChar = str.charAt(i + 1);
                switch (nextChar) {
                    case '\\':
                        sb.append('\\');
                        break;
                    case 't':
                        sb.append('\t');
                        break;
                    case 'r':
                        sb.append('\r');
                        break;
                    case 'n':
                        sb.append('\n');
                        break;
                    case '\'':
                        sb.append('\'');
                        break;
                    case '\"':
                        sb.append('\"');
                        break;
                    case '\f':
                        sb.append('\f');
                        break;
                    case '\b':
                        sb.append('\b');
                        break;
                    default:
                        sb.append(nextChar);
                        break;
                }
                i++;
            } else {
                sb.append(c);
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}
