public static String methodSignature(String name, Object... args) {
    StringBuilder sb = new StringBuilder(name + "(");
    if (args.length > 0) {
        for (int i = 0; i < args.length - 1; i++) {
            sb.append(args[i].getClass().getSimpleName()).append(", ");
        }
        Object last = args[args.length - 1];
        if (last.getClass().isArray()) {
            sb.append(last.getClass().getSimpleName().replace("[]", "..."));
        } else {
            sb.append(last.getClass().getSimpleName());
        }
    }
    sb.append(")");
    return sb.toString();
}
