public class MyClass {

    private Predicate<Object> predicate;

    public MyClass and(Predicate<Object> other) {
        this.predicate = this.predicate.and(other);
        return this;
    }

    public MyClass or(Predicate<Object> other) {
        this.predicate = this.predicate.or(other);
        return this;
    }

    public MyClass andOr(Predicate<Object>... args) {
        Predicate<Object> union = Arrays.stream(args).reduce(Predicate::or).orElse(t -> false);
        this.predicate = this.predicate.and(union);
        return this;
    }
}
