public static String escape(char[] input, int level, int type) {
    StringBuilder sb = new StringBuilder();
    for (char c : input) {
        switch (c) {
            case '"':
                if (level >= 1) sb.append("\\\"");
                else sb.append(c);
                break;
            case '\'':
                if (level >= 2) sb.append("\\\'");
                else sb.append(c);
                break;
            case '\\':
                if (level >= 3) sb.append("\\\\");
                else sb.append(c);
                break;
            case '\r':
                if (level >= 4 && type != 1) sb.append("\\r");
                else sb.append(c);
                break;
            case '\n':
                if (level >= 4 && type != 2) sb.append("\\n");
                else sb.append(c);
                break;
            case '\t':
                if (level >= 4 && type != 3) sb.append("\\t");
                else sb.append(c);
                break;
            default:
                sb.append(c);
                break;
        }
    }
    return sb.toString();
}
