public int getBatchSize(String persistenceUnit, Properties puProperties) {

    // Get the EntityManagerFactory for the given persistence unit and properties
    EntityManagerFactory emf = Persistence.createEntityManagerFactory(persistenceUnit, puProperties);

    try {

        // Get the Hibernate SessionFactory from the EntityManagerFactory
        SessionFactory sessionFactory = emf.unwrap(SessionFactory.class);

        // Get the Hibernate SessionFactory's settings
        final Settings settings = sessionFactory.getSessionFactoryOptions().getServiceRegistry().getService(ConfigurationService.class).getSettings();

        // Get the batch size from the settings
        return Integer.parseInt(settings.getProperty(Environment.STATEMENT_BATCH_SIZE));

    } finally {

        // Close the EntityManagerFactory to release its resources
        emf.close();
    }
}
