public static Method findMethod(Class javaClass, String methodName, Class<?>... parameterTypes) throws NoSuchMethodException {
    Method method;
    try {
        method = javaClass.getDeclaredMethod(methodName, parameterTypes);
    } catch (NoSuchMethodException e) {
        if (javaClass.getSuperclass() != null) {
            method = findMethod(javaClass.getSuperclass(), methodName, parameterTypes);
        } else {
            throw e;
        }
    }
    return method;
}
