public static <T> ContentBuilder marshalBean(Map<String, Object> map, T bean) throws StorageException {
    try {
        // create a new content builder
        ContentBuilder builder = new ContentBuilder(map);

        // use reflection to get the bean's properties and store them in the map
        BeanInfo info = Introspector.getBeanInfo(bean.getClass());
        for (PropertyDescriptor pd : info.getPropertyDescriptors()) {
            String name = pd.getName();
            if (!"class".equals(name)) {
                Object value = pd.getReadMethod().invoke(bean);
                map.put(name, value);
            }
        }

        return builder;
    } catch (IntrospectionException | IllegalAccessException | IllegalArgumentException | InvocationTargetException e) {
        throw new StorageException("Error while storing bean: " + e.getMessage());
    }
}
