public ByteBuffer asByteBuffer(String xpath, Node node) throws Exception {
  XPathExpression expression = XPathFactory.newInstance().newXPath().compile(xpath);
  Node resultNode = (Node) expression.evaluate(node, XPathConstants.NODE);
  String resultString = resultNode.getNodeValue();
  Charset charset = Charset.forName("UTF-8");
  return ByteBuffer.wrap(resultString.getBytes(charset));
}
