public byte[] extractTargetInfo(byte[] msg, byte[] msgFlags) {
    byte[] targetInfo;
    if (msgFlags == null) {
        msgFlags = Arrays.copyOfRange(msg, 8, 10);
    }
    int targetInfoOffset = ((msgFlags[1] & 0xFF) << 8) + (msgFlags[0] & 0xFF);
    int targetInfoLength = ((msgFlags[3] & 0xFF) << 8) + (msgFlags[2] & 0xFF);
    targetInfo = Arrays.copyOfRange(msg, targetInfoOffset, targetInfoOffset + targetInfoLength);
    return targetInfo;
}
