        filterMap = new ObjectMapper().readValue(filter, HashMap.class);
    } catch (IOException e) {
        e.printStackTrace();
    }

    // use filter map to construct query
    String query = "";
    for (String key : filterMap.keySet()) {
        if (!query.isEmpty()) {
            query += " AND ";
        }
        query += key + "=" + filterMap.get(key);
    }

    // execute query and return results
    List<AppfwglobalAuditsyslogpolicyBinding> results = new ArrayList<>();
    try {
        results = NitroApiUtils.getResourceObjects(AppfwglobalAuditsyslogpolicyBinding.class, query);
    } catch (Exception e) {
        e.printStackTrace();
    }
    return results;
}
