public static Addon parseAddonCoordinates(String coordinates) {
  String[] coords = coordinates.split(":");
  if (coords.length != 2 || coords[0].isEmpty() || coords[1].isEmpty()) {
    throw new IllegalArgumentException("Invalid addon coordinates: " + coordinates);
  }

  String[] groupAndName = coords[0].split("\\.");
  if (groupAndName.length != 2 || groupAndName[0].isEmpty() || groupAndName[1].isEmpty()) {
    throw new IllegalArgumentException("Invalid group and name in addon coordinates: " + coordinates);
  }

  String version = coords[1];
  if (version.isEmpty()) {
    throw new IllegalArgumentException("Invalid version in addon coordinates: " + coordinates);
  }

  return new Addon(groupAndName[0], groupAndName[1], version);
}
