public class JSONResolver {
    public static Object resolveJSON(JSONObject json, String[] keys) {
        if (keys.length == 1) {
            return json.get(keys[0]);
        } else {
            JSONObject subJSON = json.getJSONObject(keys[0]);
            String[] subKeys = Arrays.copyOfRange(keys, 1, keys.length);
            return resolveJSON(subJSON, subKeys);
        }
    }
}
