import java.net.URI;
import java.net.URISyntaxException;

public static String removeDefaultPortFromUrl(String url) throws URISyntaxException {
    URI uri = new URI(url);
    int port = uri.getPort();
    if (port == uri.getDefaultPort()) {
        // Default port for the scheme - remove it
        uri = new URI(uri.getScheme(), uri.getUserInfo(), uri.getHost(), -1, uri.getPath(), uri.getQuery(), uri.getFragment());
    }
    return uri.toString();
}
