public Feed getCollection(HttpServletRequest areq) throws AtomException {
    String collectionPath = areq.getPathInfo();
    if (collectionPath == null || collectionPath.length() <= 1) {
        throw new AtomException("Invalid collection path");
    }
    String[] parts = collectionPath.split("/");
    String workspaceName = parts[1];
    String collectionName = parts[2];
    Workspace workspace = getWorkspace(workspaceName);
    if (workspace == null) {
        throw new AtomNotFoundException("Workspace not found: " + workspaceName);
    }
    EntryCollection collection = workspace.getEntryCollection(collectionName);
    if (collection == null) {
        throw new AtomNotFoundException("Collection not found: " + collectionName);
    }
    Feed feed = buildFeedFromCollection(collection);
    return feed;
}
