public static double evaluateClustering(Database db, Instances rel, Cluster[] c) throws Exception {
    double[] clusterVariance = new double[c.length];
    double totalVariance = 0;
    for (int i = 0; i < c.length; i++) {
        Instances clusterInstances = c[i].getClusterInstances();
        if (clusterInstances.numInstances() > 0) {
            clusterVariance[i] = c[i].getClusterNotClassVariance();
            totalVariance += clusterVariance[i];
        }
    }

    double varianceBetweenClusters = db.getDataNotClassVariance() - totalVariance;
    double ratio = varianceBetweenClusters / db.getDataNotClassVariance();
    return ratio;
}
