public static byte[] decodeHexString(String encoded) {
    if (encoded == null || encoded.length() % 2 == 1) {
        return null;
    }
    int len = encoded.length() / 2;
    byte[] result = new byte[len];
    for (int i = 0; i < len; i++) {
        int digit1 = Character.digit(encoded.charAt(i * 2), 16);
        int digit2 = Character.digit(encoded.charAt(i * 2 + 1), 16);
        if (digit1 < 0 || digit2 < 0) {
            return null;
        }
        result[i] = (byte) ((digit1 << 4) + digit2);
    }
    return result;
}
