public static boolean renameFile(File legacyFile, String newFileName) {
    File newFile = new File(legacyFile.getParent(), newFileName);

    if (newFile.exists() && System.getProperty("os.name").startsWith("Windows")) {
        try {
            Files.move(legacyFile.toPath(), newFile.toPath(), StandardCopyOption.REPLACE_EXISTING);
        } catch (IOException e) {
            return false;
        }
    } else {
        if (!legacyFile.renameTo(newFile)) {
            return false;
        }
    }

    return true;
}
