public void shutdownSchedulersAndWorkers() {
   // Performs a graceful shutdown of all registered schedulers and workers
   // The maximum time to wait for the threads to exit is SHUTDOWN_DURATION seconds.
   final long SHUTDOWN_DURATION = 10;

   // Get the list of all registered schedulers and background workers
   List<Thread> threads = getAllSchedulerAndWorkers();

   // Shut down all schedulers and workers
   for (Thread thread : threads) {
      thread.interrupt();
   }

   // Wait for all threads to exit or until shutdownDuration expires
   long startTime = System.currentTimeMillis();
   long elapsedTime = 0;
   try {
      while (elapsedTime < SHUTDOWN_DURATION * 1000) {
         for (Thread thread : threads) {
            if (thread.isAlive()) {
               thread.join(1000);
            }
         }
         elapsedTime = System.currentTimeMillis() - startTime;
      }
   } catch (InterruptedException e) {
      Thread.currentThread().interrupt();
   }

   // Terminate all threads that have not exited gracefully
   for (Thread thread : threads) {
      if (thread.isAlive()) {
         thread.interrupt();
      }
   }
}
