public Date[] getDatesFromTimeRangeString(String timeRangeString) {
    Date[] dates = new Date[2];

    if (timeRangeString == null || timeRangeString.isEmpty()) {
        return null;
    }

    String[] dateStrings = timeRangeString.split(" - ");
    if (dateStrings.length != 2) {
        return null;
    }

    SimpleDateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd");
    try {
        dates[0] = dateFormat.parse(dateStrings[0]);
        dates[1] = dateFormat.parse(dateStrings[1]);
    } catch (ParseException e) {
        // Handle exception if required
    }

    return dates;
}
