		InputStream is = getInputStream();
		try {
			byte[] bytes = new byte[3];
			int count = is.read(bytes);
			ByteOrderMask bom = ByteOrderMask.valueOf(bytes, 0, count);
			if(bom != null){
				return false;
			}
			while(true){
				int i = is.read();
				switch(i){
					case -1:
						return false;
					case 0:
						return true;
					default:
						break;
				}
			}
		} finally {
			is.close();
		}
