public void createNewFileVersion(Node fileNode, InputStream inputStream, List<String> mixins) throws RepositoryException {
    Node fileVersionNode = fileNode.addNode(VersionConstants.RENDITIONS_FOLDER + "/" + VersionConstants.DEFAULT_VERSION_NAME, VersionConstants.NT_VERSION);
    fileVersionNode.addMixin(VersionConstants.MIX_VERSIONABLE);
    if (mixins != null) {
        for (String mixin : mixins) {
            fileVersionNode.addMixin(mixin);
        }
    }
    Binary binary = fileNode.getSession().getValueFactory().createBinary(inputStream);
    fileVersionNode.setProperty(JcrConstants.JCR_DATA, binary);
    fileVersionNode.setProperty(JcrConstants.JCR_MIMETYPE, mimeTypeService.detectMimeType(fileNode.getName()));
    fileVersionNode.setProperty(JcrConstants.JCR_VERSIONLABEL, VersionConstants.DEFAULT_VERSION_NAME);
    fileNode.setProperty(JcrConstants.JCR_BASEVERSION, fileNode.getBaseVersion());
    fileNode.getSession().save();
}
