public Message updateTwilioMessage(TwilioRestClient client) {
    // Define the endpoint URL for the Message update request
    String messageSid = "MESSAGE_SID"; // replace with actual SID of the message to update
    String endpoint = String.format("/Messages/%s.json", messageSid);

    // Create the request with the updated property values
    Map<String, String> params = new HashMap<>();
    params.put("Body", "UPDATED_MESSAGE_BODY"); // replace with actual updated message body
    params.put("Status", "read"); // replace with actual updated message status
    Request request = new Request(HttpMethod.POST, endpoint, params);

    // Make the request to the Twilio API and return the updated Message
    Response response = client.request(request);
    String responseBody = response.getBody();
    Message updatedMessage = Message.fromJson(responseBody);
    return updatedMessage;
}
