public void addOrUpdateBinding(String annotation, Object data) {
    if (injectionBindings.containsKey(annotation)) {
        // Merge data with existing binding
        Object existingData = injectionBindings.get(annotation);
        if (existingData instanceof Map && data instanceof Map) {
            ((Map<String, Object>) existingData).putAll((Map<String, Object>) data);
        } else {
            // Overwrite existing binding with new data
            injectionBindings.put(annotation, data);
        }
    } else {
        // Create new binding
        injectionBindings.put(annotation, data);
    }
}
