public String toString(String f) {
  String result = "";
  // Iterate through object's fields and append each field to the result string with the given separator
  for (Field field : this.getClass().getDeclaredFields()) {
    try {
      field.setAccessible(true);  // set field accessible
      Object value = field.get(this); // get field value
      result += value + f;  // append field value with separator to result string
    } catch (IllegalAccessException e) {
      e.printStackTrace();
    }
  }
  return result.substring(0, result.length() - f.length()); // remove last separator before returning result
}
