public static int dotProduct(int[] nums1, int[] nums2) {
    int i = 0, j = 0, sum = 0;
    while (i < nums1.length && j < nums2.length) {
        if (nums1[i] < nums2[j])
            i++;
        else if (nums1[i] > nums2[j])
            j++;
        else {
            sum += nums1[i] * nums2[j];
            i++;
            j++;
        }
    }
    return sum;
}
