public HeadersExtension parseHeadersExtension(XmlPullParser parser) throws XmlPullParserException, IOException, SmackParsingException {
    HeadersExtension headersExtension = null;
    int eventType = parser.getEventType();
    String elementName = parser.getName();

    if (eventType == XmlPullParser.START_TAG && elementName.equals(HeadersExtension.ELEMENT)) {
        String xmlns = parser.getNamespace();
        Map<String, String> headersMap = new HashMap<String, String>();
        boolean done = false;

        while (!done) {
            eventType = parser.next();

            if (eventType == XmlPullParser.START_TAG && parser.getName().equals(HeadersExtension.HEADER_ELEMENT)) {
                String headerName = parser.getAttributeValue(null, HeadersExtension.HEADER_NAME_ATTRIBUTE);
                String headerValue = parser.nextText();
                headersMap.put(headerName, headerValue);
            } else if (eventType == XmlPullParser.END_TAG && parser.getName().equals(HeadersExtension.ELEMENT)) {
                headersExtension = new HeadersExtension(xmlns, headersMap);
                done = true;
            }
        }
    }
    return headersExtension;
}
