public void guessTypeAndPutInMap(Map<String, Object> params, Object value) {
    if (value instanceof String) {
        params.put("stringParam", (String) value);
    } else if (value instanceof Integer) {
        params.put("intParam", (Integer) value);
    } else if (value instanceof Double) {
        params.put("doubleParam", (Double) value);
    } else if (value instanceof Boolean) {
        params.put("booleanParam", (Boolean) value);
    } else {
        params.put("objectParam", value);
    }
}
