public void setPrimaryKey(int index, Record record, Statement statement, String opCode) throws OnRecordErrorException {
    Map<String, Field> headers = record.getHeader().getFields();
    Map<String, String> primaryKeys = new HashMap<>();
    // add primary key headers to the map
    for (String headerName : headers.keySet()) {
        String headerValue = headers.get(headerName).getValueAsString();
        if (headerValue != null && headerValue.trim().length() > 0 && headers.get(headerName).getAttribute("primary") != null) {
            primaryKeys.put(headerName, headers.get(headerName).getValueAsString());
        }
    }
    // check if all primary keys are present in the record
    if (primaryKeys.size() != index) {
        throw new OnRecordErrorException(Errors.API_40);
    }
    // set primary key values in query statement
    try {
        for (String headerName : primaryKeys.keySet()) {
            statement.setString(primaryKeys.get(headerName), record.get(headerName).getValueAsString());
        }
    } catch (SQLException e) {
        throw new OnRecordErrorException(Errors.API_41, e.getMessage());
    }
}
