public static double[] gridIndexToPoint(double[][][] grid, int idx) {
    int[] gridSize = {grid.length, grid[0].length, grid[0][0].length};
    int x = idx % gridSize[0];
    int yz = idx / gridSize[0];
    int y = yz % gridSize[1];
    int z = yz / gridSize[1];
    double[] point = {grid[x][y][z][0], grid[x][y][z][1], grid[x][y][z][2]};
    return point;
}
