public void mergeDocs(List<String> hints) throws SeedException {
    // Check if hints list is empty or has only 1 element
    if (hints.size() < 2) {
        return;
    }

    // Get the docs link from the first element
    String docsLink = getDocsLink(hints.get(0));

    // Check if other hints have the same docs link
    for (int i = 1; i < hints.size(); i++) {
        String hint = hints.get(i);
        String otherLink = getDocsLink(hint);
        if (!docsLink.equals(otherLink)) {
            throw new SeedException("Other resource has a different docs link");
        }
    }

    // Merge the hints into one string
    String mergedHint = String.join(", ", hints);
    System.out.println("Merged hint: " + mergedHint);
}

private String getDocsLink(String hint) {
    // Parse the hint string and get the docs link
    String[] parts = hint.split(":");
    return parts[1];
}

