public int getNumOutputsFromLayerConfig(Map<String, Object> layerConfig) throws InvalidKerasConfigurationException {

    if (!layerConfig.containsKey("class_name")) {
        throw new InvalidKerasConfigurationException("Keras layer configuration is missing class name.");
    }
    String layerClassName = (String) layerConfig.get("class_name");

    if (layerClassName.equals("Dense")) {
        int outputDim = (int) layerConfig.get("units");
        return outputDim;
    } else if (layerClassName.equals("Activation")) {
        return getNumOutputsFromLayerConfig((Map<String, Object>) layerConfig.get("config"));
    } else if (layerClassName.equals("InputLayer")) {
        return (int) ((long) layerConfig.get("input_shape"));
    } else if (layerClassName.equals("Dropout")) {
        return getNumOutputsFromLayerConfig((Map<String, Object>) layerConfig.get("config"));
    } else if (layerClassName.equals("Reshape")) {
        int[] targetShape = (int[]) layerConfig.get("target_shape");
        int numElements = 1;
        for (int i = 0; i < targetShape.length; i++) {
            numElements *= targetShape[i];
        }
        return numElements;
    } else {
        throw new InvalidKerasConfigurationException("Invalid Keras layer class name: " + layerClassName);
    }
}
