public int getApproximatePendingTaskCount() {
    int count = 0;
    for (Thread thread : Thread.getAllStackTraces().keySet()) {
        if (thread.getName().startsWith("pool-")) {
            ThreadPoolExecutor executor = (ThreadPoolExecutor) thread;
            count += executor.getQueue().size();
        }
    }
    return count;
}
