public Media getClosestDpiMedia(int current, Media media) {
    List<Integer> dpiList = media.getDpiMediaMap().keySet().stream().sorted().collect(Collectors.toList());
    int closestDpi = dpiList.get(0);
    for (int dpi : dpiList) {
        if (dpi >= current) {
            closestDpi = dpi;
            break;
        } else {
            closestDpi = dpi;
        }
    }
    return media.getDpiMediaMap().getOrDefault(closestDpi, media);
}
