public boolean readNextPacket(InputStream stream) {
    try {
        // Attempt to read the next byte from the stream
        int nextByte = stream.read();

        // If we hit the end of the file, return false
        if (nextByte == -1) {
            return false;
        }

        // Otherwise, continue reading until we have a complete HMTP packet
        while (nextByte != HMTP_PACKET_END) {
            // Process the next byte in the packet
            // ...

            // Attempt to read the next byte from the stream
            nextByte = stream.read();

            // If we hit the end of the file (again), return false
            if (nextByte == -1) {
                return false;
            }
        }

        // At this point, we have a complete HMTP packet - do whatever you need to with it
        // ...

        return true;

    } catch (IOException e) {
        // Handle any error with the stream here
        return false;
    }
}
