@Override
public void setCapacity(int roomId, int maxUsers) {
    Room room = roomContext.getRoomById(roomId);
    if(room == null) {
        logger.warn("Room not found with id: {}", roomId);
        return;
    }
    int currentUsers = room.getUserList().size();
    if(currentUsers > maxUsers) {
        logger.warn("Can not set capacity. Number of users in the room ({}) is already greater than the requested maximum capacity ({})", currentUsers, maxUsers);
        return;
    }
    room.setMaxUsers(maxUsers);
    roomExtension.updateRoom(room);
}
