public static Set<String> narrowPackages(Set<String> includedPackages, InExRules rules) {
    Set<String> excludedNames = rules.getExcludedNames();
    Set<String> narrowedPackages = new HashSet<>(includedPackages);
    for (String packageName : includedPackages) {
        for (String excludedName : excludedNames) {
            if (packageName.contains(excludedName)) {
                narrowedPackages.remove(packageName);
                break;
            }
        }
    }
    return narrowedPackages;
}
