public void setPackage(String name, String specTitle, String specVersion, String specVendor, String implTitle, String implVersion, String implVendor) {
  Package pkg = getClass().getPackage();
  if (pkg != null && pkg.isSealed()) {
    throw new SecurityException("Package is sealed.");
  }
  Package definingPackage = definePackage(name, specTitle, specVersion, specVendor, implTitle, implVersion, implVendor, getClass().getClassLoader());
  if (definingPackage != null && !definingPackage.equals(pkg)) {
    throw new IllegalArgumentException("Non-matching package name");
  }
}
