public Source getLastMatchingStylesheet(List<Source> stylesheets, String media, String title) {
    Source matchingStylesheet = null;
    for (int i = stylesheets.size() - 1; i >= 0; i--) {
        Source stylesheet = stylesheets.get(i);
        if ((media == null || media.isEmpty() || stylesheet.getMedia().equalsIgnoreCase(media))
                && (title == null || title.isEmpty() || stylesheet.getTitle().equalsIgnoreCase(title))) {
            matchingStylesheet = stylesheet;
            break;
        }
    }
    return matchingStylesheet;
}
