public static Set<String> determineAliases(Map<String, Integer> environment, Set<String> freeVariables) {
        Set<String> aliases = new HashSet<>();
        for (String variable : freeVariables) {
            if (environment.containsKey(variable)) {
                for (String otherVariable : freeVariables) {
                    if (variable != otherVariable && environment.containsKey(otherVariable)
                            && environment.get(variable).equals(environment.get(otherVariable))) {
                        aliases.add(variable + " = " + otherVariable);
                    }
                }
            }
        }
        return aliases;
