public double getMinimalDistance(double x, double y, List<Point> geometry) {
    double minDistance = Double.POSITIVE_INFINITY;
    for(Point vertex : geometry) {
        double distance = Math.sqrt(Math.pow(vertex.getX() - x, 2) + Math.pow(vertex.getY() - y, 2));
        if(distance < minDistance) {
            minDistance = distance;
        }
    }
    return minDistance;
}
