public static void encryptBlock(byte[] data, int offset, byte[] dest, int destOffset) {
    byte[] keyBytes = generateRandomBytes(32); // assuming key is generated randomly
    SymmetricKey key = new SymmetricKey(keyBytes);
    KuznechikImpl kuznechik = new KuznechikImpl();
    kuznechik.setKey(key);

    byte[] encryptedBlock = kuznechik.encrypt(data, offset);
    System.arraycopy(encryptedBlock, 0, dest, destOffset, encryptedBlock.length);
}
