public Class<?> compileClass(String fileName, Map<String, Integer> lineMap, boolean ifModified, String className) {
    JavaCompiler compiler = ToolProvider.getSystemJavaCompiler();
    DiagnosticCollector<JavaFileObject> diagnostics = new DiagnosticCollector<>();

    StandardJavaFileManager fileManager = compiler.getStandardFileManager(null, null, null);
    Iterable<? extends JavaFileObject> compilationUnit = fileManager.getJavaFileObjectsFromStrings(Arrays.asList(fileName));
    JavaCompiler.CompilationTask task = compiler.getTask(null, fileManager, diagnostics, ifModified ? Arrays.asList("-Xlint:unchecked", "-verbose", "-g") : Arrays.asList("-Xlint:unchecked", "-verbose", "-g"), null, compilationUnit);
    boolean success = task.call();
    if (!success) {
        for (Diagnostic<?> diagnostic : diagnostics.getDiagnostics()) {
            System.out.format("%s [%d]%n", diagnostic.getMessage(null), diagnostic.getLineNumber());
        }
        return null;
    } else {
        try {
            URLClassLoader classLoader = URLClassLoader.newInstance(new URL[] { new File("./").toURI().toURL() });
            return classLoader.loadClass(className);
        } catch (MalformedURLException | ClassNotFoundException e) {
            return null;
        }
    }
}
