public static Table summarize(TableSliceGroup group) {
    Table result = new Table();
    for (int i = 0; i < group.numGroups(); i++) {
        TableSlice slice = group.getGroup(i);
        Table summarizedSlice = new Table();
        for (int j = 0; j < slice.numColumns(); j++) {
            Column column = slice.getColumn(j);
            if (column.getType() == ColumnType.NUMERIC) {
                double sum = column.sum();
                double average = column.average();
                double max = column.max();
                double min = column.min();
                summarizedSlice.addColumn(new NumericColumn(column.getName(), new double[]{sum, average, max, min}));
            } else if (column.getType() == ColumnType.STRING) {
                List<String> uniqueValues = column.unique();
                summarizedSlice.addColumn(new StringColumn(column.getName(), uniqueValues));
            } else if (column.getType() == ColumnType.BOOLEAN) {
                boolean[] booleans = column.asBooleanArray();
                int trueCount = 0;
                int falseCount = 0;
                for (boolean b : booleans) {
                    if (b) {
                        trueCount++;
                    } else {
                        falseCount++;
                    }
                }
                summarizedSlice.addColumn(new BooleanColumn(column.getName(), trueCount, falseCount));
            } else if (column.getType() == ColumnType.DATE) {
                Date earliestDate = column.minDate();
                Date latestDate = column.maxDate();
                summarizedSlice.addColumn(new DateColumn(column.getName(), earliestDate, latestDate));
            }
        }
        result.addRow(summarizedSlice);
    }
    return result;
}
