public static List<HttpCookie> getCookies(String cookiesString, String targetURL) {
    List<HttpCookie> cookies = new ArrayList<>();
    try {
        URI uri = new URI(targetURL);
        cookies = HttpCookie.parse(cookiesString);
        for (HttpCookie cookie : cookies) {
            cookie.setDomain(uri.getHost());
        }
    } catch (Exception e) {
        e.printStackTrace();
    }
    return cookies;
}
