public T acquire(long time, TimeUnit unit) throws TimeoutException {
    long timeout = TimeUnit.MILLISECONDS.convert(time, unit);
    long deadline = System.currentTimeMillis() + timeout;

    synchronized (this) {
        while (resourcePool.isEmpty() && timeout > 0) {
            try {
                this.wait(timeout);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw new RuntimeException(e);
            }
            timeout = deadline - System.currentTimeMillis();
        }
        if (resourcePool.isEmpty()) {
            throw new TimeoutException("Timeout occurred while acquiring a resource from the pool");
        }
        return resourcePool.remove();
    }

}
