public boolean handleIfModifiedSince(HttpExchange exchange, Date lastModified) {
    Headers requestHeaders = exchange.getRequestHeaders();
    if (requestHeaders.containsKey("If-Modified-Since")) {
        String ifModifiedSince = requestHeaders.getFirst("If-Modified-Since");
        try {
            Date ifModifiedSinceDate = new SimpleDateFormat("EEE, dd MMM yyyy HH:mm:ss zzz", Locale.ENGLISH).parse(ifModifiedSince);
            if (ifModifiedSinceDate.after(lastModified)) {
                exchange.sendResponseHeaders(HttpURLConnection.HTTP_NOT_MODIFIED, -1);
                return false;
            }
        } catch (ParseException e) {
            e.printStackTrace();
        }
    }
    return true;
}
