public String matchText(String text, boolean matchPrefix) {
    Map<String, String> tokens = new HashMap<>();
    tokens.put("hello", "Greeting");
    tokens.put("world", "Place");

    String token = tokens.get(text);
    if (token == null) {
        if (matchPrefix) {
            token = tokens.entrySet().stream()
                    .filter(entry -> text.startsWith(entry.getKey()))
                    .map(Map.Entry::getValue)
                    .findFirst().orElse(null);
        }
    }
    return token;
}
