public boolean checkMultisets(Map<Long, Integer> first, Map<Long, Integer> second) {
    if (first == null || second == null || first.size() != second.size()) {
        return false;
    }

    for (Map.Entry<Long, Integer> entry : first.entrySet()) {
        Long key = entry.getKey();
        Integer frequency = entry.getValue();

        if (!second.containsKey(key) || !second.get(key).equals(frequency)) {
            return false;
        }
    }

    return true;
}
