public class RSAEngineInit {

    public static Cipher init(boolean forEncryption, RSAPublicKeySpec param) throws NoSuchAlgorithmException, NoSuchPaddingException, InvalidKeySpecException, NoSuchProviderException, InvalidKeyException, BadPaddingException, IllegalBlockSizeException {
        // Create an instance of the Cipher for RSA
