public static void multiplyMatrix(Matrix aMat, Matrix bMat, Matrix cMat, boolean transposeA, boolean transposeB) {
    int aRows = transposeA ? aMat.getNumCols() : aMat.getNumRows();
    int aCols = transposeA ? aMat.getNumRows() : aMat.getNumCols();
    int bRows = transposeB ? bMat.getNumCols() : bMat.getNumRows();
    int bCols = transposeB ? bMat.getNumRows() : bMat.getNumCols();

    if (aCols != bRows || cMat.getNumRows() != aRows || cMat.getNumCols() != bCols) {
        throw new IllegalArgumentException("Invalid matrix dimensions for multiplication");
    }

    double[] aVals = aMat.getValues();
    double[] bVals = bMat.getValues();
    double[] cVals = cMat.getValues();

    for (int i = 0; i < aRows; i++) {
        for (int j = 0; j < bCols; j++) {
            double sum = 0;
            for (int k = 0; k < aCols; k++) {
                int aIdx = transposeA ? k * aRows + i : i * aCols + k;
                int bIdx = transposeB ? j * bRows + k : k * bCols + j;
                sum += aVals[aIdx] * bVals[bIdx];
            }
            cVals[i * bCols + j] = sum;
        }
    }
}
