@Override
protected void moveFiles(Path sourcePath, Path targetPath) throws IOException {
    if (sourcePath.toFile().isDirectory()) {
        if (!targetPath.toFile().exists()) {
            targetPath.toFile().mkdirs();
        }
        String[] fileNames = sourcePath.toFile().list();
        for (String fileName : fileNames) {
            moveFiles(new Path(sourcePath.toString() + "/" + fileName), new Path(targetPath.toString() + "/" + fileName));
        }
    } else {
        Files.move(sourcePath, targetPath, StandardCopyOption.REPLACE_EXISTING);
        log.info("Moved file: {} to {}", sourcePath, targetPath);
    }
}
