public List<Integer> getInterfaceCoreResidues(double bsaToAsaCutoff, double minAsaForSurface) {
    List<Integer> interfaceCoreResidues = new ArrayList<Integer>();
    for (int residue : interfaceResidues) {
        double bsa = getBSA(residue);
        double asa = getASA(residue);
        if (bsa > 0 && bsa/asa > bsaToAsaCutoff && asa >= minAsaForSurface) {
            interfaceCoreResidues.add(residue);
        }
    }
    return interfaceCoreResidues;
}

