public Hashtable createHashtableWithoutTracing(Subject subject) {
    Objects.requireNonNull(subject, "subject cannot be null");
    Hashtable hashtable = new Hashtable();
    for (Object principal : subject.getPrincipals()) {
        if (principal instanceof Group) {
            Group group = (Group) principal;
            Enumeration<? extends Principal> enumeration = group.members();
            while (enumeration.hasMoreElements()) {
                Principal member = enumeration.nextElement();
                if (member instanceof Serializable) {
                    hashtable.put(member.getClass().getName(), member);
                }
            }
        } else if (principal instanceof Serializable) {
            hashtable.put(principal.getClass().getName(), principal);
        }
    }
    return hashtable;
}
