public boolean nodesHaveSameNameAndNamespace(Node node1, Node node2) {
    return (getLocalName(node1).equals(getLocalName(node2)) && 
            node1.getNamespaceURI().equals(node2.getNamespaceURI()));
}

private String getLocalName(Node node) {
    String localName = node.getLocalName();
    if (localName == null) {
        localName = node.getNodeName();
        int index = localName.indexOf(':');
        if (index != -1) {
            localName = localName.substring(index + 1);
        }
    }
    return localName;
}
