public static String millisToUtcOffset(long millis) {
    int offsetMinutes = (int) TimeUnit.MILLISECONDS.toMinutes(millis);
    int hours = Math.abs(offsetMinutes / 60);
    int minutes = Math.abs(offsetMinutes - (hours * 60));
    return String.format("%+03d%02d", hours, minutes);
}
