public int getLowestEquivalentValue(int value) {
    int index = histogram.getValueBucketIndex(value);

    while (index < histogram.countsArrayLength() && histogram.getCountAtIndex(index) == 0) {
        index++;
    }

    if (index >= histogram.countsArrayLength()) {
        return histogram.getMaxValue();
    }

    return histogram.valueFromIndex(index);
}
