public String acquireLock(ZooKeeper zookeeper, String lockNode) throws KeeperException, InterruptedException {
    String lockPath = zookeeper.create(lockNode + "/lock_", null, ZooDefs.Ids.OPEN_ACL_UNSAFE, CreateMode.EPHEMERAL_SEQUENTIAL);
    while (true) {
        List<String> nodes = zookeeper.getChildren(lockNode, false);
        String currentNode = lockPath.substring(lockNode.length() + 1);
        Collections.sort(nodes);
        int currentNodeIndex = nodes.indexOf(currentNode);
        if (currentNodeIndex == 0) {
            return currentNode;
        } else {
            String previousNode = nodes.get(currentNodeIndex - 1);
            final CountDownLatch latch = new CountDownLatch(1);
            Stat stat = zookeeper.exists(lockNode + "/" + previousNode, new Watcher() {
                public void process(WatchedEvent watchedEvent) {
                    if (watchedEvent.getType() == Event.EventType.NodeDeleted) {
                        latch.countDown();
                    }
                }
            });
            if (stat != null) {
                latch.await();
            }
        }
    }
}
