public Query createDisMaxJuncQueryRule(String[] searchTerms, String[] ontologyTerms) {
    Query disMaxQuery = new DisjunctionMaxQuery(0.0f);
    disMaxQuery.setMinimumNumberShouldMatch(1);

    // add search terms as disjuncts
    for (String term : searchTerms) {
        disMaxQuery.add(new TermQuery(new Term("content", term)));
    }

    // add ontology terms as disjuncts with higher boost
    for (String term : ontologyTerms) {
        disMaxQuery.add(new TermQuery(new Term("ontology", term)), 2.0f);
    }

    // create the disMaxJunc query rule by wrapping it with a BooleanQuery
    BooleanQuery disMaxJuncQuery = new BooleanQuery.Builder()
            .add(disMaxQuery, BooleanClause.Occur.SHOULD)
            .build();

    return disMaxJuncQuery;
}
