    public static Map<String, List<String>> groupASGByCluster(List<String> asgNames) {
        Map<String, List<String>> clusterASGMap = new HashMap<String, List<String>>();

        for (String asgName : asgNames) {
            String clusterName = extractClusterName(asgName);

            if (clusterASGMap.get(clusterName) == null) {
                clusterASGMap.put(clusterName, new ArrayList<String>());
