public void unwrapRefinementTracking(Object obj) {
    if (obj instanceof RefinementTrackingFlowScopes) {
        RefinementTrackingFlowScopes flowScopes = (RefinementTrackingFlowScopes) obj;
        for (Object value : flowScopes.getValues()) {
            unwrapRefinementTracking(value);
        }
    } else if (obj instanceof List) {
        List<?> list = (List<?>) obj;
        for (Object value : list) {
            unwrapRefinementTracking(value);
        }
    } else if (obj instanceof Map) {
        Map<?, ?> map = (Map<?, ?>) obj;
        for (Object key : map.keySet()) {
            unwrapRefinementTracking(map.get(key));
        }
    }
}
