public class QueryStringBuilder {
    private StringBuilder queryString = new StringBuilder("");

    public QueryStringBuilder addParamsToQueryString(Map<String, Object> values) {
        for (Map.Entry<String, Object> entry : values.entrySet()) {
            String key = entry.getKey();
            Object value = entry.getValue();

            if (value instanceof Iterable) {
                for (Object val : (Iterable) value) {
                    addParamToQueryString(key, val);
                } 
            } else if (value instanceof Object[]) {
                for (Object val : (Object[]) value) {
                    addParamToQueryString(key, val);
                }
            } else {
                addParamToQueryString(key, value);
            }
        }
        return this;
    }

    private void addParamToQueryString(String key, Object value) {
        try {
            String encodedKey = URLEncoder.encode(key, "UTF-8");
            String encodedValue = URLEncoder.encode(value.toString(), "UTF-8");
            if (queryString.length() > 0) {
                queryString.append("&");
            }
            queryString.append(encodedKey).append("=").append(encodedValue);
        } catch (UnsupportedEncodingException e) {
            // do something with the exception or ignore
        }
    }

    @Override
    public String toString() {
        return queryString.toString();
    }
}
