public static boolean matchBackward(String str1, String str2) {
    if(str1 == null || str2 == null) {
        return false;
    }

    int str1Length = str1.length();
    int str2Length = str2.length();

    if(str1Length != str2Length) {
        return false;
    }

    for (int i = str1Length - 1, j = 0; i >= 0; i--, j++) {
        if(str1.charAt(i) != str2.charAt(j)){
            return false;
        }
    }
    return true;
}
