public void printFactorAsCSV() {
    // implementation code here
    // assuming that the factor is stored in an object called 'myFactor'
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < myFactor.getCardinality(); i++) {
        for (int j = 0; j < myFactor.getDimension(); j++) {
            sb.append(myFactor.getValue(i, j));
            if (j < myFactor.getDimension() - 1) {
                sb.append(",");
            }
        }
        sb.append("\n");
    }
    System.out.println(sb.toString());
}
