public void inlineExternalCSS(Document doc, String basePath) throws IOException, URISyntaxException {
    NodeList linkNodes = doc.getElementsByTagName("link");
    for (int i = 0; i < linkNodes.getLength(); i++) {
        Element link = (Element) linkNodes.item(i);
        if (link.getAttribute("rel").equals("stylesheet") && link.hasAttribute("href")) {
            String href = link.getAttribute("href");
            if (href.startsWith("http")) {
                continue; // skip external stylesheets
            }
            URI uri = new URI(href);
            String path = Paths.get(basePath).resolve(uri.getPath()).toString();
            File cssFile = new File(path);
            if (!cssFile.isFile()) {
                continue; // skip missing CSS files
            }
            String cssContent = new String(Files.readAllBytes(cssFile.toPath()));
            String inlinedCSS = "<style>" + cssContent + "</style>";
            Element style = doc.createElement("style");
            style.appendChild(doc.createTextNode(inlinedCSS));
            link.getParentNode().replaceChild(style, link);
        }
    }
}
