                  console.println("Checking fix " + fixId);
                  Path fixContentPath = fixPath.resolve("ifix.info");
                  if (Files.exists(fixContentPath)) {
                     BufferedReader reader = Files.newBufferedReader(fixContentPath, StandardCharsets.UTF_8);
                     String line = null;
                     while ((line = reader.readLine()) != null) {
                        String[] tokens = line.split(",");
                        String aparParams = tokens[0];
                        String fixActions = tokens[1];
                        if (fixActions.toUpperCase().contains("APPLY")) {
                           aparIds.add(aparParams);
                        }
                     }
                     reader.close();
                  } else {
                     console.println("Error: ifix.info file not found inside " + fixId);
                  }
               }
            }
            fixesStream.close();
         } else {
            console.println("No ifixes directory found in " + wlpInstallationPath);
         }
      } else {
         console.println(wlpInstallationDirectory + " is not a directory");
      }
   } catch (IOException e) {
      console.println("Error checking ifixes: " + e.getMessage());
   }

   return aparIds;
}
