public static ChunkType decodeChunkType(byte type) {
    switch (type) {
        case 0x00:
            return ChunkType.RESERVED_UNSKIPPABLE;
        case 0x01:
            return ChunkType.RESERVED_SKIPPABLE;
        case 0x02:
            return ChunkType.CHECKSUM;
        case 0x03:
            return ChunkType.FLEX;
        case 0x04:
            return ChunkType.FILTER;
        case 0x05:
            return ChunkType.CONTINUATION;
        default:
            return ChunkType.RESERVED_UNSKIPPABLE;
    }
}
