      case ENUM:
        messager.printMessage(ERROR, "FreeBuilder does not support enum types", type);
        throw new CannotGenerateCodeException();
      case INTERFACE:

        break;
      default:
        throw new AssertionError("Unexpected element kind " + type.getKind());
    }
