public static String concatenateStringsWithCharacter(List<String> parts, char character) {
    StringBuilder sb = new StringBuilder();
    for(int i = 0; i < parts.size(); i++) {
        sb.append(parts.get(i));
        if(i != parts.size()-1) {
            sb.append(character);
        }
    }
    return sb.toString();
}
