import java.awt.geom.AffineTransform;
import java.awt.image.AffineTransformOp;
import java.awt.image.BufferedImage;

public static BufferedImage rotateImage(BufferedImage image, double angle) {

    // Create an AffineTransform instance and set the rotation angle
    AffineTransform af = new AffineTransform();
    af.rotate(Math.toRadians(angle), image.getWidth() / 2, image.getHeight() / 2);

    // Apply the AffineTransformOp to the original image
    AffineTransformOp operation = new AffineTransformOp(af, AffineTransformOp.TYPE_BILINEAR);
    BufferedImage rotatedImage = new BufferedImage(image.getWidth(), image.getHeight(), image.getType());
    operation.filter(image, rotatedImage);

    // Get the bounding rectangle of the rotated image
    int minX = Integer.MAX_VALUE, minY = Integer.MAX_VALUE, maxX = 0, maxY = 0;
    for (int x = 0; x < rotatedImage.getWidth(); x++) {
        for (int y = 0; y < rotatedImage.getHeight(); y++) {
            if (rotatedImage.getRGB(x, y) != 0) {
                minX = Math.min(minX, x);
                minY = Math.min(minY, y);
                maxX = Math.max(maxX, x);
                maxY = Math.max(maxY, y);
            }
        }
    }

    // Crop the rotated image to the bounding rectangle
    return rotatedImage.getSubimage(minX, minY, maxX - minX + 1, maxY - minY + 1);
}
