public static <T> String serializeToQueryString(T value) throws UnsupportedEncodingException {
    StringBuilder serializedValue = new StringBuilder();
    BeanInfo beanInfo = Introspector.getBeanInfo(value.getClass());
    List<PropertyDescriptor> propertyDescriptors = Arrays.asList(beanInfo.getPropertyDescriptors());

    for (PropertyDescriptor propertyDescriptor : propertyDescriptors) {
        if (propertyDescriptor.getReadMethod() != null && !"class".equals(propertyDescriptor.getName())) {
            String propertyValue = propertyDescriptor.getReadMethod().invoke(value).toString();
            String escapedPropertyValue = URLEncoder.encode(propertyValue, "UTF-8").replace("+", "%20");
            if (serializedValue.length() > 0) {
                serializedValue.append("&");
            }
            serializedValue.append(propertyDescriptor.getName()).append("=").append(escapedPropertyValue);
        }
    }

    return serializedValue.toString();
}
