public <K, V> Collection<V> getDecoratedCollection(Multimap<K, V> multimap, K key) {
    return Multimaps.transformValues(multimap, input -> {
        return new ForwardingCollection<V>() {
            @Override
            protected Collection<V> delegate() {
                return multimap.get(key);
            }

            @Override
            public boolean add(V element) {
                return multimap.put(key, element);
            }

            @Override
            public boolean addAll(Collection<? extends V> collection) {
                return multimap.putAll(key, collection);
            }

            @Override
            public boolean remove(Object object) {
                return multimap.remove(key, object);
            }

            @Override
            public boolean removeAll(Collection<?> collection) {
                return multimap.keySet().removeAll(collection);
            }

            @Override
            public void clear() {
                multimap.removeAll(key);
            }
        };
    }).get(key);
}
