public NotificationDto convertToNotificationDto(Notification notification) throws WebApplicationException {
    if(notification == null) {
        throw new WebApplicationException("Notification entity cannot be null.");
    }

    NotificationDto notificationDto = new NotificationDto();
    notificationDto.setId(notification.getId());
    notificationDto.setTitle(notification.getTitle());
    notificationDto.setMessage(notification.getMessage());
    notificationDto.setTimestamp(notification.getTimestamp());

    return notificationDto;
}
