import org.json.*;

public static String extractFieldsFromJson(String timestamp, String jsonRow, String joinFields) {
    JSONObject jsonObj = new JSONObject(jsonRow);
    StringBuilder result = new StringBuilder();
    try {
        // Extract the value of the timestamp field
        result.append(jsonObj.getString(timestamp));

        // Extract the values of the fields specified in joinFields
        String[] fieldsToJoin = joinFields.split(",");
        for (String field : fieldsToJoin) {
            result.append(",");
            result.append(jsonObj.get(field).toString());
        }
    } catch (JSONException e) {
        // Handle the JSON exception
    }
    return result.toString();
}
