public void updateBlockStack(Node node, Stack<Block> blockStack) {
    // If the node is a block, push it onto the block stack
    if (node instanceof Block) {
        blockStack.push((Block) node);
    } 
    // If the node is a reference, add it to the reference collection of the top block
    else if (node instanceof Reference) {
        Block topBlock = blockStack.peek();
        topBlock.addReference((Reference) node);
    }
}
