public static double calculateFbetaValue(double beta, int tp, int fp, int fn) {
    double precision = tp / (double) (tp + fp);
    double recall = tp / (double) (tp + fn);
    return (1 + beta * beta) * (precision * recall) / (beta * beta * precision + recall);
}
