public Map<String, EmbeddableType> getEmbeddables(Class<?> clazz) {
    Map<String, EmbeddableType> embeddablesMap = new HashMap<>();
    if(clazz != null) {
        Field[] fields = clazz.getDeclaredFields();
        for(Field field : fields) {
            Embeddable embeddableAnnotation = field.getAnnotation(Embeddable.class);
            if(embeddableAnnotation != null) {
                embeddablesMap.put(field.getName(), (EmbeddableType) field.getType());
            }
        }
    }
    return embeddablesMap;
}
