public List<Rule> loadRulesFromClassLoader() throws Exception {
    List<Rule> loadedRules = new ArrayList<>();
    ClassLoader classLoader = getClass().getClassLoader();
    Enumeration<URL> ruleFiles = classLoader.getResources("rules/");

    while (ruleFiles.hasMoreElements()) {
        URL ruleFile = ruleFiles.nextElement();
        File file = new File(ruleFile.getFile());
        Rule rule = new Rule(file);
        loadedRules.add(rule);
    }

    return loadedRules;
}
