import java.util.HashMap;
import java.util.Map;

public class PercentTableGenerator {

    public static Map<String, Map<String, Double>> generatePercentTable(Map<String, String[]> sourceTable, String[] columnsToCrossTabulate) {
        //calculate counts for each combination of values from columnsToCrossTabulate
        Map<String, Map<String, Integer>> countsTable = new HashMap<>();
        for(String rowKey : sourceTable.keySet()) {
            String[] row = sourceTable.get(rowKey);
            String countKey = "";
            for(String column : columnsToCrossTabulate) {
                countKey += row[getColumnIndex(sourceTable, column)] + ",";
            }
            countKey = countKey.substring(0, countKey.length() - 1);

            if(!countsTable.containsKey(countKey)) {
                countsTable.put(countKey, new HashMap<String, Integer>());
            }
            Map<String, Integer> countRow = countsTable.get(countKey);

            for(String value : row) {
                if(!columnsToCrossTabulate(sourceTable, value)) {
                    if(!countRow.containsKey(value)) {
                        countRow.put(value, 0);
                    }
                    countRow.put(value, countRow.get(value) + 1);
                }
            }
        }

        //calculate percent table
        Map<String, Map<String, Double>> percentTable = new HashMap<>();
        for(String countKey : countsTable.keySet()) {
            Map<String, Double> percentRow = new HashMap<>();
            Map<String, Integer> countRow = countsTable.get(countKey);
            int totalCount = 0;
            for(int count : countRow.values()) {
                totalCount += count;
            }
            for(String value : countRow.keySet()) {
                percentRow.put(value, countRow.get(value) * 100.0 / totalCount);
            }
            percentTable.put(countKey, percentRow);
        }
        return percentTable;
    }

    private static boolean columnsToCrossTabulate(Map<String, String[]> sourceTable, String value) {
        for(String[] row : sourceTable.values()) {
            for(int i = 0; i < row.length; i++) {
                if(row[i].equals(value) && getColumnHeader(sourceTable, i).equals(value)) {
                    return true;
                }
            }
        }
        return false;
    }

    private static int getColumnIndex(Map<String, String[]> sourceTable, String columnHeader) {
        return Integer.parseInt(getColumnHeaderIndexMap(sourceTable).get(columnHeader));
    }

    private static String getColumnHeader(Map<String, String[]> sourceTable, int index) {
        return getColumnHeaderIndexMap(sourceTable).keySet().toArray(new String[0])[index];
    }

    private static Map<String, String> getColumnHeaderIndexMap(Map<String, String[]> sourceTable) {
        String[] headers = sourceTable.get("header");
        Map<String, String> map = new HashMap<>();
        for(int i = 0; i < headers.length; i++) {
            map.put(headers[i], Integer.toString(i));
        }
        return map;
    }
}
