@Override
public LocationInfo getLocationInfo(String locationId) throws InstagramException {
    try {
        String apiUrl = String.format(EndpointLocations.GET_LOCATION_INFORMATION, locationId);

        InstagramRequest request = new InstagramRequest(this.accessToken);
        JsonObject response = (JsonObject) request.makeRequest(apiUrl);

        if (response.has("meta") && response.get("meta").getAsJsonObject().get("code").getAsInt() == 200) {
            return new LocationInfo().createFromJson(response.get("data").getAsJsonObject());
        } else {
            throw new InstagramException("Error getting location information. " + response.toString());
        }
    } catch (IOException io) {
        throw new InstagramException("Error getting location information.", io);
    }
}
