public static BufferedImage recolorImage(BufferedImage inputImage, float shiftValue) {
    // Convert the input image to 8-bit color mapped image
    BufferedImage indexedImage = new BufferedImage(inputImage.getWidth(), inputImage.getHeight(), BufferedImage.TYPE_BYTE_INDEXED);
    Graphics graphics = indexedImage.getGraphics();
    graphics.drawImage(inputImage, 0, 0, null);
    graphics.dispose();

    // Convert the indexed image to HSV color space
    ColorConvertOp op = new ColorConvertOp(ColorSpace.getInstance(ColorSpace.CS_GRAY), ColorSpace.getInstance(ColorSpace.CS_HSV), null);
    BufferedImage hsvImage = op.filter(indexedImage, null);

    // Shift the hue of the image by the specified value
    for (int x = 0; x < hsvImage.getWidth(); x++) {
        for (int y = 0; y < hsvImage.getHeight(); y++) {
            int rgb = hsvImage.getRGB(x, y);
            float[] hsv = new float[3];
            Color.RGBtoHSB((rgb >> 16) & 0xFF, (rgb >> 8) & 0xFF, (rgb >> 0) & 0xFF, hsv);
            hsv[0] += shiftValue;
            if (hsv[0] > 1) {
                hsv[0] -= 1;
            }
            hsvImage.setRGB(x, y, Color.HSBtoRGB(hsv[0], hsv[1], hsv[2]));
        }
    }

    // Convert the HSV image back to 8-bit color mapped image
    op = new ColorConvertOp(ColorSpace.getInstance(ColorSpace.CS_HSV), ColorSpace.getInstance(ColorSpace.CS_GRAY), null);
    BufferedImage outputImage = op.filter(hsvImage, null);

    return outputImage;
}
