public String increaseDewey(int times) {
    String deweyNumber = "123.45"; // replace with desired initial dewey number
    int lastDigit = deweyNumber.charAt(deweyNumber.length() - 1) - '0'; // get last digit and convert to int
    int newLastDigit = (lastDigit + times) % 10; // increase last digit by given amount, wrapping around from 9 to 0
    String newDeweyNumber = deweyNumber.substring(0, deweyNumber.length() - 1) + newLastDigit; // replace the last digit with the new one
    return newDeweyNumber;
}
