public static void copyAndCast(Class<?> toType, Object to, Object... from) {
    if (from.length == 0) {
        return;
    }
    if (from[0].getClass().isArray()) {
        for (int i = 0; i < Array.getLength(from[0]); i++) {
            copyAndCast(toType, Array.get(to, i), Arrays.stream(from).map(a -> Array.get(a, i)).toArray());
        }
    } else {
        for (int i = 0; i < from.length; i++) {
            Array.set(to, i, toType.cast(from[i]));
        }
    }
}
