import com.google.gson.GsonBuilder;
import com.google.gson.TypeAdapterFactory;

public class GeometryTypeAdapterFactory {

    public static TypeAdapterFactory create() {
        // Creating a new instance of Geometry type adapter factory
        TypeAdapterFactory geometryTypeAdapterFactory = new TypeAdapterFactory() {
            @Override
            public <T> TypeAdapter<T> create(Gson gson, TypeToken<T> type) {
                if (Geometry.class.isAssignableFrom(type.getRawType())) {
                    return (TypeAdapter<T>) new GeometryTypeAdapter();
                }
                return null;
            }
        };

        // Passing the Geometry type adapter factory to the Gson Builder
        GsonBuilder gsonBuilder = new GsonBuilder().registerTypeAdapterFactory(geometryTypeAdapterFactory);

        // Returning a new GSON TypeAdapterFactory
        return gsonBuilder.create();
    }
}
