public void swapShortArrays(short[] shortArray1, short[] shortArray2, int index) {
    if (index >= 0 && index < shortArray1.length && index < shortArray2.length) {
        // swap the elements
        short temp = shortArray1[index];
        shortArray1[index] = shortArray2[index];
        shortArray2[index] = temp;
    } else {
        throw new IllegalArgumentException("Index is out of bounds");
    }
}
