public Object spinUntilFulfilledOrCancelled(Predicate<Object> pred, Object s, Object e, boolean mode, long nanos) throws InterruptedException {
    final long endNanoTime = System.nanoTime() + nanos;
    boolean isTimed = nanos > 0;
    Thread currentThread = Thread.currentThread();
    int spins = -1;
    Object matchedItem = null;

    while (true) {
        if (currentThread.isInterrupted())
            throw new InterruptedException();
        if (pred.test(s)) {
            matchedItem = s;
            break;
        }
        if (mode == false && nanos <= 0) {
            matchedItem = s;
            break;
        }
        if (isTimed) {
            nanos = endNanoTime - System.nanoTime();
            if (nanos <= 0) {
                matchedItem = s;
                break;
            }
        }
        if (spins < 0)
            spins = 1 << 10; // 1024 spins maximum

        if (mode == true || spins > 0) {
            for (int i = 0; i < 10000; i++) {
                if (pred.test(s)) {
                    matchedItem = s;
                    break;
                }
            }
            if (matchedItem != null)
                break;
            if (spins > 0) {
                spins--;
                continue;
            }
        }

        LockSupport.parkNanos(s, nanos);
    }

    if (currentThread.isInterrupted() && matchedItem != null)
        matchedItem = s;

    return matchedItem;
}
