import org.json.JSONArray;
import org.json.JSONException;
import org.json.JSONObject;

public String formatTSMetaList(List<TSMeta> metas) throws JSONException {

  // Create a JSON array to store the TSMeta objects
  JSONArray jsonArray = new JSONArray();

  // Iterate through the list of TSMeta objects and add them to the JSON array
  for (TSMeta meta : metas) {
    JSONObject jsonMeta = new JSONObject();
    jsonMeta.put("id", meta.getId());
    jsonMeta.put("name", meta.getName());
    jsonMeta.put("description", meta.getDescription());
    jsonMeta.put("timestamp", meta.getTimestamp());
    jsonArray.put(jsonMeta);
  }

  // Return the JSON array as a string
  return jsonArray.toString();
}
