public static boolean isValidMetadataIdentifier(String str) {
    // Check if the string is empty or null
    if (str == null || str.isEmpty()) {
        return false;
    }

    // Check if the string starts with a letter or underscore
    char firstChar = str.charAt(0);
    if (!Character.isLetter(firstChar) && firstChar != '_') {
        return false;
    }

    // Check if the remaining characters are letters, digits, or underscores
    for (int i = 1; i < str.length(); i++) {
        char c = str.charAt(i);
        if (!Character.isLetterOrDigit(c) && c != '_') {
            return false;
        }
    }

    // The string is a valid metadata identifier
    return true;
}
