public static void appendStackTrace(StringBuffer buf, Throwable thrown) {
    if (thrown != null) {
        StackTraceElement[] traceElements = thrown.getStackTrace();
        int index = traceElements.length - 1;
        for (; index >= 0; index--) {
            if (traceElements[index].toString().contains("com.example")) {
                break;
            }
        }

        buf.append("\nException Details: ");
        if (index == -1) {
            buf.append(thrown.toString());
        } else {
            buf.append(thrown.toString()).append("\n");
            for (int i = 0; i <= index; i++) {
                buf.append("\tat ").append(traceElements[i].toString()).append("\n");
            }
            buf.append("... ").append(traceElements.length - 1 - index).append(" more");
        }
    } else {
        buf.append("Throwable is null");
    }
}
