public Iterator<String> getAllUnCombined(final Object name) {
    final List<Object> values = this.headers.get(name);
    if (values == null) {
        return Collections.emptyIterator();
    } else {
        final Iterator<Object> valuesIter = values.iterator();
        return new Iterator<String>() {
            @Override
            public boolean hasNext() {
                return valuesIter.hasNext();
            }

            @Override
            public String next() {
                Object value = valuesIter.next();
                return value == null ? null : value.toString();
            }

            @Override
            public void remove() {
                valuesIter.remove();
            }
        };
    }
}
