public static <T> int countParallel(final Iterable<? extends T> iterable, final Predicate<? super T> predicate, final int batchSize) {
    final List<List<? extends T>> batches = StreamUtils
      .partition(toStream(iterable), batchSize)
      .map(ReactiveStreamsUtil::toList)
      .collect(toList());

    try {
        return ForkJoinPool
          .commonPool()
          .submit(() -> batches
          .parallelStream()
          .mapToInt(batch -> count(batch, predicate))
          .sum())
          .get();
    } catch (ExecutionException e) {
        if (e.getCause() instanceof RuntimeException) {
