public Dictionary<String, Object> getSubsetProperties(ServiceReference<?> serviceReference, String prefix) {

    Dictionary<String, Object> properties = serviceReference.getProperties();
    if (properties == null) {
        return null;
    }

    Dictionary<String, Object> subsetProperties = new Hashtable<String, Object>();

    Enumeration<String> keys = properties.keys();
    while (keys.hasMoreElements()) {
        String key = keys.nextElement();
        if (key.startsWith(prefix)) {
            String newKey = key.substring(prefix.length());
            subsetProperties.put(newKey, properties.get(key));
        }
    }

    return subsetProperties;
}
