public static String byteCountToDisplaySize(long bytes) {
    String displaySize;
    if (bytes / ONE_EB > 0) {
        displaySize = String.format("%.1f EB", (float) bytes / ONE_EB);
    } else if (bytes / ONE_PB > 0) {
        displaySize = String.format("%.1f PB", (float) bytes / ONE_PB);
    } else if (bytes / ONE_TB > 0) {
        displaySize = String.format("%.1f TB", (float) bytes / ONE_TB);
    } else if (bytes / ONE_GB > 0) {
        displaySize = String.format("%.1f GB", (float) bytes / ONE_GB);
    } else if (bytes / ONE_MB > 0) {
        displaySize = String.format("%.1f MB", (float) bytes / ONE_MB);
    } else if (bytes / ONE_KB > 0) {
        displaySize = String.format("%.1f KB", (float) bytes / ONE_KB);
    } else {
        displaySize = String.format("%d bytes", bytes);
    }
    return displaySize;
}

public static final long ONE_KB = 1024;
public static final long ONE_MB = ONE_KB * ONE_KB;
public static final long ONE_GB = ONE_KB * ONE_MB;
public static final long ONE_TB = ONE_KB * ONE_GB;
public static final long ONE_PB = ONE_KB * ONE_TB;
public static final long ONE_EB = ONE_KB * ONE_PB;    
