import com.sun.source.tree.*;
import com.sun.tools.javac.tree.JCTree.*;
import lombok.DeleteLombokAnnotations;
import lombok.core.AnnotationValues;
import lombok.javac.JavacAnnotationProcessor;
import lombok.javac.JavacNode;
import javax.annotation.processing.SupportedAnnotationTypes;
import javax.annotation.processing.SupportedSourceVersion;
import javax.lang.model.SourceVersion;
import javax.lang.model.element.AnnotationValue;
import javax.lang.model.element.Element;

@SupportedAnnotationTypes("lombok.*")
@SupportedSourceVersion(SourceVersion.RELEASE_8)
public class RemoveJavacAnnotation {

    public static void removeAnnotations(Element element, JavacNode annotationNode) {
        if (DeleteLombokAnnotations.getEnabled()) {
            if (element instanceof JCAnnotation) {
                if (isLombokAnnotation((JCAnnotation) element)) {
                    annotationNode.up().remove(annotationNode);
                    removeImports(annotationNode.getPackageDeclaration(), ((JCAnnotation)element).attribute.values);
                }
            } else {
                for (Element e : element.getEnclosedElements()) {
                    if (e instanceof JCAnnotation) {
                        if (isLombokAnnotation((JCAnnotation)e)) {
                            annotationNode.up().remove(annotationNode);
                            removeImports(annotationNode.getPackageDeclaration(), ((JCAnnotation)e).attribute.values);
                        }
                    } else {
                        removeAnnotations(e, annotationNode);
                    }
                }
            }
        }
    }

    private static boolean isLombokAnnotation(JCAnnotation annotation) {
        try {
            Class<? extends java.lang.annotation.Annotation> annType = annotation.annotationType().getClassLoader().loadClass(annotation.annotationType().toString());
            return annType.isAnnotationPresent(lombok.experimental.NonFinal.class);
        } catch (Throwable e) {
            return false;
        }
    }

    private static void removeImports(JCPackageDeclaration packageDeclaration, List<JCExpression> arguments) {
        if(packageDeclaration == null || arguments == null) {
            return;
        }
        for(JCExpression argument : arguments) {
            if(argument instanceof JCFieldAccess) {
                JCFieldAccess fa = (JCFieldAccess)argument;
                if("class".equals(fa.name.toString()) && fa.selected instanceof JCIdent) {
                    String typeName = ((JCIdent)fa.selected).name.toString();
                    if(packageDeclaration.getTypeDecls().stream()
                            .filter(e -> e instanceof JCImport)
                            .map(e -> (JCImport)e)
                            .anyMatch(imp -> imp.qualid instanceof JCFieldAccess
                                    && typeName.equals(((JCFieldAccess)imp.qualid).name.toString())
                                    && (imp.qualid instanceof JCIdent
                                            || ((JCIdent)((JCFieldAccess)imp.qualid).selected).name.toString().equals(packageDeclaration.pid.toString())
                                    )
                            )
                    ) {
                        removeImport(typeName, packageDeclaration);
                    }
                }
            }
        }
    }

    private static void removeImport(String typeName, JCPackageDeclaration packageDeclaration) {
        for(JCStatement stmt : packageDeclaration.getImports()) {
            if(stmt instanceof JCImport) {
                JCImport imp = (JCImport)stmt;
                if(imp.qualid instanceof JCFieldAccess
                        && typeName.equals(((JCFieldAccess)imp.qualid).name.toString())
                        && (imp.qualid instanceof JCIdent
                                || ((JCIdent)((JCFieldAccess)imp.qualid).selected).name.toString().equals(packageDeclaration.pid.toString())
                        )
                ) {
                    packageDeclaration.getImports().remove(stmt);
                    break;
                }
            }
        }
    }
}
