public class TypeSafeStack<T> extends Stack<T> {}

public class Namespace {
    private final Map<Class<?>, Stack<?>> m_namespaces = new Hashtable<>();

    public <T> void push(Class<T> klass, T item) {
        Stack<T> stack = getOrCreateStack(klass);
        stack.push(item);
    }

    public <T> T pop(Class<T> klass) {
        Stack<T> stack = getOrCreateStack(klass);
        return stack.pop();
    }

    public <T> boolean isEmpty(Class<T> klass) {
        Stack<T> stack = getOrCreateStack(klass);
        return stack.isEmpty();
    }

    @SuppressWarnings("unchecked")
    private <T> Stack<T> getOrCreateStack(Class<T> klass) {
        Stack<?> stack = m_namespaces.get(klass);
        if (stack == null) {
            stack = new TypeSafeStack<>();
            m_namespaces.put(klass, stack);
        }
        return (Stack<T>) stack;
    }
}
