public static byte[] decodeSingleNullable(byte[] data, int prefixPadding, int suffixPadding) {
    int length = data.length - prefixPadding - suffixPadding;
    byte[] result = new byte[length];

    for (int i = prefixPadding, j = 0; i < data.length - suffixPadding; i++, j++) {
        result[j] = (byte) (data[i] ^ DECODE_MASK[j % DECODE_MASK.length]);
    }

    return result;
