public Sketch createNewSketch(int newK) {
    int currentK = this.getK();
    if (newK >= currentK) {
        throw new IllegalArgumentException("New value of K must be smaller than current value of K.");
    }
    int shift = (int) Math.floor(Math.log(currentK / newK) / Math.log(2));
    int newM = this.getM() >> shift;
    int newN = this.getN() >> shift;
    Sketch newSketch = new Sketch(newM, newN, newK);
    for (int i = 0; i < this.getHashFunctions().length; i++) {
        newSketch.addHashFunction(this.getHashFunctions()[i]);
    }
    for (int i = 0; i < this.getCounters().length; i++) {
        int oldIndex = i << shift;
        int newIndex = (i % newN) << shift | (i / newN);
        newSketch.getCounters()[newIndex] = this.getCounters()[oldIndex];
    }
    return newSketch;
}
