public static Inet6Address mapIPv4ToIPv6(Inet4Address inet4Address) throws UnknownHostException {
    byte[] ipv4Bytes = inet4Address.getAddress();
    byte[] ipv6Bytes = new byte[16];

    // IPv6 prefix and reserved bytes
    ipv6Bytes[0] = (byte) 0x00;
    ipv6Bytes[1] = (byte) 0x00;
    ipv6Bytes[2] = (byte) 0x00;
    ipv6Bytes[3] = (byte) 0x00;
    ipv6Bytes[4] = (byte) 0x00;
    ipv6Bytes[5] = (byte) 0x00;
    ipv6Bytes[6] = (byte) 0x00;
    ipv6Bytes[7] = (byte) 0x00;
    ipv6Bytes[8] = (byte) 0x00;
    ipv6Bytes[9] = (byte) 0x00;
    ipv6Bytes[10] = (byte) 0xFF;
    ipv6Bytes[11] = (byte) 0xFF;

    // IPv4 address bytes
    ipv6Bytes[12] = ipv4Bytes[0];
    ipv6Bytes[13] = ipv4Bytes[1];
    ipv6Bytes[14] = ipv4Bytes[2];
    ipv6Bytes[15] = ipv4Bytes[3];

    return (Inet6Address) Inet6Address.getByAddress(ipv6Bytes);
}
