public static Set<Annotation> getAllAnnotations(Class<?> m) {
    Set<Annotation> annotations = new HashSet<>();
    annotations.addAll(Arrays.asList(m.getDeclaredAnnotations()));
    for (Annotation annotation : m.getDeclaredAnnotations()) {
        if (annotation.annotationType().isAnnotationPresent(Stereotype.class)) {
            annotations.addAll(getAllAnnotations(annotation.annotationType()));
        }
    }
    if (m.getSuperclass() != null) {
        annotations.addAll(getAllAnnotations(m.getSuperclass()));
    }
    for (Class<?> interfaceClass : m.getInterfaces()) {
        annotations.addAll(getAllAnnotations(interfaceClass));
    }
    return annotations;
}
