public static String getUniqueClassName(String className, List<String> existingClassNames) {
    int count = 0;
    for (String name : existingClassNames) {
        if (name.equals(className)) {
            count++;
        }
    }
    if (count > 0) {
        className += "__" + count;
    }
    return className;
}
