public void printJobSummaryInformation(List<JobExecutionInfo> jobExecutionInfos, int resultsLimit) {
    int totalCount = jobExecutionInfos.size();
    int successCount = 0;
    int failureCount = 0;
    int runningCount = 0;

    // Calculate number of successful, failed and running jobs
    for (JobExecutionInfo jobExecutionInfo : jobExecutionInfos) {
        if (BatchStatus.COMPLETED.equals(jobExecutionInfo.getStatus())) {
            successCount++;
        } else if (BatchStatus.FAILED.equals(jobExecutionInfo.getStatus())) {
            failureCount++;
        } else if (BatchStatus.STARTED.equals(jobExecutionInfo.getStatus()) ||
                   BatchStatus.STARTING.equals(jobExecutionInfo.getStatus())) {
            runningCount++;
        }
    }

    // Display summary information
    System.out.println("Total Jobs: " + totalCount);
    System.out.println("Succeeded Jobs: " + successCount);
    System.out.println("Failed Jobs: " + failureCount);
    System.out.println("Running Jobs: " + runningCount);

    if (totalCount > resultsLimit) {
        System.out.println("Only " + resultsLimit + " out of " + totalCount + " jobs are displayed.");
    }
}
