import com.google.cloud.storage.*;
import java.io.IOException;

public class GCSWriter {
  public static WritableByteChannel createObjectAndOpenForWriting(String path) throws IOException {
    // Instantiate a storage client object
    Storage storage = StorageOptions.getDefaultInstance().getService();

    // Parse the object path
    BlobId blobId = BlobId.of(path);

    // Create the object with an empty content
    BlobInfo blobInfo = BlobInfo.newBuilder(blobId).build();

    // Try to delete the object if it already exists
    if (storage.delete(blobId)) {
      System.out.println("Object already exists and it has been deleted.");
    }

    // Create the object and return a channel for writing to it
    return storage.writer(blobInfo);
  }
}
