public Object buildObjectFromCommandLine(Class requiredType, String commandline) throws Exception {
    Object instance = requiredType.newInstance();
    String[] args = commandline.split(" ");
    for(String arg : args) {
        try {
            Field field = getFieldByName(arg, requiredType);
            if(field != null) {
                if(field.getType() == boolean.class) {
                    field.set(instance, true);
                } else {
                    field.set(instance, args[i+1]);
                    i++;
                }
            }
        } catch(IllegalArgumentException e) {
            // ignore invalid arguments
        }
    }
    return instance;
}

private Field getFieldByName(String name, Class clazz) {
    Field[] fields = clazz.getDeclaredFields();
    for(Field field : fields) {
        if(field.getName().toLowerCase().equals(name.toLowerCase())) {
            return field;
        }
    }
    return null;
}
