public Dataset getDataset(int runtime, long timeOffset, long[] timeRange) {
    if (timeRange == null) {
        // Single runtime with a time offset
        return getConstantRuntimeDataset(runtime, timeOffset);
    } else if (timeRange.length == 1) {
        // Single runtime with a specific time
        return getConstantRuntimeDataset(runtime, timeRange[0]);
    } else {
        // Multiple runtimes with a constant time offset
        return getConstantOffsetDataset(runtime, timeOffset);
    }
}

