public TreeNode optimize(TreeNode root) {
    if (root == null) {
        return null;
    }

    if (root.value.equals("AND") || root.value.equals("OR")) {
        TreeNode left = optimize(root.left);
        TreeNode right = optimize(root.right);
        if (left == null && right == null) {
            return null;
        } else if (left == null) {
            return right;
        } else if (right == null) {
            return left;
        } else {
            if (left.value.equals(root.value) && right.value.equals(root.value)) {
                List<TreeNode> children = new ArrayList<TreeNode>();
                children.addAll(left.children);
                children.addAll(right.children);
                return new TreeNode(root.value, children);
            } else if (left.value.equals(root.value)) {
                return left;
            } else if (right.value.equals(root.value)) {
                return right;
            } else {
                return new TreeNode(root.value, Arrays.asList(left, right));
            }
        }
    } else {
        return root;
    }
}
