public VersionInfo readHeaderVersion() {
    int header = readHeader();

    int major = (header >> 24) & 0xFF;
    int minor = (header >> 16) & 0xFF;
    int patch = header & 0xFFFF;

    return new VersionInfo(major, minor, patch);
}
