import java.io.File;
import java.util.ArrayList;
import java.util.List;

public List<String> getClassNames(String packageName) throws ClassNotFoundException {
    List<String> classNames = new ArrayList<>();
    String path = packageName.replace('.', '/');
    ClassLoader classLoader = Thread.currentThread().getContextClassLoader();
    File directory = new File(classLoader.getResource(path).getFile());
    if (directory.exists()) {
        File[] files = directory.listFiles();
        for (File file : files) {
            if (file.isFile() && file.getName().endsWith(".class")) {
                String name = packageName + "." + file.getName().substring(0, file.getName().length() - 6);
                classNames.add(name);
            } else if (file.isDirectory()) {
                List<String> nestedClassNames = getClassNames(packageName + "." + file.getName());
                classNames.addAll(nestedClassNames);
            }
        }
    } else {
        throw new ClassNotFoundException(packageName + " does not exist as a package.");
    }
    return classNames;
}
