public String formatOptions(final Options optList, final int maxLength, final boolean showUnpublicized) {
    final StringBuilder sb = new StringBuilder();
    final List<Option> options = new ArrayList<Option>(optList.getOptions());
    Collections.sort(options);

    int max = 0;
    for (final Option option : options) {
        if (option.canAppearOnCommandLine() || showUnpublicized) {
            final int len = option.getOpt().length() + 2 + (option.hasArg() ? 4 : 0);
            if (len > max) {
                max = len;
            }
        }
    }
    int width = max <= maxLength ? max : maxLength > 5 ? maxLength - 3 : maxLength;
    boolean hasList = false;
    for (final Option option : options) {
        if (option.canAppearOnCommandLine() || showUnpublicized) {
            final String opt = option.getOpt();
            final String longOpt = option.getLongOpt();

            if (opt == null) {
                sb.append("   ");
            } else {
                sb.append("-");
                sb.append(opt);
                if (longOpt != null) {
                    sb.append(",");
                    sb.append(longOpt);
                }
            }

            final int len = sb.length();
            if (len < width) {
                for (int i = 0; i < width - len; ++i) {
                    sb.append(" ");
                }
            } else {
                sb.append("\n");
                for (int i = 0; i < max + 1; ++i) {
                    sb.append(" ");
                }
                width = max;
            }

            sb.append(" ");
            sb.append(option.getDescription());

            if (option.hasArg()) {
                final String argName = option.getArgName();
                if (argName != null && argName.length() > 0) {
                    sb.append(" <");
                    sb.append(argName);
                    sb.append(">");
                }
                hasList |= option.hasArgName() && "java.util.List".equals(option.getType());
            }
            sb.append("\n");
        }
    }
    hasListOption = hasList;
    return sb.toString();
}
