public List<DiskAdapter> getFilteredDiskAdapters(String filter) {
    //parse the filter string into a valid JSON object
    JSONObject filterObj = new JSONObject(filter);

    //initialize the list to hold the filtered disk_adapter resources
    List<DiskAdapter> filteredDiskAdapters = new ArrayList<>();

    //iterate through all disk_adapter resources and check if they match the filter criteria
    for(DiskAdapter adapter : allDiskAdapters) {
        //get the properties of the current adapter
        String vmState = adapter.getVmState();
        String name = adapter.getName();

        //check if the current adapter matches the filter
        if(vmState.equals(filterObj.getString("vm_state")) && name.matches(filterObj.getString("name"))) {
            //if the current adapter matches the filter, add it to the list of filtered disk_adapter resources
            filteredDiskAdapters.add(adapter);
        }
    }

    //return the filtered list of disk_adapter resources
    return filteredDiskAdapters;
}
