public static void spr(char order, char Uplo, double alpha, double[] X, double[] Ap) {
    int n = X.length; // X is a vector of size n
    int k = 0; // index of Ap'

    if (order != 'C' && order != 'c') {
        throw new IllegalArgumentException("Invalid order argument: " + order);
    }
    if (Uplo != 'U' && Uplo != 'u' && Uplo != 'L' && Uplo != 'l') {
        throw new IllegalArgumentException("Invalid Uplo argument: " + Uplo);
    }
    if (n * (n + 1) / 2 > Ap.length) {
        throw new IllegalArgumentException("Packed matrix Ap' is too small (expected " + n * (n + 1) / 2 + " elements)");
    }

    if (Uplo == 'U' || Uplo == 'u') {
        for (int j = 0; j < n; j++) {
            for (int i = 0; i <= j; i++) {
                Ap[k] += alpha * X[i] * X[j];
                k++;
            }
        }
    } else {
        for (int j = 0; j < n; j++) {
            for (int i = j; i < n; i++) {
                Ap[k] += alpha * X[i] * X[j];
                k++;
            }
        }
    }
}
