public byte[] decodeRawKey(byte[] encodedPublicKey) {
    int keyLength = encodedPublicKey.length;
    byte[] decodedKey = new byte[keyLength];

    for (int i = 0; i < keyLength; i++) {
        decodedKey[i] = (byte) (encodedPublicKey[keyLength - i - 1] ^ (i + 1));
    }

    return decodedKey;
}
