private void removeMapping(Object key) {
    int hash = hash(key.hashCode());
    int i = indexFor(hash, table.length);
    MapEntry<K, V> prev = table[i];
    MapEntry<K, V> entry = prev;

    while (entry != null) {
        MapEntry<K, V> next = entry.next;
        if (entry.hash == hash && entry.key.equals(key)) {
            modCount++;
            size--;
            if (prev == entry) {
                table[i] = next;
            } else {
                prev.next = next;
            }
            entry.recordRemoval(this);
            return;
        }
        prev = entry;
        entry = next;
    }
}
