public void checkAndParse(HttpServerExchange exchange) throws Exception {
    HeaderValues headerValues = exchange.getRequestHeaders().get("Content-Type");
    if (headerValues != null) {
        String contentType = headerValues.toString();
        if (contentType.startsWith("application/json")) {
            Deque<String> body = new LinkedList<>();
            exchange.getRequestReceiver().receiveFullString((exchange1, message) -> body.push(message));
            String jsonStr = body.getFirst();
            if (jsonStr.startsWith("[")) {
                List jsonList = new Gson().fromJson(jsonStr, List.class);
                // Do something with jsonList
            } else if (jsonStr.startsWith("{")) {
                Map<String, Object> jsonMap = new Gson().fromJson(jsonStr, HashMap.class);
                // Do something with jsonMap
            }
        } else if (contentType.startsWith("application/x-www-form-urlencoded") ||
                contentType.startsWith("multipart/form-data")) {
            FormData formData = exchange.getAttachment(FormDataParser.FORM_DATA);
            // Do something with formData
        }
    }
}
