import java.math.BigInteger;
import java.security.KeyFactory;
import java.security.spec.ECParameterSpec;
import java.security.spec.ECPrivateKeySpec;
import java.security.spec.ECPublicKeySpec;
import java.security.spec.InvalidKeySpecException;
import java.security.spec.NamedParameterSpec;

public BigInteger getPublicKeyFromPrivateKey(BigInteger privKey) throws InvalidKeySpecException {
    NamedParameterSpec params = ECNamedCurveTable.getParameterSpec("secp256k1");
    ECParameterSpec spec = new ECNamedCurveSpec("secp256k1", params.getCurve(), params.getG(), params.getN());
    ECPrivateKeySpec pkSpec = new ECPrivateKeySpec(privKey, spec);
    KeyFactory keyFactory = KeyFactory.getInstance("EC");
    ECPublicKeySpec pubSpec = keyFactory.getKeySpec(keyFactory.generatePublic(new ECPublicKeySpec(pkSpec.getParams().getG().multiply(privKey), pkSpec.getParams())), ECPublicKeySpec.class);
    return pubSpec.getW().getAffineX();
}
