public boolean isHomomericInterface(Interface interface) {

    // Check if either of the compounds is null
    if (interface.getFirstCompound() == null || interface.getSecondCompound() == null) {
        return true;
    }

    // Check if the compounds are the same entity
    if (interface.getFirstCompound().equals(interface.getSecondCompound())) {
        return true;
    }

    return false;
}
