public static void encodeOctetToHex(byte input, char[] output, int outoff) {
    final char[] HEX_TABLE = "0123456789ABCDEF".toCharArray();
    output[outoff++] = HEX_TABLE[(input >> 4) & 0x0F];
    output[outoff] = HEX_TABLE[input & 0x0F];
}
