public Entry getEntry(Object key) {
    for (Entry e = table[indexFor(hash(key), table.length)];
         e != null;
         e = e.next) {
        Object k;
        if (e.hash == hash(key) && ((k = e.key) == key || key.equals(k)))
            return e;
    }
    return null;
}
