public void updateShadowMatrix(SceneObject owner) {
    // Update light position and direction from the owner's transform
    transform.setPosition(owner.transform.getPosition());
    transform.setRotation(owner.transform.getRotation());

    // Create a view matrix from the light's transform
    Matrix4f viewMatrix = new Matrix4f();
    viewMatrix.identity();
    viewMatrix.lookAt(transform.getPosition(), owner.transform.getPosition(), new Vector3f(0, 1, 0));

    // Create a projection matrix for the shadow frustum
    float frustumSize = 10.0f;
    float near = 1.0f;
    float far = 100.0f;
    Matrix4f projectionMatrix = new Matrix4f();
    projectionMatrix.identity();
    projectionMatrix.ortho(-frustumSize, frustumSize, -frustumSize, frustumSize, near, far);

    // Create the shadow matrix by multiplying the model, view, and projection matrices together
    Matrix4f shadowMatrix = new Matrix4f();
    shadowMatrix.identity();
    shadowMatrix.mul(projectionMatrix);
    shadowMatrix.mul(viewMatrix);
    shadowMatrix.mul(owner.modelMatrix);

    // Set the light's shadow matrix
    this.shadowMatrix = shadowMatrix;
}
