import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;

public class PumpStreamHandler {

    public Thread createPump(InputStream is, OutputStream os, boolean closeWhenExhausted) {
        Thread thread = new Thread(new ThreadWithPumper(is, os, closeWhenExhausted));
        thread.setDaemon(true);
        thread.start();
        return thread;
    }

    public static class ThreadWithPumper implements Runnable {
        private final InputStream is;
        private final OutputStream os;
        private final boolean closeWhenExhausted;
        private volatile boolean finished;

        public ThreadWithPumper(InputStream is, OutputStream os, boolean closeWhenExhausted) {
            this.is = is;
            this.os = os;
            this.closeWhenExhausted = closeWhenExhausted;
        }

        @Override
        public void run() {
            try {
                byte[] buffer = new byte[1024];
                int len;
                while ((len = is.read(buffer)) != -1) {
                    os.write(buffer, 0, len);
                }
                if (closeWhenExhausted) {
                    is.close();
                }
                os.flush();
            } catch (IOException e) {
                // Ignore
            } finally {
                synchronized (this) {
                    finished = true;
                    notifyAll();
                }
            }
        }

        public synchronized boolean isFinished() {
            return finished;
        }

        public synchronized void waitFor() throws InterruptedException {
            while (!finished) {
                wait();
            }
        }
    }
}
