import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;

public class CollectionMapKeyTypeDeterminer {
    public static <T> Object getKeyType(String propertyName) {
        try {
            Type type = getClass().getDeclaredField(propertyName).getGenericType();
            if (type instanceof ParameterizedType) {
                Type[] genericTypes = ((ParameterizedType) type).getActualTypeArguments();
                if (genericTypes.length > 0 && genericTypes[0] instanceof Class) {
                    return (Class<?>) genericTypes[0];
                }
            }
            return String.class; // Assuming JDK version is less than 1.5
        } catch (NoSuchFieldException e) {
            e.printStackTrace();
            return null;
        }
    }
}
