public static double besselI0(double x) {
    double sum = 1.0;
    double factorial = 1.0;
    double power = 1.0;
    double xSquared = x * x;
    double term = 1.0;

    for (int i = 1; i <= 50; i++) {
        factorial *= i;
        power *= xSquared / 4.0;
        term = power / (factorial * factorial);
        sum += term;
        if (term <= sum * 1e-10) {
            break;
        }
    }

    return sum;
}
