public static Order inferOrder(int[] shape, int[] stride, int elementStride) {
    int[] tempShape = Arrays.copyOf(shape, shape.length);
    int[] tempStride = Arrays.copyOf(stride, stride.length);
    int dim = tempShape.length;
    int minIndex = 0, maxIndex = dim - 1;
    int temp;
    while (minIndex < maxIndex) {
        temp = tempShape[minIndex];
        tempShape[minIndex] = tempShape[maxIndex];
        tempShape[maxIndex] = temp;
        temp = tempStride[minIndex];
        tempStride[minIndex] = tempStride[maxIndex];
        tempStride[maxIndex] = temp;
        minIndex++;
        maxIndex--;
    }
    Order order = Order.C;
    int idx = dim - 1;
    if (tempStride[idx] == elementStride) {
        order = Order.F;
        idx--;
    }
    while (idx >= 0) {
        if (tempStride[idx] != tempShape[idx + 1] * tempStride[idx + 1]) {
            break;
        }
        idx--;
    }
    if (idx == -1) {
        return order;
    }
    idx = 0;
    while (idx < dim - 1) {
        if (tempStride[idx] != tempShape[idx] * tempStride[idx + 1]) {
            break;
        }
        idx++;
    }
    if (idx == dim - 1) {
        return Order.C;
    }
    return Order.A;
}
