import org.objectweb.asm.ClassReader;
import org.objectweb.asm.ClassVisitor;
import org.objectweb.asm.Label;
import org.objectweb.asm.MethodVisitor;
import org.objectweb.asm.Opcodes;
import org.objectweb.asm.Type;
import org.objectweb.asm.util.Printer;
import org.objectweb.asm.util.Textifier;
import org.objectweb.asm.util.TraceMethodVisitor;

public class SourceLineAnnotation {
    public static SourceLineAnnotation create(Method methodDescriptor) {
        try {
            Class<?> cls = methodDescriptor.getDeclaringClass();
            ClassLoader classLoader = cls.getClassLoader();
            String name = cls.getName().replace('.', '/') + ".class";
            byte[] bytes = classLoader.getResourceAsStream(name).readAllBytes();
            ClassReader cr = new ClassReader(bytes);
            SourceLineAnnotationVisitor cv = new SourceLineAnnotationVisitor(methodDescriptor);
            cr.accept(cv, 0);
            return cv.annotation;
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }
}

class SourceLineAnnotationVisitor extends ClassVisitor implements Opcodes {
    final Method methodDescriptor;
    SourceLineAnnotation annotation;

    public SourceLineAnnotationVisitor(Method methodDescriptor) {
        super(ASM8);
        this.methodDescriptor = methodDescriptor;
    }

    @Override
    public MethodVisitor visitMethod(int access, String methodName, String methodDescriptor, String signature, String[] exceptions) {
        MethodVisitor mv = super.visitMethod(access, methodName, methodDescriptor, signature, exceptions);
        return new MethodVisitor(ASM8, mv) {
            @Override
            public void visitLineNumber(int line, Label start) {
                if (annotation == null && line == 1) {
                    Type[] argumentTypes = Type.getArgumentTypes(SourceLineAnnotationVisitor.this.methodDescriptor);
                    Printer printer = new Textifier(ASM8);
                    TraceMethodVisitor traceMethodVisitor = new TraceMethodVisitor(printer);
                    traceMethodVisitor.visitParameters(argumentTypes);
                    traceMethodVisitor.visitInsn(Opcodes.RETURN);
                    String methodBody = printer.toString().trim();
                    annotation = new SourceLineAnnotation(SourceLineAnnotationVisitor.this.methodDescriptor, methodBody, line);
                }
                super.visitLineNumber(line, start);
            }
        };
    }
}

class SourceLineAnnotation {
    final Method method;
    final String methodBody;
    final int lineNumber;

    public SourceLineAnnotation(Method method, String methodBody, int lineNumber) {
        this.method = method;
        this.methodBody = methodBody;
        this.lineNumber = lineNumber;
    }

    @Override
    public String toString() {
        return String.format("%s #%d : %s", method.getName(), lineNumber, methodBody);
    }
}
