public ErrorItem throwableToErrorItem(String logMessage, Throwable t) {
    String errorMessage = (t.getMessage() != null) ? t.getMessage() : t.toString();
    String stackTrace = "";

    StringWriter sw = new StringWriter();
    PrintWriter pw = new PrintWriter(sw);
    t.printStackTrace(pw);
    stackTrace = sw.toString();

    ErrorItem errorItem = new ErrorItem();
    errorItem.setLogMessage(logMessage);
    errorItem.setErrorMessage(errorMessage);
    errorItem.setStackTrace(stackTrace);

    return errorItem;
}
