public static String replaceTokens(Map<String, String> tokenMap, String text) {
    for(Map.Entry<String, String> entry : tokenMap.entrySet()) {
        String key = entry.getKey();
        String value = entry.getValue();
        text = text.replace(key, value);
    }
    if(text.contains("${")) {
        throw new IllegalArgumentException("All tokens not replaced");
    }
    return text;
}
