import java.net.MalformedURLException;
import java.net.URL;
import java.util.Stack;

public static URL mergePaths(URL current, String realPath) throws MalformedURLException {
    Stack<String> parts = new Stack<>();
    String[] oldParts = current.getPath().split("/");
    for (String part : oldParts) {
        if (!part.isEmpty()) {
            parts.push(part);
        }
    }
    String[] newParts = realPath.split("/");
    for (String part : newParts) {
        if (!part.isEmpty()) {
            if (part.equals("..")) {
                if (!parts.isEmpty()) {
                    parts.pop();
                }
            } else if (!part.equals(".")) {
                parts.push(part);
            }
        }
    }
    StringBuilder sb = new StringBuilder();
    for (String part : parts) {
        sb.append("/");
        sb.append(part);
    }
    String path = (sb.length() > 0) ? sb.toString() : "/";
    String protocol = current.getProtocol();
    String host = current.getHost();
    int port = current.getPort();
    return new URL(protocol, host, port, path);
}
