public void drawRegions(Map<Point, Region> pixelToRegion, Map<Region, Color> segmentColor, Graphics output, BufferedImage storage) {
    Graphics2D graphics2D = (Graphics2D) output;

    if (storage == null) {
        storage = new BufferedImage(output.getClipBounds().width, output.getClipBounds().height,
                BufferedImage.TYPE_INT_RGB);
    }

    for (Region region : segmentColor.keySet()) {
        graphics2D.setColor(segmentColor.get(region));
        for (Point point : pixelToRegion.keySet()) {
            if (region == pixelToRegion.get(point)) {
                storage.setRGB(point.x, point.y, segmentColor.get(region).getRGB());
            }
        }
    }
    graphics2D.drawImage(storage, null, 0, 0);
}
