public <T> Stream<List<T>> collectIntoBatches(int numBatches, List<T> items) {
    int size = items.size();
    int batchSize = (int) Math.ceil((double) size / numBatches);
    return IntStream.range(0, numBatches)
        .mapToObj(i -> items.subList(i * batchSize, Math.min((i + 1) * batchSize, size)))
        .filter(list -> !list.isEmpty());
}
