public void buildEnumSummary(Element node, Element summaryContentTree) {
    NodeList enumNodes = node.getElementsByTagName("enum");
    Element enumSummary = summaryContentTree.getOwnerDocument().createElement("section");
    enumSummary.setAttribute("title", "Enum Summary");
    summaryContentTree.appendChild(enumSummary);

    for (int i = 0; i < enumNodes.getLength(); i++) {
        Element enumNode = (Element) enumNodes.item(i);
        String enumName = enumNode.getAttribute("name");

        Element enumEntry = summaryContentTree.getOwnerDocument().createElement("entry");
        enumEntry.setAttribute("name", enumName);
        enumEntry.setAttribute("type", "enum");
        enumSummary.appendChild(enumEntry);

        NodeList valueNodes = enumNode.getElementsByTagName("value");
        Element valueList = summaryContentTree.getOwnerDocument().createElement("list");
        enumEntry.appendChild(valueList);

        for (int j = 0; j < valueNodes.getLength(); j++) {
            Element valueNode = (Element) valueNodes.item(j);
            String valueName = valueNode.getAttribute("name");
            String valueDescription = valueNode.getAttribute("description");

            Element valueItem = summaryContentTree.getOwnerDocument().createElement("item");
            valueItem.setAttribute("name", valueName);
            valueItem.setAttribute("type", "enum value");
            valueItem.setTextContent(valueDescription);
            valueList.appendChild(valueItem);
        }
    }
}
