public static BufferedImage recolorImage(BufferedImage image, Colorization colorization) {
    float[] oldRGB = {colorization.getOldColor().getRed() / 255f, 
                      colorization.getOldColor().getGreen() / 255f, 
                      colorization.getOldColor().getBlue() / 255f};
    float[] newRGB = {colorization.getNewColor().getRed() / 255f, 
                      colorization.getNewColor().getGreen() / 255f, 
                      colorization.getNewColor().getBlue() / 255f};
    return recolorImage(image, colorization.getThreshold(), oldRGB, newRGB);
}
