public static <DATATYPE> List<List<DATATYPE>> getPermutations(List<DATATYPE> aInput, int nSlotCount) {
        List<List<DATATYPE>> resultList = new ArrayList<>();
        if (nSlotCount == 0) {
            resultList.add(new ArrayList<>());
            return resultList;
        }

        final DATATYPE firstElement = aInput.get(0);
        final List<DATATYPE> restList = aInput.subList(1, aInput.size());
        final List<List<DATATYPE>> permutationsOfRest = getPermutations(restList, nSlotCount - 1);

        for (List<DATATYPE> permutation : permutationsOfRest) {
            for (int position = 0; position <= permutation.size(); position++) {
                final List<DATATYPE> temp = new ArrayList<>(permutation);
                temp.add(position, firstElement);
                resultList.add(temp);
            }
        }
        return resultList;
}
