public String cancelFutures(boolean forceAbort, boolean isMultiPart, boolean isStarted) {
    if (forceAbort || (isMultiPart && !isStarted)) {
        // If the user requested forced abort, or if the upload is a multi-part and hasn't started yet,
        // cancel all in-flight transfers of the upload if applicable
        if (isMultiPart) {
            // Perform cancellation of multi-part upload
            return multiPartUploadId; // Return the multi-part upload Id
        } else {
            // Perform cancellation of single-part upload
            return null;
        }
    } else {
        // Do nothing, returns null since the upload is not cancelled
        return null;
    }
}
