public Object[] toArray(Object obj) {
    if (obj == null) {
        return new Object[0];
    }
    Class<?> clazz = obj.getClass();
    if (!clazz.isArray()) {
        Object[] result = new Object[1];
        result[0] = obj;
        return result;
    }
    int length = Array.getLength(obj);
    Object[] result = new Object[length];
    for (int i = 0; i < length; i++) {
        result[i] = Array.get(obj, i);
    }
    return result;
}
