public String getMavenArtifactPath(MavenArtifact artifact) {
    String[] coordinates = artifact.getCoordinates().split(":");
    String groupIdPath = coordinates[0].replace(".", "/");
    String artifactIdPath = coordinates[1];
    String version = coordinates[2];
    String extension = artifact.getExtension().equals("jar") ? "" : "-" + artifact.getExtension();
    return groupIdPath + "/" + artifactIdPath + "/" + version + "/" + artifactIdPath + "-" + version + extension;
}
