import okhttp3.*;
import java.io.IOException;

public class AuthleteBackchannelAPI {
    public static final MediaType JSON = MediaType.get("application/json; charset=utf-8");
    private OkHttpClient client = new OkHttpClient();

    public String callBackchannelAuthenticationAPI(String requestBodyJson, String apiBaseUrl, String apiKey, String apiSecret) throws IOException {
        String url = apiBaseUrl + "/api/backchannel/authentication";
        RequestBody requestBody = RequestBody.create(JSON, requestBodyJson);
        String authorizationHeader = "Bearer " + createBearerToken(apiKey, apiSecret, url);
        Request request = new Request.Builder()
                .url(url)
                .post(requestBody)
                .header("Content-Type", "application/json")
                .header("Authorization", authorizationHeader)
                .build();
        Response response = client.newCall(request).execute();
        return response.body().string();
    }

    private String createBearerToken(String apiKey, String apiSecret, String url) throws IOException {
        String timestamp = String.valueOf(System.currentTimeMillis() / 1000);
        String signature = createSignature(apiKey, apiSecret, timestamp, "POST", url);
        return apiKey + ':' + timestamp + ':' + signature;
    }

    private String createSignature(String apiKey, String apiSecret, String timestamp, String httpMethod, String url) throws IOException {
        String content = timestamp + httpMethod + url;
        byte[] hmac = hmacSha256(apiSecret.getBytes(), content.getBytes());
        return Base64.getUrlEncoder().withoutPadding().encodeToString(hmac);
    }

    private byte[] hmacSha256(byte[] key, byte[] message) throws IOException {
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            mac.init(new SecretKeySpec(key, "HmacSHA256"));
            return mac.doFinal(message);
        } catch (GeneralSecurityException e) {
            throw new IOException(e);
        }
    }
}
