@Override
public TableParam read(long primaryKey) throws DatabaseException {
    Connection conn = null;
    PreparedStatement stmt = null;
    ResultSet rs = null;
    TableParam tableParam = null;

    try {
        conn = getConnection();
        stmt = conn.prepareStatement("SELECT * FROM table_param WHERE id = ?");
        stmt.setLong(1, primaryKey);
        rs = stmt.executeQuery();

        if (rs.next()) {
            tableParam = new TableParam();
            tableParam.setId(rs.getLong("id"));
            tableParam.setName(rs.getString("name"));
            tableParam.setValue(rs.getString("value"));
        }
    } catch (SQLException e) {
        throw new DatabaseException(e);
    } finally {
        close(rs, stmt, conn);
    }

    return tableParam;
}
