import java.lang.reflect.Array;
import java.util.HashMap;
import java.util.Map;

public class ArrayUtil {

    public static Class<?> getFirstCommonSuperclass(Class<?> aArrType, Class<?> bArrType) {
        Map<Class<?>, Integer> classHierarchy = getClassHierarchy(aArrType);
        Class<?> currClass = bArrType;
        while (currClass != null) {
            if (classHierarchy.containsKey(currClass)) {
                return currClass;
            }
            currClass = currClass.getSuperclass();
        }
        return null;
    }

    private static Map<Class<?>, Integer> getClassHierarchy(Class<?> clazz) {
        Map<Class<?>, Integer> hierarchy = new HashMap<>();
        int level = 0;
        while (clazz != null && clazz.isArray()) {
            hierarchy.put(clazz, level++);
            clazz = clazz.getComponentType();
        }
        if (clazz != null) {
            hierarchy.put(clazz, level);
        }
        return hierarchy;
    }
}

class ArrayType { // example usage for the function
    public static void main(String[] args) {
        Class<?> strArrType = String[][].class;
        Class<?> objArrType = Object[][].class;
        Class<?> classObj = ArrayUtil.getFirstCommonSuperclass(strArrType, objArrType);
        System.out.println(classObj.getName());
    }
}
