public Authentication setupAuthentication(HttpClient httpClient, String username, String password) {

    // Create credentials provider with the given username and password
    CredentialsProvider credentialsProvider = new BasicCredentialsProvider();
    credentialsProvider.setCredentials(
            new AuthScope(AuthScope.ANY_HOST, AuthScope.ANY_PORT),
            new UsernamePasswordCredentials(username, password));

    // Setup the authentication scheme registry and add the basic authentication scheme
    Registry<AuthSchemeProvider> authSchemeRegistry = RegistryBuilder.<AuthSchemeProvider>create()
            .register(AuthSchemes.BASIC, new BasicSchemeFactory())
            .build();

    // Create the HttpClientBuilder and set the credentials and authentication scheme registry
    HttpClientBuilder httpClientBuilder = HttpClients.custom()
            .setDefaultCredentialsProvider(credentialsProvider)
            .setDefaultAuthSchemeRegistry(authSchemeRegistry);

    // Build the HttpClient and return the setup of authentication
    httpClient = httpClientBuilder.build();

    return new Authentication(httpClient, credentialsProvider, authSchemeRegistry);
}

public class Authentication {

    private final HttpClient httpClient;
    private final CredentialsProvider credentialsProvider;
    private final Registry<AuthSchemeProvider> authSchemeRegistry;

    public Authentication(HttpClient httpClient, CredentialsProvider credentialsProvider,
                          Registry<AuthSchemeProvider> authSchemeRegistry) {
        this.httpClient = httpClient;
        this.credentialsProvider = credentialsProvider;
        this.authSchemeRegistry = authSchemeRegistry;
    }

    public HttpClient getHttpClient() {
        return httpClient;
    }

    public CredentialsProvider getCredentialsProvider() {
        return credentialsProvider;
    }

    public Registry<AuthSchemeProvider> getAuthSchemeRegistry() {
        return authSchemeRegistry;
    }
}
