public Color recalculateDerivedColor(Color parentColor, int redOffset, int greenOffset, int blueOffset) {
    int red = parentColor.getRed() + redOffset;
    int green = parentColor.getGreen() + greenOffset;
    int blue = parentColor.getBlue() + blueOffset;
    red = Math.max(0, Math.min(255, red));
    green = Math.max(0, Math.min(255, green));
    blue = Math.max(0, Math.min(255, blue));
    return new Color(red, green, blue);
}
