import java.time.LocalDateTime;
import java.time.ZoneOffset;

public long[] getMillisBetweenDates(LocalDateTime[] localDateTimes) {
    long[] millisBetweenDates = new long[localDateTimes.length];
    int index = 0;
    for (LocalDateTime localDateTime : localDateTimes) {
        try {
            millisBetweenDates[index++] = localDateTime.toInstant(ZoneOffset.UTC).toEpochMilli();
        } catch (NullPointerException e) {
            millisBetweenDates[index++] = Long.MIN_VALUE;
        }
    }
    return millisBetweenDates;
}
