public static Object constructComplexTypes(JSONObject value) {
    Iterator<?> keys = value.keySet().iterator();
    while(keys.hasNext()) {
        String key = (String)keys.next();
        Object o = value.get(key);
        if(o instanceof JSONObject) {
            JSONObject jsonObject = (JSONObject)o;
            if(jsonObject.has("type") && jsonObject.getString("type").equals("complex")) {
                return constructComplexTypes(jsonObject.getJSONObject("value"));
            }
        } else if(o instanceof JSONArray) {
            JSONArray jsonArray = (JSONArray)o;
            for(int i=0; i < jsonArray.length(); i++) {
                jsonArray.put(i, constructComplexTypes(jsonArray.getJSONObject(i)));
            }
        } else if(o instanceof Number) {
            return new BigDecimal(o.toString());
        }
    }
    return null;
}
