public String resolveIdentity(String address, String subject) {
    String identity = null;
    // Attempting to resolve identity in the transport layer
    // If not found, try resolving in the session layer
    // If not found, try resolving in the presentation layer
    // If not found, try resolving in the application layer
    // If still not found, return null

    // Transport layer
    identity = resolveTransportLayerIdentity(address, subject);
    if(identity != null) {
        return identity;
    }

    // Session layer
    identity = resolveSessionLayerIdentity(address, subject);
    if(identity != null) {
        return identity;
    }

    // Presentation layer
    identity = resolvePresentationLayerIdentity(address, subject);
    if(identity != null) {
        return identity;
    }

    // Application layer
    identity = resolveApplicationLayerIdentity(address, subject);
    if(identity != null) {
        return identity;
    }

    // Identity not found
    return null;
}

