    } else {
        firstWalker = new org.apache.xpath.axes.WalkingIterator(this);
    }

    firstWalker.init(iter, opPos, firstStepPos);

    iter.setFirstWalker(firstWalker);

    if (iter instanceof org.apache.xpath.axes.PathComponent) {
        ((org.apache.xpath.axes.PathComponent)iter).setPathComponent(true);
    }

    return iter;
}
