public static int[] computeOffsets(int[] sizes) {
    int rank = sizes.length;
    int[] offsets = new int[rank];
    int offset = 1;
    for (int i = rank - 1; i >= 0; i--) {
        offsets[i] = offset;
        offset *= sizes[i];
    }
    return offsets;
}
