public List<String> createLockTokens(String lockTokenHeader, String ifHeader) {
    List<String> lockTokens = new ArrayList<>();
    if (lockTokenHeader != null && !lockTokenHeader.isEmpty()) {
        String[] tokens = lockTokenHeader.split(",");
        for (String token : tokens) {
            lockTokens.add(token.trim());
        }
    }
    if (ifHeader != null && !ifHeader.isEmpty()) {
        String[] conditions = ifHeader.split("\\s*(?=\\()|\\s+");
        for (int i = 0; i < conditions.length; i++) {
            if ("(Not".equals(conditions[i])) {
                i += 2;
                continue;
            } else if ("(lock-token:".equals(conditions[i])) {
                lockTokens.add(conditions[++i].replaceAll("[\"\\(\\)]", ""));
            }
        }
    }
    return lockTokens;
}
