public PointersPair getMemoryChunk(AllocationShape shape, AllocationPoint point, Location location) {
    // Check if the requested shape is already cached
    if (location == Location.HOST && hostCachedChunks.containsKey(shape)) {
        byte[] cachedChunk = hostCachedChunks.get(shape);
        return new PointersPair(cachedChunk, null);
    } else if (location == Location.DEVICE && deviceCachedChunks.containsKey(shape)) {
        long cachedChunk = deviceCachedChunks.get(shape);
        return new PointersPair(null, cachedChunk);
    }

    // If no cached chunk is available, allocate a new one
    if (location == Location.HOST) {
        byte[] memoryChunk = mallocHost(shape.getSize());
        hostCachedChunks.put(shape, memoryChunk);
        return new PointersPair(memoryChunk, null);
    } else { // location == Location.DEVICE
        long memoryChunk = mallocDevice(shape.getSize(), point);
        deviceCachedChunks.put(shape, memoryChunk);
        return new PointersPair(null, memoryChunk);
    }
}
