import java.io.IOException;
import java.io.ObjectOutputStream;
import java.io.OutputStream;

public class TupleSerializer<T1, T2> implements Serializer<Tuple2<T1, T2>> {

    private final Serializer<T1> first;
    private final Serializer<T2> second;

    public TupleSerializer(Serializer<T1> first, Serializer<T2> second) {
        this.first = first;
        this.second = second;
    }

    @Override
    public void serialize(OutputStream out, Tuple2<T1, T2> value) throws IOException {
        ObjectOutputStream oos = new ObjectOutputStream(out);
        oos.writeObject(value.first);
        oos.writeObject(value.second);
        oos.flush();
    }

    @Override
    public Tuple2<T1, T2> deserialize(InputStream in) throws IOException {
        ObjectInputStream ois = new ObjectInputStream(in);
        T1 firstValue = (T1) ois.readObject();
        T2 secondValue = (T2) ois.readObject();
        return new Tuple2<>(firstValue, secondValue);
    }
}
