public Node findLowestCommonAncestor(Node root, Node v, Node w) {
    if (root == null || root == v || root == w) {
        return root;
    }

    // recursively traverse left subtree
    Node left = findLowestCommonAncestor(root.left, v, w);

    // recursively traverse right subtree
    Node right = findLowestCommonAncestor(root.right, v, w);

    // if the current node has both descendants, it is the LCA
    if (left != null && right != null) {
        return root;
    } else if (left != null) {
        // one of the descendants is on the left subtree
        return left;
    } else {
        // both descendants are on the right subtree
        return right;
    }
}
