public enum EValidity {
    VALID,
    INVALID
}

public EValidity validateMessage(String aChars) {
    if (aChars.length() != 8 && aChars.length() != 12 && aChars.length() != 13 && aChars.length() != 14) {
        return EValidity.INVALID;
    }

    int sum = 0;
    int digit = 0;

    for (int i = aChars.length() - 1; i >= 0; i--) {
        char currentChar = aChars.charAt(i);

        if (currentChar < '0' || currentChar > '9') {
            return EValidity.INVALID;
        }

        digit = currentChar - '0';
        sum += ((aChars.length() - i) % 2 == 0) ? digit * 3 : digit;
    }

    return (sum % 10 == 0) ? EValidity.VALID : EValidity.INVALID;
}
