public void scrollHorizontally(View view, Side side, float scrollPosition, int stepCount) {
   int dx = computeScrollDelta(side == Side.RIGHT ? 1 : -1, scrollPosition, stepCount);
   view.scrollBy(dx, 0);
}

private int computeScrollDelta(int direction, float position, int stepCount) {
   float steps = stepCount * 1f;
   float currentStep = 0f;
   while (currentStep < steps) {
      currentStep ++;
      position *= position * (3 - 2 * position);
   }
   return (int) (position * direction * view.getWidth());
}

public enum Side {
   LEFT,
   RIGHT
}
