import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import org.apache.commons.codec.binary.Hex;

public static String generateHmacSha256Signature(int version, long timestamp, byte[] initializationVector, byte[] cipherText) throws Exception {
    Mac sha256Hmac = Mac.getInstance("HmacSHA256");
    byte[] keyBytes = "Fernet-Signing-Key".getBytes("UTF-8");
    SecretKeySpec secretKey = new SecretKeySpec(keyBytes, "HmacSHA256");
    sha256Hmac.init(secretKey);

    byte[] versionBytes = ByteBuffer.allocate(4).putInt(version).array();
    byte[] timestampBytes = ByteBuffer.allocate(8).putLong(timestamp).array();
    byte[] finalBytes = new byte[versionBytes.length + timestampBytes.length
                + initializationVector.length + cipherText.length];
    System.arraycopy(versionBytes, 0, finalBytes, 0, versionBytes.length);
    System.arraycopy(timestampBytes, 0, finalBytes, versionBytes.length, timestampBytes.length);
    System.arraycopy(initializationVector, 0, finalBytes, versionBytes.length + timestampBytes.length,
                initializationVector.length);
    System.arraycopy(cipherText, 0, finalBytes, versionBytes.length + timestampBytes.length
                + initializationVector.length, cipherText.length);

    byte[] signatureBytes = sha256Hmac.doFinal(finalBytes);
    return Hex.encodeHexString(signatureBytes);
}
