public void mergeFrom(FieldSet other) {
    for (Map.Entry<FieldDescriptor, Object> entry : other.fields.entrySet()) {
        FieldDescriptor field = entry.getKey();
        Object value = entry.getValue();

        if (field.isRepeated()) {
            for (Object element : (List<?>) value) {
                this.addRepeatedField(field, element);
            }
        } else if (field.getType() == FieldDescriptor.Type.MESSAGE) {
            Message existingValue = (Message) this.fields.get(field);
            if (existingValue == null) {
                this.fields.put(field, value);
            } else {
                this.fields.put(field, existingValue.toBuilder().mergeFrom((Message) value).build());
            }
        } else {
            this.fields.put(field, value);
        }
    }
}
