public Set<Object> transformFunction(Set<Object> B, Set<Object> A, Set<Object> C, Set<Object> gcis) {
    Set<Object> result = new HashSet<>();
    for (Object r : gcis) {
        if (B.contains(r)) {
            boolean foundA = false;
            for (Object a : A) {
                if (a.equals(r)) {
                    foundA = true;
                    break;
                }
            }
            if (foundA) {
                for (Object c : C) {
                    if (!c.equals(r)) {
                        result.add(c);
                    }
                }
            }
        }
    }
    return result;
}
