public String createSelectCriteria(Map<String, Object> valueMap) {
    StringBuilder selectCriteria = new StringBuilder();
    boolean first = true;
    for (Map.Entry<String, Object> entry : valueMap.entrySet()) {
        if (first) {
            selectCriteria.append("WHERE ");
            first = false;
        } else {
            selectCriteria.append("AND ");
        }
        selectCriteria.append(entry.getKey()).append("=").append(entry.getValue()).append(" ");
    }
    return selectCriteria.toString();
}
