import com.airbrake.AirbrakeNotice;
import com.airbrake.AirbrakeNotifier;

public class AirbrakeExceptionReporter {

    private AirbrakeNotifier notifier;

    public AirbrakeExceptionReporter(String apiKey) {
        notifier = new AirbrakeNotifier(apiKey);
    }

    public void reportAsync(Throwable ex) {
        Thread t = new Thread(() -> {
            try {
                AirbrakeNotice notice = new AirbrakeNotice(ex);
                notifier.notifyAsync(notice);
            } catch (Exception e) {
                // log or print the error
            }
        });
        t.start();
    }

}
