public void updateSubscriptions(Map<String, Set<String>> subscriptionsByEventType, String eventType, String subscriberId, boolean subscribe) {
    if (subscriptionsByEventType.containsKey(eventType)) {
        Set<String> subscribers = subscriptionsByEventType.get(eventType);
        if (subscribe) {
            subscribers.add(subscriberId);
        } else {
            subscribers.remove(subscriberId);
        }
    } else {
        if (subscribe) {
            Set<String> subscribers = new HashSet<>();
            subscribers.add(subscriberId);
            subscriptionsByEventType.put(eventType, subscribers);
        }
    }
}
