import java.awt.color.ColorSpace;
import java.awt.image.BufferedImage;
import java.awt.image.ColorModel;
import java.io.IOException;
import java.io.InputStream;

import javax.imageio.ImageIO;
import javax.imageio.ImageReader;
import javax.imageio.metadata.IIOMetadata;
import javax.imageio.metadata.IIOMetadataNode;
import javax.imageio.stream.ImageInputStream;

public static String[] decodeImage(InputStream is) {
    try {
        ImageInputStream iis = ImageIO.createImageInputStream(is);
        ImageReader reader = ImageIO.getImageReaders(iis).next();
        reader.setInput(iis, true);
        IIOMetadata metadata = reader.getImageMetadata(0);

        int width = -1;
        int height = -1;
        ColorSpace colorSpace = null;

        IIOMetadataNode dimensionNode = (IIOMetadataNode) metadata.getAsTree("javax_imageio_1.0/dimension");
        if (dimensionNode != null) {
            width = Integer.parseInt(dimensionNode.getAttribute("PixelWidth"));
            height = Integer.parseInt(dimensionNode.getAttribute("PixelHeight"));
        }

        IIOMetadataNode colorSpaceNode = (IIOMetadataNode) metadata.getAsTree("javax_imageio_1.0/ColorSpace");
        if (colorSpaceNode != null) {
            String csType = colorSpaceNode.getAttribute("name");
            if (csType != null && !csType.equals("java.awt.color.ICC_ColorSpace")) {
                switch (csType) {
                    case "java.awt.color.RGBColorSpace":
                        colorSpace = ColorSpace.getInstance(ColorSpace.CS_sRGB);
                        break;
                    case "java.awt.color.ICC_ColorSpace":
                        break;
                    default:
                        colorSpace = null;
                        break;
                }
            }
        }

        if (width == -1 || height == -1) {
            return null; // couldn't determine the size
        }

        ColorModel colorModel = null;
        try {
            colorModel = reader.getColorModel(0);
        } catch (IOException e) {
            // ignore.
        }

        BufferedImage bi = null;
        try {
            bi = reader.read(0);
        } catch (IOException e) {
            // ignore.
        }

        if (bi == null || colorModel == null) {
            return null; // couldn't read the image
        }

        return new String[]{String.valueOf(width), String.valueOf(height), String.valueOf(colorSpace)};
    } catch (IOException e) {
        return null;
    }
}
