public static Class<?> bindNativeType(String nameHint) {
    if (nameHint == null) {
        return void.class;
    } else if (nameHint.equals("ushort*") || nameHint.equals("wchar_t*")) {
        return short[].class;
    } else if (nameHint.equals("char*") || nameHint.equals("LPSTR")) {
        return byte[].class;
    } else if (nameHint.equals("unsigned char*") || nameHint.equals("BYTE*") || nameHint.equals("LPBYTE")) {
        return unsignedByte[].class;
    } else if (nameHint.equals("short*") || nameHint.equals("LPWORD")) {
        return short[].class;
    } else if (nameHint.equals("int*") || nameHint.equals("LONG*") || nameHint.equals("SYSINT*")) {
        return int[].class;
    } else if (nameHint.equals("uint*") || nameHint.equals("DWORD*") || nameHint.equals("ULONG*") || nameHint.equals("UINT*")) {
        return long[].class;
    } else if (nameHint.equals("LONGLONG*")) {
        return long[].class;
    } else if (nameHint.equals("ULONGLONG*")) {
        return BigInteger[].class;
    } else if (nameHint.equals("float*")) {
        return float[].class;
    } else if (nameHint.equals("double*")) {
        return double[].class;
    } else if (nameHint.equals("BOOL*")) {
        return boolean[].class;
    } else if (nameHint.equals("HANDLE")) {
        return Pointer.class;
    } else if (nameHint.equals("LPCWSTR") || nameHint.equals("PCWSTR")) {
        return WString.class;
    } else if (nameHint.equals("BSTR")) {
        return WString.class;
    } else if (nameHint.equals("LPWSTR") || nameHint.equals("PWSTR")) {
        return WString.class;
    } else if (nameHint.equals("GUID*")) {
        return GUID.class;
    } else if (nameHint.startsWith("struct ")) {
        try {
            String className = nameHint.substring("struct ".length());
            return Class.forName(className);
        } catch (ClassNotFoundException ex) {
            throw new IllegalArgumentException("Structure class not found: " + nameHint);
        }
    } else {
        throw new IllegalArgumentException("Unsupported native type name: " + nameHint);
    }
}
