public boolean isInsideImage(BufferedImage b, int x, int y, int radius) {
    int border = radius; // distance from the border
    int width = b.getWidth();
    int height = b.getHeight();

    // check if point is inside the image
    if ((x >= border) && (x < width - border) && (y >= border) && (y < height - border)) {
        return true;
    }

    return false;
}
