public static void destroyProcessGroup(int pgrpId, int interval, boolean inBackground) {
    try {
        if (inBackground) {
            Thread killThread = new Thread(() -> {
                try {
                    ProcessBuilder pb = new ProcessBuilder("kill", "-TERM", "-" + pgrpId);
                    Process process = pb.start();
                    process.waitFor(interval, TimeUnit.SECONDS);
                    if (process.isAlive()) {
                        process.destroyForcibly();
                    }
                } catch (Exception ex) {
                    ex.printStackTrace();
                }
            });
            killThread.start();
        } else {
            ProcessBuilder pb = new ProcessBuilder("kill", "-TERM", "-" + pgrpId);
            Process process = pb.start();
            process.waitFor(interval, TimeUnit.SECONDS);
            if (process.isAlive()) {
                process.destroyForcibly();
            }
        }
    } catch (Exception ex) {
        ex.printStackTrace();
    }
}
