public List<Long> deriveRangesFromSlots(int slot, long referenceMillis) {
    List<Long> ranges = new ArrayList<>();
    int rangeStart = slot;
    for (int i = 0; i < 24; i++) {
        if (rangeStart == slot && i > 0) {
            break;
        }
        ranges.add((long) ((rangeStart - slot) * 1000 + referenceMillis));
        rangeStart = (rangeStart + 1) % 24;
    }
    return ranges;
}
