public List<String> convertStringArrayToStringList(String[] arr, int from, int len) {
    List<String> stringList = new ArrayList<>();
    if (arr == null || from < 0 || len < 0 || from >= arr.length) {
        return stringList;
    }
    int to = Math.min(from + len, arr.length);
    for (int i = from; i < to; i++) {
        stringList.add(arr[i]);
    }
    return stringList;
}
