public void buildType(StringBuilder builder, Class<?> cls) {
  if (cls.isArray()) { // if it's an array
    builder.append("["); // append [
    buildType(builder, cls.getComponentType()); // add component type
    builder.append("]"); // append ]
  } else if (cls.isPrimitive()) { // if it's a primitive type
    builder.append(cls.getName()); // append type name
  } else { // if it's a class
    builder.append("L").append(cls.getName().replace(".", "/")).append(";"); // append class name
  }
}
