public static void extractRichText(Node node, StringBuilder builder) {
    if (node.getNodeType() == Node.TEXT_NODE) {
        builder.append(node.getNodeValue());
    } else if (node.getNodeType() == Node.ELEMENT_NODE) {
        String tagName = node.getNodeName().toLowerCase();
        if (tagName.equals("b") || tagName.equals("strong")) {
            builder.append("<b>");
            extractRichText(node.getFirstChild(), builder);
            builder.append("</b>");
        } else if (tagName.equals("i") || tagName.equals("em")) {
            builder.append("<i>");
            extractRichText(node.getFirstChild(), builder);
            builder.append("</i>");
        } else if (tagName.equals("u")) {
            builder.append("<u>");
            extractRichText(node.getFirstChild(), builder);
            builder.append("</u>");
        } else if (tagName.equals("br")) {
            builder.append("<br/>");
        } else {
            NodeList children = node.getChildNodes();
            for (int i = 0; i < children.getLength(); i++) {
                extractRichText(children.item(i), builder);
            }
        }
    }
}
