public Instruction getPredecessor(Instruction handle) {
    BasicBlock basicBlock = handle.getParent();
    InstructionList instructions = basicBlock.getInstructions();
    int index = instructions.indexOf(handle);
    if (index > 0) {
        return instructions.get(index - 1);
    } else {
        return null;
    }
}
