public void writeObjectsWithoutLockRelease(Connection connection, List<Object> objects) throws SQLException {
    try {
        connection.setAutoCommit(false); // start a transaction
        for (Object obj : objects) {
            // assuming 'objects' is a collection of custom objects with fields that match the database schema
            PreparedStatement statement = connection.prepareStatement("UPDATE objects SET field1=?, field2=?, ... WHERE id=?");
            statement.setXXX(...); // set the parameters of the statement for the current object
            statement.setInt(...); // assuming 'id' is an integer primary key
            statement.executeUpdate();
        }
        connection.commit(); // commit the transaction to release the locks
    } catch (SQLException ex) {
        connection.rollback(); // rollback the transaction if there is an error and don't release the locks
        throw ex;
    }
}
