public void addMungedImports(String pattern, Map<String, String> replacePairs) {
    List<String> imports = getImports();
    for (int i = imports.size() - 1; i >= 0; i--) {
        if (imports.get(i).matches(pattern)) {
            String newImport = imports.get(i);
            for (Map.Entry<String, String> replacePair : replacePairs.entrySet()) {
                newImport = newImport.replaceAll(replacePair.getKey(), replacePair.getValue());
            }
            imports.add(i + 1, newImport);
        }
    }
    setImports(imports);
}
