import java.util.ArrayList;
import java.util.List;

public List compileMethodsToList(Stack<String> importStack, Object object) {
    List callbacks = new ArrayList();
    // Iterate through all methods in the object
    for (Method method : object.getClass().getDeclaredMethods()) {
        // Check if the method has the necessary annotations and parameters
        if (method.isAnnotationPresent(SassFunction.class) && method.getParameterCount() >= 1 && 
                method.getParameterTypes()[0] == SassContext.class) {
            try {
                // Create a new SassFunctionDefinition and add it to the list of callbacks
                callbacks.add(new SassFunctionDefinition(method, object, importStack));
            } catch (IllegalAccessException e) {
                e.printStackTrace();
            }
        }
    }
    return callbacks;
}
