@Override
public Map<String, List<Enhancement>> parseEntityAnnotations(Element entityElem) {
    Map<String, List<Enhancement>> enhancementsMap = new HashMap<>();
    Elements eElements = entityElem.select("enhancement");
    for (Element eElem : eElements) {
        String eType = eElem.attr("class");
        List<Enhancement> eList = new ArrayList<>();
        Elements valueElements = eElem.select("value");
        for (Element valueElem : valueElements) {
            String valueStr = valueElem.text();
            Attribute[] attrs = valueElem.attributes().asList().stream().map(attr -> new Attribute(attr.getKey(), attr.getValue()))
                    .toArray(size -> new Attribute[size]);
            Enhancement enhancement = new Enhancement(valueStr, attrs, eType);
            eList.add(enhancement);
        }
        enhancementsMap.put(eType, eList);
    }
    return enhancementsMap;
