public static BezierCurve createBezierFunction(List<Point> controlPoints) {
    int n = controlPoints.size() - 1;
    double[][] bernsteinMatrix = new double[n + 1][n + 1];
    for (int i = 0; i <= n; i++) {
        int k = n - i;
        for (int j = 0; j <= i; j++) {
            bernsteinMatrix[j][k] = binomial(i, j) * Math.pow(-1, k);
        }
    }
    double[] xCoefficients = new double[n + 1];
    double[] yCoefficients = new double[n + 1];
    for (int i = 0; i <= n; i++) {
        xCoefficients[i] = controlPoints.get(i).getX();
        yCoefficients[i] = controlPoints.get(i).getY();
    }
    double[] xValues = Matrix.multiply(bernsteinMatrix, xCoefficients);
    double[] yValues = Matrix.multiply(bernsteinMatrix, yCoefficients);
    return new BezierCurve(xValues, yValues);
}

private static int binomial(int n, int k) {
    if (k == 0) {
        return 1;
    } else if (k > n / 2) {
        return binomial(n, n - k);
    } else {
        return (int) ((n - k + 1) / (double) k * binomial(n, k - 1));
    }
}
