public boolean removeAttributeIgnoreCase(String attName) {
    boolean removed = false;
    for (Iterator<String> it = attributes.keySet().iterator(); it.hasNext();) {
        String key = it.next();
        if (key.equalsIgnoreCase(attName)) {
            it.remove();
            removed = true;
            break;
        }
    }
    return removed;
}
