public static void writeBits(int b, int n) throws IOException {
    if (n < 1 || n > Integer.SIZE) {
        throw new IllegalArgumentException("Invalid number of bits!");
    }

    for (int i = n - 1; i >= 0; i--) {
        int mask = 1 << i;
        int bit = (b & mask) >>> i;
        System.out.print(bit);
    }
}
