public String getBindingName(Annotation annotation) {
    if (annotation != null) {
        // Check if the annotation is a marker annotation or just an annotation type
        if (annotation.annotationType().getDeclaredMethods().length == 0) {
            // Use the annotation's name for marker annotations
            return annotation.annotationType().getSimpleName();
        } else {
            // Ask the annotation for its toString for non-marker annotations with an instance.
            return annotation.toString();
        }
    } else {
        // If the annotation is null, return empty string
        return "";
    }
}
