public int getPrimitiveDataSize(TreeNode node) {
    int size = 0;

    if (node.getData() instanceof Integer) {
        size += Integer.BYTES;
    } else if (node.getData() instanceof Double) {
        size += Double.BYTES;
    } else if (node.getData() instanceof Float) {
        size += Float.BYTES;
    } else if (node.getData() instanceof Long) {
        size += Long.BYTES;
    } else if (node.getData() instanceof Short) {
        size += Short.BYTES;
    } else if (node.getData() instanceof Byte) {
        size += Byte.BYTES;
    } else if (node.getData() instanceof Boolean) {
        size += 1; // Boolean uses 1 byte
    } else if (node.getData() instanceof Character) {
        size += Character.BYTES;
    }

    // recursively check the size of child nodes
    for (TreeNode child : node.getChildren()) {
        size += getPrimitiveDataSize(child);
    }

    return size;
}
