public void commitOffsets(String groupId, List<TopicPartition> tpoList, KafkaConsumer consumer) {
    Map<TopicPartition, OffsetAndMetadata> offsets = new HashMap<>();
    for (TopicPartition tpo : tpoList) {
        long offset = consumer.position(tpo);
        offsets.put(tpo, new OffsetAndMetadata(offset));
    }
    consumer.commitSync(offsets);
}
