                        propertyValuesHolderX,
                        propertyValuesHolderAlpha).setDuration(SHOW_DURATION);
            case Style.ANIMATIONS_SCALE:
                final PropertyValuesHolder propertyValuesHolderScaleX = PropertyValuesHolder
                        .ofFloat(SCALE_X, 0f, 1f);
