private void bufferWrite(ChannelHandlerContext ctx, Object msg, ChannelPromise promise) {
    if (writeInProgress) {
        pendingWrites.add(new PendingWrite(ctx, msg, promise));
    } else {
        writeInProgress = true;
        ctx.write(msg, promise).addListener(future -> {
            if (!future.isSuccess()) {
                bufferFailed = true;
                writeInProgress = false;
                flushPendingWrites(ctx);
            } else {
                pendingPromise = promise;
            }
        });
    }
}
