public Set<String> findMatchDifferences(Set<String> inputMatches, Set<String> inputMatchesAlt) {
    Set<String> differences = new HashSet<>();
    for (String match : inputMatches) {
        if (!inputMatchesAlt.contains(match)) {
            differences.add(match);
        }
    }
    for (String match : inputMatchesAlt) {
        if (!inputMatches.contains(match)) {
            differences.add(match);
        }
    }
    return differences;
}
