public void inheritOwnerAndGroup(File file) {
    // Check if the file has both owner and group empty
    if (file.getOwner() == null && file.getGroup() == null) {
        // Get the parent directory of the file
        File parent = file.getParentFile();
        if (parent != null) { // Check if it has a parent
            // Inherit the owner and group from the parent directory
            file.setOwner(parent.getOwner());
            file.setGroup(parent.getGroup());
        }
    }
}
