public boolean checkColumnMappings(OldSchema oldSchema, NewSchema newSchema) {
    List<String> oldColumnMappings = oldSchema.getColumnMappings();
    List<String> newColumnMappings = newSchema.getColumnMappings();

    if (oldColumnMappings.size() != newColumnMappings.size()) {
        return false;
    }

    for (int i = 0; i < oldColumnMappings.size(); i++) {
        String oldMapping = oldColumnMappings.get(i);
        String newMapping = newColumnMappings.get(i);
        if (!oldMapping.equals(newMapping)) {
            return false;
        }
    }

    return true;
}
