public LoadBalancerFilter findLoadBalancers(List<String> names){
    Objects.requireNonNull(names, "Names list cannot be null");

    LoadBalancerFilter filter = new LoadBalancerFilter();
    for (LoadBalancer lb : loadBalancers) {
        for (String name : names) {
            if (lb.getName().toLowerCase().contains(name.toLowerCase())) {
                filter.addLoadBalancer(lb);
                break;
            }
        }
    }

    return filter;
}
