import org.json.JSONObject;
import org.apache.commons.lang3.reflect.FieldUtils;
import java.lang.reflect.Field;
import java.lang.reflect.InvocationTargetException;

public static<T> JSONObject convertToJSONObject(T t) throws IllegalAccessException, InstantiationException, InvocationTargetException {
    JSONObject jsonObject = new JSONObject();

    Field[] fields = FieldUtils.getAllFields(t.getClass());

    for (Field field : fields) {
        field.setAccessible(true);
        if (field.get(t) != null && !field.get(t).equals("") && !field.get(t).toString().isEmpty()) {
            jsonObject.put(field.getName(), field.get(t));
        }
    }

    return jsonObject;
}
