public List<String> findAttributes(Map<String, List<String>> patterns) {
    List<String> attributes = new ArrayList<>();
    boolean matchFound = false;

    for (Map.Entry<String, List<String>> entry : patterns.entrySet()) {
        List<String> patternAttributes = entry.getValue();

        if (matchFound) {
            break;
        }

        for (String attribute : patternAttributes) {
            if (attribute != null) {
                attributes.add(attribute);
                matchFound = true;
            }
        }
    }

    return attributes;
}
