import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.util.Properties;

public class PropertyFile {
    public Properties readProperties(String baseDir, Properties currentProperties, String key, boolean override) throws IOException {
        File dir = new File(baseDir);
        File[] directoryListing = dir.listFiles();
        if (directoryListing != null) {
            for (File child : directoryListing) {
                if (child.isFile() && child.getName().endsWith(".properties") && !child.getName().equals(key)) {
                    Properties property = new Properties();
                    property.load(new FileInputStream(child));
                    if (override) {
                        currentProperties.putAll(property);
                    } else {
                        currentProperties.putAll(property);
                    }
                } else if (child.isDirectory()) {
                    currentProperties = readProperties(child.getAbsolutePath(), currentProperties, key, override);
                }
            }
        } else {
            throw new IOException("Directory not found!");
        }
        return currentProperties;
    }
}
