public int getBytesRequired(Set set) {
    int bytes = 0;
    for (Object obj : set) {
        if (obj instanceof String) {
            bytes += ((String) obj).getBytes().length;
        } else if (obj instanceof Number) {
            int numBytes = ((Number) obj).toString().getBytes().length;
            bytes += (numBytes + 1); // Add one byte for the type identifier
        } else {
            throw new IllegalArgumentException("Unsupported type: " + obj.getClass().getName());
        }
    }
    return bytes;
}
