public String readContextPasswordFromXML(File xmlFile) {
    String password = null;
    String passwordType = null;
    try {
        DocumentBuilderFactory documentBuilderFactory = DocumentBuilderFactory.newInstance();
        DocumentBuilder documentBuilder = documentBuilderFactory.newDocumentBuilder();
        Document document = documentBuilder.parse(xmlFile);
        NodeList nodeList = document.getElementsByTagName("Password");

        Element element = (Element) nodeList.item(0);
        password = element.getTextContent();

        NamedNodeMap attr = element.getAttributes();
        if (attr != null) {
            Node nodeAttr = attr.getNamedItem("type");
            if (nodeAttr != null) {
                passwordType = nodeAttr.getNodeValue();
            }
        }
    } catch (ParserConfigurationException | SAXException | IOException e) {
        e.printStackTrace();
    }
    // you can save the password type for future use.
    return password;
}
