public class Container {

    private int height;
    private int levelHeight;

    public Container(int height, int levelHeight) {
        this.height = height;
        this.levelHeight = levelHeight;
    }

    public int[] calculateFreeSpace() {
        int freeHeight = height % levelHeight;
        int boxDimension = height / levelHeight;
        return new int[]{freeHeight, boxDimension};
    }

}
