public String executeCommand(String command, Map<String, String> environment, boolean backend) throws IOException {
    CommandLine cmdLine = CommandLine.parse(command);
    DefaultExecutor executor = new DefaultExecutor();
    if (environment != null) {
        executor.setEnvironment(toArray(environment));
    }
    if (backend) {
        executor.setStreamHandler(new PumpStreamHandler(null, null, null));
    }
    ByteArrayOutputStream output = new ByteArrayOutputStream();
    PumpStreamHandler streamHandler = new PumpStreamHandler(output);
    executor.setStreamHandler(streamHandler);
    int exitCode = executor.execute(cmdLine);
    if (exitCode != 0) {
        throw new IOException("Command execution failed with exit code " + exitCode);
    }
    return output.toString();
}

private static String[] toArray(Map<String, String> environment) {
    String[] array = new String[environment.size()];
    int i = 0;
    for (Map.Entry<String, String> entry : environment.entrySet()) {
        array[i++] = entry.getKey() + "=" + entry.getValue();
    }
    return array;
}
