private static Map<Class<?>, Exporter> exporters = new HashMap<>();

public static <T> Exporter<T> loadExporter(Class<T> clazz, boolean declaredFieldsOnly) {
    // If exporter has already been created, return it
    if (exporters.containsKey(clazz)) {
        return (Exporter<T>) exporters.get(clazz);
    }

    // Otherwise create a new exporter
    Exporter<T> exporter = new Exporter<>(clazz, declaredFieldsOnly);
    exporters.put(clazz, exporter);
    return exporter;
}
