public Image createImage(Color foreground, Color background) throws IOException {
    // If generate() method is not called before this method, throw an exception
    if(!isGenerated){
        throw new IOException("Generate method was not called before createImage method");
    }
    Image image = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
    Graphics2D g2d = (Graphics2D) image.getGraphics();
    // Draw the background color
    g2d.setColor(background);
    g2d.fillRect(0, 0, width, height);
    // Draw the foreground color
    g2d.setColor(foreground);
    // Draw the bars
    for (int i = 0; i < barcode.length(); i++) {
        if (barcode.charAt(i) == '1') {
            g2d.fillRect(i * barWidth, 0, barWidth, height);
        } 
    }
    return image;
}
