public boolean traversePreorder(NodeVisitor nodeVisitor, EdgeVisitor edgeVisitor, Node node) {
    Stack<Node> stack = new Stack<>();
    Set<Node> visited = new HashSet<>();

    stack.push(node);

    while (!stack.empty()) {
        node = stack.pop();
        if (!visited.contains(node)) {
            visited.add(node);
            if (nodeVisitor != null) {
                boolean cont = nodeVisitor.visit(node);
                if (!cont) {
                    return false;
                }
            }
            for (Edge e : node.edges) {
                if (edgeVisitor != null) {
                    boolean cont = edgeVisitor.visit(e);
                    if (!cont) {
                        return false;
                    }
                }
                stack.push(e.to);
            }
        }
    }
    return true;
}
