public static boolean isPrimitiveFieldDefault(Object object, Field field) throws IllegalAccessException {
    if (field.getType().isPrimitive()) {
        field.setAccessible(true);
        Object value = field.get(object);
        switch (field.getType().getName()) {
            case "boolean":
                return !(boolean) value;
            case "byte":
                return (byte) value == 0;
            case "short":
                return (short) value == 0;
            case "int":
                return (int) value == 0;
            case "long":
                return (long) value == 0L;
            case "float":
                return (float) value == 0F;
            case "double":
                return (double) value == 0D;
        }
    }
    return false;
}
