public void insertToDecisionHeap(int x) {
    // insert the variable at the end of the heap
    decisionHeap.add(x);

    // move the variable up the heap until it satisfies the heap property
    int currentIndex = decisionHeap.size() - 1;
    while (currentIndex > 0) {
        int parentIndex = (currentIndex - 1) / 2;
        if (decisionHeap.get(currentIndex) > decisionHeap.get(parentIndex)) {
            Collections.swap(decisionHeap, currentIndex, parentIndex);
            currentIndex = parentIndex;
        } else {
            break;
        }
    }
}
