public boolean isSelinuxEnforced() {
    ProcessBuilder processBuilder = new ProcessBuilder("getenforce");
    Process process;

    try {
        process = processBuilder.start();
    } catch (IOException e) {
        e.printStackTrace();
        return false;
    }

    BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
    String line;
    try {
        while ((line = reader.readLine()) != null) {
            if (line.equals("Enforcing")) {
                return true;
            }
        }
    } catch (IOException e) {
        e.printStackTrace();
        return false;
    }

    return false;
}
