public static <T> T getMostCommonElementInList(List<T> list) {
    if (list == null || list.isEmpty()) {
        return null;
    }

    Map<T, Integer> elementCounts = new HashMap<>();
    int maxCount = 0;

    for (T element : list) {
        int count = elementCounts.getOrDefault(element, 0) + 1;
        elementCounts.put(element, count);
        if (count > maxCount) {
            maxCount = count;
        }
    }

    List<T> mostCommonElements = new ArrayList<>();
    for (Map.Entry<T, Integer> entry : elementCounts.entrySet()) {
        if (entry.getValue() == maxCount) {
            mostCommonElements.add(entry.getKey());
        }
    }

    if (mostCommonElements.contains(null)) {
        return null;
    }

    return mostCommonElements.get(0);
}
