public Integer findIndex(String editorAttribute, String editorEntityType, List<String> lookupAttributes) {
    for (int i = 0; i < lookupAttributes.size(); i++) {
        String lookupAttribute = lookupAttributes.get(i);
        if (lookupAttribute != null && lookupAttribute.equalsIgnoreCase(editorAttribute) && editorEntityType != null) {
            int entityTypeStartIndex = lookupAttribute.indexOf(editorEntityType);
            if (entityTypeStartIndex != -1 && entityTypeStartIndex < lookupAttribute.length() - editorEntityType.length()) {
                char prefix = lookupAttribute.charAt(entityTypeStartIndex - 1);
                if (!Character.isLetterOrDigit(prefix)) {
                    return i;
                }
            }
        }
    }
    return null;
}
