public String waitForMenuItemPress(String menuItemText) {
    while (true) {
        try {
            EventQueue eventQueue = Toolkit.getDefaultToolkit().getSystemEventQueue();
            AWTEvent event = eventQueue.getNextEvent();
            if (event instanceof MenuItemEvent) {
                MenuItemEvent menuItemEvent = (MenuItemEvent) event;
                if (menuItemEvent.getID() == MenuItemEvent.ITEM_STATE_CHANGED) {
                    MenuItem item = (MenuItem) menuItemEvent.getSource();
                    if (item.getLabel().equals(menuItemText)) {
                        return menuItemText;
                    }
                }
            }
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
    }
}
