public boolean shouldShowChangelogActivity(Context ctx, int configId) {
    SharedPreferences prefs = PreferenceManager.getDefaultSharedPreferences(ctx);
    int previousVersion = prefs.getInt("config_version", -1);
    int currentVersion = ctx.getResources().getInteger(configId);

    if (previousVersion < currentVersion) {
        SharedPreferences.Editor editor = prefs.edit();
        editor.putInt("config_version", currentVersion);
        editor.commit();
        return true;
    } else {
        return false;
    }
}
