protected String getPairPunctuationText( int c ) throws IOException 
    {

        isb.clear();
        char echar = StringUtil.getPunctuationPair( (char) c);
        boolean matched = false;
        int j, ch;



        ialist.clear();

        for ( j = 0; j < config.PPT_MAX_LENGTH; j++ ) {
            ch = readNext();
            if ( ch == -1 ) break;
            if ( ch == echar ) {
                matched = true;
                pushBack(ch);         
                break;
            }

            isb.append( (char) ch );
            ialist.add(ch);
        }

        if ( matched == false ) {
            for ( int i = j - 1; i >= 0; i-- ) 
                pushBack( ialist.get(i) );
            return null;
        }

        return isb.toString();
    }


