import java.net.Authenticator;
import java.net.PasswordAuthentication;
import java.net.Proxy;
import java.net.InetSocketAddress;
import java.net.SocketAddress;

public static void setSocks4Proxy(String ipAddress, int port, String user) {
    final String proxyHost = ipAddress;
    final int proxyPort = port;
    final String proxyUser = user;

    Authenticator.setDefault(new Authenticator() {
        @Override
        protected PasswordAuthentication getPasswordAuthentication() {
            if (getRequestorType() == RequestorType.PROXY) {
                // If using SOCKS4, username is not required
                return new PasswordAuthentication(proxyUser, new char[]{});
            }
            return null;
        }
    });

    SocketAddress addr = new InetSocketAddress(proxyHost, proxyPort);
    Proxy proxy = new Proxy(Proxy.Type.SOCKS, addr);
    Proxy.setDefault(proxy);
}
