public WebSocket flush()
    {
        synchronized (mStateManager)
        {
            WebSocketState state = mStateManager.getState();
            if (state != OPEN && state != CLOSING)
            {
                return this;
            }
        }

        WritingThread wt = mWritingThread;

        if (wt != null)
        {

            wt.queueFlush();
        }
        return this;
