public String getRelativePathToPom(File moduleDir) {
    File pomFile = new File(moduleDir, "pom.xml");
    String basePath = pomFile.getParentFile().getParentFile().getAbsolutePath();
    String modulePath = moduleDir.getAbsolutePath();
    String relativePath = modulePath.substring(basePath.length() + 1);
    return relativePath.replace(File.separatorChar, '/');
}
