public static short[] convertToHalfPrecision(int typeSrc, float[] source, int typeDst) {
    int srcLength = source.length;
    short[] dest = new short[srcLength];

    for (int i = 0; i < srcLength; ++i) {
        float srcValue = source[i];

        if (typeSrc == Types.FLOAT) {
            srcValue = (float) convertDoubleToFloat(srcValue);
        }

        int fbits = Float.floatToIntBits(srcValue);
        int sign = (fbits >> 16) & 0x8000;
        int val = (fbits & 0x7fffffff) + 0x1000;

        if (val >= 0x47800000) {
            if ((fbits & 0x7fffffff) >= 0x47800000) {
                if (val < 0x7f800000) {
                    dest[i] = (short) (sign | 0x7c00);
                } else if (val == 0x7f800000 && (fbits & 0x007fffff) != 0) {
                    dest[i] = (short) (sign | 0x7c00 | (fbits & 0x007fffff) >> 13);
                } else {
                    dest[i] = (short) (sign | 0x7c00);
                }
            } else {
                dest[i] = (short) ((sign | 0x7bff) + ((val >>> 13) & 0x7c00) + ((val >>> 13) & 0x03ff));
            }
        } else if (val >= 0x38800000) {
            dest[i] = (short) ((sign | (val - 0x38000000) >>> 13) & 0x7fff);
        } else if (val == 0x800000) {
            dest[i] = (short) (sign | 0x0000);
        } else {
            dest[i] = (short) sign;
        }

        if (typeDst == Types.FLOAT) {
            dest[i] = (short) convertFloatToDouble(dest[i]);
        }
    }
    return dest;
}

private static double convertFloatToDouble(short hbits) {
    int mant = hbits & 0x03ff;
    int exp = (hbits & 0x7c00) >>> 10;
    if (exp == 0) {
        exp = -1022;
    } else if (exp == 0x1f) {
        return mant != 0 ? Double.NaN : ((hbits & 0x8000) != 0) ? Double.NEGATIVE_INFINITY : Double.POSITIVE_INFINITY;
    } else {
        mant |= 0x0400;
        exp += -15;
    }
    long bits = ((hbits & 0x8000) << 48) | ((exp + 1023L) << 52) | ((long) mant << 42);
    return Double.longBitsToDouble(bits);
}

private static float convertDoubleToFloat(float fval) {
    int fbits = Float.floatToIntBits(fval);
    int sign = (fbits >> 16) & 0x8000;
    int val = (fbits & 0x7fffffff) + 0x1000;

    if (val >= 0x47800000) {
        if ((fbits & 0x7fffffff) >= 0x47800000) {
            if (val < 0x7f800000) {
                return Float.intBitsToFloat(sign | 0x7c000000);
            } else if (val == 0x7f800000 && (fbits & 0x007fffff) != 0) {
                return Float.intBitsToFloat((sign | 0x7c000000) | ((fbits & 0x007fffff) >> 13));
            } else {
                return Float.intBitsToFloat(sign | 0x7f800000);
            }
        } else {
            return Float.intBitsToFloat((sign | (val >>> 13)) + ((val >>> 13) & 0x003ff));
        }
    } else if (val >= 0x38800000) {
        return Float.intBitsToFloat((sign | (val - 0x38000000) >>> 13));
    } else if (val == 0x800000) {
        return Float.intBitsToFloat(sign | 0x00000000);
    } else {
        return Float.intBitsToFloat(sign | val);
    }
}
