public static void generateFunction(Class<? extends Exception> declaredExceptionClass, Class<? extends RuntimeException> wrapperExceptionClass) throws RuntimeException, Error, Exception {
    try {
        // Some code that can throw different types of exceptions
    } catch (RuntimeException e) {
        throw e;
    } catch (Error e) {
        throw e;
    } catch (Exception e) {
        if (declaredExceptionClass.isInstance(e)) {
            throw e;
        } else {
            throw wrapperExceptionClass.getConstructor(Throwable.class).newInstance(e);
        }
    }
}
