public static String formatVertex(Vertex vertex) {
    if (vertex == null) {
        return null;
    }
    String id = String.format("id:%d", vertex.getId());
    String props = vertex.getProperties()
            .entrySet()
            .stream()
            .map(entry -> entry.getKey() + ":" + entry.getValue())
            .collect(Collectors.joining(", "));
    return String.format("{%s, %s}", id, props);
}
