public void replaceFunctionCalls(JCas jcas) {
    String regex = "@TIMEX-[1-9][0-9]*";
    Pattern pattern = Pattern.compile(regex);
    Matcher matcher = pattern.matcher(jcas.getDocumentText());
    while (matcher.find()) {
        String timexValue = getTimexValue(matcher.group());
        int start = matcher.start();
        int end = matcher.end();
        jcas.getCas().removeAnnotation(jcas.getCas().createAnnotation(TypeSystemUtils.getType(jcas.getCas(), "uima.tcas.Annotation"), start, end));
        jcas.getCas().addFsToIndexes(jcas.getCas().createStringAnnotation(TypeSystemUtils.getType(jcas.getCas(), "uima.tcas.DocumentAnnotation"), start, end, timexValue));
    }
}

private static String getTimexValue(String timex) {
    String prefix = "@TIMEX-";
    int id = Integer.parseInt(timex.substring(prefix.length()));
    switch (id) {
        case 1:
            return "PRESENT_REF";
        case 2:
            return "PAST_REF";
        case 3:
            return "FUTURE_REF";
        default:
            throw new IllegalArgumentException("Invalid TIMEX id: " + id);
    }
}
