import com.esri.core.geometry.;

public static Geometry computeSingleSideBuffer(Geometry geometry, double distance) {
   // Create a spatial reference object with the default parameters
   SpatialReference spatialRef = SpatialReference.create(3857);

   // Create a buffer parameters object with the default parameters
   BufferParameters bufferParameters = new BufferParameters();
   bufferParameters.setSpatialReference(spatialRef);
   bufferParameters.setEndType(BufferParameters.EndType.ROUND);
   bufferParameters.setJoinType(BufferParameters.JoinType.ROUND);
   bufferParameters.setMiterLimit(2.0);

   // Compute the single side buffer
   Geometry bufferGeometry = GeometryEngine.buffer(geometry, spatialRef, distance, bufferParameters);
   return bufferGeometry;
}
