public Object[] getPreparedParamValues(ControlBeanContext context, Method method, Object[] args) {
    String methodName = method.getName();
    Annotation[][] parameterAnnotations = method.getParameterAnnotations();
    Object[] parameterValues = null;

    for(int i = 0; i < parameterAnnotations.length; i++) {
        for(Annotation annotation : parameterAnnotations[i]) {
            if(annotation.annotationType().equals(PreparedParam.class)) {
                if(parameterValues == null) {
                    parameterValues = new Object[parameterAnnotations.length];
                }
                parameterValues[i] = args[i];
            }
        }
    }

    return parameterValues;
}
