import com.lowagie.text.Element;
import com.lowagie.text.Phrase;
import com.lowagie.text.exceptions.VectorPrintException;
import com.lowagie.text.pdf.PdfPCell;
import java.util.Collection;

public class CellCreator {

    public PdfPCell createAndStyleCell(Object data, Collection<Styler> stylers) throws VectorPrintException {

        PdfPCell cell = new PdfPCell();
        if (data instanceof Element) {
            cell.addElement((Element) data);
        } else {
            cell.setPhrase(createPhrase(data, stylers));
        }
        for (Styler styler : stylers) {
            styler.applyStyle(cell);
        }
        return cell;
    }

    private Phrase createPhrase(Object data, Collection<Styler> stylers) {
        Phrase phrase = new Phrase(data.toString());
        for (Styler styler : stylers) {
            styler.applyStyle(phrase);
        }
        return phrase;
    }
}
