public void handleSocks4Response(ByteBuffer buf) throws Exception {
    byte[] response = new byte[8];
    buf.get(response);

    if (response[0] != 0x00 || response[1] != 0x5a) {
        throw new Exception("Socks4 response not granted");
    }

    int port = ((response[2] & 0xff) << 8) | (response[3] & 0xff);
    if (port < 0 || port > 0xFFFF) {
        throw new Exception("Invalid Socks4 response port");
    }

    int ipAddress = ((response[4] & 0xff) << 24) | ((response[5] & 0xff) << 16) |
                    ((response[6] & 0xff) << 8) | (response[7] & 0xff);

    // Handle SOCKS4a response by reading the null-terminated hostname
    if (ipAddress == 0x00000000 && response[3] == 0x00) {
        while (buf.hasRemaining()) {
            byte b = buf.get();
            if (b == 0x00) {
                break;
            }
        }
    }

    setHandshakeComplete();
}
