public class UglyJUnit5Workaround {

    public static Object[] getArgumentsFromContext(Object testInstance, Method testMethod) throws Exception {
        Object testClassInstance = null;

        // find test class instance
        for (Class<?> clazz : testInstance.getClass().getClasses()) {
            if (clazz.getSimpleName().equals("TestClass")) {
                testClassInstance = clazz.newInstance();
                break;
            }
        }

        // find test method in test class
        Method testClassMethod = null;
        for (Method m : testClassInstance.getClass().getDeclaredMethods()) {
            if (m.getName().equals(testMethod.getName())) {
                testClassMethod = m;
                break;
            }
        }

        // get argument values
        Object[] arguments = new Object[testMethod.getParameterCount()];
        int i = 0;
        for (String parameterName : Arrays.asList(testClassMethod.getParameters())) {
            arguments[i++] = testClassMethod.getParameters()[i].get(testInstance);
        }
        return arguments;
    }
}
