public static Object unmarshalXmlPayload(String payload) throws JAXBException, IOException {
    JAXBContext context = JAXBContext.newInstance(Object.class);
    Unmarshaller unmarshaller = context.createUnmarshaller();
    StringReader reader = new StringReader(payload);
    Object unmarshalledObject = unmarshaller.unmarshal(reader);
    if (unmarshalledObject instanceof JAXBElement) {
        unmarshalledObject = ((JAXBElement) unmarshalledObject).getValue();
    }
    return unmarshalledObject;
}

public static Object unmarshalXmlPayload(byte[] payload) throws JAXBException, IOException {
    JAXBContext context = JAXBContext.newInstance(Object.class);
    Unmarshaller unmarshaller = context.createUnmarshaller();
    ByteArrayInputStream stream = new ByteArrayInputStream(payload);
    Object unmarshalledObject = unmarshaller.unmarshal(stream);
    if (unmarshalledObject instanceof JAXBElement) {
        unmarshalledObject = ((JAXBElement) unmarshalledObject).getValue();
    }
    return unmarshalledObject;
}
