import java.util.*;

public class MyClass {

  public static <T> Stream<T> createStream(T root, List<Tuple<T,T>> edges){
    // implementation of the function
    Map<T, List<T>> graph = new HashMap<>();
    for (Tuple<T,T> edge : edges) {
        T u = edge.getLeft();
        T v = edge.getRight();
        graph.computeIfAbsent(u, x -> new ArrayList<>()).add(v);
        graph.computeIfAbsent(v, x -> new ArrayList<>()).add(u);
    }
    return dfs(root, graph, new HashSet<>());
  }

  private static <T> Stream<T> dfs(T node, Map<T, List<T>> graph, Set<T> visited) {
    visited.add(node);
    List<T> neighbors = graph.get(node);
    return Stream.concat(Stream.of(node), 
        neighbors == null ? Stream.empty() : neighbors.stream()
            .filter(neighbor -> !visited.contains(neighbor))
            .flatMap(neighbor -> dfs(neighbor, graph, visited)));
  }
}

class Tuple<L, R> {
  private final L left;
  private final R right;

  public Tuple(L left, R right) {
    this.left = left;
    this.right = right;
  }

  public L getLeft() { return left; }
  public R getRight() { return right; }

  @Override
  public boolean equals(Object o) {
    if (this == o) return true;
    if (o == null || getClass() != o.getClass()) return false;
    Tuple<?, ?> tuple = (Tuple<?, ?>) o;
    return Objects.equals(left, tuple.left) &&
        Objects.equals(right, tuple.right);
  }

  @Override
  public int hashCode() {
    return Objects.hash(left, right);
  }
}
