import java.util.*;

public class ListSortAndCompare {

    public static boolean compareLists(List<String[]> expected, List<String[]> computed, int col) {
        sortList(expected, col);
        sortList(computed, col);
        return Arrays.deepEquals(expected.toArray(), computed.toArray());
    }

    private static void sortList(List<String[]> list, int col) {
        Collections.sort(list, new Comparator<String[]>() {
            public int compare(String[] o1, String[] o2) {
                return o1[col - 1].compareTo(o2[col - 1]);
            }
        });
    }
}
