public List<Object> getServiceImplementations(String serviceTypeName) {
    List<Object> serviceImplementations = new ArrayList<>();

    ServiceLoader<?> serviceLoader = ServiceLoader.load(Class.forName(serviceTypeName));
    for (Object service : serviceLoader) {
        serviceImplementations.add(service);
    }

    return serviceImplementations;
}
