private void getOnRequestPermissionsResult(int requestCode, String[] permissions, int[] grantResults) {
    int permissionCount = permissions.length;
    Map<String, Integer> permissionMap = new HashMap<>();

    // Add the permission names and corresponding results to a map
    for (int i = 0; i < permissionCount; i++) {
        permissionMap.put(permissions[i], grantResults[i]);
    }

    // Invoke annotated methods using reflection
    Class<?> clazz = this.getClass();
    Method[] methods = clazz.getMethods();
    for (Method method : methods) {
        PermissionRequest permissionRequest = method.getAnnotation(PermissionRequest.class);
        if (permissionRequest != null && permissionRequest.requestCode() == requestCode) {
            String[] requestedPermissions = permissionRequest.permissions();
            boolean isPermissionGranted = true;
            for (String permission : requestedPermissions) {
                if (permissionMap.containsKey(permission)) {
                    int result = permissionMap.get(permission);
                    if (result != PackageManager.PERMISSION_GRANTED) {
                        isPermissionGranted = false;
                    }
                }
            }

            if (isPermissionGranted) {
                try {
                    method.invoke(this);
                } catch (Exception e) {
                    e.printStackTrace();
                }
            }
        }
    }

    // Send local broadcast of the permission results
    Intent intent = new Intent(PERMISSION_RESULT_ACTION);
    intent.putExtra(REQUEST_CODE_EXTRA, requestCode);
    intent.putExtra(PERMISSIONS_EXTRA, permissions);
    intent.putExtra(GRANT_RESULTS_EXTRA, grantResults);
    LocalBroadcastManager.getInstance(this).sendBroadcast(intent);
}
