public List<String> snapshots(List<List<String>> input) {
   List<String> result = new ArrayList<>();
   Set<String> set = new HashSet<>();
   for (List<String> list : input) {
      String current = "";
      for (String s : list) {
         current += s + ",";
         if (!set.contains(current)) {
            result.add(current);
            set.add(current);
         }
      }
   }
   return result;
}
