import java.io.File;
import java.util.ArrayList;
import java.util.List;

public class ResourceFileUtils {

    public List<File> getResourceFiles(String directory, String fileName, String fileExtension) {
        List<File> fileList = new ArrayList<>();
        String filePattern = LocaleUtils.createResourceFilesPattern(fileName, fileExtension);
        File[] files = new File(directory).listFiles();
        for (File file : files) {
            if (file.isFile() && file.getName().matches(filePattern)) {
                fileList.add(file);
            }
        }
        return fileList;
    }

}
