public static <T> T deserialize(byte[] data, Class<T> clazz) throws TException {
    // Create a new instance of T
    T instance = null;
    try {
        instance = clazz.newInstance();
    } catch (InstantiationException | IllegalAccessException e) {
        throw new TException("Could not create an instance of the class", e);
    }

    // Use a TDeserializer to deserialize the data into the T instance
    TDeserializer deserializer = new TDeserializer();
    try {
        deserializer.deserialize(instance, data);
    } catch (TException e) {
        throw new TException("Could not deserialize the data into the class", e);
    }

    // Return the deserialized instance
    return instance;
}
