public void convertArray(int[] src, int srcPos, byte[] dest, int destPos) {
    int sr;
    int sg;
    int sb;

    for (int i = srcPos, j = destPos; i < src.length && j < dest.length; i += 3, j += 3) {
        sr = src[i];
        sg = src[i + 1];
        sb = src[i + 2];

        dest[j] = (byte) ((sr * 66 + sg * 129 + sb * 25 + 128) >> 8) + (byte) 16;
        dest[j + 1] = (byte) ((sr * -38 - sg * 74 + sb * 112 + 128) >> 8) + (byte) 128;
        dest[j + 2] = (byte) ((sr * 112 - sg * 94 - sb * 18 + 128) >> 8) + (byte) 128;
    }
}
