public ServiceResponse checkRedisCacheNameAvailability(RedisCacheParameters parameters) throws IllegalArgumentException {
    if (parameters == null) {
        throw new IllegalArgumentException("Parameters cannot be null");
    }
    if (parameters.getResourceType() != ResourceType.REDIS_CACHE) {
        throw new IllegalArgumentException("Invalid resource type");
    }
    String cacheName = parameters.getName();
    if (!cacheName.matches("^[a-z0-9]+(-[a-z0-9]+)*$")) {
        throw new IllegalArgumentException("Invalid cache name format");
    }
    if (cacheName.length() < 3 || cacheName.length() > 63) {
        throw new IllegalArgumentException("Cache name length must be between 3 and 63 characters");
    }
    //Code to check if the cache name is already in use goes here
    return new ServiceResponse("Success", 200);
}
