public static String createUniqueId(Object jsonVal,
                                     Map<Object, String> objToJSONVal,
                                     Map<Class<?>, List<Field>> classFieldCache,
                                     Map<String, String> jsonReferenceToId,
                                     AtomicInteger objId,
                                     boolean onlySerializePublicFields) {

        StringBuilder sb = new StringBuilder();
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            ObjectMapper om = new ObjectMapper();
            om.setVisibility(PropertyAccessor.FIELD, Visibility.ANY);

            //serialize the jsonVal using ObjectMapper
            String jsonStr = om.writeValueAsString(jsonVal);

            sb.append(jsonStr);

            //populate the id map with the generated id
            String id;
            if (jsonReferenceToId.containsKey(sb.toString())) {
                id = jsonReferenceToId.get(sb.toString());
            } else {
                //create a new object id if not already present in the map
                id = Integer.toString(objId.getAndIncrement(),36);
                jsonReferenceToId.put(sb.toString(), id);
                objToJSONVal.put(jsonVal, id);

                //serialize the fields of the object recursively to generate ids
                if (jsonVal instanceof Map) {
                    Map<?, ?> map = (Map<?, ?>) jsonVal;
                    for (Object val : map.values()) {
                        createUniqueId(val, objToJSONVal, classFieldCache, jsonReferenceToId, objId, onlySerializePublicFields);
                    }
                } else if (jsonVal instanceof Collection) {
                    Collection<?> collection = (Collection<?>) jsonVal;
                    for (Object val : collection) {
                        createUniqueId(val, objToJSONVal, classFieldCache, jsonReferenceToId, objId, onlySerializePublicFields);
                    }
                } else {
                    Class<?> clazz = jsonVal.getClass();
                    List<Field> fields;
                    if (classFieldCache.containsKey(clazz)) {
                        fields = classFieldCache.get(clazz);
                    } else {
                        fields = new ArrayList<>();
                        if (onlySerializePublicFields)
                            Collections.addAll(fields, clazz.getFields());
                        else
                            Collections.addAll(fields, clazz.getDeclaredFields());

                        //cache the fields for faster retrieval in future
                        classFieldCache.put(clazz, fields);
                    }
                    for (Field field : fields) {
                        //ignore transient and static fields
                        if (Modifier.isTransient(field.getModifiers()) || Modifier.isStatic(field.getModifiers())) {
                            continue;
                        }
                        field.setAccessible(true);
                        createUniqueId(field.get(jsonVal), objToJSONVal, classFieldCache, jsonReferenceToId, objId, onlySerializePublicFields);

                    }
                }
            }
        } catch (Exception e) {
            //Handle Exception
        }
        return sb.toString();
    }
