public String buildHTMLTable(String style, String content) {
    StringBuilder sb = new StringBuilder();
    sb.append("<table style=\"").append(style).append("\">\n");
    sb.append("<tbody>\n");
    String[] rows = content.split("\n");
    for (String row : rows) {
        sb.append("<tr>\n");
        String[] cells = row.split(",");
        for (String cell : cells) {
            sb.append("<td>").append(cell).append("</td>");
        }
        sb.append("</tr>\n");
    }
    sb.append("</tbody>\n");
    sb.append("</table>");
    return sb.toString();
}
