public Class<?> getSupportedCollectionType(Class<?> clazz) {
    if (!Streamable.class.isAssignableFrom(clazz) && Collection.class.isAssignableFrom(clazz)) {
        if (List.class.isAssignableFrom(clazz)) {
            return List.class;
        } else if (Set.class.isAssignableFrom(clazz)) {
            return Set.class;
        } else if (Queue.class.isAssignableFrom(clazz)) {
            return Queue.class;
        } else if (Deque.class.isAssignableFrom(clazz)) {
            return Deque.class;
        } else {
            return Collection.class;
        }
    } else {
        return null;
    }
}
