public void closeIdleChannels() {
    int idleTimeout = 60; // idle timeout in seconds
    long currentTime = System.currentTimeMillis();
    for (Channel channel : channels) {
        if ((currentTime - channel.getLastActiveTime()) > (idleTimeout * 1000)) {
            channel.close();
        }
    }
}
