public void traverseMethodInvocationGraph(MethodIdentifier methodID) {
    Set<MethodIdentifier> visited = new HashSet<>();
    Set<MethodIdentifier> reachable = new HashSet<>();
    Deque<MethodIdentifier> stack = new ArrayDeque<>();

    visited.add(methodID);
    reachable.add(methodID);
    stack.push(methodID);

    while (!stack.isEmpty()) {
        MethodIdentifier current = stack.pop();
        Set<MethodIdentifier> overrides = getOverrides(current);

        for (MethodIdentifier override : overrides) {
            if (!visited.contains(override)) {
                visited.add(override);
                reachable.add(override);
                stack.push(override);
            }
        }

        Set<MethodIdentifier> callers = getCallers(current);

        for (MethodIdentifier caller : callers) {
            if (!visited.contains(caller)) {
                visited.add(caller);
                reachable.add(caller);
                stack.push(caller);
            }
        }
    }
}
