public void extendPath(DependencyRelationAcceptor acceptor, int maxLength, Path path, Set<Path> frontier) {
    for (DependencyRelation relation : path.getEndNode().getRelations()) {
        if (relation.getLength() <= maxLength && acceptor.accept(relation)) {
            Node newNode = relation.getDependent();
            Path newPath = path.extend(newNode, relation);
            frontier.add(newPath);
        }
    }
}
