public void setAttribute(String key, String value, String[] attributes) {
    // Find the index of the key in the array
    int index = -1;
    for (int i = 0; i < attributes.length; i++) {
        if (attributes[i] != null && attributes[i].startsWith(key + "=")) {
            index = i;
            break;
        }
    }

    // If the key is not found, add it to the end of the array
    if (index == -1) {
        for (int i = 0; i < attributes.length; i++) {
            if (attributes[i] == null) {
                attributes[i] = key + "=" + value;
                break;
            }
        }
    }
    // Else if the key is found, append the value to the end of the string
    else {
        attributes[index] = attributes[index] + " " + value;
    }
}
