public static Tree transformUCP(Tree t) {
    List<Tree> children = t.getChildrenAsList();
    for (int i = 0; i < children.size(); i++) {
        Tree child = children.get(i);
        if (child.label().value().equals("UCP")) {
            List<Tree> ucpChildren = child.getChildrenAsList();
            if (ucpChildren.size() > 0) {
                String phrasalTag = ucpChildren.get(0).label().value();
                Tree newChild = new LabeledScoredTreeNode(new CoreLabel(phrasalTag));
                newChild.setChildren(ucpChildren.subList(1, ucpChildren.size()));
                children.set(i, newChild);
                return new LabeledScoredTreeNode(t.label(), children);
            }
        } else if (child.numChildren() > 0) {
            children.set(i, transformUCP(child));
        }
    }
    return new LabeledScoredTreeNode(t.label(), children);
}
