public static <T> int getSize(Iterable<T> iterable) {
    if (iterable instanceof Collection) {
        // If iterable is an instance of collection, return its size
        return ((Collection<?>) iterable).size();
    }
    // If iterable is not an instance of collection, count its elements
    int count = 0;
    for (T element : iterable) {
        count++;
    }
    return count;
}
