public static boolean hasAnnotation(Class<?> c, Class<?> targetClass, Map<Class<? extends Annotation>, List<Class<?>>> annotationRepository) {
    if (!annotationRepository.containsKey(targetClass)) {
        return false;
    }
    List<Class<?>> classesWithAnnotation = annotationRepository.get(targetClass);
    for (Class<?> annotatedClass : classesWithAnnotation) {
        if (c.equals(annotatedClass)) {
            return true;
        }
    }
    return false;
}
