private List<Node> getParents(String payload) {
    List<Node> parents = new ArrayList<>();
    for(Node node : nodes) {
        if(node.getChildren().stream().anyMatch(child -> child.getPayload().equals(payload))) {
            parents.add(node);
        }
    }
    return parents;
}
