    if (!fileOrDirectory.exists()) {
        return false;
    }

    if (fileOrDirectory.isDirectory()) {
        File[] files = fileOrDirectory.listFiles();
        if (files != null) {
            for (File child : files) {
                deleteFileOrDirectory(child);
            }
        }
    }

    return fileOrDirectory.delete();
}
