public List<OpenEngSBModelEntry> getAddList() {
    List<OpenEngSBModelEntry> list = new ArrayList<>();
    Class<?> clazz = this.getClass();
    while (clazz != null) {
        Field[] fields = clazz.getDeclaredFields();
        for (Field field : fields) {
            if (Modifier.isStatic(field.getModifiers())) {
                continue;
            }
            OpenEngSBModelAttribute attribute = field.getAnnotation(OpenEngSBModelAttribute.class);
            if (attribute == null || !attribute.addable()) {
                continue;
            }
            String name = attribute.name().trim().isEmpty() ? field.getName() : attribute.name().trim();
            Object value;
            try {
                field.setAccessible(true);
                value = field.get(this);
            } catch (IllegalAccessException e) {
                throw new RuntimeException(e);
            }
            OpenEngSBModelEntry entry = new OpenEngSBModelEntry(name, value, attribute.type());
            list.add(entry);
        }
        clazz = clazz.getSuperclass();
    }
    return list;
}
