import java.io.IOException;
import java.io.InputStream;
import java.util.Objects;
import me.tongfei.progressbar.ProgressBar;
import me.tongfei.progressbar.ProgressBarBuilder;

public class ProgressBarInputStream extends InputStream {

    private InputStream is;
    private ProgressBar pb;

    public ProgressBarInputStream(InputStream is, ProgressBarBuilder pbb) {
        Objects.requireNonNull(is, "Input stream cannot be null");
        Objects.requireNonNull(pbb, "Progress bar builder cannot be null");
        this.is = is;
        pb = pbb.build();
        pb.maxHint(is.available());
        pb.start();
    }

    @Override
    public int read() throws IOException {
        int read = is.read();
        if (read != -1) {
            pb.stepTo(pb.getCurrent() + 1);
        } else {
            pb.maxHint(pb.getCurrent());
            pb.stop();
        }
        return read;
    }

    @Override
    public int read(byte[] b, int off, int len) throws IOException {
        int read = is.read(b, off, len);
        if (read != -1) {
            pb.stepBy(read);
        } else {
            pb.maxHint(pb.getCurrent());
            pb.stop();
        }
        return read;
    }

    @Override
    public void close() throws IOException {
        is.close();
    }
}
