    int size = 2;
    Constraint constraint = new Constraint(size);
    constraint.setCoefficient(0, activating ? 1 : -1);
    constraint.setCoefficient(1, activating ? -1 : 1);
    constraint.setBounds(0, 0);
    return constraint;
}
