public SubjectSchemeElement searchForKey(SubjectSchemeElement root, String keyValue) {
    if (root == null) {
        return null;
    }

    if (root.getKey().equals(keyValue)) {
        return root;
    }

    for (SubjectSchemeElement child : root.getChildren()) {
        SubjectSchemeElement found = searchForKey(child, keyValue);
        if (found != null) {
            return found;
        }
    }

    return null;
}
