public static String replaceAll(final String text, final String target, final String replacement) {
    if (text.isEmpty() || target.isEmpty() || replacement == null) {
        return text;
    }

    int lastMatch = 0;
    final int len = target.length();
    final StringBuilder sb = new StringBuilder(text.length() * 2);

    for (;;) {
        final int curMatch = text.indexOf(target, lastMatch);
        if (curMatch < 0) {
            break;
        }
        sb.append(text, lastMatch, curMatch);
        sb.append(replacement);
        lastMatch = curMatch + len;
    }
    sb.append(text, lastMatch, text.length());
    return sb.toString();
}
