public static double bessel(int n, double x) {
    double EPSILON = 1e-12;
    int MAX_ITERATIONS = 1000;

    double sum = 0.0;
    double term = 1.0;
    double numerator = 1.0;
    double denominator = 1.0;

    for (int i = 0; i < MAX_ITERATIONS && Math.abs(term) > EPSILON; i++) {
        term *= (-1) * Math.pow(x / 2, 2) / ((i + 1) * (n + i + 1));
        numerator *= -(n + i);
        denominator *= i + 1;
        sum += term * numerator / denominator;
    }

    return sum;
}
