public static <T> List<T> flattenTree(Node<T> root) {
    List<T> flatList = new ArrayList<>();
    if (root != null) {
        flatList.add(root.data);
        for (Node<T> child : root.children) {
            flatList.addAll(flattenTree(child));
        }
    }
    return flatList;
}
