public void releaseLockNodes() throws Exception {
    List<String> lockNodes = zooKeeper.getChildren(LOCK_PATH, false);

    for (String lockNode : lockNodes) {
        String lockNodePath = LOCK_PATH + "/" + lockNode;
        try {
            zooKeeper.delete(lockNodePath, -1);
        } catch (InterruptedException | KeeperException e) {
            throw new Exception("Failed to release lock nodes", e);
        }
    }
}
