public void normalizeMoments(double[] sum, int nmom) {
    for (int i = 2; i <= nmom; i++) {
        double s = Math.pow(sum[0], i) + (double)i * sum[i];
        for (int j = 1; j < i; j++) {
            s += binomialCoefficient(i, j) * sum[j] * Math.pow(sum[0], i - j);
        }
        sum[i] = s / Math.pow(sum[0], ((i + 1) / 2));
    }
}

private double binomialCoefficient(int n, int k) {
    if (k > n - k)
        k = n - k;

    double result = 1.0;
    for (int i = 1; i <= k; ++i) {
        result *= (n - k + i);
        result /= i;
    }
    return result;
}
