public List<String> matchFunction(String input, String pattern) {
    List<String> matches = new ArrayList<>();
    Pattern regex = Pattern.compile(pattern);
    Matcher matcher = regex.matcher(input);
    while (matcher.find()) {
        matches.add(matcher.group());
    }
    if (matches.size() > 0) {
        return matches;
    } else {
        return null;
    }
}
