public void moveContents(int[][] matrix, int num_rows) {
    int rows = matrix.length;
    int cols = matrix[0].length;

    for (int row = rows - 1; row >= num_rows; row--) {
        for (int col = 0; col < cols; col++) {
            matrix[row][col] = matrix[row - num_rows][col];
        }
    }

    for (int row = 0; row < num_rows; row++) {
        for (int col = 0; col < cols; col++) {
            matrix[row][col] = 0;
        }
    }
}
