public String determineDBType(DatabaseMetaData metaData) throws HandlerException {
    try {
        String productName = metaData.getDatabaseProductName();
        if (productName.contains("MySQL")) {
            return "MySQL";
        } else if (productName.contains("PostgreSQL")) {
            return "PostgreSQL";
        } else if (productName.contains("Oracle")) {
            return "Oracle";
        } else {
            throw new HandlerException("Unrecognized database type");
        }
    } catch (SQLException ex) {
        throw new HandlerException("Error determining database type", ex);
    }
}
