public abstract class TemplateMethod {

    public void execute() {
        beforeExecution();
        coreExecution();
        afterExecution();
    }

    protected abstract void beforeExecution();

    protected abstract void coreExecution();

    protected abstract void afterExecution();
}

public class ConcreteTemplateMethod extends TemplateMethod {

    @Override
    protected void beforeExecution() {
        System.out.println("Before executing core method, do this first...");
    }

    @Override
    protected void coreExecution() {
        System.out.println("This is the core method.");
    }

    @Override
    protected void afterExecution() {
        System.out.println("After executing core method, do this.");
    }
}
