public void generateCode(byte[] encodedVar, int offset, int generation) {
    if (generation < 0) {
        return;
    }
    if (generation <= 0xff) {
        encodedVar[offset] = (byte) generation;
    } else {
        encodedVar[offset] = (byte) 0xff;
        encodedVar[offset + 1] = (byte) ((generation >> 8) & 0xff);
        encodedVar[offset + 2] = (byte) (generation & 0xff);
        encodedVar[offset + 3] = (byte) (generation & 0xff);
    }
}
