public boolean isNestedTypeDependency(Type type, Set<Type> nestedTypes, String mappedUniName, boolean isUniName) {
    if (type == null || nestedTypes == null || mappedUniName == null) {
        throw new IllegalArgumentException("Parameters should not be null");
    }

    if (isUniName) {
        if (type.getTypeName().equals(mappedUniName)) {
            return true;
        }
    } else {
        if (type.equals(mappedUniName)) {
            return true;
        }
    }

    for (Type nestedType : nestedTypes) {
        if (type.equals(nestedType)) {
            return true;
        }
    }

    return false;
}
