public static boolean isRootOrReferencedByRoot(DolphinBean bean) {
    if (bean.isRoot()) {
        // The bean itself is a root bean
        return true;
    } else {
        // The bean is not a root bean, but it may be referenced by one
        for (DolphinBean referencedBean : bean.getReferencedBeans()) {
            if (isRootOrReferencedByRoot(referencedBean)) {
                return true;
            }
        }
        // None of the referenced beans is a root bean
        return false;
    }
}
