public static double findLocalMinimum(double eps, int maxIterations, double a, double b, DoubleFunction<Double> f) {
    double x1 = (a + b - Math.sqrt(3) * (b - a)) / 2;
    double x2 = (a + b + Math.sqrt(3) * (b - a)) / 2;
    double f1 = f.apply(x1);
    double f2 = f.apply(x2);

    for (int i = 0; i < maxIterations; i++) {
        if (f1 < f2) {
            b = x2;
            x2 = x1;
            f2 = f1;
