public boolean isNamespaceNotProvided(String namespace) {
  // Get all the current provided namespaces
  Set<String> providedNamespaces = googGetProvidedNamespaces();

  // Check if the given namespace is already provided
  if (providedNamespaces.contains(namespace)) {
    return false;
  }

  // Check if the given namespace is part of any of the provided namespaces
  for (String providedNamespace : providedNamespaces) {
    if (providedNamespace.startsWith(namespace + ".")) {
      return false;
    }
  }

  // If the given namespace is not already provided and not part of any of the provided namespaces, return true
  return true;
}

