private static Map<Long, Long> cache = new HashMap<>();

public static long cacheRadixToPower(long radix, long power) {
    if (power < 0) {
        throw new IllegalArgumentException("Cannot cache negative powers.");
    }
    if (power == 0) {
        return 1; // Any number raised to 0 is 1
    }
    if (cache.containsKey(power)) {
        return cache.get(power);
    }
    long result = radix;
    for (int i = 1; i < power; i++) {
        result *= radix;
    }
    cache.put(power, result);
    return result;
}
