public Node getFirstUniqueNode(Node head) {
    if (head == null) {
        return null;
    }
    Node current = head;
    while (current.prev != null) {
        current = current.prev;
    }
    while (current != null && current.next == current) {
        current = current.next;
    }
    head = current;
    return current;
}
