import com.datastax.driver.core.*;

public List<Row> loadSuperColumnsFromDatabase(String keyspace, String columnFamily, String rowId, List<String> superColumnNames) {
    Cluster cluster = Cluster.builder().addContactPoint("localhost").build();
    Session session = cluster.connect(keyspace);
    PreparedStatement preparedStatement = session.prepare(
            String.format("SELECT %s FROM %s WHERE rowId = ?", String.join(",", superColumnNames), columnFamily));
    BoundStatement boundStatement = preparedStatement.bind(rowId);
    ResultSet resultSet = session.execute(boundStatement);
    List<Row> rows = resultSet.all();
    cluster.close();
    return rows;
}
