public Partitions parsePartitions(String nodes) {
    Partitions partitions = new Partitions();
    String[] nodeArray = nodes.split("\n");
    for (String node : nodeArray) {
        String[] lineArray = node.split(" ");
        if (lineArray.length >= 9) {
            String[] slots = lineArray[8].split("-");
            for (String slot : slots) {
                partitions.addPartition(Integer.parseInt(slot), lineArray[1]);
            }
        }
    }
    return partitions;
}
