public List<Facet> inspectClass(Class<?> clazz) {
   List<Facet> facetList = new ArrayList<>();
   deque<FacetConstraint> constraintsQueue = new ArrayDeque<>();
   constraintsQueue.addAll(Arrays.asList(clazz.getAnnotationsByType(FacetConstraint.class)));

   while(!constraintsQueue.isEmpty()) {
      FacetConstraint constraint = constraintsQueue.pop();
      facetList.addAll(Arrays.asList(constraint.value()));

      for(Class<?> dependentClass : constraint.dependsOn()) {
         constraintsQueue.addAll(Arrays.asList(dependentClass.getAnnotationsByType(FacetConstraint.class)));
      }
   }
   return facetList;
}
