import java.util.*;

public class SortedRangeSet {
    private List<Range> ranges;

    public SortedRangeSet() {
        ranges = new ArrayList<>();
    }

    public void union(List<Range> input) {
        if (input == null || input.isEmpty()) {
            return;
        }

        Collections.sort(input);
        Iterator<Range> it = input.iterator();
        Range curr = it.next();

        while (it.hasNext()) {
            Range next = it.next();
            if (curr.overlaps(next)) {
                curr = curr.union(next);
            } else {
                ranges.add(curr);
                curr = next;
            }
        }
        ranges.add(curr);
    }
}
