public void readExtensions(String extension) {
    String[] parts = extension.split("\\s+");
    int start = Integer.parseInt(parts[1]);
    int end;

    if(parts.length == 3) {
        end = Integer.parseInt(parts[2].replaceAll("[^\\d.]", ""));
    } else {
        end = start;
    }

    for(int i=start; i<=end; i++) {
        System.out.println("Extension " + i);
    }
}
