public class ConfigurationImplProxyFactory {

    private static Method lastCalledMethod = null;
    private static Class<?> lastCalledMethodScope = null;

    public static Object createProxy(Class<?> targetClass, InvocationHandler handler) {
        Object proxy = Proxy.newProxyInstance(
                targetClass.getClassLoader(),
                new Class[]{targetClass},
                handler);

        return proxy;
    }

    public static Method getLastCalledMethod() {
        Method method = lastCalledMethod;
        lastCalledMethod = null;
        return method;
    }

    public static Class<?> getLastCalledMethodScope() {
        Class<?> scope = lastCalledMethodScope;
        lastCalledMethodScope = null;
        return scope;
    }

    public static void identifyLastCalledMethod(Method method, Class<?> scope) {
        if (lastCalledMethod == null || !lastCalledMethod.equals(method)) {
            lastCalledMethod = method;
            lastCalledMethodScope = scope;
        }
    }
}
