public static <T> T convertByteArrayToType(Class<T> type, byte[] val) throws Exception {
    if(type.equals(Byte.class) || type.equals(byte.class)){
        return (T) Byte.valueOf(val[0]);
    } else if(type.equals(Short.class) || type.equals(short.class)){
        return (T)Short.valueOf((short) ((val[0] << 8) | (val[1] & 0xFF)));
    } else if(type.equals(Integer.class) || type.equals(int.class)){
        return (T)Integer.valueOf((val[0] << 24) | ((val[1] & 0xFF) << 16) |
                ((val[2] & 0xFF) << 8) | (val[3] & 0xFF));
    } else if(type.equals(Long.class) || type.equals(long.class)){
        return (T)Long.valueOf((val[0] << 56) | ((val[1] & 0xFFL) << 48) |
                ((val[2] & 0xFFL) << 40) | ((val[3] & 0xFFL) << 32) |
                ((val[4] & 0xFFL) << 24) | ((val[5] & 0xFFL) << 16) |
                ((val[6] & 0xFFL) << 8) | (val[7] & 0xFFL));
    } else if(type.equals(Float.class) || type.equals(float.class)){
        return (T)Float.valueOf(Float.intBitsToFloat((val[0] << 24) |
                ((val[1] & 0xFF) << 16) | ((val[2] & 0xFF) << 8) | (val[3] & 0xFF)));
    } else if(type.equals(Double.class) || type.equals(double.class)){
        return (T)Double.valueOf(Double.longBitsToDouble(
                ((long) val[0] << 56) | ((long) (val[1] & 0xFF) << 48) |
                        ((long) (val[2] & 0xFF) << 40) | ((long) (val[3] & 0xFF) << 32) |
                        ((long) (val[4] & 0xFF) << 24) | ((long) (val[5] & 0xFF) << 16) |
                        ((long) (val[6] & 0xFF) << 8) | ((long) val[7] & 0xFF)));
    } else if(type.equals(Character.class) || type.equals(char.class)){
        return (T)Character.valueOf((char)((val[0] << 8) | (val[1] & 0xFF)));
    } else if(type.equals(Boolean.class) || type.equals(boolean.class)){
        return (T)Boolean.valueOf(val[0] != 0x00);
    } else if(type.equals(String.class)){
        return (T)new String(val);
    } else{
        throw new Exception("Unsupported type!");
    }
}
