public Queue<Session> getSortedQueue(List<Session> sessions) {
    Queue<Session> sortedQueue = new PriorityQueue<>((s1, s2) -> {
        if (s1.getStartTime().equals(s2.getStartTime())) {
            return s1.getEndTime().compareTo(s2.getEndTime());
        }
        return s1.getStartTime().compareTo(s2.getStartTime());
    });
    sortedQueue.addAll(sessions);
    return sortedQueue;
}
