public boolean isBridgeMethodFor(Method bridgeMethod, Method candidateMethod) {
   // Check if the candidate method is null or not
   if (candidateMethod == null) {
      return false;
   }
   // Check if the bridge method is a bridge method or not
   if (!bridgeMethod.isBridge()) {
      return false;
   }
   // Check the method signature using Method.equals() method
   return bridgeMethod.getName().equals(candidateMethod.getName()) &&
          bridgeMethod.getReturnType().equals(candidateMethod.getReturnType()) &&
          Arrays.equals(bridgeMethod.getParameterTypes(), candidateMethod.getParameterTypes());
}
