import javax.resource.spi.security.PasswordCredential;
import javax.security.auth.Subject;
import java.util.Set;

public static class J2CSubjectUtil {

  public static Subject getSubject(Subject invocationSubject,
                                    Subject extraSubject) {
    if (invocationSubject != null) {
      Set<PasswordCredential> creds = invocationSubject.getPrivateCredentials(PasswordCredential.class);
      if (!creds.isEmpty()) {
        return invocationSubject;
      }
    }
    if (extraSubject != null) {
      Set<PasswordCredential> creds = extraSubject.getPrivateCredentials(PasswordCredential.class);
      if (!creds.isEmpty()) {
        return extraSubject;
      }
    }
    return null;
  }
}
