public static Object convertValue(Object source, String attr) throws AttributeValueConversionException {
    if (source == null) return null;
    if (attr == null) return source;

    switch (attr) {
        case "byte":
        case "java.lang.Byte":
            if (source instanceof Number) {
                return ((Number) source).byteValue();
            }
            break;
        case "short":
        case "java.lang.Short":
            if (source instanceof Number) {
                return ((Number) source).shortValue();
            }
            break;
        case "int":
        case "java.lang.Integer":
            if (source instanceof Number) {
                return ((Number) source).intValue();
            }
            break;
        case "long":
        case "java.lang.Long":
            if (source instanceof Number) {
                return ((Number) source).longValue();
            }
            break;
        case "float":
        case "java.lang.Float":
            if (source instanceof Number) {
                return ((Number) source).floatValue();
            }
            break;
        case "double":
        case "java.lang.Double":
            if (source instanceof Number) {
                return ((Number) source).doubleValue();
            }
            break;
        case "java.lang.String":
            if (!(source instanceof String)) {
                return source.toString();
            }
            break;
        case "java.util.Date":
            if (source instanceof java.util.Date) {
                return source;
            }
            break;
        default:
            return source;
    }

    throw new AttributeValueConversionException("Cannot convert value of type " + source.getClass().getName() + " to " + attr);
}
