public String quoteString(String str) {
    StringBuilder quoted = new StringBuilder();
    for (int i = 0; i < str.length(); i++) {
        char ch = str.charAt(i);
        if (ch == '\\' || ch == '\"') {
            quoted.append('\\');
        }
        quoted.append(ch);
    }
    return quoted.toString();
}
