public int registerXAResource(Object config) throws UnavailableException {
    // Check if transaction manager is available
    if (!isTransactionManagerAvailable()) {
        throw new UnavailableException("Transaction manager is not available");
    }

    // Produce XAResource object using XAResourceFactory
    XAResourceFactory xaResourceFactory = new XAResourceFactory();
    XAResource xaResource = xaResourceFactory.produceXAResource(config);

    // Register XA resource with transaction manager and get recovery ID
    int recoveryId = getTransactionManager().registerXAResource(xaResource);

    // Return recovery ID or -1 if an error occurs
    return recoveryId;
}
