public boolean shouldNotBeInstrumented(Class<?> clazz) {
    // check if the class belongs to a package that should not be instrumented
    if (clazz.getPackageName().startsWith("com.example")) {
        return true;
    }
    // check if the class is an interface or an enumeration
    if (clazz.isInterface() || clazz.isEnum()) {
        return true;
    }
    // check if the class has the annotation @DoNotInstrument
    if (clazz.isAnnotationPresent(DoNotInstrument.class)) {
        return true;
    }
    // check if the class is synthetic
    if (clazz.isSynthetic()) {
        return true;
    }
    // otherwise, the class should be instrumented
    return false;
}
