public Object searchResource(String resourceName){

    Object resource = null;

    // Search the bundle loader
    // Assuming that the bundle loader object is available as "bundleLoader"
    if(bundleLoader != null){
        resource = bundleLoader.findResource(resourceName);
    }

    // If the resource is not found in bundle loader, search the resource provider
    if(resource == null){
        // Assuming that the resource provider object is available as "resourceProvider"
        if(resourceProvider != null){
            resource = resourceProvider.findResource(resourceName);
        }
    }

    return resource;
}
