public boolean looselyMatches(String input, String localName, String uri, boolean firstLocalNameChar) {
    if (input == null || localName == null || uri == null) {
        return false;
    }
    if (input.equalsIgnoreCase(localName)) {
        return true;
    }
    if (firstLocalNameChar && input.equals(uri)) {
        return true;
    }
    return input.length() == 1 && Character.toLowerCase(input.charAt(0)) == Character.toLowerCase(localName.charAt(0));
}
