public BulkResponseObject terminateWorkflows(List<String> workflowIds, String reason) {
    BulkResponseObject response = new BulkResponseObject();
    List<String> succeededWorkflows = new ArrayList<>();
    List<String> failedWorkflows = new ArrayList<>();

    for(String workflowId : workflowIds) {
        try {
            // Code to terminate workflow with the given id and reason
            succeededWorkflows.add(workflowId);
        } catch(Exception e) {
            failedWorkflows.add(workflowId + " failed with error: " + e.getMessage());
        }
    }

    response.setSucceededWorkflows(succeededWorkflows);
    response.setFailedWorkflows(failedWorkflows);

    return response;
}
