public Map<String, String> getCatalogSchemas(Connection conn, String catalog) throws SQLException {

    Map<String, String> schemas = new HashMap<>();

    DatabaseMetaData dbmd = conn.getMetaData();
    ResultSet rs = dbmd.getSchemas(catalog, null);

    while (rs.next()) {
        String schemaName = rs.getString("TABLE_SCHEM");
        String catalogName = rs.getString("TABLE_CATALOG");
        schemas.put(schemaName, catalogName);
    }

    return schemas;
}
