public class ResultSet {
  private int size;
  private int currentPosition;

  public ResultSet(int size) {
    this.size = size;
    currentPosition = -1;
  }

  public boolean next() {
    if(currentPosition == size - 1) {
      return false;
    }
    currentPosition++;
    return true;
  }

  public boolean previous() {
    if(currentPosition == 0) {
      return false;
    }
    currentPosition--;
    return true;
  }

  public boolean absolute(int row) {
    if(row < 0) {
      currentPosition = size + row;
    }
    else {
      currentPosition = row - 1;
    }
    if(currentPosition < 0 || currentPosition >= size) {
      currentPosition = -1;
      return false;
    }
    return true;
  }

  public boolean relative(int rows) {
    if(currentPosition + rows < 0 || currentPosition + rows >= size) {
      currentPosition = -1;
      return false;
    }
    currentPosition += rows;
    return true;
  }

  public int getInt(int columnIndex) {
    return currentPosition + columnIndex;
  }

  public String getString(int columnIndex) {
    return "Row " + (currentPosition + 1) + ", Column " + columnIndex;
  }
}
