public <T extends PropertyDispatcher> T createInstance(Class<T> cls, PropertyDispatcher dispatcher) {
    try {
        Constructor<T> constructor = cls.getDeclaredConstructor(PropertyDispatcher.class);
        constructor.setAccessible(true);
        return constructor.newInstance(dispatcher);
    } catch (InstantiationException | IllegalAccessException | NoSuchMethodException | InvocationTargetException e) {
        throw new RuntimeException("Error creating instance of PropertyDispatcher subclass", e);
    }
}
