import java.lang.invoke.MethodHandles;
import java.lang.invoke.MethodType;
import java.lang.invoke.SwitchPoint;
import java.lang.invoke.WrongMethodTypeException;

public class SmartHandle {
    private final MethodHandle handle;
    private final MethodType incomingType;

    public SmartHandle(MethodHandle handle, MethodType incomingType) {
        this.handle = handle;
        this.incomingType = incomingType;
    }

    public MethodHandle castArguments(MethodType targetType) {
        MethodType thisType = handle.type();
        MethodType newType = incomingType.changeReturnType(thisType.returnType());
        newType = newType.changeParameterTypes(0, targetType.parameterArray());
        MethodHandle result = MethodHandles.explicitCastArguments(handle, newType);
        return result;
    }
}
