/**
 * Appends the given CharSequence to the content of this message.
 *
 * @param charSequence The CharSequence to append to the message content
 * @return Updated MessageAction for chaining convenience
 * @throws java.lang.IllegalArgumentException If the appended CharSequence is too big and will cause
 * the content to exceed the {@value net.dv8tion.jda.core.entities.Message#MAX_CONTENT_LENGTH} character limit
 */
public MessageAction append(CharSequence charSequence) {
    if ((getContentRaw().length() + charSequence.length()) > Message.MAX_CONTENT_LENGTH)
        throw new IllegalArgumentException("Content length cannot exceed " + Message.MAX_CONTENT_LENGTH + " characters");
    this.content.append(checkNull(charSequence));
    return this;
}
