public Launcher decorateLauncherWithPrefix(String[] prefix, Launcher launcher) {
    return new PrefixLauncherDecorator(prefix, launcher);
}

private static class PrefixLauncherDecorator extends Launcher {

    private final String[] prefix;
    private final Launcher inner;

    public PrefixLauncherDecorator(String[] prefix, Launcher inner) {
        this.prefix = prefix.clone();
        this.inner = inner;
    }

    public Proc proc(String[] cmds, OutputStream out) throws IOException, InterruptedException {
        String[] prefixedCmds = Arrays.copyOf(prefix, prefix.length + cmds.length);
        System.arraycopy(cmds, 0, prefixedCmds, prefix.length, cmds.length);
        return inner.proc(prefixedCmds, out);
    }

    // Delegation of remaining methods to wrapped launcher
}
