import java.net.URI;
import java.net.URISyntaxException;
import org.w3c.dom.Element;

public static String resolveURI(String baseURI, Element parent, String url) {
    try {
        URI resolved = new URI(url);
        if (resolved.isAbsolute()) {
            return url;
        }
        URI base = (baseURI != null) ? new URI(baseURI) : null;
        URI parentBase = getParentBase(parent);

        if (base == null && parentBase == null) {
            return null;
        } else if (base == null) {
            return parentBase.resolve(resolved).toString();
        } else if (parentBase == null) {
            return base.resolve(resolved).toString();
        } else {
            return parentBase.resolve(base).resolve(resolved).toString();
        }
    } catch (URISyntaxException e) {
        throw new RuntimeException(e);
    }
}

private static URI getParentBase(Element parent) throws URISyntaxException {
    if (parent == null) {
        return null;
    }
    String xmlBase = parent.getAttributeNS("http://www.w3.org/XML/1998/namespace", "base");
    return (xmlBase != null && xmlBase.length() > 0) ? new URI(xmlBase) : null;
}
