public PackedDecimal shiftDecimalPoint(int n) {
    // assuming PackedDecimal is a class with appropriate representation of a packed decimal number
    String[] digits = value.split(".");
    String integerPart = digits[0];
    String decimalPart = digits[1];
    String newDecimalPart = "";

    if (n > decimalPart.length()) {
        // pad with zeros if the decimal part is shorter than the requested shift
        newDecimalPart = String.format("%0" + n + "d", 0) + decimalPart;
    } else {
        newDecimalPart = decimalPart.substring(n);
    }

    // concatenate the integer part and new decimal part to form the shifted number
    String shiftedValue = integerPart + "." + newDecimalPart;

    // return a new instance of PackedDecimal with the shifted value
    return new PackedDecimal(shiftedValue);
}
