import java.util.Properties;

public class TypeGuesser {

    public Properties guessTypes(Properties properties) {
        Properties guessedTypes = new Properties();

        for (String key : properties.stringPropertyNames()) {
            String value = properties.getProperty(key);

            // Attempt to parse as boolean
            if (value.equalsIgnoreCase("true") || value.equalsIgnoreCase("false")) {
                guessedTypes.setProperty(key, "boolean");
            }
            // Attempt to parse as integer
            else if (value.matches("^-?\\d+$")) {
                guessedTypes.setProperty(key, "int");
            }
            // Attempt to parse as double
            else if (value.matches("^-?\\d+(\\.\\d+)?$")) {
                guessedTypes.setProperty(key, "double");
            }
            // Fallback to string
            else {
                guessedTypes.setProperty(key, "String");
            }
        }

        return guessedTypes;
    }
}
