public static double parseNumber(String message, int start, int limit, boolean allowInfinity) {
    String str = message.substring(start, limit).trim();
    if (allowInfinity && str.equals("\u221E")) {
        return Double.POSITIVE_INFINITY;
    }
    try {
        return Double.parseDouble(str);
    } catch (NumberFormatException e) {
        return Double.NaN;
    }
}
