import org.apache.pig.data.DataType;
import org.apache.pig.impl.logicalLayer.schema.*;

public Schema fieldToSchema(FieldSchema fieldDescriptor) throws FrontendException {
    Schema nestedSchema = null;
    byte type = fieldDescriptor.type;
    // If the type is tuple
    if (type == DataType.TUPLE) {
        if (fieldDescriptor.schema != null) {
            nestedSchema = fieldDescriptor.schema;
        } else {
            nestedSchema = new Schema();
        }
        return nestedSchema;
    }
    // If the type is bag
    else if (type == DataType.BAG) {
        FieldSchema fs = new FieldSchema(null, fieldDescriptor.schema);
        nestedSchema = new Schema(fs);
        return nestedSchema;
    }
    // If the type is map
    else if (type == DataType.MAP) {
        MapFieldSchema mschema = (MapFieldSchema) fieldDescriptor.schema;
        nestedSchema = new Schema(fieldToSchema(mschema.getValueType()));
        nestedSchema.setTwoLevelKey();
        return nestedSchema;
    }
    // If the type is atomic
    else {
        nestedSchema = new Schema(new FieldSchema(null, fieldDescriptor.type));
        return nestedSchema;
    }
}
