public String getPricesAndContracts(String ip, String token, String serviceName, int duration) throws IOException {
    String url = "https://example.com/order/dedicated/server/" + serviceName + "/ipMigration/" + duration + "?ip=" + ip + "&token=" + token;

    URL obj = new URL(url);
    HttpURLConnection con = (HttpURLConnection) obj.openConnection();
    con.setRequestMethod("GET");

    int responseCode = con.getResponseCode();
    if (responseCode == HttpURLConnection.HTTP_OK) {
        BufferedReader in = new BufferedReader(new InputStreamReader(
                con.getInputStream()));
        String inputLine;
        StringBuffer response = new StringBuffer();

        while ((inputLine = in.readLine()) != null) {
            response.append(inputLine);
        }
        in.close();

        return response.toString();
    } else {
        return "GET request failed with response code " + responseCode;
    }
}
