public void createEphemeralNode(ZooKeeper zkClient, String path, byte[] data) throws KeeperException, InterruptedException {
    if (zkClient.exists(path, false) == null) {
        String parentPath = path.substring(0, path.lastIndexOf('/'));
        if (parentPath.length() > 0) {
            zkClient.create(parentPath, new byte[0], ZooDefs.Ids.OPEN_ACL_UNSAFE, CreateMode.PERSISTENT);
        }
        zkClient.create(path, data, ZooDefs.Ids.OPEN_ACL_UNSAFE, CreateMode.EPHEMERAL);
    } else {
        System.out.println("[ERROR] Node already exists");
    }
}
