public ChannelBuffer formatResults(TSQuery data_query, List<Data> results, List<Annotation> globals) {
    // Implementation logic goes here

    // Create a new empty ChannelBuffer
    ChannelBuffer buffer = ChannelBuffers.dynamicBuffer();

    // Write the query metadata to the buffer
    buffer.writeBytes(data_query.getMetadata().getBytes(Charset.defaultCharset()));

    // Write the global annotations, if any
    if (globals != null && !globals.isEmpty()) {
        for (Annotation annotation : globals) {
            buffer.writeBytes(("Global Annotation: " + annotation.getKey() + "=" + annotation.getValue() + "\n").getBytes(Charset.defaultCharset()));
        }
    }

    // Write the data values to the buffer
    for (Data data : results) {
        buffer.writeBytes(("Timestamp: " + data.getTimestamp() + ", Value: " + data.getValue() + "\n").getBytes(Charset.defaultCharset()));
    }

    return buffer;
}
