public static int convertRelativeYearToAbsolute(int shortYear) {
    if (shortYear >= 0 && shortYear <= 99) {
        int currentYear = Calendar.getInstance().get(Calendar.YEAR);
        int currentCentury = currentYear / 100 * 100;
        int shortCentury = currentCentury + shortYear;
        return shortCentury <= currentYear ? shortCentury : shortCentury - 100;
    } else {
        throw new IllegalArgumentException("Short year must be between 0 and 99");
    }
}
