        IResource resource = JdtUtils.resolve(classpathUri, javaProject.getProject());
        if (resource != null && resource.exists()) {
            if (!(resource.getType() == IResource.FILE || resource.getType() == IResource.FOLDER)) {
                return;
            }
            if (resource.getType() == IResource.FOLDER) {
                if (isMavenResourceDirectory(jdtUtils.getPackageFragment(resource))) {
                    return;
                }
            }

            // forwarded to findResourceInWorkspace
        }
    }
}
