public byte[] serializeLogicalSmap(LogicalSmap smap) {
    try (ByteArrayOutputStream out = new ByteArrayOutputStream();
         ObjectOutputStream objOut = new ObjectOutputStream(out)) {
        objOut.writeObject(smap);
        return out.toByteArray();
    } catch (IOException e) {
        throw new RuntimeException("Error serializing logical SMAP", e);
    }
}

public LogicalSmap deserializeLogicalSmap(byte[] data) {
    try (ByteArrayInputStream in = new ByteArrayInputStream(data);
         ObjectInputStream objIn = new ObjectInputStream(in)) {
        return (LogicalSmap) objIn.readObject();
    } catch (IOException | ClassNotFoundException e) {
        throw new RuntimeException("Error deserializing logical SMAP", e);
    }
}
