public int findIndex(int[][] array, int condition, int dimension) {
    int index = -1;
    if (dimension == 0) {
        for (int i = 0; i < array.length; i++) {
            if (array[i][0] == condition) {
                index = i;
                break;
            }
        }
    } else if (dimension == 1) {
        for (int i = 0; i < array[0].length; i++) {
            if (array[0][i] == condition) {
                index = i;
                break;
            }
        }
    }
    return index;
}
