public static org.jboss.pressgang.ccms.contentspec.File parseFileMetaDataComponent(String line, int lineNumber) throws ParsingException {
    if (StringUtils.isBlank(line)) {
        return null;
    }
    String[] parts = line.split(";");
    if (parts.length != 3) {
        throw new ParsingException("Invalid file metadata component at line " + lineNumber);
    }
    org.jboss.pressgang.ccms.contentspec.File file = new org.jboss.pressgang.ccms.contentspec.File();
    file.setName(parts[0].trim());
    file.setId(Long.parseLong(parts[1].trim()));
    file.setSize(Long.parseLong(parts[2].trim()));
    return file;
}
