public static List<Class<?>> getAllClassesInPackage(Package pkg, boolean recursive, Predicate<Class<?>> predicate) {
    String packageName = pkg.getName();
    List<Class<?>> classes = new ArrayList<>();

    try {
        List<File> classFiles = new ArrayList<>();
        Enumeration<URL> urls = ClassLoader.getSystemClassLoader().getResources(packageName.replace(".", "/"));

        while (urls.hasMoreElements()) {
            URL url = urls.nextElement();
            String protocol = url.getProtocol();
            if (protocol.equals("jar")) {
                JarURLConnection conn = (JarURLConnection) url.openConnection();
                JarFile jar = conn.getJarFile();
                for (JarEntry entry : Collections.list(jar.entries())) {
                    String className = entry.getName().replace('/', '.');
                    if (className.startsWith(packageName) && className.endsWith(".class")) {
                        className = className.substring(0, className.length() - ".class".length());
                        classFiles.add(new File(className.replace(".", "/")));
                    }
                }
            } else if (protocol.equals("file")) {
                classFiles.addAll(Arrays.asList(new File(url.toURI()).listFiles()));
            }
        }

        for (File file : classFiles) {
            if (file.isDirectory() && recursive) {
                classes.addAll(getAllClassesInPackage(Package.getPackage(packageName + "." + file.getName()), true, predicate));
            } else if (file.getName().endsWith(".class")) {
                Class<?> clazz = Class.forName(packageName + "." + file.getName().substring(0, file.getName().length() - 6));
                if (predicate == null || predicate.test(clazz)) {
                    classes.add(clazz);
                }
            }
        }
    } catch (IOException | URISyntaxException | ClassNotFoundException e) {
        e.printStackTrace();
    }

    return classes;
}
