public NodeIterator castResultToNodeList(Result result) throws TransformerException {
    DOMResult domResult = (DOMResult) result;
    NodeList nodeList = domResult.getNode().getChildNodes();
    return new NodeIterator() {
        int pointer = 0;
        @Override
        public Node nextNode() {
            if (pointer < nodeList.getLength()) {
                return nodeList.item(pointer++);
            } else {
                return null;
            }
        }
        @Override
        public Node previousNode() {
            if (pointer > 0) {
                return nodeList.item(--pointer);
            } else {
                return null;
            }
        }
        @Override
        public void detach() {}
        @Override
        public int nextPosition() {
            return pointer+1;
        }
        @Override
        public void remove() {}
    };
}
