import java.io.File;
import java.lang.reflect.Method;
import java.net.URL;
import java.net.URLClassLoader;
import java.util.ArrayList;
import java.util.List;
import java.util.jar.JarEntry;
import java.util.jar.JarFile;

public class JarRunner {

    public static void run(String[] arguments) throws Exception {
        List<URL> urls = extractJarFiles();
        URLClassLoader classLoader = new URLClassLoader(urls.toArray(new URL[urls.size()]));
        Class<?> clazz = classLoader.loadClass("org.simplericity.jettyconsole.JettyConsoleStarter");
        Method mainMethod = clazz.getMethod("main", String[].class);
        mainMethod.invoke(null, (Object) arguments);
    }

    private static List<URL> extractJarFiles() throws Exception {
        List<URL> urls = new ArrayList<>();
        String classPath = System.getProperty("java.class.path");
        for (String jarFilePath : classPath.split(File.pathSeparator)) {
            File file = new File(jarFilePath);
            if (file.isFile() && file.getName().endsWith(".jar")) {
                JarFile jarFile = new JarFile(file);
                for (JarEntry entry : Collections.list(jarFile.entries())) {
                    if (entry.getName().endsWith(".jar")) {
                        File tempFile = File.createTempFile("temp", ".jar");
                        tempFile.deleteOnExit();
                        try (InputStream is = jarFile.getInputStream(entry);
                                OutputStream os = new FileOutputStream(tempFile)) {
                            ByteStreams.copy(is, os);
                        }
                        urls.add(tempFile.toURI().toURL());
                    }
                }
                urls.add(file.toURI().toURL());
                jarFile.close();
            }
        }
        return urls;
    }
}
