public List<String> getItemsNotInBucket(List<String> storage) {
  List<String> itemsNotInBucket = new ArrayList<>();

  // create new list if storage is null
  if (storage == null) {
    storage = new ArrayList<>();
  } else {
    // clear storage if it's not null
    storage.clear();
  }

  // add items not in bucket to list
  for (int i = 0; i < allItems.size(); i++) {
    if (!storage.contains(allItems.get(i))) {
      itemsNotInBucket.add(allItems.get(i));
    }
  }

  return itemsNotInBucket;
}
