import io.grpc.Attributes;
import io.grpc.EquivalentAddressGroup;
import io.netty.channel.EventLoopGroup;
import io.netty.channel.nio.NioEventLoopGroup;
import io.netty.resolver.ResolvedAddressTypes;
import io.netty.resolver.dns.DnsServerAddressStreamProviders;
import io.netty.resolver.dns.RoundRobinDnsAddressResolverGroup;
import io.netty.util.concurrent.Future;
import io.netty.util.concurrent.Promise;
import io.netty.util.concurrent.PromiseCombiner;
import io.netty.util.concurrent.UnorderedThreadPoolEventExecutor;
import io.grpc.internal.DnsNameResolverProvider;

import java.net.InetAddress;
import java.net.InetSocketAddress;
import java.net.SocketAddress;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;

public static DnsAddressEndpointGroup createDnsEndpointGroup(String hostname, int port) {
    EventLoopGroup workerGroup = new NioEventLoopGroup();

    RoundRobinDnsAddressResolverGroup resolverGroup =
            new RoundRobinDnsAddressResolverGroupBuilder(workerGroup)
                    .serverAddresses(DnsServerAddressStreamProviders.platformDefault())
                    .nameServerTimeoutMillis(10000L)
                    .resolveCacheTimeoutMillis(TimeUnit.MINUTES.toMillis(30L))
                    .maxQueriesPerResolve(16)
                    .traceEnabled(true)
                    .optResourceEnabled(true)
                    .optResourceQuery(DnsNameResolverProvider.asDomainName(hostname))
                    .ndots(1)
                    .searchDomains("")
                    .ndots(0)
                    .resolvedAddressTypes(ResolvedAddressTypes.IPV4_ONLY)
                    .build();

    List<InetSocketAddress> addresses = new ArrayList<>();
    try {
        Future<List<InetAddress>> future = resolverGroup.resolveAll(hostname, Attributes.EMPTY);
        Promise<List<InetAddress>> promise = new UnorderedThreadPoolEventExecutor(workerGroup, 32).newPromise();
        Future<InetSocketAddress> completeFuture = promise
                .flatMap(ips -> {
                    for (InetAddress remoteAddress : ips) {
                        return workerGroup.next().newPromise().setSuccess(new InetSocketAddress(remoteAddress, port));
                    }
                    return workerGroup.next().newPromise().setFailure(new IllegalStateException("unable to retrieve IPv4 addresses"));
                });
        new PromiseCombiner()
                .addAll(future, promise)
                .addListener(f -> future.getNow().forEach(inetAddress -> completeFuture.addListener(f1 -> {
                    SocketAddress resolvedAddress = completeFuture.getNow();
                    if (resolvedAddress instanceof InetSocketAddress) {
                        addresses.add((InetSocketAddress) resolvedAddress);
                    } else {
                        throw new IllegalStateException("Unable to resolve to InetSocketAddress: " + resolvedAddress);
                    }
                })));
    } catch (Throwable t) {
        throw new RuntimeException(t);
    }
    EquivalentAddressGroup addressGroup = new EquivalentAddressGroup(addresses.toArray(new InetSocketAddress[0]));

    return new DnsAddressEndpointGroup(addressGroup, workerGroup);
}
