public FieldDescription[] sortNonPkFieldDescriptions(FieldDescription[] fieldDescriptions) {
    List<FieldDescription> nonPkFieldList = new ArrayList<>();
    for (FieldDescription fieldDescription : fieldDescriptions) {
        if (!fieldDescription.isPrimaryKey()) {
            nonPkFieldList.add(fieldDescription);
        }
    }
    FieldDescription[] nonPkFields = nonPkFieldList.toArray(new FieldDescription[nonPkFieldList.size()]);

    Arrays.sort(nonPkFields, Comparator.comparingInt(FieldDescription::getOrder));
    return nonPkFields;
}
