import javax.management.*;

public static String constructMBeanConfiguration(ObjectInstance objectInstance) throws Exception {
    MBeanAttributeInfo[] attributeInfos = ManagementFactory.getPlatformMBeanServer().getMBeanInfo(objectInstance.getObjectName()).getAttributes();
    StringBuilder stringBuilder = new StringBuilder();
    stringBuilder.append(String.format("%s%n", objectInstance.getObjectName()));
    for (MBeanAttributeInfo attributeInfo : attributeInfos) {
        Object attributeValue = ManagementFactory.getPlatformMBeanServer().getAttribute(objectInstance.getObjectName(), attributeInfo.getName());
        stringBuilder.append(String.format("%s = %s%n", attributeInfo.getName(), attributeValue));
    }
    return stringBuilder.toString();
}
