public static short readLittleEndianShort(DataInput in) throws IOException {
    byte[] bytes = new byte[2];
    in.readFully(bytes);
    short value = ((short) (bytes[0] & 0xff));
    value |= ((short) (bytes[1] & 0xff)) << 8;
    return value;
}
