import java.util.Random;

public String generateAutomatonDOTCode(Random random) {

    // Define the number of states in the automaton
    int numStates = random.nextInt(10) + 1; // minimum 1 state, maximum 11 states

    // Define the set of symbols in the automaton's alphabet
    char[] alphabet = {'a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j'};

    // Create a StringBuilder object to store the DOT code
    StringBuilder dotCodeBuilder = new StringBuilder();

    // Append the DOT code header
    dotCodeBuilder.append("digraph automaton {\n");
    dotCodeBuilder.append("\trankdir=LR;\n");
    dotCodeBuilder.append("\tnode [shape = circle];\n");

    // Add the states to the DOT code
    for (int i = 0; i < numStates; i++) {
        dotCodeBuilder.append("\t").append(i).append(";\n");
    }

    // Add the transitions to the DOT code
    for (int i = 0; i < numStates; i++) {
        for (int j = 0; j < alphabet.length; j++) {
            int targetState = random.nextInt(numStates);
            dotCodeBuilder.append("\t").append(i).append(" -> ").append(targetState).append(" [label = \"").append(alphabet[j]).append("\"];\n");
        }
    }

    // Append the DOT code footer
    dotCodeBuilder.append("}");

    // Return the serialized (DOT) representation of the automaton
    return dotCodeBuilder.toString();
}
