public void createNewState(Node newNode) {
    if(newNode == null) {
        throw new IllegalArgumentException("Node cannot be null.");
    }
    // check if any leaf node in the subtree of the input node contains the same label as the incoming transition
    boolean labelExists = false;
    Queue<Node> queue = new LinkedList<>();
    queue.offer(newNode);
    while(!queue.isEmpty()) {
        Node node = queue.poll();
        if(node.isLeaf() && node.getStateLabel().equals(newNode.getIncomingTransitionLabel())) {
            labelExists = true;
            break;
        }
        for(Node child : node.getChildren()) {
            queue.offer(child);
        }
    }
    // if the label does not exist, create a new leaf node with the same label as the incoming transition
    if(!labelExists) {
        Node newState = new Node(newNode.getIncomingTransitionLabel());
        newNode.addChild(newState);
    }
}
