public void elimination(double[][] A, double[] b, int[] index) {
    int n = b.length;

    for (int k = 0; k < n - 1; k++) {
        int pivot = k;
        for (int i = k + 1; i < n; i++) {
            if (Math.abs(A[i][k]) > Math.abs(A[pivot][k])) {
                pivot = i;
            }
        }
        double[] temp = A[k];
        A[k] = A[pivot];
        A[pivot] = temp;

        double t = b[k];
        b[k] = b[pivot];
        b[pivot] = t;

        index[k] = pivot;

        for (int i = k + 1; i < n; i++) {
            double factor = A[i][k] / A[k][k];
            b[i] -= factor * b[k];
            for (int j = k + 1; j < n; j++) {
                A[i][j] -= factor * A[k][j];
            }
        }
    }
    index[n - 1] = n - 1;
}
