public JSONArray convertListToJsonArray(List<?> values) {
    if (values == null) {
        return null;
    }
    JSONArray jsonArray = new JSONArray();
    for (Object value : values) {
        if (value instanceof Map) {
            validateMapKeys((Map<?, ?>) value);
        }
        jsonArray.put(value);
    }
    return jsonArray;
}

private void validateMapKeys(Map<?, ?> map) {
    for (Object key : map.keySet()) {
        if (!(key instanceof String)) {
            throw new ClassCastException("Map keys must be String type");
        }
    }
}
