public static LatLong calculateEndPoint(LatLong startPoint, double bearing, double distance) {
    double R = 6378.1; // Radius of the earth in km
    double lat1 = Math.toRadians(startPoint.getLatitude());
    double lon1 = Math.toRadians(startPoint.getLongitude());
    double brng = Math.toRadians(bearing);
    double d = distance / 1000.0; // convert distance from meters to km

    double lat2 = Math.asin(Math.sin(lat1) * Math.cos(d / R) + Math.cos(lat1) * Math.sin(d / R) * Math.cos(brng));
    double lon2 = lon1 + Math.atan2(Math.sin(brng) * Math.sin(d / R) * Math.cos(lat1), Math.cos(d / R) - Math.sin(lat1) * Math.sin(lat2));

    return new LatLong(Math.toDegrees(lat2), Math.toDegrees(lon2));
}
