public static double expInternal(double x, double extra, double[] hiPrec) {
    final double LOG_2_A = 0.693147180559945309417232121458176568075500134360255254120680009, // log(2)A
            INV_LOG_2 = 1.4426950408889633870046509400708600878710918106928694473554, // 1/log(2)
            LOG_E_2 = 1.442695040888963387; // log(e)/log(2)

    double[] xa = new double[2];
    double[] xb = new double[2];
    double[] ya = new double[2];
    double[] yb = new double[2];
    double[] za = new double[2];
    double[] zb = new double[2];
    double[] wa = new double[2];
    double[] wb = new double[2];

    double hiPrec[]; // Declare once to avoid repeated allocation of the same memory
    if (hiPrec == null) {
        hiPrec = new double[2];
    }

    // Multipliers used in multiplication algorithm below
    final double RECIP_2PI[] = {0.5 * INV_PI, -1.5625e-2, 1.80013976e-4, -1.98412698e-6, 2.15111584e-8,
            -2.50521084e-10, 2.75573192e-12, -2.50519036e-14, 1.605904383e-16, -7.64716373e-19, 2.81078655e-21};

    double d;
    int k;

    double tmp1;
    double tmp2;
    double tmp3;
    double tmp4;
    double tmp5;
    double tmp6;
    double tmp7;
    double tmp8;

    double adjFactor = 0.0;

    if (x < 0.0) {
        // Calculation for positive x.
        x = -x;
        adjFactor = 1.0;
    }

    tmp1 = FastMath.floor(LOG_E_2 * x + 0.5);
    k = (int) tmp1;

    if (k >= 0 && k < EXP_FRAC_TABLE_LEN) {
        if (FastMath.abs(x) < MAX_ABS_VALUE) {
            // Compute exp(x) using the following Taylor series:
            // exp(x) = 1 + x + x^2/2! + x^3/3! + x^4/4! + ...
            // We sum the above series up to x^9/9! term.
            final long bits = Double.doubleToLongBits(x);
            final int exponent = (int) (bits >> 52) & 0x7FF;
            // Normalize X and split it up into two components
            xa[0] = bits & 0x000FFFFFFFFFFFFFL; // Retrieve lower order bits
            xa[0] |= 0x3FF0000000000000L; // Set exponent to 1023 (Bit 62 represents the sign - see IEEE 754 standard)
            xa[0] >>>= (IEEE_754_DOUBLE_BIAS + 52 - exponent); // Adjust exponent
            xa[1] = x - Double.longBitsToDouble(xa[0]); // Compute lower order part of x
            // Compute higher order terms accurate to at least 4 decimal places
            tmp1 = 1.0 + x;
            tmp2 = x * x * 0.5;
            tmp3 = tmp2 * x / 3.0;
            tmp4 = tmp3 * x * 0.25;
            tmp5 = xa[1] * extra;
            tmp6 = tmp4 * x * 0.2;
            tmp7 = tmp6 * x / 7.0;
            final double sum = (tmp7 + tmp5 + tmp4 + tmp3 + tmp2 + tmp1) + 1.0;
            hiPrec[0] = sum - adjFactor;
            hiPrec[1] = -(hiPrec[0] - sum + adjFactor);
            tmp8 = (hiPrec[0] - adjFactor) - tmp1;
            hiPrec[1] += tmp8;
            hiPrec[0] -= tmp8;
            // Do checks for over/underflow here
            if (hiPrec[0] >= MAX_VALUE) {
                hiPrec[0] = Double.POSITIVE_INFINITY;
                hiPrec[1] = 0.0;
            } else {
                if (hiPrec[0] < MIN_VALUE) {
                    // Underflow - use a crude approximation for exp(x)
                    // that should be accurate for this case to within a
                    // few decimal places.
                    xa[0] = 1L << 52;
                    xa[0] >>>= (IEEE_754_DOUBLE_BIAS - exponent);
                    xa[1] = 0.0;
                    adjFactor = (x > 0.0) ? -adjFactor : adjFactor;
                    final double denom = 1 << -(k + 1);
                    final double num = 1.0 / denom + 1.0 / (denom * denom);
                    tmp1 = num * 0.5 + 1.0;
                    tmp1 *= xa[0];
                    hiPrec[0] = tmp1 - adjFactor;
                    hiPrec[1] = -(hiPrec[0] - tmp1 + adjFactor);
                }
            }
        } else {
            hiPrec = exp(x);
            adjFactor = (x > 0.0) ? -1.0 : 1.0;
        }
        // Multiply by power of 2
        if (k != 0) {
            final long exp = ((long) k) << 52;
            final double p2 = Double.longBitsToDouble(exp);
            hiPrec[0] *= p2;
            hiPrec[1] *= p2;
        }
    } else {
        // Calculation for large positive x.
        if (x <= MAX_VALUE) {
            // Set z = x/2^k.
            tmp1 = floor((LOG_2_A * x) + 0.5);
            tmp2 = tmp1;
            double iP2HC[] = TWO_POWER_2_HC.clone();
            for (int i = 0; i < TWO_POWER_2.length; i++) {
                if (tmp2 >= 2048.0) {
                    iP2HC = twoSum(iP2HC[0] * 2.0, iP2HC[1] * 2.0);
                    tmp2 -= 2048.0;
                } else {
                    break;
                }
            }
            final double z = x - tmp1 * INV_LOG_2;
            final double adjustment = 0.5 * z - tmp1 * LOG_2_A;
            adjFactor = -adjustment;
            // Compute (exp(z) - 1.0) * 2^k
            final double[] hiPrec2 = new double[2];
            final double[] loPrec = new double[2];
            expFormulaA(z, hiPrec2, loPrec);
            hiPrec[0] = expSchmidt(hiPrec2) * iP2HC[0];
            hiPrec[1] = expSchmidt(hiPrec2) * iP2HC[1];
            tmp1 = hiPrec[0] - adjFactor;
            tmp2 = (hiPrec[0] - tmp1) - adjFactor;
            tmp3 = hiPrec[1] - adjFactor;
            tmp4 = (hiPrec[1] - tmp3) - adjFactor;
            tmp5 = tmp3 * tmp2;
            // Compute exponentially scaled cosh/ sinh
            final double[] coshSinh = coshSinh(tmp1);
            final double sinh = coshSinh[1];
            final double cosh = coshSinh[0];
            // Compute combination of sinh and cosh
            tmp7 = sinh + cosh;
            tmp8 = sinh - cosh;
            // Compute exponentially scaled sine and cosine
            final double[] sinCos = sinCos(tmp2);
            tmp1 = sinCos[0] - adjFactor;
            tmp2 = (sinCos[0] - tmp1) - adjFactor;
            final double cos = sinCos[0];
            final double sin = sinCos[1];
            // Compute and subtract the remainder term r1
            tmp3 = ((tmp8 * tmp1 + tmp7 * tmp2) - tmp5 * INV_TWOPI[0]) * iP2HC[0];
            tmp4 = ((tmp8 * tmp2 + tmp7 * tmp1) - tmp5 * INV_TWOPI[1]) * iP2HC[1];
            final double r1 = tmp3 + tmp4;
            hiPrec[1] = (hiPrec[1] + loPrec[1]) * iP2HC[0] + r1;
            hiPrec[0] = (hiPrec[0] + loPrec[0]) * iP2HC[0] + hiPrec[1];
            if (hiPrec[0] >= MAX_VALUE) {
                hiPrec[0] = Double.POSITIVE_INFINITY;
                hiPrec[1] = 0.0;
            }
        } else {
            hiPrec[0] = Double.POSITIVE_INFINITY;
            hiPrec[1] = 0.0;
        }
    }
    return hiPrec[0] + adjFactor;
}
