public int calculateOffset(String path, ResourceResolver resourceResolver) {
    Resource resource = resourceResolver.getResource(path);
    if (resource != null && (resource.getResourceType().equals("cq:Page") || resource.getResourceType().equals("cq:PageContent"))) {
        ValueMap valueMap = resource.getValueMap();
        if (valueMap.containsKey("cq:isVersion")) {
            return valueMap.get("cq:isVersion", Boolean.class) ? 1 : 0;
        } else if (valueMap.containsKey("cq:liveRelationship") && StringUtils.isNotBlank(valueMap.get("cq:liveRelationship", String.class))) {
            return 1;
        }
    }
    return 0;
}
