public boolean isJarIgnoredByCDI(ModuleContainer moduleContainer, ModuleType type) {
    boolean isBeansXmlPresent = false;
    // check if beans.xml is present in the jar file
    try (InputStream is = moduleContainer.getModuleAsInputStream(type, "META-INF/beans.xml")) {
        isBeansXmlPresent = is != null;
    } catch (IOException e) {
        // do nothing
    }

    boolean isImplicitBeanArchiveScanningDisabled = false;
    // check if implicit bean archive scanning is disabled in the server.xml
    try {
        ServerEnvironment serverEnv = CDI.current().getBeanManager().getExtension(ServerEnvironment.class);
        isImplicitBeanArchiveScanningDisabled = serverEnv.isImplicitBeanArchiveScanningDisabled();
    } catch (IllegalStateException | SecurityException e) {
        // do nothing
    }

    return !isBeansXmlPresent && isImplicitBeanArchiveScanningDisabled;
}
