public void dragOntoWidget(Widget widget, String dropPos) {
    // implementation code here
    // Example:
    if (dropPos.equals("CENTER")) {
        widget.add(this);
    } else if (dropPos.equals("EDGE")) {
        widget.add(this, BorderLayout.NORTH);
    } else if (dropPos.equals("BETWEEN")) {
        // calculate middle position
        int x = widget.getX() + (widget.getWidth() - this.getWidth()) / 2;
        int y = widget.getY() + (widget.getHeight() - this.getHeight()) / 2;
        this.setLocation(x, y);
        widget.add(this);
    }
}
