public void releaseConnection(Connection conn, boolean closeClient) {
    // Release the connection and decrement the active connection count
    pool.releaseConnection(conn);

    // If there are no more users against the connection and closeClient is true,
    // then close the underlying client connection
    if (closeClient && pool.getActiveConnections(conn) == 0) {
        pool.closeClient(conn.getClient());
    }
}
