public boolean isArchiveRequestedForAnalysis(String[] rootModules, String[] commandLineModules, String[] systemModules) {
    List<String> requestedModules = new ArrayList<>();
    requestedModules.addAll(Arrays.asList(rootModules));

    if (commandLineModules != null) {
        requestedModules.addAll(Arrays.asList(commandLineModules));
    }

    if (systemModules != null) {
        for (String module : systemModules) {
            if (module.startsWith("java.") || module.startsWith("jdk.")) {
                continue;
            }

            requestedModules.add(module);
        }
    }

    return !requestedModules.isEmpty();
