public void parseFromInputStream(InputStream stream) throws IOException {
    // create a new instance of SAXParserFactory
    SAXParserFactory factory = SAXParserFactory.newInstance();

    try {
        // create a new instance of SAXParser
        SAXParser parser = factory.newSAXParser();

        // create a new instance of XMLReader
        XMLReader reader = parser.getXMLReader();

        // set the content handler for the reader
        reader.setContentHandler(new DefaultHandler());

        // parse the input stream using the reader
        reader.parse(new InputSource(stream));
    } catch (ParserConfigurationException | SAXException e) {
        throw new IOException("Failed to parse input stream", e);
    }
}
