public List<CDKRMap> bitSetToSubstructureMap(BitSet set) {
    List<CDKRMap> substructureMap = new ArrayList<>();
    for (int i = set.nextSetBit(0); i >= 0; i = set.nextSetBit(i+1)) {
        CDKRNode node = graph1.getNode(i); // assuming graph1 is accessible
        CDKRMap subMap = new CDKRMap();
        subMap.put(node, graph2.getNode(set.nextSetBit(i+1))); // assuming graph2 is accessible
        substructureMap.add(subMap);
    }
    return substructureMap;
}
