public static double simpleExpSmoothing(List<Double> flatDataList, double a) {
  double s = flatDataList.get(0);
  for (int i = 1; i < flatDataList.size(); i++) {
    s = a * flatDataList.get(i) + (1 - a) * s;
  }
  return s;
}
