public double feasibilityRatio(List<S> solutionSet) {
    double aux = 0.0;
    for (int i = 0; i < solutionSet.size(); i++) {
      if (overallConstraintViolation.getAttribute(solutionSet.get(i)) < 0) {
        aux = aux + 1.0;
      }
