import org.apache.commons.math3.exception.MathException;
import org.apache.commons.math3.distribution.NormalDistribution;

public static double getRandomValue(double minX, double maxX) throws MathException {
    NormalDistribution normalDistribution = new NormalDistribution();
    double mean = (minX + maxX) / 2;
    double standardDeviation = (maxX - minX) / 6;
    if (standardDeviation <= 0) {
        throw new MathException("Invalid standard deviation value");
    }
    return normalDistribution.inverseCumulativeProbability(Math.random()) * standardDeviation + mean;
}
