public short readMemoryAtPosition(int position) throws IndexOutOfBoundsException {
    if(position < 0 || position > segmentSize - 2){
        throw new IndexOutOfBoundsException("Index out of range!");
    }
    byte b1 = memory[position];
    byte b2 = memory[position + 1];
    if(byteOrder == ByteOrder.BIG_ENDIAN){
        return (short) ((b1 << 8) | (b2 & 0xFF));
    } else {
        return (short) ((b2 << 8) | (b1 & 0xFF));
    }
}
