public static void injectProperties(Object bean, Properties props) {
    for (String propName : props.stringPropertyNames()) {
        String propValue = props.getProperty(propName);
        try {
            Method setter = bean.getClass().getMethod("set" + propName, String.class);
            setter.invoke(bean, propValue);
        } catch (NoSuchMethodException e) {
            // Ignore properties that do not have a matching setter
        } catch (IllegalAccessException | InvocationTargetException e) {
            throw new RuntimeException("Error setting property " + propName + " on object of type " + bean.getClass().getName(), e);
        }
    }
}
