public double calculateCMMMatching(int[][] foundClusters, int[][] groundTruthClusters){
    int numFoundClusters = foundClusters.length;
    int numGroundTruthClusters = groundTruthClusters.length;
    int[][] overlaps = new int[numFoundClusters][numGroundTruthClusters];
    for(int i=0; i<numFoundClusters; i++){
        for(int j=0; j<numGroundTruthClusters; j++){
            overlaps[i][j] = calculateOverlap(foundClusters[i], groundTruthClusters[j]);
        }
    }
    int[] maxFoundOverlap = new int[numFoundClusters];
    int[] maxGroundTruthOverlap = new int[numGroundTruthClusters];
    Arrays.fill(maxFoundOverlap, -1);
    Arrays.fill(maxGroundTruthOverlap, -1);
    for(int i=0; i<numFoundClusters; i++){
        for(int j=0; j<numGroundTruthClusters; j++){
            if(overlaps[i][j] > maxFoundOverlap[i]){
                maxFoundOverlap[i] = overlaps[i][j];
            }
            if(overlaps[i][j] > maxGroundTruthOverlap[j]){
                maxGroundTruthOverlap[j] = overlaps[i][j];
            }
        }
    }
    int sumMaxOverlap = 0;
    for(int i=0; i<numFoundClusters; i++){
        sumMaxOverlap += maxFoundOverlap[i];
    }
    double clusterError = 1.0 - (sumMaxOverlap / (double)(foundClusters.length));
    return clusterError;
}

private int calculateOverlap(int[] cluster1, int[] cluster2){
    int overlap = 0;
    for(int i=0; i<cluster1.length; i++){
        for(int j=0; j<cluster2.length; j++){
            if(cluster1[i] == cluster2[j]){
                overlap++;
            }
        }
    }
    return overlap;
}
