public boolean sameExecutionIds(Object obj1, Object obj2) {
    if (obj1 == null || obj2 == null) {
        return false;
    }
    if (!obj1.getClass().equals(obj2.getClass())) {
        return false;
    }
    if (obj1.equals(obj2)) {
        return true;
    }
    // Check if obj1 and obj2 have the same fields except the execution id
    Field[] fields = obj1.getClass().getDeclaredFields();
    for (Field field : fields) {
        if (!field.getName().equals("executionId")) {
            try {
                field.setAccessible(true);
                Object value1 = field.get(obj1);
                Object value2 = field.get(obj2);
