public static <T> Object setValue(JSONObject jsonObject, String configuration, T value) {
    String[] path = configuration.split("\\.");
    int length = path.length - 1;

    for (int i = 0; i < length; i++) {
        String key = path[i];

        if (!jsonObject.has(key) || !(jsonObject.get(key) instanceof JSONObject)) {
            jsonObject.put(key, new JSONObject());
        }

        jsonObject = jsonObject.getJSONObject(key);
    }

    String key = path[length];

    if (!jsonObject.has(key) || !(jsonObject.get(key) instanceof JSONObject)) {
        if (Configuration.AS_PATH_LIST.equals(Configuration.getValue(Configuration.Option.OPTIONS))) {
            JSONArray pathList = new JSONArray();
            pathList.put(configuration);
            return pathList;
        } else {
            jsonObject.put(key, value);
        }
    } else {
        if (Configuration.AS_PATH_LIST.equals(Configuration.getValue(Configuration.Option.OPTIONS))) {
            JSONArray pathList = new JSONArray();
            JSONArray jsonArray = jsonObject.getJSONArray(key);

            for (int i = 0; i < jsonArray.length(); i++) {
                String subConfiguration = configuration + "." + jsonArray.getJSONObject(i).get("key");
                pathList.put(setValue(jsonObject, subConfiguration, value));
            }

            pathList.put(configuration);
            return pathList;
        } else {
            setValue(jsonObject.getJSONObject(key), path[length + 1], value);
        }
    }

    return jsonObject;
}
