public void delCacheEntry(CacheEntry cacheEntry) {
    // Assuming that cacheEntry has dataIds and templates
    // Loop through each dataId and template and remove dependency from cacheEntry
    for (String dataId : cacheEntry.getDataIds()) {
        removeDependency(cacheEntry, dataId);
    }
    for (String template : cacheEntry.getTemplates()) {
        removeDependency(cacheEntry, template);
    }
    // Delete cacheEntry from the disk
    File file = new File(cacheEntry.getFilePath());
    file.delete();
}

private void removeDependency(CacheEntry cacheEntry, String dependency) {
    cacheEntry.getDependencies().remove(dependency);
}
