import java.io.File;
import java.net.URI;

public static String getLocalFilePath(URI uri) throws IllegalArgumentException {
    if (uri == null) {
        throw new IllegalArgumentException("The uri is null");
    }
    if (!uri.isAbsolute()) {
        throw new IllegalArgumentException("The uri is not absolute");
    }
    String scheme = uri.getScheme();
    if (scheme == null || !(scheme.equalsIgnoreCase("file") || scheme.equalsIgnoreCase("jar"))) {
        throw new IllegalArgumentException("The uri scheme must be either file or jar");
    }
    try {
        String path = uri.getPath();
        if (scheme.equalsIgnoreCase("jar")) {
            int index = path.indexOf("!/");
            if (index != -1) {
                path = path.substring(0, index);
            }
            URI jarURI = URI.create(path);
            path = getLocalFilePath(jarURI);
        }
        else {
            if (File.separatorChar != '/') {
                path = path.replace('/', File.separatorChar);
            }
            if (path.startsWith(File.separator)) {
                path = path.substring(1);
            }
        }

        return new File(path).getAbsolutePath();
    }
    catch (Exception e) {
        throw new IllegalArgumentException("Unable to resolve the uri to an absolute file path", e);
    }
}
