public boolean hasAnnotation(String annotationName, AnnotatedElement element) {
    boolean isInvisible = element.isAnnotationPresent(Invisible.class);
    boolean isVisible = element.isAnnotationPresent(Visible.class);

    if (isInvisible || isVisible) {
        Annotation[] annotations = null;

        if (isVisible) {
            annotations = element.getAnnotationsByType(Visible.class);
        } else if (isInvisible) {
            annotations = element.getAnnotationsByType(Invisible.class);
        }

        for (Annotation annotation : annotations) {
            if (annotation.annotationType().getName().equals(annotationName)) {
                return true;
            }
        }
    }

    return false;
}

@Retention(RetentionPolicy.RUNTIME)
private @interface Visible {
}

@Retention(RetentionPolicy.RUNTIME)
private @interface Invisible {
}
