public class InfinityComparator<T> implements Comparator<T> {

   private final Comparator<T> comparator;

   public InfinityComparator(Comparator<T> comparator) {
       this.comparator = comparator;
   }

   @Override
   public int compare(T a, T b) {
       if (a == null && b == null) {
           return 0;
       } else if (a == null) {
           return 1;
       } else if (b == null) {
           return -1;
       } else if (a.equals(b)) {
           return 0;
       } else if (a.equals(Double.POSITIVE_INFINITY)) {
           return 1;
       } else if (b.equals(Double.POSITIVE_INFINITY)) {
           return -1;
       } else if (a.equals(Double.NEGATIVE_INFINITY)) {
           return -1;
       } else if (b.equals(Double.NEGATIVE_INFINITY)) {
           return 1;
       } else {
           return comparator.compare(a, b);
       }
   }
}
