public int getRotationType(double[][] m) {
    int n = m.length;
    double det = getDeterminant(m);
    double trace = 0;
    for (int i = 0; i < n; i++) {
        trace += m[i][i];
    }
    if (Math.abs(det - 1.0) > 1e-8) {
        if (Math.abs(det + 1.0) < 1e-8) {
            return -1;
        } else {
            return -2;
        }
    } else {
        if (Math.abs(trace - n) < 1e-8) {
            return 1;
        } else if (Math.abs(trace + n) < 1e-8) {
            return -3;
        } else {
            boolean proper = true;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < i; j++) {
                    if (Math.abs(m[i][j] - m[j][i]) > 1e-8) {
                        proper = false;
                        break;
                    }
                }
                if (!proper) {
                    break;
                }
            }
            if (proper) {
                int fold = getFold(m);
                return fold > 0 ? fold : -fold;
            } else {
                int fold = getFold(m);
                return fold > 0 ? -fold : fold;
            }
        }
    }
}

private double getDeterminant(double[][] m) {
    int n = m.length;
    if (n == 2) {
        return m[0][0] * m[1][1] - m[0][1] * m[1][0];
    }
    double det = 0;
    for (int i = 0; i < n; i++) {
        double[][] submatrix = new double[n - 1][n - 1];
        for (int j = 1; j < n; j++) {
            for (int k = 0; k < n; k++) {
                if (k < i) {
                    submatrix[j - 1][k] = m[j][k];
                } else if (k > i) {
                    submatrix[j - 1][k - 1] = m[j][k];
                }
            }
        }
        if (i % 2 == 0) {
            det += m[0][i] * getDeterminant(submatrix);
        } else {
            det -= m[0][i] * getDeterminant(submatrix);
        }
    }
    return det;
}

private int getFold(double[][] m) {
    int n = m.length;
    while (n > 1 && Math.abs(m[n - 1][n - 1] - 1.0) < 1e-8) {
        n--;
    }
    double[][] rm = new double[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            rm[i][j] = m[i][j];
        }
    }
    double eps = 1e-8;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (Math.abs(rm[i][j]) < eps) {
                rm[i][j] = 0.0;
            }
        }
    }
    double[][] rot = new double[n][n];
    double[][] tmp = new double[n][n];
    for (int i = 0; i < n; i++) {
        rot[i][i] = 1.0;
    }
    boolean isRotational = true;
    for (int k = 0; k < 12; k++) { // Repeat at most 12 times
        boolean found = false;
        int i0 = 0, j0 = 0;
        for (int i = 0; i < n && !found; i++) {
            for (int j = i + 1; j < n && !found; j++) {
                if (Math.abs(rm[i][j] - rm[j][i]) > eps) {
                    i0 = i;
                    j0 = j;
                    found = true;
                }
            }
        }
        if (!found) {
            break;
        }
        double aii = rm[i0][i0], ajj = rm[j0][j0];
        double aij = rm[i0][j0], aji = rm[j0][i0];
        double sgn = Math.signum(aii - ajj);
        double t = sgn / (2 * Math.sqrt(aij * aji));
        double c = 1.0 / Math.sqrt(1 + t * t);
        double s = c * t;
        for (int i = 0; i < n; i++) {
            if (i != i0 && i != j0) {
                tmp[i][i] = 1.0;
            } else {
                tmp[i][i] = c;
                tmp[i0][j0] = sgn * s;
                tmp[j0][i0] = -s;
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                rot[i][j] = 0.0;
                for (int k = 0; k < n; k++) {
                    rot[i][j] += tmp[i][k] * rot[k][j];
                }
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                double sum = 0.0;
                for (int k = 0; k < n; k++) {
                    sum += rot[i][k] * rm[k][j];
                }
                rm[i][j] = sum;
            }
        }
        double tr = 0;
        for (int i = 0; i < n; i++) {
            tr += rm[i][i];
        }
        if (Math.abs(Math.abs(tr) - n) > eps) {
            isRotational = false;
            break;
        }
    }
    if (isRotational) {
        double[][] v = new double[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                v[i][j] = m[i][j];
            }
        }
        double[][] vv = new double[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                vv[i][j] = 0.0;
                for (int k = 0; k < n; k++) {
                    vv[i][j] += rot[i][k] * v[k][j];
                }
            }
        }
        double[][] err = new double[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                double sum = 0.0;
                for (int k = 0; k < n; k++) {
                    sum += rm[i][k] * vv[k][j];
                }
                err[i][j] = m[i][j] - sum;
            }
        }
        double rmsd = 0.0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                rmsd += err[i][j] * err[i][j];
            }
        }
        rmsd = Math.sqrt(rmsd / (n * n));
        if (Math.abs(rmsd) > eps) {
            isRotational = false;
        }
    }
    if (isRotational) {
        double[] eval = new double[n];
        double[][] evec = new double[n][n];
        eigenvalueDecomposition(rm, eval, evec);
        double[] d = new double[n];
        for (int i = 0; i < n; i++) {
            d[i] = Math.abs(Math.abs(eval[i]) - 1.0);
        }
        double mind = Double.POSITIVE_INFINITY;
        int minj = -1;
        for (int j = 0; j < n; j++) {
            if (d[j] < mind) {
                mind = d[j];
                minj = j;
            }
        }
        if (Math.abs(Math.abs(eval[minj]) - 1.0) < eps) {
            return -1; // Improper rotation
        } else {
            int fold = 0;
            if (Math.abs(eval[minj] - Math.cos(2 * Math.PI / 2)) < eps) {
                fold = 2;
            } else if (Math.abs(eval[minj] - Math.cos(2 * Math.PI / 3)) < eps) {
                fold = 3;
            } else if (Math.abs(eval[minj] - Math.cos(2 * Math.PI / 4)) < eps) {
                fold = 4;
            } else if (Math.abs(eval[minj] - Math.cos(2 * Math.PI / 6)) < eps) {
                fold = 6;
            }
            return fold;
        }
    } else {
        return -1; // Inversion
    }
}

private void eigenvalueDecomposition(double[][] a, double[] eval, double[][] evec) {
    int n = a.length;
    double[] d = new double[n];
    double[] e = new double[n];
    double[][] v = new double[n][n];
    for (int j = 0; j < n; j++) {
        eval[j] = a[n - 1][j];
        v[n - 1][j] = 0.0;
    }
    v[n - 1][n - 1] = 1.0;
    for (int i = n - 2; i >= 0; i--) {
        double scale = 0.0;
        double h = 0.0;
        for (int k = 0; k <= i; k++) {
            scale = scale + Math.abs(eval[k]);
        }
        if (scale == 0.0) {
            e[i] = eval[i];
            for (int j = 0; j < i; j++) {
                eval[j] = a[i - 1][j];
                a[i][j] = 0.0;
                a[j][i] = 0.0;
            }
        } else {
            for (int k = 0; k <= i; k++) {
                eval[k] /= scale;
                h += eval[k] * eval[k];
            }
            double f = eval[i];
            double g = Math.sqrt(h);
            if (f > 0) {
                g = -g;
            }
            e[i] = scale * g;
            h = h - f * g;
            eval[i] = f - g;
            for (int j = 0; j < n; j++) {
                evec[i][j] = 0.0;
            }
            for (int j = 0; j <= i; j++) {
                eval[j] = eval[j] - eval[i];
                evec[i][j] = eval[j];
            }
            f = 0.0;
            for (int j = 0; j <= i; j++) {
                eval[j] /= h;
                f += eval[j] * evec[i][j];
            }
            double hh = f / (h + h);
            for (int j = 0; j <= i; j++) {
                eval[j] -= hh * evec[i][j];
            }
            for (int j = 0; j < n; j++) {
                f = evec[i][j];
                evec[i][j] = v[j][i] + hh * evec[i][j];
                v[j][i] = -hh * f + v[j][i];
            }
        }
    }
    for (int i = 0; i < n; i++) {
        eval[i] = eval[i] + e[i];
    }
    for (int i = 0; i < n; i++) {
        int k = i;
        double p = eval[i];
        for (int j = i + 1; j < n; j++) {
            if (eval[j] < p) {
                k = j;
                p = eval[j];
            }
        }
        if (k != i) {
            eval[k] = eval[i];
            eval[i] = p;
            for (int j = 0; j < n; j++) {
                p = evec[j][i];
                evec[j][i] = evec[j][k];
                evec[j][k] = p;
            }
        }
    }
}
