public String transformToDNF(String query) {
    // First parse the query into a tree of nodes
    Node topNode = parseQuery(query);

    // Then apply the transformations to convert to DNF
    Node dnfNode = applyTransformations(topNode);

    // Finally, serialize the DNF tree back into a query string
    return serializeNode(dnfNode);
}
