public double getOffset(Symbolizer symbolizer) {
    double offset = 0.0;
    if (symbolizer instanceof LineSymbolizer) {
        LineSymbolizer lineSymbolizer = (LineSymbolizer) symbolizer;
        if (lineSymbolizer.getStroke() != null) {
            offset = lineSymbolizer.getStroke().getDashOffset();
        }
    } else if (symbolizer instanceof PointSymbolizer) {
        PointSymbolizer pointSymbolizer = (PointSymbolizer) symbolizer;
        if (pointSymbolizer.getGraphic() != null && pointSymbolizer.getGraphic().getDisplacement() != null) {
            offset = pointSymbolizer.getGraphic().getDisplacement().getY();
        }
    }

    return offset;
}
