import java.util.ArrayList;
import java.util.List;
import java.util.function.Function;
import java.util.function.Predicate;

public class SelectableItems {

    public static <T> List<SelectableItem<T>> create(List<T> items, Function<T, Long> idExtractor, Function<T, String> nameExtractor, Predicate<T> selectPredicate) {
        List<SelectableItem<T>> selectableItems = new ArrayList<>();
        for (T item : items) {
            boolean selected = selectPredicate.test(item);
            long id = idExtractor.apply(item);
            String name = nameExtractor.apply(item);
            SelectableItem<T> selectableItem = new SelectableItem<>(id, name, selected, item);
            selectableItems.add(selectableItem);
        }
        return selectableItems;
    }

    public static class SelectableItem<T> {
        private final long id;
        private final String name;
        private boolean selected;
        private final T item;

        public SelectableItem(long id, String name, boolean selected, T item) {
            this.id = id;
            this.name = name;
            this.selected = selected;
            this.item = item;
        }

        public long getId() {
            return id;
        }

        public String getName() {
            return name;
        }

        public boolean isSelected() {
            return selected;
        }

        public void setSelected(boolean selected) {
            this.selected = selected;
        }

        public T getItem() {
            return item;
        }
    }

}
