@Override
public void clear() {
    checkStatusStarted();
    final MutableLong clearCount = new MutableLong();
    final MutableLong removeCount = new MutableLong();
    final MutableLong evictedCount = new MutableLong();
    final MutableLong expiredCount = new MutableLong();
    try (AutoCloseableIterable<Cache.Entry<K, V>> entries = cacheEntries()) {
        for (Cache.Entry<K, V> entry : entries) {
            if (entry != null) {
                boolean removed = cache.remove(entry.getKey(), entry.getValue());
                if (removed) {
                    removeCount.increment();
                }
            }
        }
    } finally {
        clearCount.increment();
        statsCounter().onClear(removeCount.value(), evictedCount.value(), expiredCount.value());
        fireEvent(CacheEntryRemovedListener.REMOVED, null, null, false);
    }
}
