public static void runJavacWithNullAway(String[] args) {
    List<String> newArgs = new ArrayList<>(Arrays.asList("-Xplugin:NullAway", "-Xep:NullAway:WARN"));
    newArgs.addAll(Arrays.asList(args));
    try {
        ProcessBuilder processBuilder = new ProcessBuilder("javac", String.join(" ", newArgs));
        Process process = processBuilder.start();
        int exitCode = process.waitFor();
        if (exitCode != 0) {
            System.err.println("Javac compilation failed with exit code " + exitCode);
        }
    } catch (IOException | InterruptedException e) {
        System.err.println("Failed to run javac with NullAway: " + e.getMessage());
    }

    try {
        ProcessBuilder processBuilder = new ProcessBuilder("javac", String.join(" ", args));
        Process process = processBuilder.start();
        int exitCode = process.waitFor();
        if (exitCode != 0) {
            System.err.println("Javac compilation failed with exit code " + exitCode);
        }
    } catch (IOException | InterruptedException e) {
        System.err.println("Failed to run javac without NullAway: " + e.getMessage());
    }
}
