public boolean matchIPList(Config config, String remoteAddr) {
    List<String> ipList = config.getIPList();
    if(ipList == null || ipList.isEmpty()){
        return false;
    }
    try {
        InetAddress inetAddress = InetAddress.getByName(remoteAddr);
        for (String ip : ipList) {
            if (inetAddress.getHostAddress().matches(ip)) {
                return true;
            }
        }
    } catch (UnknownHostException e) {
        return false;
    }
    return false;
}
