public Map<String, WidgetRequest> generateWidgetRequestList(List<Entry> entries, Dashboard dashboard) throws HygieiaException {
    Map<String, WidgetRequest> widgetRequestList = new HashMap<>();

    for (Entry entry : entries) {
        Widget widget = widgetRepository.findByName(entry.getWidgetName());
        if (widget == null) {
            throw new HygieiaException("Widget not found for name: " + entry.getWidgetName(), HygieiaException.BAD_DATA);
        }

        WidgetRequest widgetRequest = new WidgetRequest();
        widgetRequest.setWidgetId(widget.getId());
        widgetRequest.setWidgetName(widget.getName());
        widgetRequest.setDashboardId(dashboard.getId());
        widgetRequest.setComponentId(dashboard.getComponentId());
        widgetRequest.setOptions(entry.getOptions());

        widgetRequestList.put(entry.getWidgetName(), widgetRequest);
    }
    return widgetRequestList;
}
