public OnClickListener createFabClickListener(final FloatingActionButton fab1, final FloatingActionButton fab2) {
    return new OnClickListener() {
        boolean isFAB1Visible = true;
        boolean isFAB2Visible = true;

        @Override
        public void onClick(View view) {
            if (isFAB1Visible && isFAB2Visible) {
