public String constructResponse(InputStream response, OutputStream outputStream) throws ParserConfigurationException, SAXException, XPathExpressionException, IOException {
    // Create a document builder factory instance
    DocumentBuilderFactory documentBuilderFactory = DocumentBuilderFactory.newInstance();
    DocumentBuilder documentBuilder = documentBuilderFactory.newDocumentBuilder();

    // Parse the response XML
    Document document = documentBuilder.parse(response);

    // Create an XPath instance
    XPath xPath = XPathFactory.newInstance().newXPath();

    // Evaluate the result element using XPath
    Node resultNode = (Node) xPath.evaluate("//result", document, XPathConstants.NODE);

    // Get the encoded result from the result element
    String encodedResult = resultNode.getTextContent();

    // Decode the result using Base64
    byte[] bytes = Base64.getDecoder().decode(encodedResult.getBytes());
    String decodedResult = new String(bytes);

    // Write the decoded result to the output stream
    outputStream.write(decodedResult.getBytes());

    // Return the decoded result
    return decodedResult;
}
