public class FileCopier {
    public static boolean copyFileToDirectory(String source, String dest) {
        Path sourcePath = Paths.get(source);
        Path destinationPath = Paths.get(dest + File.separator + sourcePath.getFileName());

        try {
            Files.copy(sourcePath, destinationPath);
            return true;
        } catch (IOException e) {
            e.printStackTrace();
            return false;
        }
    }
}
