public List<ExpiredItem> readExpiredByRange(Date startDate, Date endDate) {
  List<ExpiredItem> expiredItems = new ArrayList<>();
  // Assuming we have a database connection initialized and available
  try {
    Statement stmt = conn.createStatement();
    String query = "SELECT * FROM expired_items WHERE expiration_date BETWEEN ? AND ?";
    PreparedStatement pstmt = conn.prepareStatement(query);
    pstmt.setDate(1, new java.sql.Date(startDate.getTime()));
    pstmt.setDate(2, new java.sql.Date(endDate.getTime()));
    ResultSet rs = pstmt.executeQuery();
    while (rs.next()) {
      ExpiredItem item = new ExpiredItem(rs.getInt("id"), rs.getString("name"), rs.getDate("expiration_date"));
      expiredItems.add(item);
    }
  } catch (SQLException e) {
    System.out.println("Error reading expired items by range: " + e.getMessage());
  }
  return expiredItems;
}
