public int getNumOutputManagementVertices() {
    int numOutput = 0;
    for (Vertex vertex : this.vertices) {
        if (vertex.getStage() == this.stage && 
                (vertex.getOutputEdges().isEmpty() || 
                 vertex.getOutputEdges().stream().allMatch(e -> e.getTarget().getStage() < this.stage))) {
            numOutput++;
        }
    }
    return numOutput;
}
