public class CollectionTransformer {
    public static <T, R> Collection<R> transform(Collection<T> source, Function<T, R> transformer) {
        Collection<R> result = new ArrayList<>();
        for (T element : source) {
            try {
                R transformedElement = transformer.apply(element); // Apply transformation function
                result.add(transformedElement); // Only add elements that the partial function is defined for
            } catch (RuntimeException ignored) {
                // noop
            }
        }
        return result;
    }
}
