public Process createNewProcess(Process process) throws CalculationException {
    Process newProcess = new LinearInterpolatedProcess(process.getTimeDiscretization());

    for (int i = 0; i < process.getNumberOfTimes(); i++) {
        double time = process.getTime(i);
        double value = process.getValueAtTime(i) + this.getValueAtTime(time);
        newProcess.addTimeAndValue(time, value);
    }

    return newProcess;
}
