public boolean isTypeAcceptable(String headerValue, boolean strict, String type) {
    if (headerValue == null || type == null) {
        return false;
    }
    String[] headerTypes = headerValue.split(",");
    for (String headerType : headerTypes) {
        String[] typeParts = headerType.trim().split(";");
        String headerTypeValue = typeParts[0].toLowerCase();
        if (type.equalsIgnoreCase(headerTypeValue)) {
            return true;
        }
        if (!strict && headerTypeValue.contains("*")) {
            String[] wildCardParts = headerTypeValue.split("/");
            if (type.toLowerCase().contains(wildCardParts[0])) {
                return true;
            }
        }
    }
    return false;
}
