public class CryptoUtils {

    public static byte[] calculateHmac(String crypto, byte[] keyBytes, byte[] text) throws NoSuchAlgorithmException, InvalidKeyException {

        SecretKeySpec key = new SecretKeySpec(keyBytes, crypto);
        Mac mac = Mac.getInstance(crypto);
        mac.init(key);
        return mac.doFinal(text);

    }
}
