public static Set<String> getDirectoryPaths(String pathToJarFile) throws IOException {
    Set<String> directories = new HashSet<>();
    try (ZipFile zip = new ZipFile(pathToJarFile)) {
        Enumeration<? extends ZipEntry> entries = zip.entries();
        while (entries.hasMoreElements()) {
            ZipEntry entry = entries.nextElement();
            if (entry.isDirectory()) {
                directories.add(entry.getName());
            } else {
                String[] parts = entry.getName().split("/");
                if (parts.length > 1) {
                    String dirName = Stream.of(parts).limit(parts.length - 1).collect(Collectors.joining("/"));
                    directories.add(dirName);
                }
            }
        }
    }
    return directories;
}
