public DataTable createRawDataTable(DataTable table, String key) {
    DataTable rawDataTable = new DataTable();

    // Set the lookup key for the new raw data table
    rawDataTable.setLookupKey(key);

    // Copy the columns from the original table to the raw data table
    for (int i = 0; i < table.getColumnCount(); i++) {
        DataColumn column = table.getColumn(i);
        rawDataTable.addColumn(column.getName(), column.getType());
    }

    // Copy the rows from the original table to the raw data table
    for (int j = 0; j < table.getRowCount(); j++) {
        DataRow row = table.getRow(j);

        // Create a new row in the raw data table
        DataRow rawDataRow = rawDataTable.createRow();

        // Set the same values as the original row in the raw data row
        for (int k = 0; k < row.getColumnCount(); k++) {
            DataColumn column = row.getColumn(k);
            rawDataRow.setValue(column.getName(), column.getValue());
        }
    }

    return rawDataTable;
}
