public TargetDataLine getAudioDataLine(Mixer.Info input) throws IOException{
    TargetDataLine line = null;
    DataLine.Info info = new DataLine.Info(TargetDataLine.class, null);
    Mixer mixer = AudioSystem.getMixer(input);

    try {
