public String processResponse(DigestedResponse response, URL url) throws MovieDbException {
    int statusCode = response.getStatusCode();
    if (statusCode >= 400 && statusCode <= 499) {
        throw new MovieDbException("Client error: " + statusCode, url);
    } else if (statusCode >= 500 && statusCode <= 599) {
        throw new MovieDbException("Server error: " + statusCode, url);
    } else if (statusCode != 200 && statusCode != 201) {
        throw new MovieDbException("Unexpected status code: " + statusCode, url);
    }
    return response.getContent();
}
