import org.java_websocket.client.WebSocketClient;
import org.java_websocket.handshake.ServerHandshake;
import java.lang.ref.WeakReference;
import java.net.URI;

public class WebSocketUtil {

    public static WebSocketClient createWebSocketInstance(String token, WeakReference<WebSocketConnectionListener> stateListenerWeakReference) {
        URI uri = URI.create("wss://example.com/websocket");
        WebSocketClient webSocketClient = new WebSocketClient(uri) {
            @Override
            public void onOpen(ServerHandshake handshakedata) {
                WebSocketConnectionListener listener = stateListenerWeakReference.get();
                if (listener != null) {
                    listener.onConnectionOpen();
                }
            }

            @Override
            public void onMessage(String message) {
                // implementation details
            }

            @Override
            public void onClose(int code, String reason, boolean remote) {
                WebSocketConnectionListener listener = stateListenerWeakReference.get();
                if (listener != null) {
                    listener.onConnectionClose();
                }
            }

            @Override
            public void onError(Exception ex) {
                WebSocketConnectionListener listener = stateListenerWeakReference.get();
                if (listener != null) {
                    listener.onConnectionError(ex);
                }
            }
        };

        // set authentication token in the header
        webSocketClient.addHeader("Authorization", "Bearer " + token);

        return webSocketClient;
    }

}
