public static String expandKeyString(String keyString, Map<String, String> properties) {
    String regex = "\\$\\{(.+?)\\}";
    Pattern pattern = Pattern.compile(regex);
    Matcher matcher = pattern.matcher(keyString);
    StringBuffer sb = new StringBuffer();
    while (matcher.find()) {
        String key = matcher.group(1);
        String value = properties.getOrDefault(key, "");
        if (value.contains("${")) {
            value = expandKeyString(value, properties);
        }
        matcher.appendReplacement(sb, value);
    }
    matcher.appendTail(sb);
    return sb.toString();
}
