public Observable<WorkflowInner> createOrUpdateWorkflow(String resourceGroupName, String workflowName, Workflow workflow) throws IllegalArgumentException {
    if (resourceGroupName == null || resourceGroupName.isEmpty()) {
        throw new IllegalArgumentException("Resource group name cannot be null or empty.");
    }
    if (workflowName == null || workflowName.isEmpty()) {
        throw new IllegalArgumentException("Workflow name cannot be null or empty.");
    }
    if (workflow == null) {
        throw new IllegalArgumentException("Workflow cannot be null.");
    }

    return Observable.fromCallable(() -> {
        String apiVersion = "2016-06-01";
        String url = String.format("/subscriptions/%s/resourceGroups/%s/providers/Microsoft.Logic/workflows/%s?api-version=%s",
                subscriptionId, resourceGroupName, workflowName, apiVersion);

        String body = new ObjectMapper().writeValueAsString(workflow);

        RequestBody requestBody = RequestBody.create(MediaType.parse("application/json"), body);

        Request request = new Request.Builder()
                .url(url)
                .put(requestBody)
                .build();

        Response response = httpClient.newCall(request).execute();

        if (response.isSuccessful()) {
            try (ResponseBody responseBody = response.body()) {
                String json = responseBody.string();
                return new ObjectMapper().readValue(json, WorkflowInner.class);
            }
        } else {
            String errorMessage = String.format("Failed to create or update workflow: %s", response.message());
            throw new RuntimeException(errorMessage);
        }
    });
}
