public void removeElementFromArray(Object[] array, Object object) {
    for (int i = 0; i < array.length; i++) {
        if (array[i] == object) {
            int numMoved = array.length - i - 1;
            if (numMoved > 0) {
                System.arraycopy(array, i + 1, array, i, numMoved);
            }
            array[array.length - 1] = null;
            return;
        }
    }
}
