public void reHeap(int position) {
    int current = position;
    int parent = (current - 1) / 2;
    T temp;

    while (elements[current].compareTo(elements[parent]) > 0) {
        temp = elements[parent];
        elements[parent] = elements[current];
        elements[current] = temp;
        current = parent;
        parent = (current - 1) / 2;
    }
}
