public void watchParentFolders(Path p, Path until) throws IOException {
    // Start watching the parent folder of the given path
    Path parent = p.getParent();
    WatchService watcher = FileSystems.getDefault().newWatchService();
    parent.register(watcher, StandardWatchEventKinds.ENTRY_CREATE);

    // Keep watching parent folders until the root listener path has been reached
    while (parent != null && !parent.equals(until)) {
        WatchKey key;
        try {
            key = watcher.take();
        } catch (InterruptedException e) {
            return;
        }
        for (WatchEvent<?> event : key.pollEvents()) {
            if (event.kind() == StandardWatchEventKinds.ENTRY_CREATE) {
                Path newPath = parent.resolve((Path) event.context());
                if (!Files.isDirectory(newPath)) {
                    watchParentFolders(newPath, until);
                }
            }
        }
        key.reset();
        parent = parent.getParent();
        if (parent != until) {
            parent.register(watcher, StandardWatchEventKinds.ENTRY_CREATE);
        }
    }
}
