public int convertXmlElemToInteger(XMLStreamReader reader, String key, String expressions) throws XMLStreamException, ParserException {
    int value = 0;
    while (reader.hasNext()) {
        int event = reader.next();
        if (event == XMLStreamConstants.START_ELEMENT && reader.getLocalName().equals(key)) {
            String text = reader.getElementText();
            if (!text.matches("\\d+")) {
                throw new ParserException("Element is not a number.");
            } else {
                value = Integer.parseInt(text);
                break;
            }
        }
    }
    return value;
}
