public class MyClass {

    public static ExecutableElement findMethod(TypeElement classElement, String methodName) {
        List<? extends ExecutableElement> methods = ElementFilter.methodsIn(classElement.getEnclosedElements());
        for (ExecutableElement method : methods) {
            if (method.getSimpleName().toString().equals(methodName) && method.getParameters().isEmpty()) {
                return method;
            }
        }
        return null;
    }
}
