public List<List<Integer>> getOrbits(List<Integer> subunitIds) {
    List<List<Integer>> orbits = new ArrayList<>();
    List<Integer> visited = new ArrayList<>();
    for (int i = 0; i < subunitIds.size(); i++) {
        if (!visited.contains(i)) {
            List<Integer> orbit = new ArrayList<>();
            orbit.add(i);
            visited.add(i);
            for (int j = i + 1; j < subunitIds.size(); j++) {
                if (!visited.contains(j) && isRotationalEquivalent(subunitIds.get(i), subunitIds.get(j))) {
                    orbit.add(j);
                    visited.add(j);
                }
            }
            orbits.add(orbit);
        }
    }
    return orbits;
}

