import java.util.logging.Logger;

public class MessagePhaseListener implements PhaseListener {

    private static final long serialVersionUID = 1L;
    private static final Logger log = Logger.getLogger(MessagePhaseListener.class.getName());

    @Override
    public synchronized void afterPhase(PhaseEvent event) {
        FacesContext facesContext = event.getFacesContext();
        String clientId = facesContext.getExternalContext().getRequestParameterMap().get("javax.faces.source");
        if (clientId != null) {
            log.info("Saving message for client: " + clientId);
            facesContext.getExternalContext().getSessionMap().put(clientId, facesContext.getMessageList());
        }
    }

    @Override
    public synchronized void beforePhase(PhaseEvent event) {
    }

    @Override
    public PhaseId getPhaseId() {
        return PhaseId.ANY_PHASE;
    }
}
