public Image getFlippedCopy(boolean flipHorizontal, boolean flipVertical) {
    Image flipped = new Image(width, height);
    Graphics g = flipped.getGraphics();
    int x = flipHorizontal ? width : 0;
    int y = flipVertical ? height : 0;
    int w = flipHorizontal ? -width : width;
    int h = flipVertical ? -height : height;
    g.drawImage(this, x, y, w, h);
    g.destroy();
    return flipped;
}
