import java.util.ArrayList;
import java.util.List;

public List<String> getMultipleFieldValues(String header, boolean keepQuotes) {
    List<String> values = new ArrayList<>();
    String[] fields = header.split(",");
    for (String field : fields) {
        if (field.isEmpty()) {
            continue;
        }
        if (!keepQuotes) {
            field = field.replaceAll("^\"", "").replaceAll("\"$", "").trim();
        } else if (field.charAt(0) == '"' && field.charAt(field.length() - 1) == '"') {
            field = field.substring(1, field.length() - 1);
        }
        String[] splitValues = field.split("\"?,");
        for (String splitValue : splitValues) {
            splitValue = splitValue.trim();
            if (!keepQuotes) {
                splitValue = splitValue.replaceAll("^\"", "").replaceAll("\"$", "");
            } else if (splitValue.charAt(0) == '"' && splitValue.charAt(splitValue.length() - 1) == '"') {
                splitValue = splitValue.substring(1, splitValue.length() - 1);
            }
            values.add(splitValue);
        }
    }
    return values;
}
