public static String asTitleCase(String text) {

        text = text.replace('_', ' ');

        text = text.replaceAll("\\s+", " ");

        text = text.replaceAll(
                String.format("%s|%s|%s",
                        "(?<=[A-Z])(?=[A-Z][a-z])",
                        "(?<=[^A-Z])(?=[A-Z])",
                        "(?<=[A-Za-z])(?=[^A-Za-z])"
                ),
                " "
        );
        return Character.toUpperCase(text.charAt(0)) + text.substring(1);
