public int consumeLinearWhitespace(byte[] buffer) {
    int bytesConsumed = 0;
    int pos = 0;
    boolean crlfFound = false;
    boolean wspFound = false;

    while (pos < buffer.length) {
        byte b = buffer[pos];
        if (b == ' ' || b == '\t') {
            wspFound = true;
            bytesConsumed++;
            pos++;
        } else if (!crlfFound && b == '\r') {
            if (pos < buffer.length - 1 && buffer[pos + 1] == '\n') {
                crlfFound = true;
                bytesConsumed += 2;
                pos += 2;
            } else {
                break;
            }
        } else {
            break;
        }
    }

    if (wspFound) {
        return bytesConsumed;
    } else {
        return 0;
    }
}
