        while (true) {
            input = in.readLine();
            if (input == null || input.length() == -1)
                break;
            input = input.trim();
            if (input.length() == 0)
                break;
            System.out.println("Argument" + i++ + "='" + input + "'");
            args.add(input);
        }
        runPipeline(pipelineScript, args);
