public Map<String, Type> findRoboconfTypes(File appDirectory) {
    Map<String, Type> typesMap = new HashMap<>();
    try {
        if (appDirectory != null && appDirectory.exists() && appDirectory.isDirectory()) {
            File[] typeFiles = appDirectory.listFiles(new FilenameFilter() {
                @Override
                public boolean accept(File dir, String name) {
                    return name.endsWith(".properties");
                }
            });
            for (File file : typeFiles) {
                Properties properties = new Properties();
                try {
                    properties.load(new FileInputStream(file));
                    if (properties.containsKey("instance.of")) {
                        String typeName = properties.getProperty("instance.of");
                        if (!typesMap.containsKey(typeName)) {
                            typesMap.put(typeName, new Type(typeName));
                        }
                    }
                } catch (IOException e) {
                    // handle the exception
                }
            }
        }
    } catch (SecurityException e) {
        // handle the exception
    }
    return typesMap;
}
