public String generateHtmlOutput(TableElement tableElement) {
    StringBuilder htmlOutput = new StringBuilder();
    htmlOutput.append("<table>");

    // Generate table header
    htmlOutput.append("<thead><tr>");
    for (String header : tableElement.getHeaders()) {
        htmlOutput.append("<th>").append(header).append("</th>");
    }
    htmlOutput.append("</tr></thead>");

    // Generate table body rows
    htmlOutput.append("<tbody>");
    for (List<String> row : tableElement.getRows()) {
        htmlOutput.append("<tr>");
        for (String value : row) {
            htmlOutput.append("<td>").append(value).append("</td>");
        }
        htmlOutput.append("</tr>");
    }
    htmlOutput.append("</tbody>");

    htmlOutput.append("</table>");
    return htmlOutput.toString();
}
