import org.apache.spark.sql.Row;
import org.apache.spark.sql.functions;
import org.apache.spark.sql.types.StructType;
import org.apache.spark.sql.Dataset;

import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;
import scala.collection.JavaConverters;

public List<List<Object>> getUniqueValues(List<String> columnNames, StructType schema, Dataset<Row> data) {
    List<List<Object>> uniqueValues = new ArrayList<>();
    for (String colName : columnNames) {
        if (schema.apply(colName).dataType().typeName().equals("array")) {
            List<Object> uniqueSeq = getUniqueSequence(colName, schema, data.javaRDD());
            uniqueValues.add(uniqueSeq);
        } else {
            Dataset<Row> colData = data.select(colName).distinct();
            List<Object> uniqueList = colData.collectAsList().stream().map(row -> row.get(0)).collect(Collectors.toList());
            uniqueValues.add(uniqueList);
        }
    }
    return uniqueValues;
}

private List<Object> getUniqueSequence(String colName, StructType schema, JavaRDD<Row> data) {
    return data
            .flatMap(row -> {
                Object obj = row.getAs(colName);
                List<Object> list = new ArrayList<>();
                if (obj != null) {
                    list.addAll(JavaConverters.seqAsJavaListConverter((scala.collection.Seq<Object>) obj).asJava());
                }
                return list.iterator();
            })
            .distinct()
            .collect();
}
