public static Map<String, Object> associateValueInMap(Map<String, Object> map, String pathString, Object value) {
   String[] nodes = pathString.split("\\."); // Split path in nodes
   Map<String, Object> currentNode = map;

   // Walk through existing nodes in the map
   for (int i = 0; i < nodes.length - 1; i++) {
       Object node = currentNode.get(nodes[i]);
       if (node instanceof Map) {
           currentNode = (Map<String, Object>) node;
       } else {
           // Create new node with the same class as the original map
           Map<String, Object> newNode;
           try {
               newNode = map.getClass().newInstance();
           } catch (InstantiationException | IllegalAccessException e) {
               // Handle exception appropriately
               throw new RuntimeException(e);
           }
           currentNode.put(nodes[i], newNode);
           currentNode = newNode;
       }
   }
   // Associate new value to the last node
   currentNode.put(nodes[nodes.length - 1], value);

   return map;
}
