public static List<String> readHTMLAttributes(String htmlAttributes) {
    List<String> result = new ArrayList<>();
    StringBuilder currentAttribute = new StringBuilder();
    boolean inSingleQuote = false;
    boolean inDoubleQuote = false;
    for (int i = 0; i < htmlAttributes.length(); i++) {
        char c = htmlAttributes.charAt(i);
        if (c == '<') {
            break;
        } else if (c == '>') {
            result.add(currentAttribute.toString());
            break;
        } else if (c == ' ') {
            if (currentAttribute.length() > 0) {
                result.add(currentAttribute.toString());
                currentAttribute.setLength(0);
            }
        } else if (c == '=') {
            currentAttribute.append(c);
        } else if (c == '\'') {
            currentAttribute.append(c);
            if (!inDoubleQuote) {
                inSingleQuote = !inSingleQuote;
            }
        } else if (c == '\"') {
            currentAttribute.append(c);
            if (!inSingleQuote) {
                inDoubleQuote = !inDoubleQuote;
            }
        } else {
            currentAttribute.append(c);
        }
    }
    return result;
}
