public Object[] extractAndMergeColumns(int[][] featuresToMerge, int[][] featureMasksToMerge, int inOutIdx) {
    int numRows = featuresToMerge.length;
    int[] mergedCol = new int[numRows];
    int[] mergedMask = null;
    if(featureMasksToMerge != null) {
        mergedMask = new int[numRows];
    }
    for(int i = 0; i < numRows; i++) {
        mergedCol[i] = featuresToMerge[i][inOutIdx];
        if(featureMasksToMerge != null) {
            mergedMask[i] = featureMasksToMerge[i][inOutIdx];
        }
    }
    return new Object[]{mergedCol, mergedMask};
}
