public static boolean isZipFile(InputStream inputStream) throws IOException {
    try (PushbackInputStream pbis = new PushbackInputStream(new BufferedInputStream(inputStream), 4)) {
        byte[] signature = new byte[4];
        if (pbis.read(signature) != 4) {
            throw new EOFException();
        }
        pbis.unread(signature);
        int header = ((signature[0] & 0xFF) | (signature[1] & 0xFF) << 8 | (signature[2] & 0xFF) << 16 | (signature[3] & 0xFF) << 24);
        return header == 0x504B0304;
    }
}
