public Object removeEntryInRange(Object key, Object min, Object max) {
    Map.Entry entry = ((NavigableMap) map).ceilingEntry(min);
    Object oldValue = null;
    while (entry != null && compare(entry.getKey(), max) < 0) {
        if (key.equals(entry.getKey())) {
            oldValue = entry.getValue();
            entryIterator.remove();
            break;
        }
        entry = entryIterator.hasNext() ? entryIterator.next() : null;
    }
    return oldValue;
}
