import com.couchbase.client.java.document.json.JsonObject;

public enum WriteOperationType {
  INSERT,
  UPSERT,
  REPLACE,
  REMOVE
}

public WriteOperationType evaluateOperationType(JsonObject record, String key) {
  String operationType = record.getString("sdc.operation.type", "");
  switch (operationType) {
    case "insert":
      return WriteOperationType.INSERT;
    case "upsert":
      return WriteOperationType.UPSERT;
    case "replace":
      return WriteOperationType.REPLACE;
    case "remove":
      return WriteOperationType.REMOVE;
    default:
      // Log the default write operation
      System.out.println("Default Write Operation for key " + key + ": " + WriteOperationType.UPSERT);
      return WriteOperationType.UPSERT;
  }
}
