public static void bubbleElement(int[] arr, int pos) {
    if (arr == null || pos < 0 || pos >= arr.length) {
        return;
    }

    for (int i = 0; i < arr.length - 1; i++) {
        for (int j = 0; j < arr.length - i - 1; j++) {
            if (j == pos) {
                if (arr[j] > arr[j+1]) {
                    int temp = arr[j];
                    arr[j] = arr[j+1];
                    arr[j+1] = temp;
                }
            }
        }
    }
}
