public RVFDataset convertToRVFDatasetTFIDF(Dataset dataset) {
    RVFDataset rvfDataset = new RVFDataset();
    // L1 normalization
    for (int i = 0; i < dataset.size(); i++) {
        SparseVector currentFeatures = dataset.get(i).asVector();
        double norm = currentFeatures.L1Norm();
        for (int j = 0; j < currentFeatures.size(); j++) {
            double tfidf = (currentFeatures.value(j) / norm) *
                    Math.log(dataset.size() / dataset.getFeatureDictionary().getFrequency(j));
            rvfDataset.addSample(dataset.get(i).getLabel(), new Feature(Integer.toString(j), tfidf));
        }
    }
    return rvfDataset;
}
