public void forwardCommands(ExecutionControl ec, InputStream in, OutputStream out) {
    BufferedReader reader = new BufferedReader(new InputStreamReader(in));
    PrintWriter writer = new PrintWriter(out, true);
    String command;
    try {
        while ((command = reader.readLine()) != null) {
            String response = ec.executeCommand(command);
            writer.println(response);
        }
    } catch (IOException e) {
        e.printStackTrace();
    }
}
