import georegression.metric.alg.DistancePointTriangle3D_F64;
import org.ejml.data.FMatrixRMaj;
import org.ejml.dense.row.CommonOps_DDRM;

public class DistancePointTriangle3D {

    public static FMatrixRMaj distanceFromPointToTriangle(FMatrixRMaj triangle, FMatrixRMaj point) {
        FMatrixRMaj closestPoint = new FMatrixRMaj(3, 1);
        double distance = DistancePointTriangle3D_F64.distance(triangle.getData(), point.getData(), closestPoint.getData());

        FMatrixRMaj vectorToPoint = new FMatrixRMaj(3, 1);
        CommonOps_DDRM.subtract(point, closestPoint, vectorToPoint);

        FMatrixRMaj vectorToTriangle = new FMatrixRMaj(3, 1);
        CommonOps_DDRM.subtract(triangle.extractMatrix(0, 3, 0, 1), point, vectorToTriangle);

        FMatrixRMaj crossProduct = new FMatrixRMaj(3, 1);
        CommonOps_DDRM.cross(vectorToPoint, vectorToTriangle, crossProduct);

        if (CommonOps_DDRM.dot(triangle.extractMatrix(0, 3, 2, 2), crossProduct) > 0) {
            distance = -distance;
        }

        return closestPoint;
    }
}
