public String mapPosTagToNAF(String postag) {
    switch (postag) {
        case "NOUN":
            return "n";
        case "VERB":
            return "v";
        case "ADJ":
            return "a";
        case "ADV":
            return "r";
        case "PRON":
            return "pron";
        case "ADP":
            return "prep";
        case "CONJ":
            return "conj";
        case "DET":
            return "det";
        case "NUM":
            return "num";
        case "PRT":
            return "part";
        case "X":
            return "x";
        case ".":
            return "punct";
        default:
            return "other";
    }
}
