public Set<Synset> getSiblings(Synset synset) {
    Set<Synset> siblings = new HashSet<>();
    Synset hypernym = synset.getHypernym(); //assuming there's a method getHypernym() to retrieve the hypernym of a synset
    if (hypernym != null) {
        for (Synset s : hypernym.getHyponyms()) { //assuming there's a method getHyponyms() to retrieve the hyponyms of a synset
            if (!s.equals(synset)) {
                siblings.addAll(s.getHypernym().getHyponyms());
            }
        }
    }
    return siblings;
}
