import javax.enterprise.context.ContextNotActiveException;
import javax.enterprise.context.spi.BaseBean;
import javax.enterprise.context.spi.Context;
import javax.enterprise.inject.spi.BeanManager;

public class MyBeanUtil {

    public static <T> T getBeanInstance(BaseBean<T> bean, BeanManager beanManager) 
            throws ContextNotActiveException {
        Context context = beanManager.getContext(bean.getScope());
        if (!context.isActive()) {
            throw new ContextNotActiveException("Context is not active");
        }
        return context.get(bean, beanManager.createCreationalContext(bean));
    }

}
