import java.io.IOException;
import java.io.InputStream;
import java.util.Properties;

public class PropertyFileReader {

    private static final String PROPERTY_FILE_NAME = "databasePooling.properties";

    public int getIntValue(String aPropName, int aDefaultValue) {

        Properties prop = new Properties();
        try (InputStream input = getClass().getClassLoader().getResourceAsStream(PROPERTY_FILE_NAME)) {
            prop.load(input);
        } catch (IOException ex) {
            ex.printStackTrace();
        }

        return Integer.parseInt(prop.getProperty(aPropName, String.valueOf(aDefaultValue)).trim());
