public double gaussianVariogram(double c0, double a, double sill, double rx, double ry, double rz) {
    double distance = Math.sqrt(Math.pow(rx, 2) + Math.pow(ry, 2) + Math.pow(rz, 2));
    if(distance > a) {
        return sill;
    } else {
        return c0 + (sill - c0) * (1 - Math.exp(-(Math.pow(distance, 2) / (2 * Math.pow(a, 2)))));
    }
}
