public static String encodeJavaScript(String code) throws IOException {
    String encodedCode = "";
    ScriptEngineManager manager = new ScriptEngineManager();
    ScriptEngine engine = manager.getEngineByName("javascript");
    try {
        encodedCode = engine.eval("escape('" + code + "')").toString();
    } catch (ScriptException e) {
        throw new IOException("Error encoding JavaScript code", e);
    }
    return encodedCode;
}
