public Set<ElementAction> getElementActions(String ns) {
  Set<ElementAction> elementActions = new HashSet<>();
  Mode currentMode = getCurrentMode();
  List<Mode> baseModes = currentMode.getBaseModes();

  // Check if current mode has actions for the namespace
  if (currentMode.getElementActions().containsKey(ns)) {
    elementActions.addAll(currentMode.getElementActions().get(ns));
  } else {
    // Check in base modes
    for (Mode baseMode : baseModes) {
      if (baseMode.getElementActions().containsKey(ns)) {
        Set<ElementAction> baseActions = baseMode.getElementActions().get(ns);
        Set<ElementAction> actionsCopy = new HashSet<>(baseActions);
        changeCurrentMode(actionsCopy);
        elementActions.addAll(actionsCopy);
        break;
      }
    }
  }

  return elementActions;
}

