public Phrase getSpecialPhrase(String leading, String string, String font) {
    StringBuilder sb = new StringBuilder();

    // loop through the characters of the string
    for (int i = 0; i < string.length(); i++) {
        char ch = string.charAt(i);

        // if the character is a letter, convert it to the corresponding symbol
        if (Character.isLetter(ch)) {
            switch (ch) {
                case 'a':
                    sb.append("@");
                    break;
                case 'e':
                    sb.append("3");
                    break;
                case 'i':
                    sb.append("!");
                    break;
                case 'o':
                    sb.append("0");
                    break;
                case 's':
                    sb.append("$");
                    break;
                default:
                    sb.append(ch);
                    break;
            }
        } else {
            sb.append(ch);
        }
    }

    // create and return the special phrase
    return new Phrase(leading + sb.toString(), font);
}
