import java.security.KeyPair;
import java.security.interfaces.ECPrivateKey;
import java.security.interfaces.ECPublicKey;
import java.security.spec.ECPoint;
import java.security.spec.ECPrivateKeySpec;
import java.security.spec.ECPublicKeySpec;
import java.util.Base64;
import org.json.JSONObject;

public JSONObject ecKeyPairToJsonWebKey(KeyPair keyPair, String provider) throws Exception {
    ECPrivateKey ecPrivateKey = (ECPrivateKey) keyPair.getPrivate();
    ECPublicKey ecPublicKey = (ECPublicKey) keyPair.getPublic();
    ECPoint ecPoint = ecPublicKey.getW();

    String crv = ecPublicKey.getAlgorithm().substring(9);
    String x = Base64.getUrlEncoder().withoutPadding().encodeToString(ecPoint.getAffineX().toByteArray());
    String y = Base64.getUrlEncoder().withoutPadding().encodeToString(ecPoint.getAffineY().toByteArray());
    String d = Base64.getUrlEncoder().withoutPadding().encodeToString(ecPrivateKey.getS().toByteArray());

    JSONObject jwk = new JSONObject();
    jwk.put("kty", "EC");
    jwk.put("crv", crv);
    jwk.put("x", x);
    jwk.put("y", y);
    jwk.put("d", d);

    return jwk;
}
