public static String encode(String s) {
        if (s == null) {
            return null;
        }
        StringBuilder builder = null;
        int begin = 0;
        for (int i = 0, length = s.length(); i < length; i++) {
            char ch = s.charAt(i);


            switch (ch) {

                case 'a':
                case 'b':
                case 'c':
                case 'd':
                case 'e':
                case 'f':
                case 'g':
                case 'h':
                case 'i':
                case 'j':
