import org.apache.maven.shared.invoker.DefaultInvocationRequest;
import org.apache.maven.shared.invoker.DefaultInvoker;
import org.apache.maven.shared.invoker.InvocationRequest;
import org.apache.maven.shared.invoker.InvocationResult;
import org.apache.maven.shared.invoker.MavenInvocationException;

import java.io.File;
import java.util.Arrays;
import java.util.Collections;

public class EarInstaller {

    public static void installEarProjectArtifact(File pomFile, File appXmlFile) throws MavenInvocationException {
        InvocationRequest request = new DefaultInvocationRequest();
        request.setPomFile(pomFile);
        request.setGoals(Collections.singletonList("install"));

        request.setProperties(Collections.singletonMap("appxml", appXmlFile.getAbsolutePath()));

        DefaultInvoker invoker = new DefaultInvoker();

        InvocationResult result = invoker.execute(request);

        if (result.getExitCode() != 0) {
            throw new MavenInvocationException("Failed to install artifact.");
        }
