public Node getChildNode(String name) {
   Node childNode = null;
   NodeList childNodes = parentNode.getChildNodes();
   for(int i = 0; i < childNodes.getLength(); i++) {
      Node currentChildNode = childNodes.item(i);
      if(currentChildNode.getNodeType() == Node.ELEMENT_NODE &&
         currentChildNode.getNodeName().equals(name)) {
         childNode = currentChildNode;
         break;
      }
   }
   if(childNode == null) {
      childNode = parentNode.getOwnerDocument().createElement(name);
      parentNode.appendChild(childNode);
   }
   return childNode;
}
