import java.io.IOException;

public class Converter {
    public static String osToUnixPath(String filename) throws IOException {
        if (System.getProperty("os.name").startsWith("Windows")) {
            try {
                Process process = Runtime.getRuntime().exec(
                        new String[]{"cmd.exe", "/c", "echo " + filename});
                filename = new String(process.getInputStream().readAllBytes())
                        .trim();
            } catch (IOException e) {
                throw new IOException("Error converting filename to unix format", e);
            }    
        }
        return filename.replace("\\", "/");
    }
}
