public static String parseRangeHeader(String range) throws IllegalArgumentException {
    if (range == null || !range.startsWith("bytes=")) {
        throw new IllegalArgumentException("Invalid Range header value");
    }
    range = range.substring(6);
    int dashIndex = range.indexOf('-');
    if (dashIndex == -1 || dashIndex == 0 || dashIndex == range.length() - 1) {
        throw new IllegalArgumentException("Invalid Range header value");
    }
    String start = range.substring(0, dashIndex);
    String end = range.substring(dashIndex + 1);
    try {
        Integer.parseInt(start);
        Integer.parseInt(end);
    } catch (NumberFormatException e) {
        throw new IllegalArgumentException("Invalid Range header value", e);
    }
    return range;
}
