public static double[] createSymmetricBoxKernel(int r) {
  int width = 2 * r + 1;
  double[] kernel = new double[width];
  int center = r;

  for (int i = 0; i <= r; i++) {
    kernel[center - i] = -i;
    kernel[center + i] = i;
  }
  double sum = 0;

  for (int i = 0; i < width; i++) {
    sum += Math.abs(kernel[i]);
  }

  for (int i = 0; i < width; i++) {
    kernel[i] /= sum;
  }

  return kernel;
}
