public void calculateDifferences(ModelDiff modelDiff) {
    List<String> oldFields = modelDiff.getOldModel().getFields();
    List<String> newFields = modelDiff.getNewModel().getFields();
    List<String> differences = new ArrayList<String>();

    for (String oldField : oldFields) {
        if (!newFields.contains(oldField)) {
            differences.add("Removed field: " + oldField);
        }
    }

    for (String newField : newFields) {
        if (!oldFields.contains(newField)) {
            differences.add("Added field: " + newField);
        }
    }

    modelDiff.setDifferences(differences);
}
