import com.fasterxml.jackson.databind.JsonNode;

public class BugFixer {

    public static JsonNode parseJsonNode(JsonNode node) {
        if (node == null) {
            return null;
        }

        JsonNode result = node;
        if (node.isObject()) {
            JsonNode queryProfile = node.get("query_profile");
            if (queryProfile != null && queryProfile.isObject()) {
                // Check for the bug
                boolean bugExists = true;
                for (JsonNode field : queryProfile) {
                    if (!field.isNumber()) {
                        bugExists = false;
                        break;
                    }
                }

                if (bugExists) {
                    // Parse number keys into an array
                    ArrayNode arrayNode = new ArrayNode(JsonNodeFactory.instance);
                    Iterator<Entry<String,JsonNode>> fields = queryProfile.fields();
                    while (fields.hasNext()) {
                        Entry<String,JsonNode> entry = fields.next();
                        String key = entry.getKey();
                        JsonNode value = entry.getValue();
                        int index = Integer.parseInt(key);
                        arrayNode.add(index, value);
                        queryProfile.remove(key);
                    }
                    queryProfile.setAll(arrayNode);
                }
            }
        }

        // Recursively parse child nodes
        if (result.isArray()) {
            ArrayNode arrayNode = (ArrayNode) result;
            for (int i = 0; i < arrayNode.size(); i++) {
                arrayNode.set(i, parseJsonNode(arrayNode.get(i)));
            }
        } else if (result.isObject()) {
            ObjectNode objectNode = (ObjectNode) result;
            Iterator<Entry<String,JsonNode>> fields = objectNode.fields();
            while (fields.hasNext()) {
                Entry<String,JsonNode> entry = fields.next();
                objectNode.set(entry.getKey(), parseJsonNode(entry.getValue()));
            }
        }

        return result;
    }
}
