      long timeToWait = rate - timeSinceLastAccess;

      if (timeToWait > 0) {
         lock.wait(timeToWait);
      }

      lastAccessTime = System.currentTimeMillis();
   }
}

public void setRate(long rate) {
   this.rate = rate;
}
