public NodeIterator searchForPageContentNodes(String[] templates, String rootPath) throws RepositoryException {
    // Obtains the session from the repository
    Session session = repository.login();
    try {
        // Builds the XPATH query using the root path and the templates
        String query = "//element(*, cq:PageContent)";
        if (rootPath != null) {
            query = rootPath + query;
        }
        if (templates != null) {
            StringBuilder templateQuery = new StringBuilder();
            templateQuery.append(" and (");
            for (int i = 0; i < templates.length; i++) {
                if (i > 0) {
                    templateQuery.append(" or ");
                }
                templateQuery.append("@cq:template='").append(templates[i]).append("'");
            }
            templateQuery.append(")");
            query += templateQuery.toString();
        }
        // Executes the query and return the nodes iterator of results
        QueryManager queryManager = session.getWorkspace().getQueryManager();
        Query xpathQuery = queryManager.createQuery(query, Query.XPATH);
        return xpathQuery.execute().getNodes();
    } finally {
        session.logout();
    }
}
