public byte[] getDepsBlock() throws IOException {
    if (mDepsBlock == null) {
        mDepsBlock = makeDepsBlock();
    }
    return mDepsBlock;
}

private synchronized byte[] makeDepsBlock() throws IOException {
    ByteArrayOutputStream bytes = new ByteArrayOutputStream();
    DataOutputStream outputStream = new DataOutputStream(bytes);

    // Write the number of libraries in the deps block.
    outputStream.writeInt(mSoSources.length);

    // Write the name and hash of each library.
    for (SoSource currentSource : mSoSources) {
        String currentName = currentSource.getName();
        byte[] currentHash = currentSource.getHash();
        outputStream.writeUTF(currentName);
        outputStream.writeInt(currentHash.length);
        outputStream.write(currentHash);
    }

    byte[] depsBlock = bytes.toByteArray();
    outputStream.close();
    return depsBlock;
}
