public static long next48BitSignedLongFromBuffer(byte[] buffer, int offset) {
    long low = (((long) buffer[offset + 5] & 0xffL) << 40) |
              (((long) buffer[offset + 4] & 0xffL) << 32) |
              (((long) buffer[offset + 3] & 0xffL) << 24) |
              (((long) buffer[offset + 2] & 0xffL) << 16) |
              (((long) buffer[offset + 1] & 0xffL) << 8) |
              ((long) buffer[offset] & 0xffL);
    if ((low & 0x800000000000L) != 0) {
        return -((low ^ 0xffffffffffffL) + 1);
    } else {
        return low;
    }
}
