public Entity deleteEntity(String entityClass, String entityId, HttpClient httpClient) throws AuthenticationException, ApiException {
     HttpDelete request = new HttpDelete("https://example.com/api/" + entityClass + "/" + entityId);

     // Set the Authorization header
     String authHeader = getAuthorizationHeader();
     request.setHeader("Authorization", authHeader);

     try {
         HttpResponse response = httpClient.execute(request);

         // Check for errors
         int statusCode = response.getStatusLine().getStatusCode();
         if (statusCode < 200 || statusCode >= 300) {
             throw new ApiException("Failed to delete/cancel entity. Status code: " + statusCode);
         }

         // Parse the response and return the entity
         String json = EntityUtils.toString(response.getEntity(), "UTF-8");
         return new Entity(json);
     } catch (IOException e) {
         throw new ApiException("Failed to delete/cancel entity due to IO error", e);
     }
 }
