public JsMessage createJsMessage(JsMsgObject jmo) {
    String contentType = jmo.getContentType();

    if(contentType.equals("text/plain")) {
        return new TextJsMessage(contentType);
    } else if(contentType.equals("application/json")) {
        return new JsonJsMessage(contentType);
    } else if(contentType.equals("image/png")) {
        return new PngJsMessage(contentType);
    }

    return null; // or throw an appropriate exception
}
