public void quickFixForSARLKeyword(Issue issue, IQuickFixAcceptor acceptor) {
   // Check if the given issue is related to a no viable alternative error.
    if (issue.getCode() == ISSUES_NO_VIABLE_ALTERNATIVE_ERROR) {
        // Do the required fix to replace the input that is a SARL keyword.
        String originalString = issue.getOriginalString();
        String fixedString = originalString.replace(SARL_KEYWORD, SARL_REPLACEMENT);
        // Create a new correction proposal for the fixed input.
        TextEdit correction = new ReplaceEdit(issue.getOffset(), issue.getLength(), fixedString);
        acceptor.accept(new CorrectionProposal("Replace with alternative text", correction, 1, null, issue));
    }
}
