public ValueConverter registerConverter(ValueConverter converter) {
    for (int i = 0; i < converters.size(); i++) {
        ValueConverter existingConverter = converters.get(i);
        if (existingConverter.getSourceType().equals(converter.getSourceType())
                && existingConverter.getTargetType().equals(converter.getTargetType())) {
            return converters.set(i, converter);
        }
    }
    converters.add(converter);
    return null;
}
