public void addHiddenField(String tag, String label) {
    // Create a new hidden input element
    Element field = new Element("input");
    field.attr("type", "hidden");
    field.attr("name", tag);
    field.attr("value", label);

    // Add a new row to the table and insert the field and label as cells
    Element row = new Element("tr");
    Element labelCell = new Element("td");
    Element fieldCell = new Element("td");
    labelCell.text(label);
    fieldCell.appendChild(field);
    row.appendChild(labelCell);
    row.appendChild(fieldCell);
    table.appendChild(row);
}
