@Override
public File getLibDir(File baseDir, AOL aol, String type) {
    String architecture = aol.getArchitecture();
    String os = aol.getOS();
    String linkerName = NarUtil.getDefaults().getProperty("linker." + os + '.' + architecture);
    if (linkerName == null) {
        throw new RuntimeException("Unknown linker for architecture: " + architecture + " and OS: " + os);
    }
    String libDir = NarUtil.getDefaults().getProperty(
            "libDirectory." + linkerName + '.' + os + '.' + architecture + (type == null ? "" : '.' + type));
    if (libDir == null) {
        throw new RuntimeException(
                "Unkown lib directory for linker: " + linkerName + ", architecture: " + architecture + " and OS: " + os
                        + " and type: " + type);
    }
    return new File(baseDir, libDir);
}
