public static String encodeNotInteger(Number number) {
    if (number == null) {
        return null;
    }
    if (number instanceof Double) {
        long bits = Double.doubleToLongBits((Double) number);
        return Long.toString(bits, Character.MAX_RADIX);
    } else if (number instanceof Float) {
        int bits = Float.floatToIntBits((Float) number);
        return Integer.toString(bits, Character.MAX_RADIX);
    } else {
        throw new IllegalArgumentException("Unsupported number type");
    }
}
