public boolean matchVersionId(String vid) {
    boolean usePrefixMatch = true; // or false, depending on the flag
    boolean useGreaterThan = true; // or false, depending on the flag

    if (usePrefixMatch) {
        if (vid.startsWith(this.versionID)) {
            return true;
        }
    }

    if (useGreaterThan) {
        if (vid.equals(this.versionID)) {
            return true;
        }

        if (vid.contains(">") && this.versionID.contains(".")) { // assuming versionID is in format x.y.z
            String[] thisVersion = this.versionID.split("\\.");
            String[] vidVersion = vid.split("\\.");
            for (int i = 0; i < vidVersion.length; i++) {
                if (Integer.parseInt(vidVersion[i]) > Integer.parseInt(thisVersion[i])) {
                    return true;
                }
                if (Integer.parseInt(vidVersion[i]) < Integer.parseInt(thisVersion[i])) {
                    break;
                }
            }
        }
    }

    return false;
}
