public double hypervolume(double[][] objectiveSpace, int numObjectives, double[] a, double[] b) {
    double volume = 0.0;
    int numPoints = objectiveSpace.length;

    // Sort the objective space by the first objective
    Arrays.sort(objectiveSpace, Comparator.comparingDouble(point -> point[0]));

    // Calculate the volume dominated by individual a
    double[] vA = new double[numObjectives];
    for (int i = 0; i < numPoints; i++) {
        if (dominates(a, objectiveSpace[i], numObjectives)) {
            double h = a[0] - objectiveSpace[i][0];
            for (int j = 1; j < numObjectives; j++) {
                h = Math.min(h, a[j] - objectiveSpace[i][j]);
            }
            updateV(vA, objectiveSpace[i], numObjectives);
            volume += h * vA[numObjectives - 1];
        }
    }

    // Calculate the volume dominated by individual b
    double[] vB = new double[numObjectives];
    for (int i = 0; i < numPoints; i++) {
        if (dominates(b, objectiveSpace[i], numObjectives)) {
            double h = b[0] - objectiveSpace[i][0];
            for (int j = 1; j < numObjectives; j++) {
                h = Math.min(h, b[j] - objectiveSpace[i][j]);
            }
            updateV(vB, objectiveSpace[i], numObjectives);
            volume -= h * vB[numObjectives - 1];
        }
    }

    return volume;
}

private boolean dominates(double[] a, double[] b, int numObjectives) {
    // Returns true if individual a dominates individual b in the objective space
    boolean dominates = false;
    for (int i = 0; i < numObjectives; i++) {
        if (a[i] > b[i]) {
            return false;
        } else if (a[i] < b[i]) {
            dominates = true;
        }
    }
    return dominates;
}

private void updateV(double[] v, double[] point, int numObjectives) {
    // Updates the volume v dominated by a point in the objective space
    if (Arrays.stream(v).allMatch(x -> x == 0.0)) {
        for (int i = 0; i < numObjectives; i++) {
            v[i] = point[i];
        }
    } else {
        for (int i = 0; i < numObjectives; i++) {
            v[i] = Math.min(v[i], point[i]);
        }
    }
}
