/**
 * @see de.chandre.admintool.quartz.AdminToolQuartzService#isPaused(org.quartz.Trigger)
 */
public boolean isPaused(Trigger trigger) {
    try {
        List<String> triggerGroupNames = scheduler.getTriggerGroupNames();
        for (String groupName : triggerGroupNames) {
            Set<TriggerKey> groupTriggers = scheduler.getTriggerKeys(GroupMatcher.triggerGroupEquals(groupName));
            for (TriggerKey triggerKey : groupTriggers) {
                if (triggerKey.getName().equals(trigger.getKey().getName()) && triggerKey.getGroup().equals(trigger.getKey().getGroup())) {
                    return scheduler.getTriggerState(triggerKey) == TriggerState.PAUSED;
                }
            }
        }
    } catch (SchedulerException e) {
        // Handle exception
    }
