public static void addSystemClasspath() {
    String classpath = System.getProperty("java.class.path");
    String[] classpathEntries = classpath.split(System.getProperty("path.separator"));
    for (String entry : classpathEntries) {
        try {
            URL url = new File(entry).toURI().toURL();
            if (!Arrays.asList(((URLClassLoader)ClassLoader.getSystemClassLoader()).getURLs()).contains(url)) {
                ((URLClassLoader)ClassLoader.getSystemClassLoader()).addURL(url);
            }
        } catch (MalformedURLException e) {
            e.printStackTrace();
        }
    }
}
