public static final Pointer createXmmwordPointer(byte[] bytes) {
    if (bytes.length != 16) {
        throw new IllegalArgumentException("byte array must be exactly 16 bytes long");
    }

    Pointer pointer = new Pointer();
    pointer.setSize(16);
    pointer.setBytes(bytes);
    pointer.setType(Pointer.TYPE_XMMWORD);

    return pointer;
}
