public Object updateBean(Object object, Map<String, Object> source) {
    try {
        // create a clone of the input bean object
        Object clonedObject = object.getClass().newInstance();

        // iterate through the keys in the source map
        for (String key : source.keySet()) {
            // get the appropriate method for the key and invoke it on the cloned object
            String methodName = "set" + key.substring(0, 1).toUpperCase() + key.substring(1);
            Method method = clonedObject.getClass().getMethod(methodName, source.get(key).getClass());
            method.invoke(clonedObject, source.get(key));
        }

        return clonedObject;
    } catch (Exception e) {
        e.printStackTrace();
        return null;
    }
}
