import java.io.IOException;
import java.io.OutputStream;

import org.apache.commons.exec.CommandLine;
import org.apache.commons.exec.DefaultExecutor;
import org.apache.commons.exec.ExecuteException;
import org.apache.commons.exec.ExecuteResultHandler;
import org.apache.commons.exec.PumpStreamHandler;

public class PBSCommand {

    public ExecuteResultHandler executeCommand(String cmdLine, String[] environment, OutputStream out, OutputStream err) 
            throws ExecuteException, IOException {
        CommandLine cmd = CommandLine.parse(cmdLine);

        DefaultExecutor executor = new DefaultExecutor();

        if (environment != null && environment.length > 0) {
            executor.setEnvironment(environment);
        }

        if (out != null || err != null) {
            executor.setStreamHandler(new PumpStreamHandler(out, err));
        }

        ExecuteResultHandler resultHandler = new PBSCommandResultHandler();

        executor.execute(cmd, resultHandler);

        return resultHandler;
    }

    private class PBSCommandResultHandler implements ExecuteResultHandler {

        private ExecuteException error;

        public void onProcessComplete(int arg0) {
            // NO-OP
        }

        public void onProcessFailed(ExecuteException e) {
            error = e;
        }

        public ExecuteException getError() {
            return error;
        }

    }
}
