public static void printMatrices(int[][] m1, int[][] m2, int[][] m3, String op, PrintStream out) {
    out.println("Matrix 1:");
    printMatrix(m1, out);
    out.println("Matrix 2:");
    printMatrix(m2, out);
    out.println("Matrix 3:");
    printMatrix(m3, out);
    out.println("Operator: " + op);
    out.println("Result:");
    if (op.equals("+")) {
        printMatrix(addMatrices(m1, m2), out);
    } else if (op.equals("-")) {
        printMatrix(subtractMatrices(m1, m2), out);
    } else if (op.equals("*")) {
        printMatrix(multiplyMatrices(m1, m2), out);
    } else {
        out.println("Invalid operator provided.");
    }
}

private static void printMatrix(int[][] m, PrintStream out) {
    for (int[] row : m) {
        for (int value : row) {
            out.print(value + " ");
        }
        out.println();
    }
}

private static int[][] addMatrices(int[][] m1, int[][] m2) {
    int[][] result = new int[m1.length][m1[0].length];
    for (int i = 0; i < m1.length; i++) {
        for (int j = 0; j < m1[0].length; j++) {
            result[i][j] = m1[i][j] + m2[i][j];
        }
    }
    return result;
}

private static int[][] subtractMatrices(int[][] m1, int[][] m2) {
    int[][] result = new int[m1.length][m1[0].length];
    for (int i = 0; i < m1.length; i++) {
        for (int j = 0; j < m1[0].length; j++) {
            result[i][j] = m1[i][j] - m2[i][j];
        }
    }
    return result;
}

private static int[][] multiplyMatrices(int[][] m1, int[][] m2) {
    int[][] result = new int[m1.length][m2[0].length];
    for (int i = 0; i < m1.length; i++) {
        for (int j = 0; j < m2[0].length; j++) {
            for (int k = 0; k < m1[0].length; k++) {
                result[i][j] += m1[i][k] * m2[k][j];
            }
        }
    }
    return result;
}
