public Matrix4f getTransformMatrix(Item item, TransformType transformType) {
    return item.getCapability(CapabilityItemHandler.ITEM_HANDLER_CAPABILITY)
        .map(handler -> handler.getStackInSlot(0))
        .map(stack -> {
            if (transformType == TransformType.GUI) {
                return item.getCapability(CapabilityItemHandler.ITEM_HANDLER_CAPABILITY)
                    .map(handler -> handler.getStackInSlot(0))
                    .map(stack -> {
                        if (item instanceof BlockItem) {
                            Block block = ((BlockItem)item).getBlock();
                            return block.getRenderTransformMatrix(block.getDefaultState(), TransformType.GUI);
                        } else {
                            return Minecraft.getInstance().getItemRenderer().getItemModelMesher().getItemModel(stack).getTransforms().getGui();
                        }
                    }).orElse(new Matrix4f());
            } else {
                return Minecraft.getInstance().getItemRenderer().getModel(stack, null, null, 0).getTransform().getTransformationMatrix();
            }
        }).orElse(new Matrix4f());
}
