public static String escapeString(String inputString, int level, String type) {
    if(inputString == null || inputString.trim().isEmpty()){
        return "";
    }
    if(type == null || type.trim().isEmpty()){
        return inputString;
    }
    if(level < 0){
        level = 0;
    }
    switch (type.toUpperCase()){
        case "HTML" :
            switch (level){
                case 1:
                    return inputString.replaceAll("&", "&amp;")
                              .replaceAll("<", "&lt;")
                              .replaceAll(">", "&gt;")
                              .replaceAll("'", "&apos;")
                              .replaceAll("\"", "&quot;");
                case 2:
                    return inputString.replaceAll("&(?!amp;)", "&amp;")
                              .replaceAll("<(?!br\\s*\\/?>|p\\s*\\/?>)", "&lt;")
                              .replaceAll(">(?!(<br\\s*\\/?>|<\\/p>))", "&gt;")
                              .replaceAll("'", "&#x27;")
                              .replaceAll("\"", "&#x22;");
                default:
                    return inputString;
            }
        case "XML" :
            switch (level){
                case 1:
                    return inputString.replaceAll("&", "&amp;")
                              .replaceAll("<", "&lt;")
                              .replaceAll(">", "&gt;")
                              .replaceAll("'", "&apos;")
                              .replaceAll("\"", "&quot;");
                case 2:
                    return inputString.replaceAll("&(?!amp;)", "&amp;")
                              .replaceAll("<(?!br\\s*\\/?>|p\\s*\\/?>)", "&lt;")
                              .replaceAll(">(?!(<br\\s*\\/?>|<\\/p>))", "&gt;")
                              .replaceAll("'", "&#x27;")
                              .replaceAll("\"", "&#x22;");
                default:
                    return inputString;
            }
        default:
            return inputString;
    }
}
