public void releasePermitsWithResult(int permits, Object result, long startNanos) {
    // Release the specified number of permits
    semaphore.release(permits);

    // Calculate the latency
    long endNanos = System.nanoTime();
    long latency = endNanos - startNanos;

    // Update the result count object and latency
    resultCount.increment(result);
    latencyRecorder.record(latency);
}
