public Object waitForResult(Object lock, long timeout, boolean isInterruptible) {
    synchronized(lock) {
        try {
            if(isInterruptible) {
                lock.wait(timeout);
            } else {
                long startTime = System.currentTimeMillis();
                while(System.currentTimeMillis() - startTime < timeout) {
                    lock.wait(timeout - (System.currentTimeMillis() - startTime));
                }
            }
        } catch (InterruptedException e) {
            if(isInterruptible) {
                return null;
            }
        }
    }
    return rawResult;
}
