public static String parseQueryParameter(char[] ch, int start, int end) throws IllegalArgumentException {
    if (start > end) {
        throw new IllegalArgumentException();
    }
    StringBuilder sb = new StringBuilder();
    for (int i = start; i <= end; i++) {
        if (ch[i] == '%' && i + 2 <= end && isHexDigit(ch[i + 1]) && isHexDigit(ch[i + 2])) {
            sb.append((char)((hexToInt(ch[i + 1]) << 4) + hexToInt(ch[i + 2])));
            i += 2;
        } else if (ch[i] == '+') {
            sb.append(' ');
        } else {
            sb.append(ch[i]);
        }
    }
    return sb.toString();
}

private static boolean isHexDigit(char ch) {
    return (ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F');
}

private static int hexToInt(char ch) {
    if (ch >= '0' && ch <= '9') {
        return ch - '0';
    } else if (ch >= 'a' && ch <= 'f') {
        return ch - 'a' + 10;
    } else {
        return ch - 'A' + 10;
    }
}
