public static boolean validateIPv4(String name) {
    try {
        if (name == null || name.isEmpty()) {
            return false;
        }
        String[] parts = name.split("\\.");
        if (parts.length != 4) {
            return false;
        }
        for (String part : parts) {
            int i = Integer.parseInt(part);
            if (i < 0 || i > 255) {
                return false;
            }
        }
        if (name.endsWith(".")) {
            return false;
        }
        return true;
    } catch (NumberFormatException ex) {
        return false;
    }
}
