public int sendBackups(Operation op) throws Exception {
    if (!(op instanceof BackupAwareOperation)) {
        return 0;
    }
    BackupAwareOperation bop = (BackupAwareOperation) op;
    try {
        bop.sendBackups();
    } catch (Exception e) {
        throw new Exception("Error sending backups", e);
    }
    return bop.getAckCount();
}
