public Map<String, Integer> getConstantMap(String constant) {
    // Declare and initialize constant Map
    Map<String, Integer> constantMap = new HashMap<>();

    // If the constant already exists in constant map, return the index
    if(constantMap.containsKey(constant)) {
        return constantMap;
    }

    // If constant doesn't exist in constant Map, create a new entry with the next index available
    int index = 0;
    for(int i: constantMap.values()) {
        if(i > index) {
            index = i;
        }
    }

    index++;
    constantMap.put(constant, index);

    return constantMap;
}
