public static double logGammaLogPDF(double x, double k, double theta) {
    double logPdf = 0.0;
    if (x <= 0.0) {
        return Double.NEGATIVE_INFINITY;
    }
    logPdf = (k - 1.0) * Math.log(x) - x / theta - k * Math.log(theta) - MathUtil.logGamma(k);
    return logPdf;
}
