public static Clob byteArrayToClob(Clob clob, byte[] value) throws SQLException {
    if (clob == null) {
        throw new IllegalArgumentException("CLOB object cannot be null");
    }
    if (value == null || value.length == 0) {
        return clob;
    }
    OutputStream outStream = clob.setAsciiStream(0);
    outStream.write(value);
    outStream.flush();
    outStream.close();
    return clob;
}
