public PlanNode attachPlanNodes(Context context, PlanNode plan, Map<String, Query> subqueriesByVariableName) {
    PlanNode firstPlan = plan;
    for(Query subQuery : subqueriesByVariableName.values()) {
        PlanNode subPlan = Planner.plan(context, subQuery);
        if(firstPlan == null) {
            firstPlan = subPlan;
            plan = firstPlan;
        } else {
            subPlan.addChild(plan);
            plan = subPlan;
        }
    }
    return firstPlan == null ? plan : firstPlan;
}
