private static Field searchClassAndSuperClassesForField(Class<?> clazz, String fieldName) throws NoSuchFieldException {
    if (clazz == null) {
        throw new NoSuchFieldException("Field '" + fieldName + "' not found");
    }
    try {
        return clazz.getDeclaredField(fieldName);
    } catch (NoSuchFieldException e) {
        return searchClassAndSuperClassesForField(clazz.getSuperclass(), fieldName);
    }
}
