public OfflineDownloadOptions getOfflineDownloadOptions(OfflineRegion offlineRegion) {
    OfflineManager offlineManager = OfflineManager.getInstance(context);
    byte[] metadata = offlineRegion.getMetadata();
    if (metadata != null) {
        try {
            JSONObject jsonObject = new JSONObject(new String(metadata, "UTF-8"));
            if (jsonObject.has("offlineDownloadOptions")) {
                String options = jsonObject.getString("offlineDownloadOptions");
                return Gson().fromJson(options, OfflineDownloadOptions.class);
            }
        } catch (Exception exception) {
            Log.e(TAG, "Error occurred while parsing JSON.", exception);
        }
    }
    return null;
}
