public static <T> int binarySearch(T[] a, T key, Comparator<? super T> cmp) {
    int low = 0;
    int high = a.length - 1;

    while (low <= high) {
        int mid = (low + high) >>> 1;
        T midVal = a[mid];
        int cmpResult = cmp.compare(midVal, key);

        if (cmpResult < 0) {
            low = mid + 1;
        } else if (cmpResult > 0) {
            high = mid - 1;
        } else {
            return mid;
        }
    }

    return -(low + 1);
}
