public VersionNumber interpretVersion(String version) {
    if (version == null || version.isEmpty()) {
        throw new IllegalArgumentException("Version cannot be null or empty.");
    }
    // find the first group
    Pattern pattern = Pattern.compile("(\\d+([.]\\d+)*)");
    Matcher matcher = pattern.matcher(version);
    if (matcher.find()) {
        String foundGroup = matcher.group();
        // split the group by "."
        String[] versionNumbers = foundGroup.split("\\.");
        int[] versionIntArray = new int[versionNumbers.length];
        // parse the version numbers from string to integer
        for (int i = 0; i < versionNumbers.length; i++) {
            versionIntArray[i] = Integer.parseInt(versionNumbers[i]);
        }
        return new VersionNumber(versionIntArray);
    } else {
        throw new IllegalArgumentException("Could not find version group in string.");
    }
}
