public static void deduplicate(int[] timeArray, int[] stopSequenceArray) {
    HashMap<Integer, Integer> map = new HashMap<Integer, Integer>();
    int[] newTimeArray = new int[timeArray.length];
    int[] newStopSequenceArray = new int[stopSequenceArray.length];
    int index = 0;

    for(int i = 0; i < timeArray.length; i++) {
        if(!map.containsKey(timeArray[i])) {
            map.put(timeArray[i], stopSequenceArray[i]);
            newTimeArray[index] = timeArray[i];
            newStopSequenceArray[index] = stopSequenceArray[i];
            index++;
        }
    }

    timeArray = Arrays.copyOf(newTimeArray, index);
    stopSequenceArray = Arrays.copyOf(newStopSequenceArray, index);
}
