public void updateFunctionStateFor(Function function, FunctionState functionState) {
    // Check if the function matches the criteria for an inlinable function
    boolean isInlinable = function.getBody().getNumStatements() <= MAX_BODY_STATEMENTS
            && function.getReturnType() != Type.VOID
            && function.getParameters().size() <= MAX_PARAMETERS;

    // Update the function state
    functionState.setInlinable(isInlinable);
    functionState.setLastUpdated(new Date());
}

// Constants defining the inlining criteria
private static final int MAX_BODY_STATEMENTS = 10;
private static final int MAX_PARAMETERS = 3;
