import java.math.BigDecimal;

public class ExponentialFunction {

   public static BigDecimal computeExponential(double x, int scale) {
       BigDecimal result = BigDecimal.ZERO;
       int sign = x >= 0 ? 1 : -1;
       x *= sign;
       BigDecimal decimalPart = BigDecimal.valueOf(x % 1);
       BigDecimal wholePart = BigDecimal.valueOf(Math.floor(x));
       if (wholePart.compareTo(BigDecimal.ZERO) == 0){
           result = BigDecimal.valueOf(Math.exp(x));
       } else {
           BigDecimal fraction = wholePart.add(BigDecimal.ONE).add(decimalPart.divide(wholePart, scale, BigDecimal.ROUND_HALF_UP)).setScale(scale, BigDecimal.ROUND_HALF_UP);
           BigDecimal term = BigDecimal.ONE;
           BigDecimal sum = BigDecimal.ONE;
           for (int i = 1; term.compareTo(BigDecimal.ZERO) != 0; i++) {
               term = term.multiply(fraction).divide(BigDecimal.valueOf(i), scale, BigDecimal.ROUND_HALF_UP);
               sum = sum.add(term);
           }
           result = sum.pow(sign*wholePart.intValue()).setScale(scale, BigDecimal.ROUND_HALF_UP);
       }
       return result;
   }
}
