public String getServiceEndpointFromInterfaceNBinding(String interfaceName, String bindingName) {
    String endpointAddress = "";
    try {
        ServiceClient sc = new ServiceClient();
        Options options = sc.getOptions();
        options.setTo(new EndpointReference(endpointAddress));
        QName serviceName = new QName(interfaceName);
        QName portName = new QName(interfaceName);
        sc.getMetadata().setServiceName(serviceName);
        sc.getMetadata().setPortName(portName);
        String[] bindings = sc.getEndpointReferences();
        for (int i = 0; i < bindings.length; i++) {
            if (bindings[i].contains(bindingName)) {
                endpointAddress = bindings[i];
                break;
            }
        }
    } catch (Exception e) {
        e.printStackTrace();
    }
    return endpointAddress;
}
