public static final int MAX_DISTANCE = Integer.MAX_VALUE;

public String bestMatch(List<String> list, String value, int threshold) {
    String bestMatch = null;
    int bestDistance = MAX_DISTANCE;

    for(String listItem : list) {
        int distance = computeLevenshteinDistance(listItem, value);
        if(distance <= threshold && distance < bestDistance) {
            bestMatch = listItem;
            bestDistance = distance;
        }
    }

    if(bestMatch == null) {
        bestMatch = "default";
        bestDistance = MAX_DISTANCE;
    }

    return bestMatch;
}

public static int computeLevenshteinDistance(CharSequence lhs, CharSequence rhs) {
    int[][] distance = new int[lhs.length() + 1][rhs.length() + 1];

    for (int i = 0; i <= lhs.length(); i++) {
        distance[i][0] = i;
    }
    for (int j = 1; j <= rhs.length(); j++) {
        distance[0][j] = j;
    }

    for (int i = 1; i <= lhs.length(); i++) {
        for (int j = 1; j <= rhs.length(); j++) {
            int cost = lhs.charAt(i - 1) == rhs.charAt(j - 1) ? 0 : 1;
            distance[i][j] = Math.min(Math.min(
                    distance[i - 1][j] + 1,
                    distance[i][j - 1] + 1),
                    distance[i - 1][j - 1] + cost);
        }
    }

    return distance[lhs.length()][rhs.length()];
}
