public static TypeInfo createTypeInfo(Object obj) {
    TypeInfoFactory factory = TypeInfoFactory.getInstance();
    Class<?> clazz = obj.getClass();
    while (clazz != null) {
        TypeInfo typeInfo = factory.getTypeInfo(clazz);
        if (typeInfo != null) {
            return typeInfo;
        }
        clazz = clazz.getSuperclass();
    }
    return null;
}
