class Main
{
    public static void main (String[] args) throws java.lang.Exception
    {
        ComparablePath<String> path = createComparablePath("name", String.class);

        System.out.println("Created ComparablePath with property: " + path.getProperty() +
                            ", and type: " + path.getType().getSimpleName());
    }

    public static <A extends Comparable<? super A>> ComparablePath<A> createComparablePath(String property, Class<A> type) {
        return new ComparablePath<>(property, type);
    }
}

class ComparablePath<A extends Comparable<? super A>> {
    private String property;
    private Class<A> type;

    public ComparablePath(String property, Class<A> type) {
        this.property = property;
        this.type = type;
    }

    public String getProperty() {
        return property;
    }

    public Class<A> getType() {
        return type;
    }
}
