public Resource createSyntheticResource(ResourceResolver resourceResolver, String path, String resourceType) {
    Resource resource = resourceResolver.getResource(path);
    if (resource != null) {
        return resource;
    }
    String[] pathSegments = StringUtils.split(path, "/");
    String name = pathSegments[pathSegments.length - 1];
    String parentPath = StringUtils.join(Arrays.copyOf(pathSegments, pathSegments.length - 1), '/');
    Resource parent = createSyntheticResource(resourceResolver, parentPath, resourceType);
    return resourceResolver.create(parent, name, new HashMap<String, Object>() {{
        put(ResourceResolver.PROPERTY_RESOURCE_TYPE, resourceType);
    }});
}
