public static int[] transformArray(int[] arr) {
    int temp = arr[0];
    int index = 0;
    for(int i = 1; i < arr.length; i++) {
        if(arr[i] != temp) {
            for(int j = index; j < i; j++) {
                arr[j] = index;
            }
            index = i;
            temp = arr[i];
        }
    }
    for(int j = index; j < arr.length; j++) {
        arr[j] = index;
    }
    return arr;
}
