public PagingParams convertToPagingParams(Object value) {
    PagingParams pagingParams = new PagingParams();
    pagingParams.setOffset(0);

    if (value instanceof PagingParams) {
        PagingParams params = (PagingParams) value;
        pagingParams.setSkip(params.getSkip());
        pagingParams.setTake(params.getTake());
        pagingParams.setTotal(params.isTotal());
        pagingParams.setOrderBy(params.getOrderBy());
    } else if (value instanceof Map<?, ?>) {
        Map<?, ?> mapValue = (Map<?, ?>) value;
        pagingParams.setTake(Integer.parseInt(mapValue.getOrDefault("take", "10").toString()));
        pagingParams.setSkip(Integer.parseInt(mapValue.getOrDefault("skip", "0").toString()));
        Object totalObj = mapValue.get("total");
        if (totalObj != null) {
            pagingParams.setTotal(Boolean.parseBoolean(totalObj.toString()));
        }
        Object orderByObj = mapValue.get("orderBy");
        if (orderByObj != null) {
            pagingParams.setOrderBy(orderByObj.toString());
        }
    }

    return pagingParams;
}
