public int killPrimaryMaster(int timeoutMs) {
    int killedMasterId = -1;
    // Wait until a primary master is elected
    while (true) {
        int primaryMasterId = getPrimaryMasterId();
        if (primaryMasterId != -1) {
            // Primary master found, kill it
            killedMasterId = primaryMasterId;
            killProcess(killedMasterId);
            break;
        } else {
            // No primary master yet, wait for a while
            try {
                Thread.sleep(timeoutMs);
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        }
    }
    return killedMasterId;
}

