public int[] bitSetToIntArray(BitSet set) {
    if (set == null) {
        return new int[0];
    }
    int[] result = new int[set.cardinality()];
    int index = 0;
    for (int i = set.nextSetBit(0); i != -1; i = set.nextSetBit(i + 1)) {
        result[index++] = i;
    }
    return result;
}
