public class CustomLogger {
    private boolean isError;
    private String logMessagePrefix;
    private StringBuffer output = new StringBuffer();

    public CustomLogger(boolean isError, String logMessagePrefix) {
        this.isError = isError;
        this.logMessagePrefix = logMessagePrefix;
    }

    public void log(String line) {
        output.append(line).append(System.lineSeparator());
        if (isError) {
            System.err.println(logMessagePrefix + ": " + line);
        } else {
            System.out.println(logMessagePrefix + ": " + line);
        }
    }

    public String getOutput() {
        return output.toString();
    }
}
