public String serializeArray(Object[] array) throws ConverterException {
    if (array == null) {
        throw new ConverterException("Array is null");
    }

    try {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        ObjectOutputStream oos = new ObjectOutputStream(baos);
        oos.writeObject(array);
        oos.close();
        return Base64.getEncoder().encodeToString(baos.toByteArray());
    } catch (IOException e) {
        throw new ConverterException("Error serializing array", e);
    }
}
