public String getExceptionMessage(Exception exception) {
    String message = exception.getMessage();
    if (sendExceptionMessage) {
        if (exceptionToMessage != null && exceptionToMessage.containsKey(exception.getClass())) {
            message = exceptionToMessage.get(exception.getClass());
        } else if (defaultExceptionMessage != null) {
            message = defaultExceptionMessage;
        }
    }
    return message;
}

