public int getEffectiveValue() throws NumberFormatException {
    if (value != null && !value.isEmpty()) {
        try {
            return Integer.parseInt(value);
        } catch (NumberFormatException e) {
            throw new NumberFormatException("Value is not a parsable integer.");
        }
    } else if (defaultValue != null && !defaultValue.isEmpty()) {
        try {
            return Integer.parseInt(defaultValue);
        } catch (NumberFormatException e) {
            throw new NumberFormatException("Default value is not a parsable integer.");
        }
    } else {
        return 0;
    }
}
