public static String emphasizeTags(String input) {
    String emphasizedString = "";
    boolean tagOpen = false;
    for (int i = 0; i < input.length(); i++) {
        if (input.charAt(i) == '[' && input.charAt(i+1) == '*' && input.charAt(i+2) == ']') {
            tagOpen = !tagOpen;
            i += 2;
        } else {
            if (tagOpen) {
                emphasizedString += input.charAt(i) + "";
            } else {
                emphasizedString += "[" + input.charAt(i) + "]";
            }
        }
    }
    return emphasizedString;
}
