public static List<Method> findBestMatchingMethods(Object receiver, List<Method> methods, Class<?>... args) {
    List<Method> matchingMethods = new ArrayList<>();

    for (Method method : methods) {
        if (method.getParameterCount() == args.length && method.getDeclaringClass().isAssignableFrom(receiver.getClass())) {
            boolean isMatching = true;
            Class<?>[] parameterTypes = method.getParameterTypes();

            for (int i = 0; i < args.length; i++) {
                if (!args[i].isAssignableFrom(parameterTypes[i])) {
                    isMatching = false;
                    break;
                }
            }

            if (isMatching) {
                matchingMethods.add(method);
            }
        }
    }

    return matchingMethods;
}
