public static int convertToByteArray(BigInteger integer, byte[] buffer, int index) {
    byte[] bytes = integer.toByteArray();
    int length = bytes.length;

    for (int i = 0; i < length; ++i) {
        buffer[index + i] = bytes[length - 1 - i];
    }

    return length;
}
