        int depth = stack.getStackDepth();
        for (int i = 0; i < depth && i < userValues.size(); i++) {
            OpcodeStack.Item item = stack.getStackItem(i);
            if (item.getUserValue() == null) {
                item.setUserValue(userValues.get(i));
            }
        }
        userValues.clear();
        sawGOTO = false;
