import javax.jcr.Binary;
import javax.jcr.Node;
import javax.jcr.RepositoryException;
import javax.jcr.Session;

public static long calculateBinaryPropertiesSize(Session session) throws RepositoryException {
    long size = 0;

    for (Node node : session.getRootNode().getNodes()) {
        size += calculateBinaryPropertiesSize(node);
    }

    return size;
}

private static long calculateBinaryPropertiesSize(Node node) throws RepositoryException {
    long size = 0;

    for (String propertyName : node.getPropertyNames()) {
        if (node.getProperty(propertyName).isBinary()) {
            Binary binary = node.getProperty(propertyName).getBinary();
            size += binary.getSize();
        }
    }

    for (Node childNode : node.getNodes()) {
        size += calculateBinaryPropertiesSize(childNode);
    }

    return size;
}
