import org.apache.myfaces.shared.util.StringUtils;

public static String makeHtmlAttributesPassThrough(Object attrs) {
    if (attrs == null) {
        return null;
    }
    if (attrs instanceof String) {
        return (String) attrs;
    }
    if (attrs instanceof Map) {
        StringBuilder sb = new StringBuilder();
        for (Map.Entry entry : ((Map<?, ?>) attrs).entrySet()) {
            if (isPassThroughAttribute(entry.getKey().toString())) {
                sb.append(entry.getValue().toString()).append(' ');
            } else {
                sb.append(entry.getKey().toString()).append('=')
                        .append(StringUtils.escapeHtml(entry.getValue().toString()))
                        .append(' ');
            }
        }
        return sb.toString().trim();
    }
    throw new IllegalArgumentException("Attribute must be a String or a Map, but was " + attrs.getClass().getName());
}

private static boolean isPassThroughAttribute(String key) {
    return key.startsWith("html") || key.startsWith("jsf");
}
