public List<Edge> getIncomingEdges(Vertex iVertex, Map<String, Object> iProperties) {
    List<Edge> incomingEdges = new ArrayList<>();
    Iterator<Edge> edges = iVertex.edges(Direction.IN);
    while (edges.hasNext()) {
        Edge edge = edges.next();
        if (edge.inVertex().equals(iVertex)) {
            boolean addEdge = true;
            for (Map.Entry<String, Object> property : iProperties.entrySet()) {
                if (!edge.property(property.getKey()).orElse("").equals(property.getValue().toString())) {
                    addEdge = false;
                    break;
                }
            }
            if (addEdge) {
                incomingEdges.add(edge);
            }
        }
    }
    return incomingEdges;
}
