import java.util.List;
import java.util.concurrent.CompletableFuture;

public static CompletableFuture<CombinedAsks> combineAsks(
        AsksCallback callback,
        List<CompletableFuture<Ask>> futures) {
    // Create a new CompletableFuture to represent the combined result
    CompletableFuture<CombinedAsks> combinedFuture = new CompletableFuture<>();

    // Use CompletableFuture.allOf() to wait for all the individual futures to complete
    CompletableFuture.allOf(futures.toArray(new CompletableFuture[0]))
            .thenAccept(v -> {
                // Retrieve the results from the individual futures
                List<Ask> asks = futures.stream()
                        .map(CompletableFuture::join)
                        .collect(Collectors.toList());

                // Pass the result to the callback function to combine them
                CombinedAsks combinedAsks = callback.combine(asks);

                // Complete the combinedFuture with the final result
                combinedFuture.complete(combinedAsks);
            });

    return combinedFuture;
}
