public static void computeEigenvalue(double a, double b, double c, double d) {
    double trace = a + d;
    double determinant = a * d - b * c;
    double discriminant = Math.sqrt(trace * trace - 4 * determinant);
    double eigenvalue1 = 0.5 * (trace + discriminant);
    double eigenvalue2 = 0.5 * (trace - discriminant);
    System.out.println("Eigenvalue 1: " + eigenvalue1);
    System.out.println("Eigenvalue 2: " + eigenvalue2);
}
