public static Class<?> getComponentType(Type type, int index) {
    if (type instanceof ParameterizedType) {
        Type[] actualTypeArguments = ((ParameterizedType) type).getActualTypeArguments();
        if (actualTypeArguments.length > index) {
            Type actualTypeArgument = actualTypeArguments[index];
            if (actualTypeArgument instanceof Class) {
                return (Class<?>) actualTypeArgument;
            } else if (actualTypeArgument instanceof ParameterizedType) {
                return (Class<?>) ((ParameterizedType) actualTypeArgument).getRawType();
            } else if (actualTypeArgument instanceof GenericArrayType) {
                Type componentType = ((GenericArrayType) actualTypeArgument).getGenericComponentType();
                if (componentType instanceof Class) {
                    return Array.newInstance((Class<?>) componentType, 0).getClass();
                }
            }
        }
    } else if (type instanceof Class) {
        return getComponentType(((Class<?>) type).getGenericSuperclass(), index);
    }
    return null;
}
