public void bundleStarting() {
    ServiceReference<?> ref = bundleContext.getServiceReference(ServiceListener.class.getName());

    if (ref != null) {
        ServiceListener listener = (ServiceListener) bundleContext.getService(ref);
        // Register the service
        bundleContext.registerService(MyService.class.getName(), new MyServiceImpl(), null);
    } else {
        // Wait until service listener is up
        bundleContext.addServiceListener(new ServiceListener() {
            public void serviceChanged(ServiceEvent event) {
                if (event.getType() == ServiceEvent.REGISTERED && event.getServiceReference().getType().equals(ServiceListener.class.getName())) {
                    // Register the service
                    bundleContext.registerService(MyService.class.getName(), new MyServiceImpl(), null);
                }
            }
        });
    }
}
