public boolean isRemoteRepoExists(String repoName) {
    try {
        File repoFile = new File(".git/config");
        if (repoFile.exists()) {
            Scanner scanner = new Scanner(repoFile);
            while (scanner.hasNextLine()) {
                String line = scanner.nextLine();
                if (line.contains("[remote \""+repoName+"\"]")) {
                    scanner.close();
                    return true;
                }
            }
            scanner.close();
        }
    } catch (FileNotFoundException e) {
        e.printStackTrace();
    }
    return false;
}
