public boolean canUpdateDefinition(String newType) {
    // check if the new type is different from the current type
    if (newType.equals(currentType)) {
        return true;
    }
    // check if the new type is a subtype of the current type
    if (newType.isSubtypeOf(currentType)) {
        return true;
    }
    // otherwise, updating the definition is not possible
    return false;
}
