public String extractClassName(Direction iDirection, String iFieldName) {
    String[] parts = iFieldName.split("\\.");
    String fieldName = parts[parts.length - 1];
    String className = "";
    switch(iDirection) {
        case IN:
            if(fieldName.startsWith("in_")) {
                className = fieldName.substring(3);
            }
            break;
        case OUT:
            if(fieldName.startsWith("out_")) {
                className = fieldName.substring(4);
            }
            break;
    }
    return className;
}
