import org.osgi.framework.ServiceReference;

public class ExampleResolver {
    private BundleContext context;

    public Object resolve(String serviceName) {
        try {
            ServiceReference<?>[] references = context.getAllServiceReferences(null, "(|(" + serviceName + ")(component.name=" + serviceName + "))");
