public enum IterationOrder {
    DEPTH_FIRST,
    BREADTH_FIRST
}

public class Graph {
    private List<Node> nodes;
    private IterationOrder iterationOrder;

    public Iterable<Node> nodes() {
        if (iterationOrder == IterationOrder.DEPTH_FIRST) {
            return depthFirstOrderNodes();
        } else {
            return breadthFirstOrderNodes();
        }
    }

    private Iterable<Node> depthFirstOrderNodes() {
        // Implement DFS algorithm for node traversal
        List<Node> resultList = new ArrayList<>();
        Set<Node> visited = new HashSet<>();

        for (Node node : nodes) {
            if (!visited.contains(node)) {
                dfsVisit(node, visited, resultList);
            }
        }

        return resultList;
    }

    private void dfsVisit(Node node, Set<Node> visited, List<Node> resultList) {
        visited.add(node);
        resultList.add(node);

        for (Node neighbor : node.getNeighbors()) {
            if (!visited.contains(neighbor)) {
                dfsVisit(neighbor, visited, resultList);
            }
        }
    }

    private Iterable<Node> breadthFirstOrderNodes() {
        // Implement BFS algorithm for node traversal
        List<Node> resultList = new ArrayList<>();
        Queue<Node> queue = new LinkedList<>();
        Set<Node> visited = new HashSet<>();

        for (Node node : nodes) {
            if (!visited.contains(node)) {
                queue.offer(node);
                visited.add(node);

                while (!queue.isEmpty()) {
                    Node currentNode = queue.poll();
                    resultList.add(currentNode);

                    for (Node neighbor : currentNode.getNeighbors()) {
                        if (!visited.contains(neighbor)) {
                            queue.offer(neighbor);
                            visited.add(neighbor);
                        }
                    }
                }
            }
        }

        return resultList;
    }

    //other methods in Graph class
}

