import java.nio.file.Files;
import java.nio.file.attribute.BasicFileAttributeView;
import java.nio.file.attribute.FileAttribute;
import java.nio.file.attribute.FileTime;
import java.nio.file.Path;
import java.nio.file.attribute.BasicFileAttributes;

public class FileUtils {

    public static void setInitialAttributes(Path file, FileAttribute<?>... attrs) {
        try {
            // set default attributes
            BasicFileAttributeView view = Files.getFileAttributeView(file, BasicFileAttributeView.class);
            BasicFileAttributes attributes = view.readAttributes();
            FileTime lastModifiedTime = FileTime.fromMillis(System.currentTimeMillis());
            view.setTimes(lastModifiedTime, lastModifiedTime, attributes.creationTime());

            // attempt to set user-provided attributes
            Files.setAttribute(file, "user:myAttribute", "myValue");
            for (FileAttribute<?> attr : attrs) {
                Files.setAttribute(file, attr.name(), attr.value());
            }
        } catch (Exception e) {
            // handle exception as needed
        }
    }
}
