public int estimateJsonSize(Binder binder) {
    int size = 0;
    for (String key : binder.keySet()) {
        Object value = binder.get(key);
        if (value == null) {
            size += key.length() + 4; // for quotes, colon, and null value
        } else if (value instanceof Boolean) {
            size += key.length() + 6; // for quotes, colon, and true/false value
        } else if (value instanceof Number) {
            size += key.length() + value.toString().length() + 3; // for quotes, colon, and number value
        } else if (value instanceof String) {
            size += key.length() + ((String) value).length() + 4; // for quotes, colon, quotes, and string value
        } else if (value instanceof Binder) {
            size += key.length() + estimateJsonSize((Binder) value) + 2; // for quotes, colon, and brackets
        } else if (value instanceof List) {
            size += key.length() + estimateJsonArraySize((List) value) + 2; // for quotes, colon, and brackets
        }
    }
    return size;
}

private int estimateJsonArraySize(List list) {
    int size = 0;
    for (Object object : list) {
        if (object == null) {
            size += 4; // for null value
        } else if (object instanceof Boolean) {
            size += 6; // for true/false value
        } else if (object instanceof Number) {
            size += object.toString().length() + 1; // for number value
        } else if (object instanceof String) {
            size += ((String) object).length() + 2; // for quotes and string value
        } else if (object instanceof Binder) {
            size += estimateJsonSize((Binder) object) + 2; // for brackets
        } else if (object instanceof List) {
            size += estimateJsonArraySize((List) object) + 2; // for brackets
        }
    }
    return size;
}
