public Collection<String> getAllBrowserCookies() {
    Collection<String> cookies = new ArrayList<>();
    // Get the request object from the current session
    HttpServletRequest request = (HttpServletRequest) FacesContext.getCurrentInstance().getExternalContext().getRequest();
    // Get all cookies from the request object
    Cookie[] requestCookies = request.getCookies();
    if (requestCookies != null) {
        // Loop through all cookies and add them to the collection
        for (Cookie cookie : requestCookies) {
            cookies.add(cookie.getName() + "=" + cookie.getValue());
        }
    }
    return cookies;
}
