import javax.servlet.*;
import javax.servlet.http.HttpServletRequest;
import java.io.IOException;

public class ServerNameFilter implements Filter {

    private static final String SERVER_NAME_ATTRIBUTE = "serverName";

    @Override
    public void init(FilterConfig filterConfig) throws ServletException {
        // initialization logic, nothing to do here for this particular filter
    }

    @Override
    public void doFilter(ServletRequest request, ServletResponse response, FilterChain chain) throws IOException, ServletException {
        HttpServletRequest httpServletRequest = (HttpServletRequest) request;
        String serverName = httpServletRequest.getServerName();
        httpServletRequest.setAttribute(SERVER_NAME_ATTRIBUTE, serverName);

        chain.doFilter(request, response);
    }

    @Override
    public void destroy() {
        // destruction logic, nothing to do here for this particular filter
