public class BeanConfigurator {

    public void configureBean(BeanContext context, Environment environment) {
        if (environment != null) {
            AnnotationMetadata annotationMetadata = context.getClassElement().getAnnotationMetadata();
            AnnotationMetadataBuilder metadataBuilder = AnnotationMetadataBuilder
                    .wrap(annotationMetadata)
                    .annotate(EachProperty.class, environment.getActiveNames())
                    .annotate(Property.class, environment.getProperties());
            context.getClassElement().setAnnotationMetadata(metadataBuilder.build());
        }
    }
}
