import java.net.URI;
import java.net.URISyntaxException;

public class ProxyParser {

    public static URI parseProxyAddress(String proxyAddress) throws IllegalArgumentException {
        try {
            URI uri = new URI(proxyAddress);
            String scheme = uri.getScheme();
            if (scheme == null || (!scheme.equalsIgnoreCase("http") && !scheme.equalsIgnoreCase("https"))) {
                throw new IllegalArgumentException("Invalid proxy address. Must start with http:// or https://");
            }
            String host = uri.getHost();
            int port = uri.getPort();
            if (host == null || port == -1) {
                throw new IllegalArgumentException("Invalid proxy address. Must include host and port number.");
            }
            return uri;
        } catch (URISyntaxException e) {
            throw new IllegalArgumentException("Invalid proxy address. Malformed URI.", e);
        }
    }
}
