public void updateEntry(Map<ValueType, KeyType> map, ValueType oldValue, ValueType newValue, KeyType key) {
    if (map.containsKey(newValue)) {
        throw new IllegalArgumentException("New value already exists in the V-to-K mapping");
    }
    if (!map.containsKey(oldValue)) {
        throw new IllegalArgumentException("Old value does not exist in the V-to-K mapping");
    }
    if (!map.get(oldValue).equals(key)) {
        throw new IllegalArgumentException("Old value is not associated with the given key");
    }

    map.remove(oldValue);
    map.put(newValue, key);
}
