import java.util.Iterator;

public class ObfuscatedIterator implements Iterator<Object> {
    private final Object[] array;
    private int index;

    public ObfuscatedIterator(Object[] array) {
        this.array = array;
        index = 0;
    }

    @Override
    public boolean hasNext() {
        return index < array.length;
    }

    @Override
    public Object next() {
        return array[index++];
    }
}
