public void validateAndFixTags(Topic topic) {
    Set<String> exclusiveTags = new HashSet<String>();
    List<String> fixedTags = new ArrayList<String>();

    for(String tag : topic.getTags()) {
        if(exclusiveTags.contains(tag)) {
            continue;
        }

        boolean isExclusive = checkIfTagIsExclusive(tag);

        if(isExclusive) {
            exclusiveTags.add(tag);
            fixedTags.add(tag);
        } else {
            fixedTags.add(tag);
        }
    }

    topic.setTags(fixedTags);
}

