public void addRangeToList(List<int[]> ranges, int[] newRange) {
    int n = ranges.size();
    if (n == 0) {
        ranges.add(newRange);
        return;
    }
    int[] lastRange = ranges.get(n - 1);
    if (newRange[0] > lastRange[1]) {
        ranges.add(newRange);
        return;
    }
    lastRange[1] = Math.max(lastRange[1], newRange[1]);
    ranges.set(n - 1, lastRange);
}
