public HttpRequest createUploadSessionRequest(File file, String folderId) {
    try {
        Drive driveService = new Drive.Builder(HTTP_TRANSPORT, JSON_FACTORY, getCredentials())
            .setApplicationName(APPLICATION_NAME)
            .build();

        File uploadFile = new File(file.getAbsolutePath());
        FileContent mediaContent = new FileContent(FileUtils.getFileMimeType(uploadFile), uploadFile);
        File fileMetadata = new File();
        fileMetadata.setName(uploadFile.getName())
            .setParents(Collections.singletonList(folderId))
            .setMimeType(mediaContent.getType());

        return driveService.files().create(fileMetadata, mediaContent).setFields("id, webContentLink, webViewLink").execute().getRequest();
    } catch (IOException e) {
        System.err.println("An error occurred: " + e);
        return null;
    }
}
