public void loadProtobufDescriptorSet(FileDescriptorSet set, Map<String, FileDescriptor> dependenciesMap, Map<String, FileDescriptor> fileDescriptorMap) throws StageException {
    try {
        for (FileDescriptorProto proto : set.getFileList()) {
            // Get the file name and create a FileDescriptor
            String fileName = proto.getName();
            // Build the dependencies list
            FileDescriptor[] deps = new FileDescriptor[proto.getDependencyCount()];
            for (int i = 0; i < proto.getDependencyCount(); i++) {
                deps[i] = dependenciesMap.get(proto.getDependency(i));
            }
            // Build the current FileDescriptor
            FileDescriptor fileDescriptor = FileDescriptor.buildFrom(proto, deps);
            // Map the current FileDescriptor
            fileDescriptorMap.put(fileName, fileDescriptor);
        }
    } catch (DescriptorValidationException e) {
        throw new StageException("Unable to build Protobuf descriptor set", e);
    }
}
