public void handleFeatureSelectionEvent(FeatureSelectionEvent event) {
    if (isSelectionEnabled()) {
        int[] deselectedRows = event.getDeselectedRows();
        int[] selectedRows = event.getSelectedRows();

        // Check if any deselected row should now be selected
        for (int i = 0; i < deselectedRows.length; i++) {
            int deselectedRow = deselectedRows[i];
            if (!isRowSelected(deselectedRow)) {
                selectRow(deselectedRow);
            }
        }

        // Check if any newly selected row was previously deselected
        for (int i = 0; i < selectedRows.length; i++) {
            int selectedRow = selectedRows[i];
            if (isDeselected(selectedRow)) {
                selectRow(selectedRow);
            }
        }
    }
}
