import com.google.zxing.common.BitMatrix;
import java.awt.image.BufferedImage;

public BitMatrix createBitMatrix(BufferedImage image, int dimension, int moduleSize, int quietZone) {
    int width = image.getWidth();
    int height = image.getHeight();
    int centerX = width / 2;
    int centerY = height / 2;
    int halfDimension = dimension / 2;

    int[] topLeft = getCornerFromCenter(centerX - moduleSize * (7 + halfDimension), centerY - moduleSize * (7 + halfDimension));
    int[] topRight = getCornerFromCenter(centerX + moduleSize * (7 + halfDimension), centerY - moduleSize * (7 + halfDimension));
    int[] bottomLeft = getCornerFromCenter(centerX - moduleSize * (7 + halfDimension), centerY + moduleSize * (7 + halfDimension));
    int[] bottomRight = getCornerFromCenter(centerX + moduleSize * (7 + halfDimension), centerY + moduleSize * (7 + halfDimension));

    BitMatrix matrix = new BitMatrix(dimension + 2 * quietZone, dimension + 2 * quietZone);
    for (int y = 0; y < dimension; y++) {
        for (int x = 0; x < dimension; x++) {
            int xx = (int) (x * ((float) (topRight[0] - topLeft[0]) / dimension) + topLeft[0]);
            int yy = (int) (y * ((float) (bottomLeft[1] - topLeft[1]) / dimension) + topLeft[1]);
            matrix.set(x + quietZone, y + quietZone, image.getRGB(xx, yy) < 0xff000000);
        }
    }

    return matrix;
}

private int[] getCornerFromCenter(int centerX, int centerY) {
    return new int[]{centerX - 3, centerY - 3};
}
