public int[] createSampleRateTable() {
    int[] sampleRates = {44100, 48000, 32000, 22050, 24000, 16000, 11025, 12000, 8000};
    int[] sampleRateTable = new int[16];
    Arrays.fill(sampleRateTable, -1); // Initialize to invalid value

    int i = 0;
    while (i < sampleRates.length) {
        int srCode = i / 3;
        int srMult = i % 3;
        if (sampleRateTable[srCode] == -1 && srMult == 0) {
            sampleRateTable[srCode] = i;
        }
        i++;
    }

    return sampleRateTable;
}
