public double correlationScore(double[] a, double[] b) {
    if (a.length != b.length) {
        throw new IllegalArgumentException("Vectors a and b should have the same length");
    }
    double aMean = 0, bMean = 0, aStdDev = 0, bStdDev = 0, correlation = 0;
    int n = a.length;
    for (int i = 0; i < n; i++) {
        aMean += a[i];
        bMean += b[i];
    }
    aMean /= n;
    bMean /= n;
    for (int i = 0; i < n; i++) {
        aStdDev += Math.pow(a[i] - aMean, 2);
        bStdDev += Math.pow(b[i] - bMean, 2);
        correlation += (a[i] - aMean) * (b[i] - bMean);
    }
    aStdDev = Math.sqrt(aStdDev / (n - 1));
    bStdDev = Math.sqrt(bStdDev / (n - 1));
    correlation /= (n - 1) * aStdDev * bStdDev;
    return correlation;
}
