import java.io.File;
import java.io.FileOutputStream;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

public static void extractZipFiles(String inputZipFilename, String extractPath) throws Exception {

    byte[] buffer = new byte[1024];

    // Create output directory if it doesn't exist
    File folder = new File(extractPath);
    if (!folder.exists()) {
        folder.mkdir();
    }

    // Open input stream to read from the ZIP archive file
    try (ZipInputStream zipInputStream = new ZipInputStream(new FileInputStream(inputZipFilename))) {
        // Read each entry from the ZIP archive file
        ZipEntry zipEntry = zipInputStream.getNextEntry();
        while (zipEntry != null) {
            String fileName = zipEntry.getName();
            File newFile = new File(extractPath + File.separator + fileName);

            if (!zipEntry.isDirectory()) {
                // Create any necessary subdirectories
                new File(newFile.getParent()).mkdirs();

                // Write the file to the output directory
                FileOutputStream outputStream = new FileOutputStream(newFile);
                int length;
                while ((length = zipInputStream.read(buffer)) > 0) {
                    outputStream.write(buffer, 0, length);
                }
                outputStream.close();
            }

            // Move to the next ZIP entry in the archive
            zipEntry = zipInputStream.getNextEntry();
        }
    }
}
