private void initialize(String path) throws CacheUnitException {
    try {
        Configurations config = new Configurations(new File(path));
        DaoFileImpl<T> dao = new DaoFileImpl<>();
        CacheUnit<T> cacheUnit = new CacheUnitImpl<>(dao, config.getCacheProperties().getCapacity());
        this.cacheUnit = cacheUnit;
        BatchUpdateDaemon<T> batchUpdateDaemon = new BatchUpdateDaemonImpl<>(cacheUnit);
        this.batchUpdateDaemon = batchUpdateDaemon;
        InvalidationAuditDaemon<T> invalidationAuditDaemon = new InvalidationAuditDaemonImpl<>(cacheUnit);
        this.invalidationAuditDaemon = invalidationAuditDaemon;
        TimeLimitDaemon<T> timeLimitDaemon = new TimeLimitDaemonImpl<>(cacheUnit, config.getCacheProperties().getExpiredTime());
        this.timeLimitDaemon = timeLimitDaemon;
    } catch (Exception e) {
        throw new CacheUnitException("Failed to initialize the cache unit", e);
    }
}
