public static Map<String, List<String[]>> partitionByClass(String[][] data, int classColumn) {
    Map<String, List<String[]>> partitionedData = new HashMap<>();

    for (String[] row : data) {
        String classLabel = row[classColumn];
        List<String[]> classData = partitionedData.get(classLabel);

        if (classData == null) {
            classData = new ArrayList<>();
            partitionedData.put(classLabel, classData);
        }

        classData.add(row);
    }

    return partitionedData;
}
