public static <T extends Comparable<T>> void insertionSort(T[] data, int start, int end) {
    for (int i = start + 1; i < end; i++) {
        T currentValue = data[i];
        int j = i - 1;

        while (j >= start && data[j].compareTo(currentValue) > 0) {
            data[j + 1] = data[j];
            j--;
        }

        data[j + 1] = currentValue;
    }
}
