public static void inverseUsingLowerTriangularMatrix(double[][] matrix) {
    int n = matrix.length;
    double[][] inverse = new double[n][n];

    // Initialize the inverse matrix as an identity matrix
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) {
                inverse[i][j] = 1.0;
            } else {
                inverse[i][j] = 0.0;
            }
        }
    }

    // Apply row operations to transform the matrix into a lower triangular matrix
    for (int i = 0; i < n; i++) {
        if (matrix[i][i] == 0) {
            throw new ArithmeticException("Matrix is singular!");
        }

        for (int j = i + 1; j < n; j++) {
            double factor = matrix[j][i] / matrix[i][i];

            for (int k = 0; k < n; k++) {
                matrix[j][k] -= factor * matrix[i][k];
                inverse[j][k] -= factor * inverse[i][k];
            }
        }
    }

    // Apply back substitution to find the inverse matrix
    for (int i = n - 1; i >= 0; i--) {
        for (int j = i - 1; j >= 0; j--) {
            double factor = matrix[j][i] / matrix[i][i];

            for (int k = 0; k < n; k++) {
                matrix[j][k] -= factor * matrix[i][k];
                inverse[j][k] -= factor * inverse[i][k];
            }
        }
    }

    // Divide each row by the diagonal element to make it a diagonal matrix
    for (int i = 0; i < n; i++) {
        double diagonalElement = matrix[i][i];

        for (int j = 0; j < n; j++) {
            inverse[i][j] /= diagonalElement;
        }
    }

    // Update the original matrix with the inverse matrix
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            matrix[i][j] = inverse[i][j];
        }
    }
}
