public static String getNextToken(String inputString) {
    String nextToken = "";
    int i = 0;
    while (i < inputString.length()) {
        char c = inputString.charAt(i);
        if (Character.isWhitespace(c)) {
            i++;
        } else if (Character.isLetterOrDigit(c)) {
            while (i < inputString.length() && (Character.isLetterOrDigit(inputString.charAt(i)) || inputString.charAt(i) == '_')) {
                nextToken += inputString.charAt(i);
                i++;
            }
            break;
        } else {
            nextToken += c;
            i++;
            break;
        }
    }
    return nextToken;
}
