public static List<String> getResourcesInPackage(String root) throws IOException {
    List<String> resources = new ArrayList<>();
    URL url = Thread.currentThread().getContextClassLoader().getResource(root);
    if (url == null)
        return resources;
    URLConnection connection = url.openConnection();
    if (connection == null)
        return resources;
    if (connection instanceof JarURLConnection) {
        JarURLConnection jarURLConnection = (JarURLConnection) connection;
        JarFile jarFile = jarURLConnection.getJarFile();
        Enumeration<JarEntry> entries = jarFile.entries();
        while (entries.hasMoreElements()) {
            JarEntry jarEntry = entries.nextElement();
            if (jarEntry.getName().startsWith(root + "/")) {
                resources.add(jarEntry.getName());
            }
        }
    } else {
        URI uri = url.toURI();
        Path path = uri.getPath().contains("!") ? Paths.get(uri.toString().split("!")[0]) : Paths.get(uri);
        try (Stream<Path> stream = Files.walk(path, 1)) {
            stream.filter(path1 -> !path1.equals(path)).forEach(file -> resources.add(file.toString().substring(path.toString().length()).replace("\\", "/")));
        }
    }
    return resources;
}
