import org.apache.logging.log4j.Level;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;
import org.apache.logging.log4j.ThreadContext;
import org.apache.logging.log4j.core.appender.ConsoleAppender;
import org.apache.logging.log4j.core.appender.SyslogAppender;
import org.apache.logging.log4j.core.config.Configurator;

public class LoggingConfig {

    public static void configureLogging(String ident, Level level) {

        String syslogHost = System.getenv("SPOTIFY_SYSLOG_HOST");
        String syslogPort = System.getenv("SPOTIFY_SYSLOG_PORT");

        if (syslogHost != null && syslogPort != null) {
            // Use syslog appender
            SyslogAppender appender = SyslogAppender.newBuilder()
                .setHost(syslogHost)
                .setPort(Integer.parseInt(syslogPort)
                .build();
            appender.start();
            Configurator.setLevel(ident, level);
            Configurator.addAppender(appender);
        } else {
            // Use console appender
            ConsoleAppender appender = ConsoleAppender.newBuilder()
                .setTarget(ConsoleAppender.Target.SYSTEM_ERR)
                .build();
            appender.start();
            Configurator.setLevel(ident, level);
            Configurator.addAppender(appender);
        }

        // Set ThreadContext parameters
        ThreadContext.put("LogId", ident);
        ThreadContext.put("LogLevel", level.toString());

        Logger logger = LogManager.getLogger(ident);
        logger.info("Logging configured successfully");
    }

}
