public void visitMethodInsn(int opcode, String owner, String name, String descriptor, boolean isInterface) {
    if (opcode == INVOKESTATIC && name.equals("throwException") && descriptor.equals("(Ljava/lang/Exception;)V")) {
        // The method throws an exception, so it's not empty.
        return;
    }

    // Check if the method is empty.
    LabelNode start = new LabelNode();
    LabelNode end = new LabelNode();
    super.visitCode();
    super.visitLabel(start);
    super.visitTypeInsn(NEW, "java/lang/RuntimeException");
    super.visitInsn(DUP);
    super.visitLdcInsn("Empty method: " + name);
    super.visitMethodInsn(INVOKESPECIAL, "java/lang/RuntimeException", "<init>", "(Ljava/lang/String;)V", false);
    super.visitInsn(ATHROW);
    super.visitLabel(end);
    super.visitLocalVariable("this", "L" + owner + ";", null, start, end, 0);
    super.visitMaxs(3, 1);
    super.visitEnd();
}
