public static InputStream openConfigFile(String filePath, ClassLoader classLoader) throws FileNotFoundException {
    File configFile = new File(System.getProperty("mdw.config.location"), filePath);
    if (configFile.exists()) {
        return new FileInputStream(configFile);
    } else {
        InputStream inputStream = classLoader.getResourceAsStream(filePath);
        if (inputStream != null) {
            return inputStream;
        } else {
            throw new FileNotFoundException("Configuration file not found");
        }
    }
}
