public String getSizeInfo(boolean readable, long size, long totalSize) {
    String formattedValue = "";
    double percentage = ((double) size / totalSize) * 100;
    if (readable) {
        String[] units = {"B", "KB", "MB", "GB", "TB"};
        int digitGroups = (int) (Math.log10(size) / Math.log10(1024));
        formattedValue = String.format("%.2f" + " " + units[digitGroups], size / Math.pow(1024, digitGroups));
    } else {
        formattedValue = String.valueOf(size);
    }
    return formattedValue + " (" + String.format("%.2f", percentage) + "%)";
}
