public LinkDiscoverers getLinkDiscoverers(Collection<Object> ifAvailable) {
    List<LinkDiscoverer> discoverers = new ArrayList<>();
    for (LinkDiscoverer discoverer : ifAvailable) {
        if (discoverer instanceof HypermediaMappingDiscoverer) {
            discoverers.add(new ConvertingJackson2HttpMessageConverter(new MappingJackson2HttpMessageConverter(),
