                            app = ((RecordOwnerParent)record.getOwner()).getTask().getApplication();
            String systemName = null;
            if (app != null)
            {
                strFilePathName = Util.addURLParam(strFilePathName, Params.LANGUAGE, app.getLanguage(true), false);
                systemName = app.getProperty(Constants.SYSTEM_NAME);
            }
            if (systemName == null)
                if (record.getTable() != null)
                    if (record.getTable().getDatabase() != null)
                        if (record.getTable().getDatabase().getDatabaseOwner() != null)
                            systemName = record.getTable().getDatabase().getDatabaseOwner().getProperty(Constants.SYSTEM_NAME);
            strFilePathName = Util.addURLParam(strFilePathName, Constants.SYSTEM_NAME, systemName, false);
            URL url = null;
            if (app == null)
            {
                String strFilePrefix = "http://";
                strFilePrefix += "localhost/" + Constants.DEFAULT_SERVLET;    
                strFilePathName = strFilePrefix + strFilePathName;
                url = new URL(strFilePathName);
            }
            else
            {
                String strServletName = app.getProperty(Params.SERVLET);
                if ((strServletName == null) || (strServletName.length() == 0))
                    if ((app.getProperty(Params.CODEBASE) !=  null) && (app.getProperty(Params.CODEBASE).length() > 0))
                        if (app.getProperty(Params.CODEBASE).indexOf('/') != -1)
                            strServletName = app.getProperty(Params.CODEBASE).substring(app.getProperty(Params.CODEBASE).lastIndexOf('/') + 1) + Constants.DEFAULT_SERVLET;
                if ((strServletName == null) || (strServletName.length() == 0))
                    strServletName = Constants.DEFAULT_SERVLET;
                strFilePathName = strServletName + strFilePathName;
                 url = app.getResourceURL(strFilePathName, null);
            }
            return url.openStream();
        } catch (MalformedURLException ex) {
            ex.printStackTrace();
        } catch (IOException ex) {
            ex.printStackTrace();
        }
        return null;
