public boolean isEdgeOnUnwantedCycle(Node node, Edge edge) {
    Set<Node> visitedNodes = new HashSet<>();
    visitedNodes.add(node);

    Node current = edge.getOpposite(node);
    while (current != null && !visitedNodes.contains(current)) {
        visitedNodes.add(current);
        current = getNextNodeOnCycle(current);
    }

    return current == null;
}

private Node getNextNodeOnCycle(Node current) {
    for (Edge edge : current.getEdges()) {
        Node next = edge.getOpposite(current);
        if (next.isVisited()) {
            return next;
        }
        next.setVisited(true);
        Node result = getNextNodeOnCycle(next);
        if (result != null) {
            return result;
        }
    }
    return null;
}
