public int computeDifference(int[] set1, int[] set2, int[] buffer) {
    int i = 0, j = 0, k = 0;
    while (i < set1.length && j < set2.length) {
        if (set1[i] < set2[j]) {
            buffer[k++] = set1[i++];
        } else if (set1[i] > set2[j]) {
            j++;
        } else {
            i++;
            j++;
        }
    }
    while (i < set1.length) {
        buffer[k++] = set1[i++];
    }
    return k;
}
