public long getTimestampFromRawTextFormat(Column columnInfo, Calendar userCalendar, TimeZone timeZone) throws SQLException {
    if (!columnInfo.getTypeName().equalsIgnoreCase("text")) {
        throw new SQLException("Column type is not text.");
    }
    String rawText = columnInfo.getString();
    DateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS");
    dateFormat.setCalendar(userCalendar);
    dateFormat.setTimeZone(timeZone);
    try {
        Date date = dateFormat.parse(rawText);
