public Observable<BackupStatusResponseInner> getContainerBackupStatus(String azureRegion, ContainerBackupStatusRequest parameters) throws IllegalArgumentException {
    // validate parameters
    if(parameters == null){
        throw new IllegalArgumentException("Parameter 'parameters' cannot be null");
    }

    // call Azure API to get backup status
    HttpClient httpClient = HttpClient.newHttpClient();
    HttpRequest httpRequest = HttpRequest.newBuilder()
            .uri(URI.create("https://management.azure.com/" + azureRegion + "/providers/Microsoft.ContainerRegistry/registries/" + parameters.getRegistryName() + "/backupStatus?api-version=2019-06-01-preview"))
            .GET()
            .build();
    HttpResponse<String> httpResponse;
    try {
        httpResponse = httpClient.send(httpRequest, HttpResponse.BodyHandlers.ofString());
    } catch (IOException | InterruptedException e) {
        throw new RuntimeException("Error communicating with Azure API", e);
    }

    // parse the response into BackupStatusResponseInner object
    ObjectMapper objectMapper = new ObjectMapper();
    BackupStatusResponseInner backupStatusResponse;
    try {
        backupStatusResponse = objectMapper.readValue(httpResponse.body(), BackupStatusResponseInner.class);
    } catch (JsonProcessingException e) {
        throw new RuntimeException("Error parsing Azure API response", e);
    }

    return Observable.just(backupStatusResponse);
}
