public <T> T scanNode(TreeNode<T> tree, T p, NodeVisitor<T> visitor) {
    visitor.visit(tree, p);
    T result = visitor.getResult();

    if (tree.left() != null) {
        result = scanNode(tree.left(), result, visitor);
    }

    if (tree.right() != null) {
        result = scanNode(tree.right(), result, visitor);
    }

    return result;
}
