public void triggerDownstreamBuilds(AbstractBuild<?, ?> build, BuildListener listener) {
    if(build != null) {
        List<AbstractProject<?, ?>> downstreamProjects = build.getDownstreamProjects();
        if(downstreamProjects != null && downstreamProjects.size() > 0) {
            for(AbstractProject<?, ?> project : downstreamProjects) {
                List<Action> actions = new ArrayList<Action>();
                actions.add(new CauseAction(new Cause.UpstreamCause(build)));
                project.scheduleBuild(0, new CauseAction(new Cause.UpstreamCause(build)), actions);
                listener.getLogger().println("Triggered downstream build of " + project.getName());
            }
        } else {
            listener.getLogger().println("No downstream projects found");
        }
    } else {
        listener.getLogger().println("Current build is null");
    }
}
