public ConfiguredCloseableHttpClient createHttpClient(String name) {
  HttpClientBuilder builder = HttpClientBuilder.create();
  builder.useSystemProperties().setRedirectStrategy(new LaxRedirectStrategy());
  builder.disableContentCompression();
  builder.disableCookieManagement();
  builder.setKeepAliveStrategy(new DefaultConnectionKeepAliveStrategy());
  builder.setRetryHandler(new DefaultHttpRequestRetryHandler());
  builder.setServiceUnavailableRetryStrategy(new DefaultServiceUnavailableRetryStrategy());
  return new ConfiguredCloseableHttpClient(builder.build(), name);
}
