import io.prometheus.client.Collector;
import io.prometheus.client.Counter;
import io.prometheus.client.Gauge;

public static Collector.MetricFamilySamples.Sample getMetricFromSnapshot(String metricName, String metricDescription,
                                                                             List<String> labelKeys, List<String> labelValues,
                                                                             com.codahale.metrics.Snapshot codahaleSnapshot, double count) {
    Collector.Type metricType = Collector.Type.GAUGE;

    //Choose type according to metric name (use Gauge by default)
    if (metricName.contains("counter") || metricName.contains("total") || metricName.contains("cumulative")) {
        metricType = Counter.Type.COUNTER;
    } else if (metricName.contains("gauge") || metricName.contains("current") || metricName.contains("value")) {
        metricType = Gauge.Type.GAUGE;
    }

    //build metric name and description
    StringBuilder nameBuilder = new StringBuilder();
    nameBuilder.append(metricName);
    //add suffix according to metric type
    if(metricType == Counter.Type.COUNTER){
        nameBuilder.append("_total");
    }
    nameBuilder.append("_");
    nameBuilder.append(metricType.toString().toLowerCase());
    String name = nameBuilder.toString();

    StringBuilder descriptionBuilder = new StringBuilder();
    descriptionBuilder.append(metricDescription);
    descriptionBuilder.append(" (");
    descriptionBuilder.append(metricType.toString().toLowerCase());
    descriptionBuilder.append(")");
    String description = descriptionBuilder.toString();

    //Create metric and add values
    Collector.MetricFamilySamples.Sample sample = new Collector.MetricFamilySamples.Sample(name, labelKeys, labelValues, count, codahaleSnapshot.getMean());
    return sample;
}
