            @Override
            public void request(long outern) {
                iteratorThread.execute(() -> {
                    if (complete) {
                        return;
                    }
                    long n = outern;
                    try {
                        while (iterator.hasNext() && n-- > 0) {
                            self().onNext(iterator.next());
                        }
                        if (!iterator.hasNext()) {
                            complete = true;
                            self().onComplete();
                        }
                    } catch (Throwable t) {
                        self().onError(t);
                    }
                });
            }
            @Override
            public void cancel() {
            }
        };
        processor = in -> (OUT)in;
        onSubscribe(producer);
        Thread.currentThread().setName(Thread.currentThread()+" (rx async stream processor)");
