import org.apache.lucene.document.Document;
import org.apache.lucene.index.Term;
import org.apache.lucene.search.*;

public Query getQueryForRangeTombstone(Term partitionKey, RangeTombstone rangeTombstone) {
    Query partitionKeyQuery = new TermQuery(partitionKey);
    Query deletedDocumentsQuery = getQueryForDeletedDocuments(rangeTombstone);
    BooleanQuery.Builder builder = new BooleanQuery.Builder();
    builder.add(partitionKeyQuery, BooleanClause.Occur.MUST);
    builder.add(deletedDocumentsQuery, BooleanClause.Occur.MUST_NOT);
    return builder.build();
}

private Query getQueryForDeletedDocuments(RangeTombstone rangeTombstone) {
    Term lowerTerm = new Term(rangeTombstone.partitionKey(), rangeTombstone.minValue());
    Term upperTerm = new Term(rangeTombstone.partitionKey(), rangeTombstone.maxValue());
    Query lowerQuery = new TermQuery(lowerTerm);
    Query upperQuery = new TermQuery(upperTerm);
    Query rangeQuery = new RangeQuery(lowerTerm, upperTerm, true, true);
    BooleanQuery.Builder builder = new BooleanQuery.Builder();
    builder.add(lowerQuery, BooleanClause.Occur.SHOULD);
    builder.add(upperQuery, BooleanClause.Occur.SHOULD);
    builder.add(rangeQuery, BooleanClause.Occur.SHOULD);
    return builder.build();
}
