public void invokeObject(InputStream in, OutputStream out) throws Throwable {
    BurlapInput bIn = new BurlapInput(in);
    BurlapOutput bOut = new BurlapOutput(out);
    Object obj = bIn.readObject();
    if (obj instanceof String) {
        String methodName = (String) obj;
        try {
            Object result = invokeMethod(methodName, bIn);
            bOut.writeObject(result);
        } catch (Throwable ex) {
            bOut.writeFault(FaultException.makeFault(ex));
        }
    } else {
        bOut.writeFault(FaultException.makeFault("Expected string identifier for method invocation, instead received: "
                + obj.getClass().getName()));
    }

    bOut.close();
}
