public int getHostHash(String url) {
    int hash = url.hashCode();
    try {
        String host = new URL(url).getHost();
        hash = 31 * hash + (host != null ? host.hashCode() : 0);
    } catch (MalformedURLException e) {
        e.printStackTrace();
    }
    return hash;
}
