public boolean isVoidFunctionalInterface(JCTree.JCMethodDecl methodDecl) {
    Symbol.MethodSymbol methodSymbol = methodDecl.sym;
    Type returnType = methodSymbol.getReturnType();

    // Check if this is a functional interface
    if (!methodSymbol.isFunctional()) {
        return false;
    }

    // Check if the return type is void, including cases where it is boxed or unboxed
    return returnType.toString().equals("void") || returnType.toString().equals("java.lang.Void");
}
