public File createHeapDump(String outputDir) {
    try {
        String fileName = outputDir + "heapDump_" + System.currentTimeMillis() + ".hprof";
        //use jmap to create a heap dump in the specified file
        ProcessBuilder pb = new ProcessBuilder("jmap", "-dump:file=" + fileName, Integer.toString(ProcessHandle.current().pid()));
        Process process = pb.start();
        process.waitFor();
        return new File(fileName);
    } catch (IOException | InterruptedException e) {
        e.printStackTrace();
    }
    return null;
}
