public char getSymbolPosition(String cell) {
    char symbolPosition = 's'; // default to suffix position
    String[] cellParts = cell.split(" "); // split the cell into parts by space
    String lastPart = cellParts[cellParts.length - 1]; // get the last part

    if (lastPart.startsWith("$")) { // if the last part starts with '$'
        symbolPosition = (lastPart.endsWith("]") ? 'p' : 's'); // check if it ends with ']', if yes, it means prefix position otherwise suffix position
    } else if (lastPart.endsWith("$")) { // if the last part ends with '$'
        symbolPosition = (lastPart.startsWith("[") ? 'p' : 's'); // check if it starts with '[', if yes, it means prefix position otherwise suffix position
    }

    return symbolPosition;
}
