import org.deeplearning4j.nn.conf.Activation;

public Activation getActivationFromConfig(Map<String, Object> layerConfig) 
        throws InvalidKerasConfigurationException, UnsupportedKerasConfigurationException {

    // Extract activation function name from layer config
    String activationName = (String) layerConfig.get("activation");

    // Map Keras activation function name to DL4J activation enum
    switch(activationName) {
        case "linear":
            return Activation.IDENTITY;
        case "softmax":
            return Activation.SOFTMAX;
        case "relu":
            return Activation.RELU;
        case "sigmoid":
            return Activation.SIGMOID;
        case "tanh":
            return Activation.TANH;
        case "hard_sigmoid":
            return Activation.HARDSIGMOID;
        default:
            throw new UnsupportedKerasConfigurationException(
                    "Unsupported activation function name: " + activationName);
    }
}
