public Map<String, String> resolveLinkedIds(List<String> linkedIds, boolean useCache) {
    Map<String, String> resolvedResources = new HashMap<>();

    if (useCache) {
        // use cache to resolve resources
        for (String linkedId : linkedIds) {
            String cachedResource = Cache.get(linkedId);
            if (cachedResource != null) {
                resolvedResources.put(linkedId, cachedResource);
            } else {
                String resource = resolveFromDatabase(linkedId);
                Cache.set(linkedId, resource);
                resolvedResources.put(linkedId, resource);
            }
        }
    } else {
        // resolve resources directly from database
        for (String linkedId : linkedIds) {
            String resource = resolveFromDatabase(linkedId);
            resolvedResources.put(linkedId, resource);
        }
    }

    return resolvedResources;
}

