import org.jcodec.common.model.Picture;
import boofcv.struct.image.ImageUInt8;

public static ImageUInt8 jcodecToBoofCV(Picture input) {
    int width = input.getWidth();
    int height = input.getHeight();
    int stride = input.getPlaneData(0).getStride();
    ImageUInt8 output = new ImageUInt8(width, height);
    byte[] data = output.data;
    int pOff = 0;
    for (int y = 0; y < height; y++, pOff += stride) {
        for (int x = 0; x < width; x++) {
            data[pOff + x] = input.getPlaneData(0).getByte(y * stride + x);
        }
    }
    return output;
}
