public static int calculateDistance(String nodePath1, String nodePath2) {
    String[] nodes1 = nodePath1.split("\\.");
    String[] nodes2 = nodePath2.split("\\.");
    int minLength = Math.min(nodes1.length, nodes2.length);
    int distance = 0;
    for (int i = 0; i < minLength; i++) {
        if (!nodes1[i].equals(nodes2[i])) {
            distance += nodes1[i].length() + nodes2[i].length() + 2; // add non-overlapping length
        }
    }
    if (nodes1.length != nodes2.length) {
        int maxPathLength = (nodes1.length > nodes2.length) ? nodePath1.length() : nodePath2.length();
        distance += maxPathLength - Math.min(nodePath1.length(), nodePath2.length()) + 1;
    }
    return distance;
}
