public Node inlineArguments(Node node, Map<String, Node> arguments) {
    final NodeConvertingVisitor visitor = new NodeConvertingVisitor() {

        int varCount = 0;

        @Override
        public Node visit(Identifier identifier, Node node) {
            final Node value = arguments.get(identifier.getName());
            if (value == null) {
                return identifier;
            } else {
                if (value instanceof Function) {
                    // Can't inline functions
                    return identifier;
                }
                if (value instanceof Var) {
                    Var var = (Var) value;
                    if (var.getInit() == null) {
                        return identifier;
                    } else {
                        // Unroll "var x = val;" and inline "val".
                        Node clonedInit = var.getInit().cloneTree();
                        return clonedInit.accept(this, clonedInit);
                    }
                }
                // Cache value usage
                return value.cloneTree();
            }
        }

        @Override
        public Node visit(Call call, Node node) {
            Node callee = call.getCallee();
            Node[] arguments = new Node[call.getArgs().length];
            boolean mutated = false;
            for (int i = 0; i < arguments.length; ++i) {
                arguments[i] = call.getArg(i).accept(this);
                if (arguments[i] != call.getArg(i)) {
                    mutated = true;
                }
            }
            if (mutated || callee.accept(this) != callee) {
                call = new Call(call.getSourcePosition(), callee, arguments);
                call.setJSDocInfo(callMaybeGetJSDocInfo(node));
            }
            return call;
        }

        @Override
        public Node visit(NodeTraversal t, Node n, Node parent) {
            if (n.isName() && parent != null && !n.getString().startsWith("$jscomp$")) {
                if (NodeUtil.isLhs(parent, n) && conditionalNodeMatch(parent, n)) {
                    // Do not change conditionals from "x === undefined" to "x == null"
                    return n;
                }
                final Var var = t.getTypedScope().getVar(n.getString());
                if (var == null) {
                    final String varName = "$jscomp$where$" + varCount++;
                    final Node replacement = newName(varName, n);
                    final Var replacingVar = t.getTypedScope().declare(replacement, null, null);
                    TranspilerContext context = new TranspilerContext(t.getCompiler());
                    context.ensureTyped(replacingVar);
                    parent.replaceChild(n, replacement);
                    return replacement;
                }
                return visit(new Name(n), n);
            }
            return n;
        }

        private boolean conditionalNodeMatch(Node parent, Node child) {
            return child.getParent().isNot()
                    && child.getNext().isNumber()
                    && parent.isStrictEqual();
        }
    };
    return visitor.visit(node);
}
