public View getViewByClassAndIndex(Class<? extends View> viewClass, int index) {
    if (viewClass == null) {
        throw new IllegalArgumentException("viewClass cannot be null");
    }
    View view = null;
    int count = 0;
    for (int i = 0; i < getViewCount(); i++) {
        View v = getViewAt(i);
        if (viewClass.isInstance(v)) {
            if (count == index) {
                view = v;
                break;
            } else {
                count++;
            }
        }
    }
    return view;
}
