import java.util.concurrent.TimeUnit;

import cyclops.reactive.ReactiveSeq;

public class JitterExample {

    public static <T> ReactiveSeq<T> jitter(ReactiveSeq<T> stream, long jitterInNanos) {
        return stream.map(a -> {
            try {
                long amount = (long) (Math.random()*jitterInNanos);
                TimeUnit.NANOSECONDS.sleep(amount);
                return a;
            } catch (InterruptedException e) {
                throw new RuntimeException(e);
            }
        });
    }    
}
