import javax.ws.rs.client.Client;
import javax.ws.rs.client.ClientBuilder;
import javax.ws.rs.core.Response;

public static Response getParaApi(String resourcePath, Map<String, String> params) {
    String baseUrl = "https://api.paraio.org/v1/";
    Client client = ClientBuilder.newClient();
    WebTarget target = client.target(baseUrl).path(resourcePath);
    for (String key : params.keySet()) {
        target = target.queryParam(key, params.get(key));
    }
    Response response = target.request().get();
    return response;
}
