public BulkResponseObject pauseWorkflows(List<String> workflowIds){
    BulkResponseObject response = new BulkResponseObject();
    List<String> succeededWorkflows = new ArrayList<>();
    List<String> failedWorkflows = new ArrayList<>();

    for(String workflowId : workflowIds){
        // Perform pause operation on the workflow
        boolean pauseSuccess = pauseWorkflow(workflowId);
        if(pauseSuccess){
           succeededWorkflows.add(workflowId);
        } else {
           failedWorkflows.add(workflowId);
           response.setError(workflowId, "Failed to pause workflow");
        }
    }

    response.setSucceeded(succeededWorkflows);
    response.setFailed(failedWorkflows);

    return response;
}

