public String formatLogMessage(String message, Object... args) {
    // Check if the message contains any placeholders
    if (message == null || !message.contains("{}")) {
        return message;
    }

    // Replace every placeholder with its corresponding argument
    for (Object arg : args) {
        int index = message.indexOf("{}");
        if (index == -1) {
            break;
        }
        message = message.substring(0, index) + arg.toString() + message.substring(index + 2);
    }

    return message;
}
