private Map<String, Map<String, Object>> deserializeMonomerStoreJson(JSONParser parser, AttachmentRegistry attachmentDB) throws JsonParseException, IOException, EncoderException {
    Map<String, Map<String, Object>> monomers = new HashMap<>();

    Object obj = parser.parse();
    JSONObject jsonObject = (JSONObject) obj;
    JSONArray array = (JSONArray) jsonObject.get("monomers");

    for (int i = 0; i < array.size(); i++) {
        JSONObject jsonMonomer = (JSONObject) array.get(i);
        String symbol = (String) jsonMonomer.get("symbol");

        Map<String, Object> monomerProperties = new HashMap<>();
        monomerProperties.put("attachments", new HashMap<String, Object>());

        // Deserialize attachments
        JSONArray attachmentArray = (JSONArray) jsonMonomer.get("attachments");
        for (int j = 0; j < attachmentArray.size(); j++) {
            JSONObject jsonAttachment = (JSONObject) attachmentArray.get(j);
            String name = (String) jsonAttachment.get("name");
            String id = (String) jsonAttachment.get("id");

            Attachment att = attachmentDB.getAttachment(id);
            monomerProperties.put(name, att);
            monomerProperties.put("type", "normal");

            if (att instanceof RgroupAttachment) {
                monomerProperties.put("type", "rgroup");
            }
        }

        // Add monomer properties
        monomerProperties.put("smiles", (String) jsonMonomer.get("smiles"));
        monomerProperties.put("canSMILES", (String) jsonMonomer.get("canSMILES"));
        monomerProperties.put("molfile", (String) jsonMonomer.get("molfile"));

        monomers.put(symbol, monomerProperties);
    }

    return monomers;
}
