public AttributeStatement createAttributeStatement(String subject, List<Attribute> attributes, String attributeNamespace) {
     AttributeStatement statement = new AttributeStatementBuilder().buildObject();
     statement.setSubject(new SubjectBuilder().buildObject());
     statement.getSubject().setName(new NameIDBuilder().buildObject());
     statement.getSubject().getName().setValue(subject);

     for (Attribute attribute : attributes) {
         statement.getAttributes().add(attribute);
     }

     statement.getAttributes().forEach(attribute -> {
         attribute.setNamespace(attributeNamespace);
     });

     return statement;
}
