public Properties loadParseResolveFromReader(Reader configReader, boolean useSystemEnvironment){
    Properties properties = new Properties();
    try {
        properties.load(configReader);
    } catch (IOException e) {
        e.printStackTrace();
    }
    StrSubstitutor sub = new StrSubstitutor(useSystemEnvironment ? new EnvironmentVariableLookup() : new StrLookup<String>() {
        @Override
        public String lookup(String s) {
            return null;
        }

        @Override
        public String lookup(String s, int i, int i1) {
            return null;
        }
    });
    sub.setVariableResolver(new PropertiesVariableResolver(properties));
    String resolved = sub.replace(properties.toString());
    try {
        properties.load(new StringReader(resolved));
    } catch (IOException e) {
        e.printStackTrace();
    }
    return properties;
}
