import org.apache.avro.Schema;
import org.apache.avro.generic.GenericData;
import org.apache.avro.generic.GenericRecord;
import org.apache.flink.api.common.typeinfo.TypeInformation;
import org.apache.flink.api.java.typeutils.RowTypeInfo;
import org.apache.flink.types.Row;

public static RowTypeInfo fromAvroClass(Class<? extends GenericRecord> avroClass) {
    Schema avroSchema = avroClass.newInstance().getSchema();
    String[] fieldNames = avroSchema.getFields().stream()
            .map(Schema.Field::name)
            .toArray(String[]::new);
    TypeInformation<?>[] fieldTypes = avroSchema.getFields().stream()
            .map(field -> TypeInformation.of(fromAvroType(field.schema())))
            .toArray(TypeInformation[]::new);
    return new RowTypeInfo(fieldTypes, fieldNames);
}

private static Class<?> fromAvroType(Schema schema) {
    switch (schema.getType()) {
        case BOOLEAN:
            return Boolean.class;
        case INT:
            return Integer.class;
        case LONG:
            return Long.class;
        case FLOAT:
            return Float.class;
        case DOUBLE:
            return Double.class;
        case STRING:
            return String.class;
        case BYTES:
            return byte[].class;
        case RECORD:
            return Row.class;
        case ARRAY:
            return GenericData.Array.class;
        default:
            throw new IllegalArgumentException("Unsupported Avro type: " + schema.getType());
    }
}
