public static int getMedianIndex(int[] arr, int i, int j, int k) {
    int a = arr[i];
    int b = arr[j];
    int c = arr[k];
    if (a > b) {
        if (b > c) {
            return j;
        } else if (a > c) {
            return k;
        } else {
            return i;
        }
    } else { // a <= b
        if (a > c) {
            return i;
        } else if (b > c) {
            return k;
        } else {
            return j;
        }
    }
}
