public void setSwitchAttributes(ResponseWriter rw, UISelectBoolean selectBooleanCheckbox) throws IOException {
    if (selectBooleanCheckbox != null) {
        rw.writeAttribute("class", "custom-control-input", "class");
        rw.writeAttribute("data-toggle", "toggle", "data-toggle");
        rw.writeAttribute("name", selectBooleanCheckbox.getClientId(), null);
        rw.writeAttribute("id", selectBooleanCheckbox.getClientId(), null);
        rw.writeAttribute("data-on", "Yes", null);
        rw.writeAttribute("data-off", "No", null);
        rw.writeAttribute("data-size", "small", null);
        if (selectBooleanCheckbox.isSelected()) {
            rw.writeAttribute("checked", "checked", null);
        }
        if (selectBooleanCheckbox.isDisabled()) {
            rw.writeAttribute("disabled", "disabled", null);
        }
    }
}
