public void buildEar(File outputFile) throws MojoExecutionException, IOException {
    String traHome = System.getenv("TRA_HOME");
    String traBin = traHome + "/bin/buildear";

    if (!new File(traBin).exists()) {
        throw new MojoExecutionException("buildear binary not found in " + traHome);
    }

    String[] command = { traBin,
            "-ear", archiveFile.getAbsolutePath(),
            "-output", outputFile.getAbsolutePath() };

    Process process = new ProcessBuilder(command)
            .redirectErrorStream(true)
            .start();

    try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
        String line;
        while ((line = reader.readLine()) != null) {
            getLog().info(line);
        }
    }

    int exitCode = process.waitFor();
    if (exitCode != 0) {
        throw new MojoExecutionException("buildear execution failed with exit code " + exitCode);
    }
}
