public static Object getDefaultValue(Class<?> type) {
    if (type == boolean.class) {
        return false;
    } else if (type == char.class) {
        return '\0';
    } else if (type == byte.class || type == short.class || type == int.class || type == long.class || type == float.class || type == double.class) {
        return 0;
    } else {
        return null;
    }
}
