public static int[] getDashArray(String dashStr) {
    if (dashStr == null || dashStr.isEmpty()) {
        return null;
    }
    String[] dashStringArray = dashStr.split(" ");
    int[] dashIntArray = new int[dashStringArray.length];
    for (int i = 0; i < dashStringArray.length; i++) {
        try {
            dashIntArray[i] = Integer.parseInt(dashStringArray[i]);
        } catch (NumberFormatException e) {
            return null;
        }
    }
    return dashIntArray;
}
