public static File getClassFile(Class<?> cls) {
    String classResourceName = cls.getName().replace('.', '/') + ".class";
    URL classResourceUrl = cls.getClassLoader().getResource(classResourceName);
    if (classResourceUrl != null) {
        try {
            URI classResourceUri = classResourceUrl.toURI();
            if ("jar".equals(classResourceUri.getScheme())) {
                String jarFilePath = classResourceUri.getSchemeSpecificPart();
                int jarSeparatorIndex = jarFilePath.indexOf("!/");
                if (jarSeparatorIndex != -1) {
                    String jarFileLocation = jarFilePath.substring(0, jarSeparatorIndex);
                    return new File(new URI(jarFileLocation));
                }
            } else if ("file".equals(classResourceUri.getScheme())) {
                return new File(classResourceUri);
            }
        } catch (URISyntaxException e) {
            // ignore and return null
        }
    }
    return null;
}
