public void collectAccessControlsRecursively(AccessControlGroup group, Set<AccessControlGroup> toplevelGroups) {
    if (toplevelGroups == null || group == null) {
        return;
    }

    if (!toplevelGroups.contains(group)) {
        toplevelGroups.add(group);
    }

    for (AccessControl accessControl : group.getAccessControls()) {
        if (accessControl instanceof AccessControlGroup) {
            collectAccessControlsRecursively((AccessControlGroup) accessControl, toplevelGroups);
        } else {
            // add the access control to the toplevel groups
            for (AccessControlGroup toplevelGroup : toplevelGroups) {
                toplevelGroup.addAccessControl(accessControl);
            }
        }
    }
}
