public Set<SSSRing> assignAtomTypes(IAtomContainer molecule) throws CDKException {
    try {
        //Detect aromaticity
        AromaticityDetector.detectAromaticity(molecule);
        //Generate HOSE codes
        final IDCodeGenerator idCodeGenerator = new IDCodeGenerator();
        final CDKHueckelAromaticityDetector aromaticityDetector = new CDKHueckelAromaticityDetector();
        aromaticityDetector.detectAromaticity(molecule);
        idCodeGenerator.setMolecule(molecule, true);
        final int idCodes[] = idCodeGenerator.getIDCodes();
        final List<String> hoseCodes = new ArrayList<>(idCodes.length);
        for (final int idCode : idCodes) {
            hoseCodes.add(IDCodeParserTool.parse(idCode));
        }

        //Assign types
        final SSSRFinder sssrFinder = new SSSRFinder(molecule);
        sssrFinder.setRingSet(sssrFinder.findSSSR());
        final Set<SSSRing> sssr = sssrFinder.getSSSR();
        for (IAtom atom : molecule.atoms()) {
            if (atom.getFlag(CDKConstants.VISITED)) continue;

            final boolean aromatic = atom.getFlag(CDKConstants.ISAROMATIC);
            final String hose = hoseCodes.get(atom.getID() - 1);
            final int hCount = atom.getImplicitHydrogenCount();
            final int charge = atom.getFormalCharge();
            final boolean isotope = atom.getMassNumber() != null;

            final AtomType type = AromaticityLabeler.annotateSSSR(atom, molecule, sssr, aromatic, hose, hCount, charge, isotope);
            if (type != null) AtomTypeManipulator.configure(atom, type);
        }

        return sssr;

    } catch (final CDKException e) {
        throw new CDKException("Problems detecting aromaticity or making hose codes.", e);
    }
}
