public static void removeColumns(Table table, String... columnsToKeep) {
    List<String> columnsToKeepList = Arrays.asList(columnsToKeep);
    for (Iterator<String> iterator = table.getColumns().iterator(); iterator.hasNext();) {
        String column = iterator.next();
        if (!columnsToKeepList.contains(column)) {
            table.removeColumn(column);
        }
    }
}
