public Basic2DMatrix parseMatrixMarket(InputStream is) throws IOException {
    BufferedReader reader = new BufferedReader(new InputStreamReader(is));
    String line;
    int rows = 0;
    int columns = 0;
    int elements = 0;

    while ((line = reader.readLine()) != null) {
        if (line.startsWith("%")) {
            continue;
        }

        String[] parts = line.split(" ");
        rows = Integer.parseInt(parts[0]);
        columns = Integer.parseInt(parts[1]);
        elements = Integer.parseInt(parts[2]);
        break;
    }

    double[][] data = new double[rows][columns];
    int row = 0;
    int column = 0;

    while ((line = reader.readLine()) != null) {
        if (line.startsWith("%")) {
            continue;
        }

        String[] parts = line.split(" ");
        int rowIndex = Integer.parseInt(parts[0]) - 1;
        int columnIndex = Integer.parseInt(parts[1]) - 1;
        double value = Double.parseDouble(parts[2]);
        data[rowIndex][columnIndex] = value;

        if (++column == columns) {
            column = 0;
            row++;
        }

        if (row == rows) {
            break;
        }
    }

    return new Basic2DMatrix(data);
}
