public boolean compareXMLDeclaration(String xml1, String xml2){
    String regex = ".*<\\?xml.*?\\?>.*";
    String declaration1 = "";
    String declaration2 = "";

    Pattern pattern = Pattern.compile(regex);
    Matcher matcher1 = pattern.matcher(xml1);
    Matcher matcher2 = pattern.matcher(xml2);

    if(matcher1.find()){
        declaration1 = matcher1.group();
    }

    if(matcher2.find()){
        declaration2 = matcher2.group();
    }

    return declaration1.equals(declaration2);
}
