public void clickAndWaitFor(Object expected) {
    WebElement element = null;
    WebDriver driver = ((RemoteWebDriver) getDriver()).getWrappedDriver();

    if (expected instanceof String) {
        element = new WebDriverWait(driver, 10).until(ExpectedConditions.elementToBeClickable(By.xpath((String) expected)));
    } else if (expected instanceof WebPage) {
        element = ((WebPage) expected).getListContainer();
    } else if (expected instanceof AbstractElement) {
        element = ((AbstractElement) expected).getWebElement();
    } else if (expected instanceof ExpectedCondition<?>) {
        element = new WebDriverWait(driver, 10).until((ExpectedCondition<WebElement>) expected);
    } else {
        throw new IllegalArgumentException("Invalid parameter type");
    }

    element.click();
    new WebDriverWait(driver, 10).until(ExpectedConditions.stalenessOf(element));
}
