public Object deserializePrimitiveAsObject(Object fieldValue, Class<?> targetType, ObjectMapper objectMapper) throws JsonParseException, JsonMappingException, IOException {
    if (fieldValue == null) {
        return null;
    }

    Object wrappedValue = null;
    try {
        // Try to deserialize the primitive as the target type
        wrappedValue = objectMapper.readValue(fieldValue.toString(), targetType);
    } catch (Exception ex) {
        // Ignore this exception
    }

    // If deserialization failed, try again after wrapping as an object property
    if (wrappedValue == null) {
        Map<String, Object> propertyMap = new HashMap<>();
        propertyMap.put("value", fieldValue);
        wrappedValue = objectMapper.convertValue(propertyMap, targetType);
    }

    return wrappedValue;
}
