public static void fillRoundedRect(Graphics2D g2, int x, int y, int width, int height, int cornerRadius, int segs) {
    if (width < 0) {
        x += width;
        width = -width;
    }

    if (height < 0) {
        y += height;
        height = -height;
    }

    if (segs < 1) {
        segs = 1;
    }
    int d = cornerRadius * 2;
    if ((width <= d) || (height <= d)) {
        g2.fillRoundRect(x, y, width, height, cornerRadius, cornerRadius);
        return;
    }
    GraphicsPath gp = new GraphicsPath();

    gp.moveTo(x, y + cornerRadius);
    gp.quadTo(x, y, x + cornerRadius, y);
    gp.lineTo(x + width - cornerRadius, y);
    gp.quadTo(x + width, y, x + width, y + cornerRadius);
    gp.lineTo(x + width, y + height - cornerRadius);
    gp.quadTo(x + width, y + height, x + width - cornerRadius, y + height);
    gp.lineTo(x + cornerRadius, y + height);
    gp.quadTo(x, y + height, x, y + height - cornerRadius);
    gp.closePath();

    double seg = Math.PI / 2 / segs;
    double theta = seg;
    double t = Math.tan(seg);
    int x1 = cornerRadius;
    int y1 = 0;

    for (int i = 0; i < segs; i++) {
        int x2 = (int) (cornerRadius * Math.cos(theta));
        int y2 = (int) (cornerRadius * Math.sin(theta));
        int tx = (int) ((cornerRadius + (y2 - y1) * t) / t);
        int ty = (y2 - y1) * tx / (x2 - x1);
        gp.lineTo(x + cornerRadius + tx, y + cornerRadius - ty);
        theta += seg;
        x1 = x2;
        y1 = y2;
    }
    gp.lineTo(x + width - cornerRadius, y);
    gp.closePath();

    g2.fill(gp);

}
