public boolean findIincAndGoto(Method method) {
    boolean hasIincAndGoto = false;
    for (AbstractInsnNode instruction : method.instructions) {
        if (instruction.getOpcode() == Opcodes.IINC && instruction.getNext() != null
                && (instruction.getNext().getOpcode() == Opcodes.GOTO || instruction.getNext().getOpcode() == Opcodes.GOTO_W)) {
            hasIincAndGoto = true;
            break;
        }
    }
    return hasIincAndGoto;
}
