public List<HString> split(Predicate<HString> delimiterPredicate) {
    List<HString> splitHStrings = new ArrayList<>();
    int start = 0;
    for (int end = 0; end < this.length(); end++) {
        if (delimiterPredicate.test(this.substring(start, end + 1))) {
            if (start != end) { // Avoid adding empty tokens
                splitHStrings.add(this.substring(start, end));
            }
            start = end + 1;
        }
    }
    if (start != this.length()) { // Add the last token
        splitHStrings.add(this.substring(start));
    }
    return splitHStrings;
}
