    Hashtable<String, List<String>> hashtable = new Hashtable<>();
    for (String configuration : configurations) {
        List<String> targetsToRebuild = new ArrayList<>();
        for (String target : targets) {
            if (targetNeedsToBeRebuilt(target, configuration)) {
                targetsToRebuild.add(target);
            }
        }
        hashtable.put(configuration, targetsToRebuild);
    }
    return hashtable;
}

