@Deprecated
public static Attachment fromNonBinaryFile(File file, MediaType mediaType) throws IOException {
    if (mediaType == null) {
        mediaType = MediaType.APPLICATION_OCTET_STREAM;
    }
    if (mediaType.isBinary()) {
        throw new IllegalArgumentException("Media type cannot be binary");
    }
    FileInputStream inputStream = new FileInputStream(file);
    InputStreamReader inputStreamReader = new InputStreamReader(inputStream);
    BufferedReader bufferedReader = new BufferedReader(inputStreamReader);
    StringBuilder stringBuilder = new StringBuilder();
    String line;
    while ((line = bufferedReader.readLine()) != null) {
        stringBuilder.append(line).append("\n");
    }
    bufferedReader.close();
    inputStreamReader.close();
    inputStream.close();
    String content = stringBuilder.toString();
    return new Attachment(content.getBytes(mediaType.getCharSet()), mediaType);
}
