public List<NsSslCertKey> getFilteredSslCertKeys(String filter) {

    // parse filter string from JSON format
    Map<String, String> filterMap = new HashMap<>();
    try {
        JsonObject jsonObject = new JsonParser().parse(filter).getAsJsonObject();
        for (Map.Entry<String, JsonElement> entry : jsonObject.entrySet()) {
            filterMap.put(entry.getKey(), entry.getValue().getAsString());
        }
    } catch (JsonSyntaxException e) {
        // handle exception if the filter string is not in JSON format
        throw new IllegalArgumentException("Filter string should be in JSON format.");
    }

    // query the database and filter the results
    List<NsSslCertKey> sslCertKeys = queryDatabaseForSslCertKeys();
    List<NsSslCertKey> filteredSslCertKeys = sslCertKeys.stream()
            .filter(key -> {
                for (Map.Entry<String, String> entry : filterMap.entrySet()) {
                    String value = entry.getValue();
                    if (value.startsWith("[") && value.endsWith("]")) {
                        // handle filter with regex pattern
                        String pattern = value.substring(1, value.length() - 1);
                        if (!key.get(entry.getKey()).matches(pattern)) {
                            return false;
                        }
                    } else {
                        // handle filter with exact value
                        if (!key.get(entry.getKey()).equals(entry.getValue())) {
                            return false;
                        }
                    }
                }
                return true;
            })
            .collect(Collectors.toList());

    return filteredSslCertKeys;
}
