public List<String> fetchTickerSymbolEntities(String text) {
   List<String> tickerSymbols = new ArrayList<>();

   // Regular expression to find ticker symbols
   Pattern pattern = Pattern.compile("\\$[A-Z]+");
   Matcher matcher = pattern.matcher(text);

   // Loop through all matches and add to list
   while (matcher.find()) {
      tickerSymbols.add(matcher.group());
   }

   return tickerSymbols;
}
