public void addNotificationHandler(String serviceName, NotificationHandler handler) {
    if (notificationHandlers.containsKey(serviceName)) {
        List<NotificationHandler> handlers = notificationHandlers.get(serviceName);
        if (!handlers.contains(handler)) {
            handlers.add(handler);
        }
    } else {
        List<NotificationHandler> handlers = new ArrayList<>();
        handlers.add(handler);
        notificationHandlers.put(serviceName, handlers);
    }
}
