public Classifier trainClassifier(Reference<Collection<Datum>> ref) {
    // Create a new instance of the classifier
    Classifier classifier = new Classifier();

    // Train the classifier on the collection of Datum
    Collection<Datum> data = ref.get();
    for (Datum datum : data) {
        classifier.train(datum);
    }

    // Return the trained classifier
    return classifier;
}
