public void closeConnectionThenReply(Response response, boolean error, String errorMessage, String stackTrace, String statusCode, int statusCodeInt){
    // close the connection
    closeConnection();

    // prepare the response
    if(error){
        response.setStatusCode(statusCodeInt);
        response.setBody(errorMessage + "\n" + stackTrace);
    } else {
        response.setStatusCode(statusCodeInt);
        response.setBody(statusCode);
    }

    // send the response
    sendResponse(response);
}
