import java.util.HashMap;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;

public static List<Class<?>> getAllSubinterfaces(Class<?> interf, Map<Class<?>, List<Class<?>>> map) {
    List<Class<?>> result = new LinkedList<>();
    for (Class<?> subInterf : interf.getInterfaces()) {
        result.add(subInterf);
        List<Class<?>> subSubInterfaces = getAllSubinterfaces(subInterf, map);
        result.addAll(subSubInterfaces);
        List<Class<?>> subClasses = map.getOrDefault(subInterf, new LinkedList<>());
        subClasses.add(interf);
        map.put(subInterf, subClasses);
    }
    return result;
}
