public List<String> getAllDexPaths() throws PackageManager.NameNotFoundException, IOException {
    List<String> dexPaths = new ArrayList<>();
    // Get the app package name
    String packageName = getContext().getPackageName();
    // Get the application info
    ApplicationInfo applicationInfo = getContext().getPackageManager().getApplicationInfo(packageName, 0);
    // Get the source dir and add it to the dexPaths list
    String appSourceDir = applicationInfo.sourceDir;
    dexPaths.add(appSourceDir);
    // Get the instant-run folder and add its contents to the dexPaths list
    File instantRunDir = new File(appSourceDir + "/../instant-run");
    if (instantRunDir.isDirectory()) {
        File[] files = instantRunDir.listFiles();
        for (File file : files) {
            if (file.isFile() && file.getAbsolutePath().endsWith(".dex")) {
                dexPaths.add(file.getAbsolutePath());
            }
        }
    }
    return dexPaths;
}
