/**
  * Rotates the given quaternion to the direction vector defined by the two given vectors.
  *
  * @param from the starting vector
  * @param to the destination vector
  * @param dest will hold the result
  * @return dest
  */
public Quaternionf rotateTo(Vector3fc from, Vector3fc to, Quaternionf dest) {
    float angle = from.angle(to);
    if (angle < 1e-6f) {
        return dest;
    }

    Vector3f axis = new Vector3f();
    from.cross(to, axis);
    axis.normalize();

    float cos = (float) Math.cos(angle * 0.5);
    float sin = (float) Math.sin(angle * 0.5);

    dest.set(axis.x() * sin, axis.y() * sin, axis.z() * sin, cos).normalize();
    return dest;
}
