public void attachLightToBody(Body body, double degrees) {
   // Check if the body and degrees parameters are not null
   if (body == null || degrees == null) {
      throw new IllegalArgumentException("The body and degrees parameters cannot be null");
   }

   // Calculate the offset in radians, taking into account the body's rotation angle
   double radiansOffset = Math.toRadians(degrees) + body.getRotationAngle();

   // Use the offset to set the light's position and direction
   Light light = new Light();
   light.setPosition(body.getPosition().add(Vector2D.fromPolar(radiansOffset, light.getDistance())));
   light.setDirection(Vector2D.fromPolar(radiansOffset, 1));
}
