        distributedObject = new DistributedObject(name);
        if (publishEvent) {
            DistributedObjectEvent event = new DistributedObjectEvent(distributedObject);
            eventManager.publish(event);
        }
        if (initialize) {
            distributedObject.initialize();
        }
        DistributedObjects.put(name, distributedObject);
        return distributedObject;
    }
    return null;
}
