public boolean isMethodCallWithNumArgs(String expression, String methodName, int numArguments) {
    if (expression.startsWith(methodName + "(") && expression.endsWith(")")) {
        String args = expression.substring(methodName.length() + 1, expression.length() - 1);
        String[] arguments = args.split(",");
        return arguments.length == numArguments;
    }
    return false;
}
