public static <T, U, R, E extends Throwable> BiFunction<T, U, R> rethrowFunction(
        ThrowingBiFunction<T, U, R, E> function) {
    return (t, u) -> {
        try {
            return function.apply(t, u);
        } catch (Throwable e) {
            throwAsUnchecked(e);
            return null; // unreachable code
        }
    };
}

@SuppressWarnings("unchecked")
private static <E extends Throwable> void throwAsUnchecked(Throwable exception) throws E {
    throw (E) exception; // rely on vacuous cast
}

@FunctionalInterface
public interface ThrowingBiFunction<T, U, R, E extends Throwable> {
    R apply(T t, U u) throws E;
}
