public static double[] convertLogProbabilities(double[] a) {
    double[] result = new double[a.length];
    double max = a[0];

    for (double value : a) {
        if (value > max) {
            max = value;
        }
    }

    double sum = 0.0;
    for (int i = 0; i < a.length; i++) {
        result[i] = Math.exp(a[i] - max);
        sum += result[i];
    }

    for (int i = 0; i < result.length; i++) {
        result[i] /= sum;
    }

    return result;
}
