public Rectangle2D calculateDiagramBounds(Rectangle2D modelBounds, double currentScale, double zoom, double margin) {
    double screenWidth = currentScale * zoom;
    double screenHeight = currentScale * zoom;

    double screenX = (modelBounds.getX() * currentScale * zoom) - margin;
    double screenY = (modelBounds.getY() * currentScale * zoom) - margin;
    double screenW = (modelBounds.getWidth() * currentScale * zoom) + (2 * margin);
    double screenH = (modelBounds.getHeight() * currentScale * zoom) + (2 * margin);

    return new Rectangle2D.Double(screenX, screenY, screenW, screenH);
}
