public Collection<Variable> searchAliasedCoord(Dataset ds, String dim) {
    List<Variable> result = new ArrayList<>();

    Variable var = ds.findVariable(dim);
    if (var != null) {
        result.add(var);
    } else {
        String[] aliases = ds.getDimensionAliases(dim);
        if (aliases != null) {
            for (String alias : aliases) {
                var = ds.findVariable(alias);
                if (var != null) {
                    result.add(var);
                }
            }
        }
    }

    return result.isEmpty() ? null : result;
}
