public List<String> sliceToList(int start, int end) {
    List<String> list = new ArrayList<>();
    for (int i = start; i < end; i++) {
        if (i < 0 || i >= this.length) {
            list.add(null);
        } else {
            list.add(String.valueOf(this.charAt(i)));
        }
    }
    return list;
}
