public void shiftBitmapPattern(Point origin) {
    int multiple = bitmapPattern.length / gcd(bitmapPattern.length, origin.x);
    int shift = origin.x % multiple;
    int[] shiftedPattern = new int[bitmapPattern.length];

    for (int i = 0; i < bitmapPattern.length; i++) {
        shiftedPattern[(i + shift) % bitmapPattern.length] = bitmapPattern[i];
    }
    bitmapPattern = shiftedPattern;
}

private int gcd(int a, int b) {
    if (b == 0) {
        return a;
    }
    return gcd(b, a % b);
}
