public void drawCatalogReportPage() {
    // Assuming the catalog report page is stored in the project's JAR as a resource
    InputStream inputStream = getClass().getResourceAsStream("/path/to/catalogreportpage.html"); 

    // Read the content of the HTML file as a string
    String htmlContent = null;
    try (BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(inputStream))) {
        htmlContent = bufferedReader.lines().collect(Collectors.joining("\n"));
    } catch (IOException e) {
        e.printStackTrace();
    }

    // Use a Swing component to display the HTML content in a dialog
    JEditorPane editorPane = new JEditorPane();
    editorPane.setContentType("text/html");
    editorPane.setText(htmlContent);
    JScrollPane scrollPane = new JScrollPane(editorPane);
    JOptionPane.showMessageDialog(null, scrollPane, "Catalog Report Page", JOptionPane.PLAIN_MESSAGE);
}
