public boolean dropSpareWorkerIfExists(Callable<Void> w) {
    if (w instanceof ForkJoinPool.WorkQueue) {
        ForkJoinPool.WorkQueue workQueue = (ForkJoinPool.WorkQueue) w;
        if (workQueue.qlock < 0) return false; 
        workQueue.qlock = -1;
        int qc = workQueue.queueSize();
        if (qc <= 1 && ctl.tryDecrementWorkerCount(workQueue)) {
            workQueue.transferStealCount(ctl);
            return true;
        }
        workQueue.qlock = 0; 
    }
    return false;
}
