public static Class<?> getTypeArgument(final Type genericType) {
    if (genericType instanceof ParameterizedType) {
        final Type[] argTypes = ((ParameterizedType) genericType).getActualTypeArguments();
        if (argTypes != null && argTypes.length > 0) {
            final Type argType = argTypes[0];
            if (argType instanceof Class) {
                return (Class<?>) argType;
            } else if (argType instanceof ParameterizedType) {
                return (Class<?>) ((ParameterizedType) argType).getRawType();
            }
        }
    }
    return null;
}
