import java.lang.reflect.Method;
import java.util.HashMap;
import java.util.Map;

public class GetterExtractor {

    public static Map<String, Method> extractGetters(Class<?> type) {
        Map<String, Method> propertyToGetterMap = new HashMap<>();
        Method[] methods = type.getMethods();
        for (Method method : methods) {
            if (isGetter(method)) {
                String propertyName = getPropertyNameFromGetter(method);
                propertyToGetterMap.put(propertyName, method);
            }
        }
        return propertyToGetterMap;
    }

    public static boolean isGetter(Method method) {
        return method.getName().startsWith("get") &&
                method.getParameterCount() == 0 &&
                !void.class.equals(method.getReturnType());
    }

    public static String getPropertyNameFromGetter(Method getter) {
        String methodName = getter.getName();
        return methodName.substring(3, 4).toLowerCase() + methodName.substring(4);
    }
}
