public void buildRegex(Node alt, StringBuffer sb) {
    if (alt.children.isEmpty()) {
        sb.append(alt.symbol);
        return;
    }
    sb.append("(");
    boolean first = true;
    for (Node child : alt.children) {
        if (!first) {
            sb.append("|");
        } else {
            first = false;
        }
        buildRegex(child, sb);
    }
    sb.append(")");
}
