public static int findIntersection(double x1, double y1, double x2, double y2, double x3, double y3,
                                    double qx1, double qy1, double qx2, double qy2, double qx3, double qy3,
                                    double[] params) {
    double a1 = y2 - y1;
    double b1 = x1 - x2;
    double c1 = x2*y1 - x1*y2;

    double a2 = qy2 - qy1;
    double b2 = qx1 - qx2;
    double c2 = qx2*qy1 - qx1*qy2;

    double det = a1*b2 - a2*b1;

    if (det == 0) {
        return 0;
    }

    double x = (b1*c2 - b2*c1)/det; 
    double y = (a2*c1 - a1*c2)/det;

    if ((Math.min(x1, x2) <= x && x <= Math.max(x1, x2)) &&
            (Math.min(y1, y2) <= y && y <= Math.max(y1, y2)) &&
            (Math.min(qx1, qx2) <= x && x <= Math.max(qx1, qx2)) &&
            (Math.min(qy1, qy2) <= y && y <= Math.max(qy1, qy2))) {
        params[0] = x;
        params[1] = y;

        double dxc = x - x3;
        double dyc = y - y3;
        double dxq = x - qx3;
        double dyq = y - qy3;

        if (dxc*dxc + dyc*dyc < dxq*dxq + dyq*dyq) {
            return 1;
        }
        else {
            return 2;
        }
    }
    return 0;
}
