public double computePosition(double[] path, double elapsed, double duration) {
    double position = 0;
    double distance = 0;
    for (int i = 0; i < path.length - 1; i++) {
        distance += Math.abs(path[i + 1] - path[i]);
    }
    double speed = distance / duration;
    double elapsedFraction = elapsed / duration;
    double elapsedDistance = elapsedFraction * distance;
    double remainingDistance = distance - elapsedDistance;
    for (int i = 0; i < path.length - 1; i++) {
        double segmentDistance = Math.abs(path[i + 1] - path[i]);
        if (elapsedDistance < segmentDistance) {
            double segmentFraction = elapsedDistance / segmentDistance;
            double segmentPosition = path[i] + (path[i + 1] - path[i]) * segmentFraction;
            position = segmentPosition + remainingDistance * (path[i + 1] > path[i] ? 1 : -1);
            break;
        } else {
            elapsedDistance -= segmentDistance;
        }
    }
    return position;
}
