public List<String> adaptOutput(List<String> xreadExpressions) {
    List<String> adaptedOutput = new ArrayList<>();

    for (String expr : xreadExpressions) {
        String[] parts = expr.split("\\s+");
        if (parts.length >= 3 && parts[2].startsWith("as")) {
            adaptedOutput.add(parts[2].substring(3));
        } else {
            adaptedOutput.add(expr);
        }
    }

    return adaptedOutput;
}
