        dataOut.writeUTF(hdfsStats.getHostname());
        dataOut.writeInt(hdfsStats.getPort());
        dataOut.writeUTF(hdfsStats.getSource());

        // Convert the output stream to byte array and return it
        return out.toByteArray();
    } catch (IOException e) {
        // Handle the IOException
        e.printStackTrace();
        return null;
    }
}
