public Element getOrCreateTableRow(Element parentElement, int index) {
    NodeList trList = parentElement.getElementsByTagName("tr");
    Element tr;

    if (trList.getLength() > index) {
        tr = (Element)trList.item(index);
    } else {
        while (trList.getLength() <= index) {
            tr = parentElement.getOwnerDocument().createElement("tr");
            parentElement.appendChild(tr);
            trList = parentElement.getElementsByTagName("tr");
        }
        tr = (Element)trList.item(index);
    }
    return tr;
}
