public SSLConfig[] loadSSLConfigFromURL(String propertiesURL, String multiConfigURL) {
    Properties props = new Properties();
    try {
        props.load(new URL(propertiesURL).openStream());
    } catch (IOException e) {
        e.printStackTrace();
    }
    String[] configURLs = multiConfigURL.split(",");
    SSLConfig[] sslConfigs = new SSLConfig[configURLs.length];
    for (int i = 0; i < configURLs.length; i++) {
        URL url;
        try {
            url = new URL(configURLs[i]);
            sslConfigs[i] = new SSLConfig(url, props);
        } catch (MalformedURLException e) {
            e.printStackTrace();
        }
    }
    return sslConfigs;
}
