public void addExtraParameters(ModelAndView model, HttpServletRequest request) {
   Enumeration<String> parameterNames = request.getParameterNames();
   while (parameterNames.hasMoreElements()) {
      String paramName = parameterNames.nextElement();
      String paramValue = request.getParameter(paramName);
      if (paramName != null && !paramName.isEmpty()) {
         switch (paramName.charAt(0)) {
            case 'i':
               model.addObject(paramName, Integer.parseInt(paramValue));
               break;
            case 'b':
               model.addObject(paramName, Boolean.parseBoolean(paramValue));
               break;
            case 'd':
               model.addObject(paramName, Double.parseDouble(paramValue));
               break;
            default:
               model.addObject(paramName, paramValue);
         }
      }
   }
}
