// This is an example implementation of the described function

public void executeFirst(List<Runnable> tasks) {
    List<Runnable> observerTasks = new ArrayList<>();
    List<Runnable> interceptorTasks = new ArrayList<>();
    List<Runnable> decoratorTasks = new ArrayList<>();
    List<Runnable> otherTasks = new ArrayList<>();

    // Divide the tasks into different categories
    for (Runnable task : tasks) {
        if (task instanceof ObserverTask) {
            observerTasks.add(task);
        } else if (task instanceof InterceptorTask) {
            interceptorTasks.add(task);
        } else if (task instanceof DecoratorTask) {
            decoratorTasks.add(task);
        } else {
            otherTasks.add(task);
        }
    }

    // Execute the tasks in the order of observers, interceptors, decorators, and others
    for (Runnable task : observerTasks) {
        task.run();
    }

    for (Runnable task : interceptorTasks) {
        task.run();
    }

    for (Runnable task : decoratorTasks) {
        task.run();
    }

    for (Runnable task : otherTasks) {
        task.run();
    }
}

