    }
}

class DecoratorTaskImpl implements DecoratorTask {
    public void run() {
        System.out.println("DecoratorTaskImpl executed");
    }
}

class OtherTaskImpl implements Runnable {
    public void run() {
        System.out.println("OtherTaskImpl executed");
    }
