public class OnlineRegression {
   private double[] coeffs;
   private double learningRate;

   public OnlineRegression(int numCoeffs, double learningRate) {
       coeffs = new double[numCoeffs];
       this.learningRate = learningRate;
   }

   public void learnInstance(double[] x, double y) {
       double prediction = predict(x);
       double error = y - prediction;
       for (int i = 0; i < coeffs.length; i++) {
           coeffs[i] += learningRate * error * x[i];
       }
   }

   private double predict(double[] x) {
       double prediction = 0.0;
       for (int i = 0; i < coeffs.length; i++) {
           prediction += coeffs[i] * x[i];
       }
       return prediction;
   }
}
