public class Line {

    private Point startPoint;
    private Point endPoint;

    public Line(Point p1, Point p2) {
        startPoint = p1;
        endPoint = p2;
    }

    public int lineVsLine(Line l2) {
        //get coordinates of the start and end points of line 1
        int x1 = startPoint.getX();
        int y1 = startPoint.getY();
        int x2 = endPoint.getX();
        int y2 = endPoint.getY();

        //get coordinates of the start and end points of line 2
        int x3 = l2.startPoint.getX();
        int y3 = l2.startPoint.getY();
        int x4 = l2.endPoint.getX();
        int y4 = l2.endPoint.getY();

        //calculate dx and dy for both lines
        int dx1 = x2 - x1;
        int dy1 = y2 - y1;
        int dx2 = x4 - x3;
        int dy2 = y4 - y3;

        //calculate determinants
        int det1 = dx1 * dy2 - dx2 * dy1;
        int det2 = (x3 - x1) * dy2 - dx2 * (y3 - y1);
        int det3 = (x4 - x2) * (y3 - y1) - (x3 - x1) * (y4 - y2);

        //check the relational predicates
        if (det1 > 0 || det1 < 0) {
            if (det2 == 0 || det3 == 0) {
                return 1; //intersecting
            } else if (det2 < 0 && det3 < 0) {
                return 2; //disjoint and parallel
            } else {
                return 3; //intersecting
            }
        } else {
            if ((x1 > x3 && x1 > x4 && x2 > x3 && x2 > x4) || (y1 > y3 && y1 > y4 && y2 > y3 && y2 > y4) ||
                    (x1 < x3 && x1 < x4 && x2 < x3 && x2 < x4) || (y1 < y3 && y1 < y4 && y2 < y3 && y2 < y4)) {
                return 4; //disjoint and not parallel
            } else if (dx1 * dx2 < 0 || dy1 * dy2 < 0) {
                return 5; //intersecting
            } else if (dx1 * dx1 + dy1 * dy1 < dx2 * dx2 + dy2 * dy2) {
                return 6; //intersecting
            } else if (dx2 * dx2 + dy2 * dy2 < dx1 * dx1 + dy1 * dy1) {
                return 7; //intersecting
            } else {
                return 8; //overlapping
            }
        }
    }
}
