import java.io.File;
import java.io.IOException;
import org.apache.commons.io.FileUtils;
import org.json.JSONArray;
import org.json.JSONException;
import org.json.JSONObject;
import org.json.JSONTokener;

public class JsonUtility {

    public static Object createJsonFromFile(String path) throws JSONException {
        try {
            String fileContent = FileUtils.readFileToString(new File(path), "UTF-8");
            if (fileContent.trim().startsWith("{")) {
                return new JSONObject(new JSONTokener(fileContent));
            } else {
                return new JSONArray(new JSONTokener(fileContent));
            }
        } catch (IOException e) {
            throw new JSONException("Error reading file " + path, e);
        } catch (JSONException e) {
            throw new JSONException("Error converting XML to JSON for file " + path, e);
        }
    }
}
