public void checkForTreeComparators(ClassContext classContext) {
    boolean found = false;
    for (MethodNode method : classContext.methods) {
        for (AbstractInsnNode instruction : method.instructions) {
            if (instruction.getOpcode() == INVOKESTATIC) {
                MethodInsnNode invoke = (MethodInsnNode) instruction;
                if (invoke.owner.equals("java/util/Comparator") && invoke.name.equals("comparing") && invoke.desc.equals("(Ljava/util/function/Function;)Ljava/util/Comparator;")) {
                    found = true;
                    break;
                }
            }
        }
        if (found) {
            break;
        }
    }
    if (!found) {
        BugReporter.reportBug("No Tree comparators were found in " + classContext.className);
    }
}
