public void setArguments(List<BELObject> args) throws UnsupportedOperationException {
    if (args == null) {
        this.arguments = null;
        this.terms = null;
        this.parameters = null;
        return;
    }

    List<Term> terms = new ArrayList<>();
    List<Parameter> parameters = new ArrayList<>();

    for (BELObject arg : args) {
        if (arg instanceof Term) {
            terms.add((Term) arg);
        } else if (arg instanceof Parameter) {
            parameters.add((Parameter) arg);
        } else {
            throw new UnsupportedOperationException("Invalid argument: " + arg.getClass().getSimpleName());
        }
    }

    this.arguments = args;
    this.terms = terms;
    this.parameters = parameters;
}
