public double convertMediaTimeToEditedTime(Track trak, double mediaTv, int movieTimescale) {
    if (trak == null) {
        throw new IllegalArgumentException("Track cannot be null");
    }
    if (mediaTv < 0 || mediaTv > trak.getTrackMetaData().getDuration()) {
        throw new IllegalArgumentException("Invalid media timevalue: " + mediaTv);
    }
    if (movieTimescale <= 0) {
        throw new IllegalArgumentException("Invalid movie timescale: " + movieTimescale);
    }
    double editedTv = ((mediaTv / trak.getTrackMetaData().getTimescale()) * movieTimescale);
    return editedTv;
}
