        for(int i = 0; i < this.getWidth(); i++) {
            for(int j = 0; j < this.getHeight(); j++) {
                Color color = this.getPixel(i, j);
                float[] channels = color.getColorComponents(null);
                for(int k = 0; k < channels.length; k++) {
                    channels[k] = Math.max(0, Math.min(channels[k], 1));
                }
                color = new Color(channels[0], channels[1], channels[2], channels.length > 3 ? channels[3] : 1);
                this.setPixel(i, j, color);
            }
        }
        return this;
    }

