public boolean isClassUsable(Settings settings, Class<?> aClass) {
    boolean isUsable = true;

    // Check if the class is excluded in Fathom settings
    if (settings.getExcludedClasses().contains(aClass.getName())) {
        isUsable = false;
    }

    // Check if the runtime mode is not in the excluded modes
    if (settings.getExcludedRuntimeModes().contains(settings.getRuntimeMode())) {
        isUsable = false;
    }

    return isUsable;
}
