import java.io.*;
import java.util.*;
import java.util.zip.*;

public void copyZipAndAppendEntries(File zip, List<ZipEntry> entries, OutputStream destOut) throws IOException {
    byte[] buffer = new byte[1024];
    ZipInputStream zis = new ZipInputStream(new FileInputStream(zip));
    ZipOutputStream zos = new ZipOutputStream(destOut);
    ZipEntry entry = zis.getNextEntry();
    while (entry != null) {
        zos.putNextEntry(entry);
        int len;
        while ((len = zis.read(buffer)) > 0) {
            zos.write(buffer, 0, len);
        }
        zos.closeEntry();
        entry = zis.getNextEntry();
    }
    zis.close();
    for (ZipEntry newEntry : entries) {
        zos.putNextEntry(newEntry);
        InputStream in = new ByteArrayInputStream(newEntry.getExtra());
        int len;
        while ((len = in.read(buffer)) > 0) {
            zos.write(buffer, 0, len);
        }
        zos.closeEntry();
    }
    zos.close();
}
