public Object getUIDefaultForProperty(Class<?> clazz, String property) {
    if (clazz == null || property == null) {
        return null;
    }

    UIDefaults uiDefaults = UIManager.getLookAndFeelDefaults();
    if (uiDefaults.containsKey(property)) {
        return uiDefaults.get(property);
    }

    Class<?> currentClass = clazz;
    while (currentClass != null) {
        uiDefaults = UIManager.getDefaults();
        if (uiDefaults.get(currentClass.getName() + "." + property) != null) {
            return uiDefaults.get(currentClass.getName() + "." + property);
        }
        currentClass = currentClass.getSuperclass();
    }

    return null;
}
