public void disableWidgetsUntilAsyncComplete(Object[] widgets, Runnable callback) {
    for (Object widget : widgets) {
        widget.setEnabled(false);
    }

    new Thread(() -> {
        try {
            callback.run();
        } finally {
            for (Object widget : widgets) {
                widget.setEnabled(true);
            }
        }
    }).start();
}
