public Element setupCanvasElement(Element svgp, Projection proj, Margin margin, int width, int height) {
  Element wrapper = new Element("g", svgp.getDocument());

  int x = margin.left;
  int y = margin.top;
  int w = width - margin.right - margin.left;
  int h = height - margin.bottom - margin.top;

  String viewBox = String.format("%d %d %d %d", x, y, w, h);

  wrapper.setAttribute("transform", String.format("translate(%d,%d)", margin.left, margin.top));
  wrapper.setAttribute("viewBox", viewBox);

  return wrapper;
}
