public static String getNextOuterXMLToken(String sourceText) throws JSONException{
    int startIndex = 0;
    int endIndex = 0;
    String token = null;
    int length = sourceText.length();
    while (endIndex < length) {
        char c = sourceText.charAt(endIndex);
        if (c == '<') {
            if (endIndex > startIndex) {
                token = sourceText.substring(startIndex, endIndex).trim();
                return token;
            }
            token = Character.toString(c);
            return token;
        } else if (c == '>') {
            token = sourceText.substring(startIndex, endIndex + 1);
            return token;
        }
        endIndex += 1;
    }
    if (endIndex > startIndex) {
        token = sourceText.substring(startIndex).trim();
        return token;
    }
    return null;
}
