public ClusterMember determineClusterMember(List<ClusterMember> clusterMembers, String memberId, List<String> memberEndpoints) {
    if (clusterMembers == null || clusterMembers.isEmpty()) {
        return new ClusterMember(memberId, memberEndpoints);
    } else {
        for (ClusterMember member : clusterMembers) {
            if (memberId.equals(member.getMemberId())) {
                if (memberEndpoints.equals(member.getMemberEndpoints())) {
                    return member;
                } else {
                    member.setMemberEndpoints(memberEndpoints);
                    return member;
                }
            }
        }
        // No matching cluster member found, so create a new one.
        return new ClusterMember(memberId, memberEndpoints);
    }
}
