public List<Template> extractTemplates(List<Page> pages, List<Revision> revisions) {
    List<Template> templates = new ArrayList<>();

    for (Page page : pages) {
        for (Revision revision : revisions) {
            if (revision.getPageId() == page.getId()) {
                String pageContent = revision.getContent();

                // use regex to extract templates from page content
                Pattern templatePattern = Pattern.compile("\\{\\{([^\\}]+)\\}\\}");
                Matcher templateMatcher = templatePattern.matcher(pageContent);
                while (templateMatcher.find()) {
                    String templateName = templateMatcher.group(1);
                    Template template = new Template(templateName, page.getTitle());
                    templates.add(template);
                }
            }
        }
    }

    return templates;
}
