public class ProcessLoginConfig {
  public void processLoginConfig() {
    LoginConfig config = ProcessLoginConfig.class.getAnnotation(LoginConfig.class);
    if (config == null) {
      return;
    }

    String authMethod = config.authMethod();
    String realmName = config.realmName();
    String loginPage = config.loginPage();
    String errorPage = config.errorPage();

    Map<String, String> properties = new HashMap<String, String>();
    properties.put("authMethod", authMethod);
    properties.put("realmName", realmName);
    properties.put("loginPage", loginPage);
    properties.put("errorPage", errorPage);

    AuthConfigFactory factory = AuthConfigFactory.getFactory();
    factory.registerConfig("myLoginConfig", properties, new DummyAuthModule());
  }
}
