public int getHuffmanIndex(String label) {
    if (huffmanTree == null) {
        return -1;
    }
    Map<String, Integer> labelToIndex = huffmanTree.getLabelToIndexMap();
    if (!labelToIndex.containsKey(label)) {
        return -2;
    }
    return labelToIndex.get(label);
}
