public static int subtractCircularBufferIndices(int index0, int index1, int size) {
    int clockwiseDistance = (index1 - index0 + size) % size;
    int counterClockwiseDistance = (index0 - index1 + size) % size;

    if (clockwiseDistance == counterClockwiseDistance) {
        return -1 * clockwiseDistance;
    }
    else if (clockwiseDistance < counterClockwiseDistance) {
        return clockwiseDistance;
    }
    else {
        return -1 * counterClockwiseDistance;
    }
}
