public static <T> T getObjectFromGroovyResource(String resource, Object[] constructorArgs, Object[] args, Class<T> expectedType) {
    ClassLoader cl = Thread.currentThread().getContextClassLoader();
    GroovyClassLoader gcl = new GroovyClassLoader(cl);
    try {
        Class clazz = gcl.parseClass(new File(resource));
        Constructor<?> constructor = clazz.getConstructor(getClasses(constructorArgs));
        Object obj = constructor.newInstance(constructorArgs);
        if (args != null && args.length > 0) {
            Method method = clazz.getMethod("initialize", getClasses(args));
            method.invoke(obj, args);
        }
        return expectedType.cast(obj);
    } catch (Exception e) {
        throw new RuntimeException("Failed to create object from groovy resource " + resource, e);
    }
}

private static Class[] getClasses(Object[] objs) {
    if (objs == null || objs.length == 0) {
        return new Class[0];
    }
    Class[] classes = new Class[objs.length];
    for (int i = 0; i < objs.length; i++) {
        classes[i] = objs[i].getClass();
    }
    return classes;
}
