import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import Jama.Matrix;

public static List<double[]> generateNormalPoints(double[] mean, Matrix covariance, int count, Random rand, List<double[]> output) {
    if (output == null) {
        output = new ArrayList<>();
    }

    int dimension = mean.length;
    double[] point = new double[dimension];
    Matrix choleskyDecomposition = covariance.chol();

    for (int i = 0; i < count; i++) {
        // generate uncorrelated (standard) normal distributed numbers
        for (int j = 0; j < dimension; j++) {
            point[j] = rand.nextGaussian();
        }

        // apply Cholesky decomposition to correlate the distribution
        Matrix factors = new Matrix(point, dimension).times(choleskyDecomposition);
        output.add(factors.getColumnPackedCopy());
    }

    return output;
}
