public boolean hasParameters() {
  boolean hasParams = false;

  // check Cookies
  if (getRequest().getCookies() != null && getRequest().getCookies().length > 0) {
    hasParams = true;
  }

  // check Query parameters
  if (getRequest().getQueryString() != null && !getRequest().getQueryString().isEmpty()) {
    hasParams = true;
  }

  // check Form parameters
  if (getRequest().getParameterMap() != null && !getRequest().getParameterMap().isEmpty()) {
    hasParams = true;
  }

  // check Response header fields
  if (getResponse().getHeaderNames() != null && !getResponse().getHeaderNames().isEmpty()) {
    hasParams = true;
  }

  return hasParams;
}
