import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;

public byte[] calculatePayload(byte[] payload, byte[] encryptionKey, byte[] initVector) throws Exception {
    int maxBlockSize = 20; // set the maximum block size to 20 bytes
    int counter = 0;
    byte[] counterBytes = new byte[8];
    byte[] result = new byte[payload.length];

    while (counter * maxBlockSize < payload.length) {
        // calculate counter in byte array format, used for each iteration
        counterBytes[0] = (byte) ((counter & 0xff000000) >>> 24);
        counterBytes[1] = (byte) ((counter & 0x00ff0000) >>> 16);
        counterBytes[2] = (byte) ((counter & 0x0000ff00) >>> 8);
        counterBytes[3] = (byte) ((counter & 0x000000ff));

        // calculate hmac using encryptionKey and initVector concatenated with counterBytes
        Mac hmac = Mac.getInstance("HmacSHA256");
        SecretKeySpec secretKey = new SecretKeySpec(encryptionKey, "HmacSHA256");
        hmac.init(secretKey);
        hmac.update(initVector);
        hmac.update(counterBytes);
        byte[] hmacBytes = hmac.doFinal();

        // xor each value in the payload with the corresponding hmacBytes value
        for (int i = 0; i < maxBlockSize && i + counter * maxBlockSize < payload.length; i++) {
            result[i + counter * maxBlockSize] = (byte) (payload[i + counter * maxBlockSize] ^ hmacBytes[i]);
        }

        counter++;
    }

    return result;
}
