public void createNewCommit(String name, String email, String data, boolean erase, String message){
    try {
        // Initialize git repository
        Repository repository = new FileRepositoryBuilder()
                .setGitDir(new File("/path/to/repository/.git"))
                .build();
        Git git = new Git(repository);

        if(erase) {
            // Remove any existing data and config user
            git.commit().setAll(true).setMessage("Erased all properties").call();
            git.commit().setAuthor(name, email).setMessage(message).call();
        } else {
            // Set user and commit
            git.commit().setAuthor(name, email).setMessage(message).call();
        }

        // Push changes to remote or local repository
        git.push().call();
        git.close();
    } catch (Exception e) {
        // Handle exceptions
        e.printStackTrace();
    }
}
