public String getResourceUrlForDeleteQuoteItem(int quoteId, int quoteItemId) {
    // Assuming the base url and endpoint for deleting quote items are already defined in the code.
    String baseUrl = "https://example.com/api/quotes/";
    String endpoint = "/items/";

    // Concatenating the quote ID and quote item ID to the endpoint.
