        case "text":
            if (value instanceof String) {
                ((TextView) view).setText((String) value);
            }
            break;
        case "background_color":
            if (value instanceof Integer) {
                view.setBackgroundColor((int) value);
            }
            break;
        // add more cases for other properties as required
    }
}
