public static Node findChildNode(Node parent, String nodeName) {
    NodeList children = parent.getChildNodes();
    for (int i = 0; i < children.getLength(); i++) {
        Node child = children.item(i);
        if (child.getNodeType() == Node.ELEMENT_NODE && child.getNodeName().equals(nodeName)) {
            return child; // Found a matching child node
        }
    }
    return null; // No matching child node found
}
