public Map<Integer, List<Integer>> computeLocalities(List<Integer> medoids, DistanceFunction distFunc) {
    Map<Integer, Double> minDists = new HashMap<>();
    Map<Integer, List<Integer>> localities = new HashMap<>();
    for (int m : medoids) {
        double minDist = Double.MAX_VALUE;
        for (int m_i : medoids) {
            if (m_i != m) {
                double dist = distFunc.distanceBetween(m, m_i);
                if (dist < minDist) {
                    minDist = dist;
                }
            }
        }
        minDists.put(m, minDist);
    }
    for (int m : medoids) {
        double minDist = minDists.get(m);
        List<Integer> locality = new ArrayList<>();
        for (int o : allObjects) {
            double dist = distFunc.distanceBetween(m, o);
            if (dist <= minDist) {
                locality.add(o);
            }
        }
        localities.put(m, locality);
    }
    return localities;
}
