public Font loadFontFromStream(InputStream in, String extension) throws IOException {
    File tempFile = File.createTempFile("tempFont", extension);
    try (FileOutputStream out = new FileOutputStream(tempFile)) {
        byte[] buffer = new byte[1024];
        int bytesRead;
        while ((bytesRead = in.read(buffer)) != -1) {
            out.write(buffer, 0, bytesRead);
        }
    }
    Font font = loadFont(tempFile.getAbsolutePath());
    tempFile.delete();
    return font;
}
