public static int extractCharge(String formula) {
  int charge = 0;
  int idx = formula.indexOf("[");
  if (idx != -1) {
    String chargeString = formula.substring(idx + 1, formula.indexOf("]"));
    if (chargeString.startsWith("+")) {
      charge = Integer.parseInt(chargeString.substring(1));
    } else if (chargeString.startsWith("-")) {
      charge = Integer.parseInt(chargeString.substring(1)) * -1;
    }
  }
  return charge;
}
