public void requestNewReturnTripTime() {
    // Create a new Ping object with isReply set to false
    Ping ping = new Ping(false);

    // Send the Ping object to the remote computer over the connection
    connection.send(ping);

    // Wait for a Ping object with isReply set to true
    while (true) {
        FrameworkMessage message = connection.receive();
        if (message instanceof Ping) {
            Ping pingReply = (Ping) message;
            if (pingReply.isReply()) {
                // Update the return trip time with the new value
                setReturnTripTime(pingReply.getTime());
                break;
            }
        }
    }
}
