private String buildPositionString(String location, int increment) {
    StringBuilder positionBuilder = new StringBuilder(location);
    int locationLength = location.length();

    for (int i = 0; i < locationLength; i++) {
        char c = positionBuilder.charAt(i);

        if (Character.isDigit(c)) {
            int pos = Character.getNumericValue(c) + increment;
            positionBuilder.setCharAt(i, Character.forDigit(pos, 10));
        }
    }

    return positionBuilder.toString();
}
