public static <T> List<T> listIndexesByType(String type, Class<T> modelType) {
    IndexManager indexManager = getIndexManager();
    List<T> indexes = new ArrayList<>();
    for (String indexName : indexManager.getIndexNames()) {
        if (type == null || indexName.startsWith(type)) {
            Index<T> index = indexManager.getIndex(indexName, modelType);
            if (index != null) {
                indexes.addAll(index.list());
            }
        }
    }
    return indexes;
}
