public void saveModelIntoOriginalFile(File relationsFile, boolean writeComments, String lineSeparator) throws IOException {
    FileOutputStream outputStream = new FileOutputStream(relationsFile);
    OutputStreamWriter writer = new OutputStreamWriter(outputStream);

    if(writeComments){
        writer.write("#Saved model into original file\n");
