public static String renameTagOrAttribute(String input, String xPath, String target, String newName) throws Exception {
    DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
    factory.setNamespaceAware(true);
    DocumentBuilder builder = factory.newDocumentBuilder();
    Document doc = builder.parse(new InputSource(new StringReader(input)));
    XPath xpath = XPathFactory.newInstance().newXPath();
    NodeList nodes = (NodeList) xpath.evaluate(xPath, doc, XPathConstants.NODESET);
    for (int i = 0; i < nodes.getLength(); i++) {
        nodes.item(i).getAttributes().getNamedItem(target).setNodeValue(newName);
    }
    TransformerFactory tf = TransformerFactory.newInstance();
    Transformer t = tf.newTransformer();
    StringWriter writer = new StringWriter();
    t.transform(new DOMSource(doc), new StreamResult(writer));
    return writer.toString();
}
