import java.lang.reflect.WildcardType;
public static Type getOnlyBound(WildcardType wildcardType) {
    Type[] upperTypes = wildcardType.getUpperBounds();
    Type[] lowerTypes = wildcardType.getLowerBounds();

    if (upperTypes.length == 1) {// wildcardType<? extends T>
        Type type = upperTypes[0];
        if (type instanceof TypeVariable) {// wildcardType<? extends U extends T>
            return getOnlyBound((TypeVariable<?>) type);
        }
        return type;
    } else if (lowerTypes.length == 1) {// wildcardType<? super T>
        return lowerTypes[0];
    } else {// wildcardType<?>
        return Object.class;
    }
}

private static Type getOnlyBound(TypeVariable<?> typeVariable) {
    Type[] types = typeVariable.getBounds();
    if (types.length == 1) {
        boolean needRecursion = types[0] instanceof TypeVariable;
        return needRecursion ? getOnlyBound((TypeVariable<?>)types[0]) : types[0];
    } else {
        return Object.class;
    }
}
