public void dropDatabase(Transaction txn, boolean delete) {
    if (delete) {
        try {
            DatabaseConfig dbConfig = new DatabaseConfig();
            dbConfig.setAllowCreate(true);
            dbConfig.setTransactional(true);
            dbConfig.setSortedDuplicates(false);

            Database db = environment.openDatabase(txn, "databaseName", dbConfig);
            db.close();
            environment.removeDatabase(txn, "databaseName");
        } catch (DatabaseNotFoundException e) {
            // Handle exception
        }
    } else {
        Cursor cursor = null;

        try {
            Database db = txn.getDatabase();
            cursor = db.openCursor(txn, null);
            while (cursor.getNext(null, null, null) == OperationStatus.SUCCESS) {
              cursor.delete();
            }
        } catch (DatabaseException e) {
            // Handle exception
        } finally {
            if (cursor != null) {
                cursor.close();
            }
        }
    }
}
