public double[][] getSubmatrix(double[][] A, int[] r, int[] c) {
    double[][] subMatrix = new double[r.length][c.length];
    try {
        for (int i = 0; i < r.length; i++) {
            for (int j = 0; j < c.length; j++) {
                subMatrix[i][j] = A[r[i]][c[j]];
            }
        }
    } catch (ArrayIndexOutOfBoundsException e) {
        System.out.println("Submatrix indices are out of bounds!");
        return null;
    }
    return subMatrix;
}
