public static boolean isImplicitlyImported(String classNameOrPackageName) {
    Package teaPackage = Tea.class.getPackage();

    if (teaPackage == null) {
        return false;
    }

    String packageName = teaPackage.getName();

    if (classNameOrPackageName.equals(packageName)) {
        return true;
    }

    try {
        Class.forName(classNameOrPackageName);
        return true;
    } catch (ClassNotFoundException e) {
        // Ignore the exception as the specified class or package is not found
    }

    packageName += ".";

    return classNameOrPackageName.startsWith(packageName);
}
