public Form getAncestor(Form formToGetAncestorForParam, boolean includeFieldDataParam, boolean includeTableFieldsParam) {
    Form ancestorForm = null;
    Form currentForm = formToGetAncestorForParam;

    while (currentForm.getParentForm() != null) {
        ancestorForm = currentForm.getParentForm();
        if (!includeFieldDataParam) {
            ancestorForm.clearFieldData();
        }
        if (!includeTableFieldsParam) {
            ancestorForm.clearTableRecordData();
        }
        currentForm = ancestorForm;
    }

    return ancestorForm;
}
