import java.io.File;
import java.io.IOException;
import java.util.Properties;

public Properties getPropertyFile(String thePackage, String name) throws IOException {
    String path = System.getProperty("user.dir") + File.separator + thePackage + File.separator + name + ".properties";
    File propertyFile = new File(path);
    if (!propertyFile.exists()) {
        propertyFile.getParentFile().mkdirs(); // Create parent directories if needed
        propertyFile.createNewFile(); // Create the file if it does not exist
    }
    Properties properties = new Properties();
    properties.load(new FileInputStream(propertyFile));
    return properties;
}
