public Set<String> checkCoreFeatures(Map<String, String> manifestHeaders, Set<String> installationFeatures) {
    Set<String> missingFeatures = new HashSet<>();

    String coreFeaturesHeader = manifestHeaders.get("Core-Features");
    if (coreFeaturesHeader == null || coreFeaturesHeader.isEmpty()) {
        return missingFeatures;
    }

    String[] coreFeatures = coreFeaturesHeader.split(",");
    for (String feature : coreFeatures) {
        feature = feature.trim();
        if (!installationFeatures.contains(feature)) {
            missingFeatures.add(feature);
        }
    }

    return missingFeatures;
}
