        } catch (SAXException e) {
            throw new RuntimeException(RESPONSE_IS_NOT_WELL_FORMED + xml, e);
        }
        XPath xPath = XPathFactory.newInstance().newXPath();
        return xPath.compile(expression).evaluate(document);
