public float getStatusValue(BayesianNode bn, String nodeName, String status) throws UnknownNodeException, UnknownNodeStateException {
    float probability = 0.0f;
    BayesianNode node = bn.getNode(nodeName);
    if (node == null) {
        throw new UnknownNodeException("Node not found: " + nodeName);
    }
    State state = node.getState(status);
    if (state == null) {
        throw new UnknownNodeStateException("Unknown state: " + status);
    }
    probability = state.getProbability();
    return probability;
}
