public boolean scrollUpListView(int index) {
    boolean moreScrolling = false;
    ListView listView;
    if (index == 0) {
        listView = getListView();
    } else {
        listView = (ListView) findViewById(index);
    }
    if (listView != null) {
        int firstVisibleItem = listView.getFirstVisiblePosition();
        if (firstVisibleItem > 0) {
            listView.smoothScrollToPosition(firstVisibleItem - 1);
            moreScrolling = true;
        }
    }
    return moreScrolling;
}
