public List<Node> extractAndMergeNodes(Element head, Element body) {
    List<Node> oobNodes = new ArrayList<>();
    oobNodes.addAll(extractOOBNodes(head));
    oobNodes.addAll(extractOOBNodes(body));
    List<Node> inlineNodes = mergeInlineNodes(head, body);
    List<Node> mergedNodes = new ArrayList<>();
    mergedNodes.addAll(oobNodes);
    mergedNodes.addAll(inlineNodes);
    return mergedNodes;
}

private List<Node> extractOOBNodes(Element element) {
    List<Node> oobNodes = new ArrayList<>();
    NodeList childNodes = element.getChildNodes();
    for (int i = 0; i < childNodes.getLength(); i++) {
        Node node = childNodes.item(i);
        if (node.getNodeType() == Node.ELEMENT_NODE) {
            Element childElement = (Element) node;
            if (childElement.hasAttribute("data-oob")) {
                oobNodes.add(childElement);
            }
            oobNodes.addAll(extractOOBNodes(childElement));
        }
    }
    return oobNodes;
}

private List<Node> mergeInlineNodes(Element head, Element body) {
    List<Node> inlineNodes = new ArrayList<>();
    inlineNodes.addAll(mergeInlineCssNodes(head));
    inlineNodes.addAll(mergeInlineCssNodes(body));
    inlineNodes.addAll(mergeInlineJsNodes(head));
    inlineNodes.addAll(mergeInlineJsNodes(body));
    return inlineNodes;
}

private List<Node> mergeInlineCssNodes(Element element) {
    List<Node> cssNodes = new ArrayList<>();
    NodeList childNodes = element.getChildNodes();
    for (int i = 0; i < childNodes.getLength(); i++) {
        Node node = childNodes.item(i);
        if (node.getNodeType() == Node.ELEMENT_NODE && "style".equalsIgnoreCase(node.getNodeName())) {
            cssNodes.add(node);
        }
    }
    if (cssNodes.size() > 1) {
        StringBuilder cssBuilder = new StringBuilder();
        for (Node cssNode : cssNodes) {
            cssBuilder.append(cssNode.getTextContent());
            element.removeChild(cssNode);
        }
        Element styleElement = element.getOwnerDocument().createElement("style");
        styleElement.setTextContent(cssBuilder.toString());
        element.insertBefore(styleElement, element.getFirstChild());
        cssNodes.clear();
        cssNodes.add(styleElement);
    }
    return cssNodes;
}

private List<Node> mergeInlineJsNodes(Element element) {
    List<Node> jsNodes = new ArrayList<>();
    NodeList childNodes = element.getChildNodes();
    for (int i = 0; i < childNodes.getLength(); i++) {
        Node node = childNodes.item(i);
        if (node.getNodeType() == Node.ELEMENT_NODE && "script".equalsIgnoreCase(node.getNodeName())
                && !node.hasAttributes()) {
            jsNodes.add(node);
        }
    }
    if (jsNodes.size() > 1) {
        StringBuilder jsBuilder = new StringBuilder();
        for (Node jsNode : jsNodes) {
            jsBuilder.append(jsNode.getTextContent());
            element.removeChild(jsNode);
        }
        Element scriptElement = element.getOwnerDocument().createElement("script");
        scriptElement.setTextContent(jsBuilder.toString());
        element.insertBefore(scriptElement, element.getFirstChild());
        jsNodes.clear();
        jsNodes.add(scriptElement);
    }
    return jsNodes;
}
