public static String joinStrings(Collection<String> s, String delimiter, boolean doQuote) {
    StringBuilder builder = new StringBuilder();
    boolean isFirst = true;
    for (String str : s) {
        if (!isFirst) {
            builder.append(delimiter);
        }
        if (doQuote) {
            builder.append("\"").append(str).append("\"");
        } else {
            builder.append(str);
        }
        isFirst = false;
    }
    return builder.toString();
}
