public List<File> getAvailableRules(String rulesDirectory) throws MojoExecutionException {
    File directory = new File(rulesDirectory);
    List<File> rules = new ArrayList<>();
    if (!directory.exists() || !directory.isDirectory() || !directory.canRead()) {
        throw new MojoExecutionException("The rules directory cannot be read.");
    }
    File[] files = directory.listFiles();
    for (File file : files) {
        if (file.isFile()) {
            rules.add(file);
        }
    }
    return rules;
}
