            break;
        case PENDING:
            targetUpdateStatus = TargetUpdateStatus.UNCHANGED;
            break;
        case FAILED:
            targetUpdateStatus = TargetUpdateStatus.FAILED;
            break;
        default:
            targetUpdateStatus = TargetUpdateStatus.UNCHANGED;
            break;
    }
    return targetUpdateStatus;
}
