public GitLabProjectMember updateProjectMember(int projectId, int userId, int accessLevel, String expiresAt) throws IOException {
    String endpoint = String.format("/projects/%d/members/%d", projectId, userId);

    JsonObject requestBody = new JsonObject();
    requestBody.addProperty("access_level", accessLevel);
    requestBody.addProperty("expires_at", expiresAt);

    HttpResponse<JsonNode> response = Unirest.put(endpoint)
            .header("accept", "application/json")
            .body(requestBody)
            .asJson();

    if(response.getStatus() == 200) {
        JsonNode responseBody = response.getBody();
        return new Gson().fromJson(responseBody.toString(), GitLabProjectMember.class);
    } else {
        throw new IOException("Error: " + response.getStatus() + response.getStatusText());
    }
}
