public <T> String getNameOrDefault(T item, String name) {
    try {
        // Try to get the name property using reflection
        Object result = item.getClass().getMethod("get" + Character.toUpperCase(name.charAt(0)) + name.substring(1)).invoke(item);
        if (result != null) {
            return result.toString();
        }
    } catch (Exception e) {
        // Failed to get the name property, fallback to item.toString()
    }
    return item.toString();
}
