public double calculateTriangleArea(HalfEdge hedge0, HalfEdge hedge1){
   double base = hedge0.getLength();
   double height = hedge1.getNext().getVertex().getY() - hedge1.getVertex().getY();
   double area = 0.5 * base * height;
   return Math.pow(area, 2);
}
