public String[] parseMapDescriptor(String mapDescriptor) {
    // implementation code
    // here's a possible approach

    List<String> tokens = new ArrayList<>();
    String currentToken = "";

    for (int i = 0; i < mapDescriptor.length(); i++) {
        char currentChar = mapDescriptor.charAt(i);

        if (currentChar == ':') {
            tokens.add(currentToken);
            currentToken = "";
        } else if (currentChar == ',' || currentChar == ' ') {
            if (!currentToken.isEmpty()) {
                tokens.add(currentToken);
                currentToken = "";
            }
        } else {
            currentToken += currentChar;
        }
    }

    if (!currentToken.isEmpty()) {
        tokens.add(currentToken);
    }

    return tokens.toArray(new String[0]);
}
