public int extractIntegerProperty(String key, boolean defaultProvided, int defaultValue, List<String> errors) {
    int extractedValue = 0;
    Object propertyValue = storedValues.get(key);
    if (propertyValue != null) {
        try {
            extractedValue = Integer.parseInt(propertyValue.toString());
        } catch (NumberFormatException e) {
            errors.add("Invalid value for key " + key + ". Value should be an integer");
            return defaultValue;
        }
    } else if (defaultProvided) {
        extractedValue = defaultValue;
    } else {
        errors.add("Unable to find value for key " + key);
        return defaultValue;
    }
    return extractedValue;
}
