import java.lang.annotation.*;

@Retention(RetentionPolicy.RUNTIME)
@Target({ ElementType.FIELD, ElementType.METHOD, ElementType.TYPE })
public @interface ModifierAnnotation {
    String[] value();
}

public static void addModifiers(Class<?> clazz, String[] modifiers) {
    ModifierAnnotation annotation = clazz.getAnnotation(ModifierAnnotation.class);
    String[] currentModifiers = annotation != null ? annotation.value() : new String[0];

    String[] combinedModifiers = Stream.of(currentModifiers, modifiers)
            .flatMap(Stream::of)
            .distinct()
            .toArray(String[]::new);

    clazz.getMethods().forEach(m -> {
        ModifierAnnotation methodAnnotation = m.getAnnotation(ModifierAnnotation.class);
        String[] methodModifiers = methodAnnotation != null ? methodAnnotation.value() : new String[0];

        String[] combinedMethodModifiers = Stream.of(methodModifiers, combinedModifiers)
                .flatMap(Stream::of)
                .distinct()
                .toArray(String[]::new);

        MethodHandles.Lookup lookup = MethodHandles.lookup();
        try {
            Field modifiersField = Field.class.getDeclaredField("modifiers");
            modifiersField.setAccessible(true);
            int methodModifiersValue = lookup.unreflectGetter(modifiersField)
                    .invoke(m.getClass());
            lookup.unreflectSetter(modifiersField)
                    .invoke(m.getClass(), methodModifiersValue | Modifier.PRIVATE);
        } catch (Throwable e) {
            throw new IllegalStateException("Failed to set modifiers.", e);
        }

        m.getDeclaringClass().getDeclaredFields().forEach(f -> {
            ModifierAnnotation fieldAnnotation = f.getAnnotation(ModifierAnnotation.class);
            String[] fieldModifiers = fieldAnnotation != null ? fieldAnnotation.value() : new String[0];

            String[] combinedFieldModifiers = Stream.of(fieldModifiers, combinedModifiers)
                    .flatMap(Stream::of)
                    .distinct()
                    .toArray(String[]::new);

            try {
                Field modifiersField = Field.class.getDeclaredField("modifiers");
                modifiersField.setAccessible(true);
                int fieldModifiersValue = lookup.unreflectGetter(modifiersField)
                        .invoke(f);
                lookup.unreflectSetter(modifiersField)
                        .invoke(f, fieldModifiersValue | Modifier.PRIVATE);
            } catch (Throwable e) {
                throw new IllegalStateException("Failed to set modifiers.", e);
            }
        });
    });
}
