public static double[] estimateWheelAngleAndVelocity(double currentAngle, double currentVelocity, double acceleration, double time){
    double newAngle = currentAngle + currentVelocity * time + 0.5 * acceleration * time * time;
    double newVelocity = currentVelocity + acceleration * time;
    return new double[]{newAngle, newVelocity};
}
