public static <R> Stream<R> invokeCallbacks(Invoker invoker) {
    List<Callback> callbackList = invoker.getCallbacks();
    List<R> resultList = new ArrayList<>();
    for (Callback<R> callback : callbackList) {
        try {
            R result = callback.call();
            if (result != null) {
                resultList.add(result);
            }
        } catch (Exception e) {
            // Handle exception
        }
    }
    return resultList.stream();
}
