public ComponentVisitor getComponentVisitorWithCache(HttpServletRequest request, TargetMetaDef targetMetaDef) {
    HttpSession session = request.getSession(true);
    ComponentVisitor componentVisitor = (ComponentVisitor) session.getAttribute("cachedComponentVisitor");
    if (componentVisitor == null) {
        componentVisitor = new ComponentVisitor(targetMetaDef);
        session.setAttribute("cachedComponentVisitor", componentVisitor);
    }
