public static Pair<PrivateKey, X509Certificate> extractKeyAndCertificate(KeyStore keyStore, char[] keyStorePassword) throws IllegalStateException {
    try {
        String alias = keyStore.aliases().nextElement();
        Key key = keyStore.getKey(alias, keyStorePassword);
        if (key instanceof PrivateKey) {
            X509Certificate cert = (X509Certificate) keyStore.getCertificate(alias);
            return new Pair<>((PrivateKey) key, cert);
        }
    } catch (KeyStoreException | NoSuchAlgorithmException | UnrecoverableKeyException e) {
        throw new IllegalStateException("Error while extracting key and certificate", e);
    }
    throw new IllegalStateException("No valid key and certificate found");
}
