public static void skipFully(InputStream in, int len) throws IOException {
    int totalSkipped = 0;

    while (totalSkipped < len) {
        long skipped = in.skip(len - totalSkipped);

        if (skipped == 0) {
            if (in.read() == -1) {
                throw new IOException("EOF encountered before requested bytes could be skipped");
            }

            skipped = 1;
        }

        totalSkipped += skipped;
    }
}
