public Node findLowestHigher(Node rootNode, int value) {
    Node lowestHigherValue = null;
    while (rootNode != null) {
        if (rootNode.value > value) {
            if (lowestHigherValue == null || rootNode.value < lowestHigherValue.value) {
                lowestHigherValue = rootNode;
            }
            rootNode = rootNode.left;
        } else {
            rootNode = rootNode.right;
        }
    }
    return lowestHigherValue;
}
