public class Model {
   private Map<String, Property> properties = new HashMap<String, Property>();
   private List<Model> childModels = new ArrayList<Model>();

   public void addProperty(String name, Property property) {
      properties.put(name, property);
   }

   public void addChildModel(Model child) {
      childModels.add(child);
   }

   public void forwardEvent(String propertyName, String eventType) {
      Property property = properties.get(propertyName);
      if (property != null) {
         property.evaluate(eventType);
         for (Model child : childModels) {
            child.forwardEvent(propertyName, eventType);
         }
      }
   }
}

public interface Property {
   void evaluate(String eventType);
}

public class SpecificProperty implements Property {
   @Override
   public void evaluate(String eventType) {
      // Evaluate and trigger events as needed for this specific property
   }
}
