public void restoreState(File persistFile, List<File> contentDirs) {
    // check if persistFile is a valid file
    if (!persistFile.isFile()) {
        throw new IllegalArgumentException("Persist file does not exist or is not a valid file.");
    }

    // read content from the persistFile and deserialize the object
    try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(persistFile))) {
        Object obj = ois.readObject();
        if (obj instanceof ChangedList) {
            // update the content directories with the latest restored state
            ChangedList changedList = (ChangedList) obj;
            contentDirs.addAll(changedList.getContentDirs());
        } else {
            throw new IllegalArgumentException("Persist file does not contain a valid ChangedList object.");
        }
    } catch (IOException e) {
        throw new RuntimeException("An error occurred while reading the persist file.", e);
    } catch (ClassNotFoundException e) {
        throw new RuntimeException("An error occurred while deserializing the object from the persist file.", e);
    }
}
