public <K, V> KafkaProducer<K, V> createProducer(Class<? extends Serializer> keySerializer,
                                                 Class<? extends Serializer> valueSerializer,
                                                 Map<String, Object> overrideConfig) {
    Properties props = new Properties();
    //Set the broker list to connect
    props.put("bootstrap.servers", "localhost:9092");
    //Configure the key serializer
    props.put("key.serializer", keySerializer.getName());
    //Configure the value serializer
    props.put("value.serializer", valueSerializer.getName());
    //If we have some override configuration, lets add it.
    if (overrideConfig != null) {
        props.putAll(overrideConfig);
    }
    //Create the producer instance using properties.
    return new KafkaProducer<>(props);
}
