public Set<ArtifactEntity> checkAndUpdateArtifactEntities(List<Artifact> artifacts, Map<String, ArtifactEntity> artifactCache) {
    Set<ArtifactEntity> updatedEntities = new HashSet<>();
    for (Artifact artifact : artifacts) {
        ArtifactEntity entity = artifactCache.get(artifact.getId());
        if (entity != null) {
            updatedEntities.add(entity);
        } else {
            entity = artifactRepository.findById(artifact.getId());
            if (entity != null) {
                artifactCache.put(artifact.getId(), entity);
                updatedEntities.add(entity);
            } else {
                entity = new ArtifactEntity(artifact);
                artifactRepository.save(entity);
                artifactCache.put(artifact.getId(), entity);
                updatedEntities.add(entity);
            }
        }
    }
    return updatedEntities;
}
