public boolean createNewLoggingAction(Logger logger, Auditor auditor, Instance instance) {
    boolean newInstanceSet = false;
    ThreadLocal<LoggingAction> threadLocalInstance = getThreadLocalInstance();
    LoggingAction loggingAction = threadLocalInstance.get();
    if (loggingAction == null) {
        loggingAction = new LoggingAction(logger, auditor, instance);
        threadLocalInstance.set(loggingAction);
        newInstanceSet = true;
    }
    return newInstanceSet;
}

private ThreadLocal<LoggingAction> getThreadLocalInstance() {
    return ThreadLocal.withInitial(LoggingAction::new);
}
