public static DoubleVector addWeightedVectors(DoubleVector vector1, double weight1, DoubleVector vector2, double weight2) {
    if (vector1 == null || vector2 == null || vector1.size() != vector2.size()) {
        throw new IllegalArgumentException("Invalid input vectors");
    }

    DoubleVector resultVector = new DoubleVector(vector1.size());
    for (int i = 0; i < vector1.size(); i++) {
        double sum = (vector1.get(i) * weight1) + (vector2.get(i) * weight2);
        resultVector.set(i, sum);
    }

    return resultVector;
}
