public class UniqueFileNameGenerator {
    private Set<String> usedShortNames;

    public UniqueFileNameGenerator(Set<String> usedShortNames) {
        this.usedShortNames = usedShortNames;
    }

    public String generateUniqueShortName(String longFullName) {
        String shortName = longFullName.replaceAll("\\s+", "").toUpperCase();

        if (shortName.length() > 8) {
            shortName = shortName.substring(0, 6) + "~1";
        }

        if (usedShortNames.contains(shortName)) {
            for (int i = 2; i <= 9999; i++) {
                String newShortName = shortName.substring(0, 6) + "~" + i;

                if (!usedShortNames.contains(newShortName)) {
                    shortName = newShortName;
                    break;
                }
            }

            if (usedShortNames.contains(shortName)) {
                throw new IllegalStateException("Could not find unused short name for file: " + longFullName);
            }
        }

        usedShortNames.add(shortName);
        return shortName;
    }
}
