public void take(Subscriber<? super T> s, Iterator<? extends T> it, Runnable onClose) {
    boolean subscribed = true;
    try {
        while (it.hasNext()) {
            if (s.isUnsubscribed()) {
                subscribed = false;
                break;
            }
            s.onNext(it.next());
        }
        if (subscribed && !s.isUnsubscribed()) {
            s.onCompleted();
        }
    } catch (Throwable e) {
        Exceptions.throwOrReport(e, s);
    } finally {
        if (onClose != null) {
            onClose.run();
        }
    }
}
