public void checkComponentStatus() {
    int maxRetries = 20;
    int retryInterval = 3000;

    for (int retry = 0; retry < maxRetries; retry++) {
        try {
            // Check if component is responding here
            if (componentStatus()) {
                return;
            }
        } catch (Exception e) {
            // Log the error if required
        }

        try {
            Thread.sleep(retryInterval);
        } catch (InterruptedException e) {
            // Log the error if required
        }
    }

    throw new IllegalStateException("Component not responding after 60 seconds");
}

private boolean componentStatus() {
    // Check component status here
    return true;  // Return true if component is fine, false otherwise
}
