public static Tuple2<INDArray[], INDArray[]> mergeFeaturesWithMasks(INDArray[] arrays, INDArray[] masks) {
    if (arrays.length == 0) {
        throw new IllegalArgumentException("Arrays cannot be empty");
    }

    int nRows = arrays[0].shape()[0];
    int nCols = arrays[0].shape()[1];
    int nChannels = arrays[0].shape()[2];
    int nArrays = arrays.length;

    INDArray[] result = new INDArray[nChannels];
    INDArray[] resultMasks = new INDArray[nChannels];

    for (int channel = 0; channel < nChannels; channel++) {
        INDArray mergedArray = Nd4j.zeros(nRows, nCols, nArrays);
        INDArray mergedMask = Nd4j.zeros(nRows, nCols, nArrays);

        for (int i = 0; i < nArrays; i++) {
            INDArray array = arrays[i];
            INDArray mask = masks[i];

            if (array.shape()[2] != nChannels) {
                throw new IllegalArgumentException("All arrays must have the same number of channels");
            }

            mergedArray.put(new INDArrayIndex[]{NDArrayIndex.all(), NDArrayIndex.all(), NDArrayIndex.point(i)}, array.get(all(), all(), point(channel)));
            mergedMask.put(new INDArrayIndex[]{NDArrayIndex.all(), NDArrayIndex.all(), NDArrayIndex.point(i)}, mask.get(all(), all(), point(channel)));
        }

        result[channel] = mergedArray;
        resultMasks[channel] = mergedMask;
    }

    return new Tuple2<>(result, resultMasks);
}
