public static double applyScaleTypeAndRounding(double num, String scaleType, int scaleValue, String roundingType, int roundingValue) {
    // apply scaling
    if (scaleType.equals("MULTIPLY")) {
        num *= scaleValue;
    } else if (scaleType.equals("DIVIDE")) {
        num /= scaleValue;
    }

    // apply rounding
    if (roundingType.equals("ROUND")) {
        num = Math.round(num);
    } else if (roundingType.equals("FLOOR")) {
        num = Math.floor(num);
    } else if (roundingType.equals("CEILING")) {
        num = Math.ceil(num);
    }

    return num;
}
