public static Object unwrapObject(Class<?> type, Object object) throws Exception {
    if (type.isInstance(object)) {
        return object;
    } else if (object instanceof Callable || object instanceof Supplier) {
        Object nestedObject = unwrapObject(type, object.getClass().getMethod("call").invoke(object));
        return nestedObject;
    } else {
        throw new IllegalArgumentException("Object is not a value or supported Callable/Supplier");
    }
}
