public String transformRecursive(String original, State state) {
    String transformed = original;
    for (StringTransformerRule rule : rules) {
        String current = transformed;
        transformed = rule.transform(current);
        if (state == State.STOP || Objects.equals(current, transformed)) {
            return transformed;
        }
    }
    if (state == State.CONTINUE) {
        return transformRecursive(transformed, state);
    }
    return transformed;
}
