@Override
public boolean putIfMatch(URI uri, String etag, String content, String contentType, Header[] headers, Credentials credentials) {
    HttpPut request = new HttpPut(uri);
    StringEntity entity = new StringEntity(content, ContentType.create(contentType, Consts.UTF_8));
    request.setEntity(entity);
    request.setHeaders(headers);
    request.setHeader(HttpHeaders.IF_MATCH, etag);

    try (CloseableHttpResponse response = executeRequest(request, credentials)) {
        int statusCode = response.getStatusLine().getStatusCode();
        if (statusCode == HttpStatus.SC_OK || statusCode == HttpStatus.SC_CREATED) {
            return true;
        } else if (statusCode == HttpStatus.SC_PRECONDITION_FAILED) {
            return false;
        } else {
            throw new XcapException(buildErrorMessage(request, response), statusCode);
        }
    } catch (IOException e) {
        throw new XcapException("IO exception occurred while executing request: " + request, e);
    }
