public void addMediaTypeInformationToResourceMethod(Method methodResult, Class<?> classResult, ResourceMethod resourceMethod) {
   if(methodResult != null && classResult != null && resourceMethod != null) {
      Annotation[][] parameterAnnotations = methodResult.getParameterAnnotations();
      for(Annotation[] paramAnnotations : parameterAnnotations) {
         for(Annotation annotation : paramAnnotations) {
            if(annotation instanceof Consumes) {
               Consumes consumes = (Consumes)annotation;
               resourceMethod.getRequestMediaType().addAll(Arrays.asList(consumes.value()));
            }
            if(annotation instanceof Produces) {
               Produces produces = (Produces)annotation;
               resourceMethod.getResponseMediaType().addAll(Arrays.asList(produces.value()));
            }
         }
      }
   }
}
