public void validateJsUsingJsHint(String data) throws LinterException {
    try {
        // Initialize jshint
        JSHint jshint = new JSHint();
        String options = "{esversion: 6}";

        // Configure jshint options
        jshint.configure(options);

        // Validate the JS
        JSHintResult result = jshint.lint(data);

        // If any errors are found, throw an exception
        if (result != null && result.getErrorCount() > 0) {
            StringBuilder errorMessage = new StringBuilder();
            for (JSHintError error : result.getErrors()) {
                errorMessage.append(error.getReason() + " on line " + error.getLine() + "\n");
            }
            throw new LinterException(errorMessage.toString());
        }
    } catch (IOException e) {
        throw new LinterException("Error occurred while reading JS: " + e.getMessage());
    }
}
