public static byte[] testing(byte[] input) {
    byte[] output = new byte[(input.length + 1) / 2];
    for (int i = 0; i < input.length; i++) {
        if (i % 2 == 0) {
            output[i / 2] = (byte) ((input[i] & 0x0F) << 4);
        } else {
            output[i / 2] |= (byte) (input[i] & 0x0F);
        }
    }
    return output;
}
