public static double[] getFrequencyIntensities(double[] amplitudes, boolean complex) {
    int n = amplitudes.length;
    double[] intensities = new double[n/2 + 1];
    double norm = 1.0 / (double) n;

    for (int i = 0; i < n/2 + 1; i++) {
        double re = amplitudes[2*i];
        double im = (complex && (2*i + 1 < n)) ? amplitudes[2*i + 1] : 0.0;
        double intensity = norm * (re*re + im*im);
        intensities[i] = intensity;
    }

    return intensities;
}
