                mInputLen = mCurrentSize;
            }
            mInputStart = 0;
        }

        int ptr = mInputStart;
        final int end = ptr + mInputLen;
        final char[] buf = mInputBuffer;
        int start = ptr;
        try {
            decode_loop:
            while (ptr < end) {

                while (buf[ptr] <= INT_SPACE) {
                    if (++ptr >= end) {
                        break decode_loop;
                    }
                }

                start = ptr;
                ++ptr;
                while (ptr < end && buf[ptr] > INT_SPACE) {
                    ++ptr;
                }
                ++count;
                int tokenEnd = ptr;
                ++ptr;  

                if (tad.decodeValue(buf, start, tokenEnd)) {
                    break;
                }
