public static int[] buildLcpArray(String s, int[] suffixArray) {
    int n = s.length();
    int[] rank = new int[n];
    for (int i = 0; i < n; i++) {
        rank[suffixArray[i]] = i;
    }
    int[] lcp = new int[n - 1];
    int h = 0;
    for (int i = 0; i < n; i++) {
        if (rank[i] > 0) {
            int j = suffixArray[rank[i] - 1];
            while (i + h < n && j + h < n && s.charAt(i + h) == s.charAt(j + h)) {
                h++;
            }
            lcp[rank[i] - 1] = h;
            if (h > 0) {
                h--;
            }
        }
    }
    return lcp;
}
