import java.util.Iterator;
import java.util.List;
import java.util.ArrayList;

public class IterableCombiner<T> {

    public Iterator<T> combineIterables(Iterable<T> iterable0, Iterable<T> iterable1) {
        List<Iterator<T>> iterators = new ArrayList<>();
        iterators.add(iterable0.iterator());
        iterators.add(iterable1.iterator());

        Iterator<T> combinedIterator = new Iterator<T>() {
            int currentIndex = 0;

            @Override
            public boolean hasNext() {
                while (currentIndex < iterators.size() && !iterators.get(currentIndex).hasNext()) {
                    currentIndex++;
                }
                return currentIndex < iterators.size();
            }

            @Override
            public T next() {
                if (!hasNext()) {
                    throw new RuntimeException("No more elements");
                }
                return iterators.get(currentIndex).next();
            }
        };

        return combinedIterator;
    }
}
