public Dataset stripAndRemapLabels(Dataset dataset, List<String> labels) {
    Dataset strippedDataset = new Dataset();
    for(int i = 0; i < dataset.size(); i++) {
        DataPoint datapoint = dataset.get(i);
        DataPoint strippedDatapoint = new DataPoint();
        for(String label : labels) {
            if(datapoint.getFeatures().containsKey(label)) {
                strippedDatapoint.addFeature(label, datapoint.getFeatures().get(label));
            }
        }
        strippedDatapoint.setLabel(dataset.getLabelTranslator().mapLabel(datapoint.getLabel()));
        strippedDataset.addDataPoint(strippedDatapoint);
    }
    strippedDataset.setLabelTranslator(dataset.getLabelTranslator());
    return strippedDataset;
}
