public Map<String, Class<? extends ParaObject>> findParaObjectSubclasses() {
    Map<String, Class<? extends ParaObject>> classMap = new HashMap<>();
    String[] packageNames = new String[] { Config.CORE_PACKAGE_NAME, "para" }; // add more if needed

    for (String packageName : packageNames) {
        try {
            Class<?>[] classes = getClassLoader().getClassesForPackage(packageName);
            for (Class<?> clazz : classes) {
                if (ParaObject.class.isAssignableFrom(clazz) && !Modifier.isAbstract(clazz.getModifiers())) {
                    classMap.put(clazz.getSimpleName().toLowerCase(), (Class<? extends ParaObject>) clazz);
                }
            }
        } catch (Exception e) {
            logger.error(null, e);
        }
    }

    return classMap;
}

private ClassLoader getClassLoader() {
    if (classLoader == null) {
        synchronized (lock) {
            if (classLoader == null) {
                ClassLoader parent = getClass().getClassLoader();
                classLoader = new ClassLoader(parent, new String[] { Config.CORE_PACKAGE_NAME });
            }
        }
    }

    return classLoader;
}
