public void writeBulkOperation(Collection<Object> objects, boolean allOrNothing, OutputStream out) throws IOException {
    try (BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(out))) {
        writer.write("{\"allOrNothing\": " + allOrNothing + ", \"objects\": [");
        boolean first = true;
        for (Object obj : objects) {
            if (!first) {
                writer.write(", ");
            }
            writer.write(new Gson().toJson(obj));
            first = false;
        }
        writer.write("], \"version\":");
        writer.write(String.valueOf(VERSION));
        writer.write("}");
        writer.flush();
    } finally {
        out.close();
    }
}
