/**
 * Merges attributes of two people such that the attributes from the second person
 * are added to the attributes of the first person. If any attributes have the same key
 * in both maps, their values are combined into a single attribute with the same key.
 *
 * @param personAttributes1 The attributes of the first person
 * @param personAttributes2 The attributes of the second person
 * @return A map containing the merged attributes
 */
@Override
protected Map<String, List<Object>> mergePersonAttributes(Map<String, List<Object>> personAttributes1,
                                                           Map<String, List<Object>> personAttributes2) {
    Map<String, List<Object>> mergedAttributes = new HashMap<>();

    // Add attributes from the first person to the merged map
    for (Map.Entry<String, List<Object>> entry : personAttributes1.entrySet()) {
        String key = entry.getKey();
        List<Object> value = entry.getValue();
        mergedAttributes.put(key, new ArrayList<>(value));
    }

    // Add attributes from the second person to the merged map
    for (Map.Entry<String, List<Object>> entry : personAttributes2.entrySet()) {
        String key = entry.getKey();
        List<Object> value = entry.getValue();
        if (mergedAttributes.containsKey(key)) {
            mergedAttributes.get(key).addAll(value);
        } else {
            mergedAttributes.put(key, new ArrayList<>(value));
        }
    }

    return mergedAttributes;
}
