public class SnapshotSaveAPI {

    //A Map to store export sequence numbers for each table and partition
    private static Map<String, Map<String, Integer>> exportSequenceNumbers = new HashMap<>();

    /**
     * Method to store the export sequence numbers for every table and partition
     * @param tableName the name of the table
     * @param partitionName the name of the partition
     * @param sequenceNumber the export sequence number to be stored
     */
    public static synchronized void startSnapshotting(String tableName, String partitionName, int sequenceNumber) {
        if (exportSequenceNumbers.containsKey(tableName)) {
            Map<String, Integer> partitionSequenceNumbers = exportSequenceNumbers.get(tableName);
            partitionSequenceNumbers.put(partitionName, sequenceNumber);
        } else {
            Map<String, Integer> partitionSequenceNumbers = new HashMap<>();
            partitionSequenceNumbers.put(partitionName, sequenceNumber);
            exportSequenceNumbers.put(tableName, partitionSequenceNumbers);
        }
    }

    /**
     * Method to retrieve the full set of export sequence numbers and reset the contents
     * @return the Map of export sequence numbers for each table and partition
     */
    public static synchronized Map<String, Map<String, Integer>> getExportSequenceNumbers() {
        Map<String, Map<String, Integer>> tempExportSequenceNumbers = new HashMap<>(exportSequenceNumbers);
        exportSequenceNumbers.clear();
        return tempExportSequenceNumbers;
    }
