public Matrix mmul(String name, Matrix other) {
    int[][] result = new int[this.matrix.length][other.matrix[0].length];
    for (int i = 0; i < this.matrix.length; i++) {
        for (int j = 0; j < other.matrix[0].length; j++) {
            for (int k = 0; k < other.matrix.length; k++) {
                result[i][j] += this.matrix[i][k] * other.matrix[k][j];
            }
        }
    }
    return new Matrix(name, result);
}
