public static Object getParameterValue(Class<?> parameterClass, String value, SimpleDateFormat sdf) throws Exception {
    if (parameterClass == String.class) {
        return value;
    } else if (parameterClass == Integer.class || parameterClass == int.class) {
        return Integer.parseInt(value);
    } else if (parameterClass == Long.class || parameterClass == long.class) {
        return Long.parseLong(value);
    } else if (parameterClass == Float.class || parameterClass == float.class) {
        return Float.parseFloat(value);
    } else if (parameterClass == Double.class || parameterClass == double.class) {
        return Double.parseDouble(value);
    } else if (parameterClass == Date.class) {
        return sdf.parse(value);
    } else {
        throw new Exception("Unsupported parameter class: " + parameterClass.getName());
    }
}
