public String signText(String text, KeyParameter aesKey) throws IllegalStateException, KeyCrypterException {
    if (this.getPrivKey() == null) {
        throw new IllegalStateException("ECKey does not have the private part");
    }
    if (this.isEncrypted() && aesKey == null) {
        throw new KeyCrypterException("ECKey is encrypted and no AESKey is provided");
    }
    ECKey.ECDSASignature signature = this.sign(Sha256Hash.of(text.getBytes()));
    byte[] sigData = new byte[65]; // R and S are 32 bytes each, plus 1 byte for the header
    sigData[0] = (byte) (signature.getR().toByteArray()[0] & 0x80); // ensure positive R value
    System.arraycopy(signature.getR().toByteArray(), 0, sigData, 33 - signature.getR().toByteArray().length, signature.getR().toByteArray().length);
    sigData[32] = (byte) (signature.getS().toByteArray()[0] & 0x80); // ensure positive S value
    System.arraycopy(signature.getS().toByteArray(), 0, sigData, 65 - signature.getS().toByteArray().length, signature.getS().toByteArray().length);
    if (this.isCompressed()) {
        sigData[0] |= 0x20; // set first byte to 0x20 | (compressed ? 0x04 : 0x00) | (hashtype & 0x03);
    } else {
        sigData[0] |= 0x21;
    }
    if (this.getPubKeyHash() != null) {
        sigData[0] |= 0x08; // set fourth lowest bit to 1 if address is a P2SH address
    }
    byte[] sigHash = Sha256Hash.of(Sha256Hash.of("Bitcoin Signed Message:\n".getBytes()), Sha256Hash.of((sigData.length + text.getBytes().length) + ":".getBytes()), sigData, text.getBytes()).getBytes();
    if (this.isEncrypted()) {
        byte[] decrypted = this.getKeyCrypter().decrypt(this.getEncryptedPrivateKey(), aesKey);
        ECKey ecKey = ECKey.fromPrivate(decrypted, this.isCompressed());
        return Base64.encodeAsString(ecKey.sign(sigHash).encodeToDER());
    } else {
        return Base64.encodeAsString(this.sign(sigHash).encodeToDER());
    }
}
