public Client getClient(Configuration configuration, ClientConsumerType type, int poolSize) throws Exception{
    Client client;
    switch(type){
        case ACTIVE:
            client = new ActiveClient(configuration, poolSize);
            break;
        case PASSIVE:
            client = new PassiveClient(configuration, poolSize);
            break;
        default:
            throw new IllegalArgumentException("Invalid client type: " + type);
    }
    if(client == null){
        throw new Exception("Failed to create client");
    }
    return client;
}
