public Bitmap decodeAndResizeBitmap(byte[] picture, int reqWidth, int reqHeight) {
    // decode the input byte array into a Bitmap object
    Bitmap bitmap = BitmapFactory.decodeByteArray(picture, 0, picture.length);

    // calculate the scaling factors to resize the bitmap
    float scaleX = (float) reqWidth / bitmap.getWidth();
    float scaleY = (float) reqHeight / bitmap.getHeight();
    float scaleFactor = Math.min(scaleX, scaleY);

    // create a Matrix to apply the scaling factors
    Matrix matrix = new Matrix();
    matrix.postScale(scaleFactor, scaleFactor);

    // create a new resized Bitmap using the Matrix
    Bitmap resizedBitmap = Bitmap.createBitmap(bitmap, 0, 0, bitmap.getWidth(), bitmap.getHeight(), matrix, true);

    // recycle the original bitmap to free up memory
    bitmap.recycle();

    // return the new resized Bitmap
    return resizedBitmap;
}
