public List<List<Double>> normalizeData(List<String> schema, List<List<Double>> data, double min, double max) {
    List<List<Double>> normalizedData = new ArrayList<>();

    for (int i = 0; i < schema.size(); i++) {

        // Get the i-th column
        List<Double> column = new ArrayList<>();
        for (List<Double> row : data) {
            column.add(row.get(i));
        }

        // Get the min and max values of the column
        double columnMin = Collections.min(column);
        double columnMax = Collections.max(column);

        // Normalize all values of the column
        List<Double> normalizedColumn = new ArrayList<>();
        for (Double value : column) {
            double normalizedValue = (value - columnMin) / (columnMax - columnMin) * (max - min) + min;
            normalizedColumn.add(normalizedValue);
        }

        // Add the normalized column to the normalized data
        normalizedData.add(normalizedColumn);
    }

    // Transpose the normalized data to return it row by row
    List<List<Double>> transposedData = new ArrayList<>();
    for (int i = 0; i < data.size(); i++) {
        List<Double> row = new ArrayList<>();
        for (List<Double> column : normalizedData) {
            row.add(column.get(i));
        }
        transposedData.add(row);
    }

    return transposedData;
}
