public String bytesToHex(byte[] bytes, int size) {
    StringBuilder hexString = new StringBuilder();
    for (int i = 0; i < size; i++) {
        String hex = Integer.toHexString(0xFF & bytes[i]);
        if (hex.length() == 1) {
            hexString.append('0');
        }
        hexString.append(hex);
    }
    return hexString.toString();
}
