public void watchOverPod(String podName, int nAwaitTimeout, Logger log) throws InterruptedException {
    boolean isReady = false;
    long maxWaitTime = System.currentTimeMillis() + (nAwaitTimeout * 1000);
    while (System.currentTimeMillis() < maxWaitTime) {
        List<Pod> pods = kubernetesClient.pods().withName(podName).list().getItems();
        if (pods.size() > 0) {
            Pod pod = pods.get(0);
            PodStatus podStatus = pod.getStatus();
            if (podStatus.getPhase().equalsIgnoreCase("Running")) {
                isReady = true;
                break;
            }
        }
        Thread.sleep(5000);
    }
    if (!isReady) {
        log.error("Pod " + podName + " did not become ready within " + nAwaitTimeout + " seconds");
