import com.sun.javadoc.ClassDoc;
import com.sun.javadoc.FieldDoc;
import com.sun.javadoc.SerialFieldTag;

import java.util.ArrayList;
import java.util.List;

public class ClassSymbol {
    private List<FieldDoc> fields;

    public ClassSymbol() {
        fields = new ArrayList<>();
    }

    public void addField(FieldDoc field) {
        fields.add(field);
    }

    public FieldDoc[] fields() {
        FieldDoc[] fieldsArray = new FieldDoc[fields.size()];
        for (int i = 0; i < fieldsArray.length; i++) {
            fieldsArray[i] = fields.get(i);
        }
        return fieldsArray;
    }

    /**
     * Compute default Serializable fields from all members of ClassSymbol.
     * Since the fields of ClassDocImpl might not contain private or package
     * accessible fields, must walk over all members of ClassSymbol.
     */
    public SerialFieldTag[] serializableFields() {
        List<SerialFieldTag> serializableFields = new ArrayList<>();
        for (FieldDoc field : fields) {
            if (field.isSerializable()) {
                String name = field.name();
                String type = field.type().qualifiedTypeName();
                String doc = field.commentText();

                SerialFieldTag serialField = new SerialFieldTag(name, type, doc);
                serializableFields.add(serialField);
            }
        }
        return serializableFields.toArray(new SerialFieldTag[serializableFields.size()]);
    }
}
