public Object[] parseMethod(String method) {
    // split the method string by parentheses
    String[] parts = method.split("\\(");
    // check if there is a parameter in the method
    if (parts.length == 2) {
        // remove the closing parentheses
        String param = parts[1].replace(")", "");
        // split the parameter string by commas
        String[] params = param.split(",");
        // return the params array
        return params;
    } else {
        // return an empty array if there is no parameter
        return new Object[0];
    }
}
