import java.awt.Rectangle;
import javax.swing.JLayeredPane;

public void renderComponentsInLayers(JLayeredPane layeredPane, Rectangle bounds) {
    int layerCount = layeredPane.getLayerCount();
    for (int i = 0; i < layerCount; i++) {
        int layer = layeredPane.getLayer(i);
        for (java.awt.Component component : layeredPane.getComponentsInLayer(layer)) {
            Rectangle componentBounds = component.getBounds();
            if (componentBounds.intersects(bounds)) {
                component.paint(layeredPane.getGraphics());
            }
        }
    }
}
