public byte[] quoteIfNecessary(byte[] term) {
    String termString = new String(term, StandardCharsets.UTF_8);
    String quotedTerm = quote(termString);
    if (quotedTerm.equals(termString)) {
        return term;
    } else {
        return quotedTerm.getBytes(StandardCharsets.UTF_8);
    }
}

private String quote(String term) {
    if (needsQuote(term)) {
        return "\"" + term + "\"";
    } else {
        return term;
    }
}

private boolean needsQuote(String term) {
    return term.contains(" ") || term.contains("\t") || term.contains(",");
}
