public Index createPermutedIndex(int[] dims) {
    int numDims = dims.length;
    int[] permutedDims = new int[numDims];
    System.arraycopy(dims, 0, permutedDims, 0, numDims);

    for (int i = 0; i < numDims; i++) {
        permutedDims[dims[i]] = i;
    }

    try {
        return new Index(permutedDims);
    } catch (InvalidIndexException e) {
        System.out.println("Error: Invalid index dimensions");
        return null;
    }
}
