public byte[] loadImportSection(String filePath) throws IOException, IllegalStateException {
    File inputFile = new File(filePath);
    if (!inputFile.exists()) {
        throw new IllegalStateException("File does not exist");
    }
    if (!inputFile.canRead()) {
        throw new IllegalStateException("File cannot be read");
    }

    byte[] importSection = null;
    try (RandomAccessFile raf = new RandomAccessFile(inputFile, "r")) {
        // Read the PE offset
        raf.seek(0x3C);
        int peOffset = raf.readInt();

        // Go to the import section
        raf.seek(peOffset + 0x80);
        int size = raf.readInt();

        importSection = new byte[size];

        // Read the import section
        raf.read(importSection);
    }

    if (importSection == null) {
        throw new IllegalStateException("Unable to load import section");
    }

    return importSection;
}
