            throw new IOException("Empty or null string is not a valid file");
        }
        File file = new File(_file);
        if (!file.exists()) {
            throw new FileNotFoundException("No such file: " + _file);
        } else if (!file.isFile()) {
            throw new IOException("Not a file: " + _file);
        } else if (!file.canRead()) {
