public void appendLengthInfo(String bits) {
    int length = bits.length();
    String lengthBits = Integer.toBinaryString(length);
    // append 0's to the left of the lengthBits string as needed
    while (lengthBits.length() < 8) {
        lengthBits = "0" + lengthBits;
    }
    bits += lengthBits;
}
