public String detectInsertType(String method) {
    if (method.equals("GET")){
        return "Read";
    }
    else if (method.equals("POST")){
        return "Create";
    }
    else if (method.equals("PUT")){
        return "Replace";
    }
    else if (method.equals("PATCH")){
        return "Update";
    }
    else if (method.equals("DELETE")){
        return "Delete";
    }
    else{
        return "Invalid method";
    }
}
