import com.google.inject.Module;
import com.google.inject.util.Modules;

import java.io.FileInputStream;
import java.io.IOException;
import java.util.Properties;

public static Module loadModulesFromPropertiesFile(String propertiesFile, Module jFunkModule) throws IOException, ClassNotFoundException, IllegalAccessException, InstantiationException {
    Properties properties = new Properties();
    try (FileInputStream fileInputStream = new FileInputStream(propertiesFile)) {
        properties.load(fileInputStream);
    }

    Module combinedModule = jFunkModule;

    for (String propertyName : properties.stringPropertyNames()) {
        if (propertyName.startsWith("module.")) {
            String moduleName = properties.getProperty(propertyName);
            Module module = (Module) Class.forName(moduleName).newInstance();
            combinedModule = Modules.override(combinedModule).with(module);
        }
    }

    return combinedModule;
}
