public String determineTaskNotesRepresentation(Task task, TaskData data, ExtendedTaskData taskExtData, TaskVarData taskVarData) {
    if (taskExtData != null && taskExtData.extendedAttributes != null) {
        for (ExtendedAttribute ea : taskExtData.extendedAttributes) {
            if (ea.fieldId == ExtendedAttributeTask.NoteField) {
                return "extended task note representation used";
            }
        }
    }
    if (taskVarData != null && taskVarData.varData != null) {
        for (VariableData vd : taskVarData.varData) {
            if (vd.fieldId == VarField.NoteField) {
                return "task var note representation used";
            }
        }
    }
    if (data != null && data.text1 != null && data.text1.startsWith("<![CDATA[") && data.text1.endsWith("]]>")) {
        return "XML task note representation used";
    }
    if (task.notes != null) {
        return "legacy task note representation used";
    }
    return "no task note representation found";
}
