public Observable<PagedList<AzureFirewallFqdnTagInner>> getAzureFirewallFqdnTags(String subscriptionId) throws IllegalArgumentException {
  if(subscriptionId == null || subscriptionId.isEmpty()) {
    throw new IllegalArgumentException("Subscription ID cannot be null or empty.");
  }
  String resourceType = "Microsoft.Network/azureFirewalls/FqdnTags";
  String apiVersion = "2021-02-01";
  return azureResourceManager.resourceGroups().list()
      .flatMapIterable(ResourceGroups::values)
      .flatMap(resourceGroup -> azureResourceManager.genericResources().listByResourceGroupAsync(resourceGroup.name()))
      .flatMapIterable(GenericResource::values)
      .filter(resource -> {
        String type = resource.type();
        return type != null && type.equalsIgnoreCase(resourceType);
      })
      .concatMap(resource -> azureResourceManager.genericResources().inner().list(
          subscriptionId, 
          resource.resourceGroupName(), 
          "", 
          resourceType, 
          resource.name(), 
          apiVersion
      ).map(PagedList::new)
      .toObservable())
      .flatMapIterable(PagedList::items);
}
