public Set<String> generateForegroundEdgeHashSet(int[][] pixels) {
    Set<String> foregroundEdgeHashSet = new HashSet<>();
    int rows = pixels.length;
    int columns = pixels[0].length;

    for(int i = 1; i < rows - 1; i++) {
        for(int j = 1; j < columns - 1; j++) {
            if(pixels[i][j] == 1) {
                if(pixels[i - 1][j - 1] == 0 || pixels[i - 1][j] == 0 || pixels[i - 1][j + 1] == 0 ||
                    pixels[i][j - 1] == 0 || pixels[i][j + 1] == 0 ||
                    pixels[i + 1][j - 1] == 0 || pixels[i + 1][j] == 0 || pixels[i + 1][j + 1] == 0) {
                    foregroundEdgeHashSet.add(i + "," + j);
                }
            }
        }
    }

    return foregroundEdgeHashSet;
}
