public static <T> T[] toPrimitiveArray(Class<T> type, Object[] src, int srcPos, int len) {
    if (type == null || src == null) {
        throw new NullPointerException();
    }
    if (srcPos < 0 || len < 0 || srcPos + len > src.length) {
        throw new IndexOutOfBoundsException();
    }
    final T[] dest = (T[]) Array.newInstance(type, len);
    int destPos = 0;
    for (int i = srcPos, last = srcPos + len; i < last; i++) {
        Array.set(dest, destPos++, type.cast(src[i]));
    }
    return dest;
}
