public String getGlobalSSLProperty(String name) {
    String value = null;
    try (InputStream inputStream = new FileInputStream("ssl.client.props")) {
        Properties properties = new Properties();
        properties.load(inputStream);
        for (String propName : properties.stringPropertyNames()) {
            if (propName.startsWith("com.ibm.security.")) {
                String propValue = properties.getProperty(propName);
                if (propName.equals(name)) {
                    value = propValue;
                }
            }
        }
    } catch (IOException e) {
        e.printStackTrace();
        return null;
    }
    return value;
}
