import java.util.List;
import jdk.jshell.JShell;
import jdk.jshell.MethodSnippet;
import jdk.jshell.Snippet;

public List<MethodSnippet> getActiveMethodSnippets(){
    JShell jshell = JShell.create();
    List<Snippet> snippets = jshell.snippets();
    List<MethodSnippet> activeMethodSnippets = snippets
        .stream()
        .filter(s -> s.kind() == Snippet.Kind.METHOD)
        .filter(s -> s.status().isActive())
        .map(s -> (MethodSnippet) s)
        .collect(Collectors.toList());
    return activeMethodSnippets;
}
