public void fetchLogAsStreamAndFollow() {
    try {
        // Open the log file
        Path logFile = Paths.get("path/to/log/file.log");
        BufferedReader reader = Files.newBufferedReader(logFile, StandardCharsets.UTF_8);

        // Create a new thread to follow the log file stream asynchronously
        Thread followThread = new Thread(() -> {
            try {
                // Continuously monitor the log file for new data
                while (true) {
                    String line = reader.readLine();
                    if (line == null) {
                        Thread.sleep(1000); // Wait a second before checking for more data
                    } else {
                        // Do something with the log data (e.g. print to console)
                        System.out.println(line);
                    }
                }
            } catch (IOException e) {
                e.printStackTrace(); // Deal with exceptions appropriately
            } catch (InterruptedException e) {
                return; // Exit the thread if interrupted
            }
        });

        // Start the thread and begin monitoring the log file stream
        followThread.start();
    } catch (IOException e) {
        e.printStackTrace(); // Deal with exceptions appropriately
    }
}
