public static double[] centroidFromRelation(int[] dims, double[][] relation) {
    int n = relation.length;
    double[] centroid = new double[dims.length];
    for (int i = 0; i < dims.length; i++) {
        double sum = 0;
        for (int j = 0; j < n; j++) {
            sum += relation[j][dims[i]];
        }
        centroid[i] = sum / n;
    }
    return centroid;
}
