public static void writeFromReadableToSink(Readable readable, Sink sink) throws IOException {
    try (BufferedReader reader = new BufferedReader(readable)) {
        CharBuffer buffer = CharBuffer.allocate(8192);
        while (reader.read(buffer) != -1) {
            buffer.flip();
            sink.write(buffer);
            buffer.clear();
        }
    }
}
