public Credentials getCredentials(AuthScope authscope) {
    if (authscope == null) {
        throw new IllegalArgumentException("AuthScope may not be null");
    }
    Credentials localcreds = null;
    List<AuthScope> authprefs = new ArrayList<AuthScope>();
    for (AuthScope current : this.authPrefs) {
        if (current.match(authscope)) {
            authprefs.add(current);
        }
    }
    if (!authprefs.isEmpty()) {
        Collections.sort(authprefs);
        AuthScope bestmatch = authprefs.get(0);
        localcreds = this.credMap.get(bestmatch);
        if (localcreds == null) {
            localcreds = this.credMap.get(AuthScope.ANY);
        }
    } else {
        localcreds = this.credMap.get(AuthScope.ANY);
    }
    if (localcreds != null) {
        this.credentialsProvider.setCredentials(authscope, localcreds);
    }
    return localcreds;
}
