public String createStatusTag(ContainerResponse response) {
    String status = response.getStatus();
    String statusTag;
    if (status.startsWith("2")) {
        statusTag = "OK";
    } else if (status.startsWith("3")) {
        statusTag = "REDIRECT";
    } else if (status.startsWith("4")) {
        statusTag = "CLIENT ERROR";
    } else if (status.startsWith("5")) {
        statusTag = "SERVER ERROR";
    } else {
        statusTag = "UNKNOWN";
    }
    return "<status>" + statusTag + "</status>";
}
