public void runExample(AdManagerServices adManagerServices, AdManagerSession session, long labelId) throws ApiException, RemoteException {
   CreativeWrapperServiceInterface creativeWrapperService = adManagerServices.get(session, CreativeWrapperServiceInterface.class);

   // Create a statement to select the creative wrappers.
   StatementBuilder statementBuilder = new StatementBuilder()
       .where("id = :id")
       .orderBy("id ASC")
       .limit(1)
       .withBindVariableValue("id", labelId);

   // Retrieve a small amount of creative wrappers at a time, paging through until all
   // creative wrappers have been retrieved.
   int totalResultSetSize = 0;
   do {
     CreativeWrapperPage page =
         creativeWrapperService.getCreativeWrappersByStatement(statementBuilder.toStatement());

     if (page.getResults() != null) {
       // Print out some information for each creative wrapper.
       totalResultSetSize = page.getTotalResultSetSize();
       int i = page.getStartIndex();
       for (CreativeWrapper label : page.getResults()) {
         System.out.printf(
             "%d) Creative wrapper with ID %d, and status '%s' will be deactivated.%n", i++,
             label.getId(), label.getStatus());
       }

       // Modify statement for next iteration.
       statementBuilder.increaseOffsetBy(StatementBuilder.SUGGESTED_PAGE_LIMIT);
     }
   } while (statementBuilder.getOffset() < totalResultSetSize);

   System.out.printf("Number of creative wrappers to be deactivated: %d%n", totalResultSetSize);

   // Update statement to deactivate creative wrappers.
   statementBuilder.removeLimitAndOffset().where("status = :status").withBindVariableValue("status", "ACTIVE");

   // Deactivate creative wrappers on server.
   int numCreativesDeactivated =
       creativeWrapperService.performCreativeWrapperAction(
           new DeactivateCreativeWrappers(statementBuilder.toStatement()));

   System.out.printf("Number of creative wrappers deactivated: %d%n", numCreativesDeactivated);
 }
