public void deleteEntity(Entity entity) {
    Transaction txn = datastore.beginTransaction();
    Key entityKey = entity.getKey();
    try {
        datastore.delete(entityKey);
        txn.commit();
    } finally {
        if (txn.isActive()) {
            txn.rollback();
        }
    }
}
