import com.flowpowered.caustic.api.gl.Texture;

public ByteBuffer setTextureImageData(int[] pixels, int width, int height, Texture.Format format) {
    ByteBuffer buffer = ByteBuffer.allocateDirect(pixels.length * Integer.BYTES);
    switch (format) {
        case RGBA:
            for (int pixel : pixels) {
                buffer.putInt((pixel << 8) | ((pixel >> 24) & 0xFF));
            }
            break;
        case RGB:
            for (int pixel : pixels) {
                buffer.putInt((pixel << 8) | 0xFF);
            }
            break;
        case ALPHA:
            for (int pixel : pixels) {
                buffer.put((byte) (pixel >> 24));
            }
            break;
        case LUMINANCE_ALPHA:
            for (int pixel : pixels) {
                buffer.putInt(((pixel & 0xFF) << 8) | ((pixel >> 24) & 0xFF));
            }
            break;
        case LUMINANCE:
            for (int pixel : pixels) {
                buffer.put((byte) pixel);
            }
            break;
    }
    buffer.flip();
    return buffer;
}
