import freemarker.template.Configuration;
import freemarker.template.Template;
import freemarker.template.TemplateException;
import java.io.IOException;
import java.io.StringWriter;
import java.util.HashMap;
import java.util.Map;

public String processTemplate(String templateName, Map<String, Object> data) throws IOException, TemplateException {

    Configuration configuration = new Configuration(Configuration.VERSION_2_3_0);  // create configuration
    configuration.setClassForTemplateLoading(this.getClass(), "/templates");   // set folder path where templates files are saved

    Template template = configuration.getTemplate(templateName + ".ftl");   // get template

    StringWriter writer = new StringWriter();   // create instance of StringWriter
    template.process(data, writer);   // fill template with data

    return writer.toString();   // return processed template as string
}
