public static Formula computeBackbone(Formula formula) {
    Solver solver = MiniSat.newSolver();
    try {
        // Add the formula to the solver
        solver.add(formula);

        // Solve the formula
        IConstr result = solver.solve();

        // If the result is null, the formula is UNSAT
        if (result == null) {
            return null;
        }

        // Create a new formula with the backbone literals and return it
        Formula backbone = new Formula();
        int[] model = solver.model();
        for (int lit : model) {
            if (solver.modelValue(lit) == lbool.TRUE) {
                backbone.addLiteral(lit);
            }
        }
        return backbone;
    } catch (ContradictionException e) {
        return null;
    }
}
