import java.util.*;

public Map<String, Set<String>> collectSourcesAndTargets(BinaryInteraction[] inters) {
    Map<String, Set<String>> map = new HashMap<>();

    for (BinaryInteraction inter : inters) {
        String primaryId = inter.getPrimaryId();
        String source = inter.getSource();
        String target = inter.getTarget();

        if (!map.containsKey(primaryId)) {
            Set<String> sourceTargetSet = new HashSet<>();
            sourceTargetSet.add(source);
            sourceTargetSet.add(target);
            map.put(primaryId, sourceTargetSet);
        } else {
            Set<String> sourceTargetSet = map.get(primaryId);
            sourceTargetSet.add(source);
            sourceTargetSet.add(target);
        }
    }

    return map;
}
