                    portletRenderExecutionWorker);
            try {
                portletRenderExecutionWorker.get(0);
            } catch (Exception e) {

            }
        }
        if (!portletRenderExecutionWorker.isComplete()) {
            cancelWorker(request, portletRenderExecutionWorker);
        }
