        Random rand = new Random();
        int votingNumber = rand.nextInt(999999999 - 100000000 + 1) + 100000000;
        String[] contestants = {"Contestant 1", "Contestant 2", "Contestant 3", "Contestant 4", "Contestant 5", "Contestant 6", "Contestant 7", "Contestant 8", "Contestant 9", "Contestant 10"};
