/**
 * Returns an array containing the elements in the given array that are at the specified indexes.
 *
 * @param arr the input array
 * @param indexes the indexes to get elements from
 * @return an array containing the elements in the given array at the specified indexes
 * @throws IndexOutOfBoundsException if any index is out of the range of the input array
 * @since 1.4.0
 */
public static <T> T[] getElementsAtIndices(T[] arr, int[] indexes) throws IndexOutOfBoundsException {
    T[] result = (T[]) new Object[indexes.length];
    for (int i = 0; i < indexes.length; i++) {
        int index = indexes[i];
        if (index < 0 || index >= arr.length) {
            throw new IndexOutOfBoundsException("Index " + index + " is out of bounds");
        }
        result[i] = arr[index];
    }
    return result;
}
