public int getNDimensionalHistogramIndex(int[] coordinate) {
    int dimensions = coordinate.length;
    int[] multipliers = new int[dimensions];
    multipliers[dimensions - 1] = 1;

    // Calculate the multipliers
    for (int i = dimensions - 2; i >= 0; i--) {
        multipliers[i] = multipliers[i + 1] * histogram[i + 1].getBucketCount();
    }

    // Calculate index
    int index = 0;

    for (int i = 0; i < dimensions; i++) {
        index += coordinate[i] * multipliers[i];
    }

    return index;
}
