        // Example usage of createFunctionType()
        Method exampleMethod = CreateFunctionType.class.getDeclaredMethod("exampleMethod", String.class, int.class, String[].class);
        String functionType = createFunctionType(exampleMethod.getReturnType(), exampleMethod.getParameterTypes());
        System.out.println(functionType);
    }

    private static String createFunctionType(Class<?> returnType, Class<?>... parameterTypes) {
        StringBuilder sb = new StringBuilder();
        sb.append("(");
        for (int i = 0; i < parameterTypes.length - 1; i++) {
            sb.append(parameterTypes[i].getName()).append(",");
        }
        sb.append(parameterTypes[parameterTypes.length - 1].getName()).append("...");
        sb.append(") -> ").append(returnType.getName());
        return sb.toString();
    }

    private static void exampleMethod(String str, int num, String... varargs) {
        // empty method
    }
}
