public static String convertFlagsToModifiers(String flags) {
    String modifiers = "";
    if (flags.contains("i")) {
        modifiers += "i";
    }
    if (flags.contains("m")) {
        modifiers += "m";
    }
    if (flags.contains("s")) {
        modifiers += "s";
    }
    if (flags.contains("u")) {
        modifiers += "u";
    }
    if (flags.contains("x")) {
        modifiers += "x";
    }
    if (!modifiers.equals(flags)) {
        throw new IllegalArgumentException("Some flags couldn't be recognized");
    }
    return modifiers;
}
