public void deleteUserLogs(String serviceName, String id, String login) {
    String url = String.format("/hosting/web/%s/ownLogs/%s/userLogs/%s", serviceName, id, login);
    HttpDelete request = new HttpDelete(url);

    try (CloseableHttpClient httpClient = HttpClientBuilder.create().build();
         CloseableHttpResponse response = httpClient.execute(request)) {

        if (response.getStatusLine().getStatusCode() != HttpStatus.SC_OK) {
            throw new RuntimeException("Failed to delete userLogs. Response code: " + response.getStatusLine().getStatusCode());
        }

    } catch (IOException e) {
        throw new RuntimeException("Failed to delete userLogs", e);
    }
}
