public List<GridFSFile> findFiles(String query, String sort) throws MongoException {
    List<GridFSFile> files = new ArrayList<>();
    // create query object
    BasicDBObject criteria = new BasicDBObject();
    criteria.put("filename", Pattern.compile(query));
    // create sort object
    BasicDBObject sortOrder = new BasicDBObject(sort, 1);
    // find files in gridfs
    try {
        MongoDatabase db = mongoClient.getDatabase(databaseName);
        GridFSBucket gridFSBucket = GridFSBuckets.create(db, bucketName);
        MongoCursor<GridFSFile> cursor = gridFSBucket.find(criteria).sort(sortOrder).iterator();
        while (cursor.hasNext()) {
            files.add(cursor.next());
        }
    } catch (MongoException ex) {
        throw new MongoException("Failed to find files in GridFS", ex);
    }
    return files;
}
