public static void calculateMinMaxBoundaries(int[][] structure) {
    int minRow = structure.length;
    int maxRow = 0;
    int minCol = structure[0].length;
    int maxCol = 0;

    for (int row = 0; row < structure.length; row++) {
        for (int col = 0; col < structure[0].length; col++) {
            if (structure[row][col] == 1) {
                if (row < minRow) {
                    minRow = row;
                }
                if (row > maxRow) {
                    maxRow = row;
                }
                if (col < minCol) {
                    minCol = col;
                }
                if (col > maxCol) {
                    maxCol = col;
                }
            }
        }
    }
    System.out.println("Minimum boundaries: (" + minRow + "," + minCol + ")");
    System.out.println("Maximum boundaries: (" + maxRow + "," + maxCol + ")");
}
