@Override
public void writeCookieValue(CookieValue cookieValue) {
    HttpServletResponse response = cookieValue.getResponse();
    String cookieName = cookieValue.getCookieName();
    String cookieValueStr = cookieValue.getCookieValue();
    Boolean httpOnly = cookieValue.isHttpOnly();
    Integer maxAge = cookieValue.getMaxAge();
    String path = cookieValue.getPath();
    String domain = cookieValue.getDomain();
    Boolean secure = cookieValue.isSecure();
    Cookie cookie = new Cookie(cookieName, cookieValueStr);
    cookie.setHttpOnly(httpOnly);
    if (maxAge != null) {
        cookie.setMaxAge(maxAge);
    }
    if (path != null) {
        cookie.setPath(path);
    }
    if (domain != null) {
        cookie.setDomain(domain);
    }
    if (secure != null) {
        cookie.setSecure(secure);
    }
