import java.util.List;
import java.util.ArrayList;
import org.apache.hadoop.hbase.HColumnDescriptor;

public List<String> unknownConfigurationKeys(HColumnDescriptor columnDescriptor) {
    String[] knownKeys = {"COMPRESSION", "DATA_BLOCK_ENCODING", "BLOOMFILTER", "VERSIONS", "MIN_VERSIONS", 
                          "KEEP_DELETED_CELLS", "DATA_BLOCK_ENCODING", "TTL", "BLOCKSIZE", "IN_MEMORY", 
                          "BLOCKCACHE", "BLOCKSIZE", "REPLICATION_SCOPE"};
    List<String> unknownKeys = new ArrayList<String>();
    for(String key : columnDescriptor.getConfiguration().keySet()) {
        boolean known = false;
        for(String knownKey : knownKeys) {
            if(key.equalsIgnoreCase(knownKey)) {
                known = true;
                break;
            }
        }
        if(!known) {
            unknownKeys.add(key);
        }
    }
    return unknownKeys;
}
