public String printSearchPath(List<String> path, int size) {
    StringBuilder sb = new StringBuilder();
    sb.append("Transition Path:\n");
    for (int i = 0; i < path.size() - 1; i++) {
        sb.append("Move ").append(i + 1).append(": \n");
        sb.append(getPrintablePuzzleState(path.get(i), size));
        sb.append("->\n");
        sb.append(getPrintablePuzzleState(path.get(i+1), size));
        sb.append("\n");
    }
    return sb.toString();
}

private String getPrintablePuzzleState(String state, int size) {
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < state.length(); i++) {
        sb.append(state.charAt(i)).append(" ");
        if ((i + 1) % size == 0) {
            sb.append("\n");
        }
    }
    return sb.toString();
}
