public static String getFilenameFromResponse(Response response) {
    String contentDispositionHeader = response.getHeaderString("Content-Disposition");
    if (contentDispositionHeader != null) {
        String[] tokens = contentDispositionHeader.split(";");
        for (String token : tokens) {
            token = token.trim();
            if (token.startsWith("filename=")) {
                return token.substring("filename=".length()).trim();
            }
        }
    }
    return null;
}
