public static String escapeXml(String pValue) {
    if (pValue == null) {
        return null;
    }
    StringBuilder builder = new StringBuilder();
    for (int i = 0; i < pValue.length(); i++) {
        char c = pValue.charAt(i);
        switch (c) {
            case '<':
                builder.append("&lt;");
                break;
            case '>':
                builder.append("&gt;");
                break;
            case '&':
                builder.append("&amp;");
                break;
            default:
                builder.append(c);
        }
    }
    return builder.toString();
}
