import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import net.opentsdb.core.TSDB;
import net.opentsdb.utils.UniqueId;

public byte[] resolveTags(TSDB tsdb, Map<String, String> tags) throws NoSuchUniqueName {
    ArrayList<byte[]> out = new ArrayList<byte[]>(tags.size() * 2);
    for (Map.Entry<String, String> entry: tags.entrySet()) {
        UniqueId tag = tsdb.getUniqueId(entry.getKey(), entry.getValue(), true);
        ByteBuffer buffer = ByteBuffer.allocate(tag.idLength() + tag.nameLength());
        buffer.put(tag.id());
        if (tag.nameLength() > 0) {
            buffer.put(tag.name());
        }
        out.add(buffer.array());
    }

    Collections.sort(out, new Comparator<byte[]>() {
        @Override
        public int compare(byte[] o1, byte[] o2) {
            ByteBuffer b1 = ByteBuffer.wrap(o1);
            ByteBuffer b2 = ByteBuffer.wrap(o2);
            int i = b1.compareTo(b2);
            if (i == 0) {
                i = Integer.compare(o1.length, o2.length);
                if (i == 0) {
                    i = ByteBuffer.wrap(o1).compareTo(ByteBuffer.wrap(o2));
                }
            }
            return i;
        }
    });

    int size = 0;
    for (byte[] b : out) {
        size += b.length;
    }

    byte[] sortedTags = new byte[size];
    ByteBuffer buffer = ByteBuffer.wrap(sortedTags);

    for (byte[] b : out) {
        buffer.put(b);
    }
    return sortedTags;
}
