public static int getIntersectionSize(int[] px, int[] py) {
        int p1 = 0, p2 = 0, intersection = 0;

        while (p1 < px.length && p2 < py.length) {
            if (px[p1] == py[p2]) {
                intersection++;
                p1++;
                p2++;
            } else if (px[p1] < py[p2]) {
                p1++;
            } else {
                p2++;
            }
        }

        return intersection;
    }
