@Override
protected Criterion and(Part part, Object value, Iterator<Object> iterator) {
    String property = part.getProperty().toDotPath(alias);
    Criteria condition;
    switch (part.getType()) {
        case SIMPLE_PROPERTY:
            condition = Restrictions.eq(property, value);
            break;
        case NEGATING_SIMPLE_PROPERTY:
            condition = Restrictions.ne(property, value);
            break;
        case LIKE:
            condition = Restrictions.like(property, value.toString(), MatchMode.ANYWHERE);
            break;
        case CONTAINING:
            condition = Restrictions.like(property, value.toString(), MatchMode.ANYWHERE);
            break;
        case NOT_LIKE:
            condition = Restrictions.not(Restrictions.like(property, value));
            break;
        case NOT_CONTAINING:
            condition = Restrictions.not(Restrictions.like(property, value.toString(), MatchMode.ANYWHERE));
            break;
        case GREATER_THAN:
            condition = Restrictions.gt(property, value);
            break;
        case GREATER_THAN_EQUAL:
            condition = Restrictions.ge(property, value);
            break;
        case LESS_THAN:
            condition = Restrictions.lt(property, value);
            break;
        case LESS_THAN_EQUAL:
            condition = Restrictions.le(property, value);
            break;
        case BETWEEN:
            Object[] range = toArray(value);
            condition = Restrictions.between(property, range[0], range[1]);
            break;
        case IN:
            condition = Restrictions.in(property, (Collection<?>) value);
            break;
        case NOT_IN:
            condition = Restrictions.not(Restrictions.in(property, (Collection<?>) value));
            break;
        case TRUE:
            condition = Restrictions.eq(property, true);
            break;
        case FALSE:
            condition = Restrictions.eq(property, false);
            break;
        case IS_NULL:
            condition = Restrictions.isNull(property);
            break;
        case IS_NOT_NULL:
            condition = Restrictions.isNotNull(property);
            break;
        case EXISTS:
            DetachedCriteria subquery = (DetachedCriteria) value;
            subquery.setResultTransformer(CriteriaSpecification.DISTINCT_ROOT_ENTITY);
            condition = Subqueries.exists(subquery);
            break;
        default:
            throw new IllegalArgumentException("Unsupported keyword!" + part.getType());
    }
    return new Criterion(condition, negate);
