public ArrayStructureBB deepCopyToByteBuffer(ArrayStructure as, ByteOrder bo, boolean canonical) {
    int size = as.getSize();

    ByteBuffer bb = ByteBuffer.allocate(size * as.getSizeOf());
    if (bo != null) {
        bb.order(bo);
    }

    for (int i = 0; i < size; i++) {
        int j = i * as.getSizeOf();
        for (int k = 0; k < as.getStructureMembers().size(); k++) {
            StructureMembers.Member m = as.getStructureMembers().getMember(k);
            Object value = as.getArray(m).getObject(i);
            try {
                m.getDataType().convert(value, bb, j + m.getDataType().getSize() * k);
            } catch (IOException e) {
                throw new IllegalStateException(e);
            }
        }
    }

    bb.rewind();
    return new ArrayStructureBB(as.getStructureMembers(), as.getShape(), bb, 0, canonical);
}
