public void buildNestedClassesSummary(Element node, Content memberSummaryTree) {
    NodeList classes = node.getElementsByTagName("class");
    for (int i = 0; i < classes.getLength(); i++) {
        Element classElement = (Element) classes.item(i);
        if (classElement.getAttribute("nesting").equals("nested")) {
            String className = classElement.getAttribute("name");
            Content nestedClassLink = new Link(new ClassDocCatalog().getClassDoc(className),
                                               new StringContent(className));
            memberSummaryTree.addContent(new HtmlTree(HtmlTag.LI, nestedClassLink));
        }
    }
}
