public Dimensions computeDef(String propName) {
    int leftBracketIndex = propName.indexOf('[');
    int rightBracketIndex = propName.indexOf(']');
    String valName = propName.substring(0, leftBracketIndex);
    String methodCalls = propName.substring(leftBracketIndex+1, rightBracketIndex);
    String[] calls = methodCalls.split("\\.");
    double length = Double.parseDouble(valName);
    double width = Double.parseDouble(valName);
    double height = Double.parseDouble(valName);
    for (String call : calls) {
        int parameterIndex = call.indexOf('(');
        String methodName = call.substring(0, parameterIndex);
        int parameter = Integer.parseInt(call.substring(parameterIndex+1, call.length()-1));
        if (methodName.equals("methodOnDefinitions")) {
            length = callMethodOnDefinitions(length, parameter);
            width = callMethodOnDefinitions(width, parameter);
            height = callMethodOnDefinitions(height, parameter);
        }
    }
    return new Dimensions(length, width, height);
}

