public ApiResponse login(String email, String pin) {
    String clientId = "your_client_id";
    String clientSecret = "your_client_secret";
    String authString = clientId + ":" + clientSecret;
    String encodedAuthString = Base64.getEncoder().encodeToString(authString.getBytes());
    String apiEndpoint = "https://your-api-endpoint.com/login";

    try {
        URL url = new URL(apiEndpoint);
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setRequestMethod("POST");
        conn.setRequestProperty("Content-Type", "application/x-www-form-urlencoded");
        conn.setRequestProperty("Authorization", "Basic " + encodedAuthString);

        String body = "grant_type=password&username=" + email + "&password=" + pin;
        conn.setDoOutput(true);
        DataOutputStream outputStream = new DataOutputStream(conn.getOutputStream());
        outputStream.writeBytes(body);
        outputStream.flush();
        outputStream.close();

        int responseCode = conn.getResponseCode();
        InputStream inputStream;
        if (responseCode >= 400) {
            inputStream = conn.getErrorStream();
        } else {
            inputStream = conn.getInputStream();
        }

        BufferedReader in = new BufferedReader(new InputStreamReader(inputStream));
        String inputLine;
        StringBuilder response = new StringBuilder();
        while ((inputLine = in.readLine()) != null) {
            response.append(inputLine);
        }
        in.close();

        ApiResponse apiResponse = new ApiResponse(responseCode, response.toString());
        return apiResponse;
    } catch (IOException e) {
        e.printStackTrace();
        return new ApiResponse(500, "{\"error\": \"" + e.getMessage() + "\"}");
    }
}
