public void runLifecycleMethods(String targetMethodScope) {
    // code to retrieve all methods that match the targetMethodScope
    List<Method> lifecycleMethods = getAllLifecycleMethods(targetMethodScope);

    // code to invoke all retrieved methods
    for (Method method : lifecycleMethods) {
        try {
            method.invoke(this);
        } catch (IllegalAccessException | InvocationTargetException e) {
            e.printStackTrace();
        }
    }
}

// helper method to retrieve all methods that match the targetMethodScope
private List<Method> getAllLifecycleMethods(String targetMethodScope) {
    // code to retrieve all available methods
    List<Method> allMethods = getAllAvailableMethods();

    // code to filter methods that match the targetMethodScope
    List<Method> lifecycleMethods = new ArrayList<>();
    for (Method method : allMethods) {
        if (method.isAnnotationPresent(LifecycleMethod.class)) {
            LifecycleMethod annotation = method.getAnnotation(LifecycleMethod.class);
            if (annotation.targetMethodScope().equals(targetMethodScope)) {
                lifecycleMethods.add(method);
            }
        }
    }

    return lifecycleMethods;
}

// sample annotation to mark lifecycle methods
@Retention(RetentionPolicy.RUNTIME)
@Target(ElementType.METHOD)
@interface LifecycleMethod {
    String targetMethodScope();
}
