public int getMatchedDepth(Class<? extends Throwable> exceptionType, Throwable ex) {
    int depth = 0;
    Throwable current = ex;
    while (current != null) {
        if (exceptionType.isAssignableFrom(current.getClass())) {
            return depth;
        }
        current = current.getCause();
        depth++;
    }
    return -1; // not found
}
