public List<String> getConversions(List<String> sourceTypes, List<String> targetTypes) {
    List<String> result = new ArrayList<String>();
    if (sourceTypes.size() != targetTypes.size()) {
        return result;
    }
    for (int i = 0; i < sourceTypes.size(); i++) {
        String source = sourceTypes.get(i);
        String target = targetTypes.get(i);
        if (!source.equals(target)) {
            result.add(source + " to " + target);
        }
    }
    return result;
}
