public void doFilter(ServletRequest request, ServletResponse response, FilterChain chain) throws IOException, ServletException {
    boolean securityEnabled = true; // Change to false if security is not enabled 
    String[] urlsToInclude = {"/include1", "/include2"}; // Add URLs to include in security chain
    String[] urlsToExclude = {"/exclude1", "/exclude2"}; // Add URLs to exclude from security chain

    if(securityEnabled) {
        boolean hasIncludedUrl = false;
        boolean hasExcludedUrl = false;

        for(String includeUrl : urlsToInclude) {
            if(request instanceof HttpServletRequest && ((HttpServletRequest) request).getRequestURI().contains(includeUrl)) {
                hasIncludedUrl = true;
                break;
            }
        }

        for(String excludeUrl : urlsToExclude) {
            if(request instanceof HttpServletRequest && ((HttpServletRequest) request).getRequestURI().contains(excludeUrl)) {
                hasExcludedUrl = true;
                break;
            }
        }

        if(hasIncludedUrl && !hasExcludedUrl) {
            RequestSecurityProcessor securityProcessor = new RequestSecurityProcessor();
            securityProcessor.process(request, response, chain);
        } else {
            chain.doFilter(request, response);
        }
    } else {
        chain.doFilter(request, response);
    }
}
