public static String longToIP(long ip) {
    String result = "";
    for (int i = 0; i < 4; i++) {
        result = Long.toString(ip & 0xff) + '.' + result;
        ip = ip >> 8;
    }
    return result.substring(0, result.length() - 1);
}
