import java.util.Iterator;
import java.util.List;

public static <E> Iterator<E> cyclicIterator(List<E> elements) {
    if(elements == null) {
        throw new NullPointerException("Elements list must not be null");
    }

    return new Iterator<E>() {
        int index = 0;

        @Override
        public boolean hasNext() {
            return true;
        }

        @Override
        public E next() {
            E element = elements.get(index);
            index = (index + 1) % elements.size();
            return element;
        }

        @Override
        public void remove() {
            elements.remove(index);
        }
    };
}
