public void setIndexedProperty(int index, Object start, Object value) {
    if (start instanceof List) {
        List list = (List) start;
        while (list.size() <= index) {
            list.add(null);
        }
        list.set(index, value);
    } else if (start.getClass().isArray()) {
        Object[] array = (Object[]) start;
        while (array.length <= index) {
            Object[] newArray = new Object[array.length + 1];
            System.arraycopy(array, 0, newArray, 0, array.length);
            array = newArray;
        }
        array[index] = value;
    } else if (start instanceof Map) {
        ((Map) start).put(index, value);
    } else {
        throw new IllegalArgumentException("Indexed property can only be set on an array, list or map");
    }
}
