public int calculateNextBlockLength(String text, int offset) {
    int blockLength = 0;
    boolean inControlWord = false;

    for (int i = offset; i < text.length(); i++) {
        char c = text.charAt(i);

        if (c == '\\') {
            inControlWord = true;
        } else if (inControlWord) {
            if (c == ' ') {
                inControlWord = false;
            }
        } else {
            blockLength++;
            if (c == '}') {
                break;
            }
        }
    }

    return blockLength;
}
