public static double[] projectHomogeneousVectorBack(double[][] v) {
    int dim = v[0].length - 1;
    double[] result = new double[dim];
    for (int i = 0; i < dim; i++) {
        result[i] = v[0][i] / v[0][dim];
    }
    return result;
}
