private void drawCenterCircle(Canvas canvas, RectF circleBox, float centerTextRadiusPercent, String centerText) {
    if (!mChartData.hasCenterCircle())
        return;

    int color = mChartPaint.getCenterCircleColor();
    float radius = (circleBox.width() / 2f) * centerTextRadiusPercent / 100f;

    mRenderPaint.setColor(color);
    canvas.drawCircle(circleBox.centerX(), circleBox.centerY(), radius, mRenderPaint);

    if (centerText != null) {
        mCenterTextPaint.setTextSize(Utils.convertDpToPixel(12f));
        mCenterTextPaint.setColor(mChartPaint.getColor());

        float width = mCenterTextPaint.measureText(centerText);
        canvas.drawText(centerText, circleBox.centerX() - (width / 2f), circleBox.centerY() + 15f, mCenterTextPaint);
    }
}
