import com.vividsolutions.jts.geom.Geometry;
import com.vividsolutions.jts.geom.LineString;
import com.vividsolutions.jts.geom.LinearRing;

public class GeometryUtils {

    public static Geometry getLineStringOrLinearRing(Geometry geometry) {
        if (geometry instanceof LineString || geometry instanceof LinearRing) {
            return geometry;
        } else {
            // Convert to LineString or LinearRing if possible
            if (geometry.getNumPoints() < 2) {
                throw new IllegalArgumentException("The geometry has less than two points.");
            } else if (geometry instanceof Polygon) {
                return ((Polygon) geometry).getExteriorRing();
            } else {
                return geometry.getFactory().createLineString(geometry.getCoordinates());
            }
        }
    }

}
