public String getPOISQLQuery(Filter filter, int count, String version) {
   String query = "SELECT * FROM POI WHERE version = " + version;
   if (filter != null) {
      query += " AND ";
      for (int i = 0; i < filter.getCategories().size(); i++) {
         if (i == filter.getCategories().size() - 1) {
            query += "category = '" + filter.getCategories().get(i) + "'";
         } else {
            query += "category = '" + filter.getCategories().get(i) + "' OR ";
         }
      }
   }
   if (count > 0) {
      query += " AND ";
      for (int i = 0; i < count; i++) {
         if (i == count - 1) {
            query += "name LIKE ?";
         } else {
            query += "name LIKE ? OR ";
         }
      }
   }
   return query;
}
