public double evaluate(List<Double> solutionList) {
    double max = Double.MIN_VALUE;
    double min = Double.MAX_VALUE;
    double sum = 0.0;

    for (double solution : solutionList) {
        max = Math.max(max, solution);
        min = Math.min(min, solution);
        sum += solution;
    }

    double mean = sum / solutionList.size();
    double range = max - min;

    return mean + range;
}
