public Future<JobResult> getJobResult(JobID jobId) {
   ExecutorService executorService = Executors.newSingleThreadExecutor();
   return executorService.submit(() -> {
       JobResult result = null;
       int retries = 0;
       while (result == null && retries <= MAX_RETRIES) {
           try {
               Thread.sleep(RETRY_INTERVAL_MS);
           } catch (InterruptedException e) {
               Thread.currentThread().interrupt();
               throw new IllegalStateException("Execution interrupted", e);
           }
           result = retrieveJobResult(jobId);
           retries++;
       }
       if (result == null) {
           throw new IllegalStateException("Could not retrieve job result");
       }
       return result;
   });
}
