public static double getRelativeError(boolean upperBound, boolean oooFlag, int lgK, int stdDev, int numStdDev) {
    double errorFactor = 0.0;
    if (upperBound) {
        if (oooFlag) {
            if (lgK >= 4 && lgK <= 8)
                errorFactor = 3.3;
            else if (lgK >= 9 && lgK <= 12)
                errorFactor = 3.0;
        } else {
            if (lgK >= 4 && lgK <= 8)
                errorFactor = 0.65;
            else if (lgK >= 9 && lgK <= 12)
                errorFactor = 0.45;
        }
    } else {
        if (oooFlag) {
            if (lgK >= 4 && lgK <= 8)
                errorFactor = 3.3;
            else if (lgK >= 9 && lgK <= 12)
                errorFactor = 3.0;
        } else {
            if (lgK >= 4 && lgK <= 8)
                errorFactor = 0.70;
            else if (lgK >= 9 && lgK <= 12)
                errorFactor = 0.50;
        }
    }
    return numStdDev * stdDev / errorFactor;
}
