import org.jgrapht.Graph;
import org.jgrapht.graph.DefaultWeightedEdge;
import org.jgrapht.graph.SimpleDirectedWeightedGraph;

import java.sql.Connection;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Statement;

public static <V, E> Graph<V, E> createJGraphTGraph(Connection connection, String inputTable, String orientation, String weight, Class<V> vertexClass, Class<E> edgeClass) throws SQLException{
    Graph<V, E> graph;

    if (orientation.equalsIgnoreCase("directed")) {
        graph = new SimpleDirectedWeightedGraph<>(edgeClass);
    } else if (orientation.equalsIgnoreCase("undirected")) {
        graph = new SimpleWeightedGraph<>(edgeClass);
    } else {
        throw new IllegalArgumentException("Invalid orientation argument.");
    }

    String queryString = "SELECT * FROM " + inputTable;
    Statement statement = connection.createStatement();

    try (ResultSet resultSet = statement.executeQuery(queryString)) {
        while (resultSet.next()) {
            V source = (V) resultSet.getObject(1);
            V target = (V) resultSet.getObject(2);
            double edgeWeight = weight != null ? resultSet.getDouble(weight) : 1.0;

            E edge = graph.getEdgeFactory().createEdge(source, target);
            graph.addEdge(source, target, edge);
            graph.setEdgeWeight(edge, edgeWeight);
        }
    }

    return graph;
}
