import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;

public class GlobToRegex {
   public static Pattern convertGlobToRegex(String glob) {
       StringBuilder sb = new StringBuilder(glob.length());
       int inGroup = 0;
       int inClass = 0;
       int firstIndexInClass = -1;
       char[] arr = glob.toCharArray();

       for (int i = 0; i < arr.length; i++) {
           char ch = arr[i];
           switch (ch) {
               case '\\':
                   if (++i >= arr.length) {
                       sb.append('\\');
                   } else {
                       char next = arr[i];
                       switch (next) {
                           case ',':
                               // escape not needed
                               break;
                           case 'Q':
                           case 'E':
                               // extra escape needed
                               sb.append('\\');
                           default:
                               sb.append('\\');
                               sb.append(next);
                       }
                   }
                   break;
               case '*':
                   if (inClass == 0)
                       sb.append(".*");
                   else
                       sb.append('*');
                   break;
               case '?':
                   if (inClass == 0)
                       sb.append('.');
                   else
                       sb.append('?');
                   break;
               case '[':
                   inClass++;
                   firstIndexInClass = i+1;
                   sb.append('[');
                   break;
               case ']':
                   inClass--;
                   sb.append(']');
                   break;
               case '.':
               case '(':
               case ')':
               case '+':
               case '|':
               case '^':
               case '$':
               case '@':
               case '%':
                   if (inClass == 0 || (firstIndexInClass == i && ch == '^'))
                       sb.append('\\');
                   sb.append(ch);
                   break;
               case '!':
                   if (firstIndexInClass == i)
                       sb.append('^');
                   else
                       sb.append('!');
                   break;
               case '{':
                   inGroup++;
                   sb.append('(');
                   break;
               case '}':
                   inGroup--;
                   sb.append(')');
                   break;
               case ',':
                   if (inGroup > 0)
                       sb.append('|');
                   else
                       sb.append(',');
                   break;
               default:
                   sb.append(ch);
           }
       }
       if (inClass != 0 || inGroup != 0)
           throw new PatternSyntaxException("Invalid glob pattern", glob, -1);
       return Pattern.compile(sb.toString());
   }
}
