public Grib2Record recaptureRecord(RandomAccessFile raf, long drsPos) throws IOException {
    Grib2Record record = new Grib2Record();

    // Set the position of the file to the given drsPos
    raf.seek(drsPos);

    // Read the section for data representation
    Grib2SectionDataRepresentation dataRepresentation = new Grib2SectionDataRepresentation(raf);
    record.addSection(dataRepresentation);

    // Read the section for product definition
    Grib2SectionProductDefinition prodDefinition = new Grib2SectionProductDefinition(raf);
    record.addSection(prodDefinition);

    // Read the section for data and bitmap
    Grib2SectionDataAndBitmap dataAndBitmap = new Grib2SectionDataAndBitmap(raf, record, dataRepresentation);
    record.addSection(dataAndBitmap);

    // Return the final record
    return record;
}
