public boolean deepCompare(Vector other, double tolerance) {
    if (this == other) {
        return true;
    }

    if (other == null || getClass() != other.getClass()) {
        return false;
    }

    Vector that = (Vector) other;
    if (this.values.length != that.values.length) {
        return false;
    }

    for (int i = 0; i < this.values.length; i++) {
        if (Math.abs(this.values[i] - that.values[i]) > tolerance) {
            return false;
        }
    }
    return true;
}
