public Script loadScriptFromClass(Class<?> targetClass) throws FileNotFoundException, IOException {
    // Get the path of the target class's bytecode file
    String bytecodeFilename = targetClass.getName().replace('.', '/') + ".class";
    String bytecodeFolderPath = targetClass.getClassLoader().getResource(".").getPath();
    String bytecodeFilePath = bytecodeFolderPath + bytecodeFilename;

    // Load the bytecode file as a byte array
    byte[] bytecode = Files.readAllBytes(Paths.get(bytecodeFilePath));

    // Parse the bytecode into a Script object using a bytecode parser library
    ScriptParser parser = new ScriptParser();
    Script script = parser.parse(bytecode);

    return script;
}
