@Around("execution(* com.example.*.*(..))")
public Object injectLogging(ProceedingJoinPoint pjp) throws Throwable {
    try {
        // log the start of the method
        logger.info("Starting method: " + pjp.getSignature().getName());

        // proceed with the original method execution
        Object result = pjp.proceed();

        // log the successful completion of the method
        logger.info("Completed method: " + pjp.getSignature().getName());

        // return the result of the original method
        return result;
    } catch (Throwable e) {
        // log any exceptions that occur during the method execution
        logger.error("Exception in method: " + pjp.getSignature().getName(), e);
        throw e;
    }
}
