public String getDelimiterString(String type) {
    Locale locale = Locale.getDefault(); // or any valid locale

    switch (type) {
        case "QUOTATION_START":
            return locale.getUnicodeLocaleType("QUOTATION_START"); 
        case "QUOTATION_END":
            return locale.getUnicodeLocaleType("QUOTATION_END"); 
        case "ALT_QUOTATION_START":
            return locale.getUnicodeLocaleType("ALT_QUOTATION_START"); 
        case "ALT_QUOTATION_END":
            return locale.getUnicodeLocaleType("ALT_QUOTATION_END"); 
        default:
            throw new IllegalArgumentException("Invalid delimiter type.");
    }
}
