public static void registerParentClass(Class<?> clazz, Class<?> parentClass) {
    // Get the ElementBase subclass name
    String className = clazz.getName();

    // Get the existing set of parent classes for this subclass, if any
    Set<String> parentClasses = validParentClasses.get(className);

    // If there are no existing parent classes, create a new set
    if (parentClasses == null) {
        parentClasses = new HashSet<String>();
        validParentClasses.put(className, parentClasses);
    }

    // Add the new parent class to the set
    parentClasses.add(parentClass.getName());
}
