/**
 * Rotates the matrix by the given quaternion around the given rotation center,
 * all given in local coordinates.
 *
 * @param quat the quaternion representing the rotation
 * @param ang the angle to rotate about the given rotation center, in radians
 * @param x the x coordinate of the rotation center
 * @param y the y coordinate of the rotation center
 * @param z the z coordinate of the rotation center
 * @return this
 */
public Matrix4d rotateAroundLocal(Quaterniondc quat, double ang, double x, double y, double z) {
    double sAngle = Math.sin(ang / 2.0);
    double cAngle = Math.cosFromSin(sAngle, ang / 2.0);
    double x1 = x * (1.0 - cAngle), y1 = y * (1.0 - cAngle), z1 = z * (1.0 - cAngle);
    double xy = x * y1, xz = x * z1, yz = y * z1;
    double xs = quat.x() * sAngle, ys = quat.y() * sAngle, zs = quat.z() * sAngle;
    double wx = quat.w() * xs, wy = quat.w() * ys, wz = quat.w() * zs;
    double xx = quat.x() * xs, xy2 = quat.x() * ys + quat.y() * xs, xz2 = quat.x() * zs + quat.z() * xs;
    double yy = quat.y() * ys, yz2 = quat.y() * zs + quat.z() * ys, zz = quat.z() * zs;

    double rm00 = cAngle + quat.x() * xs - yy - zz;
    double rm01 = xy2 + wz;
    double rm02 = xz2 - wy;
    double rm10 = xy2 - wz;
    double rm11 = cAngle + yy - xx - zz;
    double rm12 = yz2 + wx;
    double rm20 = xz2 + wy;
    double rm21 = yz2 - wx;
    double rm22 = cAngle + zz - xx - yy;

    double nm00 = m00 * rm00 + m10 * rm01 + m20 * rm02;
    double nm01 = m01 * rm00 + m11 * rm01 + m21 * rm02;
    double nm02 = m02 * rm00 + m12 * rm01 + m22 * rm02;
    double nm03 = m03 * rm00 + m13 * rm01 + m23 * rm02;
    double nm10 = m00 * rm10 + m10 * rm11 + m20 * rm12;
    double nm11 = m01 * rm10 + m11 * rm11 + m21 * rm12;
    double nm12 = m02 * rm10 + m12 * rm11 + m22 * rm12;
    double nm13 = m03 * rm10 + m13 * rm11 + m23 * rm12;
    double nm20 = m00 * rm20 + m10 * rm21 + m20 * rm22;
    double nm21 = m01 * rm20 + m11 * rm21 + m21 * rm22;
    double nm22 = m02 * rm20 + m12 * rm21 + m22 * rm22;
    double nm23 = m03 * rm20 + m13 * rm21 + m23 * rm22;

    m00 = nm00; m01 = nm01; m02 = nm02; m03 = nm03;
    m10 = nm10; m11 = nm11; m12 = nm12; m13 = nm13;
    m20 = nm20; m21 = nm21; m22 = nm22; m23 = nm23;

    return this;
}
