            TalendESBJob job = new TalendESBJob();
            job.run();

            // Check if the thread was interrupted
            if (Thread.currentThread().isInterrupted()) {
                restartJob = false;
            }

            // Check if the buffer was closed
            if (job.isBufferClosed()) {
                restartJob = false;
            }

        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
