public ArrayList<String> multiPathLookup(HashMap<String, String> data, ArrayList<String> paths) {
    ArrayList<String> results = new ArrayList<String>();
    for (String path : paths) {
        if (data.containsKey(path)) {
            results.add(data.get(path));
        } else {
            results.add("NOT FOUND");
        }
    }
    return results;
}
