private Object checkForCyclesHelper(Object obj, IdentityMap<Object, Boolean> seen, Proxies<Object> proxies) {
    if (obj == null || !(obj instanceof SomeClass)) {
        return obj;
    }

    if (seen.containsKey(obj)) {
        return proxies.get(obj);
    }

    seen.put(obj, true);

    // Do whatever operation you need to do with obj here

    proxies.put(obj, obj);

    return obj;
}
