public void addValuesToMapfishParser(Template template, Map<String, Object> attributes, String requestJsonAttributes) {
     MapfishParser parser = new MapfishParser();
     JSONObject jsonAttributes = new JSONObject(requestJsonAttributes);
     Map<String, Object> values = new HashMap<>(); 

     for (Map.Entry<String, Object> entry : attributes.entrySet()) {
          String attributeName = entry.getKey();
          Object attributeValue = entry.getValue();
          Object newValue = parser.execute(template, attributeValue, jsonAttributes);
          values.put(attributeName, newValue);
     }

     parser.addValues(values);
}
