public static int findAssociateIf(int[] pointerArray, int index) {
    int count = 0;
    for (int i = index - 1; i >= 0; i--) {
        if (pointerArray[i] == 1) {
            count--;
            if (count == -1) {
                return i;
            }
        } else if (pointerArray[i] == 2) {
            count++;
        }
    }
    return -1;
}
