import org.apache.http.client.HttpRequestRetryHandler;
import org.apache.http.protocol.HttpContext;
import org.apache.http.client.HttpResponseException;

public class ExponentialBackOffRetry implements HttpRequestRetryHandler {
    private final int maxRetries;
    private final int retryInterval;

    public ExponentialBackOffRetry(int maxRetries, int retryInterval) {
        this.maxRetries = maxRetries;
        this.retryInterval = retryInterval;
    }

    public boolean retryRequest(IOException exception, int executionCount, HttpContext context) {
        if (executionCount > maxRetries) {
            return false;
        } else if (exception instanceof HttpResponseException) {
            int statusCode = ((HttpResponseException) exception).getStatusCode();
            if (statusCode == 403 || statusCode == 408) {
                return true;
            }
        }

        try {
            Thread.sleep((long) (Math.pow(retryInterval, executionCount) * 1000));
        } catch (InterruptedException e) {
            return false;
        }
        return true;
    }
}
