import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class ExecuteAppEngineCmd {

    public static void executeCommand(String command) throws AppEngineJavaComponentsNotInstalledException, InvalidJavaSdkException, IOException {
        if(!isAppEngineJavaComponentInstalled()){
            throw new AppEngineJavaComponentsNotInstalledException("App Engine Java components are not installed in the Cloud SDK");
        }
        if(!isValidJavaSDK()){
            throw new InvalidJavaSdkException("Java not found");
        }

        Runtime runtime = Runtime.getRuntime();
        Process process = runtime.exec(command);
        String line;

        BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        while ((line = bufferedReader.readLine()) != null) {
            System.out.println(line);
        }

        bufferedReader.close();
    }

    private static boolean isAppEngineJavaComponentInstalled() throws IOException {
        boolean isInstalled = false;
        Process process = Runtime.getRuntime().exec("gcloud components list");
        BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        String line;
        while ((line = bufferedReader.readLine()) != null) {
            if (line.contains("app-engine-java")) {
                isInstalled = true;
                break;
            }
        }
        bufferedReader.close();
        return isInstalled;
    }

    private static boolean isValidJavaSDK() {
        String javaHome = System.getenv("JAVA_HOME");
        if (javaHome != null) {
            return true;
        }
        return false;
    }
}
