public static String getResourceAsString(String name, Class<?> cls) throws NullPointerException, ResourceException {
    if (name == null || cls == null) {
        throw new NullPointerException("Name or Class cannot be null");
    }
    String resource = "/" + cls.getPackage().getName().replace(".", "/") + "/" + name;
    InputStream stream = cls.getResourceAsStream(resource);
    if (stream == null) {
        throw new ResourceException("Resource " + name + " not found for class " + cls.getName());
    }
    try (Scanner scanner = new Scanner(stream, StandardCharsets.UTF_8.name())) {
        return scanner.useDelimiter("\\A").next();
    }
}
