public static int arrayHashCode(Class<?> componentType, Object o) {
    if (!o.getClass().isArray()) {
        return o.hashCode();
    }
    Class<?> type = o.getClass();

    if (type == byte[].class) {
        return Arrays.hashCode((byte[]) o);
    } else if (type == short[].class) {
        return Arrays.hashCode((short[]) o);
    } else if (type == int[].class) {
        return Arrays.hashCode((int[]) o);
    } else if (type == long[].class) {
        return Arrays.hashCode((long[]) o);
    } else if (type == char[].class) {
        return Arrays.hashCode((char[]) o);
    } else if (type == float[].class) {
        return Arrays.hashCode((float[]) o);
    } else if (type == double[].class) {
        return Arrays.hashCode((double[]) o);
    } else if (type == boolean[].class) {
        return Arrays.hashCode((boolean[]) o);
    } else {
        // Handle object arrays including nested object arrays
        int result = 1;
        Object[] elements = (Object[]) o;
        for (Object element : elements) {
            int elementHashCode = arrayHashCode(componentType.getComponentType(), element);
            result = 31 * result + elementHashCode;
        }
        return result;
    }
}
