public UpdateItemRequest getCompositeWriteRequest(Map<String, Object> changeSet) {
    PrimaryKey primaryKey = new PrimaryKey("primaryKey", changeSet.get("primaryKey"));
    List<AttributeValueUpdate> attributeValueUpdatesList = new ArrayList<>();
    for (Map.Entry<String, Object> entry : changeSet.entrySet()) {
        String key = entry.getKey();
        Object value = entry.getValue();
        attributeValueUpdatesList.add(new AttributeValueUpdate(key).put(value.toString()));
    }
    return new UpdateItemRequest().withTableName("tableName").withKey(primaryKey).withAttributeUpdates(attributeValueUpdatesList);
}
