public static String getFieldNameForManyToOne(String fromAttribute, String targetEntityNamer) {
    String[] splitAttribute = fromAttribute.split("_");
    String fieldName = splitAttribute[0];
    for (int i = 1; i < splitAttribute.length; i++) {
        fieldName += splitAttribute[i].substring(0, 1).toUpperCase()+splitAttribute[i].substring(1);
    }
    if (fieldName.endsWith("Id")) {
        fieldName = fieldName.substring(0, fieldName.length() - 2);
    }
    if (fieldName.equalsIgnoreCase(targetEntityNamer)) {
        fieldName += "Field";
    }
    return fieldName;
}
