public List<Span> createMultiwordSpans(List<String> tokens, List<WF> wfs, List<Span> tokenSpans) {
    List<Span> multiwordSpans = new ArrayList<>();

    int curStart = -1;
    int curEnd = -1;
    boolean inMultiword = false;
    for (int i = 0; i < wfs.size(); i++) {
        WF wf = wfs.get(i);
        String token = tokens.get(i);
        Span tokenSpan = tokenSpans.get(i);

        if (!inMultiword && wf.getOff() != tokenSpan.getStart()) {
            multiwordSpans.add(tokenSpan);
            continue;
        }

        if (inMultiword && wf.getOff() != (curEnd + 1)) {
            multiwordSpans.add(new Span(curStart, curEnd));
            inMultiword = false;
        }

        if (!inMultiword) {
            curStart = tokenSpan.getStart();
            curEnd = tokenSpan.getEnd();
            inMultiword = true;
        } else {
            curEnd = tokenSpan.getEnd();
        }
    }

    if (inMultiword) {
        multiwordSpans.add(new Span(curStart, curEnd));
    }

    return multiwordSpans;
