public String substituteValues(String input, Object model, Map<String, BufferedImage> imageMap) {
    Pattern pattern = Pattern.compile("\\$\\{(.*?)}");
    Matcher matcher = pattern.matcher(input);
    StringBuffer buffer = new StringBuffer();
    while (matcher.find()) {
        String expression = matcher.group(1);
        if (expression.startsWith("image:")) {
            String imageName = expression.substring(6);
            BufferedImage image = imageMap.get(imageName);
            if (image != null) {
                matcher.appendReplacement(buffer, "");
                int index = buffer.length();
                try {
                    ImageIO.write(image, "gif", new ByteArrayOutputStream());
                    buffer.insert(index, "<img src='data:image/gif;base64," + Base64.getEncoder().encodeToString(toByteArray(image, "gif")) + "' />");
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
        } else {
            Object value = getValue(expression, model);
            if (value != null) {
                matcher.appendReplacement(buffer, value.toString());
            }
        }
    }
    matcher.appendTail(buffer);
    return buffer.toString();
}

private byte[] toByteArray(RenderedImage image, String format) throws IOException {
    ByteArrayOutputStream out = new ByteArrayOutputStream();
    ImageIO.write(image, format, out);
    out.close();
    return out.toByteArray();
}

private Object getValue(String expression, Object model) {
    Object value = model;
    for (String field : expression.split("\\.")) {
        try {
            Field f = value.getClass().getDeclaredField(field);
            f.setAccessible(true);
            value = f.get(value);
        } catch (Exception e) {
            return null;
        }
    }
    return value;
}
