public static double convertUnits(double value, String inputUnit, String outputUnit) {
    switch (inputUnit) {
        case "m":
            switch (outputUnit) {
                case "km":
                    return value / 1000.0;
                case "cm":
                    return value * 100.0;
                case "mm":
                    return value * 1000.0;
                default:
                    return value;
            }
        case "km":
            switch (outputUnit) {
                case "m":
                    return value * 1000.0;
                case "cm":
                    return value * 100000.0;
                case "mm":
                    return value * 1000000.0;
                default:
                    return value;
            }
        case "cm":
            switch (outputUnit) {
                case "m":
                    return value / 100.0;
                case "km":
                    return value / 100000.0;
                case "mm":
                    return value * 10.0;
                default:
                    return value;
            }
        case "mm":
            switch (outputUnit) {
                case "m":
                    return value / 1000.0;
                case "km":
                    return value / 1000000.0;
                case "cm":
                    return value / 10.0;
                default:
                    return value;
            }
        default:
            return value;
    }
}
