import io.confluent.kafka.schemaregistry.client.CachedSchemaRegistryClient;
import io.confluent.kafka.serializers.KafkaAvroDeserializerConfig;
import org.apache.avro.Schema;
import org.apache.avro.generic.GenericRecord;
import org.apache.flink.api.common.typeinfo.TypeInformation;
import org.apache.flink.api.java.typeutils.TypeExtractor;
import org.apache.flink.formats.avro.AvroDeserializationSchema;
import org.apache.flink.formats.avro.utils.MutableByteArrayInputStream;
import org.apache.flink.formats.avro.utils.MutableByteArrayOutputStream;

import java.io.IOException;
import java.nio.charset.StandardCharsets;

public class AvroDeserializationSchemaCreator {

    public static <T> AvroDeserializationSchema<T> createAvroDeserializationSchema(Class<T> tClass, String url) {

        Schema.Parser parser = new Schema.Parser();

        String subject = tClass.getName() + "-value";
        CachedSchemaRegistryClient schemaRegistry = new CachedSchemaRegistryClient(url, 100);

        try {
            int id = schemaRegistry.getLatestSchemaMetadata(subject).getId();
            String schemaString = schemaRegistry.getById(id).getSchema();

            Schema schema = parser.parse(schemaString);
            TypeInformation<T> typeInfo = TypeExtractor.getForClass(tClass);

            return new AvroDeserializationSchema<T>(schema, typeInfo) {
                private static final long serialVersionUID = 1L;

                @Override
                public T deserialize(GenericRecord genericRecord) throws IOException {
                    MutableByteArrayOutputStream outStream = new MutableByteArrayOutputStream();
                    schemaRegistry.getById(id)
                            .getSchema()
                            .getBytes(StandardCharsets.UTF_8);
                    Schema writerSchema = parser.parse(schemaString);
                    writerSchema.getFullName().equals("org.apache.avro.kafka.User"); // Check writer schema

                    schemaRegistry.getById(id).getSchema().getBytes(StandardCharsets.UTF_8);
                    DatumReader<T> reader = new GenericDatumReader<>(writerSchema, schema);
                    BinaryDecoder decoder =
                            DecoderFactory.get().binaryDecoder(genericRecord.get("payload").toString().getBytes(StandardCharsets.UTF_8), null);
                    return reader.read(null, decoder);
                }

                @Override
                public T deserialize(byte[] message) throws IOException {
                    MutableByteArrayInputStream inStream = new MutableByteArrayInputStream(message);
                    return deserialize(parse(inStream));
                }
            };
        } catch (IOException e) {
            e.printStackTrace();
        }
        return null;
    }
}
