public String extractIdentifierPart(int pos, String identifier) {
    if(identifier == null || identifier.isEmpty()) {
        return null;
    }
    String[] parts = identifier.split("-");
    if(parts.length <= pos) {
        return null;
    }
    return parts[pos];
}
