public String formatNdarray(ndarray arr, boolean summarize) {
    if (summarize && arr.size() > 1000) {
        // If summarize flag is set and the array size is greater than 1000,
        // only print the first three and last elements in any dimension
        int[] shape = arr.shape();
        StringBuilder sb = new StringBuilder();
        sb.append("[");
        for (int i = 0; i < shape[0]; i++) {
            if (i < 3 || i >= shape[0] - 3) {
                sb.append("[");
                for (int j = 0; j < shape[1]; j++) {
                    if (j < 3 || j >= shape[1] - 3) {
                        sb.append(arr.get(i,j));
                        sb.append(", ");
                    } else if (j == 3) {
                        sb.append("..., ");
                    }
                }
                sb.append("], ");
            } else if (i == 3) {
                sb.append("..., ");
            }
        }
        sb.append("]");
        return sb.toString();
    } else {
        // If summarize flag is not set or the array size is less than or equal to 1000,
        // print the entire array
        return Arrays.deepToString(arr.toArray());
    }
}
