public void handleMessage (ChaincodeStream.ChaincodeMessage message) {
    if (message.getType() == ChaincodeMessage.Type.RESPONSE) {
        blockingQueue.offer(message);
    } else {
        CompletableFuture<ChaincodeStream.ChaincodeMessage> future = pending.get(message.getChannelId());
        if (future != null) {
            future.complete(message);
        } else {
            LOGGER.warn("No pending future for message: {}", message);
        }
    }
}
