public void updateQueryParameterIndexes(String queryString) {
    String newQueryString = "";
    String[] queryParamPairs = queryString.split("&");
    for (int i = 0; i < queryParamPairs.length; i++) {
        String queryParamPair = queryParamPairs[i];
        String[] queryParamAndValue = queryParamPair.split("=");
        String queryParam = queryParamAndValue[0];
        int newIndex = i + 1;
        String newQueryParamPair = queryParam + "=" + queryParamAndValue[1].replaceAll("[^\\w\\s]","") + "[" + newIndex + "]";
        newQueryString += newQueryParamPair;
        if (i < queryParamPairs.length - 1) {
            newQueryString += "&";
        }
    }
    // Do something with the newQueryString (e.g. update a URL)
}
