public static double[][] similarityToEigen(double[][] similarityMatrix) {
    int n = similarityMatrix.length;
    double[][] eigenMatrix = new double[n][n];

    // Compute the sum of similarity scores for each node
    double[] nodeSum = new double[n];
    for (int i = 0; i < n; i++) {
        double sum = 0;
        for (int j = 0; j < n; j++) {
            sum += similarityMatrix[i][j];
        }
        nodeSum[i] = sum;
    }

    // Compute the Eigen matrix
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            eigenMatrix[i][j] = -similarityMatrix[i][j] / Math.sqrt(nodeSum[i] * nodeSum[j]);
        }
        eigenMatrix[i][i] += 1;  // Add 1 to the diagonal
    }

    return eigenMatrix;
}
