public Matrix setToRotation(AxisAngle4d axisAngle) {
    double x = axisAngle.x;
    double y = axisAngle.y;
    double z = axisAngle.z;
    double angle = axisAngle.angle;

    double c = Math.cos(angle);
    double s = Math.sin(angle);
    double t = 1.0 - c;

    double xt = x * t;
    double yt = y * t;
    double zt = z * t;
    double xs = x * s;
    double ys = y * s;
    double zs = z * s;

    this.m00 = c + xt * x;
    this.m01 = 0 + xt * y + zs;
    this.m02 = 0 + xt * z - ys;

    this.m10 = 0 + yt * x - zs;
    this.m11 = c + yt * y;
    this.m12 = 0 + yt * z + xs;

    this.m20 = 0 + zt * x + ys;
    this.m21 = 0 + zt * y - xs;
    this.m22 = c + zt * z;

    return this;
}
