import io.prometheus.client.Summary;
import io.prometheus.client.exporter.common.TextFormat;
import java.io.IOException;
import java.io.Writer;

public void exportHistogramSnapshotAsPrometheusSummary(String dropwizardName, Snapshot snapshot, long count, double factor, Writer writer) throws IOException {
    Summary.Builder summaryBuilder = Summary.build().name(dropwizardName).help(dropwizardName);
    for (double quantile : snapshot.getQuantiles(new double[] { 0.5, 0.95 })) {
      summaryBuilder.quantile(quantile, 0.05);
    }
    Summary summary = summaryBuilder.create();
    for (long sample : snapshot.getValues()) {
      summary.observe(sample * factor);
    }
    summary.observe(Double.NaN); // Ensure that NaN count is non-zero if count is zero.
    String summaryStr = summary.collect().get(0).toString();
    writer.write(String.format("# HELP %s %s\n", dropwizardName, dropwizardName));
    writer.write(String.format("# TYPE %s summary\n", dropwizardName));
    writer.write(summaryStr);
  }
