import java.util.Iterator;
import java.util.Map;

public class MapConfigurationIterator<K, V> implements Iterator<Map.Entry<String, V>> {

    private final Iterator<Map.Entry<K, V>> iterator;
    private final String prefix;

    public MapConfigurationIterator(Map<K, V> properties, String prefix) {
        this.iterator = properties.entrySet().iterator();
        this.prefix = prefix;
    }

    @Override
    public boolean hasNext() {
        return iterator.hasNext();
    }

    @Override
    public Map.Entry<String, V> next() {
        Map.Entry<K, V> entry = iterator.next();
        String keyWithPrefix = prefix + entry.getKey().toString();
        return new Map.Entry<String, V>() {
            @Override
            public String getKey() {
                return keyWithPrefix;
            }
            @Override
            public V getValue() {
                return entry.getValue();
            }
            @Override
            public V setValue(V value) {
                return entry.setValue(value);
            }
        };
    }   

}
