private void copyHeaders(SipServletRequest newRequest, SipServletRequest originalRequest) {
   Enumeration<String> headerNames = originalRequest.getHeaderNames();
   while (headerNames.hasMoreElements()) {
       String headerName = headerNames.nextElement();
       if (!shouldBeCopied(headerName)) {
           continue;
       }
       List<String> headerValues = Collections.list(originalRequest.getHeaders(headerName));
       for (String headerValue : headerValues) {
           newRequest.addHeader(headerName, headerValue);
       }
   }
}

private boolean shouldBeCopied(String headerName) {
   // add conditions here to determine if headers should be copied or not
