public static Class<?> getNonAnonymousClass(Object obj) {
    if (obj instanceof Class) {
        Class<?> cls = (Class<?>) obj;
        if (cls.isAnonymousClass()) {
            return cls.getEnclosingClass();
        } else {
            return cls;
        }
    } else {
        Object nonNullObj = (obj != null) ? obj : Object.class;
        return getNonAnonymousClass(nonNullObj.getClass());
    }
}
