public static <T> void sortSubset(T[] a, int lo0, int hi0, Comparator<? super T> comparator) {
    if (lo0 < hi0) {
        int lt = lo0, gt = hi0;
        T pivot = a[lo0];
        int i = lo0;
        while (i <= gt) {
            int cmp = comparator.compare(a[i], pivot);
            if (cmp < 0) {
                swap(a, lt++, i++);
            } else if (cmp > 0) {
                swap(a, i, gt--);
            } else {
                i++;
            }
        }
        sortSubset(a, lo0, lt - 1, comparator);
        sortSubset(a, gt + 1, hi0, comparator);
    }
}

private static <T> void swap(T[] a, int i, int j) {
    T temp = a[i];
    a[i] = a[j];
    a[j] = temp;
}
