public Put preparePut(String columnFamily, String rowKey, List<String> columns, List<byte[]> values, ColumnFamilyObject columnFamilyObj) throws IOException {
    Put put = new Put(Bytes.toBytes(rowKey));
    byte[] columnFamilyBytes = Bytes.toBytes(columnFamily);
    for (int i = 0; i < columns.size(); i++) {
        byte[] columnBytes = Bytes.toBytes(columns.get(i));
