        String masterValue = row.get(labels.indexOf(dataColumn));
        if (masterMap.containsKey(masterValue)) {
            result.add(masterMap.get(masterValue) + "," + rowToString(row));
        }
    }

    return result;
}

private String rowToString(List<String> row) {
    StringJoiner joiner = new StringJoiner(",");
    for (String value : row) {
        joiner.add(value);
    }
    return joiner.toString();
}
