public void fillTarHeader(TarHeader hdr, File file) {
    hdr.name = file.getName();
    hdr.mode = (int) file.getMode();
    hdr.type = file.isDirectory() ? TarHeader.LF_DIR : TarHeader.LF_NORMAL;
    hdr.size = file.length();
    hdr.modTime = file.lastModified() / 1000L;
    hdr.linkName = "";
    hdr.checksum = 0;
    hdr.uname = "";
    hdr.gname = "";
    hdr.devMajor = 0;
    hdr.fill(0);
}
