import java.util.ArrayList;
import java.util.List;

public class ClassLoader {
    public static List<Class<?>> loadClasses(Class<?> restrictionClass) {
        List<Class<?>> classes = new ArrayList<>();
        Package[] packages = Package.getPackages();
        for (Package pack : packages) {
            String packName = pack.getName();
            String[] classNames = getClassNames(packName);
            for (String className : classNames) {
                try {
                    Class<?> cls = Class.forName(packName + "." + className);
                    if (restrictionClass.isAssignableFrom(cls)) {
                        classes.add(cls);
                    }
                } catch (ClassNotFoundException e) {
                    // ignore
                }
            }
        }
        return classes;
    }

    private static String[] getClassNames(String packageName) {
        String[] classNames = new String[0];
        try {
            String packagePath = packageName.replace(".", "/");
            String packageResourcePath = Thread.currentThread().getContextClassLoader().getResource(packagePath).getPath();
            File directory = new File(packageResourcePath);
            if (directory.exists()) {
                classNames = directory.list();
            }
        } catch (NullPointerException e) {
            // ignore
        }
        return classNames;
    }
}
