public BoundingBox createBboxWithRatio(double ratioWidth, double ratioHeight) {
    double currentWidth = this.width;
    double currentHeight = this.height;
    double newWidth, newHeight;
    if (currentWidth / ratioWidth > currentHeight / ratioHeight) {
        newHeight = currentWidth * ratioHeight / ratioWidth;
        newWidth = currentWidth;
    } else {
        newWidth = currentHeight * ratioWidth / ratioHeight;
        newHeight = currentHeight;
    }
    double x = this.x + (currentWidth - newWidth) / 2;
    double y = this.y + (currentHeight - newHeight) / 2;
    return new BoundingBox(x, y, newWidth, newHeight);
}
