public static <K, V> Map<K, V> convertObjectToMap(Object object, Class<? extends Map> mapClass, Class<K> keyClass, Class<V> valueClass) {
    try {
        Map<K, V> map = mapClass.getDeclaredConstructor().newInstance();
        if(object != null) {
            BeanInfo beanInfo = Introspector.getBeanInfo(object.getClass());
            PropertyDescriptor[] propertyDescriptors = beanInfo.getPropertyDescriptors();
            for(PropertyDescriptor propertyDescriptor : propertyDescriptors) {
                String key = propertyDescriptor.getName();
                if(!key.equals("class")) {
                    Method getter = propertyDescriptor.getReadMethod();
                    Object value = getter.invoke(object);
                    map.put(keyClass.cast(key), valueClass.cast(value));
                }
            }
        }
        return map;
    } catch(Exception e) {
        throw new RuntimeException("Unable to convert object to map", e);
    }
}
