import java.lang.reflect.*;
import java.util.*;

public class SignatureToTypeParameterConverter {

    public static Map<String, Type> convert(String signature, TypeVariable[] typeParameters) {
        Map<String, Type> typeParameterMap = new HashMap<>();
        if (signature == null || signature.isEmpty()) {
            return typeParameterMap;
        }

        SignatureVisitor visitor = new SignatureVisitor(Opcodes.ASM7) {
            Type[] types = new Type[typeParameters.length];
            int index = 0;

            @Override
            public void visitFormalTypeParameter(String name) {
                if (index < typeParameters.length) {
                    types[index++] = typeParameters[index].getClass();
                }
            }

            @Override
            public void visitClassType(String name) {
                if (index < typeParameters.length) {
                    types[index++] = Type.getObjectType(name);
                }
            }

            @Override
            public void visitTypeVariable(String name) {
                if (index < typeParameters.length) {
                    types[index++] = new TypeVariableImpl(name, typeParameterMap);
                }
            }

            @Override
            public SignatureVisitor visitArrayType() {
                return new SignatureVisitor(Opcodes.ASM7) {
                    Type elementType = null;

                    @Override
                    public void visitBaseType(char descriptor) {
                        elementType = Type.getType(String.valueOf(descriptor));
                    }

                    @Override
                    public void visitClassType(String name) {
                        elementType = Type.getObjectType(name);
                    }

                    @Override
                    public void visitTypeVariable(String name) {
                        elementType = new TypeVariableImpl(name, typeParameterMap);
                    }

                    @Override
                    public void visitEnd() {
                        if (elementType != null) {
                            types[index++] = Array.newInstance(elementType.getClass(), 0).getClass();
                        }
                    }
                };
            }

            @Override
            public void visitEnd() {
                for (int i = 0; i < typeParameters.length; i++) {
                    if (types[i] != null) {
                        typeParameterMap.put(typeParameters[i].getName(), types[i]);
                    }
                }
            }

        };

        new SignatureReader(signature).accept(visitor);

        return typeParameterMap;
    }

    private static class TypeVariableImpl implements Type {

        private final String name;
        private final Map<String, Type> typeParameterMap;

        public TypeVariableImpl(String name, Map<String, Type> typeParameterMap) {
            this.name = name;
            this.typeParameterMap = typeParameterMap;
        }

        @Override
        public String getTypeName() {
            return name;
        }

        @Override
        public boolean equals(Object other) {
            if (!(other instanceof TypeVariable)) {
                return false;
            }
            Type otherType = typeParameterMap.get(((TypeVariable) other).getName());
            if (otherType == null) {
                return false;
            }
            return this.equals(otherType);
        }

        @Override
        public String toString() {
            return name;
        }
    }

}
