public int getOutputSize(int inputData, int kernel, int strides, int padding, String convolutionMode, int dilation) {
    int outputSize = 0;

    if (convolutionMode.equals("Same")) {
        outputSize = (int) Math.ceil((double) inputData / strides);
    } else if (convolutionMode.equals("Strict")) {
        outputSize = (int) Math.ceil((double) (inputData - kernel + 1 + 2 * padding) / strides + 1);
    } else if (convolutionMode.equals("Truncate")) {
        outputSize = (int) Math.ceil((double) (inputData - kernel + 1 + (kernel-1) * (dilation-1) + 2 * padding) / strides + 1);
    }

    return outputSize;
}
