import java.util.Random;

public class SphereGenerator {
    // generate random coordinates within sphere of radius r
    public static double[] generateRandomSphereCoordinates(double r) {
        Random random = new Random();
        double[] coordinates = new double[3];

        // generate random point in a cube of diagonal 2 * r
        double x = (random.nextDouble() * (2 * r)) - r;
        double y = (random.nextDouble() * (2 * r)) - r;
        double z = (random.nextDouble() * (2 * r)) - r;

        // check if point is within sphere of radius r
        double distance = Math.sqrt(x * x + y * y + z * z);
        while (distance > r) {
            x = (random.nextDouble() * (2 * r)) - r;
            y = (random.nextDouble() * (2 * r)) - r;
            z = (random.nextDouble() * (2 * r)) - r;
            distance = Math.sqrt(x * x + y * y + z * z);
        }

        // return the coordinates
        coordinates[0] = x;
        coordinates[1] = y;
        coordinates[2] = z;
        return coordinates;
    }
}
