import java.sql.*;

public class DatabaseUtils {

    public Object runSQLQuery(String query, String url, String user, String password) throws SQLException {
        Connection con = null;
        Statement stmt = null;
        ResultSet rs = null;
        Object result = null;
        try {
            con = DriverManager.getConnection(url, user, password);
            stmt = con.createStatement();
            rs = stmt.executeQuery(query);
            if(rs.next()) {
                result = rs.getObject(1);
            }
        } finally {
            if(rs != null) {
                rs.close();
            }
            if(stmt != null) {
                stmt.close();
            }
            if(con != null) {
                con.close();
            }
        }
        return result;
    }
}
