public static long writeAllBytes(InputStream input, OutputStream output) throws IOException {
    byte[] buffer = new byte[4096]; // You may change the buffer size according to your need
    long totalBytesWritten = 0;
    int bytesRead;
    while ((bytesRead = input.read(buffer)) != -1) {
        output.write(buffer, 0, bytesRead);
        totalBytesWritten += bytesRead;
    }
    output.flush();
    return totalBytesWritten;
}
