public Relationship addAttributesRelationship(String baseTableName, String attributesTable, String mappingTableName) {
    // Check if attributes table exists, if not create it
    if (!tableExists(attributesTable)) {
        createAttributesTable(attributesTable);
    }

    // Check if mapping table exists, if not create it
    if (!tableExists(mappingTableName)) {
        createMappingTable(mappingTableName);
    }

    // Add relationship between base table and attributes table
    Relationship relationship = createRelationship(baseTableName, attributesTable);

    // Add relationship between attributes table and mapping table
    Relationship mappingRelationship = createRelationship(attributesTable, mappingTableName);

    // Return the relationship that was added
    return relationship;
}
