import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.security.InvalidKeyException;
import java.security.NoSuchAlgorithmException;
import java.util.Base64;

public String computeHmacSha1(String secret, String payloadFrom)  {
    try {
        String algorithm = "HmacSHA1";
        Mac mac = Mac.getInstance(algorithm);
        SecretKeySpec spec = new SecretKeySpec(secret.getBytes(), algorithm);
        mac.init(spec);
        byte[] hashBytes = mac.doFinal(payloadFrom.getBytes());
        return Base64.getEncoder().encodeToString(hashBytes);
    } catch (NoSuchAlgorithmException | InvalidKeyException e) {
        return "COMPUTED_INVALID_SIGNATURE";
    }
}
