public static String convertJsonToJavaFieldName(String jsonFieldName, JsonNode node) {
    String fieldName = jsonFieldName.replaceAll("[^a-zA-Z0-9_$]", "");
    // If the first character is a number, add "field" prefix
    if(Character.isDigit(fieldName.charAt(0))) {
        fieldName = "field" + fieldName;
    }
    // Normalize field name to camel case
    fieldName = CaseFormat.LOWER_UNDERSCORE.to(CaseFormat.LOWER_CAMEL, fieldName);
    return fieldName;
}
