public Object takeSnapshot(Object data) {
    if (data == null) {
        return new Object(); // Return empty object if data is null
    } else if (data instanceof List) {
        List dataList = (List) data;
        return new ArrayList(dataList); // Return a snapshot of the list
    } else if (data instanceof Map) {
        Map dataMap = (Map) data;
        return new HashMap(dataMap); // Return a snapshot of the map
    } else if (data instanceof Object[]) {
        Object[] dataArray = (Object[]) data;
        return Arrays.copyOf(dataArray, dataArray.length); // Return a snapshot of the array
    } else {
        return new Object(); // Return empty object if data is not a known datatype
    }
}
