public double convertBinaryFieldToDouble(byte[] bytes, int oid, String targetType) throws PSQLException {
    switch (oid) {
        case 20: // integer
        case 21: // integer array
            return ByteBuffer.wrap(bytes).getInt();
        case 701: // double precision float
        case 1022: // double precision float array
            return ByteBuffer.wrap(bytes).getDouble();
        case 700: // real
        case 1021: // real array
            return ByteBuffer.wrap(bytes).getFloat();
        default:
            throw new PSQLException("Unsupported numeric type: " + targetType, PSQLState.STATEMENT_NOT_ALLOWED);
    }
}
