public void dumpStructuredBlock(int headerSize, int blockSize, byte[] data) {
    // Calculate total number of records
    int numRecords = (data.length - headerSize) / blockSize;

    // Print header information
    System.out.println("Header size: " + headerSize);
    System.out.println("Block size: " + blockSize);
    System.out.println("Number of records: " + numRecords);

    // Dump each record
    for (int i = 0; i < numRecords; i++) {
        int recordOffset = headerSize + (i * blockSize);
        byte[] recordData = Arrays.copyOfRange(data, recordOffset, recordOffset + blockSize);
        System.out.println("Record #" + i + ": " + Arrays.toString(recordData));
    }
}
