public static boolean isSubset(int[] array, int[] subset) {
    for(int i : subset) {
        boolean found = false;
        for(int j : array) {
            if(i == j) {
                found = true;
                break;
            }
        }
        if(!found) {
            return false;
        }
    }
    return true;
}
