public static String parseTemplate(String template, Map<String, String> variables) {
    // Split the template by "{{" and "}}"
    String[] parts = template.split("\\{\\{");

    // Initialize the parsed string
    StringBuilder parsed = new StringBuilder(parts[0]);

    // Loop through the remaining parts of the template string
    for (int i = 1; i < parts.length; i++) {
        String part = parts[i];

        // Check if the string contains "}}"
        if (part.contains("}}")) {

            // Extract the key from the string
            String key = part.substring(0, part.indexOf("}}"));

            // If the key exists in the variables map, replace it with the value
            if (variables.containsKey(key)) {
                parsed.append(variables.get(key)).append(part.substring(part.indexOf("}}") + 2));
            } else {
                parsed.append("{{").append(part);
            }

        } else {
            parsed.append("{{").append(part);
        }
    }

    return parsed.toString();
}
