public List<ArtifactDetails> getArtifactDetailsByRole(File downloadFile, InstanceType instanceType) throws FileNotFoundException {
    List<ArtifactDetails> result = new ArrayList<>();
    Scanner scanner = new Scanner(downloadFile);
    while (scanner.hasNextLine()) {
        String line = scanner.nextLine();
        String[] elements = line.split(",");
        ArtifactDetails artifactDetails = new ArtifactDetails();
        if (elements[0].equalsIgnoreCase(instanceType.getPlatform().name()) && elements[3].equalsIgnoreCase(instanceType.getRole())) {
            artifactDetails.setUrl(elements[1]);
            artifactDetails.setCheckSum(elements[2]);
            result.add(artifactDetails);
        }
    }
    scanner.close();
    return result;
}
