public void appendMessageForStorage(Document document, BsonOutput bsonOutput, FieldNameValidator validator) {
    bsonOutput.setPosition(0);
    bsonOutput.writeStartDocument();

    for (String key : document.keySet()) {
        Object value = document.get(key);
        validator.validate(key);

        bsonOutput.writeName(key);

        if (value == null) {
            bsonOutput.writeNull();
        } else if (value instanceof String) {
            bsonOutput.writeString((String) value);
        } else if (value instanceof Integer) {
            bsonOutput.writeInt32((Integer) value);
        } else if (value instanceof Double) {
            bsonOutput.writeDouble((Double) value);
        } else if (value instanceof Boolean) {
            bsonOutput.writeBoolean((Boolean) value);
        } else if (value instanceof Date) {
            bsonOutput.writeDateTime(((Date) value).getTime());
        } else if (value instanceof List) {
            bsonOutput.writeStartArray();
            for (Object listItem : (List) value) {
                if (listItem instanceof Document) {
                    appendMessageForStorage((Document) listItem, bsonOutput, validator);
                } else {
                    bsonOutput.writeName("item");
                    bsonOutput.writeStartDocument();
                    appendMessageForStorage(new Document("value", listItem), bsonOutput, validator);
                    bsonOutput.writeEndDocument();
                }
            }
            bsonOutput.writeEndArray();
        } else if (value instanceof Document) {
            bsonOutput.writeStartDocument();
            appendMessageForStorage((Document) value, bsonOutput, validator);
            bsonOutput.writeEndDocument();
        } else {
            throw new IllegalArgumentException("Unhandled type: " + value.getClass());
        }
    }

    bsonOutput.writeEndDocument();
}
