public boolean goToNextInnerElement(String elementName) {
    // Assuming there is an existing XML parser object called xmlParser
    try {
        while (xmlParser.hasNext()) {
            int eventType = xmlParser.next();
            if (eventType == XmlPullParser.START_TAG && xmlParser.getName().equals(elementName)) {
                return true;
            } else if (eventType == XmlPullParser.END_TAG && xmlParser.getName().equals(elementName)) {
                return false;
            }
        }
    } catch (XmlPullParserException | IOException e) {
        e.printStackTrace();
    }

    return false;
}
