public String encodeText(String text) {
    // Initialize an empty string to store the encoding result
    String encodedText = "";

    // Loop through each character in the given text
    for (int i = 0; i < text.length(); i++) {
        // Convert the current character to its ASCII code
        int asciiCode = (int) text.charAt(i);

        // Shift the ASCII code by 1
        int shiftedCode = asciiCode + 1;

        // Convert the shifted code back to its corresponding character
        char encodedChar = (char) shiftedCode;

        // Append the encoded character to the result string
        encodedText += encodedChar;
    }

    // Return the encoding result
    return encodedText;
}
