import java.io.IOException;
import java.util.HashSet;
import java.util.Set;

public class ClassFinder {

    public static Set<Class<?>> getClasses(ClassLoader classLoader, Package pkg) throws IOException {

        String packageName = pkg.getName();
        String path = packageName.replace('.', '/');
        Set<Class<?>> classes = new HashSet<Class<?>>();

        // Get all resources from the package and its sub-packages.
        Enumeration<URL> resources = classLoader.getResources(path);
        while (resources.hasMoreElements()) {
            URL resource = resources.nextElement();
            File file = new File(resource.getFile());
            if (file.isDirectory()) {
                classes.addAll(findClasses(file, packageName));
            }
        }

        return classes;
    }

    private static Set<Class<?>> findClasses(File directory, String packageName) {
        Set<Class<?>> classes = new HashSet<Class<?>>();
        if (!directory.exists()) {
            return classes;
        }
        File[] files = directory.listFiles();
        for (File file : files) {
            if (file.isDirectory()) {
                assert !file.getName().contains(".");
                classes.addAll(findClasses(file, packageName + "." + file.getName()));
            } else if (file.getName().endsWith(".class")) {
                try {
                    classes.add(Class.forName(packageName + '.' + file.getName().substring(0, file.getName().length() - 6)));
                } catch (ClassNotFoundException e) {
                    e.printStackTrace();
                }
            }
        }
        return classes;
    }
}
