import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class HashUtils {

    // Hash two hashes together
    public static DataHash hashTwoHashes(DataHash hash1, DataHash hash2, int level, String algorithm) throws NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance(algorithm);
        byte[] inputBytes = (hash1.hashCode() + hash2.hashCode() + level).getBytes();
        byte[] hashBytes = digest.digest(inputBytes);
        return new DataHash(hashBytes, algorithm);
    }
}
