public Collection<ListenerAdapter> compileListeners(Collection<Class<? extends ListenerAdapter>> listenerClasses) {
    Collection<ListenerAdapter> listeners = new ArrayList<>();

    for (Class<? extends ListenerAdapter> listenerClass : listenerClasses) {
        try {
            ListenerAdapter listener = listenerClass.getDeclaredConstructor().newInstance();
            listeners.add(listener);
        } catch (InstantiationException | IllegalAccessException | NoSuchMethodException | InvocationTargetException e) {
            e.printStackTrace();
        }
    }

    return listeners;
}
