public Set<Integer> getGuessSetForQueuePoints(Queue<Point> queuePoints){
    // initialize an empty set to hold the guesses
    Set<Integer> guessSet = new HashSet<Integer>();

    // loop through the points in the queue
    for(Point point : queuePoints){
        // add a guess for the x-coordinate of the point
        guessSet.add(guessForCoordinate(point.getX()));
        // add a guess for the y-coordinate of the point
        guessSet.add(guessForCoordinate(point.getY()));
    }

    return guessSet;
}

private int guessForCoordinate(double coord){
    // implement your guessing algorithm here
