public List<MethodNode> filterMethodsByVisibility(List<MethodNode> methodNodeList, ClassNode enclosingClassNode) {
    List<MethodNode> filteredMethods = new ArrayList<>();
    for (MethodNode methodNode : methodNodeList) {
        if ((enclosingClassNode.access & Opcodes.ACC_INTERFACE) != 0) {
            // interface methods are always public
            filteredMethods.add(methodNode);
        } else if ((methodNode.access & Opcodes.ACC_PUBLIC) != 0) {
            filteredMethods.add(methodNode);
        } else if ((methodNode.access & Opcodes.ACC_PROTECTED) != 0) {
            // check if the invoking class is a subclass of the enclosing class
            boolean isSubclass = false;
            String superClass = methodNode.owner.replace("/", ".");
            while (superClass != null && !isSubclass) {
                if (superClass.equals(enclosingClassNode.name.replace("/", "."))) {
                    isSubclass = true;
                } else {
                    try {
                        Class<?> clazz = Class.forName(superClass);
                        superClass = clazz.getSuperclass().getName();
                    } catch (ClassNotFoundException e) {
                        superClass = null;
                    }
                }
            }
            if (isSubclass) {
                filteredMethods.add(methodNode);
            }
        } else if ((methodNode.access & Opcodes.ACC_PRIVATE) == 0) {
            // package-private
            String methodPackage = enclosingClassNode.name.substring(0, enclosingClassNode.name.lastIndexOf("/"));
            String classPackage = methodNode.owner.substring(0, methodNode.owner.lastIndexOf("/"));
            if (methodPackage.equals(classPackage)) {
                filteredMethods.add(methodNode);
            }
        }
    }
    return filteredMethods;
}
