public static <K> Date parseDate(K value) {
    if (value == null) {
        return null;
    }
    try {
        if (value instanceof Date) {
            return (Date) value;
        }
        SimpleDateFormat formatter = new SimpleDateFormat("yyyy-MM-dd");
        return formatter.parse(value.toString());
    } catch (ParseException e) {
        throw new IllegalArgumentException("Unable to parse date from value: " + value, e);
    }
}
