public CPOption deleteCPOption(long CPOptionId) throws PortalException {
    CPOption cpOption = getCPOption(CPOptionId);
    if (cpOption == null) {
        throw new PortalException("CPOption with id " + CPOptionId + " does not exist");
    }
    try {
        cpOptionPersistence.remove(cpOption);
        resourceLocalService.deleteResource(cpOption.getCompanyId(), CPOption.class.getName(),
                ResourceConstants.SCOPE_INDIVIDUAL, cpOption.getCPOptionId());
    } catch (NoSuchModelException e) {
        throw new PortalException(e);
    } catch (SystemException e) {
        throw new PortalException(e);
    }
    return cpOption;
}
