public boolean isScenarioOutdated(Map<String, String> defaultTranslations, Map<String, String> enTranslations, Map<String, String> frTranslations, String key) {
    if (!defaultTranslations.containsKey(key)) {
        return true;
    }
    String defaultTranslation = defaultTranslations.get(key);
    String enTranslation = enTranslations.get(key);
    String frTranslation = frTranslations.get(key);

    if (defaultTranslation == null || !defaultTranslation.equals(enTranslation)) {
        return true;
    }
    if (defaultTranslation.equals(frTranslation)) {
        return false;
    }
    return true;
}
