public static String createEncodedQueryString(HttpServletRequest request) {
    Map<String, String[]> parameterMap = request.getParameterMap();
    if (parameterMap.isEmpty()) {
        return null;
    }
    StringBuilder encodedQueryStringBuilder = new StringBuilder();
    try {
        for (Map.Entry<String, String[]> entry : parameterMap.entrySet()) {
            String name = URLEncoder.encode(entry.getKey(), StandardCharsets.UTF_8.name());
            for (String value : entry.getValue()) {
                if (encodedQueryStringBuilder.length() > 0) {
                    encodedQueryStringBuilder.append("&");
                }
                encodedQueryStringBuilder.append(name);
                encodedQueryStringBuilder.append("=");
                encodedQueryStringBuilder.append(URLEncoder.encode(value, StandardCharsets.UTF_8.name()));
            }
        }
    } catch (UnsupportedEncodingException ex) {
        throw new RuntimeException("Failed to encode query string.", ex);
    }
    return encodedQueryStringBuilder.toString();
}
