public static CellStyle getColumnStyle(Workbook wb, FormulaEvaluator fcell, Cell poiCell, float rowHeight) {
    CellStyle style = poiCell.getCellStyle();
    int colIndex = poiCell.getColumnIndex();
    int rowIndex = poiCell.getRowIndex();
    if (rowIndex == 0) {
        float defaultHeight = wb.getSheetAt(0).getDefaultRowHeightInPoints();
        float maxHeight = defaultHeight * 2;
        float minHeight = defaultHeight * 0.75f;
        if (rowHeight > maxHeight) {
            rowHeight = maxHeight;
        } else if (rowHeight < minHeight) {
            rowHeight = minHeight;
        }
    }
    return style;
}
