public void traceJndiCall(String methodName, Object... objs) {
    StringBuilder message = new StringBuilder("JNDI_CALL ");
    message.append(methodName).append(": ");
    for (Object obj : objs) {
        message.append(obj.toString()).append(", ");
    }
    message.delete(message.length() - 2, message.length()); // remove the last comma and space
