import java.io.File;

public class UniqueNameCreator {
    public String createUniqueName(String name) {
        String fileName = name;
        int counter = 0;
        File file = new File(fileName);

        while (file.exists()) {
            counter++;
            fileName = name + counter;
            file = new File(fileName);
        }

        return fileName;
    }
}
