public Byte[] byteArrayToByteObjectArray(byte[][] dd) {
        int height = dd.length;
        int width = dd[0].length;
        Byte[] result = new Byte[height*width];

        for(int i = 0; i < height; i++){
            for(int j = 0; j < width; j++){
                result[i*width+j] = Byte.valueOf(dd[i][j]);
            }
        }

        return result;
}
