public static SFSObject serializeObject(Method[] methods, Object object) {
    SFSObject serializedObject = new SFSObject();
    for (Method method : methods) {
        try {
            Object value = method.invoke(object);
            if (value != null) {
                if (value instanceof Integer) {
                    serializedObject.putInt(method.getName(), (Integer) value);
                } else if (value instanceof Long) {
                    serializedObject.putLong(method.getName(), (Long) value);
                } else if (value instanceof Double) {
                    serializedObject.putDouble(method.getName(), (Double) value);
                } else if (value instanceof Boolean) {
                    serializedObject.putBool(method.getName(), (Boolean) value);
                } else if (value instanceof String) {
                    serializedObject.putUtfString(method.getName(), (String) value);
                } else if (value instanceof List) {
                    List<Object> list = (List<Object>) value;
                    if (!list.isEmpty()) {
                        if (list.get(0) instanceof Integer) {
                            serializedObject.putIntArray(method.getName(), list.stream().mapToInt(i -> (Integer) i).toArray());
                        } else if (list.get(0) instanceof Long) {
                            serializedObject.putLongArray(method.getName(), list.stream().mapToLong(i -> (Long) i).toArray());
                        } else if (list.get(0) instanceof Double) {
                            serializedObject.putDoubleArray(method.getName(), list.stream().mapToDouble(i -> (Double) i).toArray());
                        } else if (list.get(0) instanceof Boolean) {
                            serializedObject.putBoolArray(method.getName(), list.stream().mapToBoolean(i -> (Boolean) i).toArray());
                        } else if (list.get(0) instanceof String) {
                            serializedObject.putUtfStringArray(method.getName(), list.stream().map(i -> (String) i).toArray(String[]::new));
                        } else {
                            SFSArray nestedArray = new SFSArray();
                            for (Object obj : list) {
                                nestedArray.add(serializeObject(obj.getClass().getMethods(), obj));
                            }
                            serializedObject.putSFSArray(method.getName(), nestedArray);
                        }
                    }
                } else if (value instanceof Map) {
                    @SuppressWarnings("unchecked")
                    Map<String, Object> map = (Map<String, Object>) value;
                    if (!map.isEmpty()) {
                        SFSObject nestedObject = new SFSObject();
                        for (Map.Entry<String, Object> entry : map.entrySet()) {
                            if (entry.getValue() != null) {
                                if (entry.getValue() instanceof Integer) {
                                    nestedObject.putInt(entry.getKey(), (Integer) entry.getValue());
                                } else if (entry.getValue() instanceof Long) {
                                    nestedObject.putLong(entry.getKey(), (Long) entry.getValue());
                                } else if (entry.getValue() instanceof Double) {
                                    nestedObject.putDouble(entry.getKey(), (Double) entry.getValue());
                                } else if (entry.getValue() instanceof Boolean) {
                                    nestedObject.putBool(entry.getKey(), (Boolean) entry.getValue());
                                } else if (entry.getValue() instanceof String) {
                                    nestedObject.putUtfString(entry.getKey(), (String) entry.getValue());
                                }
                            }
                        }
                        serializedObject.putSFSObject(method.getName(), nestedObject);
                    }
                } else {
                    serializedObject.putSFSObject(method.getName(), serializeObject(value.getClass().getMethods(), value));
                }
            }
        } catch (IllegalAccessException | InvocationTargetException e) {
            e.printStackTrace();
        }
    }
    return serializedObject;
}
