public String getTitle() throws ID3v2FormatException {
    String title = ""; // initialize title to empty string

    // check if title field is set
    if (isTitleSet()) {
        byte[] titleBytes = getTitleBytes();
        try {
            // decode title bytes using UTF-8 encoding
            title = new String(titleBytes, "UTF-8");
        } catch (UnsupportedEncodingException e) {
            // throw exception if UTF-8 encoding is not supported
            throw new ID3v2FormatException("Unsupported encoding for title field.");
        }
    }

    return title; // return title string
}
