      if (subset.isInSubset(scan)) {
        isOkToUnload = true;
        for (LCMSDataSubset exludedSubset : exlude) {
          if (exludedSubset.isInSubset(scan)) {
            isOkToUnload = false;
            break;
          }
        }
        if (isOkToUnload) {
          scan.setSpectrum(null, false);
        }
      }
    }
