import java.net.URL;
import java.util.*;

public List<URL> scanBundleForProcessDefinitions(Bundle bundle) {
    List<URL> processDefURLs = new ArrayList<>();

    // Get the header value for the process definitions location
    String processDefHeader = bundle.getHeaders().get(Constants.BUNDLE_PROCESS_DEFINITIONS_HEADER);

    // If the header is not null, extract the URLs and add them to the list
    if (processDefHeader != null) {
        processDefURLs.addAll(Arrays.asList(bundle.getResources(processDefHeader)));
    }

    // If the header is null or did not find any URLs, try the default location
    if ((processDefHeader == null || processDefURLs.isEmpty()) && bundle.getEntry(Constants.BUNDLE_PROCESS_DEFINTIONS_DEFAULT) != null) {
        processDefURLs.add(bundle.getResource(Constants.BUNDLE_PROCESS_DEFINTIONS_DEFAULT));
    }

    return processDefURLs;
}
