public void setRequestHeader(String headerName, String headerValue) {
    // Convert the header name to lowercase to perform case-insensitive comparison
    String name = headerName.toLowerCase();

    // Loop through all existing headers and check if the header name matches
    for (int i = 0; i < requestHeaders.size(); i++) {
        String existingName = requestHeaders.get(i).getName().toLowerCase();
        if (existingName.equals(name)) {
            // Replace the existing header with the new value
            requestHeaders.set(i, new Header(headerName, headerValue));
            return;
        }
    }

    // If no existing header was found, add a new one
    requestHeaders.add(new Header(headerName, headerValue));
}
