public int singlePathFunction(Node it1, Node it2, Node heavyPath) {
    int dist = 0;

    while (heavyPath != lca(it1, it2)) {
        if (height(heavyPath.left) > height(heavyPath.right)) {
            dist += heavyPath.weight + distance(heavyPath, it1);
            it1 = heavyPath.parent;
        } else {
            dist += heavyPath.weight + distance(heavyPath, it2);
            it2 = heavyPath.parent;
        }
        heavyPath = heavyPath.parent;
    }

    dist += distance(lca(it1, it2), it1) + distance(lca(it1, it2), it2);

    return dist;
}
