public Geometry getOffsetLine(Geometry geometry, double offset, BufferParameters parameters) {
    // Check input validity
    if(geometry == null || parameters == null) {
        return null;
    }

    // Compute buffer zone
    Geometry bufferGeometry = geometry.buffer(offset, parameters);
    if(bufferGeometry == null) {
        return null;
    }

    // Compute line with correct side
    if(geometry instanceof LineString) {
        return bufferGeometry;
    } else if(geometry instanceof Polygon) {
        Polygon polygonGeometry = (Polygon) geometry;
        Coordinate[] shellCoords;

        if(offset > 0) {
            shellCoords = bufferGeometry.getExteriorRing().getCoordinates();
        } else {
            shellCoords = bufferGeometry.getInteriorRingN(0).getCoordinates();
        }

        return new GeometryFactory().createLineString(shellCoords);
    } else {
        return null;
    }
}
