public <U> boolean call(Subscriber<? super U> subscriber) {
    try {
        subscriber.onStart();
        for (Object value : values) {
            if (value == null) {
                subscriber.onError(new NullPointerException("NotificationLite values array contains a null element"));
                return true;
            }
            if(NotificationLite.accept(value, subscriber)) {
                return true;
            }
        }
        subscriber.onCompleted();
        return true;
    } catch (Throwable ex) {
        Exceptions.throwIfFatal(ex);
        subscriber.onError(ex);
        return true;
    }
}
