public static String getCommandLineInterfaceText(Class<?> aClass, Class<?> requiredType) {
    Method[] methods = aClass.getDeclaredMethods();
    StringBuilder builder = new StringBuilder();
    for (Method method : methods) {
        if (method.getParameterTypes().length == 0 
                && method.getReturnType().equals(requiredType)) {
            builder.append(method.getName()).append(System.lineSeparator());
        }
    }
    String result = builder.toString();
    return result.trim();
}
