public Object getResultFromSession(String key) {
    if (key == null) throw new NullPointerException("key cannot be null");
    Object result = getSession().getAttribute(key);
    if (result == null) {
        // Recursively prepare session with @Load parents
        prepareSessionWithLoadParents();

        // Get the result again from session
        result = getSession().getAttribute(key);

        // Put the result in the session if necessary
        if (result == null) {
            result = calculateResult(); // calculate result if not found in session
            getSession().setAttribute(key, result); // put the result in the session
        }
    }
    return result;
}
