import javax.net.ssl.SSLSocket;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;

public static void performProxyHandshakeAndSSLHandshake(
        SSLSocket sslSocket,
        String proxyHost, int proxyPort,
        String targetHost, int targetPort,
        String proxyUsername, String proxyPassword
) throws IOException {
    // Open a socket to the proxy server
    Socket proxySocket = new Socket(proxyHost, proxyPort);

    // Send a CONNECT request to the proxy server
    String connectRequest = "CONNECT " + targetHost + ":" + targetPort + " HTTP/1.1\r\n";
    if (proxyUsername != null && proxyPassword != null) {
        String credentials = proxyUsername + ":" + proxyPassword;
        byte[] credentialsEncoded = Base64.getEncoder().encode(credentials.getBytes());
        connectRequest += "Proxy-Authorization: Basic " + new String(credentialsEncoded) + "\r\n";
    }
    connectRequest += "\r\n";
    OutputStream proxyOutputStream = proxySocket.getOutputStream();
    proxyOutputStream.write(connectRequest.getBytes());
    proxyOutputStream.flush();

    // Wait for the proxy server to respond with a success code
    InputStream proxyInputStream = proxySocket.getInputStream();
    byte[] buffer = new byte[8192];
    int read = proxyInputStream.read(buffer);
    String response = new String(buffer, 0, read);
    if (!response.startsWith("HTTP/1.1 200")) {
        throw new IOException("Failed to establish a tunnel through the proxy server.");
    }

    // Perform SSL handshake with the remote server through the proxy
    sslSocket.startHandshake();
}
