public void reject(int errorCode) throws IllegalStateException, IOException {
    if (accepted || rejected) {
        throw new IllegalStateException("The acceptance or rejection has already been made.");
    }
    if (socket.isClosed()) {
        throw new IOException("The connection is already closed.");
    }
    // Reject the bind request
    byte[] rejection = createRejectPacket(errorCode);
    DatagramPacket rejectionPacket = new DatagramPacket(rejection, rejection.length, remoteAddress);
    socket.send(rejectionPacket);
    rejected = true;
}
