public EsaSubsystemFeatureDefinitionImpl createEsaSubsystemFeatureDefinition(File esa) throws ZipException, IOException {
    // First, we need to extract the contents of the esa file.
    Path tempDir = Files.createTempDirectory("tempDir"); // Create a temporary directory to extract the contents to.
    ZipFile zipFile = new ZipFile(esa);
    zipFile.extractAll(tempDir.toAbsolutePath().toString());

    // Next, we need to find the subsystem definition file within the esa.
    File subsystemDefFile = null;
    try (Stream<Path> paths = Files.walk(tempDir)) {
        subsystemDefFile = paths
                .filter(Files::isRegularFile)
                .filter(file -> file.getFileName().toString().equals("Subsystem-Def.def"))
                .findFirst()
                .orElse(null);
        if (subsystemDefFile == null) {
            throw new FileNotFoundException("Could not find Subsystem-Def.def file in esa.");
        }
    }

    // Finally, we can create an EsaSubsystemFeatureDefinitionImpl instance and return it.
    return new EsaSubsystemFeatureDefinitionImpl(subsystemDefFile.toPath());
}
