public static <T> DSL<T> createDSL(Class<T> type) {
    return new DSL<>(type);
}

public class DSL<T> {
    private final Class<T> type;
    private String field;
    private Object value;

    public DSL(Class<T> type) {
        this.type = type;
    }

    public DSL<T> with(String field, Object value) {
        this.field = field;
        this.value = value;
        return this;
    }

    public T build() {
        try {
            T instance = type.getDeclaredConstructor().newInstance();
            Field field = type.getDeclaredField(this.field);
            field.setAccessible(true);
            field.set(instance, this.value);
            return instance;
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}
