import java.io.*;

public String copyFile(InputStream inputStream, String pathToExtractTo, String filename, boolean overwriteFilesThatExist) throws IOException {
    File directory = new File(pathToExtractTo);
    if (!directory.exists()) {
        directory.mkdirs();
    }
    File file = new File(directory, filename);

    if (!overwriteFilesThatExist && file.exists()) {
        return file.getAbsolutePath();
    }

    try (OutputStream outputStream = new FileOutputStream(file)) {
        byte[] buffer = new byte[8192];
        int length;
        while ((length = inputStream.read(buffer)) > 0) {
            outputStream.write(buffer, 0, length);
        }
    }
    return file.getAbsolutePath();
}
