public void appendSuffix(String tl, String td, StringBuilder sb) {
    if (tl.equals("start") && td.equals("forward")) {
        sb.append(" (from start)");
    } else if (tl.equals("start") && td.equals("backward")) {
        sb.append(" (last from start)");
    } else if (tl.equals("end") && td.equals("forward")) {
        sb.append(" (up to end)");
    } else if (tl.equals("end") && td.equals("backward")) {
        sb.append(" (last to end)");
    }
}
