public static String join(String[] array, String sep, int from, int upto) {
    if (array == null || array.length == 0) {
        return "";
    }

    StringBuilder sb = new StringBuilder();

    for (int i = from; i < upto && i < array.length; i++) {
        if (array[i] == null) {
            sb.append("");
        } else {
            sb.append(array[i]);
        }

        if (i < upto - 1 && i < array.length - 1) {
            sb.append(sep);
        }
    }

    return sb.toString();
}
