public int bindSelectionCriteria(PreparedStatement stmt, int index, Criteria crit, ClassDescriptor cld) throws SQLException {
    SelectionCriteria selCrit = crit.getSelectionCriteria();
    if (selCrit == null) {
        return index;
    }
    for (Iterator i = selCrit.getFields().iterator(); i.hasNext();) {
        FieldCriteria fCrit = (FieldCriteria) i.next();
        String fieldName = fCrit.getField().getAttributeName();
        int nextIndex = fCrit.getField().getSqlType().bindValue(stmt, index, fCrit.getValue());
        if (fCrit.getField().isJdbcOidField()) {
            selectIdentity(stmt, fieldName, cld.getObjectClass());
        }
        index = nextIndex;
    }
    return index;
}
