public byte[] serializeLink(ByteBuffer buffer, ORID iParentRecord, Object iLinked) {
    ByteArrayOutputStream byteOutputStream = new ByteArrayOutputStream();
    DataOutputStream dataOutputStream = new DataOutputStream(byteOutputStream);

    try {
        if(iLinked instanceof ORID) {
            ORID linkedOrid = (ORID)iLinked;
            dataOutputStream.writeByte(ORID.LINK);
            linkedOrid.toStream(dataOutputStream);
        } else if(iLinked instanceof Record) {
            Record linkedRecord = (Record)iLinked;
            dataOutputStream.writeByte(ORID.RECORD_BYTES);
            linkedRecord.getIdentity().toStream(dataOutputStream);
            buffer.putInt(linkedRecord.getVersion());
        } else {
            throw new IllegalArgumentException("Invalid iLinked argument");
        }

        dataOutputStream.flush();
        return byteOutputStream.toByteArray();
    } catch(IOException e) {
        throw new RuntimeException(e);
    }
}
