public int computeBranchWeight(Node node) {
    if (node == null) {
        return 0;
    } else {
        int leftBranchWeight = computeBranchWeight(node.getLeftChild());
        int rightBranchWeight = computeBranchWeight(node.getRightChild());

        return node.getWeight() + Math.max(leftBranchWeight, rightBranchWeight);
    }
}
