public void injectScheduledExecutorService(ServiceReference<ScheduledExecutorService> schedulerRef) {
    ScheduledExecutorService newScheduler = bundleContext.getService(schedulerRef);
    if (newScheduler != null && !newScheduler.equals(scheduler)) {
        synchronized (monitorMap) {
            for (Monitor monitor : monitorMap.values()) {
                if (monitor.getFuture() != null) {
                    monitor.getFuture().cancel(false);
                    scheduleMonitor(monitor, newScheduler);
                }
            }
        }
        scheduler = newScheduler;
    }
}
