import java.io.File;
import java.util.ArrayList;

public ArrayList<File> findSSHPrivateKeys(ArrayList<File> sshDirectories) {
    ArrayList<File> privateKeys = new ArrayList<File>();
    for (File directory : sshDirectories) {
        File[] files = directory.listFiles();
        if (files != null) {
            for (File file : files) {
                if (file.isFile() && (file.getName().equals("id_rsa") || file.getName().equals("id_dsa"))) {
                    privateKeys.add(file);
                }
            }
        }
    }
    return privateKeys;
}
