public <T> T getAncestor(Class<T> clazz) {
    Object ancestor = this; // start from the current object
    while (ancestor != null) {
        if (clazz.isInstance(ancestor)) {
            return clazz.cast(ancestor); // found the ancestor of the specified class
        }
        ancestor = ((ParentClass)ancestor).getParent(); // go up to the parent class
    }
    return null; // not found
}
