public void setTimeFromMilliseconds(long millis) {
    // Validate the millis parameter
    if (millis < 0 || millis > 86400000) {
        throw new IllegalArgumentException("Invalid value for milliseconds");
    }

    // Copy the time part from the millis parameter
    Calendar calendar = Calendar.getInstance();
    calendar.setTimeInMillis(millis);
    int hour = calendar.get(Calendar.HOUR_OF_DAY);
    int minute = calendar.get(Calendar.MINUTE);
    int second = calendar.get(Calendar.SECOND);
    int millisecond = calendar.get(Calendar.MILLISECOND);

    // Set the time part to this object
    this.set(Calendar.HOUR_OF_DAY, hour);
    this.set(Calendar.MINUTE, minute);
    this.set(Calendar.SECOND, second);
    this.set(Calendar.MILLISECOND, millisecond);
}
