public void printCircularGraph(String[] nodes, Map<String, List<String>> edges) throws CircularDependenciesException{
    Map<String, Integer> visited = new HashMap<>();
    Stack<String> stack = new Stack<>();

    for (String node : nodes) {
        if (!visited.containsKey(node)) {
            topologicalSort(node, edges, visited, stack);
        }
    }

    String lastNodeVisited = stack.peek();
    Set<String> path = new HashSet<>();
    path.add(lastNodeVisited);

    while (!stack.isEmpty()) {
        String node = stack.pop();

        if (!lastNodeVisited.equals(node) && path.contains(node)) {
            throw new CircularDependenciesException("Circular dependency found!");
        }

        lastNodeVisited = node;
        System.out.println(node);

        if (edges.containsKey(node)) {
            for (String neighbor : edges.get(node)) {
                path.add(node);
                topologicalSort(neighbor, edges, visited, stack);
                path.remove(node);
            }
        }
    }
}

private void topologicalSort(String node, Map<String, List<String>> edges, Map<String, Integer> visited, Stack<String> stack) {
    visited.put(node, 1);

    if (edges.containsKey(node)) {
        for (String neighbor : edges.get(node)) {
            if (!visited.containsKey(neighbor)) {
                topologicalSort(neighbor, edges, visited, stack);
            }
        }
    }

    stack.push(node);
}
