public String peekIonType(char c, Reader input) throws IOException {
    StringBuilder sb = new StringBuilder();
    input.mark(1);

    // Read characters until we encounter a dot or whitespace
    while (Character.isJavaIdentifierPart(c) && c != '.') {
        sb.append(c);
        input.mark(1);
        c = (char) input.read();
    }

    // If the characters we read match an ion type, return the corresponding keyword id
    String str = sb.toString();
    switch (str) {
        case "null":
            return "Null";
        case "true":
        case "false":
            return "Boolean";
        case "+":
        case "-":
        case "0":
        case "1":
        case "2":
        case "3":
        case "4":
        case "5":
        case "6":
        case "7":
        case "8":
        case "9":
            if (str.matches("-?[0-9]+")) {
                return "Int";
            } else {
                return "Float";
            }
        case "nan":
        case "inf":
        case "-inf":
            return "Float";
        case "b64":
            return "Blob";
        case "timestamp":
            return "Timestamp";
        case "symbol":
            return "Symbol";
        default:
            input.reset();
            return null;
    }
}
