public String createDeweyNumber(String deweyNumberString) {
   String[] deweyNumbers = deweyNumberString.split("\\.");
   StringBuilder deweyNumber = new StringBuilder();
   for (String number : deweyNumbers) {
      int num = Integer.parseInt(number);
      deweyNumber.append(String.format("%03d", num));
   }
   return deweyNumber.toString();
}
