public String resolveHostName(String host, String type) {
    String resolvedForm = "";
    try {
        InetAddress inetAddress = InetAddress.getByName(host);
        switch (type) {
            case "A":
                resolvedForm = inetAddress.getHostAddress();
                break;
            case "CNAME":
                resolvedForm = inetAddress.getCanonicalHostName();
                break;
            default:
                resolvedForm = "Invalid resource type.";
                break;
        }
    } catch (UnknownHostException e) {
        resolvedForm = "Hostname could not be resolved.";
    }
    return resolvedForm;
}
