public static int[] createHistogram(int[] eventCounters, Function<Integer, Integer> function) {
    int[] histogram = new int[eventCounters.length];
    for (int i = 0; i < eventCounters.length; i++) {
        int transformedValue = function.apply(eventCounters[i]);
        histogram[transformedValue]++;
    }
    return histogram;
}
