private String getPartitionSpec(ConversionEntity conversionEntity) {
    String partitionSpec = conversionEntity.getPartitionSpec1();
    if (conversionEntity.getPartitionSpec2() != null && !conversionEntity.getPartitionSpec2().isEmpty()) {
        partitionSpec = partitionSpec + "_" + conversionEntity.getPartitionSpec2();
    }
    if (conversionEntity.getPartitionSpec3() != null && !conversionEntity.getPartitionSpec3().isEmpty()) {
        partitionSpec = partitionSpec + "_" + conversionEntity.getPartitionSpec3();
    }
    return partitionSpec;
}
