public void bindValuesToObject(Object obj, PreparedStatement statement) throws SQLException {
    // Get the class of the object
    Class objClass = obj.getClass();

    // Get the list of fields in the object
    Field[] fields = objClass.getDeclaredFields();

    // Loop through the fields and bind their values to the statement's parameters
    int i = 1;
    for (Field field : fields) {
        field.setAccessible(true);

        // Get the value of the field in the object
        Object value = field.get(obj);

        // Bind the value to the statement's parameter at index i
        statement.setObject(i, value);

        // Increment the parameter index
        i++;
    }
}
