import htsjdk.samtools.*;

public void performIndexing(String bamFilePath, int granularityLevel) {
    // Open the BAM file
    SamReader reader = SamReaderFactory.makeDefault().open(new File(bamFilePath));

    // Choose the granularity level
    BAMIndexer indexer = new BAMIndexer(new File(bamFilePath + ".bai"), reader.getFileHeader());
    indexer.setIndexGranularity(granularityLevel);

    // Iterate over the aligned reads and add them to the index
    BAMRecordIterator iter = reader.iterator();
    while (iter.hasNext()) {
        SAMRecord rec = iter.next();
        indexer.processAlignment(rec);
    }

    // Finish the indexing and close the input and output files
    iter.close();
    reader.close();
    indexer.finish();
}
