public void indexDocument(Document iDocument) {
    // Get all the fields in the document
    List<Field> fields = iDocument.getFields();

    // Create a new index for the document
    Index index = new Index();

    // Loop through all the fields in the document
    for (Field field : fields) {
        // Get the name and value of the field
        String name = field.getName();
        String value = field.getValue();

        // Index the field
        index.addField(name, value);
    }

    // Save the index
    index.save();
}
