public static void runParallelFunctions(final Runnable... functions) {
    final CountDownLatch latch = new CountDownLatch(functions.length);

    for (final Runnable function : functions) {
        new Thread(new Runnable() {
            @Override
            public void run() {
                try {
                    function.run();
                } catch (Exception e) {
                    // Pass the error to the latch's await() method.
                    latch.countDown();
                    return;
                }
                // Count down the latch's await() method.
                latch.countDown();
            }
        }).start();
    }

    // Wait for all functions to finish, or until an error is caught.
    try {
        latch.await();
    } catch (InterruptedException e) {
        e.printStackTrace();
    }
}
