public void closeProfileProxy(int profile, BluetoothProfile proxy) {
  if (mProfileProxies == null) {
    return;
  }

  synchronized (mProfileProxies) {
    BluetoothProfile priorProxy = mProfileProxies.get(profile);
    if (priorProxy == proxy) {
      mProfileProxies.put(profile, null);
      try {
        mService.closeProfileProxy(profile, priorProxy);
      } catch (RemoteException e) {
        Log.e(TAG, "Error talking to BT service in closeProfileProxy", e);
      }
    }
  }
}
