import java.io.File;

public void createDirectoryAtIndex(int pos) {
    // Construct the parent path
    StringBuilder parentPathBuilder = new StringBuilder();
    for (int i = 0; i < pos; i++) {
        parentPathBuilder.append(File.separator);
        parentPathBuilder.append(i);
    }
    String parentPath = parentPathBuilder.toString();

    // Create the parent directory if it doesn't exist
    File parentDir = new File(parentPath);
    if (!parentDir.exists()) {
        parentDir.mkdirs();
    }

    // Create the directory at the specified index
    File newDir = new File(parentPath + File.separator + pos);
