public int getMousePositionRelativeToTop(Document document) {
    Element root = document.getDocumentElement();
    Node mouse = document.createElement("mouse");
    Node top = root.getElementsByTagName("top").item(0);
    int mouseYPos = mouse.getClientRects()[0].top;
    int topPos = top.getClientRects()[0].top;
    return mouseYPos - topPos;
}
