public static double averageCPUUtil(double[] cpuUtilData) {
    double sum = 0.0;
    int count = 0;
    int length = cpuUtilData.length;
    int startTime = (length < 60) ? 0 : length - 60;
    int endTime = length - 1;
    for(int i = startTime; i <= endTime; i++) {
        sum += cpuUtilData[i];
        count++;
    }
    return (sum / count);
}
