public Node findNodeByKey(Node root, int key) {
    if (root == null) {
        return null;
    }
    if (root.key == key) {
        return root;
    }
    if (key < root.key) {
        return findNodeByKey(root.left, key);
    } else {
        return findNodeByKey(root.right, key);
    }
}
