public static void updateMatrix(Matrix matrix, Function<Integer, Integer> function) {
    int rows = matrix.getNumRows();
    int cols = matrix.getNumColumns();
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            int oldValue = matrix.getElement(i, j);
            int newValue = function.apply(oldValue);
            matrix.setElement(i, j, newValue);
        }
    }
}
