public static <T, K> boolean searchVector(Vector<T> secondVector, Entry<K, T> entry) {
    if (secondVector == null || entry == null) {
        return false;
    }
    for (T element : secondVector) {
        Entry<K, T> currentEntry = (Entry<K, T>) element;
        if (currentEntry.getKey().equals(entry.getKey()) && currentEntry.getValue().equals(entry.getValue())) {
            return true;
        }
    }
    return false;
}
