import javax.xml.datatype.DatatypeFactory;
import javax.xml.datatype.XMLGregorianCalendar;
import java.util.Date;

public class TimestampUtil {

    public static XMLGregorianCalendar timestamp(Date date) {
        try {
            DatatypeFactory dataTypeFactory = DatatypeFactory.newInstance();
            XMLGregorianCalendar xmlGregorianCalendar = dataTypeFactory.newXMLGregorianCalendar();
            xmlGregorianCalendar.setTimezone(0);
            xmlGregorianCalendar.setTime(date.getHours(), date.getMinutes(), date.getSeconds());
            xmlGregorianCalendar.setDay(date.getDate());
            xmlGregorianCalendar.setMonth(date.getMonth() + 1);
            xmlGregorianCalendar.setYear(date.getYear() + 1900);
            return xmlGregorianCalendar;
        } catch (Exception e) {
            throw new RuntimeException("Error while converting the given date to XMLGregorianCalendar", e);
        }
    }
}
