public static boolean iteratorsEqual(Iterator<?> i1, Iterator<?> i2) {
    while (i1.hasNext() && i2.hasNext()) {
        Object o1 = i1.next();
        Object o2 = i2.next();
        if (!Objects.equals(o1, o2)) {
            return false;
        }
    }
    return !i1.hasNext() && !i2.hasNext();
}
