public Set<String> searchForPreviousDeployments(CommandContext commandContext, Deployment deployment) {
    Set<String> previousDeploymentIds = new HashSet<>();
    List<Deployment> deployments = commandContext.getDeploymentManager().findDeploymentsByName(deployment.getName());
    for (Deployment previousDeployment : deployments) {
        if (!previousDeployment.getId().equals(deployment.getId())) {
            previousDeploymentIds.add(previousDeployment.getId());
        }
    }
    return previousDeploymentIds;
}
