import java.util.HashSet;
import java.util.Set;
import org.apache.bcel.classfile.ConstantPool;
import org.apache.bcel.classfile.ConstantPoolGen;
import org.apache.bcel.generic.ClassGen;
import org.apache.bcel.generic.ConstantPoolGen;
import org.apache.bcel.generic.InvokeInstruction;
import org.apache.bcel.generic.MethodGen;
import org.apache.bcel.generic.Type;
import org.apache.bcel.verifier.exc.AssertionViolatedException;
import org.apache.bcel.verifier.exc.StructuralCodeConstraintException;
import org.apache.bcel.verifier.structurals.Type;

public class MethodCallResolver {

    public static Set<MethodGen> resolveMethodCallTargets(InvokeInstruction invokeInstruction, TypeFrame typeFrame, ConstantPoolGen cpg) throws DataflowAnalysisException, ClassNotFoundException {
        Set<MethodGen> setMethods = new HashSet<MethodGen>();
        try {
            Type[] argTypes = invokeInstruction.getArgumentTypes(cpg);
            String methodName = invokeInstruction.getMethodName(cpg);
            String className = invokeInstruction.getClassName(cpg);

            // resolve instructions for both static and instance methods
            if (invokeInstruction instanceof INVOKESTATIC) {
                setMethods.addAll(resolveStaticMethodCallTargets(className, methodName, argTypes, cpg));
            } else if (invokeInstruction instanceof INVOKEVIRTUAL) {
                setMethods.addAll(resolveInstanceMethodCallTargets(className, methodName, argTypes, cpg));
            } else if (invokeInstruction instanceof INVOKESPECIAL) {
                setMethods.addAll(resolveInstanceMethodCallTargets(className, methodName, argTypes, cpg));
            } else if (invokeInstruction instanceof INVOKEINTERFACE) {
                setMethods.addAll(resolveInterfaceMethodCallTargets(className, methodName, argTypes, cpg));
            }
        } catch (AssertionViolatedException e) {
            throw new DataflowAnalysisException(e.toString());
        } catch (StructuralCodeConstraintException e) {
            throw new DataflowAnalysisException(e.toString());
        }
        return setMethods;
    }

    private static Set<MethodGen> resolveStaticMethodCallTargets(String className, String methodName, Type[] argTypes,
            ConstantPoolGen cpg) throws ClassNotFoundException {
        Set<MethodGen> setMethods = new HashSet<MethodGen>();
        ClassGen classGen = new ClassGen(className);
        for (Method m : classGen.getMethods()) {
            if (m.getName().equals(methodName) && m.isStatic() && signaturesMatch(m.getArgumentTypes(), argTypes)) {
                setMethods.add(new MethodGen(m, classGen.getClassName(), cpg));
            }
        }
        return setMethods;
    }

    private static Set<MethodGen> resolveInstanceMethodCallTargets(String className, String methodName, Type[] argTypes,
            ConstantPoolGen cpg) throws ClassNotFoundException {
        Set<MethodGen> setMethods = new HashSet<MethodGen>();
        ClassGen classGen = new ClassGen(className);
        while (classGen != null) {
            for (Method m : classGen.getMethods()) {
                if (m.getName().equals(methodName) && !m.isStatic() && signaturesMatch(m.getArgumentTypes(), argTypes)) {
                    setMethods.add(new MethodGen(m, classGen.getClassName(), cpg));
                }
            }
            classGen = classGen.getSuperclass();
        }
        return setMethods;
    }

    private static Set<MethodGen> resolveInterfaceMethodCallTargets(String className, String methodName, Type[] argTypes,
            ConstantPoolGen cpg) throws ClassNotFoundException {
        Set<MethodGen> setMethods = new HashSet<MethodGen>();
        ClassGen classGen = new ClassGen(className);
        for (String interfaceName : classGen.getInterfaceNames()) {
            ClassGen interfaceGen = new ClassGen(interfaceName);
            Method interfaceMethod = interfaceGen.getMethodByName(methodName);
            if (interfaceMethod != null && !interfaceMethod.isStatic() && signaturesMatch(interfaceMethod.getArgumentTypes(), argTypes)) {
                setMethods.add(new MethodGen(interfaceMethod, interfaceGen.getClassName(), cpg));
            }
        }
        return setMethods;
    }

    private static boolean signaturesMatch(Type[] signature1, Type[] signature2) {
        if (signature1.length != signature2.length) {
            return false;
        }
        for (int i = 0; i < signature1.length; i++) {
            if (!signature1[i].equals(signature2[i])) {
                if (signature1[i] instanceof Type.OBJECT && signature2[i] instanceof Type.OBJECT) {
                    ClassGen classGen1 = new ClassGen(signature1[i].toString());
                    ClassGen classGen2 = new ClassGen(signature2[i].toString());
                    if (!classGen2.isSuperclassOf(classGen1)) {
                        return false;
                    }
                } else {
                    return false;
                }
            }
        }
        return true;
    }
}
