public void waitForOperationToComplete(String operationName, int maxSeconds) throws InterruptedException {
    long startTime = System.currentTimeMillis();
    while (true) {
        if (TimeUnit.MILLISECONDS.toSeconds(System.currentTimeMillis() - startTime) > maxSeconds) {
            throw new InterruptedException("Operation did not complete within the specified time.");
        }
        // Check if the operation is completed
        if (checkOperationCompleted(operationName)) {
            return;
        }
        Thread.sleep(1000);
    }
}

