public ArrayStructure fixSizedStructures(Structure s, Section section) throws IOException, InvalidRangeException {
    int[] shape = section.getShape();
    int count = (int) section.computeSize();
    ByteBuffer bbuff = s.getByteBuffer(section);
    ArrayStructureW arrayW = new ArrayStructureW(s, shape);
    StructureMembers members = s.makeStructureMembers();
    ByteBufferIterator ii = new ByteBufferIterator(s.getDimensions(), bbuff);

    for (int i = 0; i < count; i++) {
        members.clear();
        s.readStructure(ii, members);
        arrayW.setStructureData(arrayW.addObject(), members);
    }

    return arrayW;
}
