public void addPosAndSentenceTags(JCas jcas) {
    try {
        // set TreeTagger home directory
        System.setProperty("treetagger.home", "/path/to/treetagger");

        // get document text from jcas
        String text = jcas.getDocumentText();

        // initialize TreeTagger model and tagger
        TreeTaggerWrapper<String> tagger = new TreeTaggerWrapper<>();
        tagger.setModel("taggerPath/english-utf8.par:iso8859-1");
        tagger.setHandler(new TokenHandler<String>() {
            @Override
            public void token(String token, String pos, String lemma) {
                // create annotation for each token with POS and sentence tags
                TokenAnnotation annotation = new TokenAnnotation(jcas);
                annotation.setBegin(offset);
                annotation.setEnd(offset + token.length());
                annotation.setPos(pos);
                // check if token is end of sentence
                if (token.endsWith(".") || token.endsWith("?") || token.endsWith("!")) {
                    annotation.setSentenceTag("EOS");
                } else {
                    annotation.setSentenceTag("");
                }
                annotation.addToIndexes();
                // increment offset
                offset += token.length() + 1;
            }
        });

        // process document text with TreeTagger
        tagger.process(asList(text.split("\\s+")));

        // clean up
        tagger.destroy();
    } catch (IOException | TreeTaggerException e) {
        e.printStackTrace();
    }
}
