public class QuestOWLEmptyEntitiesChecker {
    private final OWLOntology ontology;
    private final OWLDataFactory dataFactory;
    private final Map<String, String> classMappings;
    private final Map<String, String> objectPropertyMappings;
    private final Map<String, String> dataPropertyMappings;

    public QuestOWLEmptyEntitiesChecker(OWLOntology ontology, Map<String, String> classMappings, 
                            Map<String, String> objectPropertyMappings, Map<String, String> dataPropertyMappings) {
        this.ontology = ontology;
        this.classMappings = classMappings;
        this.objectPropertyMappings = objectPropertyMappings;
        this.dataPropertyMappings = dataPropertyMappings;
        this.dataFactory = ontology.getOWLOntologyManager().getOWLDataFactory();
    }

    public List<OWLClass> getEmptyConcepts() throws Exception {
        List<OWLClass> emptyClasses = new ArrayList<>();

        for (Map.Entry<String, String> classMapping : classMappings.entrySet()) {
            String uri = classMapping.getValue();
            String sparql = String.format("ASK { ?s a <%s> }", uri);

            boolean result = executeAskQuery(sparql);

            if (!result) {
                OWLClass emptyClass = dataFactory.getOWLClass(IRI.create(uri));
                emptyClasses.add(emptyClass);
            }
        }

        return emptyClasses;
    }

    public List<OWLObjectProperty> getEmptyObjectProperties() throws Exception {
        List<OWLObjectProperty> emptyObjectProperties = new ArrayList<>();

        for (Map.Entry<String, String> objectPropertyMapping : objectPropertyMappings.entrySet()) {
            String uri = objectPropertyMapping.getValue();
            String sparql = String.format("ASK { ?s <%s> ?o }", uri);

            boolean result = executeAskQuery(sparql);

            if (!result) {
                OWLObjectProperty emptyObjectProperty = dataFactory.getOWLObjectProperty(IRI.create(uri));
                emptyObjectProperties.add(emptyObjectProperty);
            }
        }

        return emptyObjectProperties;
    }

    public List<OWLDataProperty> getEmptyDataProperties() throws Exception {
        List<OWLDataProperty> emptyDataProperties = new ArrayList<>();

        for (Map.Entry<String, String> dataPropertyMapping : dataPropertyMappings.entrySet()) {
            String uri = dataPropertyMapping.getValue();
            String sparql = String.format("ASK { ?s <%s> ?o }", uri);

            boolean result = executeAskQuery(sparql);

            if (!result) {
                OWLDataProperty emptyDataProperty = dataFactory.getOWLDataProperty(IRI.create(uri));
                emptyDataProperties.add(emptyDataProperty);
            }
        }

        return emptyDataProperties;
    }

    private boolean executeAskQuery(String sparql) throws Exception {
        Query query = QueryFactory.create(sparql);
        QueryExecution queryExecution = QueryExecutionFactory.create(query, ontology);
        boolean result = queryExecution.execAsk();
        queryExecution.close();
        return result;
    }
}
