public static String getThreadIdFromStack() {
    StackTraceElement[] stackTraceElements = Thread.currentThread().getStackTrace();
    for (StackTraceElement element : stackTraceElements) {
        if (element.getMethodName().equals("logHandler")) { // assuming logHandler is the name of the method that calls this function
            return Thread.currentThread().getName();
        }
    }
    return null;
}
