public int renderEntities(List<Node> nodes, List<Integer> index, List<String> mustacheKeys, Map<Integer, Node> cachedNodes, StringBuilder stringBuilder) {
    int lastIndex = -1;
    for (int i = 0; i < nodes.size(); i++) {
        Node node = nodes.get(i);
        int nodeIndex = index.get(i);
        String mustacheKey = null;
        if (mustacheKeys != null && mustacheKeys.size() > i) {
            mustacheKey = mustacheKeys.get(i);
        }
        if (node == null) {
            continue;
        }

        if (cachedNodes.containsKey(nodeIndex)) {
            stringBuilder.append(renderEntity(cachedNodes.get(nodeIndex), mustacheKey));
        } else {
            stringBuilder.append(renderEntity(node, mustacheKey));
        }
        lastIndex = nodeIndex;
    }
    return lastIndex + 1;
}

