public void pruneFeatures(int neighbors, double distance) {
    List<Feature> prunedFeatures = new ArrayList<>();
    for (Feature feature : features) {
        Set<Feature> nearbyFeatures = new HashSet<>();
        for (Feature otherFeature : features) {
            if (!otherFeature.equals(feature) && feature.distanceTo(otherFeature) <= distance) {
                nearbyFeatures.add(otherFeature);
            }
        }
        if (nearbyFeatures.size() < neighbors) {
            prunedFeatures.add(feature);
            for (Observation observation : feature.getObservations()) {
                removeObservation(observation);
            }
        }
    }
    for (Feature prunedFeature : prunedFeatures) {
        removeFeature(prunedFeature);
    }
    pruneViews(1);
}
