public void convertType(Object value, DeviceData deviceDataArgin, int dataType) throws DevFailed {
    try {
        switch (dataType) {
            case TangoConst.Tango_DEV_SHORT:
                short shortValue = (short) value;
                deviceDataArgin.insert(shortValue);
                break;
            case TangoConst.Tango_DEV_LONG:
                int longValue = (int) value;
                deviceDataArgin.insert(longValue);
                break;
            case TangoConst.Tango_DEV_FLOAT:
                float floatValue = (float) value;
                deviceDataArgin.insert(floatValue);
                break;
            case TangoConst.Tango_DEV_DOUBLE:
                double doubleValue = (double) value;
                deviceDataArgin.insert(doubleValue);
                break;
            case TangoConst.Tango_DEV_BOOLEAN:
                boolean booleanValue = (boolean) value;
                deviceDataArgin.insert(booleanValue);
                break;
            case TangoConst.Tango_DEV_STRING:
                String stringValue = (String) value;
                deviceDataArgin.insert(stringValue);
                break;
            default:
                throw new DevFailed("Unsupported data type");
        }
    } catch (DevFailed e) {
        throw e;
    } catch (Exception e) {
        throw new DevFailed("Error in converting type", e);
    }
}
