import org.apache.http.client.HttpClient;
import org.apache.http.client.methods.HttpPost;
import org.apache.http.entity.StringEntity;
import org.apache.http.impl.client.HttpClientBuilder;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClients;

import java.io.IOException;

public class ApiClient {
    private static final String BASE_URL = "https://example.com/api/v1/login";
    private static final ObjectMapper objectMapper = new ObjectMapper();

    public ApiResponse login(String email, String password) throws IOException {
        CloseableHttpClient httpClient = null;
        CloseableHttpResponse httpResponse = null;

        try {
            httpClient = HttpClients.createDefault();
            HttpPost request = new HttpPost(BASE_URL);
            request.addHeader("Content-Type", "application/json");
            request.addHeader("Accept", "*/*");
            request.addHeader("User-Agent", "Apache-HttpClient/4.5.1");
            request.setEntity(new StringEntity(String.format("{\"email\":\"%s\",\"password\":\"%s\"}", email, password)));
            httpResponse = httpClient.execute(request);

            String response = EntityUtils.toString(httpResponse.getEntity());

            ApiResponse apiResponse = objectMapper.readValue(response, ApiResponse.class);

            return apiResponse;
        } finally {
            if (httpClient != null) {
                httpClient.close();
            }
            if (httpResponse != null) {
                httpResponse.close();
            }
        }
    }
}
