public Set<String> expandEnumeration(String enumeration) {
    Set<String> expandedSet = new HashSet<>();
    String[] values = enumeration.split(",");
    for (String value : values) {
        String[] range = value.trim().split("-");
        if (range.length > 1) {
            // it is a range
            int start = Integer.parseInt(range[0].trim());
            int end = Integer.parseInt(range[1].trim());
            for (int i = start; i <= end; i++) {
                expandedSet.add(String.valueOf(i));
            }
        } else {
            // it is a single value
            expandedSet.add(value.trim());
        }
    }
    return expandedSet;
}
