public AbstractTopology removeHosts(AbstractTopology currentTopology, List<HostInfo> removalHostInfos) {
    List<HostInfo> currentHostInfos = currentTopology.getHostInfos();
    List<PartitionInfo> currentPartitionInfos = currentTopology.getPartitionInfos();
    List<PartitionInfo> removedPartitionInfos = new ArrayList<>();
    List<HostInfo> remainingHostInfos = new ArrayList<>(currentHostInfos);
    for (HostInfo toRemove : removalHostInfos) {
        if (!currentHostInfos.contains(toRemove)) {
            throw new RuntimeException("Invalid hosts for topology");
        }
        Iterator<PartitionInfo> partitionIterator = currentPartitionInfos.iterator();
        while (partitionIterator.hasNext()) {
            PartitionInfo partition = partitionIterator.next();
            if (partition.getHostInfos().contains(toRemove)) {
                if (partition.getHostInfos().size() == 1) {
                    partitionIterator.remove();
                    removedPartitionInfos.add(partition);
                } else {
                    List<HostInfo> updatedHostInfos = partition.getHostInfos()
                            .stream()
                            .filter(hi -> !hi.equals(toRemove))
                            .collect(Collectors.toList());
                    partition.setHostInfos(updatedHostInfos);
                }
            }
        }
        remainingHostInfos.remove(toRemove);
    }
    return currentTopology.newInstance(remainingHostInfos, currentTopology.getSegmentInfos(), currentTopology.getSchema(), currentPartitionInfos, removedPartitionInfos);
}
