public String sendToEchoClient(String message) throws IOException {
    Socket socket = newSocket("localhost", 8080);
    sendMessage(socket, message);
    String response = receiveResponse(socket);
    socket.close();
    return response;
}

private Socket newSocket(String host, int port) throws IOException {
    return new Socket(host, port);
}

private void sendMessage(Socket socket, String message) throws IOException {
    PrintWriter out = new PrintWriter(socket.getOutputStream(), true);
    out.println(message);
}

private String receiveResponse(Socket socket) throws IOException {
    BufferedReader in = new BufferedReader(new InputStreamReader(socket.getInputStream()));
    return in.readLine();
}
