public LeafNode queryTree(Node from, HyperPlane planes, double[] x, SimilarityFunction similarityFunction) {
    if(from instanceof LeafNode) {
        return (LeafNode) from;
    }
    else {
        InternalNode internalNode = (InternalNode) from;
        double value = planes.evaluate(internalNode.splitDimension, x);
        Node next;
        if(value < internalNode.splitValue) {
            next = internalNode.leftChild;
        }
        else {
            next = internalNode.rightChild;
        }
        return queryTree(next, planes, x, similarityFunction);
    }
}
