import java.io.IOException;
import java.net.HttpURLConnection;
import java.net.InetSocketAddress;
import java.net.Proxy;
import java.net.URL;

public static HttpURLConnection httpsOverHttpProxy(URL url, String proxyHost, int proxyPort, String proxyUsername, String proxyPassword) throws IOException {
    Proxy proxy = new Proxy(Proxy.Type.HTTP, new InetSocketAddress(proxyHost, proxyPort));
    HttpURLConnection connection = (HttpURLConnection) url.openConnection(proxy);

    if (proxyUsername != null && proxyPassword != null) {
        String encodedCredentials = base64Encode((proxyUsername + ":" + proxyPassword).getBytes());
        connection.setRequestProperty("Proxy-Authorization", "Basic " + encodedCredentials);
    }

    connection.setRequestMethod("CONNECT");
    connection.setDoOutput(true);
    connection.getOutputStream().write("\r\n".getBytes());
    connection.connect();

    if (connection.getResponseCode() == HttpURLConnection.HTTP_PROXY_AUTH) {
        throw new IOException("Proxy authentication required.");
    } else if (connection.getResponseCode() != HttpURLConnection.HTTP_OK) {
        throw new IOException("Unable to connect to proxy.");
    }

    return connection;
}

private static String base64Encode(byte[] bytes) {
    return Base64.getEncoder().encodeToString(bytes);
}
