import java.awt.image.BufferedImage;

public static Dimension checkImageScaling(BufferedImage image, Dimension maxDimension) {
    Dimension imageSize = new Dimension(image.getWidth(), image.getHeight());

    if (maxDimension == null || imageSize.width <= maxDimension.width && imageSize.height <= maxDimension.height) {
        return null; // No scaling is required
    }

    Dimension scaledDimension = getScaledDimension(imageSize, maxDimension);

    if (scaledDimension.width <= 0 || scaledDimension.height <= 0) {
        return new Dimension(-1, -1); // Scaling is required but not possible
    }

    return scaledDimension; // Scaling is required and possible, return the scaled dimension
}

private static Dimension getScaledDimension(Dimension imageSize, Dimension maxDimension) {
    int originalWidth = imageSize.width;
    int originalHeight = imageSize.height;
    int maxWidth = maxDimension.width;
    int maxHeight = maxDimension.height;
    int newWidth = originalWidth;
    int newHeight = originalHeight;

    // First, scale to the width limit
    if (originalWidth > maxWidth) {
        newWidth = maxWidth;
        newHeight = (newWidth * originalHeight) / originalWidth;
    }

    // If the resulting height is too big, scale to the height limit instead
    if (newHeight > maxHeight) {
        newHeight = maxHeight;
        newWidth = (newHeight * originalWidth) / originalHeight;
    }

    return new Dimension(newWidth, newHeight);
}
