public class BroadcastRDivOp {

    /**
     * Performs a broadcast reverse division operation.
     *
     * @param dividend an array of dividend values
     * @param divisor an array of divisor values
     * @return an array of quotient values based on broadcast reverse division of dividend and divisor
     * @throws IllegalArgumentException if the length of dividend array is not same as divisor array 
     */
    public static double[] broadcastRDiv(double[] dividend, double[] divisor) {
        if (dividend.length != divisor.length) {
            throw new IllegalArgumentException("Length of dividend and divisor arrays must be same.");
        }

        double[] quotient = new double[dividend.length];
        for (int i = 0; i < dividend.length; i++) {
            quotient[i] = divisor[i] / dividend[i];
        }

        return quotient;
    }

}
