public File synchronizeLogSegment(String url, long epoch) throws IOException {
    String tempFileName = "log_" + epoch + "_temp";
    URL logSegmentUrl = new URL(url);
    File tempFile = File.createTempFile(tempFileName, null);
    tempFile.deleteOnExit();
    try (InputStream in = logSegmentUrl.openStream();
         FileOutputStream out = new FileOutputStream(tempFile)) {
        byte[] buffer = new byte[4096];
        int bytesRead;
        while ((bytesRead = in.read(buffer)) != -1) {
            out.write(buffer, 0, bytesRead);
        }
    }
    return tempFile;
}
