public int readMarkdownLink(StringBuilder out, String in, int start) {
    int pos = start;

    boolean isLink = false;
    boolean isImage = false;

    int length = in.length();

    if (pos < length && in.charAt(pos) == '[') {
        isLink = true;
    } else if (pos + 1 < length && in.charAt(pos) == '!' && in.charAt(pos + 1) == '[') {
        isImage = true;
        pos++;
    } else {
        return -1;
    }

    if (isLink) {
        pos++;
    }

    int textStart = pos;
    int textEnd = in.indexOf(']', pos);

    if (textEnd == -1) {
        return -1;
    }

    int linkStart = textEnd + 1;

    if (linkStart < length && in.charAt(linkStart) == '(') {
        linkStart++;
    } else {
        return -1;
    }

    int linkEnd = in.indexOf(')', linkStart);

    if (linkEnd == -1) {
        return -1;
    }

    out.append(in, textStart, textEnd);

    if (isLink) {
        out.append("](").append(in, linkStart, linkEnd).append(')');
    } else {
        out.append("![");
        out.append(in, textStart, textEnd);
        out.append("](").append(in, linkStart, linkEnd).append(')');
    }

    return linkEnd + 1;
}
