public char next() throws IOException {
    char c = input.read();
    if (c == '/') {
        if (input.peek() == '/')
            while (input.read() != '\n') ;
        else if (input.peek() == '*') {
            input.read();
            while (true) {
                c = input.read();
                if (c == '/') break;
                if (c == '*' && input.peek() == '/') {
                    input.read();
                    break;
                }
            }
        }
    }
    return c;
}
