public boolean hasPath(Graph graph, int u, int v, boolean includeAdjacent) {
  List<Integer>[] adjList = graph.getAdjList();

  // Mark all the vertices as not visited
  boolean[] visited = new boolean[adjList.length];
  Arrays.fill(visited, false);

  // Create a queue for BFS
  LinkedList<Integer> queue = new LinkedList<Integer>();

  // Mark the current node as visited and enqueue it
  visited[u] = true;
  queue.add(u);

  while (queue.size() != 0) {
    // Dequeue a vertex from queue and print it
    u = queue.poll();

    // Get all adjacent vertices of the dequeued vertex u
    // If a adjacent has not been visited, then mark it
    // visited and enqueue it
    for (int i : adjList[u]) {
      // Check if this is the destination node v
      if (i == v) {
        return true;
      }

      // If includeAdjacent is false, check for another path of distance > 1
      if (!includeAdjacent && i != v) {
        for (int j : adjList[i]) {
          if (j != u && j != v && !visited[j]) {
            return true;
          }
        }
      }

      if (!visited[i]) {
        visited[i] = true;
        queue.add(i);
      }
    }
  }

  // If BFS is complete without visiting v, then there is no path
  return false;
}
