import org.hamcrest.BaseMatcher;
import org.hamcrest.Description;
import org.hamcrest.Matcher;

public class BooleanMethodMatcher<T> extends BaseMatcher<T> {

    private final T target;
    private final String methodName;

    private BooleanMethodMatcher(T target, String methodName) {
        this.target = target;
        this.methodName = methodName;
    }

    public boolean matches(Object o) {
        try {
            return (Boolean) target.getClass()
                    .getMethod(methodName)
                    .invoke(target);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    public void describeTo(Description description) {
        description.appendText("result of " + methodName + " of " + target);
    }

    public static <T> Matcher<T> matchesBooleanMethod(T target, String methodName) {
        return new BooleanMethodMatcher(target, methodName);
    }
}
