public Observable<List<UsageInner>> retrieveAccountUsage(String resourceGroupName, String automationAccountName) throws IllegalArgumentException {
    if (resourceGroupName == null || resourceGroupName.isEmpty()) {
        throw new IllegalArgumentException("Resource group name cannot be null or empty");
    }
    if (automationAccountName == null || automationAccountName.isEmpty()) {
        throw new IllegalArgumentException("Automation account name cannot be null or empty");
    }

    String baseURL = "https://management.azure.com/subscriptions/{subscriptionId}/resourcegroups/{resourceGroupName}/providers/Microsoft.Automation/automationAccounts/{automationAccountName}/listAccountUsages";
    String url = baseURL.replace("{subscriptionId}", subscriptionId)
                       .replace("{resourceGroupName}", resourceGroupName)
                       .replace("{automationAccountName}", automationAccountName);

    return httpClient.get(url).flatMap(response -> response.getBodyAsMono(new ParameterizedTypeReference<List<UsageInner>>() {}));
}
