public Matcher constructMatcher(String matcherName, Object matcherParameter) {

    switch(matcherName) {
        case "equals":
            return Matchers.equalTo(matcherParameter);
        case "contains":
            return Matchers.containsString((String) matcherParameter);
        case "greaterThan":
            return Matchers.greaterThan((Comparable) matcherParameter);
        case "lessThan":
            return Matchers.lessThan((Comparable) matcherParameter);
        default:
            throw new IllegalArgumentException("Invalid matcher name: " + matcherName);
    }
}
