public double getTotalReturn(int timeFrame, List<Double> ticks) {
    List<Double> returns = new ArrayList<Double>();
    int fullTimeFrames = ticks.size() / timeFrame;
    int lastIndex = fullTimeFrames * timeFrame;
    for (int i = 0; i < lastIndex - timeFrame; i++) {
        double current = ticks.get(i);
        double next = ticks.get(i + timeFrame);
        double returnVal = (next - current) / current;
        returns.add(returnVal);
    }
    double totalReturn = 1.0;
    for (double returnVal : returns) {
        totalReturn *= (1 + returnVal);
    }
    double annualizedReturn = Math.pow(totalReturn, 1.0 / fullTimeFrames) - 1;
    return annualizedReturn;
}
