public static void registerSPIsFromResource(Resource pResource, Class<?> pCategory, ClassLoader pLoader) throws IOException, ClassNotFoundException {
    BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(pResource.getInputStream(), StandardCharsets.UTF_8));
    String nextLine;

    while ((nextLine = bufferedReader.readLine()) != null) {
        String trimmed = nextLine.trim();
        if (trimmed.isEmpty() || trimmed.startsWith("#")) {
            continue;
        }
        Class<?> spiClass = Class.forName(trimmed, true, pLoader);
        if (!pCategory.isAssignableFrom(spiClass)) {
            throw new ClassCastException("Class " + trimmed + " not a " + pCategory.getName());
        }
        registerSPI((Class<? extends T>) spiClass, pLoader);
    }
}
