public DoubleMatrix[] computeSVD(DoubleMatrix A) {
    DoubleMatrix[] svd = new DoubleMatrix[3];
    SingularValueDecomposition svdObj = new SingularValueDecomposition(A);
    svd[0] = svdObj.getU();
    svd[1] = svdObj.getS();
    svd[2] = svdObj.getV().transpose();
    return svd;
}
