public String getTemplateBySource(ISource source) {
    // Get a template string based on the source implementation
    if (source instanceof XmlSource) {
        // Return an xml template
        return "<xml></xml>";
    } else if (source instanceof JsonSource) {
        // Return a json template
        return "{ \"key\" : \"value\" }";
    } else {
        // Default to a generic template
        return "<template></template>";
    }
}
