        XPathExpression<Attribute> fileExpr = xpf.compile(XPATH_DISK_FILE, Filters.attribute());
        List<Element> disks = diskExpr.evaluate(domainXml);
        Iterator<StorageVol> cloneDiskIter = volumes.iterator();
