public static int countNeedlesInHaystack(String needle, String haystack) {
    int count = 0;
    int index = 0;
    while (index != -1) {
        index = haystack.indexOf(needle, index);
        if (index != -1) {
            count++;
            index += needle.length();
        }
    }
    return count;
}
