            this.diskCacheException = ex;
            diskException = ex;
            returnCode = DISK_EXCEPTION;
        } catch (IOException ex) {
            diskException = ex;
            if (ex.getMessage().equals(DISK_CACHE_IN_GB_OVER_LIMIT_MSG)) {
                returnCode = DISK_SIZE_OVER_LIMIT_EXCEPTION;
            } else {
                this.diskCacheException = ex;
                returnCode = DISK_EXCEPTION;
            }
        } catch (Exception ex) {
            returnCode = OTHER_EXCEPTION;
            diskException = ex;
