public void importStatement() throws RecognitionException {
    match(IMPORT);
    if (LA(1) == FUNCTION || LA(1) == STATIC) {
        match(LA(1));
    }
    qualifiedIdentifier();
    if (LA(1) == DOT && LA(2) == STAR) {
        match(DOT);
        match(STAR);
    } else if (LA(1) == ACC || LA(1) == ACCUMULATE) {
        if (LA(1) == ACC) {
            match(ACC);
        } else {
            match(ACCUMULATE);
        }
        qualifiedIdentifier();
        match(ID);
    }
}
