public Object sqlToJava(Object obj) {
    // Check if obj is null and return null
    if (obj == null) {
        return null;
    }

    // Check if obj is a string and convert it to a date
    if (obj instanceof String) {
        SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd");
        try {
            return sdf.parse((String) obj);
        } catch (ParseException e) {
            throw new RuntimeException("Error parsing date", e);
        }
    }

    // Return obj unchanged if it's not a string
    return obj;
}
