public static String[] findAlternateIdentifiers(FedoraClient fedora, String vitalPid, String dsPid) throws FedoraException {
    if (!fedora.exists(vitalPid)) {
        throw new FedoraException("Object with provided VITAL PID does not exist.");
    }
    if (!fedora.getDatastreamObject(vitalPid, dsPid).exists()) {
        return new String[0];
    }
    Datastream datastream = fedora.getDatastreamObject(vitalPid, dsPid);
    List<AlternateID> alternateIDs = datastream.listAlternateIDs();
    String[] result = new String[alternateIDs.size()];
    for (int i = 0; i < alternateIDs.size(); i++) {
        result[i] = alternateIDs.get(i).getValue();
    }
    return result;
}
