import java.io.*;

public void addResourceToFilesystem(String pathToFile, InputStream resource) throws IOException {
    File file = new File(pathToFile);
    // If resource is null, create a folder
    if (resource == null) {
        file.mkdirs();
    } else {
        FileOutputStream output = null;
        try {
            // Create a new file or overwrite existing one
            output = new FileOutputStream(file);
            // Copy content from resource to file
            byte[] buffer = new byte[4096];
            int bytesRead;
            while ((bytesRead = resource.read(buffer)) != -1) {
                output.write(buffer, 0, bytesRead);
            }
        } finally {
            if (output != null) {
                output.close();
            }
            if (resource != null) {
                resource.close();
            }
        }
    }
}
