public <T> CompletableFuture<T> getResult(Map<String, RedisFuture<T>> executions) {
    CompletableFuture<Void> allFutures = CompletableFuture.allOf(executions.values().toArray(new CompletableFuture<?>[0]));
    return allFutures.thenApply(value -> {
        RedisFuture<T> lastFuture = executions.values().iterator().next();
        for (RedisFuture<T> future : executions.values()) {
            if (lastFuture.isDone()) {
                lastFuture = future;
            }
        }
        try {
            return lastFuture.get();
        } catch (InterruptedException | ExecutionException e) {
            throw new RuntimeException(e);
        }
    });
}
