public Observable<PagedList<EnvironmentSettingInner>> listEnvironmentSettings(String resourceGroupName, String labAccountName, String labName) throws IllegalArgumentException {
    if (resourceGroupName == null || resourceGroupName.isEmpty()) throw new IllegalArgumentException("Resource group name cannot be null or empty.");
    if (labAccountName == null || labAccountName.isEmpty()) throw new IllegalArgumentException("Lab account name cannot be null or empty.");
    if (labName == null || labName.isEmpty()) throw new IllegalArgumentException("Lab name cannot be null or empty.");

    final String filter = String.format("labName eq '%s'", labName);
    final List<EnvironmentSettingInner> settingsList = new ArrayList<>();
    final LabAccount labAccount = this.azure.labAccounts().getByResourceGroup(resourceGroupName, labAccountName);
    final String subscriptionId = labAccount.subscriptionId();
    final String labResourceId = labAccount.id() + "/labs/" + labName;

    return this.azure.environmentSettings().listAsync(subscriptionId, labResourceId, filter)
            .mapPage(settingsList::add)
            .last()
            .map(l -> new PagedList<>(settingsList, l.getResponse().getHeaders()));
}
