public static byte[] replaceAndScale(GridDatatype grid, Array data) {
  byte[] scaledData = new byte[(int) data.getSize()];
  ArrayByte scaledArray = new ArrayByte.D1(scaledData.length);

  IndexIterator dataIt = data.getIndexIterator();
  IndexIterator scaledIt = scaledArray.getIndexIterator();
  while (dataIt.hasNext() && scaledIt.hasNext()) {
    double value = dataIt.getDoubleNext();
    if (Double.isNaN(value)) {
      scaledIt.setByteNext((byte) 0);
    } else {
      byte scaledValue = (byte) ((value - grid.getValidMin()) *
        ((double) 254 / (grid.getValidMax() - grid.getValidMin())) + 1);
      scaledIt.setByteNext(scaledValue);
    }
  }

  return scaledData;
}
