import java.util.concurrent.atomic.AtomicInteger;

public class QueryCounter {

    private final int minAllowedStatements;
    private final int maxAllowedStatements;
    private final AtomicInteger queryCounter = new AtomicInteger(0);

    public QueryCounter(int minAllowedStatements, int maxAllowedStatements) {
        this.minAllowedStatements = minAllowedStatements;
        this.maxAllowedStatements = maxAllowedStatements;
    }

    public void executeQuery() {
        queryCounter.incrementAndGet();
    }

    public void verify() throws WrongNumberOfQueriesError {
        int numberOfQueries = queryCounter.get();
        if (numberOfQueries < minAllowedStatements || numberOfQueries > maxAllowedStatements) {
            throw new WrongNumberOfQueriesError();
        }
    }
}

public class WrongNumberOfQueriesError extends Exception {

}
