public static void selectInPlace(int[] array, int from, int to, int[] allRequired, int requiredFrom, int requiredTo) {
    for (int i = requiredFrom; i <= requiredTo; i++) {
        int index = -1;
        int min = Integer.MAX_VALUE;
        for (int j = from; j <= to; j++) {
            if (allRequired[i] == j && array[j] < min) {
                index = j;
                min = array[j];
            }
        }
        if (index != -1) {
            swap(array, from, index);
            from++;
        }
    }
}

private static void swap(int[] array, int i, int j) {
    int temp = array[i];
    array[i] = array[j];
    array[j] = temp;
}
