public static Map<String, List<String>> readHeaders(InputStream in, byte[] buffer) throws IOException {
    Map<String, List<String>> headers = new HashMap<>();
    ByteArrayOutputStream headerBytes = new ByteArrayOutputStream();
    int b;
    boolean readingName = true;
    String name = null;
    while ((b = in.read()) != -1) {
        if (readingName) {
            if (b == ':') {
                name = headerBytes.toString("UTF-8").trim();
                headerBytes.reset();
                readingName = false;
            } else {
                headerBytes.write(b);
            }
        } else {
            if (b == '\r') {
                continue;
            }
            if (b == '\n') {
                String value = headerBytes.toString("UTF-8").trim();
                headerBytes.reset();
                if (name == null || "".equals(name)) {
                    break;
                }
                List<String> values = headers.get(name);
                if (values == null) {
                    values = new ArrayList<>();
                    headers.put(name, values);
                }
                String[] parts = value.split(",");
                for (String part : parts) {
                    values.add(part.trim());
                }
                readingName = true;
                name = null;
            } else {
                headerBytes.write(b);
            }
        }
    }
    return headers;
}
