public void encodeMapToErlang(OutputStream buf, Map<String, Object> map) throws IOException {
    DataOutputStream output = new DataOutputStream(buf);
    output.writeByte(OtpExternal.mapTag);
    output.writeInt(map.size());

    for (Map.Entry<String, Object> entry : map.entrySet()) {
        output.write(encodeObjectToErlang(entry.getKey()));
        output.write(encodeObjectToErlang(entry.getValue()));
    }
}
