public Hashtable<Point, Integer> hitMissOperation(BinaryFast b, Set<Point> input, boolean[][] kernel) {
    Hashtable<Point, Integer> matches = new Hashtable<Point, Integer>();

    int w = b.getWidth();
    int h = b.getHeight();

    // Iterate through each point in the input set
    for (Point p : input) {
        int x = p.x;
        int y = p.y;

        boolean match = true;

        // Check if the kernel matches the neighborhood of the point
        for (int i = 0; i < kernel.length; i++) {
            for (int j = 0; j < kernel[i].length; j++) {
                int xp = x + i - 1;
                int yp = y + j - 1;

                if (xp >= 0 && xp < w && yp >= 0 && yp < h) {
                    if (kernel[i][j] != b.get(xp, yp)) {
                        match = false;
                        break;
                    }
                }
            }

            if (!match) {
                break;
            }
        }

        // If there is a match, add it to the output hash table
        if (match) {
            matches.put(p, 1);
        }
    }

    return matches;
}
