public void createProject(String projectName, IPath location, String natureId) throws NotAllowedException, CoreException {
    IWorkspace workspace = ResourcesPlugin.getWorkspace();
    IProject project = workspace.getRoot().getProject(projectName);

    if (project.exists()) {
        throw new NotAllowedException("Project already exists.");
    }

    project.create(null);
    project.open(null);

    IProjectDescription description = project.getDescription();
    description.setNatureIds(new String[] { natureId });
    project.setDescription(description, null);

    IFolder srcFolder = project.getFolder("src");
    srcFolder.create(true, true, null);

    IFolder binFolder = project.getFolder("bin");
    binFolder.create(true, true, null);

    IFolder libFolder = project.getFolder("lib");
    libFolder.create(true, true, null);

    IFolder resFolder = project.getFolder("res");
    resFolder.create(true, true, null);

    IClasspathEntry[] buildPath = {
            JavaCore.newSourceEntry(project.getFullPath().append("src")),
            JavaCore.newLibraryEntry(new Path("/path/to/library.jar"), null, null)
    };
    IJavaProject javaProject = JavaCore.create(project);
    javaProject.setRawClasspath(buildPath, project.getFullPath().append("bin"), null);
}
