public int getMatchingCpInstancesCount(long CPDefinitionId, Date displayDate, int status) {
    try {
        String query = "SELECT COUNT(*) FROM CpInstance WHERE CPDefinitionId = ? AND displayDate < ? AND status = ?";
        PreparedStatement statement = connection.prepareStatement(query);
        statement.setLong(1, CPDefinitionId);
        statement.setTimestamp(2, new Timestamp(displayDate.getTime()));
        statement.setInt(3, status);
        ResultSet resultSet = statement.executeQuery();
        resultSet.next();
        return resultSet.getInt(1);
    } catch (SQLException e) {
        // handle exception
    }
    return 0;
}
