public List<dependencyType> readDependencies() throws IOException {
    File file = new File("build/resolved");
    List<dependencyType> dependencies = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            dependencies.add((dependencyType) line);
        }
    } catch (IOException e) {
        throw new IOException("Error reading dependencies file", e);
    }
    return dependencies;
}
