public static Set<Class<?>> getAllInterfaces(Object instance) {
    Set<Class<?>> interfaces = new HashSet<>();
    Class<?> clazz = instance.getClass();

    while (clazz != null) {
        for (Class<?> i : clazz.getInterfaces()) {
            interfaces.add(i);
        }
        clazz = clazz.getSuperclass();
    }

    return interfaces;
}
