public Set<String> determineModifiedVariables(Block block, Scope scope, Set<String> modified) {
    for (Statement statement : block.getStatements()) {
        if (statement instanceof ExpressionStatement) {
            Expression expr = ((ExpressionStatement) statement).getExpression();
            if (expr instanceof Assignment) {
                Expression leftExpr = ((Assignment) expr).getLeftHandSide();
                if (leftExpr instanceof Name) {
                    String name = ((Name) leftExpr).getIdentifier();
                    if (scope.contains(name)) {
                        modified.add(name);
                    }
                }
            }
        } else if (statement instanceof Block) {
            determineModifiedVariables((Block) statement, scope.createInnerScope(), modified);
        }
    }
    return modified;
}
