import java.util.concurrent.CompletableFuture;
import java.util.function.BiFunction;

public class ServiceCallCreator<E, V> {

    public <H> CompletableFuture<ServiceCall<E, V>> createServiceCall(Observable<E> first, BiFunction<V, Integer, Observable<E>> next, HeaderCallback<H, V> callback) {
        CompletableFuture<ServiceCall<E, V>> future = new CompletableFuture<>();
        HeaderSubscriber<H, V> subscriber = new HeaderSubscriber<>(callback, future);
        first.first().subscribe(subscriber);
        return future;
    }

    private class HeaderSubscriber<H> extends Subscriber<V> {
        private final HeaderCallback<H, V> callback;
        private final CompletableFuture<ServiceCall<E, V>> future;
        private int pageCount = 1;

        HeaderSubscriber(HeaderCallback<H, V> callback, CompletableFuture<ServiceCall<E, V>> future) {
            this.callback = callback;
            this.future = future;
        }

        @Override
        public void onNext(V header) {
            Observable<E> next = next.apply(header, pageCount++);
            ServiceCall<E, V> serviceCall = new ServiceCallImpl<>(header, next, callback);

            future.complete(serviceCall);
        }

        @Override
        public void onError(Throwable ex) {
            future.completeExceptionally(ex);
        }
    }
}

interface ServiceCall<E, V> {
    Observable<E> getPage();

    V getHeader();
}

interface HeaderCallback<H, V> {
    H onHeader(V header);
}

class ServiceCallImpl<E, V> implements ServiceCall<E, V> {

    private final V header;
    private final Observable<E> page;
    private final HeaderCallback<?, V> callback;

    ServiceCallImpl(V header, Observable<E> page, HeaderCallback<?, V> callback) {
        this.header = header;
        this.page = page;
        this.callback = callback;
    }

    @Override
    public Observable<E> getPage() {
        return page;
    }

    @Override
    public V getHeader() {
        return header;
    }

    public <H> H getHeaderValue() {
        return (H) callback.onHeader(header);
    }
}

