public static int size(Object input) {
    if (input instanceof String) {
        return ((String) input).length();
    } else if (input instanceof Object[]) {
        return ((Object[]) input).length;
    } else if (input instanceof int[]) {
        return ((int[]) input).length;
    } else if (input instanceof byte[]) {
        return ((byte[]) input).length;
    } else if (input instanceof short[]) {
        return ((short[]) input).length;
    } else if (input instanceof long[]) {
        return ((long[]) input).length;
    } else if (input instanceof double[]) {
        return ((double[]) input).length;
    } else if (input instanceof float[]) {
        return ((float[]) input).length;
    } else if (input instanceof char[]) {
        return ((char[]) input).length;
    } else if (input instanceof boolean[]) {
        return ((boolean[]) input).length;
    } else {
        return -1;
    }
}
