public FDBigInt add(FDBigInt a, FDBigInt b) {
    FDBigInt result = new FDBigInt(Math.max(a.nWords, b.nWords));

    int carry = 0;
    int i = 0;
    for (; i < a.nWords && i < b.nWords; i++) {
        long sum = (a.words[i] & 0xFFFFFFFFL) + (b.words[i] & 0xFFFFFFFFL) + carry;
        result.words[i] = (int) sum;
        carry = (int) (sum >>> 32);
    }
    for (; i < a.nWords; i++) {
        long sum = (a.words[i] & 0xFFFFFFFFL) + carry;
        result.words[i] = (int) sum;
        carry = (int) (sum >>> 32);
    }
    for (; i < b.nWords; i++) {
        long sum = (b.words[i] & 0xFFFFFFFFL) + carry;
        result.words[i] = (int) sum;
        carry = (int) (sum >>> 32);
    }

    if (carry != 0) {
        result.ensureCapacity(result.nWords + 1);
        result.words[result.nWords++] = carry;
    }

    return result;
}
