public void marshalException(CDROutputStream out, Exception e) throws IOException {
    out.write_string(e.getClass().getName());
    out.write_string(e.getMessage());
    StackTraceElement[] stackTrace = e.getStackTrace();
    out.write_long(stackTrace.length);
    for (int i = 0; i < stackTrace.length; i++) {
        StackTraceElement element = stackTrace[i];
        out.write_string(element.getClassName());
        out.write_string(element.getMethodName());
        out.write_string(element.getFileName());
        out.write_long(element.getLineNumber());
    }
}
