public ArrayStructure getArraySequence(String memberName) {
    if (!(this.getClass().getDeclaredField(memberName).getType() == Sequence.class)) {
        throw new IllegalArgumentException("Member variable must be of type Sequence.");
    }
    try {
        Field member = this.getClass().getDeclaredField(memberName);
        member.setAccessible(true);
        Sequence sequence = (Sequence) member.get(this);
        return sequence.getArrayStructure();
    } catch (Exception e) {
        throw new RuntimeException("Failed to get ArraySequence", e);
    }
}
