public void registerMBean(ObjectInstance objectInstance, String mBeanAttributeName, 
                           String metricName, MetricRegistry metricRegistry) {
    Attribute attribute;
    try {
        attribute = mbeanServer.getAttribute(objectInstance.getObjectName(), mBeanAttributeName);
    } catch (Exception e) {
        throw new RuntimeException(e);
    }
    if (attribute instanceof Number) {
        metricRegistry.register(metricName, 
            new JmxAttributeGauge(mbeanServer, objectInstance.getObjectName(), mBeanAttributeName));
    } else if (attribute instanceof CompositeData) {
        metricRegistry.registerAll(MetricRegistry.name(metricName), 
            new JmxAttributeCompositeData(mbeanServer, objectInstance.getObjectName(), mBeanAttributeName));
    } else if (attribute instanceof TabularData) {
        metricRegistry.registerAll(MetricRegistry.name(metricName), 
            new JmxAttributeCompositeData(mbeanServer, objectInstance.getObjectName(), mBeanAttributeName));
    }
}
