public static Tuple clamp(Tuple t, Tuple min, Tuple max, Tuple result) throws IllegalArgumentException {
    if (t.getSize() != min.getSize() || min.getSize() != max.getSize() || max.getSize() != result.getSize()) {
        throw new IllegalArgumentException("Tuples should have the same size.");
    }
    for (int i = 0; i < t.getSize(); i++) {
        double val = t.getElement(i);
        double lowerBound = min.getElement(i);
        double upperBound = max.getElement(i);
        result.setElement(i, Math.max(lowerBound, Math.min(upperBound, val)));
    }
    return result;
}
