public static String[] splitNeverNull(String pArg, char pEscape, String pDelimiter) {
    if (pArg == null) {
        return new String[0];
    }
    List<String> parts = new ArrayList<>();
    StringBuilder sb = new StringBuilder();
    boolean escaped = false;
    for (int i = 0; i < pArg.length(); i++) {
        char c = pArg.charAt(i);
        if (c == pEscape) {
            escaped = !escaped;
        } else if (!escaped && c == pDelimiter.charAt(0) && pDelimiter.equals(pArg.substring(i, i + pDelimiter.length()))) {
            parts.add(sb.toString());
            sb = new StringBuilder();
            i += pDelimiter.length() - 1;
        } else {
            sb.append(c);
        }
    }
    if (sb.length() > 0) {
        parts.add(sb.toString());
    }
    return parts.toArray(new String[parts.size()]);
}
