public boolean hasDecoration(Element element, Decoration decorationType) {
    if (element instanceof Note) {
        Note note = (Note) element;
        return note.getDecorations().contains(decorationType);
    } else if (element instanceof Chord) {
        Chord chord = (Chord) element;
        for (Note note : chord.getNotes()) {
            if (note.getDecorations().contains(decorationType)) {
                return true;
            }
        }
        return false;
    } else {
        return false;
    }
}
