public void placeRing(Ring ring, Point2D ringCenter, double bondLength) {
    double[] angles = defaultAngles;
    AffineTransform transform = AffineTransform.getRotateInstance(angles[0]);
    Point2D[] vertices = ring.getVertices();
    Point2D[] transformedVertices = new Point2D[vertices.length];
    for (int i = 0; i < vertices.length; i++) {
        transformedVertices[i] = transform.transform(vertices[i], null);
        transformedVertices[i].setLocation(transformedVertices[i].getX() * bondLength + ringCenter.getX(),
                                           transformedVertices[i].getY() * bondLength + ringCenter.getY());
    }
    ring.setVertices(transformedVertices);
}
