public int flipBitsAndReportCardinalityChange(long[] bitmap, int start, int end) {
    int beforeCardinality = 0;
    int afterCardinality = 0;

    for (int i = start; i < end; i++) {
        beforeCardinality += Long.bitCount(bitmap[i]);
        bitmap[i] = ~bitmap[i];
        afterCardinality += Long.bitCount(bitmap[i]);
    }

    return afterCardinality - beforeCardinality;
}
