public static void clearSSLContextCacheIfFilesUsed(SSLContext sslContext, String trustStorePath, String keyStorePath) {
    if (sslContext != null && (trustStorePath != null || keyStorePath != null)) {
        SSLContext.setDefault(null);
        try {
            Field field = SSLContext.class.getDeclaredField("contextSpi");
            field.setAccessible(true);
            Object contextSpi = field.get(sslContext);
            if (contextSpi != null) {
                field = contextSpi.getClass().getDeclaredField("cache");
                field.setAccessible(true);
                Object cache = field.get(contextSpi);
                if (cache != null) {
                    Method m = cache.getClass().getDeclaredMethod("remove", Object.class);
                    m.setAccessible(true);
                    if (trustStorePath != null) {
                        m.invoke(cache, new File(trustStorePath).toURI().toURL());
                    }
                    if (keyStorePath != null) {
                        m.invoke(cache, new File(keyStorePath).toURI().toURL());
                    }
                }
            }
        } catch (IllegalAccessException | InvocationTargetException | NoSuchFieldException | MalformedURLException e) {
            // handle exceptions
        }
        SSLContext.setDefault(sslContext);
    }
}
