public Field findField(Class clazz, Class<?> typeWanted, String name) {
    Field field = null;
    Class<?> currentClazz = clazz;

    while (currentClazz != null && field == null) {
        try {
            field = currentClazz.getDeclaredField(name);
            if (typeWanted != null && !typeWanted.isAssignableFrom(field.getType())) {
                field = null;
            }
        } catch (NoSuchFieldException e) {
            // If the field is not found, move on to the superclass
            currentClazz = currentClazz.getSuperclass();
        }
    }

    return field;
}
