  if(o instanceof UUID) {
    return (UUID) o;
  } else if(o instanceof String) {
    try {
      return UUID.fromString((String) o);
    } catch(IllegalArgumentException e) {
      throw new PageException("Failed to cast Object to UUID");
    }
  } else {
    throw new PageException("Failed to cast Object to UUID");
  }
}
