public static ExecutableScript createExecutableScriptFromResource(String language, String resource, ScriptFactory scriptFactory) throws NotValidException {
    if (language == null || language.isEmpty() || resource == null || resource.isEmpty()) {
        throw new NotValidException();
    }
    InputStream inputStream = Thread.currentThread().getContextClassLoader().getResourceAsStream(resource);
    if (inputStream == null) {
        throw new NotValidException();
    }
    try (Reader reader = new InputStreamReader(inputStream, StandardCharsets.UTF_8)) {
        return scriptFactory.createScript(language, reader);
    } catch (IOException e) {
        throw new NotValidException(e);
    }
}
