public boolean isJarFileReadable(String path) {
    File jarFile = new File(path);
    if(!jarFile.isFile()){
        return false;
    }
    if(jarFile.canRead()){
        JarFile jar;
        try {
            jar = new JarFile(jarFile);
            jar.close();
            return true;
        } catch (IOException ignored) {
            //Unable to read JAR file
        }
    }
    return false;
}
