import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

public class SortAVA {

    public static List<String> sort(List<String> avas) {
        List<String> standardKeywords = new ArrayList<>();
        List<String> oidKeywords = new ArrayList<>();

        for (String ava : avas) {
            if (ava.contains("OID")) {
                oidKeywords.add(ava);
            } else {
                standardKeywords.add(ava);
            }
        }

        standardKeywords.sort(Comparator.naturalOrder());
        oidKeywords.sort(new Comparator<String>() {
            @Override
            public int compare(String o1, String o2) {
                String oid1 = o1.substring(o1.indexOf("OID"));
                String oid2 = o2.substring(o2.indexOf("OID"));
                return Double.compare(Double.parseDouble(oid1.split("=")[1]), Double.parseDouble(oid2.split("=")[1]));
            }
        });

        List<String> sortedAvAs = new ArrayList<>(standardKeywords);
        sortedAvAs.addAll(oidKeywords);
        return sortedAvAs;
    }

}

