import org.apache.commons.exec.CommandLine;
import org.apache.commons.exec.DefaultExecutor;
import org.apache.commons.exec.ExecuteException;
import org.apache.commons.exec.ExecuteResultHandler;
import org.apache.commons.exec.ExecuteWatchdog;
import org.apache.commons.exec.ProcessDestroyer;
import org.apache.commons.exec.PumpStreamHandler;

import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.IOException;
import java.io.UnsupportedEncodingException;
import java.nio.charset.Charset;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.concurrent.TimeUnit;

public class WhoisLookup {

    /**
     * Uses the Ruby Whois gem to perform a whois lookup
     * @param domain domain name to lookup
     * @param timeout timeout in seconds
     * @return
     */
    public static String performWhoisLookup(String domain, int timeout) {
        try {
            CommandLine cmdLine = new CommandLine("ruby");
            cmdLine.addArgument("whois");
            cmdLine.addArgument(domain);

            ByteArrayOutputStream stdout = new ByteArrayOutputStream();
            ExecuteWatchdog watchDog = new ExecuteWatchdog(TimeUnit.SECONDS.toMillis(timeout));
            DefaultExecutor executor = new DefaultExecutor();
            executor.setWatchdog(watchDog);
            executor.setStreamHandler(new PumpStreamHandler(stdout));

            executor.execute(cmdLine, new WhoisResultHandler());

            return stdout.toString(StandardCharsets.UTF_8.name());
        } catch (IOException e) {
            throw new RuntimeException("Error performing whois lookup for domain " + domain, e);
        }
    }

    static class WhoisResultHandler implements ExecuteResultHandler {

        private volatile Exception executionException;

        public void onProcessComplete(int exitValue) {
        }

        public void onProcessFailed(ExecuteException e) {
            executionException = e;
        }

        public Exception getException() {
            return executionException;
        }
    }
}
