public void removeDuplicateHead(List<String> page) {
    if (page == null || page.isEmpty()) {
        return;
    }

    String head = null;
    for (Iterator<String> iterator = page.iterator(); iterator.hasNext();) {
        String element = iterator.next();
        if (element.startsWith("H")) {
            if (head == null) {
                head = element;
            } else {
                iterator.remove();
                if (element.equals(head)) {
                    head = null;
                }
            }
        }
    }
}
