import java.util.HashSet;
import java.util.Set;

public class LogGenerator {

    private Set<String> loggedColumns = new HashSet<>();

    public void logIfNotAlready(String... columnValues) {
        StringBuilder messageBuilder = new StringBuilder("Accessed columns: ");

        for (String column : columnValues) {
            if (!loggedColumns.contains(column)) {
                loggedColumns.add(column);
                messageBuilder.append(column).append(", ");
            }
        }

        if (messageBuilder.toString().endsWith(", ")) {
            messageBuilder.setLength(messageBuilder.length() - 2);
        }

        System.out.println(messageBuilder.toString());
    }
}
