public static void runParsingAlgorithm(double[][] scores, Edge[][][] inChart) {
    int n = scores.length;
    for (int k = 1; k < n; k++) {
        for (int s = 0; s < n - k; s++) {
            int t = s + k;
            for (int r = s; r < t; r++) {
                double rs = inChart[s][r][0].getInsideScore() + inChart[r + 1][t][1].getInsideScore() + scores[s][t];
                if (rs > inChart[s][t][1].getInsideScore()) {
                    inChart[s][t][1].setInsideEdge(r, inChart[s][r][0], inChart[r + 1][t][1]);
                    inChart[s][t][1].setInsideScore(rs);
                }
                double rt = inChart[r][t][1].getInsideScore() + inChart[s][r][0].getInsideScore() + scores[t][s];
                if (rt > inChart[s][t][0].getInsideScore()) {
                    inChart[s][t][0].setInsideEdge(r, inChart[s][r][0], inChart[r + 1][t][1]);
                    inChart[s][t][0].setInsideScore(rt);
                }
            }
        }
    }
}
