public Polygon createPolygon(List<Point> shell, List<List<Point>> holes) {
    GeometryFactory geometryFactory = new GeometryFactory();
    LinearRing linearRing = geometryFactory.createLinearRing(shell.toArray(new Coordinate[0]));
    LinearRing[] holesArray = new LinearRing[holes.size()];
    for (int i = 0; i < holes.size(); i++) {
        List<Point> hole = holes.get(i);
        holesArray[i] = geometryFactory.createLinearRing(hole.toArray(new Coordinate[0]));
    }
    Polygon polygon = geometryFactory.createPolygon(linearRing, holesArray);
    return polygon;
}
