public FieldDescription[] getOptimisticLockingFieldsSortedAscending(FieldDescription[] fieldDescriptions) {
    // Filter fields that support optimistic locking
    FieldDescription[] optimisticLockingFields = Arrays.stream(fieldDescriptions)
        .filter(FieldDescription::supportsOptimisticLocking)
        .toArray(FieldDescription[]::new);

    // Sort fields based on getOrder property
    Arrays.sort(optimisticLockingFields, Comparator.comparingInt(FieldDescription::getOrder));

    return optimisticLockingFields;
}
