public List<Interceptor> getAllInterceptors() {
    if (firstInterceptor == null) {
        return Collections.emptyList();
    }
    List<Interceptor> interceptors = new ArrayList<>();
    Interceptor currentInterceptor = firstInterceptor;
    while (currentInterceptor != null) {
        interceptors.add(currentInterceptor);
        currentInterceptor = currentInterceptor.getNextInterceptor();
    }
    return Collections.unmodifiableList(interceptors);
}
