public int invalidateOldItems(List<String> configurationItemNameList, List<Cmdb> cmdbList) {
    int countInvalidated = 0;
    for (Cmdb cmdb : cmdbList) {
        if (!configurationItemNameList.contains(cmdb.getConfigurationItemName())) {
            if (cmdb.isValid()) {
                cmdb.setValid(false);
                countInvalidated++;
            }
        }
    }
    return countInvalidated;
}
