		el = (Element) n;
		prefix = el.getPrefix();
		if (prefix != null && prefix.length() > 0) {
			el.setPrefix(null);
		} else {
			prefix = "";
		}
		dropNamespaceDecls(el);
		removePrefixFromChildren(el, prefix);
