public static void merge(byte[] byteArray, int start, int middle, int end) {
    byte[] mergedArray = new byte[end - start + 1];
    int leftIndex = start;
    int rightIndex = middle + 1;
    int mergedIndex = 0;

    while (leftIndex <= middle && rightIndex <= end) {
        if (byteArray[leftIndex] < byteArray[rightIndex]) {
            mergedArray[mergedIndex] = byteArray[leftIndex];
            mergedIndex++;
            leftIndex++;
        } else {
            mergedArray[mergedIndex] = byteArray[rightIndex];
            mergedIndex++;
            rightIndex++;
        }
    }

    while (leftIndex <= middle) {
        mergedArray[mergedIndex] = byteArray[leftIndex];
        mergedIndex++;
        leftIndex++;
    }

    while (rightIndex <= end) {
        mergedArray[mergedIndex] = byteArray[rightIndex];
        mergedIndex++;
        rightIndex++;
    }

    for (int i = 0; i < mergedArray.length; i++) {
        byteArray[start + i] = mergedArray[i];
    }
}
