public void swapTreeModelAndJTree(BugTreeModel newModel, JTree newTree) {
    // Get the current model and tree
    BugTreeModel currentModel = (BugTreeModel) tree.getModel();
    JTree currentTree = (JTree) tree.getParent().getComponent(0);

    // Set the new model and tree
    tree.setModel(newModel);
    currentModel.dispose();
    currentTree.removeAll();
    currentTree.add(newTree);
}
