public boolean isNextTokenOfType(String[] typeOptions) throws IllegalStateException {
    if (!isStarted) {
        throw new IllegalStateException("The stream should be started before calling this method.");
    }
    StreamToken nextToken = getNextToken();
    for (String type : typeOptions) {
        if (nextToken.getType().equals(type)) {
            return true;
        }
    }
    return false;
}
