public Predicate buildFullTextMatchingPredicate(FullTextConfiguration configuration, boolean plain, String query, String value){
    FullTextEntityManager fullTextEntityManager = org.hibernate.search.jpa.Search.getFullTextEntityManager(entityManager);
    QueryBuilder queryBuilder = fullTextEntityManager.getSearchFactory().buildQueryBuilder().forEntity(configuration.getEntityClass()).get();

    String[] fields = configuration.getFields().toArray(new String[0]);
    Query query = queryBuilder.keyword().onFields(fields).matching(value).createQuery();
    if(plain){
        query = queryBuilder.keyword().onFields(fields).matching(value).matchingMode(MatchingMode.EXACT).createQuery();
    }

    FullTextQuery fullTextQuery = fullTextEntityManager.createFullTextQuery(query, configuration.getEntityClass());
    return fullTextQuery;
}
