public static void analyzeJavaAppStructure(String fileName) {
  try {
    // Create a FileWriter object to write to file
    FileWriter fileWriter = new FileWriter(fileName);

    // Get the current working directory and print it to file
    String workingDir = System.getProperty("user.dir");
    fileWriter.write("Current working directory: " + workingDir + "\n");

    // Get the list of files and directories in the working directory
    File directory = new File(workingDir);
    File[] fileList = directory.listFiles();

    // Print each file and directory to file
    for (int i = 0; i < fileList.length; i++) {
      fileWriter.write(fileList[i].getName() + "\n");
    }

    // Close the FileWriter object
    fileWriter.close();

  } catch (IOException e) {
    System.out.println("Error: " + e.getMessage());
  }
}
