public ComparisonFailure createComparisonFailure(String message) {
    try {
        Class<?> clazz = Class.forName("org.junit.ComparisonFailure");
        Constructor<?> constructor = clazz.getConstructor(String.class, String.class, String.class);
        return (ComparisonFailure) constructor.newInstance(message, null, null);
    } catch (ClassNotFoundException | NoSuchMethodException | InstantiationException | IllegalAccessException | InvocationTargetException e) {
        return null;
