public double getDoubleProperty(Class<?> aClass, String key, double defaultValue) {
   Properties properties = new Properties();
   double value = defaultValue;
   try {
      InputStream inputStream = aClass.getClassLoader().getResourceAsStream(aClass.getSimpleName() + ".properties");
      if (inputStream != null) {
         properties.load(inputStream);
         String propertyValue = properties.getProperty(key);
         if (propertyValue != null) {
            value = Double.parseDouble(propertyValue);
         }
      }
   } catch (IOException | NumberFormatException ex) {
      ex.printStackTrace();
   }
   return value;
}
