public static double[][] getUpperTriangularMatrix(double[][] R, boolean compact) {
    if (compact) {
        int m = R.length;
        int n = R[0].length;
        int newLength = Math.min(m, n);
        double[][] result = new double[newLength][newLength];
        for (int i = 0; i < newLength; i++) {
            for (int j = i; j < newLength; j++) {
                result[i][j] = R[i][j];
            }
        }
        return result;
    } else {
        int n = R[0].length;
        double[][] result = new double[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                result[i][j] = R[i][j];
            }
        }
        return result;
    }
}
