public static String parsePrefix(String zoneId, int prefixLength) throws DateTimeException {
    if (zoneId == null) {
        throw new DateTimeException("Zone ID must not be null");
    }

    if (prefixLength != 2 && prefixLength != 3) {
        throw new DateTimeException("Prefix length must be either 2 or 3");
    }

    String prefix = zoneId.substring(0, prefixLength);
    String suffix = zoneId.substring(prefixLength);

    if (!prefix.matches("[A-Za-z]{2,3}")) {
        throw new DateTimeException("Invalid prefix format");
    }

    if (!suffix.matches("[A-Za-z0-9~/+-]{1,}")) {
        throw new DateTimeException("Invalid suffix format");
    }

    return zoneId;
}
