public String getTargetHost(HttpServletRequest request) {
    String targetHost;
    String hostHeader = request.getHeader("Host");
    if(hostHeader != null) {
        targetHost = hostHeader;
    } else {
        int port = request.getServerPort();
        if(port == 80) {
            targetHost = request.getServerName();
        } else {
            targetHost = request.getServerName() + ":" + port;
        }
    }
    return targetHost;
}
