import java.io.*;
import java.util.*;

public class SafariFavoritesModifier {

    public static void main(String[] args) throws IOException {
        File favoritesFile = new File("safariCopies/safari.app/Contents/Resources/BuiltinFavorites.plist");

        FileInputStream fis = new FileInputStream(favoritesFile);
        byte[] buffer = new byte[(int) favoritesFile.length()];
        fis.read(buffer);
        fis.close();

        String favoritesXML = new String(buffer, "UTF-8");
        favoritesXML = favoritesXML.replaceAll("(?s)<string>[^<]*</string>", "<string>about:blank</string>");

        FileOutputStream fos = new FileOutputStream(favoritesFile);
        fos.write(favoritesXML.getBytes("UTF-8"));
        fos.close();
    }
}
