    WatchKey key;
    while ((key = watchService.take()) != null) {
        for (WatchEvent<?> event : key.pollEvents()) {
            WatchEvent.Kind<?> kind = event.kind();
            if (kind == StandardWatchEventKinds.OVERFLOW) {
                continue;
            }

            WatchEvent<Path> ev = (WatchEvent<Path>) event;
            Path fileName = ev.context();
            Path child = directory.resolve(fileName);
            scanFile(child, kind.name(), scanContext);
        }

        boolean valid = key.reset();
        if (!valid) {
            break;
        }
    }
}

private void scanFile(Path file, String action, ScanContext scanContext) throws IOException {
    String path = file.toString();
    String checksum = getFileChecksum(file);

    scanContext.handleScanResult(path, action, checksum);
}

private String getFileChecksum(Path file) throws IOException {
    try (InputStream in = Files.newInputStream(file)) {
        return DigestUtils.md5Hex(in);
    }
}
