import java.io.*;
import java.util.*;

public List<String> readLines(String classpathOrFilePath) throws IOException {
    BufferedReader reader;
    InputStream inputStream = getClass().getResourceAsStream(classpathOrFilePath);
    if(inputStream != null) { // check if classpath resource exists
        reader = new BufferedReader(new InputStreamReader(inputStream));
    } else { // otherwise, treat path as file path
        File file = new File(classpathOrFilePath);
        reader = new BufferedReader(new FileReader(file));
    }
    List<String> lines = new ArrayList<>();
    String line = reader.readLine();
    while(line != null) {
        lines.add(line);
        line = reader.readLine();
    }
    reader.close();
    return lines;
}
