public void removeColumnsFromDataset(Set<String> columnSet) {
    // check if the column set is not empty
    if (!columnSet.isEmpty()) {
        // get the current metadata of the dataframe
        DataFrameMetaData metaData = getDataframeMetadata();

        // remove columns from the metadata
        for (String column : columnSet) {
            metaData.removeColumn(column);
        }

        // create a new dataframe without the removed columns
        DataFrame newDataframe = new DataFrame();

        // iterate through the rows of the current dataframe
        ExecutorService executorService = Executors.newFixedThreadPool(10);
        for (int i = 0; i < getDataframeRowCount(); i++) {
            final int rowIndex = i;
            executorService.execute(new Runnable() {
                @Override
                public void run() {
                    // create a new row for the new dataframe without the removed columns
                    DataRow newRow = new DataRow();

                    // iterate through the metadata of the current dataframe
                    for (String column : metaData.getColumnNames()) {
                        // if the column is not removed, add it to the new row
                        if (!columnSet.contains(column)) {
                            newRow.addData(metaData.getColumnType(column), getDataframeData(rowIndex, column));
                        }
                    }

                    // add the new row to the new dataframe
                    newDataframe.addRow(newRow);
                }
            });
        }
        executorService.shutdown();
        try {
            executorService.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }

        // set the metadata and data of the new dataframe to the current dataframe
        setMetadata(metaData);
        setData(newDataframe.getData());
    }
}
