import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;

public class LigandSorter {

    public static void sort(ArrayList<Ligand> ligands) {

        // Define a custom comparator to compare ligands based on atomic and mass numbers
        Comparator<Ligand> ligandComparator = new Comparator<Ligand>() {
            @Override
            public int compare(Ligand l1, Ligand l2) {
                if (l1.getAtomicNumber() > l2.getAtomicNumber()) {
                    return -1;
                } else if (l1.getAtomicNumber() < l2.getAtomicNumber()) {
                    return 1;
                } else {
                    if (l1.getMassNumber() > l2.getMassNumber()) {
                        return -1;
                    } else if (l1.getMassNumber() < l2.getMassNumber()) {
                        return 1;
                    } else {
                        return 0;
                    }
                }
            }
        };

        // Sort the ligands using the custom comparator
        Collections.sort(ligands, ligandComparator);
    }
}
