import javax.swing.tree.DefaultMutableTreeNode;
import javax.swing.tree.TreeModel;
import java.util.ArrayList;
import java.util.List;

public List<DefaultMutableTreeNode> getLeafNodes(TreeModel treeModel, DefaultMutableTreeNode node) {
    List<DefaultMutableTreeNode> leafNodes = new ArrayList<>();

    if (!node.getAllowsChildren()) {
        leafNodes.add(node);
        return leafNodes;
    }

    for (int i = 0; i < treeModel.getChildCount(node); i++) {
        DefaultMutableTreeNode child = (DefaultMutableTreeNode) treeModel.getChild(node, i);
        leafNodes.addAll(getLeafNodes(treeModel, child));
    }

    return leafNodes;
}
