public void sendErrorMessage(int code) {
  // construct error message body based on code input
  String message = "";

  // determine the status code and message
  switch (code) {
    case 400:
      message = "Bad Request";
      break;
    case 401:
      message = "Unauthorized";
      break;
    case 403:
      message = "Forbidden";
      break;
    case 404:
      message = "Not Found";
      break;
    case 500:
      message = "Internal Server Error";
      break;
    default:
      message = "Unknown error occurred";
      break;
  }

  // send response to client with the defined status code and message
  Response.status(code).entity(message).build();
}
