public int getNextTransactionalId(int index, int nextFreeTransactionalId, int parallelism, int kafkaProducersPoolSize) {
    int totalIds = parallelism * kafkaProducersPoolSize;
    int chunkSize = (int) Math.ceil((double) totalIds / parallelism);
    int chunkIndex = index % parallelism;
    int start = nextFreeTransactionalId + (chunkIndex * chunkSize);
    int end = Math.min(start + chunkSize, nextFreeTransactionalId + totalIds);
    int rangeSize = end - start;
    long taskId = Thread.currentThread().getId();
    int transactionalIdIndex = (int) (taskId % rangeSize);
    return start + transactionalIdIndex;
}
