public void setMaxActiveTransactions(int maximumActiveTransactions, Transaction transaction) throws ObjectManagerException {
    if (maximumActiveTransactions < 0) {
        throw new ObjectManagerException("Invalid maximum active transactions");
    }
    synchronized (transaction) {
        if (maximumActiveTransactions < transaction.getActiveTransactions()) {
            throw new ObjectManagerException("The new maximum is less than the current active transactions");
        }

        // update the maximum active transactions
        transaction.setMaxActiveTransactions(maximumActiveTransactions);

        // check if any new transactions should be allowed to start
        transaction.notifyAll();
    }
}
