public static <T> T[] splice(T[] insertedItems, T[] origItems, int idx, Class<T[]> tClass) {
    int newLength = origItems.length + insertedItems.length;
    T[] result = Arrays.copyOf(origItems, newLength);
    System.arraycopy(result, idx, result, idx + insertedItems.length, origItems.length - idx);
    System.arraycopy(insertedItems, 0, result, idx, insertedItems.length);
    return result;
}
