public static void writeBugAnnotationAsXML(XMLOutput xmlOutput, String elementName, BugAnnotation annotation, Map<String, String> attributeList, boolean addMessages) throws IOException {
    xmlOutput.writeStartElement(elementName);
    for(Map.Entry<String,String> entry : attributeList.entrySet()){
        xmlOutput.writeAttribute(entry.getKey(), entry.getValue());
    }
    String shortMsg = addMessages ? annotation.getShortMsg() : null;
    String longMsg = addMessages ? annotation.getLongMsg() : null;
    xmlOutput.writeStartElement("Message");
    if (shortMsg != null) {
        xmlOutput.writeAttribute("ShortDescription", shortMsg);
    }
    if (longMsg != null) {
        xmlOutput.writeAttribute("LongDescription", longMsg);
    }
    xmlOutput.writeEndElement();
    String[] bugLines = annotation.getBugLines();
    if (bugLines != null) {
        for (String bugLine : bugLines) {
            xmlOutput.writeStartElement("BugLine");
            xmlOutput.writeAttribute("line", bugLine);
            xmlOutput.writeEndElement();
        }
    }
    String[] patchLines = annotation.getPatchLines();
    if (patchLines != null) {
        for (String patchLine : patchLines) {
            xmlOutput.writeStartElement("PatchLine");
            xmlOutput.writeAttribute("line", patchLine);
            xmlOutput.writeEndElement();
        }
    }
    xmlOutput.writeEndElement();
}
