public int getRowCount(String dynamicQuery, String[] projection) {
    // assuming some database connection and query execution code here

    // execute the query with the projection
    ResultSet resultSet = executeQuery(dynamicQuery, projection);

    // navigate to the last row of the result set to get the row count
    try {
        resultSet.last();
        int rowCount = resultSet.getRow();
        return rowCount;
    } catch (SQLException e) {
        e.printStackTrace();
        return 0;
    }
}
