public void cancelAllTimeWatchers() {
    StackTraceElement[] stackTrace = Thread.currentThread().getStackTrace();
    StackTraceElement currentStackTraceElement = stackTrace[1];
    long threadId = Thread.currentThread().getId();

    synchronized (timeWatchers) {
        for (String key : timeWatchers.keySet()) {
            TimeWatcher timeWatcher = timeWatchers.get(key);
            if (timeWatcher.getLevel() == currentStackTraceElement.getClassName() + "." + currentStackTraceElement.getMethodName() && timeWatcher.getThreadId() == threadId) {
                timeWatcher.cancel();
            }
        }
    }

    synchronized (timePoints) {
        for (String key : timePoints.keySet()) {
            TimePoint timePoint = timePoints.get(key);
            if (timePoint.getLevel() == currentStackTraceElement.getClassName() + "." + currentStackTraceElement.getMethodName() && timePoint.getThreadId() == threadId) {
                timePoint.cancel();
            }
        }
    }
}
