public void checkClassDescriptor(ClassDescriptor classDef, int checkLevel) throws ConstraintException {
    if (classDef.getProcedureSettings() == null) {
        throw new ConstraintException("Procedure settings not found in class descriptor.");
    } else if (checkLevel <= CheckLevel.STRICT && !classDef.getProcedureSettings().isStrict()) {
        throw new ConstraintException("Procedure settings must be set to strict mode in strict check level.");
    } else if (checkLevel <= CheckLevel.BASIC && classDef.getProcedureSettings().isDefensiveCopy()) {
        throw new ConstraintException("Defensive copy must not be set in basic check level.");
    }
}
