public double computeUnscaledNorm(Data mbr, int start, int end) {
    double sum = 0.0;
    for(int i=start; i<end; i++) {
        sum += Math.pow(mbr.getCoordinate(i),2);
    }
    return Math.sqrt(sum);
}
