    public static void parseAndValidateHtml(URL url) throws IOException {
        // Connect to the URL and retrieve the HTML content as an input stream
        try (InputStream in = url.openConnection().getInputStream()) {
            // Parse the HTML content using Jsoup
            Document doc = Jsoup.parse(in, StandardCharsets.UTF_8.name(), url.toString());

