        DateTieredCompactionStrategy strategy = (DateTieredCompactionStrategy) DatabaseDescriptor.getCompactionStrategyClassInstance(SSTableReader.formatType);
        long maxTimestamp = 0;
        for (SSTableReader sstable : strategy.getSSTables()) {
            maxTimestamp = Math.max(maxTimestamp, sstable.getMaxTimestamp());
        }
        if (maxTimestamp == 0) {
            throw new NoSuchElementException("There are no SSTables");
        }
        return maxTimestamp;
    }
}
