import java.awt.Color;
import java.util.ArrayList;
import java.util.List;

public class ColorPaletteGenerator {
    public static List<Color> generateRedBluePalette(int n, float alpha) {
        List<Color> palette = new ArrayList<>();
        int red = 255;
        int blue = 0;
        int stepSize = 255 / (n - 1);

        for (int i = 0; i < n; i++) {
            Color color = new Color(red, 0, blue, Math.round(alpha * 255));
            palette.add(color);
            red -= stepSize;
            blue += stepSize;
        }

        return palette;
    }
}
