public void reportInterruptCause(String buildRecord) {
    // Check if buildRecord is available
    if (buildRecord != null && !buildRecord.isEmpty()) {
        // Record the cause of interruption to the build
        buildRecord += " - Cause of interruption: " + Thread.currentThread().getName();

        // Print the cause of interruption
        System.out.println("Cause of interruption: " + Thread.currentThread().getName());
    }
}
