@Override
public EnquireLinkResp enquireLinkResp(byte[] pdu) throws PDUException {
    if (pdu.length != 16) {
        throw new PDUException("PDU length is invalid");
    }
    ByteBuffer bb = ByteBuffer.wrap(pdu);
    bb.order(ByteOrder.BIG_ENDIAN);
    int commandId = bb.getInt();
    int commandStatus = bb.getInt();
    int sequenceNumber = bb.getInt();
    EnquireLinkResp enquireLinkResp = new EnquireLinkResp(commandStatus);
    enquireLinkResp.setSequenceNumber(sequenceNumber);
    return enquireLinkResp;
}
