public static void setExponentialBackoffInterval(Duration interval, Duration maxInterval) {
    Objects.requireNonNull(interval, "Interval cannot be null");
    Objects.requireNonNull(maxInterval, "Max interval cannot be null");
    if (interval.isNegative() || interval.isZero()) {
        throw new IllegalArgumentException("Interval must be greater than 0");
    }
    if (interval.compareTo(maxInterval) >= 0) {
        throw new IllegalArgumentException("Interval must be less than max interval");
    }
    Duration currentInterval = interval;
    while (true) {
        try {
            Thread.sleep(currentInterval.toMillis());
            currentInterval = Duration.ofMillis(currentInterval.toMillis() * 2);
            if (currentInterval.compareTo(maxInterval) >= 0) {
                return;
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            return;
        }
    }
}
