public static double determinant(double[][] matrix) throws MatrixException {
    int n = matrix.length;

    // If the matrix is not square
    if (n != matrix[0].length)
        throw new MatrixException("The matrix must be square");

    double det = 0;

    // Base case
    if (n == 1) {
        det = matrix[0][0];
    } else if (n == 2) {
        det = matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0];
    } else {
        for (int i = 0; i < n; i++) {
            // Get the submatrix
            double[][] submatrix = new double[n - 1][n - 1];
            for (int j = 1; j < n; j++) {
                for (int k = 0; k < n; k++) {
                    if (k < i) {
                        submatrix[j - 1][k] = matrix[j][k];
                    } else if (k > i) {
                        submatrix[j - 1][k - 1] = matrix[j][k];
                    }
                }
            }

            // Recursive call to compute the determinant of the submatrix
            det += matrix[0][i] * Math.pow(-1, i) * determinant(submatrix);
        }
    }

    return det;
}
