import com.google.api.core.ApiFuture;
import com.google.common.util.concurrent.MoreExecutors;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.Executor;

public static <V> ApiFuture<V> fromCompletableFuture(
    CompletableFuture<V> completableFuture, Executor executor) {
  CompletableFuture<V> decorated = new CompletableFuture<V>();
  completableFuture.whenCompleteAsync(
      (V result, Throwable throwable) -> {
        if (throwable != null) {
          decorated.completeExceptionally(throwable);
        } else {
          decorated.complete(result);
        }
      },
      executor);
  return ApiFutures.catching(
      decorated,
      Throwable.class,
      t -> {
        throw new RuntimeException(t);
      },
      MoreExecutors.directExecutor());
}
