public class SessionLogs {

  public static Map<String, String> createSessionLogsMap(String rawSessionMap) throws Exception {
    ObjectMapper mapper = new ObjectMapper();
    JsonNode node = mapper.readTree(rawSessionMap);
    Map<String, String> sessionLogsMap = new HashMap<>();
    for (JsonNode logNode : node) {
      String sessionId = logNode.get("session_id").asText();
      String logText = logNode.get("log_text").asText();
      sessionLogsMap.put(sessionId, logText);
    }
    return sessionLogsMap;
  }
}
