public FetchRequest readFetchRequest(ByteBuffer buffer) throws IllegalArgumentException {
    // Check if buffer is null or empty
    if (buffer == null || !buffer.hasRemaining()) {
        throw new IllegalArgumentException("Buffer is null or empty.");
    }

    // Read topic length and topic bytes
    if (buffer.remaining() < 2) {
        throw new IllegalArgumentException("Buffer data format error - no topic length.");
    }
    short topicLength = buffer.getShort();
    if (buffer.remaining() < topicLength) {
        throw new IllegalArgumentException("Buffer data format error - no topic.");
    }
    byte[] topicBytes = new byte[topicLength];
    buffer.get(topicBytes);

    // Read partition
    if (buffer.remaining() < 4) {
        throw new IllegalArgumentException("Buffer data format error - no partition.");
    }
    int partition = buffer.getInt();

    // Read offset
    if (buffer.remaining() < 8) {
        throw new IllegalArgumentException("Buffer data format error - no offset.");
    }
    long offset = buffer.getLong();

    // Read max bytes
    if (buffer.remaining() < 4) {
        throw new IllegalArgumentException("Buffer data format error - no max bytes.");
    }
    int maxBytes = buffer.getInt();

    // Create and return fetch request
    String topic = new String(topicBytes, StandardCharsets.UTF_8);
    return new FetchRequest(topic, partition, offset, maxBytes);
}
