public void pyramidStructure(double[] scaleFactors) {
    int pyramidHeight = scaleFactors.length;

    for (int row = 1; row <= pyramidHeight; row++) {
        for (int col = 1; col <= pyramidHeight - row; col++) {
            System.out.print(" ");
        }
        for (int col = 1; col < 2 * row; col++) {
            int scaleFactorIndex = col <= row ? col - 1 : 2 * row - col - 1;
            int scaleFactor = (int)(scaleFactors[scaleFactorIndex]);
            System.out.print(scaleFactor);
        }
        System.out.println();
    }
}
