public Path getClosestDirectory(FileSystem fs, Path path) throws IOException {

  if (!fs.provider().getScheme().equalsIgnoreCase(path.toUri().getScheme())) {
      throw new IllegalArgumentException("Path " + path + "does not belong to file system " + fs);
  }

  // If the path is a directory, return it
  if (Files.isDirectory(path)) {
      return path;
  }

  // Go up the path to find the closest directory
  Path current = path;
  while (current.getParent() != null) {
      current = current.getParent();
      if (Files.isDirectory(current)) {
          return current;
      }
  }

  throw new FileNotFoundException("No directory found in the path " + path);
}
