import java.security.KeyPair;
import java.security.KeyPairGenerator;
import java.security.NoSuchAlgorithmException;
import java.security.PrivateKey;
import java.security.PublicKey;
import java.security.cert.CertificateEncodingException;
import java.security.cert.CertificateException;
import java.security.cert.X509Certificate;
import java.util.Date;

import javax.security.auth.x500.X500Principal;

public static X509Certificate createSelfSignedCertificate(X509Certificate cert) throws NoSuchAlgorithmException, CertificateEncodingException, CertificateException {
    PublicKey publicKey = cert.getPublicKey();
    PrivateKey privateKey = generatePrivateKey(publicKey.getAlgorithm());

    X500Principal issuer = cert.getIssuerX500Principal();
    X500Principal subject = cert.getSubjectX500Principal();
    Date startDate = cert.getNotBefore();
    Date endDate = cert.getNotAfter();
    byte[] encodedCert = cert.getEncoded();

    X509Certificate newCert = CertUtils.generateCertificate(issuer, subject, publicKey, privateKey, startDate, endDate, null, null);
    newCert.verify(publicKey);

    return newCert;
}

private static PrivateKey generatePrivateKey(String algorithm) throws NoSuchAlgorithmException {
    KeyPairGenerator generator = KeyPairGenerator.getInstance(algorithm);
    KeyPair keyPair = generator.genKeyPair();

    return keyPair.getPrivate();
}
