public boolean isValidFileNameForContentType(String fileName, String baseContentType) {
    boolean isValid = false;

    String extension = FilenameUtils.getExtension(fileName); // using FilenameUtils class from Apache Commons IO library

    // check if extension is valid for given content type
    if (baseContentType.equalsIgnoreCase("image/jpeg") && extension.equalsIgnoreCase("jpg")) {
        isValid = true;
    } else if (baseContentType.equalsIgnoreCase("image/png") && extension.equalsIgnoreCase("png")) {
        isValid = true;
    } else if (baseContentType.equalsIgnoreCase("application/pdf") && extension.equalsIgnoreCase("pdf")) {
        isValid = true;
    }

    return isValid;
}
