public String readLongString(Object longString) throws SQLException, IOException {
    String result = null;

    if (longString instanceof Clob) { // Handle CLOB type
        Clob clob = (Clob) longString;
        Reader reader = clob.getCharacterStream();
        StringWriter writer = new StringWriter();
        char[] buffer = new char[1024];
        int bytesRead = -1;

        while ((bytesRead = reader.read(buffer)) != -1) {
            writer.write(buffer, 0, bytesRead);
        }

        result = writer.toString();
    } else if (longString instanceof String) { // Handle TEXT type
        result = (String) longString;
    }

    return result;
}
