public List<TweakInfo> removeCallNodes(List<TweakInfo> tweaks) {
    List<TweakInfo> result = new ArrayList<>();
    for (TweakInfo tweak : tweaks) {
        TweakInfo newTweak = new TweakInfo(tweak.getName(), tweak.getDefaultValue(), tweak.getDescription());
        List<FieldInfo> fields = new ArrayList<>();
        for (FieldInfo field : tweak.getFields()) {
            if (field.getType().equals(FieldType.CALL)) {
                Object defaultValue;
                if (field.getDefaultValue() instanceof Number) {
                    defaultValue = 0;
                } else if (field.getDefaultValue() instanceof Boolean) {
                    defaultValue = false;
                } else {
                    defaultValue = "";
                }
                fields.add(new FieldInfo(field.getName(), defaultValue, field.getDescription(), FieldType.VALUE));
            } else {
                fields.add(field);
            }
        }
        newTweak.setFields(fields);
        result.add(newTweak);
    }
    return result;
}
