import java.io.File;
import java.io.FileNotFoundException;
import java.util.ArrayList;
import java.util.Scanner;

public class DatePrinter {

    public static void printDatesInFile(int row, int col) {

        // create a file object
        File file = new File("filename.txt");

        // create a scanner object to read the file
        Scanner scanner;
        try {
            scanner = new Scanner(file);
        } catch (FileNotFoundException e) {
            e.printStackTrace();
            return;
        }

        // create an array list to store the dates
        ArrayList<String> dates = new ArrayList<String>();

        // read the file and extract the dates
        int currentRow = 1;
        while(scanner.hasNextLine()) {

            // read the line
            String line = scanner.nextLine();

            // split the line into columns
            String[] columns = line.split(",");

            // check if the row and column match the given values
            if(currentRow == row && columns.length > col) {

               // get the date from the specified column
               String date = columns[col];

               // add the date to the array list
               dates.add(date);
            }

            // increment the row counter
            currentRow++;
        }

        // print the dates
        System.out.println("Dates in column " + col + " of row " + row + ":");
        for(String date : dates) {
            System.out.println(date);
        }
    }
}
