import javax.naming.*;
import javax.naming.directory.DirContext;

public class DirContextPool {
    private static DirContext[] contextPool;
    private static boolean[] contextInUse;

    public DirContextPool(int poolSize, String providerURL) throws NamingException {
        contextPool = new DirContext[poolSize];
        contextInUse = new boolean[poolSize];

        for (int i = 0; i < poolSize; i++) {
            contextPool[i] = new InitialDirContext();
            contextPool[i].addToEnvironment(Context.PROVIDER_URL, providerURL);
            contextInUse[i] = false;
        }
    }

    public synchronized DirContext getContext() throws NamingException {
        while (true) {
            for (int i = 0; i < contextPool.length; ++i) {
                if (!contextInUse[i]) {
                    contextInUse[i] = true;
                    return contextPool[i];
                }
            }

            // Wait for a context to be freed up
            try {
                wait();
            } catch (InterruptedException e) {
                //interrupt and check if any available context
                for (int i = 0; i < contextPool.length; ++i) {
                    if (!contextInUse[i])
                        return contextPool[i];
                }

                // No free context available so throw an exception
                throw new NamingException("Couldn't get a free context");
            }
        }
    }

    public synchronized void freeContext(DirContext context) {
        for (int i = 0; i < contextPool.length; ++i) {
            if (context == contextPool[i]) {
                contextInUse[i] = false;
                notify();
                break;
            }
        }
    }
}
