public <T extends Assignable<? extends Archive>> Constructor<T> findArchiveConstructor(Class<T> extensionImplClass) {
    Constructor<?>[] constructors = extensionImplClass.getConstructors();
    for (Constructor<?> constructor : constructors) {
        Type[] parameterTypes = constructor.getGenericParameterTypes();
        if (parameterTypes.length != 1) {
            continue;
        }
        Type type = parameterTypes[0];
        if (type instanceof ParameterizedType) {
            ParameterizedType pType = (ParameterizedType) type;
            Type rawType = pType.getRawType();
            if (rawType instanceof Class && Archive.class.isAssignableFrom((Class<?>) rawType)) {
                return (Constructor<T>) constructor;
            }
        }
    }
    return null;
}
