public boolean deepCompare(Vector[] other, double tolerance) {
    if (other.length != this.length) {
        return false;
    }
    for (int i = 0; i < this.length; i++) {
        if (this[i].size() != other[i].size()) {
            return false;
        }
        for (int j = 0; j < this[i].size(); j++) {
            double diff = Math.abs(this[i].get(j) - other[i].get(j));
            if (diff > tolerance) {
                return false;
            }
        }
    }
    return true;
}
