public interface TransitionCallback {
    void onTransitionStart(Transition transition);
    void onTransitionEnd(Transition transition);
    void onTransitionCancel(Transition transition);
}
public static TransitionCallback customizeTransitionBehavior(View fromView) {
    Transition transition = TransitionInflater.from(fromView.getContext()).inflateTransition(android.R.transition.move);
    transition.setDuration(500);
    transition.setInterpolator(new AccelerateDecelerateInterpolator());
    transition.addListener(new Transition.TransitionListener() {
        @Override
        public void onTransitionStart(Transition transition) {
            // do something when transition starts
        }

        @Override
        public void onTransitionEnd(Transition transition) {
            // do something when transition ends
        }

        @Override
        public void onTransitionCancel(Transition transition) {
            // do something when transition is canceled
        }

        @Override
        public void onTransitionPause(Transition transition) {
            // do something when transition is paused
        }

        @Override
        public void onTransitionResume(Transition transition) {
            // do something when transition is resumed
        }
    });
    return new TransitionCallback() {
        @Override
        public void onTransitionStart(Transition transition) {
            transition.setDuration(500);
            transition.setInterpolator(new AccelerateDecelerateInterpolator());
        }

        @Override
        public void onTransitionEnd(Transition transition) {
            // do something when transition ends
        }

        @Override
        public void onTransitionCancel(Transition transition) {
            // do something when transition is canceled
        }
    };
}
