public Image importPdfPagesAsImages(PdfContentByte canvas, URL data, float opacity) throws VectorPrintException, BadElementException {
    Image img = null;
    try {
        PdfReader reader = new PdfReader(data);
        int n = reader.getNumberOfPages();
        for (int i = 1; i <= n; i++) {
            img = processImage(Image.getInstance(reader, i));
            img.setAbsolutePosition(0, 0);
            img.scalePercent(opacity);
            canvas.addImage(img);
        }
        reader.close();
    } catch (IOException e) {
        throw new VectorPrintException("ImportPdfPagesAsImages->IOException", e);
    }
    return img;
}
