public static List<String> getTargetClasses(String xml) throws Exception {
    List<String> targetClasses = new ArrayList<>();
    DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
    DocumentBuilder builder = factory.newDocumentBuilder();
    Document document = builder.parse(new InputSource(new StringReader(xml)));
    NodeList nodeList = document.getElementsByTagName("TargetClass");
    for (int i = 0; i < nodeList.getLength(); i++) {
        Element element = (Element) nodeList.item(i);
        targetClasses.add(element.getAttribute("name"));
    }
    return targetClasses;
}
