public Object createFixture(String name, Object[] params) throws Exception {
    Class<?> fixtureClass = Class.forName(name);
    Constructor<?> constructor = fixtureClass.getConstructor(getTypes(params));
    return constructor.newInstance(params);
}

private Class<?>[] getTypes(Object[] params) {
    Class<?>[] types = new Class<?>[params.length];
    for (int i = 0; i < types.length; i++) {
        types[i] = params[i].getClass();
    }
    return types;
}
