public String getTaskStatus(String taskId, Map<String, String> reqHeaders) {
    String endpoint = "http://example.com/tasks/status";
    String queryParams = String.format("taskId=%s&waitTime=0", taskId);

    try {
        URL url = new URL(endpoint + "?" + queryParams);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");

        for (Map.Entry<String, String> header : reqHeaders.entrySet()) {
            connection.setRequestProperty(header.getKey(), header.getValue());
        }

        int responseCode = connection.getResponseCode();

        if (responseCode == HttpURLConnection.HTTP_OK) {
            BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
            String response = in.readLine();
            in.close();

            return response;
        } else {
            throw new RuntimeException("Failed to get task status. Response code: " + responseCode);
        }
    } catch (IOException e) {
        throw new RuntimeException("Failed to get task status. Exception: " + e.getMessage());
    }
}
