public byte[] truncateAndKeepMiddle(byte[] input, int length) {
    if(input.length <= length) {
        return input;
    }
    int offset = (input.length - length) / 2;
    byte[] output = new byte[length];
    System.arraycopy(input, offset, output, 0, length);
    return output;
}
