public void addCustomFieldsToTree(TreeNode parentNode, CustomFieldsFile file) {
    // Add custom fields to the tree by iterating through the list of fields in the custom fields file
    for(CustomField field : file.getFields()) {
        // Create a new tree node for this custom field
        TreeNode customFieldNode = new TreeNode(field.getName());

        // Add the custom field node as a child to the parent node
        parentNode.addChild(customFieldNode);
    }
}
