public void cleanUpTerminatedMockInstances(Duration period) {
    // Read value of period from properties file, if not overridden by user
    Properties properties = new Properties();
    try {
        InputStream input = new FileInputStream("aws-mock.properties");
        properties.load(input);
    } catch (IOException e) {
        // Handle exception
    }
    long cleanUpPeriodMillis = Long.parseLong(properties.getProperty("cleanUpPeriodMillis"));

    // Schedule cleanup task using ScheduledExecutorService
    ScheduledExecutorService executorService = Executors.newSingleThreadScheduledExecutor();
    executorService.scheduleWithFixedDelay(() -> {
        // Perform cleanup logic here
    }, 0, cleanUpPeriodMillis, TimeUnit.MILLISECONDS);
}
