public void addColumnsToGet(Collection<Column> columns, Get get) {
    for (Column column : columns) {
        byte[] family = column.getFamily();
        byte[] qualifier = column.getQualifier();
        if (!get.getFamilyMap().containsKey(family) || !get.getFamilyMap().get(family).containsKey(qualifier)) {
            get.addColumn(family, qualifier);
        }
    }
}
