public static int countOccurrences(String str, String keyw) {
    int count = 0;
    int index = 0;
    while (true) {
        index = str.toLowerCase().indexOf(keyw.toLowerCase(), index);
        if (index != -1) {
            count++;
            index += keyw.length();
        } else {
            break;
        }
    }
    return count;
}
