public boolean isHigherVersion(Version other) {
    // Split version strings to get major and minor version numbers
    int[] thisVersion = Arrays.stream(this.getVersion().split("\\."))
                              .mapToInt(Integer::parseInt)
                              .limit(2)
                              .toArray();
    int[] otherVersion = Arrays.stream(other.getVersion().split("\\."))
                               .mapToInt(Integer::parseInt)
                               .limit(2)
                               .toArray();

    // Compare major and minor version numbers
    if (thisVersion[0] > otherVersion[0]) {
        return true;
    } else if (thisVersion[0] == otherVersion[0]) {
        if (thisVersion[1] > otherVersion[1]) {
            return true;
        }
    }
    return false;   
}
