public Node addItemToList(String item) {
    if (map.containsKey(item)) {
        Node node = map.get(item);
        node.setWeight(node.getWeight() + 1);
        return node;
    } else {
        Node node = new Node(item, 1);
        if (map.size() >= maxSize) {
            removeHalfListItems();
        }
        list.addFirst(node);
        map.put(item, node);
        return node;
    }
}

private void removeHalfListItems() {
    int targetSize = list.size() / 2;
    while (list.size() > targetSize) {
        Node node = list.removeLast();
        map.remove(node.getValue());
    }
    resetWeights();
}

private void resetWeights() {
    for (Node node : list) {
        node.setWeight(1);
    }
}
