public JAXBInfo buildJAXBInfo(Class<?> cls, String rootNns) throws SecurityException, NoSuchFieldException, ClassNotFoundException, ParseException {
    JAXBInfo info = new JAXBInfo();
    info.setCls(cls);
    info.setRootNns(rootNns);

    ElementInfo elemInfo = getElementInfo(cls);
    info.setElementInfo(elemInfo);

    List<Field> fields = getAllFields(cls);

    for (Field field : fields) {
        if (field.isAnnotationPresent(XmlTransient.class)) {
            continue;
        }
        String fieldName = field.getName();
        Class<?> fieldType = field.getType();

        if (isPrimitiveType(fieldType)) {
            ElementInfo subElementInfo = new ElementInfo();
            subElementInfo.setName(fieldName);
            subElementInfo.setNamespace(info.getRootNns());
            subElementInfo.setClassName(fieldType.getName());
            subElementInfo.setPrimitive(true);

            elemInfo.getChildren().add(subElementInfo);
        } else if (isCollectionType(fieldType)) {
            ElementInfo subElementInfo = new ElementInfo();
            subElementInfo.setName(fieldName);
            subElementInfo.setNamespace(info.getRootNns());
            subElementInfo.setPrimitive(false);

            Type genericType = field.getGenericType();
            if (genericType instanceof ParameterizedType) {
                ParameterizedType paramType = (ParameterizedType) genericType;
                Type[] typeArguments = paramType.getActualTypeArguments();
                if (typeArguments != null && typeArguments.length > 0) {
                    Type typeArg = typeArguments[0];
                    if (typeArg instanceof Class) {
                        String className = ((Class<?>) typeArg).getName();
                        subElementInfo.setClassName(className);
                    }
                }
            }

            elemInfo.getChildren().add(subElementInfo);
        } else {
            String fieldNameCap = capitalize(fieldName);
            String methodName = "get" + fieldNameCap;
            Method method = cls.getMethod(methodName);

            ElementInfo subElementInfo = getElementInfo(fieldType);
            subElementInfo.setName(fieldName);
            subElementInfo.setNamespace(info.getRootNns());
            subElementInfo.setPrimitive(false);

            JAXBInfo subInfo = buildJAXBInfo(fieldType, info.getRootNns());
            subElementInfo.setSubJAXBInfo(subInfo);

            elemInfo.getChildren().add(subElementInfo);
        }
    }

    return info;
}
