public Profile mergeProfiles(List<Profile> profiles) {
    Profile mergedProfile = new Profile();
    for (Profile profile : profiles) {
        if (profile != null) {
            if (profile.getLimit() != null) {
                if (mergedProfile.getLimit() == null) {
                    mergedProfile.setLimit(profile.getLimit());
                } else {
                    mergedProfile.setLimit(mergedProfile.getLimit() + profile.getLimit());
                }
            }
            if (profile.getQuality() != null) {
                mergedProfile.setQuality(profile.getQuality());
            }
            if (profile.getFormat() != null) {
                mergedProfile.setFormat(profile.getFormat());
            }
            if (profile.getSize() != null) {
                mergedProfile.setSize(profile.getSize());
            }
        }
    }
    return mergedProfile;
}
