public static <T extends ImageGray<T>> DenseOpticalFlowBlockPyramid<T> createPyramid(BlockPyramid.Config config) {
    if( config == null )
        throw new IllegalArgumentException("Configuration cannot be null");

    // Computes image derivates and pyramids
    PyramidFloatGauss pyramid = new PyramidFloatGauss(config.pyramidTopSize, config.pyramidLayers, config.sigma, true, ImageType.single(config.imageType));

    // Extracts feature intensity statistics from each image layer
    FeatureIntensity<T> intensity = createIntensity(config);

    // Configures block intensity statistics
    DenseOpticalFlowBlockRegisterPyramid.Input<T> input = new DenseOpticalFlowBlockRegisterPyramid.Input<T>();
    input.intensity = intensity;
    input.pyramid = pyramid;
    input.config = config;

    // Creating an instance of pyramid block registration
    return new DenseOpticalFlowBlockRegisterPyramid<>(input);
}

private static <T extends ImageGray<T>>
FeatureIntensity<T> createIntensity(BlockPyramid.Config config) {
    Factory<T> factoryI = FactoryKeepBorderInterpolation.single(config.imageType);
    ImageGradient<T, ?> gradient = FactoryDerivative.sobel(config.imageType, factoryI);
    ImageMiscOps<T> ops = FactoryImageMiscOps.single(config.imageType);

    return new FeatureIntensity<>(gradient, ops, ImageType.single(config.imageType));
}
