public class JavaFilesIndexer {
    public static List<File> createJavaFilesIndex(File rootFolder) {
        List<File> index = new ArrayList<>();
        indexJavaFiles(rootFolder, index);
        return index;
    }

    private static void indexJavaFiles(File folder, List<File> index) {
        if (folder.isDirectory()) {
            for (File file : folder.listFiles()) {
                if (file.isDirectory()) {
                    indexJavaFiles(file, index);
                } else if (file.getName().endsWith(".java")) {
                    index.add(file);
                }
            }
        }
    }
}
