public static void spookyHash128(final BitVector bv,
                                 final long seed,
                                 final long[] tuple) {
    final long[] h = new long[] {seed, seed, seed, seed};
    final long[] m = new long[2];
    final long[] spooky = new long[2];
    final ByteBuffer buf = ByteBuffer.wrap(bv.array(), bv.offset(), bv.capacity()).order(ByteOrder.LITTLE_ENDIAN);
    while (buf.remaining() >= 16) {
        m[0] = buf.getLong();
        m[1] = buf.getLong();
        mix(m, h);
    }
    spookyAfterMix(h);
    spooky[0] = h[1] + h[0];
    spooky[1] = h[2] + h[3];
    longToByteArray(spooky[0], tuple, 0);
    if (tuple.length > 1) {
        longToByteArray(spooky[1], tuple, 2);
    }
}
