public boolean isMultipointWithinEnvelope(double[] multipoint_a, double[] envelope_b) {
    double minX = envelope_b[0];
    double minY = envelope_b[1];
    double maxX = envelope_b[2];
    double maxY = envelope_b[3];

    for (int i = 0; i < multipoint_a.length; i += 2) {
        double x = multipoint_a[i];
        double y = multipoint_a[i+1];

        if (x < minX || x > maxX || y < minY || y > maxY) {
            return false;
        }
    }

    return true;
}
