public int extractNTLMFlags(byte[] msg) {
     // Byte 20 contains the byte array for the flags
     int flags = ((msg[19] & 0xff) << 16) | ((msg[18] & 0xff) << 8) | (msg[17] & 0xff);
     return flags;
}
