public static boolean deleteFileAndContents(File f) {
    if (f.isDirectory()) {
        File[] files = f.listFiles();
        if (files != null) {
            for (File subFile : files) {
                deleteFileAndContents(subFile); // recursive call
            }
        }
    }
    return f.delete();
}
