import java.awt.Dimension;
import java.awt.Toolkit;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.Reader;

import javax.swing.JDialog;
import javax.swing.JFrame;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;

public class GraphVIZDialog extends JDialog
{
    private static final long serialVersionUID = 1L;
    private JTextArea area;

    public GraphVIZDialog(JFrame parent, Reader r, boolean modal) throws IOException
    {
        super(parent, modal);
        setTitle("Graph Description");

        BufferedReader br = new BufferedReader(r);
        StringBuilder sb = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) {
            sb.append(line);
        }
        br.close();
        GraphVIZPanel panel = new GraphVIZPanel(sb.toString());
        panel.setPreferredSize(new Dimension(800,600));

        area = new JTextArea(sb.toString());
        area.setEditable(false);
        JScrollPane sp = new JScrollPane(area);

        getContentPane().setLayout(new BorderLayout());
        getContentPane().add(sp, BorderLayout.NORTH);
        getContentPane().add(panel, BorderLayout.CENTER);

        pack();
        Dimension ss = Toolkit.getDefaultToolkit().getScreenSize();
        int w = getWidth();
        int h = getHeight();
        setLocation((ss.width-w)/2, (ss.height-h)/2);
        setVisible(true);
    }
}
