import java.util.Comparator;
import java.util.Optional;
import java.util.concurrent.ForkJoinPool;
import java.util.stream.Collector;
import java.util.stream.Stream;

public class MinExecutor {

    public static <T> Optional<T> executeMin(Stream<T> stream, Comparator<? super T> comparator, Collector<? super T, ?, Optional<T>> collector) {

        if (stream.isParallel()) {
            ForkJoinPool customPool = new ForkJoinPool();
            return customPool.submit(() -> stream.min(comparator).collect(collector)).join();
        }

        return stream.min(comparator).collect(collector);
    }
}
