public void copyBytes(InputStream is, int length) throws IOException {
    byte[] byteArray = new byte[length];
    int totalBytesRead = 0;
    int bytesRead = 0;
    while (totalBytesRead < length && bytesRead != -1) {
        bytesRead = is.read(byteArray, totalBytesRead, length - totalBytesRead);
        if (bytesRead > 0) {
            totalBytesRead += bytesRead;
        }
    }
}
