public void buildCPESearchIndex(CveDB cve) throws IndexException {
    try {
        Directory dir = FSDirectory.open(Paths.get("cpe_index"));
        Analyzer analyzer = new StandardAnalyzer();
        IndexWriterConfig iwc = new IndexWriterConfig(analyzer);
        iwc.setOpenMode(OpenMode.CREATE);
        IndexWriter writer = new IndexWriter(dir, iwc);

        for (Cve c : cve.getCveList()) {
            Document doc = new Document();
            doc.add(new StringField("cpe", c.getCpe(), Field.Store.YES));
            doc.add(new StringField("vendor", c.getVendor(), Field.Store.YES));
            doc.add(new StringField("product", c.getProduct(), Field.Store.YES));
            writer.addDocument(doc);
        }

        writer.close();
    } catch (IOException e) {
        throw new IndexException("Error creating CPE search index", e);
    }
}
