import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.ArrayList;

public Map<Integer, List<String>> splitArgumentsByShard(DataSourceProvider dataSourceProvider, List<String> args) {
    Map<Integer, List<String>> map = new TreeMap<Integer, List<String>>();
    int shardId;
    for (String arg : args) {
        // get virtual shard id from data source provider
        shardId = dataSourceProvider.getVirtualShardId(arg);
        // if the shardId is not in the map, create a new list for it
        if (!map.containsKey(shardId)) {
            map.put(shardId, new ArrayList<String>());
        }
        // add the arg to the corresponding shard
        map.get(shardId).add(arg);
    }
    return map;
}
