public Object getTemplate(String fullName) throws ClassNotFoundException, NoSuchMethodException {
    String[] parts = fullName.split("\\.");
    String name = parts[parts.length - 1];
    String path = fullName.replace('.', '/') + ".groovy";
    URL url = getClass().getClassLoader().getResource(path);
    if (url == null) {
        throw new ClassNotFoundException(fullName);
    }
    GroovyClassLoader loader = new GroovyClassLoader();
    Class<?> clazz = loader.parseClass(url);
    Method method;
    try {
        method = clazz.getMethod(name);
    } catch (NoSuchMethodException e) {
        throw new NoSuchMethodException(fullName);
    }
    return method.invoke(clazz.newInstance());
}
