public static <T> TIMESTAMP[] getTimestampArray(T[] v) {
    if (v == null) {
        return null;
    }

    TIMESTAMP[] result = new TIMESTAMP[v.length];
    for (int i = 0; i < v.length; i++) {
        if (v[i] == null) {
            result[i] = new TIMESTAMP(null);
        } else {
            // replace "Object" in the line below with the actual type of the object you're trying to convert to a TIMESTAMP
            result[i] = new TIMESTAMP((Object) v[i]);
        }
    }

    return result;
}
