public void validateComponentName(String name, String type, List<String> previousEntries) {
    if(name == null || name.isEmpty()) {
        throw new IllegalStateException("Invalid " + type + " name: empty or null value");
    }
    if(!name.matches("[a-zA-Z0-9_]+")) {
        throw new IllegalStateException("Invalid " + type + " name: contains invalid characters");
    }
    if(previousEntries.contains(name)) {
        throw new IllegalStateException("Invalid " + type + " name: already exists");
    }
}
