public String[] readExternalIdentifiers(boolean inNotation, boolean isSubset) {
    String[] identifiers = new String[3];
    if(inNotation || !isSubset) {
        // parsing a notation decl or not a subset decl, so no external identifiers needed
        return null;
    }
    // try reading external identifiers
    try {
        identifiers[0] = getPublicIdentifier();
        identifiers[1] = getSystemIdentifier();
        identifiers[2] = getBaseURI();
    } catch (Exception e) {
        // handle any exceptions thrown while reading identifiers
        e.printStackTrace();
    }
    return identifiers;
}
