        setFirstChild(null);
        rc = true;
      } else {

        do {
          if (currNode == node) {

            if (node.getPrevSibling() != null) {
              node.getPrevSibling().setNextSibling(node.getNextSibling());
            }
            if (node == getFirstChild()) {
              setFirstChild(node.getNextSibling());
            }
