public static MessageNode createMessageNode(String pattern) throws IllegalArgumentException {
    if(pattern == null || pattern.isEmpty()) {
        throw new IllegalArgumentException("MessagePattern can not be empty");
    }

    MessageFormat mf = new MessageFormat(pattern);
    MessageNode node = mf.getMessageNode(0);

    if(node == null || node.getMessageText().length() == 0) {
        throw new IllegalArgumentException("MessagePattern does not represent a MessageFormat pattern");
    }

    return node;
}
