public static void streamReadable(Readable readable, FASTQVariant variant, EventBasedReaderCallback listener) throws IOException {
    if (readable == null || variant == null || listener == null) {
        throw new IllegalArgumentException("Readable, FASTQVariant, and EventBasedReaderCallback must not be null");
    }

    BufferedReader reader = new BufferedReader(readable);

    String line;
    FastqRecord record = null;
    while ((line = reader.readLine()) != null) {
        if (line.startsWith("@")) {
            if (record != null) {
                listener.onRecord(record);
            }
            record = new FastqRecord(line.substring(1), "", "", "");
        } else if (record != null) {
            if (record.getSequence().isEmpty()) {
                record.setSequence(line);
            } else if (line.startsWith("+")) {
                // Do nothing
            } else if (record.getQuality().isEmpty()) {
                record.setQuality(line);
            } else {
                record.setDescription(record.getDescription() + line);
            }
        }
    }

    if (record != null) {
        listener.onRecord(record);
    }
}
