public static DateRange getDateRange(int hours, Date start, Date end) {
    Calendar calStart = Calendar.getInstance();
    calStart.setTime(start);
    calStart.set(Calendar.HOUR_OF_DAY, hours);
    calStart.set(Calendar.MINUTE, 0);
    calStart.set(Calendar.SECOND, 0);
    calStart.set(Calendar.MILLISECOND, 0);

    Calendar calEnd = Calendar.getInstance();
    calEnd.setTime(end);
    if (calEnd.get(Calendar.HOUR_OF_DAY) == 0 && calEnd.get(Calendar.MINUTE) == 0 &&
            calEnd.get(Calendar.SECOND) == 0 && calEnd.get(Calendar.MILLISECOND) == 0) {
        calEnd.add(Calendar.DAY_OF_MONTH, 1);
    }
    calEnd.set(Calendar.HOUR_OF_DAY, hours);
    calEnd.set(Calendar.MINUTE, 0);
    calEnd.set(Calendar.SECOND, 0);
    calEnd.set(Calendar.MILLISECOND, 0);

    return new DateRange(calStart.getTime(), calEnd.getTime());
}
