public Object callMethodOrPOJO(Object obj, String methodName, Object... args) throws Exception {
    try {
        Method method = obj.getClass().getMethod(methodName);
        return method.invoke(obj, args);
    } catch (NoSuchMethodException e) {
        MetaClass metaClass = GroovySystem.getMetaClassRegistry().getMetaClass(obj.getClass());
        return metaClass.invokeMethod(obj, methodName, args);
    }
}
