public String formatTimecode(int[] timecodeTrack, int counter) {
    int framesPerSecond = timecodeTrack[0];
    int framesPerMinute = timecodeTrack[1];
    int framesPerHour = timecodeTrack[2];

    int totalFrames = counter % framesPerSecond;
    int seconds = (counter / framesPerSecond) % 60;
    int minutes = ((counter / framesPerSecond) / 60) % 60;
    int hours = ((((counter / framesPerSecond) / 60) / 60) % 24) + ((counter / framesPerHour) % 24);

    String formattedTimecode = String.format("%02d:%02d:%02d:%02d", hours, minutes, seconds, totalFrames);

    return formattedTimecode;
}
