public CompactDFA minimizeDFA(DFA dfa, List<Character> alphabet, int pruningMode) {

    Table<Integer, Integer, Boolean> table = HashBasedTable.create();

    // Initialize table for all pairs of states (q, p) where q is not accepting and p is accepting
    for (State q : dfa.getStates()) {
        if (!q.isAccepting()) {
            for (State p : dfa.getAcceptingStates()) {
                table.put(q.getId(), p.getId(), true);
                table.put(p.getId(), q.getId(), true);
            }
        }
    }

    boolean changed = true;
    while (changed) {
        changed = false;
        for (State q : dfa.getStates()) {
            if (!q.isAccepting()) {
                for (State p : dfa.getAcceptingStates()) {
                    if (table.get(q.getId(), p.getId()) == null) {
                        boolean isEquivalent = true;

                        // Check equivalence for each character in the alphabet
                        for (char c : alphabet) {
                            State qNext = q.getTransition(c);
                            State pNext = p.getTransition(c);

                            // Check if qNext and pNext are equivalent
                            if (qNext != null && pNext != null && table.get(qNext.getId(), pNext.getId()) != null) {
                                continue;
                            } else if (qNext == null && pNext == null) {
                                continue;
                            } else {
                                isEquivalent = false;
                                break;
                            }
                        }
                        if (isEquivalent) {
                            table.put(q.getId(), p.getId(), true);
                            table.put(p.getId(), q.getId(), true);
                            changed = true;
                        }
                    }
                }
            }
        }
    }

    Map<Integer, Integer> stateMap = new HashMap<>();
    for (State s : dfa.getStates()) {
        stateMap.put(s.getId(), stateMap.size());
    }
    int[][] transitionTable = new int[stateMap.size()][alphabet.size()];
    int[] stateType = new int[stateMap.size()];
    int index = 0;

    // Create arrays for the CompactDFA
    for (int i = 0; i < dfa.getStates().size(); i++) {
        State s = dfa.getStates().get(i);
        // If this state is not reachable from the start state, skip it
        if (stateMap.containsKey(s.getId())) {
            for (int j = 0; j < alphabet.size(); j++) {
                State t = s.getTransition(alphabet.get(j));
                if (t != null && stateMap.containsKey(t.getId())) {
                    transitionTable[stateMap.get(s.getId())][j] = stateMap.get(t.getId());
                } else {
                    transitionTable[stateMap.get(s.getId())][j] = -1;
                }
            }
            if (s.isAccepting()) {
                stateType[stateMap.get(s.getId())] = CompactDFA.TYPE_ACCEPTING;
            } else {
                stateType[stateMap.get(s.getId())] = CompactDFA.TYPE_NON_ACCEPTING;
            }
            index++;
        }
    }

    return new CompactDFA(transitionTable, stateType, pruningMode);
}
