public byte[] extractSessionKey(GSSContext gssContext, Subject subject) throws GSSException {
    byte[] sessionKey = gssContext.getSessionKey();
    if (sessionKey == null && subject != null) {
        Set<GSSCredential> creds = subject.getPrivateCredentials(GSSCredential.class);
        for (GSSCredential cred : creds) {
            GSSName target = gssContext.getTargName();
            if (target != null && cred.getName().equals(target)) {
                sessionKey = cred.getSessionKey();
                break;
            }
        }
    }
    if (sessionKey == null) {
        throw new GSSException(GSSException.NO_DEFAULT_KEY);
    }
    return sessionKey;
}
