public Person getPersonById(String id) {
    // implementation to fetch person by id from the data source
    // and return Person object if found, otherwise throw an exception

    // sample code assuming the data source is a database
    Connection conn = DriverManager.getConnection(DB_URL, USER, PASS);
    Statement stmt = conn.createStatement();
    ResultSet rs = stmt.executeQuery("SELECT * FROM persons WHERE id='" + id + "'");
    if (rs.next()) {
        Person person = new Person();
        person.setId(rs.getString("id"));
        person.setName(rs.getString("name"));
        person.setAge(rs.getInt("age"));
