public double distanceToHyperrectangle(Node node, double[] x) throws Exception {
    double dist = 0.0;
    int dimensions = x.length;
    for (int i = 0; i < dimensions; i++) {
        double value = x[i];
        if (value < node.getMin()[i]) {
            dist += Math.pow(node.getMin()[i] - value, 2);
        } else if (value > node.getMax()[i]) {
            dist += Math.pow(value - node.getMax()[i], 2);
        }
    }
    return Math.sqrt(dist);
}
