public boolean hasSuffix(Bytes suffix) {
    if (suffix.length() > this.length()) {
        return false;
    }
    for (int i = 0; i < suffix.length(); i++) {
        if (suffix.byteAt(i) != this.byteAt(this.length() - suffix.length() + i)) {
            return false;
        }
    }
    return true;
}
