public <T, U, V, R> List<R> zipWith(Stream<? extends T> a, Stream<? extends U> b, 
                                     Stream<? extends V> c, TriFunction<? super T, ? super U, ? super V, ? extends R> zipFunction) {
    Iterator<? extends T> i1 = a.iterator();
    Iterator<? extends U> i2 = b.iterator();
    Iterator<? extends V> i3 = c.iterator();
    List<R> result = new ArrayList<>();
    while (i1.hasNext() && i2.hasNext() && i3.hasNext()) {
        result.add(zipFunction.apply(i1.next(), i2.next(), i3.next()));
    }
    return result;
}
