public void loadDataUsingHttp(ClientHttpRequestFactory clientHttpRequestFactory, String styleRef, Function<Data, Style> loadFunction) {
    try {
        URI uri = new URI(styleRef);
        String scheme = uri.getScheme();
        if (scheme != null && scheme.equals("http")) {
            RestTemplate restTemplate = new RestTemplate(clientHttpRequestFactory);
            ResponseEntity<Data> responseEntity = restTemplate.getForEntity(uri, Data.class);
            if (responseEntity.getStatusCode() == HttpStatus.OK) {
                Data data = responseEntity.getBody();
                if (data != null) {
                    loadFunction.apply(data);
                }
            }
        }
    } catch (Exception e) {
        //handle exception
    }
}
