public static void sortSuffixes(String[] suffixes, int start, int mid, int end) {
    int leftSize = mid - start + 1;
    int rightSize = end - mid;
    String[] left = new String[leftSize];
    String[] right = new String[rightSize];
    int i, j;

    // Copy the suffixes into left and right arrays
    for (i = 0; i < leftSize; i++) {
        left[i] = suffixes[start + i];
    }
    for (j = 0; j < rightSize; j++) {
        right[j] = suffixes[mid + 1 + j];
    }

    i = 0;
    j = 0;
    int k = start;

    // Merge the left and right suffixes in sorted order
    while (i < leftSize && j < rightSize) {
        if (left[i].compareTo(right[j]) <= 0) {
            suffixes[k] = left[i];
            i++;
        } else {
            suffixes[k] = right[j];
            j++;
        }
        k++;
    }

    // Copy remaining suffixes from left array
    while (i < leftSize) {
        suffixes[k] = left[i];
        i++;
        k++;
    }

    // Copy remaining suffixes from right array
    while (j < rightSize) {
        suffixes[k] = right[j];
        j++;
        k++;
    }
}
