public static double[] symmetricMatrixScalingFactors(double[][] matrix) {
    int n = matrix.length;
    double[] scalingFactors = new double[n - 1];
    for (int j = 0; j < n - 1; j++) {
        double l2Norm = 0.0;
        for (int i = j + 1; i < n; i++) {
            double element = matrix[i][j];
            l2Norm += element * element;
        }
        l2Norm = Math.sqrt(l2Norm);
        if (l2Norm != 0.0) {
            scalingFactors[j] = 1.0 / l2Norm;
        } else {
            scalingFactors[j] = 1.0;
        }
    }
    return scalingFactors;
}
