public static boolean recursivelyDeleteDirectory(File fileToRemove) {
    // Check if the file is null or if it doesn't exist
    if (fileToRemove == null || !fileToRemove.exists()) {
        return false;
    }

    // Check if the file is a directory
    if (fileToRemove.isDirectory()) {
        // Get a list of all the files and directories inside the current directory
        File[] fileList = fileToRemove.listFiles();
        if (fileList != null) {
            for (File file : fileList) {
                // Recursively call this method for each file/directory inside the current directory
                recursivelyDeleteDirectory(file);
            }
        }
    }

    // Check if the file is not the server lock or server running file
    if (!fileToRemove.getName().equals("server.lock") && !fileToRemove.getName().endsWith(".run")) {
        // Try to delete the file
        if (!fileToRemove.delete()) {
            return false;
        }
    }

    // Return true since the clean succeeded
    return true;
}
