public void checkComponentMethods(String expression) throws NoSuchMethodException {
    Component component = new Component(); // assuming Component is the class we need to check against
    Pattern pattern = Pattern.compile("\\.\\s*(\\p{Alpha}\\w*)\\s*\\("); // pattern to extract method names
    Matcher matcher = pattern.matcher(expression);
    while (matcher.find()) {
        String methodName = matcher.group(1);
        if (!Arrays.stream(component.getClass().getDeclaredMethods())
            .anyMatch(method -> method.getName().equals(methodName))) {
                throw new NoSuchMethodException("Method " + methodName + " not declared in Component");
            }
    }
}
