public static double calculateMedian(double[] survivalFunction) {
    Arrays.sort(survivalFunction);
    int n = survivalFunction.length;
    if(n % 2 == 0) {
        return (survivalFunction[(n / 2) - 1] + survivalFunction[(n / 2)]) / 2;
    } else {
        return survivalFunction[n / 2];
    }
}
