public static byte[] encodeBase64(byte[] source, int off, int len, byte[] alphabet, int maxLineLength) {
    if (source == null) {
        throw new IllegalArgumentException("Cannot encode null source array");
    }
    if (off < 0 || len < 0 || off + len > source.length) {
        throw new IllegalArgumentException("Invalid offset or length");
    }

    if (alphabet == null) {
        alphabet = STANDARD_ALPHABET;
    }

    int len43 = (len * 4 + 2) / 3;
    int lines = (len43 + maxLineLength - 1) / maxLineLength;
    int bufferSize = len43 + lines * (lineSeparator != null ? lineSeparator.length : 0);
    byte[] encoded = new byte[bufferSize];
    int encodedIndex = 0;
    int lineLength = 0;
    int blockIndex = off;
    int blocks = (len / 3) * 3;

    for (int i = 0; i < blocks; i += 3, blockIndex += 3) {
        int block = (source[blockIndex] & 0xff) << 16 | (source[blockIndex + 1] & 0xff) << 8 | (source[blockIndex + 2] & 0xff);
        encoded[encodedIndex++] = alphabet[(block >>> 18) & 0x3f];
        encoded[encodedIndex++] = alphabet[(block >>> 12) & 0x3f];
        encoded[encodedIndex++] = alphabet[(block >>> 6) & 0x3f];
        encoded[encodedIndex++] = alphabet[block & 0x3f];
        lineLength += 4;
        if (lineLength == maxLineLength) {
            if (lineSeparator != null) {
                for (byte b : lineSeparator) {
                    encoded[encodedIndex++] = b;
                }
            }
            lineLength = 0;
        }
    }

    int t = off + len - blocks;
    switch (t) {
        case 1:
            int remaining = source[blockIndex] & 0xff;
            encoded[encodedIndex++] = alphabet[(remaining >>> 2) & 0x3f];
            encoded[encodedIndex++] = alphabet[(remaining << 4) & 0x3f];
            if (pad) {
                encoded[encodedIndex++] = PAD;
                encoded[encodedIndex++] = PAD;
            }
            break;

        case 2:
            int remaining1 = source[blockIndex] & 0xff;
            int remaining2 = source[blockIndex + 1] & 0xff;
            int remainingBlock = (remaining1 << 8) | remaining2;
            encoded[encodedIndex++] = alphabet[(remainingBlock >>> 10) & 0x3f];
            encoded[encodedIndex++] = alphabet[(remainingBlock >>> 4) & 0x3f];
            encoded[encodedIndex++] = alphabet[(remainingBlock << 2) & 0x3f];
            if (pad) {
                encoded[encodedIndex++] = PAD;
            }
            break;
    }

    return encoded;
}
