public String retrieveKey(Clause key) {
    Clause value = null;

    // Traverse sub-clauses to find the key
    if (key != null) {
        value = key.get(key.getKey());
    }

    // If value is a StringClause, return the string version of it
    if (value instanceof StringClause) {
        return ((StringClause) value).getValue();
    }

    // Return null if not set
    return null;
}
