public void adaptView(Color preferenceColor, Color persistedColor, View view) {
    if (preferenceColor == null || view == null) {
        return;
    }

    // Check if the preference color is different from the persisted color
    boolean isDifferent = !preferenceColor.equals(persistedColor);

    // Adapt the view according to the preference's properties and the color difference
    if (isDifferent) {
        // Change the view's background color to the preference color
        view.setBackgroundColor(preferenceColor);

        // Set the view's text color to a contrasting color
        float[] hsv = new float[3];
        Color.RGBToHSV(preferenceColor.getRed(), preferenceColor.getGreen(), preferenceColor.getBlue(), hsv);
        int textColor = hsv[2] > 0.5f ? Color.BLACK : Color.WHITE;
        view.setTextColor(textColor);

        // Apply additional styling as needed
        // ...
    } else {
        // Reset the view's background color and text color to their default values
        view.setBackgroundColor(Color.WHITE);
        view.setTextColor(Color.BLACK);
    }
}
