public static int countOccurrences(String str, String keyw) {
    if (keyw == null || keyw.isEmpty()) {
        return 0;
    }
    int count = 0, index = 0;
    while ((index = str.indexOf(keyw, index)) != -1) {
        count++;
        index += keyw.length();
    }
