public static void warningAndAttemptToCorrect(Object expected, Object actual) {
    if (!expected.getClass().equals(actual.getClass())) {
        System.out.println("WARNING: Objects do not have the same type!");
        if (expected instanceof Integer && actual instanceof Long) {
            expected = ((Integer) expected).longValue();
        } else if (expected instanceof Long && actual instanceof Integer) {
            actual = ((Integer) actual).longValue();
        } else if (expected instanceof Double && actual instanceof Float) {
            expected = ((Double) expected).floatValue();
        } else if (expected instanceof Float && actual instanceof Double) {
            actual = ((Double) actual).floatValue();
        }
        System.out.println("ATTEMPTING TO CORRECT:");
        System.out.println("Expected: " + expected);
        System.out.println("Actual: " + actual);
    } else {
        System.out.println("Objects have the same type!");
    }
}
