public Map<String, Set<FileDescriptor>> checkAndUpdateIndex(Map<String, Set<FileDescriptor>> mutableServices, Map<String, Set<FileDescriptor>> index) {
    // create a new map to store the potentially updated index
    Map<String, Set<FileDescriptor>> updatedIndex = new HashMap<>();

    // iterate through each mutable service in the provided map
    for(Map.Entry<String, Set<FileDescriptor>> entry : mutableServices.entrySet()) {
        String serviceName = entry.getKey();
        Set<FileDescriptor> fileDescriptors = entry.getValue();

        // check if the service name exists in the index map
        if(index.containsKey(serviceName)) {
            Set<FileDescriptor> existingFileDescriptors = index.get(serviceName);

            // check if the file descriptors have changed
            if(!existingFileDescriptors.equals(fileDescriptors)) {
                // add the updated file descriptors to the updated index map
                updatedIndex.put(serviceName, fileDescriptors);
            } else {
                // add the existing file descriptors to the updated index map
                updatedIndex.put(serviceName, existingFileDescriptors);
            }
        } else {
            // add the new service and its file descriptors to the updated index map
            updatedIndex.put(serviceName, fileDescriptors);
        }
    }

    // check for service names that have been removed from the mutable services map
    for(Map.Entry<String, Set<FileDescriptor>> entry : index.entrySet()) {
        String serviceName = entry.getKey();

        if(!mutableServices.containsKey(serviceName)) {
            // remove the service from the index map
            updatedIndex.remove(serviceName);
        }
    }

    return updatedIndex;
}
