public static int decode(BigInteger[] valueRef, byte[] src, int srcOffset) throws CorruptEncodingException {
    if (src == null) {
        throw new CorruptEncodingException("src cannot be null.");
    }
    int length = src.length - srcOffset;
    if (valueRef == null || valueRef.length == 0) {
        throw new CorruptEncodingException("valueRef cannot be null or empty.");
    }
    if (valueRef[0] == null) {
        valueRef[0] = BigInteger.ZERO;
    }
    for (int i = 0; i < length; i++) {
        byte b = src[srcOffset + i];
        if (b >= 0) {
            valueRef[0] = valueRef[0].shiftLeft(7).or(BigInteger.valueOf(b));
        } else {
            valueRef[0] = valueRef[0].shiftLeft(7).or(BigInteger.valueOf(b & 0x7f));
            i++;
            while (i < length && (src[srcOffset + i] & 0x80) != 0) {
                byte c = src[srcOffset + i];
                i++;
                valueRef[0] = valueRef[0].shiftLeft(7).or(BigInteger.valueOf(c & 0x7f));
            }
            if (i >= length || (src[srcOffset + i] & 0x80) != 0) {
                throw new CorruptEncodingException("Invalid encoding.");
            }
            byte c = src[srcOffset + i];
            valueRef[0] = valueRef[0].shiftLeft(7).or(BigInteger.valueOf(c & 0x7f));
        }
    }
    return length;
}
