public static NodeList evaluateXPathNodeListNS(Node contextNode, NamespaceContext namespaceContext, String expression, Object... args) throws XPathExpressionException {
    DocumentBuilderFactory builderFactory = DocumentBuilderFactory.newInstance();
    builderFactory.setNamespaceAware(true);
    DocumentBuilder builder;
    try {
        builder = builderFactory.newDocumentBuilder();
        Document doc = builder.newDocument();
        XPathFactory xpathFactory = XPathFactory.newInstance();
        XPath xpath = xpathFactory.newXPath();
        xpath.setNamespaceContext(namespaceContext);
        Object[] formattedArgs = formatArgs(args);
        String formattedExpression = String.format(expression, formattedArgs);
        XPathExpression expr = xpath.compile(formattedExpression);
        return (NodeList) expr.evaluate(contextNode, XPathConstants.NODESET);
    } catch (ParserConfigurationException e) {
        throw new IllegalStateException(e);
    }
}

private static Object[] formatArgs(Object... args) {
    List<Object> formattedArgs = new ArrayList<>();
    for (Object arg : args) {
        if (arg instanceof NodeList) {
            NodeList nodeList = (NodeList) arg;
            for (int i = 0; i < nodeList.getLength(); i++) {
                Node node = nodeList.item(i);
                formattedArgs.add(node.getTextContent());
            }
        } else {
            formattedArgs.add(arg);
        }
    }
    return formattedArgs.toArray();
}
