public int encodeASN1OctetString(byte[] octets, ByteBuffer buf) {
    int length = octets.length;
    int padding = (length < 128) ? 1 : ((int) Math.ceil(Math.log(length) / Math.log(256)));
    buf.put((byte) 0x04);
    buf.put((byte) (padding + length));
    for (int i = 0; i < padding; i++) {
        buf.put((byte) (length >> 8 * (padding - i - 1)));
    }
    buf.put(octets);
    return padding + length + 2;
}
