import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;

public class BitemporalDateTimeUtils {

    public static BitemporalDateTime parse(Object value) {
        if (value == null) {
            return null;
        }
        LocalDateTime dateTime;
        if (value instanceof Long) {
            dateTime = LocalDateTime.parse(String.valueOf(value), DateTimeFormatter.ofPattern("yyyyMMddHHmmss"));
        } else if (value instanceof String) {
            dateTime = LocalDateTime.parse((String) value, DateTimeFormatter.ofPattern("yyyyMMddHHmmss"));
        } else {
            throw new IllegalArgumentException("Cannot parse value of type " + value.getClass());
        }
        return new BitemporalDateTime(dateTime);
    }
}
