public static <V> boolean findPathToNode(TreeNode<V> node, Comparator<? super V> comparator, V target, SearchMode mode, boolean forwards, List<TreeNode<V>> path) {
    if (node == null) {
        return false;
    }

    path.add(node);

    int cmp = comparator.compare(target, node.getValue());
    if (cmp == 0 || 
            (mode == SearchMode.LESS_THAN && cmp < 0) || 
            (mode == SearchMode.GREATER_THAN && cmp > 0)) {
        return true;
    }

    boolean found = false;
    if (cmp < 0) {
        found = findPathToNode(node.getLeft(), comparator, target, mode, forwards, path);
    } else if (cmp > 0) {
        found = findPathToNode(node.getRight(), comparator, target, mode, forwards, path);
    }

    if (!found) {
        path.remove(path.size() - 1);
    }
    return found;
}
