public static <T extends Comparable<? super T>> Predicate<T> isWithinRangeExclusive(T from, T to) {
    Objects.requireNonNull(from);
    Objects.requireNonNull(to);
    if (to.compareTo(from) <= 0) {
        throw new IllegalArgumentException("To value must be greater than from value");
    }
    return (T value) -> value.compareTo(from) > 0 && value.compareTo(to) <= 0;
}
