public void cancelSucceedingTasks() {
    Task currentTask = this;
    while (currentTask.rightSibling != null) {
        currentTask.rightSibling.cancel();
        currentTask.rightSibling = null;
        currentTask = currentTask.parent;
    }
    if (currentTask.parent != null) {
        currentTask.parent.cancelSucceedingTasks();
    }
}
