public double computePixelDepth(List<Point2D> obs, List<AffineTransform> motion) {
  double depth = 0;
  Point2D firstObs = obs.get(0);
  for (int i = 1; i < obs.size(); i++) {
    Point2D currObs = obs.get(i);
    AffineTransform mat = motion.get(i - 1);
    Point2D transformedFirstObs = mat.transform(firstObs, null);
    double currDepth = (transformedFirstObs.getX() - currObs.getX()) / (i + 1);
    depth += currDepth;
  }
  return depth;
}
