public File getFile(String path) throws FileNotFoundException, IOException {
    File file = new File(path); 
    if (!file.exists()) {
        // Perform welcome file lookup
        // Assuming 'index.html' is the welcome file for this example
        File directory = new File(path);
        File welcomeFile = new File(directory, "index.html");
        if (welcomeFile.exists()) {
            return welcomeFile;
        } else {
            throw new FileNotFoundException("File not found: " + path);
        }
    }
    return file;
}
