public String guessParameterType(DBCatalog db, Node elm) {
   NodeList childNodes = elm.getChildNodes();
   String parameterType = "";
   for (int i = 0; i < childNodes.getLength(); i++) {
      Node childNode = childNodes.item(i);
      if (childNode.getNodeType() == Node.ELEMENT_NODE && childNode.hasAttributes()) {
         NamedNodeMap nodeMap = childNode.getAttributes();
         for (int j = 0; j < nodeMap.getLength(); j++) {
            Node node = nodeMap.item(j);
            if (node.getNodeName().startsWith("param") && db.isValidType(node.getNodeValue())) {
               parameterType = db.getTypeRepresentation(node.getNodeValue());
            }
         }
      }
   }
   return parameterType;
}
