import java.util.*;

public static Geometry convexHull(Geometry geom) {
    if (geom == null) return null;
    if (geom.isEmpty()) return geom;

    // Extract the coordinate array from the geometry
    Coordinate[] coords = geom.getCoordinates();

    // Sort the coordinates by x-coordinate and then by y-coordinate
    Arrays.sort(coords);

    // Create two lists of coordinates: the upper list and the lower list
    LinkedList<Coordinate> upper = new LinkedList<Coordinate>();
    LinkedList<Coordinate> lower = new LinkedList<Coordinate>();
    for (int i = 0; i < coords.length; i++) {
        while (upper.size() >= 2 && !isCCW(upper.get(upper.size() - 2), upper.get(upper.size() - 1), coords[i]))
            upper.removeLast();
        while (lower.size() >= 2 && !isCCW(lower.get(lower.size() - 2), lower.get(lower.size() - 1), coords[coords.length - i - 1]))
            lower.removeLast();
        upper.addLast(coords[i]);
        lower.addLast(coords[coords.length - i - 1]);
    }

    // Concatenate the two lists and remove the last element (which is duplicated)
    upper.addAll(lower.subList(1, lower.size()));
    Coordinate[] hullCoords = upper.toArray(new Coordinate[upper.size() - 1]);

    // Create a new geometry from the convex hull coordinates
    GeometryFactory factory = geom.getFactory();
    return factory.createPolygon(factory.createLinearRing(hullCoords), null);
}

private static boolean isCCW(Coordinate p1, Coordinate p2, Coordinate p3) {
    double dx1 = p2.x - p1.x;
    double dy1 = p2.y - p1.y;
    double dx2 = p3.x - p2.x;
    double dy2 = p3.y - p2.y;
    return (dx1 * dy2 - dx2 * dy1) > 0;
}
