public void removeLastEntry(int[] heap, int entry) {
    heap[entry] = heap[heap.length-1];
    heap[heap.length-1] = 0;
    trickleDown(heap, entry);
}

private void trickleDown(int[] heap, int index) {
    int leftChild = index * 2 + 1;
    int rightChild = index * 2 + 2;

    if (leftChild < heap.length && heap[leftChild] < heap[index]) {
        swap(heap, leftChild, index);
        trickleDown(heap, leftChild);
    }

    if (rightChild < heap.length && heap[rightChild] < heap[index]) {
        swap(heap, rightChild, index);
        trickleDown(heap, rightChild);
    }
}

private void swap(int[] heap, int i, int j) {
    int temp = heap[i];
    heap[i] = heap[j];
    heap[j] = temp;
}
