public GoogleIdToken authenticateAndAuthorizeGoogleIdToken(String token)
        throws GeneralSecurityException, IOException {

    GoogleIdTokenVerifier verifier = new GoogleIdTokenVerifier.Builder(
            new NetHttpTransport(), JacksonFactory.getDefaultInstance())
            .setAudience(Collections.singletonList(CLIENT_ID))
            .build();

    GoogleIdToken idToken = verifier.verify(token);

    if (idToken != null) {
        Payload payload = idToken.getPayload();
        String email = payload.getEmail();

        // Check if the user is authorized to access the application
        if (isUserAuthorized(email)) {
            return idToken;
        }
    }

    return null;
}

private boolean isUserAuthorized(String email) {
    // Check if the user is authorized based on business rules.
    // For example, check if the user is part of an approved domain.
    // Return true if the user is authorized, false otherwise.
    return true;
}
