public Color[] reduceImageColors(int[] pixels, int numColors) {
    ArrayList<Color> colorList = new ArrayList<>();
    int[] rgbValues = new int[pixels.length];

    for (int i = 0; i < pixels.length; i++) {
        int r = (pixels[i] >> 16) & 0xFF;
        int g = (pixels[i] >> 8) & 0xFF;
        int b = pixels[i] & 0xFF;
        rgbValues[i] = (r << 16) | (g << 8) | b;
    }

    KMeans kMeans = new KMeans(numColors, rgbValues);
    int[] labels = kMeans.getLabels();
    int[] centroids = kMeans.getCentroids();

    for (int c : centroids) {
        int r = (c >> 16) & 0xFF;
        int g = (c >> 8) & 0xFF;
        int b = c & 0xFF;
        colorList.add(new Color(r, g, b));
    }

    Color[] colorPalette = new Color[colorList.size()];
    colorList.toArray(colorPalette);

    for (int i = 0; i < pixels.length; i++) {
        pixels[i] = labels[i];
    }

    return colorPalette;
}
