import java.util.stream.Stream;

public class TimeSeriesMetricDeltas {

    private String metricName;
    private long metricValue;

    // constructor
    public TimeSeriesMetricDeltas(String metricName, long metricValue) {
        this.metricName = metricName;
        this.metricValue = metricValue;
    }

    // Getters and Setters
    public String getMetricName() {
        return metricName;
    }

    public void setMetricName(String metricName) {
        this.metricName = metricName;
    }

    public long getMetricValue() {
        return metricValue;
    }

    public void setMetricValue(long metricValue) {
        this.metricValue = metricValue;
    }

    // Create stream of TimeSeriesMetricsDeltas with values
    public static Stream<TimeSeriesMetricDeltas> createTimeSeriesMetricDeltas(String[] metricNames, long[] metricValues) {
        if (metricNames.length != metricValues.length) {
            throw new IllegalArgumentException("Length of metricNames and metricValues should be same");
        }
        return Stream.iterate(0, i -> i + 1)
                .limit(metricNames.length)
                .map(i -> new TimeSeriesMetricDeltas(metricNames[i], metricValues[i]));
    }
}
