import java.util.ArrayList;
import java.util.List;

public class HashNeighbors {
    public static List<String> getNeighbors(String hash) {
        List<String> neighbors = new ArrayList<String>();
        int row = Integer.parseInt(hash.substring(0, 4), 16);
        int col = Integer.parseInt(hash.substring(4, 8), 16);
        for (int rowOffset = -1; rowOffset <= 1; rowOffset++) {
            for (int colOffset = -1; colOffset <= 1; colOffset++) {
                if (rowOffset == 0 && colOffset == 0) {
                    continue;
                }
                int neighborRow = row + rowOffset;
                int neighborCol = col + colOffset;
                if (neighborRow < 0 || neighborRow > 65535 || neighborCol < 0 || neighborCol > 65535) {
                    continue;
                }
                String neighborHash = String.format("%04x%04x", neighborRow, neighborCol);
                neighbors.add(neighborHash);
            }
        }
        return neighbors;
    }
}
