public List<String> trimList(List<String> list, String delimiter) {
    if (list == null || list.isEmpty()) {
        return list;
    }

    List<String> trimmedList = new ArrayList<>();
    boolean foundNonEmpty = false;

    for (String element : list) {
        if (!foundNonEmpty && element.trim().equals("")) {
            continue;
        } else {
            foundNonEmpty = true;
            if (!element.endsWith(delimiter)) {
                trimmedList.add(element.trim());
            } else {
                trimmedList.add(element.trim().substring(0, element.length() - delimiter.length()));
            }
        }
    }

    while (!trimmedList.isEmpty() && trimmedList.get(trimmedList.size() - 1).equals("")) {
        trimmedList.remove(trimmedList.size() - 1);
    }

    return trimmedList;
}
