public void commitData() throws IOException {
    // assuming the data is being written to a file
    File dataFile = new File("path/to/data/file");
    // create a file output stream to write the data
    FileOutputStream fileOutputStream = new FileOutputStream(dataFile);
    // get a channel for the file output stream
    FileChannel fileChannel = fileOutputStream.getChannel();
    // force any changes to be written to the disk
    fileChannel.force(true);
    // close the file channel and output stream
    fileChannel.close();
    fileOutputStream.close();
}
