private boolean rule3(double sample) {
        if (null == rule3PreviousSample) {
            rule3PreviousSample = sample;
            rule3Count = 0;
            return false;
        }
        if (sample > rule3PreviousSample) {
            if (rule3Count > 0) {
                ++rule3Count;
            } else {
                rule3Count = 1;
            }
        } else if (sample < rule3PreviousSample) {
            if (rule3Count < 0) {
                --rule3Count;
            } else {
                rule3Count = -1;
            }
        } else {
            rule3Count = 0;
        }
        rule3PreviousSample = sample;
        return Math.abs(rule3Count) >= 6;
