public Map<String, List<String>> getPropertyMap(String[] result, int startingPoint) {
    Map<String, List<String>> propertyMap = new HashMap<>();
    int i = startingPoint;
    while (i < result.length) {
        String propertyName = result[i];
        int propertySize = Integer.parseInt(result[i+1]);
        List<String> propertyValues = new ArrayList<>();
        for (int j = i+2; j < i+2+propertySize; j++) {
            propertyValues.add(result[j]);
        }
        propertyMap.put(propertyName, propertyValues);
        i += propertySize + 2;
    }
    return propertyMap;
}
