public DependencyNode getVerboseDependencyTree() {
    DefaultRepositorySystemSession session = new DefaultRepositorySystemSession();
    session.setConfigProperty(ConfigurationProperties.DEFAULT_LAYOUT_PROVIDER, "maven");
    session.setConfigProperty(ConfigurationProperties.USER_AGENT, "MyAgent/1.0");

    RepositorySystem system = RepositorySystemFactory.newRepositorySystem();
    LocalRepository localRepo = new LocalRepository("target/local-repository");
    LocalRepositoryManager manager = system.newLocalRepositoryManager(new DefaultRepositorySystemSession(), localRepo);

    DefaultRepositorySystemSession repoSession = new DefaultRepositorySystemSession();
    repoSession.setLocalRepositoryManager(manager);

    MavenRepositorySystemSession mavenSession = new MavenRepositorySystemSession();
    mavenSession.setRepositoryListener(new ConsoleRepositoryListener());
    mavenSession.setTransferListener(new ConsoleTransferListener());
    mavenSession.setDependencyGraphTransformer(null);

    MavenModelResolver resolver = new MavenModelResolver(system, repoSession, localRepo);

    DefaultArtifact artifact = new DefaultArtifact("groupId", "artifactId", "classifier", "extension", "version");
    ArtifactDescriptorRequest descriptorRequest = new ArtifactDescriptorRequest(artifact, null, null);

    ArtifactDescriptorResult descriptorResult = repoSession.getRepositorySystem().readArtifactDescriptor(repoSession, descriptorRequest);
    DependencyRequest dependencyRequest = new DependencyRequest();
    dependencyRequest.setRootArtifact(descriptorResult.getArtifact());
    dependencyRequest.setCollectRequest(new CollectRequest(descriptorResult.getArtifact(), descriptorResult.getRepositories()));

    DependencyResult dependencyResult = repoSession.getRepositorySystem().resolveDependencies(repoSession, dependencyRequest);

    return dependencyResult.getRoot();
}
