import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import javax.management.remote.JMXRequest;

public static String throwableToJson(Throwable pExp, JMXRequest pJmxReq) throws JsonProcessingException {

    ObjectMapper mapper = new ObjectMapper();
    ObjectNode rootNode = mapper.createObjectNode();

    rootNode.put("exceptionClass", pExp.getClass().getName());
    rootNode.put("message", pExp.getMessage());

    ObjectNode traceNode = mapper.createObjectNode();
    int traceNodeIndex = 0;

    for (StackTraceElement ste : pExp.getStackTrace()) {
        ObjectNode elementNode = mapper.createObjectNode();
        elementNode.put("className", ste.getClassName());
        elementNode.put("fileName", ste.getFileName());
        elementNode.put("methodName", ste.getMethodName());
        elementNode.put("lineNumber", ste.getLineNumber());
        traceNode.set(String.valueOf(traceNodeIndex++), elementNode);
    }

    rootNode.set("trace", traceNode);

    return mapper.writerWithDefaultPrettyPrinter().writeValueAsString(rootNode);
}
