import java.util.*;

public class PairedSequence {
    public static <K,V> Map<K,V> pairedMap(Iterable<K> keys, Iterable<V> values) {
        Iterator<K> keyIterator = keys.iterator();
        Iterator<V> valueIterator = values.iterator();
        Map<K,V> map = new HashMap<>();

        while (keyIterator.hasNext() && valueIterator.hasNext()) {
            K key = keyIterator.next();
            V value = valueIterator.next();
            if (map.containsKey(key)) {
                throw new IllegalArgumentException("Duplicate key: " + key);
            }
            map.put(key, value);
        }

        if (keyIterator.hasNext() || valueIterator.hasNext()) {
            throw new IllegalArgumentException("Iterables have different numbers of elements");
        }

        return map;
    }
}
