public static String encodeXmlAttribute(String input) {
    String output = "";

    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        switch (c) {
            case '&':
                output += "&amp;";
                break;
            case '\"':
                output += "&quot;";
                break;
            case '\'':
                output += "&apos;";
                break;
            case '<':
                output += "&lt;";
                break;
            case '>':
                output += "&gt;";
                break;
            case ' ':
                output += "&#x20;";
                break;
            default:
                output += c;
        }
    }

    return output;
}
