import java.util.Comparator;
import java.util.SortedMap;
import java.util.TreeMap;

public class RangeOrdering<C extends Comparable<C>> implements Comparator<SortedMap<C, ?>> {

  @Override
  public int compare(SortedMap<C, ?> s1, SortedMap<C, ?> s2) {
    C s1Lower = s1.firstKey();
    C s2Lower = s2.firstKey();

    int cmp = s2Lower.compareTo(s1Lower);
    if (cmp != 0) {
      return cmp;
    } else {
      return s2.get(s2Lower).toString().compareTo(s1.get(s1Lower).toString());
    }
  }
}
