public static void reverseSubtraction(NDArray other, NDArray result) throws ShapeMismatchException {
    // Check input shapes
    if (!Arrays.equals(other.getShape(), result.getShape())) {
        throw new ShapeMismatchException("Input shapes do not match");
    }

    // Subtract values from 'other' from 'result', element-wise
    for (int i = 0; i < result.size(); i++) {
        double value = other.get(i) - result.get(i);
        result.set(value, i);
    }
}
