public Set<String> getLicenseEntities(List<String> licStrings){
   Set<String> entities = new HashSet<>();
   for(String licString : licStrings){
      Pattern pattern = Pattern.compile("(<entity>(.*?)<\\/entity>)");
      Matcher matcher = pattern.matcher(licString);
      while(matcher.find()){
         entities.add(matcher.group(2));
      }
   }
   return entities;
}
