public List<Selection> extractSelectedFiles(Intent data) {
    List<Selection> fileList = new ArrayList<>();
    if (data == null) return fileList;

    Uri uri = data.getData();
    if (uri == null) return fileList;

    ClipData clipData = data.getClipData();
    if (clipData == null) {
        fileList.add(new Selection(uri.getPath()));
    } else {
        for (int i = 0; i < clipData.getItemCount(); i++) {
            Uri clipUri = clipData.getItemAt(i).getUri();
            fileList.add(new Selection(clipUri.getPath()));
        }
    }

    return fileList;
}
