public Optional<RangeArgs> getRangeArgs(String loopExpression) {
    if(loopExpression.startsWith("range(") && loopExpression.endsWith(")")) {
        String[] parts = loopExpression.substring(6, loopExpression.length() - 1).split(",");
        int start = Integer.parseInt(parts[0].trim());
        int end = Integer.parseInt(parts[1].trim());
        int step = parts.length > 2 ? Integer.parseInt(parts[2].trim()) : 1;
        return Optional.of(new RangeArgs(start, end, step));
    } else {
        return Optional.empty();
    }
}
