public boolean mergeZipContents(File zipFile, Map<String, String> pMergedInfo) {
    boolean found = false;
    try (ZipFile zip = new ZipFile(zipFile)) {
        Enumeration<? extends ZipEntry> entries = zip.entries();
        while (entries.hasMoreElements()) {
            ZipEntry entry = entries.nextElement();
            if (entry.isDirectory()) {
                continue;
            }
            try (InputStream inputStream = zip.getInputStream(entry)) {
                ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
                byte[] buffer = new byte[4096];
                int bytesRead;
                while ((bytesRead = inputStream.read(buffer)) != -1) {
                    outputStream.write(buffer, 0, bytesRead);
                }
                String contents = outputStream.toString("UTF-8");
                outputStream.close();
                String existing = pMergedInfo.get(entry.getName());
                if (existing != null) {
                    if (!existing.equals(contents)) {
                        pMergedInfo.put(entry.getName(), existing + "\n" + contents);
                        found = true;
                    }
                } else {
                    pMergedInfo.put(entry.getName(), contents);
                    found = true;
                }
            }
        }
    } catch (IOException e) {
        return found;
    }
    return found;
}
