        loadRegionData();
        Region r = numericCodeMap.get(code);
        if ( r == null ) {  
            String pad = "";
            if ( code < 10 ) {
                pad = "00";
            } else if ( code < 100 ) {
                pad = "0";
            }
            String id = pad + Integer.toString(code);
            r = regionAliases.get(id);
        }
        if ( r == null ) {
            throw new IllegalArgumentException("Unknown region code: " + code);
        }
