public void parseMessages(XMLStreamReader xmlStreamReader, Schema schema) throws SAXException, IOException {
    Validator validator = schema.newValidator();
    while(xmlStreamReader.hasNext()) {
        if(xmlStreamReader.isStartElement()) {
            String elemName = xmlStreamReader.getLocalName();
            if(elemName.equals("message")) {
                String message = xmlStreamReader.getElementText();
                // do something with message
                try {
                    validator.validate(new StreamSource(new StringReader(message)));
                } catch(SAXException ex) {
                    // handle validation error
                } catch(IOException ex) {
                    // handle I/O error
                }
            }
        }
        xmlStreamReader.next();
    }
}
