public void setDeepCopySubjectMode(AuthenticationManager authenticationManager) {
    try {
        Class<?> authenticationManagerClass = authenticationManager.getClass();
        Method setAuthenticationTrees = authenticationManagerClass.getDeclaredMethod("setAuthenticationTrees", Map.class);
        setAuthenticationTrees.setAccessible(true);
        Field deepCopyField = authenticationManagerClass.getDeclaredField("deepCopySubjectMode");
        deepCopyField.setAccessible(true);
        Map<String, Boolean> authenticationTrees = (Map<String, Boolean>) setAuthenticationTrees.invoke(authenticationManager, new HashMap<>());
        authenticationTrees.forEach((name, value) -> {
            try {
                deepCopyField.setBoolean(value, true);
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        });
    } catch (Exception e) {
        throw new RuntimeException(e);
    }
}
