public ServiceRegistration createAndRegisterUserRegistryConfiguration(BundleContext bc) {
    SecurityManager securityManager = new SecurityManager();
    Realm realm = new TextConfigurationRealm();
    securityManager.setRealm(realm);
    Subject subject = new Subject.Builder(securityManager).buildSubject();
    ServiceRegistration registration = bc.registerService(UserRegistryConfiguration.class.getName(), new UserRegistryConfiguration(subject), null);
    return registration;
}
