public static int[] rangeArray(int[] arr, int start, int end) {
    if (start == 0 && end == arr.length - 1) {
        return arr;
    }
    int[] resultArray = new int[end - start + 1];
    int index = 0;
    for (int i = start; i <= end; i++) {
        resultArray[index] = arr[i];
        index++;
    }
    return resultArray;
}
