public void updateNamespaceAndDiskSpace(String path, long nsDelta, long dsDelta) throws QuotaExceededException, FileNotFound {
    File file = new File(path);
    if (!file.exists()) {
        throw new FileNotFound("File " + path + " not found");
    }
    long nsCount = nsDelta;
    long dsCount = dsDelta;
    File parent = file.getParentFile();
    while (parent != null) {
        try {
            updateQuota(parent, nsCount, dsCount);
        } catch (QuotaExceededException e) {
            throw new QuotaExceededException("Quota exceeded for path " + parent.getAbsolutePath());
        }
        nsCount += parent.list().length;
        dsCount += parent.getTotalSpace() - parent.getFreeSpace();
        parent = parent.getParentFile();
    }
}

private void updateQuota(File directory, long nsDelta, long dsDelta) throws QuotaExceededException {
    if (directory.isDirectory()) {
        long namespace = directory.list().length + nsDelta;
        long diskspace = directory.getUsableSpace() + dsDelta;
        if (namespace > MAX_NAMESPACE || diskspace > MAX_DISKSPACE) {
            throw new QuotaExceededException("Quota exceeded for directory " + directory.getAbsolutePath());
        }
    }
}
