public String getQueryString(Map<String, String> params, String encoding) throws UnsupportedEncodingException {
    StringBuilder result = new StringBuilder();
    if(params!=null && !params.isEmpty()) {
        result.append("?");
        for (Map.Entry<String, String> entry : params.entrySet()) {
            result.append(URLEncoder.encode(entry.getKey(), encoding));
            result.append("=");
            result.append(URLEncoder.encode(entry.getValue(), encoding));
            result.append("&");
        }
        result.deleteCharAt(result.length() - 1);
    }
    return result.toString();
}
