import com.github.javaparser.ast.Node;

public class JSDocCrawler {

    public Set<String> findNullNamesInJSDoc(Node node) {
        Set<String> nullNames = new HashSet<>();
        String jsDocComment = node.getComment().orElse(null);
        if (jsDocComment == null) {
            return nullNames;
        }
        Pattern pattern = Pattern.compile("\\*\\s*@(param|return)\\s+\\{\\s*\\??\\s*([^\\s]+)\\s*\\}");
        Matcher matcher = pattern.matcher(jsDocComment);
        while (matcher.find()) {
            String name = matcher.group(2);
            if (name.startsWith("?")) {
                nullNames.add(name.substring(1));
            }
        }
        return nullNames;
    }
}
