public static String snakeToCamelCase(String snakeCase) {
    if (!snakeCase.contains("_")) {
        return snakeCase;
    }
    StringBuilder camelCaseBuilder = new StringBuilder(snakeCase.length());
    boolean capitalizeNext = false;
    for (char c : snakeCase.toCharArray()) {
        if (c == '_') {
            capitalizeNext = true;
        } else if (capitalizeNext) {
            camelCaseBuilder.append(Character.toUpperCase(c));
            capitalizeNext = false;
        } else {
            camelCaseBuilder.append(Character.toLowerCase(c));
        }
    }
    return camelCaseBuilder.toString();
}
