public static double getBicubicInterpolationCoverageValue(double[][] values, double offsetX, double offsetY) {
    int i = (int) Math.floor(offsetX);
    int j = (int) Math.floor(offsetY);
    double u = offsetX - i;
    double v = offsetY - j;

    double[] arr = new double[4];
    for (int k = 0; k < 4; k++) {
        arr[k] = cubicInterpolate(values[k][j - 1], values[k][j], values[k][j + 1], values[k][j + 2], u);
    }
    return cubicInterpolate(arr[0], arr[1], arr[2], arr[3], v);
}

private static double cubicInterpolate(double v0, double v1, double v2, double v3, double x) {
    double P = (v3 - v2) - (v0 - v1);
    double Q = (v0 - v1) - P;
    double R = v2 - v0;
    double S = v1;
    return P * Math.pow(x, 3) + Q * Math.pow(x, 2) + R * x + S;
}
