public double[] normalizeSequence(String schema, double[] sequence) {
    double sum = 0.0;
    double mean = 0.0;
    double variance = 0.0;

    // Calculate sum
    for(double num : sequence) {
        sum += num;
    }

    // Calculate mean
    mean = sum / sequence.length;

    // Calculate variance
    for(double num : sequence) {
        variance += Math.pow(num - mean, 2);
    }
    variance = variance / sequence.length;

    // Normalize sequence
    for(int i=0; i<sequence.length; i++) {
        sequence[i] = (sequence[i] - mean) / Math.sqrt(variance);
    }

    return sequence;
}
