public static List<Triangle> drapeMultilinestringToTriangles(Geometry[] polygons, Geometry[] triangles, STRtree sTRtree) {
    List<LineString> lines = new ArrayList<>();
    for (Geometry geometry : polygons) {
        if (geometry instanceof MultiLineString) {
            lines.addAll(Arrays.asList(((MultiLineString) geometry).getLineStrings()));
        } else if (geometry instanceof LineString) {
            lines.add((LineString) geometry);
        }
    }

    List<Triangle> triList = new ArrayList<>();
    for (Geometry triangle : triangles) {
        StrTreeIntersectingEdgeVisitor visitor = new StrTreeIntersectingEdgeVisitor(triangle);
        sTRtree.query(triangle.getEnvelopeInternal(), visitor);
        if (visitor.getIntersections().isEmpty()) {
            triList.add(new Triangle(triangle));
            continue;
        }

        for (LineString line : lines) {
            for (int k = 0; k < line.getNumPoints() - 1; k++) {
                Coordinate a = line.getCoordinateN(k);
                Coordinate b = line.getCoordinateN(k + 1);
                LineSegment segment = new LineSegment(a, b);

                for (int i = 0; i < visitor.getIntersections().size(); i++) {
                    Coordinate intersection = visitor.getIntersections().get(i);
                    double frac = segment.lineRelativeTo(intersection);
                    if (frac >= 0 && frac < 1) {
                        Coordinate p = segment.pointAlong(frac);
                        if (triangle.contains(p)) {
                            triList.add(new Triangle(triangle.getCoordinateN(0), triangle.getCoordinateN(1), triangle.getCoordinateN(2), p));
                            break;
                        }
                    }
                }
            }
        }
    }

    return triList;
}
