public List<Neighbour> recoverNeighbours(MessageStore store) throws MessageStoreException {
    List<Neighbour> neighbours = new ArrayList<>();

    try {
        // Get all messages from the message store
        List<Message> messages = store.getAllMessages();

        // Loop through messages and retrieve neighbours
        for (Message message : messages) {
            if (message.getType() == MessageType.NEIGHBOUR) {
                Neighbour neighbour = (Neighbour) message.getData();
                neighbours.add(neighbour);
            }
        }
    } catch (MessageStoreException ex) {
        // If there was an error with the message store, throw an exception
        throw new MessageStoreException("Failed to recover Neighbours from the MessageStore.");
    }

    return neighbours;
}
