public Iterator<?> createIteratorWrapper(String metaTypeDescription, Object settings, Map<String, Object> knownTypes) {
    // Check for null inputs
    if(metaTypeDescription == null || settings == null) {
        throw new IllegalArgumentException("Meta type description and settings object must not be null");
    }

    if (isCollectionType(metaTypeDescription)) {
        Collection<?> collection = (Collection<?>) settings;
        if (collection.isEmpty()) {
            return null;
        } else {
            return new IteratorWrapper(collection.iterator());
        }
    } else if (isArrayType(metaTypeDescription)) {
        Object[] array = (Object[]) settings;
        if (array.length == 0) {
            return null;
        } else {
            return new IteratorWrapper(Arrays.asList(array).iterator());
        }
    } else if (isMapType(metaTypeDescription)) {
        Map<?, ?> map = (Map<?, ?>) settings;
        if (map.isEmpty()) {
            return null;
        } else {
            return new IteratorWrapper(map.entrySet().iterator());
        }
    } else if (knownTypes != null) {
        Object knownType = knownTypes.get(metaTypeDescription);
        if (knownType != null) {
            return createIteratorWrapper(convertToString(knownType), settings, null);
        }
    }
    return null;
}

private boolean isCollectionType(String metaTypeDescription) {
    return metaTypeDescription.equals("collection");
}

private boolean isArrayType(String metaTypeDescription) {
    return metaTypeDescription.endsWith("[]");
}

private boolean isMapType(String metaTypeDescription) {
    return metaTypeDescription.equals("map");
}

private String convertToString(Object knownType) {
    return knownType.toString();
}

class IteratorWrapper implements Iterator<Object> {
    private Iterator<?> originalIterator;

    public IteratorWrapper(Iterator<?> originalIterator) {
        this.originalIterator = originalIterator;
    }

    @Override
    public boolean hasNext() {
        return originalIterator.hasNext();
    }

    @Override
    public Object next() {
        return originalIterator.next();
    }

    // Unsupported operations should be handled here as well
}
