import java.io.IOException;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.jar.Attributes;
import java.util.jar.JarFile;
import java.util.jar.Manifest;

public class JarFileParser {

    public static void parseJarFiles() throws IOException, DuplicateJarsException {
        String classPath = System.getProperty("java.class.path");
        Map<String, List<String>> jarFileMap = new HashMap<>();
        for (String path : classPath.split(System.getProperty("path.separator"))) {
            if (path.endsWith(".jar")) {
                String name = getName(path);
                if (!jarFileMap.containsKey(name)) {
                    jarFileMap.put(name, new ArrayList<>());
                }
                jarFileMap.get(name).add(path);
            }
        }
        for (List<String> paths : jarFileMap.values()) {
            if (paths.size() > 1) {
                throw new DuplicateJarsException(paths);
            }
        }
        for (String path : classPath.split(System.getProperty("path.separator"))) {
            if (path.endsWith(".jar")) {
                try (JarFile jarFile = new JarFile(path)) {
                    Manifest manifest = jarFile.getManifest();
                    if (manifest != null) {
                        Attributes attributes = manifest.getMainAttributes();
                        String classPathAttr = attributes.getValue("Class-Path");
                        if (classPathAttr != null) {
                            for (String name : classPathAttr.split(" ")) {
                                if (!name.isEmpty()) {
                                    String jarFileName = getName(name);
                                    List<String> paths = jarFileMap.get(jarFileName);
                                    if (paths != null) {
                                        if (paths.size() > 1) {
                                            throw new DuplicateJarsException(paths);
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    private static String getName(String path) {
        int i = path.lastIndexOf("/");
        if (i >= 0) {
            return path.substring(i + 1);
        }
        i = path.lastIndexOf("\\");
        if (i >= 0) {
            return path.substring(i + 1);
        }
        return path;
    }
}

class DuplicateJarsException extends Exception {
    DuplicateJarsException(List<String> jars) {
        super("Duplicate jars found: " + jars);
    }
}
