public static Annotation getTypeQualifierAnnotation(String methodDesc, int param, String tqv) {
    Method method;
    try {
        // Get the method description and parse it into a Method object
        method = Type.getMethod(methodDesc);
    } catch (IllegalArgumentException e) {
        throw new RuntimeException("Couldn't parse method description: " + methodDesc, e);
    }

    // Get the parameter at the specified index
    Type[] argumentTypes = method.getArgumentTypes();
    if (param >= argumentTypes.length) {
        throw new IllegalArgumentException("Invalid parameter index: " + param);
    }

    // Get the annotations for the parameter
    Annotation[][] parameterAnnotations = method.getParameterAnnotations();
    if (parameterAnnotations.length <= param) {
        return null;
    }

    // Find the TypeQualifierAnnotation with the specified value
    for (Annotation annotation : parameterAnnotations[param]) {
        if (annotation.annotationType().getSimpleName().equals("TypeQualifierAnnotation")
                && annotation.toString().contains(tqv)) {
            return annotation;
        }
    }
    return null;
}
