public void addSourceCode(String sourceCode, String other) {
    // find the index of 'other'
    int index = sourceCodeList.indexOf(other);

    // if 'other' is not found, add the source code at the end of the list
    if (index == -1) {
        sourceCodeList.add(sourceCode);
    }
    else {
        // otherwise, add the source code after 'other'
        sourceCodeList.add(index + 1, sourceCode);
    }
}
