public static BufferedImage sobelBumpMap(BufferedImage input) {
    int width = input.getWidth();
    int height = input.getHeight();

    BufferedImage output = new BufferedImage(width, height, BufferedImage.TYPE_3BYTE_BGR);

    int[][] kernelX = {
        {-1, 0, 1},
        {-2, 0, 2},
        {-1, 0, 1}
    };

    int[][] kernelY = {
        {-1, -2, -1},
        {0, 0, 0},
        {1, 2, 1}
    };

    for (int x = 1; x < width - 1; x++) {
        for (int y = 1; y < height - 1; y++) {
            int pixelX = (
                kernelX[0][0] * new Color(input.getRGB(x - 1, y - 1)).getRed() +
                kernelX[0][1] * new Color(input.getRGB(x, y - 1)).getRed() +
                kernelX[0][2] * new Color(input.getRGB(x + 1, y - 1)).getRed() +
                kernelX[1][0] * new Color(input.getRGB(x - 1, y)).getRed() +
                kernelX[1][1] * new Color(input.getRGB(x, y)).getRed() +
                kernelX[1][2] * new Color(input.getRGB(x + 1, y)).getRed() +
                kernelX[2][0] * new Color(input.getRGB(x - 1, y + 1)).getRed() +
                kernelX[2][1] * new Color(input.getRGB(x, y + 1)).getRed() +
                kernelX[2][2] * new Color(input.getRGB(x + 1, y + 1)).getRed()
            );

            int pixelY = (
                kernelY[0][0] * new Color(input.getRGB(x - 1, y - 1)).getRed() +
                kernelY[0][1] * new Color(input.getRGB(x, y - 1)).getRed() +
                kernelY[0][2] * new Color(input.getRGB(x + 1, y - 1)).getRed() +
                kernelY[1][0] * new Color(input.getRGB(x - 1, y)).getRed() +
                kernelY[1][1] * new Color(input.getRGB(x, y)).getRed() +
                kernelY[1][2] * new Color(input.getRGB(x + 1, y)).getRed() +
                kernelY[2][0] * new Color(input.getRGB(x - 1, y + 1)).getRed() +
                kernelY[2][1] * new Color(input.getRGB(x, y + 1)).getRed() +
                kernelY[2][2] * new Color(input.getRGB(x + 1, y + 1)).getRed()
            );

            int pixel = (int) Math.sqrt(pixelX * pixelX + pixelY * pixelY);

            output.setRGB(x, y, new Color(pixel, pixel, pixel).getRGB());
        }
    }

    return output;
}
