public void storeIzouAesKey(SecretKey key) throws Exception {
    KeyStore keyStore = KeyStore.getInstance("JCEKS");
    keyStore.load(null, null);
    char[] password = "myKeystorePassword".toCharArray();
    SecretKeyEntry entry = new SecretKeyEntry(key);
    PasswordProtection protection = new PasswordProtection(password);
    keyStore.setEntry("izouAesKey", entry, protection);
    keyStore.store(new FileOutputStream("myKeystore.jceks"), password);
}
