private static class VertexMapFunction<VD, UD> implements Function<Vertex<VD>, UD>, Serializable {
    private static final long serialVersionUID = 1L;

    private MapFunction<Vertex<VD>, UD> mapFunc;

    private VertexMapFunction(MapFunction<Vertex<VD>, UD> mapFunc) {
        this.mapFunc = mapFunc;
    }

    @Override
    public UD apply(Vertex<VD> v) {
        return mapFunc.call(v);
    }
}
