public int execute()
    {
        int executed = 0;
        final long now = now();
        for (Entry<Timer, Long> entry : entries()) {
            final Timer timer = entry.getKey();
            final Long expiration = entry.getValue();

            if (!timer.alive) {

                timers.remove(expiration, timer);
                continue;
            }

            if (expiration - now > 0) {
                break;
            }
            insert(timer);
            timer.handler.time(timer.args);
            ++executed;
        }
        return executed;
