public int putBytes(byte[] bytes, int position, int length) {
    if(position < 0 || length <= 0 || bytes.length == 0) {
        return 0;
    }
    int count = 0;
    for(int i = position; i < bytes.length && i < position + length; i++) {
        if(buffer.remaining() == 0) {
            return count;
        }
        buffer.put(bytes[i]);
        count++;
    }
    return count;
}
