public void exportData() {

  // Get the data to export from the backend
  List<MyData> dataToExport = backendService.getDataToExport();

  // Create a CSV file to store the exported data
  File csvFile = new File("exported_data.csv");

  try (PrintWriter writer = new PrintWriter(csvFile)) {

    // Write the headers of the CSV file
    writer.println("Column 1,Column 2,Column 3");

    // Write each row of data to the CSV file
    for (MyData data : dataToExport) {
      writer.println(data.getColumn1() + "," + data.getColumn2() + "," + data.getColumn3());
    }

  } catch (FileNotFoundException e) {
    // Handle the exception if the file cannot be created
    e.printStackTrace();
  }

  // Send the CSV file to the frontend
  frontendService.sendDataToClient(csvFile);
}
