public GeometryCollection parseValueGetterToGeometryCollection(ValueGetter data, int srid) throws SQLException, ParseException {
    GeometryFactory geometryFactory = new GeometryFactory(new PrecisionModel(), srid);
    // The byte order (1 or 0) is determined by the first byte of the first geometry
    byte[] bytes = data.getBytes();
    ByteBuffer byteBuffer = ByteBuffer.wrap(bytes);
    byte order = byteBuffer.get();
    // The first four bytes of the input represent the type of the WKB object
    int typeInt = byteBuffer.getInt();
    // Convert the WKB object to a JTS GeometryCollection
    WKBReader wkbReader = new WKBReader(geometryFactory);
    return (GeometryCollection) wkbReader.read(new InputStreamInByteBuffer(byteBuffer), order, new Integer(typeInt).byteValue());
}
