public static double calculateEuclideanDistance(double[] series1, double[] series2) throws Exception {
    if (series1.length != series2.length) {
        throw new Exception("Series lengths must be equal.");
    }

    double dist = 0;

    for (int i = 0; i < series1.length; i++) {
        dist += Math.pow(series1[i] - series2[i], 2);
    }

    return Math.sqrt(dist);
}
