import java.net.URI;
import java.net.URISyntaxException;
import java.security.InvalidKeyException;
import java.security.NoSuchAlgorithmException;
import java.time.LocalDateTime;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.Base64;
import java.util.HashMap;
import java.util.Map;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;

public class V4SignedURLGenerator {

  public static URI getSignedURL(String endpoint, String region, String accessKey, String secretKey, String bucket, String objectKey) throws URISyntaxException, InvalidKeyException, NoSuchAlgorithmException {
    String service = "s3";
    String algorithm = "AWS4-HMAC-SHA256";
    String datetime = LocalDateTime.now(ZoneId.of("UTC")).format(DateTimeFormatter.ofPattern("yyyyMMdd'T'HHmmss'Z'"));
    String date = datetime.substring(0, 8);
    String credentialScope = date + "/" + region + "/" + service + "/aws4_request";
    String canonicalHeaders = "host:" + endpoint + "\n" + "x-amz-content-sha256:UNSIGNED-PAYLOAD\n" + "x-amz-date:" + datetime + "\n";
    String signedHeaders = "host;x-amz-content-sha256;x-amz-date";
    String payloadHash = "UNSIGNED-PAYLOAD";

    String canonicalRequest =
        "GET\n" +
        "/" + objectKey + "\n" +
        "\n" +
        canonicalHeaders + "\n" +
        signedHeaders + "\n" +
        payloadHash;

    String stringToSign =
        algorithm + "\n" +
        datetime + "\n" +
        credentialScope + "\n" +
        hash(canonicalRequest);

    String signingKey = getSignatureKey(secretKey, date, region, service);
    String signature = hmacSha256(signingKey, stringToSign);

    String authorizationHeader =
        algorithm + " " +
        "Credential=" + accessKey + "/" + credentialScope + ", " +
        "SignedHeaders=" + signedHeaders + ", " +
        "Signature=" + signature;

    String url =
        "https://" + endpoint + "/" + objectKey + "?" + "X-Amz-Algorithm=AWS4-HMAC-SHA256"
        + "&X-Amz-Credential=" + accessKey + "/" + credentialScope
        + "&X-Amz-Date=" + datetime
        + "&X-Amz-Expires=604800"
        + "&X-Amz-SignedHeaders=" + signedHeaders
        + "&X-Amz-Signature=" + signature;

    return new URI(url);
  }

  private static String hmacSha256(String key, String data) throws NoSuchAlgorithmException, InvalidKeyException {
    Mac mac = Mac.getInstance("HmacSHA256");
    mac.init(new SecretKeySpec(key.getBytes(), "HmacSHA256"));
    byte[] result = mac.doFinal(data.getBytes());
    return Base64.getEncoder().encodeToString(result);
  }

  private static String hash(String data) throws NoSuchAlgorithmException {
    byte[] byteData = data.getBytes();
    MessageDigest md = MessageDigest.getInstance("SHA-256");
    byte[] digest = md.digest(byteData);
    return bytesToHex(digest);
  }

  private static String getSignatureKey(String key, String date, String region, String service) throws NoSuchAlgorithmException, InvalidKeyException {
    byte[] kSecret = ("AWS4" + key).getBytes();
    byte[] kDate = hmacSha256(date, new String(kSecret)).getBytes();
    byte[] kRegion = hmacSha256(region, new String(kDate)).getBytes();
    byte[] kService = hmacSha256(service, new String(kRegion)).getBytes();
    byte[] kSigning = hmacSha256("aws4_request", new String(kService)).getBytes();
    return new String(kSigning);
  }

  private static String bytesToHex(byte[] bytes) {
    StringBuilder sb = new StringBuilder();
    for(byte b : bytes) {
      sb.append(String.format("%02x", b));
    }
    return sb.toString();
  }
}
