import java.io.File;
import java.util.ArrayList;
import java.util.List;

public class FileSearch {
    public List<File> findFiles(File dir, String filenameToSearch) {
        List<File> result = new ArrayList<>();

        if (!dir.isDirectory()) {
            return result;
        }

        File[] files = dir.listFiles();

        if (files != null) {
            for (File file : files) {
                if (file.isDirectory()) {
                    result.addAll(findFiles(file, filenameToSearch));
                } else if (match(file.getName(), filenameToSearch)) {
                    result.add(file);
                }
            }
        }

        return result;
    }

    private boolean match(String filename, String pattern) {
        String regex = pattern.replaceAll("\\*", ".*").replaceAll("\\?", ".");
        return filename.matches(regex);
    }
}
