public static double[] calculateMinMax(double[][] coordinates) {
    double xMin = coordinates[0][0];
    double xMax = coordinates[0][0];
    double yMin = coordinates[0][1];
    double yMax = coordinates[0][1];
    double zMin = coordinates[0][2];
    double zMax = coordinates[0][2];

    for (double[] coordinate : coordinates) {
        if (coordinate[0] < xMin) {
            xMin = coordinate[0];
        }
        if (coordinate[0] > xMax) {
            xMax = coordinate[0];
        }
        if (coordinate[1] < yMin) {
            yMin = coordinate[1];
        }
        if (coordinate[1] > yMax) {
            yMax = coordinate[1];
        }
        if (coordinate[2] < zMin) {
            zMin = coordinate[2];
        }
        if (coordinate[2] > zMax) {
            zMax = coordinate[2];
        }
    }

    return new double[] {xMin, xMax, yMin, yMax, zMin, zMax};
}
