	public static String getFirstFreeBusStopName(BusNetwork busNetwork) {
		if (busNetwork == null) {
			return null;
		}
		int nb = busNetwork.getBusStopCount();
		String name;
		do {
			++nb;
			name = Locale.getString("NAME_TEMPLATE", Integer.toString(nb));  
		}
		while (busNetwork.getBusStop(name) != null);
		return name;
