public List<Object> removeValuesFromArray(Object[] values, boolean ifMatch) {
    List<Object> removedEntries = new ArrayList<>();
    int j = 0;
    for (int i = 0; i < this.array.length; i++) {
        if (ifMatch == Arrays.asList(values).contains(this.array[i])) {
            removedEntries.add(this.array[i]);
        } else {
            this.array[j++] = this.array[i];
        }
    }
    this.array = Arrays.copyOf(this.array, j);
    return removedEntries;
}
