public void updateBidirectionalRelationship(Object entity, Object existingEntity) {
    if (entity instanceof Entity && existingEntity instanceof Entity) {
        Entity e1 = (Entity) entity;
        Entity e2 = (Entity) existingEntity;
        if (e1.getRelationship() != null && e2.getRelationship() != null) {
            if (e1.getRelationship().equals(e2) && !e2.getRelationship().equals(e1)) {
                e2.setRelationship(e1);
            } else if (e2.getRelationship().equals(e1) && !e1.getRelationship().equals(e2)) {
                e1.setRelationship(e2);
            }
        }
    }
}
