public List<Properties> loadJobConfigsFromFiles(Path path, Configuration sysProps) {
        File[] files = new File(path.toString()).listFiles();
        List<Properties> jobConfigsList = new ArrayList<>();
        if (files != null) {
          for (File file : files) {
              if (!file.isDirectory()) {
                  try (InputStream inputStream = new FileInputStream(file)) {
                      Properties properties = new Properties();
                      properties.load(inputStream);
                      jobConfigsList.add(properties);
                  } catch (IOException ex) {
                      // handle exception
                  }
              }
          }
        }
        return jobConfigsList;
    }
