public void forwardEvent(Event event) {
   // iterate over all handler methods
   for(Handler handler : handlers) {
      // check if handler can handle the event
      if(handler.canHandle(event)) {
         // if yes, deliver the event to the handler
         handler.handle(event);
         return;
      }
   }
   // if no handler method was found, the event gets silently ignored
}
