public void processOccupantArrival(Occupant occupant, Room room) {
    // Check if the room is available
    if (!room.isAvailable()) {
        System.out.println("Sorry, the room is already occupied.");
        return;
    }

    // Assign the room to the occupant
    room.setOccupant(occupant);

    // Update the room status
    room.setAvailable(false);

    // Print a message to confirm the assignment
    System.out.println(occupant.getName() + " has been assigned to room " + room.getNumber() + ".");
}
