public static double[][] sparseMatrixMult(double[][] A, double[][] B) {
    if(A.length == 0 || A[0].length != B.length || B.length == 0 || B[0].length == 0)
        return null;
    int n = A.length, m = B[0].length;
    double[][] res = new double[n][m];
    int[] col = new int[B.length+1], pos = new int[B.length+1];
    for(int i=0;i<B.length;i++) {
        for(int p=0;p<B[i].length;p++) {
            if(B[i][p] != 0) {
                res[pos[i+1]][p] += B[i][p];
            }
        }
        col[i+1] = col[i] + 1;
        pos[i+1] = pos[i] + col[i];
    }
    for(int i=0;i<A.length;i++) {
        for(int j=0;j<B.length;j++) {
            if(A[i][j] != 0) {
                for(int p=col[j];p<col[j+1];p++) {
                    res[i][pos[p]] += A[i][j]*B[j][p];
                }
            }
        }
    }
    return res;
}
