public static String sanitizeString(String input) {
   String sanitized = input.replaceAll("\\\\", "\\\\\\\\"); //escape backslashes
   sanitized = sanitized.replaceAll("\\(", "\\\\("); // escape parenthesis
   sanitized = sanitized.replaceAll("\\)", "\\\\)"); 
   sanitized = sanitized.replaceAll("\\[", "\\\\["); // escape brackets
   sanitized = sanitized.replaceAll("\\]", "\\\\]"); 
   sanitized = sanitized.replaceAll("\\{", "\\\\{"); // escape curly braces
   sanitized = sanitized.replaceAll("\\}", "\\\\}"); 
   sanitized = sanitized.replaceAll("\\^", "\\\\^"); // escape caret
   sanitized = sanitized.replaceAll("\\$", "\\\\$"); // escape dollar sign
   sanitized = sanitized.replaceAll("\\.", "\\\\."); // escape period
   sanitized = sanitized.replaceAll("\\|", "\\\\|"); // escape pipe
   sanitized = sanitized.replaceAll("\\+", "\\\\+"); // escape plus sign
   sanitized = sanitized.replaceAll("\\?", "\\\\?"); // escape question mark
   sanitized = sanitized.replaceAll("(?<!\\\\)\\*", "\\\\E.*\\\\Q"); // replace unescaped wildcards
   sanitized = "\\Q" + sanitized + "\\E"; // wrap in \Q and \E to match exact string
   return sanitized;
}
