public static boolean isInSection(ZonedDateTime section, ZonedDateTime dateTime) {
    DayOfWeek dayOfWeek = dateTime.getDayOfWeek();
    LocalTime time = dateTime.toLocalTime();
    LocalTime startTime = section.toLocalTime();
    LocalTime endTime = section.plus(section.getOffset()).toLocalTime();

    return dayOfWeek.equals(section.getDayOfWeek()) && !time.isBefore(startTime) && !time.isAfter(endTime);
}
