import java.util.jar.JarFile;
import java.util.jar.Manifest;

public class ManifestReader {

    public static void main(String[] args) throws IOException {

        String jarFilePath = "/path/to/your.jar";

        Manifest manifest = getManifest(jarFilePath);

        Attributes mainAttributes = manifest.getMainAttributes();

        String title = mainAttributes.getValue("Title");
        String createdBy = mainAttributes.getValue("Created-By");
        String version = mainAttributes.getValue("Version");

        System.out.println("Title: " + title);
        System.out.println("Created By: " + createdBy);
        System.out.println("Version: " + version);
    }

    public static Manifest getManifest(String jarFilePath) throws IOException {
        JarFile jar = new JarFile(jarFilePath);
        return jar.getManifest();
    }
}
