public File unpackLibrary(String shortName) {
    String libraryName = "lib" + shortName + ".so";
    InputStream stream = getClass().getResourceAsStream("/libs/" + libraryName);
    File tempDir = createTempDirectory();
    File libFile = new File(tempDir, libraryName);
    try {
        Files.copy(stream, libFile.toPath(), StandardCopyOption.REPLACE_EXISTING);
    } catch (IOException e) {
        throw new UncheckedIOException("Failed to write library file to temp directory", e);
    }
    return libFile;
}

private File createTempDirectory() {
    try {
        return Files.createTempDirectory("tempDir").toFile();
    } catch (IOException e) {
        throw new RuntimeException("Failed to create temp directory");
    }
}
