public void cacheAuthorizationInfo(String apiKey, AuthorizationInfo authInfo) {
    if(authInfo != null) {
        // Cache authorization info by ID if possible
        String authInfoId = authInfo.getId();
        if(authInfoId != null && !authInfoId.isEmpty()) {
            Map<String, AuthorizationInfo> authInfoById = getAuthorizationCacheById(apiKey);
            if(authInfoById != null && !authInfoById.containsKey(authInfoId)) {
                authInfoById.put(authInfoId, authInfo);
            }
        }
    }
}
