public static <F> boolean replaceSubscriptionIfNotCancelled(AtomicReferenceFieldUpdater<F, Subscription> field, F instance, Subscription s) {
    Subscription currentSubscription = field.get(instance);
    if (currentSubscription == cancelledSubscription()) {
        return false;
    } else {
        return field.compareAndSet(instance, currentSubscription, s);
    }
}
