public void longClickViewForSpecifiedTime(View view, int time) {
    long downTime = SystemClock.uptimeMillis();
    long eventTime = SystemClock.uptimeMillis() + time;
    MotionEvent motionEvent = MotionEvent.obtain(downTime, eventTime, MotionEvent.ACTION_DOWN, view.getX(), view.getY(), 0);
    view.onTouchEvent(motionEvent);
    motionEvent = MotionEvent.obtain(downTime, eventTime, MotionEvent.ACTION_UP, view.getX(), view.getY(), 0);
    view.onTouchEvent(motionEvent);
}
