public void writeJsDocumentation(String methodComment, Writer writer) throws IOException {
    StringBuilder jsComment = new StringBuilder();

    // check if method comment is not empty
    if (!methodComment.isEmpty()) {
        // remove javadoc delimiters
        methodComment = methodComment.replaceAll("/\\*\\*", "").replaceAll("\\*/", "");

        // split method comment by line
        String[] lines = methodComment.split("\\r?\\n");

        // loop through lines and format as js comment
        for (String line : lines) {
            jsComment.append("// ").append(line.trim()).append("\n");
        }
    }

    // write js comment to writer
    writer.write(jsComment.toString());
}
