public static HttpResponse fetchHttpResponse(String target) throws StageException {
    try {
        URL url = new URL(target);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");
        connection.connect();
        int responseCode = connection.getResponseCode();
        if (responseCode == HttpURLConnection.HTTP_OK) {
            BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
            StringBuilder response = new StringBuilder();
            String inputLine;
            while ((inputLine = in.readLine()) != null) {
                response.append(inputLine);
            }
            in.close();
            return new HttpResponse(responseCode, response.toString());
        } else {
            throw new StageException("HTTP request returned " + responseCode);
        }
    } catch (MalformedURLException e) {
        throw new StageException("Invalid URL: " + target, e);
    } catch (IOException e) {
        throw new StageException("Error connecting to the server: " + target, e);
    }
}
