public void updateBindingQueue(Queue<Binding> bindingQueue, Set<Node> dependentNodes) {
    while (!bindingQueue.isEmpty()) {
        Binding binding = bindingQueue.poll();
        double prevPosition = binding.getPosition();
        binding.iteratePosition();
        if (binding.getPosition() != prevPosition) {
            dependentNodes.addAll(binding.getDependentNodes());
        }
    }
    for (Node dependentNode : dependentNodes) {
        updateBindingQueue(dependentNode.getBindingQueue(), dependentNodes);
    }
}
