public void validateClusters(List<Cluster> clusterList) {
    Iterator<Cluster> iterator = clusterList.iterator();
    while (iterator.hasNext()) {
        Cluster cluster = iterator.next();
        if (cluster.isEmpty()) {
            iterator.remove();
            continue;
        }
        if (clusterList.indexOf(cluster) != cluster.getId()) {
            cluster.setId(clusterList.indexOf(cluster));
        }
    }
}
