private static final int ARG_NAME_NOT_NUMBER = -1;
	private static final int ARG_NAME_NOT_VALID = -2;

	private static int validateArgumentNameOrNumber(String nameOrNumber) {
		if (nameOrNumber == null || nameOrNumber.isEmpty()) {
			return ARG_NAME_NOT_VALID;
		}
		boolean isNumber = true;
		for (char c : nameOrNumber.toCharArray()) {
			if (!Character.isDigit(c)) {
				isNumber = false;
				break;
			}
		}
		if (isNumber) {
			return Integer.parseInt(nameOrNumber);
		}
		boolean isPatternIdentifer = true;
		for (char c : nameOrNumber.toCharArray()) {
			if (!Character.isDigit(c) && !Character.isLetter(c) && c != '_' && c != '$') {
				isPatternIdentifer = false;
				break;
			}
		}
		if (isPatternIdentifer) {
			return ARG_NAME_NOT_NUMBER;
		}
		return ARG_NAME_NOT_VALID;
	}
