public boolean isTokenMatch(String input) {
    // Check if the input string contains the token 'CASE', 'BEGIN' or 'END'
    if (input.matches(".*\\b(CASE|BEGIN|END)\\b.*")) {
        // Check if the matched token is not embedded in an identifier
        if (!input.matches(".*\\w+(CASE|BEGIN|END)\\w+.*")) {
            // Check if the token is followed by operators with or without whitespaces
            if (input.matches(".*(CASE|BEGIN|END)\\s*\\W.*")) {
                return true;
            }
        }
    }
    return false;
}
