public void setLogFilename(String filename) {
    if (filename == null || filename.isEmpty()) {
        // If no filename is set or a null filename passed, then requests are logged to System.err.
        System.setProperty("org.eclipse.jetty.util.log.stderr", "true");
        return;
    }

    if (filename.contains("yyyy_mm_dd")) {
        // If the filename contains the string "yyyy_mm_dd", then a RolloverFileOutputStream is used and the
        // log is rolled over nightly and aged according setRetainDays.
        RolloverFileOutputStream outputStream = new RolloverFileOutputStream(filename, true, 30, TimeZone.getDefault());
        NCSARequestLog requestLog = new NCSARequestLog(outputStream);
        requestLog.setRetainDays(30);
        this.server.setRequestLog(requestLog);
    } else {
        // Set the log to the file specified by filename
        NCSARequestLog requestLog = new NCSARequestLog(filename);
        requestLog.setRetainDays(30);
        this.server.setRequestLog(requestLog);
    }
}
