public HttpEntity getAtomFeedContent(Map<String, String> namespaceDictionary, Map<String, String> feed) {
    DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
    DocumentBuilder builder;

    try {
        builder = factory.newDocumentBuilder();
        Document document = builder.newDocument();

        Element root = document.createElement("feed");
        for (Map.Entry<String, String> entry : namespaceDictionary.entrySet()) {
            root.setAttribute("xmlns:" + entry.getKey(), entry.getValue());
        }

        for (Map.Entry<String, String> entry : feed.entrySet()) {
            Element element = document.createElement(entry.getKey());
            element.setTextContent(entry.getValue());
            root.appendChild(element);
        }

        document.appendChild(root);
        TransformerFactory transformerFactory = TransformerFactory.newInstance();
        Transformer transformer = transformerFactory.newTransformer();
        DOMSource source = new DOMSource(document);
        StringWriter writer = new StringWriter();
        StreamResult result = new StreamResult(writer);
        transformer.transform(source, result);
        String content = writer.toString();
        return new ByteArrayEntity(content.getBytes("UTF-8"));
    } catch (Exception e) {
        e.printStackTrace();
        return null;
    }
}
