private void buildMapsFromIntersection(Map<String, String> ordered_intersection) {
    current_values.clear();
    meta.clear();

    for(Map.Entry<String, String> entry : ordered_intersection.entrySet()) {
        String[] parts = entry.getKey().split(DELIMITER, 2);

        if(parts.length == 2) {
            String meta_key = parts[0];

            if(!meta.containsKey(meta_key)) {
                meta.put(meta_key, new ArrayList<>());
            }

            List<String> meta_list = meta.get(meta_key);
            meta_list.add(parts[1]);
        }

        current_values.put(entry.getKey(), entry.getValue());
    }
}
