         for (AnnotationType atv : AnnotationType.values()) {
            writer.beginObject();
            writer.property("name", atv.name());
            writer.property("type", atv.type());
            writer.property("parent", atv.getParent().name());
            writer.property("tagType", atv.getTagAttribute().name());
