public Expression buildCustomExpression() {
    Operator customOperator1 = new Operator("+", 2, true) {
        @Override
        public double apply(double... values) {
            return values[0] + values[1];
        }
    };
    Operator customOperator2 = new Operator("-", 2, true) {
        @Override
        public double apply(double... values) {
            return values[0] - values[1];
        }
    };
    Function customFunction1 = new Function("sin", 1) {
        @Override
        public double apply(double... values) {
            return Math.sin(values[0]);
        }
    };
    Function customFunction2 = new Function("cos", 1) {
        @Override
        public double apply(double... values) {
            return Math.cos(values[0]);
        }
    };
    Expression expression = new Expression();
    expression.addOperator(customOperator1);
    expression.addOperator(customOperator2);
    expression.addFunction(customFunction1);
    expression.addFunction(customFunction2);
    return expression;
}
