public String extractToken(RequestContext context) {
    String token = null;
    // Check headers for token
    List<String> headers = context.getRequest().getHeaders().get("Authorization");
    if (headers != null && !headers.isEmpty()) {
        String header = headers.get(0);
        if (header != null && header.startsWith("Bearer")) {
            token = header.substring(7).trim();
        }
    }
    // Check form body for token
    if (token == null && context.getRequest().getFormParams() != null) {
        MultivaluedMap<String, String> formParams = context.getRequest().getFormParams();
        if (formParams.containsKey("token")) {
            token = formParams.getFirst("token");
        }
    }
    return token;
}
