public void load(String _sql) throws EFapsException {
    try (final Connection con = Context.getConnection();
         final Statement stmt = con.createStatement();
         final ResultSet rs = stmt.executeQuery(_sql)) {
        if (rs.next()) {
            setId(rs.getLong(1));
            final long parentId = rs.getLong(2);
            if (parentId > 0) {
                getParent().setId(parentId);
                getParent().initialize();
            }
            cacheMethods();
        }
    } catch (final SQLException e) {
        throw new EFapsException(getClass(), "load", e);
    }
}
