public List<Dashboard> getDashboardsWithCollectorItems(List<CollectorItem> collectorItems, String collectorType) {
    List<Dashboard> dashboards = new ArrayList<>();
    for (Dashboard dashboard : dashboardRepository.findAll()) {
        List<Component> components = dashboard.getComponents();
        for (Component component : components) {
            for (CollectorItem item : component.getCollectorItems()) {
                if (item.getCollector().equals(collectorType) && collectorItems.contains(item)) {
                    dashboards.add(dashboard);
                    break;
                }
            }
        }
    }
    return dashboards;
}
