        } else if (key.equalsIgnoreCase(":scheme")) {
            containsScheme = true;
        } else if (key.equalsIgnoreCase(":path")) {
            containsPath = true;
        } else if (key.equalsIgnoreCase(":authority") && headers.get(":method").equalsIgnoreCase("CONNECT")) {
            return true;
        }
    }

    return containsMethod && containsScheme && containsPath;
}
