public boolean compareMethodDeclarations(Method m1, Method m2) {
    if (m1.getName().equals(m2.getName())) { // check if the method names are the same
        if (m1.getReturnType().equals(m2.getReturnType())) { // check if the return types are the same
            Class<?>[] params1 = m1.getParameterTypes();
            Class<?>[] params2 = m2.getParameterTypes();
            if (params1.length == params2.length) { // check if the number of parameters is the same
                for (int i = 0; i < params1.length; i++) {
                    if (!params1[i].equals(params2[i])) { // check if the parameter types are the same
                        return false;
                    }
                }
                return true;
            }
        }
    }
    return false;
}
