public Set<Class<?>> generateSubClassMapping(Class<?>[] classes, Configuration configuration) {
    Set<Class<?>> objectSubClasses = new HashSet<>();
    for (Class<?> clazz : classes) {
        if (clazz.getSuperclass() == Object.class) {
            Set<Class<?>> subClasses = new HashSet<>();
            for (Class<?> subClass : classes) {
                if (subClass.getSuperclass() == clazz) {
                    subClasses.add(subClass);
                }
            }
            objectSubClasses.add(clazz);
            objectSubClasses.addAll(subClasses);
            generateSubClassLists(subClasses, classes);
        }
    }
    return objectSubClasses;
}

private void generateSubClassLists(Set<Class<?>> subClasses, Class<?>[] classes) {
    for (Class<?> clazz : subClasses) {
        Set<Class<?>> subClassesOfSubClass = new HashSet<>();
        for (Class<?> subClass : classes) {
            if (subClass.getSuperclass() == clazz) {
                subClassesOfSubClass.add(subClass);
            }
        }
        if (!subClassesOfSubClass.isEmpty()) {
            subClasses.add(clazz);
            subClasses.addAll(subClassesOfSubClass);
            generateSubClassLists(subClassesOfSubClass, classes);
        }
    }
}
