public static String approximateZone(String host) {
    if (host == null || host.isEmpty()) {
        return null;
    }
    int dotIndex = host.indexOf(".");
    if (dotIndex == -1 || dotIndex == host.length() - 1) {
        return null;
    }
    return host.substring(dotIndex + 1);
}
