public void modifyNode(Element element, NodeStack nodeStack) {
    String correctNamespace = "http://example.com/correctnamespace";
    String elementNamespace = element.getNamespaceURI();
    if (!correctNamespace.equals(elementNamespace)) {
        throw new IllegalArgumentException("Element is not in the correct namespace.");
    }
    String elementName = element.getLocalName();
    if ("completed".equals(elementName)) {
        nodeStack.pop();
    } else {
        String propertyName = element.getAttribute("name");
        String propertyValue = element.getAttribute("value");
        nodeStack.peek().addProperty(propertyName, propertyValue);
    }
}
