public boolean deleteDatabase(String file) {
   File databaseFolder = new File(file).getParentFile();
   if (databaseFolder.exists() && databaseFolder.isDirectory()) {
      File[] files = databaseFolder.listFiles();
      for (File dbFile : files) {
         if (!dbFile.delete()) {
            return false;
         }
      }
      return databaseFolder.delete();
   } else {
      return false;
   }
}
