import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.util.Properties;

public class ConfigFileReader {
    public Properties getProperties() throws IOException {
        Properties properties = new Properties();
        InputStream inputStream = null;
        try {
            String configLocation = System.getProperty("mdw.config.location");
            if (configLocation != null) {
                File configFile = new File(configLocation);
                if (configFile.exists()) {
                    inputStream = new FileInputStream(configFile);
                }
            }
            if (inputStream == null) {
                String fileName = "fully_qualified_file_name";
                File configFile = new File(fileName);
                if (configFile.exists()) {
                    inputStream = new FileInputStream(configFile);
                }
            }
            if (inputStream == null) {
                String etcDir = System.getProperty("user.dir") + "/etc/";
                File configFile = new File(etcDir, "config_file_name");
                if (configFile.exists()) {
                    inputStream = new FileInputStream(configFile);
                }
            }
            if (inputStream == null) {
                inputStream = getClass().getClassLoader().getResourceAsStream("META-INF/mdw/config_file_name");
            }
            if (inputStream == null) {
                throw new IOException("Unable to find configuration file");
            }
            properties.load(inputStream);
        } finally {
            if (inputStream != null) {
                inputStream.close();
            }
        }
        return properties;
    }
}
