public Collection<Command> processCommands(ServerConnector serverConnector, Collection<Command> commands) {
    Collection<Command> outgoingCommands = new ArrayList<>();

    for (Command command : commands) {
        Command outgoingCommand = serverConnector.handleCommand(command);
        outgoingCommands.add(outgoingCommand);
    }

    return outgoingCommands;
}
