public int getValue(int offset, int type) {
    if (type == 4) {
        return page.getInt(offset);
    } else if (type == 2) {
        return page.getShort(offset) & 0xFFFF;
    } else if (type == 1) {
        return page.get(offset) & 0xFF;
    } else {
        throw new IllegalArgumentException("Unsupported value type: " + type);
    }
}
