import javax.servlet.http.HttpServletRequest;

public enum SecurityEventSourceTypeEnum {
    WEB, MOBILE, UNKNOWN
}

public SecurityEventSourceTypeEnum getAccessType(HttpServletRequest theServletRequest) {
    // Identify the access type based on theServletRequest as required
    // Example: If the request is coming from a mobile device, return SecurityEventSourceTypeEnum.MOBILE
    // If the request is coming from a web browser, return SecurityEventSourceTypeEnum.WEB
    // Otherwise return SecurityEventSourceTypeEnum.UNKNOWN

    String userAgent = theServletRequest.getHeader("User-Agent");
    if (userAgent != null && userAgent.toLowerCase().contains("mobile")) {
        return SecurityEventSourceTypeEnum.MOBILE;
    } else if (userAgent != null) {
        return SecurityEventSourceTypeEnum.WEB;
    }
    return SecurityEventSourceTypeEnum.UNKNOWN;
}
