public Set<String> findInverseTransitiveDependencies(Set<String> requiresSet, Set<Archive> archives, String regex, Set<String> packages) {
    Set<String> dependencies = new HashSet<String>();

    // If requires set is empty, use archives depending on packages specified in regex or -p options
    if (requiresSet.isEmpty()) {
        for (Archive archive : archives) {
            for (String packageName : packages) {
                if (archive.dependsOn(packageName) && archive.matchesRegex(regex)) {
                    dependencies.add(archive.getName());
                }
            }
        }
    } else {
        Set<String> targets = new HashSet<String>(requiresSet);
        while (!targets.isEmpty()) {
            Set<String> newTargets = new HashSet<String>();
            for (Archive archive : archives) {
                for (String target : targets) {
                    if (archive.dependsOn(target)) {
                        dependencies.add(archive.getName());
                        newTargets.add(archive.getName());
                        break;
                    }
                }
            }
            targets = newTargets;
        }
    }

    return dependencies;
}
