public void reinitializeProtocols() {
    for (EURLProtocol protocol : EURLProtocol.values()) {
        ProtocolRegistry.addProtocol(protocol);
    }
    ServiceLoader<EURLStreamHandlerProvider> loader =
        ServiceLoader.load(EURLStreamHandlerProvider.class);
    for (EURLStreamHandlerProvider provider : loader) {
        provider.createURLStreamHandler(EURLProtocol.HTTPS.toString());
        provider.createURLStreamHandler(EURLProtocol.FILE.toString());
        provider.createURLStreamHandler(EURLProtocol.HTTP.toString());
    }
}
