  Collections.sort(points.subList(left, right+1), new Comparator<T>() {
    @Override
    public int compare(T o1, T o2) {
      return comp.compare(coord(o1, axis), coord(o2, axis));
    }
  });
  Node<T> node = new Node<>();
  node.location = points.get(mid);
  node.left = buildTree(left, mid-1, (axis+1)%k, comp, points);
  node.right = buildTree(mid+1, right, (axis+1)%k, comp, points);
  return node;
}
