protected void processRequest(SipServletRequest request) throws ServletException, IOException {
    String method = request.getMethod();

    if ("INVITE".equals(method)) {
        doInvite(request);
    } else if ("ACK".equals(method)) {
        doAck(request);
    } else if ("BYE".equals(method)) {
        doBye(request);
    } else if ("CANCEL".equals(method)) {
        doCancel(request);
    } else if ("OPTIONS".equals(method)) {
        doOptions(request);
    } else if ("REGISTER".equals(method)) {
        doRegister(request);
    } else {
        doOther(request);
    }
}
