public boolean isMethodMatching(Method method) {
    Annotation[] annotations = method.getAnnotations();
    boolean overrideAnnotationFound = false;
    boolean callSuperAnnotationFound = false;
    for (Annotation annotation : annotations) {
        if (annotation instanceof Override) {
            overrideAnnotationFound = true;
        } else if (annotation instanceof CallSuper) {
            callSuperAnnotationFound = true;
        }
    }
    return overrideAnnotationFound && !callSuperAnnotationFound;
}
