import java.lang.annotation.Annotation;
import java.lang.reflect.Field;
import java.util.Arrays;
import java.util.stream.Collectors;

public class DefaultFilter {
    public Filter createDefaultFilter(String filterString) {
        return (object) -> {
            for (Field field : object.getClass().getDeclaredFields()) {
                Annotation annotation = field.getAnnotation(Filterable.class);
                if (annotation != null && ((Filterable) annotation).value()) {
                    field.setAccessible(true);
                    try {
                        Object fieldVal = field.get(object);
                        if (fieldVal != null && fieldVal.toString().toLowerCase().contains(filterString.toLowerCase())) {
                            return true;
                        }
                    } catch (IllegalAccessException e) {
                        e.printStackTrace();
                    }
                }
            }
            return false;
        };
    }
}
