import java.util.Collection;
import java.util.LinkedHashSet;
import java.util.Set;
import java.util.function.Function;

public class CollectionToSetLens<X, CX extends Collection<X>> {

    private final Function<CX, Set<X>> get;
    private final Function<CX, Function<Set<X>, CX>> set;

    public CollectionToSetLens(Function<CX, Set<X>> get, Function<CX, Function<Set<X>, CX>> set) {
        this.get = get;
        this.set = set;
    }

    public Set<X> get(CX collection) {
        return get.apply(collection);
    }

    public CX set(CX collection, Set<X> set) {
        return this.set.apply(collection).apply(new LinkedHashSet<>(set));
    }

    public static <A, S extends Collection<A>> CollectionToSetLens<A, S> collectionToSetLens() {
        Function<S, Set<A>> get = s -> new LinkedHashSet<>(s);
        Function<S, Function<Set<A>, S>> set = s -> setValues -> {
            s.clear();
            s.addAll(setValues);
            return s;
        };
        return new CollectionToSetLens<>(get, set);
    }
}
