public static DFA conjunction(DFA dfa1, DFA dfa2, Set<Character> inputAlphabet) {
     DFA conjDFA = new DFA(inputAlphabet);

     Set<StatePair> visited = new HashSet<>();

     Queue<StatePair> queue = new LinkedList<>();
     StatePair start = new StatePair(dfa1.getStartState(), dfa2.getStartState());
     queue.add(start);

     while (!queue.isEmpty()) {
         StatePair currentPair = queue.poll();
         State currentState1 = currentPair.getState1();
         State currentState2 = currentPair.getState2();

         if (dfa1.isFinalState(currentState1) && dfa2.isFinalState(currentState2))
             conjDFA.addFinalState(currentPair);

         for (char c : inputAlphabet) {
             State nextState1 = dfa1.getTransition(currentState1, c);
             State nextState2 = dfa2.getTransition(currentState2, c);
             StatePair nextPair = new StatePair(nextState1, nextState2);

             if (!visited.contains(nextPair)) {
                 queue.add(nextPair);
                 visited.add(nextPair);
             }

             conjDFA.addTransition(currentPair, c, nextPair);
         }
     }

     return conjDFA;
 }
