public int countElementsInBuckets() throws IOException, FileLockException {
    int count = 0;
    for (int i = 0; i < NUM_BUCKETS; i++) {
        try (FileChannel channel = FileChannel.open(Paths.get("bucket_" + i), StandardOpenOption.READ)) {
            FileLock lock = channel.lock(0, Long.MAX_VALUE, true);
            count += channel.size() / RECORD_SIZE;
            lock.release();
        }
    }
    return count;
}
