public List<ReleaseItem> getMergedChangeLog(boolean full) {
    List<ReleaseItem> result = new ArrayList<>();
    List<ReleaseItem> recentChanges = new ArrayList<>();

    // Add all changes since last version
    for (ReleaseItem item : changeLog) {
        if (item.getVersion().compareTo(lastVersion) > 0) {
            recentChanges.add(item);
        }
    }

    // Return all changes if full history is requested
    if (full) {
        result = changeLog;
    } else {
        // Find all versions between lastVersion and most recent
        List<Version> versions = new ArrayList<>();
        for (ReleaseItem item : recentChanges) {
            if (!versions.contains(item.getVersion())) {
                versions.add(item.getVersion());
            }
        }

        // Add latest changes for each version
        for (Version version : versions) {
            ReleaseItem latest = null;
            for (ReleaseItem item : recentChanges) {
                if (item.getVersion().equals(version)) {
                    if (latest == null || item.getDateTime().compareTo(latest.getDateTime()) > 0) {
                        latest = item;
                    }
                }
            }
            result.add(latest);
        }
    }

    // Sort result list
    Collections.sort(result, getChangeLogComparator());
    return result;
}
