public static double trapezoidalIntegral(int n) {
   double a = 0;  // Lower limit
   double b = 1;  // Upper limit
   double h = (b - a) / n;  // Step size
   double sum = 0;

   for (int i = 1; i < n; i++) {
      double x = a + i * h;
      sum += equation(x);
   }

   double integral = h * ((equation(a) + equation(b)) / 2 + sum);
   return integral;
}

// Sample equation method
public static double equation(double x) {
   return Math.sin(x);
}
