public static double[][] nonsymReductionToHessenberg(double[][] matrix) {
    int n = matrix.length;
    for(int i = 1; i < n-1; i++) {
        double[] column = new double[n-i];

        for(int j = i; j < n; j++) {
            column[j-i] = matrix[j][i-1];
        }

        double norm = 0;
        for(int j = 0; j < n-i; j++) {
            norm += column[j]*column[j];
        }
        norm = Math.sqrt(norm);

        if(column[0] >= 0) {
            norm = -norm;
        }

        double[] v = new double[n-i];
        v[0] = column[0] - norm;
        for(int j = 1; j < n-i; j++) {
            v[j] = column[j];
        }

        double beta = 0;
        for(int j = 0; j < n-i; j++) {
            beta += v[j]*v[j];
        }
        beta = 2/beta;

        double[][] tempMatrix = new double[n-i][n-i+1];
        for(int j = 0; j < n-i; j++) {
            for(int k = 0; k < n-i+1; k++) {
                if(k == 0) {
                    tempMatrix[j][k] = 1 - beta*v[j]*v[j];
                } else {
                    tempMatrix[j][k] = -beta*v[j]*v[j+k];
                }
            }
        }

        double[][] subMatrix = new double[n-i][n-i+1];
        for(int j = i; j < n; j++) {
            for(int k = i-1; k < n; k++) {
                subMatrix[j-i][k-i+1] = matrix[j][k];
            }
        }

        double[][] resultMatrix = new double[n][n];
        for(int j = 0; j < i; j++) {
            for(int k = 0; k < i; k++) {
                resultMatrix[j][k] = matrix[j][k];
            }
        }
        for(int j = i; j < n; j++) {
            for(int k = i-1; k < n; k++) {
                resultMatrix[j][k] = matrix[j][k] - tempMatrix[j-i][k-i+1]*subMatrix[j-i][k-i+1];
            }
        }

        for(int j = i-1; j < n; j++) {
            for(int k = 0; k < n-i; k++) {
                resultMatrix[j][i-1+k] = matrix[j][i-1+k] - subMatrix[j-i][k]*tempMatrix[k][i-1+j];
            }
        }

        matrix = resultMatrix;
    }
    return matrix;
}
