public static void invertBuffer(char[] buffer) {
    int left = 0;
    int right = buffer.length - 1;

    while (left < right) {
        char temp = buffer[left];
        buffer[left] = buffer[right];
        buffer[right] = temp;
        left++;
        right--;
    }
}
