        BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()));
        String line;
        Pattern pattern = Pattern.compile(regexp);
        while ((line = reader.readLine()) != null) {
            Matcher matcher = pattern.matcher(line);
            if (matcher.find()) {
                return line;
            }
        }
        return null;
    }
}
