public String getSystemType(String osName, boolean currentSystem) {
    // implementation here
    Properties properties = System.getProperties();
    String vmName = properties.getProperty("java.vm.name");
    String osArch = properties.getProperty("os.arch");

    if (!currentSystem || (vmName != null && vmName.contains("Dalvik"))) {
        return "mobile";
    } else if ("Linux".equals(osName)) {
        if ("arm".equals(osArch) || "arm64".equals(osArch) || "ppc64le".equals(osArch) || "s390x".equals(osArch)) {
            return "server";
        } else if ("x86_64".equals(osArch) || "amd64".equals(osArch)) {
            return "desktop";
        } else {
            return "unknown";
        }
    } else if ("Mac OS X".equals(osName)) {
        return "desktop";
    } else if ("AIX".equals(osName)) {
        return "server";
    } else if (osName != null && osName.toLowerCase(Locale.ENGLISH).contains("sunos")) {
        return "server";
    } else if ("Windows".equals(osName)) {
        return "desktop";
    } else {
        return "unknown";
    }
}
