import java.lang.invoke.MethodHandle;
import java.lang.invoke.MethodHandles;
import java.lang.invoke.MethodType;

public class BuilderFinder {

    public static <T> MethodHandle findBuilder(Class<T> clazz) throws NoSuchMethodException, IllegalAccessException {
        MethodHandles.Lookup lookup = MethodHandles.lookup();

        MethodHandle newBuilderMethod = lookup.findStatic(clazz, "newBuilder", MethodType.methodType(clazz));
        MethodHandle builderMethod = lookup.findVirtual(clazz, "builder", MethodType.methodType(clazz));

        return MethodHandles.foldArguments(newBuilderMethod, builderMethod.asType(builderMethod.type().changeReturnType(Void.class)));
    }
}
