public static boolean isDestructuringPatternNested(ObjectNode n) {
    JsonNode type = n.get("type");
    if (type != null && "ObjectPattern".equals(type.asText())) {
        JsonNode propertiesNode = n.get("properties");
        if(propertiesNode != null && propertiesNode.isArray()) {
            for(JsonNode propertyNode : propertiesNode) {
                if(propertyNode.isObject()) {
                    JsonNode valueNode = propertyNode.get("value");
                    if(valueNode != null && valueNode.isObject() &&
                       valueNode.has("type") && valueNode.get("type").asText().equals("ObjectPattern")) {
                        return true;
                    }
                }
            }
        }
    }
    return false;
}
