public List<Polygon> createAndCollectShadowPolygons(List<Polygon> shadows, List<Point> coordinates, Polygon shadow, ShadowFactory factory) {
    // initialize list to collect shadow polygons
    List<Polygon> shadowPolygons = new ArrayList<>();

    // loop over coordinates and create shadow polygons
    for (Point point : coordinates) {
        // create shadow polygon
        Polygon shadowPolygon = factory.createShadowPolygon(shadow, point);

        // check if shadow polygon intersects with any existing shadows
        boolean intersectsWithExistingShadow = shadows.stream()
                .anyMatch(existingShadow -> existingShadow.intersects(shadowPolygon));

        // add shadow polygon to collection if it doesn't intersect with any existing shadows
        if (!intersectsWithExistingShadow) {
            shadowPolygons.add(shadowPolygon);
        }
    }

    // add collected shadow polygons to main shadow list
    shadows.addAll(shadowPolygons);

    // return the collected shadow polygons
    return shadowPolygons;
}
