public static GVRScriptBundle loadGVRScriptBundle(GVRContext gvrContext, String filePath, GVRResourceVolume volume) throws IOException {

    GVRAssetLoader loader = gvrContext.getAssetLoader();
    GVRAndroidResource resource = volume.openResource(filePath);
    InputStream stream = resource.getStream();
    JsonReader jsonReader = new JsonReader(new InputStreamReader(stream, "UTF-8"));

    Gson gson = new GsonBuilder().create();

    GVRScriptBundle scriptBundle = gson.fromJson(jsonReader, GVRScriptBundle.class);

    jsonReader.close();
    stream.close();
    resource.close();

    return scriptBundle;
}
