public void notifyListeners(List<DatabaseListener> listeners, DatabaseServer databaseServer) throws DatabaseException {
    try {
        for (DatabaseListener listener : listeners) {
            listener.onDatabaseServerOpened(databaseServer);
        }
    } catch (Exception e) {
        throw new DatabaseException("An error occurred while notifying the database listeners.", e);
    }
}
