public PathExtractor createExtractor(int indexInRow, NodeCache cache, TypeSystem types) {
    checkArgument(indexInRow >= 0 && indexInRow < cache.getRowSize(), "Index must be valid.");
    checkNotNull(cache, "Cache cannot be null.");
    checkNotNull(types, "Type system cannot be null.");

    Node node = cache.getNodeAt(indexInRow);
    String nodeName = node.getName();
    List<String> nodePath = new ArrayList<String>();
    nodePath.add(nodeName);

    return new PathExtractor(nodePath, types);
}
