public void ensureNonNullNavigationProperties(EntityType entityType) throws ODataException {
    List<String> nonNullNavigationProps = entityType.getNavigationProperties().stream()
            .filter(prop -> !prop.isNullable())
            .map(NavigationProperty::getName)
            .collect(Collectors.toList());

    for (String propName : nonNullNavigationProps) {
        if (entityType.getProperty(propName) == null) {
            throw new ODataException("Navigation property " + propName + " cannot be null.");
        }
    }
}
