public boolean isIOManagerProperlyShutdown() {
    if (ioManager.isClosed()) {
        try {
            ioManager.getExecutionThread().join();
            ioManager.getAsyncTaskThread().join();
            return true;
        } catch (InterruptedException e) {
            return false;
        }
    }
    return false;
}
