public static String getDriverVersion(String driverFilePath) throws IOException {
    File file = new File(driverFilePath); // instantiate a File object with the driver file path
    if (!file.exists()) {
        throw new FileNotFoundException("Driver file not found.");
    }
    // create a JarFile object with the driver file
    JarFile jarFile = new JarFile(file);
    // get the MANIFEST.MF file from the jar file
    Manifest manifest = jarFile.getManifest();
    Attributes attributes = manifest.getMainAttributes();
    // get the driver version attribute from the MANIFEST.MF file
    String driverVersion = attributes.getValue("Driver-Version");
    // close the JarFile object
    jarFile.close();
    return driverVersion;
}
