public ProClass loadProClass(String className, String feature, ErrorHandler loadFailure) {
    ProClass proClass = null;
    try {
        Class<?> loadedClass = Class.forName(className);
        proClass = (ProClass) loadedClass.newInstance();
        proClass.setFeature(feature);
    } catch (ClassNotFoundException e) {
        loadFailure.handleError("Class " + className + " not found");
    } catch (InstantiationException | IllegalAccessException | ClassCastException e) {
        loadFailure.handleError("Error loading class " + className + ": " + e.getMessage());
    }
    return proClass != null ? proClass : new ProClass();
}
