public static double[] calculateEigenvalues(double[][] matrix) {
    double trace = matrix[0][0] + matrix[1][1];
    double determinant = matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0];
    double[] eigenvalues = new double[2];
    eigenvalues[0] = (trace - Math.sqrt(trace * trace - 4 * determinant)) / 2;
    eigenvalues[1] = (trace + Math.sqrt(trace * trace - 4 * determinant)) / 2;
    return eigenvalues;
}
