public void addBufferToQueue(byte[] buf, Consumer<byte[]> listener) {
    // add the buffer to the queue
    queue.add(buf);

    // create a new thread to process the queue
    new Thread(() -> {
        try {
            // get the first buffer from the queue
            byte[] nextBuffer = queue.take();

            // process each byte in the buffer
            for (byte b : nextBuffer) {
                // do some processing ...
            }

            // if there is a listener, notify it that this buffer has been consumed and written
            if (listener != null) {
                listener.accept(nextBuffer);
            }
        } catch (InterruptedException e) {
            // handle interruption ...
        }
    }).start();
}
