public static int[] gatherTreeInfo(Node aT, int[] postorder) {
    int[] parent = new int[postorder.length];
    int[] leftChild = new int[postorder.length];
    int[] rightSibling = new int[postorder.length];

    for(int i = 0; i < postorder.length; i++) {
        Node currentNode = postorder[i];
        if(currentNode.parent != null) {
            parent[i] = currentNode.parent.value;
        } else {
            parent[i] = -1;
        }

        if(currentNode.leftChild != null) {
            leftChild[i] = Arrays.asList(postorder).indexOf(currentNode.leftChild);
        } else {
            leftChild[i] = -1;
        }

        if(currentNode.rightSibling != null) {
            rightSibling[i] = Arrays.asList(postorder).indexOf(currentNode.rightSibling);
        } else {
            rightSibling[i] = -1;
        }
    }

    int[][] info = {parent, leftChild, rightSibling};
    return info;
}
