public class BshUtil {

    public static BshMethod findStaticMethod(Class<?> baseClass, String methodName) {

        Method[] methods = baseClass.getMethods();
        for (Method method : methods) {
            if (method.getName().equals(methodName) && method.getModifiers() == Modifier.STATIC) {
                return new BshMethod(method);
            }
        }
        return null;
    }
}
