public double[] matrixToVector(double[][] m) {
    double[] vector = new double[3];
    if(m.length == 1 && m[0].length == 3) { // check if 1x3 matrix
        for(int i=0; i<3; i++) {
            vector[i] = m[0][i];
        }
    } else if(m.length == 3 && m[0].length == 1) { // check if 3x1 matrix
        for(int i=0; i<3; i++) {
            vector[i] = m[i][0];
        }
    } else {
        throw new IllegalArgumentException("Invalid matrix dimensions. Must be 3x1 or 1x3.");
    }
    return vector;
}
