public void unzipDeeperSide(int[] sides) {
    int left = 0;
    int right = sides.length - 1;

    while (left < right) {
        int leftDepth = sides[left];
        int rightDepth = sides[right];

        if (leftDepth < rightDepth) {
            // unzip deeper side on the left
            while (left < right && sides[left] <= leftDepth) {
                left++;
            }
        } else {
            // unzip deeper side on the right
            while (left < right && sides[right] <= rightDepth) {
                right--;
            }
        }
    }
}
