import java.util.*;

public class RoundRobinAllocation {

    public static Map<String, List<String>> allocateInstances(List<String> containerIds, List<String> instanceIds) {
        Map<String, List<String>> allocationMap = new HashMap<>();
        int index = 0;
        for (String instanceId : instanceIds) {
            String containerId = containerIds.get(index);
            List<String> containerInstances = allocationMap.getOrDefault(containerId, new ArrayList<>());
            containerInstances.add(instanceId);
            allocationMap.put(containerId, containerInstances);

            index++;
            if (index == containerIds.size()) {
                index = 0;
            }
        }

        return allocationMap;
    }
}
