public List<List<Integer>> minimumCycleBasis(List<List<Integer>> cycles) {
    List<List<Integer>> basis = new ArrayList<>();
    for (List<Integer> cycle : cycles) {
        boolean found = false;
        for (List<Integer> baseCycle : basis) {
            if (baseCycle.containsAll(cycle) || cycle.containsAll(baseCycle)) {
                found = true;
                break;
            }
        }
        if (!found) {
            basis.add(cycle);
        }
    }
    return basis;
}
