import java.lang.annotation.Annotation;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.reflect.AnnotatedElement;
import java.lang.reflect.Field;
import java.util.HashMap;

public class AnnotationUtils {

  public static <T extends AnnotatedElement> T addAnnotation(
      final Class<? extends Annotation> annotation, final HashMap<String, Object> memberValues, final T toAnnotate) throws NoSuchFieldException, IllegalAccessException {
    final Annotation realAnnotation = buildAnnotation(annotation, memberValues);
    final Annotation[] annotations = toAnnotate.getDeclaredAnnotations();
    final int length = annotations.length;
    final Annotation[] newAnnotations = new Annotation[length + 1];
    System.arraycopy(annotations, 0, newAnnotations, 0, length);
    newAnnotations[length] = realAnnotation;
    final Class<?> superClass = toAnnotate.getClass().getSuperclass();
    final Field annotationsField = superClass.getDeclaredField("annotations");
    annotationsField.setAccessible(true);
    annotationsField.set(toAnnotate, newAnnotations);
    return toAnnotate;
  }

  private static <T extends Annotation> T buildAnnotation(
      final Class<T> annotation, final HashMap<String, Object> memberValues) {
    return (T) java.lang.reflect.Proxy.newProxyInstance(
        AnnotationUtils.class.getClassLoader(),
        new Class[] {annotation, Annotation.class},
        (proxy, method, args) -> {
          final String methodName = method.getName();
          if (methodName.equals("equals")) {
            return args[0].equals(buildAnnotation(annotation, memberValues));
          }
          if (methodName.equals("hashCode")) {
            return buildAnnotation(annotation, memberValues).hashCode();
          }
          if (methodName.equals("annotationType")) {
            return annotation;
          }
          final Object v = memberValues.get(methodName);
          if (v == null) {
            return method.getDefaultValue();
          }
          return v;
        });
  }

  public static void main(String[] args) {
    final TestAnnotation objectAnnotated = new TestAnnotation();
    try {
      addAnnotation(MyAnnotation.class, new HashMap<String, Object>() {{
        put("value", "myValue");
        put("name", "myName");
        put("code", 1);
      }}, objectAnnotated);
      for (Annotation annotation : objectAnnotated.getClass().getDeclaredAnnotations()) {
        if (annotation instanceof MyAnnotation) {
          final MyAnnotation myAnnotation = ((MyAnnotation) annotation);
          System.out.println(myAnnotation.value() + " " + myAnnotation.name() + " " + myAnnotation.code());
        }
      }
    } catch (NoSuchFieldException | IllegalAccessException e) {
      e.printStackTrace();
    }
  }
}

@Retention(RetentionPolicy.RUNTIME)
@interface MyAnnotation {
  String value();

  String name();

  int code();
}

@MyAnnotation(value = "myValue", name = "myName", code = 1)
class TestAnnotation {}l
