public int getTotalCapacity(List<Buffer> list) {
    if (list == null || list.isEmpty()) {
        return 0;
    }
    int totalCapacity = 0;
    for (Buffer buffer : list) {
        totalCapacity += buffer.capacity();
    }
    return totalCapacity;
}
