public static double[] compute(double[] in, boolean copy) {
    double[] out;
    if (copy) {
        out = new double[in.length];
        System.arraycopy(in, 0, out, 0, in.length);
    } else {
        out = in;
    }

    for (int i = 0; i < in.length; i++) {
        out[i] = out[i] * (1 - out[i]);
    }

    return out;
}
