public boolean isSegmentRoot(Node node, RemovingRule removingRule) {
    if (node == null) {
        throw new IllegalArgumentException("Node cannot be null.");
    }
    if (node instanceof Lian) {
        return true;
    }
    Node parent = node.getParent();
    while (parent != null && parent != removingRule) {
        parent = parent.getParent();
    }
    return parent == null;
}
