public void iterateZipEntries(ZipFile zipFile, ZipEntryCallback zipEntryCallback) throws IOException {
    Enumeration<? extends ZipEntry> entries = zipFile.entries();
    while (entries.hasMoreElements()) {
        ZipEntry entry = entries.nextElement();
        if (!entry.isDirectory() && !entry.isCompressed()) {
            zipEntryCallback.execute(entry);
        }
    }
}
