public int compareTo(InstanceManager other) {
    // Compare this instance's priority with the other instance's priority
    int priorityComp = Integer.compare(this.priority, other.priority);
    if (priorityComp != 0) {
        return priorityComp;
    }

    // If priorities are equal, compare this instance's name with the other instance's name
    return this.name.compareTo(other.name);
}
