public void identifyAndSetCoordinateAxes(NetcdfDataset ncDataset) {
    List<Variable> coordinateVariables = ncDataset.getCoordinateVariables();
    for (Variable variable : coordinateVariables) {
        String[] axisAttributeValues = variable.findAttributeString("_CoordinateAxisType", null);
        if (axisAttributeValues != null) {
            for (String axisAttributeValue : axisAttributeValues) {
                if (axisAttributeValue.equals("Lon") || axisAttributeValue.equals("Lat") || axisAttributeValue.equals("Height") || axisAttributeValue.equals("Pressure") || axisAttributeValue.equals("Time")) {
                    ncDataset.setIsCoordinateAxis(true);
                }
            }
        } else if (variable.getName().equalsIgnoreCase("lon") || variable.getName().equalsIgnoreCase("lat") || variable.getName().equalsIgnoreCase("height") || variable.getName().equalsIgnoreCase("pressure") || variable.getName().equalsIgnoreCase("time")) {
            ncDataset.setIsCoordinateAxis(true);
        }
    }
}
