        if(concurrencyControl == ConcurrencyControl.FAIL_ON_CONFLICT) {
            throw new CouchbaseLiteException("Delete failed due to conflict.", CBLError.Domain.CBLITE, CBLError.Code.CONFLICT);
        } else {
            document.delete();
            return true;
        }
    } catch (CouchbaseLiteException e) {
        throw new CouchbaseLiteException("Error deleting document: " + e.getMessage(), e.getDomain(), e.getCode());
    }
}
