public static List<String> parseFile(String filePath) {
  List<String> dependenciesAndAnnotations = new ArrayList<>();
  try {
    File file = new File(filePath);
    Scanner scanner = new Scanner(file);
    while (scanner.hasNextLine()) {
      String line = scanner.nextLine();
      if (line.contains("import") || line.contains("@")) {
        dependenciesAndAnnotations.add(line);
      }
    }
    scanner.close();
  } catch (FileNotFoundException e) {
    System.out.println("File not found: " + filePath);
  }
  return dependenciesAndAnnotations;
}
