public Properties loadProperties(String resourceName) {
    Properties properties = new Properties();
    try {
        File propFile = new File(resourceName);
        if (propFile.exists()) {
            try (InputStream is = new FileInputStream(propFile)) {
                properties.load(is);
                return properties;
            } catch (IOException e) {
                // handle exception
            }
        } else {
            URL propUrl = getClass().getResource(resourceName);
            if (propUrl != null) {
                try (InputStream is = propUrl.openStream()) {
                    properties.load(is);
                    return properties;
                } catch (IOException e) {
                    // handle exception
                }
            }
        }
    } catch (Exception e) {
        // handle exception
    }
    return null;
}
