public static Mat computeFundamentalMatrix(Mat features1, Mat features2) {
    // Assuming that the set of associated features are correct
    // Computing fundamental matrix directly with less code
    Mat fundamentalMatrix = Calib3d.findFundamentalMat(features1, features2, Calib3d.FUNDAMENTAL_7POINT);

    // Adding noise detection and removal
    Mat mask = new Mat();
    Mat filteredFundamentalMatrix = Calib3d.findFundamentalMat(features1, features2, mask, Calib3d.FM_RANSAC, 1, 0.99);

    // Returning filtered fundamental matrix
    return filteredFundamentalMatrix;
}
