public void removeAndRecreateRules(LanguageModel lm) {
    List<Rule> rulesToRemove = new ArrayList<>();
    for (Rule rule : rules) {
        if (lm != null && rule.canProfitFromModel(lm)) {
            rulesToRemove.add(rule);
        }
    }
    rules.removeAll(rulesToRemove);
    for (Rule rule : rulesToRemove) {
        Rule newRule = rule.recreateWithModel(lm);
        rules.add(newRule);
    }
}
