import java.util.HashMap;
import java.util.Map;

public class BufferedCounter {

    private Map<String, Long> counterMap;

    public BufferedCounter() {
        this.counterMap = new HashMap<>();
    }

    public void incrCounter(String group, String counter, long amount) {
        String key = group + "." + counter;
        long currentValue = counterMap.getOrDefault(key, 0L);
        counterMap.put(key, currentValue + amount);
    }

    // Additional method to flush the buffered counters
    public void flushCounters() {
        for (Map.Entry<String, Long> entry : counterMap.entrySet()) {
            String[] parts = entry.getKey().split("\\.");
            String group = parts[0];
            String counter = parts[1];
            long value = entry.getValue();
            Reporter.get().incrCounter(group, counter, value);
        }
        counterMap.clear();
    }
}
