import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.ParserConfigurationException;

import org.w3c.dom.Document;
import org.w3c.dom.NodeList;
import org.xml.sax.InputSource;
import org.xml.sax.SAXException;

import java.io.IOException;
import javax.xml.xpath.XPath;
import javax.xml.xpath.XPathConstants;
import javax.xml.xpath.XPathExpression;
import javax.xml.xpath.XPathExpressionException;
import javax.xml.xpath.XPathFactory;

public class XpathEvaluator {

    public static void assertXpathsEqual(String controlXpath, String testXpath, String inXMLString) throws SAXException, IOException, XPathExpressionException {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        DocumentBuilder builder;
        Document document;

        try {
            builder = factory.newDocumentBuilder();
            document = builder.parse(new InputSource(new StringReader(inXMLString)));
        } catch (ParserConfigurationException e) {
            // Handle exception
        }

        XPathFactory xPathfactory = XPathFactory.newInstance();
        XPath xpath = xPathfactory.newXPath();

        XPathExpression controlExpression = xpath.compile(controlXpath);
        XPathExpression testExpression = xpath.compile(testXpath);

        NodeList controlNodes = (NodeList) controlExpression.evaluate(document, XPathConstants.NODESET);
        NodeList testNodes = (NodeList) testExpression.evaluate(document, XPathConstants.NODESET);

        if (controlNodes.getLength() != testNodes.getLength()) {
            throw new AssertionError("The number of nodes in the two Xpath evaluations is different.");
        }

        for (int i = 0; i < controlNodes.getLength(); i++) {
            if (!controlNodes.item(i).isEqualNode(testNodes.item(i))) {
                throw new AssertionError("The Xpath evaluations are not equal.");
            }
        }
    }
}
