public class Canvas {

    private int width;
    private int height;
    private char[][] canvas;

    // Constructor
    public Canvas(int width, int height) {
        this.width = width;
        this.height = height;
        this.canvas = new char[height][width];

        // Initialize canvas with empty spaces
        for (int i = 0; i < height; i++) {
            for (int j = 0; j < width; j++) {
                canvas[i][j] = ' ';
            }
        }
    }

    // Draw horizontal line on the canvas
    public void drawHorizontalLine(int x1, int x2, int y, char c) {
        for (int i = x1; i <= x2; i++) {
            canvas[y-1][i-1] = c;
        }
    }

    // Draw vertical line on the canvas
    public void drawVerticalLine(int x, int y1, int y2, char c) {
        for (int i = y1; i <= y2; i++) {
            canvas[i-1][x-1] = c;
        }
    }

    // Draw rectangle on the canvas
    public void drawRectangle(int x1, int y1, int x2, int y2, char c) {
        drawHorizontalLine(x1, x2, y1, c);
        drawHorizontalLine(x1, x2, y2, c);
        drawVerticalLine(x1, y1, y2, c);
        drawVerticalLine(x2, y1, y2, c);
    }

    // Fill region with color
    public void bucketFill(int x, int y, char c) {
        char color = canvas[y-1][x-1];

        if (color != c) {
            fill(x, y, color, c);
        }
    }

    // Helper method for bucketFill
    private void fill(int x, int y, char color, char c) {
        if (x < 1 || y < 1 || x > width || y > height) {
            return;
        }

        if (canvas[y-1][x-1] != color) {
            return;
        }

        canvas[y-1][x-1] = c;
        fill(x-1, y, color, c);
        fill(x+1, y, color, c);
        fill(x, y-1, color, c);
        fill(x, y+1, color, c);
    }

    // Print the canvas
    public void printCanvas() {
        for (int i = 0; i <= width + 1; i++) {
            System.out.print("-");
        }
        System.out.println();

        for (int i = 0; i < height; i++) {
            System.out.print("|");
            for (int j = 0; j < width; j++) {
                System.out.print(canvas[i][j]);
            }
            System.out.println("|");
        }

        for (int i = 0; i <= width + 1; i++) {
            System.out.print("-");
        }
        System.out.println();
    }
}
