public static Vector3 rotateVector(double angle, double x, double y, double z, Vector3 vector) {
    double sinHalfAngle = Math.sin(angle / 2);
    double cosHalfAngle = Math.cos(angle / 2);

    double rx = x * sinHalfAngle;
    double ry = y * sinHalfAngle;
    double rz = z * sinHalfAngle;
    double rw = cosHalfAngle;

    Quaternion rotation = new Quaternion(rx, ry, rz, rw);
    Quaternion conjugate = rotation.conjugate();

    Quaternion vectorQuat = new Quaternion(vector.getX(), vector.getY(), vector.getZ(), 0);
    Quaternion rotatedQuat = rotation.multiply(vectorQuat).multiply(conjugate);

    return new Vector3(rotatedQuat.getX(), rotatedQuat.getY(), rotatedQuat.getZ());
}
