import java.io.IOException;
import java.io.OutputStream;

public class SerializeUtils {

    public static void serializePrimitive(Object object, OutputStream outputStream) throws IOException {
        if (object instanceof Integer) {
            outputStream.write('i');
            outputStream.write(((Integer)object).toString().getBytes());
            outputStream.write('e');
        } else if (object instanceof Long) {
            outputStream.write('l');
            outputStream.write(((Long)object).toString().getBytes());
            outputStream.write('e');
        } else if (object instanceof Float) {
            outputStream.write('f');
            outputStream.write(((Float)object).toString().getBytes());
            outputStream.write('e');
        } else if (object instanceof Double) {
            outputStream.write('d');
            outputStream.write(((Double)object).toString().getBytes());
            outputStream.write('e');
        } else if (object instanceof Boolean) {
            outputStream.write('b');
            outputStream.write((Boolean.toString((Boolean)object)).getBytes());
            outputStream.write('e');
        } else if (object instanceof String) {
            String str = ((String)object);
            outputStream.write(str.length());
            outputStream.write(':');
            outputStream.write(str.getBytes());
        }
    }
}
