public void verifyApplicationName(String name) throws IllegalArgumentException {
    if (name == null || name.isEmpty()) {
        throw new IllegalArgumentException("Application name must not be null or empty");
    }
    if (name.contains("/") || name.contains(":") || name.contains("*") || name.contains("?") || name.contains("\"") || name.contains("<") || name.contains(">") || name.contains("|")) {
        throw new IllegalArgumentException("Application name contains illegal characters");
    }
}
