public static double[][][] loadTripletMatrixFromFile(String fileName) {
    File file = new File(fileName);
    try {
        Scanner scanner = new Scanner(file);
        int numberOfRows = scanner.nextInt();
        int numberOfColumns = scanner.nextInt();
        int numberOfNonZeroElements = scanner.nextInt();
        double[][][] T = new double[numberOfRows][numberOfColumns][2];

        for (int i = 0; i < numberOfNonZeroElements; i++) {
            int row = scanner.nextInt();
            int column = scanner.nextInt();
            double real = scanner.nextDouble();
            double imag = scanner.nextDouble();
            T[row][column][0] = real;
            T[row][column][1] = imag;
        }
        scanner.close();
        return T;

    } catch (FileNotFoundException e) {
        e.printStackTrace();
        return null;
    }
}
