import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.select.Elements;

public class HtmlReplacer {

    public static String replaceHtmlElement(String content, String selector, String replacement) {

        Document doc = Jsoup.parse(content);

        Elements elements = doc.select(selector);

        if(elements.isEmpty()) {
            return content;
        }

        Element replaceElem = Jsoup.parse(replacement).body().child(0);

        for(Element element : elements) {
            element.replaceWith(replaceElem.clone());
        }

        return doc.html();
    }
}
