public void runExample(AdWordsServicesInterface adWordsServices, AdWordsSession session, Long sharedBudgetId) throws ApiException, RemoteException {
  // Get the BudgetService.
  BudgetServiceInterface budgetService =
      adWordsServices.get(session, BudgetServiceInterface.class);

  Budget sharedBudget = null;

  if (sharedBudgetId == null) {
    // Create a shared budget for the campaign to use.
    sharedBudget = new Budget();
    sharedBudget.setName("Interplanetary Cruise #" + System.currentTimeMillis());
    Money budgetAmount = new Money();
    budgetAmount.setMicroAmount(50_000_000L);
    sharedBudget.setAmount(budgetAmount);
    sharedBudget.setDeliveryMethod(BudgetBudgetDeliveryMethod.STANDARD);

    BudgetOperation budgetOperation = new BudgetOperation();
    budgetOperation.setOperand(sharedBudget);
    budgetOperation.setOperator(Operator.ADD);

    // Add the budget
    BudgetReturnValue budgetResult = budgetService.mutate(
        new BudgetOperation[] {budgetOperation});

    sharedBudget = budgetResult.getValue()[0];
    System.out.printf("Shared budget with name '%s' and ID %d was created.\n",
        sharedBudget.getName(), sharedBudget.getBudgetId());
  } else {
    // Get the existing shared budget.
    sharedBudget = budgetService.get(new SelectorBuilder()
        .fields(BudgetField.BudgetId, BudgetField.Name, BudgetField.Amount,
            BudgetField.DeliveryMethod)
        .equalsId(sharedBudgetId)
        .build())
        .getEntries()[0];
  }

  // Set the ID of the shared budget on the campaign.
  Campaign campaign = new Campaign();
  campaign.setName("Interplanetary Cruise #" + System.currentTimeMillis());
  campaign.setAdvertisingChannelType(AdvertisingChannelType.SEARCH);

  Budget budget = new Budget();
  budget.setBudgetId(sharedBudget.getBudgetId());
  campaign.setBudget(budget);

  // Set the advertising locale and location.
  GeoTargetTypeSetting geoSetting = new GeoTargetTypeSetting();
  geoSetting.setPositiveGeoTargetType(GeoTargetTypeSettingPositiveGeoTargetType.LOCATION_OF_PRESENCE);
  campaign.setSettings(new Setting[] {geoSetting});

  // Create the operation.
  CampaignOperation operation = new CampaignOperation();
  operation.setOperand(campaign);
  operation.setOperator(Operator.ADD);

  // Add the campaign and display the results.
  CampaignReturnValue result = campaignService.mutate(new CampaignOperation[] {operation});
  System.out.printf("Campaign with name '%s' and ID %d was added.\n", result.getValue()[0].getName(),
      result.getValue()[0].getId());
}
