    @Override 
    protected int voteImpl(Authentication authentication, Object o, Collection<ConfigAttribute> collection) {
        // First, Check if the authentication object is an instance of UsernamePasswordAuthenticationToken
        if (!(authentication instanceof UsernamePasswordAuthenticationToken)) {
            return ABSTAIN;
        }

        // Next, get the authenticated principal
        UsernamePasswordAuthenticationToken token = (UsernamePasswordAuthenticationToken) authentication;
        Object principal = token.getPrincipal();

        // Check if the principal has IP limits set
        String[] ipLimits = getIpLimits(principal);
        if (ipLimits == null || ipLimits.length == 0) {
            return ABSTAIN;
        }

        // Get the IP address of the request
        String ipAddress = getIpAddress();

        // Check if the IP address is within the specified range(s)
        for (String ip : ipLimits) {
            if (isInRange(ipAddress, ip)) {
                return ALLOW;
            }
        }

        // If the IP address is outside the specified range(s), deny access
        return DENY;
    }

