public BoundingBox scaleBoundingBox(double factor, BoundingBox bbox) {
    if (factor <= 0) {
        throw new IllegalArgumentException("Scale factor must be greater than 0.");
    }

    double width = bbox.getWidth() * factor;
    double height = bbox.getHeight() * factor;

    Point center = bbox.getCenter();
    double minX = center.getX() - (width / 2);
    double minY = center.getY() - (height / 2);

    return new BoundingBox(minX, minY, width, height);
}
