public DTOTile convertServerTileToDTOTile(ServerTile tile, String crs, List<String> featureIncludes) {
    DTOTile dtoTile = new DTOTile();
    dtoTile.setTileId(tile.getTileId());
    dtoTile.setCrs(crs);
    dtoTile.setZoom(tile.getZoom());
    dtoTile.setX(tile.getX());
    dtoTile.setY(tile.getY());
    dtoTile.setFeatures(new ArrayList<>());

    for (ServerFeature serverFeature : tile.getFeatures()) {
        DTOFeature dtoFeature = new DTOFeature();
        dtoFeature.setGeometry(serverFeature.getGeometry());
        dtoFeature.setProperties(getProperties(serverFeature.getProperties(), featureIncludes));
        dtoTile.getFeatures().add(dtoFeature);
    }

    return dtoTile;
}

private Map<String, Object> getProperties(Map<String, Object> serverProperties, List<String> featureIncludes) {
    Map<String, Object> properties = new HashMap<>();
    for (String key : featureIncludes) {
        if (serverProperties.containsKey(key)) {
            properties.put(key, serverProperties.get(key));
        }
    }
    return properties;
}
