public static double findMedian(double[] vector) {
  Arrays.sort(vector);
  int n = vector.length;
  if (n % 2 == 0) {
    return (vector[(n / 2) - 1] + vector[n / 2]) / 2.0;
  } else {
    return vector[n / 2];
  }
}
