public static LTSminVersion parseLTSminVersion(String version) {
    try {
        String[] versionFragments = version.split("\\.");
        int major = Integer.parseInt(versionFragments[0]);
        int minor = Integer.parseInt(versionFragments[1]);
        int patch = Integer.parseInt(versionFragments[2]);
        return new LTSminVersion(major, minor, patch);
    } catch (Exception e) {
        return new LTSminVersion(0, 0, 0);
    }
}
