public static <T, R> Collection<R> mapObjects(Mapper<T, R> mapper, Enumeration<T> en, boolean allowNull) {
    Collection<R> results = new ArrayList<>();
    while (en.hasMoreElements()) {
        T element = en.nextElement();
        R mappedElement = mapper.map(element);
        if (mappedElement != null || (mappedElement == null && allowNull)) {
            results.add(mappedElement);
        }
    }
    return results;
}
