public static long validatePositiveInteger(String valueName, String value, long defaultValue) {
    if (value == null || value.isEmpty()) {
        return defaultValue;
    }
    try {
        long numericValue = Long.parseLong(value.trim());
        if (numericValue <= 0) {
            throw new IllegalArgumentException(String.format("%s should be a positive integer", valueName));
        }
        return numericValue;
    } catch (NumberFormatException e) {
        throw new IllegalArgumentException(String.format("%s should be a positive integer", valueName));
    }
}
