public Pcm enleverColonnes(PcmInfoContainer pcmic, Pcm pcm) {
    List<Feature> featuresToRemove = new ArrayList<>();

    // Obtenir la liste des colonnes inutiles
    for (Feature feature : pcm.getFeatures()) {
        if (isInutile(feature, pcmic)) {
            featuresToRemove.add(feature);
        }
    }

    // Enlever les colonnes inutiles
    for (Feature feature : featuresToRemove) {
        pcm.removeFeature(feature);
    }

    return pcm;
}

