public class WatchDog {
    private Thread watchdogThread;
    private WatchdogInterruptListener interruptListener;

    public interface WatchdogInterruptListener {
        void onInterrupt();
    }

    public WatchDog setInterruptListener(WatchdogInterruptListener listener) {
        this.interruptListener = listener;
        return this;
    }

    public void start() {
        watchdogThread = new Thread(() -> {
            try {
                // Do some process here
            } catch (InterruptedException e) {
                if (interruptListener != null) {
                    interruptListener.onInterrupt();
                } else {
                    System.out.println("Watchdog thread interrupted.");
                }
            }
        });
        watchdogThread.start();
    }
}
