public boolean checkBilevelImage(Metadata metadata, int n) {
    // Get the TIFF image data from the metadata
    TiffImageData tiffImageData = metadata.getTiffImageData();

    // Get the specified IFD
    TiffDirectory ifd = tiffImageData.getDirectories().get(n);

    // Check if the image is bilevel by looking at the PhotometricInterpretation tag
    if (ifd.contains(TagConstants.TIFF_TAG_PHOTOMETRIC_INTERPRETATION)) {
        int photometricInterpretation = ifd.getInt(TagConstants.TIFF_TAG_PHOTOMETRIC_INTERPRETATION);
        return photometricInterpretation == PhotometricInterpretationConstants.WHITE_IS_ZERO 
            || photometricInterpretation == PhotometricInterpretationConstants.BLACK_IS_ZERO;
    }

    return false;
}
