public String getAjaxUrlPrefix(ServletContext servletContext, ServletRequest request, INamable nameable) {
     // obtaining the context path name
     String contextPath = servletContext.getContextPath();

     // obtain the base URL for the request
     StringBuffer requestUrl = request.getRequestURL();
     String baseURL = requestUrl.toString();
     int position = baseURL.indexOf(contextPath);

     // create the URL prefix
     String urlPrefix = baseURL.substring(0, position) + contextPath + nameable.getHandlingPage() + "/" ;

     return urlPrefix;
}
