public int countParagraphs(String document) {
    if (document == null || document.isEmpty()) {
        return 0;
    }
    String[] paragraphs = document.split("(\\r\\n|\\n|\\r){2,}");
    int count = 0;
    for (String paragraph : paragraphs) {
        if (!paragraph.contains("footnote")) {
            count++;
        }
    }
    return count;
}
