public static void registerTypeVariables(Type type) {
    if (type instanceof Class) {
        Class<?> clazz = (Class<?>) type;
        registerTypeVariables(clazz.getSuperclass());
        for (Type iface : clazz.getGenericInterfaces()) {
            registerTypeVariables(iface);
        }
    } else if (type instanceof ParameterizedType) {
        for (Type arg : ((ParameterizedType) type).getActualTypeArguments()) {
            registerTypeVariables(arg);
        }
    } else if (type instanceof TypeVariable) {
        TypeVariable<?> typeVar = (TypeVariable<?>) type;
        for (Type bound : typeVar.getBounds()) {
            registerTypeVariables(bound);
        }
    }
}
