import java.util.Collection;

public void populateObjectOrCollection(Object o, Object subroot, Collection col, Class cl) throws ConfigException {

  if (o == null && col == null) {
    throw new ConfigException("Both object and collection can't be null.");
  }

  if (subroot == null) {
    throw new ConfigException("Subroot object can't be null.");
  }

  if (cl == null) {
    throw new ConfigException("Class type can't be null.");
  }

  if (col != null) {
    if (!col.isEmpty()) {
      col.clear();
    }
    if (o instanceof Collection && cl.isAssignableFrom(o.getClass())) {
      col.addAll((Collection) o);
    }
  }

  if (o != null) {
    if (col != null) {
      if (o instanceof Collection && cl.isAssignableFrom(o.getClass())) {
        col.addAll((Collection) o);
      }
    }
    else {
      PropertyDescriptor[] propertyDescriptors = Introspector.getBeanInfo(cl).getPropertyDescriptors();
      for (PropertyDescriptor propDesc : propertyDescriptors) {
        Method writerMethod = propDesc.getWriteMethod();
        if (writerMethod == null) {
          continue;
        }
        Class<?> propertyType = propDesc.getPropertyType();
        if (Collection.class.isAssignableFrom(propertyType)) {
          try {
            Collection collection = (Collection) propDesc.getReadMethod().invoke(subroot);
            if (collection != null) {
              Method addMethod = propertyType.getMethod("add", Object.class);
              for (Object obj : (Collection) o) {
                addMethod.invoke(collection, obj);
              }
            }
          }
          catch (IllegalAccessException | InvocationTargetException | NoSuchMethodException ex) {
            throw new ConfigException("Error occurred while setting property " + propDesc.getName() + " on class " + cl.getName());
          }
        }
        else {
          try {
            writerMethod.invoke(subroot, new Object[] { o });
          }
          catch (IllegalAccessException | InvocationTargetException ex) {
            throw new ConfigException("Error occurred while setting property " + propDesc.getName() + " on class " + cl.getName());
          }
        }
      }
    }
  }
}
