import java.io.Closeable;
import java.io.IOException;
import java.util.Iterator;

public class CloseableIterable<T> implements Iterable<T>, Closeable {

    private final Iterable<? extends Iterable<T>> inputs;

    public CloseableIterable(Iterable<? extends Iterable<T>> inputs) {
        this.inputs = inputs;
    }

    @Override
    public void close() throws IOException {
        for (Iterable<T> iterable : inputs) {
            if (iterable instanceof Closeable) {
                ((Closeable) iterable).close();
            }
        }
    }

    @Override
    public Iterator<T> iterator() {
        return new Iterator<T>() {

            private Iterator<? extends Iterable<T>> iterator = inputs.iterator();
            private Iterator<T> currentIterator;

            private boolean advanceToNextIterator() {
                while (iterator.hasNext()) {
                    currentIterator = iterator.next().iterator();
                    if (currentIterator.hasNext()) {
                        return true;
                    }
                }
                return false;
            }

            @Override
            public boolean hasNext() {
                if (currentIterator == null || !currentIterator.hasNext()) {
                    return advanceToNextIterator();
                }
                return true;
            }

            @Override
            public T next() {
                if (!hasNext()) {
                    throw new UnsupportedOperationException("No more elements");
                }
                return currentIterator.next();
            }

            @Override
            public void remove() {
                throw new UnsupportedOperationException();
            }
        };
    }
}
