public byte[] readBytes(int offset, int length) throws IOException {
    byte[] bytes = new byte[length];
    seek(offset);
    int totalBytesRead = 0;
    int bytesRead;
    while (totalBytesRead < length && (bytesRead = in.read(bytes, totalBytesRead, length - totalBytesRead)) != -1) {
        totalBytesRead += bytesRead;
    }
    if (totalBytesRead != length) {
        throw new IOException("Could not read requested length bytes starting from offset "+ offset);
    }
    return bytes;
}
