public Map<String, List<Object>> mergePersonAttributes(Map<String, List<Object>> toModify, Map<String, List<Object>> toAdd) {
    for (Map.Entry<String, List<Object>> entry : toAdd.entrySet()) {
        String key = entry.getKey();
        List<Object> value = entry.getValue();
        if (toModify.containsKey(key)) {
            List<Object> existingValue = toModify.get(key);
            existingValue.addAll(value);
        } else {
            toModify.put(key, value);
        }
    }
    return toModify;
