public String getSecuredAttribute(VaultBlock vaultBlock, String attributeName) throws Exception {
    if (!isVaultSessionStarted()) {
        throw new IllegalStateException("Vault session not started");
    }
    Map<String, String> securedAttributes = vaultBlock.getSecuredAttributes();
    if (securedAttributes.containsKey(attributeName)) {
        return securedAttributes.get(attributeName);
    } else {
        return null;
    }
}
