public int[] getTileGrid(double[] webMercatorBoundingBox, int zoom) {
    double lat1 = Math.atan(Math.sinh(Math.PI - (2 * Math.PI * webMercatorBoundingBox[3]) / Math.pow(2, zoom)));
    double lat2 = Math.atan(Math.sinh(Math.PI - (2 * Math.PI * webMercatorBoundingBox[1]) / Math.pow(2, zoom)));
    double lon1 = webMercatorBoundingBox[0] / Math.pow(2, zoom) * 360.0 - 180.0;
    double lon2 = webMercatorBoundingBox[2] / Math.pow(2, zoom) * 360.0 - 180.0;
    int x1 = (int) Math.floor((lon1 + 180.0) / 360.0 * Math.pow(2, zoom));
    int y1 = (int) Math.floor((1.0 - Math.log(Math.tan(lat1) + 1.0 / Math.cos(lat1)) / Math.PI) / 2.0 * Math.pow(2, zoom));
    int x2 = (int) Math.floor((lon2 + 180.0) / 360.0 * Math.pow(2, zoom));
    int y2 = (int) Math.floor((1.0 - Math.log(Math.tan(lat2) + 1.0 / Math.cos(lat2)) / Math.PI) / 2.0 * Math.pow(2, zoom));

    int[] tileGrid = new int[4];
    tileGrid[0] = Math.min(x1, x2); // min x
    tileGrid[1] = Math.min(y1, y2); // min y
    tileGrid[2] = Math.max(x1, x2); // max x
    tileGrid[3] = Math.max(y1, y2); // max y

    return tileGrid;
}
