public List<BuildConfig> depthFirstSearch(BuildConfig buildConfig) {
    List<BuildConfig> path = new ArrayList<>();
    Stack<BuildConfig> stack = new Stack<>();
    Set<BuildConfig> visited = new HashSet<>();
    stack.push(this);

    while(!stack.isEmpty()) {
        BuildConfig current = stack.pop();
        if(current.equals(buildConfig)) {
            path.add(current);
            return path;
        }
        visited.add(current);
        for(BuildConfig dependency : current.getDependencies()) {
            if(!visited.contains(dependency)) {
                stack.push(dependency);
            }
        }
    }
    path.add(this);
    return path;
}
