public void launchType(IJavaElement[] scope, String mode, String selectTitle, String emptyMessage) {
    IType[] types = null;
    try {
        types = JavaUI.getTypes(scope);
    } catch (JavaModelException e) {
        e.printStackTrace();
    }
    if (types == null || types.length == 0) {
        MessageDialog.openError(getShell(), selectTitle, emptyMessage);
        return;
    }
    IType type = null;
    if (types.length == 1) {
        type = types[0];
    } else {
        ElementListSelectionDialog dialog = new ElementListSelectionDialog(getShell(), new JavaElementLabelProvider(JavaElementLabelProvider.SHOW_DEFAULT));
        dialog.setTitle(selectTitle);
        dialog.setMessage(selectTitle);
        dialog.setElements(types);
        if (dialog.open() == Window.OK) {
            type = (IType) dialog.getFirstResult();
        }
    }
    if (type != null) {
        DebugUITools.launch(type, mode);
    }
}
