public static boolean checkSchemaNameAndNamespace(String schemaName, String namespace, String fileName, String filePath) {
    // Extract the file name without its extension
    String nameWithoutExtension = fileName.replaceFirst("[.][^.]+$", "");
    // Extract the last part of the file path (the directory containing the file)
    String directoryName = new File(filePath).getName();

    // Compare the extracted values with the given schema name and namespace
    if (nameWithoutExtension.equals(schemaName) && directoryName.equals(namespace)) {
        return true;
    } else {
        return false;
    }
}
