import java.io.IOException;
import java.net.URL;
import javax.xml.XMLConstants;
import javax.xml.transform.stream.StreamSource;
import javax.xml.validation.Schema;
import javax.xml.validation.SchemaFactory;
import javax.xml.validation.Validator;
import org.xml.sax.SAXException;

public static boolean validateXMLFromURL(URL url) throws SAXException {
    try {
        SchemaFactory schemaFactory = SchemaFactory.newInstance(XMLConstants.W3C_XML_SCHEMA_NS_URI);
        Schema schema = schemaFactory.newSchema(new StreamSource("schema.xsd")); //replace "schema.xsd" with your schema file name
        Validator validator = schema.newValidator();
        validator.validate(new StreamSource(url.openStream()));
        return true;
    } catch (IOException ioException) {
        ioException.printStackTrace();
        return false;
    } catch (SAXException saxException) {
        saxException.printStackTrace();
        throw saxException;
    }
}
