public void deliverPropertyChangeEvent(String key, Object oldValue, Object newValue) {
    PropertyChangeListener[] listeners = getPropertyChangeListeners(key);
    if (listeners != null && listeners.length > 0) {
        PropertyChangeEvent event = new PropertyChangeEvent(this, key, oldValue, newValue);
        for (PropertyChangeListener listener : listeners) {
            listener.propertyChange(event);
        }
    }
}
