public void startDocument(String rootNamespaceURI, String rootLocalName, Map<String, String> namespaces) {
    try {
        // check if processing instruction is needed
        boolean xmlPI = true; // set to true for simplicity, replace with actual logic
        if (xmlPI) {
            System.out.println("<?xml version=\"1.0\" encoding=\"UTF-8\"?>");
        }

        // start the root element
        StringBuilder sb = new StringBuilder();
        sb.append("<");
        if (!rootNamespaceURI.isEmpty()) {
            sb.append("{");
            sb.append(rootNamespaceURI);
            sb.append("}");
        }
        sb.append(rootLocalName);
        for (Map.Entry<String, String> entry : namespaces.entrySet()) {
            String prefix = entry.getKey();
            String uri = entry.getValue();
            sb.append(" xmlns");
            if (!prefix.isEmpty()) {
                sb.append(":");
                sb.append(prefix);
            }
            sb.append("=\"");
            sb.append(uri);
            sb.append("\"");
        }
        sb.append(">");
        System.out.println(sb.toString());
    } catch (Exception e) {
        e.printStackTrace();
    }
}
