public double estimateLocalIntrinsicDimensionality(Object ignore, Iterator it, double[] p) {
    int k = 10; // number of nearest neighbors to consider
    int n = 0; // count of neighbors that met the criteria
    double sum = 0.0;
    while (it.hasNext()) {
        Object x = it.next();
        if (x != ignore) {
            double[] distances = new double[k];
            int m = 0;
            Iterator it2 = it;
            while (it2.hasNext()) {
                Object y = it2.next();
                if (y != ignore) {
                    double dist = distance(x, y);
                    if (m < k) {
                        distances[m++] = dist;
                    } else {
                        int index = maxIndex(distances);
                        if (dist < distances[index]) {
                            distances[index] = dist;
                        }
                    }
                }
            }
            if (m == k) {
                double sumDistances = 0.0;
                for (int i = 0; i < k; i++) {
                    sumDistances += distances[i];
                }
                p[n++] = k / sumDistances;
                sum += Math.log(k / sumDistances);
            }
        }
    }
    double d = -sum / n + 1;
    return d;
}

