public static long[] extractRangeHeader(String rangeHeader) {
    long[] range = new long[2];
    if (rangeHeader == null || !rangeHeader.startsWith("bytes=")) {
        range[0] = 0;
        range[1] = 0;
        return range;
    }
    rangeHeader = rangeHeader.substring("bytes=".length());
    int dashIdx = rangeHeader.indexOf('-');
    if (dashIdx == -1) {
        range[0] = 0;
        range[1] = 0;
        return range;
    }
    try {
        range[0] = Long.parseLong(rangeHeader.substring(0, dashIdx));
    } catch (NumberFormatException ignored) {
        range[0] = 0;
    }
    try {
        range[1] = Long.parseLong(rangeHeader.substring(dashIdx + 1));
    } catch (NumberFormatException ignored) {
        range[1] = 0;
    }
    return range;
}
