import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.ArrayList;

public class TemplateEvaluator {

    public static class EvaluationResult {
        private String evaluatedTemplate;
        private List<String> evaluationErrors;

        public EvaluationResult(String evaluatedTemplate, List<String> evaluationErrors) {
            this.evaluatedTemplate = evaluatedTemplate;
            this.evaluationErrors = evaluationErrors;
        }

        public String getEvaluatedTemplate() {
            return evaluatedTemplate;
        }

        public List<String> getEvaluationErrors() {
            return evaluationErrors;
        }
    }

    public static EvaluationResult evaluateTemplate(String template, Map<String, Object> context, boolean urlEncode) {
        List<String> errors = new ArrayList<>();
        String evaluatedTemplate = template;

        for (Map.Entry<String, Object> entry : context.entrySet()) {
            String key = "@(" + entry.getKey() + ")";
            Object value = entry.getValue();
            String valueStr = (value != null) ? value.toString() : "";
            if (urlEncode) {
                valueStr = java.net.URLEncoder.encode(valueStr);
            }
            if (evaluatedTemplate.contains(key)) {
                evaluatedTemplate = evaluatedTemplate.replace(key, valueStr);
            } else {
                errors.add("Template does not contain key: " + key);
            }
        }

        return new EvaluationResult(evaluatedTemplate, errors);
    }

}
