public StatementExecutor getStatementExecutor(String statement, DBInstance db) throws SQLException {
    StatementExecutor executor = null;
    if (db != null) {
        // Check if the cached instance exists
        executor = db.getFromCache(statement);
    }
    if (executor == null) {
        // Parse and create a new instance
        PreparedStatement pstmt = db.getConnection().prepareStatement(statement);
        executor = StatementExecutor.create(pstmt);
        if (db != null) {
            // Put new instance into cache
            db.putIntoCache(statement, executor);
        }
    }
    return executor;
}
