public Token consume(TokenType... expected) throws UnexpectedTokenException {
    Token nextToken = getNextToken();

    for (TokenType type : expected) {
        if (nextToken.getType() == type) {
            return nextToken;
        }
    }

    throw new UnexpectedTokenException("Unexpected token type: " + nextToken.getType());
}
