public static Class<?> getReturnType(String methodDescriptor) {
    int index = methodDescriptor.lastIndexOf(")") + 1;
    String returnType = methodDescriptor.substring(index);

    switch (returnType) {
        case "B":
            return byte.class;
        case "C":
            return char.class;
        case "D":
            return double.class;
        case "F":
            return float.class;
        case "I":
            return int.class;
        case "J":
            return long.class;
        case "S":
            return short.class;
        case "Z":
            return boolean.class;
        case "V":
            return void.class;
        default:
            try {
                return Class.forName(returnType.replace("/", "."));
            } catch (ClassNotFoundException e) {
                e.printStackTrace();
                return null;
            }
    }
}
