import javax.lang.model.type.TypeMirror;
import java.util.Map;

public TypeReference resolveTypeReference(TypeMirror mirror, Map<TypeMirror, TypeReference> boundTypes) {
    TypeReference result = null;
    if (mirror instanceof TypeVariable) {
        TypeVariable variable = (TypeVariable) mirror;
        result = boundTypes.get(variable);
        if (result == null) {
            result = new TypeReference(variable);
            boundTypes.put(variable, result);
            result.setReferencedType(resolveTypeReference(variable.getUpperBound(), boundTypes));
        }
    } else if (mirror instanceof DeclaredType) {
        DeclaredType declaredType = (DeclaredType) mirror;
        Element element = declaredType.asElement();
        result = new TypeReference(element);
        List<TypeReference> typeArgs = new ArrayList<>();
        for (TypeMirror typeArg : declaredType.getTypeArguments()) {
            typeArgs.add(resolveTypeReference(typeArg, boundTypes));
        }
        result.setTypeArguments(typeArgs);
    } else if (mirror instanceof ArrayType) {
        ArrayType arrayType = (ArrayType) mirror;
        TypeReference referent = resolveTypeReference(arrayType.getComponentType(), boundTypes);
        result = new ArrayTypeReference(referent);
    } else if (mirror instanceof PrimitiveType) {
        PrimitiveType primitiveType = (PrimitiveType) mirror;
        result = new TypeReference(primitiveType.getKind().toString());
    } else if (mirror instanceof VoidType) {
        result = TypeReference.VOID;
    }
    return result;
}
