public int compareVersions(String version) {
   String[] versionParts = version.split("\\."); // Splitting the string version by '.' and creating an array of parts
   int major = Integer.parseInt(versionParts[0]); // First part of the array is the major version
   int minor = Integer.parseInt(versionParts[1]); // Second part of the array is the minor version
   int revision = Integer.parseInt(versionParts[2]); // Third part of the array is the revision version

   if (this.major != major) { // Comparison of major versions
      return Integer.compare(this.major, major);
   }
   if (this.minor != minor) { // Comparison of minor versions
      return Integer.compare(this.minor, minor);
   }
   if (this.revision != revision) { // Comparison of revision versions
      return Integer.compare(this.revision, revision);
   }

   // If all versions are the same
   return this.toString().compareTo(version);
}
