public List<String> getAllIdentifiers(String owner, String repository) throws Exception {
    RepositoryService repoService = new RepositoryService();
    Repository repo = repoService.getRepository(owner, repository);
    CommitService commitService = new CommitService();
    List<RepositoryCommit> commits = commitService.getCommits(repo);

    List<String> identifiers = new ArrayList<>();
    for (RepositoryCommit commit : commits) {
        String author = commit.getAuthor().getLogin();
        if (!identifiers.contains(author)) {
            identifiers.add(author);
        }
    }
    return identifiers;
}
