import com.docuverse.luceneplus.LucenePDFConfiguration;
import com.docuverse.luceneplus.PdfxStreamDocument;

import org.apache.lucene.document.Document;

public class PdfToLuceneConverter {
    public static Document createLuceneDocument(PdfxStreamDocument pdfxStreamDoc) {
        LucenePDFConfiguration config = new LucenePDFConfiguration();
        Document luceneDoc = new Document();

        if (pdfxStreamDoc.hasText()) {
            luceneDoc.add(config.getTextField(pdfxStreamDoc.getText()));
        }

        if (pdfxStreamDoc.hasMetadata()) {
            luceneDoc.add(config.getPublicationDateField(pdfxStreamDoc.getPublicationDate()));
            luceneDoc.add(config.getAuthorField(pdfxStreamDoc.getAuthor()));
            luceneDoc.add(config.getTitleField(pdfxStreamDoc.getTitle()));
            luceneDoc.add(config.getKeywordsField(pdfxStreamDoc.getKeywords()));
            luceneDoc.add(config.getSummaryField(pdfxStreamDoc.getSummary()));
        }

        return luceneDoc;
    }
}
