public static double sin(double xa, double xb) {
    double[] coeffs = {
            -1.6666586697E-1,
            8.333331447E-3,
            -1.984126965E-4,
            2.755731579E-6,
            -2.505075968E-8,
            1.589691017E-10
    };

    double x = xa + xb;
    int sign = 1;
    if (x < 0) {
        x = -x;
        sign = -1;
    }
    int quadrant = (int) (x / (Math.PI / 2));
    switch (quadrant) {
        case 0:
        case 4:
            break;
        case 1:
            x = Math.PI - x;
            break;
        case 2:
            x -= Math.PI;
            break;
        case 3:
            sign = -sign;
            x = -x - Math.PI;
            break;
        default:
            return Double.NaN;
    }

    if (x > Math.PI / 4) {
        x = Math.PI / 2 - x;
    }
    double xa3 = x * x * x;
    double xa5 = xa3 * x * x;
    double result = (coeffs[0] * xa5) + xa3;
    result = result * x;
    result = result + xa;
    result = result * sign;
    return result;
}
