public static int convertIntervalToSeconds(int interval, String unit) {
    int seconds = -1;
    switch (unit.toLowerCase()) {
        case "second":
        case "seconds":
            seconds = interval;
            break;
        case "minute":
        case "minutes":
            seconds = interval * 60;
            break;
        case "hour":
        case "hours":
            seconds = interval * 60 * 60;
            break;
        case "day":
        case "days":
            seconds = interval * 60 * 60 * 24;
            break;
        default:
            System.out.println("Error: unsupported unit");
    }
    return seconds;
}
