        throw new IllegalArgumentException("Resource group name cannot be null or empty");
    }
    if (vmScaleSetName == null || vmScaleSetName.isEmpty()) {
        throw new IllegalArgumentException("VM scale set name cannot be null or empty");
    }

    return Observable.fromCallable(() -> {
        List<String> vmIds = new ArrayList<>();

        // Code to get the virtual machine ids in the scale set

        ComputeManagementClient computeClient = new ComputeManagementClientImpl();
        for (String vmId : vmIds) {
            computeClient.virtualMachines().restartAsync(resourceGroupName, vmId);
        }

        return new Object(); // Change return type as per your requirements
    });
}
