public int intersect(int[] set1, int length1, int[] set2, int length2, int[] buffer) {
    int i = 0;
    int j = 0;
    int k = 0;
    int count = 0;

    while (i < length1 && j < length2) {
        if (set1[i] < set2[j]) {
            i++;
        } else if (set1[i] > set2[j]) {
            j++;
        } else {
            buffer[k++] = set1[i];
            i++;
            j++;
            count++;
        }
    }

    return count;
}
