public void runJob(JobConfig config, int attempts, AlluxioConf alluxioConf) throws Exception {
    int tryCount = 0;
    Exception lastException = null;
    while (tryCount < attempts) {
        try {
            Job job = JobUtils.createJob(config, alluxioConf);
            job.run();
            return;
        } catch (Exception e) {
            tryCount++;
            lastException = e;
            Thread.sleep(1000 * tryCount);
        }
    }
    throw new Exception("Failed to run the job after " + attempts + " attempts.", lastException);
}
