import java.lang.reflect.Constructor;
import java.lang.reflect.Method;
import java.lang.reflect.Type;
import java.util.Arrays;

public static Type[] resolvedGenericParameterTypes(Method methodOrConstructor) {
    Type[] parameterTypes = methodOrConstructor.getGenericParameterTypes();
    TypeVariable<?>[] typeParameters = null;
    Class<?> declaringClass = methodOrConstructor.getDeclaringClass();
    if (methodOrConstructor instanceof Constructor) {
        typeParameters = declaringClass.getTypeParameters();
    } else {
        typeParameters = ((Method) methodOrConstructor).getTypeParameters();
    }
    if (typeParameters.length == 0) {
        return parameterTypes;
    }
    Type[] resolvedTypes = new Type[parameterTypes.length];
    Class<?> superClass = declaringClass.getSuperclass();
    Type[] superTypeArgs = null;
    if (superClass != null) {
        superTypeArgs = resolvedGenericParameterTypes(getMatchingAccessibleMethod(superClass, methodOrConstructor));
    }
    for (int i = 0; i < parameterTypes.length; i++) {
        Type parameterType = parameterTypes[i];
        if (parameterType instanceof TypeVariable) {
            TypeVariable<?> typeVariable = (TypeVariable<?>) parameterType;
            Type resolvedType = null;
            if (declaringClass.equals(typeVariable.getGenericDeclaration())) {
                resolvedType = typeParameters[typeVariable.getBounds().length - 1];
            } else {
                if (declaringClass.isAssignableFrom(superClass)) {
                    resolvedType = resolveTypeVariable(superTypeArgs, typeVariable);
                }
            }
            if (resolvedType != null) {
                resolvedTypes[i] = resolvedType;
                continue;
            }
        }
    resolvedTypes[i] = parameterType;
    }
    return resolvedTypes;
}

