public List<Integer> extractExonBoundaries(List<Integer> chromPos) {
    List<Integer> exonBoundaries = new ArrayList<>();

    for (int i = 0; i < chromPos.size() - 1; i++) {
        int currentPosition = chromPos.get(i);
        int nextPosition = chromPos.get(i + 1);

        if (nextPosition - currentPosition > 1) {
            exonBoundaries.add((currentPosition + 1) / 3);
            exonBoundaries.add((nextPosition - 1) / 3);
        }
    }

    return exonBoundaries;
}
