public static int binarySearch(int[][] matrix, int i, int j) {
    int start = 0;
    int end = matrix.length - 1;
    int colLen = matrix[0].length;

    while (start <= end) {
        int mid = start + (end - start) / 2;
        int val = matrix[mid][0];

        if (val == i) {
            return matrix[mid][j];
        } else if (val < i) {
            start = mid + 1;
        } else {
            end = mid - 1;
        }
    }

    return matrix[start - 1][j];
}
