public static String getMimeValue(String name, String delimiter) {
  String[] parts = name.split(delimiter);
  String extension = parts[parts.length - 1];
  String mimeValue = ""; //Default value if extension is not supported

  switch (extension) {
    case "pdf":
      mimeValue = "application/pdf";
      break;
    case "doc":
    case "docx":
      mimeValue = "application/msword";
      break;
    case "xls":
      mimeValue = "application/vnd.ms-excel";
      break;
    case "xlsx":
      mimeValue = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";
      break;
    case "ppt":
      mimeValue = "application/vnd.ms-powerpoint";
      break;
    case "pptx":
      mimeValue = "application/vnd.openxmlformats-officedocument.presentationml.presentation";
      break;
    case "txt":
      mimeValue = "text/plain";
      break;
    case "png":
      mimeValue = "image/png";
      break;
    case "jpg":
    case "jpeg":
      mimeValue = "image/jpeg";
      break;
    case "gif":
      mimeValue = "image/gif";
      break;
    default:
      //Extension not supported
      break;
  }

  return mimeValue;
}
