import java.util.zip.CRC32;

public String getPrintableVarBinary(byte[] bin) {
    CRC32 crc = new CRC32();
    crc.update(bin);
    long crcValue = crc.getValue();
    String hexValue = bytesToHex(bin);
    if (hexValue.length() > 13) {
        hexValue = hexValue.substring(0, 10) + "...";
    }
    return "bin[crc:" + crcValue + ",value:0x" + hexValue + "]";
}

private String bytesToHex(byte[] bytes) {
    StringBuilder sb = new StringBuilder();
    for (byte b : bytes) {
        sb.append(String.format("%02x", b));
    }
    return sb.toString();
}
