public static Tuple addValueToTuple(Tuple t0, double value, Tuple result) {
    if (t0.getSize() != result.getSize()) {
        throw new IllegalArgumentException("Tuple sizes do not match");
    }
    for (int i = 0; i < t0.getSize(); i++) {
        result.set(i, t0.get(i) + value);
    }
    return result;
}
