public static double[] symmetryPreservingScaleFactors(double[] rowValue, int[] rowPtr, int[] colIndex, int rowCount, int colCount) {
    double[] scalingFactors = new double[rowCount];
    Arrays.fill(scalingFactors, 1.0);

    for (int i = 0; i < rowCount; ++i) {
        double diagonalValue = 0.0;

        for (int j = rowPtr[i]; j < rowPtr[i + 1]; ++j) {
            if (colIndex[j] == i) {
                diagonalValue = rowValue[j];
                break;
            }
        }

        for (int j = rowPtr[i]; j < rowPtr[i + 1]; ++j) {
            int k = colIndex[j];
            double value = rowValue[j];

            for (int l = rowPtr[k]; l < rowPtr[k + 1]; ++l) {
                if (colIndex[l] == k) {
                    double symmetricValue = rowValue[l];

                    if (diagonalValue != 0.0 && symmetricValue != 0.0) {
                        double factor = Math.sqrt(Math.abs(value * symmetricValue) / diagonalValue);
                        scalingFactors[i] = Math.min(scalingFactors[i], factor);
                        scalingFactors[k] = Math.min(scalingFactors[k], factor);
                    }
                }
            }
        }
    }

    return scalingFactors;
}
