public static <T> Function<Object[], T> builder(Function<T, Object[]> builderFunction) {
    return args -> {
        T instance = null;
        try {
            instance = (T) args[0];
        } catch (ClassCastException e) {
            throw new IllegalArgumentException("The first argument must be an instance of the class created by the builder");
        }
        Object[] argsWithoutInstance = Arrays.copyOfRange(args, 1, args.length);
        return builderFunction.apply(instance, argsWithoutInstance);
    };
}
