public synchronized void grantLock(Object obj, int txNum) throws InterruptedException {
  LockObject lock = lockTable.get(obj);
  if (lock == null) {
    lock = new LockObject();
    lockTable.put(obj, lock);
  }
  else if (lock.hasConflict(txNum)) {
    wait();
  }
  lock.grant(txNum);
}
