public static void normalizeRectangle(Rectangle rect) {
    if (rect.getMinX() > rect.getMaxX()) {
        double tempX = rect.getMinX();
        rect.setMinX(rect.getMaxX());
        rect.setMaxX(tempX);
    }
    if (rect.getMinY() > rect.getMaxY()) {
        double tempY = rect.getMinY();
        rect.setMinY(rect.getMaxY());
        rect.setMaxY(tempY);
    }
}
