public static String combineWorksheets(String w1FileName, String w2FileName, String delimiter, boolean secondSheetMetaData) throws Exception {
    // read first worksheet into a list of strings
    List<String> w1Lines = Files.readAllLines(Paths.get(w1FileName), StandardCharsets.UTF_8);

    // map the first worksheet into a list of string arrays using the delimiter
    List<String[]> w1Rows = w1Lines.stream()
            .map(line -> line.split(delimiter))
            .collect(Collectors.toList());

    // read second worksheet into a list of strings
    List<String> w2Lines = Files.readAllLines(Paths.get(w2FileName), StandardCharsets.UTF_8);

    // map the second worksheet into a list of string arrays using the delimiter
    List<String[]> w2Rows = w2Lines.stream()
            .map(line -> line.split(delimiter))
            .collect(Collectors.toList());

    // create map of the rows from the second worksheet using the first column as key
    Map<String, String[]> w2Map = new HashMap<>();
    for (String[] row : w2Rows) {
        w2Map.put(row[0], row);
    }

    // create new list of string arrays for the combined worksheet
    List<String[]> combinedRows = new ArrayList<>();

    // loop over rows from the first worksheet
    for (String[] row1 : w1Rows) {
        String[] combinedRow = new String[row1.length + (secondSheetMetaData ? 1 : 0)];
        boolean foundInW2 = false;

        // check if row exists in second worksheet, and if so, merge it with the first row
        if (w2Map.containsKey(row1[0])) {
            String[] row2 = w2Map.get(row1[0]);
            System.arraycopy(row1, 0, combinedRow, 0, row1.length);
            System.arraycopy(row2, 1, combinedRow, row1.length, row2.length-1);
            foundInW2 = true;
        } else {
            System.arraycopy(row1, 0, combinedRow, 0, row1.length);
        }

        // add meta data column if second worksheet is meta data and row was not found
        if (secondSheetMetaData && !foundInW2) {
            combinedRow[row1.length] = "";
        }

        combinedRows.add(combinedRow);
    }

    // create new file for combined worksheet and save the rows
    String combinedFileName = "combined.csv";
    try (CSVWriter writer = new CSVWriter(new FileWriter(combinedFileName))) {
        for (String[] row : combinedRows) {
            writer.writeNext(row);
        }
    }

    return combinedFileName;
}
