public String overrideTransliterator(boolean escapeUnprintable) {
    String ruleString = "";
    Transliterator tempTransliterator = new Transliterator();
    try {
        ruleString = tempTransliterator.toRules();
        if (escapeUnprintable) {
            StringBuilder escapedString = new StringBuilder();
            for (char c : ruleString.toCharArray()) {
                if (c < 0x20 || c > 0x7E) {
                    escapedString.append(String.format("\\u%04x", (int) c));
                } else {
                    escapedString.append(c);
                }
            }
            ruleString = escapedString.toString();
        }
    } catch (IllegalArgumentException e) {
        e.printStackTrace();
    }
    return ruleString;
}
