public JsonParser createJsonParser(CoronaConf conf) throws IOException {
    Path stateFilePath = Paths.get(conf.getStateFile());
    ObjectMapper mapper = new ObjectMapper();
    JsonParser parser = mapper.getFactory().createParser(Files.newBufferedReader(stateFilePath));
