public boolean isPINodeWellFormed(String data) {
    if (data == null || data.isEmpty()) {
        return false;
    }
    String regex = "^[a-zA-Z_][a-zA-Z0-9._-]*$";
    Pattern pattern = Pattern.compile(regex);
    Matcher matcher = pattern.matcher(data);
    return matcher.matches();
}
