@Deprecated
public void startWatchingFile(String file, FileWatcher watcher) {
    Path path = Paths.get(file);
    try {
        WatchService watchService = FileSystems.getDefault().newWatchService();
        path.register(watchService, StandardWatchEventKinds.ENTRY_MODIFY, StandardWatchEventKinds.ENTRY_DELETE, StandardWatchEventKinds.ENTRY_CREATE);

        Thread th = new Thread(() -> {
            while (true) {
                WatchKey key;
                try {
                    key = watchService.take();
                } catch (InterruptedException ex) {
                    return;
                }

                for (WatchEvent<?> event : key.pollEvents()) {
                    if (event.kind() == StandardWatchEventKinds.OVERFLOW) {
                        continue;
                    }

                    WatchEvent<Path> ev = (WatchEvent<Path>) event;
                    Path filename = ev.context();
                    if (filename.toString().equals(path.getFileName().toString())) {
                        watcher.onUpdate(path);
                    }
                }

                if (!key.reset()) {
                    return;
                }
            }
        });
        th.setDaemon(true);
        th.start();
    } catch (IOException ex) {
        ex.printStackTrace();
    }
}
