public Dashboard findDashboard(EntityManager em, String dashboardName, Owner owner) {
    if (dashboardName == null || dashboardName.isEmpty() || owner == null) {
        return null;
    }
    String query = "SELECT d FROM Dashboard d WHERE d.dashboardName = :dashboardName and d.owner = :owner";
    TypedQuery<Dashboard> typedQuery = em.createQuery(query, Dashboard.class);
    typedQuery.setParameter("dashboardName", dashboardName);
    typedQuery.setParameter("owner", owner);
    try {
        return typedQuery.getSingleResult();
    } catch (NoResultException e) {
        return null;
    }
}
