import java.util.Iterator;

public class FilterIterable<T> implements Iterable<T> {

    private Iterable<T> fromIterable;
    private Predicate<T> predicate;

    public FilterIterable(Iterable<T> fromIterable, Predicate<T> predicate) {
        this.fromIterable = fromIterable;
        this.predicate = predicate;
    }

    public Iterator<T> iterator() {

        final Iterator<T> iter = fromIterable.iterator();

        return new Iterator<T>() {

            T next = null;

            public boolean hasNext() {
                while (next == null && iter.hasNext()) {
                    T element = iter.next();
                    if (predicate.test(element)) {
                        next = element;
                    }
                }
                return next != null;
            }

            public T next() {
                if (!hasNext()) {
                    throw new NoSuchElementException();
                }
                T element = next;
                next = null;
                return element;
            }

            public void remove() {
                throw new UnsupportedOperationException();
            }
        };
    }
}
