public void addCommentTags(Element element, String tags, boolean depr, boolean first, DocumentationTree htmltree) {
  String commentTags = "";
  if (depr) {
    commentTags += "<@deprecated>" + System.lineSeparator();
  }
  if (first && !tags.isEmpty()) {
    commentTags += "<@firstSentence>" + tags + "</@firstSentence>" + System.lineSeparator();
  }
  commentTags += "<@body>" + System.lineSeparator() + "</@body>" + System.lineSeparator();

  htmltree.addComment(element, commentTags);
}
