public void logException(String level, Exception exception) {
    // log the exception with the provided severity level
    switch(level) {
        case "DEBUG":
            // log as debug
            logger.debug(exception.getMessage(), exception);
            break;
        case "INFO":
            // log as info
            logger.info(exception.getMessage(), exception);
            break;
        case "WARN":
            // log as warning
            logger.warn(exception.getMessage(), exception);
            break;
        case "ERROR":
            // log as error
            logger.error(exception.getMessage(), exception);
            break;
        case "FATAL":
            // log as fatal
            logger.fatal(exception.getMessage(), exception);
            break;
        default:
            // log as info by default
            logger.info(exception.getMessage(), exception);
            break;
    }
}
