public void checkAndReclaim(Map<String, WeakReference<Object>> nameMap) {
    Iterator<Map.Entry<String, WeakReference<Object>>> iterator = nameMap.entrySet().iterator();
    while (iterator.hasNext()) {
        Map.Entry<String, WeakReference<Object>> entry = iterator.next();
        if (entry.getValue().get() == null) {
            iterator.remove();
        }
    }
}
