public static void shutdownExecutorServices(long timeout, TimeUnit unit, ExecutorService... executorServices) {
    try {
        // init the shutdown process gracefully
        for (ExecutorService executorService : executorServices) {
            executorService.shutdown();
        }

        // wait until all executor services are terminated
        for (ExecutorService executorService : executorServices) {
            if (!executorService.awaitTermination(timeout, unit)) {
                // we need to hard shutdown the executor service since it didn't terminate in the given timeout
                executorService.shutdownNow();
            }
        }
    } catch (InterruptedException e) {
        // (re-)cancel the executor services on interrupt
        for (ExecutorService executorService : executorServices) {
            executorService.shutdownNow();
        }
        Thread.currentThread().interrupt();
    }
}
