public static void writeStaticField(Field field, Object value) throws IllegalAccessException {
    if (field == null || !Modifier.isStatic(field.getModifiers())) {
        throw new IllegalArgumentException("Field cannot be null and must be static.");
    }
    if (!field.isAccessible()) {
        field.setAccessible(true);
    }
    if (Modifier.isFinal(field.getModifiers())) {
        throw new IllegalAccessException("Field is final and cannot be modified.");
    }
    if (!field.getType().isAssignableFrom(value.getClass())) {
        throw new IllegalArgumentException("Value is not assignable to the field.");
    }
    field.set(null, value);
}
