public void createOrUpdateBatchTables(Connection conn) throws SQLException {
    String[] tableNames = {"table1", "table2", "table3"}; // Example table names

    try (Statement stmt = conn.createStatement()) {
        for (String tableName : tableNames) {
            String sql = "SELECT 1 FROM " + tableName + " WHERE 1 = 0";
            try {
                stmt.executeQuery(sql);
            } catch (SQLException e) {
                // Table does not exist, so create it
                String createSql = "CREATE TABLE " + tableName + " (id INT PRIMARY KEY)";
                stmt.executeUpdate(createSql);
            }
        }
    }
}
