public void testMPJWTWithNoMpJwtFeatureAndNoAppLoginConfig() throws Exception {
    //Check if login-config is set to MP-JWT
    InputStream webXml = Thread.currentThread().getContextClassLoader().getResourceAsStream("WEB-INF/web.xml");
    boolean isMpJwtConfigured = false;
    if (webXml != null) {
        Document document = DocumentBuilderFactory.newInstance().newDocumentBuilder().parse(webXml);
        NodeList loginConfigList = document.getElementsByTagName("login-config");
        for (int i = 0; i < loginConfigList.getLength(); i++) {
            Node loginConfig = loginConfigList.item(i);
            if (loginConfig != null && loginConfig.getFirstChild() != null) {
                String authMethod = loginConfig.getFirstChild().getNodeValue().trim();
                if ("MP-JWT".equals(authMethod)) {
                    isMpJwtConfigured = true;
                    break;
                }
            }
        }
    }
    if (isMpJwtConfigured) {
        //If the mpJwt feature is not enabled
        if (System.getProperty("mp.jwt.verify.publickey.location") == null) {
            //Throw exception with 401 status
            throw new Exception("Unauthorized Access: 'mpJwt' feature is not enabled");
        }
    } else { //If there is no login-config in the app
        //Throw exception with 401 status
        throw new Exception("Unauthorized Access: login-config does not exist in the app");
    }
}
