import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.Map;

public class GetRequest {
    public static Response makeGetRequest(String url, String query, Map<String, String> headers, int connectTimeOut, int readTimeOut) throws HttpException {
        try {
            if (url == null || url.isEmpty()) {
                throw new HttpException("Invalid URL");
            }
            if (connectTimeOut <= 0) {
                throw new HttpException("Connect timeout must be greater than zero");
            }
            if (readTimeOut <= 0) {
                throw new HttpException("Read timeout must be greater than zero");
            }
            if (query != null && !query.isEmpty()) {
                url += "?" + query;
            }

            URL obj = new URL(url);
            HttpURLConnection con = (HttpURLConnection) obj.openConnection();

            con.setRequestMethod("GET");

            if (headers != null && !headers.isEmpty()) {
                for (Map.Entry<String, String> entry : headers.entrySet()) {
                    con.setRequestProperty(entry.getKey(), entry.getValue());
                }
            }

            con.setConnectTimeout(connectTimeOut);
            con.setReadTimeout(readTimeOut);

            int responseCode = con.getResponseCode();

            BufferedReader in = new BufferedReader(new InputStreamReader(con.getInputStream()));
            String inputLine;
            StringBuffer response = new StringBuffer();

            while ((inputLine = in.readLine()) != null) {
                response.append(inputLine);
            }
            in.close();

            return new Response(responseCode, response.toString());

        } catch (Exception e) {
            throw new HttpException("Error while making HTTP GET request: " + e.getMessage());
        }
    }
}

class Response {
    int responseCode;
    String responseMsg;

    public Response(int responseCode, String responseMsg) {
        this.responseCode = responseCode;
        this.responseMsg = responseMsg;
    }

    public int getResponseCode() {
        return responseCode;
    }

    public void setResponseCode(int responseCode) {
        this.responseCode = responseCode;
    }

    public String getResponseMsg() {
        return responseMsg;
    }

    public void setResponseMsg(String responseMsg) {
        this.responseMsg = responseMsg;
    }
}

class HttpException extends Exception {
    public HttpException(String message) {
        super(message);
    }
}
