import java.lang.reflect.Method;
import java.lang.reflect.Parameter;

public MethodParameterInfo[] getMethodParameterInfo(Method method) {
    Parameter[] parameters = method.getParameters();
    MethodParameterInfo[] parameterInfoArray = new MethodParameterInfo[parameters.length];
    for (int i = 0; i < parameters.length; i++) {
        Parameter parameter = parameters[i];
        String parameterName = parameter.getName();
        Class<?> parameterType = parameter.getType();
        MethodParameterInfo parameterInfo = new MethodParameterInfo(parameterName, parameterType);
        parameterInfoArray[i] = parameterInfo;
    }
    return parameterInfoArray;
}
