      return "D";  
    } else if (postag.startsWith("A")) {
      return "G";  
    } else if (postag.startsWith("NC")) {
      return "N";  
    } else if (postag.startsWith("NP")) {
      return "R";  
    } else if (postag.startsWith("SP")) {
      return "P";  
    } else if (postag.startsWith("P")) {
      return "Q";  
    } else if (postag.startsWith("V")) {
      return "V";  
    } else {
      return "O";  
    }
