public List<LoadBalancer> findLoadBalancers(String loadBalancerId) throws CloudException, InternalException {
    if (loadBalancerId != null) {
        // find a single load balancer by id
        LoadBalancer loadBalancer = cloudProvider.getLoadBalancerSupport().getLoadBalancer(loadBalancerId);
        if (loadBalancer != null) {
            return Collections.singletonList(loadBalancer);
        }
        else {
            return Collections.emptyList();
        }
    }
    else {
        // find all load balancers
        return cloudProvider.getLoadBalancerSupport().listLoadBalancers();
    }
}
