public class SentenceIterator implements Iterable<String> {
    private String sentence;

    public SentenceIterator(String sentence) {
        this.sentence = sentence;
    }

    @Override
    public Iterator<String> iterator() {
        return new Iterator<String>() {
            int currentPosition = 0;

            @Override
            public boolean hasNext() {
                return currentPosition < sentence.length();
            }

            @Override
            public String next() {
                StringBuilder word = new StringBuilder();
                while (currentPosition < sentence.length() && sentence.charAt(currentPosition) != ' ') {
                    word.append(sentence.charAt(currentPosition++));
                }
                currentPosition++;
                return word.toString();
            }
        };
    }
}
