public static MimeBodyPart addContentDispositionHeaderToStream(Object context, String pid, String dsID, boolean download, String asOfDateTime, InputStream stream) throws Exception {
    DataSource ds = new InputStreamDataSource(stream, MimeTypes.getMIMEType(dsID));
    DataHandler dh = new DataHandler(ds);
    MimeBodyPart mp = new MimeBodyPart();
    String fileName = pid + "." + dsID;
    fileName = fileName.replaceAll("[^\\p{ASCII}]", "").replaceAll("\\s+", "-").replaceAll("&", "-").replaceAll("#", "-");
    if (StringUtils.isNotBlank(asOfDateTime)) {
        fileName = asOfDateTime + "_" + fileName;
    }
    mp.setDataHandler(dh);
    if (download) {
        mp.setDisposition(MimeBodyPart.ATTACHMENT);
        mp.setFileName(MimeUtility.encodeText(fileName, "UTF-8", "B"));
    } else {
        mp.setDisposition(MimeBodyPart.INLINE);
    }
    return mp;
}

