public static boolean isDeprecated(Method method) {
    if (method.isAnnotationPresent(Deprecated.class)) {
        return true;
    }

    Class<?> declaringClass = method.getDeclaringClass();
    if (declaringClass.isAnnotationPresent(Deprecated.class)) {
        return true;
    }

    for (Class<?> interfaceClass : declaringClass.getInterfaces()) {
        try {
            Method interfaceMethod = interfaceClass.getMethod(method.getName(), method.getParameterTypes());
            if (isDeprecated(interfaceMethod)) {
                return true;
            }
        } catch (NoSuchMethodException e) {
            // Not in this interface, move on.
        }
    }

    Class<?> superClass = declaringClass.getSuperclass();
    if (superClass != null) {
        try {
            Method superMethod = superClass.getMethod(method.getName(), method.getParameterTypes());
            if (isDeprecated(superMethod)) {
                return true;
            }
        } catch (NoSuchMethodException e) {
            // Not in the superclass, move on.
        }
    }

    return false;
}
