public String getCurrentEventDescription(XmlPullParser reader) throws XmlPullParserException, IOException {
    String result = "";
    int eventType = reader.getEventType();
    switch (eventType) {
        case XmlPullParser.START_DOCUMENT:
            result = "Start document";
            break;
        case XmlPullParser.END_DOCUMENT:
            result = "End document";
            break;
        case XmlPullParser.START_TAG:
            result = "Start tag: " + reader.getName();
            break;
        case XmlPullParser.END_TAG:
            result = "End tag: " + reader.getName();
            break;
        case XmlPullParser.TEXT:
            result = "Text: " + reader.getText();
            break;
        default:
            result = "Unknown event type " + eventType;
            break;
    }
    return result;
}
