public String replaceEnvVariables(String val) {
   String pattern = "\\$\\{(.+?)\\}";
   Pattern regex = Pattern.compile(pattern);
   Matcher regexMatcher = regex.matcher(val);
   StringBuffer buffer = new StringBuffer();

   while (regexMatcher.find()) {
      String envVariable = System.getenv(regexMatcher.group(1));

      if (envVariable!=null) {
         regexMatcher.appendReplacement(buffer, envVariable);
      }
   }

   regexMatcher.appendTail(buffer);
   return buffer.toString();
}
