public LogInfoSummary createCustomLogInfoSummary(EventLog log, EventClassifier defaultClassifier) {
    // Initialize new LogInfoSummary object
    LogInfoSummary summary = new LogInfoSummary();
    // Set custom event classifier for the summary
    summary.setEventClassifier(defaultClassifier);
    // Populate log info fields based on the provided event log
    summary.setLogStartTime(log.getStartTime());
    summary.setLogEndTime(log.getEndTime());
    summary.setTotalEvents(log.getTotalEvents());
    summary.setInfoEvents(log.getInfoEvents());
    summary.setWarningEvents(log.getWarningEvents());
    summary.setErrorEvents(log.getErrorEvents());
    // Return the completed LogInfoSummary object
    return summary;
}
