public void addPostParamsToRequest(HttpServletRequest request) {
    // Assuming the post parameters are already present in the request object
    // Loop through the parameter names and add each parameter to the request object
    Enumeration<String> parameterNames = request.getParameterNames();
    while(parameterNames.hasMoreElements()) {
        String paramName = parameterNames.nextElement();
        String[] paramValues = request.getParameterValues(paramName);
        for (String paramValue : paramValues) {
            request.setAttribute(paramName, paramValue);
        }
    }
}
