import java.util.Iterator;
import java.util.Comparator;

public class SubRangeIterator<V> implements Iterator<V> {
    private SortedBTree<V> btree;
    private Comparator<V> comparator;
    private V start, end;
    private boolean forwards;
    private Iterator<V> iterator;

    public SubRangeIterator(SortedBTree<V> btree, Comparator<V> comparator, V start, V end, boolean forwards) {
        this.btree = btree;
        this.comparator = comparator;
        this.start = start;
        this.end = end;
        this.forwards = forwards;
        iterator = btree.iterator();
    }

    @Override
    public boolean hasNext() {
        // Return true if there are more nodes in the sub-range
        V node = getNextNode();
        if (node == null) {
            return false;
        }
        if (comparator.compare(node, end) <= 0) {
            return true;
        }
        return false;
    }

    @Override
    public V next() {
        // Get next node in the sub-range
        return getNextNode();
    }

    private V getNextNode() {
        // Get next node that is in the sub-range
        if (forwards) {
            while (iterator.hasNext()) {
                V node = iterator.next();
                if (comparator.compare(node, start) >= 0) {
                    return node;
                }
            }
        } else {
            while (iterator.hasNext()) {
                V node = iterator.next();
                if (comparator.compare(node, end) > 0) {
                    continue;
                }
                if (comparator.compare(node, start) < 0) {
                    return null;
                } else {
                    return node;
                }
            }
        }
        return null;
    }
}
