public ObjectName createObjectNameFromJmxResource(Annotation jmxResource, Object obj) throws IllegalArgumentException {
    String jmxName = ((JmxResource) jmxResource).value();
    StringBuilder nameBuilder = new StringBuilder(jmxName + ":");
    try {
        for (Method method : obj.getClass().getMethods()) {
            if (method.isAnnotationPresent(JmxAttribute.class)) {
                Object value = method.invoke(obj);
                JmxAttribute jmxAttribute = method.getAnnotation(JmxAttribute.class);
                String attributeName = jmxAttribute.value();
                nameBuilder.append(attributeName).append("=").append(value).append(",");
            }
        }
        nameBuilder.deleteCharAt(nameBuilder.lastIndexOf(","));
        return new ObjectName(nameBuilder.toString());
    } catch (Exception e) {
        throw new IllegalArgumentException("Could not build ObjectName for " + obj.getClass(), e);
    }
}
