public static boolean validateRelationName(String baseTableName, String relatedTableName, String relationName) {
    // Check that relation name is not empty
    if (relationName.trim().isEmpty()) {
        return false;
    }

    // Check that relation name is unique
    Set<String> relationNames = new HashSet<>();
    relationNames.add(relationName);
    // Add existing relation names from base and related tables
    // assuming they have been retrieved from a database
    relationNames.addAll(getRelationNames(baseTableName));
    relationNames.addAll(getRelationNames(relatedTableName));
    return relationNames.size() == 2;
}

