import java.util.HashMap;
import java.util.Map;
import java.util.Properties;

public static Map<String, Object> propsToMap(Properties props){
   Map<String, Object> map = new HashMap<>();
   for(Map.Entry<Object, Object> entry : props.entrySet()){
      String key = (String) entry.getKey();
      if(key.contains(".")){
         String[] splitKey = key.split("\\.");
         Map<String, Object> tempMap = map;
         for(int i = 0; i < splitKey.length - 1; i++){
            String innerKey = splitKey[i];
            Map<String, Object> childMap = (Map<String, Object>) tempMap.get(innerKey);
            if(childMap == null){
               childMap = new HashMap<>();
               tempMap.put(innerKey, childMap);
            }
            tempMap = childMap;
         }
         tempMap.put(splitKey[splitKey.length - 1], entry.getValue());
      }else{
         map.put(key, entry.getValue());
      }
   }
   return map;
}
