public class DirectoryLocator {

    public static File locateDirectory(String dirName) throws IOException {
        File dir = new File(dirName);
        if (dir.isDirectory()) {
            return dir;
        }

        File parentDir = new File("..");
        while (parentDir != null) {
            dir = new File(parentDir, dirName);
            if (dir.isDirectory()) {
                return dir.getCanonicalFile();
            }
            parentDir = parentDir.getParentFile();
        }

        throw new IOException("Directory not found: " + dirName);
    }

}
