import java.lang.reflect.Constructor;
import java.lang.reflect.InvocationTargetException;

public class ObjectFactory {
    public static Object createInstance(TypeDescriptor type, Object... args) throws Exception {
        try {
            Class<?> clazz = Class.forName(type.getTypeName());
            Constructor<?>[] constructors = clazz.getConstructors();
            for (Constructor<?> constructor : constructors) {
                try {
                    Object instance = constructor.newInstance(args);
                    return instance;
                } catch (InstantiationException e) {
                    // continue trying other constructors
                } catch (IllegalAccessException e) {
                    // continue trying other constructors
                } catch (IllegalArgumentException e) {
                    // continue trying other constructors
                } catch (InvocationTargetException e) {
                    // continue trying other constructors
                }
            }
            throw new Exception("Constructor for class " + clazz.getName() + " not found.");
        } catch (ClassNotFoundException e) {
            throw new Exception("Class not found: " + type.getTypeName());
        }
    }
}
