public void moveJsNodes(Element head, Element body) {
  NodeList jsNodes = head.getElementsByTagName("script");
  int length = jsNodes.getLength();
  for (int i = 0; i < length; i++) {
    Node node = jsNodes.item(i);
    Node newNode = node.cloneNode(true);
    body.appendChild(newNode);
    head.removeChild(node);
  }
}
