import org.apache.zookeeper.ZooKeeper;
import org.apache.zookeeper.CreateMode;
import org.apache.zookeeper.Watcher;
import org.apache.zookeeper.WatchedEvent;

public class ZookeeperClientCreator {

    public static ZooKeeper createClient(String config) throws Exception {

        String hostPort = config.substring(config.indexOf(":")+1);
        ZooKeeper zk = new ZooKeeper(hostPort, 5000, new Watcher() {
            public void process(WatchedEvent event) {
                System.out.println("Event Received: " + event.toString());
            }
        });

        String controlNode = "/myapp/control";
        if (zk.exists(controlNode, false) == null) {
            zk.create(controlNode, new byte[0], ZooDefs.Ids.OPEN_ACL_UNSAFE, CreateMode.PERSISTENT);
        }

        String stateNode = "/myapp/state";
        if (zk.exists(stateNode, false) == null) {
            zk.create(stateNode, new byte[0], ZooDefs.Ids.OPEN_ACL_UNSAFE, CreateMode.PERSISTENT);
        }

        return zk;
    }
}
