import java.net.HttpURLConnection;
import java.net.URL;
import java.io.BufferedReader;
import java.io.InputStreamReader;

public static String exchangeAccessCodeForAccessToken(String code, String redirectUrl) throws Exception {
    String url = "https://wepayapi.com/v2/oauth2/token";
    URL obj = new URL(url);
    HttpURLConnection con = (HttpURLConnection) obj.openConnection();
    con.setRequestMethod("POST");
    con.setRequestProperty("User-Agent", "Mozilla/5.0");
    String urlParameters = "client_id=YOUR_CLIENT_ID&client_secret=YOUR_CLIENT_SECRET&redirect_uri=" + redirectUrl + "&code=" + code + "&grant_type=authorization_code";
    con.setDoOutput(true);
    OutputStream os = con.getOutputStream();
    os.write(urlParameters.getBytes());
    os.flush();
    os.close();
    int responseCode = con.getResponseCode();
    BufferedReader in = new BufferedReader(new InputStreamReader(con.getInputStream()));
    String inputLine;
    StringBuffer response = new StringBuffer();
    while ((inputLine = in.readLine()) != null) {
        response.append(inputLine);
    }
    in.close();
    return response.toString();
}
