import org.springframework.transaction.TransactionStatus;
import org.springframework.transaction.support.TransactionCallbackWithoutResult;
import org.springframework.transaction.support.TransactionTemplate;

public void executeTransactionWithoutRollback(TransactionTemplate transactionTemplate, TransactionCallbackWithoutResult transactionCallback) {
    transactionTemplate.execute(new TransactionCallbackWithoutResult() {
        protected void doInTransactionWithoutResult(TransactionStatus transactionStatus) {
            try {
                transactionCallback.doInTransactionWithoutResult(transactionStatus);
            } catch (Exception e) {
                // Ignore any exception that is thrown and do not trigger a rollback
            }
        }
    });
}
