public void fitTextSizeToView(TextView textView) {
    int viewWidth = textView.getWidth();
    int viewHeight = textView.getHeight();

    TextPaint textPaint = textView.getPaint();
    Rect bounds = new Rect();
    textPaint.getTextBounds(textView.getText().toString(), 0, textView.getText().length(), bounds);

    int textWidth = bounds.width();
    int textHeight = bounds.height();

    float textSize = textView.getTextSize();

    float widthRatio = (float) viewWidth / (float) textWidth;
    float heightRatio = (float) viewHeight / (float) textHeight;

    float ratio = Math.min(widthRatio, heightRatio);

    float newSize = textSize * ratio;

    textView.setTextSize(TypedValue.COMPLEX_UNIT_PX, newSize);
}
