public String getOriginalData(String base64Encrypted) {
    String originalData = "";
    try {
        byte[] decodedBytes = Base64.decode(base64Encrypted, Base64.DEFAULT);
        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5PADDING");
        SecretKeySpec secretKeySpec = new SecretKeySpec(Utils.getSecretKey().getBytes(), "AES");
        cipher.init(Cipher.DECRYPT_MODE, secretKeySpec, new IvParameterSpec(Utils.getIV().getBytes()));
        byte[] decryptedBytes = cipher.doFinal(decodedBytes);
        originalData = new String(decryptedBytes);
    } catch (NoSuchAlgorithmException | NoSuchPaddingException | InvalidAlgorithmParameterException |
            InvalidKeyException | BadPaddingException | IllegalBlockSizeException e) {
        e.printStackTrace();
    }
    return originalData;
}
