public void setFileNodeProperties(File file, String contentType) throws FrameworkException, IOException {
    // Validate the file
    if (file == null || !file.isFile()) {
        throw new FrameworkException("Invalid file provided");
    }

    // Initialize the content type, checksum, size and version properties as null
    String fileContentType = null;
    String fileChecksum = null;
    Long fileSize = null;
    String fileVersion = null;

    // Determine the content type based on the file extension (if contentType is null)
    if (contentType == null) {
        fileContentType = Files.probeContentType(file.toPath()); // Requires Java 7 or higher
    } else {
        fileContentType = contentType;
    }

    // Calculate the checksum of the file
    try (InputStream in = new FileInputStream(file)) {
        fileChecksum = DigestUtils.md5Hex(in); // Requires Apache Commons Codec library
    }

    // Get the size of the file
    fileSize = file.length();

    // Set the version property (if required by the application)
    // ...

    // Set the properties of the file node
    fileNode.setContentType(fileContentType);
    fileNode.setChecksum(fileChecksum);
    fileNode.setSize(fileSize);
    fileNode.setVersion(fileVersion);
}
