public static int elapsedTimeInPart(long timestamp1, long timestamp2, int part) {
    long diffInMillis = Math.abs(timestamp1 - timestamp2) * 1000;
    switch (part) {
        case Calendar.YEAR:
            return (int) (diffInMillis / (365 * 24 * 60 * 60 * 1000L));
        case Calendar.MONTH:
            return (int) (diffInMillis / (30 * 24 * 60 * 60 * 1000L));
        case Calendar.DAY_OF_MONTH:
            return (int) (diffInMillis / (24 * 60 * 60 * 1000L));
        case Calendar.HOUR:
            return (int) (diffInMillis / (60 * 60 * 1000L));
        case Calendar.MINUTE:
            return (int) (diffInMillis / (60 * 1000L));
        case Calendar.SECOND:
            return (int) (diffInMillis / 1000L);
        default:
            throw new IllegalArgumentException("Unknown part: " + part);
    }
}
