public Converter getConverter(Class<?> sourceType, Class<?> destinationType, List<Converter> converters) {

    for (Converter converter : converters) {
        MatchResult result = converter.supports(sourceType, destinationType);

        if (result == MatchResult.FULL) {
            return converter;
        }

        if (result == MatchResult.PARTIAL && partialConverter == null) {
            partialConverter = converter;
        }
    }

    return partialConverter;
}
