public static int readLittleEndianInt(DataInput in) throws IOException {
    int b1 = in.readByte() & 0xFF;
    int b2 = in.readByte() & 0xFF;
    int b3 = in.readByte() & 0xFF;
    int b4 = in.readByte() & 0xFF;

    return (b4 << 24) + (b3 << 16) + (b2 << 8) + b1;
}
