public static void adjustLineColumnNumbers(String tokenText, int tokenStart, Position position) {
    int length = tokenText.length();
    int index;

    for (index = 0; index < length; index++) {
        char ch = tokenText.charAt(index);
        if (ch == '\r') {
            if ((index + 1) < length && tokenText.charAt(index + 1) == '\n') {
                index++;
            }
            position.line++;
            position.column = 0;
        } else if (ch == '\n') {
            position.line++;
            position.column = 0;
        } else {
            position.column++;
        }
    }

    if (index < length) {
        position.column += (length - index);
    }

    position.index += tokenStart;
}
