public static String getRawEscapedBasename(String path) {
    String[] pathSegments = path.split("/");
    String basename = pathSegments[pathSegments.length - 1];

    String[] basenameSegments = basename.split("\\.");
    if (basenameSegments.length > 1) {
        basename = basenameSegments[0];
    }

    return basename.replaceAll("[^a-zA-Z0-9]", "\\\\$0");
}
