public static OtpErlangObject readCompressedTerm(OtpInputStream stream) throws OtpErlangDecodeException {
    try {
        OtpInputStream uncompressedStream = new OtpInputStream(stream.read_binary());
        OtpInputStream decompressedStream = new OtpInputStream(new InflaterInputStream(uncompressedStream));
        OtpErlangObject result = decompressedStream.read_any();
        uncompressedStream.close();
        decompressedStream.close();
        return result;
    } catch (IOException e) {
        throw new OtpErlangDecodeException("Failed to decode compressed term", e);
    }
}
