public void deploy(AppPersistenceUnitService persistenceUnitService, List<SubDeployment> subDeployments) {
    ExecutorService executor = Executors.newFixedThreadPool(subDeployments.size());

    try {
        Future<?>[] futures = new Future<?>[subDeployments.size()];
        int i = 0;
        for (SubDeployment subDeployment : subDeployments) {
            futures[i++] = executor.submit(() -> {
                if (subDeployment.getNextPhaseDep() != null) {
                    try {
                        subDeployment.getNextPhaseDep().await();
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                        return;
                    }
                }
                if (subDeployment.getPhase().equals(Phase.FIRST_MODULE_USE)) {
                    synchronized (persistenceUnitService) {
                        while (!persistenceUnitService.isStarted()) {
                            try {
                                persistenceUnitService.wait();
                            } catch (InterruptedException e) {
                                Thread.currentThread().interrupt();
                                return;
                            }
                        }
                    }
                }
                subDeployment.execute();
            });
        }

        for (Future<?> future : futures) {
            try {
                future.get();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            } catch (ExecutionException e) {
                // handle exception
            }
        }
    } finally {
        executor.shutdown();
    }
}
