public int[][] sortEdgesForRendering(int dindex) {
    int[][] sortedEdges = new int[edges.length][2];
    for (int i = 0; i < edges.length; i++) {
        sortedEdges[i][0] = Math.min(edges[i][0], edges[i][1]);
        sortedEdges[i][1] = i;
    }
    Arrays.sort(sortedEdges, (a, b) -> a[0] - b[0]);
    return sortedEdges;
}
