public class OutermostClass {

    public Class<?> getOutermostClass(Object symbol) {
        Class<?> outerClass = symbol.getClass().getEnclosingClass();
        while (outerClass != null && outerClass.getEnclosingClass() != null) {
            outerClass = outerClass.getEnclosingClass();
        }
        return outerClass;
    }
}
