public int convertTypeToGLConstant(String type) {
    switch (type) {
        case "int":
            return GL.GL_INT;
        case "float":
            return GL.GL_FLOAT;
        case "bool":
        case "boolean":
            return GL.GL_BOOL;
        case "vec2":
            return GL.GL_FLOAT_VEC2;
        case "vec3":
            return GL.GL_FLOAT_VEC3;
        case "vec4":
            return GL.GL_FLOAT_VEC4;
        case "mat3":
            return GL.GL_FLOAT_MAT3;
        case "mat4":
            return GL.GL_FLOAT_MAT4;
        case "sampler2D":
            return GL.GL_SAMPLER_2D;
        default:
            throw new IllegalArgumentException("Invalid type: " + type);
    }
}
