public TimestampedHiveDatasetVersion createTimestampedHiveDatasetVersion(Partition partition) {
    Objects.requireNonNull(partition, "Partition argument cannot be null");
    final String dataLocation = partition.getDataLocation();
    Objects.requireNonNull(dataLocation, "Partition data location cannot be null");
    final Path hdfsPath = new Path(dataLocation);
    FileSystem fs;
    try {
        fs = hdfsPath.getFileSystem(new Configuration());
    } catch (IOException e) {
        throw new IllegalArgumentException("Failed to get FileSystem for partition data location: " + dataLocation, e);
    }
    if (!fs.exists(hdfsPath)) {
        throw new IllegalArgumentException("Partition data location doesn't exist: " + dataLocation);
    }
    long modifiedTimeMillis;
    try {
        modifiedTimeMillis = fs.getFileStatus(hdfsPath).getModificationTime();
    } catch (IOException e) {
        throw new IllegalArgumentException("Failed to get modification time for partition data location: " + dataLocation, e);
    }
    return new TimestampedHiveDatasetVersion(partition.getSpec(), modifiedTimeMillis);
}
