public static boolean areActivitiesConflicting(List<Activity> activities) {
    // Sort activities by their start time
    Collections.sort(activities, Comparator.comparing(Activity::getStartTime));

    // Use a stack to keep track of overlapping activities
    Stack<Activity> stack = new Stack<>();
    stack.push(activities.get(0));

    // Iterate over the remaining activities, checking for conflicts
    for (int i = 1; i < activities.size(); i++) {
        Activity current = activities.get(i);

        // Check if the current activity overlaps with the top activity on the stack
        if (current.getStartTime() < stack.peek().getEndTime()) {
            // Activities conflict, return true
            return true;
        }

        // Current activity doesn't conflict, so add it to the stack
        stack.push(current);
    }

    // No conflicts found, return false
    return false;
}
