public void removeNode(Node node) {
    List<Edge> edgesToRemove = new ArrayList<>();
    for (Edge edge : node.edges()) {
        edgesToRemove.add(edge);
    }
    for (Edge edge : edgesToRemove) {
        edge.getFrom().removeEdge(edge);
        edge.getTo().removeEdge(edge);
    }
    node.clearEdges();
}
