public Drawable getActivityIcon(ComponentName component) {
    PackageManager packageManager = getPackageManager();
    try {
        ActivityInfo activityInfo = packageManager.getActivityInfo(component, 0);
        if (activityInfo.getIconResource() > 0) {
            return activityInfo.loadIcon(packageManager);
        } else {
            ApplicationInfo applicationInfo = packageManager.getApplicationInfo(component.getPackageName(), 0);
            if (applicationInfo.icon > 0) {
                return applicationInfo.loadIcon(packageManager);
            }
        }
    } catch (PackageManager.NameNotFoundException e) {
        e.printStackTrace();
    }
    return null;
}
