public static boolean isPixelBlack(BufferedImage image, int x, int y, int luminanceCutOff) {
    int pixel = image.getRGB(x, y);
    int red = (pixel >> 16) & 0xff;
    int green = (pixel >> 8) & 0xff;
    int blue = (pixel) & 0xff;
    double luma = 0.2126 * red + 0.7152 * green + 0.0722 * blue;
    return luma < luminanceCutOff;
}
