public static Set<Integer> filterBasedScanning(UnicodeSet unicodeSet, int startCodePoint, int endCodePoint) {
    Set<Integer> result = new HashSet<>();

    for (int codePoint = startCodePoint; codePoint <= endCodePoint; codePoint++) {
        if (unicodeSet.contains(codePoint)) {
            result.add(codePoint);
        }
    }

    return result;
}
