public ExternalNode evaluateMidd(MIDD midd, Map<String, Object> variables) {
    Node currentNode = midd.getRoot(); // get the root node of MIDD
    while(currentNode instanceof InternalNode) {
        String currentId = currentNode.getAttributeId();
        Object currentVal = variables.get(currentId);
        currentNode = ((InternalNode)currentNode).getChild(currentVal); // get child based on attribute value
    }
    return (ExternalNode)currentNode; // cast to external node and return
}
