public <V> V submitAfterWait(Future<V> future, Callable<V> callable,
                             long timeout, TimeUnit unit) throws ExecutionException, TimeoutException {
    try {
        future.get(timeout, unit);
    } catch (InterruptedException e) {
        future.cancel(true);
        throw new RuntimeException("Future interrupted.");
    } catch (ExecutionException e) {
        future.cancel(true);
        throw e;
    } catch (TimeoutException e) {
        future.cancel(true);
        throw new TimeoutException("Future timed out.");
    }
    return callable.call();
}
