public Drawable createArrowIcon(Context context, int width, int height, int color, ExpandDirection expandDirection) {
    Drawable iconDrawable;

    if (expandDirection == ExpandDirection.UP) {
        iconDrawable = ContextCompat.getDrawable(context, R.drawable.ic_arrow_up);
    } else if (expandDirection == ExpandDirection.LEFT) {
        iconDrawable = ContextCompat.getDrawable(context, R.drawable.ic_arrow_left);
    } else if (expandDirection == ExpandDirection.DOWN) {
        iconDrawable = ContextCompat.getDrawable(context, R.drawable.ic_arrow_down);
    } else {
        iconDrawable = ContextCompat.getDrawable(context, R.drawable.ic_arrow_right);
    }

    iconDrawable.setColorFilter(color, PorterDuff.Mode.SRC_ATOP);
    iconDrawable.setBounds(0, 0, width, height);

    return iconDrawable;
}
