        } else if (rhsType instanceof GenericArrayType) {
            Type[] lhsTypeArguments = lhsType instanceof ParameterizedType
                    ? ((ParameterizedType) lhsType).getActualTypeArguments()
                            : new Type[] { Object.class };
            if (lhsTypeArguments.length == 1) {
                Type lhsComponentType = lhsTypeArguments[0];
                Type rhsComponentType = ((GenericArrayType) rhsType).getGenericComponentType();
                return isAssignable(lhsComponentType, rhsComponentType);
            }
        }
    } else if (lhsType instanceof GenericArrayType) {
        Type lhsComponentType = ((GenericArrayType) lhsType).getGenericComponentType();
        if (rhsType instanceof Class) {
            Class<?> rhsClass = (Class<?>) rhsType;
            if (rhsClass.isArray()) {
                Type rhsComponentType = rhsType.getComponentType();
                return isAssignable(lhsComponentType, rhsComponentType);
            }
        } else if (rhsType instanceof GenericArrayType) {
            Type rhsComponentType = ((GenericArrayType) rhsType).getGenericComponentType();
            return isAssignable(lhsComponentType, rhsComponentType);
        } else if (rhsType instanceof ParameterizedType) {
            Type[] rhsTypeArguments = ((ParameterizedType) rhsType).getActualTypeArguments();
            if (rhsTypeArguments.length == 1) {
                Type rhsComponentType = rhsTypeArguments[0];
                if (rhsComponentType instanceof WildcardType) {
                    rhsComponentType = ((WildcardType) rhsComponentType).getUpperBounds()[0];
                }
                return isAssignable(lhsComponentType, rhsComponentType);
            }
        }
    } else if (lhsType instanceof WildcardType) {
        WildcardType lhsWildcardType = (WildcardType) lhsType;
        Type[] lhsUpperBounds = lhsWildcardType.getUpperBounds();
        Type[] lhsLowerBounds = lhsWildcardType.getLowerBounds();
        if (rhsType instanceof WildcardType) {
            WildcardType rhsWildcardType = (WildcardType) rhsType;
            Type[] rhsUpperBounds = rhsWildcardType.getUpperBounds();
            Type[] rhsLowerBounds = rhsWildcardType.getLowerBounds();
            for (Type lhsBound : lhsUpperBounds) {
                for (Type rhsBound : rhsUpperBounds) {
                    if (isAssignable(rhsBound, lhsBound)) {
                        return true;
                    }
                }
            }
            for (Type lhsBound : lhsLowerBounds) {
                for (Type rhsBound : rhsLowerBounds) {
                    if (isAssignable(lhsBound, rhsBound)) {
                        return true;
                    }
                }
            }
        } else {
            for (Type lhsBound : lhsUpperBounds) {
                if (!isAssignable(lhsBound, rhsType)) {
                    return false;
                }
            }
            for (Type lhsBound : lhsLowerBounds) {
                if (!isAssignable(rhsType, lhsBound)) {
                    return false;
                }
            }
            return true;
        }
    }
    return false;
}
