public static <K, V> boolean haveCommonPair(Map<K, V> map1, Map<K, V> map2) {
    for (Map.Entry<K, V> entry : map1.entrySet()) {
        K key = entry.getKey();
        V value = entry.getValue();
        if (map2.containsKey(key) && map2.get(key).equals(value)) {
            return true;
        }
    }
    return false;
}
