public String generateIndent(int delta) {
    int indentLevel = currentIndentLevel += delta;
    if (indentLevel < 0) {
        currentIndentLevel = 0;
        return "";
    } else {
        StringBuilder spaces = new StringBuilder();
        for (int i = 0; i < indentLevel; i++) {
            spaces.append(" ");
        }
        return spaces.toString();
    }
}
