public static int getNumberOfDigits(int x) {
    if (x == Integer.MIN_VALUE) {
        return 11;
    }
    boolean negative = x < 0;
    if (negative) {
        x = -x;
    }
    if (x < 10) {
        return negative ? 2 : 1;
    } else if (x < 100) {
        return negative ? 3 : 2;
    } else if (x < 1000) {
        return negative ? 4 : 3;
    } else if (x < 10000) {
        return negative ? 5 : 4;
    } else if (x < 100000) {
        return negative ? 6 : 5;
    } else if (x < 1000000) {
        return negative ? 7 : 6;
    } else if (x < 10000000) {
        return negative ? 8 : 7;
    } else if (x < 100000000) {
        return negative ? 9 : 8;
    } else if (x < 1000000000) {
        return negative ? 10 : 9;
    } else {
        return negative ? 11 : 10;
    }
}
