public static boolean containsFieldName(List<Condition> conditions, String fieldName) {
    for (Condition condition : conditions) {
        if (condition.getFieldName().equals(fieldName)) {
            return true;
        }
        if (condition.getNestedConditions() != null && containsFieldName(condition.getNestedConditions(), fieldName)) {
            return true;
        }
    }
    return false;
}
