public void downloadPluginFromMavenRepo(String repoUrl, String pluginName) {
    // Construct the plugin URL
    String pluginUrl = repoUrl + "/plugins/" + pluginName + ".jar";

    // Download the plugin using a HTTP client library
    HttpClient httpClient = new HttpClient();
    GetMethod getMethod = new GetMethod(pluginUrl);
    try {
        int statusCode = httpClient.executeMethod(getMethod);
        if (statusCode != HttpStatus.SC_OK) {
            throw new RuntimeException("Failed to download plugin. Status code: " + statusCode);
        }

        // Save the plugin to the local file system
        File pluginFile = new File("plugins/" + pluginName + ".jar");
        FileOutputStream outputStream = new FileOutputStream(pluginFile);
        InputStream inputStream = getMethod.getResponseBodyAsStream();
        byte[] buffer = new byte[4096];
        int bytesRead = -1;
        while ((bytesRead = inputStream.read(buffer)) != -1) {
            outputStream.write(buffer, 0, bytesRead);
        }

        // Close the input and output streams
        outputStream.close();
        inputStream.close();
    } catch (Exception e) {
        throw new RuntimeException("Failed to download plugin: " + e.getMessage(), e);
    } finally {
        getMethod.releaseConnection();
    }
}
