@Override
public double valueOptionWithThetaMethod(FDMEuropeanCallOption option, double theta) {
    double[][] grid = option.getModel().getPriceGrid(option.getMaturity(), option.getStrike());
    double[] timeNodes = option.getModel().getTimeDiscretization().getAsDoubleArray();

    int numTimeSteps = timeNodes.length - 1;
    int numSpaceSteps = grid[0].length - 1;

    double deltaT = option.getModel().getTimeDiscretization().getTimeStep(0);
    double deltaX = option.getModel().getSpaceDiscretization().getSpaceStep(0);

    double theta1 = (theta - 1) * 0.5;
    double theta2 = (theta + 1) * 0.5;

    double[][] newGrid = new double[numTimeSteps + 1][numSpaceSteps + 1];

    for(int j = 0; j <= numSpaceSteps; j++) {
        newGrid[numTimeSteps][j] = Math.max(grid[numTimeSteps][j], 0);
    }

    for(int i = numTimeSteps - 1; i >= 0; i--) {
        for(int j = 1; j < numSpaceSteps; j++) {
            double d2VdX2 = (grid[i][j+1] - 2 * grid[i][j] + grid[i][j-1]) / (deltaX * deltaX);
            double dVdT = (grid[i+1][j] - grid[i][j]) / deltaT;
            double drift = option.getModel().getDrift(timeNodes[i], option.getInitialValue(), j * deltaX);
            double diffusion = option.getModel().getDiffusion(timeNodes[i], option.getInitialValue(), j * deltaX);

            newGrid[i][j] = theta1 * newGrid[i+1][j-1] + theta2 * newGrid[i+1][j] + theta1 * newGrid[i+1][j+1]
                    + deltaT * (theta2 * (drift + diffusion * d2VdX2) + theta1 * dVdT);
        }

        newGrid[i][0] = 2.0 * newGrid[i][1] - newGrid[i][2];
        newGrid[i][numSpaceSteps] = 2.0 * newGrid[i][numSpaceSteps-1] - newGrid[i][numSpaceSteps-2];
    }

