public boolean put(Object item, String itemId, long maxWait, TimeUnit unit) throws Exception {
    if (queue.remainingCapacity() == 0) {
        if (queueBuilder.getMaxItems() == 0) {
            throw new Exception("Queue is full!");
        } else {
            boolean inserted = false;
            try {
                inserted = queue.offer(item, maxWait, unit);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
            if (!inserted) {
                return false;
            } else {
                itemIds.add(itemId);
                return true;
            }
        }
    } else {
        boolean inserted = queue.offer(item);
        if (!inserted) {
            return false;
        } else {
            itemIds.add(itemId);
            return true;
        }
    }
}
