public void checkIdleTimeAndPostCommand(long userLastEventTime, long maxIdleTime) {
    long currentTime = System.currentTimeMillis();
    if((currentTime - userLastEventTime) > maxIdleTime) {
        if((currentTime - userLastEventTime) > (2*maxIdleTime)) {
            // log the user out
            System.out.println("Logging the user out as their idle time has exceeded the limit.");
        } else {
            // post a command to idle the user out
            System.out.println("Posting a command to idle the user out as their idle time has exceeded the limit.");
        }
    }
}
