public List<Module> locateModules() {
    List<Module> modules = new ArrayList<>();
    File localRepository = new File(System.getProperty("user.home"), ".m2/repository"); //assuming maven repository
    File[] moduleDirectories = localRepository.listFiles();
    if (moduleDirectories != null) {
        for (File moduleDirectory : moduleDirectories) {
            if (moduleDirectory.isDirectory()) {
                String[] parts = moduleDirectory.getName().split(":");
                if (parts.length == 3) { //groupId:artifactId:version
                    Module module = new Module(parts[0], parts[1], parts[2]);
                    modules.add(module);
                }
            }
        }
    }
    return modules;
}
