public Charset getCharsetFromContentType(HttpResponse response) {
    String contentType = response.getHeaders("Content-Type")[0].getValue();
    if (contentType != null) {
        String charsetPattern = "charset=([^\\s;]+)";
        Pattern pattern = Pattern.compile(charsetPattern, Pattern.CASE_INSENSITIVE);
        Matcher matcher = pattern.matcher(contentType);
        if (matcher.find()) {
            String charset = matcher.group(1).trim();
            try {
                return Charset.forName(charset);
            } catch (UnsupportedCharsetException e) {
                // log warning or return default charset
            }
        }
    }
    return Charset.forName("ISO-8859-1");
}
