public static List<Method> findUnoverriddenPublicSuperMethods(Class<?> clazz) {
    List<Method> result = new ArrayList<>();

    // Get all public methods of the class
    Method[] publicMethods = clazz.getMethods();

    // Traverse through all public methods
    for (Method publicMethod : publicMethods) {

        // Check if method is public and not static
        if (Modifier.isPublic(publicMethod.getModifiers())
                && !Modifier.isStatic(publicMethod.getModifiers())) {

            boolean methodOverridden = false;

            // Traverse through all superclasses of the class
            for (Class<?> superclass = clazz.getSuperclass();
                 superclass != null && !methodOverridden;
                 superclass = superclass.getSuperclass()) {

                // Check if superclass defines a method with same name and signature
                try {
                    superclass.getDeclaredMethod(publicMethod.getName(), publicMethod.getParameterTypes());
                    methodOverridden = true;
                } catch (NoSuchMethodException e) {
                    // No matching method found in superclass; check next superclass
                }
            }

            // If method is not overridden in any superclass, add it to result list
            if (!methodOverridden)
                result.add(publicMethod);
        }
    }

    return result;
}
