    nodeMetrics.setAppId(application.getAppId());
    nodeMetrics.setAppName(application.getName());
    businessMetrics.setAppId(application.getAppId());
    businessMetrics.setAppName(application.getName());
    // calculate node health percent
    double nodeHealthPercent = calculateNodeHealthPercent();
    nodeMetrics.setHealthPercent(nodeHealthPercent);
    result.add(nodeMetrics);
    // calculate business health percent
    double businessHealthPercent = calculateBusinessHealthPercent();
    businessMetrics.setHealthPercent(businessHealthPercent);
    result.add(businessMetrics);
    return result;
}

