class Service {
  // some fields and methods here
}

class CachedService {
  private Service previousService;
  private Service currentService;

  // constructor
  public CachedService(Service previousService, Service currentService) {
    this.previousService = previousService;
    this.currentService = currentService;
  }

  // getters and setters
  public Service getPreviousService() {
    return previousService;
  }

  public void setPreviousService(Service previousService) {
    this.previousService = previousService;
  }

  public Service getCurrentService() {
    return currentService;
  }

  public void setCurrentService(Service currentService) {
    this.currentService = currentService;
  }
}

public CachedService cacheService(Service service, boolean update) {
  CachedService cachedService;

  // get the current service, if any
  Service currentService = getCachedService();

  if (currentService == null || update) {
    // if no service is cached or 'update' flag is set to true,
    // replace the cached service with the new service
    cachedService = new CachedService(currentService, service);
  } else {
    // if a service is already cached and 'update' flag is false,
    // do not replace it, just return it
    cachedService = new CachedService(currentService, currentService);
  }

  // cache the new or updated service
  cacheService(cachedService.getCurrentService());

  return cachedService;
}
