public void writeLittleEndianInt(int v) throws IOException {
    byte[] buf = new byte[4];
    buf[0] = (byte)(v & 0xff);
    buf[1] = (byte)((v >> 8) & 0xff);
    buf[2] = (byte)((v >> 16) & 0xff);
    buf[3] = (byte)((v >> 24) & 0xff);
    outputStream.write(buf);
}
