import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

public static boolean unzipByteArrayToFile(File zipFile, String directory) {
    byte[] buffer = new byte[1024];
    try {
        // create output directory if it doesn't exist
        File folder = new File(directory);
        if (!folder.exists()) {
            folder.mkdirs();
        }
        // get the zip file content
        ZipInputStream zis = new ZipInputStream(new FileInputStream(zipFile));
        // loop through all entries in the zip file
        ZipEntry ze = zis.getNextEntry();
        while (ze != null) {
            String fileName = ze.getName();
            File newFile = new File(directory + File.separator + fileName);
            if (ze.isDirectory()) {
                newFile.mkdirs();
            } else {
                // create all non-existing directories before output file 
                new File(newFile.getParent()).mkdirs();
                FileOutputStream fos = new FileOutputStream(newFile);
                int len;
                while ((len = zis.read(buffer)) > 0) {
                    fos.write(buffer, 0, len);
                }
                fos.close();
            }
            ze = zis.getNextEntry();
        }
        zis.closeEntry();
        zis.close();
        return true;
    } catch (IOException ex) {
        ex.printStackTrace();
        return false;
    }
}
