public void updateOrAddToList(List<Object> values) {
    if (largeList == null) {
        largeList = new ArrayList<>();
    }
    for (Object value : values) {
        if (value instanceof Map) {
            Map<String, Object> map = (Map<String, Object>) value;
            if (map.containsKey("key")) {
                int index = -1;
                for (int i = 0; i < largeList.size(); i++) {
                    Object obj = largeList.get(i);
                    if (obj instanceof Map) {
                        Map<String, Object> existingMap = (Map<String, Object>) obj;
                        if (existingMap.get("key").equals(map.get("key"))) {
                            index = i;
                            break;
                        }
                    }
                }
                if (index > -1) {
                    largeList.set(index, value);
                } else {
                    largeList.add(value);
                }
            }
        } else {
            int index = largeList.indexOf(value);
            if (index > -1) {
                largeList.set(index, value);
            } else {
                largeList.add(value);
            }
        }
    }
}
