public static byte[] hexStringToByteArray(String hex) throws IllegalArgumentException {
    int length = hex.length();
    if (length % 2 != 0) {
        throw new IllegalArgumentException("Hex String must have an even length.");
    }
    byte[] bytes = new byte[length / 2];
    for (int i = 0; i < length; i += 2) {
        char c1 = hex.charAt(i);
        char c2 = hex.charAt(i + 1);
        int b = 0;
        if (c1 >= '0' && c1 <= '9') {
            b |= (c1 - '0') << 4;
        } else if (c1 >= 'a' && c1 <= 'f') {
            b |= (c1 - 'a' + 10) << 4;
        } else if (c1 >= 'A' && c1 <= 'F') {
            b |= (c1 - 'A' + 10) << 4;
        } else {
            throw new IllegalArgumentException("Hex String contains non-hex characters.");
        }
        if (c2 >= '0' && c2 <= '9') {
            b |= c2 - '0';
        } else if (c2 >= 'a' && c2 <= 'f') {
            b |= c2 - 'a' + 10;
        } else if (c2 >= 'A' && c2 <= 'F') {
            b |= c2 - 'A' + 10;
        } else {
            throw new IllegalArgumentException("Hex String contains non-hex characters.");
        }
        bytes[i / 2] = (byte) b;
    }
    return bytes;
}
