public boolean hasSameNameSibling(String nodePath, Session session) throws RepositoryException {
    boolean hasSibling = false;
    Node node = session.getNode(nodePath);
    if (node.getDepth() > 1) {
        String parentPath = node.getParent().getPath();
        String nodeName = node.getName();
        if (node.getIndex() > 1) {
            if (session.nodeExists(parentPath + "/" + nodeName + "[2]")) {
                hasSibling = true;
            }
        } else {
            NodeIterator siblings = session.getNodes(parentPath, nodeName);
            if (siblings.getSize() > 1) {
                hasSibling = true;
            }
        }
    }
    return hasSibling;
}
