public static double[][] concatMatricesVertical(double[][] top, double[][] bottom, double[][] out) {
    int rowCountTop = top.length;
    int rowCountBottom = bottom.length;
    int colCount = top[0].length;

    if (colCount != bottom[0].length) {
        throw new IllegalArgumentException("Matrices must have the same number of columns.");
    }

    if (out == null || out.length != rowCountTop + rowCountBottom || out[0].length != colCount) {
        out = new double[rowCountTop + rowCountBottom][colCount];
    }

    System.arraycopy(top, 0, out, 0, rowCountTop);
    System.arraycopy(bottom, 0, out, rowCountTop, rowCountBottom);

    return out;
}
