public boolean areResourcesAvailable(Tenant tenant) {
    boolean isAvailable = true;

    // Check if the tenant is available
    if (!isTenantAvailable(tenant)) {
        isAvailable = false;
    }

    // Check if all the applications of the tenant are available
    for (Application app : tenant.getApplications()) {
        if (!isApplicationAvailable(app)) {
            isAvailable = false;
            break;
        }
    }

    // Check if all the storage managers of the tenant are available
    for (StorageManager storageMgr : tenant.getStorageManagers()) {
        if (!isStorageManagerAvailable(storageMgr)) {
            isAvailable = false;
            break;
        }
    }

    return isAvailable;
}

