public class AlternativeExceptionVisitor implements NodeVisitor {

    private final List<String> alternativeExceptions = new ArrayList<>();

    @Override
    public void visit(CatchClause n, Object arg) {
        BlockStmt block = n.getBody();
        if (block.getStatements().size() != 1) {
            // Cannot handle complex catch blocks
            return;
        }
        Statement statement = block.getStatement(0);
        if (!(statement instanceof ThrowStmt)) {
            // Cannot handle catch blocks without throw statements
            return;
        }
        ThrowStmt throwStmt = (ThrowStmt) statement;
        Expression expr = throwStmt.getExpression();
        if (!(expr instanceof ObjectCreationExpr)) {
            // Cannot handle throw statements without object creation expressions
            return;
        }
        ObjectCreationExpr objCreateExpr = (ObjectCreationExpr) expr;
        String catchType = n.getParameter().getType().asString();
        String altException = objCreateExpr.getType().asString();
        if (!catchType.equals(altException)) {
            alternativeExceptions.add(altException);
        }
    }

    public List<String> getAlternativeExceptions() {
        return alternativeExceptions;
    }

}
