public void ensureCapacity(long minCapacity) {
    if (minCapacity > Integer.MAX_VALUE) {
        throw new IllegalArgumentException("minCapacity is too large.");
    }
    int minInternalCapacity = (int) Math.max(minCapacity, this.internalCapacity);
    if (minInternalCapacity > this.elements.length) {
        grow(minInternalCapacity);
    }
}
