public static byte[] toUidByteArray(long uid, int width) throws IllegalStateException {
    if ((uid >> (8 * width)) != 0) {
        throw new IllegalStateException("UID is larger than the specified width would allow");
    }

    byte[] result = new byte[width];
    for (int i = 0; i < width; i++) {
        result[i] = (byte) (uid >>> (8 * i));
    }
    return result;
}
