public static String toLowerCaseExceptUrlsAndClasses(String input) {
    StringBuilder result = new StringBuilder();

    boolean skipMode = false;
    boolean insideUrl = false;

    for (int i = 0; i < input.length(); i++) {
        char currentChar = input.charAt(i);
        char nextChar = i < input.length() - 1 ? input.charAt(i+1) : '\0';

        if (currentChar == '(') {
            // entering possible class definition
            skipMode = true;
        } else if (skipMode && currentChar == ')') {
            // leaving class definition
            skipMode = false;
            result.append(currentChar);
        } else if (Character.isUpperCase(currentChar) && !skipMode) {
            // uppercase character, needs conversion to lowercase
            result.append(Character.toLowerCase(currentChar));
        } else {
            // just append the character
            result.append(currentChar);
        }

        if (currentChar == 'h' && nextChar == 't') {
            // possible start of url
            insideUrl = true;
        }
        if (insideUrl && currentChar == ' ') {
            // leaving url
            insideUrl = false;
        }

        if (insideUrl) {
            // don't modify characters inside urls
            result.setCharAt(result.length() - 1, currentChar);
        }
    }

    return result.toString();
}
