import org.jgroups.conf.ConfigurationException;
import org.jgroups.conf.ProtocolStackConfigurator;
import org.jgroups.stack.Configurator;
import org.jgroups.util.Util;

import java.net.URL;
import java.util.Objects;

public class ProtocolStackConfiguratorBuilder {

    public static ProtocolStackConfigurator buildProtocolStackConfigurator(String url) throws Exception {
        Objects.requireNonNull(url);
        URL configFile = new URL(url);
        Configurator configurator = new Configurator(configFile);
        ProtocolStackConfigurator protocolStackConfigurator = configurator.getProtocolStack();
        if (protocolStackConfigurator == null) {
            throw new ConfigurationException("Unable to create protocol stack configurator from url: " + url + ".");
        }
        return protocolStackConfigurator;
    }
}
