@Component(service={})
public class QuickStartSecurityRegistryConfiguration {

    @Reference
    private UserRegistryConfiguration userRegistryConfiguration;

    private ServiceRegistration<ManagedService> serviceRegistration;

    @Activate
    protected void activate() {
        Dictionary<String, Object> properties = new Hashtable<>();
        properties.put("registry.config.type", "quickstart-security");
        serviceRegistration = FrameworkUtil.getBundle(this.getClass()).getBundleContext()
                .registerService(ManagedService.class, new QuickStartSecurityRegistryManagedService(), properties);
    }

    @Deactivate
    protected void deactivate() {
        if (serviceRegistration != null) {
            serviceRegistration.unregister();
        }
    }

    private class QuickStartSecurityRegistryManagedService implements ManagedService {

        private Dictionary<String, ?> properties;

        @Override
        public void updated(Dictionary<String, ?> properties) throws ConfigurationException {
            if (properties != null) {
                if (Boolean.FALSE.equals(properties.get("enabled"))) {
                    if (serviceRegistration != null) {
                        serviceRegistration.unregister();
                    }
                } else {
                    if (this.properties == null || !this.properties.equals(properties)) {
                        userRegistryConfiguration.update(properties);
                        this.properties = properties;
                    }
                }
            }
        }
    }
}
