public Reference findLeafBucketReference(Reference pStartKey, Key pSeqBucketKey) throws TTIOException {
    Reference leafBucketRef = null;
    try (Index ind = OpenIndex(pStartKey)) {
        if (ind == null) {
            throw new TTIOException("Index is null");
        }

        try (Cursor cursor = ind.browse()) {
            Pair<Key, Reference> entry;
            boolean startSearch = false;

            while (cursor.getNext(entry) && !startSearch) {
                if (pSeqBucketKey.isSmallerThan(entry.getKey())) {
                    startSearch = true;
                    continue;
                }
                if (pSeqBucketKey.equals(entry.getKey())) {
                    leafBucketRef = entry.getValue();
                    break;
                }
            }
        }
    }
    return leafBucketRef;
}
