public Provider getGlobalHotkeyProvider(boolean useSwingEventQueue) {
    String os = System.getProperty("os.name").toLowerCase();
    if (os.contains("win")) {
        return new WindowsProvider(useSwingEventQueue);
    } else if (os.contains("mac")) {
        return new CarbonProvider(useSwingEventQueue);
    } else if (os.contains("nix") || os.contains("nux") || os.contains("aix")) {
        return new X11Provider(useSwingEventQueue);
    } else {
        return null;
    }
}
