public static String formatPhoneNumber(String phoneNumber) {
    // Remove all non-numeric characters from the phoneNumber
    String numericPhoneNumber = phoneNumber.replaceAll("[^0-9]", "");

    // Check the length of the numericPhoneNumber to determine which format to use
    int length = numericPhoneNumber.length();
    if (length == 10) {
        // Format for local numbers (e.g. 030 12345-67)
        return String.format("%s %s-%s", numericPhoneNumber.substring(0, 3),
                                          numericPhoneNumber.substring(3, 8),
                                          numericPhoneNumber.substring(8));
    } else if (length == 11) {
        // Format for international numbers (e.g. +49 30 12345-67)
        return String.format("+%s %s %s-%s", numericPhoneNumber.substring(0, 2),
                                             numericPhoneNumber.substring(2, 4),
                                             numericPhoneNumber.substring(4, 9),
                                             numericPhoneNumber.substring(9));
    } else {
        // Invalid phone number
        return "Invalid phone number";
    }
}
