public void addGeometry(Geometry geom, Geometry[] array) {
    int index = 0;
    // Find the next available index to insert the new geometry
    while(index < array.length && array[index] != null) {
        index++;
    }
    if(index == array.length) {
        array = Arrays.copyOf(array, array.length + 1); // Increase the size of the array by 1
    }
    array[index] = geom; // Add the new geometry at the first available index
}
