public static boolean validatePMML(PMML pmml, Map<String, DataType> schema) {
    List<Model> models = pmml.getModels();
    if (models == null || models.isEmpty()) {
        return false;
    }
    KMeansModel kMeansModel = (KMeansModel) models.get(0);
    MiningSchema miningSchema = kMeansModel.getMiningSchema();
    List<MiningField> miningFields = miningSchema.getMiningFields();
    if (miningFields.size() != schema.size()) {
        return false;
    }
    for (MiningField miningField : miningFields) {
        DataType dataType = schema.get(miningField.getName().getValue());
        if (dataType == null || !dataType.equals(miningField.getDataType())) {
            return false;
        }
    }
    return true;
}
