public void visitAllNodes(Resource resource) {
    // mark the resource as visited
    resource.setVisited(true);

    // loop through all child resources
    for (Resource childResource : resource.getChildren()) {
        // if the child resource has not been visited yet, visit it
        if (!childResource.isVisited()) {
            visitAllNodes(childResource);
        }
    }
}
