public int truncateList(List<Object> list, int upToSequenceNumber) {
    int truncateIndex = -1;
    for (int i = 0; i < list.size(); i++) {
        Object obj = list.get(i);
        if (obj instanceof SequenceNumber && ((SequenceNumber) obj).getValue() == upToSequenceNumber) {
            truncateIndex = i;
            break;
        }
    }
    if (truncateIndex >= 0) {
        int numTruncated = truncateIndex + 1;
        list.subList(0, numTruncated).clear();
        return numTruncated;
    }
    return 0;
}
