public AFPChain swapStructuresOrder(AFPChain a) {
    int[][] mapping = new int[a.getNRes1()][a.getNBlocks()];

    for (int i = 0; i < a.getNRes1(); i++) {
        for (int j = 0; j < a.getNBlocks(); j++) {
            mapping[i][j] = a.getOptAln()[i][j];
        }
    }

    int[][] newOptAln = new int[a.getNRes1()][a.getNBlocks()];
    for (int i = 0; i < a.getNRes1(); i++) {
        for (int j = 0; j < a.getNBlocks(); j++) {
            newOptAln[i][j] = mapping[i][a.getNBlocks() - 1 - j];
        }
    }

    return new AFPChain(
            a.getName1(),
            a.getName2(),
            a.getSeq1(),
            a.getSeq2(),
            newOptAln,
            a.getGapPenalty(),
            a.getScoring(),
            a.getBlockScore(),
            a.isTm(),
            a.getTmScore(),
            a.getRmsd(),
            a.getLen1(),
            a.getLen2(),
            a.getCa1(),
            a.getCa2(),
            a.getSecStruct1(),
            a.getSecStruct2(),
            a.getNRes1(),
            a.getNRes2(),
            a.getAlgorithm(),
            a.getVersion(),
            a.getBlockNum(),
            a.getCycle(),
            a.getMoved(),
            a.getZ()
    );
}
