import org.apache.commons.cli.*;

public static CommandLineParser createParser(String containerWorkDir) {

    Options options = new Options();
    options.addOption(new Option("c", "class", true, "Container's class name"));
    options.addOption(new Option("a", "args", true, "Container's launch arguments"));

    CommandLineParser parser = new DefaultParser();

    try {
        CommandLine cmd = parser.parse(options, containerWorkDir.split(" "));
        return cmd;
    } catch (ParseException e) {
        System.err.println("Error: Invalid input arguments!");
    }

    return null;
}
