public Attribute createNewAttributeInstance(String str) throws BOSHException {
    if (str == null) {
        return null;
    }
    Attribute attribute = Attribute.createFromString(str);
    if (attribute == null) {
        throw new BOSHException("Failed to create attribute from string: " + str);
    }
    return attribute;
}
