public ArrayList<TextView> clickOnListLine(int line, int index, int id) {
    ListView listView = (ListView) findViewById(index);
    View view = listView.getChildAt(line);
    view.findViewById(id).performClick();

    ArrayList<TextView> textViews = new ArrayList<>();
    for(int i=0; i<view.getChildCount(); i++) {
        View child = view.getChildAt(i);
        if(child instanceof TextView) {
            textViews.add((TextView) child);
        }
    }

    return textViews;
}
