public Object getMBeanAttribute(String name, String attrInfo) throws JMException {
    MBeanServer mbs = ManagementFactory.getPlatformMBeanServer();
    Object attributeResult = null;
    try {
        ObjectName objectName = new ObjectName(name);
        attributeResult = mbs.getAttribute(objectName, attrInfo);
    } catch (Exception e) {
        throw new JMException("Error getting MBean attribute. " + e.getMessage());
    }
