public Prefer createPreferHeader(String value) {
    if (value == null || value.isEmpty()) {
        return null;
    }

    Prefer prefer = new Prefer();

    String[] preferences = value.split(",");
    for (String preference : preferences) {
        String[] preferenceParts = preference.trim().split("=", 2);
        if (preferenceParts.length != 2) {
            return null;
        }

        String name = preferenceParts[0].trim();
        String valueString = preferenceParts[1].trim();

        switch (name.toLowerCase()) {
            case "wait":
                long wait = Long.parseLong(valueString);
                prefer.setWait(wait);
                break;
            case "handling":
                prefer.setHandling(valueString);
                break;
            default:
                return null;
        }
    }

    return prefer;
}
