public int checkChar(String signature, int pos) {
    // check if pos is within the given string
    if(pos >= signature.length()) {
        return -1; // invalid input, return -1
    }

    // check the character at given position
    char c = signature.charAt(pos);
    if(c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') {
        return pos + 1; // if character is a vowel, return next index
    } else {
        return pos; // if character is not a vowel, return current index
    }
}
