public void validateMutexLock(Object mutex) throws IllegalMonitorStateException {
    synchronized(mutex) {
        if(!Thread.holdsLock(mutex) || !Thread.currentThread().holdsLock(mutex)) {
            throw new IllegalMonitorStateException();
        }
    }
}
