public static int compare(ApiObjectFieldDoc o1, ApiObjectFieldDoc o2) {
    // Compare field names
    int result = o1.name().compareTo(o2.name());
    if (result != 0) {
        return result;
    }

    // Compare tags
    result = ApiFieldTagImpl.compare(o1, o2);
    if (result != 0) {
        return result;
    }

    // Compare field types
    Type t1 = o1.type();
    Type t2 = o2.type();
    if (t1 == null && t2 == null) {
        return 0;
    } else if (t1 == null) {
        return 1;
    } else if (t2 == null) {
        return -1;
    }
    result = t1.simpleTypeName().compareTo(t2.simpleTypeName());
    if (result != 0) {
        return result;
    }
    if (t1.dimension() != t2.dimension()) {
        return t1.dimension() - t2.dimension();
    }
    if (t1.dimension() > 0) {
        t1 = t1.asElementType();
        t2 = t2.asElementType();
    }
    if (! t1.qualifiedTypeName().equals(t2.qualifiedTypeName())) {
        return t1.qualifiedTypeName().compareTo(t2.qualifiedTypeName());
    }
    return 0;
}
