public List<SegmentPair> readHighScoringPairs(Readable readable) throws IOException {
    Objects.requireNonNull(readable, "Readable must not be null");
    List<SegmentPair> highScoringPairs = new ArrayList<>();

    BufferedReader reader = null;
    try {
        reader = new BufferedReader(readable);
        String line = null;
        while ((line = reader.readLine()) != null) {
            // Parse the line into two segments and their scores
            String[] parts = line.split("\\s+");
            if (parts.length == 4) {
                String segment1 = parts[0];
                String segment2 = parts[1];
                int score = Integer.parseInt(parts[3]);

                // Create a new SegmentPair object and add it to the list
                SegmentPair pair = new SegmentPair(segment1, segment2, score);
                highScoringPairs.add(pair);
            }
        }
    } finally {
        if (reader != null) {
            reader.close();
        }
    }

    return highScoringPairs;
}
