public class ResourceDirectoriesFinder {

  public Map<String, File> findResourceDirectories(File applicationFilesDirectory, Graph graph) {
    Map<String, File> directories = new HashMap<>();

    for (Node node : graph.getNodes()) {
      if (node.isScoped()) {
        String componentName = node.getComponent();
        File directory = new File(applicationFilesDirectory, componentName);
        directories.put(componentName, directory);
      }
    }

    return directories;
  }

}
