public List<Command> pollPendingCommands(String workerId) {
    List<Command> commandsPolled = new ArrayList<>();
    for (int i = 0; i < commandQueue.size(); i++) {
        Command c = commandQueue.get(i);
        if (c.getWorkerId().equals(workerId)) {
            commandsPolled.add(c);
            commandQueue.remove(i);
            i--;
        }
    }
    return commandsPolled;
}
