public String receiveMessageByPolling(WebSocketConfig config, int timeout) {
    WebSocketHandler webSocketHandler = new WebSocketHandler(config);
    String message = null;
    long startTime = System.currentTimeMillis();
    while (message == null && (System.currentTimeMillis() - startTime) <= timeout) {
        message = webSocketHandler.pollForIncomingMessage();
    }
    return message;
}
