public Entry getEntry(Object key) {
    if (key == null) {
        return null;
    }
    int hash = hash(key.hashCode());
    for (Entry e = table[indexFor(hash, table.length)];
         e != null;
         e = e.next) {
        Object k;
        if (e.hash == hash && ((k = e.key) == key || key.equals(k))) {
            return e;
        }
    }
    return null;
}
