public Method findResolvedMethod(Class<?> clazz) {
    for (Method method : clazz.getDeclaredMethods()) {
        if (method.isAnnotationPresent(CLIResolver.class) && method.isAnnotationPresent(Resolved.class)) {
            return method;
        }
    }
    throw new RuntimeException("No resolved method annotated with CLIResolver found in class " + clazz.getName());
}
