import java.util.Iterator;
import java.util.Spliterator;
import java.util.Spliterators;
import java.util.concurrent.Flow;
import java.util.concurrent.Flow.Publisher;
import java.util.concurrent.Flow.Subscriber;
import java.util.concurrent.Flow.Subscription;

public class DeferredRichIterable<T> implements Flow.Publisher<T>, Iterable<T> {
    private Iterable<? extends T> source;

    public DeferredRichIterable(Iterable<? extends T> source) {
        this.source = source;
    }

    @Override
    public void subscribe(Subscriber<? super T> subscriber) {
        subscriber.onSubscribe(new IteratorSubscription<>(source.iterator(), subscriber));
    }

    @Override
    public Iterator<T> iterator() {
        return source.iterator();
    }

    public static void main(String[] args) {
        DeferredRichIterable<Integer> iterable = new DeferredRichIterable<>(List.of(1, 2, 3));
        iterable.forEach(System.out::println);
    }

    private static class IteratorSubscription<T> implements Subscription {
        private final Iterator<? extends T> iterator;
        private final Subscriber<? super T> subscriber;

        private boolean isCanceled;

        public IteratorSubscription(Iterator<? extends T> iterator, Subscriber<? super T> subscriber) {
            this.iterator = iterator;
            this.subscriber = subscriber;
        }

        @Override
        public void request(long n) {
            if (n <= 0 || isCanceled) {
                return;
            }

            for (long i = 0; i < n && iterator.hasNext(); i++) {
                T next = iterator.next();
                if (next == null) {
                    cancel();
                    subscriber.onError(new NullPointerException("null element"));
                    return;
                }
                subscriber.onNext(next);
            }
            if (!iterator.hasNext()) {
                subscriber.onComplete();
            }
        }

        @Override
        public void cancel() {
            isCanceled = true;
        }
    }
}
