public void addEEDependencyToDeployments(DeploymentUnitContext phaseContext) throws DeploymentUnitProcessingException {
    // Assuming you're using Maven, this code will add the EE APIs as a dependency to all deployments
    final List<ArchivePath> deployments = phaseContext.getAllAttachments().keySet().stream().filter(archivePath -> archivePath.toString().endsWith(".jar")).collect(Collectors.toList());

    for (ArchivePath deployment : deployments) {
        final DeploymentUnit deploymentUnit = phaseContext.getDeploymentUnit().getAttachment(Attachments.DEPLOYMENT_UNIT);
        final DeploymentUnitMetaData deploymentUnitMetaData = deploymentUnit.getAttachment(Attachments.MANIFEST);

        deploymentUnitMetaData.addManifestEntry("Dependencies", "javax:javaee-api:jar:7.0");

        phaseContext.putAttachment(Attachments.MANIFEST, deploymentUnitMetaData);
    }
}
