public static <T> T retry(String action, Callable<T> f, RetryPolicy policy) throws Exception {
    Exception exception = null;
    for (int i = 0; i < policy.getMaxRetries(); i++) {
        try {
            return f.call();
        } catch (IOException e) {
            exception = e;
            if (policy.shouldRetry(i)) {
                Thread.sleep(policy.getDelay());
            } else {
                break;
            }
        }
    }
    String message = String.format("Failed to %s after %d retries", action, policy.getMaxRetries());
    if (exception != null) {
        throw new Exception(message, exception);
    } else {
        throw new Exception(message);
    }
}
