public HashMap<String, Double> calculateTemperatureMetrics(Map<String, Double> data) {
    double sumTemperature = 0.0;
    double maxTemperature = Double.MIN_VALUE;
    double minTemperature = Double.MAX_VALUE;
    for (double temperature : data.values()) {
        sumTemperature += temperature;
        maxTemperature = Math.max(maxTemperature, temperature);
        minTemperature = Math.min(minTemperature, temperature);
    }

    double annualAverageTemperature = sumTemperature / data.size();
    double annualAmplitude = maxTemperature - minTemperature;

    HashMap<String, Double> result = new HashMap<>();
    result.put("TAV", annualAverageTemperature);
    result.put("TAMP", annualAmplitude);
    return result;
}
