/**
 * Checks for timeouts in a list of channels.
 * @param channels the list of channels to check timeouts for
 * @param timeoutMillis the timeout value in milliseconds
 */
public void checkForTimeouts(List<Channel> channels, long timeoutMillis) {
    long currentTime = System.currentTimeMillis();
    for (Channel channel : channels) {
        long lastActivityTime = channel.getLastActivityTime();
        if (currentTime - lastActivityTime > timeoutMillis) {
            channel.onTimeout();
        }
