public void deleteFromDatastore(Entity entity) throws EntityManagerException {
  if(entity.getKey() == null) {
    throw new EntityManagerException("Cannot delete entity without a valid ID");
  }
  try {
    Datastore datastore = DatastoreOptions.getDefaultInstance().getService();
    Key key = entity.getKey();
    datastore.delete(key);
  } catch (Exception e) {
    throw new EntityManagerException("Error while deleting entity", e);
  }
}
