public double crossValidateAndFindOptimalC(List<Data> data, int numFolds, String scorer) {
    double[] C_values = {0.01, 0.1, 1, 10, 100};
    double best_C_val = C_values[0];
    double best_score = 0.0;

    for (double C_val : C_values) {
        double score_sum = 0.0;

        for (int i = 0; i < numFolds; i++) {
            // Split data into train and test for current fold
            List<Data> trainData = new ArrayList<>();
            List<Data> testData = new ArrayList<>();
            // implement splitting logic

            // Train a classifier using current C value and train data
            Classifier classifier = new Classifier(C_val);
            classifier.train(trainData);

            // Test classifier and calculate score
            double foldScore = 0.0;
            switch (scorer) {
                case "F-score":
                    foldScore = classifier.calculateFScore(testData);
                    break;
                case "accuracy":
                    foldScore = classifier.calculateAccuracy(testData);
                    break;
                // Add other scoring options as needed
            }
            score_sum += foldScore;
        }

        // Update best_C_val and best_score if current C value performed better
        double avg_score = score_sum / numFolds;
        if (avg_score > best_score) {
            best_score = avg_score;
            best_C_val = C_val;
        }
    }

    // Save best C value for future use
    // implement save logic

    return best_C_val;
}
