public void buildSheetForConfigMap(Sheet sheet, Map<String, String> sheetConfigMap, Map<String, CellAttributes> cellAttributesMap) {
    for (Map.Entry<String, String> entry : sheetConfigMap.entrySet()) {
        String cellAddress = entry.getKey();
        Cell cell = sheet.getRow(CellReference.convertColStringToIndex(cellAddress)).getCell(CellReference.convertColStringToIndex(cellAddress));
        String cellValue = entry.getValue();
        cell.setCellValue(cellValue);
        CellAttributes cellAttributes = cellAttributesMap.get(cellAddress);
        if(cellAttributes!=null){
            cell.setCellStyle(cellAttributes.getCellStyle());
            if(cellAttributes.getRowSpan() > 1 || cellAttributes.getColSpan() > 1){
                CellRangeAddress mergedRegion = new CellRangeAddress(cell.getRowIndex(),cell.getRowIndex() + cellAttributes.getRowSpan() - 1, cell.getColumnIndex(), cell.getColumnIndex() + cellAttributes.getColSpan() - 1);
                sheet.addMergedRegion(mergedRegion);
            }
        }
    }
}
