public void updateStreamState(StreamState streamState, List<StateUpdate> stateUpdates) {
    for(StateUpdate update : stateUpdates) {
        String key = update.getKey();
        Object value = update.getValue();
        switch (key) {
            case "name":
                streamState.setName((String) value);
                break;
            case "isActive":
                streamState.setActive((Boolean) value);
                break;
            case "values":
                streamState.setValues((List<String>) value);
                break;
            // add more cases as needed for other properties of StreamState
            default:
                throw new IllegalArgumentException("Unknown key: " + key);
        }
    }
}
