public List<Integer> extractTVEColumnIndices(Expression e, List<Integer> accum) {
    if (e instanceof TVEColumn) {
        TVEColumn tve = (TVEColumn) e;
        accum.add(tve.getIndex());
    }
    if (e instanceof Operation) {
        Operation op = (Operation) e;
        for (Expression exp : op.getOperands()) {
            extractTVEColumnIndices(exp, accum);
        }
    }
    return accum;
}
