public static void validateArguments(String[] args, boolean supportsTarget, boolean supportsDefaultTarget) throws IllegalArgumentException {
    String[] validArgs = {"arg1", "arg2", "arg3"}; // Replace with valid arguments for your task
    for (String arg : args) {
        if (!Arrays.asList(validArgs).contains(arg)) {
            throw new IllegalArgumentException("Unknown argument specified: " + arg);
        }
    }
    if (supportsDefaultTarget && !Arrays.asList(args).contains("-D")) {
        throw new IllegalArgumentException("DefaultTarget (-D) not defined");
    }
    if (supportsTarget) {
        boolean targetFound = false;
        for (String arg : args) {
            if (arg.startsWith("-t")) {
                targetFound = true;
                break;
            }
        }
        if (!targetFound) {
            throw new IllegalArgumentException("Target (-t) not defined");
        }
    }
}
