private char[] growBuffer(char[] buffer, int index) {
    if (index == 0) {
      return buffer;
    }
    int newSize = buffer.length;
    while (index > newSize) {
      newSize <<= 1;
    }
    char[] newBuffer = new char[newSize];
    System.arraycopy(buffer, 0, newBuffer, 0, buffer.length);
    return newBuffer;
}
