public ProtoRebalanceTaskInfo convertToProto(RebalanceTaskInfo stealInfo) {
    ProtoRebalanceTaskInfo.Builder builder = ProtoRebalanceTaskInfo.newBuilder();
    builder.setTaskName(stealInfo.getTaskName());
    builder.setTaskId(stealInfo.getTaskId());
    builder.setTaskType(ProtoTaskType.valueOf(stealInfo.getTaskType().name()));
    builder.setPriority(stealInfo.getPriority());
    builder.setSubmissionTime(stealInfo.getSubmissionTime());
    builder.setJobId(stealInfo.getJobId());
    builder.setSourceWorkerHost(stealInfo.getSourceWorkerHost());
    builder.setDestinationWorkerHost(stealInfo.getDestinationWorkerHost());
    builder.setTaskConfiguration(ProtoTaskConfiguration.newBuilder()
            .setTaskConfig(stealInfo.getTaskConfiguration().getTaskConfig())
            .setSerializedTaskConfig(stealInfo.getTaskConfiguration().getSerializedTaskConfig())
            .build());
    builder.setTargetTaskResources(ProtoTaskResources.newBuilder()
            .setCpu(stealInfo.getTargetTaskResources().getCpu())
            .setRam(stealInfo.getTargetTaskResources().getRam())
            .setDisk(stealInfo.getTargetTaskResources().getDisk())
            .setNetwork(stealInfo.getTargetTaskResources().getNetwork())
            .build());
    builder.setTargetResourceProfile(ProtoResourceProfile.newBuilder()
            .setCpu(stealInfo.getTargetResourceProfile().getCpu())
            .setRam(stealInfo.getTargetResourceProfile().getRam())
            .setDisk(stealInfo.getTargetResourceProfile().getDisk())
            .setNetwork(stealInfo.getTargetResourceProfile().getNetwork())
            .build());
    builder.setTaskState(ProtoTaskState.valueOf(stealInfo.getTaskState().name()));
    builder.setStolenFrom(ProtoWorkerInfo.newBuilder()
            .setWorkerId(stealInfo.getStolenFrom().getWorkerId())
            .setWorkerHost(stealInfo.getStolenFrom().getWorkerHost())
            .setWorkerPort(stealInfo.getStolenFrom().getWorkerPort())
            .setAvailableCpu(stealInfo.getStolenFrom().getAvailableCpu())
            .setAvailableRam(stealInfo.getStolenFrom().getAvailableRam())
            .setAvailableDisk(stealInfo.getStolenFrom().getAvailableDisk())
            .setAvailableNetwork(stealInfo.getStolenFrom().getAvailableNetwork())
            .build());
    return builder.build();
}
