public void adjustNameServiceConfig(Map<String, String> nameServiceKeys) {
    // iterate over the keys in the map and modify the configuration accordingly
    for (Map.Entry<String, String> entry : nameServiceKeys.entrySet()) {
        String key = entry.getKey();
        String value = entry.getValue();

        // modify the configuration based on the key-value pair
        switch(key) {
            case "location":
                // set location for name service
                setNameServiceLocation(value);
                break;
            case "cacheSize":
                // set cache size for name service
                setNameServiceCacheSize(Integer.parseInt(value));
                break;
            case "timeout":
                // set timeout for name service
                setNameServiceTimeout(Integer.parseInt(value));
                break;
            default:
                // handle unknown keys or values
                throw new IllegalArgumentException("Unknown name service configuration key: " + key);
        }
    }
}
