public void appendExpression(StringBuilder sb, Expression expr) {
    if (expr instanceof BinaryExpression) {
        BinaryExpression binaryExpr = (BinaryExpression) expr;
        sb.append("(");
        appendExpression(sb, binaryExpr.getLeft());
        sb.append(binaryExpr.getOperator().toString());
        appendExpression(sb, binaryExpr.getRight());
        sb.append(")");
    } else if (expr instanceof UnaryExpression) {
        UnaryExpression unaryExpr = (UnaryExpression) expr;
        sb.append("(");
        sb.append(unaryExpr.getOperator().toString());
        appendExpression(sb, unaryExpr.getOperand());
        sb.append(")");
    } else if (expr instanceof LiteralExpression) {
        LiteralExpression literalExpr = (LiteralExpression) expr;
        sb.append(literalExpr.getValue().toString());
    } else {
        throw new IllegalArgumentException("Unsupported expression type: " + expr.getClass().getName());
    }
}
