public Assertion verifyObservable(Observable expectedValue) {
    // check if the actual observable has the same value as the expected observable
    if (actualObservable.getValue().equals(expectedValue.getValue())) {
        return this;
    }
    // if not, throw an assertion error with a message indicating the failure
    throw new AssertionError("Observable values do not match: expected " + expectedValue.getValue() + " but was " + actualObservable.getValue());
}
