import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

public class CSVLoader {

    // Store the CSV data in an ArrayList
    private List<String[]> data = new ArrayList<>();

    public CSVLoader(String filename) {
        // Read the CSV file and populate the data list
        try (BufferedReader reader = new BufferedReader(new FileReader(filename))) {
            String line;
            while ((line = reader.readLine()) != null) {
                // Split the line into an array of values and add to data
                data.add(line.split(","));
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    // Retrieve a specific field from the CSV data
    public String getField(int rowIndex, int columnIndex) {
        if (rowIndex < 0 || rowIndex >= data.size() ||
            columnIndex < 0 || columnIndex >= data.get(rowIndex).length) {
            return null;
        }
        return data.get(rowIndex)[columnIndex];
    }

}
