public Context constructCLabsForNodes(Context context) throws ContextPreprocessorException {
    // Check if context is null
    if (context == null) {
        throw new ContextPreprocessorException("Context parameter cannot be null.");
    }

    // Get all nodes of the context
    List<Node> nodes = context.getNodes();

    // Construct cLab for each node
    for (Node node : nodes) {
        CLab cLab = new CLab(node);
        node.setCLab(cLab);
    }

    // Return context with updated cLabs
    return context;
}
