public static double smallestAngle(double alpha, double beta) {
    double delta = beta - alpha;
    double modDelta = (delta + 360.0) % 360.0; 
    double oppositeDelta = (modDelta > 0.0)? modDelta - 360.0: modDelta + 360.0; 
    double absDelta = Math.abs(modDelta); 
    double absOppositeDelta = Math.abs(oppositeDelta); 

    if (absDelta < absOppositeDelta) {
        return modDelta;
    } else {
        return oppositeDelta;
    }
}
