public static int nextTwinPrime(int m) {
    int nextPrime = m % 2 == 0 ? m + 1 : m + 2;
    while (!isTwinPrime(nextPrime)) {
        nextPrime += 2;
    }
    return nextPrime;
}

public static boolean isTwinPrime(int n) {
    return isPrime(n) && (isPrime(n - 2) || isPrime(n + 2));
}

public static boolean isPrime(int n) {
    if (n < 2) {
        return false;
    }
    for (int i = 2; i <= Math.sqrt(n); i++) {
        if (n % i == 0) {
            return false;
        }
    }
    return true;
}
