public static boolean isBeanAccessor(String methodName, int actualParameterCount, int requiredParameterCount, String prefix, Class<?> returnType, Class<?> requiredReturnType, boolean includeType) {
    if (methodName == null || prefix == null) {
        return false;
    }
    if (methodName.length() <= prefix.length() || !methodName.startsWith(prefix)) {
        return false;
    }
    String propertyName = methodName.substring(prefix.length());
    boolean isGetter = (actualParameterCount == 0 && returnType != null &&
            (returnType.equals(requiredReturnType) || requiredReturnType == null) &&
            (propertyName.length() > 0 && Character.isUpperCase(propertyName.charAt(0))));
    boolean isSetter = (actualParameterCount == 1 && returnType == void.class &&
            (propertyName.length() > 0 && Character.isUpperCase(propertyName.charAt(0))));
    if (includeType && returnType != null) {
        isGetter = (isGetter && returnType.getName().equals(requiredReturnType.getName()));
    }
    return isGetter || isSetter;
}
