import javax.swing.*;
import javax.swing.border.*;
import java.awt.*;

public static JComponent decorateWithShadow(JComponent comp, Color outline, int margin) {
    ShadowBorder border = new ShadowBorder(outline, margin);
    DCPanel panel = new DCPanel(border);
    panel.add(comp);
    return panel;
}

private static class DCPanel extends JPanel {
    DCPanel(Border border) {
        setLayout(new BorderLayout());
        setOpaque(false);
        setBorder(border);
    }

    @Override
    public void paintComponent(Graphics g) {
        // Paint the shadow border in the panel's background color
        super.paintComponent(g);
        Dimension size = getSize();
        Insets insets = getInsets();
        int width = size.width - insets.left - insets.right;
        int height = size.height - insets.top - insets.bottom;
        g.setColor(getBackground());
        ((ShadowBorder)getBorder()).paintBorder(this, g, 0, 0, width, height);
    } 
}

private static class ShadowBorder extends AbstractBorder {
    private static final long serialVersionUID = 1L;
    private static final int RADIUS = 10;
    private static final int OFFSET_X = 0;
    private static final int OFFSET_Y = 3;
    private static final int SHADOW_THICKNESS = 5;

    private final Color color;
    private final int thickness;

    ShadowBorder(Color color, int thickness) {
        this.color = color;
        this.thickness = thickness;
    }

    @Override
    public Insets getBorderInsets(Component c) {
        return new Insets(thickness, thickness, thickness + RADIUS, thickness + RADIUS);
    }

    @Override
    public Insets getBorderInsets(Component c, Insets insets) {
        insets.left = insets.right = insets.bottom = thickness;
        insets.top = thickness + RADIUS;
        return insets;
    }

    @Override
    public void paintBorder(Component c, Graphics g, int x, int y, int width, int height) {
        Graphics2D g2 = (Graphics2D) g.create();
        g2.translate(x, y);
        g2.setColor(color);
        g2.fillRoundRect(
            OFFSET_X, 
            OFFSET_Y, 
            width - 2 * OFFSET_X, 
            height - OFFSET_Y - RADIUS, 
            RADIUS, RADIUS
        );
        g2.dispose();
    }
}
