public static double[] sigmoidDerivative(double[] x, double[] wrt) {
    double[] result = new double[x.length];
    for (int i = 0; i < x.length; i++) {
        double sigmoid = 1 / (1 + Math.exp(-x[i]));
        result[i] = sigmoid * (1 - sigmoid) * wrt[i];
    }
    return result;
}
