public void removeUnusedViewsFromCache(int viewType) {
    Iterator<Map.Entry<Integer, View>> iterator = viewCache.entrySet().iterator();
    while (iterator.hasNext()) {
        Map.Entry<Integer, View> entry = iterator.next();
        if (entry.getKey() == viewType && entry.getValue().getParent() == null) {
            iterator.remove();
        }
