public static int decodeVersionInformation(int[] bits) {
    int version = -1;
    int versionBits = 0;
    for (int i = 0; i < 6; i++) {
        versionBits <<= 1;
        versionBits |= bits[i];
    }
    for (int i = 0; i < Constants.getVersionInfoPolynomial(versionBits); i++) {
        if (bits[i + 6] == 0 || versionBits >> (Constants.getVersionInfoPolynomial(versionBits) - i - 1) == 0x01) {
            version = versionBits & 0x0f;
            break;
        }
    }
    return version;
}
