public Map<String, Map<Integer, Integer>> getStatusCodeDistribution(List<Map<String, String>> resultList) {
    Map<String, Map<Integer, Integer>> aggregateResultMap = new HashMap<>();
    for (Map<String, String> result : resultList) {
        String targetHost = result.get("targetHost");
        int statusCode = Integer.parseInt(result.get("statusCode"));
        if (!aggregateResultMap.containsKey(targetHost)) {
            aggregateResultMap.put(targetHost, new HashMap<>());
        }
        if (!aggregateResultMap.get(targetHost).containsKey(statusCode)) {
            aggregateResultMap.get(targetHost).put(statusCode, 1);
        } else {
            aggregateResultMap.get(targetHost).put(statusCode, aggregateResultMap.get(targetHost).get(statusCode) + 1);
        }
    }
    return aggregateResultMap;
}
