        voltQueueSQL(getStations);
        final VoltTable stationsResult = voltExecuteSQL()[0];
        final List<Short> stations = new ArrayList<>();
        while (stationsResult.advanceRow()) {
            final short station = (short) stationsResult.getLong("station_id");
            stations.add(station);
            voltQueueSQL(getLastDeparts, station);
        }

        final List<StationStats> stationStats = getStationStats(stations, voltExecuteSQL());

        for (StationStats stats : stationStats) {
            voltQueueSQL(updateWaitTime,
                         stats.station,
                         stats.lastDepartTime,
                         stats.totalTime,
                         stats.totalEntries);
        }

        voltQueueSQL(deleteOldData, -ttl_seconds);
        return voltExecuteSQL(true);
