public List<InterceptorBinding> mergeInterceptorBindings(List<InterceptorBinding> classLevelBindings, List<InterceptorBinding> inheritedBindings, List<InterceptorBinding> stereotypeBindings) {
    List<InterceptorBinding> mergedBindings = new ArrayList<>();

    // Add all the class-level bindings to the merged list
    mergedBindings.addAll(classLevelBindings);

    // Iterate through the inherited bindings and add them to the merged list if they are not already present
    for (InterceptorBinding inheritedBinding : inheritedBindings) {
        if (!mergedBindings.contains(inheritedBinding)) {
            mergedBindings.add(inheritedBinding);
        }
    }

    // Iterate through the stereotype bindings and add them to the merged list if they are not already present
    for (InterceptorBinding stereotypeBinding : stereotypeBindings) {
        if (!mergedBindings.contains(stereotypeBinding)) {
            mergedBindings.add(stereotypeBinding);
        }
    }

    return mergedBindings;
}
