import java.io.File;
import java.io.IOException;
import java.nio.channels.FileLock;
import java.nio.file.Files;
import java.nio.file.StandardCopyOption;

public void makeFileImmutable(String src, FileLock lease) throws IOException {
    File file = new File(src);
    // Move the file to a temporary location
    File tempFile = new File(file.getParent(), file.getName() + ".tmp");
    Files.move(file.toPath(), tempFile.toPath(), StandardCopyOption.REPLACE_EXISTING);
    // Release the lease
    lease.release();
    // Move the temporary file back to the original location
    Files.move(tempFile.toPath(), file.toPath(), StandardCopyOption.REPLACE_EXISTING);
    // Set the file to be immutable
    file.setReadOnly();
}
