public List<Integer> guessAbortedIds(int configuredPoolSize, int currentParallelism, int safeScaleDownFactor) {
    List<Integer> abortedIds = new ArrayList<>();
    int maxNumOfWorkers = configuredPoolSize * currentParallelism * safeScaleDownFactor;
    for (int i = 1; i <= maxNumOfWorkers; i++) {
        if (i % currentParallelism != 0) {
            abortedIds.add(i);
        }
    }
    return abortedIds;
}
