public int getBinIndex(double x) {
    // assuming binSize and numBins are known variables
    int binIndex = (int) Math.floor(x / binSize);
    if (binIndex < 0) {
        binIndex = 0;
    } else if (binIndex >= numBins) {
        binIndex = numBins - 1;
    }
    return binIndex;
}
