public List<ShortcutInfo> getDynamicPinnedShortcuts() {
    List<ShortcutInfo> pinnedShortcuts = new ArrayList<>();
    ShortcutManager shortcutManager = getSystemService(ShortcutManager.class);
    if (shortcutManager != null) {
        List<ShortcutInfo> allShortcuts = shortcutManager.getDynamicShortcuts();
        for (ShortcutInfo shortcut : allShortcuts) {
            if (shortcut.isPinned()) {
                pinnedShortcuts.add(shortcut);
            }
        }
    }
    return pinnedShortcuts;
}
