import javax.swing.*;
import javax.swing.text.DateFormatter;
import java.awt.*;
import java.text.DateFormat;
import java.text.ParseException;
import java.text.SimpleDateFormat;
import java.util.Calendar;
import java.util.Date;

public static void addTimePickerToTextField(JFormattedTextField field, String format, boolean[] filter) {
    DateFormat dateFormat = new SimpleDateFormat(format);
    field.setColumns(8); // Change size of field as per requirement
    field.setValue(Calendar.getInstance().getTime()); // Set current time as preset value in text field
    DateFormatter formatter = new DateFormatter(dateFormat);
    formatter.setAllowsInvalid(false);
    formatter.setOverwriteMode(true);
    field.setFormatterFactory(new DefaultFormatterFactory(formatter));
    // Add a date picker to the text field
    JSpinner timeSpinner = new JSpinner(new SpinnerDateModel());
    JSpinner.DateEditor timeEditor = new JSpinner.DateEditor(timeSpinner, format);
    timeEditor.getTextField().setEditable(false); // Disable text field of the spinner
    timeSpinner.setEditor(timeEditor);

    // Disable some days that are not selectable
    JSpinner.DateEditor editor = new JSpinner.DateEditor(timeSpinner, format);
    JComponent arrow = editor.getUiComponent().getComponent(0);
    arrow.setVisible(false);

    if (filter != null && filter.length > 0) {
        for (int i = 0; i < filter.length; i++) {
            // Set the disabled dates in the time picker
            if (filter[i]) {
                Calendar calendar = Calendar.getInstance();
                calendar.setTime((Date) timeSpinner.getValue());
                calendar.add(Calendar.DAY_OF_MONTH, i);
                Date date = calendar.getTime();
                editor.getFormat().setEditable(false);
                arrow.setVisible(false);
                editor.getUiComponent().setEnabled(false);
                JFormattedTextField tf = editor.getTextField();
                try {
                    Date existingDate = editor.getFormat().parse(tf.getText());
                    if (existingDate.after(date) || existingDate.before(date)) {
                        tf.setValue(dateFormat.format(date));
                    }
                } catch (ParseException e) {
                    tf.setValue(dateFormat.format(date));
                }
            }
        }
    }
    field.add(timeSpinner);
}
