public void replaceValue(JSONObject bodyObj, Object replaceValue) {
    for (Object key : bodyObj.keySet()) {
        Object value = bodyObj.get(key);
        if (value instanceof JSONObject) {
            replaceValue((JSONObject) value, replaceValue);
        } else if (value instanceof JSONArray) {
            for (int i = 0; i < ((JSONArray) value).size(); i++) {
                replaceValue(((JSONArray) value).getJSONObject(i), replaceValue);
            }
        } else if (value.equals(replaceValue)) {
            bodyObj.put(key.toString(), "REPLACED_VALUE");
        }
    }
}
