import java.util.ArrayList;
import java.util.List;

public List<String> tokenizeParagraph(MorphoAnalyzer morphoAnalyzer, String paragraph) {

    List<String> sentences = new ArrayList<String>();     // create a list to store sentences

    String[] tokens = paragraph.split("\\s+");     // split paragraph by whitespace

    String sentence = "";
    for(String token : tokens) {
        sentence += token + " ";    // add token with space to sentence
        if(morphoAnalyzer.isSentenceEnd(token)) {   // check if token indicates end of sentence
            sentences.add(sentence.trim());     // add sentence to list and trim whitespace
            sentence = "";    // reset sentence
        }
    }
    if(!sentence.isEmpty()) {   // add any remaining text as a sentence
        sentences.add(sentence.trim());
    }

    return sentences;
}
