public boolean waitForFragment(String tag, String id, long timeout) {
    long startTime = System.currentTimeMillis();
    while (System.currentTimeMillis() - startTime <= timeout) {
        Fragment fragment = null;
        if (tag != null) {
            fragment = getSupportFragmentManager().findFragmentByTag(tag);
        } else if (id != null) {
            fragment = getSupportFragmentManager().findFragmentById(Integer.parseInt(id));
        }
        if (fragment != null) {
            return true;
        }
        try {
            Thread.sleep(100);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
    }
    return false;
}
