public List<IAtomType> readAtomTypesFromOWL(IChemObjectBuilder builder, InputStream inputStream) throws IOException {
    OWLOntologyManager manager = OWLManager.createOWLOntologyManager();
    OWLOntology owlOntology = manager.loadOntologyFromOntologyDocument(inputStream);

    List<IAtomType> atomTypes = new ArrayList<>();

    Set<OWLClass> classes = owlOntology.getClassesInSignature();
    for (OWLClass cls : classes) {
        IAtomType atomType = builder.newInstance(IAtomType.class);
        atomType.setAtomTypeName(cls.getIRI().getFragment());
        Set<OWLAnnotation> annotations = cls.getAnnotations(owlOntology);
        for (OWLAnnotation annotation : annotations) {
            if (annotation.getProperty().isLabel()) {
                atomType.setDescription(annotation.getValue().toString());
            }
            if (annotation.getProperty().isComment()) {
                atomType.setSpecification(annotation.getValue().toString());
            }
        }
        atomTypes.add(atomType);
    }

    return atomTypes;
}
