public boolean hasInsufficientReplicas(int[] targetReplicaAssignment, int[] clusterReplicaAssignment) {
    // Initialize an array to keep track of the number of replicas for each tier
    int[] replicaCounts = new int[targetReplicaAssignment.length];

    // Update the replica counts for each tier in the target replica assignment
    for (int replica : targetReplicaAssignment) {
        replicaCounts[replica]++;
    }

    // Check if any tier in the target replica assignment has insufficient replicas
    for (int i = 0; i < targetReplicaAssignment.length; i++) {
        if (replicaCounts[targetReplicaAssignment[i]] > clusterReplicaAssignment[targetReplicaAssignment[i]]) {
            return true;
        }
    }

    return false;
}
