import org.nd4j.linalg.api.ndarray.INDArray;
import org.nd4j.linalg.factory.Nd4j;

public static INDArray jaccardSimilarityReduction(INDArray x, INDArray y, int... dimensions) {
    INDArray intersection = Nd4j.getExecutioner().exec(new And(x.gt(0), y.gt(0)));
    INDArray union = Nd4j.getExecutioner().exec(new Or(x.gt(0), y.gt(0)));
    INDArray jaccard = intersection.sum(dimensions).divi(union.sum(dimensions));
    INDArray jaccardDistance = Nd4j.onesLike(jaccard).sub(jaccard);
    return jaccardDistance;
}
