public static Image convolveWithBoxFilter(IntegralImage integral, double[][] kernel, Image output) {
    if (output == null)
        output = new Image(integral.getWidth() - kernel.length + 1, integral.getHeight() - kernel[0].length + 1);
    for (int y = 0; y < output.getHeight(); y++) {
        for (int x = 0; x < output.getWidth(); x++) {
            double sum = 0;
            for (int ky = 0; ky < kernel[0].length; ky++) {
                int y0 = y + ky;
                int y1 = y0 - kernel[0].length;
                for (int kx = 0; kx < kernel.length; kx++) {
                    int x0 = x + kx;
                    int x1 = x0 - kernel.length;
                    sum += (integral.getSum(x0, y0) + integral.getSum(x1, y1)
                            - integral.getSum(x0, y1) - integral.getSum(x1, y0))
                            * kernel[kx][ky];
                }
            }
            output.set(x, y, sum);
        }
    }
    return output;
}
