public String getSuccessMessageFromCookie() {
    // Retrieve the cookie containing the success message
    Cookie[] cookies = request.getCookies();
    if (cookies != null) {
        for (Cookie cookie : cookies) {
            if (cookie.getName().equals("azkaban.success.message")) {
                return cookie.getValue();
            }
        }
    }
    // If cookie not found or the value is empty, return default message
    return "Your request was completed successfully.";
}
