public TreeElement findSelectedElement(TreeElement elem) {
  if(elem.isSelected()){
    return elem;
  }else{
    for(TreeElement child: elem.getChildren()){
      TreeElement selected = findSelectedElement(child);
      if(selected != null){
        return selected;
      }
    }
    return null;
  }
}
