import javax.xml.bind.JAXBContext;
import javax.xml.bind.JAXBException;
import javax.xml.bind.Marshaller;
import javax.xml.bind.Unmarshaller;

import org.eclipse.persistence.jaxb.JAXBContextFactory;

public static JAXBContext getJAXBContext(Class<?>... classes) throws JAXBException {
    ClassLoader classLoader = Thread.currentThread().getContextClassLoader();

    return JAXBContextFactory.createContext(classes, null, classLoader);
}

public static Marshaller getMarshaller(Class<?>... classes) throws JAXBException {
    JAXBContext jaxbContext = getJAXBContext(classes);

    Marshaller marshaller = jaxbContext.createMarshaller();
