public int getFirstChildHandle(int nodeHandle) {
    int firstChild = m_expandedNameTable.getFirstChild(nodeHandle);
    if (firstChild == DTM.NULL) {
        return DTM.NULL;
    }
    while (needsTwoThreads()) { // this method checks whether the thread is available to wait 
        try {
            Thread.sleep(50);
        } catch (InterruptedException e) {
            // ignore
        }
    }
    int firstChildHandle = m_parent.doWaitForChild(nodeHandle, firstChild, true, 0);
    if (firstChildHandle == -1) {
        return DTM.NULL;
    }
    return firstChildHandle;
}
