public static int[] createIntArray(byte[] buffer, int bitCount, ByteOrder order) {
    int byteSize = buffer.length;
    int intSize = (int) Math.ceil((float) bitCount / Integer.SIZE);
    int[] intArray = new int[intSize];

    ByteBuffer bb = ByteBuffer.wrap(buffer);
    bb.order(order);

    for(int i=0; i < intSize; i++) {
        if(bitCount <= 8) {
            intArray[i] = bb.get() & 0xFF;
        } else if(bitCount <= 16) {
            intArray[i] = bb.getShort() & 0xFFFF;
        } else if(bitCount <= 32) {
            intArray[i] = bb.getInt();
        } else {
            throw new IllegalArgumentException("Bit count overflows int size.");
        }
    }

    return intArray;
}
