            .reduceSingle(source, (single, transformer) -> transformer.apply(single));
    return new Subscriber<T>() {
        @Override
        public void onSubscribe(Subscription s) {
            instrumented.subscribe(s);
        }
        @Override
        public void onNext(T t) {
            // Implement the onNext method if required
        }
        @Override
        public void onError(Throwable t) {
            // Implement the onError method if required
        }
        @Override
        public void onComplete() {
            // Implement the onComplete method if required
        }
    };
}
