public static double averageWordsPerSentence(String strText) {
    if (strText == null || strText.isEmpty()) {
        return 0;
    }
    String[] sentences = strText.split("[!?.:]+\\s*");
    int numSentences = sentences.length;
    int numWords = 0;
    for (String sentence : sentences) {
        numWords += sentence.split("\\s+").length;
    }
    return (double) numWords / numSentences;
}
