public Class<?> resolveEnclosingClass(int pos, Env<?> env, MemberInstance<?, ?> member) {
    ClassType ct = (ClassType) env.outermost();

    while (ct.outer() != null) {
        if (ct.record() == member.container()) 
            return ct.getDecl();
        ct = (ClassType) ct.outer();
    }

    throw new AssertionError("no enclosing class found");
}
