public void writeLastCheckpointTimeToFile(String sd) throws IOException{
   // get the current date and time
   LocalDateTime currentDateTime = LocalDateTime.now();

   // format the current date and time in desired format (e.g. yyyy-MM-dd HH:mm:ss)
   DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");
   String formattedDateTime = currentDateTime.format(formatter);

   // write the formatted date and time to a file called "last_checkpoint.txt"
   BufferedWriter writer = new BufferedWriter(new FileWriter("last_checkpoint.txt"));
   writer.write(formattedDateTime);

   // close the writer
   writer.close();
}
