import javax.net.ssl.SSLEngine;
import javax.net.ssl.SSLContext;
import java.net.SocketAddress;
import java.util.Map;

public class SSLUtils {

    public static SSLEngine createSSLEngine(SSLContext sslContext, Map<String, ?> optionMap, SocketAddress peerAddress) {
        SSLEngine engine = sslContext.createSSLEngine();
        engine.setUseClientMode(false);

        // Configure the SSL engine from the option map
        for (Map.Entry<String, ?> entry : optionMap.entrySet()) {
            String key = entry.getKey();
            Object value = entry.getValue();

            switch (key) {
                case "enabledProtocols":
                    engine.setEnabledProtocols((String[]) value);
                    break;
                case "enabledCipherSuites":
                    engine.setEnabledCipherSuites((String[]) value);
                    break;
                case "wantClientAuth":
                    engine.setWantClientAuth((Boolean) value);
                    break;
                case "needClientAuth":
                    engine.setNeedClientAuth((Boolean) value);
                    break;
                case "useClientMode":
                    engine.setUseClientMode((Boolean) value);
                    break;
                case "allowUnsafeRenegotiation":
                    engine.setAllowUnsafeRenegotiation((Boolean) value);
                    break;
                case "needClientAuth":
                    engine.setNeedClientAuth((Boolean) value);
                    break;
                case "enabledProtocols":
                    engine.setEnabledProtocols((String[]) value);
                    break;
                default:
                    throw new IllegalArgumentException("Unknown option: " + key);
            }
        }

        return engine;
    }
}
