import javax.lang.model.element.VariableElement;
import com.sun.source.tree.Tree.Kind;
import com.sun.source.util.TreePathScanner;
import com.sun.tools.javac.tree.JCTree.JCVariableDecl;

public List<ASTParameter> buildASTParameters(List<VariableElement> variableElements) {
    List<ASTParameter> astParams = new ArrayList<>();
    for (VariableElement variableElement : variableElements) {
        ASTParameter astParam = new ASTParameter(variableElement.getSimpleName().toString(), variableElement.asType().toString(), variableElement);
        new TreePathScanner<Void, Void>() {
            @Override
            public Void visitVariable(JCVariableDecl jcVariableDecl, Void aVoid) {
                if (jcVariableDecl.getName().toString().equals(variableElement.getSimpleName().toString()) && jcVariableDecl.getType().toString().equals(variableElement.asType().toString())) {
                    if (jcVariableDecl.getInitializer() != null) {
                        astParam.setDefaultValue(jcVariableDecl.getInitializer().getKind() == Kind.STRING_LITERAL ? jcVariableDecl.getInitializer().toString().replace("\"", "") : jcVariableDecl.getInitializer().toString());
                    }
                    return null;
                }
                return super.visitVariable(jcVariableDecl, aVoid);
            }
        }.scan(compilationUnit, null);
        astParams.add(astParam);
    }
    return astParams;
}

class ASTParameter {
    private String name;
    private String type;
    private String defaultValue;
    private VariableElement variableElement;

    public ASTParameter(String name, String type, VariableElement variableElement) {
        this.name = name;
        this.type = type;
        this.variableElement = variableElement;
    }

    public void setDefaultValue(String defaultValue) {
        this.defaultValue = defaultValue;
    }

    public String getName() {
        return name;
    }

    public String getType() {
        return type;
    }

    public String getDefaultValue() {
        return defaultValue;
    }

    public VariableElement getVariableElement() {
        return variableElement;
    }
}
