public boolean executeRunnables(Queue<Runnable> queue) {
    boolean executed = false;
    Runnable latest = null;
    while (!queue.isEmpty()) {
        Runnable current = queue.poll();
        if (current != latest) {
            executed = true;
            current.run();
            latest = current;
        }
        for (Runnable r : queue) {
            if (r instanceof ScheduledRunnable) {
                ScheduledRunnable sr = (ScheduledRunnable) r;
                if (sr.getDelay() < 0 && sr.getTask().scheduledExecutionTime() < latestExecutionTime) {
                    queue.remove(sr);
                    sr.getTask().run();
                    executed = true;
                }
            }
        }
    }
    return executed;
}
