public enum IndexOperator {
    EQUALS("="),
    GREATER_THAN(">"),
    GREATER_THAN_OR_EQUALS(">="),
    LESS_THAN("<"),
    LESS_THAN_OR_EQUALS("<=");

    private final String symbol;

    IndexOperator(String symbol) {
        this.symbol = symbol;
    }

    public static IndexOperator fromString(String operator) {
        for (IndexOperator op : IndexOperator.values()) {
            if (op.symbol.equalsIgnoreCase(operator)) {
                return op;
            }
        }
        return null;
    }
}
