public AntlrDatatypeRuleToken ruleOpMultiAssign(String kw) {
    AntlrDatatypeRuleToken current = new AntlrDatatypeRuleToken();

    switch (kw) {
        case "+=":
            current.setText("+=");
            break;
        case "-=":
            current.setText("-=");
            break;
        case "*=":
            current.setText("*=");
            break;
        case "/=":
            current.setText("/=");
            break;
        case "%=":
            current.setText("%=");
            break;
        case "<<=":
            current.setText("<<=");
            break;
        case ">>=":
            current.setText(">>=");
            break;
        case "<=<=":
            current.setText("<<=");
            break;
        case ">><=":
            current.setText(">>=");
            break;
        default:
            // Throw exception or handle error accordingly
            break;
    }

    return current;
}
