public static <T> Supplier<T> lazy(Supplier<T> supplier) {
    return new Supplier<T>() {
        private T value;
        private boolean evaluated = false;

        @Override
        public T get() {
            if (!evaluated) {
                value = supplier.get();
                evaluated = true;
            }
            return value;
        }
    };
}
