public static String getRangeAddress(int row1, int col1, int row2, int col2) {
    String colName1 = convertColNumToColName(col1);
    String colName2 = convertColNumToColName(col2);
    return colName1 + row1 + ":" + colName2 + row2;
}

private static String convertColNumToColName(int colNum) {
    StringBuilder sb = new StringBuilder();
    while (colNum > 0) {
        int remainder = (colNum - 1) % 26;
        sb.insert(0, (char) (65 + remainder));
        colNum = (colNum - 1) / 26;
    }
    return sb.toString();
}
