public static boolean isQualifiedForDeletion(String rawDatasetPath, List<String> refinedPaths) {
    File rawDatasetDir = new File(rawDatasetPath);
    long rawModTime = getLatestModTime(rawDatasetDir.listFiles());

    for (String refinedPath : refinedPaths) {
        File refinedDir = new File(refinedPath);
        if (!refinedDir.exists()) {
            continue;
        }
        long refinedModTime = getLatestModTime(refinedDir.listFiles());
        if (rawModTime <= refinedModTime) {
            return false;
        }
    }
    return true;    
}

private static long getLatestModTime(File[] files) {
    long latest = Long.MIN_VALUE;
    for (File file : files) {
        long modTime = file.lastModified();
        if (modTime > latest) {
            latest = modTime;
        }
    }
    return latest;
}
