public void removeRemoteFileOrDirectory(String path, boolean force, boolean recurse) throws SftpStatusException, SshException {
    File remoteFile = new File(path);
    if (remoteFile.exists()) {
        if (remoteFile.isDirectory() && recurse) {
            // delete directory recursively
            for (File file : remoteFile.listFiles()) {
                if (file.isDirectory()) {
                    removeRemoteFileOrDirectory(file.getAbsolutePath(), force, recurse);
                } else {
                    if (!force) {
                        if (!file.delete()) {
                            throw new SftpStatusException(0, "File " + file.getAbsolutePath() + " could not be deleted.");
                        }
                    } else {
                        file.delete();
                    }
                }
            }
        }
        if (!force) {
            if (!remoteFile.delete()) {
                throw new SftpStatusException(0, "File " + remoteFile.getAbsolutePath() + " could not be deleted.");
            }
        } else {
            remoteFile.delete();
        }
    }
}
