public boolean addPropertyValueToGeoPackage(String geoPackage, String property, String value) {
    try {
        // Open the GeoPackage file
        GeoPackage gpkg = new GeoPackage(new File(geoPackage));

        // Add the property value to the specified GeoPackage
        if (gpkg.getTables().contains(property)) {
            FeatureDao dao = gpkg.getFeatureDao(property);
            FeatureRow row = dao.newRow();
            row.setValue(1, value);
            dao.create(row);
        }

        // Close the GeoPackage file
        gpkg.close();

        return true;
    } catch (Exception e) {
        e.printStackTrace();
        return false;
    }
}
