public Range intersect(Range r) throws InvalidRangeException {
    if (this.isEmpty() || r.isEmpty()) {
        return Range.EMPTY;
    }

    if (this.stride() != 1 || r.stride() != 1) {
        throw new UnsupportedOperationException("Intersection of Ranges with strides is not supported");
    }

    int high = Math.min(this.last(), r.last());
    int low = Math.max(this.first(), r.first());

    if (high < low) {
        return Range.EMPTY;
    }

    return Range.closed(low, high);
}
