public static String getNaaccrFormat(String flatFile) {

    BufferedReader reader = null;

    try {
        reader = new BufferedReader(new FileReader(flatFile));
        String line = reader.readLine();

        if (line != null) {
            String[] fields = line.split("\\|");

            if (fields.length == 233) {
                return "NAACCR 15";
            } else if (fields.length == 384) {
                return "NAACCR 16";
            }
        }
    } catch (IOException e) {
        e.printStackTrace();
    } finally {
        try {
            if (reader != null) {
                reader.close();
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    return null;
}
