public static <T> void populateSerializationInstance(T instance, Map<String, Object> dataMap) {
    try {
        BeanInfo beanInfo = Introspector.getBeanInfo(instance.getClass());
        ObjectInputStream inputStream = new ObjectInputStream(new ByteArrayInputStream(new byte[]{}));
        ObjectOutputStream outputStream = new ObjectOutputStream(new ByteArrayOutputStream());
        for (PropertyDescriptor propertyDescriptor : beanInfo.getPropertyDescriptors()) {
            String key = propertyDescriptor.getName();
            if (dataMap.containsKey(key)) {
                Method setter = propertyDescriptor.getWriteMethod();
                if (setter != null) {
                    Object value = dataMap.get(key);
                    if (value != null && !setter.getParameterTypes()[0].isAssignableFrom(value.getClass())) {
                        try {
                            value = new ObjectMapper().convertValue(value, setter.getParameterTypes()[0]);
                        } catch (IllegalArgumentException e) {
                            //Could not convert the value to match the parameter type of the setter method
                            continue;
                        }
                    }
                    setter.invoke(instance, value);
                }
            }
        }
        inputStream.readObject();
        outputStream.writeObject(instance);
    } catch (IOException | IntrospectionException | InvocationTargetException | IllegalAccessException | ClassNotFoundException e) {
        //Handle any exceptions
        e.printStackTrace();
    }
}
