public int getHighestNonOverlappingLevel(Font font, FontRenderContext frc, boolean horizontal, int xyLinesConstantValue) {
    int level = 0;
    Rectangle2D previousLabelBounds = null;

    for (int i = 0; i < labels.size(); i++) {
        String label = labels.get(i);
        GlyphVector gv = font.createGlyphVector(frc, label);
        Rectangle2D labelBounds = gv.getVisualBounds();

        if (previousLabelBounds == null) {
            level++;
            previousLabelBounds = labelBounds;
            continue;
        }

        boolean overlap = horizontal ? labelBounds.intersects(previousLabelBounds) : previousLabelBounds.intersects(labelBounds);

        if (!overlap) {
            level++;
            previousLabelBounds = labelBounds;
        }
    }

    return level;
}
