public void putFieldInfo(ByteVector output, FieldWriter fieldWriter) {
    output.putShort(fieldWriter.access);
    output.putShort(fieldWriter.name);
    output.putShort(fieldWriter.desc);
    output.putShort(fieldWriter.signature);

    int attrsCount = fieldWriter.attrs != null ? fieldWriter.attrs.size() : 0;
    output.putShort(attrsCount);

    for (int i = 0; i < attrsCount; i++) {
        ByteVector attrBuf = new ByteVector();
        ((Attribute) fieldWriter.attrs.get(i)).put(this, null, 0, -1, -1, attrBuf);
        output.putShort(this.newUTF8(((Attribute) fieldWriter.attrs.get(i)).type)).putInt(attrBuf.length);
        output.putByteArray(attrBuf.data, 0, attrBuf.length);
    }
}
