public Map<String, byte[]> createVoldemortKeyValueFromAvroRecord(GenericRecord inputRecord) {

    // Extracting the key and value from the Avro record
    Object key = inputRecord.get("key");
    Object value = inputRecord.get("value");

    // Mapping out for each of the responsible voldemort nodes
    Map<String, byte[]> voldemortKeyValues = new HashMap<>();
    List<Integer> responsibleNodes = getResponsibleNodes(key);

    for (int nodeId : responsibleNodes) {
        byte[] serializedValue = serializeValue(value);
        byte[] voldemortKey = generateVoldemortKey(nodeId, key);

        // Combining node_id & partition_id of the responsible node followed by serialized value
        byte[] voldemortValue = combineNodeIdAndPartitionId(nodeId, serializedValue);

        // Adding to the map
        voldemortKeyValues.put(new String(voldemortKey), voldemortValue);
    }

    return voldemortKeyValues;
}

