import java.util.Calendar;
import java.util.Date;
import java.util.GregorianCalendar;

public class JulianDateCalculator {

    public static double calculateJulianDay(Date time) {
        Calendar calendar = new GregorianCalendar();
        if (time != null) {
            calendar.setTime(time);
        }
        int year = calendar.get(Calendar.YEAR);
        int month = calendar.get(Calendar.MONTH) + 1;
        int day = calendar.get(Calendar.DAY_OF_MONTH);
        int hour = calendar.get(Calendar.HOUR_OF_DAY);
        int min = calendar.get(Calendar.MINUTE);
        int sec = calendar.get(Calendar.SECOND);
        int millis = calendar.get(Calendar.MILLISECOND);

        double fractionOfDay = (hour + (min / 60.0) + (sec / 3600.0) + (millis / 3600000.0)) / 24.0;

        if (month <= 2) {
            year--;
            month += 12;
        }

        int A = year / 100;
        int B = 2 - A + (A / 4);
        int C = (int) (365.25 * year);
        int D = (int) (30.6001 * (month + 1));

        double JD = B + C + D + day + (fractionOfDay) + 1720994.5;
        return JD;
    }
}
