import java.util.HashSet;
import java.util.Random;
import java.util.Set;

public static Set<Integer> generateRandomDistinctIntegers(int N, int Max) {
    if (N > Max + 1) {
        throw new IllegalArgumentException("N is greater than Max+1");
    }

    Set<Integer> set = new HashSet<>();
    Random random = new Random();

    while (set.size() < N) {
        set.add(random.nextInt(Max + 1));
    }

    return set;
}
