public Collection<CmsSearchResourceBean> convertSearchResults(Collection<CmsSearchResource> searchResults) {
    // Create a new collection to store the transformed results
    Collection<CmsSearchResourceBean> transformedResults = new ArrayList<>();

    // Loop through each search result and transform it to a CmsSearchResourceBean
    for (CmsSearchResource searchResult : searchResults) {
        CmsSearchResourceBean transformedResult = new CmsSearchResourceBean();
        transformedResult.setId(searchResult.getId());
        transformedResult.setPath(searchResult.getPath());
        transformedResult.setTitle(searchResult.getTitle());
        transformedResult.setDescription(searchResult.getDescription());
        transformedResult.setLastModified(searchResult.getLastModified());
        transformedResults.add(transformedResult);
    }

    // Return the transformed results collection
    return transformedResults;
}
