import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.security.GeneralSecurityException;
import java.io.UnsupportedEncodingException;
import java.util.Base64;

public static String computeHmacSha1(String baseString, String keyString) throws GeneralSecurityException, UnsupportedEncodingException {
    String algorithm = "HmacSHA1";
    Mac mac = Mac.getInstance(algorithm);
    mac.init(new SecretKeySpec(keyString.getBytes("UTF-8"), algorithm));
    byte[] hash = mac.doFinal(baseString.getBytes("UTF-8"));
    String encodedHash = Base64.getEncoder().encodeToString(hash);
    return encodedHash;
}
