import java.util.regex.Pattern;

public class WildcardMatcher {

  public static boolean matches(String path, String pattern) {
    String[] pathTokens = tokenizePath(path);
    String[] patternTokens = tokenizePath(pattern);

    if (pathTokens.length < patternTokens.length - countWildcards(pattern, "**")) {
        return false;
    }

    for (int i = 0, j = 0; i < pathTokens.length && j < patternTokens.length; i++, j++) {
        if (patternTokens[j].equals("*")) {
            continue;
        } else if (patternTokens[j].equals("**")) {
            if (j == patternTokens.length - 1) {
                return true;
            }
            while (i < pathTokens.length) {
                if (matches(concatTokens(patternTokens, j + 1), concatTokens(pathTokens, i))) {
                    return true;
                }
                i++;
            }
            return false;
        } else if (!patternTokens[j].equals("?") && !patternTokens[j].equals(pathTokens[i])) {
            return false;
        }
    }

    return true;
  }

  private static String[] tokenizePath(String path) {
    path = path.replaceAll("\\\\", "/");
    return path.split("/");
  }

  private static int countWildcards(String pattern, String wildcard) {
    return pattern.split(Pattern.quote(wildcard), -1).length - 1;
  }

  private static String concatTokens(String[] tokens, int start) {
    if (start >= tokens.length) {
        return "";
    }
    String result = tokens[start];
    for (int i = start + 1; i < tokens.length; i++) {
        result += "/" + tokens[i];
    }
    return result;
  }

}
