import org.apache.kafka.clients.admin.AdminClient;
import org.apache.kafka.clients.admin.AdminClientConfig;
import org.apache.kafka.clients.admin.ListTopicsResult;
import org.apache.kafka.common.KafkaFuture;
import java.util.Properties;

public boolean checkIfTopicExists(String topicName) {
    Properties properties = new Properties();
    properties.put(AdminClientConfig.BOOTSTRAP_SERVERS_CONFIG, "localhost:9092");

    try (AdminClient adminClient = AdminClient.create(properties)) {
        ListTopicsResult topicsResult = adminClient.listTopics();
        KafkaFuture<java.util.Set<java.lang.String>> topicNamesFuture = topicsResult.names();
        java.util.Set<java.lang.String> topicNames = topicNamesFuture.get();

        return topicNames.contains(topicName);

    } catch (Exception e) {
        System.out.println("An exception occurred while checking if the topic exists: " + e.getMessage());
        return false;
    }
}
