public void writeFieldsTillChecksum(DataOutputStream out, Header header) throws IOException {
    // Loop through all the fields except the checksum field
    for (int i = 0; i < header.fieldCount - 1; i++) {
        Field field = header.fields.get(i);
        // Write the field id
        out.writeShort(field.id);
        // Write the field value length
        out.writeShort(field.value.length);
        // Write the field value
        out.write(field.value);
    }
}
