public static long parseLong(byte[] bytes, int idx) {
    long value = 0;
    for (int i = idx; i < idx + 8; i++) {
        int shift = (i - idx) * 8;
        value += ((long) bytes[i] & 0xffL) << shift;
    }
    return value;
}
