public List<Sentence> getPreviousSentencesOfSameType(JCas jCas, Annotation annotation) {
   List<Sentence> sentencesList = new ArrayList<>();
   Type sentenceType = jCas.getTypeSystem().getType("org.apache.uima.conll.dataset.type.Sentence");
   FSIterator<Annotation> iterator = jCas.getAnnotationIndex(sentenceType).iterator();
   while (iterator.isValid()) {
       Annotation currentAnnotation = iterator.get();
       if (currentAnnotation.equals(annotation)) {
           break;
       }
       if (currentAnnotation.getType().equals(sentenceType)) {
           sentencesList.add((Sentence) currentAnnotation);
       }
       iterator.moveToNext();
   }
   Collections.sort(sentencesList, Comparator.comparingInt(Sentence::getBegin));
   return sentencesList;
}
