public static boolean canGenerateEmptyMatch(String pattern) {
    if (pattern.isEmpty()) {
        return true;
    } 
    else if (pattern.length() == 1) {
        return pattern.charAt(0) == '*';
    }
    else if (pattern.charAt(1) == '*') {
        return canGenerateEmptyMatch(pattern.substring(2)) || canGenerateEmptyMatch(pattern.substring(1));
    }
    else if (pattern.charAt(1) == '?') {
        return canGenerateEmptyMatch(pattern.substring(2));
    }
    else {
        return false;
    }
}
