import java.io.IOException;
import java.net.HttpURLConnection;
import java.net.URL;

public void sendUIReport(String target, String entity) throws IOException {
    URL url = new URL(target);
    HttpURLConnection connection = (HttpURLConnection) url.openConnection();
    connection.setDoOutput(true);
    connection.setRequestMethod("POST");
    connection.setRequestProperty("Content-Type", "application/json");
    byte[] entityBytes = entity.getBytes();
    connection.setRequestProperty("Content-Length", Integer.toString(entityBytes.length));
    connection.getOutputStream().write(entityBytes);
    connection.getResponseCode();
    connection.disconnect();
}
