public boolean isValidQuery(String query) {
    if (query == null) {
        return true;
    }
    String[] queryParts = query.split("=");
    for (String part : queryParts) {
        if (part.isEmpty() || !part.contains("&") && part.indexOf('=') != part.lastIndexOf('=')) {
            return false;
        }
    }
    return true;
}
