public List<String> parseSuperTypes(List<Token> tokens) throws ParsingException {
    List<String> supertypes = new ArrayList<>();

    if (tokens.isEmpty()) {
        return supertypes;
    }

    int index = 0;
    Token currentToken = tokens.get(index);
    if (currentToken.getType() != TokenType.SUPER) {
        return supertypes;
    }

    index++;

    while (index < tokens.size()) {
        currentToken = tokens.get(index);

        if (currentToken.getType() == TokenType.COMMA) {
            index++;
            continue;
        }

        if (currentToken.getType() != TokenType.IDENTIFIER) {
            throw new ParsingException("Expected identifier for supertype, but got " + currentToken.getValue());
        }

        supertypes.add(currentToken.getValue());
        index++;
    }

    return supertypes;
}
