public boolean isSegwitCommitment(byte[] script) {
    if (script == null || script.length != 38) {
        return false;
    }

    // Check for the pattern OP_RETURN 0x24 0xaa21a9ed
    return script[0] == (byte) 0x6a &&
           script[1] == (byte) 0x24 &&
           script[2] == (byte) 0xaa &&
           script[3] == (byte) 0x21 &&
           script[4] == (byte) 0xa9 &&
