public class MongoFactory {
    private static final Logger LOGGER = LoggerFactory.getLogger(MongoFactory.class);

    public static MongoClient createMongoClient(MongoClientSettings settings) {
        if (System.getProperty("local.mongo.port") != null) {
            LOGGER.debug("Connecting to local embedded MongoDB instance at port {}", System.getProperty("local.mongo.port"));
            settings.getStreamFactoryFactory().setStreamFactory(new NettyStreamFactoryFactory());
