public double getWordSimilarity(String label1, String label2) {
    Map<String, Integer> vector1 = getWordVector(label1);
    Map<String, Integer> vector2 = getWordVector(label2);
    return getCosineSimilarity(vector1, vector2);
}

private Map<String, Integer> getWordVector(String word) {
    Map<String, Integer> vector = new HashMap<>();
    for (char c : word.toLowerCase().toCharArray()) {
        String letter = String.valueOf(c);
        vector.put(letter, vector.getOrDefault(letter, 0) + 1);
    }
    return vector;
}

private double getCosineSimilarity(Map<String, Integer> vector1, Map<String, Integer> vector2) {
    double dotProduct = 0;
    double magnitude1 = 0;
    double magnitude2 = 0;

    Set<String> uniqueKeys = new HashSet<>();
    uniqueKeys.addAll(vector1.keySet());
    uniqueKeys.addAll(vector2.keySet());

    for (String key : uniqueKeys) {
        int value1 = vector1.getOrDefault(key, 0);
        int value2 = vector2.getOrDefault(key, 0);
        dotProduct += value1 * value2;
        magnitude1 += value1 * value1;
        magnitude2 += value2 * value2;
    }

    if (magnitude1 == 0 || magnitude2 == 0) {
        return 0;
    } else {
        return dotProduct / (Math.sqrt(magnitude1) * Math.sqrt(magnitude2));
    }
}
