import java.io.FileWriter;
import java.io.IOException;
import java.time.LocalDateTime;
import java.util.List;

public void writeRecentSelectionsToFile(List<String> recentSelections, String filePath) {
  try {
    FileWriter writer = new FileWriter(filePath, true); // 'true' value to append new selections to the file
    String timeNow = LocalDateTime.now().toString();

    writer.write("Recent selections (written on " + timeNow + "):\n");
    for (String selection : recentSelections) {
      writer.write(selection + "\n");
    }
    writer.close();
    System.out.println("Recent selections written to file at: " + filePath);
  } catch (IOException e) {
    System.out.println("Error when writing to file at " + filePath + " : " + e.getMessage()); 
  }
}
