public String constructInsertQuery(String tableName, String[] propertyNames) {
    StringBuilder sb = new StringBuilder();
    sb.append("INSERT INTO ");
    sb.append(tableName);
    sb.append(" (");

    for(int i = 0; i < propertyNames.length; i++) {
        sb.append(propertyNames[i]);
        if (i != propertyNames.length - 1) {
            sb.append(", ");
        }
    }

    sb.append(") VALUES (");

    for(int i = 0; i < propertyNames.length; i++) {
        sb.append("?");
        if (i != propertyNames.length - 1) {
            sb.append(", ");
        }
    }

    sb.append(")");

    return sb.toString();
}
