public static <T extends Number> T findMaxValue(int start, int endExclusive, Class<T> type, Function<Integer, T> producer) {
    T max = producer.apply(start);
    for (int i = start + 1; i < endExclusive; i++) {
        T value = producer.apply(i);
        if (max.doubleValue() < value.doubleValue()) {
            max = value;
        }
    }
    return max;
}
