public static Class<?> getRawClass(Type type) {
    if (type instanceof Class<?>) {
        return (Class<?>) type;
    } else if (type instanceof ParameterizedType) {
        return getRawClass(((ParameterizedType) type).getRawType());
    } else if (type instanceof GenericArrayType) {
        Class<?> componentRawClass = getRawClass(((GenericArrayType) type).getGenericComponentType());
        return Array.newInstance(componentRawClass, 0).getClass();
    } else if (type instanceof TypeVariable<?>) {
        Type[] bounds = ((TypeVariable<?>) type).getBounds();
        if (bounds.length == 0) {
            return Object.class;
        } else {
            return getRawClass(bounds[0]);
        }
    } else {
        throw new IllegalArgumentException("Cannot handle type: " + type.getClass().getName());
    }
}
