public static String htmlFilter(String value, boolean markupHTMLSpaceReturn) {
    if (value == null) {
        return null;
    }
    StringBuilder result = new StringBuilder(value.length() + 50);
    for (int i = 0; i < value.length(); i++) {
        char chr = value.charAt(i);
        switch (chr) {
            case '<':
                result.append("&lt;");
                break;
            case '>':
                result.append("&gt;");
                break;
            case '\"':
                result.append("&quot;");
                break;
            case '\'':
                result.append("&#39;");
                break;
            case '&':
                result.append("&amp;");
                break;
            case '\n':
                if (markupHTMLSpaceReturn)
                    result.append("&lt;br /&gt;");
                else
                    result.append(chr);
                break;
            case ' ':
                if (markupHTMLSpaceReturn)
                    result.append("&amp;nbsp;");
                else
                    result.append(chr);
                break;
            default:
                result.append(chr);
        }
    }
    return result.toString();
}
