public static List<VariableTree> findYoungerSiblings(BlockTree tree, Tree start) {
    boolean startFound = false;
    List<VariableTree> result = new ArrayList<>();
    for (StatementTree statement : tree.getStatements()) {
        if (startFound && statement instanceof VariableTree) {
            result.add((VariableTree) statement);
        }
        if (statement.equals(start)) {
            startFound = true;
        }
    }
    return result;
}
