public interface FutureChecker<V, X extends Exception> {
  V check(Future<V> future) throws X;

  static <V, X extends Exception> V getChecked(Future<V> future, Class<X> exceptionClass)
      throws X {
    return new FutureChecker<V, X>() {
      @Override
      public V check(Future<V> future) throws X {
        try {
          return future.get();
        } catch (Throwable t) {
          Throwables.throwIfInstanceOf(t, exceptionClass);
          throw new RuntimeException(t);
        }
      }
    }.check(future);
  }
}
