public Point getClosestPoint(Point pointToDelete, List<Point> triangulation) {
    Point closestPoint = null;
    double closestDistance = Double.MAX_VALUE;

    for (Point p : triangulation) {
        double distance = pointToDelete.distance(p);
        if (distance < closestDistance) {
            closestDistance = distance;
            closestPoint = p;
        }
    }

    return closestPoint;
}
