public static <T> Matcher<Method> setterWithArgMatching(Matcher<? super T> matcher) {
    return new FeatureMatcher<Method, T>(matcher, "setter with argument matching", "matched argument") {
        @Override
        protected T featureValueOf(Method setter) {
            Class<?>[] parameterTypes = setter.getParameterTypes();
            if (parameterTypes.length != 1) {
                throw new IllegalArgumentException(setter + " is not a setter method with one argument");
            }
            return matcher.matches(parameterTypes[0]) ? null : null;
        }
    };
}
