public void calculateAverageWaitTime(int ttl_seconds) throws VoltAbortException {
    // Implementation using TreeMap to keep track of stations and their wait times
    TreeMap<String, Double> stationWaitTimes = new TreeMap<>();
    // Iterate through all wait time calculations
    Iterator<Map.Entry<String, Double>> iter = stationWaitTimes.entrySet().iterator();
    while (iter.hasNext()) {
        Map.Entry<String, Double> entry = iter.next();
        // Check if wait time calculation is older than ttl_seconds
        if (entry.getValue() < (System.currentTimeMillis() - ttl_seconds * 1000)) {
            // Remove stale wait time calculation from the Map
            iter.remove();
        }
    }
    // Implement logic to calculate current average wait time for each station
    // ...
}
