public int calculateFrameLength(int layer, int bitRate, int sampleRate, boolean padding) {
    int bitrateIndex = (layer == 1) ? 0 : (layer == 2) ? 1 : 2;
    int samplesInFrame = (layer == 1) ? 384 : 1152;
    int paddingSize = (padding) ? 1 : 0;
    int byteRate = (bitRate * 1000 / 8 * samplesInFrame / sampleRate) + paddingSize;

    return byteRate;
}
