public void verifyElementDisplayed(PageElement pageElement, boolean displayed) throws FailureException {
  try {
    // Wait for the element to be visible
    WebDriverWait wait = new WebDriverWait(driver, TIMEOUT);
    if (displayed) {
        wait.until(ExpectedConditions.visibilityOfElementLocated(pageElement.getElementLocator()));
    } else {
        wait.until(ExpectedConditions.invisibilityOfElementLocated(pageElement.getElementLocator()));
    }
  } catch (TimeoutException e) {
    throw new FailureException(Messages.FAIL_MESSAGE_UNABLE_TO_FIND_ELEMENT, e);
  }
}
