public NavigationAnimation createNewPanningNavigationAnimation(MapPresenter mapPresenter, Coordinate target) {
    return new NavigationAnimation(mapPresenter) {
        @Override
        protected void animate(double progress) {
            Point currentPoint = mapPresenter.getMap().getMapPosition().getCenter();
            Point targetPoint = mapPresenter.getMap().getViewArea().getPosition(target, mapPresenter.getMap());
            Point newPoint = new Point(
                    currentPoint.getX() + (targetPoint.getX() - currentPoint.getX()) * progress,
                    currentPoint.getY() + (targetPoint.getY() - currentPoint.getY()) * progress);
            mapPresenter.getMap().setPosition(new MapPosition(target, mapPresenter.getMap().getMapPosition().getZoom(), mapPresenter.getMap().getMapPosition().getTilt(), newPoint));
        }
    };
}
