public static boolean hasValueInPublicanCfg(String contentSpec, String value) {
    // declare the file paths of the default and additional publican cfg files
    String defaultPublicanCfgFilePath = "/etc/publican/publican.cfg";
    String additionalPublicanCfgFilePath = "/etc/publican.cfg";

    // create an array of the file paths
    String[] publicanCfgFilePaths = {defaultPublicanCfgFilePath, additionalPublicanCfgFilePath};

    // loop through each file path to check for the specified value
    for (String filePath : publicanCfgFilePaths) {
        // read each line in the file
        try (Scanner scanner = new Scanner(new File(filePath))) {
            while (scanner.hasNextLine()) {
                String line = scanner.nextLine();
                // check if the line contains the specified value
                if (line.contains(value)) {
                    return true;
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
    return false;
}
