import java.io.FileInputStream;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.Reader;
import java.util.zip.GZIPInputStream;
import javax.xml.stream.XMLInputFactory;
import javax.xml.stream.XMLStreamException;
import javax.xml.stream.XMLStreamReader;

public String parseGZIPXMLFile(File file) throws XMLStreamException, IOException {
    XMLInputFactory factory = XMLInputFactory.newInstance();
    Reader reader = new InputStreamReader(new GZIPInputStream(new FileInputStream(file)));

    XMLStreamReader xmlReader = factory.createXMLStreamReader(reader);
    StringBuilder sb = new StringBuilder();

    while (xmlReader.hasNext()) {
        int event = xmlReader.next();
        switch (event) {
            case XMLStreamReader.START_ELEMENT:
                sb.append("<");
                sb.append(xmlReader.getLocalName());
                for (int i = 0; i < xmlReader.getAttributeCount(); i++) {
                    sb.append(" ");
                    sb.append(xmlReader.getAttributeLocalName(i));
                    sb.append("=\"");
                    sb.append(xmlReader.getAttributeValue(i));
                    sb.append("\"");
                }
                sb.append(">");
                break;
            case XMLStreamReader.END_ELEMENT:
                sb.append("</");
                sb.append(xmlReader.getLocalName());
                sb.append(">");
                break;
            case XMLStreamReader.CHARACTERS:
                sb.append(xmlReader.getText());
                break;
            default:
                break;
        }
    }

    xmlReader.close();
    reader.close();

    return sb.toString();
}
