public byte[] getPayload(ByteBuffer buffer) {
    int contentLength = -1;
    int position = buffer.position();
    ByteBuffer duplicateBuffer = buffer.duplicate();

    // Look for content length header
    while (duplicateBuffer.hasRemaining()) {
        if ((char) duplicateBuffer.get() == '\r' && duplicateBuffer.hasRemaining()
                && (char) duplicateBuffer.get() == '\n' && duplicateBuffer.hasRemaining()
                && (char) duplicateBuffer.get() == 'C' && duplicateBuffer.hasRemaining()
                && (char) duplicateBuffer.get() == 'o' && duplicateBuffer.hasRemaining()
                && (char) duplicateBuffer.get() == 'n' && duplicateBuffer.hasRemaining()
                && (char) duplicateBuffer.get() == 't' && duplicateBuffer.hasRemaining()
                && (char) duplicateBuffer.get() == 'e' && duplicateBuffer.hasRemaining()
                && (char) duplicateBuffer.get() == 'n' && duplicateBuffer.hasRemaining()
                && (char) duplicateBuffer.get() == 't' && duplicateBuffer.hasRemaining()
                && (char) duplicateBuffer.get() == '-' && duplicateBuffer.hasRemaining()
                && (char) duplicateBuffer.get() == 'L' && duplicateBuffer.hasRemaining()
                && (char) duplicateBuffer.get() == 'e' && duplicateBuffer.hasRemaining()
                && (char) duplicateBuffer.get() == 'n' && duplicateBuffer.hasRemaining()
                && (char) duplicateBuffer.get() == 'g' && duplicateBuffer.hasRemaining()
                && (char) duplicateBuffer.get() == 't' && duplicateBuffer.hasRemaining()
                && (char) duplicateBuffer.get() == 'h' && duplicateBuffer.hasRemaining()
                && (char) duplicateBuffer.get() == ':' && duplicateBuffer.hasRemaining()) {
            StringBuilder lengthBuilder = new StringBuilder();
            while (duplicateBuffer.hasRemaining()) {
                char c = (char) duplicateBuffer.get();
                if (c == '\r') {
                    duplicateBuffer.get(); // consume '\n'
                    break;
                }
                lengthBuilder.append(c);
            }

            contentLength = Integer.parseInt(lengthBuilder.toString());
            break;
        }
    }

    if (contentLength >= 0 && buffer.remaining() >= contentLength) {
        byte[] payload = new byte[contentLength];
        buffer.get(payload);
        return payload;
    } else {
        buffer.position(position);
        return null;
    }
}
