public class XmlUtils {

    public static Document readXmlFromResource(String resourceName) throws Exception {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        DocumentBuilder builder = factory.newDocumentBuilder();
        try (InputStream resourceStream = XmlUtils.class.getClassLoader().getResourceAsStream(resourceName)) {
            if (resourceStream == null) {
                throw new IllegalStateException("Resource not found: " + resourceName);
            }
            InputSource inputSource = new InputSource(resourceStream);
            return builder.parse(inputSource);
        }
    }

}
