public List<InventoryStatus> fetchInventoryStatus(String filter) {
    // Convert the filter string from JSON format to a Map
    Map<String, String> filterMap = new Gson().fromJson(filter, new TypeToken<Map<String, String>>(){}.getType());

    // Use the filter map to fetch the filtered set of InventoryStatus resources
    List<InventoryStatus> filteredInventoryStatus = new ArrayList<>();
    for (InventoryStatus status : inventoryStatusList) {
        boolean isMatched = true;

        for (Map.Entry<String, String> filterEntry : filterMap.entrySet()) {
            String fieldName = filterEntry.getKey();
            String fieldValue = filterEntry.getValue();

            // Check if the status object matches the filter
            if (fieldName.equals("vm_state") && !status.getVmState().equals(fieldValue)) {
                isMatched = false;
                break;
            } else if (fieldName.equals("name") && !status.getName().matches(fieldValue)) {
                isMatched = false;
                break;
            }
        }

        // Add the status object to the filtered list if it matches the filter
        if (isMatched) {
            filteredInventoryStatus.add(status);
        }
    }

    return filteredInventoryStatus;
}
