public static Color interpolate(Color a, Color b, float mixing) throws IllegalArgumentException {
    if(mixing < 0 || mixing > 1) {
        throw new IllegalArgumentException("Mixing coefficient must be between 0 and 1");
    }
    int red = (int) (mixing * a.getRed() + (1 - mixing) * b.getRed());
    int green = (int) (mixing * a.getGreen() + (1 - mixing) * b.getGreen());
    int blue = (int) (mixing * a.getBlue() + (1 - mixing) * b.getBlue());
    return new Color(red, green, blue);
}
