public void convertDoubleQuotedString(StringBuilder sb, SourceRange sourceRange) {
    int start = sourceRange.getStart();
    int end = sourceRange.getEnd();
    sb.deleteCharAt(end - 1);
    sb.deleteCharAt(start);
    int i = start;
    while (i < end - 2) {
        char ch = sb.charAt(i);
        if (ch == '\\') {
            ch = sb.charAt(i + 1);
            sb.setCharAt(i, getEscapeChar(ch));
            sb.deleteCharAt(i + 1);
            end--;
        }
        i++;
    }
}
