import java.util.stream.Stream;

public Stream<String> encodeToRDF(Stream<String> stream) {
    return stream.flatMap(outcome -> {
        String[] parts = outcome.split(",");
        String subject = parts[0];
        String predicate = parts[1];
        String object = parts[2];
        return Stream.of(String.format("<%s> <%s> <%s> .", subject, predicate, object));
    });
}
