public class IndexFragment extends Fragment {

  private Map<Class<?>, Map<Object, Set<Attribute>>> typeIndex;

  public IndexFragment() {
    this.typeIndex = new HashMap<>();
  }

  public void index(Attribute attribute) {
    Class<?> type = attribute.getType();
    Object value = attribute.getValue();
    if (!typeIndex.containsKey(type)) {
      typeIndex.put(type, new HashMap<>());
    }
    if (!typeIndex.get(type).containsKey(value)) {
      typeIndex.get(type).put(value, new HashSet<>());
    }
    typeIndex.get(type).get(value).add(attribute);
  }

  public Set<Attribute> find(Class<?> type, Object value) {
    if (!typeIndex.containsKey(type) || !typeIndex.get(type).containsKey(value)) {
      return Collections.emptySet();
    }
    return Collections.unmodifiableSet(typeIndex.get(type).get(value));
  }
}
