public static byte[] encodeRun(int length) {
    if (length <= 0 || length > 0xFFFF) {
        throw new IllegalArgumentException("Invalid length: " + length);
    }

    byte[] encoded = new byte[2];

    if (length < 4) {
        encoded[0] = (byte) ((length - 1) & 0xFF);
    } else {
        encoded[0] = (byte) 0xFF;
        encoded[1] = (byte) ((length - 1) & 0xFFFF);
    }

    return encoded;
}
