public void updateColumnInfo(int c, TableColumn col) {
    int width = col.getWidth();
    boolean resizable = col.isResizable();
    String widthUnit = col.getWidthUnit();

    if (widthUnit == TableColumn.PIXELS) {
        col.setMinWidth(width);
        col.setMaxWidth(width);
    } else if (widthUnit == TableColumn.PERCENTAGE) {
        col.setMinWidth(0);
        col.setMaxWidth(Integer.MAX_VALUE);
    }

    if (!resizable) {
        col.setMinWidth(width);
        col.setMaxWidth(width);
    }
}
