import org.springframework.beans.factory.config.AutowireCapableBeanFactory;

public static PropertyMapper createPropertyMapper(String property) {
    return new PropertyMapper() {
        @Override
        public void map(Object source, Object target, AutowireCapableBeanFactory beanFactory) {
            PropertyDescriptor sourceDescriptor = BeanUtils.getPropertyDescriptor(source.getClass(), property);
            PropertyDescriptor targetDescriptor = BeanUtils.getPropertyDescriptor(target.getClass(), property);

            if (sourceDescriptor != null && targetDescriptor != null) {
                BeanWrapper sourceWrapper = new BeanWrapperImpl(source);
                BeanWrapper targetWrapper = new BeanWrapperImpl(target);
                targetWrapper.setPropertyValue(property, sourceWrapper.getPropertyValue(property));

                if (beanFactory != null) {
                    beanFactory.autowireBean(target);
                }
            }
        }
    };
}

public interface PropertyMapper {
    void map(Object source, Object target, AutowireCapableBeanFactory beanFactory);
}
