public static String createNewSessionId(String sessionId, List<String> memcachedNodes) {
    // Check if memcachedNodes list contains a single node without nodeId
    if(memcachedNodes.size() == 1 && memcachedNodes.get(0).indexOf(":") == -1) {
        return sessionId;
    }

    // Select a random node from the memcachedNodes list
    Random rand = new Random();
    String selectedNode = memcachedNodes.get(rand.nextInt(memcachedNodes.size()));

    // Append the selected node id to the sessionId
    String newSessionId = sessionId + ":" + selectedNode.substring(selectedNode.indexOf(":")+1);

    return newSessionId;
}
