public boolean isPerfectInterval(String interval) {
    String[] intervals = {"unison", "fourth", "fifth"};
    int numOctaves = interval.replaceAll("[^\\d]", ""); //get number of octaves from interval string
    interval = interval.replaceAll("[0-9]", ""); //remove digits from interval string
    return (Arrays.asList(intervals).contains(interval) && numOctaves <= 1);
}
