public Cookie getCookieByName(HttpResponse response, String name) {
    Header[] headers = response.getHeaders("Set-Cookie");
    for (Header header : headers) {
        String cookieStr = header.toString();
        if (cookieStr.contains(name)) {
            return Cookie.parse(header, false);
        }
    }
    return null;
}
