import java.util.Scanner;

public class PersonMessage {

    public static void main(String[] args) {
        Person.Builder personBuilder = Person.newBuilder();
        Scanner scanner = new Scanner(System.in);

        System.out.println("Enter the person's name:");
        String name = scanner.nextLine();
        personBuilder.setName(name);

        System.out.println("Enter the person's age:");
        int age = scanner.nextInt();
        personBuilder.setAge(age);

        System.out.println("Enter the person's address:");
        String address = scanner.nextLine(); // clear the buffer
        address = scanner.nextLine(); // read the address from input
        personBuilder.setAddress(address);

        System.out.println("Enter the person's phone number:");
        String phone = scanner.nextLine();
        personBuilder.setPhone(phone);

        Person person = personBuilder.build();
        System.out.println("Message:\n" + person.toString());
    }
}
