public HashMap<Integer, PreKey> getPreKeysMap(Bundle bundle) {
    HashMap<Integer, PreKey> preKeys = new HashMap<>();
    int preKeyCount = bundle.getInt("preKeyCount");
    for (int i = 0; i < preKeyCount; i++) {
        int preKeyId = bundle.getInt("preKey" + i + "_id");
        byte[] preKeyBytes = bundle.getBytes("preKey" + i + "_data");
        PreKey preKey = new PreKey(preKeyId, preKeyBytes);
        preKeys.put(preKeyId, preKey);
    }
    return preKeys;
}
