public BluetoothGatt connectToDevice(BluetoothDevice device) throws BleDisconnectedException {
    final RxBleClient rxBleClient = RxBleClient.create(context);
    final BluetoothGatt bluetoothGatt = device.connectGatt(context, false, new BluetoothGattCallback() {

        @Override
        public void onConnectionStateChange(BluetoothGatt gatt, int status, int newState) {
            super.onConnectionStateChange(gatt, status, newState);

            if(newState == BluetoothProfile.STATE_CONNECTED){
                // Connection established, we can proceed
                RxBleConnection rxBleConnection = rxBleClient.getBleDevice(gatt.getDevice().getAddress())
                        .establishConnection(false)
                        .blockingGet(); // Wait until connection is established

                if(rxBleConnection.getState() == RxBleConnection.RxBleConnectionState.CONNECTED){
                    // Connection reached CONNECTED state
                    return gatt;
                } else {
                    // Connection failed for some reason
                    throw new BleDisconnectedException();
                }
            }
        }

        @Override
        public void onDisconnected(BluetoothGatt gatt, int status) {
            // Device disconnected before connection could be established
            throw new BleDisconnectedException();
        }
    });

    return bluetoothGatt;
}
