public Set<Class<? extends Component>> getClassesWithoutScribes(ICalendar ical) {
    Set<Class<? extends Component>> classesWithoutScribes = new HashSet<>();

    for (Component component : ical.getComponents()) {
        Class<? extends Component> componentClass = component.getClass();
        if (!hasScribe(componentClass)) {
            classesWithoutScribes.add(componentClass);
        }
        for (Property property : component.getProperties()) {
            Class<? extends Property> propertyClass = property.getClass();
            if (!hasScribe(propertyClass)) {
                classesWithoutScribes.add(propertyClass);
            }
        }
    }

    return classesWithoutScribes;
}

private boolean hasScribe(Class<?> clazz) {
    try {
        Class.forName(clazz.getName() + "Scribe");
        return true;
    } catch (ClassNotFoundException e) {
        return false;
    }
}
