public static <E extends Throwable> E wrapException(final E exp) {
    if (exp == null) {
        throw new IllegalArgumentException("Exception to be wrapped cannot be null");
    }

    // Typecast to Throwable to avoid NullPointerException on getMessage() method
    final Throwable cause = ((Throwable) exp).getCause();
    if (cause != null && exp.getClass().equals(cause.getClass())) {
        return exp;
    }

    // Create a new instance of E if the error message has changed after wrapping
    final String message = exp.getMessage() != null ? exp.getMessage() : "";
    final E wrappedExp;
    try {
        wrappedExp = (E) exp.getClass().getConstructor(String.class).newInstance(message);
    } catch (final NoSuchMethodException | IllegalAccessException | InstantiationException
            | InvocationTargetException ex) {
        return exp;
    }

    wrappedExp.initCause(exp);
    return wrappedExp;
}
