public List<AceAssertion> findSatisfiedAceAssertions(List<ACE> aces, List<AceAssertion> unsatisfiedAssertions) {
    List<AceAssertion> satisfiedAssertions = new ArrayList<>();
    Iterator<AceAssertion> it = unsatisfiedAssertions.iterator();

    while (it.hasNext()) {
        AceAssertion assertion = it.next();
        for (ACE ace : aces) {
            if (ace.matches(assertion)) {
                satisfiedAssertions.add(assertion);
                it.remove();
                break;
            }
        }
    }

    return satisfiedAssertions;
}
