public static Vector parseVectorFromMatrixMarket(InputStream is) throws IOException {
    BufferedReader reader = new BufferedReader(new InputStreamReader(is));
    String line = reader.readLine();
    while (line.startsWith("%")) {
        line = reader.readLine();
    }
    String[] tokens = line.split("\\s+");
    int rows = Integer.parseInt(tokens[0]);
    int nnz = Integer.parseInt(tokens[1]);
    double[] values = new double[nnz];
    int[] indices = new int[nnz];
    int position = 0;
    while ((line = reader.readLine()) != null) {
        tokens = line.split("\\s+");
        for (int i = 1; i < tokens.length; i++) {
            values[position] = Double.parseDouble(tokens[i]);
            indices[position] = Integer.parseInt(tokens[0]);
            position++;
        }
    }
    reader.close();
    return new Vector(rows, nnz, values, indices);
}
