public void waitForTimeout(WidgetCallback callback, int timeout) throws WidgetTimeoutException {
    long startTime = System.currentTimeMillis();
    while (true) {
        if (callback.isReady()) {
            break;
        }
        long currentTime = System.currentTimeMillis();
        if (currentTime - startTime >= timeout) {
            throw new WidgetTimeoutException("Timeout: " + timeout + " ms exceeded.");
        }
        try {
            Thread.sleep(100);
        } catch (InterruptedException e) {
            // Do nothing
        }
    }
}
