public void deployAssignedVertices(Collection<ExecutionVertex> startVertices) {
   List<ExecutionVertex> assignedVertices = new ArrayList<>();

   // Filter execution vertices with state ASSIGNED
   for (ExecutionVertex vertex : startVertices) {
      if (vertex.getState() == ExecutionState.ASSIGNED) {
         assignedVertices.add(vertex);
      }
   }

   // Deploy assigned vertices on the allocated resource objects
   for (ExecutionVertex vertex : assignedVertices) {
      AllocatedResource resource = vertex.getAllocatedResource();
      if (resource != null) {
         resource.deployVertex(vertex);
      }
   }
}
