import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.FileReader;
import java.io.FileWriter;
import java.io.IOException;

public class FileFragmentationFixer {

  public static void writeOutNonFragmentedRows(String inputFilePath, String outputFilePath) throws IOException {
    try (BufferedReader reader = new BufferedReader(new FileReader(inputFilePath));
         BufferedWriter writer = new BufferedWriter(new FileWriter(outputFilePath))) {

      String line;
      String previousLine = null;
      while ((line = reader.readLine()) != null) {
        if (previousLine != null && !previousLine.endsWith("\n")) {
          writer.newLine(); // add newline if previous line wasn't properly terminated
        }
        writer.write(line);
        previousLine = line;
      }
    }
  }
}
