public char readCharacter(Reader reader, boolean allowEOF) throws IOException {
    int nextChar = reader.read();
    if (nextChar == -1) {
        if (allowEOF) {
            return (char) nextChar;
        } else {
            throw new IOException("Unexpected End of Stream");
        }
    }
    return (char) nextChar;
}
