public String renderTemplate(String template, Map<String, Object> parameters, Map<String, Object> extraGlobalScopes) throws IOException {
    StringWriter writer = new StringWriter();
    MustacheFactory mf = new DefaultMustacheFactory();
    Mustache mustache = mf.compile(new StringReader(template), "example");
    Map<String, Object> scopes = new HashMap<>();
    scopes.putAll(parameters);
    scopes.putAll(extraGlobalScopes);
    mustache.execute(writer, scopes).flush();
    return writer.toString();
}
