public void openAndCloseJsonArray(JsonParser jp, List<String> results) throws JsonParseException, IOException {
   if (jp.getCurrentToken() != JsonToken.START_ARRAY) {
      throw new JsonParseException("Expecting start of array", jp.getCurrentLocation());
   }

   results.add("[");
   while (jp.nextToken() != JsonToken.END_ARRAY) {
      results.add(jp.getText());
   }
   results.add("]");
}
