public List<Label> getProjectLabels(Object projectIdOrPath, int itemsPerPage) throws GitLabApiException {
        GitLabApi gitLabApi = getGitLabApi();
        ProjectApi projectApi = gitLabApi.getProjectApi();
        PaginationFilter filter = new PaginationFilter(itemsPerPage);

        List<Label> results = new ArrayList<>();
        try {
            Pager<Label> labelsPager = projectApi.getLabels(projectIdOrPath, filter);
