public boolean matchQName(String regQName, String targetQName, boolean ignorePrefix) {
  String[] regSplit = regQName.split(":");
  String[] targetSplit = targetQName.split(":");

  if(regSplit.length != targetSplit.length) {
      return false;
  }

  if(regSplit.length == 2 && !regSplit[0].equals(targetSplit[0]) && !ignorePrefix) {
      return false;
  }

  String regLocalPart = regSplit[regSplit.length - 1];
  String targetLocalPart = targetSplit[targetSplit.length - 1];

  if(regLocalPart.contains("*")) {
      String regMatch = regLocalPart.replace("*", "");
      return targetLocalPart.startsWith(regMatch);
  }

  return regLocalPart.equals(targetLocalPart);
}
