public double getGroundResolution(double latitude, int mapSize) {
    final double earthRadius = 6378137; // in meters
    final double degToRad = Math.PI / 180;
    final double radToDeg = 180 / Math.PI;

    double groundResolution = Math.cos(latitude * degToRad) * 2 * Math.PI * earthRadius / mapSize;
    return groundResolution;
}
