import java.util.ArrayList;
import java.util.List;

public class HandlerScanner {

    public List<Object> scanHandlers() throws Exception {
        List<Object> handlers = new ArrayList<>();
        ClassPathScanningCandidateComponentProvider provider = new ClassPathScanningCandidateComponentProvider(false);
        provider.addIncludeFilter(new AnnotationTypeFilter(Handler.class));
        for (BeanDefinition beanDef : provider.findCandidateComponents("module.application.service.handler")) {
            Class<?> clazz = Class.forName(beanDef.getBeanClassName());
            if (clazz.isAnnotationPresent(Handler.class)) {
                Handler handlerAnnotation = clazz.getAnnotation(Handler.class);
                Object handlerInstance = clazz.newInstance();
                handlers.add(handlerInstance);
            }
        }
        return handlers;
    }
}
