public static File findTemplate(String filename) throws IOException {
    File file = null;
    InputStream inputStream = Thread.currentThread().getContextClassLoader().getResourceAsStream(filename);

    try {
        file = File.createTempFile(filename, ".temp");
        Files.copy(inputStream, file.toPath(), StandardCopyOption.REPLACE_EXISTING);
    } catch (IOException e) {
        String error = "Error occurred while copying template " + filename + " to the temporary file system";
        logger.error(error);
        throw e;
    }

    if (!file.exists()) {
        file = new File(filename);
    }

    return file;
}
