public UnionPattern compileMatchPattern(int opPos) throws TransformerException {
    final int endPat = getStepCount(opPos);
    final boolean useUnion = true;
    UnionPattern up = null;

    for (int i = 0; i < endPat; i++) {
        final int stePos = getStepOp(opPos, i);
        final int type = getOp(stepOp, stePos);

        if (Constants.ELEM_WILDCARD == type) {
            if (null == up) {
                up = new UnionPattern();
            }

            final StepPattern any2 = new ContextMatchStepPattern(StepPattern.ANODE, Axis.ALL);

            up.addPattern(any2);
        } else {
            final StepPattern pat = this.loadStep(opPos, stePos, null, 0);

            if (null == up && Constants.ELEM_NAME == pat.getNodeType()) {
                final ContextMatchStepPattern cp = new ContextMatchStepPattern(StepPattern.QNAME, Axis.ALL, pat.getNodeName(), pat.getNamespace(), true);

                up = new UnionPattern(cp);

                cp.setPredicates(pat.getPredicates());
            } else {
                if (null == up) {
                    up = new UnionPattern();
                }

                up.addPattern(pat);
            }
        }
    }

    return up;
}
