public static double[] normalToGeneral(double[] input, double[] output) {
    if (output == null) {
        output = new double[4];
    }
    output[0] = input[0];
    output[1] = input[1];
    output[2] = input[2];
    output[3] = -1 * (input[0] * input[3] + input[1] * input[4] + input[2] * input[5]);
    return output;
}
