public ArrayList<String> provideResponseMessages(OperationContext context) {
    ArrayList<String> responseMessages = new ArrayList<String>();
    // check the context operation and generate response messages accordingly
    switch (context.getOperation()) {
        case "addition":
            responseMessages.add("Example: 5 + 3 = 8");
            responseMessages.add("Example: 10 + (-2) = 8");
            break;
        case "subtraction":
            responseMessages.add("Example: 8 - 3 = 5");
            responseMessages.add("Example: 10 - (-2) = 12");
            break;
        case "multiplication":
            responseMessages.add("Example: 2 * 3 = 6");
            responseMessages.add("Example: (-3) * (-4) = 12");
            break;
        case "division":
            responseMessages.add("Example: 10 / 2 = 5");
            responseMessages.add("Example: (-12) / 4 = -3");
            break;
        default:
            responseMessages.add("No response message available for this operation.");
    }
    return responseMessages;
}
