public void readBootstrapMethods(ClassReader classReader, CharBuffer charBuffer) {
    int[] bootstrapMethods = classReader.getBootstrapMethods();
    for (int bootstrapMethodIndex : bootstrapMethods) {
        int[] bootstrapMethodArguments = classReader.readBootstrapMethodArguments(bootstrapMethodIndex);
        String bootstrapMethodDescriptor = classReader.readUTF8(classReader.readUnsignedShort());
        List<String> bootstrapMethodArgumentsNames = new ArrayList<>();
        for (int bootstrapMethodArgumentIndex : bootstrapMethodArguments) {
            bootstrapMethodArgumentsNames.add(classReader.readConstantToString(bootstrapMethodArgumentIndex, charBuffer));
        }
        symbolTable.addBootstrapMethodEntry(bootstrapMethodDescriptor, bootstrapMethodArgumentsNames);
    }
}
