public static void generateBeanInfoFiles(RootDoc rootDoc) {
    ClassDoc[] classDocs = rootDoc.classes();
    for (ClassDoc classDoc : classDocs) {
        BeanInfo beanInfo = null;
        try {
            beanInfo = Introspector.getBeanInfo(classDoc.asClass());
        } catch (IntrospectionException ex) {
            System.err.println("Failed to generate BeanInfo for class: " + classDoc.qualifiedName());
            ex.printStackTrace();
        }
        if (beanInfo != null) {
            String outputFilename = classDoc.qualifiedName() + "BeanInfo.java";
            try (PrintWriter writer = new PrintWriter(outputFilename, "UTF-8")) {
                writer.println("public class " + classDoc.simpleTypeName() + "BeanInfo extends java.beans.SimpleBeanInfo {");
                // Write the bean info content
                writer.println("}");
                System.out.println("Generated BeanInfo for: " + classDoc.qualifiedName());
            } catch (IOException ex) {
                System.err.println("Failed to write BeanInfo file for class: " + classDoc.qualifiedName());
                ex.printStackTrace();
            }
        }
    }
}
