import java.lang.reflect.Method;
import java.util.HashMap;
import java.util.Map;

public class ReflectionMethodInvoker {

    private static final Map<String, Method> METHOD_CACHE = new HashMap<>();

    public static Object invokeMethod(String methodName, Class<?> clazz, Object... params) throws Exception {
        String cacheKey = clazz.getCanonicalName() + "." + methodName;
        Method method = METHOD_CACHE.get(cacheKey);
        if (method == null) {
            method = clazz.getMethod(methodName);
            METHOD_CACHE.put(cacheKey, method);
        }
        return method.invoke(null, params);
    }
}
