import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.util.zip.GZIPInputStream;

public class Serializables {
    public static Serializable deserialize(byte[] data, boolean compressed) throws IOException, ClassNotFoundException {
        ByteArrayInputStream bais = new ByteArrayInputStream(data);
        ObjectInputStream ois = compressed ? new ObjectInputStream(new GZIPInputStream(bais)) : new ObjectInputStream(bais);
        Object obj = ois.readObject();
        return (Serializable) obj;
    }
}
