public String convertToXWikiParameters(String params) {
   // Split the wikimodel parameters on "|"
   String[] paramList = params.split("\\|");

   // Convert the parameters to XWiki format by replacing "=" with "&"
   StringBuilder sb = new StringBuilder();
   for (String param : paramList) {
      if (param.contains("=")) {
         String xwikiParam = param.replace("=", "&");
         sb.append(xwikiParam).append("&");
      }
   }

   // Remove the last "&" character and return the final XWiki parameter string
   return sb.toString().substring(0, sb.length() - 1);
}
