public SelectResults formatQueryResults(List<QueryResult> queryResults, int limit) {
    SelectResults selectResults = new SelectResults();
    int resultCount = 0;
    for (QueryResult queryResult : queryResults) {
        for (Object result : queryResult.getResults()) {
            if (resultCount < limit) {
                selectResults.addResult(formatResult(result));
                resultCount++;
            } else {
                break;
            }
        }
        if (resultCount >= limit) {
            break;
        }
    }
    return selectResults;
}

