public class ArtifactFinder {
    public static ArrayList<File> findAllArtifacts(File dir) {
        ArrayList<File> artifactList = new ArrayList<>();
        File[] files = dir.listFiles();
        if (files != null) {
            for (File file : files) {
                if (file.isDirectory()) {
                    artifactList.addAll(findAllArtifacts(file));
                } else {
                    artifactList.add(file);
                }
            }
        }
        return artifactList;
    }
}
