public static InetSocketAddress readSocketAddressFromBuffer(String buffer) {
    String[] parts = buffer.split(":");
    if (parts.length != 2) {
        return null;
    }
    String host = parts[0];
    int port;
    try {
        port = Integer.parseInt(parts[1]);
    } catch (NumberFormatException e) {
        return null;
    }
    return new InetSocketAddress(host, port);
}
