public void updateSketch(byte[] key, long value) {
    // Retrieve the Summary object associated with the key
    Summary summary = SummaryManager.getSummary(key);

    // If the Summary object does not exist, create a new one
    if (summary == null) {
        summary = new Summary();
        SummaryManager.putSummary(key, summary);
    }

    // Update the Summary object with the given value
    summary.update(value);
}
