public static Set<String> checkApplicationNames(List<String> document, List<String> applicationNames) {
    Set<String> locationsWithoutNames = new HashSet<>();

    for (int i = 0; i < document.size(); i++) {
        String currentLine = document.get(i);
        boolean foundApplicationName = false;
        for (int j = 0; j < applicationNames.size(); j++) {
            String currentAppName = applicationNames.get(j);
            if (currentLine.contains(currentAppName)) {
                foundApplicationName = true;
                break;
            }
        }
        if (!foundApplicationName) {
            locationsWithoutNames.add("line " + i);
        }
    }

    return locationsWithoutNames;
}
