public void move(PoolChunk chunk) {
    final int usage = chunk.usage();
    if (usage < maxUsage) {
        synchronized (next) {
            if (next.head == null || usage < next.head.minUsage) {
                removeFromList(chunk);
                next.insertHead(chunk);
                chunk.parent = next;
            } else {
                move0(chunk);
            }
        }
    }
}

private void move0(PoolChunk chunk) {
    for (PoolChunkList cur = next; cur.next != null; cur = cur.next) {
        if (cur.next.head == null || chunk.usage() < cur.next.head.minUsage) {
            removeFromList(chunk);
            cur.next.insertHead(chunk);
            chunk.parent = cur.next;
            break;
        }
    }
}
