public int computeFreeParameters(DataRelation relation, Set<Cluster> clustering){
     int numParameters = 0;
     int numDimensions = relation.getDimensions();
     for(Cluster cluster: clustering){
          int numPoints = cluster.getNumPoints();
          numParameters += numPoints * numDimensions;
          numParameters += numDimensions * (numDimensions + 1) / 2; // upper triangle of the covariance matrix
     }
     return numParameters;
}
