public Point calculateClosestPointOnEdge(Point queryPoint, Line edge) {
   double edgeLength = edge.getEnd().distance(edge.getStart());
   if (edgeLength == 0) {
      return edge.getStart(); // Edge has zero length, return the start point
   }
   double t = ((queryPoint.getX() - edge.getStart().getX()) * (edge.getEnd().getX() - edge.getStart().getX())
         + (queryPoint.getY() - edge.getStart().getY()) * (edge.getEnd().getY() - edge.getStart().getY()))
         / Math.pow(edgeLength, 2);

   t = Math.max(0, Math.min(1, t)); // Clamp t to be between 0 and 1
   Point closestPoint = new Point(edge.getStart().getX() + t * (edge.getEnd().getX() - edge.getStart().getX()),
         edge.getStart().getY() + t * (edge.getEnd().getY() - edge.getStart().getY()));
   return closestPoint;
}
