public static void getMatchingFiles(String fullPattern, File dir, Set<File> result) throws IOException {
    File[] files = dir.listFiles();
    if (files != null) {
        for (File file : files) {
            if (file.isDirectory()) {
                getMatchingFiles(fullPattern, file, result);
            } else {
                String filePath = file.getAbsolutePath();
                if (filePath.matches(fullPattern)) {
                    result.add(file);
                }
            }
        }
    } else {
        throw new IOException("Unable to retrieve directory contents: " + dir);
    }
}
