    String osName = System.getProperty("os.name").toLowerCase();
    String mariaDBVersion = getConfiguredMariaDBVersion(); // implementation of this function is not included
    String mariaDBFilePath = getFilePathBasedOnOS(osName, mariaDBVersion);
    // implementation of unpacking the file to file system is not included
}

private String getFilePathBasedOnOS(String osName, String mariaDBVersion) {
    String fileExtension;
    if (osName.contains("win")) {
        fileExtension = ".exe";
    } else if (osName.contains("mac")) {
        fileExtension = ".dmg";
    } else if (osName.contains("nix") || osName.contains("nux") || osName.contains("aix")) {
        fileExtension = ".tar.gz";
    } else {
        // handle unsupported OSes
        return null;
    }
    return "/path/to/mariadb-" + mariaDBVersion + fileExtension;
}
