public void setCodeCookie(HttpServletRequest request, HttpServletResponse response, String code) {
  Cookie codeCookie = new Cookie("code", code);
  codeCookie.setMaxAge(3600); // set the cookie expiration time to be 1 hour
  codeCookie.setHttpOnly(true); // restrict access to the cookie only to HTTP requests
  codeCookie.setSecure(true); // ensure that the cookie can only be transmitted via HTTPS
  response.addCookie(codeCookie); // add the cookie to the HTTP response
}
