public int getHandlerCount(Handler firstHandler, Handler handler) {
    int count = 0;
    Handler currentHandler = firstHandler;
    while (currentHandler != null && currentHandler.equals(handler)) {
        count++;
        currentHandler = currentHandler.getNextHandler();
    }
    return count;
}
