public PGPPublicKeyRingCollection getSigningPublicKeyRingCollection(PGPPublicKeyRingCollection publicKeyRingCollection) throws IOException, PGPException {
    PGPPublicKeyRingCollection signingPublicKeyRingCollection = new PGPPublicKeyRingCollection(new ArrayList<>());
    Iterator<PGPPublicKeyRing> publicKeyRingIterator = publicKeyRingCollection.getKeyRings();
    while (publicKeyRingIterator.hasNext()) {
        PGPPublicKeyRing publicKeyRing = publicKeyRingIterator.next();
        if (publicKeyRing.contains(getSigningPublicKey(publicKeyRing))) {
            signingPublicKeyRingCollection = PGPPublicKeyRingCollection.addPublicKeyRing(signingPublicKeyRingCollection, publicKeyRing);
        }
    }
    return signingPublicKeyRingCollection;
}

private PGPPublicKey getSigningPublicKey(PGPPublicKeyRing publicKeyRing) {
    PGPSecretKeyRing secretKeyRing = getSecretKeyRing(publicKeyRing);

    if (secretKeyRing == null) {
        throw new IllegalArgumentException("Secret key not found in specified key ring");
    }

    PGPSecretKey signingSecretKey = secretKeyRing.getSecretKey();
    return signingSecretKey.getPublicKey();
}

private PGPSecretKeyRing getSecretKeyRing(PGPPublicKeyRing publicKeyRing) {
    PGPSecretKeyRingCollection secretKeyRingCollection = getSecretKeyRingCollection();
    Iterator<PGPSecretKeyRing> secretKeyRingIterator = secretKeyRingCollection.getKeyRings();

    while (secretKeyRingIterator.hasNext()) {
        PGPSecretKeyRing secretKeyRing = secretKeyRingIterator.next();
        if (secretKeyRing.getPublicKey().equals(publicKeyRing.getPublicKey())) {
            return secretKeyRing;
        }
    }
    return null;
}

