public void registerMBean(Object bean, ObjectName parent) throws Exception {
    MBeanServer mbs = ManagementFactory.getPlatformMBeanServer();
    ObjectName name = new ObjectName(bean.getClass().getName() + ":type=" + bean.getClass().getSimpleName());
    if (parent != null) {
        mbs.registerMBean(bean, name, parent);
    } else {
        mbs.registerMBean(bean, name);
    }
}
