public void runCompounds(List<Compound> comp, int numproc) throws Exception {
    ExecutorService executorService = Executors.newFixedThreadPool(numproc + 1);
    try {
        for (Compound compound : comp) {
            executorService.submit(compound::run);
        }
    } finally {
        executorService.shutdown();
    }
}
