public void setWedgeBond(Bond bond, Atom end, WedgeStyle style) {
    // Determine the two atoms involved in the bond
    Atom start = bond.getBeginAtom();
    end = bond.getEndAtom();

    // Determine the storage order of the atoms
    boolean reverse = start.compareTo(end) > 0;

    // Set the appropriate bond direction and style
    if (reverse) {
        bond.setDirection(Direction.BACKWARD);
        bond.setStereo(style == WedgeStyle.UP ? Stereo.DOWN : Stereo.UP);
    } else {
        bond.setDirection(Direction.FORWARD);
        bond.setStereo(style == WedgeStyle.UP ? Stereo.UP : Stereo.DOWN);
    }
}
