public static <K, V> Map<K, V> getMapDifference(Map<K, V> oldObject, Map<K, V> newObject) {
    Map<K, V> difference = new HashMap<>();

    for (K key : oldObject.keySet()) {
        if (!newObject.containsKey(key)) {
            difference.put(key, oldObject.get(key));
        } else if (!Objects.equals(oldObject.get(key), newObject.get(key))) {
            difference.put(key, oldObject.get(key));
        }
    }

    for (K key : newObject.keySet()) {
        if (!oldObject.containsKey(key)) {
            difference.put(key, newObject.get(key));
        }
    }

    return difference;
}
