public class RandomDateUtils {

    private static final long MIN_INSTANT = -2880000000000L; // minimum instant value is Thu Jan 01 00:00:00 GMT 1970

    public static Date getRandomDateBefore(Date before) {
        if (before == null || before.getTime() <= MIN_INSTANT) {
            throw new IllegalArgumentException("Invalid input date");
        }
        long randomTime = (long) (Math.random() * before.getTime());
        return new Date(randomTime);
    }
}
