public void readTraceFile(File traceFile, Callback callback) {
    try (BufferedReader reader = new BufferedReader(new FileReader(traceFile))) {
        String line;
        while ((line = reader.readLine()) != null) {
            if (callback != null) {
                callback.sendMessage(line);
            } else {
                return;
            }
        }
    } catch (IOException e) {
        System.err.println("Error reading trace file: " + e.getMessage());
    }
}
