public void buildFieldDocumentation(Element node, Document memberDetailsTree) {
   //Retrieve the list of fields from the XML node
   NodeList fieldList = node.getElementsByTagName("field");

   //iterate through each field and add documentation to the memberDetailsTree
   for(int i = 0; i < fieldList.getLength(); i++) {
      Element field = (Element) fieldList.item(i);
      String fieldName = field.getAttribute("name");

      //Create a new member element to hold the documentation for this field
      Element member = memberDetailsTree.createElement("member");
      member.setAttribute("name", fieldName);
      memberDetailsTree.appendChild(member);

      //Get the documentation from the XML and add it to the member element
      Element docElement = (Element) field.getElementsByTagName("documentation").item(0);
      if(docElement != null) {
         String docText = docElement.getTextContent();
         Element summaryElement = memberDetailsTree.createElement("summary");
         summaryElement.setTextContent(docText);
         member.appendChild(summaryElement);
      }
   }
}
