public static double[][] calculatePercents(int[][] sourceTable, int column1, int column2) {
    int rowCount = sourceTable.length;
    int[] column1Counts = new int[rowCount];
    int[] column2Counts = new int[rowCount];
    double[][] percents = new double[rowCount][rowCount];

    // Calculate counts for each column
    for (int i = 0; i < rowCount; i++) {
        for (int j = 0; j < rowCount; j++) {
            int value = sourceTable[i][j];
            column1Counts[i] += value;
            column2Counts[j] += value;
        }
    }

    // Calculate percents for each cell
    for (int i = 0; i < rowCount; i++) {
        for (int j = 0; j < rowCount; j++) {
            int value = sourceTable[i][j];
            double percent = 0.0;
            if (column1Counts[i] != 0) {
                percent = ((double) value / column1Counts[i]) * 100.0;
            }
            percents[i][j] = percent;
        }
    }

    return percents;
}
