public void convertOrcToJson(FileSystem fs, Path outputPath, OutputStream outputStream) throws IOException {
    Reader reader = OrcFile.createReader(fs, outputPath);
    TypeDescription schema = reader.getSchema();
    RecordReader rows = reader.rows();
    VectorizedRowBatch batch = schema.createRowBatch();
    Writer writer = new JsonWriter(outputStream);
    writer.writeStartArray();
    while (rows.nextBatch(batch)) {
        for (int r = 0; r < batch.size; r++) {
            writer.writeStartObject();
            for (int m = 0; m < batch.numCols; ++m) {
                String fieldName = schema.getFieldNames().get(m);
                TypeDescription fieldType = schema.getChildren().get(m);
                Object fieldValue = OrcUtils.getFieldValue(batch.cols[m], r, fieldType);
                writer.writeFieldName(fieldName);
                if (fieldValue instanceof String) {
                    writer.writeString((String) fieldValue);
                } else if (fieldValue instanceof Boolean) {
                    writer.writeBoolean((Boolean) fieldValue);
                } else if (fieldValue instanceof Long) {
                    writer.writeNumber((Long) fieldValue);
                } else if (fieldValue instanceof Double) {
                    writer.writeNumber((Double) fieldValue);
                } else if (fieldValue instanceof Timestamp) {
                    writer.writeString(((Timestamp) fieldValue).toInstant().toString());
                } else if (fieldValue instanceof Decimal) {
                    writer.writeNumber(((Decimal) fieldValue).doubleValue());
                } else {
                    writer.writeNull();
                }
            }
            writer.writeEndObject();
        }
    }
    writer.writeEndArray();
    writer.close();
}
