public void removeChild(Node child) {
    Objects.requireNonNull(child, "Child cannot be null.");
    if (!Arrays.asList(children).contains(child)) {
        throw new IllegalArgumentException("Given child is not a child of this node.");
    }
    child.parent = null;
    children = Arrays.stream(children)
                     .filter(node -> !node.equals(child))
                     .toArray(Node[]::new);
}
