public static double computeSquaredEuclideanDistanceOnSphere(double[] t0, double[] t1, double size) {
    if (t0.length != t1.length) {
        throw new IllegalArgumentException("Arrays must have the same length");
    }
    double sum = 0.0;
    for (int i = 0; i < t0.length; i++) {
        double delta = t0[i] - t1[i];
        sum += delta * delta;
    }
    return size*size * sum;
}
