import java.net.URL;
import java.util.HashMap;
import java.util.Map;

public class ClassLoaderUtil {

    public static URL searchResource(String resourceName, ClassLoader classLoader, ClassLoader[] additionalLoaders) {
        URL url = searchResource(resourceName, classLoader);
        if (url == null && additionalLoaders != null) {
            for (ClassLoader additionalLoader : additionalLoaders) {
                if (additionalLoader != null) {
                    url = searchResource(resourceName, additionalLoader);
                    if (url != null) {
                        break;
                    }
                }
            }
        }
        return url;
    }

    private static URL searchResource(String resourceName, ClassLoader classLoader) {
        URL url = null;
        if (classLoader != null) {
            String resource = resourceName.endsWith("/") ? resourceName : resourceName + "/";
            url = classLoader.getResource(resource);
            if (url == null && resourceName.startsWith("/")) {
                url = classLoader.getResource(resourceName.substring(1));
            }
            if (url != null && "jar".equals(url.getProtocol())) {
                String jarUrl = url.toString().substring(0, url.toString().lastIndexOf("!") + 1);
                url = getJarEntryUrl(jarUrl, resource);
            }
        }
        return url;
    }

    private static URL getJarEntryUrl(String jarUrl, String resourceName) {
        Map<String, URL> resourceMap = new HashMap<>();
        URL url = resourceMap.put(resourceName, null);
        if (url == null) {
            url = ClassLoader.getSystemResource(resourceName);
            if (url != null) {
                resourceMap.put(resourceName, url);
            }
        }
        return url;
    }
}
