public String[][] getFormattedTokens(DataFrame frame) {
    List<List<String>> data = frame.getData();
    int numRows = data.size();
    int numCols = frame.getColumnNames().size();
    String[][] tokens = new String[numRows][numCols];
    for (int i = 0; i < numRows; i++) {
        List<String> row = data.get(i);
        for (int j = 0; j < numCols; j++) {
            tokens[i][j] = row.get(j);
        }
    }
    return tokens;
}
