public void parseVariableDefinitions(BeanDefinitionBuilder builder, Element element) {
    NodeList childNodes = element.getChildNodes();
    for (int i = 0; i < childNodes.getLength(); i++) {
        Node childNode = childNodes.item(i);
        if (childNode instanceof Element && "variable".equals(childNode.getNodeName())) {
            String name = ((Element) childNode).getAttribute("name");
            String value = ((Element) childNode).getAttribute("value");
            builder.addPropertyValue(name, value);
        }
    }
}
