    public List<String> getAttributesFromRequest(HttpServletRequest request) {
        String username = currentUserProvider.getCurrentUser().getUsername();
        // Assuming the attributes are stored as request parameters with the prefix "attr_"
        return request.getParameterMap().entrySet().stream()
                .filter(entry -> entry.getKey().startsWith("attr_"))
                .map(entry -> entry.getValue()[0])
                .collect(Collectors.toList());
    }
}

