public static String unbackQuoteChars(String string) {
    StringBuilder result = new StringBuilder();
    int i = 0;
    while (i < string.length()) {
        char ch = string.charAt(i);
        if (ch == '\\') {
            i++;
            ch = string.charAt(i);
            switch (ch) {
                case 'r':
                    result.append('\r');
                    break;
                case 'n':
                    result.append('\n');
                    break;
                case 't':
                    result.append('\t');
                    break;
                case '\\':
                    result.append('\\');
                    break;
                case '"':
                    result.append('"');
                    break;
                case '%':
                    result.append('%');
                    break;
                default:
                    throw new IllegalArgumentException("Invalid escaped character: \\" + ch);
            }
        } else {
            result.append(ch);
        }
        i++;
    }
    return result.toString();
}
