public static <T> Matcher<Method> setterWithArgumentMatching(final Matcher<T> matcher) {
    return new TypeSafeMatcher<Method>() {
        @Override
        public void describeTo(Description description) {
            description.appendText("setter with argument matching: ");
            description.appendDescriptionOf(matcher);
        }

        @Override
        public boolean matchesSafely(Method method) {
            if (method.getParameterCount() == 1
                    && method.getName().startsWith("set")
                    && !method.getReturnType().equals(void.class)) {
                Class<?> parameterType = method.getParameterTypes()[0];
                return matcher.matches(parameterType);
            }
            return false;
        }
    };
}
