public static Tensor separableConv2d(Tensor inputs, Conv2DConfig conv2DConfig) {
    // Extract the necessary parameters from the configuration
    int[] kernelSize = conv2DConfig.getKernelSize();
    int[] strides = conv2DConfig.getStrides();
    int[] padding = conv2DConfig.getPadding();
    int depthMultiplier = conv2DConfig.getDepthMultiplier();

    // Perform the depthwise convolution
    Tensor depthwiseConv = Conv2d.depthwiseConv2d(inputs, kernelSize, strides, padding);

    // Perform the pointwise convolution
    Tensor pointwiseWeights = Tensor.random(inputs.getShape()[2], depthMultiplier);
    Tensor pointwiseConv = Conv2d.conv2d(depthwiseConv, pointwiseWeights, strides, padding);

    return pointwiseConv;
}
