public Model createFlattenedPom(File pomFile) throws MojoExecutionException, MojoFailureException {
    try {
        Model model = new MavenXpp3Reader().read(new FileReader(pomFile));
        ModelResolver mr = new DefaultModelResolver(
            session, 
            Collections.emptyList(), 
            null, 
            new DefaultArtifactResolver(), 
            new DefaultRepositorySystem(null, null, null), 
            Collections.emptyList());
        ModelBuildingRequest req = new DefaultModelBuildingRequest();
        req.setProcessPlugins(false);
        req.setModelResolver(mr);
        req.setSystemProperties(System.getProperties());
        req.setModel(model);
        DefaultModelBuilder dmb = new DefaultModelBuilderFactory().newInstance();
        return dmb.build(req).getEffectiveModel();
    } catch (IOException | XmlPullParserException | ModelBuildingException e) {
        throw new MojoExecutionException("Error processing POM: " + e.getMessage());
    }
}
