public String getClassName() {
    String className = null;
    try {
        // Assume that 'file' is the instance of the File or ZipFile or JarFile class
        // and 'lastEntry' is the last entry returned by the 'next()' method
        String fileName = (file instanceof File) ? ((File) file).getName() : ((ZipFile/JarFile) file).getName();
