public static String formatFileSize(long value) {
    String unit = "B";
    double size = value;
    if (size >= 1024) {
        unit = "KB";
        size /= 1024;
    }
    if (size >= 1024) {
        unit = "MB";
        size /= 1024;
    }
    if (size >= 1024) {
        unit = "GB";
        size /= 1024;
    }
    if (size >= 1024) {
        unit = "TB";
        size /= 1024;
    }
    return String.format("%.2f %s", size, unit);
}
