public int calculateTrackDurationConsideringEdits(Track track) {
    int duration = 0;
    for (Segment segment : track.getSegments()) {
        duration += segment.getDuration();
        if (segment.getEdits() != null) {
            for (Edit edit : segment.getEdits()) {
                duration += edit.getDuration();
            }
        }
    }
    return duration;
}
