public String getResponseType(int code) {
    String responseType;
    switch(code) {
        case 200:
            responseType = "OK";
            break;
        case 201:
            responseType = "Created";
            break;
        case 204:
            responseType = "No Content";
            break;
        case 400:
            responseType = "Bad Request";
            break;
        case 401:
            responseType = "Unauthorized";
            break;
        case 403:
            responseType = "Forbidden";
            break;
        case 404:
            responseType = "Not Found";
            break;
        case 500:
            responseType = "Internal Server Error";
            break;
        case 503:
            responseType = "Service Unavailable";
            break;
        default:
            responseType = "Unknown";
            break;
    }
    return responseType;
}
