public static void determinePairwiseDistances(int id, ArrayIterator it, Object n, DistanceQuery distQuery, DataStore m) {
    double[] newObject = m.get(id);
    while(it.hasNext()) {
        double[] object = m.get(it.getNextID());
        double distance = distQuery.getDistance(newObject, object);
        m.setDistance(id, it.getNextID(), distance);
        m.setDistance(it.getNextID(), id, distance);
    }
}
