import java.util.concurrent.*;

public class ScheduleRunner {
    public static <V> ScheduledFuture<V> runWithSchedule(int delayMillis, Callable<V> callable) {
        ScheduledExecutorService executor = Executors.newSingleThreadScheduledExecutor();
        ScheduledFuture<V> future = executor.schedule(callable, delayMillis, TimeUnit.MILLISECONDS);
        executor.shutdown();
        return future;
    }
}
