public String formatLibrary(Database db, String iLanguage) {
    String result = "";
    // Retrieve all functions from the database, filtered by language if specified
    List<Function> functions = db.getFunctions().stream()
                                      .filter(f -> iLanguage == null || f.getLanguage().equals(iLanguage))
                                      .collect(Collectors.toList());
    // Format the functions into a string
    for (Function f : functions) {
        result += f.getName() + "\n"
                + "  Parameters: " + f.getParameters() + "\n"
                + "  Returns: " + f.getReturns() + "\n"
                + "  Description: " + f.getDescription() + "\n\n";
    }
    return result;
}
