public static boolean isInternationalPhoneNumber(String s) {
    if (s == null || s.isEmpty()) {
        return false;
    }

    String phoneNumber = s.trim();

    if (phoneNumber.charAt(0) == '+') {
        phoneNumber = phoneNumber.substring(1);
    }

    return phoneNumber.matches("\\d+");
}
