public class GenericBuilder<T> {
    private final Supplier<T> instanceSupplier;

    private GenericBuilder(Supplier<T> instanceSupplier) {
        this.instanceSupplier = instanceSupplier;
    }

    public static <T> GenericBuilder<T> of(Supplier<T> instanceSupplier) {
        return new GenericBuilder<>(instanceSupplier);
    }

    public <U> GenericBuilder<T> with(BiConsumer<T, U> consumer, U value) {
        T instance = instanceSupplier.get();
        consumer.accept(instance, value);
        return new GenericBuilder<>(() -> instance);
    }

    public T build() {
        return instanceSupplier.get();
    }
}
