public List<CompactionResource> fetchFilteredCompactionResources(String filter) {
    List<CompactionResource> resources = new ArrayList<>();
    // Convert the JSON filter string to a Map
    Map<String, String> filterMap = new HashMap<>();
    try {
        JSONObject jsonObject = new JSONObject(filter);
        Iterator<String> keys = jsonObject.keys();
        while (keys.hasNext()) {
            String key = keys.next();
            String value = jsonObject.getString(key);
            filterMap.put(key, value);
        }
    } catch (JSONException e) {
        e.printStackTrace();
        throw new IllegalArgumentException("Invalid filter string: " + filter);
    }
    // Fetch the resources that match the filter criteria
    for (CompactionResource resource : allResources) {
        boolean matchesFilter = true;
        for (Map.Entry<String, String> filterEntry : filterMap.entrySet()) {
            String propertyName = filterEntry.getKey();
            String propertyValue = filterEntry.getValue();
            if (!resource.getPropertyValue(propertyName).equals(propertyValue)) {
                matchesFilter = false;
                break;
            }
        }
        if (matchesFilter) {
            resources.add(resource);
        }
    }
    return resources;
}
