public static String readFileFromPath(FileSystem fs, String path, int bufferSize) throws IOException {
    Path filePath = fs.getPath(path);
    try (InputStream inputStream = Files.newInputStream(filePath);
            BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream, StandardCharsets.UTF_8))) {
        char[] buffer = new char[bufferSize];
        StringBuilder stringBuilder = new StringBuilder();
        int numCharsRead;
        while ((numCharsRead = reader.read(buffer, 0, bufferSize)) != -1) {
            stringBuilder.append(buffer, 0, numCharsRead);
        }
        return stringBuilder.toString();
    }
}
