public void removePageAttributes(Map<String, Object> attributes, Map<String, Object> priorAttributes) {
    // Check if attributes map is not null or empty
    if (attributes != null && !attributes.isEmpty()) {
        // Iterate over the attributes map
        for (Map.Entry<String, Object> entry : attributes.entrySet()) {
            String key = entry.getKey();
            Object value = entry.getValue();

            // Check if the attribute is exposed and can be restored
            if (isExposedAttribute(key)) {
                // Save prior value of the attribute
                Object priorValue = savePriorAttributeValue(key, priorAttributes, value);

                // Remove the attribute from the map
                attributes.remove(key);

                // Restore the attribute's prior value, if it exists
                if (priorValue != null) {
                    attributes.put(key, priorValue);
                }
            }
        }
    }
}

private boolean isExposedAttribute(String key) {
    // Check if the key is an exposed attribute
    return key.startsWith("page.") && !key.equals("page.id");
}

private Object savePriorAttributeValue(String key, Map<String, Object> priorAttributes, Object attributeValue) {
    if (priorAttributes != null) {
        // Check if the key exists in the prior attributes map
        if (priorAttributes.containsKey(key)) {
            // Save the prior value of the attribute in the map
            return priorAttributes.put(key, attributeValue);
        } else {
            // Add the attribute to the prior attributes map with its current value
            priorAttributes.put(key, attributeValue);
        }
    }

    return null;
}
