public DataSource createBatchCreateEntityPart(String entityName, Object entity, String uri, String contentId) throws JAXBException {
    JAXBContext context = JAXBContext.newInstance(entity.getClass());
    Marshaller marshaller = context.createMarshaller();
    marshaller.setProperty(Marshaller.JAXB_FORMATTED_OUTPUT, true);

    ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
    marshaller.marshal(entity, outputStream);

    DataSource source = new ByteArrayDataSource(outputStream.toByteArray(), "application/xml");
    DataHandler handler = new DataHandler(source);

    BodyPart bodyPart = new MimeBodyPart();
    bodyPart.setDataHandler(handler);
    bodyPart.setDisposition(FormDataContentDisposition.name("entity").fileName(uri).creationDate(new Date()).size(outputStream.size()).build());
    bodyPart.setHeader("Content-ID", contentId);

    return source;
}
