public static <T> Iterator<List<T>> iterativelyPartition(Iterable<T> iterable, int iterationGoalMillis) {
    int targetSize = 1;
    long startTime = System.currentTimeMillis();
    Iterator<T> iterator = iterable.iterator();
    List<T> buffer = new ArrayList<>(targetSize);
    return new Iterator<>() {
        @Override
        public boolean hasNext() {
            if (buffer.isEmpty()) {
                if (iterator.hasNext()) {
                    buffer.add(iterator.next());
                }
            }
            return !buffer.isEmpty();
        }

        @Override
        public List<T> next() {
            if (!hasNext()) {
                throw new NoSuchElementException();
            }
            int count = 1;
            long iterationStartTime = System.currentTimeMillis();
            while (iterator.hasNext()) {
                if ((System.currentTimeMillis() - iterationStartTime) * targetSize >= iterationGoalMillis) {
                    break;
                }
                buffer.add(iterator.next());
                count++;
            }
            long elapsed = System.currentTimeMillis() - startTime + 1;
            int totalSize = buffer.size() + count - 1;
            targetSize = (int) Math.ceil((double) totalSize / elapsed * iterationGoalMillis);
            List<T> result = new ArrayList<>(buffer);
            buffer.clear();
            return result;
        }
    };
}
