public Coin parseCoinValue(String coinValueStr) throws NumberFormatException {
    String[] parts = coinValueStr.split("\\.");

    if(parts.length != 2 || parts[0].isEmpty() || parts[1].isEmpty()) {
        throw new NumberFormatException();
    }

    int wholePart = Integer.parseInt(parts[0]);
    int fractionalPart = Integer.parseInt(parts[1]);
    if(fractionalPart >= 100) {
        throw new NumberFormatException();
    }

    return new Coin(wholePart, fractionalPart);
}
