public boolean sameStructure(BufferedListModel model, Collection collection) {
    List<Object> list1 = model.asList();
    List<Object> list2 = new ArrayList<>(collection);

    if (list1.isEmpty() && list2 == null) {
        return true;
    }

    if (list1.size() != list2.size()) {
        return false;
    }

    for (int i = 0; i < list1.size(); i++) {
        Object element1 = list1.get(i);
        Object element2 = list2.get(i);

        if ((element1 == null || element1 instanceof List && ((List) element1).isEmpty()) &&
                (element2 == null || element2 instanceof List && ((List) element2).isEmpty())) {
            continue;
        }

        if (!Objects.equals(element1, element2)) {
            return false;
        }
    }

    return true;
}
