public static <T extends Serializable> void restoreReferencesAfterSerialization(T serializableObject, Map<String, BigMap<?, ?>> objReferences) {
    if (serializableObject != null && objReferences != null && !objReferences.isEmpty()) {
        try {
            ByteArrayOutputStream baos = new ByteArrayOutputStream();
            ObjectOutputStream oos = new ObjectOutputStream(baos);
            oos.writeObject(serializableObject);
            oos.flush();
            oos.close();

            ByteArrayInputStream bais = new ByteArrayInputStream(baos.toByteArray());
            ObjectInputStream ois = new ObjectInputStream(bais);
            T deserializedObject = (T) ois.readObject();
            ois.close();

            // Retrieve all fields from the deserialized object
            Field[] fields = deserializedObject.getClass().getDeclaredFields();

            for (Field field : fields) {
                if (objReferences.containsKey(field.getName())) {
                    field.setAccessible(true); // make the field accessible
                    field.set(deserializedObject, objReferences.get(field.getName())); // set the reference back
                }
            }

        } catch (IOException | ClassNotFoundException | IllegalAccessException e) {
            e.printStackTrace();
        }
    }
}
