private <T> void copyEventHandler(RuntimeInjector runtimeInjector, Class<T> param) throws InjectionException {
     try {
         Set<EventHandler<T>> handlers = injector.get().getAllBindings().keySet().stream()
                                          .filter(KeyMatchers.isSubtypeOf(param))
                                          .map(injector.get()::getInstance)
                                          .collect(Collectors.toSet());

         for (EventHandler<T> handler : handlers) {
             runtimeInjector.addHandler(handler);
         }
     } catch (ConfigurationException e) {
         throw new InjectionException("Configuration error occurred while copying event handler.", e);
     }
}
