public List<Runner> buildRunnersForChildClasses(Class<?>[] children, Runner parent) throws Exception {
    List<Runner> runners = new ArrayList<>();
    List<Class<?>> processedClasses = new ArrayList<>();
    for (Class<?> child : children) {
        if (processedClasses.contains(child)) {
            throw new Exception("Infinite recursion detected at class: " + child.getName());
        }
        processedClasses.add(child);
        Runner runner = new Runner.Builder().parent(parent).child(child).build();
        List<Runner> childRunners = buildRunnersForChildClasses(child.getDeclaredClasses(), runner);
        runners.add(runner);
        runners.addAll(childRunners);
    }
    return runners;
}
