    List<String> convertedFeatures = new ArrayList<String>();
    for (String feature : features) {
        if (!normalFeature && feature.startsWith("!")) {
            convertedFeatures.add(feature.substring(1));
        } else if (!normalFeature) {
            convertedFeatures.add("!" + feature);
        } else {
            convertedFeatures.add(feature);
        }
    }
    return convertedFeatures;
}
