public static void verifyNoCycle(Vertex node, Set<Vertex> dependencies) throws CyclicDependencyException {
    Set<Vertex> visited = new HashSet<>();
    Set<Vertex> recStack = new HashSet<>();
    visited.add(node);
    if (hasCycle(node, visited, recStack, dependencies)) {
        throw new CyclicDependencyException("Graph contains a cycle");
    }
}

private static boolean hasCycle(Vertex node, Set<Vertex> visited, Set<Vertex> recStack, Set<Vertex> dependencies) {
    if (!dependencies.contains(node)) {
        return false;
    }
    recStack.add(node);
    for (Vertex neighbor : dependencies) {
        if (!visited.contains(neighbor)) {
            visited.add(neighbor);
            if (hasCycle(neighbor, visited, recStack, dependencies)) {
                return true;
            }
        } else if (recStack.contains(neighbor)) {
            return true;
        }
    }
    recStack.remove(node);
    return false;
}
