import org.objectweb.asm.Type;
import org.objectweb.asm.tree.*;

public Object addMethodAnnotation(ClassNode javaClass, MethodNode method) {
    AnnotationNode annotation = new AnnotationNode(Type.getDescriptor(MyMethodAnnotation.class));
    if (method.visibleAnnotations == null) {
        method.visibleAnnotations = new java.util.ArrayList<>();
        method.visibleAnnotations.add(annotation);
    } else {
        boolean isNew = true;
        for (AnnotationNode ann : method.visibleAnnotations) {
            if (Type.getDescriptor(MyMethodAnnotation.class).equals(ann.desc)) {
                ann = annotation;
                isNew = false;
            }
        }
        if (isNew) {
            method.visibleAnnotations.add(annotation);
        }
    }
    if (method.instructions != null && !method.instructions.isEmpty()) {
        int lineNumber = -1;
        for (AbstractInsnNode insn : method.instructions) {
            if (insn instanceof LineNumberNode) {
                lineNumber = ((LineNumberNode) insn).line;
                break;
            }
        }
        if (lineNumber > 0) {
            annotation = new AnnotationNode(Type.getDescriptor(SourceLineAnnotation.class));
            annotation.values = new java.util.ArrayList<>();
            annotation.values.add(new Integer(lineNumber));
            method.visibleAnnotations.add(annotation);
        }
    }
    return this;
}
