import java.net.*;
import java.io.*;

public class BiDirectionalExample {

    public static void main(String[] args) throws IOException {

        Socket socket = new Socket("localhost", 8888);

        BufferedReader fromServer = new BufferedReader(new InputStreamReader(socket.getInputStream()));
        BufferedWriter toServer = new BufferedWriter(new OutputStreamWriter(socket.getOutputStream()));

        // Chat messages to send to the server
        String[] messagesToSend = {"Hello server", "How are you?", "Thanks for responding"};

        // Send chat messages to the server
        for (String message : messagesToSend) {
            toServer.write(message);
            toServer.newLine();
            toServer.flush();
        }

        // Print any chat messages sent from the server
        String receivedMessage;
        while ((receivedMessage = fromServer.readLine()) != null) {
            System.out.println(receivedMessage);
        }

        socket.close();
    }
}
