public MultiPos replaceAll(String replacement) {
    List<Integer> positions = new ArrayList<>();
    String replaced = text;
    int index = replaced.indexOf(target);
    while (index >= 0) {
        positions.add(index);
        replaced = replaced.substring(0, index) + replacement + replaced.substring(index + target.length());
        index = replaced.indexOf(target, index + replacement.length());
    }
    return new MultiPos(positions, replaced);
}
