public Signer DERencode(Signer signer, ASN1Object tbsObj) throws IOException {
    ByteArrayOutputStream baos = new ByteArrayOutputStream();
    DEROutputStream dos = new DEROutputStream(baos);
    dos.writeObject(tbsObj);
    byte[] encodedObj = baos.toByteArray();
    signer.update(encodedObj);
    return signer;
}
