public boolean isSupportedFile(File file) {
    // Check if file extension is supported by sequencer
    String extension = getFileExtension(file.getName());
    List<String> supportedExtensions = Arrays.asList("mp3", "wav", "aif");
    if (!supportedExtensions.contains(extension)) {
        return false;
    }

    // Check if file is a container and extract root files
    if (isContainer(file)) {
        List<File> rootFiles = getRootFiles(file);
        if (rootFiles.isEmpty()) {
            return false;
        }

        // Process each root file and extract metadata
        for (File rootFile : rootFiles) {
            Metadata metadata = extractMetadata(rootFile);
            if (metadata.isEmpty()) {
                return false;
            }
        }
    } else {
        // File is not a container, extract metadata directly
        Metadata metadata = extractMetadata(file);
        if (metadata.isEmpty()) {
            return false;
        }
    }

    // File is supported by sequencer
    return true;
}

