@Override
public List<URI> getPackageURIs() {
  List<URI> packageURIs = new ArrayList<>();
  for (Map.Entry<String, Object> entry : configMap.entrySet()) {
    String key = entry.getKey();
    Object value = entry.getValue();
    if (key.startsWith(PACKAGES_PROP_PREFIX) && value instanceof String) {
      String[] packageNames = ((String) value).split("\\s*,\\s*");
      for (String packageName : packageNames) {
        packageName = packageName.trim();
        if (!packageName.isEmpty()) {
          // If package name is a root-relative path, then it must be absolute. Here we check
          // whether it's an absolute path or not and convert to an absolute path if needed.
          URI packageURI = baseUrl.resolve(packageName);
          packageURIs.add(packageURI);
        }
      }
    }
  }
  return packageURIs;
}
