public long previousRecordPosition(DataFormatter formatter) throws IOException {
    long currentPosition = formatter.getFilePointer();
    byte[] eyeCatcher = formatter.getEyeCatcher();
    long startPosition = 0;
    int bufferSize = 1024;
    byte[] buffer = new byte[bufferSize];
    int bytesRead;

    while (currentPosition > startPosition) {
        long prevPosition = currentPosition - bufferSize;
        if (prevPosition < startPosition) {
            prevPosition = startPosition;
        }
        formatter.seek(prevPosition);
        bytesRead = formatter.read(buffer);

        for (int i = bytesRead - eyeCatcher.length; i >= 0; i--) {
            if (Arrays.equals(Arrays.copyOfRange(buffer, i, i + eyeCatcher.length), eyeCatcher)) {
                formatter.seek(prevPosition + i - 4);
                return formatter.getFilePointer();
            }
        }

        currentPosition = prevPosition;
    }

    throw new IOException("No eyeCatcher found in region from start of the file to the current position.");
}
