public SkippableIterator reverseflatand(Bitmap bitmap) {
    // create an empty list to store the bitmap values
    List<Integer> bitmapValues = new ArrayList<>();

    // loop through all the bytes in the bitmap
    for (int i = 0; i < bitmap.length(); i++) {
        // get the value of the current byte and add it to the list of bitmap values
        bitmapValues.add(bitmap.get(i));
    }

    // reverse the list of bitmap values
    Collections.reverse(bitmapValues);

    // create a skippable iterator for the reversed bitmap values
    SkippableIterator iterator = new SkippableIteratorImpl(bitmapValues);

    // return the skippable iterator
    return iterator;
}
