public static Element getFirstChildElementByName(Element elem, String ns, String name) {
    NodeList children = elem.getChildNodes();
    for (int i = 0; i < children.getLength(); i++) {
        Node child = children.item(i);
        if (child.getNodeType() == Node.ELEMENT_NODE && child.getLocalName().equals(name) && (ns == null || ns.equals(child.getNamespaceURI()))) {
            return (Element) child;
        }
    }
    return null;
}
