public static <T> String getCommaSeparatedList(Collection<T> list) {
    StringBuilder result = new StringBuilder();
    for (T item : list) {
        result.append(item).append(", ");
    }
    if (result.length() > 2) {
        result.setLength(result.length() - 2);
    }
    return result.toString();
}
