public int readCharacters(char[] buf, int length) throws IOException {
    int index = 0;
    int readCount = 0;
    int charRead;

    while (index < length && (charRead = System.in.read()) != -1) {
        buf[index++] = (char) charRead;
        readCount++;
    }

    if (readCount == 0 && length != 0) {
        return -1;
    }

    return readCount;
}
