public static String createUtcOffset(TimeZone timezone) {
    int offsetInMinutes = timezone.getRawOffset() / (60 * 1000);
    int hours = Math.abs(offsetInMinutes / 60);
    int minutes = Math.abs(offsetInMinutes % 60);
    char sign = offsetInMinutes >= 0 ? '+' : '-';

    return String.format("%c%02d:%02d", sign, hours, minutes);
}
