public static void solveSudoku(String[] args) {
    for (String filename : args) {
        // open the file with the puzzle
        File file = new File(filename);

        try {
            Scanner scanner = new Scanner(file);

            // read the puzzle into a 2D array
            int[][] puzzle = new int[9][9];

            int row = 0;

            while (scanner.hasNextLine()) {
                String line = scanner.nextLine();

                for (int col = 0; col < 9; col++) {
                    puzzle[row][col] = Integer.parseInt(line.charAt(col) + "");
                }

                row++;
            }

            scanner.close();

            // solve the puzzle
            solve(puzzle);

            // print the solution
            for (int i = 0; i < 9; i++) {
                for (int j = 0; j < 9; j++) {
                    System.out.print(puzzle[i][j] + " ");
                }

                System.out.println();
            }
        }
        catch (FileNotFoundException e) {
            System.out.println("File not found: " + filename);
        }
    }
}

private static boolean solve(int[][] puzzle) {
    for (int row = 0; row < 9; row++) {
        for (int col = 0; col < 9; col++) {
            if (puzzle[row][col] == 0) {
                for (int num = 1; num <= 9; num++) {
                    if (isValid(puzzle, row, col, num)) {
                        puzzle[row][col] = num;

                        if (solve(puzzle)) {
                            return true;
                        }
                        else {
                            puzzle[row][col] = 0;
                        }
                    }
                }

                return false;
            }
        }
    }

    return true;
}

private static boolean isValid(int[][] puzzle, int row, int col, int num) {
    for (int i = 0; i < 9; i++) {
        if (puzzle[row][i] == num) {
            return false;
        }

        if (puzzle[i][col] == num) {
            return false;
        }

        int boxRow = 3 * (row / 3) + i / 3;
        int boxCol = 3 * (col / 3) + i % 3;

        if (puzzle[boxRow][boxCol] == num) {
            return false;
        }
    }

    return true;
}
