import javax.faces.context.FacesContext;
import javax.faces.event.PreDestroyViewMapEvent;
import javax.faces.event.SystemEventListener;

public class ViewScopeContextualInstanceDestroyer implements SystemEventListener {

    @Override
    public void processEvent(SystemEvent event) {
        PreDestroyViewMapEvent destroyEvent = (PreDestroyViewMapEvent) event;
        FacesContext context = FacesContext.getCurrentInstance();
        context.getViewRoot().getViewMap().forEach((key, value) -> {
            if (value instanceof ContextualInstance) {
                ((ContextualInstance) value).destroy();
            }
        });
    }

    @Override
    public boolean isListenerForSource(Object source) {
        return source instanceof FacesContext;
    }

}
