@see org.commonjava.indy.core.rest.util.FileManager#downloadAll(java.util.List, java.lang.String)
*/
public void downloadAll(List<String> urls, String destDir) {
    try {
        for (String url : urls) {
            URLConnection conn = new URL(url).openConnection();
            InputStream in = conn.getInputStream();
            String fileName = url.substring(url.lastIndexOf('/') + 1);
            OutputStream out = new FileOutputStream(destDir + "/" + fileName);
            byte[] buffer = new byte[1024];
            int length;
            while ((length = in.read(buffer)) > 0) {
                out.write(buffer, 0, length);
            }
            out.close();
            in.close();
        }
    } catch (IOException e) {
        e.printStackTrace();
    }
}
