public static <T> CachedSparseTensor<T> cacheAllPermutations(SparseTensor<T> tensor) {
    int[] shape = tensor.shape();
    int[] permutation = new int[shape.length];
    for (int i = 0; i < permutation.length; i++) {
        permutation[i] = i;
    }
    List<CachedSparseTensor<T>> cachedPermutedTensors = new ArrayList<>(factorial(shape.length));
    do {
        cachedPermutedTensors.add(CachedSparseTensor.permute(tensor, permutation));
    } while (nextPermutation(permutation));
    return CachedSparseTensor.concat(cachedPermutedTensors.toArray(new CachedSparseTensor[0]));
}

private static boolean nextPermutation(int[] permutation) {
    int i = permutation.length - 2;
    while (i >= 0 && permutation[i] >= permutation[i + 1]) {
        i--;
    }
    if (i >= 0) {
        int j = permutation.length - 1;
        while (permutation[j] <= permutation[i]) {
            j--;
        }
        swap(permutation, i, j);
        int k = i + 1;
        int l = permutation.length - 1;
        while (k < l) {
            swap(permutation, k, l);
            k++;
            l--;
        }
        return true;
    }
    return false;
}

private static void swap(int[] permutation, int i, int j) {
    int temp = permutation[i];
    permutation[i] = permutation[j];
    permutation[j] = temp;
}

private static int factorial(int n) {
    int result = 1;
    for (int i = 2; i <= n; i++) {
        result *= i;
    }
    return result;
}
