public static boolean isSimpleRange(int[] arr) {
    int minIndex = arr[0];
    int maxIndex = arr[0];

    for (int i = 1; i < arr.length; i++) {
        if (arr[i] < minIndex) {
            minIndex = arr[i];
        }
        if (arr[i] > maxIndex) {
            maxIndex = arr[i];
        }
    }

    return (maxIndex - minIndex + 1) == arr.length;
}
