public Node findBottomMostHead(Node parentNode) {
    if (parentNode == null) {
        return null;
    }
    if (parentNode.getChildren().size() == 0) {
        return parentNode;
    }
    for (Node childNode : parentNode.getChildren()) {
        Node bottomMostChild = findBottomMostHead(childNode);
        if (bottomMostChild != null) {
            return bottomMostChild;
        }
    }
    return null;
}
