public class Cube {
    private double x;
    private double y;
    private double z;
    private double length;

    // Constructors
    public Cube(double x, double y, double z, double length) {
        this.x = x;
        this.y = y;
        this.z = z;
        this.length = length;
    }

    public Cube(double length) {
        this(0, 0, 0, length);
    }

    // Getter methods
    public double getX() {
        return x;
    }

    public double getY() {
        return y;
    }

    public double getZ() {
        return z;
    }

    public double getLength() {
        return length;
    }

    // Setter methods
    public void setX(double x) {
        this.x = x;
    }

    public void setY(double y) {
        this.y = y;
    }

    public void setZ(double z) {
        this.z = z;
    }

    public void setLength(double length) {
        this.length = length;
    }

    // Compute and return the center of the cube
    public Point3D getCenter(Point3D storage) {
        if (storage == null) {
            storage = new Point3D.Double();
        }
        storage.setLocation(x + length / 2, y + length / 2, z + length / 2);
        return storage;
    }
}
