import org.apache.hadoop.fs.Path;
import org.apache.hadoop.yarn.api.records.LocalResource;
import org.apache.hadoop.yarn.api.records.LocalResourceType;
import org.apache.hadoop.yarn.api.records.LocalResourceVisibility;
import org.apache.hadoop.yarn.util.ConverterUtils;

import java.io.IOException;
import java.net.URI;

public class LocalResourceCreator {

    public static LocalResource create(Path path) throws IOException {
        LocalResource resource = Records.newRecord(LocalResource.class);
        URI uri = path.toUri();
        resource.setResource(ConverterUtils.getYarnUrlFromURI(uri));
        resource.setSize(Files.size(path));
        resource.setTimestamp(Files.getLastModifiedTime(path).toMillis());
        resource.setType(LocalResourceType.FILE);
        resource.setVisibility(LocalResourceVisibility.APPLICATION);
        return resource;
    }
}
