public String getPropertyValue(Class clazz, String language, String... propertyComponents) {
    String propertyName = String.join(".", propertyComponents);
    String value;
    if (language != null && !language.isEmpty()) {
        value = clazz.getSimpleName() + "." + propertyName + "." + language;
        if (System.getProperty(value) != null) {
            return System.getProperty(value);
        }
    }
    value = clazz.getSimpleName() + "." + propertyName;
    return System.getProperty(value, "");
}
