public static double shiftTowardsZero(double val, double shift) {
    if(shift < 0) {
        throw new IllegalArgumentException("shift must be non-negative");
    }
    if(Math.abs(val) <= shift) {
        return 0;
    } else if(val < 0) {
        return val + shift;
    } else {
        return val - shift;
    }
}
