public HttpUrlConnection makeHttpPostRequest(String url, Map<String, String> headers, Map<String, String> parameters, Map<String, File> files) throws HelloSignException {
    try {
        URL requestUrl = new URL(url);
        HttpURLConnection connection = (HttpURLConnection) requestUrl.openConnection();
        connection.setDoOutput(true);
        connection.setRequestMethod("POST");

        String boundary = UUID.randomUUID().toString();
        connection.setRequestProperty("Content-Type", "multipart/form-data; boundary=" + boundary);
        OutputStream outputStream = connection.getOutputStream();
        PrintWriter writer = new PrintWriter(new OutputStreamWriter(outputStream, Charset.forName("UTF-8")), true);

        for (Map.Entry<String, String> entry : parameters.entrySet()) {
            writer.append("--" + boundary).append("\r\n");
            writer.append("Content-Disposition: form-data; name=\"" + entry.getKey() + "\"").append("\r\n");
            writer.append("Content-Type: text/plain; charset=" + "UTF-8").append("\r\n");
            writer.append("\r\n");
            writer.append(entry.getValue());
            writer.append("\r\n");
        }

        if (files != null && !files.isEmpty()) {
            for (Map.Entry<String, File> entry : files.entrySet()) {
                File file = entry.getValue();
                writer.append("--" + boundary).append("\r\n");
                writer.append("Content-Disposition: form-data; name=\"" + entry.getKey() + "\"; filename=\"" + file.getName() + "\"").append("\r\n");
                writer.append("Content-Type: " + URLConnection.guessContentTypeFromName(file.getName())).append("\r\n");
                writer.append("Content-Transfer-Encoding: binary").append("\r\n");
                writer.append("\r\n");
                writer.flush();
                try (FileInputStream inputStream = new FileInputStream(file)) {
                    byte[] buffer = new byte[1024];
                    int bytesRead;
                    while ((bytesRead = inputStream.read(buffer)) != -1) {
                        outputStream.write(buffer, 0, bytesRead);
                    }
                    outputStream.flush();
                } catch (IOException e) {
                    throw new HelloSignException("Error reading file: " + file.getName(), e);
                }
                writer.append("\r\n");
                writer.flush();
            }
        }

        writer.append("--" + boundary + "--").append("\r\n");
        writer.close();

        if (headers != null && !headers.isEmpty()) {
            for (Map.Entry<String, String> entry : headers.entrySet()) {
                connection.setRequestProperty(entry.getKey(), entry.getValue());
            }
        }

        return connection;
    } catch (IOException e) {
        throw new HelloSignException("Error making http post request", e);
    }
}
