public void pruneCache(int neededSpace) {
    if (cache.size() <= 0) {
        // cache is empty
        return;
    }

    Set<String> keysToRemove = new HashSet<String>();
    int currentCacheSize = 0;

    for (Map.Entry<String, byte[]> entry : cache.entrySet()) {
        // add the size of the cache entry to the current cache size
        currentCacheSize += entry.getValue().length;

        if (currentCacheSize > neededSpace) {
            // we have found enough cache entries to remove
            break;
        }

        // add the key to the set of keys to remove
        keysToRemove.add(entry.getKey());
    }

    // remove all keys that we no longer need
    for (String key : keysToRemove) {
        cache.remove(key);
    }
}
