public Set<String> getAmbiguousNames(List<InterfaceInfo> interfaceInfoList) {
    Set<String> ambiguousNames = new HashSet<>();
    Map<String, Integer> methodCountMap = new HashMap<>();

    for (InterfaceInfo interfaceInfo : interfaceInfoList) {
        List<String> methodNames = interfaceInfo.getMethodNames();

        for (String methodName : methodNames) {
            int count = methodCountMap.getOrDefault(methodName, 0);
            methodCountMap.put(methodName, count + 1);

            if (count == 1) {
                ambiguousNames.add(methodName);
            }
        }
    }

    return ambiguousNames;
}
