import org.elasticsearch.action.admin.cluster.health.ClusterHealthRequest;
import org.elasticsearch.action.admin.cluster.health.ClusterHealthResponse;
import org.elasticsearch.client.Client;
import org.elasticsearch.client.transport.TransportClient;
import org.elasticsearch.common.settings.Settings;
import org.elasticsearch.common.transport.InetSocketTransportAddress;
import org.elasticsearch.common.unit.TimeValue;
import org.elasticsearch.common.xcontent.XContentBuilder;
import org.elasticsearch.common.xcontent.XContentFactory;
import org.elasticsearch.index.query.QueryBuilders;
import org.elasticsearch.search.SearchHits;

import java.io.IOException;
import java.net.InetAddress;
import java.net.UnknownHostException;

public class ElasticsearchCluster {

    public static void createAndStartCluster(String[] args) {
        // Create and start Elasticsearch cluster with arguments.

        // Set cluster name
        String clusterName = args[0];

        // Set Elasticsearch data directory path
        String dataDirectory = args[1];

        // Set network host for Elasticsearch transport client
        String networkHost = args[2];

        // Set Elasticsearch transport client port
        int transportClientPort = Integer.parseInt(args[3]);

        // Set Elasticsearch cluster nodes addresses
        String nodesAddresses = args[4];

        // Set Elasticsearch index name
        String indexName = args[5];

        // Set Elasticsearch document type name
        String documentType = args[6];

        // Set Elasticsearch index mapping
        XContentBuilder mapping = null;
        try {
            mapping = XContentFactory.jsonBuilder()
                    .startObject()
                    .startObject(documentType)
                        .startObject("properties")
                            .startObject("field1")
                                .field("type", "text")
                            .endObject()
                            .startObject("field2")
                                .field("type", "integer")
                            .endObject()
                        .endObject()
                    .endObject()
                .endObject();
        } catch (IOException e) {
            System.out.println("Error building Elasticsearch index mapping");
            e.printStackTrace();
        }

        // Set Elasticsearch client settings
        Settings settings = Settings.builder()
                .put("cluster.name", clusterName)
                .put("path.data", dataDirectory)
                .build();

        // Create Elasticsearch transport client node
        try {
            Client client = TransportClient.builder()
                    .settings(settings)
                    .build()
                    .addTransportAddress(new InetSocketTransportAddress(InetAddress.getByName(networkHost), transportClientPort));

            // Create Elasticsearch index
            client.admin().indices().prepareCreate(indexName)
                    .addMapping(documentType, mapping)
                    .execute().actionGet();

            // Add documents to Elasticsearch index
            for (int i = 0; i < 10; i++) {
                XContentBuilder documentBuilder = XContentFactory.jsonBuilder()
                        .startObject()
                            .field("field1", "document " + i)
                            .field("field2", i)
                        .endObject();
                client.prepareIndex(indexName, documentType)
                        .setSource(documentBuilder)
                        .execute().actionGet();
            }

            // Get documents from Elasticsearch index
            SearchHits searchHits = client.prepareSearch(indexName)
                    .setQuery(QueryBuilders.matchAllQuery())
                    .setFrom(0)
                    .setSize(10)
                    .execute().actionGet().getHits();

            System.out.println("Total hits: " + searchHits.getTotalHits());

            // Check cluster health status
            ClusterHealthRequest healthRequest = new ClusterHealthRequest()
                    .waitForGreenStatus()
                    .timeout(TimeValue.timeValueSeconds(5));
            ClusterHealthResponse healthResponse = client.admin().cluster().health(healthRequest).actionGet();
            System.out.println("Cluster health status: " + healthResponse.getStatus());

            // Close Elasticsearch transport client node
            client.close();
        } catch (UnknownHostException e) {
            System.out.println("Error creating Elasticsearch transport client node");
            e.printStackTrace();
        }
    }
}
