public void sendInvalidationEvents() {
    Queue<Recipient> recipients = invalidator.getRecipients();
    while (!recipients.isEmpty()) {
        Recipient recipient = recipients.poll();
        Queue<Event> queue = invalidator.getQueue(recipient);
        while (!queue.isEmpty()) {
            Event event = queue.poll();
            recipient.receiveInvalidationEvent(event);
        }
    }
}
