public void printNamespacesToStream(NodeType nodeTypeData, OutputStream out) throws RepositoryException, IOException {
    NamespaceRegistry namespaceRegistry = nodeTypeData.getSession().getWorkspace().getNamespaceRegistry();
    String[] prefixArray = namespaceRegistry.getPrefixes();
    String prefix;
    for (String p : prefixArray) {
        prefix = p.trim();
        if (prefix.length() > 0) {
            out.write(prefix.getBytes());
            out.write(" = ".getBytes());
            out.write(namespaceRegistry.getURI(prefix).getBytes());
            out.write("\n".getBytes());
        }
    }
}
