public JSONArray extractComponents(JSONObject jsonData) {
    JSONArray components = new JSONArray();

    Iterator<String> keys = jsonData.keys();
    while(keys.hasNext()) {
        String key = keys.next();
        components.put(jsonData.get(key));    
    }

    return components;
}
