public static char[] appendCharArrayPart(char[] c, int off, int len) throws IOException {
    if (c == null) {
        throw new IllegalArgumentException("Char array can not be null");
    }
    if (off < 0 || off >= c.length) {
        throw new IndexOutOfBoundsException("Start index must be between 0 and the length of the char array");
    }
    if (len < 1 || off + len > c.length) {
        throw new IllegalArgumentException("Length must be greater than zero and start index plus length must not exceed the length of the char array");
    }
    char[] result = new char[len];
    System.arraycopy(c, off, result, 0, len);
    return result;
}
