public int getIndex(SQLTable _sqlTable) {
    if (_sqlTable == null) {
        throw new IllegalArgumentException("SQLTable should not be null.");
    }

    int index = -1;
    for (int i = 0; i < sqlTables.size(); i++) {
        if (_sqlTable.equals(sqlTables.get(i))) {
            index = i;
            break;
        }
    }

    if (index == -1) {
        sqlTables.add(_sqlTable);
        index = sqlTables.size() - 1;
    }

    return index;
}
