import java.io.*;
import org.apache.hadoop.fs.FileSystem;
import org.apache.hadoop.fs.Path;
import org.apache.hadoop.conf.Configuration;

public void replaceOrAppendFolder(String destFolderPath, String mapReduceOutputPath) throws Exception {
    // Create a new record count file
    int recordCount = getRecordCount(mapReduceOutputPath);
    Path recordCountFilePath = new Path(destFolderPath, "record_count.txt");
    FileSystem fs = FileSystem.get(new Configuration());
    OutputStream os = fs.create(recordCountFilePath);
    os.write(Integer.toString(recordCount).getBytes());
    os.close();
    // Replace or append the destination folder with new files from map-reduce job
    Path mapReduceOutputFolderPath = new Path(mapReduceOutputPath);
    Path destFolder = new Path(destFolderPath);
    fs.copyFromLocalFile(false, true, new Path(mapReduceOutputFolderPath, "*"), destFolder);
}

private int getRecordCount(String mapReduceOutputPath) throws Exception {
    // Get the number of files in map-reduce output folder
    Path mapReduceOutputFolderPath = new Path(mapReduceOutputPath);
    FileSystem fs = FileSystem.get(new Configuration());
    FileStatus[] fileStatuses = fs.listStatus(mapReduceOutputFolderPath);
    int fileCount = fileStatuses.length;
    // Count the number of records in each file
    int recordCount = 0;
    for(FileStatus fileStatus : fileStatuses) {
        Path filePath = fileStatus.getPath();
        BufferedReader br = new BufferedReader(new InputStreamReader(fs.open(filePath)));
        while(br.readLine() != null) {
            recordCount++;
        }
        br.close();
    }
    return recordCount;
}
