public <T> void populateUsermeta(T obj, Map<String, String> userMetadata) {
    Field[] fields = obj.getClass().getDeclaredFields();
    for (Field field : fields) {
        RiakUsermeta annotation = field.getAnnotation(RiakUsermeta.class);
        if (annotation != null) {
            String key = annotation.key();
            String value = userMetadata.get(key);
            if (value != null) {
                try {
                    field.setAccessible(true);
                    field.set(obj, value);
                } catch (IllegalAccessException e) {
                    e.printStackTrace();
                }
            }
        }
    }
}
