public Object find(Object[] array, Object key) {
    return find(array, key, 0);
}

private Object find(Object[] array, Object key, int index) {
    if (index >= array.length) {
        return null;
    } else if (array[index].equals(key)) {
        return array[index];
    } else {
        return find(array, key, index + 1);
    }
}
