import org.apache.lucene.util.fst.*;

public FST<Object> deepCopyFst(FST<Object> fst) throws Exception {
    // Create a new empty FST with the same comparator
    FST<Object> newFst = new FST<>(fst.inputType(), fst.outputs);

    // Create a new symbol table with the same input/output symbols
    ByteSequenceOutputs outputs = ByteSequenceOutputs.getSingleton();
    PositiveIntOutputs weights = PositiveIntOutputs.getSingleton();
    Builder.UnCompiledNode<Object>[] newNodes = fst.compiled.nodes.clone();
    Comparator<BytesRef> comparator = fst.bytesReader.getComparator();
    newFst.setFST(new Builder<>(FST.INPUT_TYPE.BYTE2, outputs).compile(newFst.inputIterator(), weights, newNodes.length, 0, true, false, weights.getNoOutput(), comparator, true).getFST());

    // Add states to the new FST
    int nodeCount = 0;
    for (Builder.UnCompiledNode<Object> oldNode : newNodes) {
        if (oldNode == null) {
            continue;
        }
        // Create a copy of the old node
        Builder.Node<Object> newNode = new Builder.Node<>(++nodeCount, oldNode.inputCount, oldNode.output, oldNode.target);

        // Add transitions to the new node
        for (int arcIndex = 0; arcIndex < oldNode.numArcs(); arcIndex++) {
            Builder.Arc<Object> oldArc = oldNode.arc(arcIndex);
            // Create a copy of the old arc
            int newTarget = oldArc.target();
            BytesRef newInput = new BytesRef(oldArc.label().length);
            newInput.copyBytes(oldArc.label());
            newNode.addArc(new Builder.Arc<>(newInput, oldArc.output(), oldArc.nextFinalOutput(), newTarget));
        }

        // Add final output if it exists
        if (oldNode.isFinal()) {
            newNode.isFinal = true;
            newNode.nextFinalOutput = oldNode.nextFinalOutput;
        }

        // Add the new node to the FST
        newFst.addNode(newNode);
    }

    newFst.finish();

    return newFst;
}
