import java.util.Vector;
import sun.misc.Unsafe;

public class OffHeapAllocator {

    private static final Unsafe unsafe = Unsafe.getUnsafe();
    private static final int OBJECT_HEADER_SIZE = 16;
    private static final int INT_SIZE_IN_BYTES = 4;

    public static Vector allocateOffHeapColumns(int capacity) {
        long vectorSize = (long) capacity * INT_SIZE_IN_BYTES;
        long vectorAddress = unsafe.allocateMemory(vectorSize);
        Vector columns = new Vector(capacity);

        for (int i = 0; i < capacity; i++) {
            long columnAddress = unsafe.allocateMemory(vectorSize);
            unsafe.putAddress(vectorAddress + (i * OBJECT_HEADER_SIZE), columnAddress);
            columns.add(columnAddress);
        }

        return columns;
    }
}
