public static boolean checkBinaryOperator(BinaryOperator op, Traversal t, Node n) throws Exception {
    if (op == null || t == null || n == null) {
        throw new IllegalArgumentException("Invalid arguments");
    }

    Type left = n.getLeft().getType();
    Type right = n.getRight().getType();

    // Check if both operands have the same type
    if (!left.equals(right)) {
        t.error("Operands have different types");
        return false;
    }

    // Apply type-specific checks based on operator
    switch (op) {
        case ADD:
            if (!(left instanceof IntType || left instanceof RealType)) {
                t.error("Addition is only defined for integer and real types");
                return false;
            }
            break;
        case SUBTRACT:
            if (!(left instanceof IntType || left instanceof RealType)) {
                t.error("Subtraction is only defined for integer and real types");
                return false;
            }
            break;
        case MULTIPLY:
            if (!(left instanceof IntType || left instanceof RealType)) {
                t.error("Multiplication is only defined for integer and real types");
                return false;
            }
            break;
        case DIVIDE:
            if (!(left instanceof IntType || left instanceof RealType)) {
                t.error("Division is only defined for integer and real types");
                return false;
            }
            if (right instanceof IntType && (int) n.getRight().getValue() == 0) {
                t.error("Division by zero");
                return false;
            }
            break;
        case ASSIGN:
            if (!(left instanceof IntType || left instanceof RealType || left instanceof BooleanType)) {
                t.error("Assignment is only defined for integer, real, and boolean types");
                return false;
            }
            break;
        case AND:
            if (!(left instanceof BooleanType)) {
                t.error("Logical and is only defined for boolean types");
                return false;
            }
            break;
        case OR:
            if (!(left instanceof BooleanType)) {
                t.error("Logical or is only defined for boolean types");
                return false;
            }
            break;
        case NOT:
            if (!(left instanceof BooleanType)) {
                t.error("Logical not is only defined for boolean types");
                return false;
            }
            break;
        default:
            t.error("Invalid operator");
            return false;
    }

    return true;
}
