public static boolean allDiagonalElementsPositive(double[][] a) {
    int rows = a.length;
    int cols = a[0].length;
    if(rows != cols) {
        throw new IllegalArgumentException("Input matrix is not square.");
    }
    for (int i = 0; i < rows; i++) {
        if (a[i][i] <= 0) {
            return false;
        }
    }
    return true;
}
