public static int reverseFloatArraySearch(float[] floatArray, float value) {
    int low = 0;
    int high = floatArray.length - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (floatArray[mid] == value) {
            return mid;
        } else if (floatArray[mid] > value) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return -1;
}
