public double calculateVarianceForXbar(List<Double> sampleDataCollection, double populationM, double Nbar) {
  double sum = 0.0;
  for (Double x : sampleDataCollection) {
    sum += Math.pow(x - populationM, 2);
  }
  return sum / (Nbar - 1);
}
