public void traverseInheritanceGraph(ClassDescriptor start, InheritanceGraphVisitor visitor) 
        throws ClassNotFoundException {
    Class<?> clazz = Class.forName(start.getClassName());
    visitor.visit(clazz);
    Class<?> superClass = clazz.getSuperclass();
    if (superClass != null) {
        ClassDescriptor superClassDescriptor = new ClassDescriptor(superClass.getName());
        traverseInheritanceGraph(superClassDescriptor, visitor);
    }
    for (Class<?> superInterface : clazz.getInterfaces()) {
        ClassDescriptor superInterfaceDescriptor = new ClassDescriptor(superInterface.getName());
        traverseInheritanceGraph(superInterfaceDescriptor, visitor);
    }
}
