public static double kendallTau(int[] x, int[] y) {
    int n = x.length;
    int concordant = 0, discordant = 0;
    for (int i = 0; i < n - 1; i++) {
        for (int j = i + 1; j < n; j++) {
            if ((x[i] < x[j] && y[i] < y[j]) || (x[i] > x[j] && y[i] > y[j])) {
                concordant++;
            } else if ((x[i] < x[j] && y[i] > y[j]) || (x[i] > x[j] && y[i] < y[j])) {
                discordant++;
            }
        }
    }
    return (double)(concordant - discordant) / (double)(n * (n - 1) / 2);
}
