public static double sumOfSquaredDifferences(List<Double> dataSet) throws EmptyDataSetException {
    if (dataSet.isEmpty()) {
        throw new EmptyDataSetException("Data set cannot be empty");
    }
    double sum = 0;
    double mean = calculateMean(dataSet);
    for (double d : dataSet) {
        sum += Math.pow(d - mean, 2);
    }
    return sum;
}

private static double calculateMean(List<Double> dataSet) throws EmptyDataSetException {
    if (dataSet.isEmpty()) {
        throw new EmptyDataSetException("Data set cannot be empty");
    }
    double sum = 0;
    for (double d : dataSet) {
        sum += d;
    }
    return sum / dataSet.size();
}
