import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.HashMap;
import java.util.Map;

public Map<String, String> parseFile(String file) {
    Map<String, String> infoMap = new HashMap<>();
    try (BufferedReader br = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = br.readLine()) != null) {
            // Assuming that the separator between the key and the value is ":"
            String[] info = line.split(":");
            if (info.length == 2) {
                // Adding the key-value pair to the map
                infoMap.put(info[0].trim(), info[1].trim());
            }
        }
    } catch (IOException e) {
        // Printing the error
        System.err.println("Error while reading file: " + file + "! " + e.getMessage());
        // Returning null indicates an error
        return null;
    }
    // Returning the infoMap
    return infoMap;
}
