public String getForwardedIPAddress() {
    HttpServletRequest request = ((ServletRequestAttributes) RequestContextHolder.getRequestAttributes()).getRequest();

    String xForwardedForHeader = request.getHeader("X-Forwarded-For");
    if (xForwardedForHeader != null) {
        return xForwardedForHeader.split(",")[0];
    }

    String proxyClientIpHeader = request.getHeader("Proxy-Client-IP");
    if (proxyClientIpHeader != null) {
        return proxyClientIpHeader;
    }

    String wlProxyClientIpHeader = request.getHeader("WL-Proxy-Client-IP");
    if (wlProxyClientIpHeader != null) {
        return wlProxyClientIpHeader;
    }

    String httpXRealIpHeader = request.getHeader("HTTP_X_REAL_IP");
    if (httpXRealIpHeader != null) {
        return httpXRealIpHeader;
    }

    return request.getRemoteAddr();
}
