public int readChunkLength(InputStream inputStream) throws IOException {
    int chunkLength = 0;
    boolean chunkLengthStarted = false;

    // Read bytes until we find the chunk length
    while (true) {
        int b = inputStream.read();
        if (b == -1) {
            // End of input stream
            throw new EOFException("Unexpected end of input stream");
        }
        else if (chunkLengthStarted && b == '\r') {
            // Ignore '\r' characters
            continue;
        }
        else if (chunkLengthStarted && b == '\n') {
            // Found end of chunk length
            break;
        }
        else if (Character.isWhitespace(b)) {
            // Ignore whitespace characters before chunk length
            continue;
        }
        else {
            // Parse chunk length
            chunkLengthStarted = true;
            chunkLength = chunkLength * 16 + Character.digit(b, 16);
        }
    }

    return chunkLength;
}
