public double evaluate3DSimilarity(IAtomContainer query, IAtomContainer target) throws CDKException {
    if (!query.getAtomContainerSet().getAtomContainer(0).getProperties().containsKey("CDKConstants.NON_CONFORMER")) {
        // Generate 3D coordinates for the query molecule
        generate3DCoordinates(query);
    }
    if (!target.getAtomContainerSet().getAtomContainer(0).getProperties().containsKey("CDKConstants.NON_CONFORMER")) {
        // Generate 3D coordinates for the target molecule
        generate3DCoordinates(target);
    }
    // Check if both molecules have 3D coordinates
    if (query.getAtomContainerSet().getAtomContainer(0).getProperty("CDKConstants.NON_CONFORMER") == null ||
            target.getAtomContainerSet().getAtomContainer(0).getProperty("CDKConstants.NON_CONFORMER") == null) {
        throw new CDKException("Both molecules must have 3D coordinates");
    }
    // Create the similarity calculator
    IAtomContainerComparator calculator = new AtomContainerComparator("TanimotoSimilarity", MetricUtil.THREAD_COUNT);
    // Calculate the similarity between the molecules
    return calculator.getSimilarity(query, target);
}

private void generate3DCoordinates(IAtomContainer molecule) {
    try {
        // Convert the molecule to an MDL molfile
        StringWriter writer = new StringWriter();
        MolHandler molHandler = new MolHandler(molecule);
        molHandler.write(writer);
        // Run the Open Babel "gen3D" command on the molfile
        Process p = Runtime.getRuntime().exec("obabel -:" + writer.toString() + " -Omol -h -m --gen3D");
        // Read the output of the command (the molecule with 3D coordinates)
        MolImporter molImporter = new MolImporter(p.getInputStream());
        molecule = molImporter.read();
        molImporter.close();
        // Set the property indicating that the molecule has 3D coordinates
        molecule.getAtomContainerSet().getAtomContainer(0).setProperty("CDKConstants.NON_CONFORMER", true);
    } catch (Exception e) {
        e.printStackTrace();
    }
}
