import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;

public class SortedChunkIterator {

    public static Iterator<String> getSortedChunkIterator(List<String> sortedChunks) throws IOException {

        List<BufferedReader> readers = new ArrayList<>();
        List<String> currentLines = new ArrayList<>();
        for (String filename : sortedChunks) {
            BufferedReader reader = new BufferedReader(new FileReader(filename));
            readers.add(reader);
            currentLines.add(reader.readLine());
        }

        List<String> result = new ArrayList<>();

        while (!currentLines.isEmpty()) {
            int minIndex = Collections.min(getLineIndexes(currentLines));
            result.add(currentLines.get(minIndex));

            String newLine = readers.get(minIndex).readLine();
            if (newLine == null) {
                currentLines.remove(minIndex);
                readers.get(minIndex).close();
                readers.remove(minIndex);
                currentLines.remove(minIndex);
            } else {
                currentLines.set(minIndex, newLine);
            }
        }

        return result.iterator();
    }

    private static List<Integer> getLineIndexes(List<String> lines) {
        List<Integer> indexes = new ArrayList<>();
        for (int i = 0; i < lines.size(); i++) {
            if (lines.get(i) != null) {
                indexes.add(i);
            }
        }
        return indexes;
    }
}
