public static List<String> executeCommandAndWaitForExpectedPhrase(String command, String expectedPhrase) throws IOException, InterruptedException {
    List<String> consoleOutput = new ArrayList<>();
    Process process = Runtime.getRuntime().exec(command);
    BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));

    String line = "";
    while ((line = reader.readLine()) != null) {
        consoleOutput.add(line);
        if (line.contains(expectedPhrase)) {
            break;
        }
    }

    process.waitFor();
    process.destroy();
    return consoleOutput;
}
