import io.netty.handler.codec.http2.Http2Headers;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import com.linecorp.armeria.common.HttpHeaderNames;
import com.linecorp.armeria.common.HttpHeaders;

public class Http2ToArmeriaHeadersConverter {

    private static final Logger logger = LoggerFactory.getLogger(Http2ToArmeriaHeadersConverter.class);

    public static HttpHeaders convert(Http2Headers http2Headers) {
        HttpHeaders armeriaHeaders = HttpHeaders.of();
        http2Headers.forEach(header ->
                armeriaHeaders.set(HttpHeaderNames.of(header.getKey().toString()),
                        header.getValue().toString()));
        if (logger.isDebugEnabled()) {
            logger.debug("headers before conversion: {}", http2Headers);
            logger.debug("headers after conversion: {}", armeriaHeaders);
        }
        return armeriaHeaders;
    }
}
