import javax.xml.bind.DatatypeConverter;
import javax.xml.parsers.DocumentBuilderFactory;
import java.security.MessageDigest;

public static String calculateHashValue(String xml) throws Exception {
    String grantForms = null;
    try {
        grantForms = DocumentBuilderFactory.newInstance()
                .newDocumentBuilder()
                .parse(new ByteArrayInputStream(xml.getBytes()))
                .getElementsByTagName("grant:forms")
                .item(0)
                .getTextContent();
    } catch (Exception ex) {
        throw new Exception("Error parsing the XML: " + ex.getMessage());
    }

    MessageDigest md = MessageDigest.getInstance("SHA-1");
    md.update(grantForms.getBytes());
    byte[] digest = md.digest();

    return DatatypeConverter.printHexBinary(digest);
}
