public void unionDependencies(EntryInfo entryInfo) {
  List<String> cacheIds = entryInfo.getCacheIds();
  List<String> dataIds = entryInfo.getDataIds();
  List<String> templateNames = entryInfo.getTemplateNames();

  // code to check for duplicates and perform union

  // add unique cacheIds to dataIds list
  for (String cacheId : cacheIds) {
    if (!dataIds.contains(cacheId)) {
      dataIds.add(cacheId);
    }
  }

  // add unique templateNames to templates list
  for (String templateName : templateNames) {
    if (!templates.contains(templateName)) {
      templates.add(templateName);
    }
  }
}
