    public long slTTL(byte[] sessionKey, byte[] hashKey, byte[] listKey, byte[] value) {
        String sessionKeyStr = new String(sessionKey, StandardCharsets.UTF_8);
        String hashKeyStr = new String(hashKey, StandardCharsets.UTF_8);
        String listKeyStr = new String(listKey, StandardCharsets.UTF_8);
        String valueStr = new String(value, StandardCharsets.UTF_8);

        Jedis jedis = null;
        try {
            jedis = jedisPool.getResource();
            jedis.auth(password);

            String compositeKey = hashKeyStr + ":" + listKeyStr + ":" + valueStr;

            Long ttl = jedis.ttl(compositeKey);
            if (ttl != null && ttl > 0) {
                return ttl;
            }

            SessionData sessionData = getSessionData(sessionKeyStr, jedis);
            Map<String, List<String>> hashList = getOrCreateHashList(sessionData, hashKeyStr);

            long maxTTL = -1;
            for (String key : hashList.keySet()) {
                if (!key.equals(listKeyStr)) {
                    List<String> list = hashList.get(key);
                    for (String item : list) {
                        String itemCompositeKey = key + ":" + listKeyStr + ":" + item;
                        Long itemTTL = jedis.ttl(itemCompositeKey);
                        if (itemTTL != null) {
                            maxTTL = Math.max(maxTTL, itemTTL);
                        }
                    }
                }
            }

            if (maxTTL > 0) {
                return maxTTL;
            }

            return jedis.ttl(hashKeyStr);
        } finally {
            if (jedis != null) {
                jedis.close();
            }
        }
    }

    // ...
}
