    // establish connection to server
    Connection conn = establishConnection(server);
    if(conn == null) {
        throw new ConnectionNotAvailableException("No connection to server");
    }

    // send message to server
    conn.write(message);

    // wait for and receive reply from server
    byte[] reply = conn.read();

    // close connection
    conn.close();

    // return result
    return reply;
}

