    {
        Vector<BaseField> vParamList = new Vector<BaseField>();
        try   {
            if (this.lockOnDBTrxType(null, DBConstants.SELECT_TYPE, false))   
                this.unlockIfLocked(this.getRecord(), null);     

            this.setResultSet(null, DBConstants.SQL_SEEK_TYPE);
