            ResultSet resultSet = this.executeQuery(strRecordset, DBConstants.SQL_SEEK_TYPE, vParamList);
            this.setResultSet(resultSet, DBConstants.SQL_SEEK_TYPE);
            boolean more = resultSet.next();
            if (SHARE_STATEMENTS)
                m_iLastOrder = -1;       
