public void assertSubscriptionHasNoErrors(String msg, Subscription subscription) {
    List<Exception> errors = new ArrayList<>();
    if (subscription.getNotifyErrors() != null) {
        errors.addAll(subscription.getNotifyErrors());
    }
    if (subscription.getSubscriptionErrors() != null) {
        errors.addAll(subscription.getSubscriptionErrors());
    }
    if (!errors.isEmpty()) {
        StringBuilder exceptionMessage = new StringBuilder(msg + "\n");
        for (Exception error : errors) {
            exceptionMessage.append(error.getMessage()).append("\n");
        }
        throw new AssertionError(exceptionMessage.toString());
    }
}
