public static InputStream getResourceAsStream(ServletContext context, String path) throws ResourceNotFoundException {
    InputStream inputStream = context.getResourceAsStream(path);
    if (inputStream == null) {
        URL resourceURL = context.getResource(path);
        if (resourceURL == null) {
            throw new ResourceNotFoundException("Could not find resource: " + path);
        }
        inputStream = resourceURL.openStream();
    }
    return inputStream;
}
