public PolylineOptions buildOpenArcPath(LatLng center, LatLng start, LatLng end) {
    PolylineOptions options = new PolylineOptions();
    double radius = SphericalUtil.computeDistanceBetween(center, start);
    double startAngle = SphericalUtil.computeHeading(center, start);
    double endAngle = SphericalUtil.computeHeading(center, end);

    if (startAngle > endAngle) {
        endAngle += 360;
    }

    for (double angle = startAngle; angle <= endAngle; angle += 10) {
        double lat = center.latitude + radius * Math.sin(Math.toRadians(angle));
        double lng = center.longitude + radius * Math.cos(Math.toRadians(angle));
        options.add(new LatLng(lat, lng));
    }

    return options;
}
