public List<String> extractRoutes(Class<?> controllerClazz) {
    List<String> routes = new ArrayList<>();
    Annotation[] annotations = controllerClazz.getAnnotations();
    for (Annotation annotation : annotations) {
        if (annotation instanceof Route) {
            Route route = (Route) annotation;
            String[] values = route.value();
            for (String value : values) {
                routes.add(value);
            }
        }
    }
    if (routes.isEmpty()) {
        routes.add("");
    }
    return routes;
}
