public int findNearestCentroidIndex(double[] vector, double[][] centroids) {
    int nearestIndex = 0;
    double minDist = Double.MAX_VALUE;

    for (int i = 0; i < centroids.length; i++) {
        double dist = 0;
        for (int j = 0; j < vector.length; j++) {
            double diff = vector[j] - centroids[i][j];
            dist += diff * diff;
        }
        if (dist < minDist) {
            nearestIndex = i;
            minDist = dist;
        }
    }

    return nearestIndex;
}
