public void printResultSet(ResultSet resultSet) throws SQLException {
    ResultSetMetaData rsmd = resultSet.getMetaData();
    int numColumns = rsmd.getColumnCount();
    int[] columnWidths = new int[numColumns];

    for (int i = 1; i <= numColumns; i++) {
        columnWidths[i - 1] = Math.max(rsmd.getColumnDisplaySize(i), rsmd.getColumnName(i).length());
    }

    String rowFormat = "";

    for (int width : columnWidths) {
        rowFormat += "%-" + (width + 1) + "s";
    }

    rowFormat += "%n";

    System.out.printf(rowFormat, (Object[]) getColumnNames(rsmd));

    while (resultSet.next()) {
        Object[] rowData = new Object[numColumns];

        for (int i = 1; i <= numColumns; i++) {
            rowData[i - 1] = resultSet.getString(i);
        }

        System.out.printf(rowFormat, rowData);
    }
}

private String[] getColumnNames(ResultSetMetaData rsmd) throws SQLException {
    int numColumns = rsmd.getColumnCount();
    String[] columnNames = new String[numColumns];

    for (int i = 1; i <= numColumns; i++) {
        columnNames[i - 1] = rsmd.getColumnName(i);
    }

    return columnNames;
}
