public static double[][] reshapeImageData(double[][] imageData, int height, int width) {
    int paddedHeight = imageData.length;
    int paddedWidth = imageData[0].length;
    double[][] reshapedData = new double[height][width];

    int rowPadding = (paddedHeight - height) / 2;
    int colPadding = (paddedWidth - width) / 2;

    for (int i = 0; i < height; i++) {
        for (int j = 0; j < width; j++) {
            reshapedData[i][j] = imageData[i + rowPadding][j + colPadding];
        }
    }

    return reshapedData;
}
