public Connection getConnection(Object dataSource, Properties props) throws SQLException {
    Connection con = null;
    if (dataSource instanceof String) {
        try {
            con = getDataSource((String) dataSource).getConnection();
        } catch (NamingException e) {
            con = getDriverManagerConnection((String) dataSource, props);
        }
    } else if (dataSource instanceof DataSource) {
        con = ((DataSource) dataSource).getConnection();
    } else {
        throw new IllegalArgumentException("dataSource is not a String or DataSource object");
    }
    return con;
}

private DataSource getDataSource(String jndiName) throws NamingException {
    Context ctx = new InitialContext();
    return (DataSource) ctx.lookup(jndiName);
}

private Connection getDriverManagerConnection(String str, Properties props) throws SQLException {
    String url = str;
    String user = null;
    String password = null;

    int x = str.indexOf(';');
    if (x > 0) {
        url = str.substring(0, x);
        String[] paramList = str.substring(x + 1).split(";");
        for (String param : paramList) {
            String[] keyValue = param.split("=");
            if (keyValue.length == 2) {
                String key = keyValue[0].trim();
                String value = keyValue[1].trim();
                if (key.equalsIgnoreCase("user")) {
                    user = value;
                } else if (key.equalsIgnoreCase("password")) {
                    password = value;
                } else {
                    props.setProperty(key, value);
                }
            }
        }
    }
    return DriverManager.getConnection(url, user, password);
}
