import java.security.*;
import javax.crypto.*;
import javax.crypto.spec.*;

public PublicKey convertDnskeyToPublicKey(DNSKEY dnskey) {

   byte[] publicKeyBytes = dnskey.getPublicKey();

   try {
        KeyFactory kf = KeyFactory.getInstance("RSA"); // or "EC" or whatever

        // get the modulus and exponent from the publicKeyBytes
        BigInteger modulus = new BigInteger(1, Arrays.copyOfRange(publicKeyBytes,2, 2 + publicKeyBytes[0]));
        BigInteger exponent = new BigInteger(1, Arrays.copyOfRange(publicKeyBytes,2 + publicKeyBytes[0], 2 + publicKeyBytes[0] + publicKeyBytes[2 + publicKeyBytes[0]]));

        // create the public key specification
        RSAPublicKeySpec pubSpec = new RSAPublicKeySpec(modulus, exponent);

        // generate the public key
        PublicKey publicKey = kf.generatePublic(pubSpec);

        return publicKey;
    } catch (NoSuchAlgorithmException | InvalidKeySpecException e) {
        throw new IllegalArgumentException("Invalid DNSKEY record");
    }
}
