public class Matrix3dc implements org.joml.Matrix3dc {

    // constructor and other methods implementation

    /* (non-Javadoc)
     * @see org.joml.Matrix3dc#transform(org.joml.Vector3fc, org.joml.Vector3f)
     */
    @Override
    public Vector3f transform(Vector3fc v, Vector3f dest) {
        float x, y, z;
        x = (m00 * v.x()) + (m10 * v.y()) + (m20 * v.z());
        y = (m01 * v.x()) + (m11 * v.y()) + (m21 * v.z());
        z = (m02 * v.x()) + (m12 * v.y()) + (m22 * v.z());
        return dest.set(x, y, z);
    }
}
