import java.util.ArrayList;

public ArrayList searchForKeys(List<String> keys) throws DRUMSException, IOException {
    ArrayList results = new ArrayList();
    // Loop through all buckets
    for (Bucket bucket : allBuckets) {
        // Check if bucket contains any key from the keys list
        for (String key : keys) {
            if (bucket.contains(key)) {
                results.add(bucket.get(key));
            }
        }
    }
    return results;
