public BitcointoyouPublicTrade[] listPublicTrades(String currencyPair, long tradeTimestamp, long minTradeId) throws IOException {
    String baseUrl = "https://api.bitcointoyou.com/api/v3";
    String url = baseUrl + "/public/trades/" + currencyPair + "?timestamp=" + tradeTimestamp + "&tid=" + minTradeId;

    HttpURLConnection connection = (HttpURLConnection) new URL(url).openConnection();
    connection.setRequestMethod("GET");
    int statusCode = connection.getResponseCode();
    if (statusCode == 200) {
        InputStream inputStream = connection.getInputStream();
        BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream));
        StringBuilder response = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            response.append(line);
        }
        reader.close();
        inputStream.close();
        connection.disconnect();
        JSONArray jsonArray = new JSONArray(response.toString());
        BitcointoyouPublicTrade[] trades = new BitcointoyouPublicTrade[jsonArray.length()];
        for (int i = 0; i < jsonArray.length(); i++) {
            JSONObject jsonObject = jsonArray.getJSONObject(i);
            BitcointoyouPublicTrade trade = new BitcointoyouPublicTrade();
            trade.setTradeId(jsonObject.getLong("tid"));
            trade.setTimestamp(jsonObject.getLong("date"));
            trade.setPrice(jsonObject.getDouble("price"));
            trade.setAmount(jsonObject.getDouble("amount"));
            trade.setSide(jsonObject.getString("type"));
            trades[i] = trade;
        }
        return trades;
    } else {
        throw new IOException("Failed to retrieve trades: " + statusCode);
    }
}
