public Observable<NetworkInterfaceInner> updateNetworkInterfaceTags(String resourceGroupName, String networkInterfaceName, Map<String, String> tags) throws IllegalArgumentException {
  // validate parameters
  if (resourceGroupName == null || resourceGroupName.isEmpty() || networkInterfaceName == null || networkInterfaceName.isEmpty() || tags == null || tags.isEmpty()) {
    throw new IllegalArgumentException("Invalid parameters");
  }

