    NetworkInterfaceInner networkInterface = inner.get(resourceGroupName, networkInterfaceName);
    networkInterface.setTags(tags);
    inner.createOrUpdate(resourceGroupName, networkInterfaceName, networkInterface);
    return networkInterface;
  });
}
