public List<Node> getChildNodesByNamespaceAndName(Node parentNode, String namespace, String name) {
    List<Node> matchingChildNodes = new ArrayList<>();
    NodeList childNodes = parentNode.getChildNodes();
    for (int i = 0; i < childNodes.getLength(); i++) {
        Node childNode = childNodes.item(i);
        if (childNode.getLocalName().equals(name) && childNode.getNamespaceURI().equals(namespace)) {
            matchingChildNodes.add(childNode);
        }
    }
    return Collections.unmodifiableList(matchingChildNodes);
}
