public static void pairwiseDistance(double[][] x, boolean squared, boolean half, double[][] dist) {
    int n = x.length;
    for (int i = 0; i < n; i++) {
        for (int j = half ? i + 1 : 0; j < n; j++) {
            double d = 0;
            for (int k = 0; k < x[0].length; k++) {
                double temp = x[i][k] - x[j][k];
                d += temp * temp;
            }
            if (!squared) {
                d = Math.sqrt(d);
            }
            dist[i][j] = d;
            if (half) {
                dist[j][i] = d;
            }
        }
    }
}
