/**
 * Returns a list of all the upstream elements of the given elements.
 * @param elements the list of elements to find the upstream elements for
 * @param existingElements the list of elements already found in the recursion 
 * @return a list of all the upstream elements of the given elements
 */
@Override
public List<Element> getAllUpstreamElements(List<Element> elements, List<Element> existingElements) {
    List<Element> upstreamElements = new ArrayList<>();
    for (Element element : elements) {
        if (!existingElements.contains(element)) {
            existingElements.add(element);
            List<Element> connectedElements = element.getConnectedElements();
            upstreamElements.addAll(getAllUpstreamElements(connectedElements, existingElements));
        }
    }
    return upstreamElements;
}
