		toasts.add(toast);
		toast.setToastManager(this);
		toast.fadeIn();
		toastMainTable.pack();
		root.addActor(toastMainTable);
		updateToastsPositions();
		if (timeSec > 0) {
			Timer.Task fadeOutTask = new Timer.Task() {
				@Override
