public void replaceCalColorSpaces(PDFDocument document) {
    // Get list of pages in the document
    List<PDFPage> pages = document.getPages();

    // Loop through each page
    for (PDFPage page : pages) {
        // Get the page contents
        List<PDFObject> contents = page.getContents();

        // Loop through each content object
        for (PDFObject content : contents) {
            // Check if the content object represents a color space
            if (content instanceof PDFDictionary && ((PDFDictionary) content).containsKey("ColorSpace")) {
                PDFObject colorSpaceObj = ((PDFDictionary) content).get("ColorSpace");

                // Check if the color space is CalRGB or CalGray
                if (colorSpaceObj instanceof PDFName) {
                    PDFName colorSpaceName = (PDFName) colorSpaceObj;
                    if (colorSpaceName.getValue().equals("CalRGB") || colorSpaceName.getValue().equals("CalGray")) {
                        // Replace the color space with DeviceRGB or DeviceGray
                        ((PDFDictionary) content).put("ColorSpace", new PDFName("Device" + colorSpaceName.getValue().substring(3)));
                    }
                } else if (colorSpaceObj instanceof PDFArray) { // Check if the color space is an array
                    PDFArray colorSpaceArray = (PDFArray) colorSpaceObj;

                    // Check if the first element of the array is CalRGB or CalGray
                    if (colorSpaceArray.get(0) instanceof PDFName) {
                        PDFName colorSpaceName = (PDFName) colorSpaceArray.get(0);
                        if (colorSpaceName.getValue().equals("CalRGB") || colorSpaceName.getValue().equals("CalGray")) {
                            // Replace the first element of the array with DeviceRGB or DeviceGray
                            colorSpaceArray.set(0, new PDFName("Device" + colorSpaceName.getValue().substring(3)));
                        }
                    }
                }
            }
        }
    }
}
