public int findReorderingGroup(int primaryWeight, int[][] groups) {
    int firstScript = -1;
    for (int i = 0; i < groups.length; i++) {
        int[] group = groups[i];
        if (primaryWeight >= group[0] && primaryWeight <= group[1]) {
            firstScript = group[2];
            break;
        }
    }
    return firstScript;
}
