public class CachedModelChecker implements ModelChecker {
    private Map<List<Object>, Object> cache = new HashMap<>();
    private ModelChecker modelChecker;

    public CachedModelChecker(ModelChecker modelChecker) {
        this.modelChecker = modelChecker;
    }

    @Override
    public Object findCounterExample(Object model, Collection<Object> properties, Object property) {
        List<Object> key = Arrays.asList(model, properties, property);
        if (cache.containsKey(key)) {
            return cache.get(key);
        } else {
            Object result = modelChecker.findCounterExample(model, properties, property);
            cache.put(key, result);
            return result;
        }
    }
}
