public static <I, O> MealyMachine<?, I, ?, O> inferMealyMachine(StateLocalInputSUL<I, O> sul, MealyMembershipOracle<I, O> oracle) throws MembershipException, IOException {
    try {
        HypothesisMealy<I, O> hypothesis = new ExtensibleHypothesisMealy<>(oracle);
        Teacher<I, Word<O>> teacher = new SULSymbolQueryOracle<>(sul);
        LearnerAngluinMealy<I, O> learner = new LearnerAngluinMealy<>(teacher, hypothesis);

        // Refine hypothesis using observation table learning
        while (!learner.isConjectureValid()) {
            learner.refineHypothesis();
        }

        return learner.getConjecture();
    } catch (HypothesisConstructionException e) {
        throw new RuntimeException(e);
    }
} 
