public void serializeRowToPagesWithoutRowLength(byte[] row, byte[] output, int offset, int pageSize) {
    int pageCount = (int) Math.ceil((double) row.length / pageSize);
    int rowIndex = 0;
    for (int i = 0; i < pageCount; i++) {
        int pageOffset = offset + (i * pageSize);
        int pageLength = Math.min(pageSize, row.length - rowIndex);
        System.arraycopy(row, rowIndex, output, pageOffset, pageLength);
        rowIndex += pageLength;
    }
}
