import java.io.IOException;
import org.apache.hadoop.conf.Configuration;
import org.apache.hadoop.hbase.HBaseConfiguration;
import org.apache.hadoop.hbase.TableName;
import org.apache.hadoop.hbase.client.Admin;
import org.apache.hadoop.hbase.client.ColumnFamilyDescriptor;
import org.apache.hadoop.hbase.client.ColumnFamilyDescriptorBuilder;
import org.apache.hadoop.hbase.client.Table;
import org.apache.hadoop.hbase.client.TableDescriptor;
import org.apache.hadoop.hbase.client.TableDescriptorBuilder;
import org.apache.hadoop.hbase.util.Bytes;

public class ModifyColumnFamilyRule {
   public static void modifyRule(String tableName, String colFamilyName, int timeToLive) throws IOException {
      Configuration config = HBaseConfiguration.create();
      try (Admin admin = ConnectionFactory.createConnection(config).getAdmin()) {
         TableName table = TableName.valueOf(tableName);
         if (admin.tableExists(table)) {
            TableDescriptor tableDesc = admin.getDescriptor(table);
            ColumnFamilyDescriptor colFamilyDesc = tableDesc.getColumnFamily(Bytes.toBytes(colFamilyName));
            ColumnFamilyDescriptor newColFamilyDesc = ColumnFamilyDescriptorBuilder.newBuilder(colFamilyDesc)
               .setTimeToLive(timeToLive)
               .build();
            TableDescriptor newTableDesc = TableDescriptorBuilder.newBuilder(tableDesc)
               .removeColumnFamily(Bytes.toBytes(colFamilyName))
               .setColumnFamily(newColFamilyDesc)
               .build();
            admin.modifyTable(newTableDesc);
         }
      }
   }
}
