public Node findSingleChildNode(Node node, String ruleName) {
    if (node == null) {
        return null;
    }
    for (Node child : node.getChildNodes()) {
        int childCount = countFirstChildNodes(child);
        if (childCount == 1 && child.getNodeName().equals(ruleName)) {
            return child;
        } else {
            Node matchedNode = findSingleChildNode(child, ruleName);
            if (matchedNode != null) {
                return matchedNode;
            }
        }
    }
    return null;
}

private int countFirstChildNodes(Node node) {
    int count = 0;
    NodeList childNodes = node.getChildNodes();
    for (int i = 0; i < childNodes.getLength(); i++) {
        if (childNodes.item(i).getNodeType() == Node.ELEMENT_NODE) {
            count++;
            if (count > 1) {
                return count;
            }
        }
    }
    return count;
}
