public class Parser {
  public static Class<?> parse(String text) throws Exception {
    // Use Java Compiler API to parse the text into a Java class
    JavaCompiler compiler = ToolProvider.getSystemJavaCompiler();
    StandardJavaFileManager fileManager = compiler.getStandardFileManager(null, null, null);
    StringSourceFileObject sourceFile = new StringSourceFileObject("Main", text);
    ArrayList<JavaFileObject> compilationUnits = new ArrayList<>();
    compilationUnits.add(sourceFile);
    Iterable<? extends JavaFileObject> fileObjects = compilationUnits;
    DiagnosticCollector<JavaFileObject> diagnosticCollector = new DiagnosticCollector<>();
    CompilationTask task = compiler.getTask(null, fileManager, diagnosticCollector, null, null, fileObjects);
    boolean success = task.call();
    if (!success) {
      StringBuilder errorMessage = new StringBuilder();
      for (Diagnostic<? extends JavaFileObject> diagnostic : diagnosticCollector.getDiagnostics()) {
        errorMessage.append(diagnostic.getMessage(null)).append("\n");
      }
      throw new Exception("Compilation error: " + errorMessage.toString());
    }
    fileManager.close();
    // Find and return the main class from parsed Java classes
    ClassLoader classLoader = Thread.currentThread().getContextClassLoader();
    for (JavaFileObject fileObject : compilationUnits) {
      if (fileObject.getKind() == JavaFileObject.Kind.CLASS) {
        String className = fileObject.getName().split("\\.")[0];
        Class<?> clazz = classLoader.loadClass(className);
        if (clazz.getAnnotation(MainClass.class) != null) {
          return clazz;
        }
      }
    }
    throw new Exception("Main class not found");
  }
}
