public class BitVectorIndexer {

    // assume this variable is the underlying bit vector
    private BitVector bitVector;

    public BitVectorIndexer(BitVector bitVector) {
        this.bitVector = bitVector;
    }

    public BitVector getBitVectorAtIndex() {
        // create a new BitVector object as a copy of the underlying bit vector
        BitVector copy = new BitVector(bitVector.size());
        for (int i = 0; i < bitVector.size(); i++) {
            if (bitVector.get(i)) {
                copy.set(i);
            }
        }
        return copy;
    }

}
