public static double doSecantIteration(int n) {
    double x0 = 0; // initial guess for x0
    double x1 = 1; // initial guess for x1

    for (int i = 0; i < n; i++) {
        double fx0 = f(x0); // evaluate function at x0
        double fx1 = f(x1); // evaluate function at x1

        double x2 = x1 - (fx1 * (x1 - x0)) / (fx1 - fx0); // compute root using secant method

        x0 = x1; // update guesses
        x1 = x2;
    }

    return x1; // return final guess
}

// example function f(x)
public static double f(double x) {
    return x * x - 4;
}
