public Node replaceNamesWithExpressionTrees(Node node, Node parent, Map<String, Node> replacements) {
    if (node instanceof NameNode && replacements.containsKey(((NameNode) node).getName())) {
        Node replacement = replacements.get(((NameNode) node).getName());
        if (parent != null) {
            if (parent.getLeftChild() == node) {
                parent.setLeftChild(replacement);
            } else {
                parent.setRightChild(replacement);
            }
        }
        node = replacement;
    } else {
        if (node.getLeftChild() != null) {
            replaceNamesWithExpressionTrees(node.getLeftChild(), node, replacements);
        }
        if (node.getRightChild() != null) {
            replaceNamesWithExpressionTrees(node.getRightChild(), node, replacements);
        }
    }
    return node;
}
