import com.nomagic.magicdraw.core.Application;
import com.nomagic.magicdraw.core.project.Project;
import com.nomagic.magicdraw.uml.symbols.DiagramPresentationElement;
import com.nomagic.magicdraw.uml.symbols.PresentationElement;
import java.io.PrintWriter;
import java.util.Collection;

public void writeDynamicViewsAsWebSeqDiagrams(Project project) {

    Collection<DiagramPresentationElement> dynamicViews = project.getActiveDiagram().getDiagramSheet().getPresentationElementsOfType(DiagramPresentationElement.class, true);

    for (DiagramPresentationElement dynamicView : dynamicViews) {
        if (dynamicView.getDiagram().isDynamic()) {
            PrintWriter writer = new PrintWriter(System.out);
            writer.println("@startuml");
            for (PresentationElement<?> pe : dynamicView.getPresentationElements()) {
                if (pe instanceof LifelineView) {
                    LifelineView lifeline = (LifelineView) pe;
                    writer.println(lifeline.toWebSequenceDiagramString());
                }
            }
            writer.println("@enduml");
            writer.flush();
        }
    }
}
