public String getEntityName(EntityDataModel entityDataModel, String entityTypeName) throws ODataEdmException {
    for (EntitySet entitySet : entityDataModel.getEntitySets()) {
        if (entitySet.getEntityType().getName().equals(entityTypeName)) {
            return entitySet.getName();
        }
    }
    for (Singleton singleton : entityDataModel.getSingletons()) {
        if (singleton.getEntityType().getName().equals(entityTypeName)) {
            return singleton.getName();
        }
    }
    throw new ODataEdmException("Unable to find entity name in entity data model.");
}
