import java.util.Random;

public static String generateRandomString(int length, char min, char max) {
    Random random = new Random();
    StringBuilder sb = new StringBuilder();
    int diff = max - min + 1;

    for (int i = 0; i < length; i++) {
        char c = (char)(random.nextInt(diff) + min);
        sb.append(c);
    }

    return sb.toString();
}
