public static String getShortClassName(Class<?> c) throws NullPointerException {
   if(c == null){
      throw new NullPointerException();
   }
   String fullName = c.getName();
   int lastIndex = fullName.lastIndexOf(".");
   if(lastIndex == -1 || (lastIndex == 0 && fullName.charAt(0) == '$')){
      return fullName;
   } else {
      int startIndex = fullName.lastIndexOf(".", lastIndex-1)+1;
      int endIndex = (fullName.charAt(lastIndex-1) == '$') ? lastIndex-1 : lastIndex;
      return fullName.substring(startIndex, endIndex);
   }
}
