public byte[] encryptDecryptRSA(byte[] input, int offset, int len, boolean decrypt) 
        throws InvalidAlgorithmParameterException, InvalidKeyException, BadPaddingException, IllegalBlockSizeException {

    try {
        Cipher cipher = Cipher.getInstance("RSA");
        Key key;
        if(decrypt) {
            key = privateKey; // privateKey is a private key object of type 'Key'
            cipher.init(Cipher.DECRYPT_MODE, key);
        } else {
            key = publicKey; // publicKey is a public key object of type 'Key'
            cipher.init(Cipher.ENCRYPT_MODE, key);
        }
        return cipher.doFinal(input, offset, len);

    } catch(NoSuchAlgorithmException | NoSuchPaddingException e) {
        // handle exception
    }

    return null;
}
