public static <T> Function<String, T> getConverter(Class<T> type) {
    ServiceLoader<ValueConverter<T>> loader = ServiceLoader.load(ValueConverter.class);
    for (ValueConverter<T> converter : loader) {
        if (converter.getType().equals(type)) {
            return converter::convert;
        }
    }
    throw new NoSuchElementException("No suitable converter found for type: " + type.getName());
}
