public static void checkAccess(ClassLoader ccl, Class<?>... interfaces) throws SecurityException {
     for (Class<?> iface : interfaces) {
         Package ifacePackage = iface.getPackage();
         if (ifacePackage != null && isRestrictedPackage(ifacePackage, ccl)) {
             throw new SecurityException("Access denied to interface " + iface.getName());
         }
     }
}

private static boolean isRestrictedPackage(Package ifacePackage, ClassLoader ccl) {
     String packageName = ifacePackage.getName();
     if (packageName.startsWith("java.")) {
         return true;
     }
     if (packageName.startsWith("javax.")) {
         return true;
     }
     if (ccl != null) {
         String[] restrictedPackages = getRestrictedPackages(ccl);
         for (String restrictedPackage : restrictedPackages) {
             if (packageName.startsWith(restrictedPackage)) {
                 return true;
             }
         }
     }
     return false;
}

private static String[] getRestrictedPackages(ClassLoader ccl) {
     // return the list of restricted packages
     return new String[] {"com.example.restricted", "com.anotherexample.restricted"};
}
