public static Mat labeledToBinary(Mat labelImage, Mat binaryImage) {
    Core.compare(labelImage, Scalar.all(0), binaryImage, Core.CMP_NE);
    Core.normalize(binaryImage, binaryImage, 0, 255, Core.NORM_MINMAX);
    binaryImage = binaryImage.reshape(1, binaryImage.cols() * binaryImage.rows());
    Core.compare(binaryImage, Scalar.all(0), binaryImage, Core.CMP_NE);
    binaryImage = binaryImage.reshape(1, labelImage.size().height);
    return binaryImage;
}
