import java.io.File;

public static void deleteFileOrDirectory(String path) {
    File fileOrDir = new File(path);
    if (!fileOrDir.exists()) {
        return;
    }
    if (fileOrDir.isDirectory()) {
        for (File child : fileOrDir.listFiles()) {
            deleteFileOrDirectory(child.getPath());
        }
    }
    fileOrDir.delete();
}
