class SpliteratorWithCloseHandler<T> implements Spliterator<T> {

    private final Spliterator<T> spliterator;
    private final Runnable onClose;

    SpliteratorWithCloseHandler(Spliterator<T> spliterator, Runnable onClose) {
        this.spliterator = spliterator;
        this.onClose = onClose;
    }

    @Override
    public boolean tryAdvance(Consumer<? super T> action) {
        return spliterator.tryAdvance(action);
    }

    @Override
    public Spliterator<T> trySplit() {
        Spliterator<T> split = spliterator.trySplit();
        if (split != null) {
            return new SpliteratorWithCloseHandler<>(split, onClose);
        }
        return null;
    }

    @Override
    public long estimateSize() {
        return spliterator.estimateSize();
    }

    @Override
    public int characteristics() {
        return spliterator.characteristics();
    }

    @Override
    public void forEachRemaining(Consumer<? super T> action) {
        spliterator.forEachRemaining(action);
    }

    @Override
    public void forEachRemaining(Consumer<? super T> action, Runnable onAfterCompletion) {
        spliterator.forEachRemaining(action);
        onAfterCompletion.run();
        onClose.run();
    }
}
