	String p2 = path2.replace('\\', '/');
	if (p1.endsWith("/") && !p2.endsWith("/")) p2 = p2 + "/";
	else if (p2.endsWith("/") && !p1.endsWith("/")) p1 = p1 + "/";
	return p1.equalsIgnoreCase(p2);
