public static double crossEntropy(Counter<String> from, Counter<String> to) {
    if(from == null || to == null || from.isEmpty() || to.isEmpty()) {
        throw new IllegalArgumentException("Counters cannot be null or empty");
    }

    double sum = 0.0;
    double total = from.totalCount();

    for(Map.Entry<String, Double> entry : to.entrySet()) {
        String key = entry.getKey();
        double value = entry.getValue();

        if(value < 0.0) {
            throw new IllegalArgumentException("Count cannot be negative");
        }

        double fromProb = from.getCount(key) / total;
        sum += value * Math.log(fromProb);
    }

    return -1.0 * sum;
}
