public static List<String> splitHourRange(String hourRange) {
    List<String> result = new ArrayList<>();
    String[] hours = hourRange.split("-");
    int start = Integer.parseInt(hours[0].split(":")[0]);
    int end = Integer.parseInt(hours[1].split(":")[0]);

    if (start > end) {
        result.add(hours[0] + "-" + "23:59");
        result.add("00:00" + "-" + hours[1]);
    } else {
        result.add(hourRange);
    }
    return result;
}
