public void invertMatrix(double[][] matrix) {
    int n = matrix.length;
    double[][] identity = new double[n][n];

    // Creating an identity matrix
    for(int i=0; i<n; i++) {
        for(int j=0; j<n; j++) {
            if(i == j) {
                identity[i][j] = 1;
            }
        }
    }

    // Solving for against the identity matrix
    for(int i=0; i<n; i++) {
        double c = matrix[i][i];
        for(int j=0; j<n; j++) {
            matrix[i][j] /= c;
            identity[i][j] /= c;
        }
        for(int j=0; j<n; j++) {
            if(i != j) {
                double factor = matrix[j][i];
                for(int k=0; k<n; k++) {
                    matrix[j][k] -= factor * matrix[i][k];
                    identity[j][k] -= factor * identity[i][k];
                }
            }

        }
    }

    // Saving the inverted matrix
    for(int i=0; i<n; i++) {
        for(int j=0; j<n; j++) {
            A_inv[i][j] = identity[i][j];
        }
    }
}
