import java.io.BufferedWriter;
import java.io.IOException;
import java.io.Writer;
import java.util.List;

public void writeSingleFrameToWriter(Molecule mol, Writer writer) throws IOException {
    BufferedWriter out = new BufferedWriter(writer);
    List<Atom> atoms = mol.getAtoms();
    List<Vector3D> positions = mol.getPositions();

    out.write(Integer.toString(atoms.size()));
    out.newLine();
    out.write("Generated by myXYZwriter");
    out.newLine();

    for (int i = 0; i < atoms.size(); i++) {
        Atom atom = atoms.get(i);
        Vector3D position = positions.get(i);

        out.write(String.format("%-2s %10.5f %10.5f %10.5f", atom.getSymbol(), position.getX(), position.getY(), position.getZ()));
        out.newLine();
    }

    out.flush();
}
