public void listenForStartLevel() {
    ServiceTracker<StartLevel, StartLevel> tracker = new ServiceTracker<>(context, StartLevel.class, null);
    tracker.open();

    try {
        // Listen for framework events
        while (true) {
            ServiceEvent event = tracker.waitForService(timeoutMillis);
            if (event == null) {
                break;
            }

            // Check if the event is a STARTLEVEL_CHANGED event
            if (event.getType() == ServiceEvent.MODIFIED && event.getServiceReference().getProperty(Constants.SERVICE_ID).equals(Constants.STARTLEVEL_SERVICE_ID)) {
                tracker.close();
                synchronized (lock) {
                    lock.notifyAll();
                }
                break;
            }
        }
    } catch (InterruptedException e) {
        Thread.currentThread().interrupt();
    } finally {
        tracker.close();
    }
}
