public static String enterScope(String currentString, String bracket) {
    if (currentString == null || bracket == null) {  // input validation
        throw new IllegalArgumentException("Input cannot be null");
    }
    String trimmedString = currentString.trim();  // trim any existing whitespace
    if (trimmedString.endsWith("{") || trimmedString.endsWith("(") || trimmedString.endsWith("[")) {
        return trimmedString + bracket;  // already in a scope, just append bracket
    } else {
        return trimmedString + " " + bracket;  // not in a scope, append whitespace and bracket
    }
}
