public void elementValueArrayInitializer() {
    match(LBRACE);
    // check if elementValue is present
    if (token.getType() != RBRACE) {
        elementValue();
        // check for multiple elementValues separated by comma
        while (token.getType() == COMMA) {
            match(COMMA);
            elementValue();
        }
    }
    match(RBRACE);
}
