import java.nio.ByteBuffer;
import java.util.zip.Adler32;

public int computeChecksum(ByteBuffer buffer, String channelName) {
    Adler32 adler32 = new Adler32();
    adler32.update(channelName.getBytes());
    adler32.update(buffer);
    return (int) adler32.getValue() % 65536;
}
