public boolean acquireQueued(final Node node, final int arg) {
    boolean interrupted = false;
    try {
        boolean acquired = false;
        for (;;) {
            final Node predecessor = node.predecessor();
            if (predecessor == head && tryAcquire(arg)) {
                setHead(node);
                predecessor.next = null; // help GC
                acquired = true;
                return interrupted;
            }
            if (shouldParkAfterFailedAcquire(predecessor, node) &&
                parkAndCheckInterrupt()) {
                interrupted = true;
            }
        }
    } catch (final Throwable t) {
        cancelAcquire(node);
        if (interrupted) {
            Thread.currentThread().interrupt();
        }
        throw t;
    } finally {
        if (!acquired) {
            cancelAcquire(node);
        }
    }
}
