public double bPolyTransformation(double value, double alpha) throws JMetalException {
    if (value < 0.0) {
        throw new JMetalException("Error: the value to transform must be greater than or equal to zero") ;
    }

    if (alpha < 0.0) {
        throw new JMetalException("Error: the alpha value must be greater than or equal to zero") ;
    }

    if (alpha > 1.0) {
        throw new JMetalException("Error: the alpha value must be lesser than or equal to one") ;
    }

    double res;
    double y = 1.0 - Math.pow(value, alpha);
    res = 1.0 - (y * y);

    return res;
}
