public PathExtractor createExtractor(int indexInRow, NodeCache cache, TypeSystem types) {
    Preconditions.checkArgument(indexInRow >= 0 && indexInRow < cache.numNodes(),
        "Index out of bounds: %s (total number of nodes: %s)", indexInRow, cache.numNodes());

    Node node = cache.node(indexInRow);
    Preconditions.checkNotNull(node, "Null node at index %s", indexInRow);

    // check if the node has a parent
    if (node.parent() == null) {
        throw new IllegalStateException("Node at index " + indexInRow + " has no parent node");
    }

    List<Node> pathNodes = new ArrayList<>();
    pathNodes.add(node.parent());

    // get all the parent nodes (up to the root)
    while (pathNodes.get(pathNodes.size() - 1).parent() != null) {
        pathNodes.add(pathNodes.get(pathNodes.size() - 1).parent());
    }

    Collections.reverse(pathNodes);

    PathExtractor pathExtractor = new PathExtractor(types);
    for (Node pathNode : pathNodes) {
        pathExtractor = pathExtractor.child(pathNode.type(), pathNode.childIndex());
    }

    return pathExtractor;
}
