public String reverseIfOpcode(String opcode) {
    String reversedOpcode = "";

    if (opcode.equals("IFEQ")) {
        reversedOpcode = "IFNE";
    } else if (opcode.equals("IFNE")) {
        reversedOpcode = "IFEQ";
    } else if (opcode.equals("IFLT")) {
        reversedOpcode = "IFGE";
    } else if (opcode.equals("IFGE")) {
        reversedOpcode = "IFLT";
    } else if (opcode.equals("IFGT")) {
        reversedOpcode = "IFLE";
    } else if (opcode.equals("IFLE")) {
        reversedOpcode = "IFGT";
    }

    return reversedOpcode;
}
