public static double[] calculateStatistics(double[] data) {
    double sum = 0;
    int count = 0;
    double min = Double.MAX_VALUE;
    double max = Double.MIN_VALUE;

    for (double d : data) {
        if (!Double.isNaN(d)) {
            sum += d;
            count++;
            if (d < min) {
                min = d;
            }
            if (d > max) {
                max = d;
            }
        }
    }

    double average = sum / count;

    return new double[] {average, max, min};
}
