public Method findGetterMethod(Class<?> clazz, String propertyName, boolean failover) {
    String capitalized = propertyName.substring(0, 1).toUpperCase() + propertyName.substring(1);
    String getterName = "get" + capitalized;
    String isName = "is" + capitalized;
    try {
        Method getter = clazz.getMethod(getterName);
        return getter;
    } catch (NoSuchMethodException e) {
        if (failover) {
            try {
                Method isMethod = clazz.getMethod(isName);
                if (isMethod.getReturnType() == Boolean.TYPE) {
                    return isMethod;
                }
            } catch (NoSuchMethodException ex) {
                return null;
            }
        }
        return null;
    }
}
