public Map<String, Object> getDifference(String itemId, int revisionFrom, int revisionTo) {
    Map<String, Object> diff = new HashMap<>();
    // Fetch item data for revisionFrom
    ItemData itemFrom = fetchItemData(itemId, revisionFrom);
    // Fetch item data for revisionTo
    ItemData itemTo = fetchItemData(itemId, revisionTo);
    // Compare fields in both revisions
    for (FieldData field : itemFrom.getFields()) {
        if (!itemTo.hasField(field.getName())) {
            // Field was removed in the new revision
            diff.put(field.getName(), null);
        } else {
            // Field exists in both revisions, compare values
            Object valueFrom = field.getValue();
            Object valueTo = itemTo.getField(field.getName()).getValue();
            if (!Objects.equals(valueFrom, valueTo)) {
                // Field value was changed between revisions
                diff.put(field.getName(), valueTo);
            }
        }
    }
    // Check for added fields in the new revision
    for (FieldData field : itemTo.getFields()) {
        if (!itemFrom.hasField(field.getName())) {
            diff.put(field.getName(), field.getValue());
        }
    }
    return diff;
}

