public static String substitutePropertyValue(String value, Properties props) {
    if (value == null) {
        return null;
    }
    String result = value;
    int startIndex = 0;
    int endIndex = 0;
    while (startIndex >= 0) {
        startIndex = result.indexOf("${", endIndex);
        if (startIndex >= 0) {
            endIndex = result.indexOf("}", startIndex);
            if (endIndex > startIndex) {
                String key = result.substring(startIndex + 2, endIndex);
                String propValue = props.getProperty(key);
                if (propValue != null) {
                    result = result.substring(0, startIndex) + propValue + result.substring(endIndex + 1);
                    endIndex = startIndex + propValue.length();
                }
            }
        }
    }
    return result;
}
