public int generateAndWriteToFile(String fileName, String code) {
    int filesWritten = 0;
    try {
        File file = new File(fileName);
        String existingCode = "";
        if(file.exists()) {
            try(BufferedReader reader = new BufferedReader(new FileReader(file))) {
                String line;
                while((line = reader.readLine()) != null) {
                    existingCode += line;
                }
            }
        }
        if(!existingCode.equals(code)) {
            try(BufferedWriter writer = new BufferedWriter(new FileWriter(file))) {
                writer.write(code);
            }
            filesWritten++;
        }
    } catch(IOException e) {
        e.printStackTrace();
    }
    return filesWritten;
}
