public Rectangle getBoundingBox(int srcWidth, int srcHeight, AffineTransform transform) {
    Point2D topLeft = new Point2D.Double(0, 0);
    Point2D bottomRight = new Point2D.Double(srcWidth, srcHeight);
    Point2D topRight = new Point2D.Double(bottomRight.getX(), topLeft.getY());
    Point2D bottomLeft = new Point2D.Double(topLeft.getX(), bottomRight.getY());
    Point2D[] points = {topLeft, topRight, bottomRight, bottomLeft};

    transform.transform(points, 0, points, 0, 4);

    double minX = Double.MAX_VALUE;
    double minY = Double.MAX_VALUE;
    double maxX = Double.MIN_VALUE;
    double maxY = Double.MIN_VALUE;

    for (Point2D point : points) {
        minX = Math.min(minX, point.getX());
        maxX = Math.max(maxX, point.getX());
        minY = Math.min(minY, point.getY());
        maxY = Math.max(maxY, point.getY());
    }

    int intMinX = (int) Math.floor(minX);
    int intMinY = (int) Math.floor(minY);
    int intMaxX = (int) Math.ceil(maxX);
    int intMaxY = (int) Math.ceil(maxY);

    return new Rectangle(intMinX, intMinY, intMaxX - intMinX, intMaxY - intMinY);
}
