public ApiResponseObjectDoc buildApiResponseObjectDoc(Method method) {
    ApiResponseObjectDoc response = new ApiResponseObjectDoc();

    Type returnType = method.getGenericReturnType();
    if (returnType instanceof ParameterizedType) {
        ParameterizedType type = (ParameterizedType) returnType;
        Type[] typeArguments = type.getActualTypeArguments();
        if (typeArguments.length > 0) {
            String typeName = typeArguments[0].getTypeName();
            if (typeName.startsWith("org.springframework.http.ResponseEntity<")) {
                typeName = typeName.substring(typeName.indexOf("<") + 1, typeName.lastIndexOf(">"));
            }
            response.setType(typeName);
        }
    } else {
        response.setType(returnType.getTypeName());
    }

    return response;
}
