            super.close();
            synchronized (baseClients) {
                for (WebClient wc : baseClients) {
                    wc.close();
                }
            }
            String moduleName = getModuleName();
            synchronized (clientsPerModule) {
                List<JAXRSClientImpl> clients = clientsPerModule.get(moduleName);
