public String formatStandardTime(String movie, int mediaFrameNo) {
    int hours = mediaFrameNo / (30 * 60 * 60);
    int minutes = (mediaFrameNo / (30 * 60)) % 60;
    int seconds = (mediaFrameNo / 30) % 60;
    int frames = mediaFrameNo % 30;
    return String.format("%s = %02d:%02d:%02d.%02d", movie, hours, minutes, seconds, frames);
}
