public static void copyAndCloseStreams(Reader reader, Writer writer) throws IOException {
    try {
        char[] buffer = new char[1024];
        int length;
        while ((length = reader.read(buffer)) != -1) {
            writer.write(buffer, 0, length);
        }
    } finally {
        try {
            reader.close();
        } finally {
            writer.close();
        }
    }
}
