public ConsistentHash removeAndAssign(ConsistentHash baseCH, List<Address> actualMembers) {
    if (baseCH == null) {
        return null;
    }

    List<Address> oldMembers = baseCH.getMembers();
    Set<Address> membersToRemove = new HashSet<>(oldMembers);
    membersToRemove.removeAll(actualMembers);
    ConsistentHash newCH = baseCH.remove(membersToRemove);

    List<Address> previousOwners = newCH.getMembers();
    List<Address> newSegmentsOwners = new ArrayList<>(previousOwners);
    for (Address address : actualMembers) {
        if (!previousOwners.contains(address))
            newSegmentsOwners.add(address);
    }
    int oldFactor = baseCH.getNumSegmentsPerOwner();
    int newFactor = Math.max(1, newSegmentsOwners.size() / actualMembers.size());
    if (newFactor != oldFactor) {
        // rebalance the segments if necessary
        return newCH.rebalance(newFactor, null);
    }
    return newCH;
}
