public int createDFSPathsAndWriteData(List<String> paths, byte[] data) {
    try {
        FileSystem fileSystem = FileSystem.get(new Configuration());
        Path[] dfsPaths = new Path[paths.size()];

        // create the dfs paths
        for (int i = 0; i < paths.size(); i++) {
            dfsPaths[i] = new Path(paths.get(i));
        }

        // write data to the dfs paths
        FSDataOutputStream output;
        for (Path path : dfsPaths) {
            output = fileSystem.create(path);
            output.write(data);
            output.close();
        }

        fileSystem.close();
        return 0;
    } catch (IOException e) {
        e.printStackTrace();
        return -1;
    }
}
