public static String addComment(String values, String comment, char star) {
    StringBuilder sb = new StringBuilder();
    sb.append(star).append(" ").append(comment).append("\n");
    for (String value : values.split(",")) {
        sb.append(value.trim()).append(",").append("\n");
    }
    return sb.toString();
}
