public List<String> partitionPathBySchemaName(String path, Schema schema) {
    if (schema == null || schema.getName() == null || schema.getName().isEmpty()) {
        return Collections.singletonList(path);
    }

    String schemaName = schema.getName();

    List<String> pathParts = Arrays.asList(path.split("/"));
    List<String> partitionedPathParts = new ArrayList<>();

    for (String pathPart : pathParts) {
        if (pathPart.contains(schemaName)) {
            int index = pathPart.indexOf(schemaName);

            if (index == 0) {
                partitionedPathParts.add(schemaName);
                String remainingPart = pathPart.substring(schemaName.length());
                if (!remainingPart.isEmpty()) {
                    partitionedPathParts.add(remainingPart);
                }
            } else {
                String beforeSchemaName = pathPart.substring(0, index);
                String afterSchemaName = pathPart.substring(index);
                partitionedPathParts.add(beforeSchemaName);
                partitionedPathParts.add(schemaName);
                if (!afterSchemaName.isEmpty()) {
                    partitionedPathParts.add(afterSchemaName);
                }
            }
        } else {
            partitionedPathParts.add(pathPart);
        }
    }

    return partitionedPathParts;
}
