public static BeanReferences removeLaterDuplicates(BeanReferences beanRefs) {
    Set<BeanReference> set = new LinkedHashSet<>(); // use LinkedHashSet to maintain the order
    boolean changed = false;
    for (BeanReference ref : beanRefs.getBeanReferences()) {
        if (!set.contains(ref)) {
            set.add(ref);
        } else {
            changed = true;
        }
    }
    return changed ? new BeanReferences(new ArrayList<>(set)) : beanRefs;
}
