public static UIComponent findComponent(String id, UIComponent base, char separatorChar, FacesContext context, ComponentCallback callback) {
    if (base == null) return null;
    if (id.equals(base.getId())) {
        callback.foundCallback(base);
        return base;
    }
    UIComponent childFound = null;
    for (UIComponent child : base.getFacetsAndChildren()) {
        String childId = child.getId();
        if (childId != null && childId.startsWith(separatorChar + "")) {
            childId = childId.substring(1);
        }
        if (id.equals(childId)) {
            callback.foundCallback(child);
            return child;
        }
        if (child.getChildCount() > 0) {
            childFound = findComponent(id, child, separatorChar, context, callback);
            if (childFound != null) {
                break;
            }
        }
    }
    if (childFound == null) {
        callback.notFoundCallback(base);
    }
    return childFound;
}
