public void guaranteeUnreachable(Node tail, Node unlinkedNode) {
    // Traverse the linked list starting from the tail until we reach the unlinked node or the head
    while (tail != null && tail != unlinkedNode) {
        tail = tail.getPrevious();
    }

    // If we reached the unlinked node, update the tail to the node before it
    if (tail == unlinkedNode) {
        tail = unlinkedNode.getPrevious();
    }
}
