public void endSection(String section) {
    if (currentSection == null) {
        throw new IllegalStateException("Can't end section. No section started.");
    }

    if (!currentSection.equals(section)) {
        throw new IllegalStateException("Can't end section. Wrong section name.");
    }

    long endTime = System.nanoTime();

    ProfilerData data = profileData.get(section);
    data.time += (endTime - currentSectionStartTime);
    data.count++;

    currentSection = null;
}
