public Discriminator prepareSplit(BlockNode node, Splitter splitter) {
    Set<Node> nodesToSplit = node.getSubtreeNodes();
    Map<Node, SplitData> splitDataMap = new HashMap<>();
    for (Node n : nodesToSplit) {
        if (n instanceof Transition) {
            splitDataMap.put(n, new SplitData(splitter.getPriority((Transition) n)));
        } else {
            splitDataMap.put(n, new SplitData());
        }
    }
    node.annotateWith(splitDataMap);
    return splitter.getNextDiscriminator();
}
