public byte[] removeScriptObject(byte[] inputScript, byte[] scriptObject) {
    List<Byte> scriptBytes = new ArrayList<>();

    int i = 0;
    while (i < inputScript.length) {
        if (inputScript[i] == scriptObject[0] && inputScript.length - i >= scriptObject.length) {
            boolean found = true;
            for (int j = 1; j < scriptObject.length; j++) {
                if (inputScript[i+j] != scriptObject[j]) {
                    found = false;
                    break;
                }
            }
            if (found) {
                i += scriptObject.length;
                continue;
            }
        }
        scriptBytes.add(inputScript[i]);
        i++;
    }

    byte[] result = new byte[scriptBytes.size()];
    for (int j = 0; j < scriptBytes.size(); j++) {
        result[j] = scriptBytes.get(j);
    }
    return result;
}
