import groovy.lang.Binding;
import groovy.lang.GroovyShell;
import java.io.PrintWriter;
import java.io.StringWriter;

public class GroovyRunner {

    public static String runScript(String script) {
        // Redirect standard output to a string
        StringWriter output = new StringWriter();
        System.setOut(new PrintWriter(output));

        // Prepare the script and shell
        Binding binding = new Binding();
        GroovyShell shell = new GroovyShell(binding);

        try {
            // Evaluate the script
            Object result = shell.evaluate(script);

            // Reset standard output
            System.setOut(new PrintWriter(System.out));

            // Return the result as plain text
            return output.toString() + result.toString();
        } catch (Exception e) {
            // Reset standard output
            System.setOut(new PrintWriter(System.out));

            // Return the exception message as plain text
            return output.toString() + e.getMessage();
        }
    }

}
