public static <T> T unmarshalStream(InputStream is, Map<String, String> parameters) throws KubernetesClientException {
    T object = null;
    try {
        BufferedReader reader = new BufferedReader(new InputStreamReader(is));
        String line;
        StringBuilder builder = new StringBuilder();
        while ((line = reader.readLine()) != null) {
            builder.append(line).append("\n");
        }
        String content = builder.toString();
        for (Map.Entry<String, String> entry : parameters.entrySet()) {
            content = content.replaceAll("\\{\\{" + entry.getKey() + "\\}\\}", entry.getValue());
        }
        object = new Yaml().loadAs(content, (Class<T>) Object.class);
    } catch (IOException e) {
        throw new KubernetesClientException("Error reading InputStream", e);
    }
    return object;
}
