public Set<Integer> getResourcesByQuery(String query) {
    Set<Integer> matchingResourceIds = new HashSet<Integer>();

    // Code to fetch all resource ids and their associated terms
    Map<Integer, Set<String>> resourceTermsMapping = fetchAllResourceTermsMapping();

    for (int resourceId : resourceTermsMapping.keySet()) {
        Set<String> resourceTerms = resourceTermsMapping.get(resourceId);

        for (String term : resourceTerms) {
            if (term.contains(query)) {
                matchingResourceIds.add(resourceId);
                break;
            }
        }
    }

    return matchingResourceIds;
}
