public int copyLimitedBytes(InputStream input, OutputStream output, byte[] buffer, int length) throws IOException {
    int totalBytesCopied = 0;
    int bytesRead = 0;
    while (totalBytesCopied < length && (bytesRead = input.read(buffer, 0, Math.min(length - totalBytesCopied, buffer.length))) != -1) {
        output.write(buffer, 0, bytesRead);
        totalBytesCopied += bytesRead;
    }
    return totalBytesCopied;
}
