        allowedChars += ":@&=+%,";
    } else {
        allowedChars += ":@&=+%'/,";
    }
    allowedChars += t;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (allowedChars.indexOf(c) == -1) {
            throw new IllegalArgumentException("Illegal character found: " + c);
        }
    }
}
