public static String resilientUrlDecode(String input) {
    String decodedString = null;
    try {
        decodedString = java.net.URLDecoder.decode(input, "UTF-8");
    } catch (Exception e) {
        // If URLDecoder throws an exception, catch it and try decoding using a different encoding
        try {
            decodedString = java.net.URLDecoder.decode(input, "ISO-8859-1");
        } catch (Exception ex) {
            // If both encodings fail, return the original input
            return input;
        }
    }
    return decodedString;
}
