public String createStringExpression(Expression left, Expression right) throws TemplateException {
    String leftExp = left.getExpression();
    String rightExp = right.getExpression();
    if (leftExp.contains(";") || rightExp.contains(";")) {
        throw new TemplateException("The expressions contain a semicolon");
    }
    return "(" + leftExp + " + " + rightExp + ")";
}
