public Set<String> excludeProjectedVariables(Map<String, ?> variables, Set<String> projectedVariables) throws UnsatisfiableDescendingSubstitutionException {
    Set<String> excludedVariables = new HashSet<String>();
    for (String variable : variables.keySet()) {
        if (!projectedVariables.contains(variable)) {
            excludedVariables.add(variable);
        }
        if (variables.get(variable) == null) {
            throw new UnsatisfiableDescendingSubstitutionException();
        }
    }
    return excludedVariables;
}
