                Thread.sleep(500); // blocks the thread for 500 ms
            }
            byte[] data = new byte[inputStream.available()];
            inputStream.read(data);
            System.out.println(new String(data));
            inputStream.close();
        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        }
    }
}
