public static AxisAlignedBB rotateAxisAlignedBB(AxisAlignedBB aabb, double angle, Axis axis) {
    Vec3d center = aabb.getCenter();
    Matrix4f matrix = new Matrix4f();
    matrix.translate(center);
    switch (axis) {
        case X:
            matrix.rotate(angle, new Vector3f(1, 0, 0));
            break;
        case Y:
            matrix.rotate(angle, new Vector3f(0, 1, 0));
            break;
        case Z:
            matrix.rotate(angle, new Vector3f(0, 0, 1));
            break;
    }
    matrix.translate(center.negate());
    return aabb.offset(matrix.transform(aabb.getCenter().subtract(center)));
}
