public synchronized Object checkValue(Object value) throws ExpressionException {
    //assuming the multidimensional array is called 'arr'
    int arrLength = arr.length;
    int valueLength = Array.getLength(value);
    if (arrLength == 0 || valueLength == 0) {
        throw new ExpressionException("Array length cannot be zero");
    }
    int arrDimLength = Array.getLength(arr[0]);
    int valDimLength = Array.getLength(value[0]);
    if (valDimLength >= arrDimLength) {
        throw new ExpressionException("Value's dimension is too big to fit in the array");
    }
    return value;
}
