public void saveProxyCredentialsToFile(String proxyFileName, String uc, String encoding) throws IOException {
    Path path = Path.of(proxyFileName);

    byte[] privateKeyBytes = uc.getBytes(encoding);

    try (FileOutputStream fileOutputStream = new FileOutputStream(proxyFileName)) {
        fileOutputStream.write(privateKeyBytes);
    }

    Set<PosixFilePermission> perms = new HashSet<>();
    perms.add(PosixFilePermission.OWNER_READ);
    perms.add(PosixFilePermission.OWNER_WRITE);
    perms.add(PosixFilePermission.GROUP_READ);
    perms.add(PosixFilePermission.OTHERS_READ);
    Files.setPosixFilePermissions(path, perms);
}
