public List<File> fetchI18nSourceFiles(File sourceDirectory) throws IOException {
    List<File> sourceFiles = new ArrayList<>();
    File[] files = sourceDirectory.listFiles();
    for (File file : files) {
        if (file.isFile() && file.getName().endsWith(".xml")) {
            sourceFiles.add(file);
        } else if (file.isDirectory()) {
            sourceFiles.addAll(fetchI18nSourceFiles(file));
        }
    }
    return sourceFiles;
}
