public String main(HttpHost targetHost, HttpHost proxyHost, String httpRequestMethod, String encoding, UsernamePasswordCredentials upc, InputStream keystore, String password) throws IOException {
    KeyStore keyStore;
    try {
        keyStore = KeyStore.getInstance(KeyStore.getDefaultType());
        keyStore.load(keystore, password.toCharArray());
    } catch (KeyStoreException | NoSuchAlgorithmException | CertificateException | IOException e) {
        throw new IOException("Could not load keystore", e);
    }

    HttpClientBuilder httpClientBuilder = HttpClientBuilder.create();
    if (proxyHost != null) {
        httpClientBuilder.setProxy(proxyHost);
    }
    if (upc != null) {
        CredentialsProvider credentialsProvider = new BasicCredentialsProvider();
        credentialsProvider.setCredentials(new AuthScope(targetHost.getHostName(), targetHost.getPort(), AuthScope.ANY_REALM), upc);
        httpClientBuilder.setDefaultCredentialsProvider(credentialsProvider);
    }
    CloseableHttpClient httpClient = httpClientBuilder.setSSLContext(getSSLContext(keyStore, password)).build();

    try {
        HttpRequestBase request = null;
        switch (httpRequestMethod.toUpperCase()) {
            case "GET":
                request = new HttpGet(targetHost.toURI());
                break;
            case "POST":
                request = new HttpPost(targetHost.toURI());
                break;
            default:
                throw new IOException("Unsupported HTTP method: " + httpRequestMethod.toUpperCase());
        }

        CloseableHttpResponse response = httpClient.execute(request);

        try {
            HttpEntity entity = response.getEntity();
            if (entity != null) {
                return EntityUtils.toString(entity, encoding);
            } else {
                throw new IOException("Empty response");
            }
        } finally {
            response.close();
        }
    } finally {
        httpClient.close();
    }
}

private SSLContext getSSLContext(KeyStore keystore, String password) throws IOException {
    SSLContext sslcontext;
    try {
        sslcontext = SSLContexts.custom().loadKeyMaterial(keystore, password.toCharArray()).build();
    } catch (NoSuchAlgorithmException | KeyStoreException | UnrecoverableKeyException | KeyManagementException e) {
        throw new IOException("Could not create SSL context", e);
    }

    return sslcontext;
}
