    InputStream inputStream = getClass().getResourceAsStream(url);
    if (inputStream != null) {
        try (Reader reader = new InputStreamReader(inputStream, StandardCharsets.UTF_8)) {
            return SObject.parseJson(reader);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
    return null;
}
