public String determineNetworkAccessPointTypeCode(String address) {
    // Check if the address contains the word "ipv6"
    if (address.toLowerCase().contains("ipv6")) {
        return "I";
    }
    // Check if the address contains a colon
    if (address.contains(":")) {
        return "M";
    }
    // Check if the address contains a period
    if (address.contains(".")) {
        return "I";
    }
    return null; // Return null if the address is not recognized
}
