public ContentHandler createResultContentHandler(Result outputTarget) throws TransformerException {
    if (outputTarget == null) {
        throw new IllegalArgumentException("OutputTarget argument cannot be null");
    }
    OutputProperties outputProperties = getOutputProperties();
    Serializer serializer = SerializerFactory.getSerializer(outputProperties);
    serializer.setOutputStream(getOutputStream(outputTarget));
    return serializer.asContentHandler();
}

private static OutputStream getOutputStream(Result outputTarget) throws TransformerException {
    if (outputTarget instanceof StreamResult) {
        StreamResult streamResult = (StreamResult) outputTarget;
        if (streamResult.getOutputStream() != null) {
            return streamResult.getOutputStream();
        }
        if (streamResult.getWriter() != null) {
            return new WriterOutputStream(streamResult.getWriter());
        }
        if (streamResult.getSystemId() != null) {
            try {
                return new FileOutputStream(streamResult.getSystemId());
            } catch (FileNotFoundException e) {
                throw new TransformerException("Unable to open file " + streamResult.getSystemId(), e);
            }
        }
        throw new TransformerException("Cannot create output stream or writer for StreamResult");
    }
    throw new TransformerException("Result type " + outputTarget.getClass().getName() + " not supported");
}
