public List<Object> sampleDataset(int numSamples, boolean withReplacement) {
    List<Object> dataset = new ArrayList<Object>();
    // logic to retrieve the dataset

    List<Object> sampledDataset = new ArrayList<Object>();
    Random rng = new Random();

    if (withReplacement) {
       for (int i = 0; i < numSamples; i++) {
           int randomIndex = rng.nextInt(dataset.size());
           sampledDataset.add(dataset.get(randomIndex));
       }
    } else {
       List<Object> copyOfDataset = new ArrayList<Object>(dataset);
       for (int i = 0; i < numSamples; i++) {
           int randomIndex = rng.nextInt(copyOfDataset.size());
           sampledDataset.add(copyOfDataset.remove(randomIndex));
       }
    }

    return sampledDataset;
}
