public void watchNode(String path) throws ZooKeeperException {
    try {
        // create a ZooKeeper instance
        ZooKeeper zookeeper = new ZooKeeper("localhost", 2181, 5000, null);

        // create a watcher for the given path
        Watcher watcher = new Watcher() {
            @Override
            public void process(WatchedEvent event) {
                if (event.getType() == EventType.NodeDataChanged) {
                    System.out.println("Node data has been changed.");
                    // do something else here
                }
            }
        };

        // set the watcher for the given path
        zookeeper.getData(path, watcher, null);

    } catch (IOException e) {
        throw new ZooKeeperException("Error creating ZooKeeper instance", e);
    } catch (KeeperException | InterruptedException e) {
        throw new ZooKeeperException("Error watching node", e);
    }
}
