public void cachedDC(String backupFilePath) {
   // Assuming the backup file exists at the specified path
   File backupFile = new File(backupFilePath);

   try {
      Path backupPath = backupFile.toPath();
      WatchService watchService = backupPath.getFileSystem().newWatchService();
      backupPath.register(watchService, StandardWatchEventKinds.ENTRY_CREATE, 
                StandardWatchEventKinds.ENTRY_DELETE, StandardWatchEventKinds.ENTRY_MODIFY);

      while (true) {
         WatchKey watchKey = watchService.take();

         for (WatchEvent<?> event : watchKey.pollEvents()) {
            WatchEvent.Kind<?> kind = event.kind();

            if (kind == StandardWatchEventKinds.OVERFLOW) {
               continue;
            }

            WatchEvent<Path> pathEvent = (WatchEvent<Path>) event;
            Path filePath = pathEvent.context();

            // Write the changes to the backup file as they occur
            FileWriter writer = new FileWriter(backupFile, true);
            writer.write(filePath.toString() + " " + kind.toString() + "\n");
            writer.close();
         }

         if (!watchKey.reset()) {
            break;
         }
      }
   } catch (IOException | InterruptedException e) {
      e.printStackTrace();
   }
}
