public <T> T deserializeFromString(String clazz, String stringContainingSerialisedInput) throws ClassNotFoundException, IOException {
    Class<?> cls = Class.forName(clazz);
    ObjectInput in = null;
    try {
        byte[] bytes = Base64.getDecoder().decode(stringContainingSerialisedInput);
        in = new ObjectInputStream(new ByteArrayInputStream(bytes));
        Object obj = in.readObject();
        return (T) cls.cast(obj);
    } finally {
        if (in != null) {
            in.close();
        }
    }
}
