public double[] convertToFranceLambert(double lambda, double phi) {
    double phi0 = Math.PI / 2.0;
    double phi1 = 44.0 * Math.PI / 180.0;
    double phi2 = 49.0 * Math.PI / 180.0;
    double phiC = (phi1 + phi2) / 2.0;
    double lambda0 = 3.0 * Math.PI / 180.0;
    double n = 0.7289686274;
    double C = 11754255.426;
    double xs = 700000.0;
    double ys = 6600000.0;

    double L = lambda - lambda0;
    double lphi = Math.log(Math.tan(Math.PI / 4.0 + phi / 2.0));
    double lphic = Math.log(Math.tan(Math.PI / 4.0 + phiC / 2.0));
    double r = C * Math.pow(Math.tan(phiC / 2.0), n) / Math.pow(Math.tan(phi / 2.0), n);

    double x = xs + r * Math.sin(n * L);
    double y = ys + r * Math.cos(n * L) * (lphi - lphic);

    double[] result = new double[2];
    result[0] = x;
    result[1] = y;
    return result;
}
