@Override
public long count(List<Criteria> criteriaList) {
    CriteriaBuilder criteriaBuilder = entityManager.getCriteriaBuilder();
    CriteriaQuery<Long> criteriaQuery = criteriaBuilder.createQuery(Long.class);
    Root<T> root = criteriaQuery.from(entityClass);

    List<Predicate> predicates = buildPredicates(criteriaBuilder, root, criteriaList);
    criteriaQuery.where(predicates.toArray(new Predicate[]{}));
    criteriaQuery.select(criteriaBuilder.count(root));

    return entityManager.createQuery(criteriaQuery).getSingleResult();
}

private List<Predicate> buildPredicates(CriteriaBuilder criteriaBuilder, Root<T> root, List<Criteria> criteriaList) {
    List<Predicate> predicates = new ArrayList<>();
    for (Criteria criteria : criteriaList) {
        switch (criteria.getOperator()) {
            case EQUALS:
                predicates.add(criteriaBuilder.equal(root.get(criteria.getName()), criteria.getValue()));
                break;
            case LIKE:
                predicates.add(criteriaBuilder.like(root.<String>get(criteria.getName()), "%" + criteria.getValue() + "%"));
                break;
            case GREATER_THAN:
                predicates.add(criteriaBuilder.greaterThan(root.<String>get(criteria.getName()), criteria.getValue()));
                break;
            case LESS_THAN:
                predicates.add(criteriaBuilder.lessThan(root.<String>get(criteria.getName()), criteria.getValue()));
                break;
            case GREATER_THAN_OR_EQUAL:
                predicates.add(criteriaBuilder.greaterThanOrEqualTo(root.<String>get(criteria.getName()), criteria.getValue()));
                break;
            case LESS_THAN_OR_EQUAL:
                predicates.add(criteriaBuilder.lessThanOrEqualTo(root.<String>get(criteria.getName()), criteria.getValue()));
                break;
        }
    }
    return predicates;
