public static String toUserPresentableMessage(IOException ioe, String action) {
    String errorMessage = "Internal Server Error";
    int statusCode = 500;

    if (ioe instanceof HttpException) {
        statusCode = ((HttpException)ioe).getStatusCode();

        if (statusCode >= 400 && statusCode < 500) {
            errorMessage = ioe.getMessage();
        }
    }

    return "Error " + statusCode + " occurred while " + action + ". " + errorMessage;
}
