public class Example {
    public static Object get(Object obj, String key) {
        if (obj instanceof Map) {
            // If the object is a Map (e.g. a HashMap or TreeMap)
            Map<?, ?> map = (Map<?, ?>) obj;
            Object value = map.get(key);
            if (value != null) {
                return value;
            }
        } else if (obj instanceof JSONObject) {
            // If the object is a JSONObject (from the JSON library)
            JSONObject json = (JSONObject) obj;
            if (json.has(key)) {
                return json.get(key);
            }
        } else if (obj instanceof JSONArray) {
            // If the object is a JSONArray (from the JSON library)
            JSONArray array = (JSONArray) obj;
            try {
                int index = Integer.parseInt(key);
                if (index >= 0 && index < array.length()) {
                    return array.get(index);
                }
            } catch (NumberFormatException e) {
                // Ignore the exception and continue to the next check
            }
        } else if (obj instanceof Object[]) {
            // If the object is an array (e.g. String[], int[], etc.)
            Object[] array = (Object[]) obj;
            try {
                int index = Integer.parseInt(key);
                if (index >= 0 && index < array.length) {
                    return array[index];
                }
            } catch (NumberFormatException e) {
                // Ignore the exception and continue to the next check
            }
        } else if (obj instanceof Iterable) {
            // If the object is an iterable (e.g. List, Set, etc.)
            Iterable<?> iterable = (Iterable<?>) obj;
            try {
                int index = Integer.parseInt(key);
                if (index >= 0) {
                    int i = 0;
                    for (Object item : iterable) {
                        if (i == index) {
                            return item;
                        }
                        i++;
                    }
                }
            } catch (NumberFormatException e) {
                // Ignore the exception and continue to the next check
            }
        }

        // If the key was not found or the object type is not supported, return null
        return null;
    }
}
