public static boolean isMethodReference(String input) {
    int index = input.indexOf("<");
    if (index != -1) {
        int matchingIndex = input.indexOf(">", index);
        if (matchingIndex != -1) {
            String terminal = input.substring(matchingIndex + 1).trim();
            if (terminal.equals(".") || terminal.equals("::")) {
                return true;
            }
        }
    }
    return false;
}
