public static Object convertValueToType(Class<?> type, Object value) {
    if (value == null) {
        return null;
    }

    TypeCode typeCode = TypeConverter.toTypeCode(type);
    if (typeCode == null) {
        return null;
    }

    switch (typeCode) {
        case INTEGER:
            if (value instanceof BigDecimal) {
                return ((BigDecimal) value).intValueExact();
            } else if (value instanceof Number) {
                return ((Number) value).intValue();
            } else if (value instanceof String) {
                return Integer.parseInt((String) value);
            }
            break;
        case FLOAT:
            if (value instanceof BigDecimal) {
                return ((BigDecimal) value).floatValue();
            } else if (value instanceof Number) {
                return ((Number) value).floatValue();
            } else if (value instanceof String) {
                return Float.parseFloat((String) value);
            }
            break;
        case DOUBLE:
            if (value instanceof BigDecimal) {
                return ((BigDecimal) value).doubleValue();
            } else if (value instanceof Number) {
                return ((Number) value).doubleValue();
            } else if (value instanceof String) {
                return Double.parseDouble((String) value);
            }
            break;
        case BOOLEAN:
            if (value instanceof Boolean) {
                return value;
            } else if (value instanceof String) {
                String booleanValue = (String) value;
                if (booleanValue.equalsIgnoreCase("true")) {
                    return true;
                } else if (booleanValue.equalsIgnoreCase("false")) {
                    return false;
                }
            }
            break;
        case DATE:
            if (value instanceof Date) {
                return value;
            } else if (value instanceof LocalDate) {
                return Date.from(((LocalDate) value).atStartOfDay(ZoneId.systemDefault()).toInstant());
            } else if (value instanceof LocalDateTime) {
                return Date.from(((LocalDateTime) value).atZone(ZoneId.systemDefault()).toInstant());
            } else if (value instanceof String) {
                return Date.from(LocalDate.parse((String) value).atStartOfDay(ZoneId.systemDefault()).toInstant());
            }
            break;
        case STRING:
            return value.toString();
        default:
            break;
    }

    return null;
}
