public static <T> Collection<T> findAllGoals(SearchMethod<T> method) {
    Collection<T> goals = new ArrayList<>();
    while(method.hasNext()) {
        T state = method.next();
        if(method.isGoal(state)) {
            goals.add(state);
        }
    }
    return goals;
}
