public static PGPSecretKey readAndUnlockPrivateKey(InputStream secretKey, char[] password, PGPSecretKeyRingCollection keyFilter) throws IOException, PGPException {
    PGPObjectFactory factory = new PGPObjectFactory(PGPUtil.getDecoderStream(secretKey));
    Object obj = factory.nextObject();
    PGPSecretKeyRingCollection pgpSec = null;
    if (obj instanceof PGPSecretKeyRingCollection) {
        pgpSec = (PGPSecretKeyRingCollection) obj;
    } else if (obj instanceof PGPSecretKeyRing) {
        pgpSec = new PGPSecretKeyRingCollection(Collections.singletonList((PGPSecretKeyRing) obj));
    }
    PGPSecretKey foundKey = null;
    if (pgpSec != null) {
        Iterator<PGPSecretKeyRing> keyRingIter = pgpSec.getKeyRings();
        while (foundKey == null && keyRingIter.hasNext()) {
            PGPSecretKeyRing keyRing = keyRingIter.next();
            Iterator<PGPSecretKey> keyIter = keyRing.getSecretKeys();
            while (foundKey == null && keyIter.hasNext()) {
                PGPSecretKey key = keyIter.next();
                if (keyFilter == null || keyFilter.contains(key.getPublicKey().getKeyID())) {
                    foundKey = key;
                }
            }
        }
    }
    if (foundKey == null) {
        return null;
    }
    try {
        return foundKey.extractPrivateKey(new JcePBESecretKeyDecryptorBuilder().setProvider("BC").build(password));
    } catch (PGPException e) {
        return null;
    }
}
