public List<MultiIndex.Action> getRedoLogActions() throws IOException {
    List<MultiIndex.Action> actions = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader("redoLog.txt"))) {
        String line = reader.readLine();
        while (line != null) {
            actions.add(MultiIndex.Action.valueOf(line));
            line = reader.readLine();
        }
    }
    catch (IOException ex) {
        throw new IOException("An error occured while reading from the redo log.", ex);
    }
    return actions;
}
