public double[] generateWindow(String windowType, int nSamples) {
    double[] window = new double[nSamples];
    switch (windowType) {
        case "rectangular":
            for (int i = 0; i < nSamples; i++) {
                window[i] = 1.0;
            }
            break;
        case "hanning":
            double alpha = 0.5;
            for (int i = 0; i < nSamples; i++) {
                window[i] = alpha - (1 - alpha) * Math.cos((2 * Math.PI * i) / (nSamples - 1));
            }
            break;
        case "hamming":
            for (int i = 0; i < nSamples; i++) {
                window[i] = 0.54 - 0.46 * Math.cos((2 * Math.PI * i) / (nSamples - 1));
            }
            break;
        // add more cases for other window types if needed
        default: // rectangular window is used as default
            for (int i = 0; i < nSamples; i++) {
                window[i] = 1.0;
            }
            break;
    }
    return window;
}
