public static void encodeLong(byte[] target, int idx, long value) {
  target[idx++] = (byte)(value >>> 56);
  target[idx++] = (byte)(value >>> 48);
  target[idx++] = (byte)(value >>> 40);
  target[idx++] = (byte)(value >>> 32);
  target[idx++] = (byte)(value >>> 24);
  target[idx++] = (byte)(value >>> 16);
  target[idx++] = (byte)(value >>> 8);
  target[idx] = (byte)value;
}
