public static String getFirstSubdirectoryOfNearestNodePath(String requiringFile, String requireText) throws IOException {
    Path filePath = Paths.get(requiringFile).toAbsolutePath();
    String[] pathParts = filePath.toString().split(Pattern.quote(File.separator));
    int nodeModulesIndex = -1;
    for (int i = pathParts.length - 1; i >= 0; i--) {
        if (pathParts[i].equals("node_modules")) {
            nodeModulesIndex = i;
            break;
        }
    }
    if (nodeModulesIndex == -1) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    for (int i = nodeModulesIndex; i < pathParts.length; i++) {
        sb.append(File.separator);
        sb.append(pathParts[i]);
        if (Files.exists(Paths.get(sb.toString() + File.separator + requireText))) {
            return sb.toString();
        }
    }
    return null; // no matching directory found
}
