public static String trimTail(String sSrc, int nCount) {
    if(sSrc.length() <= nCount) {
        return "";
    }
    String tail = sSrc.substring(sSrc.length()-nCount);
    if(sSrc.endsWith(tail)) {
        return sSrc.substring(0, sSrc.length()-nCount);
    } else {
        return sSrc;
    }
}
