public Graph reverseEdges(Graph graph) throws UnsupportedOperationException {
    if (!(graph instanceof DirectedGraph)) {
        throw new UnsupportedOperationException("Only directed graphs can have their edges reversed.");
    }
    Graph reversed = new DirectedGraph(graph.getNumVertices());
    for (int v : graph.getVertices()) {
        for (int u : graph.getNeighbors(v)) {
            reversed.addEdge(u, v);
        }
    }
    return reversed;
}
