public static List<String> extractNonNullText(List<SymbolToken> symbolTokens) throws UnknownSymbolException {
    List<String> nonNullTexts = new ArrayList<>();
    for (SymbolToken symbolToken : symbolTokens) {
        String text = symbolToken.getText();
        if (text == null) {
            throw new UnknownSymbolException("Token is missing text: " + symbolToken);
        } else {
            nonNullTexts.add(text);
        }
    }
    return Collections.unmodifiableList(nonNullTexts);
}
