    public E get(int index) {
        if (index < 0 || index >= size()) {
            throw new IndexOutOfBoundsException();
        }
        return entries[index];
    }

    @Override
    public E set(int index, E element) {
        if (index < 0 || index >= size()) {
            throw new IndexOutOfBoundsException();
        }
        E previous = entries[index];
        entries[index] = element;
        return previous;
    }

    @Override
    public int size() {
        return entries.length;
    }
}
