public static double calculatePolygonArea(List<List<Double>> vertices) {
    double area = 0;
    int numVertices = vertices.size();
    for (int i = 0; i < numVertices; i++) {
        double xi = vertices.get(i).get(0);
        double yi = vertices.get(i).get(1);
        double xj = vertices.get((i + 1) % numVertices).get(0);
        double yj = vertices.get((i + 1) % numVertices).get(1);
        area += (xj + xi) * (yj - yi);
    }
    return Math.abs(area / 2);
}
