import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.transform.dom.DOMSource;

import org.w3c.dom.Document;
import org.xml.sax.InputSource;

public boolean compareDocuments(Document d1, Document d2) throws MarshalException {
    try {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        factory.setNamespaceAware(true); // Ignore namespaces

        DocumentBuilder builder = factory.newDocumentBuilder();
        DOMSource ds1 = new DOMSource(d1);
        DOMSource ds2 = new DOMSource(d2);

        InputSource is1 = new InputSource();
        InputSource is2 = new InputSource();

        is1.setByteStream(ds1);
        is2.setByteStream(ds2);

        Document doc1 = builder.parse(is1);
        Document doc2 = builder.parse(is2);

        return doc1.isEqualNode(doc2);
    } catch (Exception e) {
        throw new MarshalException("Error while comparing documents", e);
    }
}
