public abstract class Workhorse implements Callable<Void> {

    @Override
    public Void call() throws Exception {
        try {
            // "code around" logic
            beforeExecute();
            execute();
            afterExecute(null);
        } catch (Throwable t) {
            afterExecute(t);
            throw t;
        }
        return null;
    }

    protected abstract void execute() throws Exception;

    protected void beforeExecute() throws Exception {
        // Default no-op implementation
    }

    protected void afterExecute(Throwable t) throws Exception {
        // Default no-op implementation
    }
}
