@Override
public int handleTransliterate(Replaceable text,
        Transliterator.Position pos, boolean incremental) {
    int limit = pos.limit;
    int start = pos.start;
    int minLimit = start;

    while (start < limit) {
        int c = text.char32At(start);
        if (!filter.contains(c)) {
            break;
        }
        start += UTF16.getCharCount(c);
    }

    boolean outFrontier = false;

    if (start > minLimit && start < limit) {
        text.copy(minLimit, start, limit - start);
        limit -= start - minLimit;
        pos.limit = limit;
        pos.contextLimit -= start - minLimit;
        pos.start = (pos.pos += start - minLimit);
        outFrontier = true;
        start = minLimit;
    }

    int delta = 0;
    while (start < limit) {
        int c = text.char32At(start);
        int delta2 = transliterator.transliterate(text, pos, c, incremental);
        if (delta2 != 0 || c >= 0x10000) {
            // Something changed or was inserted.  We need
            // to increment all indexes by delta, and re-do
            // the filter step if the character is new.
            if (!filter.contains(c)) {
                start += UTF16.getCharCount(c);
                limit += delta2;
                pos.contextLimit += delta2;
            } else {
                start += UTF16.getCharCount(c);
            }
            limit += delta2;
            pos.contextLimit += delta2;
            pos.start += delta;
            delta += delta2;
        } else {
            start += UTF16.getCharCount(c);
        }
    }

    if (!outFrontier && delta != 0) {
        pos.start += delta;
    }

    return delta;
}
