import org.osgi.framework.BundleContext;
import org.osgi.framework.FrameworkEvent;
import org.osgi.framework.FrameworkListener;

public class FrameworkWaiter implements FrameworkListener {

    private final Object lock;
    private boolean startLevelChanged;

    public FrameworkWaiter(Object lock) {
        this.lock = lock;
    }

    public void waitForStartLevel(BundleContext context) throws InterruptedException {
        synchronized (lock) {
            startLevelChanged = false;
            context.addFrameworkListener(this);

            while (!startLevelChanged) {
                lock.wait();
            }

            context.removeFrameworkListener(this);
        }
    }

    @Override
    public void frameworkEvent(FrameworkEvent event) {
        if (event.getType() == FrameworkEvent.STARTLEVEL_CHANGED) {
            synchronized (lock) {
                startLevelChanged = true;
                lock.notifyAll();
            }
        }
    }
}
