    for (String topic : topics) {
        try {
            // try to parse integer from topic
            int topicValue = Integer.parseInt(topic);
            integerTopics.add(topicValue);
        } catch (NumberFormatException e) {
            // topic is not an integer
            stringTopics.add(topic);
        }
    }

    // do something with the string and integer topics...
}
