public Observable<PagedList<ComputeNode>> listComputeNodes(String nextPageLink) throws IllegalArgumentException {
    if (nextPageLink == null || nextPageLink.isEmpty()) {
        throw new IllegalArgumentException("NextPageLink cannot be null or empty.");
    }
    return Observable.fromEmitter(emitter -> {
        PagedList<ComputeNode> pagedListResult = new PagedList<>();
        emitter.setCancellation(() -> pagedListResult.clear());
        try {
            while (nextPageLink != null && !nextPageLink.isEmpty()) {
                ComputeNodeListOptions options = new ComputeNodeListOptions();
                options.withNextLink(nextPageLink);
                PagedList<ComputeNode> page = batchClient
                        .getBatchClient()
                        .getComputeNodeOperations()
                        .listComputeNodes(poolId, options);
                pagedListResult.addAll(page);
                nextPageLink = page.getNextPageLink();
            }
            if (pageresult.isEmpty()) {
                emitter.onError(new BatchErrorException(new BatchError().withCode("EmptyResult").withMessage("No results found.")));
            } else {
                emitter.onNext(pagedListResult);
                emitter.onCompleted();
            }
        } catch (Throwable t) {
            emitter.onError(t);
        }
    }, Emitter.BackpressureMode.BUFFER);
}
