                        trace.debug(this,
                                    cclass,
                                    "readheader",
                                    new Object[] { new Integer(instanceVersion), new Byte(sectorByte)
                                                  , new Long(startByteAddress), new Long(fileSize)
                                                  , new Long(headerSequence), new java.util.Date(headerWriteTime) }
