public boolean isPermissionDenied(Activity activity, String... deniedPermissions) {
    // Check if any of the denied permissions is permanently disabled
    for (String deniedPermission : deniedPermissions) {
        if (ActivityCompat.checkSelfPermission(activity, deniedPermission)
                == PackageManager.PERMISSION_DENIED &&
                !ActivityCompat.shouldShowRequestPermissionRationale(activity, deniedPermission)) {
            return true;
        }
    }
    return false;
}
