    CommerceDiscountUserSegmentRel commerceDiscountUserSegmentRel)
    throws PortalException {

    super.delete(commerceDiscountUserSegmentRel);

    if (!CTConstants.PERSISTENCE_MODE_ONLINE.equals(
            getCTPersistenceHelper().getPersistenceMode(
                CommerceDiscountUserSegmentRel.class))) {

        return commerceDiscountUserSegmentRel;
    }

    clearUniqueFindersCache(commerceDiscountUserSegmentRel);

    CommerceDiscountUserSegmentRelModelImpl
        commerceDiscountUserSegmentRelModelImpl =
            (CommerceDiscountUserSegmentRelModelImpl)commerceDiscountUserSegmentRel;

    Session session = null;

    try {
        session = openSession();

        if (commerceDiscountUserSegmentRel.isCachedModel() ||
            BatchSessionUtil.isEnabled()) {

            Object staleObjectDetector =
                session.get(
                    CommerceDiscountUserSegmentRelImpl.class,
                    commerceDiscountUserSegmentRel.getPrimaryKeyObj());

            if (staleObjectDetector != null) {
                session.evict(staleObjectDetector);
            }
        }

        session.delete(commerceDiscountUserSegmentRel);
    }
    catch (Exception e) {
        throw processException(e);
    }
    finally {
        closeSession(session);
    }

    _resourceLocalService.deleteResource(
        commerceDiscountUserSegmentRel.getCompanyId(),
        CommerceDiscountUserSegmentRel.class.getName(),
        ResourceConstants.SCOPE_INDIVIDUAL,
        commerceDiscountUserSegmentRel.getCommerceDiscountUserSegmentRelId());

    return commerceDiscountUserSegmentRel;
}
