public static void normalizeArray(double[] arr) {
    double sum = 0.0;
    for (int i = 0; i < arr.length; i++) {
        sum += arr[i];
    }
    if (Double.isNaN(sum) || sum == 0.0) {
        throw new RuntimeException("Invalid array sum: " + sum);
    }
    for (int i = 0; i < arr.length; i++) {
        arr[i] /= sum;
    }
}
