public int copyToResponse(byte[] buffer, byte[] response, int num, int read) {
    if (read < buffer.length) {
        System.arraycopy(buffer, 0, response, num, read);
        return num + read;
    } else {
        System.arraycopy(buffer, 0, response, num, response.length - num);
        return response.length;
    }
}
