public Node[] doubleNodeArraySize(Node[] oldTable) {
    int oldCapacity = oldTable.length;
    Node[] newTable = new Node[2 * oldCapacity];
    for (int i = 0; i < oldCapacity; i++) {
        Node head = oldTable[i];
        if (head != null) {
            oldTable[i] = null;
            do {
                Node next = head.next;
                int newIndex = head.hashCode() % (2 * oldCapacity);
                head.next = newTable[newIndex];
                newTable[newIndex] = head;
                head = next;
            } while (head != null);
        }
    }
    return newTable;
}
