public Annotation findAnnotation(Class<?> type, List<Annotation> annotations, Class<? extends Annotation> annotation) {
    Annotation result = null;
    for (Annotation anno : annotations) {
        if (annotation.equals(anno.annotationType())) {
            result = anno;
            break;
        }
    }
    if (result == null) {
        result = type.getAnnotation(annotation);
    }
    return result;
}
