public boolean readUTFLong(byte[] raw) throws IOException {
    long val = 0;
    int shift = 0;
    boolean isValid = true;
    for(int i = 0; i < 8; i++) {
        int b = in.read();
        if(b == -1) {
            throw new IOException("Unexpected end of input stream");
        }
        if(i == 0 && raw != null) {
            raw[i] = (byte) b;
        }
        if((b & 0x80) == 0) {
            if(i == 0 && b == 0xff) {
                isValid = false;
            }
            val |= ((long) b) << shift;
            break;
        }
        val |= ((long) (b & 0x7f)) << shift;
        shift += 7;
        if(i == 6 && (b & 0xfe) != 0xfe) {
            isValid = false;
        }
    }
    if(raw != null) {
        for(int i = 1; i < 8; i++) {
            int b = (int) (val >>> (8 * i));
            raw[i] = (byte) b;
        }
    }
    return isValid && (val != 0xffffffffffffffffL);
}
