public static int computeFinalWidth(FontMetrics fm, String text, int wordSpacing) {
    int width = fm.stringWidth(text);
    int spaces = text.length() - text.replace(" ", "").length();
    int spaceWidth = fm.stringWidth(" ");
    int totalSpacingWidth = spaces * (spaceWidth + wordSpacing);

    return width + totalSpacingWidth;
}
