public boolean handleException(Exception e, Object run, Object listener) throws Exception {
    try {
        // log the exception
        LOGGER.error("Exception caught: ", e);

        // call the listener to handle the exception
        if (listener != null) {
            if (listener instanceof ExceptionHandlerListener) {
               if (((ExceptionHandlerListener) listener).handleException(e, run)) {
                    return true;
                }
            }
        }

        // call the run object to handle the exception
        if (run != null) {
            if (run instanceof ExceptionHandler) {
                if (((ExceptionHandler) run).handleException(e)) {
                    return true;
                }
            }
        }

        // re-throw the exception to upper-level 
        throw e;
    } catch (Exception ex) {
        // do any necessary processing for the exception, e.g. printStackTrace
        ex.printStackTrace();
    }

    return false;
}
