import java.beans.PropertyDescriptor;
import java.util.ArrayList;
import java.util.List;
import java.lang.reflect.Field;
import java.lang.reflect.Modifier;

public static List<PropertyDescriptor> getFieldsAsProperties(Object obj, Class<?>[] clazzes){
    List<PropertyDescriptor> propertyDescriptors = new ArrayList<>();

    Field[] fields = getAllFields(obj.getClass(), clazzes);

    for(Field field : fields){
        try {
            PropertyDescriptor propertyDescriptor = new PropertyDescriptor(field.getName(), obj.getClass());
            propertyDescriptors.add(propertyDescriptor);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    return propertyDescriptors;
}

private static Field[] getAllFields(Class<?> objClass, Class<?>[] clazzes){
    List<Field> fields = new ArrayList<>();
    for(Class<?> clazz : clazzes){
        fields.addAll(getDeclaredFields(objClass, clazz));
    }
    return fields.toArray(new Field[fields.size()]);
}

private static List<Field> getDeclaredFields(Class<?> objClass, Class<?> clazz){
    List<Field> fields = new ArrayList<>();
    for(Field field : objClass.getDeclaredFields()){
        if(field.getType().equals(clazz) && Modifier.isPrivate(field.getModifiers())){
            field.setAccessible(true);
            fields.add(field);
        }
    }
    return fields;
}
