public void openReceiveServer() throws Exception {
    // Set up socket and input/output streams
    int portNumber = 12345; // replace with desired port number
    ServerSocket serverSocket = new ServerSocket(portNumber);
    Socket clientSocket = serverSocket.accept();
    PrintWriter out = new PrintWriter(clientSocket.getOutputStream(), true);
    BufferedReader in = new BufferedReader(new InputStreamReader(clientSocket.getInputStream()));

    // Receive input from client
    String inputLine;
    while ((inputLine = in.readLine()) != null) {
        // Process input as needed
        System.out.println("Received input: " + inputLine);

        // Send response back to client
        String response = "Response to client: " + inputLine;
        out.println(response);
        System.out.println("Sent response: " + response);
    }

    // Close connections
    out.close();
    in.close();
    clientSocket.close();
    serverSocket.close();
}
