public boolean isValidLocation(Mover mover, int sx, int sy, int x, int y) {
    // Check if the difference in x and y coordinates is less than or equal to the mover's range
    int xDiff = Math.abs(sx - x);
    int yDiff = Math.abs(sy - y);
    if (xDiff + yDiff <= mover.getRange()) {
        // Check if the location is not occupied by an obstacle or another mover
        if (grid.isBlocked(x, y) || grid.isOccupied(x, y)) {
            return false;
        }
        return true;
    }
    return false;
}
