public AtomContainer cleanMolecule(AtomContainer molecule) {
    // Remove any atoms that have no element symbol
    for (Atom atom : molecule.atoms()) {
        if (atom.getSymbol() == null) {
            molecule.removeAtomAndConnectedElectronContainers(atom);
        }
    }

    // Remove any bonds that have both ends pointing to the same atom
    for (Bond bond : molecule.bonds()) {
        if (bond.length() == 0) {
            molecule.removeBondAndConnectedElectronContainers(bond);
        }
    }

    // Return the cleaned molecule
    return molecule;
}
