public class NetscalerClient {

    private static final String BASE_URL = "https://your-netscaler-url.com";

    public static void main(String[] args) throws IOException {
        String token = authenticate(); // replace with your authentication function
        String cipherResources = fetchCipherResources(token);
        System.out.println(cipherResources);
    }

    public static String fetchCipherResources(String token) throws IOException {
        String url = BASE_URL + "/nitro/v1/stat/sslcipher";

        HttpClient client = HttpClientBuilder.create().build();
        HttpGet request = new HttpGet(url);
        request.addHeader("Authorization", "Bearer " + token);

        HttpResponse response = client.execute(request);
        HttpEntity entity = response.getEntity();
        String responseBody = EntityUtils.toString(entity);
        return responseBody;
    }
}
