public void extractResourceFromPluginZip(ZipEntry zipEntry) throws IOException {
    String workDirectoryPath = "/path/to/work/directory/";
    String resourceName = zipEntry.getName();

    File resourceFile = new File(workDirectoryPath + resourceName);

    // If the resource file already exists, just return
    if (resourceFile.exists()) {
        return;
    }

    // Create parent directories if they don't exist
    File parentDirectories = resourceFile.getParentFile();
    if (!parentDirectories.exists()) {
        parentDirectories.mkdirs();
    }

    // Extract resource from ZIP file and save to work directory
    try (InputStream zipInputStream = getClass().getResourceAsStream(resourceName);
         OutputStream resourceOutputStream = new FileOutputStream(resourceFile)) {
        byte[] buffer = new byte[1024];
        int bytesRead;
        while ((bytesRead = zipInputStream.read(buffer)) > 0) {
            resourceOutputStream.write(buffer, 0, bytesRead);
        }
    }
}
