public static List<Integer> distinctAndFilterByOccurrences(List<Integer> input, int occurrencesFilter) {
    Map<Integer, Integer> countMap = new HashMap<>();
    // count occurrences of each element in input
    for (int i : input) {
        countMap.put(i, countMap.getOrDefault(i, 0) + 1);
    }
    // filter elements with occurrence less than or equal to occurrencesFilter
    List<Integer> result = new ArrayList<>();
    for (int i : countMap.keySet()) {
        if (countMap.get(i) > occurrencesFilter) {
            result.add(i);
        }
    }
    return result;
}
