import org.apache.thrift.TException;
import org.apache.thrift.TDeserializer;
import org.apache.thrift.protocol.TBinaryProtocol;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.Base64;

public static ThriftEnvelopeEvent generateThrifTEnvelopeEvent(String type, String payload) throws TException {
    byte[] payloadBytes = Base64.getDecoder().decode(payload); // decode the base64 payload
    TDeserializer deserializer = new TDeserializer(new TBinaryProtocol.Factory()); // create a deserializer
    Object thriftObject = null;
    try {
        thriftObject = Class.forName(type).newInstance(); // create an instance of the Thrift class
        deserializer.deserialize((Object) thriftObject, payloadBytes); // deserialize the payload using the deserializer
    } catch (InstantiationException | IllegalAccessException | ClassNotFoundException e) {
        throw new TException("Invalid Thrift schema name", e); // if the class cannot be instantiated, throw an exception
    }
    if (thriftObject == null) {
        throw new TException("Could not deserialize payload into a Thrift object"); // if the payload cannot be deserialized into a Thrift object, throw an exception
    }
    long timestamp = Instant.now().toEpochMilli(); // get the current timestamp
    return new ThriftEnvelopeEvent(thriftObject, timestamp); // return the ThriftEnvelopeEvent with the Thrift object and the timestamp
}
