import org.apache.log4j.Level;
import org.apache.log4j.Logger;
import org.apache.log4j.jmx.LoggerDynamicMBean;

public class LogLevelManagement {
    private static final String MASTER_LOGGER_NAME = "org.apache.spark.status.AppStatusLogger";
    private static final String WORKER_LOGGER_NAME = "org.apache.spark.network.netty.NettyBlockTransferService";

    /**
     * Sets or gets log level of master and worker through their REST API.
     *
     * @param args same arguments as {@link LogLevel}
     */
    public static void setOrGetLogLevel(String[] args) {
        if (args.length < 1) {
            throw new IllegalArgumentException("Invalid number of arguments");
        }
        LogLevel logLevel = LogLevel.valueOf(args[0].toUpperCase());

        setLogLevel(MASTER_LOGGER_NAME, logLevel);
        setLogLevel(WORKER_LOGGER_NAME, logLevel);
    }

    private static void setLogLevel(String loggerName, LogLevel logLevel) {
        Logger logger = Logger.getLogger(loggerName);

        if (logger != null) {
            LoggerDynamicMBean bean = new LoggerDynamicMBean(logger);
            bean.setLoggerLevel(logLevel.getLog4jLevel());
        }
    }

    public enum LogLevel {
        DEBUG(Level.DEBUG),
        INFO(Level.INFO),
        WARN(Level.WARN),
        ERROR(Level.ERROR),
        FATAL(Level.FATAL);

        private final Level log4jLevel;

        LogLevel(Level log4jLevel) {
            this.log4jLevel = log4jLevel;
        }

        public Level getLog4jLevel() {
            return log4jLevel;
        }
    }
}
