public class Builder<T> {
    private final Supplier<T> instanceSupplier;

    private Builder(Supplier<T> instanceSupplier) {
        this.instanceSupplier = instanceSupplier;
    }

    public static <T> Builder<T> create(Supplier<T> instanceSupplier) {
        return new Builder<>(instanceSupplier);
    }

    public static <T> Builder<T> create(Class<T> clazz) {
        return create(() -> {
            try {
                return clazz.getDeclaredConstructor().newInstance();
            } catch (InstantiationException | IllegalAccessException | NoSuchMethodException | InvocationTargetException e) {
                throw new RuntimeException("Unable to create instance.", e);
            }
        });
    }

    public T build() {
        return instanceSupplier.get();
    }
}
