public List<String> splitInRange(String str, String delim, int start, int end) {
    List<String> result = new ArrayList<>();
    if (str == null || str.isEmpty() || start > end) {
        return result;
    }
    String[] splitArray = str.split(delim, -1);
    for (int i = start; i <= end && i < splitArray.length; i++) {
        result.add(splitArray[i]);
    }
    return result;
}
