public double evaluateClustering(Database db, Instances rel, Cluster[] c) {
    double ssq = 0.0;
    for (int i = 0; i < rel.numInstances(); i++) {
        int clusterIndex = c[0].clusterInstance(rel.instance(i));
        double[] centroid = c[clusterIndex].getCentroid();
        ssq += Math.pow(distance(rel.instance(i), centroid), 2.0);
    }
    return ssq;
}

private double distance(Instance a, double[] b) {
    double sum = 0.0;
    for (int i = 0; i < a.numAttributes(); i++) {
        double diff = a.value(i) - b[i];
        sum += diff * diff;
    }
    return Math.sqrt(sum);
}
