public void joinAllInterfaces() {
    Enumeration<NetworkInterface> interfaces = NetworkInterface.getNetworkInterfaces();
    while (interfaces.hasMoreElements()) {
        NetworkInterface currentInterface = interfaces.nextElement();
        if (currentInterface.isUp() && !currentInterface.isLoopback()) {
            Enumeration<InetAddress> addresses = currentInterface.getInetAddresses();
            while (addresses.hasMoreElements()) {
                InetAddress address = addresses.nextElement();
                if (address instanceof Inet4Address) {
                    try {
                        MulticastSocket socket = new MulticastSocket();
                        socket.setInterface(address);
                        socket.joinGroup(InetAddress.getByName("224.0.0.251")); // join multicast group
                        byte[] buffer = new byte[4096];
                        DatagramPacket packet = new DatagramPacket(buffer, buffer.length);
                        socket.receive(packet); // wait for multicast responses
                        String message = new String(packet.getData(), 0, packet.getLength());
                        System.out.println("Received message: " + message);
                        socket.leaveGroup(InetAddress.getByName("224.0.0.251")); // leave multicast group
                    } catch (IOException e) {
                        e.printStackTrace();
                    }
                }
            }
        }
    }
}
