public static void removeHeadAndTailTagsIfNamedIncludedOrConfiguration(SAXEventRecorder recorder) {
    List<QName> events = recorder.getEvents();
    if (events.size() >= 2) {
        QName headTag = events.get(0);
        QName tailTag = events.get(events.size() - 1);
        if (headTag.getLocalPart().equals("included") || headTag.getLocalPart().equals("configuration")) {
            events.remove(0);
        }
        if (tailTag.getLocalPart().equals("included") || tailTag.getLocalPart().equals("configuration")) {
            events.remove(events.size() - 1);
        }
    }
}
