public Schema createSchema(JAXBContext context) throws IOException, SAXException {
    final SchemaOutputResolver resolver = new SchemaOutputResolver() {
        @Override
        public Result createOutput(String namespaceUri, String suggestedFileName) throws IOException {
            return new StreamResult(new File(suggestedFileName));
        }
    };
    final List<ByteArrayOutputStream> schemas = new ArrayList<>();
    context.generateSchema(resolver);
    for (File schema : resolver.getSchemaFiles()) {
        final ByteArrayOutputStream bos = new ByteArrayOutputStream();
        final FileInputStream fis = new FileInputStream(schema);
        byte[] buffer = new byte[1024];
        int read;
        while ((read = fis.read(buffer)) != -1) {
            bos.write(buffer, 0, read);
        }
        fis.close();
        bos.close();
        schemas.add(bos);
    }
    final Source[] schemaSources = new StreamSource[schemas.size()];
    for (int i = 0; i < schemaSources.length; i++) {
        schemaSources[i] = new StreamSource(new ByteArrayInputStream(schemas.get(i).toByteArray()));
    }
    final SchemaFactory schemaFactory = SchemaFactory.newInstance(XMLConstants.W3C_XML_SCHEMA_NS_URI);
    return schemaFactory.newSchema(schemaSources);
}
