public void skipBytesIfNeeded(BinaryRow row, int bytes) {
    if (row.getSizeInBytes() + bytes > row.getSegment().size()) {
        int numBytesToSkip = row.getSegment().size() - row.getSizeInBytes();
        row.getSegment().skipBytes(numBytesToSkip);
    }
}
