public List<Integer> produceRandomSample(List<Integer> source, int except, int k, Random random) {
    List<Integer> newDBIDs = new ArrayList<>();
    Set<Integer> visited = new HashSet<>();

    // Add the excluded object to the visited set
    visited.add(except);

    // Shuffle the source list
    Collections.shuffle(source, random);

    // Iterate through the shuffled source list
    for (int i = 0; i < source.size(); i++) {
        int dbId = source.get(i);

        // If the current dbId is not in the visited set and not equal to the excluded object
        if (!visited.contains(dbId) && dbId != except) {
            // Add the current dbId to the visited set and to the newDBIDs list
            visited.add(dbId);
            newDBIDs.add(dbId);

            // If the size of the newDBIDs list is equal to k, break out of the loop
            if (newDBIDs.size() == k) {
                break;
            }
        }
    }

    return newDBIDs;
}
