public String getReasonFromX509Entry(X509Certificate entry) {
    try {
        boolean[] keyUsage = entry.getKeyUsage();
        if (keyUsage != null && keyUsage.length > 6 && keyUsage[6]) {
            // keyUsage[6] corresponds to the "Certificate signing" bit
            return "Certificate signing";
        }
        // if no reason is found, return null
        return null;
    } catch (CertificateParsingException e) {
        // handle exception
        return null;
    }
}
