public static int[] removeValue(int[] arr, int value) {
    int index = -1;
    for (int i = 0; i < arr.length; i++) {
        if (arr[i] == value) {
            index = i;
            break;
        }
    }
    if (index == -1) {
        return arr;
    }
    int[] newArr = new int[arr.length - 1];
    int j = 0;
    for (int i = 0; i < arr.length; i++) {
        if (i != index) {
            newArr[j] = arr[i];
            j++;
        }
    }
    return newArr;
}
