public Table lookForCommonTableByName(String tableName) {
    // start by looking for the table in the current scope
    Table table = getCurrentScope().getTable(tableName);

    // if it's not found, look in parent scopes
    if (table == null) {
        Scope parentScope = getCurrentScope().getParentScope();
        while (parentScope != null) {
            table = parentScope.getTable(tableName);
            if (table != null) {
                break;
            }
            parentScope = parentScope.getParentScope();
        }
    }

    // return the table found (or null if not found)
    return table;
}
