public List<PathInfo> getPathsInfo(List<Path> paths) throws IOException {
    List<PathInfo> pathsInfo = new ArrayList<>();
    BasicFileAttributes attrs;
    for (Path path : paths) {
        attrs = Files.readAttributes(path, BasicFileAttributes.class);
        pathsInfo.add(new PathInfo(path, attrs.creationTime(), attrs.lastModifiedTime(), attrs.size()));
    }
    return pathsInfo;
}

