public boolean canUserAccountBeLocked(CMSContext cms, User user) {
    int inactivityThreshold = 30; // inactivity threshold in minutes
    Calendar now = Calendar.getInstance();
    now.setTime(new Date());
    Calendar lastActivity = Calendar.getInstance();
    lastActivity.setTime(user.getLastActivityDate());
    long diffInMinutes = (now.getTimeInMillis() - lastActivity.getTimeInMillis()) / (60 * 1000); // difference in minutes

    if (diffInMinutes >= inactivityThreshold) {
        return true; // user can be locked
    }
    return false; // user cannot be locked
}
