public void processUserElements(ConfigurationAdmin configAdmin, String roleName, Dictionary<String, Object> roleProps, String[] pids) {
    try {
        Configuration config = configAdmin.getConfiguration(roleName, null);
        Dictionary<String, Object> properties = config.getProperties() != null ? new Hashtable<>(config.getProperties()) : new Hashtable<>();

        for (String pid : pids) {
            Configuration pidConfig = configAdmin.getConfiguration(pid, null);
            Dictionary<String, Object> pidProps = pidConfig.getProperties();
            if (pidProps != null) {
                Enumeration<String> keys = pidProps.keys();
                while (keys.hasMoreElements()) {
                    String key = keys.nextElement();
                    properties.put(key, pidProps.get(key));
                }
            }
        }

        if (!properties.equals(config.getProperties())) {
            config.update(properties);
        }
    } catch (Exception e) {
        e.printStackTrace();
    }
}
