public void logHexDump(byte[] data) {
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < data.length; i++) {
        sb.append(String.format("%02X ", data[i]));
        if ((i + 1) % 16 == 0) {
            sb.append("\n");
        }
    }
    System.out.println(sb.toString());
}
