import java.awt.image.BufferedImage;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.ConvolveOp;
import java.awt.image.Kernel;

public static BufferedImage applyGaussianBlur(BufferedImage src, BufferedImage dst, int radius) {
    int size = radius * 2 + 1;
    float weight = 1.0f / (size * size);
    float[] data = new float[size * size];

    for (int i = 0; i < data.length; i++) {
        data[i] = weight;
    }

    BufferedImage blurredImage = dst;

    if (blurredImage == null) {
        blurredImage = new BufferedImage(src.getWidth(), src.getHeight(), BufferedImage.TYPE_INT_ARGB);
    }

    Graphics2D g2d = blurredImage.createGraphics();
    g2d.drawImage(src, 0, 0, null);
    g2d.dispose();

    Kernel kernel = new Kernel(size, size, data);
    ConvolveOp op = new ConvolveOp(kernel, ConvolveOp.EDGE_NO_OP, null);
    blurredImage = op.filter(blurredImage, null);

    return blurredImage;
}
