public void printPercentileHistogram(PrintStream out, String name, double[] p) {
   int[] array = new int[p.length];
   for(int i = 0; i < dataset.length; i++) {
       for(int j = 0; j < p.length; j++) {
           if(dataset[i] <= p[j]) {
               array[j]++;
           }
       }
   }
   out.println("Histogram of Percentiles for dataset: " + name);
   for(int i = 0; i < p.length; i++) {
       out.printf("%d%%: %s%n", (int)(p[i] * 100), "*".repeat(array[i]));
   }
}
