public static Object createInstance(Class<?> type, Object... parameters) throws Exception {
    Constructor<?> constructor = type.getDeclaredConstructor(getParameterTypes(parameters));
    constructor.setAccessible(true);
    return constructor.newInstance(parameters);
}

private static Class<?>[] getParameterTypes(Object[] parameters) {
    Class<?>[] parameterTypes = new Class<?>[parameters.length];
    for (int i = 0; i < parameters.length; i++) {
        parameterTypes[i] = parameters[i].getClass();
    }
    return parameterTypes;
}
