                work.length, info);
        for (MatrixEntry e : Afact) {
            if (e.column() < Q.numColumns())
                Q.set(e.row(), e.column(), e.get());
        }
        if (info.val < 0)
            throw new IllegalArgumentException();

        for (int i = 0; i < jpvt.length; i++) {
            --jpvt[i];
        }
        return this;
