import io.netty.bootstrap.ServerBootstrap;
import io.netty.channel.Channel;
import io.netty.channel.ChannelOption;
import io.netty.channel.EventLoopGroup;
import io.netty.channel.socket.nio.NioServerSocketChannel;

public class TcpServer {
    private final EventLoopGroup acceptGroup;
    private final EventLoopGroup clientGroup;
    private final Channel serverChannel;

    public TcpServer(SocketAddress socketAddress, EventLoopGroup acceptGroup,
                     EventLoopGroup clientGroup, Class<? extends Channel> channelClass) {
        this.acceptGroup = acceptGroup;
        this.clientGroup = clientGroup;

        ServerBootstrap serverBootstrap = new ServerBootstrap()
                .channel(channelClass)
                .group(acceptGroup, clientGroup)
                .childHandler(new ServerChannelInitializer())
                .option(ChannelOption.TCP_NODELAY, true)
                .childOption(ChannelOption.SO_KEEPALIVE, true);

        serverChannel = serverBootstrap.bind(socketAddress).syncUninterruptibly().channel();
    }

    public void stop() {
        serverChannel.close();
        acceptGroup.shutdownGracefully();
        clientGroup.shutdownGracefully();
    }
}
