public byte[] constructBodyPartFromApplicationData(byte[] applicationData, String contentType) throws IOException {
    if (contentType.startsWith("text")) {
        return new String(applicationData).getBytes(StandardCharsets.UTF_8);
    } else if (contentType.startsWith("image")) {
        return applicationData;
    } else {
        return Base64.getDecoder().decode(new String(applicationData));
    }
}
