public Map<String, Double> aggregateStats(int lowerLevel, int upperLevel, List<Stat> stats) {
    Map<String, List<Double>> statsMap = new HashMap<>();
    for (Stat stat : stats) {
        if (stat.getLevel() >= lowerLevel && stat.getLevel() <= upperLevel) {
            if (stat.getType().equals(Type.TIME_BASED)) {
                if (!statsMap.containsKey(stat.getName())) {
                    statsMap.put(stat.getName(), new ArrayList<>());
                }
                statsMap.get(stat.getName()).add(stat.getValue());
            }
            if (stat.getType().equals(Type.MAX_VALUE)) {
                if (!statsMap.containsKey(stat.getName())) {
                    statsMap.put(stat.getName(), new ArrayList<>());
                }
                Double previousMaxValue = statsMap.get(stat.getName()).stream().max(Double::compare).orElse(Double.NEGATIVE_INFINITY);
                statsMap.get(stat.getName()).add(Math.max(previousMaxValue, stat.getValue()));
            }
        }
    }
    return statsMap.entrySet().stream().collect(Collectors.toMap(Map.Entry::getKey, e -> {
        List<Double> values = e.getValue();
        Double sum = values.stream().reduce(0.0, Double::sum);
        return e.getKey().equals(Type.TIME_BASED.name()) ? sum / values.size() : values.get(values.size() - 1);
    }));
}
