public void encodeInputStreamToOutputStream(InputStream is, OutputStream os, int estimate) throws IOException {
    byte[] buffer = new byte[estimate];
    int length;

    while ((length = is.read(buffer)) != -1) {
        os.write(buffer, 0, length);
    }

    is.close();
    os.close();
}
