public Set<User> getUsersByNameAndRole(String name, String role) {
  Set<User> users = new HashSet<>();
  for (User user : getAllUsers()) {
    if (role == null || user.getRole().equals(role)) {
      if (name == null || user.getFirstName().contains(name) || user.getLastName().contains(name)) {
        users.add(user);
      }
    }
  }
  return users;
}
