    private int age;

    public Element(String name, int age) {
        this.name = name;
        this.age = age;
    }

    public String getName() {
        return name;
    }

    public int getAge() {
        return age;
    }
}

public class PropertyInfo {
    private String propertyName;
    private Class<?> propertyType;
    private Object propertyValue;

    public PropertyInfo(String propertyName, Class<?> propertyType, Object propertyValue) {
        this.propertyName = propertyName;
        this.propertyType = propertyType;
        this.propertyValue = propertyValue;
    }

    public String getPropertyName() {
        return propertyName;
    }

    public Class<?> getPropertyType() {
        return propertyType;
    }

    public Object getPropertyValue() {
        return propertyValue;
    }
}

public List<PropertyInfo> getPropertyInfoList(List<Element> elements) {
    List<PropertyInfo> propertyInfoList = new ArrayList<>();

    for (Element element : elements) {
        Class<?> elementClass = element.getClass();

        for (java.lang.reflect.Field field : elementClass.getDeclaredFields()) {
            try {
                field.setAccessible(true);
                propertyInfoList.add(new PropertyInfo(field.getName(), field.getType(), field.get(element)));
            } catch (IllegalAccessException e) {
                e.printStackTrace();
            }
        }
    }

    return propertyInfoList;
}
