public static void trainAndWriteModel(String[] args) throws IOException {
    String eventFile = args[0];
    int iterations = 100;
    int cutoff = 5;
    if (args.length > 1) {
        iterations = Integer.parseInt(args[1]);
    }
    if (args.length > 2) {
        cutoff = Integer.parseInt(args[2]);
    }
    String modelFile = eventFile + ".model";
    EventStream eventStream = new FileEventStream(new File(eventFile));
    ObjectStream<Event> es = new EventStreamIterator(eventStream);
    Map<String, String> trainParams = new HashMap<>();
    trainParams.put(TrainingParameters.ALGORITHM_PARAM, "MAXENT");
    trainParams.put(TrainingParameters.ITERATIONS_PARAM, String.valueOf(iterations));
    trainParams.put(TrainingParameters.CUTOFF_PARAM, String.valueOf(cutoff));
    TrainerFactory trainerFactory = new EventTrainerFactory();
    MaxentModel model = (new opennlp.tools.ml.maxent.GISTrainer()).trainModel(es, trainerFactory, trainParams);
    FileOutputStream modelOutFile = new FileOutputStream(modelFile);
    model.serialize(modelOutFile);
}
