public String resolveClientIdAndExpression(FacesContext context, UIComponent source, String expression) {
    if (expression == null || expression.isEmpty()) {
        return "";
    }

    String result = expression.trim();

    if (result.startsWith("@")) {
        // passthrough expression
        result = result.replaceFirst("@", "");
    } else {
        // client id expression
        String separatorChar = Character.toString(UINamingContainer.getSeparatorChar(context));
        String resultToFind = source.getId() + separatorChar;
        int indexOfResult = result.indexOf(resultToFind);

        if (indexOfResult == -1) {
            // the source component id was not found, so just return the expression
            return result;
        }

        // remove the source component id and separator from the expression
        result = result.substring(indexOfResult + resultToFind.length());

        // if the expression is empty now, just return the separator char
        if (result.isEmpty()) {
            return separatorChar;
        }
    }

    return result;
}
