public class MyHttpRequest {

    public static void getRequest(String path, Map<String, String> params) throws IOException, RESTException {
        String requestURL = buildRequestURL(path, params);
        URL url = new URL(requestURL);
        HttpURLConnection con = (HttpURLConnection) url.openConnection();
        con.setRequestMethod("GET");
        int responseCode = con.getResponseCode();
        if (responseCode != HttpURLConnection.HTTP_OK) {
            throw new RESTException("Error - HTTP response code: " + responseCode);
        }
        // handle entity parsing here
    }

    private static String buildRequestURL(String path, Map<String, String> params) {
        StringBuilder sb = new StringBuilder(path);
        if (params != null && !params.isEmpty()) {
            sb.append("?");
            for (Map.Entry<String, String> entry : params.entrySet()) {
                sb.append(entry.getKey()).append("=").append(entry.getValue()).append("&");
            }
            sb.deleteCharAt(sb.length() - 1);
        }
        return sb.toString();
    }

}

class RESTException extends Exception {
    public RESTException(String message) {
        super(message);
    }
}
