public final void translate(CharSequence input, Writer out) throws IOException {
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (Character.isHighSurrogate(c)) {
            if (++i == input.length()) {
                throw new IllegalArgumentException("High surrogate at end of input");
            }
            char c2 = input.charAt(i);
            if (!Character.isLowSurrogate(c2)) {
                throw new IllegalArgumentException("Expected low surrogate but got char '"+c2+"' at index "+i);
            }
            out.write(c);
            out.write(c2);
        } else if (Character.isLowSurrogate(c)) {
            throw new IllegalArgumentException("Unexpected low surrogate character '"+c+"' at index "+i);
        } else {
            out.write(c);
        }
    }
}
