public <T> void performActionOnError(Consumer<Throwable> onError, long emissionCount) {
    Observable.create(emitter -> {
       // some code to emit observables
       // ...

       // throw an exception after emissionCount
       if (emissionCount == 0) {
           throw new Exception("Error occurred after " + emissionCount + " emissions");
       }

       emitter.onComplete();
    })
    .subscribe(
        result -> {
            // do something with the result
            // ...
        },
        error -> {
            // perform action on error with the provided emission count
            onError.accept(error);
        }
    );
}
