public int getMinutesPerYear(Calendar calendar) {
    if (calendar == null) {
        throw new IllegalArgumentException("Calendar cannot be null");
    }
    int year = calendar.get(Calendar.YEAR);
    if (calendar instanceof GregorianCalendar) {
        if (((GregorianCalendar) calendar).isLeapYear(year)) {
            return 366 * 24 * 60;
        } else {
            return 365 * 24 * 60;
        }
    }
    return calendar.getActualMaximum(Calendar.DAY_OF_YEAR) * 24 * 60;
}
