public boolean applyMaskAndCompare(byte[] mask, byte[] other) {
    if (mask.length != other.length) {
        return false;
    }
    for (int i = 0; i < mask.length; i++) {
        if ((mask[i] & other[i]) != mask[i]) {
            return false;
        }
    }
    return true;
}
