public static TypeVariable<?>[] formalTypeParametersFromClass(Class<?> adaptorClass) {
    Type eventFieldType = null;
    try {
        Field eventField = adaptorClass.getField("event");
        eventFieldType = eventField.getGenericType();
    } catch (NoSuchFieldException e) {
        // handle the exception
    }

    Type[] genericInterfaces = adaptorClass.getGenericInterfaces();
    for (Type type : genericInterfaces) {
        if (type instanceof ParameterizedType) {
            ParameterizedType parameterizedType = (ParameterizedType) type;
            Type rawType = parameterizedType.getRawType();
            if (rawType instanceof Class && EventSet.class.isAssignableFrom((Class<?>) rawType)) {
                Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
                if (eventFieldType != null && eventFieldType.equals(actualTypeArguments[1])) {
                    Type[] formalTypeParameters = ((Class<?>) rawType).getTypeParameters();
                    if (formalTypeParameters != null && formalTypeParameters.length > 0) {
                        TypeVariable<?>[] typeVariables = new TypeVariable<?>[formalTypeParameters.length];
                        for (int i = 0; i < formalTypeParameters.length; i++) {
                            typeVariables[i] = (TypeVariable<?>) formalTypeParameters[i];
                        }
                        return typeVariables;
                    }
                }
            }
        }
    }
    return null;
}
