import com.google.errorprone.ErrorProneOptions;
import com.sun.source.util.JavacTask;

import javax.annotation.Nullable;
import javax.lang.model.element.AnnotationMirror;
import javax.lang.model.element.TypeElement;
import javax.tools.Diagnostic;
import javax.tools.JavaFileManager;
import javax.tools.JavaFileObject;
import javax.tools.StandardLocation;
import javax.tools.ToolProvider;

public class ErrorProneVisitorState {

  private final JavacTask task;
  private final ErrorProneOptions options;

  private ErrorProneVisitorState(JavacTask task, ErrorProneOptions options) {
    this.task = task;
    this.options = options;
  }

  public static ErrorProneVisitorState create(String... args) {
    JavacTask task = null;
    try {
      task = ToolProvider.getSystemJavaCompiler()
                         .getTask(null, null, null, null, null, null);
    } catch (Throwable t) {
      // gracefully degrade on a headless environment
      return null;
    }
    ErrorProneOptions opts = ErrorProneOptions.processArgs(args);
    return new ErrorProneVisitorState(task, opts);
  }

  @Nullable
  public TypeElement getTypeFromString(String fullyQualifiedName) {
    String[] parts = fullyQualifiedName.split("\\.");
    JavaFileManager fileManager = task.getContext()
                                         .get(JavaFileManager.class);
    try {
      JavaFileObject fileObject = fileManager.getJavaFileForInput(
          StandardLocation.PLATFORM_CLASS_PATH,
          parts[0],
          JavaFileObject.Kind.SOURCE);
      return task.parse().getElement(fileObject, fullyQualifiedName);
    } catch (Exception e) {
      return null;
    }
  }

  public boolean isSuppressWarnings(AnnotationMirror annotation) {
    return options.isExcluded(annotation);
  }

  public void reportMatch(Diagnostic<? extends JavaFileObject> diagnostic) {
    task.getTaskListener()
        .report(new ErrorProneDiagnostic(diagnostic, options));
  }
}
