public static Class<?> extractElementType(Type type, Object item) {
    if (type == null) {
        return null;
    }
    if (type instanceof Class) {
        return (Class<?>) type;
    }
    if (type instanceof ParameterizedType) {
        Type[] typeArguments = ((ParameterizedType) type).getActualTypeArguments();
        if (typeArguments.length == 1) {
            return extractElementType(typeArguments[0], item);
        }
    }
    if (type instanceof GenericArrayType) {
        Type componentType = ((GenericArrayType) type).getGenericComponentType();
        if (item instanceof List) {
            List<?> itemList = (List<?>) item;
            if (!itemList.isEmpty()) {
                Object firstItem = itemList.get(0);
                if (firstItem != null) {
                    Class<?> itemType = firstItem.getClass();
                    return Array.newInstance(itemType, 0).getClass();
                }
            }
        } else if (item instanceof Object[]) {
            Object[] array = (Object[]) item;
            if (array.length > 0) {
                Object firstItem = array[0];
                if (firstItem != null) {
                    Class<?> itemType = firstItem.getClass();
                    return Array.newInstance(itemType, 0).getClass();
                }
            }
        }
    }
    return Object.class;
}
