public Group findGroup(String fullName) {
    if (fullName == null || fullName.isEmpty()) {
        return rootGroup; //assuming that rootGroup is a predefined variable representing the root group
    }

    String[] groupNames = fullName.split("/");
    Group currentGroup = rootGroup;

    for (String groupName : groupNames) {
        currentGroup = currentGroup.getSubgroup(groupName);
        if (currentGroup == null) {
            return null;
        }
    }

    return currentGroup;
}
