public RLPObject readRLPData(ByteBuffer bb) {
    byte[] prefix = new byte[1];
    bb.get(prefix);

    if (prefix[0] <= RLPElement.LAST_SINGLE_BYTE) {
        // single byte value
        return new RLPElement(prefix);
    } else if (prefix[0] <= RLPElement.LAST_LONG) {
        // short string
        int len = prefix[0] - RLPElement.LAST_SINGLE_BYTE;
        byte[] data = new byte[len];
        bb.get(data);
        return new RLPElement(data);
    } else if (prefix[0] < RLPList.LAST_SHORT_ITEM) {
        // long string
        int lenlen = prefix[0] - RLPElement.LAST_LONG;
        int len = byteArrayToInt(Arrays.copyOfRange(bb.array(), bb.position(), bb.position() + lenlen));
        bb.position(bb.position() + lenlen);
        byte[] data = new byte[len];
        bb.get(data);
        return new RLPElement(data);
    } else if (prefix[0] <= RLPList.LAST_SHORT_ITEM) {
        // short list
        int len = prefix[0] - RLPList.LAST_SHORT_ITEM;
        RLPList list = new RLPList();
        for (int i = 0; i < len; i++) {
            list.add(readRLPData(bb));
        }
        return list;
    } else {
        // long list
        int lenlen = prefix[0] - RLPList.LAST_LONG;
        int len = byteArrayToInt(Arrays.copyOfRange(bb.array(), bb.position(), bb.position() + lenlen));
        bb.position(bb.position() + lenlen);
        RLPList list = new RLPList();
        int end = bb.position() + len;
        while (bb.position() < end) {
            list.add(readRLPData(bb));
        }
        return list;
    }
}
