import java.io.*;

public class SigmetReader {

    private static final int GLOBAL_DATA_START = 1024; // assuming global data starts at byte position 1024
    private static final int GLOBAL_DATA_LENGTH = 512; // assuming global data length is 512 bytes

    public static byte[] readGlobalData(String filename) throws IOException {
        byte[] data = new byte[GLOBAL_DATA_LENGTH];
        try (RandomAccessFile file = new RandomAccessFile(filename, "r")) {
            file.seek(GLOBAL_DATA_START);
            file.read(data);
        }
        return data;
    }
}
