public CompiledStatement getCompiledStatement(Session session, int csid) {
    // First, check if the CompiledStatement object exists in the session
    CompiledStatement compiledStatement = session.getCompiledStatement(csid);

    // If it doesn't exist, return null
    if (compiledStatement == null) {
        return null;
    }

    // If it does exist, check if it has been invalidated
    if (compiledStatement.isInvalid()) {
        return null;
    }

    // If it hasn't been invalidated, return the CompiledStatement object
    return compiledStatement;
}
