public void addTimeBasedUuidToEntries(Map<String, Object> entries, boolean updateRdn) throws Exception {
    UUID uuid;
    for(Map.Entry<String, Object> entry : entries.entrySet()) {
        uuid = UUID.randomUUID();
        if(updateRdn) {
            // Update RDN with UUID
            entry.setValue(uuid.toString());                
        } else {
            // Add UUID to entry
            entry.put("uuid", uuid.toString());
        }
    }
}
