public int castSQLTypeToInt(String strType) throws DatabaseException {
    switch(strType.toUpperCase()) {
        case "VARCHAR":
            return Types.VARCHAR;
        case "CHAR":
            return Types.CHAR;
        case "INTEGER":
            return Types.INTEGER;
        case "BIGINT":
            return Types.BIGINT;
        case "SMALLINT":
            return Types.SMALLINT;
        case "FLOAT":
            return Types.FLOAT;
        case "DOUBLE":
            return Types.DOUBLE;
        case "BOOLEAN":
            return Types.BOOLEAN;
        case "DATE":
            return Types.DATE;
        case "TIME":
            return Types.TIME;
        case "TIMESTAMP":
            return Types.TIMESTAMP;
        default:
            throw new DatabaseException("Invalid SQL Type");
    }
}
