public void updateMetadata(String directoryName, FileSystem outputFs, CheckSumGenerator checkSumGenerator, Path nodePath, Path metadata) throws IOException {
    // compute the checksum of checksums
    long checksumOfChecksums = checkSumGenerator.computeChecksumOfChecksums(nodePath);

    // compute the total data size
    long totalDataSize = calculateTotalDataSize(directoryName, outputFs);

    // compute the total index size
    long totalIndexSize = calculateTotalIndexSize(directoryName, outputFs);

    // update the metadata file with the computed information
    try (BufferedWriter writer = Files.newBufferedWriter(metadata)) {
        writer.write("Checksum of Checksums: " + checksumOfChecksums + "\n");
        writer.write("Total Data Size: " + totalDataSize + "\n");
        writer.write("Total Index Size: " + totalIndexSize + "\n");
    }
}

private long calculateTotalDataSize(String directoryName, FileSystem outputFs) throws IOException {
    long totalSize = 0;
    Path directory = outputFs.getPath(directoryName);
    try (DirectoryStream<Path> dirStream = Files.newDirectoryStream(directory)) {
        for (Path entry : dirStream) {
            if (Files.isDirectory(entry)) {
                totalSize += calculateTotalDataSize(directoryName + "/" + entry.getFileName().toString(), outputFs);
            } else {
                totalSize += Files.size(entry);
            }
        }
        return totalSize;
    }
}

private long calculateTotalIndexSize(String directoryName, FileSystem outputFs) throws IOException {
    long totalSize = 0;
    Path directory = outputFs.getPath(directoryName);
    try (DirectoryStream<Path> dirStream = Files.newDirectoryStream(directory)) {
        for (Path entry : dirStream) {
            if (Files.isRegularFile(entry) && entry.getFileName().toString().endsWith(".idx")) {
                totalSize += Files.size(entry);
            }
        }
        return totalSize;
    }
}
