public Map<String, String> getStringMap(Map<String, String> map) {
    Map<String, String> utf8Map = new HashMap<>();
    for (Map.Entry<String, String> entry : map.entrySet()) {
        String key = entry.getKey();
        String value = entry.getValue();
        try {
            byte[] encodedKey = key.getBytes(StandardCharsets.UTF_8);
            byte[] encodedValue = value.getBytes(StandardCharsets.UTF_8);
            String utf8Key = new String(encodedKey, StandardCharsets.UTF_8);
            String utf8Value = new String(encodedValue, StandardCharsets.UTF_8);
            utf8Map.put(utf8Key, utf8Value);
        } catch (Exception e) {
            // Handle exception
        }
    }
    return utf8Map;
}
