public Object getConstantFieldValue(Class<?> javaClazz, Field javaField, ClassLoader compileClassLoader, Class<?> fieldType) {
    try {
        Class<?> resolvedClazz = compileClassLoader.loadClass(javaClazz.getFullyQualifiedName());
        Field resolvedField = resolvedClazz.getDeclaredField(javaField.getName());
        if (Modifier.isStatic(resolvedField.getModifiers()) && Modifier.isFinal(resolvedField.getModifiers())) {
            resolvedField.setAccessible(true);
            Object value = resolvedField.get(null);
            if (fieldType.isInstance(value))
                return value;
        }
    } catch (ClassNotFoundException | NoSuchFieldException | IllegalAccessException e) {
        // handle errors
    }
    // return null if constant field value is not found or not of required type.
    return null;
}
