public static double[] reduceArray(String name, double[] x, int... dimensions) {
    int[] shape = new int[dimensions.length];
    int count = 0;
    int reduceSize = 1;
    for (int d : dimensions) {
        reduceSize *= x[d];
        shape[count++] = x[d];
    }

    double[] result = new double[x.length - reduceSize];
    count = 0;
    int reductionIndex = 0;
    for (int i = 0; i < x.length; i++) {
        if (reductionIndex == dimensions.length || i < dimensions[reductionIndex]) {
            result[count++] = x[i];
        } else if (i == dimensions[reductionIndex] + shape[reductionIndex] - 1) {
            reductionIndex++;
        }
    }
    return result;
}
