public int convertBytesToUnsignedInt(RandomAccessFile raf) throws IOException {
    byte[] bytes = new byte[2];
    raf.readFully(bytes); // reads 2 bytes from the given RandomAccessFile
    int val = ((bytes[0] & 0xFF) << 8) | (bytes[1] & 0xFF); // converts bytes to an unsigned int
    return val;
}
