public static Object determineMostPreciseMatch(List<FunctionDeclaration> candidates, List<Argument> args) {
    Object mostPreciseMatch = null;
    for (FunctionDeclaration candidate : candidates) {
        if (candidate.isApplicable(args)) {
            if (mostPreciseMatch == null) {
                mostPreciseMatch = candidate;
            } else if (candidate.isSubtypeOf(mostPreciseMatch)) {
                mostPreciseMatch = candidate;
            }
        }
    }
    return mostPreciseMatch;
}
