public static String crushDiffsIntoEncodedString(List<Diff> diffs) {
    StringBuilder delta = new StringBuilder();
    int deltaInsert = 0;
    int deltaDelete = 0;
    for (Diff aDiff : diffs) {
        switch (aDiff.operation) {
            case INSERT:
                deltaInsert += aDiff.text.length();
                delta.append("+").append(encode(aDiff.text));
                break;
            case DELETE:
                deltaDelete += aDiff.text.length();
                delta.append("-").append(aDiff.text.length());
                break;
            case EQUAL:
                // Upon reaching an equality, check prior equalities
                if (deltaDelete >= 1 || deltaInsert >= 1) {
                    delta.append("=").append(deltaDelete).append("\t")
                            .append(deltaInsert).append("\t");
                    delta.append(diffsToText(diffs.subList(
                            aDiffIndex - deltaDelete - deltaInsert, aDiffIndex)));
                    deltaInsert = 0;
                    deltaDelete = 0;
                }
                break;
        }
    }
    if (deltaDelete >= 1 || deltaInsert >= 1) {
        delta.append("=").append(deltaDelete).append("\t").append(deltaInsert).append("\t");
        delta.append(diffsToText(diffs.subList(diffs.size() - deltaDelete - deltaInsert, diffs.size())));
    }
    return delta.toString();
}

private static String encode(String s) {
    StringBuilder encoded = new StringBuilder();
    for (char ch : s.toCharArray()) {
        if (ch < 0x20 || ch > 0x7E) {
            encoded.append(String.format("%%%02X", (int) ch));
        } else {
            encoded.append(ch);
        }
    }
    return encoded.toString();
}

private static String diffsToText(List<Diff> diffs) {
    StringBuilder text = new StringBuilder();
    for (Diff aDiff : diffs) {
        if (aDiff.operation != Operation.DELETE) {
            text.append(aDiff.text);
        }
    }
    return text.toString();
}

