public ApproximateHistogram constructHistogramFromBuffer(ByteBuffer buf) {
    final int size = buf.getInt();
    final ApproximateHistogram hist = new ApproximateHistogram(size);
    for (int i = 0; i < size; i++) {
        hist.setCountAtIndex(i, buf.getLong());
    }
    hist.setStartTimeSec(buf.getLong());
    hist.setEndTimeSec(buf.getLong());
    hist.setTotalCount(buf.getLong());
    hist.setBucketSize(buf.getDouble());
    return hist;
}
