public double getNaturalAbundanceOfIsotopes(IMolecularFormula formula) {
    double naturalAbundance = 0.0;
    for (IIsotope isotope : formula.isotopes()) {
        Double abundance = isotope.getNaturalAbundance();
        if (abundance != null) {
            naturalAbundance += abundance;
        }
    }
    return naturalAbundance;
}
