public String constructHttpPostBody(Map<String, String> postParams) {
    StringBuilder bodyBuilder = new StringBuilder();
    for (Map.Entry<String, String> entry : postParams.entrySet()) {
        String key = entry.getKey();
        String value = entry.getValue();
        bodyBuilder.append(key).append("=").append(value).append("&");
    }
    // Remove the last "&" character from the body string
    bodyBuilder.setLength(bodyBuilder.length() - 1);
    return bodyBuilder.toString();
}
