public Vector<LoggingEvent> decodeEventsFromString(String document) {
    Vector<LoggingEvent> events = new Vector<LoggingEvent>();
    String[] lines = document.split("\n");

    for (String line : lines) {
        String[] fields = line.split("\\|");

        if (fields.length != 4) {
            continue;
        }

        String loggerName = fields[0];
        Level level = Level.toLevel(fields[1]);
        String message = fields[2];
        long timeStamp = Long.parseLong(fields[3]);

        LoggingEvent event = new LoggingEvent(loggerName, level, message, timeStamp);
        events.add(event);
    }

    return events;
}
