public static boolean isValidRecord(Object record) {
    if(record == null || !(record instanceof Map)) {
        return false;
    }

    Map<?, ?> recordMap = (Map<?, ?>) record;
    for(Map.Entry<?, ?> entry : recordMap.entrySet()) {
        Object key = entry.getKey();
        Object value = entry.getValue();
        if(!(key instanceof String) || !(value instanceof String)) {
            return false;
        }
        if(!isValidTypeTransformationExpression(value.toString())) {
            return false;
        }
    }
    return true;
}

