public static <T> T convertObjectToType(Object target, Class<T> type) {
    if (type.isInstance(target)) {
        return type.cast(target);
    } else {
        String strTarget = target.toString().trim();
        if (type == String.class)
            return type.cast(strTarget);
        else if (type == Integer.class || type == int.class)
            return type.cast(Integer.parseInt(strTarget));
        else if (type == Double.class || type == double.class)
            return type.cast(Double.parseDouble(strTarget));
        else if (type == Long.class || type == long.class)
            return type.cast(Long.parseLong(strTarget));
        else if (type == Boolean.class || type == boolean.class)
            return type.cast(Boolean.parseBoolean(strTarget));
        else if (type == Float.class || type == float.class)
            return type.cast(Float.parseFloat(strTarget));
        else if (type == Byte.class || type == byte.class)
            return type.cast(Byte.parseByte(strTarget));
        else if (type == Character.class || type == char.class)
            return type.cast(strTarget.charAt(0));
        else if (type.isEnum())
            return (T) Enum.valueOf((Class<Enum>) type, strTarget);
        else
            throw new IllegalArgumentException("Cannot convert object to type " + type.getName());
    }
}
