public int[] getChildren(int[] parents, int parent) {
    List<Integer> childrenList = new ArrayList<>();
    for (int i = 0; i < parents.length; i++) {
        if (parents[i] == parent) {
            childrenList.add(i);
        }
    }
    int[] children = new int[childrenList.size()];
    for (int i = 0; i < childrenList.size(); i++) {
        children[i] = childrenList.get(i);
    }
    return children;
}
