public String formatFailureMessage(List<String> messages, List<String> facts){
    StringBuilder failureMessage = new StringBuilder();
    for (String message : messages) {
        failureMessage.append(message).append("\n");
    }
    int maxLength = getMaxFactLength(facts);
    String format = "%" + maxLength + "s: %s%n";
    for (String fact : facts) {
        String[] parts = fact.split(":", 2);
        String key = parts[0];
        String value = parts[1];
        failureMessage.append(String.format(format, key, value));
    }
    return failureMessage.toString();
}

private int getMaxFactLength(List<String> facts) {
    int maxLength = 0;
    for (String fact : facts) {
        String[] parts = fact.split(":", 2);
        int length = parts[0].length();
        if (length > maxLength) {
            maxLength = length;
        }
    }
    return maxLength;
}
