public String addChineseIndexCharacters(String tailoring) {
    String[] indexCharacters = {"一", "二", "三", "四", "五", "六", "七", "八", "九", "十"};
    StringBuilder stringBuilder = new StringBuilder(tailoring.trim());
    for (int i = stringBuilder.length() - 1, j = 0; i >= 0 && j < indexCharacters.length; i--, j++) {
        stringBuilder.insert(i, indexCharacters[j]);
    }
    return stringBuilder.toString();
}
