import java.io.OutputStream;
import java.io.PrintStream;

public class ThreadBoundOutputStream extends OutputStream {
    private final StringBuilder sb = new StringBuilder();

    @Override
    public synchronized void write(int b) {
        char c = (char) b;
        sb.append(c);
        if (c == '\n') {
            flush();
        }
    }

    @Override
    public synchronized void flush() {
        String str = sb.toString();
        if (!str.isEmpty()) {
            // replace '\n' with the platform-specific newline
            str = str.replace(System.lineSeparator(), "\n");
            // write to System.out
            System.out.print(str);
            sb.setLength(0);
        }
    }

    // static variables for thread-local storage of the stream
    private static final ThreadLocal<ThreadBoundOutputStream> THREAD_LOCAL =
            new ThreadLocal<>();
    private static final PrintStream PRINT_STREAM = System.out;

    // binds the stream to System.out
    public static synchronized ThreadBoundOutputStream bindSystemOut() {
        ThreadBoundOutputStream tbo = THREAD_LOCAL.get();
        if (tbo == null) {
            tbo = new ThreadBoundOutputStream();
            System.setOut(new PrintStream(tbo, true));
            THREAD_LOCAL.set(tbo);
        }
        return tbo;
    }

    // unbinds the stream from System.out
    public static synchronized void unbindSystemOut() {
        ThreadBoundOutputStream tbo = THREAD_LOCAL.get();
        if (tbo != null) {
            System.setOut(PRINT_STREAM);
            THREAD_LOCAL.remove();
        }
    }
}
