import java.util.Iterator;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.LinkedBlockingQueue;

public class ElementParser {
    public static <T> void parse(Iterator<T> iter, int offset, int count, int processThreadNum,
            int queueSize, ElementProcessor<T> elementParser, Runnable onComplete, Runnable onError) {

        LinkedBlockingQueue<T> queue = new LinkedBlockingQueue<>(queueSize);
        ExecutorService executor = Executors.newFixedThreadPool(processThreadNum);

        // fill the queue with data to be processed
        new Thread(() -> {
            int i = 0;
            while (iter.hasNext() && i < offset + count) {
                T element = iter.next();
                if (i >= offset) {
                    try {
                        queue.put(element);
                    } catch (InterruptedException e) {
                        onError.run();
                    }
                }
                i++;
            }
            // add a null element to the queue for each processing thread to know when to terminate
            for (int t = 0; t < processThreadNum; t++) {
                try {
                    queue.put(null);
                } catch (InterruptedException e) {
                    onError.run();
                }
            }
        }).start();

        // start the processing threads
        for (int t = 0; t < processThreadNum; t++) {
            executor.execute(() -> {
                boolean done = false;
                while (!done) {
                    try {
                        T element = queue.take();
                        if (element == null) {
                            done = true;
                            break;
                        }
                        elementParser.process(element);
                    } catch (InterruptedException e) {
                        onError.run();
                    } catch (RuntimeException e) {
                        onError.run();
                    }
                }
                // when processing is done, execute the onComplete runnable in the main thread
                executor.execute(onComplete);
            });
        }
    }
}

interface ElementProcessor<T> {
    void process(T element);
}
