import javax.swing.*;
import java.awt.event.InputMap;
import java.awt.event.KeyEvent;

public KeyStroke findKeyStroke(JComponent component, int keyCode, int modifiers) {
    KeyStroke ks = null;
    InputMap im = component.getInputMap(JComponent.WHEN_IN_FOCUSED_WINDOW);
    ks = (im == null) ? null : (KeyStroke) im.get(KeyStroke.getKeyStroke(keyCode, modifiers));

    if (ks == null) {
        im = component.getInputMap(JComponent.WHEN_FOCUSED);
        ks = (im == null) ? null : (KeyStroke) im.get(KeyStroke.getKeyStroke(keyCode, modifiers));
    }

    if (ks == null) {
        im = component.getInputMap(JComponent.WHEN_ANCESTOR_OF_FOCUSED_COMPONENT);
        ks = (im == null) ? null : (KeyStroke) im.get(KeyStroke.getKeyStroke(keyCode, modifiers));
    }

    return ks;
}
