public List<Archive> getMatchingArchives(List<Report> reports, List<Archive> archives, boolean excludeRequired) {
    List<Archive> matchingArchives = new ArrayList<>();
    for (Archive archive : archives) {
        boolean hasMatchingDependencies = false;
        for (Report report : reports) {
            if (archive.getDependencies().contains(report)) {
                hasMatchingDependencies = true;
                break;
            }
        }
        if (hasMatchingDependencies && (!excludeRequired || !archive.isRequired())) {
            matchingArchives.add(archive);
        }
    }
    return matchingArchives;
}
