public int compareTo(EvolutionResult other) {
    double thisFitness = getBestFitness();
    double otherFitness = other.getBestFitness();

    if (thisFitness < otherFitness) {
        return -1;
    } else if (Double.compare(thisFitness, otherFitness) == 0) {
        return 0;
    } else {
        return 1;
    }
}
