public NetcdfVariable makeNetcdfVariable(NetcdfFile ncfile, Group g, String useName, RandomAccessFile raf) throws IOException, InvalidRangeException {
    Variable variable = g.findVariable(useName);
    if (variable == null) {
        variable = new Variable(ncfile, g, null, useName);
    }
    int[] shape = new int[variable.getRank()];
    for (int i=0; i<shape.length; i++) {
        shape[i] = variable.getDimension(i).getLength();
    }

    return new NetcdfVariable(ncfile, variable, null, null, null, null, null, null, null, null, null, -1, -1, raf, shape);
}
