public class FileWriterUtil {

    public static void writeFileInFscrawlerDirectory(String subdir, String filename, String content) throws IOException {

        String homeDir = System.getProperty("user.home");

        String dirPath = homeDir + File.separator + ".fscrawler";

        if(subdir != null && !subdir.isEmpty()) {
            dirPath += File.separator + subdir;
        }

        File dir = new File(dirPath);
        if(!dir.exists()) {
            dir.mkdirs();
