import java.io.BufferedReader;
import java.io.FileReader;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.Statement;

public class SQLUtility {
    public void executeSQLScript() throws Exception {
        // Replace the value of ANNIS_HOME with the path of the directory containing the SQL scripts
        String ANNIS_HOME = "/path/to/ANNIS_HOME";
        String scriptName = "script.sql";
        String scriptPath = ANNIS_HOME + "/scripts/" + scriptName;

        // Replace the following JDBC connection details with your database details
        String url = "jdbc:mysql://localhost:3306/testdb";
        String user = "testuser";
        String password = "testpass";

        Connection con = DriverManager.getConnection(url, user, password);

        BufferedReader reader = new BufferedReader(new FileReader(scriptPath));
        String line = reader.readLine();
        StringBuilder sb = new StringBuilder();

        while (line != null) {
            sb.append(line);
            sb.append("\n");
            line = reader.readLine();
        }

        reader.close();
        String query = sb.toString();

        Statement stmt = con.createStatement();
        stmt.execute(query);
        con.close();
    }
}
