public int searchTargetString(String[] target, String[] indexWith) {
    int result = -1;
    for (String str : indexWith) {
        for (int i = 0; i < target.length; i++) {
            if (target[i].contains(str)) {
                result = i;
                break;
            }
        }
        if (result != -1) {
            break;
        }
    }
    return result;
}
