public boolean checkClassChange(Class oldInfo, Class newInfo) {
    if (oldInfo.getModifiers() != newInfo.getModifiers() ||
            oldInfo.getSuperclass() != newInfo.getSuperclass())
        return true;

    Class<?>[] oldInterfaces = oldInfo.getInterfaces();
    Class<?>[] newInterfaces = newInfo.getInterfaces();

    if (oldInterfaces.length != newInterfaces.length)
        return true;

    for (int i = 0; i < oldInterfaces.length; i++) {
        if (!newInfo.isAssignableFrom(oldInterfaces[i]))
            return true;
    }

    return false;
}
