public Set<Class<?>> findAllExternalClassReferences(Object outline, Set<Class<?>> classes) throws IllegalAccessException {
   Set<Class<?>> externalClasses = new HashSet<>();
   Class<?> rootClass = outline.getClass();
   for (Field field : rootClass.getDeclaredFields()) {
       if (field.isAnnotationPresent(ExternalClass.class)) {
           field.setAccessible(true);
           Object fieldValue = field.get(outline);
           externalClasses.addAll(findAllExternalClassReferences(fieldValue, classes));
       } else {
           Class<?> fieldType = field.getType();
           if (fieldType.isArray() || Collection.class.isAssignableFrom(fieldType)) {
               ParameterizedType genericType = (ParameterizedType) field.getGenericType();
               Class<?> elementClass = (Class<?>) genericType.getActualTypeArguments()[0];
               if (classes.contains(elementClass)) {
                   continue;
               }
               externalClasses.add(elementClass);
           } else if (!classes.contains(fieldType)) {
                externalClasses.add(fieldType);
           }
       }
   }
   return externalClasses;
}
