        if (sslConfig.getExcludeCipherSuites() != null) {
            selected_ciphers.removeAll(Arrays.asList(sslConfig.getExcludeCipherSuites()));
	}
        return selected_ciphers.toArray(new String[selected_ciphers.size()]);
