public boolean writeCFPointFormat(NetcdfFile fileIn, NetcdfFileWriter fileOut, boolean inMemory) throws IOException {
    //Open the PointObsDataset and read variables
    PointObsDataset pointObs = PointObsDataset.open(fileIn.getLocation());
    List variables = pointObs.getDataVariables();
    List<VariableSimpleIF> dataVars = new ArrayList<>();
    for (Object variable : variables) {
        VariableSimpleIF dataVar = (VariableSimpleIF) variable;
        dataVars.add(dataVar);
    }
    //Set output format as netCDF-3 classic mode
    fileOut.setVersion(NC_FORMAT_CLASSIC);
    //Define dimensions
    List<Dimension> dimList = new ArrayList<>();
    Dimension timeDim = fileOut.addDimension(null, "time", -1); 
    Dimension latDim = fileOut.addDimension(null, "lat", -1);
    Dimension lonDim = fileOut.addDimension(null, "lon", -1);
    dimList.add(timeDim);
    dimList.add(latDim);
    dimList.add(lonDim);
    //Define variables and create in the file
    Variable timeVar = fileOut.addVariable(null, "time", DataType.DOUBLE, "time");
    timeVar.addAttribute(new Attribute(CF.STANDARD_NAME, CF.TIME));
    timeVar.addAttribute(new Attribute(CF.CALENDAR, CF.GREGORIAN));
    timeVar.addAttribute(new Attribute(_Coordinate.AxisType, AxisType.Time.toString()));
    timeVar.addAttribute(new Attribute(_Coordinate.Axis, "T"));
    timeVar.addAttribute(new Attribute(CDM.UNITS, "seconds since 1970-01-01T00:00:00Z"));
    Variable latVar = fileOut.addVariable(null, "lat", DataType.DOUBLE, "lat");
    latVar.addAttribute(new Attribute(CF.STANDARD_NAME, CF.LATITUDE));
    latVar.addAttribute(new Attribute(_Coordinate.AxisType, AxisType.Lat.toString()));
    latVar.addAttribute(new Attribute(_Coordinate.Axis, "Y"));
    latVar.addAttribute(new Attribute(CDM.UNITS, CF.DEGREES_NORTH));
    Variable lonVar = fileOut.addVariable(null, "lon", DataType.DOUBLE, "lon");
    lonVar.addAttribute(new Attribute(CF.STANDARD_NAME, CF.LONGITUDE));
    lonVar.addAttribute(new Attribute(_Coordinate.AxisType, AxisType.Lon.toString()));
    lonVar.addAttribute(new Attribute(_Coordinate.Axis, "X"));
    lonVar.addAttribute(new Attribute(CDM.UNITS, CF.DEGREES_EAST));
    List<Variable> dataVarsOut = new ArrayList<>();
    for (VariableSimpleIF dataVar : dataVars) {
        List<Dimension> dims = new ArrayList<>();
        dims.add(timeDim);
        dims.add(latDim);
        dims.add(lonDim);
        Variable outVar = fileOut.addVariable(null, dataVar.getShortName(), dataVar.getDataType(), dims);
        outVar.addAttribute(new Attribute(CF.STANDARD_NAME, dataVar.getShortName()));
        outVar.addAttribute(new Attribute(CDM.UNITS, dataVar.getUnitsString()));
        outVar.addAttribute(new Attribute(_Coordinate.AxisType, "Height"));
        outVar.addAttribute(new Attribute(_Coordinate.Axis, "Z"));
        dataVarsOut.add(outVar);
    }
    fileOut.create();
    //Read data into memory
    if (inMemory) {
        pointObs.readDataAllAtOnce();
    }
    //Write data to output file
    int[] origin = new int[3];
    int[] shape = new int[3];
    origin[0] = 0;
    shape[0] = 1; //write one record at a time
    for (VariableSimpleIF dataVarIn : dataVars) {
        Array dataArray = inMemory ? dataVarIn.read() : pointObs.getData(dataVarIn);
        origin[1] = 0;
        shape[1] = dataArray.getShape()[0];
        shape[2] = 1;
        IntStream.range(0, dataArray.getShape()[1]).forEach(i ->
                IntStream.range(0, dataArray.getShape()[0]).forEach(j -> {
                    try {
                        origin[2] = i;
                        shape[2] = 1;
                        double value = dataArray.getDouble(j, i);
                        fileOut.write(dataVarsOut.get(i), origin, Array.factory(DataType.DOUBLE, new int[]{1}, new double[]{value}));
                    } catch (IOException e) {
                        e.printStackTrace();
                    }
                })
        );
    }
    return true;
}
