public boolean hasTagMatch(UdpChannel udpChannel) {
    boolean match = false;

    // check if the tags of the channels match
    if (this.tag != null && udpChannel.getTag() != null) {
        match = this.tag.equals(udpChannel.getTag());
    }

    // check if the endpoints of the channels match
    if(match && this.endpoint != null && udpChannel.getEndpoint() != null) {
        match = this.endpoint.equals(udpChannel.getEndpoint());
    }

    return match;
}
