public Object discardEntryFromBucket(int bucketIndex, int entryIndex) {
    // Check if the bucket and entry indices are valid
    if (bucketIndex >= 0 && bucketIndex < buckets.length && entryIndex >= 0 && entryIndex < buckets[bucketIndex].size()) {
        // Retrieve the value to be discarded
        Object discardedValue = buckets[bucketIndex].get(entryIndex);
        // Remove the entry from the bucket
        buckets[bucketIndex].remove(entryIndex);
        return discardedValue;
    } else {
        return null; // Invalid indices provided
    }
}
