    if (solution.size() < MIN_SUBSET_SIZE || solution.size() > MAX_SUBSET_SIZE) {
        hasValidSize = false;
    }

    return new SubsetValidation(isValid, hasValidSize);
}

private static final int MIN_SUBSET_SIZE = 1;
private static final int MAX_SUBSET_SIZE = 10;
