                    if (field.getType().equals(int.class) || field.getType().equals(Integer.class)) {
                        int value = field.getInt(obj);
                        if (value < argument.min() || value > argument.max()) {
                            throw new IllegalArgumentException(String.format("%s value '%d' is outside the valid range [%d,%d]", field.getName(), value, argument.min(), argument.max()));
                        }
                    } else if (field.getType().equals(double.class) || field.getType().equals(Double.class)) {
                        double value = field.getDouble(obj);
                        if (value < argument.min() || value > argument.max()) {
                            throw new IllegalArgumentException(String.format("%s value '%f' is outside the valid range [%f,%f]", field.getName(), value, argument.min(), argument.max()));
                        }
                    }
                }
            }
        }
    }
}
