public void combine(Key key, Iterator<Value> values, TaskInputOutputContext context)
        throws IOException, InterruptedException {
    List<Value> valueList = new ArrayList<>();
    while (values.hasNext()) {
        Value value = values.next();
        valueList.add(new Value(value));    //Use defensive copying to avoid modification
    }
    context.write(key, combineValues(valueList));
}

private Value combineValues(List<Value> values) {
    //Perform combine logic here
    Value result = null;
    for (Value value : values) {
        if (result == null) {
            result = new Value(value);
        } else {
            result.increment(value);
        }
    }
    return result;
}
