public void parseAbcFile(String abcFile) {
    String[] lines = abcFile.split("\n");
    for (String line : lines) {
        if (line.startsWith("%%")) {
            //comment line
            processComment(line);
        } else if (line.startsWith("X:")) {
            //xcommand
            processXCommand(line);
        } else if (line.startsWith("[")) {
            //abc-tune
            processAbcTune(line);
        } else if (line.startsWith("%")) {
            //file field
            processFileField(line);
        } else {
            //either text-line or tex
            if (line.contains("\\tex")) {
                processTex(line);
            } else {
                processTextLine(line);
            }
        }
    }
}

