public int findOffsetMatch(byte[] bytes, char[] chars) {
    if (bytes != null && chars != null) {
        throw new IllegalArgumentException("Both parameters cannot be non-null");
    }
    int n = bytes != null ? bytes.length : chars.length;
    for (int i = 0; i < n; i++) {
        if (bytes != null && bytes[i] == (byte) chars[i]) {
            return i;
        } else if (chars != null && chars[i] == (char) bytes[i]) {
            return i;
        }
    }
    return -1; // no offset match found
}
