public List<Privilege> constructPrivileges(List<String> names) throws ValueFormatException, AccessControlException, RepositoryException {
    List<Privilege> privileges = new ArrayList<Privilege>();
    for (String name : names) {
        Privilege privilege = null;
        try {
            privilege = AccessControlUtils.getPrivilege(name);
        } catch (AccessControlException e) {
            throw new AccessControlException("Error while constructing Privilege objects for " + name, e);
        } catch (RepositoryException e) {
            throw new RepositoryException("Error while constructing Privilege objects for " + name, e);
        }
        if (privilege == null) {
            throw new ValueFormatException("Invalid privilege name: " + name);
        }
        privileges.add(privilege);
    }
    return privileges;
}
