        this.networkCost = networkCost;
        this.diskCost = diskCost;
    }

    // Method to add costs
    public void addCosts(Costs other) {
        if (this.networkCost != null && other.networkCost != null) {
            this.networkCost += other.networkCost;
        } else {
            this.networkCost = null;
        }

        if (this.diskCost != null && other.diskCost != null) {
            this.diskCost += other.diskCost;
        } else {
            this.diskCost = null;
        }
    }
}
