    List<Reuters21578StoryBean> storyList = new ArrayList<>();
    BufferedReader reader = null;
    try {
        reader = new BufferedReader(new FileReader(fileName));
        String line;
        while ((line = reader.readLine()) != null) {
            String[] tokens = line.split("\\t");
            if (tokens.length >= 3) {
                String storyId = tokens[0];
                String headline = tokens[1];
                String text = tokens[2];
                Reuters21578StoryBean story = new Reuters21578StoryBean(storyId, headline, text);
                storyList.add(story);
            }
        }
    } finally {
        if (reader != null) {
            reader.close();
        }
    }
    return storyList;
}

class Reuters21578StoryBean {
    String storyId;
    String headline;
    String text;

    public Reuters21578StoryBean(String storyId, String headline, String text) {
        this.storyId = storyId;
        this.headline = headline;
        this.text = text;
    }
}
