public static Point convertCoordinates(Location location) {
    double latitude = location.getLatitude();
    double longitude = location.getLongitude();
    int x = (int) (longitude * MAP_WIDTH / 360.0);
    int y = (int) ((2 * Math.atan(Math.exp(latitude * Math.PI / 180.0)) - Math.PI / 2.0) * MAP_HEIGHT / Math.PI);
    return new Point(x, y);
}
