import java.util.HashSet;
import java.util.Set;

import javax.enterprise.context.Dependent;
import javax.enterprise.inject.spi.Bean;
import javax.enterprise.inject.spi.BeanManager;

public class PseudoScopedBeanDependencyChecker {

    private BeanManager beanManager;

    public PseudoScopedBeanDependencyChecker(BeanManager beanManager) {
        this.beanManager = beanManager;
    }

    public void checkCircularDependencies() {
        Set<Bean<?>> beans = beanManager.getBeans(Object.class, Dependent.class);

        Set<Bean<?>> visitedBeans = new HashSet<>();
        for (Bean<?> bean : beans) {
            checkCircularDependency(bean, visitedBeans);
        }
    }

    private void checkCircularDependency(Bean<?> bean, Set<Bean<?>> visitedBeans) {
        if (visitedBeans.contains(bean)) {
            throw new RuntimeException("Circular dependency detected in pseudo-scoped bean: " + bean.getBeanClass());
        }
        visitedBeans.add(bean);
        for (Bean<?> dependency : bean.getInjectionPoints()) {
            if (dependency.getScope().equals(Dependent.class)) {
                checkCircularDependency(dependency, visitedBeans);
            }
        }
        visitedBeans.remove(bean);
    }
}
