import java.util.Iterator;
import java.util.List;

public class MyIterator<T> implements Iterator<T> {
    private Iterator<List<T>> listOfIterators;
    private Iterator<T> currentIterator;

    public MyIterator(Iterable<Iterator<T>> metaIterable) {
        this.listOfIterators = metaIterable.iterator();
        if (listOfIterators.hasNext()) {
            this.currentIterator = listOfIterators.next();
        }
    }

    @Override
    public boolean hasNext() {
        while ((currentIterator == null || !currentIterator.hasNext()) && listOfIterators.hasNext()) {
            currentIterator = listOfIterators.next();
        }
        return currentIterator != null && currentIterator.hasNext();
    }

    @Override
    public T next() {
        if (!hasNext()) {
            throw new java.util.NoSuchElementException();
        }
        return currentIterator.next();
    }
}
