public URI getOCSPResponderURI(X509Certificate certificate) {
   try {
      ASN1Primitive obj = certificate.getExtensionValue(Extension.authorityInfoAccess.getId());
      if (obj == null) {
         return null;
      }
      AuthorityInformationAccess authorityInformationAccess = AuthorityInformationAccess.getInstance(obj);
      AccessDescription[] accessDescriptions = authorityInformationAccess.getAccessDescriptions();
      for (AccessDescription accessDescription : accessDescriptions) {
         if (accessDescription.getAccessMethod().toString().equals(AccessDescription.id_ad_ocsp.toString())) {
            GeneralName generalName = accessDescription.getAccessLocation();
            return new URI(generalName.getName().toString());
         }
      }
   } catch (Exception e) {
      // Handle exception appropriately
   }
   return null;
}
