public History[] retrieveRequestHistory(Map<String, String> filters) throws Exception {
    int defaultSize = 10; // Set the default size to 10

    if (filters.isEmpty()) {
        // If no filters are specified, return default size history
        return retrieveHistory(defaultSize);
    } else {
        // Apply specified filters and return filtered history
        List<History> filteredHistory = new ArrayList<>();
        for (History h : retrieveHistory()) {
            boolean include = true;
            for (Map.Entry<String, String> filter : filters.entrySet()) {
                if (!h.getMetadata().containsKey(filter.getKey()) || 
                        !h.getMetadata().get(filter.getKey()).equals(filter.getValue())) {
                    // Exclude history item if it does not match the specified filter
                    include = false;
                    break;
                }
            }
            if (include) {
                filteredHistory.add(h);
            }
        }
        return filteredHistory.toArray(new History[0]);
    }
}

