public int[][] findStronglyConnectedComponents(int[][] A) {
    // Check for null input
    if (A == null) {
        return null;
    }

    // Initialize variables
    int n = A.length;
    int[] index = new int[n];
    int[] lowlink = new int[n];
    boolean[] onStack = new boolean[n];
    Stack<Integer> stack = new Stack<>();
    int indexCounter = 0;
    int[][] components;
    List<List<Integer>> componentList = new ArrayList<>();

    // Recursive function to find strongly connected components
    Function<Integer, Void> strongconnect = new Function<Integer, Void>() {
        @Override
        public Void apply(Integer v) {
            // Set the index and lowlink for v
            index[v] = indexCounter;
            lowlink[v] = indexCounter;
            indexCounter++;
            stack.push(v);
            onStack[v] = true;

            // Loop through neighbors of v
            for (int i = A[v][0]; i < A[v][0] + A[v][1]; i++) {
                int w = A[i][0];
                if (index[w] == -1) {
                    // Recursively call strongconnect on w
                    strongconnect.apply(w);
                    lowlink[v] = Math.min(lowlink[v], lowlink[w]);
                } else if (onStack[w]) {
                    lowlink[v] = Math.min(lowlink[v], index[w]);
                }
            }

            // If v is a root node, pop the stack and create a new component
            if (lowlink[v] == index[v]) {
                List<Integer> component = new ArrayList<>();
                int w;
                do {
                    w = stack.pop();
                    onStack[w] = false;
                    component.add(w);
                } while (w != v);
                componentList.add(component);
            }

            return null;
        }
    };

    // Initialize index array
    Arrays.fill(index, -1);

    // Perform Tarjan's algorithm to find strongly connected components
    for (int i = 0; i < n; i++) {
        if (index[i] == -1) {
            strongconnect.apply(i);
        }
    }

    // Convert componentList to int[][] and return
    int numComponents = componentList.size();
    components = new int[numComponents][];
    for (int i = 0; i < numComponents; i++) {
        List<Integer> component = componentList.get(i);
        int size = component.size();
        components[i] = new int[size];
        for (int j = 0; j < size; j++) {
            components[i][j] = component.get(j);
        }
    }
    return components;
}
