import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

public class OverrideOrder {

  public static List<String> getOverrideOrder(Class<?> clazz) {
    Set<String> fieldsAndMethods = new LinkedHashSet<>();
    getSuperclassFieldsAndMethods(clazz, fieldsAndMethods);
    getSubclassFieldsAndMethods(clazz, fieldsAndMethods);
    return new ArrayList<>(fieldsAndMethods);
  }

  private static void getSuperclassFieldsAndMethods(Class<?> clazz, Set<String> fieldsAndMethods) {
    if (clazz.getSuperclass() != null) {
      getSuperclassFieldsAndMethods(clazz.getSuperclass(), fieldsAndMethods);
    }
    addFieldsAndMethods(clazz.getDeclaredFields(), fieldsAndMethods);
    addFieldsAndMethods(clazz.getDeclaredMethods(), fieldsAndMethods);
  }

  private static void getSubclassFieldsAndMethods(Class<?> clazz, Set<String> fieldsAndMethods) {
    for (Class<?> subclazz : clazz.getClasses()) {
      addFieldsAndMethods(subclazz.getDeclaredFields(), fieldsAndMethods);
      addFieldsAndMethods(subclazz.getDeclaredMethods(), fieldsAndMethods);
      getSubclassFieldsAndMethods(subclazz, fieldsAndMethods);
    }
  }

  private static void addFieldsAndMethods(Method[] methods, Set<String> fieldsAndMethods) {
    for (Method method : methods) {
      fieldsAndMethods.add(method.toString());
    }
  }

  private static void addFieldsAndMethods(java.lang.reflect.Field[] fields, Set<String> fieldsAndMethods) {
    for (java.lang.reflect.Field field : fields) {
      fieldsAndMethods.add(field.toString());
    }
  }
}
