public static double calculateBIC(int k, int n, int d, double distortion, int[] clusterSize) {
    double logLikelihood = (-n * d / 2) * Math.log(2 * Math.PI) - (n / 2) * Math.log(distortion / n) - ((k * d * (d + 1)) / 2) * Math.log(n);
    double penaltyTerm = (k / 2) * Math.log(n);
    for (int i = 0; i < k; i++) {
        penaltyTerm += ((clusterSize[i] - 1) / 2) * Math.log(clusterSize[i] - 1) - ((clusterSize[i] - 1) * d / 2) * Math.log(distortion / (clusterSize[i] - 1));
    }
    return logLikelihood - penaltyTerm;
}
