public void writeData(List<String> data, boolean close) throws IOException{
    int chunkSize = 1000; // Configured chunk size
    String filePath = "path/to/file.csv";

    try (BufferedWriter writer = new BufferedWriter(new FileWriter(filePath, true))) {
        for (String line : data) {
            writer.write(line);
            writer.newLine();

            if (writer.getBufferSize() >= chunkSize || close) {
                writer.flush();
            }
        }
    }
}
