import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.xpath.XPath;
import javax.xml.xpath.XPathConstants;
import javax.xml.xpath.XPathExpression;
import javax.xml.xpath.XPathFactory;
import org.w3c.dom.Document;
import org.w3c.dom.NodeList;

public class XPathProcessor {

    public static NodeList getNodes(Document dom, String xpathExpr) throws XPathExpressionException {
        XPathFactory xpathFactory = XPathFactory.newInstance();
        XPath xpath = xpathFactory.newXPath();
        XPathExpression expression = xpath.compile(xpathExpr);
        return (NodeList) expression.evaluate(dom, XPathConstants.NODESET);
    }

    public static void main(String[] args) throws Exception {
        DocumentBuilderFactory builderFactory = DocumentBuilderFactory.newInstance();
        DocumentBuilder builder = builderFactory.newDocumentBuilder();
        Document dom = builder.parse("example.xml");
        String xpathExpr = "/root/element[@attribute='value']";
        NodeList matchingNodes = getNodes(dom, xpathExpr);
        for (int i = 0; i < matchingNodes.getLength(); i++) {
            System.out.println(matchingNodes.item(i));
        }
    }
}
