        int probationVictim = calculateProbationVictim(probationSpace);
        if (admissionCandidate > probationVictim) {
            admissionWindow.remove(admissionCandidate);
            probationSpace.add(admissionCandidate);
        } else {
            probationSpace.remove(probationVictim);
            probationSpace.add(admissionCandidate);
        }
    }
}

