    ObjectName mbeanServerController = new ObjectName("jboss.system:type=ServerMBean");
    ObjectName jmxAdaptor = (ObjectName) server.getAttribute(mbeanServerController, "JMXAdaptor");
    ObjectName jmxInvoker = (ObjectName) server.invoke(jmxAdaptor, "getInvoker", new Object[]{"jmx"}, new String[]{"java.lang.String"});

    ObjectName jmxInvokerController = new ObjectName("jboss.management.local:J2EEDomain=jbosssx,service=EJB");
    ServiceControllerMBean jmxInvokerService = (ServiceControllerMBean) MBeanServerInvocationHandler.newProxyInstance(server, jmxInvokerController, ServiceControllerMBean.class, false);

    if (!jmxInvokerService.isStarted()) {
        jmxInvokerService.start();
    }

    ObjectName pool = new ObjectName(":service=invoker,type=jrmp");
    Object[] params2 = new Object[]{new String[]{"java.lang.String", "java.lang.String", "java.lang.Object"}, new String[]{"org.jboss.invocation.jrmp.server.JRMPInvokerInvocation", "java.lang.String", "java.lang.String"}};
    String[] signature2 = new String[]{String[].class.getName(), String[].class.getName()};

    Object invokerProxy = server.invoke(pool, "getMethodInvocationsHandlerProxy", params2, signature2);
    ClassLoader loader = Thread.currentThread().getContextClassLoader();

    Class propertyEditorManagerClass = loader.loadClass("java.beans.PropertyEditorManager");
    Class xMBeanInvokerClass = loader.loadClass("org.jboss.mx.util.MBeanProxyExt");

    Object jmxInvokerProxy;
    if (xMBeanInvokerClass.isAssignableFrom(invokerProxy.getClass())) {
        MethodDelegate methodDelegate = new MethodDelegate(invokerProxy, "invoke", new Class[]{ObjectName.class, String.class, Object[].class, String[].class}, loader);
        jmxInvokerProxy = methodDelegate;
    } else {
        jmxInvokerProxy = invokerProxy;
    }

    Class jmxInvokerProxyClass = loader.loadClass("org.jboss.mx.util.MBeanProxyExt");
    Method addPropertyEditor = propertyEditorManagerClass.getMethod("registerEditor", new Class[]{Class.class, Class.forName("java.beans.PropertyEditor")});
    addPropertyEditor.invoke(null,jmxInvokerProxyClass,AccessControlListEditor.class);
    addPropertyEditor.invoke(null,jmxInvokerProxyClass,AbsoluteScheduleEditor.class);
}
