public <T> T convertEntityToObject(Entity entity, Class<T> clazz) {
    if (entity == null) {
        return null;
    }
    String kind = entity.getKind();
    try {
        T obj = clazz.newInstance();
        if (datastoreKindToPojoClassMappings.containsKey(kind)) {
            BeanUtils.copyProperties(obj, entity);
            return obj;
        }
    } catch (InstantiationException | IllegalAccessException e) {
        e.printStackTrace();
    }
    return (T) entity;
}
