public String deserializePayload(String registryUrl, String topic, byte[] payload) throws IOException {
    SchemaRegistryClient schemaRegistry = new CachedSchemaRegistryClient(registryUrl, 10);
    int schemaId = schemaRegistry.getLatestSchemaMetadata(topic).getId();
    Schema schema = schemaRegistry.getByID(schemaId);
    ByteArrayInputStream inputStream = new ByteArrayInputStream(payload);
    DatumReader<Object> reader = new GenericDatumReader<>(schema);
    Decoder decoder = DecoderFactory.get().binaryDecoder(inputStream, null);
    Object decodedData = reader.read(null, decoder);
    String deserializedPayload = decodedData.toString();
    return deserializedPayload;
}
