public void executeRemoteCommand(String command) throws BuildException{
    try {
        // create a new instance of JSch
        JSch jsch = new JSch();
        // connect to the remote host (replace hostname and username with your values)
        Session session = jsch.getSession("username", "hostname", 22);
        // set password for the session (you can also use key-based authentication)
        session.setPassword("password");
        // set StrictHostKeyChecking property to no to avoid UnknownHostKey exception
        Properties config = new Properties();
        config.put("StrictHostKeyChecking", "no");
        session.setConfig(config);
        // connect to the session
        session.connect();
        // create a new channel for executing the command
        ChannelExec channelExec = (ChannelExec) session.openChannel("exec");
        // set the command to be executed
        channelExec.setCommand(command);
        // connect to the channel
        channelExec.connect();
        // read the output from the channel
        InputStream in = channelExec.getInputStream();
        byte[] buffer = new byte[1024];
        int len = -1;
        while ((len = in.read(buffer)) != -1) {
            System.out.print(new String(buffer, 0, len));
        }
        // disconnect from the channel
        channelExec.disconnect();
        // disconnect from the session
        session.disconnect();
    } catch (JSchException e) {
        throw new BuildException("Error executing remote command: " + e.getMessage());
    } catch (IOException e) {
        throw new BuildException("Error executing remote command: " + e.getMessage());
    }
}
