public static GrayS16 convertInterleavedToGrayAverage(InterleavedS16 input, GrayS16 output)
{
    int width = input.getWidth();
	int height = input.getHeight();

	if (output == null) {
	    output = new GrayS16(width, height);
	} else {
	    if (output.getWidth() != width || output.getHeight() != height)
	        throw new IllegalArgumentException("Input output image does not have same shape as input image");
	}

	int bands = input.getNumBands();

	for (int y = 0; y < height; y++) {
	    for (int x = 0; x < width; x++) {
	        int sum = 0;
	        for (int band = 0; band < bands; band++) {
	            sum += input.getBand(x,y,band);
	        }
	        output.set(x,y,sum/bands);
	    }
	}

    return output;
}
