public static double calculateExpectedInterRaterAgreement(double[] probabilities) {
    if (probabilities == null) {
        throw new NullPointerException("Annotation study is null.");
    }
    if (probabilities.length == 0) {
        throw new ArithmeticException("No items in the annotation study.");
    }
    double sum = 0.0;
    for (double p : probabilities) {
        sum += p;
    }
    double expectedAgreement = sum / probabilities.length;
    return expectedAgreement;
}
