public int getJulianEasterSunday(int nYear) {
    if (nYear < 0) throw new IllegalArgumentException("Year must be positive");

    int nA = nYear % 4;
    int nB = nYear % 7;
    int nC = nYear % 19;
    int nD = (19 * nC + 15) % 30;
    int nE = (2 * nA + 4 * nB - nD + 34) % 7;
    int nF = nD + nE + 114;

    int nMonth = nF / 31;
    int nDay = (nF % 31) + 1;

    int nJulianMonth = 3 + nMonth;
    if (nJulianMonth > 12) nJulianMonth -= 12;

    int nJulianYear = nYear;
    if (nMonth > 10) nJulianYear++;

    int nJulianDay = (nDay + (13 * nJulianMonth - 7) / 5 + nJulianYear % 100 - nJulianYear % 100 / 4 + nJulianYear / 100 / 4 - 2 * (nJulianYear / 100)) % 7;
    if (nJulianDay <= 0) nJulianDay += 7;

    int nJulianDate = 7 * (nMonth - 1) + nJulianDay + 1;

    return nJulianDate;
}
