import java.util.Set;
import org.apache.maven.plugin.MojoExecutionException;

public Set<String> determineJXmlFilesToCompile(Map<String, String> mapping) throws MojoExecutionException {
    Set<String> jxmlFiles = new HashSet<>();

    try {
        for (Map.Entry<String, String> entry : mapping.entrySet()) {
            String sourceFileName = entry.getKey();
            String sourceFilePath = entry.getValue();

            if (sourceFileName.endsWith(".jxml")) {
                jxmlFiles.add(sourceFilePath);
            }
        }
    } catch (Exception e) {
        throw new MojoExecutionException("There was an error determining the set of jxml files to compile.", e);
    }

    return jxmlFiles;
}
