import java.io.File;
import java.io.FileWriter;
import java.io.IOException;
import java.util.List;

import org.jgrapht.graph.DefaultWeightedEdge;
import org.jgrapht.graph.WeightedDirectedMultigraph;

public class GraphWriter {

    public static void writePajek(WeightedDirectedMultigraph<String, DefaultWeightedEdge> graph, File file) throws IOException {
        FileWriter writer = new FileWriter(file);

        writer.write("*Vertices " + graph.vertexSet().size() + "\n");
        int i = 1;
        for (String vertex : graph.vertexSet()) {
            writer.write(i + " \"" + vertex + "\"\n");
            i++;
        }

        writer.write("*Arcs\n");
        List<String> vertexList = graph.vertexList();

        for (String vertex : vertexList) {
            int vertexId = vertexList.indexOf(vertex) + 1;

            for (String target : graph.outgoingEdgesOf(vertex)) {
                int targetId = vertexList.indexOf(graph.getEdgeTarget(target)) + 1;

                double weight = graph.getEdgeWeight(target);

                writer.write(String.format("%d %d %.2f\n", vertexId, targetId, weight));
            }
        }

        writer.close();
    }
}
