public boolean updateIndexes(Map<String, String> indexes, Database database, ExecutorService queue) {
    boolean success = true;
    List<Callable<Void>> callables = new ArrayList<Callable<Void>>();

    for (String indexName : indexes.keySet()) {
        String indexDefinition = indexes.get(indexName);
        callables.add(new Callable<Void>() {
            @Override
            public Void call() throws Exception {
                database.updateIndex(indexName, indexDefinition);
                return null;
            }
        });
    }

    try {
        List<Future<Void>> futures = queue.invokeAll(callables);

        for (Future<Void> future : futures) {
            if (!future.isDone()) {
                success = false;
                break;
            }

            if (future.isCancelled()) {
                success = false;
                // Handle cancellation here
            }
        }
    } catch (InterruptedException e) {
        success = false;
        // Handle interruption here
    }

    return success;
}
