public static Long convertToUTC(Date date) {
   if(date == null) {
       return null;
   }
   int offset = date.getTimezoneOffset();
   Calendar cal = Calendar.getInstance();
   cal.setTime(date);
   cal.add(Calendar.MINUTE, offset);
   return cal.getTimeInMillis();
}
