            .byDetectableFace(true)
            .withReturnRecognitionModel(false)
            .withReturnRecognitionModel(false)
            .withReturnFaceId(false)
            .withReturnExcludedFace(false)
            .withReturnRecognitionModel(false)
            .withUserData(true)
