public void processRequest(HttpServletRequest request, HttpServletResponse response, FilterChain chain) throws IOException, ServletException {
    // create list of security processors
    List<RequestSecurityProcessor> processors = Arrays.asList(
        new AuthenticationProcessor(),
        new AuthorizationProcessor(),
        new ValidationProcessor()
    );

    // iterate over the list and call the processRequest method on each processor
    for (RequestSecurityProcessor processor : processors) {
        processor.processRequest(request, response, chain);
    }
    // finally, call the filter chain
    chain.doFilter(request, response);
}
