public BsonBoolean getBsonBooleanOrDefault(Document document, String key, BsonBoolean defaultValue) {
    if (document.containsKey(key)) {
        BsonValue value = document.get(key);
        if (value.isBoolean()) {
            return value.asBoolean();
        } else {
            throw new BsonInvalidOperationException("Value is not of the expected type");
        }
    } else {
        return defaultValue;
    }
}
