public static String getJsTopicName(Annotation[][] parameterAnnotations, String topic) {
    String jsTopicName = null;
    for (Annotation[] annotations : parameterAnnotations) {
        for (Annotation annotation : annotations) {
            if (annotation instanceof JsTopicName) {
                JsTopicName topicName = (JsTopicName) annotation;
                if (topicName.value().equals(topic)) {
                    jsTopicName = topicName.jsName();
                    break;
                }
            }
        }
        if (jsTopicName != null) {
            break;
        }
    }
    return jsTopicName;
}
