public static boolean hasValidatingMcfInterface(OutputStream out, String classname, ClassLoader cl) {
    try {
        Class<?> clazz = Class.forName(classname, false, cl);
        Class<?>[] interfaces = clazz.getInterfaces();
        boolean hasValidatingMcfInterface = false;
        for (Class<?> iface : interfaces) {
            if (iface.getName().endsWith("ValidatingMcf")) {
                hasValidatingMcfInterface = true;
                break;
            }
        }
        if (!hasValidatingMcfInterface) {
            out.write(("Error: class " + classname + " does not implement ValidatingMcf interface").getBytes());
            return false;
        }
    } catch (ClassNotFoundException e) {
        out.write(("Error: class " + classname + " not found").getBytes());
        return false;
    } catch (IOException e) {
        // Handle IOException as appropriate
    }
    return true;
}
