public static <T> T[] getArrayOrDefault(Collection<?> coll, T[] defaultValue) {
    T[] array = null;
    if (coll != null && !coll.isEmpty()) {
        Object[] collArray = coll.toArray();
        if (defaultValue != null && collArray.getClass().getComponentType().isAssignableFrom(defaultValue.getClass().getComponentType())) {
            // use the provided array if it has the same component type as the collection
            array = defaultValue;
        } else {
            // else create a new array with the same component type as the collection
            array = (T[]) Array.newInstance(collArray.getClass().getComponentType(), collArray.length);
        }
        System.arraycopy(collArray, 0, array, 0, collArray.length);
    } else if (defaultValue != null) {
        array = defaultValue;
    }
    return array;
}
