public static int intervalStart(int[] histogram) {
    int start = 0;
    int min = histogram[start];
    for (int i = 1; i < histogram.length; i++) {
        if (histogram[i] < min) {
            min = histogram[i];
            start = i;
        }
    }
    return start;
}
