public String transformSignature(String signature) {
    String transformedSignature = signature;
    if (signature != null) {
        transformedSignature = signature.replace('/', '.');
        int startIndex = transformedSignature.indexOf('L');
        int endIndex = transformedSignature.lastIndexOf(';');
        if (startIndex >= 0 && endIndex >= 0) {
            String packageName = transformedSignature.substring(startIndex + 1, endIndex).replaceAll("\\.", "/");
            transformedSignature = transformedSignature.substring(0, startIndex + 1) + packageName + transformedSignature.substring(endIndex);
        }
    }
    return transformedSignature;
}
