public static void bucketSort(int[] arr, int m) {
    if (arr == null || arr.length == 0) return;

    int maxVal = m + 1;
    int[] bucket = new int[maxVal];

    for (int i = 0; i < arr.length; i++) {
        bucket[arr[i]]++;
    }

    int outPos = 0;
    for (int i = 0; i < bucket.length; i++) {
        for (int j = 0; j < bucket[i]; j++) {
            arr[outPos++] = i;
        }
    }
}
