import org.neo4j.cypher.javacompat.ExecutionEngine;
import org.neo4j.cypher.javacompat.ExecutionResult;
import org.neo4j.cypher.javacompat.Transaction;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public void mapToCypherAndJson(List<String> queries, QueriesPrintObserver toObserve, String format) {
    // execute queries using the ExecutionEngine
    try (Transaction tx = graphDb.beginTransaction()) {
        ExecutionEngine engine = new ExecutionEngine(graphDb);
        Map<String, Object> queryResult = new HashMap<>();
        ObjectMapper mapper = new ObjectMapper();

        for (String query : queries) {
            ExecutionResult result = engine.execute(query);
            queryResult.put(query, result);

            // map to CYPHER statement and JSON
            String cypherStatement = result.dumpToString();
            String jsonResult = null;
            try {
                jsonResult = mapper.writeValueAsString(result.javaIterator().next());
            } catch (JsonProcessingException e) {
                e.printStackTrace();
            }

            // print the mapping results to output streams configured in QueriesPrintObserver
            toObserve.writeCypherStatement(cypherStatement);
            toObserve.writeJsonResult(jsonResult);
        }

        tx.success();
    }
}
