public User changePassword(String existingPasswordParam, String newPasswordParam, String confirmNewPasswordParam) {
   // code to get the currently logged in user
   User currentUser = getCurrentUser(); // assume this returns the currently logged in user

   // verify that the existing password matches the user's current password
   if (!currentUser.getPassword().equals(existingPasswordParam)) {
      throw new IllegalArgumentException("Existing password is incorrect");
   }

   // verify that the new password and confirm new password are the same
   if (!newPasswordParam.equals(confirmNewPasswordParam)) {
      throw new IllegalArgumentException("New passwords do not match");
   }

   // set the user's new password
   currentUser.setPassword(newPasswordParam);

   // code to save the user's changes
   saveChangesTocurrentUser(currentUser); // assume this saves the user's changes

   return currentUser;
}
