public boolean isLightOnScreen(int x, int y, int radius) {
    // Assuming the camera screen has a rectangular shape with coordinates (x1, y1) and (x2, y2)
    int x1 = 0; // Replace with actual value
    int y1 = 0; // Replace with actual value
    int x2 = 100; // Replace with actual value
    int y2 = 100; // Replace with actual value

    // Check if the circle enclosing the light intersects or contains the camera screen
    int dx = Math.max(x1 - x, 0);
    int dy = Math.max(y1 - y, 0);
    if (dx * dx + dy * dy <= radius * radius) {
        return true;
    }
    dx = Math.max(x - x2, 0);
    dy = Math.max(y - y2, 0);
    if (dx * dx + dy * dy <= radius * radius) {
        return true;
    }
    dx = Math.max(x1 - x, 0);
    dy = Math.max(y - y2, 0);
    if (dx * dx + dy * dy <= radius * radius) {
        return true;
    }
    dx = Math.max(x - x2, 0);
    dy = Math.max(y1 - y, 0);
    if (dx * dx + dy * dy <= radius * radius) {
        return true;
    }
    return false;
}
