public void addOrUpdateItem(Item aItem, ActionType eActionType) throws IllegalArgumentException {
    if (eActionType == ActionType.CREATE) {
        if (existingItemList.contains(aItem.getItemId())) {
            throw new IllegalArgumentException("Cannot create item with same ID already exists.");
        }
        existingItemList.add(aItem.getItemId());
        itemList.add(aItem);
    } else if (eActionType == ActionType.UPDATE) {
        boolean foundItem = false;
        for (int i = 0; i < itemList.size(); i++) {
            if (itemList.get(i).getItemId() == aItem.getItemId()) {
                foundItem = true;
                itemList.set(i, aItem);
                break;
            }
        }
        if (!foundItem) {
            throw new IllegalArgumentException("Cannot update an item that does not exist.");
        }
    }
}
