public static long getMinimum(long[] values) {
    if(values == null) {
        throw new NullPointerException("values parameter cannot be null");
    }

    if(values.length == 0) {
        throw new IllegalArgumentException("values parameter cannot be empty");
    }

    long minimum = values[0];

