import java.lang.reflect.Field;

public static void setValueAtPath(Object target, Object value, String path) throws NoSuchFieldException, IllegalAccessException, InstantiationException {
    String[] pathArr = path.split("\\.");
    Object currentObject = target;

    for (int i = 0; i < pathArr.length - 1; i++) {
        Field field = currentObject.getClass().getDeclaredField(pathArr[i]);
        field.setAccessible(true);

        Object nestedObject = field.get(currentObject);
        if (nestedObject == null) {
            nestedObject = field.getType().newInstance();
            field.set(currentObject, nestedObject);
        }

        currentObject = nestedObject;
    }

    Field field = currentObject.getClass().getDeclaredField(pathArr[pathArr.length - 1]);
    field.setAccessible(true);
    field.set(currentObject, value);
}
