public String encodeHtmlEntities(String html) {
   StringBuilder sb = new StringBuilder();
   for (char c : html.toCharArray()) {
       switch (c) {
           case '\'':
               sb.append("&#39;");
               break;
           case '\"':
               sb.append("&quot;");
               break;
           case '<':
               sb.append("&lt;");
               break;
           case '>':
               sb.append("&gt;");
               break;
           case '&':
               sb.append("&amp;");
               break;
           default:
               sb.append(c);
               break;
       }
   }
   return sb.toString();
}
