import java.awt.Color;
import java.util.Collection;

public class ColorRemover {
    public static void removeHelperTextColors(Collection<Color> colors) {
        colors.removeIf(color -> isHelperTextColor(color));
    }

    private static boolean isHelperTextColor(Color color) {
        int red = color.getRed();
        int green = color.getGreen();
        int blue = color.getBlue();
        return red >= 245 && green <= 130 && blue <= 130;
    }
}
