public String getAddressHexString(String address) {
    String hexValue = Long.toHexString(Long.parseLong(address, 16));
    int numberOfCharacters = address.length();
    if(address.indexOf("0x") == 0 || address.indexOf("0X") == 0) {
        numberOfCharacters -= 2;
        hexValue = "0x" + hexValue;
    }
    while(hexValue.length() < numberOfCharacters) {
        hexValue = "0" + hexValue;
    }
    return hexValue;
}
