public KeyStore loadKeystore(String server, Object keystore) throws KeystoreException {
    try {
        KeyStore ks = KeyStore.getInstance("PKCS12");
        char[] password = "keystore_password".toCharArray();

        if (keystore instanceof File) {
            FileInputStream fis = new FileInputStream((File) keystore);
            ks.load(fis, password);
        } else if (keystore instanceof InputStream) {
            ks.load((InputStream) keystore, password);
        } else if (keystore instanceof byte[]) {
            ks.load(new ByteArrayInputStream((byte[]) keystore), password);
        } else if (keystore instanceof KeyStore) {
            ks = (KeyStore) keystore;
        } else if (keystore instanceof String) {
            FileInputStream fis = new FileInputStream((String) keystore);
            ks.load(fis, password);
        } else {
            throw new IllegalArgumentException("Unsupported keystore type: " + keystore.getClass().getName());
        }

        return ks;
    } catch (Exception e) {
        throw new KeystoreException("Failed to load keystore for " + server, e);
    }
}
