public BoundingBox getBoundingBox() {
    double north = tile2lat(getTileY(), getZoom());
    double south = tile2lat(getTileY() + 1, getZoom());
    double west = tile2lon(getTileX(), getZoom());
    double east = tile2lon(getTileX() + 1, getZoom());
    return new BoundingBox(north, south, east, west);
}

private static double tile2lon(int x, int zoom) {
    return x / Math.pow(2.0, zoom) * 360.0 - 180.0;
}

private static double tile2lat(int y, int zoom) {
    double n = Math.PI - 2.0 * Math.PI * y / Math.pow(2.0, zoom);
    return Math.toDegrees(Math.atan(Math.sinh(n)));
}
