public ParamValueLoader getParamValueLoader(Class<? extends Annotation> annoType, ActContext ctx) {
    List<Annotation> annotations = new ArrayList<>();
    Method method = ctx.handlerMethod();
    if (method != null) {
        Annotation[] handlerAnnotations = method.getAnnotations();
        annotations.addAll(Arrays.asList(handlerAnnotations));
        Parameter[] params = method.getParameters();
        for (Annotation[] paramAnnotations : getAllAnnotations(params)) {
            annotations.addAll(Arrays.asList(paramAnnotations));
        }
    }

    Method currentMethod = ctx.actionContext().method();
    if (currentMethod != null) {
        Annotation[] currentAnnotations = currentMethod.getAnnotations();
        annotations.addAll(Arrays.asList(currentAnnotations));
        Parameter[] currentParams = currentMethod.getParameters();
        for (Annotation[] currentParamAnnotations : getAllAnnotations(currentParams)) {
            annotations.addAll(Arrays.asList(currentParamAnnotations));
        }
    }

    List<Annotation> filteredAnnotations = annotations.stream().filter(annoType::isInstance).collect(Collectors.toList());

    return (ParamValueLoader) (paramValueLoaderConfig, paramName, ctx1) -> {
        Optional<Annotation> optionalAnnotation = filteredAnnotations.stream().filter(annoType::isInstance).findFirst();
        if (optionalAnnotation.isPresent()) {
            Annotation annotation = optionalAnnotation.get();
            ValueLoader valueLoader = paramValueLoaderConfig.get(annoType);
            return valueLoader.load(annotation, paramName, ctx1);
        }
        return null;
    };
}

private Annotation[][] getAllAnnotations(Parameter[] parameters) {
    Annotation[][] annotations = new Annotation[parameters.length][];
    for (int i = 0; i < parameters.length; i++) {
        annotations[i] = parameters[i].getAnnotations();
    }
    return annotations;
}
