public class Downloader {

    public static byte[] downloadFromUri(String uri) throws IOException {
        byte[] data = null;
        URL url = new URL(uri);
        Path tempFile = Files.createTempFile("download", null); // create a temporary file to store the downloaded bytes
        Files.copy(url.openStream(), tempFile, StandardCopyOption.REPLACE_EXISTING);
        data = Files.readAllBytes(tempFile); // read the bytes from the temporary file into a byte array
        Files.deleteIfExists(tempFile); // delete the temporary file
        return data;
    }
}
