import java.util.*;

public Map<String, String> getOrderedParameters(QueryObject query, Map<String, String> allParameters) {
    Map<String, String> orderedParams = new LinkedHashMap<>();
    Set<String> visitedParams = new HashSet<>();

    for (Map.Entry<String, String> entry : allParameters.entrySet()) {
        String param = entry.getKey();
        String value = entry.getValue();
        visitParam(query, allParameters, param, value, visitedParams, orderedParams);
    }

    return orderedParams;
}

private void visitParam(QueryObject query, Map<String, String> allParameters, String param, String value, Set<String> visitedParams, Map<String, String> orderedParams) {
    if (visitedParams.contains(param)) {
        return;
    }

    visitedParams.add(param);

    if (query.contains(param)) {
        for (String dependent : query.getDependents(param)) {
            if (allParameters.containsKey(dependent)) {
                visitParam(query, allParameters, dependent, allParameters.get(dependent), visitedParams, orderedParams);
            }
        }
    }

    orderedParams.put(param, value);
}
