public static Writable readWithType(DataInput dataInput) throws IOException {
    Writable writable;
    String className = dataInput.readUTF();
    try {
        Class<?> writableClass = Class.forName(className);
        writable = (Writable) writableClass.newInstance();
        writable.readFields(dataInput);
    } catch (ClassNotFoundException | IllegalAccessException | InstantiationException e) {
        throw new IOException("Error reading writable", e);
    }
    return writable;
}
