public static void extendImage(int[][] image, int padding) {
    int width = image[0].length;
    int height = image.length;

    // Extend the top and bottom rows:
    for (int i = 0; i < width; i++) {
        for (int j = 0; j < padding; j++) {
            image[j][i] = image[padding][i];
            image[height - 1 - j][i] = image[height - 1 - padding][i];
        }
    }

    // Extend the left and right columns:
    for (int i = 0; i < height; i++) {
        for (int j = 0; j < padding; j++) {
            image[i][j] = image[i][padding];
            image[i][width - 1 - j] = image[i][width - 1 - padding];
        }
    }

    // Extend the four corners by copying the nearest pixel:
    for (int i = 0; i < padding; i++) {
        for (int j = 0; j < padding; j++) {
            image[i][j] = image[padding][padding];
            image[i][width - 1 - j] = image[padding][width - 1 - padding];
            image[height - 1 - i][j] = image[height - 1 - padding][padding];
            image[height - 1 - i][width - 1 - j] = image[height - 1 - padding][width - 1 - padding];
        }
    }
}
