public LocalDateTime parseLocalDateTime(TimeZone tz, byte[] bytes) throws PSQLException {
    ByteBuffer buffer = ByteBuffer.wrap(bytes);
    // Extract the OID
    int oid = buffer.getInt();
    // Check if the OID is compatible with timestamp or timestamptz
    if (oid != Oid.TIMESTAMP && oid != Oid.TIMESTAMPTZ) {
        throw new PSQLException("Invalid OID for local date time object", PSQLState.INVALID_PARAMETER_VALUE);
    }
    // Extract the number of microseconds since 2000-01-01 00:00:00
    long micros = buffer.getLong();
    // Convert to milliseconds and add to the base date
    LocalDateTime baseDate = LocalDateTime.of(2000, 1, 1, 0, 0, 0);
    long millis = (micros / 1000) + (micros % 1000 >= 500 ? 1 : 0);
    LocalDateTime localDateTime = baseDate.plus(millis, ChronoUnit.MILLIS);
    // Adjust to the given time zone
    ZonedDateTime zonedDateTime = ZonedDateTime.of(localDateTime, ZoneId.systemDefault());
    ZonedDateTime adjustedZone = zonedDateTime.withZoneSameInstant(tz.toZoneId());
    return adjustedZone.toLocalDateTime();
}
