public Set<Region> findLocalMaximums(Set<Region> regions) {
    Set<Region> output = new HashSet<>();
    for (Region r : regions) {
        boolean isLocalMaximum = true;
        for (Region neighbor : regions) {
            if (!r.equals(neighbor) && r.overlaps(neighbor)) {
                if (r.getConfidence() <= neighbor.getConfidence()) {
                    isLocalMaximum = false;
                    break;
                }
            }
        }
        if (isLocalMaximum) {
            output.add(r);
        }
    }
    return output;
}
