public static int parseInt(String s, int pos) {
    int radix = 10;
    int result = 0;
    boolean negative = false;
    char ch = s.charAt(pos);

    if (ch == '-') {
        negative = true;
        pos++;
    } else if (ch == '+') {
        pos++;
    }

    if (s.regionMatches(pos, "0x", 0, 2)) {
        pos += 2;
        radix = 16;
    } else if (ch == '0') {
        pos++;
        radix = 8;
    }

    while (pos < s.length()) {
        ch = s.charAt(pos);
        int digit = Character.digit(ch, radix);
        if (digit == -1) {
            break;
        }
        result = result * radix + digit;
        pos++;
    }

    if (negative) {
        result = -result;
    }

    return result;
}
