public static AsyncOutputStream convertToAsyncOutputStream(AsynchronousFileChannel asynchronousFileChannel) {
    return new AsyncOutputStream() {
        @Override
        public void write(byte[] bytes, int offset, int length, AsyncHandler<Void> asyncHandler) {
            ByteBuffer buffer = ByteBuffer.wrap(bytes, offset, length);
            long position = getCurrentPosition();
            asynchronousFileChannel.write(buffer, position, null, new CompletionHandler<Integer, Void>() {
                @Override
                public void completed(Integer result, Void attachment) {
                    updatePosition(result);
                    asyncHandler.completed(null);
                }

                @Override
                public void failed(Throwable exc, Void attachment) {
                    asyncHandler.failed(exc);
                }
            });
        }

        @Override
        public void close(AsyncHandler<Void> asyncHandler) {
            try {
                asynchronousFileChannel.close();
                asyncHandler.completed(null);
            } catch (IOException e) {
                asyncHandler.failed(e);
            }
        }

        private long currentPosition = 0;

        private synchronized long getCurrentPosition() {
            return currentPosition;
        }

        private synchronized void updatePosition(int bytesWritten) {
            currentPosition += bytesWritten;
        }
    };
}
