public static int checkMatchInTailArray(int[] base, int index, int key) {
    if (index >= base.length) {
        return -1; // Negative means it doesn't match.
    }
    int value = base[index];
    if (value == key) {
        if (index == base.length - 1) {
            return index; // Index is complete match.
        } else {
            return 0; // 0 means it is prefix match.
        }
    } else {
        return checkMatchInTailArray(base, index + 1, key); // Recurse on the next index.
    }
}
