public boolean computePixelLocation(Point3D worldPt, Point2D pixelPt) {
    double x = worldPt.getX();
    double y = worldPt.getY();
    double z = worldPt.getZ();

    if (z < 0) {
        return false;
    }

    double fx = camera.getFx();
    double fy = camera.getFy();
    double cx = camera.getCx();
    double cy = camera.getCy();

    double u = fx * x / z + cx;
    double v = fy * y / z + cy;

    pixelPt.setLocation(u, v);
    return true;
}
