public Expression simplifyBinaryExpression(BinaryExpression be, Type targetType) {
    if (be.getLeft() instanceof ConstantExpression && be.getRight() instanceof ConstantExpression) {
        int leftValue = ((ConstantExpression) be.getLeft()).getValue();
        int rightValue = ((ConstantExpression) be.getRight()).getValue();
        int result;
        switch (be.getOperation()) {
            case PLUS:
                result = leftValue + rightValue;
                break;
            case MINUS:
                result = leftValue - rightValue;
                break;
            case DIVIDE:
                result = leftValue / rightValue;
                break;
            case MULTIPLY:
                result = leftValue * rightValue;
                break;
            default:
                result = 0; // or throw an exception, depending on requirements
                break;
        }
        return new ConstantExpression(result);
    } else {
        return be;
    }
}
