public boolean hasSideEffects(Expression expr) {
    if (expr instanceof AssignmentExpression) {
        return true;
    } else if (expr instanceof CallExpression) {
        return true;
    } else if (expr instanceof UnaryExpression) {
        final Operator operator = ((UnaryExpression) expr).getOperator();
        return operator == Operator.DELETE || operator == Operator.INC || operator == Operator.DEC;
    } else if (expr instanceof BinaryExpression) {
        final Operator operator = ((BinaryExpression) expr).getOperator();
        return operator == Operator.ASSIGN || operator == Operator.ASSIGN_ADD || operator == Operator.ASSIGN_SUB || operator == Operator.ASSIGN_MUL || operator == Operator.ASSIGN_DIV || operator == Operator.ASSIGN_MOD || operator == Operator.ASSIGN_BIT_AND || operator == Operator.ASSIGN_BIT_OR || operator == Operator.ASSIGN_BIT_XOR || operator == Operator.ASSIGN_SHIFT_LEFT || operator == Operator.ASSIGN_SHIFT_RIGHT;
    }
    return false;
}
