public static int lcm(int x, int y) {
    int max, lcm = 0;

    // Get the maximum number between x and y
    if (x > y) {
        max = x;
    } else {
        max = y;
    }

    // Loop until least common multiple is found
    while (true) {
        if (max % x == 0 && max % y == 0) {
            lcm = max;
            break;
        }
        max++;
    }

    return lcm;
}
