public String generateCatchCode(CatchTree tree, Env<?> env, int startpc, int endpc){
    StringBuilder codeBuilder = new StringBuilder();
    // retrieve exception variable name
    VariableTree variableTree = tree.getParameter();
    String exceptionVarName = variableTree.getName().toString();
    // generate catch block
    codeBuilder.append("catch (")
              .append(tree.getParameter().toString())
              .append(") {\n");
    // create new environment for catch block
    EnvWithExceptionHandler catchEnv = env.dup();
    // define the exception variable
    int catchEntry = catchEnv.nextLocal++;
    String catchVarTypeName = catchEnv.enclMethodSym.type.getThrownTypes().head.toString();
    codeBuilder.append(catchVarTypeName)
              .append(" ")
              .append(exceptionVarName)
              .append(" = (")
              .append(catchVarTypeName)
              .append(")")
              .append("$in.readObject();\n");
    catchEnv.scope.enter();
    Symbol.VarSymbol catchVarSym =
            new VarSymbol(0,
                          names.fromString(exceptionVarName),
                          catchEnv.enclMethodSym.type.getThrownTypes().head,
                          catchEnv.scope);
    catchEnv.scope.enter(catchVarSym);
    catchEnv.info.vars[catchEntry] = catchVarSym;
    // generate catch block statements
    for (StatementTree statement : tree.getBlock().getStatements()) {
        codeBuilder.append(translate(statement, catchEnv));
    }
    // close catch block
    codeBuilder.append("}\n");
    return codeBuilder.toString();
}
