public static String deriveOuterClassName(String protoFileName) {
    String[] parts = protoFileName.split("\\.");
    String imageName = parts[0];
    String[] nameParts = imageName.split("_");
    StringBuilder outerClassNameBuilder = new StringBuilder();
    for(String namePart : nameParts) {
        outerClassNameBuilder.append(Character.toUpperCase(namePart.charAt(0)));
        if(namePart.length() > 1) {
            outerClassNameBuilder.append(namePart.substring(1));
        }
    }
    return outerClassNameBuilder.toString();
}
