public BaseResponse sendDeleteRequest(Service service, Map<String, String> req_args) throws Exception {
    // Create HTTP client and DELETE request
    CloseableHttpClient httpClient = HttpClients.createDefault();
    HttpDelete httpDelete = new HttpDelete(service.getUrl());

    // Set headers for DELETE request
    httpDelete.setHeader(HttpHeaders.CONTENT_TYPE, "application/json");
    httpDelete.setHeader(HttpHeaders.ACCEPT, "application/json");

    // Set query parameters for DELETE request
    List<NameValuePair> queryParams = new ArrayList<>();
    for (Map.Entry<String, String> entry : req_args.entrySet()) {
        queryParams.add(new BasicNameValuePair(entry.getKey(), entry.getValue()));
    }
    httpDelete.setURI(new URI(httpDelete.getURI().toString() + "?" + URLEncodedUtils.format(queryParams, "utf-8")));

    // Execute DELETE request and read response
    CloseableHttpResponse httpResponse = httpClient.execute(httpDelete);
    InputStream responseStream = httpResponse.getEntity().getContent();
    String responseString = IOUtils.toString(responseStream, StandardCharsets.UTF_8);

    // Close HTTP client request
    httpClient.close();

    // Convert response to BaseResponse object
    return new BaseResponse(responseString);
}
