public static LineString interpolateLineString(LineString lineString) {
    Coordinate[] coordinates = lineString.getCoordinates();
    double startZ = coordinates[0].getZ();
    double endZ = coordinates[coordinates.length-1].getZ();

    if (Double.isNaN(startZ) || Double.isNaN(endZ)) {
        return lineString;
    }

    double slope = (endZ - startZ) / (coordinates.length-1);

    for(int i=0; i<coordinates.length; i++) {
        double z = startZ + i*slope;
        Coordinate coordinate = coordinates[i];
        coordinate.setZ(z);
    }

    return new LineString(coordinates, lineString.getFactory());
}
