public static void removeNulls(JsonNode source) {
    if (source == null) {
        return;
    }
    if (source.isArray()) {
        for (int i = 0; i < source.size(); i++) {
            JsonNode child = source.get(i);
            if (child.isNull()) {
                ((ArrayNode) source).remove(i--);
            } else {
                removeNulls(child);
            }
        }
    } else if (source.isObject()) {
        Iterator<Map.Entry<String, JsonNode>> fields = source.fields();
        while (fields.hasNext()) {
            Map.Entry<String, JsonNode> field = fields.next();
            JsonNode child = field.getValue();
            if (child.isNull()) {
                fields.remove();
            } else {
                removeNulls(child);
            }
        }
    }
}
