public void buildHulls(Cluster clu, ClusteringHierarchy hier, Map<Cluster, Hull> hulls) {
    if (clu.isLeaf()) { // base case
        hulls.put(clu, new Hull(clu.getPoints()));
    } else {
        Cluster leftChild = hier.getLeftChild(clu);
        Cluster rightChild = hier.getRightChild(clu);
        buildHulls(leftChild, hier, hulls);
        buildHulls(rightChild, hier, hulls);
        Hull leftHull = hulls.get(leftChild);
        Hull rightHull = hulls.get(rightChild);
        Hull combinedHull = Hull.combine(leftHull, rightHull);
        hulls.put(clu, combinedHull);
    }
}
