public Block modifyBlockMap(Block block) throws IOException {
   // Assuming the 'blockMap' is a HashMap or similar key-value data structure that stores block to datanode mapping.
   // Also assuming that 'neededReplications' is a set that holds the blocks that need replication.

   DatanodeInfo datanode = blockMap.get(block); // Retrieve the datanode where the block is residing
   if (datanode == null) {
      throw new IOException("Block does not exist in blockMap!");
   }

   // Remove from 'neededRepications' set if this datanode now has enough replicas for this block
   Collection<DatanodeDescriptor> nodesContainingBlock = blocksMap.getNodes(block);
   if (nodesContainingBlock == null || nodesContainingBlock.size() <= block.replication) {
      neededReplications.remove(block, datanode);
   }

   return blockMap.remove(block); // Remove the block from the map and return it.
}
