public List<EngineeringObject> getChangedObjects(EKBCommit commit, EKBModel model) {
    List<EngineeringObject> changedObjects = new ArrayList<>();
    List<EKBObject> modelObjects = model.getObjects();

    for (EKBObject obj : modelObjects) {
        if (obj instanceof EngineeringObject) {
            EngineeringObject engObj = (EngineeringObject) obj;
            if (commit.getChangedObjects().contains(engObj.getId())) {
                changedObjects.add(engObj);
            }
        }
    }

    return changedObjects;
}
