public void appendDigits(int num, int mindigits, int maxdigits, StringBuilder sb){
    String strNum = String.valueOf(num);
    int numDigits = strNum.length();
    int zerosToAdd = Math.max(mindigits-numDigits, 0);
    int digitsToAdd = Math.min(maxdigits-numDigits, zerosToAdd);
    for(int i=0; i<digitsToAdd; i++){ 
        sb.append(this.zero); 
    }
    for(int i=0; i<zerosToAdd; i++){ 
        sb.append("0"); 
    }
    sb.append(strNum);
}
