public Set<Formula> computeBackbone(Collection<Formula> formulas, Collection<Variable> variables, BackboneType backboneType) {
    Solver solver = SolverFactory.newDefault();
    Set<Formula> backbone = new HashSet<>();

    for (Variable variable : variables) {
        try {
            solver.push();

            switch (backboneType) {
                case NEGATIVE:
                    solver.add(formulas);
                    solver.add(variable.negate());
                    break;
                case POSITIVE:
                    solver.add(formulas);
                    solver.add(variable);
                    break;
                case STRICT:
                    solver.add(formulas);
                    solver.add(variable);
                    solver.add(variable.negate().asDisjunction());
                    break;
            }

            if (solver.isSatisfiable()) {
                backbone.add(variable);
            } else if (solver.isUnsatisfiable()) {
                return null;
            }

            solver.pop();
        } catch (ContradictionException e) {
            // variable already assigned, skip
        }
    }

    return backbone;
}
