public String getKMLTypeRepresentation(int sqlTypeId, String sqlTypeName) throws SQLException {
    String kmlType = null;
    switch (sqlTypeId) {
        case Types.BIT:
        case Types.BOOLEAN:
            kmlType = "boolean";
            break;
        case Types.TINYINT:
        case Types.SMALLINT:
        case Types.INTEGER:
            kmlType = "int";
            break;
        case Types.BIGINT:
            kmlType = "long";
            break;
        case Types.DOUBLE:
        case Types.FLOAT:
        case Types.REAL:
            kmlType = "float";
            break;
        case Types.NUMERIC:
        case Types.DECIMAL:
        case Types.CHAR:
        case Types.VARCHAR:
        case Types.LONGVARCHAR:
        case Types.DATE:
        case Types.TIME:
        case Types.TIMESTAMP:
        default:
            kmlType = "string";
            break;
    }
    return kmlType;
}
