public boolean isRestorable(String version, String dataset) {
    File versionFile = new File(version);
    File datasetFile = new File(dataset);

    if(versionFile.exists() && datasetFile.exists() && versionFile.getAbsolutePath().equals(datasetFile.getAbsolutePath())) {
        // Version points to the same data location as dataset
        return false;
    } else if(versionFile.length() == 0 || !versionFile.exists()) {
        // Version points to an empty or non-existent data location
        return false;
    } else {
        return true;
    }
}
