public int countAdditionalOccurrences(String property, int count) {
    int totalCount = 0;
    for(int i = 0; i < count; i++) {
        String reference = "reference" + (i+1) + "_" + property;
        int occurrences = reference.split(property, -1).length - 1;
        totalCount += occurrences;
    }
    return totalCount;
}
