public class ScenarioConfiguration {

    private List<Agent> agents;
    private List<Action> actions;

    public ScenarioConfiguration(List<Agent> agents, List<Action> actions) throws DuplicatedAgentIDException, DuplicatedActionIDException {
        this.agents = new ArrayList<>();
        this.actions = new ArrayList<>();

        // check for duplicate agent IDs
        Set<Integer> agentIds = new HashSet<>();
        for (Agent agent : agents) {
            if (agentIds.contains(agent.getId())) {
                throw new DuplicatedAgentIDException();
            }
            agentIds.add(agent.getId());
            this.agents.add(agent);
        }

        // check for duplicate action IDs
        Set<Integer> actionIds = new HashSet<>();
        for (Action action : actions) {
            if (actionIds.contains(action.getId())) {
                throw new DuplicatedActionIDException();
            }
            actionIds.add(action.getId());
            this.actions.add(action);
        }
    }

    // getters and setters

}
