import org.tensorflow.Tensor;
import org.tensorflow.types.Type;
import org.nd4j.linalg.api.ndarray.INDArray;
import org.nd4j.nativeblas.NativeOpsHolder;

public static Tensor toTensorWithZeroCopy(INDArray ndArray) {
    int[] shape = new int[ndArray.rank()];
    long[] stride = new long[ndArray.rank()];
    for (int i = 0; i < ndArray.rank(); i++) {
        shape[i] = (int)ndArray.shape()[i];
        stride[i] = ndArray.stride(i);
    }
    int[] intShape = Arrays.stream(shape).map(i -> (int) i).toArray();
    long size = ndArray.length();
    Pointer pointer = NativeOpsHolder.getInstance().getDeviceNativeOps().pointerForAddress(ndArray.data().pointer());
    return Tensor.allocate(Type.FLOAT, intShape, pointer, size);
}
