public CE getPreviousCE(Data data, CollationBuffer collationBuffer, boolean isNumeric) {
    int c = collationBuffer.getChar();
    while (c != CollationBuffer.DONE) {
        int ce = collationBuffer.getCE();
        if (data.isUnsafeBackward(c, isNumeric)) {
            return Collation.backwardCompatibleCE32(ce);
        }
        c = collationBuffer.previousChar();
    }
    return Collation.FALLBACK_CE;
}
