import io.micrometer.core.instrument.Clock;
import io.micrometer.core.instrument.Counter;
import io.micrometer.core.instrument.MeterRegistry;
import io.micrometer.core.instrument.Tag;
import io.micrometer.core.instrument.Timer;

public class TaskTimer {

    private final MeterRegistry registry;

    public TaskTimer(MeterRegistry registry) {
        this.registry = registry;
    }

    public void measureTask(String name, String... tags) {
        Timer timer = Timer.builder(name)
                .tags(parseTags(tags))
                .register(registry);

        timer.record(() -> {
            // code block to measure time
        });
    }

    public Counter getTaskCount(String name, String... tags) {
        Counter counter = Counter.builder(name)
                .tags(parseTags(tags))
                .register(registry);

        counter.increment();
        return counter;
    }

    private Tag[] parseTags(String... tags) {
        if (tags.length % 2 != 0) {
            throw new IllegalArgumentException("Tags must be an even number of arguments representing key/value pairs of tags");
        }

        Tag[] tagArray = new Tag[tags.length / 2];
        for (int i = 0; i < tags.length; i += 2) {
            tagArray[i / 2] = Tag.of(tags[i], tags[i + 1]);
        }

        return tagArray;
    }
}
