   while (i < input.length() && (input.charAt(i) == 'E' || input.charAt(i) == 'N')) {
      if (input.charAt(i) == 'E') {
         if (input.charAt(i+1) == 'Q') {
            result = result && cmp(input.substring(i+2));
            i += 3;
         } else {
            return false;
         }
      } else {
         if (input.charAt(i+1) == 'E') {
            result = result && !cmp(input.substring(i+2));
            i += 2;
         } else {
            return false;
         }
      }
   }

   return result;
}

