public List<String> loadLegacyWarnings(List<String> legacyWarnings) {
    List<String> resultList = new ArrayList<String>();
    for(String warning : legacyWarnings) {
        String warningWithoutLineNumber = warning.replaceAll("\\d+", "");
        if(!resultList.contains(warningWithoutLineNumber)) {
            resultList.add(warningWithoutLineNumber);
        }
    }
    return resultList;
}
