public static double calculateAvg(List<LasRecord> points, String valueType) {
    double sum = 0;
    int count = 0;
    for (LasRecord point : points) {
        double val = point.getValues().get(valueType);
        if (!Double.isNaN(val)) {
            sum += val;
            count++;
        }
    }
    return count == 0 ? Double.NaN : sum / count;
}
