public String convertPartTreeToWhereQuery(PartTree partTree) {
    Iterator<Part> parts = partTree.iterator();
    StringBuilder whereQuery = new StringBuilder("(");
    while (parts.hasNext()) {
        Part part = parts.next();
        String fieldName = part.getProperty().getSegment();
        switch (part.getType()) {
            case SIMPLE_PROPERTY:
                whereQuery.append(fieldName).append(" = ? ");
                break;
            case NEGATING_SIMPLE_PROPERTY:
                whereQuery.append(fieldName).append(" != ? ");
                break;
            case LIKE:
                whereQuery.append(fieldName).append(" like ? ");
                break;
            case NOT_LIKE:
                whereQuery.append(fieldName).append(" not like ? ");
                break;
            case GREATER_THAN:
                whereQuery.append(fieldName).append(" > ? ");
                break;
            case GREATER_THAN_EQUAL:
                whereQuery.append(fieldName).append(" >= ? ");
                break;
            case LESS_THAN:
                whereQuery.append(fieldName).append(" < ? ");
                break;
            case LESS_THAN_EQUAL:
                whereQuery.append(fieldName).append(" <= ? ");
                break;
            case BETWEEN:
                whereQuery.append(fieldName).append(" between ? and ? ");
                break;
            case IN:
                whereQuery.append(fieldName).append(" in ? ");
                break;
            case NOT_IN:
                whereQuery.append(fieldName).append(" not in ? ");
                break;
            default:
                throw new IllegalArgumentException("Unsupported part type: " + part.getType());
        }

        if (parts.hasNext()) {
            whereQuery.append("and ");
        }
    }
    whereQuery.append(")");
    return whereQuery.toString();
}
