private void setCardViewElevation(int elevation) {
    if (getResources().getBoolean(R.bool.is_split_screen)) {
        if (elevation < 0) elevation = 0;
        if (elevation > 16) elevation = 16;
        PreferenceFragment preferenceFragment =
                (PreferenceFragment) getSupportFragmentManager().findFragmentById(R.id.preference_fragment);
        if (preferenceFragment != null) {
            View view = preferenceFragment.getView();
            if (view != null) {
                int px = (int) TypedValue.applyDimension(TypedValue.COMPLEX_UNIT_DIP,
                        elevation, getResources().getDisplayMetrics());
                ViewCompat.setElevation(view, px);
            }
        }
    }
}
