public boolean updateLastRecoveryTimeIfExpired(Date lastRecoveryTime, int recoveryTimeInMinutes) {
    Date currentDateTime = new Date();
    long elapsedTime = currentDateTime.getTime() - lastRecoveryTime.getTime();
    long recoveryTimeInMillis = recoveryTimeInMinutes * 60 * 1000;
    if (elapsedTime >= recoveryTimeInMillis) {
        lastRecoveryTime.setTime(currentDateTime.getTime());
        return true;
    }
    return false;
}
