import java.util.*;

public class MyClass {

    public static Set<Class<?>> getSubclasses(Class<?> clazz, Map<Class<?>, Set<Class<?>>> classToSubclass) {
        Set<Class<?>> subclasses = new HashSet<>();
        Set<Class<?>> classes = getClassHierarchy(clazz);
        classes.remove(clazz); // Exclude the passed class itself

        for (Class<?> cls : classes) {
            Set<Class<?>> directSubclasses = new HashSet<>();
            for (Class<?> c : classes) {
                if (c.getSuperclass() != null && c.getSuperclass().equals(cls)) {
                    directSubclasses.add(c);
                }
            }
            if (!directSubclasses.isEmpty()) {
                subclasses.add(cls);
                classToSubclass.put(cls, directSubclasses);
            }
        }
        return subclasses;
    }

    private static Set<Class<?>> getClassHierarchy(Class<?> clazz) {
        Set<Class<?>> classes = new HashSet<>();
        while (clazz != null) {
            classes.add(clazz);
            clazz = clazz.getSuperclass();
        }
        return classes;
    }
}
