public void extractAndInsertMappings(DataSource dataSource, Map<String, String> preprocessedMapping) {
    try {
        Connection connection = dataSource.getConnection();
        Statement statement = connection.createStatement();
        ResultSet resultSet = statement.executeQuery("SELECT * FROM mappings");

        while (resultSet.next()) {
            String mappingId = UUID.randomUUID().toString();
            String sourceKey = resultSet.getString("source_key");
            String targetKey = resultSet.getString("target_key");

            if (preprocessedMapping.containsKey(sourceKey)) {
                throw new RuntimeException("Duplicate Exception for source key: " + sourceKey);
            }

            preprocessedMapping.put(sourceKey, targetKey);
        }

        resultSet.close();
        statement.close();
        connection.close();
    } catch (SQLException e) {
        throw new RuntimeException("Something went wrong while extracting and inserting mappings", e);
    }
}
