public static Map<String, Object> diff(Map<String, Object> old, Map<String, Object> nw) {
    Map<String, Object> diff = new HashMap<>();

    // check for new or modified keys
    for (String key : nw.keySet()) {
        if (!old.containsKey(key) || !old.get(key).equals(nw.get(key))) {
            diff.put(key, nw.get(key));
        }
    }

    // check for removed keys
    for (String key : old.keySet()) {
        if (!nw.containsKey(key)) {
            diff.put(key, null);
        }
    }

    return diff;
}
