public Map<String, String> createParameterMap(HttpServletRequest request) throws IOException {
    Map<String, String> paramMap = new HashMap<>();
    String body = null;
    try (Scanner scanner = new Scanner(request.getInputStream(), StandardCharsets.UTF_8.name())) {
        body = scanner.useDelimiter("\\A").next();
    }
    if (body != null && !body.isEmpty()) {
        String[] params = body.split("&");
        for (String param : params) {
            String[] keyValue = param.split("=");
            if (keyValue.length > 1) {
                String key = URLDecoder.decode(keyValue[0], StandardCharsets.UTF_8.name());
                String value = URLDecoder.decode(keyValue[1], StandardCharsets.UTF_8.name());
                paramMap.put(key, value);
            }
        }
    }
    return paramMap;
}
