public static int readUTF8(byte[] bytes, int offset) {
    int numBytes = 0;
    int codePoint = bytes[offset] & 0xFF;
    if ((codePoint & 0x80) == 0x00) {
        numBytes = 1;
    } else if ((codePoint & 0xE0) == 0xC0) {
        numBytes = 2;
        codePoint &= 0x1F;
    } else if ((codePoint & 0xF0) == 0xE0) {
        numBytes = 3;
        codePoint &= 0x0F;
    } else if ((codePoint & 0xF8) == 0xF0) {
        numBytes = 4;
        codePoint &= 0x07;
    } else {
        return INVALID;
    }

    for (int i = 1; i < numBytes; i++) {
        codePoint <<= 6;
        codePoint += bytes[offset + i] & 0x3F;
    }

    return codePoint;
}
