import java.util.*;

public static double[][] createSymmetricMatrix(int num, Random rand, double[] eigenvalues) {
    double[][] matrix = new double[num][num];
    double[][] symmetricMatrix = new double[num][num];

    for (int i = 0; i < num; i++) {
        for (int j = 0; j < num; j++) {
            if (j >= i) {
                matrix[i][j] = rand.nextDouble();
                matrix[j][i] = matrix[i][j];
            }
        }
    }

    for (int i = 0; i < num; i++) {
        for (int j = 0; j < num; j++) {         
            symmetricMatrix[i][j] = eigenvalues[i] * matrix[i][j];
            symmetricMatrix[j][i] = symmetricMatrix[i][j];
        }
    }

    return symmetricMatrix;
}
