public static void rewireGlobalClassTypes() throws ClassNotFoundException {
    ClassLoader classLoader = Thread.currentThread().getContextClassLoader();
    Class<?> serializedClass = classLoader.loadClass("YOUR_CLASS_NAME");

    ObjectOutputStream out = null;
    ObjectInputStream in = null;

    try {
        out = new ObjectOutputStream(new ByteArrayOutputStream());
        out.writeObject(new YOUR_CLASS_NAME());

        in = new ObjectInputStream(new ByteArrayInputStream(out.toByteArray()));
        in.readObject();

    } catch (IOException e) {
        throw new ClassNotFoundException("Failed to re-wire global class types after serialization.", e);
    } finally {
        try {
            if (out != null) {
                out.close();
            }
            if (in != null) {
                in.close();
            }
        } catch (IOException ex) {
            // Log the exception or re-throw as needed
        }
    }
}
