public class Builder<T> {
    private T instance;

    public Builder(T instance) {
        this.instance = instance;
    }

    public static <T> Builder<T> createBuilder(T instance) {
        return new Builder<>(instance);
    }

    public Builder<T> with(Function<T, T> function) {
        instance = function.apply(instance);
        return this;
    }

    public T build() {
        return instance;
    }
}
