import io.joshworks.snappy.http.server.Endpoint;

public class MySseEndPoint implements Endpoint {

    private final Sse sse = new Sse();
    private final SseBroadcaster broadcaster = new SseBroadcaster();

    @Override
    public Response call(EndpointRequest request) throws Exception {

        SseEventSink eventSink = sse.newEventSink();
        broadcaster.register(eventSink);

        ConnectionCallback connectionCallback = (request, response) -> {
            // define endpoint handler logic here
        };

        // register endpoint handler
        connectionCallback.onSubscribe(request, eventSink);

        return Response.ok(). contentType(MediaType.TEXT_PLAIN).body("Listening for SSE events...").sse(broadcaster).build();
    }
}
