public int getSui(int year) {
    // Get the winter solstice for the given year
    Calendar solstice = Calendar.getInstance();
    solstice.set(Calendar.YEAR, year);
    solstice.set(Calendar.MONTH, Calendar.DECEMBER);
    solstice.set(Calendar.DAY_OF_MONTH, 22);
    while (solstice.get(Calendar.DAY_OF_WEEK) != Calendar.SUNDAY) {
        solstice.add(Calendar.DATE, 1);
    }

    // Get the start and end of the sui period
    Calendar start = Calendar.getInstance();
    start.setTime(solstice.getTime());
    start.add(Calendar.MONTH, -10);
    Calendar end = Calendar.getInstance();
    end.setTime(solstice.getTime());
    end.add(Calendar.MONTH, 1);

    // Check if the sui period is in the same year as the given year
    if (start.get(Calendar.YEAR) == year) {
        return year;
    } else {
        return year + 1;
    }
}
