public Object[] mergePatches(Patch[] patches, String text) {
   StringBuilder patchedText = new StringBuilder(text);
   boolean[] appliedPatches = new boolean[patches.length];
   for (int i = 0; i < patches.length; i++) {
      if (!appliedPatches[i]) {
         Patch patch = patches[i];
         if (patch.getStartIndex() > patchedText.length()) {
            // Patch start index is beyond end of string
            continue;
         }
         if (patch.getStartIndex() + patch.getText().length() < patchedText.length()) {
            // Patch end index is before end of string
            continue;
         }
         patchedText.replace(patch.getStartIndex(), patch.getStartIndex() + patch.getText().length(), patch.getText());
         appliedPatches[i] = true;
      }
   }
   return new Object[]{patchedText.toString(), appliedPatches};
}
