public static void compressWithHuffman(OutputStream out, String data) throws IOException {
    // First, calculate the frequency of each character in the input string
    Map<Character, Integer> freqMap = new HashMap<>();
    for (int i = 0; i < data.length(); i++) {
        char c = data.charAt(i);
        freqMap.put(c, freqMap.getOrDefault(c, 0) + 1);
    }

    // Build the Huffman tree using the calculated frequency map
    HuffmanTree huffmanTree = HuffmanTree.build(freqMap);

    // Encode the input string using the built Huffman tree
    BitOutputStream bitOut = new BitOutputStream(out);
    huffmanTree.encode(data, bitOut);

    // Flush the buffer and close the output stream
    bitOut.flush();
    out.close();
}
