public Class<?>[] getComponentClasses(Class<?> clazz) {
    if (!clazz.isArray()) {
        return null;
    }
    Class<?> componentType = clazz.getComponentType();
    if (!componentType.isArray()) {
        return null;
    }
    int dimensions = getArrayDimensions(clazz);
    Class<?>[] componentClasses = new Class<?>[dimensions];
    componentClasses[0] = componentType;
    for (int i = 1; i < dimensions; i++) {
        componentType = componentType.getComponentType();
        componentClasses[i] = componentType;
    }
    return componentClasses;
}

private int getArrayDimensions(Class<?> clazz) {
    int dimensions = 0;
    while (clazz.isArray()) {
        dimensions++;
        clazz = clazz.getComponentType();
    }
    return dimensions;
}
