import java.util.HashMap;
import java.util.Map;

public class L2Normalizer {
    public static Counter<String> safeL2Normalize(Counter<String> c) {
        double norm = 0;
        Map<String, Double> countMap = new HashMap<String, Double>();
        for (String word : c.keySet()) {
            double count = c.getCount(word);
            norm += count * count;
            countMap.put(word, count);
        }
        norm = Math.sqrt(norm);
        Counter<String> normalizedCounter = new Counter<String>();
        if (norm > 0) {
            for (String word : countMap.keySet()) {
                double count = countMap.get(word);
                normalizedCounter.setCount(word, count / norm);
            }
        }
        return normalizedCounter;
    }
}
