public void readToBuffer(Reader reader, char[] buffer, int offset, int length) throws IOException {
    int charsRead = 0;
    while (charsRead < length - offset) {
        int read = reader.read(buffer, offset + charsRead, length - offset - charsRead);
        if (read == -1) {
            throw new IOException("Stream ended prematurely.");
        }
        charsRead += read;
    }
}
