public Number createNumber(Object source, Class<? extends Number> destinationType) {
    if (source == null) {
        return null;
    }
    if (destinationType.equals(Byte.class)) {
        return ((Number) source).byteValue();
    } else if (destinationType.equals(Short.class)) {
        return ((Number) source).shortValue();
    } else if (destinationType.equals(Integer.class)) {
        return ((Number) source).intValue();
    } else if (destinationType.equals(Long.class)) {
        return ((Number) source).longValue();
    } else if (destinationType.equals(Float.class)) {
        return ((Number) source).floatValue();
    } else if (destinationType.equals(Double.class)) {
        return ((Number) source).doubleValue();
    } else {
        throw new IllegalArgumentException("Invalid destination type provided.");
    }
}
