public String getCurrentStackAsString(boolean filter) {
    StackTraceElement[] stackTraceElements = Thread.currentThread().getStackTrace();
    if (filter) {
        List<StackTraceElement> stackTraceList = Arrays.asList(stackTraceElements);
        stackTraceList = stackTraceList.stream()
                .filter(s -> !s.getClassName().startsWith("java.util.concurrent.ThreadPoolExecutor"))
                .collect(Collectors.toList());
        stackTraceElements = stackTraceList.toArray(new StackTraceElement[stackTraceList.size()]);
    }
    return Arrays.toString(stackTraceElements);
}
