public class BulkAsyncApiController {

    @Autowired
    private BulkAsyncApiService bulkAsyncApiService;

    @PostMapping("/bulk")
    public ResponseEntity<String> bulkApiRequests(@RequestBody List<BulkAsyncApiRequest> apiRequests) {
        List<BulkAsyncApiResponse> apiResponses = bulkAsyncApiService.bulkApiRequests(apiRequests);
        String response = apiResponses.stream()
                .map(BulkAsyncApiResponse::getResponse)
                .collect(Collectors.joining("|"));
        return ResponseEntity.ok(response);
    }

    @PostMapping("/async")
    public ResponseEntity<String> asyncApiRequests(@RequestBody List<BulkAsyncApiRequest> apiRequests) {
        String jobId = bulkAsyncApiService.asyncApiRequests(apiRequests);
        return ResponseEntity.ok(jobId);
    }

    @GetMapping("/status/{jobId}")
    public ResponseEntity<String> getJobStatus(@PathVariable String jobId) {
        AsyncApiRequestStatus status = bulkAsyncApiService.getJobStatus(jobId);
        return ResponseEntity.ok(status.name());
    }

    @GetMapping("/result/{jobId}")
    public ResponseEntity<String> getJobResult(@PathVariable String jobId) {
        AsyncApiRequestResult result = bulkAsyncApiService.getJobResult(jobId);
        return ResponseEntity.ok(result.toString());
    }
}
