public Observable<SourceUploadDefinitionInner> getUploadLocation(String resourceGroupName, String registryName) throws IllegalArgumentException {
    // Validate parameters
    if (resourceGroupName == null || registryName == null) {
        throw new IllegalArgumentException("Invalid arguments for getUploadLocation function.");
    }

    // Call Azure SDK API to get upload location
    return azure.containerRegistries()
                .getByResourceGroup(resourceGroupName, registryName)
                .inner()
                .withTargetType("docker")
                .withOsType("linux")
                .withRegion(Region.US_WEST)
                .withStorageAccount(storageAccountName)
                .withName("acrbuildsource")
                .withRelativePath(relativePath)
                .getSourceUploadUrlAsync();
}
