public void addTypeParamsForExecutableMember(Member member, HtmlTree htmltree) {
    // Check if the member is an executable member
    if (member instanceof Executable) {
        // Get the type parameters for the executable member
        TypeVariable<? extends Executable>[] typeParams = ((Executable) member).getTypeParameters();

        // If there are type parameters, add them to the content tree
        if (typeParams.length > 0) {
            HtmlTree typeParamsTree = new HtmlTree(HtmlTag.UL);
            for (TypeVariable<? extends Executable> typeParam : typeParams) {
                typeParamsTree.addContent(new HtmlTree(HtmlTag.LI).addContent(typeParam.toString()));
            }
            htmltree.addContent(typeParamsTree);
        }
    }
}
