public String getResourceQueryDescription(String resourceUrl) {
    // Assume that 'resourceUrl' contains the query parameters in the URL

    String queryString = resourceUrl.substring(resourceUrl.indexOf("?") + 1);

    // Split the query string into individual parameters
    String[] queryParameters = queryString.split("&");

    // Build a description of the query
    StringBuilder queryDescription = new StringBuilder();
    queryDescription.append("Query parameters:\n");

    for (String param : queryParameters) {
        String[] parts = param.split("=");
        queryDescription.append("\t").append(parts[0]).append(": ").append(parts[1]).append("\n");
    }

    return queryDescription.toString();
}
