public class GCloudVersionChecker {

    public static boolean isSDKUpToDate() {
        try {
            Process p = Runtime.getRuntime().exec("gcloud components update --dry-run");
            BufferedReader reader = new BufferedReader(new InputStreamReader(p.getInputStream()));
            String line = reader.readLine();
            while (line != null) {
                if (line.contains("This will update")) {
                    return false;
                }
                line = reader.readLine();
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
        return true;
    }
}
