public CurrencyUnit getCurrencyUnit(CurrencyQuery currencyQuery) {
    Objects.requireNonNull(currencyQuery, "CurrencyQuery must not be null");
    CurrencyContext currencyContext = currencyQuery.getCurrencyContext();
    List<CurrencyUnit> matchingCurrencyUnits = new ArrayList<>();
    Iterable<CurrencyUnit> currencyUnits = this.getCurrencyUnits(currencyQuery);
    for (CurrencyUnit currencyUnit : currencyUnits) {
        if (currencyContext == null || currencyUnit.getContext().equals(currencyContext)) {
            matchingCurrencyUnits.add(currencyUnit);
        }
    }
    if (matchingCurrencyUnits.isEmpty()) {
        return null;
    }
    return matchingCurrencyUnits.get(0);
}
