public int getMatchingCPDefinitionsCount(int CProductId, String status) {
    //use your database connection to execute the SQL query
    String sqlQuery = "SELECT COUNT(*) FROM cp_definition "
                    + "WHERE CProductId = ? AND status = ?";
    int count = 0;
    try (PreparedStatement stmt = conn.prepareStatement(sqlQuery)) {
        stmt.setInt(1, CProductId);
        stmt.setString(2, status);
        ResultSet rs = stmt.executeQuery();
        if (rs.next()) {
            count = rs.getInt(1);
        }
    } catch (SQLException e) {
        e.printStackTrace();
    }
    return count;
}
