public void deleteTempMapOutputFiles(){
    String filePrefix = "map_"; //prefix of the temp files to be deleted

    File folder = new File("/path/to/temp/files/folder"); //specify the path to the folder containing temp files

    //get all files in the folder
    File[] files = folder.listFiles();

    //loop through the file list and delete all files with the specified prefix
    for(File file : files){
        if(file.getName().startsWith(filePrefix)){
            file.delete();
        }
    }
}
