public static String cutOffValidationMatcher(String expression) {
    String prefix = "valid(";
    String suffix = ")";
    if (expression.startsWith(prefix) && expression.endsWith(suffix)) {
        return expression.substring(prefix.length(), expression.length() - suffix.length());
    }
    return expression;
}
