public String resolveTemplate(ClientAnnotation clientAnnotation, String templateString) {
    String resolved = templateString;
    // Get the variables to replace in the template
    Map<String, String> variables = clientAnnotation.getVariables();
    // Replace all variables in template with actual values
    for (Map.Entry<String, String> entry : variables.entrySet()) {
        String variable = entry.getKey();
        String value = entry.getValue();
        resolved = resolved.replaceAll("\\{" + variable + "\\}", value);
    }
    return resolved;
}
