public Class getPrimaryKeyClass(String j2eeName) {
    if(j2eeName == null) {
        return null;
    }
    try {
        Context initialCtx = new InitialContext();
        Object homeObj = initialCtx.lookup(j2eeName);
        Home home = (Home) PortableRemoteObject.narrow(homeObj, Home.class);
        Method pkMethod = home.getClass().getMethod("getPrimaryKeyClass", null);
        Class pkClass = (Class) pkMethod.invoke(home, null);
        return pkClass;
    } catch(Exception ex) {
        return null;
    }
}
