public void compareAndModifyRelations(CmsContext cms, Resource importResource, List<Relation> relations) throws CmsException {
    Resource resource = cms.readResource(importResource.getPath());
    List<Relation> resourceRelations = resource.getRelations();

    for (Relation relation : relations) {
        if (!resourceRelations.contains(relation)) {
            resourceRelations.add(relation);
        }
    }

    cms.modifyResource(resource);
}
