import java.nio.file.Files;
import java.nio.file.Path;

public static void copyToExtensionDir(File file, String extensionDirPath) throws IOException {
    Path source = file.toPath();
    Path destDir = new File(extensionDirPath).toPath();

    // Add the extension to the file name
    String fileName = file.getName();
    String fileExt = fileName.substring(fileName.lastIndexOf('.'));
    String newFileName = fileName.replace(fileExt, "") + "_copy" + fileExt;

    Path destFile = destDir.resolve(newFileName);

    // Copy the file if it doesn't already exist in the extension directory
    if (!Files.exists(destFile)) {
        Files.copy(source, destFile);
