public static <T> void reorderListByTwoRotations(List<T> list, int startIndex, int pivotIndex, int endIndex) {

    // Step 1: Reverse the sublist from startIndex to pivotIndex
    Collections.reverse(list.subList(startIndex, pivotIndex + 1));

    // Step 2: Reverse the sublist from pivotIndex+1 to endIndex
    Collections.reverse(list.subList(pivotIndex + 1, endIndex + 1));

    // Step 3: Reverse the entire sublist from startIndex to endIndex
    Collections.reverse(list.subList(startIndex, endIndex + 1));

}
