private void copyAndAssignNewId(List<InMemoryMappingFile> inMemoryMappingFiles) {
    Map<ByteArrayWrapper, byte[]> byteArraysMappedById = new HashMap<>();
    for (InMemoryMappingFile inMemoryMappingFile : inMemoryMappingFiles) {
