public static Integer[] createColumnMapping(Model model, ColumnMapping reference, String modelName) {
    Integer[] mapping = new Integer[reference.size()];
    for (int i = 0; i < reference.size(); i++) {
        String columnName = reference.get(i);
        if (!model.getColumnNames().contains(columnName)) {
            System.err.println(String.format("Column '%s' not found in model '%s'", columnName, modelName));
            continue;
        }
        mapping[i] = model.getColumnIndex(columnName);
    }
    return mapping;
}
