import java.io.File;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;

public void removeJavaFiles(String path) {
    File file = new File(path);
    if (file.isDirectory()) {
        try {
            Path dir = Paths.get(path);
            Files.walk(dir)
                .filter(p -> p.toString().endsWith(".java")
                            || p.toString().endsWith(".class")
                            || p.toString().endsWith(".cache"))
                .forEach(p -> {
                    try {
                        Files.delete(p);
                    } catch (IOException e) {
                        e.printStackTrace();
                    }
                });
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
