import java.io.*;
import java.nio.charset.StandardCharsets;

public class Serializer {

    /**
     * Serializes to a byte stream using UTF-8 encoding and specifies that in the XML encoding declaration.
     * @since 1.504
     * @param obj object to be serialized
     * @return byte array containing serialized object
     * @throws IOException
     */
    public static byte[] serializeToByteStream(Object obj) throws IOException {
        ByteArrayOutputStream byteOutStream = new ByteArrayOutputStream();
        OutputStreamWriter utfWriter = new OutputStreamWriter(byteOutStream, StandardCharsets.UTF_8);
        ObjectOutputStream objOutStream = new ObjectOutputStream(byteOutStream);

        utfWriter.write("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n");
        utfWriter.flush();

        objOutStream.writeObject(obj);
        objOutStream.flush();

        byte[] serializedData = byteOutStream.toByteArray();

        utfWriter.close();
        objOutStream.close();
        byteOutStream.close();

        return serializedData;
    }
}
