public static double computeAverageFanOut(Iterable<Page> pages) {
    double totalFanOut = 0;
    int numPages = 0;
    for (Page page : pages) {
        totalFanOut += page.getOutgoingLinks().size();
        numPages++;
    }
    return (numPages > 0) ? (totalFanOut / numPages) : 0;
}
