public static int encodeDescendingOrderShort(Short value, byte[] dst, int dstOffset) {
    if (value == null) {
        throw new IllegalArgumentException("Input value cannot be null");
    }

    short encoded = value.shortValue();

    if (encoded >= 0x0000 && encoded <= 0x007f) {
        dst[dstOffset++] = (byte) encoded;
        return 1;
    } else if (encoded >= 0x0080 && encoded <= 0x7fff) {
        dst[dstOffset++] = (byte) (0x80 | (encoded & 0x007f));
        dst[dstOffset++] = (byte) ((encoded >> 7) & 0x007f);
        return 2;
    } else if (encoded <= -0x0080 && encoded >= -0x7fff) {
        dst[dstOffset++] = (byte) ((encoded >> 8) | 0x80);
        dst[dstOffset++] = (byte) ((encoded & 0x00ff));
        return 2;
    } else {
        dst[dstOffset++] = (byte) ((encoded >> 16) | 0x80);
        dst[dstOffset++] = (byte) ((encoded >> 8) & 0x00ff);
        dst[dstOffset++] = (byte) ((encoded & 0x00ff));
        return 3;
    }
}
