public class ByteVector {
    private byte[] vector;
    private int size;

    public ByteVector() {
        this.vector = new byte[10];
        this.size = 0;
    }

    public ByteVector putByte(byte b) {
        if (this.size == this.vector.length) {
            byte[] newVector = new byte[this.vector.length * 2];
            System.arraycopy(this.vector, 0, newVector, 0, this.vector.length);
            this.vector = newVector;
        }
        this.vector[this.size++] = b;
        return this;
    }
}
