public String readClassifierConfigurationParameterValue(MavenProject project, Log log) {
    String parameterValue = null;
    try {
        Plugin plugin = project.getPlugin("org.springframework.boot:spring-boot-maven-plugin");
        if (plugin != null) {
            Xpp3Dom configuration = (Xpp3Dom) plugin.getConfiguration();
            if (configuration != null) {
                Xpp3Dom classifier = configuration.getChild("classifier");
                if (classifier != null) {
                    parameterValue = classifier.getValue();
                } else {
                    log.warn("Classifier configuration parameter not found in the spring-boot-maven-plugin");
                }
            } else {
                log.warn("Plugin configuration not found for the spring-boot-maven-plugin");
            }
        } else {
            log.warn("spring-boot-maven-plugin not found in the project");
        }
    } catch (Exception e) {
        log.error("Error occurred while reading classifier configuration parameter", e);
    }
    return parameterValue;
}
