public Drawable adjustDrawableBounds(Drawable marker, Point hotspot) {
    if (marker == null || hotspot == null) {
        return null;
    }
    int markerWidth = marker.getIntrinsicWidth();
    int markerHeight = marker.getIntrinsicHeight();
    int left = hotspot.x - markerWidth / 2;
    int right = left + markerWidth;
    int top = hotspot.y - markerHeight / 2;
    int bottom = top + markerHeight;
    marker.setBounds(left, top, right, bottom);
    return marker;
}
