public class RegexUtils {

    public static List<GroupInfo> parseNamedGroups(String namedPattern) {
        List<GroupInfo> groupInfoList = new ArrayList<>();
        Pattern pattern = Pattern.compile("\\(\\?<([a-zA-Z][a-zA-Z0-9]*)>");
        Matcher matcher = pattern.matcher(namedPattern);
        while (matcher.find()) {
            GroupInfo groupInfo = new GroupInfo(matcher.group(1), matcher.start(), matcher.end());
            groupInfoList.add(groupInfo);
        }
        return groupInfoList;
    }

    public static class GroupInfo {
        private String name;
        private int startIndex;
        private int endIndex;

        public GroupInfo(String name, int startIndex, int endIndex) {
            this.name = name;
            this.startIndex = startIndex;
            this.endIndex = endIndex;
        }

        // getters and setters
    }
}
