public BitSet parseCharToBitSet(char[] charArray) {
    BitSet bitSet = new BitSet(charArray.length);
    for(int i=0; i<charArray.length; i++) {
        if(charArray[i] == '1') {
            bitSet.set(i, true);
        } else {
            bitSet.set(i, false);
        }
    }
    return bitSet;
}
