import org.w3c.dom.*;
import javax.xml.parsers.*;
import java.util.*;
import java.io.*;

public static List<String> getDifferencesBetweenDoms(String controlDom, String testDom, List<String> ignoreAttributes) throws Exception {

    List<String> differences = new ArrayList<String>();

    DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
    DocumentBuilder db = dbf.newDocumentBuilder();

    // Parse the control dom
    Document controlDoc = db.parse(new ByteArrayInputStream(controlDom.getBytes()));

    // Parse the test dom
    Document testDoc = db.parse(new ByteArrayInputStream(testDom.getBytes()));

    // Recursively compare the two DOMs
    recursivelyCompareNodes(controlDoc.getDocumentElement(), testDoc.getDocumentElement(), ignoreAttributes, differences);

    return differences;
}

private static void recursivelyCompareNodes(Node controlNode, Node testNode, List<String> ignoreAttributes, List<String> differences) {
    // Compare the nodes' types and names
    if (!controlNode.getNodeName().equals(testNode.getNodeName())) {
        differences.add("'" + controlNode.getNodeName() + "' node in control is different from '" + testNode.getNodeName() + "' node in test");
        return;
    } else if (controlNode.getNodeType() != testNode.getNodeType()) {
        differences.add("'" + controlNode.getNodeName() + "' node type in control is different from '" + testNode.getNodeName() + "' node type in test");
        return;
    }

    // Compare the nodes' attributes
    NamedNodeMap controlAttrs = controlNode.getAttributes();
    NamedNodeMap testAttrs = testNode.getAttributes();

    int controlAttrCount = controlAttrs == null ? 0 : controlAttrs.getLength();
    int testAttrCount = testAttrs == null ? 0 : testAttrs.getLength();

    boolean attrsEqual = controlAttrCount == testAttrCount;
    for (int i = 0; attrsEqual && i < testAttrCount; i++) {
        Node testAttr = testAttrs.item(i);

        if (ignoreAttributes.contains(testAttr.getNodeName())) {
            continue;
        }

        Node controlAttr = controlAttrs.getNamedItem(testAttr.getNodeName());

        attrsEqual = controlAttr.getNodeValue().equals(testAttr.getNodeValue());
    }

    if (!attrsEqual) {
        differences.add("'" + controlNode.getNodeName() + "' node attributes are different");
        return;
    }

    // Compare the nodes' children
    NodeList controlChildren = controlNode.getChildNodes();
    NodeList testChildren = testNode.getChildNodes();

    int controlChildCount = controlChildren == null ? 0 : controlChildren.getLength();
    int testChildCount = testChildren == null ? 0 : testChildren.getLength();

    int i = 0;
    for (; i < controlChildCount && i < testChildCount; i++) {
        Node controlChild = controlChildren.item(i);
        Node testChild = testChildren.item(i);

        if (controlChild.getNodeType() == Node.ELEMENT_NODE) {
            // Recursively compare Element nodes
            recursivelyCompareNodes(controlChild, testChild, ignoreAttributes, differences);
        } else if (!controlChild.getTextContent().equals(testChild.getTextContent())) {
            differences.add("'" + controlChild.getNodeName() + "' node text content is different");
        }
    }

    // Check for extra nodes in the control dom
    for (; i < controlChildCount; i++) {
        Node controlChild = controlChildren.item(i);

        if (controlChild.getNodeType() == Node.ELEMENT_NODE) {
            differences.add("'" + controlChild.getNodeName() + "' node is missing from test");
        }
    }

    // Check for extra nodes in the test dom
    for (; i < testChildCount; i++) {
        Node testChild = testChildren.item(i);

        if (testChild.getNodeType() == Node.ELEMENT_NODE) {
            differences.add("'" + testChild.getNodeName() + "' node is extra in test");
        }
    }
}
