import javax.annotation.processing.ProcessingException;
import java.lang.annotation.Annotation;
import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.List;

public static List<Field> scanForAnnotatedFields(Class<?> clazz, Class<? extends Annotation> annotation) throws ProcessingException {
    List<Field> fields = new ArrayList<>();

    while (clazz != null) {
        for (Field field : clazz.getDeclaredFields()) {
            if (field.isAnnotationPresent(annotation)) {
                fields.add(field);
            }
        }
        clazz = clazz.getSuperclass();
    }

    if (fields.isEmpty()) {
        throw new ProcessingException("No fields annotated with " + annotation.getSimpleName() + " found in class hierarchy");
    }

    return fields;
}
