import java.io.IOException;
import java.io.InputStream;
import java.util.Properties;

public class PropertyLoader {

    public static Properties loadProperties(String path) throws IOException {
        Properties props = new Properties();
        InputStream inputStream = null;
        try {
            inputStream = PropertyLoader.class.getResourceAsStream(path);
            if (inputStream != null) {
                props.load(inputStream);
            } else {
                inputStream = PropertyLoader.class.getClassLoader().getResourceAsStream(path);
                if (inputStream != null) {
                    props.load(inputStream);
                } else {
                    throw new IOException("Unable to load properties from path: " + path);
                }
            }
        } finally {
            if (inputStream != null) {
                inputStream.close();
            }
        }
        return props;
    }
}
