public void closeSession(String message, GSSContext context) {
    if(context != null) {
        try {
            context.dispose();
        } catch (GSSException e) {
            System.err.println("Error disposing GSSContext: " + e.getMessage());
        }
    }
    System.out.println("Closing session. Error message: " + message);
}
