public List<?> listInQualityOrder(Enumeration<?> e) {
    List<Object> list = new ArrayList<>();
    while (e.hasMoreElements()) {
        Object obj = e.nextElement();
        if (obj instanceof QualityValue) {
            QualityValue qv = (QualityValue) obj;
            int index = 0;
            for (Object o : list) {
                if (o instanceof QualityValue) {
                    QualityValue qv2 = (QualityValue) o;
                    if (qv.getQuality() > qv2.getQuality()) {
                        break;
                    }
                }
                index++;
            }
            list.add(index, obj);
        } else {
            list.add(obj);
        }
    }
    return list;
}
