public void visitNodes(Resource resource) {
    Queue<Resource> queue = new LinkedList<>();
    Set<Resource> visited = new HashSet<>();
    queue.offer(resource);
    visited.add(resource);

    while (!queue.isEmpty()) {
        Resource currentResource = queue.poll();
        // Process current resource
        for (Resource childResource : currentResource.getChildren()) {
            if (!visited.contains(childResource)) {
                queue.offer(childResource);
                visited.add(childResource);
            }
        }
    }
}
