        DigestCalculatorProvider digestCalculatorProvider = digestCalculatorProviderBuilder.build();

        OCSPReqBuilder ocspReqBuilder = new OCSPReqBuilder();
        OCSPExtension reqExtensions = new OCSPExtension(true, new ASN1ObjectIdentifier("1.2.3.4"), new DEROctetString(new byte[]{0x01, 0x02, 0x03, 0x04}));

        ocspReqBuilder.addExtension(OCSPObjectIdentifiers.id_pkix_ocsp_nonce, false, new DEROctetString(new byte[]{0x01, 0x02, 0x03, 0x04}));
        ocspReqBuilder.addExtension(new ASN1ObjectIdentifier("1.2.840.113583.1.1.8"), false, reqExtensions);

        CertificateID certID = new CertificateID(digestCalculatorProvider.get(CertificateID.HASH_SHA1), new JcaX509CertificateHolder(issuerCert), serialNumber);

        ocspReqBuilder.addRequest(certID);

        OCSPReq ocspReq = ocspReqBuilder.build();

        return ocspReq.getEncoded();
    } catch (Exception e) {
        throw new CertificateVerificationException("Error generating OCSP request.", e);
    }
}
