public static long toLong(Object value) throws UndefinedPropertyException, ParseException {
    if (value == null) {
        throw new UndefinedPropertyException("Value is null");
    }
    if (value instanceof Long) {
        return (long) value;
    }
    if (value instanceof String) {
        try {
            return Long.parseLong((String) value);
        } catch (NumberFormatException e) {
            throw new ParseException("Cannot convert to long: " + value, e);
        }
    }
    throw new ParseException("Cannot convert to long: " + value);
}
