public static int maxValueInRange(int[] arr, int start, int end) {
    if (start < 0 || end > arr.length || start >= end) {
        throw new IllegalArgumentException("Invalid range parameters");
    }

    int max = arr[start];
    for (int i = start + 1; i < end; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}
