public List<TrajectoryEnvelope> getGroundTrajectoryEnvelopes() {
    List<TrajectoryEnvelope> groundEnvelopeList = new ArrayList<>();    
    for (TrajectoryEnvelope envelope : trajectoryEnvelopes) {
        if (envelope.isGroundEnvelope()) {
            groundEnvelopeList.add(envelope);
        }
    }    
    Collections.sort(groundEnvelopeList, new Comparator<TrajectoryEnvelope>() {
        @Override
        public int compare(TrajectoryEnvelope envelope1, TrajectoryEnvelope envelope2) {
            return Long.compare(envelope1.getStartTime(), envelope2.getStartTime());
        }
    });    
    return groundEnvelopeList;
}
