public boolean isEqualVersion(String version) {
    String[] versionParts = version.split("\\.");
    String[] currentParts = CURRENT_VERSION.split("\\.");

    for (int i = 0; i < versionParts.length && i < currentParts.length; i++) {
        int versionPart = Integer.parseInt(versionParts[i]);
        int currentPart = Integer.parseInt(currentParts[i]);
        if (versionPart != currentPart) {
            return false;
        }
    }

    return true;
}
