public Optional<String> writeBackup(Encoder encoder, Token token) throws IOException {
    String backupFilename = token.getBackupFilename();
    if (backupFilename != null && !backupFilename.isEmpty()) {
        File backupFile = new File(backupFilename);
        if (!backupFile.exists()) {
            backupFile.createNewFile();
        }
        try (FileWriter writer = new FileWriter(backupFile)) {
            writer.write(encoder.encode(token));
            return Optional.of(backupFilename);
        }
    }
    return Optional.empty();
}
