public void loadExcessData(ByteBuffer writeBuffer, ByteBuffer readBuffer, int capacity) {
    int remainingCapacity = writeBuffer.remaining();
    if (remainingCapacity < capacity) {
        ByteBuffer excessData = readBuffer.slice();
        excessData.limit(capacity - remainingCapacity);
        writeBuffer.put(excessData);
    }
}
