public static String processPath(String path, String separator) {
    if (path == null || separator == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    String[] dirs = path.split(separator);
    for (String dir : dirs) {
        if (dir.equals(".") || dir.equals("")) { // ignore '.' and ''
            continue;
        }
        if (dir.equals("..")) { // handle '..', go back one level
            int index = sb.lastIndexOf(separator);
            if (index != -1) {
                sb.delete(index, sb.length());
            }
            continue;
        }
        sb.append(dir).append(separator); // add directory separator
    }
    // remove last directory separator
    if (sb.length() > 0 && sb.charAt(sb.length() - 1) == separator.charAt(0)) {
        sb.deleteCharAt(sb.length() - 1);
    }
    return sb.toString();
}
