public <ValueType> List<ValueType> getNodeValueForProperty(String propertyId, Class<ValueType> type) {
    List<ValueType> list = new ArrayList<>();
    Object property = getNodeProperty(propertyId);
    if (property instanceof List) {
        for (Object item : (List<?>) property) {
            if (type.isInstance(item)) {
                list.add(type.cast(item));
            }
        }
    } else if (type.isInstance(property)) {
        list.add(type.cast(property));
    }
    return list.isEmpty() ? null : list;
}
