protected void invokeOperation(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
    MBeanServer mbs = ManagementFactory.getPlatformMBeanServer();
    ObjectName name = (ObjectName) request.getSession().getAttribute("objectName");
    MBeanInfo info = null;
    try {
        info = mbs.getMBeanInfo(name);
    } catch (IntrospectionException | InstanceNotFoundException | ReflectionException e) {
        throw new ServletException("Failed invoking operation", e);
    }

    int operationIndex = Integer.parseInt(request.getParameter("opIndex"));
    MBeanOperationInfo operation = info.getOperations()[operationIndex];

    String[] signature = new String[operation.getSignature().length];
    for (int i = 0; i < signature.length; i++) {
        signature[i] = operation.getSignature()[i].getType();
    }

    Object[] args = new Object[signature.length];
    for (int i = 0; i < signature.length; i++) {
        args[i] = request.getParameter("arg" + i);
    }

    Object result;
    try {
        result = mbs.invoke(name, operation.getName(), args, signature);
        request.setAttribute("result", result);
    } catch (InstanceNotFoundException | ReflectionException | MBeanException e) {
        throw new ServletException("Failed invoking operation", e);
    }

    request.setAttribute("opName", operation.getName());
    request.setAttribute("opSig", signature);
    request.getRequestDispatcher("/operationResult.jsp").forward(request, response);
}
