public Class<? extends BsonValue> getClassForBsonType(BsonType bsonType) {
    switch (bsonType) {
        case ARRAY:
            return BsonArray.class;
        case BINARY:
            return BsonBinary.class;
        case BOOLEAN:
            return BsonBoolean.class;
        case DATE_TIME:
            return BsonDateTime.class;
        case DB_POINTER:
            return BsonDbPointer.class;
        case DECIMAL128:
            return BsonDecimal128.class;
        case DOCUMENT:
            return BsonDocument.class;
        case DOUBLE:
            return BsonDouble.class;
        case INT32:
            return BsonInt32.class;
        case INT64:
            return BsonInt64.class;
        case JAVASCRIPT:
            return BsonJavaScript.class;
        case JAVASCRIPT_WITH_SCOPE:
            return BsonJavaScriptWithScope.class;
        case MAX_KEY:
            return BsonMaxKey.class;
        case MIN_KEY:
            return BsonMinKey.class;
        case NULL:
            return BsonNull.class;
        case OBJECT_ID:
            return BsonObjectId.class;
        case REGULAR_EXPRESSION:
            return BsonRegularExpression.class;
        case STRING:
            return BsonString.class;
        case SYMBOL:
            return BsonSymbol.class;
        case TIMESTAMP:
            return BsonTimestamp.class;
        case UNDEFINED:
            return BsonUndefined.class;
        default:
            throw new IllegalArgumentException("Cannot get class for unsupported BsonType " + bsonType);
    }
}
