public List<TMTrafficPolicy> fetchFilteredTMTrafficPolicies(String filterJson) {
    // parse the filter JSON string into a map of key-value pairs
    Map<String, String> filterMap = new HashMap<>();
    try {
        filterMap = new ObjectMapper().readValue(filterJson, new TypeReference<Map<String, String>>(){});
    } catch (IOException e) {
        // handle exception
    }

    // construct the query based on the filter values
    QueryBuilder<TMTrafficPolicy> queryBuilder = QueryBuilder.queryFor(TMTrafficPolicy.class);
    for (Map.Entry<String, String> entry : filterMap.entrySet()) {
        queryBuilder = queryBuilder.where(entry.getKey()).eq(entry.getValue());
    }

    // execute the query and return the filtered list of TMTrafficPolicy resources
    return queryBuilder.build().execute();
}
