public static int[] inverseBWTMergedPointer(String bwt) {
    int n = bwt.length();
    int[] merged = new int[n];
    int[] next = new int[256];
    int[] rank = new int[n];

    for (char c : bwt.toCharArray()) {
        ++next[c];
    }

    for (int i = 1; i < 256; i++) {
        next[i] += next[i - 1];
    }

    for (int i = 0; i < n; i++) {
        char c = bwt.charAt(i);
        merged[next[c] - 1] = i;
        rank[i] = next[c];
        --next[c];
    }

    return merged;
}
