import org.junit.Test;
import org.junit.runners.model.Statement;

public class TestStatement extends Statement {

    private final Statement next;
    private final Test test;

    public TestStatement(Statement next, Test test) {
        this.next = next;
        this.test = test;
    }

    @Override
    public void evaluate() throws Throwable {
        Class<? extends Throwable> expectedException = test.expected();
        if (expectedException == Test.None.class) {
            next.evaluate();
            return;
        }

        try {
            next.evaluate();
            throw new AssertionError("Expected exception " + expectedException.getName() + " was not thrown.");
        } catch (Throwable ex) {
            if (!expectedException.isInstance(ex)) {
                throw new AssertionError("Unexpected exception type. Expected " + expectedException.getName() + " but was " + ex.getClass().getName() + ".", ex);
            }
        }       
    }
}
