public String substituteTemplateVars() {
  Map<String, String> varsMap = new HashMap<String, String>();
  Class<? extends TemplateVars> subclass = this.getClass();
  Field[] fields = subclass.getDeclaredFields();
  for (Field field : fields) {
    try {
      // Set accessible to allow private or protected access
      field.setAccessible(true);
      // Get the value of the field and add it to the map
      String value = field.get(this).toString();
      varsMap.put(field.getName(), value);
    } catch (IllegalAccessException e) {
      // Ignore
    }
  }
  String template = parsedTemplate();
  for (Map.Entry<String, String> entry : varsMap.entrySet()) {
    // Replace each variable with its value in the template
    template = template.replace("{{" + entry.getKey() + "}}", entry.getValue());
  }
  return template;
}
