public boolean isWhitespace(String token) {
    /* 
       A character is a whitespace if it is a space (" "), 
       a horizontal tab (\t), a new line (\n), a carriage return(\r), 
       a form feed(\f), or a vertical tab(\v).
    */
    return token.matches("\\s+");
}
