import java.util.Locale;
import java.util.Properties;

public Locale determineLanguage(Properties localizationProperties, Locale desiredLocale) {
    Locale localeToUse = desiredLocale;

    // check if there is a specific locale defined in the properties for the desired language
    String langCode = desiredLocale.getLanguage();
    String propValue = localizationProperties.getProperty(langCode);
    if (propValue != null) {
        localeToUse = new Locale(langCode, propValue);
    }

    // check if fallback languages are defined in the properties file
    String fallbackLangPropKey = "fallback.languages";
    propValue = localizationProperties.getProperty(fallbackLangPropKey);
    if (propValue != null) {
        String[] fallbackLangCodes = propValue.split(",");
        for (String fallbackLangCode : fallbackLangCodes) {
            fallbackLangCode = fallbackLangCode.trim();
            if (!fallbackLangCode.equals(langCode)) {
                propValue = localizationProperties.getProperty(fallbackLangCode);
                if (propValue != null) {
                    localeToUse = new Locale(fallbackLangCode, propValue);
                    break;
                }
            }
        }
    }

    return localeToUse;
}
