public Factor addBinaryFactor(int a, int b, double value) {
    Variable[] vars = new Variable[2];
    vars[0] = model.getVariable(a);
    vars[1] = model.getVariable(b);
    Factor factor = new Factor(vars);

    for (AssignmentIterator it = factor.assignmentIterator(); it.hasNext();) {
        Assignment as = it.assignment();
        double val = (as.get(a) == as.get(b)) ? value : 1;
        factor.set(as, val);
    }
    model.addFactor(factor);
    return factor;
}
