import java.io.ObjectStreamClass;
import java.util.HashMap;
import java.util.Map;

public class ObjectStreamClassHash {
    private static Map<Class<?>, Long> hashValues = new HashMap<>();

    public static synchronized long getSerialVersionUID(Class<?> clazz) {
        Long hash = hashValues.get(clazz);
        if (hash == null) {
            ObjectStreamClass osc = ObjectStreamClass.lookup(clazz);
            hash = osc.getSerialVersionUID();
            hashValues.put(clazz, hash);
        }
        return hash;
    }
}
