public List<String> getSupportedLocales() {    
    List<String> supportedLocales = new ArrayList<>();
    supportedLocales.add("en"); // Default english locale
    Locale[] locales = Locale.getAvailableLocales();
    for (Locale locale : locales) {
        if (locale.getLanguage().isEmpty() || locale.getDisplayLanguage().isEmpty()) {
            continue; // Invalid locale, skip to next iteration
        }
        String supportedLocale = locale.getLanguage().toLowerCase(); // Extract language code
        if (!supportedLocales.contains(supportedLocale)) {
            supportedLocales.add(supportedLocale);
        }
    }
    supportedLocales.add("native"); // Add the 'native' option
    return supportedLocales;
}
