public long executeInsertAndGetFirstGeneratedKey(PreparedStatement stmt) throws SQLException {
  stmt.executeUpdate();
  ResultSet rs = stmt.getGeneratedKeys();
  if (rs.next()) {
    long key = rs.getLong(1);
    rs.close();
    stmt.close();
    return key;
  } else {
    rs.close();
    stmt.close();
    return 0;
  }
}
