public Object convertPrimitiveNodeToObject(Node primitiveNode) {
    Object primitiveObject = null;
    switch (primitiveNode.getNodeType()) {
        case Node.ELEMENT_NODE:
            Element element = (Element) primitiveNode;
            String tagName = element.getTagName();
            if ("boolean".equals(tagName)) {
                primitiveObject = Boolean.parseBoolean(element.getTextContent());
            } else if ("int".equals(tagName)) {
                primitiveObject = Integer.parseInt(element.getTextContent());
            } else if ("long".equals(tagName)) {
                primitiveObject = Long.parseLong(element.getTextContent());
            } else if ("double".equals(tagName)) {
                primitiveObject = Double.parseDouble(element.getTextContent());
            } else if ("float".equals(tagName)) {
                primitiveObject = Float.parseFloat(element.getTextContent());
            }
            break;
        case Node.TEXT_NODE:
            primitiveObject = primitiveNode.getNodeValue();
            break;
    }
    return primitiveObject;
}
