public String readUntilFirstDelimiter(String chars) throws IOException {
    StringBuilder sb = new StringBuilder();
    int c;
    while ((c = System.in.read()) != -1) {
        char ch = (char) c;
        if (chars.indexOf(ch) >= 0) {
            break;
        }
        sb.append(ch);
    }
    return sb.toString();
}
