public ViewGroup waitForRecyclerView(int recyclerViewIndex) {
  RecyclerView recyclerView = null;
  ViewGroup recyclerViewParent = null;
  int counter = 0;

  // Wait until the RecyclerView is displayed 
  while (recyclerView == null && counter < 10) {
    recyclerView = (RecyclerView) solo.getView(R.id.recyclerView, recyclerViewIndex);
    counter++;
    solo.sleep(1000);
  }

  // If the RecyclerView is displayed, return the parent view group
  if (recyclerView != null) {
    recyclerViewParent = (ViewGroup) recyclerView.getParent();
  }

  return recyclerViewParent;
}
