public HashMap<String, String> deserialize(String[] tokens) {
    HashMap<String, String> map = new HashMap<String, String>();
    for (String token : tokens) {
        String[] pair = token.split(":");
        if (pair.length == 2) {
            String key = pair[0];
            String value = pair[1];
            map.put(key, value);
        }
    }
    return map;
}
