public BufferedImage getMirage(Color[] colorizations, ImageKey key) {
    BufferedImage sourceImage = getSourceImage(key);
    BufferedImage resultImage = new BufferedImage(sourceImage.getWidth(), sourceImage.getHeight(), BufferedImage.TYPE_INT_ARGB);
    Graphics2D g2d = resultImage.createGraphics();
    for (int i = 0; i < colorizations.length; i++) {
        g2d.setComposite(AlphaComposite.SrcAtop);
        g2d.setColor(colorizations[i]);
        g2d.fillRect(0, 0, sourceImage.getWidth(), sourceImage.getHeight());
    }
    g2d.dispose();
    BufferedImage mirroredImage = getMirage(ImageKey);
    g2d = mirroredImage.createGraphics();
    g2d.drawImage(resultImage, 0, 0, null);
    g2d.dispose();
    return mirroredImage;
}
