import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class EntityMetadataHelper {

    private static final Map<Class<?>, EntityMetadata> metadataCache = new ConcurrentHashMap<>();

    public static EntityMetadata getEntityMetadata(Class<?> source) {
        EntityMetadata metadata = metadataCache.get(source);
        if (metadata == null) {
            synchronized (metadataCache) {
                metadata = metadataCache.get(source);
                if (metadata == null) {
                    metadata = new EntityMetadata();
                    // populate the metadata object based on the source class
                    metadataCache.put(source, metadata);
                }
            }
        }
        return metadata;
    }
}

