public static Short decodeSignedShort(byte[] src, int srcOffset) {
    if (src == null) {
        return null;
    }

    byte firstByte = src[srcOffset];
    if (firstByte >= 0) {
        return (short) firstByte;
    }

    if (src.length - srcOffset < 3) {
        return null;
    }

    // Decode 3-byte signed integer.
    return (short) (((firstByte & 0x7F) << 8) | (src[srcOffset + 1] & 0xFF) | ((src[srcOffset + 2] & 0xFF) << 8));
}
