import java.io.FileInputStream;
import java.security.Key;
import java.security.KeyStore;
import java.security.PrivateKey;

public class AsymmetricEncryptionPrivateKey {
    public static PrivateKey getPrivateKey(String alias, String password) throws Exception {
        String keystorePath = "path/to/keystore";
        String keystorePassword = "keystore_password";

        FileInputStream fis = new FileInputStream(keystorePath);
        KeyStore keystore = KeyStore.getInstance(KeyStore.getDefaultType());
        keystore.load(fis, keystorePassword.toCharArray());

        Key key = keystore.getKey(alias, password.toCharArray());
        if (key instanceof PrivateKey) {
            return (PrivateKey) key;
        }
        throw new Exception("PrivateKey not found for alias: " + alias);
    }
}
