public static Set<String> altdissect(String regex) {
    Set<String> result = new HashSet<>();
    int index = 0;
    int nextAlt = regex.indexOf('|');
    while (nextAlt != -1) {
        result.add(regex.substring(index, nextAlt));
        index = nextAlt + 1;
        nextAlt = regex.indexOf('|', index);
    }
    result.add(regex.substring(index));
    return result;
}
