public class Builder<T> {
    private T instance;

    private Builder() {}

    public static <T> Builder<T> create(Class<T> clazz) {
        Builder<T> builder = new Builder<>();
        try {
            builder.instance = clazz.newInstance();
        } catch (InstantiationException | IllegalAccessException e) {
            e.printStackTrace();
        }
        return builder;
    }

    public <R> Builder<T> set(Function<T, R> setter, R value) {
        setter.apply(instance, value);
        return this;
    }

    public T build() {
        return instance;
    }
}
