       throw new IllegalArgumentException("Typed Array cannot be null");
   }
   int decimalCount = 0;
   for (int i = 0; i < typedArray.length(); i++) {
        float value = typedArray.getFloat(i, 0f);
        String valueStr = String.valueOf(value);
        int index = valueStr.indexOf(".");
        if (index != -1) {
            decimalCount = Math.max(decimalCount, valueStr.length() - index - 1);
        }
   }
   return decimalCount;
}
