public Observable<DomainInner> createDomain(String resourceGroupName, String domainName, DomainInfo domainInfo) throws IllegalArgumentException {
    // validate the parameters
    if (resourceGroupName == null || domainName == null || domainInfo == null) {
        throw new IllegalArgumentException("One or more parameters are invalid.");
    }

    // create a new domain asynchronously
    // implementation details depend on the technology being used
    // for example, using Azure SDK:
    Domain domain = azure.domains().define(domainName)
            .withExistingResourceGroup(resourceGroupName)
            .withInfo(domainInfo)
            .createAsync();

    // return an observable to the DomainInner object
    return domain.inner();
}
