import java.io.BufferedInputStream;
import java.io.BufferedOutputStream;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.util.zip.DeflaterOutputStream;

public static void compress(String resourcePath, String outputPath) throws IOException {
    try (BufferedInputStream bis = new BufferedInputStream(new FileInputStream(resourcePath));
         BufferedOutputStream bos = new BufferedOutputStream(new DeflaterOutputStream(new FileOutputStream(outputPath)))) {

        byte[] buffer = new byte[1024];
        int len;
        while ((len = bis.read(buffer)) > 0) {
            bos.write(buffer, 0, len);
        }
    }
}
