public ResponseEntity<String> getLocale(String localeId) {
    // Check if the requested locale is available in the application
    Locale locale = new Locale(localeId);

    if (Arrays.asList(Locale.getAvailableLocales()).contains(locale)) {
        // If the locale is available, return http status code 200 (OK) with the locale
        String message = "Locale " + localeId + " is available.";
        return new ResponseEntity<>(message, HttpStatus.OK);
    } else {
        // If the locale is not available, return http status code 404 (Not Found)
        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
    }
}
