public static double[][][] reverseTimeSeries(double[][][] in) {
    int minibatch = in.length;
    int size = in[0].length;
    int timeSeriesLength = in[0][0].length;
    double[][][] out = new double[minibatch][size][timeSeriesLength];
    for (int b = 0; b < minibatch; b++) {
        for (int i = 0; i < size; i++) {
            for (int t = 0; t < timeSeriesLength; t++) {
                out[b][i][t] = in[b][i][timeSeriesLength - 1 - t];
            }
        }
    }
    return out;
}
