public Instant getEarliestUninstantiatedStartMoment(List<Instant> startMoments) {
    if(startMoments == null || startMoments.isEmpty()){
        return null;
    }
    Instant earliestUninstantiatedStartMoment = null;
    for(Instant startMoment : startMoments){
        if(startMoment != null){
            continue;
        }
        if(earliestUninstantiatedStartMoment == null || startMoment.isBefore(earliestUninstantiatedStartMoment)){
            earliestUninstantiatedStartMoment = startMoment;
        }
    }
    return earliestUninstantiatedStartMoment;
}
