import java.io.IOException;
import java.security.InvalidKeyException;
import java.security.NoSuchAlgorithmException;

public class MinioExample {
    public static void main(String[] args) throws NoSuchAlgorithmException, IOException, InvalidKeyException, MinioException {
        String accessKey = "accesskey";
        String secretKey = "secretkey";
        String bucketName = "mybucket";
        String objectName = "myobject";
        String filePath = "/path/to/file";
        String encryptionAlgorithm = "AES256";
        String sseCustomerKey = "SSEC customer provided key";

        // Initialize the client with access key, secret key and endpoint.
        MinioClient client = new MinioClient("http://localhost:9000", accessKey, secretKey);

        // Put object with SSE_C
        client.putObject(bucketName, objectName, filePath, null, null, encryptionAlgorithm, sseCustomerKey);

        // Stat object to retrieve SSE_C information
        ObjectStat stat = client.statObject(bucketName, objectName, sseCustomerKey);
        System.out.println("Encryption algorithm: " + stat.encryptionAlgorithm());
        System.out.println("Encryption key MD5: " + stat.sseCustomerKeyMd5());
    }
}
