public byte[] berEncodeCookie(String cookie) {
    byte[] cookieBytes = cookie.getBytes(StandardCharsets.UTF_8);
    byte[] lengthBytes = encodeLength(cookieBytes.length);
    byte[] result = new byte[lengthBytes.length + cookieBytes.length];
    System.arraycopy(lengthBytes, 0, result, 0, lengthBytes.length);
    System.arraycopy(cookieBytes, 0, result, lengthBytes.length, cookieBytes.length);
    return result;
}

private byte[] encodeLength(int length) {
    if (length <= 127) {
        return new byte[]{(byte) length};
    } else {
        int temp = length;
        int numBytes = 0;
        while (temp > 0) {
            temp = temp >> 8;
            numBytes++;
        }

        byte[] result = new byte[numBytes + 1];
        result[0] = (byte) (0x80 | numBytes);
        for (int i = 1; i <= numBytes; i++) {
            int shift = (numBytes - i) * 8;
            result[i] = (byte) ((length >> shift) & 0xFF);
        }
        return result;
    }
}
