public Dimension findWHHeaders(InputStream fis, Holder lastTkhdHolder) throws IOException {
    Dimension dimensions = new Dimension(0, 0);
    byte[] buffer = new byte[1024];
    int bytesRead;

    while ((bytesRead = fis.read(buffer)) != -1) {
        int pos = 0;
        while (pos < bytesRead - 11) {
            if (buffer[pos++] == 0 && buffer[pos++] == 0 && buffer[pos++] == 0 && buffer[pos++] == 1 && buffer[pos] >= 0x10 && buffer[pos] <= 0x1f) {
                int boxLength = buffer[pos] & 0x000000ff;
                int header = read32(buffer, pos + 4);
                if (header == 0x746b6864) {
                    lastTkhdHolder.value = new byte[buffer.length];
                    System.arraycopy(buffer, pos + 8, lastTkhdHolder.value, 0, buffer.length - (pos + 8));
                }
                if (header == 0x76696465 || header == 0x61766331) {
                    if (buffer[pos + boxLength] == 0 && buffer[pos + boxLength + 1] == 0 && buffer[pos + boxLength + 2] == 0 && buffer[pos + boxLength + 3] == 1) {
                        int volWidth = read16(buffer, pos + 16);
                        int volHeight = read16(buffer, pos + 18);
                        if (volWidth > 0 && volHeight > 0) {
                            dimensions = new Dimension(volWidth, volHeight);
                        }
                    }
                }
                pos += boxLength;
            }
        }
    }
    return dimensions;
}

private int read32(byte[] buffer, int off) {
    return (buffer[off] & 0xff) << 24 |
           (buffer[off + 1] & 0xff) << 16 |
           (buffer[off + 2] & 0xff) << 8 |
           (buffer[off + 3] & 0xff);
}

private int read16(byte[] buffer, int off) {
    return (buffer[off] & 0xff) << 8 | (buffer[off + 1] & 0xff);
}

public class Holder {
    public byte[] value;
}
