public static String removeTrailingWhitespace(String s) {
    if (s == null) {
        return null;
    }
    int length = s.length();
    while (length > 0 && Character.isWhitespace(s.charAt(length - 1))) {
        length--;
    }
    return s.substring(0, length);
}
