public List<List<Point>> processCorners(List<Point> corners) {
    List<List<Point>> clusters = new ArrayList<>();
    List<Point> cluster = new ArrayList<>();
    boolean isNewCluster = true;

    // Sort the corner points based on their coordinates
    Collections.sort(corners, new Comparator<Point>() {
        @Override
        public int compare(Point o1, Point o2) {
            if (o1.y == o2.y) {
                return Integer.compare(o1.x, o2.x);
            }
            return Integer.compare(o1.y, o2.y);
        }
    });

    // Iterate over all the corners and group them into clusters of chessboard patterns
    for (int i = 0; i < corners.size(); i++) {
        Point currentPoint = corners.get(i);

        if (isNewCluster) {
            // Add the first point to a new cluster
            cluster.add(currentPoint);
            isNewCluster = false;
            continue;
        }

        Point previousPoint = corners.get(i - 1);
        double distance = Math.sqrt(Math.pow(currentPoint.x - previousPoint.x, 2) + Math.pow(currentPoint.y - previousPoint.y, 2));

        if (distance < 30) { // Adjust this threshold as needed
            // Add the current point to the current cluster
            cluster.add(currentPoint);
        } else {
            // Start a new cluster
            clusters.add(cluster);
            cluster = new ArrayList<>();
            cluster.add(currentPoint);
            isNewCluster = true;
        }
    }

    // Add the last cluster to the list
    clusters.add(cluster);

    return clusters;
}
