public static String getParamValue(String value, String paramName) {
    if (value == null || paramName == null) {
        return null;
    }

    int startIndex = value.indexOf(paramName + "=");
    if (startIndex == -1) {
        return null;
    }

    startIndex += paramName.length() + 1;

    int endIndex = value.indexOf("&", startIndex);
    if (endIndex == -1) {
        endIndex = value.length();
    }

    return value.substring(startIndex, endIndex);
}
