import java.net.InetAddress;
import java.util.ArrayList;
import java.util.List;

public List<Subnet> getRangeSubnets(InetAddress other) {
    List<Subnet> subnets = new ArrayList<>();

    // Convert the two addresses to integers for easier comparison
    long thisAddress = ipToLong(this);
    long otherAddress = ipToLong(other);

    // Find the beginning and end of the range
    long start = Math.min(thisAddress, otherAddress);
    long end = Math.max(thisAddress, otherAddress);

    // Iterate over the range with a subnet mask of increasing size
    for (int mask = 32; mask >= 0; mask--) {
        long subnetSize = (long) Math.pow(2, 32 - mask);

        // If the subnet size is greater than the remaining range, skip to the next size
        if (subnetSize > end - start + 1) {
            continue;
        }

        // Calculate the subnet address and add it to the list
        long subnetAddress = start / subnetSize * subnetSize;
        subnets.add(new Subnet(longToIp(subnetAddress), mask));

        // Move to the next subnet in the range
        start = subnetAddress + subnetSize;
    }

    return subnets;
}

private long ipToLong(InetAddress address) {
    byte[] bytes = address.getAddress();
    long result = 0;
    for (byte b : bytes) {
        result = result << 8 | (b & 0xFF);
    }
    return result;
}

private InetAddress longToIp(long address) {
    byte[] bytes = new byte[4];
    bytes[0] = (byte) ((address >> 24) & 0xFF);
    bytes[1] = (byte) ((address >> 16) & 0xFF);
    bytes[2] = (byte) ((address >> 8) & 0xFF);
    bytes[3] = (byte) (address & 0xFF);
    try {
        return InetAddress.getByAddress(bytes);
    } catch (UnknownHostException e) {
        throw new RuntimeException("Invalid IP address", e);
    }
}

public class Subnet {
    private InetAddress address;
    private int mask;

    public Subnet(InetAddress address, int mask) {
        this.address = address;
        this.mask = mask;
    }

    // Getters and setters...
}
