public void sendWarningMessage(Object source, String msg, boolean isHighPriority) {
    // get all registered handlers
    List<Handler> handlers = getHandlers();

    // send warning message to high priority handlers first (if applicable)
    if (isHighPriority) {
        for (Handler handler : handlers) {
            if (handler.isHighPriority()) {
                handler.handleWarning(source, msg);
            }
        }
    }

    // send warning message to non-high priority handlers (if applicable)
    for (Handler handler : handlers) {
        if (!isHighPriority || !handler.isHighPriority()) {
            handler.handleWarning(source, msg);
        }
    }
}
