public void reportToRollbar(String message, String level) {
  Config config = new ConfigBuilder("ROLLBAR_ACCESS_TOKEN")
    .build();
  Rollbar rollbar = Rollbar.init(config);
  switch (level) {
      case "debug":
          rollbar.debug(message);
          break;
      case "info":
          rollbar.info(message);
          break;
      case "warning":
          rollbar.warning(message);
          break;
      case "error":
          rollbar.error(message);
          break;
      case "critical":
          rollbar.critical(message);
          break;
      default:
          break;
  }
}
