public boolean removeLastOccurrence(Object o) {
    if (o == null) {
        for (Entry<E> e = tail; e != null; e = e.prev) {
            if (e.element == null) {
                unlink(e);
                return true;
            }
        }
    } else {
        for (Entry<E> e = tail; e != null; e = e.prev) {
            if (o.equals(e.element)) {
                unlink(e);
                return true;
            }
        }
    }
    return false;
}
