public String getCpp98ByteOrderEncodingString(ByteOrder byteOrder, PrimitiveType primitiveType) {
    if (byteOrder == ByteOrder.LITTLE_ENDIAN) {
        if (primitiveType == PrimitiveType.CHAR || primitiveType == PrimitiveType.INT8 || primitiveType == PrimitiveType.UINT8) {
            return "LittleEndian";
        } else if (primitiveType == PrimitiveType.INT16 || primitiveType == PrimitiveType.UINT16) {
            return "LittleEndianShort";
        } else if (primitiveType == PrimitiveType.FLOAT || primitiveType == PrimitiveType.INT32 || primitiveType == PrimitiveType.UINT32) {
            return "LittleEndian";
        } else if (primitiveType == PrimitiveType.DOUBLE || primitiveType == PrimitiveType.INT64 || primitiveType == PrimitiveType.UINT64) {
            return "LittleEndian";
        }
    } else if (byteOrder == ByteOrder.BIG_ENDIAN) {
        if (primitiveType == PrimitiveType.CHAR || primitiveType == PrimitiveType.INT8 || primitiveType == PrimitiveType.UINT8) {
            return "BigEndian";
        } else if (primitiveType == PrimitiveType.INT16 || primitiveType == PrimitiveType.UINT16) {
            return "BigEndianShort";
        } else if (primitiveType == PrimitiveType.FLOAT || primitiveType == PrimitiveType.INT32 || primitiveType == PrimitiveType.UINT32) {
            return "BigEndian";
        } else if (primitiveType == PrimitiveType.DOUBLE || primitiveType == PrimitiveType.INT64 || primitiveType == PrimitiveType.UINT64) {
            return "BigEndian";
        }
    }
    throw new IllegalArgumentException("Unsupported byte order or primitive type");
}
