public static String ipv6ByteArrayToString(byte[] src) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < src.length; i += 2) {
            sb.append(Integer.toHexString(((src[i] << 8) & 0xFF00) | (src[i + 1] & 0xFF)));
            if (i < src.length - 2) {
                sb.append(":");
            }
        }
        return sb.toString();
    }
