public static Molecule mergeUnusedRGroups(Molecule molecule) throws BuilderMoleculeException, ChemistryException {
    RGroupDetector detector = new RGroupDetector(molecule);
    List<Integer> unusedRGroups = detector.getUnusedRGroups();
    MoleculeBuilder builder = new MoleculeBuilder(molecule.toSmiles());
    for (int rGroup : unusedRGroups) {
        builder.addAtom("[" + rGroup + "]");
    }
    return builder.getMolecule();
}
