public Map<Token, Partition> findPredecessors(Partition partition) {
    Map<Token, Partition> result = new HashMap<>();
    if (partitions.size() <= 1 || !partitions.contains(partition)) {
        return result;
    }
    List<Partition> sortedPartitions = getSortedPartitions();
    int index = sortedPartitions.indexOf(partition);
    // The direct predecessor is the partition right before the given partition on the ring
    Partition directPredecessor = sortedPartitions.get((index - 1 + partitions.size()) % partitions.size());
    for (Token token : directPredecessor.tokens()) {
        result.put(token, directPredecessor);
    }
    // Find other predecessors that overlap with the direct predecessor
    for (int i = index - 2; i >= 0; i--) {
        Partition predecessor = sortedPartitions.get(i);
        for (Token token : predecessor.tokens()) {
            if (directPredecessor.contains(token)) {
                result.put(token, predecessor);
            }
        }
        if (!predecessor.hasOverlap(directPredecessor)) {
            break;
        }
    }
    return result;
}

private List<Partition> getSortedPartitions() {
    List<Partition> sortedPartitions = new ArrayList<>(partitions);
    sortedPartitions.sort(Comparator.<Partition>naturalOrder());
    return sortedPartitions;
}
