public void logBatchJobOperationsUpload(String uploadContents, String uploadUri, String batchJobUploadResponse, Throwable throwable) {
    if (throwable == null) {
        // log successful upload
        System.out.println("Upload successful.");
        System.out.println("Upload contents: " + uploadContents);
        System.out.println("Upload URI: " + uploadUri);
        System.out.println("Batch job upload response: " + batchJobUploadResponse);
    } else {
        // log failed upload with error message
        System.err.println("Upload failed with error message: " + throwable.getMessage());
        System.err.println("Upload contents: " + uploadContents);
        System.err.println("Upload URI: " + uploadUri);
        System.err.println("Batch job upload response (if available): " + batchJobUploadResponse);
    }
}
