public void notifyObservers(Uri notifyUri) {
    boolean isNotifyChange = ContentResolver.SCHEME_CONTENT.equals(notifyUri.getScheme())
            && notifyUri.getQueryParameter(Content.NOTIFY_PARAM).equals(String.valueOf(Content.NOTIFY_CHANGE));

    if (!isNotifyChange) {
        return;
    }

    boolean isSyncAdapter = ContentResolver.getIsSyncable(account, authority) > 0
                        && !ContentResolver.getSyncAutomatically(account, authority)
                        && !ContentResolver.getCurrentSyncs().isEmpty();

    if (!isSyncAdapter) {
        getContext().getContentResolver().notifyChange(notifyUri, null, true);
    }
}
