public String transferFileStream(File localFile, TransferListener listener) throws IOException {
    String checksum = null;
    try (InputStream remoteFileStream = getRemoteFileStream(); FileOutputStream localFileStream = new FileOutputStream(localFile)) {
        byte[] buffer = new byte[1024];
        int bytesRead;
        while ((bytesRead = remoteFileStream.read(buffer)) != -1) {
            localFileStream.write(buffer, 0, bytesRead);
            listener.bytesTransferred(bytesRead);
        }
        checksum = calculateChecksum(localFile);
        if (!checksum.equals(getRemoteFileChecksum())) {
            throw new IOException("Checksum does not match. File transfer was not successful.");
        }
    }
    return checksum;
}

