@Deprecated
public DBObject parseAndValidate(String str, Class<?> clazz, Mapper mapper, boolean validate) {
    DBObject entity = mapper.fromDBObject(clazz, new BasicDBObject());
    String[] parts = str.split(";"); //assuming fields are separated by semicolon

    for (String part : parts) {
        String[] nameValue = part.split("=");
        if (nameValue.length != 2) {
            throw new IllegalArgumentException("Invalid part: " + part);
        }
        String name = nameValue[0];
        String val = nameValue[1];
        Field field = null;
        try {
            field = clazz.getDeclaredField(name);
        } catch (NoSuchFieldException e) {
            throw new IllegalArgumentException("Invalid field name: " + name, e);
        }
        field.setAccessible(true);
        Object value = mapper.fromDBObjectValue(DBObject.class, val);
        try {
            field.set(entity, value);
        } catch (IllegalAccessException e) {
            throw new IllegalArgumentException("Error setting field: " + name, e);
        }
    }
    if (validate) {
        ValidationResult validationResult = Validation.buildDefaultValidatorFactory()
        .getValidator()
        .validate(entity);
        if (!validationResult.isValid()) {
            throw new ValidationException("Validation failed for entity: " + entity);
        }
    }
    return entity;
}
