public void populateNullFields(RequestOptions first, RequestOptions second) {
    Field[] fields = first.getClass().getDeclaredFields();

    for (Field field : fields) {
        field.setAccessible(true);
        Object value;
        try {
            value = field.get(first);
            if (value == null) {
                Object secondValue = field.get(second);
                if (secondValue != null) {
                    field.set(first, secondValue);
                }
            }
        } catch (IllegalAccessException e) {
            e.printStackTrace();
        }
    }
}
