public Location getSnappedLocation(Event event) {
    Location location = event.getLocation();
    if (maximumBounds != null) {
        double x = Math.min(location.getX(), maximumBounds.getMaxX());
        x = Math.max(x, maximumBounds.getMinX());
        double y = Math.min(location.getY(), maximumBounds.getMaxY());
        y = Math.max(y, maximumBounds.getMinY());
        double z = Math.min(location.getZ(), maximumBounds.getMaxZ());
        z = Math.max(z, maximumBounds.getMinZ());
        location = new Location(location.getWorld(), x, y, z);
    }
    return location;
}
