public static String extractWorkingDirConfig(String[] args) {
    String workingDirConfig = "";

    // Check if the arguments contain the 'dir' option
    int index = Arrays.asList(args).indexOf("-dir");
    if (index >= 0 && index < args.length - 1) {
        workingDirConfig = args[index] + " " + args[index + 1];
    }

    // Check if the arguments contain the 'workingDirectory' option
    index = Arrays.asList(args).indexOf("--workingDirectory");
    if (index >= 0 && index < args.length - 1) {
        workingDirConfig = args[index] + " " + args[index + 1];
    }

    return workingDirConfig;
}
