public String resolveEmbeddedKey(String value) {
    // Check if the value is null or empty
    if (value == null || value.isEmpty()) {
        return "";
    }

    // Regex pattern for finding the embedded key
    String pattern = "\\{\\{(.*?)\\}\\}";

    // Create a pattern object
    Pattern r = Pattern.compile(pattern);

    // Create a matcher object
    Matcher m = r.matcher(value);

    // Check if embedded key is present
    if (m.find()) {
        // Get the embedded key
        String key = m.group(1);

        // If the key is not null or empty
        if (key != null && !key.isEmpty()) {
            // Fetch the value for the key, you can use a map/properties file for this
            String resolvedValue = ""; //fetch resolved value for the key
            if (resolvedValue != null && !resolvedValue.isEmpty()) {
                // Replace the embedded key with the resolved value
                value = value.replace("{{" + key + "}}", resolvedValue);
            }
        }
    }

    // Return the fully resolved string
    return value;
}
