import java.util.Map;
import java.util.HashMap;

public class PluralizationRulesParser {

    public enum Category {
        ZERO, ONE, TWO, FEW, MANY, OTHER
    }

    public static Category parsePluralCategory(double n, Map<Integer, Integer> operands) {
        int integerN = (int) n;
        boolean hasFractionalPart = (n - integerN) != 0.0;

        int mod10 = integerN % 10;
        int mod100 = integerN % 100;

        if (operands.containsKey(0) && integerN == operands.get(0)) {
            return Category.ZERO;
        } else if (operands.containsKey(1) && integerN == operands.get(1)) {
            return Category.ONE;
        } else if (operands.containsKey(2) && integerN == operands.get(2)) {
            return Category.TWO;
        } else if (operands.containsKey(3) && operands.get(3).equals(mod10) && !operands.containsKey(4) && (mod100 < 12 || mod100 > 14)) {
            return Category.FEW;
        } else if (operands.containsKey(4) && (operands.get(4).equals(mod10) || operands.get(4).equals(mod100)) && !operands.containsKey(3)) {
            return Category.MANY;
        } else {
            return Category.OTHER;
        }
    }

    public static void main(String[] args) {
        Map<Integer, Integer> operands = new HashMap<>();
        operands.put(1, 0);
        operands.put(3, 2);
        operands.put(4, 3);

        int n1 = 0;
        int n2 = 1;
        int n3 = 2;
        int n4 = 3;
        int n5 = 4;
        int n6 = 5;

        System.out.println(parsePluralCategory(n1, operands));
        System.out.println(parsePluralCategory(n2, operands));
        System.out.println(parsePluralCategory(n3, operands));
        System.out.println(parsePluralCategory(n4, operands));
        System.out.println(parsePluralCategory(n5, operands));
        System.out.println(parsePluralCategory(n6, operands));
    }
}
