public int[] decode(int[] encoded, int[] target) {
    int n = encoded.length + 1;
    int totalSum = n * (n + 1) / 2;
    int encodedSum = 0;
    for (int i = 1; i < n - 1; i += 2) {
        encodedSum ^= encoded[i];
    }
    int missing = totalSum - encodedSum;
    target[0] = missing;
    for (int i = 0; i < n - 1; i++) {
        target[i + 1] = target[i] ^ encoded[i];
    }
    return target;
}
