public static <T> T retryWithSampling(Supplier<T> task, int maxAttempts, int samplingIntervalMillis) throws InterruptedException {
    int attempts = 0;
    Throwable lastException = null;
    while (attempts < maxAttempts) {
        try {
            return task.get();
        } catch (Throwable ex) {
            lastException = ex;
            attempts++;
            if (attempts >= maxAttempts) {
                break;
            }
            Thread.sleep(samplingIntervalMillis);
        }
    }
    System.err.println("Retried " + attempts + " times, last exception was:");
    lastException.printStackTrace();
    throw new RuntimeException(lastException);
}
