public static int bindInCriteria(PreparedStatement stmt, int index, Criteria crit, ClassDescriptor cld) throws SQLException {
    Object value = cld.getPropertyDescriptor(crit.getPropertyName()).getGetMethod().invoke(crit.getObject());

    if (value == null) {
        stmt.setNull(index, cld.getJdbcTypeForEnum(JdbcTypeHelper.getJdbcEnumType(cld.getPropertyType(crit.getPropertyName()))));
    } else {
        stmt.setObject(index, value);
    }

    return index + 1;
}
