public Map<String, Object> merge(Map<String, Object> obj1, Map<String, Object> obj2) {
    Map<String, Object> result = new HashMap<>();
    for (Map.Entry<String, Object> entry : obj1.entrySet()) {
        String key = entry.getKey();
        Object value1 = entry.getValue();
        Object value2 = obj2.get(key);
        if (value2 == null) {
            result.put(key, value1);
        } else if (value1 instanceof Map && value2 instanceof Map) {
            result.put(key, merge((Map<String, Object>)value1, (Map<String, Object>)value2));
        } else if (value1 instanceof List && value2 instanceof List) {
            List<Object> list1 = (List<Object>)value1;
            List<Object> list2 = (List<Object>)value2;
            List<Object> mergedList = new ArrayList<>();
            mergedList.addAll(list1);
            mergedList.addAll(list2);
            result.put(key, mergedList);
        } else if (value1 == null || value2 == null) {
            result.put(key, null);
        } else {
            List<Object> list = new ArrayList<>();
            list.add(value1);
            list.add(value2);
            result.put(key, list);
        }
    }
    for (Map.Entry<String, Object> entry : obj2.entrySet()) {
        String key = entry.getKey();
        if (!obj1.containsKey(key)) {
            result.put(key, entry.getValue());
        }
    }
    return result;
}
