public static boolean resolveAutoWireFlagFromAnnotation(Class<?> clazz, boolean defaultAutoWire) {
    boolean autoWireEnabled = defaultAutoWire;
    if(clazz.isAnnotationPresent(Component.class)) {
        Component component = clazz.getAnnotation(Component.class);
        autoWireEnabled = component.autowire();
    }
    return autoWireEnabled;
}
