import java.util.Collection;
import java.util.concurrent.CountDownLatch;

public class NodeBroadcast {

    public static CountDownLatch broadcastOperation(Collection<Node> nodes, Operation op) {
        CountDownLatch latch = new CountDownLatch(nodes.size());

        for (Node node : nodes) {
            new Thread(() -> {
                node.performOperation(op);
                latch.countDown();
            }).start();
        }

        return latch;
    }
}
