public static long parseTimePeriod(String period) throws NumberFormatException {
    if (period == null || period.equals("")) {
        return 0L;
    }
    String[] splitPeriod = period.split("(?<=\\D)(?=\\d)|(?<=\\d)(?=\\D)");
    long parsedPeriod = Long.parseLong(splitPeriod[0].trim());
    switch (splitPeriod[1].toLowerCase()) {
        case "msec":
            parsedPeriod *= 1;
            break;
        case "sec":
            parsedPeriod *= 1000;
            break;
        case "min":
            parsedPeriod *= 60000;
            break;
        case "h":
            parsedPeriod *= 3600000;
            break;
        default:
            throw new NumberFormatException("Invalid period format");
    }
    return parsedPeriod;
}
