public int getLastNodeIndex(XPathContext xctxt) {
    int lastIndex = -1;

    // Get the current context node.
    DTM dtm = xctxt.getDTM(xctxt.getContextNode());
    int context = xctxt.getCurrentNode();

    // Get the root node of the DTMs XPath tree.
    int docRoot = dtm.getDocument();

    if (context != DTM.NULL) {
        // Iterate over the nodes until we reach the root node.
        while (context != DTM.NULL && context != docRoot) {
            lastIndex = context;
            context = dtm.getParent(context);
        }
    }

    return lastIndex;
}
