import java.util.Map;

public class CollisionFreeMap {
    private Map<String, byte[]> data;

    public CollisionFreeMap(Map<String, byte[]> data) {
        this.data = data;
    }

    public byte[] get(String key) {
        return data.get(key);
    }

    public void put(String key, byte[] value) {
        data.put(key, value);
    }

    // Method for Fluo table data format conversion
    public static byte[] convertToFluoFormat(String key, byte[] value) {
        int keyLength = key.getBytes().length;
        int valueLength = value.length;

        byte[] bytes = new byte[8 + keyLength + valueLength];
        ByteBuffer.wrap(bytes).putInt(keyLength).putInt(valueLength).put(key.getBytes()).put(value);

        return bytes;
    }
}
