public double getBatchNormEpsilon(Map<String, Object> layerConfig) throws InvalidKerasConfigurationException {
    if (!layerConfig.containsKey("epsilon")) {
        throw new InvalidKerasConfigurationException("Epsilon parameter is missing.");
    }
    Object epsilonObj = layerConfig.get("epsilon");
    if (!(epsilonObj instanceof Number)) {
        throw new InvalidKerasConfigurationException("Epsilon parameter must be a number.");
    }
    double epsilon = ((Number) epsilonObj).doubleValue();
    if (!(epsilon > 0 && epsilon < 1)) {
        throw new InvalidKerasConfigurationException("Epsilon parameter must be a value between 0 and 1.");
    }
    return epsilon;
}
