public ProbeTest tryRetrieveProbeTestAnnotation(Description description) throws NoSuchMethodException {
    Method method = findMethod(description);
    if (method == null) {
        throw new NoSuchMethodException();
    }
    return method.getAnnotation(ProbeTest.class);
}

private Method findMethod(Description description) {
    Class<?> testClass = description.getTestClass();
    if (testClass == null) {
        return null;
    }
    String methodName = description.getMethodName();
    return Arrays.stream(testClass.getMethods())
            .filter(method -> methodName.equals(method.getName()))
            .findFirst()
            .orElse(null);
}
