private static final String DB_TABLE_NAME = "tableName";
private static final String DB_CREATE_TABLE = "CREATE TABLE IF NOT EXISTS " + DB_TABLE_NAME + " (id INTEGER PRIMARY KEY, name TEXT, age INTEGER, address TEXT)";

public SQLiteDatabase initializeDatabase(Context context, String name, int version, int cacheSize) {
    SQLiteDatabase db = null;
    try {
        DbOpenHelper dbHelper = new DbOpenHelper(context, name, null, version, cacheSize);
        db = dbHelper.getWritableDatabase();
        createTable(db); // Create table if not exists
    } catch (Exception e) {
        e.printStackTrace();
    }
    return db;
}

public void createTable(SQLiteDatabase db) {
    db.execSQL(DB_CREATE_TABLE);
}

public class DbOpenHelper extends SQLiteOpenHelper {

    private static final String dbName = "db";
    private static final int dbVersion = 1;
    private static final int dbCacheSize = 10 * 1024 * 1024; // 10MB

    public DbOpenHelper(Context context, String dbName, SQLiteDatabase.CursorFactory factory, int dbVersion, int dbCacheSize) {
        super(context, dbName, factory, dbVersion, new DatabaseErrorHandler() {
            @Override
            public void onCorruption(SQLiteDatabase sqLiteDatabase) {
                sqLiteDatabase.execSQL("DROP TABLE IF EXISTS " + DB_TABLE_NAME);
            }
        });
        setWriteAheadLoggingEnabled(true);
    }

    @Override
    public void onCreate(SQLiteDatabase db) {
        createTable(db);
    }

    @Override
    public void onUpgrade(SQLiteDatabase db, int oldVersion, int newVersion) {
        db.execSQL("DROP TABLE IF EXISTS " + DB_TABLE_NAME);
        onCreate(db);
    }
}
