public <T> T getMetaData(String key, Class<T> type, T defaultValue) {
    T value = defaultValue;
    if (metaData.containsKey(key)) {
        try {
            String rawData = metaData.get(key);
            if (type.equals(String.class)) {
                value = type.cast(rawData);
            } else if (type.equals(Integer.class)) {
                value = type.cast(Integer.parseInt(rawData));
            } else if (type.equals(Double.class)) {
                value = type.cast(Double.parseDouble(rawData));
            } else if (type.equals(Boolean.class)) {
                value = type.cast(Boolean.parseBoolean(rawData));
            } else {
                // throw some exception or log error message
            }
        } catch (NumberFormatException e) {
            // throw some exception or log error message
        }
    }
    return value;
}
