public List<Integer> createInitialOrdering(Formula formula, Map<Integer, Node> nodes) {
    List<Integer> ordering = new ArrayList<>();
    Set<Node> visited = new HashSet<>();

    for (Clause clause : formula.getClauses()) {
        for (Literal literal : clause.getLiterals()) {
            Node node = nodes.get(literal.getVariable());
            dfs(node, visited, ordering);
        }
    }

    return ordering;
}

private void dfs(Node node, Set<Node> visited, List<Integer> ordering) {
    if (visited.contains(node)) {
        return;
    }

    visited.add(node);

    for (Node child : node.getChildren()) {
        dfs(child, visited, ordering);
    }

    ordering.add(node.getVariable());
}
