import javax.management.AttributeList;
import javax.management.MBeanServerConnection;
import javax.management.ObjectInstance;
import javax.management.ObjectName;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;

public List<ObjectInstance> queryMBeanConnection(MBeanServerConnection mbeanServerConnection, ObjectName objectName) throws Exception {
    Set<ObjectInstance> objectInstances = mbeanServerConnection.queryMBeans(objectName, null);
    List<ObjectInstance> instanceList = new ArrayList<>();

    for (ObjectInstance instance : objectInstances) {
        AttributeList attributes = mbeanServerConnection.getAttributes(instance.getObjectName(), new String[]{"Name"});
        if (attributes.size() > 0 && attributes.asList().get(0).getValue().toString().contains("Metric") {
            instanceList.add(instance);
        }
    }

    return instanceList;
}
