import java.io.ByteArrayInputStream;
import java.io.DataInputStream;
import java.io.IOException;
import javax.sound.sampled.AudioFormat;
import javax.sound.sampled.AudioInputStream;

public class AiffDataCreator {
    public AiffData createAiffData(byte[] buffer) {
        try {
            AudioInputStream audioInputStream = new AudioInputStream(
                new ByteArrayInputStream(buffer), new AudioFormat(
                AudioFormat.Encoding.PCM_SIGNED, 44100, 16, 1, 2, 44100, false), 
                buffer.length / 4);

            DataInputStream dataInputStream = new DataInputStream(audioInputStream);
            AiffData aiffData = new AiffData();
            aiffData.setData(dataInputStream.readFully());
            dataInputStream.close();
            return aiffData;
        } catch (IOException e) {
            e.printStackTrace();
            return null;
        }
    }
}
