public static JTextField assignValidator(JTextField textBox, String pattern, String errorMessage) {
    textBox.setInputVerifier(new InputVerifier() {
        @Override
        public boolean verify(JComponent input) {
            String inputText = ((JTextField) input).getText();
            Pattern regexPattern = Pattern.compile(pattern);
            Matcher regexMatcher = regexPattern.matcher(inputText);
            if (!regexMatcher.matches()) {
                JOptionPane.showMessageDialog(input, errorMessage);
                return false;
            }
            return true;
        }
    });
    return textBox;
}
