public String parseInlineString(XMLEventReader xer) throws XMLStreamException, FormatNotUnderstoodException {
    boolean found = false;
    String value = null;
    while (!found && xer.hasNext()) {
        XMLEvent event = xer.nextEvent();
        if (event.isCharacters()) {
            value = event.asCharacters().getData();
            found = true;
        } else if (event.isEndElement() && event.asEndElement().getName().getLocalPart().equals("is")) {
            found = true;
        } else if (event.isStartElement()) {
            throw new FormatNotUnderstoodException("Unexpected element: " + event.asStartElement().getName().getLocalPart());
        }
    }
    if (value == null) {
        throw new FormatNotUnderstoodException("No inline string value found");
    }
    return value;
}
