private int printArray(PrintStream os, int index, int dims, int[] shape, int offset) {
    if (dims == 1) {
        os.print("[");
        for (int i = 0; i < shape[offset]; i++) {
            os.print(VEC[index+i]);
            if (i != shape[offset]-1) {
                os.print(", ");
            }
        }
        os.print("]");
        return shape[offset];
    } else {
        int size = 1;
        for (int i = offset; i < dims; i++) {
            size *= shape[i];
        }
        int written = 0;
        os.print("[");
        for (int i = 0; i < shape[offset]; i++) {
            int w = printArray(os, index + i * size, dims - 1, shape, offset + 1);
            written += w;
            if (i != shape[offset]-1) {
                os.print(", ");
            }
        }
        os.print("]");
        return written;
    }
}
