public static <L, M, R> Fst<L, R> composePreprocessed(Fst<L, M> fst1, MutableFst<M, R> fst2, boolean useSorted, boolean trimOutput) {
        if (fst1 == null || fst2 == null) {
            return null;
        }
        if (useSorted && !fst1.isSorted()) {
            fst1 = fst1.copy();
            fst1.sortByOutput();
        }
        Fst<L, M> composed = fst1.compose(fst2, Functions.<M>identity());
        if (trimOutput) {
            return composed.projectOut(OutputLabel.class);
        } else {
            return composed;
        }
}
