public static long calculateColor(Color left, Color right) {
    long red = ((left.getRed() + right.getRed()) / 2) << 16;
    long green = ((left.getGreen() + right.getGreen()) / 2) << 8;
    long blue = (left.getBlue() + right.getBlue()) / 2;

    return red | green | blue;
}
