public static StringBuilder formatNext16BytesAsASCII(byte[] buffer, byte[] data, int inOffset) {
    StringBuilder stringBuilder = new StringBuilder();

    for (int i = inOffset; i < inOffset + 16; i++) {
        if(i >= data.length) {
            break;
        }
        if(data[i] < 32 || data[i] > 126) { // Non-ASCII bytes
            stringBuilder.append('.');
        } else { // ASCII bytes
            stringBuilder.append((char) data[i]);
        }
    }
    return stringBuilder;
}
