public double calculateProfit(TimeSeries series, Trade trade) {
     double buyPrice = series.getTick(trade.getEntry()).getClosePrice();
     double sellPrice = series.getTick(trade.getExit()).getClosePrice();
     double amount = trade.getAmount();
     double profit = (sellPrice - buyPrice) * amount;
     return profit;
 }
