public OutbindRequest waitForOutbindRequest(int timeout) throws TimeoutException, IllegalStateException {
    if (this.currentState != SessionState.OPEN) {
        throw new IllegalStateException("Invocation of this method is invalid when the state is not OPEN");
    }

    long startTime = System.currentTimeMillis();
    synchronized (this) {
        while (outbindRequest == null) {
            long elapsedTime = System.currentTimeMillis() - startTime;
            long waitTime = timeout - elapsedTime;
            if (waitTime <= 0) {
                throw new TimeoutException("Timeout has been reached, connection will be closed automatically");
            }

            try {
                this.wait(waitTime);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }

        OutbindRequest request = outbindRequest;
        outbindRequest = null;
        return request;
    }
}
