public static float[] unpackIntArray(String part, String ibitst) {
    int[] sizes = Arrays.stream(part.split("/")).mapToInt(Integer::parseInt).toArray();
    int totalSize = Arrays.stream(sizes).sum();
    int[] bitSizes = new int[sizes.length];
    int bitsSoFar = 0;
    for (int i = 0; i < bitSizes.length; i++) {
        bitSizes[i] = sizes[i] * sizes.length;
        bitsSoFar += bitSizes[i];
    }

    int bitsLeft = totalSize - bitsSoFar;

    for (int i = 0; i < bitSizes.length; i++) {
        bitSizes[i] += bitsLeft / (sizes.length - 1);
        bitsLeft -= bitsLeft / (sizes.length - 1);
    }

    int[] pos = new int[sizes.length];
    int val = 0;
    for (int i = 0; i < ibitst.length(); i++) {
        if (ibitst.charAt(i) == '1') {
            val += (1 << bitSizes[pos.length - 1 - pos[pos.length - 1]]) * (ibitst.charAt(i) - '0');
        }

        if (pos[pos.length - 1] == sizes[pos.length - 1] - 1) {
            pos[pos.length - 1] = 0;
            for (int j = pos.length - 2; j >= 0; j--) {
                if (++pos[j] != sizes[j]) {
                    break;
                }

                pos[j] = 0;
            }
        } else {
            pos[pos.length - 1]++;
        }
    }

    float[] floats = new float[val];
    for (int i = 0; i < val; i++) {
        floats[i] = Float.intBitsToFloat(Arrays.stream(pos).map(x -> x * sizes.length).sum() + i);
    }

    return floats;
}
