public List<Stepdoc> getStepdocs(List<CandidateSteps> candidateSteps) {
    List<Stepdoc> stepdocs = new ArrayList<>();

    for (CandidateSteps steps : candidateSteps) {
        List<StepCandidate> stepCandidates = steps.listCandidates();
        for (StepCandidate candidate : stepCandidates) {
            Stepdoc stepdoc = candidate.getStepdoc();
            stepdocs.add(stepdoc);
        }
    }

    return stepdocs;
}
