public void deleteDirectory(File dir, PathChecker pathChecker) throws IOException {
    if (pathChecker.isPathValid(dir.toPath())) {
        if (dir.isDirectory()) {
            File[] files = dir.listFiles();
            if (files != null) {
                for (File file : files) {
                    deleteDirectory(file, pathChecker);
                }
            }
        }
        if (!dir.delete()) {
            throw new IOException("Failed to delete " + dir);
        }
    } else {
        throw new IOException("Invalid path " + dir);
    }
}
