public static int searchCharArray(char[] charArray, char value, int occurrence) {
    int index = -1;
    int count = 0;
    for(int i=0; i<charArray.length; i++) {
        if(charArray[i] == value) {
            count++;
            if(count == occurrence) {
                index = i;
                break;
            }
        }
    }
    return index;
}
