public String getSource(String sequence, String parentSource) {
    String source = ""; // initialize source variable

    // checking if sequence has source
    if (sequence.contains("source")) {
        // extract source string
        source = sequence.split("source=")[1].split(";")[0];
    } else if (!parentSource.isEmpty()) {
        // if sequence has no source then check for parent source
        source = parentSource;
    }

    return source;
}
