public boolean isBytesAvailableForVarInt() {
    int count = 0;
    int position = 0;
    byte b;
    do {
        b = getByte(position++);
        count++;
        if (count > 5) {
            throw new RuntimeException("VarInt is too big");
        }
    } while ((b & 0x80) != 0);
    return true;
}
