public <X, QP extends MessageQueryParameter<X>> List<X> getParameterValue(Class<QP> parameterClass) {
    List<X> result = new ArrayList<>();
    for (MessageQueryParameter<?> parameter : parameters) {
        if (parameterClass.isInstance(parameter)) {
            QP castedParameter = parameterClass.cast(parameter);
            result.add(castedParameter.getValue());
        }
    }
