public List<JdbcType> getJdbcTypesFromQueryOrResultSet(Query query, ResultSet resultSet) throws SQLException {
    List<JdbcType> jdbcTypes = new ArrayList<>();
    if (query != null) {
        jdbcTypes.addAll(query.getJdbcTypes());
    } else if (resultSet != null) {
        ResultSetMetaData metaData = resultSet.getMetaData();
        int columnCount = metaData.getColumnCount();
        for (int i = 1; i <= columnCount; i++) {
            jdbcTypes.add(JdbcType.valueOf(metaData.getColumnTypeName(i)));
        }
    } else {
        throw new SQLException("Query and ResultSet both are null");
    }
    return jdbcTypes;
}
