public static String readEncoding(File dictionaryFile) throws FileNotFoundException, UnsupportedCharsetException {
    InputStream inputStream = new FileInputStream(dictionaryFile);
    BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream, StandardCharsets.UTF_8));
    String encoding = "";
    try {
        encoding = reader.readLine();
        reader.close();
    } catch (IOException e) {
        e.printStackTrace();
    }
    if (!Charset.isSupported(encoding)) {
        throw new UnsupportedCharsetException("The encoding of the file is not supported.");
    }
    return encoding;
}
