import android.graphics.LinearGradient;
import android.graphics.RadialGradient;
import android.graphics.Shader;
import android.graphics.SweepGradient;

public Shader createShaderFromPaintReference(PaintReference paintReference) {
    Shader shader = null;

    switch (paintReference.getShaderType()) {
        case LINEAR:
            shader = new LinearGradient(paintReference.getStartX(), paintReference.getStartY(),
                    paintReference.getEndX(), paintReference.getEndY(),
                    paintReference.getColors(), paintReference.getOffsets(),
                    paintReference.getTileMode());
            break;
        case RADIAL:
            shader = new RadialGradient(paintReference.getCenterX(), paintReference.getCenterY(),
                    paintReference.getRadius(), paintReference.getColors(), paintReference.getOffsets(),
                    paintReference.getTileMode());
            break;
        case SWEEP:
            shader = new SweepGradient(paintReference.getCenterX(), paintReference.getCenterY(),
                    paintReference.getColors(), paintReference.getOffsets());
            break;
    }

    return shader;
}
