public List<Point> simplify(List<Point> points, double sqTolerance) {
    if (points.size() <= 2) {
        return points;
    }
    int index = -1;
    double maxSqDist = 0;
    for (int i = 1; i < points.size() - 1; i++) {
        double sqDist = getSqSegDist(points.get(i), points.get(0), points.get(points.size() - 1));
        if (sqDist > maxSqDist) {
            index = i;
            maxSqDist = sqDist;
        }
    }
    if (maxSqDist > sqTolerance) {
        List<Point> result = new ArrayList<>();
        List<Point> simplified1 = simplify(points.subList(0, index + 1), sqTolerance);
        List<Point> simplified2 = simplify(points.subList(index, points.size()), sqTolerance);
        result.addAll(simplified1);
        result.addAll(simplified2);
        return result;
    } else {
        return Collections.singletonList(points.get(0));
    }
}

private double getSqSegDist(Point point, Point p1, Point p2) {
    double x = p1.getX();
    double y = p1.getY();
    double dx = p2.getX() - x;
    double dy = p2.getY() - y;
    if (dx != 0 || dy != 0) {
        double t = ((point.getX() - x) * dx + (point.getY() - y) * dy) / (dx * dx + dy * dy);
        if (t > 1) {
            x = p2.getX();
            y = p2.getY();
        } else if (t > 0) {
            x += dx * t;
            y += dy * t;
        }
    }
    double dx = point.getX() - x;
    double dy = point.getY() - y;
    return dx * dx + dy * dy;
}
