public class HydrogenAtomTypesMapper {

    public Map<String, String> mapHydrogenAtomTypes(InputStream hdefIn) throws IOException {
        Map<String, String> parentToHydrogenDefinition = new HashMap<>();

        BufferedReader reader = new BufferedReader(new InputStreamReader(hdefIn));
        String line;
        while ((line = reader.readLine()) != null) {
            String[] tokens = line.split("\t");
            if (tokens.length == 2) {
                parentToHydrogenDefinition.put(tokens[0], tokens[1]);
            }
        }

        return parentToHydrogenDefinition;
    }
}
