public String format(ILoggingEvent event) {
    StringBuilder message = new StringBuilder();
    message.append("<log4j:event logger=\"").append(event.getLoggerName()).append("\"")
           .append(" timestamp=\"").append(event.getTimeStamp()).append("\"")
           .append(" level=\"").append(event.getLevel()).append("\">\n")
           .append("<log4j:message><![CDATA[").append(event.getFormattedMessage()).append("]]></log4j:message>\n")
           .append("<log4j:properties>\n");
    for (Map.Entry<String, String> entry : event.getMDCPropertyMap().entrySet()) {
        message.append("<log4j:data name=\"").append(entry.getKey()).append("\"")
               .append(" value=\"").append(entry.getValue()).append("\"/>\n");
    }
    message.append("</log4j:properties>\n")
           .append("</log4j:event>\n");
    return message.toString();
}
