public Map<RDFName, List<String>> getRDFMap(List<RDFName> names, List<List<String>> values) {

    // initialize an empty map
    Map<RDFName, List<String>> rdfMap = new HashMap<>();

    // iterate over the names and values lists and populate the map accordingly
    for (int i = 0; i < names.size(); i++) {
        RDFName name = names.get(i);
        List<String> valueList = values.get(i);
        rdfMap.put(name, valueList);
    }

    // return the map
    return rdfMap;
}
