import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.sql.SQLException;
import java.sql.Statement;

public class LoggingStatement {

    public static Statement createLoggingStatement(final Statement stmt) {
        InvocationHandler handler = new InvocationHandler() {
            @Override
            public Object invoke(Object proxy, Method method, Object[] args) throws Throwable {
                try {
                    System.out.println("Before Method Execution: " + method.getName());
                    Object result = method.invoke(stmt, args);
                    System.out.println("After Method Execution: " + method.getName());
                    return result;
                } catch (SQLException e) {
                    System.out.println("Exception during method execution: " + e.getMessage());
                    throw e;
                }
            }
        };
        return (Statement) Proxy.newProxyInstance(
                stmt.getClass().getClassLoader(),
                new Class[] { Statement.class },
                handler);
    }
}
