public Map<String, String> getOrCreateProtocolHeader(String message) {
    Map<String, String> headersMap = new HashMap<>();

    //Check if message headers already exist
    if (message.contains("Headers: ")) {
        int headerIndex = message.indexOf("Headers: ") + 9;
        String headerString = message.substring(headerIndex);
        String[] headers = headerString.split(", ");

        //Add existing headers to map
        for (String header : headers) {
            String[] headerKeyValue = header.split(": ");
            headersMap.put(headerKeyValue[0], headerKeyValue[1]);
        }
    } else {
        headersMap.put("Content-Type", "application/json");
        headersMap.put("Authorization", "Bearer <auth_token_goes_here>");
    }

    return headersMap;
}
