public class TokenRangeMerger {

    public Collection<DeepTokenRange> mergeTokenRanges(Map<Host, List<Token>> tokens, Session session, Partitioner p) {
        List<DeepTokenRange> tokenRanges = new ArrayList<>();
        for (Host host : tokens.keySet()) {
            List<Token> hostTokens = tokens.get(host);
            for (TokenRange tokenRange : p.splitEvenly(hostTokens, (int) (hostTokens.size() * 1.5))) {
                tokenRanges.add(new DeepTokenRange(tokenRange, host));
            }
        }
        Collections.shuffle(tokenRanges);
        return tokenRanges;
    }

}
