public double[] convertLambertIItoLambert93(double x, double y) {

    double n = 0.7289686274;
    double c = 11745793.39;
    double xs = 700000;
    double ys = 12655612.0499;
    double lambdaC = 2.3372291667;
    double phi1 = 46.5;
    double phi2 = 44.5;
    double phi0 = 46.8;
    double e = 0.08248325676;
    double lambda = (x - xs) / (c * n) + lambdaC;
    double r = Math.sqrt(Math.pow((x - xs), 2) + Math.pow((y - ys), 2));
    double gamma = Math.atan((x - xs) / (ys - y));
    double phi = phi0 - (1 / n) * (Math.log(Math.abs(r / c)) / e - (n / 2) * Math.pow(((Math.log(Math.abs(r / c))) / e), 2) + Math.pow(((Math.log(Math.abs(r /c))) / e), 3) * (n / 24) - Math.pow(((Math.log(Math.abs(r / c))) / e), 4) * (n / 720));

    return new double[] { phi, lambda };
}
