public String reduceUrl(String url) {
    // Remove the protocol and domain from the URL
    String path = url.replaceFirst("^https?://[^/]+", "");
    // Split the path by '/' and keep only non-empty chunks
    String[] chunks = Arrays.stream(path.split("/"))
                            .filter(chunk -> !chunk.isEmpty())
                            .toArray(String[]::new);
    // If there are less than two chunks, the URL cannot be reduced
    if (chunks.length < 2) {
        return url;
    }
    // Replace the last chunk with {id}
    chunks[chunks.length - 1] = "{id}";
    // Join the chunks using '/'
    return "/" + String.join("/", chunks);
}
