public Map<String, List<Double>> applyAggregations(Map<String, Function<List<Double>, Double>> functions, Map<String, List<Double>> columns) {
    Map<String, List<Double>> result = new HashMap<>();

    // Iterate over the columns
    for (Map.Entry<String, List<Double>> entry : columns.entrySet()) {
        String columnName = entry.getKey();
        List<Double> columnValues = entry.getValue();

        // Create a new list to store the aggregation result for this column
        List<Double> columnAggregations = new ArrayList<>();

        // Iterate over the functions
        for (Function<List<Double>, Double> function : functions.values()) {
            // Apply the aggregation function to the column values
            columnAggregations.add(function.apply(columnValues));
        }

        // Add the column aggregations to the result map
        result.put(columnName, columnAggregations);
    }

    return result;
}
