public static Integer previousElement(Collection<Integer> primaryKeyCollection) {
    if (primaryKeyCollection.isEmpty()) {
        return null;
    }
    Iterator<Integer> it = primaryKeyCollection.iterator();
    Integer current = it.next();
    Integer previous = null;
    while (it.hasNext()) {
        previous = current;
        current = it.next();
    }
    return previous;
}
