public static Point2D.Double transformSize(Point2D.Double SizeSrc, AffineTransform transform) {
    double x = SizeSrc.x;
    double y = SizeSrc.y;
    double x2 = x + SizeSrc.x;
    double y2 = y + SizeSrc.y;
    Point2D.Double p1 = new Point2D.Double(x, y);
    Point2D.Double p2 = new Point2D.Double(x2, y);
    Point2D.Double p3 = new Point2D.Double(x2, y2);
    Point2D.Double p4 = new Point2D.Double(x, y2);
    transform.transform(p1, p1);
    transform.transform(p2, p2);
    transform.transform(p3, p3);
    transform.transform(p4, p4);
    double edgeX = p1.distance(p2);
    double edgeY = p2.distance(p3);

    return new Point2D.Double(edgeX, edgeY);
}
