public void applyTransformersOnSources(List<Package> packages) {
    for (Package pack : packages) {
        List<Source> sources = pack.getSources();
        Map<Transformer, List<Source>> transformerGroups = new HashMap<>();
        for (Source source : sources) {
            Transformer transformer = source.getTransformer();
            if (!transformerGroups.containsKey(transformer)) {
                transformerGroups.put(transformer, new ArrayList<>());
            }
            transformerGroups.get(transformer).add(source);
        }
        for (Map.Entry<Transformer, List<Source>> transformerGroup : transformerGroups.entrySet()) {
            List<Source> sourceGroup = transformerGroup.getValue();
            Transformer transformer = transformerGroup.getKey();
            transformer.apply(sourceGroup);
        }
    }
}
