public List<Cell> getCellsByFamilyAndQualifier(String family, String qualifier, List<Cell> cellList) {
    List<Cell> filteredCells = new ArrayList<>();
    for (Cell cell : cellList) {
        if (Bytes.equals(CellUtil.cloneFamily(cell), Bytes.toBytes(family)) 
            && Bytes.equals(CellUtil.cloneQualifier(cell), Bytes.toBytes(qualifier))) {
            filteredCells.add(cell);
        }
    }
    Collections.sort(filteredCells, new RowCellComparator());
    return filteredCells;
}
