public static Class<?> getTypeClass(Type type, ClassLoader classLoader) throws ClassNotFoundException {
    switch (type.getSort()) {
        case Type.ARRAY:
            Class<?> elementType = getTypeClass(type.getElementType(), classLoader);
            return Class.forName("[L" + elementType.getName() + ";", false, classLoader);
        case Type.BOOLEAN:
            return boolean.class;
        case Type.BYTE:
            return byte.class;
        case Type.CHAR:
            return char.class;
        case Type.DOUBLE:
            return double.class;
        case Type.FLOAT:
            return float.class;
        case Type.INT:
            return int.class;
        case Type.LONG:
            return long.class;
        case Type.SHORT:
            return short.class;
        case Type.VOID:
            return void.class;
        case Type.OBJECT:
        default:
            return Class.forName(type.getClassName(), false, classLoader);
    }
}
