public int[] readIntArrayBulk(InputStream inputStream) throws IOException {
    List<Integer> intList = new ArrayList<>();
    int b;

    while ((b = inputStream.read()) != -1) {
        int val = b;

        while ((b = inputStream.read()) >= 0x80) {
            val = (val << 7) | (b & 0x7F);
        }

        val = (val << 7) | b;
        intList.add(val);
    }

    int[] intArr = new int[intList.size()];

    for (int i = 0; i < intList.size(); i++) {
        intArr[i] = intList.get(i);
    }

    return intArr;
}
