public class StagingProcess {
    public void initiateReleaseStagingProcess(String apiUrl, String apiKey, String stagingRepositoryKey, String version) throws IOException {
        String url = apiUrl + "/api/build/promote/" + stagingRepositoryKey;
        String requestBody = "{\"sourceRepo\":\"" + stagingRepositoryKey +
                "\",\"targetRepo\":\"" + stagingRepositoryKey +
                "\",\"comment\":\"Release version " + version + "\"," +
                "\"stagedBuildNumber\":" + version + ",\"copy\":\"false\"," +
                "\"failFast\":\"true\",\"dependencies\":\"true\"," +
                "\"properties\":{},\"dryRun\":\"false\"}";
        HttpPost request = new HttpPost(url);
        request.addHeader("X-JFrog-Art-Api", apiKey);
        request.setEntity(new StringEntity(requestBody, ContentType.APPLICATION_JSON));
        try (CloseableHttpClient httpClient = HttpClients.createDefault()) {
            httpClient.execute(request);
        }
    }
}
