public static <K, V1, V2> Multimap<K, V2> transformKeys(Multimap<K, V1> input, Function<? super K, ? extends V2> function) {
    Multimap<K, V2> output = ArrayListMultimap.create();
    for (Entry<K, V1> entry : input.entries()) {
