public List<String> listAdditionalBundledPlugins() {
  List<String> bundledPlugins = new ArrayList<>();
  String bundledPluginsProperty = System.getProperty("hudson.bundled.plugins");
  if (bundledPluginsProperty != null) {
    String[] plugins = bundledPluginsProperty.split(",");
    for (String plugin : plugins) {
      if (plugin.contains("*")) {
        File pluginDir = new File(plugin.substring(0, plugin.lastIndexOf("/")));
        String[] matchingPlugins = pluginDir.list((dir, name) -> name.matches(plugin.substring(plugin.lastIndexOf("/") + 1)));
        if (matchingPlugins != null) {
          Collections.addAll(bundledPlugins, matchingPlugins);
        }
      } else {
        bundledPlugins.add(plugin);
      }
    }
  }
  return bundledPlugins;
}
