public void removeAppMsgAfterDuration(AppMsg appMsg) {
    Handler handler = new Handler();
    handler.postDelayed(new Runnable() {
        @Override
        public void run() {
            ViewGroup parentView = (ViewGroup) appMsg.getView().getParent();
            if (parentView != null) {
                parentView.removeView(appMsg.getView());
            }
        }
    }, appMsg.getDuration()); // appMsg.getDuration() returns the duration for which the message should be displayed in milliseconds
}
