public Map<String, List<BacklogInfo>> getBacklogSnapshotGroupedByStream(List<BacklogInfo> backlogInfos) {
    Map<String, List<BacklogInfo>> backlogSnapshot = new HashMap<>();
    for (BacklogInfo backlogInfo : backlogInfos) {
        String stream = backlogInfo.getStream();
        if (!backlogSnapshot.containsKey(stream)) {
            backlogSnapshot.put(stream, new ArrayList<>());
        }
        backlogSnapshot.get(stream).add(backlogInfo);
    }
    return backlogSnapshot;
}
