public enum EValidity {
    VALID, INVALID
}

public static EValidity validateEan8(String sMsg) {
    if (sMsg == null || sMsg.length() != 8 || !sMsg.matches("[0-9]+")) {
        throw new IllegalArgumentException("Invalid EAN-8 message format");
    }
    int sum = 0;
    for (int i = 0; i < 8; i++) {
        int num = sMsg.charAt(i) - '0';
        if (i % 2 == 0) {
            sum += num * 3;
        } else {
            sum += num;
        }
    }
    int checkDigit = (10 - (sum % 10)) % 10;
    if (checkDigit != sMsg.charAt(7) - '0') {
        return EValidity.INVALID;
    }
    return EValidity.VALID;
}
