public Map<Integer, Integer> getRowPositionModifications(Adapter adapter, List<?> data) {
    if (!adapter.isMutable()) {
        Map<Integer, Integer> rowPositionModifications = new HashMap<>();
        for (int i = 0; i < data.size(); i++) {
            Object item = data.get(i);
            int oldPosition = adapter.getPosition(item);
            int newPosition = i;
            if (oldPosition != -1 && oldPosition != newPosition) {
                rowPositionModifications.put(oldPosition, newPosition);
            }
        }
        return rowPositionModifications;
    } else {
        throw new IllegalStateException("Adapter is not immutable");
    }
}
