public boolean isFrustumBoxIntersecting(Frustum frustum, Box box) {
    Vector3f max = box.getMax();
    Vector3f min = box.getMin();
    Vector3f vertices[] = new Vector3f[8];
    vertices[0] = new Vector3f(max.x, max.y, max.z);
    vertices[1] = new Vector3f(max.x, max.y, min.z);
    vertices[2] = new Vector3f(max.x, min.y, max.z);
    vertices[3] = new Vector3f(max.x, min.y, min.z);
    vertices[4] = new Vector3f(min.x, max.y, max.z);
    vertices[5] = new Vector3f(min.x, max.y, min.z);
    vertices[6] = new Vector3f(min.x, min.y, max.z);
    vertices[7] = new Vector3f(min.x, min.y, min.z);
    for(int i=0;i<frustum.planes.length;i++) {
        int inCount=8;
        int ptIn=1;
        for(int j=0;j<8;j++) {
            if(frustum.planes[i].distance(vertices[j])<0) {
                inCount--;
                ptIn=0;
            }
        }
        if(inCount==0) {
            return false;
        }
    }
    return true;
}
