public static boolean matches(char[] buffer, int location, String content) {
    char[] contentArray = content.toCharArray();
    if (buffer.length - location < contentArray.length) {
        return false;
    }
    for (int i = 0; i < contentArray.length; i++) {
        if (buffer[location + i] != contentArray[i]) {
            return false;
        }
    }
    return true;
}
