import java.util.ArrayList;
import java.util.List;

public class OptionParser {
   private OptionSource optionSource;
   private List<String> positionalArgs;

   public OptionParser(OptionSource optionSource) {
      this.optionSource = optionSource;
      this.positionalArgs = new ArrayList<>();
   }

   public List<String> parse(String[] args) {
      int i = 0;
      while (i < args.length) {
         String arg = args[i];
         if (arg.equals("--")) {
            // stop processing options after this
            i++;
            break;
         }
         if (!arg.startsWith("-")) {
            // not an option, add to positional arguments
            positionalArgs.add(arg);
            i++;
            continue;
         }
         String optName = getOptionName(arg);
         String optVal = getOptionValue(args, i);
         Option opt = optionSource.getOption(optName);
         opt.setValue(optVal);
         i += opt.getNumArgs() + 1;
      }
      while (i < args.length) {
         positionalArgs.add(args[i]);
         i++;
      }
      return positionalArgs;
   }

   private String getOptionName(String arg) {
      if (arg.startsWith("--")) {
         return arg.substring(2);
      } else {
         return arg.substring(1);
      }
   }

   private String getOptionValue(String[] args, int i) {
      if (i + 1 < args.length && !args[i + 1].startsWith("-")) {
         return args[i + 1];
      } else {
         return null;
      }
   }
}
