public static double[][] blockDiagonalEigenvalueMatrix(double[][] matrix) {
    RealMatrix rm = new Array2DRowRealMatrix(matrix);
    BlockRealMatrix brm = new BlockRealMatrix(rm.getData());
    EigenDecomposition ed = new EigenDecomposition(brm);

    double[] eigenvalues = ed.getRealEigenvalues();
    int n = eigenvalues.length;
    double[][] diagonal = new double[n][n];

    for (int i = 0; i < n; i++) {
        diagonal[i][i] = eigenvalues[i];
    }

    return diagonal;
}
