import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.Base64;
import java.util.zip.GZIPInputStream;

public static byte[] decodeBase64(String s) throws IOException {
    byte[] decodedBytes = Base64.getDecoder().decode(s.getBytes(StandardCharsets.UTF_8));

    try (InputStream is = new GZIPInputStream(new ByteArrayInputStream(decodedBytes))) {
        byte[] buffer = new byte[1024];
        int length;
        while ((length = is.read(buffer)) > 0) {
            // do nothing, read to end of stream
        }
        return buffer;
    }
}
