public double[] findMinMaxWithErrorBars(double[] data, double[] errorBars) {
    if (data == null || errorBars == null || data.length != errorBars.length) {
        throw new IllegalArgumentException("Invalid input");
    }

    double min = Double.MAX_VALUE;
    double max = Double.MIN_VALUE;

    for (int i = 0; i < data.length; i++) {
        double lowerBound = data[i] - errorBars[i];
        double upperBound = data[i] + errorBars[i];

        if (lowerBound < min) {
            min = lowerBound;
        }

        if (upperBound > max) {
            max = upperBound;
        }
    }

    return new double[]{min, max};
}
