public List<String> getAllViews(Optional<String> filterSchema) {
    List<String> views = new ArrayList<>();
    try (Connection conn = DriverManager.getConnection("jdbc:postgresql://localhost:5432/mydb", "username", "password")) {
        String query;
        if (filterSchema.isPresent()) {
            query = "SELECT viewname FROM pg_catalog.pg_views WHERE schemaname = ?";
            try (PreparedStatement stmt = conn.prepareStatement(query)) {
                stmt.setString(1, filterSchema.get());
                try (ResultSet rs = stmt.executeQuery()) {
                    while (rs.next()) {
                        views.add(rs.getString("viewname"));
                    }
                }
            }
        } else {
            query = "SELECT viewname FROM pg_catalog.pg_views";
            try (PreparedStatement stmt = conn.prepareStatement(query); ResultSet rs = stmt.executeQuery()) {
                while (rs.next()) {
                    views.add(rs.getString("viewname"));
                }
            }
        }
    } catch (SQLException e) {
        e.printStackTrace();
    }
    return views;
}
