public double[][] computeDoubleCenteredDeltaMatrix(DataAdapter adapter, double[][] data) {
    int numRows = data.length;
    int numCols = data[0].length;
    double[][] doubleCenteredDeltaMatrix = new double[numRows][numCols];

    for (int i = 0; i < numCols; i++) {
        double mean = adapter.getMean(data, i);
        for (int j = 0; j < numRows; j++) {
            doubleCenteredDeltaMatrix[j][i] = data[j][i] - mean;
        }
    }

    for (int i = 0; i < numRows; i++) {
        double mean = adapter.getMean(doubleCenteredDeltaMatrix[i]);
        for (int j = 0; j < numCols; j++) {
            doubleCenteredDeltaMatrix[i][j] -= mean;
        }
    }

    return doubleCenteredDeltaMatrix;
}
