import ucar.ma2.Array;
import ucar.ma2.ArrayFloat;
import ucar.ma2.InvalidRangeException;
import ucar.nc2.Dimension;
import ucar.nc2.NetcdfFileWriter;
import ucar.nc2.Variable;

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

public class NetCDFWriter {

  public void writeNetCDF(String location, GridDataset gds, List<String> gridList, HorizSubset llbb, Range range) 
    throws IOException, InvalidRangeException {

    try (NetcdfFileWriter writer = NetcdfFileWriter.createNew(NetcdfFileWriter.Version.netcdf3, location)) {
      List<Dimension> dimensions = new ArrayList<>();
      List<Variable> variables = new ArrayList<>();

      // Add dimensions and variables
      for (String gridName : gridList) {
        GridDatatype g = gds.findGridByShortName(gridName);
        if (g != null) {
          for (Dimension d : g.getDimensions()) {
            if (!dimensions.contains(d)) {
              dimensions.add(d);
            }
          }
          variables.add(g.getVariable());
        }
      }

      // Define dimensions and variables in the file
      for (Dimension d : dimensions) {
        writer.addDimension(null, d.getShortName(), d.getLength());
      }

      for (Variable v : variables) {
        List<Dimension> varDims = new ArrayList<>();
        for (Dimension d : v.getDimensions()) {
          varDims.add(d);
        }

        Variable newVar = writer.addVariable(null, v.getShortName(), v.getDataType(), varDims);
        newVar.addAttribute(new Attribute("units", v.getUnitsString()));
        newVar.addAttribute(new Attribute("_CoordinateAxisType", v.findAttributeString("_CoordinateAxisType", "")));
        newVar.addAttribute(new Attribute("_CoordinateZisPositive", v.findAttributeString("_CoordinateZisPositive", "")));

        // Can add more attributes here
      }

      // Add necessary global metadata
      writer.addGroupAttribute(null, new Attribute("Conventions", "CF-1.6"));
      writer.addGroupAttribute(null, new Attribute("title", "Title of the file"));

      // Create the file
      writer.create();

      // Write data to the file
      for (Variable v : variables) {
        Array data = gds.findGridData(v.getShortName(), range, llbb).read();
        ArrayFloat af = (ArrayFloat) data.reduce();

        int[] origin = new int[v.getRank()];
        int[] shape = new int[v.getRank()];

        for (int i = 0; i < v.getRank(); i++) {
          shape[i] = v.getShape(i);
        }

        writer.write(v, origin, af.reshape(shape));
      }
    }
  }
}
