import javax.enterprise.context.ApplicationScoped;
import javax.enterprise.inject.spi.BeanManager;
import javax.inject.Inject;

@ApplicationScoped
public class CDIInjector {

    @Inject 
    private BeanManager beanManager;

    public <T> ManagedObject<T> getManagedObject(Class<T> klass, boolean doPostConstruct) throws InjectionProviderException {
        ManagedObject<T> managedObject = new ManagedObject<>();

        try {
            T instance = beanManager.createInstance().select(klass).get();

            if (doPostConstruct) {
                beanManager.fireEvent(instance, new PostConstructLiteral());
            }

            managedObject.setInstance(instance);
        } catch (Exception e) {
            throw new InjectionProviderException("Unable to create Managed Object", e);
        }

        return managedObject;
    }

}
