public boolean isAttributeIgnored(Element receivedElement, Attribute receivedAttribute, List<Element> ignoreMessageElements) {
    if (ignoreMessageElements != null && ignoreMessageElements.contains(receivedElement)) {
        return true; // element is ignored, so attribute is ignored as well
    } else {
        String attributeName = receivedAttribute.getName();
        return attributeName.startsWith("xml") || attributeName.startsWith("xmlns") || attributeName.equals("id"); // checking if attribute should be ignored
    }
}
