public static int calculateChecksum(File chunkFile) throws IOException {
    int checksum = 0;
    try (BufferedInputStream inputStream = new BufferedInputStream(new FileInputStream(chunkFile))) {
        int byteRead;
        while ((byteRead = inputStream.read()) != -1) {
            checksum += byteRead;
        }
    }
    return checksum;
}
