import java.time.LocalDate;
import java.time.temporal.ChronoUnit;

public static LocalDate truncateDate(ChronoUnit unit, LocalDate expr) {
    switch (unit) {
        case DAYS:
            return expr.truncatedTo(ChronoUnit.DAYS);
        case WEEKS:
            return expr.truncatedTo(ChronoUnit.WEEKS);
        case MONTHS:
            return expr.truncatedTo(ChronoUnit.MONTHS);
        case YEARS:
            return expr.truncatedTo(ChronoUnit.YEARS);
        default:
            throw new IllegalArgumentException("Invalid unit specified");
    }
}
