public static Class<?> findQualifiedMemberType(Environment env, Class<?> site, String name, Class<?> c) {
    ClassLoader loader = site.getClassLoader();
    try {
        Class<?> theClass = c.isInterface() ?
            Class.forName(name, false, loader) :
            env.lookupClass(name);
        if (!c.isAssignableFrom(theClass))
            throw new NoSuchTypeException(name + " is not a subtype of " + c);
        if (!Modifier.isPublic(theClass.getModifiers()))
            throw new NoSuchTypeException(name + " is not public");
        return theClass;
    } catch (ClassNotFoundException e) {
        throw new NoSuchTypeException(e.getMessage());
    }
}
