public Set<String> getKeysByPath(Map<String, Object> map, String... path) {
    Object value = map;
    for (String key : path) {
        if (value instanceof Map) {
            value = ((Map<String, Object>) value).get(key);
        } else {
            value = null;
            break;
        }
    }
    if (value instanceof Map) {
        return ((Map<String, Object>) value).keySet();
    }
    return new HashSet<>();
}
