import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.logging.Level;
import java.util.logging.Logger;

public class HashGenerator {

    private static final Logger LOGGER = Logger.getLogger(HashGenerator.class.getName());

    public static String generateHash(String input, String algorithm) {

        try {
            MessageDigest md = MessageDigest.getInstance(algorithm);
            byte[] messageDigest = md.digest(input.getBytes());
            StringBuilder sb = new StringBuilder();
            for (byte b : messageDigest) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException ex) {
            LOGGER.log(Level.SEVERE, "Error generating hash code: " + ex.getMessage(), ex);
            return null;
        }
    }
}
