public boolean mergeMetaData(ResourceMetadata other) {
   // Merges the metrics and attributes from the given instance, to the current instance
   boolean wasModified = false;
   for(String metric : other.getMetrics()) {
      if(this.metrics.add(metric)) {
         wasModified = true;
      }
   }
   for(String attribute : other.getAttributes()) {
      String value = other.getAttributeValue(attribute);
      if(this.setAttribute(attribute, value)) {
         wasModified = true;
      }
   }
   return wasModified;
}
