import java.io.FileInputStream;
import java.io.IOException;
import java.security.GeneralSecurityException;
import java.security.Key;
import java.security.KeyStore;
import java.security.cert.Certificate;
import java.security.interfaces.RSAPrivateKey;
import java.security.spec.PKCS8EncodedKeySpec;
import java.security.spec.X509EncodedKeySpec;
import java.util.Base64;

public static KeyStore createKeyStore(String certPath) throws IOException, GeneralSecurityException {

    KeyStore keystore = KeyStore.getInstance("JKS");
    keystore.load(null, null);

    // load CA cert
    Certificate caCert = CertificateFactory.getInstance("X509").generateCertificate(new FileInputStream(certPath + "/ca.pem"));

    // load Client cert
    Certificate clientCert = CertificateFactory.getInstance("X509").generateCertificate(new FileInputStream(certPath + "/cert.pem"));

    // load Client private key and store into keystore
    byte[] encodedPrivateKey = Files.readAllBytes(Paths.get(certPath + "/key.pem"));
    encodedPrivateKey = Base64.getMimeDecoder().decode(encodedPrivateKey);
    PKCS8EncodedKeySpec keySpec = new PKCS8EncodedKeySpec(encodedPrivateKey);
    RSAPrivateKey pk = (RSAPrivateKey) KeyFactory.getInstance("RSA").generatePrivate(keySpec);
    X509Certificate[] certChain = new X509Certificate[2];
    certChain[0] = (X509Certificate) caCert;
    certChain[1] = (X509Certificate) clientCert;

    KeyStore.PrivateKeyEntry privEntry = new KeyStore.PrivateKeyEntry(pk, certChain);
    KeyStore.ProtectionParameter password = new KeyStore.PasswordProtection("docker".toCharArray());
    keystore.setEntry("alias", privEntry, password);

    return keystore;
}
