public SearchRequestBuilder getSearchRequestBuilder(Client client, QueryBuilder queryBuilder, List<AggregationBuilder> aggregationBuilders, String... indices) {
    SearchRequestBuilder searchRequestBuilder = client.prepareSearch(indices)
