public static Map<String, String> parseShorthand(String shorthand) {
    Map<String, String> result = new HashMap<>();
    String[] parts = shorthand.split("-");
    for (int i = 0; i < parts.length; i++) {
        String part = parts[i];
        if (part.length() == 0) {
            continue;
        } else if (part.contains(":")) {
            String[] subParts = part.split(":");
            result.put(subParts[0], subParts[1]);
        } else if (i < parts.length - 1 && !parts[i + 1].contains(":")) {
            result.put(part, parts[i + 1]);
            i++;
        } else {
            result.put(part, "");
        }
    }
    return result;
}
