public void ensureCapacity(int headerSize) {
    int currentSize = 0;
    for (int index = startIndex; index != nextIndex; index = (index + 1) % capacity) {
        HeaderField header = headerFields[index];
        currentSize += header.size();
        if (currentSize > headerSize) {
            while (currentSize > headerSize) {
                HeaderField removedHeader = headerFields[startIndex];
                currentSize -= removedHeader.size();
                headerFields[startIndex] = null;
                startIndex = (startIndex + 1) % capacity;
            }
            break;
        }
    }
}
