public Node findClosestNode(Point target) {
    double minDistance = Double.MAX_VALUE;
    Node closestNode = null;

    for (Node node : nodes) {
        double distance = node.getLocation().distance(target);
        if (distance < minDistance) {
            minDistance = distance;
            closestNode = node;
        }
    }

    if (minDistance > minimumDistance)
        return null;

    return closestNode;
}
