public static <K,V> K getLastKey(Map<K,V> map, boolean reverseOrder) {
    if (map.isEmpty()) {
        return null;
    }
    List<K> keys = new ArrayList<>(map.keySet());
    if (reverseOrder) {
        Collections.reverse(keys);
    }
    return keys.get(keys.size()-1);
}
