public static int readUntilEndChar(StringBuilder out, String in, int start, String end) {
    int index = start;
    int endIndex = -1;
    while (index < in.length()) {
        char c = in.charAt(index);
        if (end.indexOf(c) >= 0) { // end char found
            endIndex = index;
            break;
        }
        out.append(c);
        index++;
    }
    return endIndex;
}
