public boolean pushDownCriteriaToJoin(TreeNode criteriaNode, TreeNode joinNode) {
   if (criteriaNode == null || joinNode == null) {
       throw new IllegalArgumentException("Criteria node or join node cannot be null");
   }

   boolean criteriaPushedDown = false;
   List<TreeNode> joinConditions = joinNode.getChildren();
   for (TreeNode condition : joinConditions) {
       if (condition.getType() == TreeNodeType.LOGICAL_OPERATOR 
               && condition.getValue().equals("AND")) {
           List<TreeNode> subConditions = condition.getChildren();
           if (!subConditions.contains(criteriaNode)) {
               subConditions.add(criteriaNode);
               criteriaPushedDown = true;
           }
       }
   }

   return criteriaPushedDown;
}
