public Side selectBestSideToSplit(Polyline polyline) {
   Side bestSide = null;
   double bestScore = polyline.getScore();
   for (Side side : polyline.getSides()) {
      double splitScore = side.getSplitScore();
      if (splitScore > bestScore) {
         bestScore = splitScore;
         bestSide = side;
      }
   }
   return bestSide;
}
