public void sortByPeanoCurve(Object[] objs, int start, int end, double[][] mms, int[] dims, int depth, int[] bits, int[] desc) {
   if (start >= end || depth >= dims.length) return;
   int[] bounds = new int[] {start, end};
   int dim = dims[depth];
   for (int b : bits) {
      int split = quickSelectByDim(objs, bounds[0], bounds[1], dim, b, mms);
      sortByPeanoCurve(objs, bounds[0], split, mms, dims, depth + 1, bits, desc);
      bounds[0] = split;
   }
   sortByPeanoCurve(objs, bounds[0], bounds[1], mms, dims, depth + 1, bits, desc);
   for (int i = start; i < end; i++) {
      desc[i] = i;
   }
   Arrays.sort(desc, start, end, (i, j) -> peanoCompare(objs, i, j, mms, dims, bits));
}
