public void rotateMolecule(List<Point3D> atomCon, Point3D center, double angle) {
   double sinTheta = Math.sin(angle);
   double cosTheta = Math.cos(angle);

   for (Point3D atom : atomCon) {
      double x = atom.getX() - center.getX();
      double y = atom.getY() - center.getY();
      double z = atom.getZ() - center.getZ();

      atom.setX((cosTheta + (1 - cosTheta) * x * x) * atom.getX() + ((1 - cosTheta) * x * y - sinTheta * z) * atom.getY() + ((1 - cosTheta) * x * z + sinTheta * y) * atom.getZ() + center.getX());
      atom.setY(((1 - cosTheta) * y * x + sinTheta * z) * atom.getX() + (cosTheta + (1 - cosTheta) * y * y) * atom.getY() + ((1 - cosTheta) * y * z - sinTheta * x) * atom.getZ() + center.getY());
      atom.setZ(((1 - cosTheta) * z * x - sinTheta * y) * atom.getX() + ((1 - cosTheta) * z * y + sinTheta * x) * atom.getY() + (cosTheta + (1 - cosTheta) * z * z) * atom.getZ() + center.getZ());
   }
}
