public Property deepCopy() throws IOException, URISyntaxException, ParseException {
    Property copy = new Property();
    // Copy basic properties
    copy.setName(this.getName());
    copy.setValue(this.getValue());
    // Copy URI if it exists
    if (this.getURI() != null) {
        copy.setURI(new URI(this.getURI().toString()));
    }
    // Copy date if it exists
    if (this.getDate() != null) {
        copy.setDate(new Date(this.getDate().getTime()));
    }
    // Copy parameters
    for (Parameter param : this.getParameters()) {
        copy.getParameters().add(new Parameter(param.getName(), param.getValue()));
    }
    return copy;
}
