public void deleteAllTraits(AtlasVertex instanceVertex) throws AtlasException{
    AtlasGraphManagement management = AtlasGraphProvider.getGraphInstance().getManagementSystem();
    try{
        AtlasVertex vertex = AtlasGraphUtilsV2.findByVertexId(instanceVertex.id().toString());
        if (vertex == null) {
            throw new AtlasException("Vertex for id " + instanceVertex.id().toString() + " is not found");
        }
        AtlasVertex instanceVertexToDeleteTraits = graphHelper.getVertexForGUID(instanceVertex.getId().toString());
        AtlasType type = typeRegistry.getType(instanceVertexToDeleteTraits);

        String relationshipLabel = AtlasGraphUtilsV2.getTraitLabel(type.getTypeName());

        //delete all the traits from the vertex
        Iterable<AtlasEdge> edges = instanceVertexToDeleteTraits.getEdges(AtlasEdgeDirection.OUT, relationshipLabel);
        for (AtlasEdge edge : edges) {
            graphHelper.getGraph().removeEdge(edge);
        }
    } finally {
        AtlasGraphProvider.releaseGraphInstance();
    }
}
