public List<String> mergeDuplicateIons(List<String> frags) {
    List<String> mergedFrags = new ArrayList<>();
    for (String frag : frags) {
        String mergedFrag = frag;
        while (mergedFrag.contains("++") || mergedFrag.contains("--") || mergedFrag.contains("[]") 
            || mergedFrag.contains("[.]") || mergedFrag.contains(".]")) {
            if (mergedFrag.contains("++")) {
                mergedFrag = mergedFrag.replace("++", "+");
            }
            if (mergedFrag.contains("--")) {
                mergedFrag = mergedFrag.replace("--", "-");
            }
            if (mergedFrag.contains("[]")) {
                mergedFrag = mergedFrag.replace("[]", "");
            }
            if (mergedFrag.contains("[.]")) {
                mergedFrag = mergedFrag.replace("[.]", "[");
            }
            if (mergedFrag.contains(".]")) {
                mergedFrag = mergedFrag.replace(".]", "]");
            }
        }
        if (!mergedFrags.contains(mergedFrag)) {
            mergedFrags.add(mergedFrag);
        }
    }
    return mergedFrags;
}
