public static List<Class<?>> getListOfSuperclassesAndInterfaces(Class<?> clazz) {
    List<Class<?>> resultList = new ArrayList<>();
    if (clazz == null) {
        return resultList;
    } else {
        resultList.add(clazz);
        resultList.addAll(getListOfSuperclassesAndInterfaces(clazz.getSuperclass()));
        for (Class<?> iface : clazz.getInterfaces()) {
            resultList.addAll(getListOfSuperclassesAndInterfaces(iface));
        }
        return resultList;
    }
}
