public Table generateDependenciesTable(List<Dependency> dependencies, Map<String, String> filters) {
    List<Dependency> filteredDependencies = new ArrayList<>();
    for (Dependency dependency : dependencies) {
        boolean filtered = true;
        for (Map.Entry<String, String> filter : filters.entrySet()) {
            String propertyValue = dependency.getProperty(filter.getKey());
            if (propertyValue == null || !propertyValue.equals(filter.getValue())) {
                filtered = false;
                break;
            }
        }
        if (filtered) {
            filteredDependencies.add(dependency);
        }
    }

    Table dependenciesTable = new Table();
    dependenciesTable.addColumn("Dependency Name");
    dependenciesTable.addColumn("Type");
    dependenciesTable.addColumn("Version");
    dependenciesTable.addColumn("License");

    for (Dependency dependency : filteredDependencies) {
        TableRow row = new TableRow();
        row.addCell(dependency.getName());
        row.addCell(dependency.getType());
        row.addCell(dependency.getVersion());
        row.addCell(dependency.getLicense());
        dependenciesTable.addRow(row);
    }

    return dependenciesTable;
}
