public static void shuffleDBIDArray(DBID[] ids, Random random, int limit) {
    for(int i = 0; i < limit; i++) {
        int j = random.nextInt(i + 1);
        DBID temp = ids[i];
        ids[i] = ids[j];
        ids[j] = temp;
    }
    for(int i = limit; i < ids.length; i++) {
        int j = random.nextInt(ids.length);
        DBID temp = ids[i];
        ids[i] = ids[j];
        ids[j] = temp;
    }
}
