public static <T> T getValueFromAnnotation(Annotation annotation, String value, Class<T> expectedType) {
    return expectedType.cast(annotation.getClass().getDeclaredMethods().stream()
            .filter(method -> method.getName().equals(value))
            .findFirst()
            .map(method -> {
                try {
                    return method.invoke(annotation);
                } catch (IllegalAccessException | InvocationTargetException e) {
                    throw new RuntimeException(e);
                }
            }).orElse(null));
}
