import org.json.simple.JSONArray;
import org.json.simple.JSONObject;
import org.json.simple.parser.JSONParser;
import org.json.simple.parser.ParseException;
import java.io.FileReader;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

public class FeatureParser {
    public static List<Feature> parseJSONFile(String filename) throws IOException, ParseException {
        List<Feature> featureList = new ArrayList<>();
        JSONParser parser = new JSONParser();
        JSONArray jsonArray = (JSONArray) parser.parse(new FileReader(filename));

        for (Object object : jsonArray) {
            JSONObject jsonObject = (JSONObject) object;
            String name = (String) jsonObject.get("name");
            String description = (String) jsonObject.get("description");
            JSONArray scenariosJSON = (JSONArray) jsonObject.get("scenarios");
            List<Scenario> scenariosList = new ArrayList<>();

            for (Object scenarioObject : scenariosJSON) {
                JSONObject scenarioJSON = (JSONObject) scenarioObject;
                String scenarioName = (String) scenarioJSON.get("name");
                String scenarioDescription = (String) scenarioJSON.get("description");
                JSONArray stepsJSON = (JSONArray) scenarioJSON.get("steps");
                List<Step> stepsList = new ArrayList<>();

                for (Object stepObject : stepsJSON) {
                    JSONObject stepJSON = (JSONObject) stepObject;
                    String stepDescription = (String) stepJSON.get("description");
                    String expectedResult = (String) stepJSON.get("expected_result");
                    Step step = new Step(stepDescription, expectedResult);
                    stepsList.add(step);
                }

                Scenario scenario = new Scenario(scenarioName, scenarioDescription, stepsList);
                scenariosList.add(scenario);
            }

            Feature feature = new Feature(name, description, scenariosList);
            featureList.add(feature);
        }

        return featureList;
    }
}
