public List<SecStrucState> parseDSSP(String dsspOut, Structure structure, boolean assign)
        throws StructureException, IOException {

    List<SecStrucState> annotations = new ArrayList<>();

    BufferedReader reader = new BufferedReader(new StringReader(dsspOut));
    String line;

    while ((line = reader.readLine()) != null) {
        if (line.trim().startsWith("#")) {
            continue;
        }
        if (line.trim().length() < 109) {
            continue;
        }

        SecStrucState annotation = new SecStrucState();

        int index = Integer.parseInt(line.substring(5, 10).trim());
        Chain chain = structure.getChainByIndex(line.substring(11, 12));

        if (chain != null) {
            // assign SS to residues if assign flag is set
            if (assign) {
                for (int i = 0; i < 4; i++) {
                    char code = line.charAt(i + 16);
                    SecondaryStructure secStruct;
                    switch (code) {
                        case 'H':
                            secStruct = SecondaryStructure.HELIX;
                            break;
                        case 'E':
                            secStruct = SecondaryStructure.STRAND;
                            break;
                        default:
                            secStruct = SecondaryStructure.COIL;
                            break;
                    }
                    chain.getAtomGroup(index).setSecondaryStructure(secStruct);
                    index++;
                }
            }

            List<SecondaryStructure.Type> types = new ArrayList<>();
            for (int i = 0; i < 4; i++) {
                char code = line.charAt(i + 16);
                SecondaryStructure.Type type;
                switch (code) {
                    case 'H':
                        type = SecondaryStructure.Type.HELIX;
                        break;
                    case 'E':
                        type = SecondaryStructure.Type.STRAND;
                        break;
                    default:
                        type = SecondaryStructure.Type.COIL;
                        break;
                }
                types.add(type);
            }
            annotation.setTypes(types);

            annotation.setStartIndex(index - 4);
            annotation.setChain(chain);
            annotations.add(annotation);
        }
    }
    reader.close();

    return annotations;
}
