public Map<String, Integer> createResourceMap(List<String> resourceTypes, String actionType) {
    Map<String, Integer> resourceMap = new HashMap<>();
    // initializing the map with count 0 for each resource type
    for(String resourceType : resourceTypes) {
        resourceMap.put(resourceType, 0);
    }
    // logic to update count based on actionType parameter
    // for example, if actionType is 'pending', increase count for each resource type by 1
    if(actionType.equals("pending")) {
        for(String resourceType : resourceTypes) {
            int count = resourceMap.get(resourceType);
            resourceMap.put(resourceType, count+1);
        }
    }
    // similarly handle other action types
    // running, stopped, etc.
    return resourceMap;
}
