public String getBuildToolsLibDirPath() {
    return System.getenv("ANDROID_HOME") + "/build-tools/" + getVersion() + "/lib/";
}

private String getVersion() {
    // Get the highest version of build-tools installed
    File buildToolsDir = new File(System.getenv("ANDROID_HOME") + "/build-tools/");
    String[] buildToolsVersions = buildToolsDir.list();
    int highestVersion = 0;
    for (String version : buildToolsVersions) {
        int versionNumber = Integer.parseInt(version.replace(".", ""));
        highestVersion = Math.max(highestVersion, versionNumber);
    }
    // Convert the highest version number back to format X.X.X
    return highestVersion / 100 + "." + (highestVersion % 100) / 10 + "." + highestVersion % 10;
}
