                    null,
                    updatersMap,
                    interceptersMap,
                    serializedFrame);
            frames[idx] = versionedFrame;
            idx++;
            currentMethodState = currentMethodState.getNext();
        }

        Object context = cn.getContext();

        return new SerializedState(coroutine, context, frames);
