public void insertIntoHeap(int k, int x) {
    heap.add(k, x);
    int i = k;

    while (i > 0 && heap.get(i) > heap.get(parent(i))) {
        swap(i, parent(i));
        i = parent(i);
    }

    while (leftChild(i) < heap.size()) {
        int maxChild = maxChild(i);
        if (heap.get(i) < heap.get(maxChild)) {
            swap(i, maxChild);
            i = maxChild;
        } else {
            break;
        }
    }
}

private int parent(int i) {
    return (i - 1) / 2;
}

private int leftChild(int i) {
    return 2 * i + 1;
}

private int rightChild(int i) {
    return 2 * i + 2;
}

private int maxChild(int i) {
    int left = leftChild(i);
    int right = rightChild(i);

    if (right >= heap.size() || heap.get(left) > heap.get(right)) {
        return left;
    } else {
        return right;
    }
}

private void swap(int i, int j) {
    int temp = heap.get(i);
    heap.set(i, heap.get(j));
    heap.set(j, temp);
}
