public static int numberOfCCWRotations(Grid g) {
    byte[] location = {3, 6, 0, 5}; // canonical location of corner
    int[] values = new int[4];
    for (int i = 0; i < 4; i++) {
        Corner c = g.getCorner(i);
        values[i] = c.getValue();
    }
    int minRotations = Integer.MAX_VALUE;
    for (int i = 0; i < 4; i++) {
        int diff = (values[i] - values[0] + 12) % 12; // take modulo 12 to wrap around
        int[] newValues = new int[4];
        for (int j = 0; j < 4; j++) {
            newValues[j] = (values[j] - values[0] + 12 - diff) % 12; // normalize values
        }
        int rotations = 0;
        for (int j = 0; j < 4; j++) {
            if (newValues[j] != location[j]) {
                int k = (j + 1) % 4;
                while (newValues[k] != location[j]) { // keep rotating until desired corner is in place
                    k = (k + 1) % 4;
                    rotations++;
                }
                Corner temp = g.getCorner(k);
                g.setCorner(k, g.getCorner(j));
                g.setCorner(j, temp);
                newValues[k] = newValues[j];
            }
        }
        minRotations = Math.min(minRotations, rotations);
    }
    return minRotations;
}
