public String callAuthenticatedEndpoint(String accessToken, String dataUrl) throws HttpException {
    internalInit();
    try {
        HttpRequest request = HttpRequest.newBuilder().uri(new URI(dataUrl))
                .header("Authorization", "Bearer " + accessToken).GET().build();

        HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());

        if (response.statusCode() >= 200 && response.statusCode() < 300)
            return response.body();
        else
            throw new HttpException("Error calling endpoint: " + response.statusCode() + " " + response.body());
    } catch (URISyntaxException | IOException | InterruptedException e) {
        throw new HttpException("Error calling endpoint: " + e.getMessage());
    }
}
