public <T> T endAsyncMethod(CompletableFuture<T> promise) {
    // complete the promise
    promise.complete(null);
    // get the result of the promise if it is not null
    T result = null;
    try {
        result = promise.get();
    } catch (InterruptedException | ExecutionException e) {
        // handle the exception
        e.printStackTrace();
    }
    return result;
}
