public String createEncodedHref(String collectionName, Map<String, String> filters) {
    String encodedName = URLEncoder.encode(collectionName, StandardCharsets.UTF_8);
    StringBuilder sb = new StringBuilder(encodedName);
    if (filters != null && !filters.isEmpty()) {
        sb.append("?");
        for (Map.Entry<String, String> entry : filters.entrySet()) {
            String encodedKey = URLEncoder.encode(entry.getKey(), StandardCharsets.UTF_8);
            String encodedValue = URLEncoder.encode(entry.getValue(), StandardCharsets.UTF_8);
            sb.append(encodedKey).append("=").append(encodedValue).append("&");
        }
        sb.deleteCharAt(sb.length() - 1);
    }
    return sb.toString();
}
