        return "The path is final because it ends with .pdf";
    } else if (path.contains("archive/")) {
        return "The path is final because it is inside an archive folder";
    } else if (path.length() > 50) {
        return "The path is final because it is longer than 50 characters";
    } else {
        return null;
    }
}
