public List<Metric> mapMetrics(List<Metric> metrics, List<Double> constants) {
    List<Metric> mappedMetrics = new ArrayList<>();
    for (Metric metric : metrics) {
        List<DataPoint> newDataPoints = new ArrayList<>();
        for (DataPoint dataPoint : metric.getDataPoints()) {
            double mappedValue = dataPoint.getValue();
            for (double constant : constants) {
                mappedValue *= constant;
            }
            newDataPoints.add(new DataPoint(dataPoint.getTimestamp(), mappedValue));
        }
        mappedMetrics.add(new Metric(metric.getName(), newDataPoints));
    }
    return mappedMetrics;
}
