public List<Attribute> getExtendedAttributes(Operation operation) {
    List<Attribute> extendedAttributes = new ArrayList<>();

    // loop through AttributeUpdates of the operation
    for (AttributeUpdate attributeUpdate : operation.getAttributeUpdates()) {
        // check if AttributeUpdate has extended attributes
        if (attributeUpdate.getExtendedAttributes() != null) {
            // add all extended attributes to the list
            extendedAttributes.addAll(attributeUpdate.getExtendedAttributes());
        }
    }
    return extendedAttributes;
}
