public boolean waitForResponses(int expectedResponses, int timeout, boolean waitForLocalNode) throws InterruptedException {
    long endTimeMillis = System.currentTimeMillis() + timeout;
    int receivedResponses = 0;
    while (System.currentTimeMillis() < endTimeMillis && receivedResponses < expectedResponses) {
        if (waitForLocalNode) {
            receivedResponses = countResponses();
        } else {
            receivedResponses = countResponsesExcludeLocalNode();
        }
        Thread.sleep(100);
    }
    return receivedResponses >= expectedResponses;
}
