public String determineMacLibrary(String library) {
    String osArch = System.getProperty("os.arch");
    String libraryResource = "";
    if (osArch.equals("x86_64")) {
        libraryResource = "lib/" + library + "_x86_64.dylib";
    } else if (osArch.equals("arm64")) {
        libraryResource = "lib/" + library + "_arm64.dylib";
    } else {
        // unsupported architecture
        throw new UnsupportedOperationException("Unsupported architecture: " + osArch);
    }
    return libraryResource;
}
