public void writeDatagram(DatagramPacket datagram) throws IOException {
    // Get the data in the datagram
    byte[] data = datagram.getData();

    // Get the length of the data
    int length = datagram.getLength();

    // Get the address and port of the remote host
    InetAddress address = datagram.getAddress();
    int port = datagram.getPort();

    // Create a new datagram packet with the data, length, address, and port
    DatagramPacket newDatagram = new DatagramPacket(data, length, address, port);

    // Write the new datagram to the underlying stream
    outputStream.write(newDatagram.getData(), 0, newDatagram.getLength());
}
