public static String standardizeURI(String uri) {
    // Define regexes to match Elasticsearch API paths
    Pattern pattern1 = Pattern.compile("/_search/?([\\?#].*)?$");
    Pattern pattern2 = Pattern.compile("/_msearch/?([\\?#].*)?$");
    Pattern pattern3 = Pattern.compile("/([_\\w]+)/?([_\\w]+)?/?([\\?#].*)?$");

    // Replace numerical IDs with '?'
    uri = uri.replaceAll("/([_\\w]+)/([\\d,]+)/?", "/$1/?");

    // Remove additional parameters in the request
    Matcher matcher1 = pattern1.matcher(uri);
    if (matcher1.find()) {
        uri = matcher1.replaceAll("/_search");
    }
    Matcher matcher2 = pattern2.matcher(uri);
    if (matcher2.find()) {
        uri = matcher2.replaceAll("/_msearch");
    }
    Matcher matcher3 = pattern3.matcher(uri);
    if (matcher3.find()) {
        uri = matcher3.replaceAll("/$1/$2");
    }

    return uri;
}
