public static Map<String, String> addTzidParameter(Property property, boolean hasTime, WriteContext context) {
    Map<String, String> parameters = property.getParameters();
    String tzid = context.getTimezoneId();
    if (tzid != null && hasTime && !parameters.containsKey(Parameter.TZID)) {
        parameters.put(Parameter.TZID, tzid);
        property.setParameters(parameters);
    }
    return parameters;
}
