import java.time.LocalDate;
import java.time.Month;
import java.util.Iterator;

public class MonthGenerator implements Iterable<LocalDate> {

    private final int[] months;
    private final LocalDate startDate;

    public MonthGenerator(int[] months, LocalDate startDate) {
        this.months = months;
        this.startDate = startDate;
    }

    @Override
    public Iterator<LocalDate> iterator() {
        return new Iterator<LocalDate>() {

            private int currentMonth = 0;
            private LocalDate currentDate = LocalDate.of(startDate.getYear(), months[currentMonth], startDate.getDayOfMonth());

            @Override
            public boolean hasNext() {
                return true;
            }

            @Override
            public LocalDate next() {
                LocalDate toReturn = currentDate;
                currentMonth++;
                if (currentMonth == months.length) {
                    currentMonth = 0;
                    currentDate = currentDate.plusYears(1);
                }
                currentDate = currentDate.withMonth(months[currentMonth]);
                return toReturn;
            }
        };
    }

    public static void main(String[] args) {
        MonthGenerator generator = new MonthGenerator(new int[]{2, 6, 12}, LocalDate.of(2021, Month.JANUARY, 1));
        for (LocalDate localDate : generator) {
            System.out.println(localDate);
        }
    }
}
