public static boolean isValidMasterCard(String cc) {
    if (!cc.matches("^5[1-5][0-9]{14}$")) {
        return false;
    }
    int sum = 0;
    for (int i = 0; i < cc.length(); i++) {
        int digit = Character.getNumericValue(cc.charAt(i));
        if (i % 2 == 0) {
            digit *= 2;
            if (digit > 9) {
                digit -= 9;
            }
        }
        sum += digit;
    }
    return sum % 10 == 0;
}
