public static <T> void runContinuation(Task<T> task, Consumer<T> onSuccess, Consumer<Exception> onFailure, Runnable onCancellation) {
    task.whenComplete((result, exception) -> {
        if (task.isCancelled()) {
            onCancellation.run();
        } else if (exception != null) {
            onFailure.accept(exception);
        } else {
            onSuccess.accept(result);
        }
    });
}
