public void testReportParameters(Report report) throws ParameterNotFoundException {
    List<String> definedParameters = report.getDefinedParameters();
    List<String> usedParameters = report.getUsedParameters();

    for (String parameter : usedParameters) {
        if (!definedParameters.contains(parameter)) {
            throw new ParameterNotFoundException("Parameter " + parameter + " used in report is not defined.");
        }
    }
}
