public boolean commitPersistUnlock(Transaction transaction) {
    boolean success = false;
    try {
        transaction.commit();
        success = true;
    } catch (Exception ex) {
        // Handle any exceptions that occur during commit
    } finally {
        try {
            transaction.close();
        } catch (Exception ex) {
            // Handle any exceptions that occur during resource release
        }
    }
    return success;
}
