public Filtration optimizeFiltrationWithDimFilter(Filtration filtration) {
    List<Filter> filters = filtration.getFilters();
    List<Filter> optimizedFilters = new ArrayList<>();

    for (int i = 0; i < filters.size(); i++) {
        Filter currentFilter = filters.get(i);

        if (currentFilter instanceof DimFilter) {
            List<Filter> children = ((DimFilter) currentFilter).getChildren();
            if (children.size() == 1 && children.get(0) instanceof IntervalFilter) {
                optimizedFilters.add(children.get(0));
            } else {
                optimizedFilters.add(currentFilter);
            }
        } else {
            optimizedFilters.add(currentFilter);
        }
    }

    return new Filtration(optimizedFilters);
}
