import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.Base64;

public static String httpPostRequest(String url, String body, String credentials) throws Exception {
    URL obj = new URL(url);
    HttpURLConnection con = (HttpURLConnection) obj.openConnection();

    // Setting basic post request
    con.setRequestMethod("POST");
    con.setRequestProperty("Content-Type", "application/json");

    // Adding Basic Authentication header if credentials provided
    if(credentials != null && !credentials.isEmpty()){
        String auth = "Basic " + Base64.getEncoder().encodeToString(credentials.getBytes());
        con.setRequestProperty("Authorization", auth);
    }

    // Adding post body to request
    con.setDoOutput(true);
    OutputStream os = con.getOutputStream();
    os.write(body.getBytes());
    os.flush();
    os.close();

    // Reading response from server
    BufferedReader in = new BufferedReader(new InputStreamReader(con.getInputStream()));
    String inputLine;
    StringBuffer response = new StringBuffer();

    while ((inputLine = in.readLine()) != null) {
        response.append(inputLine);
    }
    in.close();

    return response.toString();
}
