public void configureOrcidClient(Properties properties) {
    //Initialize the ORCID client using the provided properties
    String clientId = properties.getProperty("clientId");
    String clientSecret = properties.getProperty("clientSecret");
    String accessTokenUri = properties.getProperty("accessTokenUri");
    String userAuthorizationUri = properties.getProperty("userAuthorizationUri");
    String redirectUri = properties.getProperty("redirectUri");

    OAuth2ProtectedResourceDetails details = new AuthorizationCodeResourceDetails();
    details.setClientId(clientId);
    details.setClientSecret(clientSecret);
    details.setAccessTokenUri(accessTokenUri);
    details.setUserAuthorizationUri(userAuthorizationUri);
    details.setPreEstablishedRedirectUri(redirectUri);

    //Create the ORCID client using the initialized properties
    OAuth2RestTemplate restTemplate = new OAuth2RestTemplate(details);
    OrcidRestTemplate orcidRestTemplate = new OrcidRestTemplate(restTemplate);

    //Set the ORCID client for use
    OrcidClientImpl.setOrcidRestTemplate(orcidRestTemplate);
}
