public static <K, V> void sortWithComparator(K[] keys, V[] values, int start, int end, Comparator<? super K> comparator) {
    Arrays.sort(keys, start, end, comparator);
    Arrays.sort(values, start, end, new Comparator<Integer>() {
        @Override
        public int compare(Integer o1, Integer o2) {
            return comparator.compare(keys[o1], keys[o2]);
        }
    });
}
