public List<String> fetchFilteredHostnames(int numOfHostnames, String filterStr) {
    List<Nshostname> allHostnames = getAllHostnames(); // Assuming this method returns all available hostnames

    // Converting filterStr to a Map to apply filtering
    Map<String, String> filterMap = convertFilterStringToMap(filterStr); // Implement this method

    // Filtering hostnames based on the filter criteria
    List<String> filteredHostnames = allHostnames.stream()
                                                  .filter(hostname -> meetsFilterCriteria(hostname, filterMap))
                                                  .map(Nshostname::getHostname)
                                                  .limit(numOfHostnames)
                                                  .collect(Collectors.toList());
    return filteredHostnames;
}

private boolean meetsFilterCriteria(Nshostname hostname, Map<String, String> filters) {
    for (Map.Entry<String, String> entry : filters.entrySet()) {
        String filterKey = entry.getKey();
        String filterValue = entry.getValue();

        switch (filterKey) {
            case "port":
                if (!hostname.getPort().equals(filterValue)) {
                    return false;
                }
                break;

            case "servicetype":
                if (!hostname.getServiceType().equals(filterValue)) {
                    return false;
                }
                break;

            // Add more cases for additional filter keys, as required

            default:
                throw new IllegalArgumentException("Invalid filter key: " + filterKey);
        }
    }
    return true;
}

