public boolean isEqual(Object a, Object b) {
    if(a == null || b == null) {
        return a == b;
    }
    if(a instanceof Integer && b instanceof Double) {
        return Double.valueOf((Integer)a).equals((Double)b);
    }
    if(a instanceof Double && b instanceof Integer) {
        return Double.valueOf((Integer)b).equals((Double)a);
    }
    return a.equals(b);
}
