public Optional<JobKey> retrieveJobKeyByName(String name) throws MangooSchedulerException {
    try {
        JobKey jobKey = scheduler.getJobKeys(GroupMatcher.anyGroup()).stream()
                .filter(jk -> jk.getName().equals(name))
                .findFirst()
                .orElse(null);
        if (jobKey == null) {
            return Optional.empty();
        }
        return Optional.of(jobKey);
    } catch (SchedulerException e) {
        throw new MangooSchedulerException("Failed to retrieve JobKey for name: " + name, e);
    }
}
