public double[][] computeAndExtractNullPoints(double[][] M) {

    int n = M.length;

    // Compute M times M
    double[][] M_times_M = new double[n][n];
    for(int i=0; i<n; i++) {
        for(int j=0; j<n; j++) {
            for(int k=0; k<n; k++) {
                M_times_M[i][j] += M[i][k] * M[k][j];
            }
        }
    }

    // Find eigenvalues and eigenvectors using Apache Commons Math library
    EigenDecomposition eigen = new EigenDecomposition(MatrixUtils.createRealMatrix(M_times_M));
    double[] eigenValues = eigen.getRealEigenvalues();
    RealMatrix eigenVectors = eigen.getV();

    // Sort the eigenvectors by ascending order of their eigenvalues
    TreeMap<Double, RealVector> sortedEigenvectors = new TreeMap<>();
    for(int i=0; i<n; i++) {
        sortedEigenvectors.put(eigenValues[i], eigenVectors.getColumnVector(i));
    }
    List<RealVector> sortedVectors = new ArrayList<>(sortedEigenvectors.values());

    // Extract null points from the 4 eigenvectors with smallest eigenvalues
    List<double[]> nullPoints = new ArrayList<>();
    for(int i=0; i<4; i++) {
        RealVector eigenvector = sortedVectors.get(i);
        double[] nullPoint = new double[n];
        for(int j=0; j<n; j++) {
            nullPoint[j] = (Math.abs(eigenvector.getEntry(j)) < 1e-8) ? 1.0 : 0.0;
        }
        nullPoints.add(nullPoint);
    }

    // Return the null points as a double[][]
    double[][] result = new double[4][n];
    for(int i=0; i<4; i++) {
        result[i] = nullPoints.get(i);
    }
    return result;
}
