public MailAccount lookupReservedAccount(String accountReservationKey) {
    Thread thread = Thread.currentThread();
    Map<String, MailAccount> reservedAccounts = getReservedAccounts(thread);
    return reservedAccounts.get(accountReservationKey);
}

private Map<String, MailAccount> getReservedAccounts(Thread thread) {
    Map<String, MailAccount> reservedAccounts = (Map<String, MailAccount>) thread.getLocal(getReservedAccountsKey());
    if (reservedAccounts == null) {
        reservedAccounts = new HashMap<>();
        thread.setLocal(getReservedAccountsKey(), reservedAccounts);
    }
    return reservedAccounts;
}

private static Object getReservedAccountsKey() {
    return "reservedAccounts-" + MailAccount.class.getName();
}
