import javax.annotation.ManagedBean;
import javax.naming.Context;
import javax.naming.InitialContext;
import javax.naming.NamingException;
import javax.servlet.ServletContext;
import javax.servlet.ServletContextEvent;
import javax.servlet.ServletContextListener;

public class ManagedBeanListener implements ServletContextListener {

    private static final String JNDI_PREFIX = "java:comp/env/";

    @Override
    public void contextInitialized(ServletContextEvent event) {
        ServletContext servletContext = event.getServletContext();
        DeploymentAnnotationIndex index = DeploymentAnnotationIndex.getAnnotationIndex(servletContext);

        for (Class<?> clazz : index.getClassesWithAnnotation(ManagedBean.class)) {
            ManagedBean annotation = clazz.getAnnotation(ManagedBean.class);
            String name = annotation.value();

            if (name.isEmpty()) {
                name = clazz.getSimpleName();
            }

            String jndiName = getJndiName(servletContext, name);

            try {
                Context jndiContext = new InitialContext();
                Object managedBean = clazz.newInstance();
                jndiContext.bind(jndiName, managedBean);
            } catch (NamingException | InstantiationException | IllegalAccessException e) {
                throw new DeploymentUnitProcessingException("Failed to bind managed bean with JNDI name: " + jndiName, e);
            }
        }
    }

    private String getJndiName(ServletContext servletContext, String name) {
        String contextName = servletContext.getContextPath().replaceAll("/", "");
        contextName = contextName.isEmpty() ? "ROOT" : contextName;
        return JNDI_PREFIX + contextName + "/" + name;
    }

    @Override
    public void contextDestroyed(ServletContextEvent event) {
        // Do nothing
    }

}
