public void setUTF8Sequence(int position, int codePoint) throws InvalidCodePointException {
    if (codePoint < 0 || codePoint > 0x10FFFF) {
        throw new InvalidCodePointException("Invalid code point");
    }
    byte[] utf8Bytes;
    if (codePoint <= 0x7F) {
        utf8Bytes = new byte[]{(byte) codePoint};
    } else if (codePoint <= 0x7FF) {
        utf8Bytes = new byte[2];
        utf8Bytes[0] = (byte) (0xC0 | ((codePoint >> 6) & 0x1F));
        utf8Bytes[1] = (byte) (0x80 | (codePoint & 0x3F));
    } else if (codePoint <= 0xFFFF) {
        utf8Bytes = new byte[3];
        utf8Bytes[0] = (byte) (0xE0 | ((codePoint >> 12) & 0x0F));
        utf8Bytes[1] = (byte) (0x80 | ((codePoint >> 6) & 0x3F));
        utf8Bytes[2] = (byte) (0x80 | (codePoint & 0x3F));
    } else {
        utf8Bytes = new byte[4];
        utf8Bytes[0] = (byte) (0xF0 | ((codePoint >> 18) & 0x07));
        utf8Bytes[1] = (byte) (0x80 | ((codePoint >> 12) & 0x3F));
        utf8Bytes[2] = (byte) (0x80 | ((codePoint >> 6) & 0x3F));
        utf8Bytes[3] = (byte) (0x80 | (codePoint & 0x3F));
    }
    // Set the bytes to the given position
    // ...
}
