public Cache getDefaultCache(PageContext pc, String type) throws IOException {
        Cache cache = null;

        // Check if the cache is defined in the Application Context
        Map<String, Object> appScope = pc.getServletContext().getAttribute(Config.APPLICATION_SCOPE);
        if (appScope != null) {
            Object cfApplication = appScope.get("application");
            if (cfApplication instanceof CFApplication) {
                CFApplication cfApp = (CFApplication) cfApplication;
                cache = cfApp.getCache(type);
            }
        }

        // If cache is not defined in Application Context, get the default cache for the given type
        if (cache == null) {
            switch (type) {
                case Config.CACHE_DEFAULT_PROCESSED_TEMPLATES:
                    cache = pc.getPageContextServlet().getProcessedTemplatesCache();
                    break;
                case Config.CACHE_DEFAULT_QUERY:
                    cache = pc.getPageContextServlet().getQueryCache();
                    break;
                case Config.CACHE_DEFAULT_STATIC_FILES:
                    cache = pc.getPageContextServlet().getStaticFilesCache();
                    break;
                default:
                    throw new IllegalArgumentException("Invalid cache type: " + type);
            }
        }

        return cache;
    }
