import org.apache.jena.rdf.model.Literal;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.net.URI;
import java.time.*;
import java.util.*;

public Object rdfLiteralToObjectConverter(Literal lit) {

    Object obj = null;
    String datatypeURI = lit.getDatatypeURI();

    if (datatypeURI.equals(XSDstring.getURI())) {
        obj = lit.getString();
    } else if (datatypeURI.equals(XSDboolean.getURI())) {
        obj = lit.getBoolean();
    } else if (datatypeURI.equals(XSDbyte.getURI())) {
        obj = Byte.valueOf(lit.getString());
    } else if (datatypeURI.equals(XSDshort.getURI())) {
        obj = Short.valueOf(lit.getString());
    } else if (datatypeURI.equals(XSDint.getURI())) {
        obj = Integer.valueOf(lit.getString());
    } else if (datatypeURI.equals(XSDinteger.getURI())) {
        obj = new BigInteger(lit.getString());
    } else if (datatypeURI.equals(XSDlong.getURI())) {
        obj = Long.valueOf(lit.getString());
    } else if (datatypeURI.equals(XSDfloat.getURI())) {
        obj = Float.valueOf(lit.getString());
    } else if (datatypeURI.equals(XSDdouble.getURI())) {
        obj = Double.valueOf(lit.getString());
    } else if (datatypeURI.equals(XSDdecimal.getURI())) {
        obj = new BigDecimal(lit.getString());
    } else if (datatypeURI.equals(XSDdateTime.getURI())) {
        obj = lit.getDateTime().toGregorianCalendar().toZonedDateTime();
    } else if (datatypeURI.equals(XSDdate.getURI())) {
        obj = lit.getDateTime().toGregorianCalendar().toZonedDateTime().toLocalDate();
    } else if (datatypeURI.equals(XSDtime.getURI())) {
        obj = lit.getDateTime().toGregorianCalendar().toZonedDateTime().toLocalTime();
    } else if (datatypeURI.equals(XSDanyURI.getURI())) {
        obj = URI.create(lit.getString());
    }

    return obj;
}
