import net.sourceforge.argparse4j.ArgumentParser;
import net.sourceforge.argparse4j.impl.Arguments;
import net.sourceforge.argparse4j.inf.ArgumentParserException;
import net.sourceforge.argparse4j.inf.Namespace;

public static Namespace parseUnknownArguments(String[] unknown) {
    ArgumentParser parser = ArgumentParsers.newFor("unknownargs").build()
    parser.addArgument("--foo.bar")
        .dest("fooBar")
        .type(String.class);
    parser.addArgument("--bar.baz")
        .dest("barBaz")
        .type(String.class)
        .nargs("+");
    parser.addArgument("--foo.bar.baz")
        .dest("fooBarBaz")
        .type(String.class)
        .nargs("?")
        .setDefault("default");

    Namespace ns = null;
    try {
        ns = parser.parseArgs(unknown);
    } catch (ArgumentParserException e) {
        parser.handleError(e);
        System.exit(1);
    }

    return ns;
}
