import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.security.InvalidKeyException;
import java.security.NoSuchAlgorithmException;
import java.util.Base64;

public class SignatureVerifier {

    public static boolean verifySignature(String payload, String signature, String appSecret) {
        try {
            SecretKeySpec keySpec = new SecretKeySpec(appSecret.getBytes(StandardCharsets.UTF_8), "HmacSHA1");
            Mac mac = Mac.getInstance("HmacSHA1");
            mac.init(keySpec);
            byte[] result = mac.doFinal(payload.getBytes(StandardCharsets.UTF_8));
            String encodedResult = Base64.getEncoder().encodeToString(result);

            return signature.equals("sha1=" + encodedResult);
        } catch (NoSuchAlgorithmException | InvalidKeyException e) {
            e.printStackTrace(); // Handle error appropriately
            return false;
        }
    }

}
