public class Plane {

    private double a;
    private double b;
    private double c;
    private double d;

    public Plane setFromThreePoints(Vector3 v1, Vector3 v2, Vector3 v3) {
        Vector3 normal = new Vector3();
        Vector3 edge1 = new Vector3();
        Vector3 edge2 = new Vector3();
        edge1.sub(v2, v1);
        edge2.sub(v3, v1);
        normal.cross(edge1, edge2).normalize();
        this.a = normal.x;
        this.b = normal.y;
        this.c = normal.z;
        this.d = -normal.dot(v1);
        return this;
    }

}
