public int findMinimumKey(int[] sortedBlock, int minCursor, int resultCursor, boolean isMatch) {
    int prevKey = Integer.MAX_VALUE;
    int minKey = Integer.MIN_VALUE;

    for (int i = sortedBlock.length - 1; i >= 0; i--) {
        int currKey = sortedBlock[i];

        if (currKey < prevKey) {
            prevKey = currKey;
        }

        if (isMatch && currKey == resultCursor) {
            isMatch = false;
            minKey = prevKey;
        }

        if (minKey != Integer.MIN_VALUE && currKey < resultCursor && currKey > minCursor) {
            return currKey;
        }
    }
    return Integer.MIN_VALUE;
}
