public String compressIPv6(String address) {
    String[] groups = address.split(":");
    int firstIndex = -1;
    int lastIndex = -1;
    int maxZeroCount = 0;
    int zeroCount = 0;
    for (int i = 0; i < groups.length; i++) {
        if (groups[i].isEmpty()) {
            if (firstIndex == -1) {
                firstIndex = i;
            }
            zeroCount++;
            if (zeroCount > maxZeroCount) {
                maxZeroCount = zeroCount;
                lastIndex = i;
            }
        } else {
            zeroCount = 0;
        }
    }
    if (maxZeroCount > 1) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < groups.length; i++) {
            if (i == firstIndex) {
                sb.append("::");
                i = lastIndex;
            } else {
                sb.append(groups[i]);
                if (i < groups.length - 1) {
                    sb.append(":");
                }
            }
        }
        return sb.toString();
    } else {
        return address;
    }
}
