public boolean matchPattern(String pattern, String path) {
    String[] patternParts = pattern.split("/");

    if (patternParts.length == 0) {
        return path.equals(pattern);
    }

    String[] pathParts = path.split("/");
    int patternIndex = 0;
    int pathIndex = 0;

    while (patternIndex < patternParts.length && pathIndex < pathParts.length) {
        String patternPart = patternParts[patternIndex];
        String pathPart = pathParts[pathIndex];

        if (patternPart.equals("*")) {
            patternIndex++;
            if (patternIndex == patternParts.length) {
                return true;
            }

            String nextPatternPart = patternParts[patternIndex];
            while (pathIndex < pathParts.length) {
                pathPart = pathParts[pathIndex];
                if (pathPart.equals(nextPatternPart)) {
                    pathIndex++;
                    break;
                }
                pathIndex++;
            }
            continue;
        }
        if (!patternPart.equals(pathPart)) {
            return false;
        }
        patternIndex++;
        pathIndex++;
    }

    return patternIndex == patternParts.length && pathIndex == pathParts.length;
}
