public void mapPropertiesToConditionalElements(FunctionInputDef inputDef) {
    List<ConditionalElement> conditionalElements = inputDef.getConditionalElements(); 
    List<Property> properties = inputDef.getProperties();

    for (Property property : properties) {
        String propertyName = property.getName();
        List<ConditionalElement> referencingConditionalElements = new ArrayList<>();
        for (ConditionalElement conditionalElement : conditionalElements) {
            if (conditionalElement.getParams().contains(propertyName)) {
                referencingConditionalElements.add(conditionalElement);
            }
        }
        property.setReferencingConditionalElements(referencingConditionalElements);
    }
}
