public Object getCachedProperty(ManagedObjectReference mor, String propName) {
  try {
    PropertySpec propertySpec = new PropertySpec();
    propertySpec.setAll(false);
    propertySpec.setType(mor.getType());
    propertySpec.getPathSet().add(propName);

    ObjectSpec objectSpec = new ObjectSpec();
    objectSpec.setObj(mor);

    PropertyFilterSpec propertyFilterSpec = new PropertyFilterSpec();
    propertyFilterSpec.getPropSet().add(propertySpec);
    propertyFilterSpec.getObjectSet().add(objectSpec);

    List<PropertyFilterSpec> listpfs = new ArrayList<PropertyFilterSpec>(1);
    listpfs.add(propertyFilterSpec);

    List<ObjectContent> listobjcont = retrievePropertiesAllObjects(listpfs);

    Object propertyValue = null;
    if (listobjcont != null) {
      for (ObjectContent oc : listobjcont) {
        List<DynamicProperty> listDynamicProps = oc.getPropSet();
        if (listDynamicProps != null) {
          for (DynamicProperty t : listDynamicProps) {
            if (t.getName().equals(propName)) {
              propertyValue = t.getVal();
              break;
            }
          }
        }
      }
    }
    if (propertyValue instanceof ManagedObjectReference) {
      return MorUtil.createExactManagedEntity((ManagedObjectReference) propertyValue, si.getMOR());
    } else {
      return propertyValue;
    }
  } catch (Exception ex) {
    ex.printStackTrace();
    return null;
  }
}
