public static String createScoreSQLFragment(List<String> searchFields) throws Exception {
    // declaring variables
    StringBuilder sqlFragmentBuilder = new StringBuilder();
    int fieldCount = searchFields.size();

    // building the SQL fragment for single field search
    String singleFieldSearch = "coalesce(nullif(position(lower(?) IN lower(X)), 0), 9999)";

    // building the SQL fragment for multiple fields search
    String multipleFieldsSearch = "least(coalesce(nullif(position(lower(?) IN lower(X)), 0), 9999),";
    for(int i = 1; i < fieldCount; i++) {
        multipleFieldsSearch += "coalesce(nullif(position(lower(?) IN lower(X)), 0), 9999),";
    }
    if(fieldCount > 1) {
        multipleFieldsSearch = multipleFieldsSearch.substring(0, multipleFieldsSearch.length() - 1);
        multipleFieldsSearch += ")";
    }

    // determining which SQL fragment to use based on the number of search fields
    if(fieldCount == 1) {
        sqlFragmentBuilder.append(singleFieldSearch);
    } else if(fieldCount > 1) {
        sqlFragmentBuilder.append(multipleFieldsSearch);
    } else {
        throw new Exception("At least one search field is required");
    }

    // building the final SQL fragment
    sqlFragmentBuilder.append(" as SCORE");
    return sqlFragmentBuilder.toString();
}
