public ConfigParser getParser(String name) throws ConfigException {
   int lastDotIndex = name.lastIndexOf(".");
   if (lastDotIndex == -1) {
       throw new ConfigException("File name does not have a dot");
   }

   String suffix = name.substring(lastDotIndex + 1);

   switch(suffix) {
       case "properties":
           return new PropertiesConfigParser();
       case "yaml":
           return new YamlConfigParser();
       case "json":
           return new JsonConfigParser();
       default:
           throw new ConfigException("Unknown file suffix: " + suffix);
   }
}
