public void removeAllEntries(BonsaiTree bonsaiTree) {
    Page currentPage = bonsaiTree.getRootPage();
    while (currentPage != null) {
        if (currentPage.isLeaf()) {
            currentPage.deleteAllEntries();
            bonsaiTree.addPageToFreelist(currentPage);
            currentPage = null;
        } else {
            Page nextPage = ((InternalPage) currentPage).getLeftmostPage();
            bonsaiTree.addPageToFreelist(currentPage);
            currentPage = nextPage;
        }
    }
}
