import java.util.Base64;

public static String encodeBytes(int howMany, byte[] buffer) {
    int length = howMany;
    if (length > buffer.length) {
        length = buffer.length;
    }

    int numTriples = length / 3;
    int remainder = length % 3;

    byte[] encodedBytes = new byte[numTriples * 4 + ((remainder == 0) ? 0 : 4)];

    int srcIndex = 0;
    int tgtIndex = 0;
    for (int i = 0; i < numTriples; i++) {
        byte b1 = buffer[srcIndex++];
        byte b2 = buffer[srcIndex++];
        byte b3 = buffer[srcIndex++];

        byte b4 = (byte) (b1 >> 2);
        byte b5 = (byte) (((b1 & 0x3) << 4) | ((b2 & 0xF0) >> 4));
        byte b6 = (byte) (((b2 & 0xF) << 2) | ((b3 & 0xC0) >> 6));
        byte b7 = (byte) (b3 & 0x3F);

        encodedBytes[tgtIndex++] = (byte) Base64.getEncoder().encode(b4);
        encodedBytes[tgtIndex++] = (byte) Base64.getEncoder().encode(b5);
        encodedBytes[tgtIndex++] = (byte) Base64.getEncoder().encode(b6);
        encodedBytes[tgtIndex++] = (byte) Base64.getEncoder().encode(b7);
    }

    if (remainder == 1) {
        byte b1 = buffer[srcIndex++];

        byte b2 = 0;
        byte b3 = 0;

        byte b4 = (byte) (b1 >> 2);
        byte b5 = (byte) ((b1 & 0x3) << 4);
        byte b6 = 0;
        byte b7 = 0;

        encodedBytes[tgtIndex++] = (byte) Base64.getEncoder().encode(b4);
        encodedBytes[tgtIndex++] = (byte) Base64.getEncoder().encode(b5);
        encodedBytes[tgtIndex++] = (byte) Base64.getEncoder().encode(b6);
        encodedBytes[tgtIndex++] = (byte) Base64.getEncoder().encode(b7);
    } else if (remainder == 2) {
        byte b1 = buffer[srcIndex++];
        byte b2 = buffer[srcIndex++];

        byte b3 = 0;

        byte b4 = (byte) (b1 >> 2);
        byte b5 = (byte) (((b1 & 0x3) << 4) | ((b2 & 0xF0) >> 4));
        byte b6 = (byte) ((b2 & 0xF) << 2);
        byte b7 = 0;

        encodedBytes[tgtIndex++] = (byte) Base64.getEncoder().encode(b4);
        encodedBytes[tgtIndex++] = (byte) Base64.getEncoder().encode(b5);
        encodedBytes[tgtIndex++] = (byte) Base64.getEncoder().encode(b6);
        encodedBytes[tgtIndex++] = (byte) Base64.getEncoder().encode(b7);
    }

    return new String(encodedBytes);
}
