public List<Double> determinePreferenceVector(Relation relation, List<Integer> neighborIDs, StringBuffer msg) {
    List<Double> preferenceVector = new ArrayList<Double>();
    for(int i=0; i<neighborIDs.size(); i++) {
        double preferenceValue = 0.0;
        for(int j=0; j<relation.getSize(); j++) {
            Object object = relation.getObject(j);
            int neighborID = neighborIDs.get(i);
            double similarity = relation.getSimilarity(object, neighborID);
            preferenceValue += similarity;
        }
        preferenceVector.add(preferenceValue);
    }
    return preferenceVector;
}
