public void retainWithinCurrentCover(List<Candidate> candidates, double fmax, Set<Neighbor> collect) {
    Iterator<Candidate> iterator = candidates.iterator();
    while (iterator.hasNext()) {
        Candidate candidate = iterator.next();
        if (candidate.getDist() <= fmax) {
            collect.add(new Neighbor(candidate.getId(), candidate.getDist()));
        } else {
            iterator.remove();
        }
    }
}
