public void putData(String keyStr, Object value) {
  String[] keys = keyStr.split("\\.");  // split the keys by '.'

  Object temp = this.data;  // start at the root of the data tree
  int i = 0;
  for (; i < keys.length - 1; i++) {  // iterate over keys except the last one
    String key = keys[i];

    if (temp instanceof Map) {  // if temp is a Map
      @SuppressWarnings("unchecked")  // this cast cannot be checked
      Map<String, Object> map = (Map<String, Object>) temp;

      if (!map.containsKey(key)) {  // if the key is not yet in the map, create an empty map
        map.put(key, new HashMap<String, Object>());
      }

      temp = map.get(key);  // go to the next level of the map
    } else if (temp instanceof List) {  // if temp is a List
      @SuppressWarnings("unchecked")  // this cast cannot be checked
      List<Object> list = (List<Object>) temp;

      int index = Integer.parseInt(key);  // assume the key is an integer

      while (list.size() <= index) {  // if the index is not yet in the list, add null values
        list.add(null);
      }

      if (list.get(index) == null) {  // if the index is not yet in the list, create an empty map
        list.set(index, new HashMap<String, Object>());
      }

      temp = list.get(index);  // go to the next level of the list
    } else {  // if temp is neither a Map nor a List, create a new empty map
      Map<String, Object> map = new HashMap<String, Object>();
      this.data = map;
      temp = map;
    }
  }

  // now temp points to the map or list that should contain the value
  String key = keys[i];
  if (temp instanceof Map) {  // if temp is a Map
    @SuppressWarnings("unchecked")  // this cast cannot be checked
    Map<String, Object> map = (Map<String, Object>) temp;
    map.put(key, value);  // insert the value at the last key in the map
  } else if (temp instanceof List) {  // if temp is a List
    @SuppressWarnings("unchecked")  // this cast cannot be checked
    List<Object> list = (List<Object>) temp;
    int index = Integer.parseInt(key);  // assume the last key is an integer
    while (list.size() <= index) {  // if the last index is not yet in the list, add null values
      list.add(null);
    }
    list.set(index, value);  // insert the value at the last index in the list
  } else {  // if temp is neither a Map nor a List, create a new empty map
    Map<String, Object> map = new HashMap<String, Object>();
    map.put(key, value);
    this.data = map;
  }
}
