import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.Enumeration;
import java.util.List;
import java.util.jar.JarEntry;
import java.util.jar.JarFile;
import java.util.jar.Manifest;

public class JarUtils {

  public static List<String> getAllJars(String... jarNames) throws IOException {
    List<String> result = new ArrayList<>();
    for (String jarName : jarNames) {
      addJars(result, jarName);
    }
    return result;
  }

  private static void addJars(List<String> jarList, String jarName) throws IOException {
    JarFile jarFile = new JarFile(jarName);
    jarList.add(jarName);

    Manifest manifest = jarFile.getManifest();
    if (manifest != null) {
      String classPath = manifest.getMainAttributes().getValue("Class-Path");
      if (classPath != null) {
        String[] classPathEntries = classPath.split(" ");
        for (String entry : classPathEntries) {
          if (entry.endsWith(".jar")) {
            jarList.add(entry);
            addJars(jarList, entry);
          }
        }
      }
    }

    Enumeration<JarEntry> entries = jarFile.entries();
    while (entries.hasMoreElements()) {
      JarEntry entry = entries.nextElement();
      if (entry.getName().endsWith(".jar")) {
        InputStream inputStream = jarFile.getInputStream(entry);
        String embeddedJar = entry.getName();
        jarList.add(embeddedJar);
        addJars(jarList, embeddedJar);
      }
    }
  }
}
