public interface CallbackFunction {
  void execute();
}

public void repeatedlyCallFunctionWhileConditionMet(CallbackFunction callback, BooleanSupplier condition) throws Exception {
  boolean shouldContinue = true;

  while (shouldContinue) {
    try {
        // Call the required function
        // ...

        // Check the condition after each called function
        shouldContinue = condition.getAsBoolean();

    } catch (Exception e) {
        // Handle the error
        shouldContinue = false;
        throw e;
    }
  }

  // Call the callback function when stopped
  callback.execute();
}
