public enum Os {
    WINDOWS, MAC, LINUX, ANDROID, IOS, UNKNOWN
}

public Os parseUserAgent(String agentString) {
    if (agentString.contains("Windows")) {
        return Os.WINDOWS;
    } else if (agentString.contains("Macintosh") || agentString.contains("Mac OS X")) {
        return Os.MAC;
    } else if (agentString.contains("Android")) {
        return Os.ANDROID;
    } else if (agentString.contains("iPhone") || agentString.contains("iPad") || agentString.contains("iPod")) {
        return Os.IOS;
    } else if (agentString.contains("Linux")) {
        return Os.LINUX;
    } else {
        return Os.UNKNOWN;
    }
}
