public double[][] computeWeightMatrix(int bpp) {
    double[][] weightMatrix = new double[bpp * 3][bpp * 3];

    for(int i = 0; i < bpp; i++) {
        for(int j = 0; j < bpp; j++) {
            int x = bpp * 0 + i;
            int y = bpp * 0 + j;
            weightMatrix[x][y] = 1;
            weightMatrix[x + bpp][y + bpp] = 1;
            weightMatrix[x + bpp * 2][y + bpp * 2] = 1;
        }
    }

    return weightMatrix;
}
