public boolean columnExists(String table, String name) {
    try {
        Connection conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/mydatabase", "root", "password"); // replace with your database details
        Statement stmt = conn.createStatement();
        ResultSet rs = stmt.executeQuery("SELECT * FROM " + table + " LIMIT 0"); // select zero rows to just get column info
        ResultSetMetaData metadata = rs.getMetaData();
        int columnCount = metadata.getColumnCount();
        for (int i = 1; i <= columnCount; i++) {
            if (metadata.getColumnName(i).equals(name)) {
                return true;
            }
        }
        return false;
    } catch (SQLException e) {
        System.out.println("Error: " + e.getMessage());
        return false;
    }
}
