public static String removeFirstSelect(String query) {
    // Find the index of the first occurrence of 'select'
    int index = query.toLowerCase().indexOf("select");

    // If 'select' is found, remove it (with leading spaces)
    if (index != -1) {
        String leadingSpaces = query.substring(0, index);
        query = query.substring(index + 6); // Skip 6 characters for 'select'
        query = leadingSpaces.trim() + query;
    }

    return query;
}
