public class AuthleteAPI {

    public static void main(String[] args) throws IOException {
        String authleteEndpoint = "https://api.authlete.com/api/backchannel/authentication/issue";
        URL url = new URL(authleteEndpoint);

        HttpsURLConnection connection = (HttpsURLConnection) url.openConnection();
        connection.setRequestMethod("POST");
        connection.setRequestProperty("Content-Type", "application/json");
        connection.setRequestProperty("Accept", "application/json");

        String requestBody = "{\"backchannelAuthenticationRequestId\": \"request_id_here\"}";

        connection.setDoOutput(true);
        OutputStream outStream = connection.getOutputStream();
        outStream.write(requestBody.getBytes());
        outStream.flush();

        BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()));
        String line;
        StringBuilder response = new StringBuilder();
        while ((line = reader.readLine()) != null) {
            response.append(line);
        }
        reader.close();

        String responseBody = response.toString();
        System.out.println(responseBody);
    }
}
