public void addColumnToLastGroup(int columnIndex) {
    int lastGroupIndex = -1;
    for (int i = 0; i < columnGroups.size(); i++) {
        if (columnGroups.get(i).size() > 0) {
            lastGroupIndex = i;
        }
    }
    if (lastGroupIndex < 0) { // If no groups exist
        ArrayList<Integer> newGroup = new ArrayList<Integer>();
        newGroup.add(columnIndex);
        columnGroups.add(newGroup);
    } else {
        columnGroups.get(lastGroupIndex).add(columnIndex);
    }
}
