public Evaluation evaluateDistributed(INDArray data, List<String> labelsList) {
    int batchSize = 32;
    Evaluation evaluation = new Evaluation(labelsList);
    List<String> subLabels = labelsList.subList(0, batchSize);
    int nIterations = data.rows() / batchSize;
    for (int i = 0; i < nIterations; i++) {
        int fromIdx = i * batchSize;
        int toIdx = fromIdx + batchSize;
        if (toIdx > data.rows()) {
            toIdx = data.rows();
            subLabels = labelsList.subList(fromIdx, toIdx);
        }
        INDArray inputData = data.get(NDArrayIndex.interval(fromIdx, toIdx), NDArrayIndex.all(), NDArrayIndex.all(), NDArrayIndex.all());
        INDArray output = model.output(inputData);
        evaluation.eval(subLabels, output, inputData);
    }
    return evaluation;
}
