import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.NoSuchElementException;

public class MyClass {

    public static <T extends Comparable<? super T>> List<T> findMinimums(Iterable<T> elements) {
        List<T> minimums = new ArrayList<T>();
        T minimum = null;
        for (T element : elements) {
            if (minimum == null || element.compareTo(minimum) < 0) {
                minimum = element;
                minimums.clear();
            }
            if (element.compareTo(minimum) == 0) {
                minimums.add(element);
            }
        }
        if (minimum == null) {
            throw new NoSuchElementException("Empty Iterable");
        }
        return minimums;
    }
}
