public void modifyPropositionSet(Set<String> propositionSet, double activationDegree, ImplicationOperator implication) {
    for (String proposition : propositionSet) {
        if (implication == ImplicationOperator.MIN) {
            // compute the minimum between the current truth value and the activation degree
            double newTruthValue = Math.min(propositionSet.get(proposition), activationDegree);
            propositionSet.put(proposition, newTruthValue);
        } else if (implication == ImplicationOperator.PROD) {
            // compute the product of the current truth value and the activation degree
            double newTruthValue = propositionSet.get(proposition) * activationDegree;
            propositionSet.put(proposition, newTruthValue);
        } else {
            // handle other implication operators, if needed
            throw new IllegalArgumentException("Unknown implication operator: " + implication);
        }
    }
}
