public Object traverseXMLElement(Element current, Object instance) throws SlickXMLException {
    // check if instance is null
    if (instance == null) {
        // create new instance based on current element
        instance = createObjectFromElement(current);
    }
    // loop through child elements
    for (Element child : current.getChildren()) {
        // create object from child element
        Object childObject = createObjectFromElement(child);
        // add child object to parent instance
        addChildObjectToInstance(childObject, instance);
        // recursively traverse child element
        traverseXMLElement(child, childObject);
    }
    // return instance
    return instance;
}

