public static float computeCatmullRomSpline(float x, int numKnots, float[] xknots, float[][] yknots) {
    int startIndex = 0;
    int endIndex = numKnots - 1;
    int midIndex = (startIndex + endIndex) / 2;

    while (startIndex <= endIndex) {
        if (x < xknots[midIndex]) {
            endIndex = midIndex - 1;
        } else if (x > xknots[midIndex]) {
            startIndex = midIndex + 1;
        } else {
            return yknots[midIndex][0];
        }
        midIndex = (startIndex + endIndex) / 2;
    }

    int index0 = midIndex - 1;
    int index1 = midIndex;
    int index2 = midIndex + 1;
    int index3 = midIndex + 2;

    float t = (x - xknots[index1]) / (xknots[index2] - xknots[index1]);
    float t2 = t * t;
    float t3 = t2 * t;

    return 0.5f * ((2.0f * yknots[index1][0]) +
                   (-yknots[index0][0] + yknots[index2][0]) * t +
                   (2.0f * yknots[index0][0] - 5.0f * yknots[index1][0] +
                    4.0f * yknots[index2][0] - yknots[index3][0]) * t2 +
                   (-yknots[index0][0] + 3.0f * yknots[index1][0] -
                    3.0f * yknots[index2][0] + yknots[index3][0]) * t3);
}
