public String getConfusionMatrixAsString(int[][] confusionMatrix) {
    StringBuilder sb = new StringBuilder();
    sb.append("\tPredicted\n")
      .append("Actual\t");

    // Append the predicted column headers
    for (int i = 0; i < confusionMatrix.length; i++) {
        sb.append(i).append("\t");
    }

    sb.append("\n");

    // Append the confusion matrix values
    for (int i = 0; i < confusionMatrix.length; i++) {
        sb.append(i).append("\t");
        for (int j = 0; j < confusionMatrix[i].length; j++) {
            sb.append(confusionMatrix[i][j]).append("\t");
        }
        sb.append("\n");
    }

    return sb.toString();
}
