public void assertSelectValuesEqual(String[] expectedValues) {
  // Check if the element is present and is a select
  WebElement element = driver.findElement(By.tagName("select"));
  if (element.isDisplayed() && element.isEnabled()) {
    // Get the values of the select options
    List<WebElement> options = element.findElements(By.tagName("option"));
    List<String> actualValues = new ArrayList<String>();
    for (WebElement option : options) {
      actualValues.add(option.getAttribute("value"));
    }
    // Assert that the actual values equal the expected values
    Assert.assertEquals(actualValues, Arrays.asList(expectedValues));
  } else {
    // Log and record failure due to element not being present or not a select
    System.out.println("Failure: Element not present or not a select");
    // Take a screenshot for traceability and debugging support
    File screenshot = ((TakesScreenshot) driver).getScreenshotAs(OutputType.FILE);
    try {
      FileUtils.copyFile(screenshot, new File("test-output/screenshots/select-failure.png"));
    } catch (IOException e) {
      e.printStackTrace();
    }
    // Throw an exception to mark the test as failed
    throw new AssertionError("Element not present or not a select");
  }
}
