public boolean dispatchTokens(int numOfTokens) {
    boolean isQueued = false;
    synchronized(queue) {
        if(queue.size() < MAX_QUEUE_SIZE) {
            queue.addAll(Collections.nCopies(numOfTokens, DEFAULT_TOKEN));
            isQueued = true;
        }
    }
    return isQueued;
}
