public static JSONArray copyJSONArray(JSONArray src, boolean deep) {
    JSONArray copy = new JSONArray();
    if (deep) {
        for (int i = 0; i < src.length(); i++) {
            Object obj = src.get(i);
            if (obj instanceof JSONArray) {
                copy.put(copyJSONArray((JSONArray) obj, deep));
            } else if (obj instanceof JSONObject) {
                copy.put(copyJSONObject((JSONObject) obj, deep));
            } else {
                copy.put(obj);
            }
        }
    } else {
        for (int i = 0; i < src.length(); i++) {
            copy.put(src.get(i));
        }
    }
    return copy;
}

private static JSONObject copyJSONObject(JSONObject src, boolean deep) {
    JSONObject copy = new JSONObject();
    Iterator<String> it = src.keys();
    while (it.hasNext()) {
        String key = it.next();
        Object obj = src.opt(key);
        if (obj instanceof JSONArray) {
            copy.put(key, copyJSONArray((JSONArray) obj, deep));
        } else if (obj instanceof JSONObject) {
            copy.put(key, copyJSONObject((JSONObject) obj, deep));
        } else {
            copy.put(key, obj);
        }
    }
    return copy;
}
