public View getViewByName(String name) {
    View view = findViewById(name);
    if (view != null) {
        return view;
    }
    return findViewTraversal(name, (ViewGroup) getWindow().getDecorView());
}

private View findViewTraversal(String name, ViewGroup viewGroup) {
    final int count = viewGroup.getChildCount();
    for (int i = 0; i < count; i++) {
        final View child = viewGroup.getChildAt(i);
        if (child instanceof ViewGroup) {
            View view = findViewTraversal(name, (ViewGroup) child);
            if (view != null) {
                return view;
            }
        } else if (child instanceof View) {
            if (name.equals(getViewName(child))) {
                return child;
            }
        }
    }
    return null;
}

private String getViewName(View view) {
    if (view.getId() == View.NO_ID) {
        return null;
    }
    return getResourceEntryName(view.getId());
}
