public static double[] smoothWithGaussianBlur(double[] values, int kernelRadius) throws Exception {
    if (values == null || values.length == 0) {
        throw new Exception("The input array cannot be null or empty.");
    }
    if (kernelRadius < 1) {
        throw new Exception("The kernel radius must be greater than or equal to 1.");
    }
    int kernelSize = 2 * kernelRadius + 1;
    double[] kernel = new double[kernelSize];
    double sigma = kernelRadius / 3.0;
    double normalizer = 0.0;
    for (int i = 0; i < kernelSize; i++) {
        kernel[i] = Math.exp(-0.5 * Math.pow((i - kernelRadius) / sigma, 2));
        normalizer += kernel[i];
    }
    for (int i = 0; i < kernelSize; i++) {
        kernel[i] /= normalizer;
    }
    int lastIndex = values.length - 1;
    double[] smoothedValues = new double[values.length];
    for (int i = 0; i < values.length; i++) {
        double sum = 0.0;
        for (int j = -kernelRadius; j <= kernelRadius; j++) {
            int index = i + j;
            if (index < 0) {
                index = -index;
            } else if (index > lastIndex) {
                index = lastIndex - (index - lastIndex);
            }
            sum += values[index] * kernel[j + kernelRadius];
        }
        smoothedValues[i] = sum;
    }
    return smoothedValues;
}
