public static int powModFastRisky(int base, int exponent, int modulus) {
    if (modulus <= 0 || exponent == Integer.MIN_VALUE) throw new ArithmeticException("Invalid inputs.");
    if (exponent < 0) {
        base = invertMod(base, modulus);
        exponent = -exponent;
    }
    int result = 1;
    for (int i = Integer.highestOneBit(exponent); i != 0; i >>>= 1) {
        if ((exponent & i) != 0) {
            // result = (result * base) % modulus;
            int tmp = result * base - modulus * ((result * base) / modulus);
            result = tmp < 0 ? tmp + modulus : tmp;
        }
        // base = (base * base) % modulus
        int tmp = base * base - modulus * ((base * base) / modulus);
        base = tmp < 0 ? tmp + modulus : tmp;
    }
    return result;
}

private static int invertMod(int x, int m) {
    if (m <= 0) throw new ArithmeticException("Modulus must be positive");
    int y = x % m;
    if (y < 0) y += m;
    if (y <= 1) return y;
    int z = ((1 - m / y) * invertMod(m % y, y)) % m;
    return z < 0 ? z + m : z;
}
