public Object execute(Object value) throws SuperCsvCellProcessorException, SuperCsvConstraintViolationException {
    if (value == null) { // throw exception if value is null
        throw new SuperCsvCellProcessorException("Value cannot be null");
    }

    String stringValue = value.toString(); // convert object value to string
    String regexPattern = "^[A-Za-z0-9]+$"; // define regular expression pattern

    if (!stringValue.matches(regexPattern)) { // throw exception if value doesn't match the regular expression
        throw new SuperCsvConstraintViolationException("Value doesn't match the regular expression pattern.");
    }

    return value; // return the original value if it passes both checks
}
