public static String determinePhrase(String a, String b){
    int aLength = a.length();
    int bLength = b.length();
    int aTokenCount = a.split(" ").length;
    int bTokenCount = b.split(" ").length;

    if(aLength == bTokenCount && bLength == aTokenCount){
        // a and b are transposed
        if(aTokenCount == bTokenCount){
            // Choose the phrase with most characters
            return (aLength >= bLength) ? a : b;
        } else {
            // Choose the phrase with most tokens
            return (aTokenCount >= bTokenCount) ? a : b;
        }
    } else {
        // a and b are not transposed
        return (aLength >= bLength) ? a : b;
    }
}
