public BoundingBox scaleBoundingBox(BoundingBox bbox, double factor) {
    double newWidth = bbox.getWidth() * factor;
    double newHeight = bbox.getHeight() * factor;
    double newMinX = bbox.getCenterX() - (newWidth / 2);
    double newMinY = bbox.getCenterY() - (newHeight / 2);
    return new BoundingBox(newMinX, newMinY, newWidth, newHeight);
}
