public BufferedImage getFrameImage(int width, int height, BufferedImage image) {

    // get the currently active frame design
    FrameDesign activeDesign = getActiveFrameDesign();

    // create a new BufferedImage with the given width, height and image type
    BufferedImage frameImage = new BufferedImage(width, height, image.getType());

    // get the graphics context of the frame image
    Graphics2D g2d = frameImage.createGraphics();

    // draw the frame design onto the frame image
    activeDesign.drawFrame(g2d, 0, 0, width, height);

    // dispose the graphics context
    g2d.dispose();

    // return the frame image with the added frame in the currently active frame design
    return frameImage;
}
