public static <K, V> Flux<K> iterateKeys(RedisCacheCommands commands, ScanArgs scanArgs) {
    return Flux.<K>create(fluxSink -> {
        ScanCursor scanCursor = null;
        do {
            if (scanCursor == null) {
                scanCursor = ScanCursor.INITIAL;
            }
            else {
                scanCursor = commands.scan(scanCursor, scanArgs);
            }

            List<K> keys = commands.keys(scanArgs.getPattern().orElse("*"));

            for (K key : keys) {
                fluxSink.next(key);
            }
        } while (!scanCursor.isFinished());

        fluxSink.complete();
    });
}
