import java.time.DayOfWeek;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;

public static List<LocalDate> constructDayFilter(List<DayOfWeek> days, boolean weeksInYear) {

    List<LocalDate> filter = new ArrayList<>();
    LocalDate today = LocalDate.now();

    for (DayOfWeek day : days) {
        LocalDate date = today.with(day);
        int weekNum = weeksInYear ? date.get(IsoFields.WEEK_OF_WEEK_BASED_YEAR) : date.get(IsoFields.WEEK_OF_MONTH);
        LocalDate weekStartDate = weeksInYear ? LocalDate.of(date.getYear(), 1, 1).with(IsoFields.WEEK_OF_WEEK_BASED_YEAR, weekNum) :
                LocalDate.of(date.getYear(), date.getMonth(), 1).with(IsoFields.WEEK_OF_MONTH, weekNum);
        filter.add(weekStartDate.with(day));
    }
    return filter;
}
