public static int modInverse(int base, int k) {
    int odd = 1, even = 0, currBase = base;
    while (k > 1) {
        even += odd * -(currBase / (1 << (k - 1)));
        currBase = currBase % (1 << (k - 1));
        k--;
        if (k % 2 == 1) {
            odd += even * -(currBase / (1 << (k - 1)));
            currBase = (currBase * base + 1) % (1 << k);
        }
    }
    return odd;
}
