public static <T> Object toPrimitiveArray(T[] src, int srcPos, int len) {
    if (src == null) {
        throw new NullPointerException("Source array cannot be null");
    }

    if (srcPos < 0 || len < 0 || len > src.length - srcPos) {
        throw new IllegalArgumentException("Invalid range or length");
    }

    Class<?> clazz = src.getClass().getComponentType();
    Object dest = Array.newInstance(clazz, len);

    if (Boolean.class.equals(clazz)) {
        for (int i = 0; i < len; i++) {
            Array.setBoolean(dest, i, (Boolean) src[srcPos + i]);
        }
    } else if (Character.class.equals(clazz)) {
        for (int i = 0; i < len; i++) {
            Array.setChar(dest, i, (Character) src[srcPos + i]);
        }
    } else if (Number.class.isAssignableFrom(clazz)) {
        for (int i = 0; i < len; i++) {
            Number value = (Number) src[srcPos + i];
            if (Byte.class.equals(clazz)) {
                Array.setByte(dest, i, value.byteValue());
            } else if (Short.class.equals(clazz)) {
                Array.setShort(dest, i, value.shortValue());
            } else if (Integer.class.equals(clazz)) {
                Array.setInt(dest, i, value.intValue());
            } else if (Long.class.equals(clazz)) {
                Array.setLong(dest, i, value.longValue());
            } else if (Float.class.equals(clazz)) {
                Array.setFloat(dest, i, value.floatValue());
            } else if (Double.class.equals(clazz)) {
                Array.setDouble(dest, i, value.doubleValue());
            }
        }
    } else {
        throw new IllegalArgumentException("Invalid type: " + clazz.getName());
    }

    return dest;
}
