public static String getCaller(int level) {
    StackTraceElement[] stackTrace = Thread.currentThread().getStackTrace();

    // Index 0 is always the getStackTrace() method, index 1 is the current method
    int callerIndex = level + 1;
    if (callerIndex >= stackTrace.length) {
        throw new IndexOutOfBoundsException("Invalid stack trace level: " + level);
    }

    String callerClass = stackTrace[callerIndex].getClassName();
    String callerMethod = stackTrace[callerIndex].getMethodName();

    return "Caller class: " + callerClass + ", Caller method: " + callerMethod;
}
