public RedisInstance parseRoleOutput(String roleOutput) {
    String[] roleArray = roleOutput.split("\\r?\\n");
    String[] masterInfo = roleArray[1].split(" ");
    String masterHost = masterInfo[1].split(":")[0];
    int masterPort = Integer.parseInt(masterInfo[1].split(":")[1]);
    List<String[]> slaveInfos = new ArrayList<String[]>();
    for (int i = 3; i < roleArray.length; i++) {
        String[] slaveInfo = roleArray[i].split(" ");
        slaveInfos.add(slaveInfo);
    }
    return new RedisInstance(masterHost, masterPort, slaveInfos);
}
