public void copyS3ObjectAsMultipleCopyPartRequests(AmazonS3 s3, String sourceBucket, String sourceKey, String destinationBucket, String destinationKey, long objectSize, int partSize) throws Exception {
   long bytePosition = 0;
   List<PartETag> partETags = new ArrayList<>();
   for (int i = 1; bytePosition < objectSize; i++) {
       CopyPartRequest copyPartRequest = new CopyPartRequest()
               .withSourceBucketName(sourceBucket)
               .withSourceKey(sourceKey)
               .withDestinationBucketName(destinationBucket)
               .withDestinationKey(destinationKey)
               .withUploadId(uploadId)
               .withPartNumber(i)
               .withFirstByte(bytePosition)
               .withLastByte(Math.min(bytePosition + partSize, objectSize) - 1);
       partETags.add(s3.copyPart(copyPartRequest).getPartETag());
       bytePosition += partSize;
   }
   // complete the multipart request
   CompleteMultipartUploadRequest completeRequest = new
       CompleteMultipartUploadRequest(destinationBucket, destinationKey, uploadId, partETags);
   s3.completeMultipartUpload(completeRequest);
}
