public void addToTail(Object obj) {
  if(size == capacity) {
    head = head.next;
    size--;
  }
  Node temp = new Node(obj);
  if(tail == null) {
    tail = temp;
    head = temp;
  } else {
    tail.next = temp;
    tail = temp;
  }
  size++;
}
