public static boolean validateClassDefiningCalls(String code) {
    int count = 0;
    int startIndex = 0;
    int endIndex = 0;
    while ((startIndex = code.indexOf("class", endIndex)) != -1) {
        endIndex = code.indexOf("{", startIndex);
        if (endIndex == -1) {
            return false;
        }
        count++;
    }
    return count > 0 && code.lastIndexOf("}", endIndex) == code.length() - 1;
}
