public static Node appendLineSeparator(Node parentNode) {
    if (parentNode == null) {
        return null;
    }

    if (parentNode.getLastChild() instanceof Text) {
        String lastChildText = ((Text) parentNode.getLastChild()).getTextContent();
        if (lastChildText.trim().length() > 0) {
            parentNode.appendChild(parentNode.getOwnerDocument().createTextNode(System.lineSeparator()));
        }
    }

    return parentNode;
}
