import io.reactivex.Observable;
import java.util.List;
import java.util.concurrent.Callable;

public class TaskGroupInvoker {

  public Observable<Object> invokeTasks(InvocationContext context, List<TaskGroupEntry> entries) {

    return Observable.fromIterable(entries)
        .flatMap(taskEntry -> {
            Callable<Object> task = taskEntry.getTask();
            boolean executeOnObserve = taskEntry.shouldExecuteOnObserve();

            return Observable.fromCallable(() -> {
              InvocationContext currentContext = taskEntry.getContext()
                  .orElse(context);
              return task.call(currentContext);
            })
            .subscribeOn(executeOnObserve ? Schedulers.trampoline() : TaskGroupEntry.getDefaultScheduler());
        })
        .toList()
        .map(resultList -> resultList.toArray(new Object[resultList.size()]))
        .toObservable();
  }
}
