public static Snapshot getLastSnapshotWithCommitIdBeforeTimePoint(List<Snapshot> snapshots, LocalDateTime timePoint) {
    Snapshot lastSnapshot = null;
    for (Snapshot snapshot : snapshots) {
        if (snapshot.getCommitId().compareTo(timePoint) <= 0) {
            if (lastSnapshot == null || lastSnapshot.getCommitId().compareTo(snapshot.getCommitId()) < 0) {
                lastSnapshot = snapshot;
            }
        }
    }
    return lastSnapshot;
}
