public static Document downgradeToV1_2_5(Document doc) {
    Element rootNode = doc.getDocumentElement();

    // Change version attribute of the xml node
    rootNode.setAttribute("xmlns", "http://www.openimmo.de");
    rootNode.setAttribute("xmlns:xsi", "http://www.w3.org/2001/XMLSchema-instance");
    rootNode.setAttribute("xsi:schemaLocation", "http://www.openimmo.de openimmo.xsd");
    rootNode.setAttribute("openimmo_version", "1.2.5");

    // Remove additional elements that are not present in 1.2.5
    NodeList nodes = rootNode.getElementsByTagName("uebertragung");
    if (nodes.getLength() > 0) {
        rootNode.removeChild(nodes.item(0));
    }

    nodes = rootNode.getElementsByTagName("weitere_adresse");
    for (int i = 0; i < nodes.getLength(); i++) {
        rootNode.removeChild(nodes.item(i));
    }

    return doc;
}
