public static String[] extractTagsFromDocComment(String docComment) {
    String[] sentences = docComment.split("\\.");
    String firstSentence = sentences[0].trim();
    List<String> tags = new ArrayList<>();

    // Extracting tags from the first sentence by looking for words
    // starting with @ symbol
    for (String word : firstSentence.split("\\s+")) {
        if (word.startsWith("@")) {
            tags.add(word);
        }
    }

    // Converting the list of tags to an array
    String[] tagsArray = new String[tags.size()];
    tags.toArray(tagsArray);

    return tagsArray;
}
