public String extractEncodingFromContentType(String contentType, String defaultEncoding) {
    String encoding = extractEncoding(contentType);
    return encoding == null ? defaultEncoding == null ? JoddCore.encoding : defaultEncoding : encoding;
}

private String extractEncoding(String contentType) {
    if (contentType == null) {
        return null;
    }
    int i = contentType.indexOf("charset=");
    if (i == -1) {
        return null;
    }
    String encoding = contentType.substring(i + 8).trim();
    if (encoding.startsWith("\"")) {
        i = encoding.indexOf('\"', 1);
        if (i != -1) {
            return encoding.substring(1, i);
        }
    } else {
        i = encoding.indexOf(';');
        if (i != -1) {
            return encoding.substring(0, i);
        }
    }
    return encoding;
}
