public void quote(String str, StringBuilder sb) {
    // Quotes the given string and appends to the StringBuilder
    sb.append("\"");
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            sb.append("\\\\");
        } else if (c == '\"') {
            sb.append("\\\"");
        } else {
            sb.append(c);
        }
    }
    sb.append("\"");
}
