public static SimpleTimeZone parseCustomTimeZone(String id) {
    int offsetInMillis;
    try {
        if (id.startsWith("GMT+")) {
            final int hours = Integer.parseInt(id.substring(4, 6));
            final int minutes = parseMinutes(id, 6);
            offsetInMillis = hours * 60 * 60 * 1000 + minutes * 60 * 1000;
        } else if (id.startsWith("GMT-")) {
            final int hours = Integer.parseInt(id.substring(4, 6));
            final int minutes = parseMinutes(id, 6);
            offsetInMillis = -hours * 60 * 60 * 1000 - minutes * 60 * 1000;
        } else if (id.startsWith("GMT")) {
            final int hours = Integer.parseInt(id.substring(3, 5));
            final int minutes = parseMinutes(id, 5);
            offsetInMillis = hours * 60 * 60 * 1000 + minutes * 60 * 1000;
        } else {
            return null;
        }
        final SimpleTimeZone timeZone = new SimpleTimeZone(offsetInMillis, id);
        timeZone.setID(id);
        timeZone.setRawOffset(offsetInMillis);
        return timeZone;
    } catch (NumberFormatException e) {
        return null;
    }
}

private static int parseMinutes(String id, int index) {
    if (id.length() >= index + 2 && id.charAt(index) == ':') {
        return Integer.parseInt(id.substring(index + 1, index + 3));
    } else if (id.length() >= index + 2) {
        return Integer.parseInt(id.substring(index, index + 2));
    } else {
        return 0;
    }
}
