public static INDArray matrixMultiplication(INDArray other, INDArray result) {
    if (result == null || !Arrays.equals(result.shape(), new int[]{this.rows, other.columns()})) {
        result = Nd4j.create(this.rows, other.columns());
    }
    // Check if the matrices can be multiplied
    if (this.columns != other.rows()) {
        throw new IllegalArgumentException("Matrices cannot be multiplied: " + this.columns + " != " + other.rows());
    }
    for (int i = 0; i < this.rows; i++) {
        for (int j = 0; j < other.columns(); j++) {
            double val = 0;
            for (int k = 0; k < this.columns; k++) {
                val += this.getDouble(i, k) * other.getDouble(k, j);
            }
            result.putScalar(new int[]{i, j}, val);
        }
    }
    return result;
}
