@Deprecated
public static byte[] obtainDataForTextField(String text, Charset charset, int length, DBFAlignment alignment) {
    byte[] data = new byte[length];
    byte[] textBytes = text.getBytes(charset);

    if (textBytes.length > length) {
        System.arraycopy(textBytes, 0, data, 0, length);
    } else {
        int paddingLength = length - textBytes.length;
        int paddingLeft = 0;
        int paddingRight = 0;

        switch (alignment) {
            case LEFT:
                paddingRight = paddingLength;
                break;
            case CENTER:
                paddingLeft = paddingLength / 2;
                paddingRight = paddingLength - paddingLeft;
                break;
            case RIGHT:
                paddingLeft = paddingLength;
                break;
        }

        for (int i = 0; i < paddingLeft; i++) {
            data[i] = (byte) 0x20; // padding character
        }

        System.arraycopy(textBytes, 0, data, paddingLeft, textBytes.length);

        for (int i = length - paddingRight; i < length; i++) {
            data[i] = (byte) 0x20; // padding character
        }
    }

    return data;
