import java.util.HashMap;
import java.util.Map;

public class DatabaseStrategyFactory {
    private Map<String, DatabaseStrategy> strategies;

    public DatabaseStrategyFactory() {
        strategies = new HashMap<>();
        // add strategies for each known database product name
        strategies.put("mysql", new MySQLDatabaseStrategy());
        strategies.put("oracle", new OracleDatabaseStrategy());
        // add more strategies as needed
    }

    public DatabaseStrategy getDatabaseStrategy(String productName) {
        // check if there is a strategy for given product name
        DatabaseStrategy strategy = strategies.get(productName.toLowerCase());
        // return the found strategy or the default one
        return strategy == null ? new DefaultDatabaseStrategy() : strategy;
    }
}
