public static int[] generateSolverVector(int[] clause) {
    int[] solverVector = new int[clause.length];
    for (int i = 0; i < clause.length; i++) {
        int literal = clause[i];
        solverVector[i] = (literal > 0) ? literal : -literal;
    }
    return solverVector;
}
