public Api getApiFromCacheOrES(int orgId, int apiId, String version) {
    // Check if the API exists in the cache
    Api api = cache.getApi(orgId, apiId, version);
    if (api != null) {
        return api;
    }

    // If the API doesn't exist in the cache, get it from ES
    api = es.getApi(orgId, apiId, version);
    if (api != null) {
        // Add the API to the cache
        cache.putApi(api);
    }

    return api;
}
