/**
 * Apply scaling to this matrix and store the result into dest.
 *
 * @param factor the scaling factor
 * @param dest   will receive the result
 * @return dest
 */
public Matrix4x3d scale(double factor, Matrix4x3d dest) {
    dest.m00 = m00 * factor;
    dest.m01 = m01 * factor;
    dest.m02 = m02 * factor;
    dest.m10 = m10 * factor;
    dest.m11 = m11 * factor;
    dest.m12 = m12 * factor;
    dest.m20 = m20 * factor;
    dest.m21 = m21 * factor;
    dest.m22 = m22 * factor;
    dest.m30 = m30;
    dest.m31 = m31;
    dest.m32 = m32;
    return dest;
}
