public Map<String, String> getCurrentThreadPoolStatus() {
    Map<String, String> statusMap = new TreeMap<>();
    for(Map.Entry<String, ThreadPoolExecutor> entry : threadPoolMap.entrySet()) {
        String name = entry.getKey();
        ThreadPoolExecutor executor = entry.getValue();
        String status = "Active count: " + executor.getActiveCount() + ", Completed task count: " + executor.getCompletedTaskCount() + ", Queue size: " + executor.getQueue().size();
        statusMap.put(name, status);
    }
    return statusMap;
}
