public static LineString forceDimension(LineString lineString, int dimension) {
    Coordinate[] coords = lineString.getCoordinates();
    for (Coordinate coord : coords) {
        if (coord.dimension != dimension) {
            double[] newCoords = new double[dimension];
            for (int i = 0; i < dimension; i++) {
                if (i < coord.dimension) {
                    newCoords[i] = coord.getOrdinate(i);
                } else {
                    newCoords[i] = Double.NaN;
                }
            }
            coord.setCoordinate(newCoords);
        }
    }
    return new GeometryFactory().createLineString(coords);
}
