public static int findFullSyncStart(int[] arr, int start, int end) {
    int i = start;
    while (i <= end) {
        if (arr[i] == 1) {
            int count = 0;
            while (i <= end && arr[i] == 1) {
                i++;
                count++;
            }
            if (count >= 5 && arr[i] == 0) {
                return i - count;
            }
        } else {
            i++;
        }
    }
    return -1;
}
