public String createSubmissionLink(String submission) {
    if (submission == null || submission.isEmpty()) {
        throw new IllegalArgumentException("Submission cannot be null or empty.");
    }

    Document doc = getDocument();
    Element head = doc.selectFirst("head");
    if (head == null) {
        head = doc.createElement("head");
        doc.prependChild(head);
    }

    Element link = doc.createElement("link");
    link.attr("rel", "submission");
    link.attr("href", submission);
    head.appendChild(link);

    return link.outerHtml();
}

