public void sendFlushRequest(ChannelHandlerContext ctx, ChannelFuture future) {
    Channel channel = ctx.channel();
    ChannelPipeline pipeline = channel.pipeline();
    ChannelHandlerContext closestDownstreamCtx = pipeline.context(channel.pipeline().lastKey());
    while (closestDownstreamCtx != null && closestDownstreamCtx.handler() instanceof ChannelUpstreamHandler) {
        closestDownstreamCtx = pipeline.context(closestDownstreamCtx, channel.pipeline().lastKey());
    }
    if (closestDownstreamCtx != null) {
        ChannelHandlerContext targetCtx = pipeline.context(closestDownstreamCtx.name());
        targetCtx.writeAndFlush(Unpooled.EMPTY_BUFFER, future);
    } else {
        channel.writeAndFlush(Unpooled.EMPTY_BUFFER, future);
    }
}
