public int getNextCodePoint(CharBuffer buffer) {
    int codePoint = buffer.get();
    if (Character.isHighSurrogate((char) codePoint) && buffer.hasRemaining()) {
        char highSurrogate = (char) codePoint;
        char lowSurrogate = buffer.get();
        if (Character.isSurrogatePair(highSurrogate, lowSurrogate)) {
            codePoint = Character.toCodePoint(highSurrogate, lowSurrogate);
        } else {
            buffer.position(buffer.position() - 1);
        }
    }
    return codePoint;
}
