public static long getMostRecentModifiedTimestamp(Collection<?> fileLists) {
    long mostRecentModifiedTimestamp = 0;
    for (Object file : fileLists) {
        long modifiedTimestamp;
        if (file instanceof FileList) {
            modifiedTimestamp = ((FileList) file).getLastModified();
        } else if (file instanceof Path) {
            try {
                modifiedTimestamp = Files.getLastModifiedTime((Path) file).toMillis();
            } catch (IOException e) {
                modifiedTimestamp = 0;
            }
        } else {
            continue;
        }
        if (modifiedTimestamp > mostRecentModifiedTimestamp) {
            mostRecentModifiedTimestamp = modifiedTimestamp;
        }
    }
    return mostRecentModifiedTimestamp;
}
