import javax.el.ELContext;
import javax.el.ELResolver;
import javax.el.ExpressionFactory;
import javax.el.ValueExpression;
import javax.faces.context.FacesContext;
import java.util.HashMap;
import java.util.Map;

public Map<String, Object> evaluateElExpressions(Map<String, String> parameters) {
    FacesContext facesContext = FacesContext.getCurrentInstance();
    ELContext elContext = facesContext.getELContext();
    ExpressionFactory expressionFactory = facesContext.getApplication().getExpressionFactory();
    ELResolver elResolver = elContext.getELResolver();

    Map<String, Object> evaluatedParameters = new HashMap<>();
    for (Map.Entry<String, String> entry : parameters.entrySet()) {
        ValueExpression valueExpression = expressionFactory.createValueExpression(elContext, entry.getValue(), Object.class);
        evaluatedParameters.put(entry.getKey(), valueExpression.getValue(elContext));
    }
    return evaluatedParameters;
}
