public void unregisterAll(Object object) {
    if (object == null) {
        throw new NullPointerException("object is null");
    }
    if (!registeredObjects.contains(object)) {
        throw new IllegalArgumentException("object was not previously registered");
    }
    registeredObjects.remove(object);
    producers.entrySet().removeIf(entry -> entry.getValue().equals(object));
    handlers.entrySet().removeIf(entry -> entry.getValue().equals(object));
}
