public void assertNumOfColumns(int numOfColumns){
    try {
        WebElement tableElement = driver.findElement(By.tagName("table"));
        List<WebElement> columnElements = tableElement.findElements(By.tagName("th"));
        int actualNumOfColumns = columnElements.size();
        if(actualNumOfColumns != numOfColumns){
            // Log the error and take a screenshot
            System.out.println("Error: Table has " + actualNumOfColumns + " columns, expected " + numOfColumns);
            File sourceFile = ((TakesScreenshot)driver).getScreenshotAs(OutputType.FILE);
            FileUtils.copyFile(sourceFile, new File("screenshot.png"));
            Assert.fail("Table has " + actualNumOfColumns + " columns, expected " + numOfColumns);
        }
    } catch (NoSuchElementException e) {
        // Log the error and take a screenshot
        System.out.println("Error: Table not found");
        File sourceFile = ((TakesScreenshot)driver).getScreenshotAs(OutputType.FILE);
        FileUtils.copyFile(sourceFile, new File("screenshot.png"));
        Assert.fail("Table not found");
    }
}
