public void getAllSuperTypesWithoutInstantiation(Types types, TypeMirror type, List<? super TypeMirror> result) {
    if (type.getKind() == TypeKind.NONE || type.getKind() == TypeKind.NULL) {
        return;
    }
    result.add(type);
    TypeMirror objectType = types.erasure(types.directSupertypes(type).get(0));
    getAllSuperTypesWithoutInstantiation(types, objectType, result);
}
