import java.io.IOException;
import java.io.InputStream;
import java.net.HttpURLConnection;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.util.Map;

public static HttpURLConnection post(String stringUrl, Map<String, String> parameters, String input, String charset)
        throws IOException {
    URL url = new URL(stringUrl);
    HttpURLConnection connection = (HttpURLConnection) url.openConnection();
    connection.setRequestMethod("POST");
    connection.setDoOutput(true);

    if (parameters != null) {
        for (Map.Entry<String, String> entry : parameters.entrySet()) {
            connection.setRequestProperty(entry.getKey(), entry.getValue());
        }
    }

    if (input != null && input.length() > 0) {
        byte[] bytes = input.getBytes(charset != null ? charset : StandardCharsets.UTF_8.name());
        try (OutputStream outputStream = connection.getOutputStream()) {
            outputStream.write(bytes, 0, bytes.length);
        }
    }

    return connection;
}

public static String getResponse(HttpURLConnection connection) throws IOException {
    StringBuilder sb = new StringBuilder();
    try (InputStream inputStream = connection.getInputStream()) {
        byte[] buffer = new byte[4096];
        int bytesRead;
        while ((bytesRead = inputStream.read(buffer)) != -1) {
            sb.append(new String(buffer, 0, bytesRead, StandardCharsets.UTF_8));
        }
    }
    return sb.toString();
}
