public class MessageLoader {
    public static ZMsg loadMsg(DataInputStream file) throws IOException {
        ZMsg msg = new ZMsg();
        byte[] buffer = new byte[1024]; // initialize buffer
        int bytesRead = 0;
        while ((bytesRead = file.read(buffer)) != -1) {  
            msg.add(buffer, 0, bytesRead); // append received bytes to the ZMsg object
        }
        return msg;
    }
}
