public void writeXML(QueryCapability dqc, OutputStream os) throws IOException {
    // Create XML writer with the specified output stream
    XMLOutputFactory xmlFactory = XMLOutputFactory.newInstance();
    XMLStreamWriter writer = xmlFactory.createXMLStreamWriter(os);

    // Start writing the XML document
    writer.writeStartDocument("UTF-8", "1.0");
    writer.writeStartElement("catalog");

    // Write QueryCapability to XML
    writer.writeStartElement("QueryCapability");
    writer.writeAttribute("name", dqc.getName());
    writer.writeAttribute("version", dqc.getVersion());
    writer.writeStartElement("queries");
    for (String query : dqc.getQueries()) {
        writer.writeStartElement("query");
        writer.writeCharacters(query);
        writer.writeEndElement();
    }
    writer.writeEndElement();
    writer.writeEndElement();

    // End the XML document
    writer.writeEndElement();
    writer.writeEndDocument();

    // Close the writer and stream
    writer.flush();
    writer.close();
    os.close();
}
