public static boolean isDecimal(String str, int beginIndex, int endIndex) {
    if(str == null || str.isEmpty() || beginIndex < 0 || endIndex >= str.length()) {
        return false;
    }
    for(int i=beginIndex; i<=endIndex; i++) {
        char c = str.charAt(i);
        if(!Character.isDigit(c) && !(c >= 0xFF10 && c <= 0xFF19)) {
            return false;
        }
    }
    return true;
}
