public int getMonthLength(int year, int month) {
    int monthLength;

    switch (month) {
        case 1: // January
        case 3: // March
        case 5: // May
        case 7: // July
        case 8: // August
        case 10: // October
        case 12: // December
            monthLength = 31;
            break;
        case 4: // April
        case 6: // June
        case 9: // September
        case 11: // November
            monthLength = 30;
            break;
        case 2: // February
            if (isLeapYear(year)) {
                monthLength = 29;
            } else {
                monthLength = 28;
            }
            break;
        default:
            throw new IllegalArgumentException("Invalid month value");
    }

    return monthLength;
}

private boolean isLeapYear(int year) {
    return (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;
}
