public static boolean isListenerConfigured(ServletContext context, String listenerClassName) {
    boolean configuredInWebXml = context.getFilterRegistrations().values().stream()
            .filter(filter -> filter.getClassName().equals(listenerClassName))
            .findAny().isPresent();

    boolean configuredInTld = context.getResourcePaths("/META-INF").stream()
            .filter(path -> path.endsWith(".tld"))
            .flatMap(tld -> readListenerClassesFromTld(context.getResourceAsStream(tld)).stream())
            .anyMatch(listenerClassName::equals);

    return configuredInWebXml || configuredInTld;
}

private static Set<String> readListenerClassesFromTld(InputStream tld) {
    try {
        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
        DocumentBuilder db = dbf.newDocumentBuilder();
        Document doc = db.parse(tld);
        doc.getDocumentElement().normalize();

        Set<String> listenerClasses = new HashSet<>();
        NodeList listenerNodes = doc.getElementsByTagName("listener-class");
        for (int i = 0; i < listenerNodes.getLength(); i++) {
            Node node = listenerNodes.item(i);
            if (node.getNodeType() == Node.ELEMENT_NODE) {
                Element element = (Element) node;
                String listenerClass = element.getTextContent().trim();
                if (!listenerClass.isEmpty()) {
                    listenerClasses.add(listenerClass);
                }
            }
        }
        return listenerClasses;
    } catch (Exception e) {
        throw new RuntimeException("Error reading TLD", e);
    }
}
