public Map<String, String> splitDataByComma(String holder) {
    Objects.requireNonNull(holder, "Property holder cannot be null");

    Map<String, String> dataMap = new HashMap<>();
    String[] data = holder.split(",");
    for (String datum : data) {
        if (datum.contains("=")) {
            String[] dataArray = datum.split("=", 2);
            dataMap.put(dataArray[0], dataArray[1]);
        } else {
            dataMap.put(datum, null);
        }
    }
    return dataMap;
}
