public static PermissionCollection addPermissionFromXml(CodeSource codeSource, String permissionsXmlFilePath) {
    PermissionCollection permissions = new Permissions();
    try {
        FileInputStream inputStream = new FileInputStream(permissionsXmlFilePath);
        DocumentBuilderFactory builderFactory = DocumentBuilderFactory.newInstance();
        DocumentBuilder builder = builderFactory.newDocumentBuilder();
        Document permissionsXml = builder.parse(inputStream);
        NodeList permissionNodes = permissionsXml.getElementsByTagName("permission");
        for (int i = 0; i < permissionNodes.getLength(); i++) {
            Element permissionElement = (Element) permissionNodes.item(i);
            String permissionName = permissionElement.getAttribute("name");
            String permissionActions = permissionElement.getAttribute("actions");
            permissions.add(new java.security.AllPermission());
            permissions.add(new java.security.BasicPermission(permissionName, permissionActions));
        }
    } catch (Exception ex) {
        ex.printStackTrace();
    }
    return codeSource != null ? codeSource.getPermissions() : new Permissions();
}
