public static void updatePermittedActions(int bits, List<String> permittedActions) {
    // Check if bits imply READ
    boolean readBit = ((bits & 4) == 4); // 4 is the mask for READ bit
    if (readBit && !permittedActions.contains("READ")) {
        permittedActions.add("READ");
    } else if (!readBit && permittedActions.contains("READ")) {
        permittedActions.remove("READ");
    }

    // Check if bits imply WRITE
    boolean writeBit = ((bits & 2) == 2); // 2 is the mask for WRITE bit
    if (writeBit && !permittedActions.contains("WRITE")) {
        permittedActions.add("WRITE");
    } else if (!writeBit && permittedActions.contains("WRITE")) {
        permittedActions.remove("WRITE");
    }

    // Check if bits imply EXECUTE
    boolean executeBit = ((bits & 1) == 1); // 1 is the mask for EXECUTE bit
    if (executeBit && !permittedActions.contains("EXECUTE")) {
        permittedActions.add("EXECUTE");
    } else if (!executeBit && permittedActions.contains("EXECUTE")) {
        permittedActions.remove("EXECUTE");
    }
}
