public void submitForm(String path, Map<String, String> formParams) throws ClientException {
    HttpClient client = HttpClient.newHttpClient();
    HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create(path))
            .header("Accept", "application/json")
            .header("Content-Type", "application/x-www-form-urlencoded")
            .POST(HttpRequest.BodyPublishers.ofString(buildParamsString(formParams)))
            .build();
    try {
        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
        int statusCode = response.statusCode();
        if (statusCode != 200 && statusCode != 204) {
            throw new ClientException("Unexpected response from server.");
        }
    } catch (IOException e) {
        throw new ClientException("Network error occurred.", e);
    } catch (InterruptedException e) {
        throw new ClientException("Request interrupted.", e);
    }
}

private String buildParamsString(Map<String, String> params) throws UnsupportedEncodingException {
    StringBuilder result = new StringBuilder();
    for (Map.Entry<String, String> entry : params.entrySet()) {
        if (result.length() > 0) {
            result.append("&");
        }
        result.append(URLEncoder.encode(entry.getKey(), "UTF-8"));
        result.append("=");
        result.append(URLEncoder.encode(entry.getValue(), "UTF-8"));
    }
    return result.toString();
}
