public void setSeed(int[] array) {
    int len = array.length;
    int j = 0;
    int k = 0;
    int state[] = new int[N];
    for (int i = 0; i < N; i++) {
        state[i] = 0;
    }
    if (len == 0) {
        throw new IllegalArgumentException("Array length must be greater than zero");
    }
    for (int i = 0; i < N; i++) {
        state[i] = array[k] ^ (state[i] >>> 30);
        k++;
        if (k >= len) {
            k = 0;
        }
    }
    for (int i = N - 1; i >= 0; i--) {
        j = i - 1;
        if (i == 0) {
            j = N - 1;
        }
        state[i] = (state[i] ^ ((state[j] ^ (state[i] << 1)) >>> 18)) >>> 0;
    }
    index = 0;
    this.mt = state;
}
