import java.io.*;
import java.util.zip.CRC32;
import java.util.zip.ZipEntry;
import java.util.zip.ZipFile;

public class ExtractLibrary {
    public static File extractLibrary(String libraryName, String dirName) throws IOException {
        String tempDirPath = System.getProperty("java.io.tmpdir");
        File tempDir = new File(tempDirPath + File.separator + (dirName != null ? dirName : ""));
        if (!tempDir.exists()) {
            tempDir.mkdir();
        }

        File extractedFile = new File(tempDir, libraryName);
        if (!extractedFile.exists()) {
            extractFromClasspath(libraryName, extractedFile);
        } else {
            long crc = getCRC(extractedFile);
            long newCrc = getCRCFromJar(libraryName);
            if (crc != newCrc) {
                extractFromClasspath(libraryName, extractedFile);
            }
        }

        return extractedFile;
    }

    private static void extractFromClasspath(String libraryName, File extractedFile) throws IOException {
        InputStream is = ExtractLibrary.class.getClassLoader().getResourceAsStream(libraryName);
        OutputStream os = new FileOutputStream(extractedFile);

        byte[] buffer = new byte[4096];
        int length;
        while ((length = is.read(buffer)) > 0) {
            os.write(buffer, 0, length);
        }
        os.close();
        is.close();
    }

    private static long getCRCFromJar(String libraryName) throws IOException {
        ZipFile zipFile = new ZipFile(new File(System.getProperty("java.class.path")));
        try {
            ZipEntry entry = zipFile.getEntry(libraryName);
            if (entry == null) {
                throw new FileNotFoundException("Could not find " + libraryName + " in JAR");
            }
            InputStream is = zipFile.getInputStream(entry);
            CRC32 crc = new CRC32();
            byte[] bytes = new byte[4096];
            int len;
            while ((len = is.read(bytes)) > 0) {
                crc.update(bytes, 0, len);
            }
            is.close();
            return crc.getValue();
        } finally {
            zipFile.close();
        }
    }

    private static long getCRC(File file) throws IOException {
        CRC32 crc = new CRC32();
        try (InputStream is = new FileInputStream(file)) {
            byte[] bytes = new byte[4096];
            int len;
            while ((len = is.read(bytes)) > 0) {
                crc.update(bytes, 0, len);
            }
        }
        return crc.getValue();
    }
}
