public static <T> SoftReferenceObjectPool<T> createObjectPool(Supplier<T> connectionSupplier) {
    Objects.requireNonNull(connectionSupplier, "connectionSupplier must not be null");
    return new SoftReferenceObjectPool<>(new BasePooledObjectFactory<T>() {
        @Override
        public T create() throws Exception {
            return connectionSupplier.get();
        }

        @Override
        public PooledObject<T> wrap(T obj) {
            if (obj == null) {
                return null;
            }
            throw new UnsupportedOperationException("Allocated instances of the connection pool are wrapped " +
                    "and must not be returned with ObjectPool.returnObject(Object).");
        }
    });
}
