import org.apache.hadoop.hive.metastore.api.StorageDescriptor;
import org.apache.hadoop.hive.metastore.api.Table;
import org.apache.hadoop.hive.ql.metadata.Hive;
import org.apache.hadoop.hive.serde2.typeinfo.TypeInfo;
import org.apache.hadoop.hive.serde2.typeinfo.TypeInfoFactory;
import org.apache.hadoop.hive.serde2.typeinfo.TypeInfoUtils;
import org.apache.hadoop.hive.serde2.typeinfo.TypeUtils;
import org.apache.hadoop.mapred.JobConf;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Optional;
import java.util.stream.Collectors;

public class HivePartitionDatasetVersionFinder {

    private final String tableName;
    private final Hive hive;
    private final String backupPattern;
    private final String stagingPattern;
    private final String trashPattern;

    public HivePartitionDatasetVersionFinder(String tableName,
                                              Hive hive,
                                              String backupPattern,
                                              String stagingPattern,
                                              String trashPattern) {
        this.tableName = tableName;
        this.hive = hive;
        this.backupPattern = backupPattern;
        this.stagingPattern = stagingPattern;
        this.trashPattern = trashPattern;
    }

    public List<String> findVersions() throws Exception {
        Table table = hive.getTable(tableName);
        List<Table> tables = hive.getAllTables(table.getDbName());
        List<String> versionTableNames = new ArrayList<>();
        for (Table t : tables) {
            if (isVersionTable(t.getTableName())) {
                versionTableNames.add(t.getTableName());
                if (t.getPartitionKeysSize() == 0) {
                    hive.dropTable(tableName, true, true, true);
                }
            }
        }

        //sort version tables by time stamp in descending order
        Collections.sort(versionTableNames, Comparator.reverseOrder());

        return versionTableNames;
    }

    private boolean isVersionTable(String tableName) {
        boolean isBackupTable = tableName.matches(String.format(backupPattern, this.tableName, ".*"));
        boolean isStagingTable = tableName.matches(String.format(stagingPattern, this.tableName, ".*"));
        boolean isTrashTable = tableName.matches(String.format(trashPattern, this.tableName, ".*"));
        return isBackupTable || isStagingTable || isTrashTable;
    }

    private Optional<TypeInfo> getTypeInfo(String serde) {
        try {
            String typeName = StorageDescriptor.getDeserializer(serde, new JobConf()).getObjectInspector().getTypeName();
            return Optional.of(TypeInfoUtils.getTypeInfoFromTypeString(typeName));
        } catch (Exception e) {
            return Optional.empty();
        }
    }
}

