public static long parseSizeValue(String propertyName, String propertyValue) throws NumberFormatException {
    long result = Long.parseLong(propertyValue.trim());
    if (propertyValue.endsWith("g") || propertyValue.endsWith("G")) {
        result = result * 1024 * 1024 * 1024;
    } else if (propertyValue.endsWith("m") || propertyValue.endsWith("M")) {
        result = result * 1024 * 1024;
    } else if (propertyValue.endsWith("k") || propertyValue.endsWith("K")) {
        result = result * 1024;
    }
    return result;
}
