    // Convert IP address from string to byte array
    String[] ipAddressParts = ipAddress.split("\\.");
    byte[] ipBytes = new byte[4];
    for (int i = 0; i < 4; i++) {
        ipBytes[i] = (byte) Integer.parseInt(ipAddressParts[i]);
    }

    // Create subnet mask from CIDR notation
    byte[] maskBytes = new byte[4];
    for (int i = 0; i < 4; i++) {
        int n = Math.min(subnetMask, 8);
        subnetMask -= n;
        maskBytes[i] = (byte) (256 - (1 << 8 - n));
    }

    // Initialize the internal fields from the supplied CIDR mask
    this.ipAddress = ipAddress;
    this.subnetMask = subnetMask;
    this.ipBytes = ipBytes;
    this.maskBytes = maskBytes;
}
