public Map<String, Object> getArgumentsMap(Map<String, String> arguments) {
    Map<String, Object> argumentMap = new HashMap<String, Object>();

    for (Map.Entry<String, String> entry : arguments.entrySet()) {
        String key = entry.getKey();
        String value = entry.getValue();

        if (value.matches("\\d+")) {
            argumentMap.put(key, Integer.parseInt(value));
        } else if (value.matches("\\d+\\.\\d+")) {
            argumentMap.put(key, Double.parseDouble(value));
        } else if (value.equals("true") || value.equals("false")) {
            argumentMap.put(key, Boolean.parseBoolean(value));
        } else {
            argumentMap.put(key, value);
        }
    }

    return argumentMap;
}
