public static String longToHexString(long num) {
    String hexString = Long.toHexString(num);
    int paddingLength = 16 - hexString.length();

    if (paddingLength > 0) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < paddingLength; i++) {
            sb.append("0");
        }
        sb.append(hexString);
        hexString = sb.toString();
    }

    return hexString;
}
