import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.math.BigInteger;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Date;

public class ImageUtils {

    public static String generateCachedFileName(String originalPath, Date createdTime) {
        try {
            // Convert the image path to bytes
            FileInputStream fis = new FileInputStream(new File(originalPath));
            byte[] content = new byte[(int) new File(originalPath).length()];
            fis.read(content);
            fis.close();

            // Generate the MD5 digest
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] hash = md.digest(content);

            // Combine the hash and the creation time to create the file name
            String fileName = new BigInteger(1, hash).toString(16) + "_" + createdTime.getTime();

            return fileName;
        } catch (IOException | NoSuchAlgorithmException e) {
            e.printStackTrace();
            return null;
        }
    }
}
