public String convertToShortQuartzForm(String e, int max) {
    String result = e;
    if (e.startsWith("/")) { // handling the case where the string starts with '/'
        result = "*" + e;
    } else {
        String[] segments = e.split("/"); // splitting the string with "/"
        if(segments.length == 2) { // checking if there is any segment after "/"
            int interval = Integer.parseInt(segments[1]);
            String leftSegment = segments[0];
            if(leftSegment.contains("-")) { // Checking if the left segment contains "-"
                String[] range = leftSegment.split("-");
                int start = Integer.parseInt(range[0]);
                int end = Integer.parseInt(range[1]);
                if(start == 0) { // If the start of the segment is 0, then remove it
                    leftSegment = "";
                } else {
                    leftSegment = Integer.toString(start); // Otherwise, replace the left segment with start
                }
                //calculating the right segment
                int rightSegment = end;
                while (rightSegment < max) {
                    rightSegment += interval;
                }
                if(!(rightSegment == max && leftSegment.equals(""))) { // if the right segment is not the same as max value and the left segment is not empty, then add "/"
                    result = leftSegment + "/" + rightSegment;
                }
                else{
                    result = Integer.toString(start);
                }
            }
            else {// if there is no '-' in the left segment, then add "*/"
                result = "*/" + Integer.toString(interval);
            }
        }
    }
    return result;
}
