public static String encodePath(List<Point> path, int precision) {
    StringBuilder encodedPath = new StringBuilder();
    long lastLat = 0, lastLng = 0;

    for (Point point : path) {
        long lat = Math.round(point.lat * Math.pow(10, precision));
        long lng = Math.round(point.lng * Math.pow(10, precision));

        encodedPath.append(encodeValue(lat - lastLat))
                   .append(encodeValue(lng - lastLng));

        lastLat = lat;
        lastLng = lng;
    }

    return encodedPath.toString();
}

private static String encodeValue(long value) {
    StringBuilder sb = new StringBuilder();

    // A value of 0 is represented by 0 bits
    value <<= 1;

    if (value < 0) {
        value = ~value;
    }

    while (value >= 0x20) {
        sb.append(Character.toChars((int) ((0x20 | (value & 0x1f)) + 63)));
        value >>= 5;
    }

    sb.append(Character.toChars((int) (value + 63)));
    return sb.toString();
}
