public List<Solution> getNeighbors(List<Solution> solutionList, Solution solutionPosition) {
    List<Solution> neighbors = new ArrayList<>();
    int row = solutionPosition.getRow();
    int column = solutionPosition.getColumn();

    // North
    if (row > 0) {
        neighbors.add(solutionList.get((row - 1) * solutionList.size() + column));
    }

    // South
    if (row < solutionList.size() - 1) {
        neighbors.add(solutionList.get((row + 1) * solutionList.size() + column));
    }

    // East
    if (column > 0) {
        neighbors.add(solutionList.get(row * solutionList.size() + column - 1));
    }

    // West
    if (column < solutionList.size() - 1) {
        neighbors.add(solutionList.get(row * solutionList.size() + column + 1));
    }

    return neighbors;
}
