public int findNodeIndex(int[] weights, int strength) {
    int currentStrength = 0;
    for (int i = 0; i < weights.length; i++) {
        if (weights[i] == 5) {
            if (currentStrength >= strength) {
                return i;
            } else if (i + 1 < weights.length && weights[i + 1] == 5) {
                currentStrength = strength + 1;
                i++;
            }
        } else if (weights[i] >= strength) {
            currentStrength = weights[i];
        }
    }
    return weights.length - 1;
}
