public List<ContainerPlanSet> buildContainerPlanSets(List<Instance> instances) {
    List<ContainerPlanSet> containerPlanSets = new ArrayList<>();
    Map<Integer, List<Instance>> resourceGroupMap = new HashMap<>();

    // Group instances based on their resource levels
    for (Instance instance : instances) {
        int resources = instance.getCpu() + instance.getRam() + instance.getDisk();
        List<Instance> group = resourceGroupMap.computeIfAbsent(resources, k -> new ArrayList<>());
        group.add(instance);
    }

    // Sum up resources for each group and create a set of container plans
    for (Map.Entry<Integer, List<Instance>> entry : resourceGroupMap.entrySet()) {
        int resources = entry.getKey();
        List<Instance> instancesInGroup = entry.getValue();
        int instancesCount = instancesInGroup.size();
        int cpu = 0;
        int ram = 0;
        int disk = 0;
        for (Instance instance : instancesInGroup) {
            cpu += instance.getCpu();
            ram += instance.getRam();
            disk += instance.getDisk();
        }
        ContainerPlanSet containerPlanSet = new ContainerPlanSet(resources, instancesCount, cpu, ram, disk);
        containerPlanSets.add(containerPlanSet);
    }

    return containerPlanSets;
}
