@Override
public List<AnalyzedSentence> checkText(String text) {
    List<AnalyzedSentence> analyzedSentences = new ArrayList<>();
    try {
        MorphologicalAnalyzer morphologicalAnalyzer = new MorphologicalAnalyzer();
        Chunker chunker = new Chunker();
        Parser parser = new Parser();

        List<Token> tokenList = Tokenizer.tokenize(text);
        List<List<ParseTree>> parseTreeList = parser.parse(tokenList);
        List<List<Chunk>> chunkList = chunker.chunk(tokenList, parseTreeList);
        List<List<Analysis>> analysisList = morphologicalAnalyzer.analyze(tokenList);

        for (int i = 0; i < tokenList.size(); i++) {
            analyzedSentences.add(new AnalyzedSentence(tokenList.get(i), analysisList.get(i),
                    parseTreeList.get(i), chunkList.get(i)));
        }
    } catch (CogrooException e) {
        System.out.println("Cogroo Exception: " + e.getMessage());
    }
    return analyzedSentences;
