public Collection<Photo> getContactsPhotos(int count, boolean justFriends, boolean singlePhoto, boolean includeSelf) throws FlickrException {
    Set<String> extras = new HashSet<String>();
    extras.add("url_sq");
    extras.add("url_t");
    extras.add("url_s");
    extras.add("url_q");
    extras.add("url_m");
    extras.add("url_n");
    extras.add("url_z");
    extras.add("url_c");
    extras.add("url_l");
    extras.add("url_o");

    Map<String, String> params = new HashMap<String, String>();
    params.put("method", "flickr.photos.search");
    params.put("per_page", String.valueOf(count));
    params.put("sort", "date-posted-desc");
    params.put("format", "json");
    params.put("nojsoncallback", "1");
    params.put("extras", String.join(",", extras));
    if (justFriends) {
      params.put("privacy_filter", "5");
    }
    if (singlePhoto) {
      params.put("media", "photos");
    }
    if (!includeSelf) {
      params.put("exclude_self", "1");
    }

    Response response = transport.post(transport.getPath(), params);
    String responseBody = response.getContent();

    PhotoList photos = PhotoUtils.createPhotoList(responseBody);
    Set<String> photoIds = new HashSet<String>();
    for (Iterator<?> it = photos.iterator(); it.hasNext();) {
      Photo photo = (Photo) it.next();
      photoIds.add(photo.getId());
    }

    Collection<Photo> photoList = PhotoUtils.getPhotos(photoIds);

    return photoList;
}
