public void assertNextTokenIsNull() throws IllegalStateException, IOException {
    if (!reader.hasNext()) {
        throw new IllegalStateException("Reader is closed.");
    }
    JsonToken token = reader.peek();
    if(token != JsonToken.NULL) {
        throw new IllegalStateException("Next token is not null.");
    }
    reader.nextNull();
}
