public static double calculateAverageBondLength(Reaction reaction) {
    List<Bond> bonds = reaction.getBonds();
    double sum = 0.0;
    for (Bond bond : bonds) {
        sum += bond.getLength();
    }
    return sum / bonds.size();
}
