import org.openqa.selenium.By;
import org.openqa.selenium.WebDriver;

public static By getByObject(WebDriver driver, String locator) {
    By byObject = null;

    if (locator.startsWith("//")) {
        byObject = By.xpath(locator);
    } else if (locator.contains(":")) {
        String[] locatorPart = locator.split(":", 2);
        String locatorPrefix = locatorPart[0];
        String locatorValue = locatorPart[1].trim();

        switch (locatorPrefix) {
            case "id":
                byObject = By.id(locatorValue);
                break;
            case "name":
                byObject = By.name(locatorValue);
                break;
            case "class":
                byObject = By.className(locatorValue);
                break;
            case "tag":
                byObject = By.tagName(locatorValue);
                break;
            case "linkText":
                byObject = By.linkText(locatorValue);
                break;
            case "partialLinkText":
                byObject = By.partialLinkText(locatorValue);
                break;
            case "css":
                byObject = By.cssSelector(locatorValue);
                break;
            default:
                throw new IllegalArgumentException("Unknown locator prefix '" + locatorPrefix + "'");
        }
    } else {
        byObject = By.id(locator);
    }

    return byObject;
}
