import java.security.InvalidArgumentException;
import java.security.spec.ECGenParameterSpec;

public static ECGenParameterSpec getCurve(int securityLevel) throws InvalidArgumentException {
    if (securityLevel != 256 && securityLevel != 384) {
        throw new InvalidArgumentException("Invalid security level. Must be 256 or 384.");
    }
    String curveName = securityLevel == 256 ? "secp256r1" : "secp384r1";
    return new ECGenParameterSpec(curveName);
}
