public String manipulateExpression(String originalExpression) {
    StringBuilder manipulatedExpression = new StringBuilder(originalExpression);
    boolean added = false;
    for (int i = 0; i < manipulatedExpression.length(); i++) {
        char currentChar = manipulatedExpression.charAt(i);
        if (currentChar == '(') {
            if (i > 0 && manipulatedExpression.charAt(i - 1) != '+' && manipulatedExpression.charAt(i - 1) != '*' && manipulatedExpression.charAt(i - 1) != '(') {
                manipulatedExpression.insert(i, '+');
                i++;
                added = true;
            }
        } else if (currentChar == ')') {
            if (i < manipulatedExpression.length() - 1 && manipulatedExpression.charAt(i + 1) != '+' && manipulatedExpression.charAt(i + 1) != '*' && manipulatedExpression.charAt(i + 1) != ')') {
                manipulatedExpression.insert(i + 1, '+');
                added = true;
            }
        }
        if (added) {
            i++;
            added = false;
        }
    }
    return manipulatedExpression.toString();
}
