public static int maxIntegerDigits(int[] values) {
    int maxDigits = Integer.MIN_VALUE;
    for (int value : values) {
        int digits = String.valueOf(Math.abs(value)).length();
        if (digits > maxDigits) {
            maxDigits = digits;
        }
    }
    return maxDigits;
}
