public int getCommerceWishListItemCount(long commerceWishListId, String CPInstanceUuid) {
    Session session = null;
    int count = 0;
    try {
        session = openSession();
        String queryString = "SELECT COUNT(*) FROM CommerceWishListItem WHERE commerceWishListId = :commerceWishListId AND CPInstanceUuid = :CPInstanceUuid";
        Query query = session.createQuery(queryString);
        query.setParameter("commerceWishListId", commerceWishListId);
        query.setParameter("CPInstanceUuid", CPInstanceUuid);
        count = ((Number) query.uniqueResult()).intValue();
    } catch (Exception e) {
        throw e;
    } finally {
        if (session != null) {
            session.close();
        }
    }
    return count;
}
