public static void normalizeAndCollapseWhitespaces(StringBuffer strBuffer) {
    if (strBuffer == null) {
        return;
    }

    int length = strBuffer.length();
    boolean lastCharWasSpace = false;
    int j = 0;

    for (int i = 0; i < length; i++) {
        char c = strBuffer.charAt(i);
        if (Character.isWhitespace(c)) {
            if (!lastCharWasSpace) {
                strBuffer.setCharAt(j++, ' ');
                lastCharWasSpace = true;
            }
        } else {
            strBuffer.setCharAt(j++, c);
            lastCharWasSpace = false;
        }
    }

    strBuffer.setLength(j);
}
