public boolean ensureLastMarkedParamIsBool(Object emptyDefault, int mark) throws GroovyBugError {
    if (mark == Thread.currentThread().getStackTrace().length) {
        return (boolean) emptyDefault;
    } else if (mark == Thread.currentThread().getStackTrace().length - 1) {
        return (boolean) Thread.currentThread().getStackTrace()[mark];
    } else {
        throw new GroovyBugError();
    }
}
