/**
 * This function checks if checkpoint has failed continuously and aborts the standby
 * to avoid continuously rolling edit log on the primary without finalizing checkpoint.
 *
 * @param checkpointStatus an array of booleans representing the status of checkpoint
 * @param maxAttempts the maximum number of checkpoint attempts allowed before aborting the standby
 * @throws IllegalStateException if checkpoint fails continuously beyond the maximum allowed attempts
 */
public void abortIfCheckpointFailsContinuously(boolean[] checkpointStatus, int maxAttempts) {
    int failedAttempts = 0;
    for (boolean status : checkpointStatus) {
        if (!status) {
            failedAttempts++;
            if (failedAttempts >= maxAttempts) {
                throw new IllegalStateException("Checkpoint failed continuously beyond maximum allowed attempts. Aborting standby.");
            }
        } else {
            failedAttempts = 0;
        }
    }
}
