public static String escapeXml(String s) {
    StringBuilder out = new StringBuilder(Math.max(16, s.length()));
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '"')
            out.append("&quot;");
        else if (c == '\'')
            out.append("&apos;");
        else if (c == '<')
            out.append("&lt;");
        else if (c == '>')
            out.append("&gt;");
        else if (c == '&')
            out.append("&amp;");
        else
            out.append(c);
    }
    return out.toString();
}
