public byte[] readPayloadFromBuffer(ByteBuffer buffer) throws IOException {
    ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
    byte[] payload;

    while (buffer.hasRemaining()) {
        outputStream.write(buffer.get());
    }

    try {
        outputStream.flush();
        payload = outputStream.toByteArray();
    } catch (IOException e) {
        throw new IOException("An error occurred while reading the payload from buffer.", e);
    } finally {
        outputStream.close();
    }

    return payload;
}
