public static IntTupleIncrementor getColexIntTupleIncrementor() {
    return tuple -> {
        for (int i = tuple.length - 1; i >= 0; i--) {
            if (tuple[i] < Integer.MAX_VALUE) {
                tuple[i]++;
                break;
            } else {
                tuple[i] = 0;
            }
        }
        return tuple;
    };
}
