public static EdgeConfig overrideFlowEdgeProperties(EdgeConfig edgeConfig, String edgeFilePath) {
    String edgeName = edgeFilePath.substring(edgeFilePath.lastIndexOf("/") + 1);
    String flowPropKey = "flow-" + edgeName;
    String capacityPropKey = "capacity-" + edgeName;

    String flowPropValue = edgeConfig.getProperties().getProperty(flowPropKey);
    String capacityPropValue = edgeConfig.getProperties().getProperty(capacityPropKey);

    if (flowPropValue != null) {
        edgeConfig.getFlowProps().setFlow(flowPropValue);
    }
    if (capacityPropValue != null) {
        edgeConfig.getCapacityProps().setCapacity(Long.parseLong(capacityPropValue));
    }

    return edgeConfig;
}
