public double calculateInterRaterAgreement(AnnotationItem item) {
    if(item == null) {
        throw new NullPointerException("Annotation item cannot be null");
    }

    double totalAnnotations = item.getNumberOfAnnotators();
    double totalAgreements = 0.0;

    for(int i = 0; i < totalAnnotations; i++) {
        for(int j = i+1; j < totalAnnotations; j++) {
            totalAgreements += item.getAgreement(i, j);
        }
    }

    return (2 * totalAgreements) / (totalAnnotations * (totalAnnotations - 1));
}
