import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.util.List;

public void listFilesOfType(String directoryPath, String type) throws IOException {
    File directory = new File(directoryPath);

    // Check if the directory exists and is a directory
    if(!directory.exists() || !directory.isDirectory()) {
        throw new IllegalArgumentException("Invalid directory path!");
    }

    // Iterate over all the files in the directory
    for(File file : directory.listFiles()) {
        // Get the MIME type of the current file
        String mimeType = Files.probeContentType(file.toPath());

        // Check if the MIME type contains the given type string
        if(mimeType != null && mimeType.contains(type)) {
            System.out.println(file.getName());
        }
    }
}
