public static void printCharSequenceSpans(CharSequence text) {
        if (!(text instanceof Spanned)) {
            System.out.println(text.toString());
            return;
        }
        Spanned spanned = (Spanned) text;

        int start = 0;
        int end = spanned.length();

        while (start < end) {
            int next;

            // Get the next span transition and handle the case where
            // there are no more spans.
            final Object[] spans = spanned.getSpans(start, end, Object.class);
            if (spans.length == 0) {
                next = end;
            } else {
                next = spanned.getSpanStart(spans[0]);
                for (int i = 1; i < spans.length; ++i) {
                    final int spanStart = spanned.getSpanStart(spans[i]);
                    if (spanStart < next) {
                        next = spanStart;
                    }
                }
            }

            // Print the span and the text covered by it.
            System.out.println(text.subSequence(start, next).toString());
            if (next < end) {
                for (Object span : spanned.getSpans(next + 1, next + 1, Object.class)) {
                    System.out.println(span.toString());
                }
            }
            start = next;
