@Override
public void leave(ActivityExecution execution) {
    if (execution.getActivity().getProperty("type").equals("parallel")) {
        boolean allExecutionsEnded = true;
        List<ActivityExecution> executions = execution.getActivity().getExecutions();
        for (ActivityExecution ex : executions) {
            if (!ex.isEnded()) {
                allExecutionsEnded = false;
                break;
            }
        }
        if (allExecutionsEnded) {
            super.leave(execution);
        }
    } else {
        super.leave(execution);
    }
}
