public static <T extends Number & Comparable<? super T>> Map<T, T> computeCoalescedRange(
        Map<T, T> map, T start, T end) {
    if (start.compareTo(end) > 0) {
        throw new IllegalArgumentException(String.format("Invalid range: [%s, %s]", start, end));
    }

    TreeMap<T, T> coalescedRange = new TreeMap<>(map);
    Map.Entry<T, T> lowerEntry = coalescedRange.lowerEntry(start);
    if (lowerEntry != null && lowerEntry.getValue().compareTo(start) >= 0) {
        start = lowerEntry.getKey();
    }
    Map.Entry<T, T> upperEntry = coalescedRange.floorEntry(end);
    if (upperEntry != null) {
        end = upperEntry.getValue();
    }

    coalescedRange.subMap(start, true, end, true).clear();

    coalescedRange.put(start, end);
    return coalescedRange;
}
