public static void ensureNthElementInCorrectPosition(int[] arr, int left, int right, int n, int origin) {
    int pivot = arr[n-1];
    int i = left, j = right-1;

    while (i <= j) {
        while (i < right && Math.abs(arr[i]-origin) < Math.abs(pivot-origin)) {
            i++;
        }

        while (j >= left && Math.abs(arr[j]-origin) >= Math.abs(pivot-origin)) {
            j--;
        }

        if (i <= j) {
            int temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
            i++;
            j--;
        }
    }

    if (j < n-1) {
        j++;
    }

    if (j - left + 1 == n) {
        return;
    } else if (n < j - left + 1) {
        ensureNthElementInCorrectPosition(arr, left, j, n, origin);
    } else {
        ensureNthElementInCorrectPosition(arr, j+1, right, n-(j-left+1), origin);
    }
}
