public static double[][] makeDense(double[][] sparseInstance) {
    int numRows = sparseInstance.length;
    int numCols = sparseInstance[0].length;
    double[][] denseInstance = new double[numRows][numCols];

    // Copy values from the sparse array to the dense array
    for (int i = 0; i < numRows; i++) {
        for (int j = 0; j < numCols; j++) {
            denseInstance[i][j] = sparseInstance[i][j];
        }
    }

    return denseInstance;
}
