public String getAPIDocumentation(Class<?> controller) {
    if (controller.isAnnotationPresent(Api.class)) {
        Api classApi = controller.getAnnotation(Api.class);
        StringBuilder documentationBuilder = new StringBuilder();
        documentationBuilder.append("Class: ").append(controller.getSimpleName()).append("\n");
        documentationBuilder.append("Description: ").append(classApi.value()).append("\n\n");

        Method[] methods = controller.getMethods();
        for (Method method : methods) {
            if (method.isAnnotationPresent(ApiMethod.class)) {
                ApiMethod methodApi = method.getAnnotation(ApiMethod.class);
                documentationBuilder.append("Method: ").append(method.getName()).append("\n");
                documentationBuilder.append("Description: ").append(methodApi.value()).append("\n");
                documentationBuilder.append("HTTP method: ").append(methodApi.httpMethod()).append("\n");
                documentationBuilder.append("Path: ").append(methodApi.path()).append("\n\n");
            }
        }

        return documentationBuilder.toString();
    }
    return null;
}
