import java.nio.ByteBuffer;

public static ByteBuffer mergeBuffers(ByteBuffer... buffers) {
    if (buffers == null || buffers.length == 0) {
        return ByteBuffer.allocate(0);
    }
    int totalSize = 0;
    ByteOrder order = buffers[0].order();
    for (ByteBuffer buffer : buffers) {
        if (buffer.order() != order) {
            throw new IllegalArgumentException("The specified buffers have different endianness.");
        }
        totalSize += buffer.remaining();
    }
    ByteBuffer mergedBuffer = ByteBuffer.allocate(totalSize).order(order);
    for (ByteBuffer buffer : buffers) {
        mergedBuffer.put(buffer);
    }
    mergedBuffer.flip();
    return mergedBuffer;
}
