public View waitForView(int view, int index, long timeout) {
    View targetView = null;
    long endTime = System.currentTimeMillis() + timeout;
    do {
        List<View> views = findViewsById(view);
        if (views != null && views.size() > index) {
            targetView = views.get(index);
        }
        if (targetView == null) {
            try {
                Thread.sleep(200);
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        }
    } while (targetView == null && System.currentTimeMillis() < endTime);

    return targetView;
}

private List<View> findViewsById(int viewId) {
    ArrayList<View> matchViews = new ArrayList<>();
    ViewFinder viewFinder = ViewFinder.getInstance();
    View root = viewFinder.getRootView();
    if (root != null) {
        viewFinder.findViewsWithText(matchViews, root, viewId);
    }

    return matchViews;
}
