public void processRequest(Transport transport, Listener listener) throws ModbusIOException {
   // Read the request from the transport
   Request request = transport.readRequest();

   // Check if the request is null
   if (request == null) {
      throw new ModbusIOException("Invalid request");
   }

   // Check if the unit ID is valid
   int unitId = request.getUnitID();
   if (unitId < 0 || unitId > 255) {
      throw new ModbusIOException("Invalid unit ID");
   }

   // Send back a response
   transport.writeResponse(listener.processRequest(request));
}
