public List<File> locateClassFiles(File classDirectory) throws MojoExecutionException {
    try {
        List<File> classFiles = new ArrayList<>();
        Files.walk(classDirectory.toPath())
            .filter(path -> path.toFile().isFile() && path.toString().endsWith(".class"))
            .map(Path::toFile)
            .forEach(classFiles::add);
        return classFiles;
    } catch (IOException e) {
        throw new MojoExecutionException("Error scanning class file resources.", e);
    }
}
