public static String getTypeName(ClassDoc cd) {
  Type t = cd.asType();
  if (t instanceof ArrayType) {
    return getTypeName(((ArrayType) t).componentType()) + "[]";
  } else if (t instanceof ParameterizedType) {
    return getTypeName(((ParameterizedType) t).getRawType());
  } else if (t instanceof WildcardType) {
    Type[] upperBounds = ((WildcardType) t).upperBounds();
    if (upperBounds.length == 1) {
      return getTypeName(upperBounds[0]);
    }
    Type[] lowerBounds = ((WildcardType) t).lowerBounds();
    if (lowerBounds.length == 1) {
      return getTypeName(lowerBounds[0]);
    }
    return "?";
  } else if (t instanceof TypeVariable) {
    return t.toString();
  } else if (t instanceof ClassType) {
    return ((ClassType) t).simpleTypeName();
  }
  return "UNKNOWN";
}
