public CertificateAuthenticator getCertificateAuthenticator(X509Certificate[] certChain) throws LoginException {
    ServiceLoader<CertificateAuthenticator> authenticators = ServiceLoader.load(CertificateAuthenticator.class);
    for (CertificateAuthenticator authenticator : authenticators) {
