public double[] divideArrays(double[] arr1, double[] arr2) {
    double[] result = new double[arr1.length * arr2.length];

    int index = 0;
    for (int i = 0; i < arr1.length; i++) {
        for (int j = 0; j < arr2.length; j++) {
            result[index++] = arr1[i] / arr2[j];
        }
    }

    return result;
}
