public <T extends Enum<T>> T recognizeOptionFromString(String option, Class<T> enumType) {
    String[] optionParts = option.split("\\.");
    if (optionParts.length != 2) {
        throw new IllegalArgumentException("Invalid option format. Expected format: optionType.optionName");
    }
    try {
        T recognizedOption = Enum.valueOf(enumType, optionParts[1]);
        if (!recognizedOption.getClass().getSimpleName().equals(optionParts[0])) {
            throw new IllegalArgumentException("Invalid option type. Expected type: " + optionParts[0]);
        }
        return recognizedOption;
    } catch (IllegalArgumentException ex) {
        throw new IllegalArgumentException("Unrecognized option: " + option, ex);
    }
}
