/**
 * Ensure that the capacity is not less than the proposed capacity. If it is less, return the minimum
 * capacity that should be set.
 *
 * @param capacity     the current capacity
 * @param proposedSize the proposed size that should be ensured
 * @return the capacity that should be set to fulfill the proposed
 */
@Override
public int ensureCapacity(int capacity, int proposedSize) {
    if (capacity < proposedSize) {
        capacity = Math.max(proposedSize, capacity * 2);
    }
    return capacity;
}
