import java.io.IOException;
import org.apache.log4j.Logger;

public void setPermissions(String user, String tokenFile, Logger logger) throws IOException {
    String[] command = { "execute-as-user", user, "chmod", "460", tokenFile };
    Process process = Runtime.getRuntime().exec(command);
    try {
        process.waitFor();
        if (process.exitValue() != 0) {
            logger.error("Failed to set file permissions.");
        }
        String[] command2 = { "execute-as-user", user, "chown", user, tokenFile };
        Process process2 = Runtime.getRuntime().exec(command2);
        process2.waitFor();
        if (process2.exitValue() != 0) {
            logger.error("Failed to set file ownership.");
        }
    } catch (InterruptedException e) {
        logger.error("Interrupted while waiting for process to complete.");
        Thread.currentThread().interrupt();
    }
}
