public void runManagers(List<DependencyManager> managers) throws Exception {
    boolean success = false;
    for (DependencyManager manager : managers) {
        try {
            manager.run();
            success = true;
            break;
        } catch (Exception e) {
            // ignore and try the next manager
        }
    }
    if (!success) {
        throw new Exception("Failed to run any dependency manager.");
    }
}
