public Descriptor unmarshalDescriptorContent(String descriptorContent) throws CmsXmlException, CmsException {
    try {
        // Create a new JAXB Context for Descriptor class
        JAXBContext context = JAXBContext.newInstance(Descriptor.class);

        // Create an Unmarshaller for the Descriptor class
        Unmarshaller unmarshaller = context.createUnmarshaller();

        // Read the descriptor content as input stream
        InputStream inStream = new ByteArrayInputStream(descriptorContent.getBytes(StandardCharsets.UTF_8));

        // Unmarshal the descriptor content
        return (Descriptor) unmarshaller.unmarshal(inStream);
    } catch (JAXBException e) {
        throw new CmsXmlException("XML structure of the descriptor is wrong", e);
    } catch (IOException e) {
        throw new CmsException("Reading the descriptor file fails", e);
    }
}
