public Map<String, String> parseMultipartFormDataWithoutExceptions(byte[] formData) {
    Map<String, String> fields = new HashMap<>(); 
    String boundary = extractBoundary(formData);
    if(boundary == null) {
        return fields; // or return null?
    }

    String[] parts = new String(formData).split(boundary);

    for(int i = 1; i < parts.length - 1; i++) {
        String part = parts[i];
        String[] subparts = part.split("\r\n\r\n");

        String field = subparts[0].split("name=")[1].replaceAll("\"", "");
        String value = subparts[1].substring(0, subparts[1].length() - 2);
        fields.put(field, value);
    }
    return fields;
}
