public Object performBitOperation(Object field, String operation, int value) {
    switch (operation) {
        case "AND":
            return ((int)field) & value;
        case "OR":
            return ((int)field) | value;
        case "XOR":
            return ((int)field) ^ value;
        default:
            return field;
    }
}
