public ScheduledExecutorService createHousekeepingService(HikariConfig hikariConfig) {
    ScheduledExecutorService scheduledExecutorService = hikariConfig.getScheduledExecutorService();

    if (scheduledExecutorService != null) {
        return scheduledExecutorService;
    } else {
        int threadPoolSize = hikariConfig.getThreadPoolSize();
        ThreadFactory threadFactory = Optional.ofNullable(hikariConfig.getThreadFactory())
                                               .orElseGet(HikariThreadFactory::defaultThreadFactory);
        ScheduledThreadPoolExecutor executor = new ScheduledThreadPoolExecutor(threadPoolSize, threadFactory);
        executor.setExecuteExistingDelayedTasksAfterShutdownPolicy(false);
        executor.setRemoveOnCancelPolicy(true);
        return executor;
    }
}
