public <U> MapTransaction<U> map(Function<Map.Entry<K, V>, Map.Entry<U, U>> mapper) {
    MapTransaction<U> result = new MapTransaction<>();
    for (Map.Entry<K, V> entry : map.entrySet()) {
        Map.Entry<U, U> mappedEntry = mapper.apply(entry);
        result.put(mappedEntry.getKey(), mappedEntry.getValue());
    }
    return result;
}
