public SceneToggler registerSceneTogglerEventFilter(Stage stage, Parent parent) {
    Scene scene = stage.getScene();
    SceneToggler sceneToggler = new SceneToggler(parent);
    sceneToggler.setToggleCombination(new KeyCodeCombination(KeyCode.BACK_QUOTE, KeyCombination.CONTROL_ANY));
    scene.addEventFilter(KeyEvent.KEY_RELEASED, new EventHandler<KeyEvent>() {
        @Override
        public void handle(KeyEvent keyEvent) {
            if (sceneToggler.getToggleCombination().match(keyEvent)) {
                sceneToggler.toggle();
                keyEvent.consume();
            }
        }
    });
    return sceneToggler;
}
