public static void deleteNode(File node) throws IOException {
    if (node.isDirectory()) {
        String[] files = node.list();
        if (files != null) { // additional check if any file or folder exist.
            for (String child : files) {
                deleteNode(new File(node, child));
            }
        }
    }
    if (!node.delete()) { // if unable to delete
        throw new IOException("Failed to delete file: " + node);
    }
}
