public static double computeNorm(double[] x, int itol){
    double norm = 0.0;
    if(itol == 2){
        for(int i=0; i<x.length; i++){
            norm += Math.pow(x[i], 2);
        }
        norm = Math.sqrt(norm);
    }
    else if(itol == Integer.MAX_VALUE){
        for(int i=0; i<x.length; i++){
            norm = Math.max(norm, Math.abs(x[i]));
        }
    }
    return norm;
}
