			if (xmlStream == null) {
				File xmlFile = new File(xmlPath);
				xmlStream = new FileInputStream(xmlFile);
			}

			validateXMLSchema(xsdStream, xmlStream);

		} finally {
			if (xsdStream != null) {
				try {
					xsdStream.close();
