public static StringBuilder appendAttributeValue(String value, StringBuilder buf) {
    if (value == null) {
        return buf;
    }

    buf.append('"');
    for (int i = 0; i < value.length(); i++) {
        char c = value.charAt(i);
        if (c == '\\' || c == '"') {
            buf.append('\\');
        }
        buf.append(c);
    }
    buf.append('"');

    return buf;
}
