public static String removeTrailingLineEnd(String text, boolean formalRTF) {
    if (formalRTF) {
        text = text.replaceAll("\\r\\n", "\r").replaceAll("\\n", "\r");
    } else {
        text = text.replaceAll("\\r\\n|\\n", "");
    }
    return text.replaceAll("\\r*$", "");
}
