public String getSourceLine(int lineNumber) {
    try {
        BufferedReader reader = new BufferedReader(new FileReader("file.txt"));
        int currentLine = 1;
        String line;
        while ((line = reader.readLine()) != null) {
            if (currentLine == lineNumber) {
                reader.close();
                return line;
            }
            currentLine++;
        }
        reader.close();
    } catch (IOException e) {
        return null;
    }
    return null;
}
