import java.util.HashMap;
import java.util.Map;
import javax.management.*;
import javax.management.remote.*;

public Map<String, Object> getMBeanResult(String mbeanName) throws Exception {
    Map<String, Object> result = new HashMap<>();

    JMXServiceURL serviceUrl = new JMXServiceURL("service:jmx:rmi:///jndi/rmi://localhost:1099/jmxrmi");
    JMXConnector jmxConnector = JMXConnectorFactory.connect(serviceUrl);

    MBeanServerConnection mbeanConn = jmxConnector.getMBeanServerConnection();
    ObjectName mbeanObjectName = new ObjectName(mbeanName);

    MBeanInfo mbeanInfo = mbeanConn.getMBeanInfo(mbeanObjectName);
    MBeanAttributeInfo[] mbeanAttrs = mbeanInfo.getAttributes();

    for (MBeanAttributeInfo attr : mbeanAttrs) {
        String attrName = attr.getName();
        Object value = mbeanConn.getAttribute(mbeanObjectName, attrName);
        result.put(attrName, value);
    }

    return result;
}
