public static Object makeArray(String dtype, List<String> stringValues) throws NumberFormatException {
    switch (dtype) {
        case "int":
            int[] intArr = new int[stringValues.size()];
            for (int i = 0; i < stringValues.size(); i++) {
                intArr[i] = Integer.parseInt(stringValues.get(i));
            }
            return intArr;
        case "double":
            double[] doubleArr = new double[stringValues.size()];
            for (int i = 0; i < stringValues.size(); i++) {
                doubleArr[i] = Double.parseDouble(stringValues.get(i));
            }
            return doubleArr;
        case "float":
            float[] floatArr = new float[stringValues.size()];
            for (int i = 0; i < stringValues.size(); i++) {
                floatArr[i] = Float.parseFloat(stringValues.get(i));
            }
            return floatArr;
        case "long":
            long[] longArr = new long[stringValues.size()];
            for (int i = 0; i < stringValues.size(); i++) {
                longArr[i] = Long.parseLong(stringValues.get(i));
            }
            return longArr;
        case "short":
            short[] shortArr = new short[stringValues.size()];
            for (int i = 0; i < stringValues.size(); i++) {
                shortArr[i] = Short.parseShort(stringValues.get(i));
            }
            return shortArr;
        case "byte":
            byte[] byteArr = new byte[stringValues.size()];
            for (int i = 0; i < stringValues.size(); i++) {
                byteArr[i] = Byte.parseByte(stringValues.get(i));
            }
            return byteArr;
        case "boolean":
            boolean[] boolArr = new boolean[stringValues.size()];
            for (int i = 0; i < stringValues.size(); i++) {
                boolArr[i] = Boolean.parseBoolean(stringValues.get(i));
            }
            return boolArr;
        default:
            throw new NumberFormatException("Unknown dtype: " + dtype);
    }
}
