public class HelloREEF {

    public static void startJob(String[] args) throws InjectionException {

        Configuration runtimeConfig = LocalDriverRuntimeConfiguration.CONF.build();
        Configuration driverConfig = DriverConfiguration.CONF.build();
        Configuration driverAndRuntimeConfig = Configurations.merge(driverConfig, runtimeConfig);
        Configuration partialLauncherConfig = LauncherConfiguration.CONF
                .set(REED_DRIVER_CONF, driverAndRuntimeConfig).build();

        ReefService reef = new Builder().withConfigurations(partialLauncherConfig).build();
        reef.run();
    }
}
