public SoapFault constructSoapFault(String faultCode, String faultString, String faultDetail) {
    QName faultCodeQName = new QName(SOAPConstants.URI_NS_SOAP_1_1_ENVELOPE, faultCode);
    SoapFault soapFault = new SoapFault(faultString, faultCodeQName);

    if (faultDetail != null && !faultDetail.isEmpty()) {
        QName faultDetailQName = new QName(SOAPConstants.URI_NS_SOAP_1_1_ENVELOPE, "detail");
        Detail detail = soapFault.addDetail();
        detail.addSoapFaultDetailElement(faultDetailQName).addTextNode(faultDetail);
    }

    return soapFault;
}
