public Map<Integer, Spectrum> unloadSpectra(Map<Integer, Spectrum> scansInSubsetByNumber, Set<String> subset, Set<String> exclude) {
    Map<Integer, Spectrum> unloadedScans = new HashMap<>();
    for (Map.Entry<Integer, Spectrum> entry : scansInSubsetByNumber.entrySet()) {
        Integer scanNumber = entry.getKey();
        Spectrum spectrum = entry.getValue();
        boolean isSubsetMatch = false;
        boolean isExcludeMatch = false;
        for (String subsetMatch : subset) {
            if (spectrum.matches(subsetMatch)) {
                isSubsetMatch = true;
                break;
            }
        }
        if (!isSubsetMatch) {
            continue;
        }
        for (String excludeMatch : exclude) {
            if (spectrum.matches(excludeMatch)) {
                isExcludeMatch = true;
                break;
            }
        }
        if (isExcludeMatch) {
            continue;
        }
        unloadedScans.put(scanNumber, spectrum);
    }
    return unloadedScans;
}
