public String stripAndIncrement(String version) {
  String[] parts = version.split("\\.");
  int i = parts.length - 1;
  while (i >= 0) {
    int num = Integer.parseInt(parts[i]);
    if (num == 0) {
      parts[i] = "1";
      break;
    } else {
      parts[i] = "0";
    }
    i--;
  }
  return String.join(".", parts);
}
