import org.semanticweb.owlapi.model.DatatypeProperty;
import org.semanticweb.owlapi.model.OWLDataRange;
import org.semanticweb.owlapi.model.OWLOntology;

import java.util.HashMap;
import java.util.Map;

public class MappingDataTypeRepair {
   public Map<DatatypeProperty, OWLDataRange> getDataTypeFromOntology(OWLOntology ontology) {
       Map<DatatypeProperty, OWLDataRange> datatypeMap = new HashMap<>();
       ontology.axioms().forEach(axiom -> {
           if (axiom.getDatatypeDefinition() != null) {
               OWLDataRange range = axiom.getDatatypeDefinition().getDatatype();
               axiom.getDatatypeDefinition().getDatatype().getBuiltInDatatype().ifPresent(builtIn ->
                       axiom.getDatatypeDefinition().getDatatype().getDataRange().getBound()
                               .filter(bound -> bound.isFinite() && bound.asLong() <= 10)
                               .ifPresent(data -> datatypeMap.put(axiom.getDatatype(), range)));
           } else {
               axiom.nestedClassExpressions().forEach(expression -> {
                   if (expression.isDataRestricted()) {
                       expression.asDataRestrictedClass().ranges().forEach(range ->
                               datatypeMap.put((DatatypeProperty) expression.asDataRestrictedClass().getOnProperty(), range));
                   }
               });
           }
       });
       return datatypeMap;
   }
}
