public static double convertSpeed(double value, String outputUnit) {
    switch(outputUnit) {
        case "km/h":
            return value * 3.6;
        case "mi/h":
            return value * 2.23694;
        case "ft/s":
            return value * 3.28084;
        default:
            return value; // default to meters per second if the output unit is not recognized
    }
