public Match findMatchingPair(Session session, int level) {
    List<Request> requests = session.getRequests();

    for (int i = 0; i < requests.size() - 1; i++) {
        Request request1 = requests.get(i);
        Node host1 = request1.getHost();

        for (int j = i + 1; j < requests.size(); j++) {
            Request request2 = requests.get(j);
            Node host2 = request2.getHost();

            if (nodeManager.checkMatchingPair(host1, host2, level)) {
                return new Match(request1, request2);
            }
        }
    }

    return null;
}
