public static int[] generateMapping(int[] nodes) {
    int n = nodes.length;
    int[] parent = new int[n];
    parent[0] = -1;

    for (int i = 1; i < n; i++) {
        int node = nodes[i];
        int j = i - 1;

        while (j >= 0 && nodes[j] > node) {
            j--;
        }

        parent[i] = (j >= 0) ? j : -1;
    }

    return parent;
}
