public class DockerFileCreator {

    public static String createDockerFile(String destDir) throws IOException {
        String dockerFileName = "Dockerfile";
        String dockerFileContent = "FROM openjdk:8-jre-alpine\n" +
                "COPY ./app.jar /app/\n" +
                "CMD java $JAVA_OPTS -jar /app/app.jar\n";

        File dockerFile = new File(destDir, dockerFileName);
        FileWriter fileWriter = new FileWriter(dockerFile);
        try {
            fileWriter.write(dockerFileContent);
            return dockerFile.getAbsolutePath();
        } finally {
            fileWriter.close();
        }
    }
}
