public String generateProtobufCode(String code, String field, List<String> enumNames) {
     StringBuilder result = new StringBuilder();
     result.append("@Protobuf\n");
     result.append(code); // assuming code is already defined
     result.append(" "); // add space character for readability
     result.append(field);
     result.append(" = ");
     result.append(enumNames.get(0)); // assuming enumNames is not empty and at least one enum name exists
     for (int i = 1; i < enumNames.size(); i++) {
        result.append(" | ");
        result.append(enumNames.get(i));
     }
     result.append(";");
     return result.toString();
}
