public void readNextHeader(String headers, Map<String, String> header) {
    if (headers != null && !headers.isEmpty()) {
        int index = headers.indexOf("\n");
        if (index != -1) {
            String nextHeader = headers.substring(0, index);
            headers = headers.substring(index + 1);
            String[] parts = nextHeader.split(": ");
            if (parts.length == 2) {
                header.put(parts[0], parts[1]);
            }
        }
    }
}
