public boolean parseRangeHeader(FileRequestContext context) {
    String rangeHeader = context.getRequest().getHeader("Range");
    List<Range> ranges = new ArrayList<>();
    if (rangeHeader == null) {
        return true;
    }
    String[] rangeValues = rangeHeader.split("=")[1].split(",");
    for (String rangeValue : rangeValues) {
        String[] rangeParts = rangeValue.split("-");
        long start = Long.parseLong(rangeParts[0]);
        long end = rangeParts.length > 1 ? Long.parseLong(rangeParts[1]) : context.getFileLength() - 1;
        if (start > end || end >= context.getFileLength()) {
            return false;
        }
        ranges.add(new Range(start, end));
    }
    context.setRanges(ranges);
    return true;
}
