public Node buildTree(Node node, List<String> labels) throws Exception {
    if (node == null || labels == null || labels.isEmpty()) {
        throw new Exception("Invalid input parameters");
    }

    for (int i = 0; i < labels.size(); i++) {
        String label = labels.get(i);
        Node child = new Node(label);
        node.addChild(child);
        if (i < labels.size() - 1) {
            buildTree(child, labels.subList(i + 1, labels.size()));
        }
    }

    return node;
}
