public boolean isStrongParent(char[] chars, char[] latestNode) {
    boolean strongParent = true;
    // check if current parent is strong
    for (char c : chars) {
        if (c == '[' || c == '{' || c == '(') {
            strongParent = false;
            break;
        }
    }
    // check if latest inline node ends with a closing character of the parent
    if (latestNode[latestNode.length - 1] == chars[chars.length - 1]) {
        // check if the closing character(s) of the child should become (part of) the closing character(s) of the parent
        char[] newArray = new char[chars.length + latestNode.length - 1];
        System.arraycopy(chars, 0, newArray, 0, chars.length - 1);
        System.arraycopy(latestNode, 0, newArray, chars.length - 1, latestNode.length);
        for (int i = 0; i < newArray.length; i++) {
            if (newArray[i] == '[' && newArray[i+1] == ']') {
                System.arraycopy(newArray, i+2, newArray, i, newArray.length-i-2);
                newArray[newArray.length-2] = newArray[newArray.length-1] = ' ';
                i--;
            } else if (newArray[i] == '{' && newArray[i+1] == '}') {
                System.arraycopy(newArray, i+2, newArray, i, newArray.length-i-2);
                newArray[newArray.length-2] = newArray[newArray.length-1] = ' ';
                i--;
            } else if (newArray[i] == '(' && newArray[i+1] == ')') {
                System.arraycopy(newArray, i+2, newArray, i, newArray.length-i-2);
                newArray[newArray.length-2] = newArray[newArray.length-1] = ' ';
                i--;
            } else if (newArray[i] == '<') {
                while (newArray[i] != '>') {
                    i++;
                    if (i == newArray.length) {
                        break;
                    }
                }
            }
        }
        if (newArray[newArray.length - 1] != chars[chars.length - 1]) {
            strongParent = false;
        }
    }
    return strongParent;
}
