public String createRelativePath(String path, boolean withIndex) {
    String[] parts = path.split("/");
    StringBuilder relativePath = new StringBuilder();

    if (parts.length > 1 && !parts[0].isEmpty()) {
        for (int i = 0; i < parts.length - 1; i++) {
            if (withIndex) {
                relativePath.append(i).append("/");
            } else {
                relativePath.append(parts[i]).append("/");
            }
        }
        relativePath.append(parts[parts.length - 1]);
    } else {
        relativePath.append(parts[0]);
    }

    return relativePath.toString();
}
