public static int getMaxColumn(int[][] matrix, int col, Comparator<Integer> comparator) {
    int max = matrix[0][col];
    for (int i = 1; i < matrix.length; i++) {
        int currVal = matrix[i][col];
        if (comparator.compare(currVal, max) > 0) {
            max = currVal;
        }
    }
    return max;
}
