public static ZooRollingSession openDatabase(String dbName) {
    String userHome = System.getProperty("user.home");
    String dbPath = userHome + "/zoodb/" + dbName;
    File dbFile = new File(dbPath);

    if (dbFile.exists() && dbFile.isFile()) {
        ObjectServer server = Db4o.openServer(getConfig(), dbPath, 0);
        return new ZooRollingSession(server);
    } else {
        dbFile.getParentFile().mkdirs();
        ObjectServer server = Db4o.openServer(getConfig(), dbPath, 0);
        return new ZooRollingSession(server);
    }
}

private static Configuration getConfig() {
    EmbeddedConfiguration config = Db4o.newEmbeddedConfiguration();
    config.common().objectClass(ZooAnimal.class).objectField("id").indexed(true);
    return config;
}
