public static int compareVersions(String a, String b) {
    String[] versionA = a.split("\\.");
    String[] versionB = b.split("\\.");

    int maxLength = Math.max(versionA.length, versionB.length);

    for (int i = 0; i < maxLength; i++) {
        int num1 = i < versionA.length ? Integer.parseInt(versionA[i]) : 0;
        int num2 = i < versionB.length ? Integer.parseInt(versionB[i]) : 0;
        if (num1 < num2) {
            return -1;
        } else if (num1 > num2) {
            return 1;
        }
    }

    return 0;
}
