public void addQueryStringArguments(Request request, Map<String, String> queryStringArguments) {
    String queryString = "";
    if (queryStringArguments.size() > 0) {
        queryString += "?";
        for (String key : queryStringArguments.keySet()) {
            queryString += key + "=" + queryStringArguments.get(key) + "&";
        }
        queryString = queryString.substring(0, queryString.length() - 1);
    }
    request.setUrl(request.getUrl() + queryString);
}
