import org.apache.jena.rdf.model.*;
import org.rdfhdt.hdtjena.HDTJena;
import org.rdfhdt.hdtjena.NodeDictionary;

public static Triple convertTriple(String tripleId) {
  // Assume tripleId is a string in format "subject predicate object".
  String[] tripleComponents = tripleId.split(" ");
  String subject = tripleComponents[0];
  String predicate = tripleComponents[1];
  String object = tripleComponents[2];

  // Initialize Jena model and node dictionary.
  Model model = ModelFactory.createDefaultModel();
  NodeDictionary dictionary = ((HDTJena)model.getGraph()).getDictionary();

  // Convert string values to Jena nodes.
  Node subjNode = dictionary.getNode(subject);
  Node predNode = dictionary.getNode(predicate);
  Node objNode = dictionary.getNode(object);

  // Return the resulting triple.
  return new Triple(subjNode, predNode, objNode);
}
