public static List<Map<String, String>> convertToDirectRepresentation(List<List<String>> table) {

    List<Map<String, String>> tableDirect = new ArrayList<>();

    if (table != null && !table.isEmpty()) {
        List<String> headers = table.get(0);

        for (int i = 1; i < table.size(); i++) { // start from index 1 to skip headers
            List<String> rowValues = table.get(i);
            Map<String, String> rowDirect = new HashMap<>();

            for (int j = 0; j < rowValues.size(); j++) {
                String columnHeader = headers.get(j);
                String cellValue = rowValues.get(j);
                rowDirect.put(columnHeader, cellValue);
            }
            tableDirect.add(rowDirect);
        }
    }

    return tableDirect;
}
