public void lockDatasets(Object[] datasets) {
    // Iterate over each dataset object
    for (Object dataset : datasets) {
        // Ensure the dataset is not null
        if (dataset != null) {
            // Check if the dataset supports deletion
            if (dataset instanceof Deletable) {
                // Cast the dataset to its Deletable interface
                Deletable deletableDataset = (Deletable) dataset;
                // Lock the dataset against deletions
                deletableDataset.setLocked(true);
            }
            else {
                // Throw an exception if the dataset does not support deletion
                throw new UnsupportedOperationException("Dataset does not support deletion");
            }
        }
        else {
            // Throw an exception if the dataset is null
            throw new IllegalArgumentException("Dataset cannot be null");
        }
    }
}
