public boolean moveToNextKey() {
    if (!iterator.hasNext()) {
        return false;
    }
    Object currentKey = iterator.next().getKey();
    while (iterator.hasNext()) {
        if (!iterator.next().getKey().equals(currentKey)) {
            iterator.previous();
            return true;
        }
    }
    return true;
}
