public byte[] readBytes(int len) throws Exception {
    byte[] bytes = new byte[len];
    int bytesRead = 0;
    while (bytesRead < len) {
        int count = inputStream.read(bytes, bytesRead, len - bytesRead);
        if (count == -1) {
            throw new Exception("Not enough data is present");
        }
        bytesRead += count;
    }
    return bytes;
}
