public void parseMessage(String input, StringBuilder builder) {
    String[] fields = input.split(";"); // splitting the input message into fields using the semicolon as delimiter

    for (String field : fields) {
        int separatorIndex = field.indexOf(":"); // finding the index of the separator character ':'

        if (separatorIndex > 0) {
            String name = field.substring(0, separatorIndex); // getting the name part
            String value = field.substring(separatorIndex + 1); // getting the value part

            // appending the name and value to the StringBuilder
            builder.append(name).append(" = ").append(value).append(System.lineSeparator());
        }
    }
}
