public synchronized void concurrentAddition(long sequence, long toAdd) {
    // Check if the current sequence + toAdd exceeds Long.MAX_VALUE
    if (sequence + toAdd < sequence) {
        throw new IllegalArgumentException("Delta to add would cause sequence to exceed Long.MAX_VALUE");
    }
    sequence += toAdd;
}
