import java.util.List;
import org.bitcoinj.core.NetworkParameters;
import org.bitcoinj.core.Transaction;
import org.bitcoinj.core.TransactionInput;
import org.bitcoinj.core.TransactionOutput;
import org.bitcoinj.script.Script;
import org.bitcoinj.script.ScriptOpCodes;

public List<Transaction> parseTransactions(NetworkParameters params, String paymentMessage) {
    List<Transaction> transactions = new ArrayList<>();
    byte[] payload = Utils.HEX.decode(paymentMessage);
    int cursor = 0;
    while (cursor < payload.length) {
        Transaction t = new Transaction(params);
        int txLen = (int) Utils.readUint32(payload, cursor);
        cursor += 4;
        byte[] txBytes = Arrays.copyOfRange(payload, cursor, cursor + txLen);
        t.bitcoinSerialize(txBytes);
        cursor += txLen;
        if (!t.getInputs().isEmpty()) {
            for (TransactionInput in : t.getInputs()) {
                Script script = in.getScriptSig();
                if (script.getProgram().length == 0 ||
                        script.getProgram()[0] != ScriptOpCodes.OP_RETURN) {
                    throw new RuntimeException("Unexpected input script type");
                }
            }
        }
        if (!t.getOutputs().isEmpty()) {
            for (TransactionOutput out : t.getOutputs()) {
                if (out.getScriptPubKey().isSentToRawPubKey() ||
                        out.getScriptPubKey().isSentToAddress()) {
                    // Valid type of output
                } else {
                    throw new RuntimeException("Unexpected output script type");
                }
            }
        }
        transactions.add(t);
    }
    return transactions;
}
