public NamespaceEntity getNamespaceEntity(EntityManager em, String qualifier) {
    if(em == null || qualifier == null || qualifier.isEmpty()) {
        return null;
    }
    try {
        Query query = em.createQuery("SELECT n FROM NamespaceEntity n WHERE n.qualifier = :qualifier");
        query.setParameter("qualifier", qualifier);
        NamespaceEntity namespaceEntity = (NamespaceEntity)query.getSingleResult();
        return namespaceEntity;
    } catch(NoResultException e) {
        return null;
    }
}
