  public static void writeJarToStream(File jarFile, OutputStream outputStream) throws IOException {
      try (JarFile jar = new JarFile(jarFile)) {
          jar.stream().forEach(entry -> {
              try {
                  outputStream.write(entry.getBytes());
              } catch (IOException e) {
                  throw new RuntimeException("Failed to write entry: " + entry.getName(), e);
              }
          });
      } finally {
          outputStream.close();
      }
  }
}
