public boolean reduceFetchSizeAndRetryQuery(int initialFetchSize, int minFetchSize, int frameSize, String query) {
    int currentFetchSize = initialFetchSize;
    while (currentFetchSize >= minFetchSize) {
        try {
            // execute the query with current fetch size
            executeQuery(query, currentFetchSize);
            return true;
        } catch (Exception e) {
            if (isFrameSizeIssue(e)) {
                // reduce the fetch size and retry the query
                currentFetchSize = Math.max(currentFetchSize - frameSize, minFetchSize);
            } else {
                return false;
            }
        }
    }
    return false;
}

