public static <T> String join(Iterable<T> iterable, char separator) {
    StringBuilder sb = new StringBuilder();
    for (Iterator<T> iterator = iterable.iterator(); iterator.hasNext();) {
        T element = iterator.next();
        sb.append(element);
        if (iterator.hasNext()) {
            sb.append(separator);
        }
    }
    return sb.toString();
}
