public class PropertiesUtil {

    public static Properties overrideWithDockerProperties(Properties p) throws IOException {
        Properties dockerProperties = loadPropertiesFromFile(System.getProperty("user.home") + "/.docker.io.properties");
        dockerProperties.putAll(p);
        return dockerProperties;
