public void deleteFromLDAP(String name) throws EntityHasDescendantsException, EntityNotFoundException, WIMSystemException {
    try {
        // initialize LDAP context
        DirContext context = new InitialDirContext();

        // delete the given name from the LDAP tree
        context.destroySubcontext(name);
    } catch (NameNotFoundException e) {
        // part of the name cannot be found to destroy the entity
        throw new EntityNotFoundException(e.getMessage());
    } catch (NotEmptyException e) {
        // context being destroyed is not empty
        throw new EntityHasDescendantsException(e.getMessage());
    } catch (NamingException e) {
        // any other NamingException occurs or the context cannot be released
        throw new WIMSystemException(e.getMessage());
    }
}
