public static <T> int findIntersectionIndex(Range range, List<TimePhasedResourceAssignment<T>> assignments, int startIndex) {
    for (int i = startIndex; i < assignments.size(); i++) {
        TimePhasedResourceAssignment<T> assignment = assignments.get(i);
        if (assignment.getTimephasedData().getStart().isAfter(range.getEnd())) {
            break;
        }
        if (assignment.getTimephasedData().getEnd().isAfter(range.getStart())) {
            return i;
        }
    }
    return -1;
}
