public Map<String, Integer> generateHistogramBuckets(double rval, Date from, Date to, int interval) {
    Map<String, Integer> histogramBuckets = new LinkedHashMap<>();
    Calendar calendar = Calendar.getInstance();
    calendar.setTime(from);
    while (calendar.getTime().before(to)) {
        SimpleDateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
        String key = dateFormat.format(calendar.getTime());
        histogramBuckets.put(key, 0);
        calendar.add(Calendar.MINUTE, interval);
    }
    return histogramBuckets;
}
