public void augmentSelection(StateEngine stateEngine, Set<Record> matches) {
    Set<Record> referencedRecords = new HashSet<>();
    Set<Record> newMatches = new HashSet<>(matches);
    for (Record record : matches) {
        referencedRecords.addAll(stateEngine.getReferencedRecords(record));
    }
    while (!referencedRecords.isEmpty()) {
        Set<Record> newReferences = new HashSet<>();
        for (Record record : referencedRecords) {
            if (!newMatches.contains(record)) {
                newMatches.add(record);
                newReferences.addAll(stateEngine.getReferencedRecords(record));
            }
        }
        referencedRecords = newReferences;
    }
    matches.addAll(newMatches);
}
