public static double[] solveLinearEquation(double[][] matrixA, double[] vectorB) {
    int n = matrixA.length;
    double[] result = new double[n];

    // Decompose matrix A into Lower Triangular and Upper Triangular matrix
    double[][] L = new double[n][n];
    double[][] U = new double[n][n];
    for (int i = 0; i < n; i++) {
        L[i][i] = 1.0;
        for (int j = i; j < n; j++) {
            double sum = 0.0;
            for (int k = 0; k < i; k++) {
                sum += L[i][k] * U[k][j];
            }
            U[i][j] = matrixA[i][j] - sum;
        }
        for (int j = i + 1; j < n; j++) {
            double sum = 0.0;
            for (int k = 0; k < i; k++) {
                sum += L[j][k] * U[k][i];
            }
            L[j][i] = (matrixA[j][i] - sum) / U[i][i];
        }
    }

    // Solve equation L*Y = B for Y
    double[] Y = new double[n];
    for (int i = 0; i < n; i++) {
        double sum = 0.0;
        for (int j = 0; j < i; j++) {
            sum += L[i][j] * Y[j];
        }
        Y[i] = (vectorB[i] - sum) / L[i][i];
    }

    // Solve equation U*X = Y for X
    for (int i = n - 1; i >= 0; i--) {
        double sum = 0.0;
        for (int j = i + 1; j < n; j++) {
            sum += U[i][j] * result[j];
        }
        result[i] = (Y[i] - sum) / U[i][i];
    }

    return result;
}
