public void writeToCache(BufferedWriter writer, File f, BufferedReader bf){
    try {
        String line;
        while ((line = bf.readLine()) != null) {
            writer.write(line);
        }
        writer.flush();
        writer.close();
    } catch (IOException e) {
        System.out.println("An IOException occurred while writing to cache: " + e.getMessage());
    }
}
