public Member postConstructionInit(Group group) {
    List<Member> nonDroppedMembers = group.getNonDroppedMembers();
    Member primaryMember = nonDroppedMembers.get(0);
    for (int i = 1; i < nonDroppedMembers.size(); i++) {
        Member member = nonDroppedMembers.get(i);
        member.setMirror(primaryMember);
        primaryMember.setMirror(member);
    }
    return primaryMember;
}
