public static void importDeclaration(String importStatement) {
    String[] parts = importStatement.split("\\s+");
    int len = parts.length;
    if (len < 2 || len > 4) {
        throw new IllegalArgumentException("Invalid import statement");
    }
    if (!parts[0].equals("import")) {
        throw new IllegalArgumentException("Invalid import statement, should start with 'import'");
    }
    if (len == 3 && !parts[1].equals("static")) {
        throw new IllegalArgumentException("Invalid import statement, 'static' keyword expected");
    }
    String identifier = parts[len - 2]; // get the identifier
    if (identifier.contains(".")) {
        throw new IllegalArgumentException("Invalid import statement, identifier should not contain a dot");
    }
    String withStar = parts[len - 1]; // get the last part containing '*' if present
    if (!withStar.equals(";")) {
        if (!withStar.equals("*;") || len != 4) {
            throw new IllegalArgumentException("Invalid import statement, '*' or ';' expected");
        }
    }
    System.out.println("Import declaration for: " + parts[1] + " " + identifier + " " + withStar);
}
