public List<DependencyInfo> collectChildren(DependencyInfo dependencyInfo) {
    List<DependencyInfo> children = new ArrayList<>();

    if (dependencyInfo.getChildren() != null && !dependencyInfo.getChildren().isEmpty()) {
        for (DependencyInfo child : dependencyInfo.getChildren()) {
            children.add(child);
            children.addAll(collectChildren(child));
        }
    }

    return children;
}
