public static Object deserializeByteArray(byte[] byteArray, Class<?> expectedType) throws IOException {
    ObjectInputStream ois = null;
    try {
        ois = new ObjectInputStream(new ByteArrayInputStream(byteArray));
        Object obj = ois.readObject();
        if (!expectedType.isInstance(obj)) {
            throw new ClassCastException("Deserialized object is not of expected type: " + expectedType.getName());
        }
        return obj;
    } catch (ClassNotFoundException | IOException | ClassCastException ex) {
        throw new IOException("Failed to deserialize object", ex);
    } finally {
        if (ois != null) {
            ois.close();
        }
    }
}
