public static Object removeAtIndex(Object[] arr, int index) {
    if (index < 0 || index >= arr.length) {
        return null;
    }
    Object value = arr[index];
    System.arraycopy(arr, index + 1, arr, index, arr.length - index - 1);
    arr[arr.length - 1] = null;
    return value;
}
