public class DocBookParser {
  public static String findFirstTitle(String xml) throws Exception {
    DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
    DocumentBuilder builder = factory.newDocumentBuilder();
    Document doc = builder.parse(new File(xml));
    NodeList titleElements = doc.getElementsByTagName("title");

    if (titleElements.getLength() > 0) {
      return titleElements.item(0).getTextContent().trim();     
    } else {
      return "Title not found.";
    }
  }
}
