public List<byte[]> sendRequestAndGetReplies(DatagramSocket datagramSocket, byte[] rqstBytes, int timeout) throws IOException {
    List<byte[]> replies = new ArrayList<>();
    DatagramPacket requestPacket = new DatagramPacket(rqstBytes, rqstBytes.length);
    datagramSocket.send(requestPacket);
    datagramSocket.setSoTimeout(timeout);
    while (true) {
        try {
            byte[] buffer = new byte[1024];
            DatagramPacket replyPacket = new DatagramPacket(buffer, buffer.length);
            datagramSocket.receive(replyPacket);
            replies.add(Arrays.copyOf(buffer, replyPacket.getLength()));
        } catch (SocketTimeoutException e) {
            break;
        }
    }
    return replies;
}
