import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.ObjectOutputStream;
import java.nio.ByteOrder;
import java.util.List;

public class MyClass {

    public byte[] writeToByteArray(ObjectOutputStream out, ByteOrder order, FieldType type, Object o, List<?> list) throws IOException {
        ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();

        // Set the byte order if needed
        if (order != null) {
            out.writeByte((order == ByteOrder.BIG_ENDIAN) ? 0 : 1);
        }

        // Write the object to the byte array
        switch (type) {
            case BYTE:
                out.writeByte((byte) o);
                break;
            case SHORT:
                out.writeShort((short) o);
                break;
            case INT:
                out.writeInt((int) o);
                break;
            case LONG:
                out.writeLong((long) o);
                break;
            case FLOAT:
                out.writeFloat((float) o);
                break;
            case DOUBLE:
                out.writeDouble((double) o);
                break;
            case STRING:
                out.writeUTF((String) o);
                break;
            case OBJECT:
                out.writeObject(o);
                break;
            case LIST:
                out.writeObject(list);
                break;
            // Handle other field types
        }

        // Return the byte array
        return byteArrayOutputStream.toByteArray();
    }

    // Define the FieldType enum
    private enum FieldType {
        BYTE,
        SHORT,
        INT,
        LONG,
        FLOAT,
        DOUBLE,
        STRING,
        OBJECT,
        LIST,
        // Add other field types if needed
    }
}
