public class FileCallableResolver {
    public static <T> Callable<T> resolve(final FilePath filePath, final FileCallable<T> fileCallable) {
        return new Callable<T>() {
            public T call() throws Exception {
                return filePath.act(fileCallable);
            }

            public void run() throws Exception {
                call();
            }

            public Class<? extends T> getClass(Object instance) {
                return instance.getClass();
            }

            public void checkRoles(RoleChecker checker) throws SecurityException {
                checker.check(this, Roles.SLAVE);
            }

            public T execute(VirtualChannel channel) throws Exception, InterruptedException {
                return call();
            }
        };
    }
}
