public double[] rescaleCoordinates(Atom atom1, Atom atom2, double[] point2) {
    double covalentRadius1 = atom1.getCovalentRadius();
    double covalentRadius2 = atom2.getCovalentRadius();
    double bondLength = covalentRadius1 + covalentRadius2;
    if (Double.isNaN(bondLength)) {
        bondLength = 1.0;
    }
    double deltaX = point2[0] - atom2.getX();
    double deltaY = point2[1] - atom2.getY();
    double deltaZ = point2[2] - atom2.getZ();
    double scaleFactor = bondLength / Math.sqrt(deltaX * deltaX + deltaY * deltaY + deltaZ * deltaZ);
    double[] newCoords = new double[3];
    newCoords[0] = atom2.getX() + deltaX * scaleFactor;
    newCoords[1] = atom2.getY() + deltaY * scaleFactor;
    newCoords[2] = atom2.getZ() + deltaZ * scaleFactor;
    return newCoords;
}
