public void buildSitesFromStructSiteGen(Structure structure, List<StructSiteGen> structSiteGens) {
    for (StructSiteGen structSiteGen : structSiteGens) {
        Chain chain = structure.getChainByPDB(structSiteGen.getChainId());
        if (chain != null) {
            Residue startResidue = chain.getResidueByPDB(
                structSiteGen.getOneLetterCodeStart() + structSiteGen.getStartResidueNumber()
            );
            Residue endResidue = chain.getResidueByPDB(
                structSiteGen.getOneLetterCodeEnd() + structSiteGen.getEndResidueNumber()
            );
            if (startResidue != null && endResidue != null) {
                Site site = new Site(structSiteGen.getSiteId(), startResidue, endResidue);
                site.setDescription(structSiteGen.getDescription());
                site.setComment(structSiteGen.getComment());
                structure.addSite(site);
            }
        }
    }
}
