public String checkInputHandlers(InputHandler[] inputHandlers) throws SQLException {
    String queryString = null;
    for (InputHandler inputHandler : inputHandlers) {
        if (queryString == null) {
            queryString = inputHandler.getQueryString();
        } else if (!queryString.equals(inputHandler.getQueryString())) {
            throw new SQLException("SQL Query string is not the same among whole array of InputHandler");
        }
    }
    if (queryString == null) {
        throw new SQLException("No InputHandler instance is found in the array");
    }
    return queryString;
}
