public List<DNSView> fetchFilteredDNSViews(String filterString) {
    List<DNSView> filteredViews = new ArrayList<>();
    JsonObject filterJson = JsonParser.parseString(filterString).getAsJsonObject();

    // Assuming we have a list of all DNS views, we iterate through them and check if each view matches the filter
    for (DNSView view : allDNSViews) {
        if (viewMatchesFilter(view, filterJson)) {
            filteredViews.add(view);
        }
    }

    return filteredViews;
}

private boolean viewMatchesFilter(DNSView view, JsonObject filterJson) {
    for (Map.Entry<String, JsonElement> entry : filterJson.entrySet()) {
        String filterKey = entry.getKey();
        String filterValue = entry.getValue().getAsString();
        if (!viewContainsFilterValue(view, filterKey, filterValue)) {
            return false;
        }
    }
    return true;
}

private boolean viewContainsFilterValue(DNSView view, String filterKey, String filterValue) {
    switch (filterKey) {
        case "port":
            return view.getPort() == Integer.parseInt(filterValue);
        case "servicetype":
            return view.getServiceType().equals(filterValue);
        // add more cases for each field that can be filtered on
        default:
            throw new IllegalArgumentException("Unsupported filter key: " + filterKey);
    }
}
