public static String getTagValue(String pData, String pTag) {
    String startTag = "<" + pTag + ">";
    String endTag = "</" + pTag + ">";
    int startIndex = pData.indexOf(startTag);
    if (startIndex < 0)
        return null;
    startIndex += startTag.length();
    int endIndex = pData.indexOf(endTag, startIndex);
    if (endIndex < 0)
        return null;
    return pData.substring(startIndex, endIndex).trim();
}
