public List<String> buildCommandListFromComments(Sheet sheet, int sheetRightCol, Map<String, String> cellAttributesMap) {
    List<String> commandList = new ArrayList<>();
    Iterator<Row> rowIterator = sheet.iterator();

    while (rowIterator.hasNext()) {
        Row row = rowIterator.next();
        Iterator<Cell> cellIterator = row.iterator();
        while (cellIterator.hasNext()) {
            Cell cell = cellIterator.next();
            String cellValue = cell.getStringCellValue();
            if (cellValue.startsWith("#")) {
                String[] parts = cellValue.substring(1).trim().split("\\s+", 2);
                String command = parts[0].toLowerCase();
                String arguments = "";
                if (parts.length > 1) {
                    arguments = parts[1];
                }
                cell.setCellValue("");
                cellAttributesMap.put(cell.getAddress().formatAsString(), arguments);
                commandList.add(command);
            }
        }
    }
    return commandList;
}
