/**
 * Gets the remaining JSDoc line without the {@link JsDocToken#EOL},
 * {@link JsDocToken#EOF} or {@link JsDocToken#EOC}.
 *
 * @return the remaining JSDoc line
 */
public String getRemainingJsDocLine() {
    StringBuilder sb = new StringBuilder();
    char currentChar = readNextChar();
    while (currentChar != JsDocToken.EOF && currentChar != JsDocToken.EOL && currentChar != JsDocToken.EOC) {
        sb.append(currentChar);
        currentChar = readNextChar();
    }
    return sb.toString();
}
