public static void packLong(OutputStream out, long value) throws IOException {
    if (value < 0) {
        throw new IllegalArgumentException("Value must be non-negative");
    }
    int numBytes = 1;
    long maxValue = 0x80;  // 0x80 = 128, the maximum value of a signed byte
    while (value >= maxValue && numBytes < 10) {
        maxValue <<= 7;
        numBytes++;
    }
    while (numBytes > 1) {
        out.write((byte) ((value >>> (7 * (numBytes - 1))) | 0x80));
        numBytes--;
    }
    out.write((byte) value);
}
