public Node insertEjbRefsBeforeEjbLocalRef(Node parent) {
    Node ejbRefNode = null;
    NodeList childNodes = parent.getChildNodes();
    for (int i = 0; i < childNodes.getLength(); i++) {
        Node node = childNodes.item(i);
        if ("ejb-ref".equals(node.getNodeName())) {
            ejbRefNode = node;
            break;
        }
        if ("ejb-local-ref".equals(node.getNodeName())) {
            break;
        }
    }
    if (ejbRefNode == null) {
        ejbRefNode = parent.getFirstChild();
    }
    return ejbRefNode;
}
