import java.nio.file.Path;
import java.nio.file.PathMatcher;
import java.nio.file.Paths;
import java.nio.file.FileSystems;
import java.nio.file.attribute.BasicFileAttributes;
import java.io.IOException;
import java.util.Set;
import java.util.HashSet;
import java.io.File;
import java.nio.file.FileVisitResult;
import java.nio.file.FileVisitor;

public class Filter implements PathFilter {

    private Set<PathMatcher> matchers;
    private boolean acceptOnMatch;
    private boolean rejectOnNoMatch;

    Filter(Set<String> filterPaths, boolean acceptOnMatch, boolean rejectOnNoMatch) {
        matchers = new HashSet<>();
        filterPaths.forEach(pathString -> this.matchers.add(Paths.get(pathString)));
        this.acceptOnMatch = acceptOnMatch;
        this.rejectOnNoMatch = rejectOnNoMatch;
    }

    public boolean accept(Path path) {
        for (PathMatcher matcher : matchers) {
            if (matcher.matches(path)) {
                return acceptOnMatch;
            }
        }
        return rejectOnNoMatch;
    }

    public static void main(String[] args) {

        if(args.length == 0) {
            System.out.println("Please provide a path.");
            return;
        }

        Path path = Paths.get(args[0]);
        FileVisitor<Path> visitor = new FileVisitor<Path>() {

            public FileVisitResult preVisitDirectory(Path dir, BasicFileAttributes attrs)
                                                        throws IOException {
                return Filter.this.accept(dir) ? FileVisitResult.CONTINUE
                                               : FileVisitResult.SKIP_SUBTREE;
            }

            public FileVisitResult visitFile(Path file, BasicFileAttributes attrs)
                                                        throws IOException {
                return Filter.this.accept(file) ? FileVisitResult.CONTINUE
                                                : FileVisitResult.TERMINATE;
            }

            public FileVisitResult visitFileFailed(Path file, IOException exc)
                                                        throws IOException {
                return acceptOnNoMatch() ? FileVisitResult.CONTINUE
                                         : FileVisitResult.TERMINATE;
            }

            public FileVisitResult postVisitDirectory(Path dir, IOException exc)
                                                        throws IOException {
                return acceptOnNoMatch() ? FileVisitResult.CONTINUE
                                         : FileVisitResult.TERMINATE;
            }
        };

        try {
            java.nio.file.Files.walkFileTree(path, visitor);
        } catch (IOException ex) {
            System.err.println("IOException : " + ex.getMessage());
        }
    }
}
