public static StringBuffer sanitizePath(String input) {
    StringBuffer output = new StringBuffer(input);

    // Remove quotation marks
    if (output.charAt(0) == '"' && output.charAt(input.length() - 1) == '"') {
        output.deleteCharAt(input.length() - 1);
        output.deleteCharAt(0);
    }

    // Replace "\\" with "/"
    for (int i = 0; i < output.length() - 1; i++) {
        if (output.charAt(i) == '\\' && output.charAt(i + 1) == '\\') {
            output.replace(i, i + 2, "/");
        }
    }

    // Replace remaining "\" with "/"
    for (int i = 0; i < output.length(); i++) {
        if (output.charAt(i) == '\\') {
            output.replace(i, i + 1, "/");
        }
    }

    return output;
}
