public List<String> readImports(File[] importFiles) {
    List<String> importSymbols = new ArrayList<String>();
    for (File importFile : importFiles) {
        try (BufferedReader reader = new BufferedReader(new FileReader(importFile))) {
            String line;
            while ((line = reader.readLine()) != null) {
                if (line.startsWith("import ")) {
                    String symbol = line.substring("import ".length(), line.lastIndexOf(';'));
                    importSymbols.add(symbol);
                }
            }
        } catch (IOException e) {
            System.err.println("Error reading import file: " + e.getMessage());
        }
    }
    return importSymbols;
}
