public String getKerberosChallenge() throws Exception {
    String challenge = null;
    Subject subject = Subject.getSubject(AccessController.getContext());
    if (subject == null) {
        throw new Exception("Subject not found");
    }
    KerberosTicket tgt = Subject.doAs(subject, new PrivilegedExceptionAction<KerberosTicket>() {
        @Override
        public KerberosTicket run() throws Exception {
            return (KerberosTicket) Subject.getSubject(AccessController.getContext())
                    .getPrivateCredentials(KerberosTicket.class).iterator().next();
        }
    });
    if (tgt != null) {
        challenge = "Kerberos " + new String(Base64.encodeBase64(tgt.getEncoded()), Charset.forName("UTF-8"));
    }
    return challenge;
}
