public Quaternion slerp(Quaternion a, Quaternion b, float percent) {
    // Ensure percent is within range [0, 1]
    percent = Math.min(Math.max(percent, 0), 1);

    // Calculate the angle between the two quaternions
    float dot = a.dot(b);
    if (dot < 0) {
        // If the dot product is negative, the quaternions are more than 90 degrees apart.
        // Flip one quaternion to take the shortest path around the sphere.
        b.negate();
        dot = -dot;
    }

    final float EPSILON = 0.0001f;
    if (1 - dot < EPSILON) {
        // If the quaternions are nearly identical, just return one of them.
        return a;
    }

    // Calculate the angle between the two quaternions
    float theta = (float) Math.acos(dot);
    float sinTheta = (float) Math.sin(theta);
    float sin1MinusPercentTheta = (float) Math.sin((1 - percent) * theta);
    float sinPercentTheta = (float) Math.sin(percent * theta);

    // The formula for spherical linear interpolation of quaternions.
    Quaternion interpolated = new Quaternion(
            (a.x * sin1MinusPercentTheta + b.x * sinPercentTheta) / sinTheta,
            (a.y * sin1MinusPercentTheta + b.y * sinPercentTheta) / sinTheta,
            (a.z * sin1MinusPercentTheta + b.z * sinPercentTheta) / sinTheta,
            (a.w * sin1MinusPercentTheta + b.w * sinPercentTheta) / sinTheta
            );

    // Normalize the interpolated quaternion and return it.
    return interpolated.normalize();
}
