private TreeTraversalAction traverseTree(Node node, boolean visibleOnly, TreeVisitor visitor) {
    if (node == null) {
        return TreeTraversalAction.CONTINUE;
    }
    if (visibleOnly && !node.isVisible()) {
        return TreeTraversalAction.CONTINUE;
    }
    visitor.visit(node);
    if (node instanceof Branch) {
        Branch branch = (Branch) node;
        switch (visitor.getTraversalType()) {
            case DEPTH_FIRST_PRE:
                for (Node child : branch.getChildren()) {
                    TreeTraversalAction action = traverseTree(child, visibleOnly, visitor);
                    if (action == TreeTraversalAction.TERMINATE) {
                        return action;
                    }
                }
                break;
            case DEPTH_FIRST_POST:
                for (Node child : branch.getChildren()) {
                    TreeTraversalAction action = traverseTree(child, visibleOnly, visitor);
                    if (action == TreeTraversalAction.TERMINATE) {
                        return action;
                    }
                }
                break;
            case BREADTH_FIRST:
                for (Node child : branch.getChildren()) {
                    if (visibleOnly && !child.isVisible()) {
                        continue;
                    }
                    visitor.enqueue(child);
                }
                break;
        }
    }
    return visitor.doWithNode(node);
}
