import java.lang.reflect.Field;
import java.lang.reflect.Modifier;
import java.util.ArrayList;
import java.util.List;

public class MyClass {

    public List<Class<?>> getValueTypes(ObjectTypeAttributeDefinition definition) {
        List<Class<?>> valueTypes = new ArrayList<>();
        try {
            Field[] fields = definition.getClass().getDeclaredFields();
            for (Field field : fields) {
                if (Modifier.isPrivate(field.getModifiers()) && field.getName().equals("valueTypes")) {
                    field.setAccessible(true);
                    valueTypes = (List<Class<?>>) field.get(definition);
                }
            }
        } catch (IllegalAccessException e) {
            e.printStackTrace();
        }
        return valueTypes;
    }
}
