public void writeLineToCsv(String[] columns) throws IOException {
    // Throw an exception if the columns array is null or has length zero
    if (columns == null || columns.length == 0) {
        throw new IllegalArgumentException("Columns array must not be empty or null");
    }

    // Write the columns to the CsvWriter
    for (int i = 0; i < columns.length; i++) {
        CsvWriter.write(columns[i]);
        if (i < columns.length - 1) {
            CsvWriter.write(",");
        }
    }
    CsvWriter.write("\n");
}
