public Pane asPaneWithCustomErrorLabel(String userReadableError, Exception exception) {
    StringWriter sw = new StringWriter();
    PrintWriter pw = new PrintWriter(sw);
    exception.printStackTrace(pw);
    String exceptionText = sw.toString();

    Label label = new Label(userReadableError);
    label.setStyle("-fx-font-size: 1.2em; -fx-font-weight: bold;");

    TextArea textArea = new TextArea(exceptionText);
    textArea.setEditable(false);
    textArea.setWrapText(true);
    textArea.setMaxHeight(Double.MAX_VALUE);

    VBox pane = new VBox();
    pane.setSpacing(5);
    pane.setFillWidth(true);
    pane.getChildren().addAll(label, textArea);

    return pane;
}
