public static GrayF32 convertInterleavedToF32(InterleavedF32 input, GrayF32 output) {
    if (output == null) {
        output = new GrayF32(input.width, input.height);
    }

    for (int y = 0; y < input.height; y++) {
        int index = input.stride * y;

        for (int x = 0; x < input.width; x++, index += input.numBands) {
            float sum = 0f;

            for (int band = 0; band < input.numBands; band++) {
                sum += input.data[index + band];
            }

            output.set(x, y, sum / input.numBands);
        }
    }

    return output;
}
