public static int gcd(int value1, int value2) {
    if (value1 == 0 && value2 == 0) {
        return 0;
    }

    value1 = Math.abs(value1);
    value2 = Math.abs(value2);

    while (value2 > 0) {
        int temp = value2;
        value2 = value1 % value2;
        value1 = temp;
    }

    return value1;
}
