public Map<String, Double> getAllCostDrivers(XTrace trace) {
   Map<String, Double> costDrivers = new HashMap<>();
   XAttributeMap attributes = trace.getAttributes();
   for (XAttribute attribute : attributes.values()) {
      if (attribute instanceof XAttributeMap) {
         Map<String, Double> nestedCostDrivers = getAllCostDrivers((XAttributeMap) attribute);
         for (Map.Entry<String, Double> entry : nestedCostDrivers.entrySet()) {
            String key = attribute.getKey() + "." + entry.getKey();
            Double value = entry.getValue();
            costDrivers.put(key, value);
         }
      } else if (attribute instanceof XAttributeLiteral) {
         String key = attribute.getKey();
         Double value = Double.parseDouble(((XAttributeLiteral) attribute).getValue());
         costDrivers.put(key, value);
      }
   }
   return costDrivers;
}

private Map<String, Double> getAllCostDrivers(XAttributeMap map) {
   Map<String, Double> costDrivers = new HashMap<>();
   for (XAttribute attribute : map.values()) {
      if (attribute instanceof XAttributeMap) {
         Map<String, Double> nestedCostDrivers = getAllCostDrivers((XAttributeMap) attribute);
         for (Map.Entry<String, Double> entry : nestedCostDrivers.entrySet()) {
            String key = attribute.getKey() + "." + entry.getKey();
            Double value = entry.getValue();
            costDrivers.put(key, value);
         }
      } else if (attribute instanceof XAttributeLiteral) {
         String key = attribute.getKey();
         Double value = Double.parseDouble(((XAttributeLiteral) attribute).getValue());
         costDrivers.put(key, value);
      }
   }
   return costDrivers;
}
