public String hideMultiLineDesc(String option, String desc) {
    String[] lines = desc.split("\\r?\\n");
    StringBuilder sb = new StringBuilder();
    sb.append(lines[0]);
    if (option.equals("--current-option--help")) {
        for (int i = 1; i < lines.length; i++) {
            sb.append("\n").append(lines[i]);
        }
    } else {
        sb.append("...");
    }
    return sb.toString();
}
