public void updateTask(Task task) throws ApplicationException {
    if(task == null) {
        throw new ApplicationException("Task cannot be null");
    }

    if(task.getStatus() == TaskStatus.TERMINAL && task.getEndTime() == null) {
        task.setEndTime(new Date());
    }

    ExecutionDAO executionDAO = new ExecutionDAO();
    executionDAO.updateTask(task);

    IndexDAO indexDAO = new IndexDAO();
    indexDAO.storeTask(task);
}
