public boolean isBestScoreGreaterThanNeighborhood(int[][] currentLayer, int[][] otherLayer, int row, int col) {
    int bestScore = currentLayer[row][col];
    int startRow = row - 1;
    int startCol = col - 1;

    for (int i = startRow; i < startRow + 3; i++) {
        for (int j = startCol; j < startCol + 3; j++) {
            if (i >= 0 && i < otherLayer.length && j >= 0 && j < otherLayer[0].length) {
                if (bestScore <= otherLayer[i][j]) {
                    return false;
                }
            }
        }
    }
    return true;
}
