public boolean hasBeans(String bdaId) {

    BeanManager beanManager = CDI.current().getBeanManager();
    Bean<?> bean = beanManager.getBeans(Object.class).iterator().next();
    CreationalContext<?> creationalContext = beanManager.createCreationalContext(bean);

    Set<Bean<?>> beans = beanManager.getBeans(Object.class, new BdaLiteral(bdaId));
    if (beans.isEmpty()) {
        return false;
    }

    for (Bean<?> bean : beans) {
        if (bean != null) {
            Object obj = beanManager.getReference(bean, Object.class, creationalContext);
            if (obj != null) {
                return true;
            }
        }
    }

    return false;
}

