@Override
public void handleResponse(HttpRequest request, HttpResponse response, boolean supportsRetry) throws IOException {
    int statusCode = response.getStatusCode();

    // Handle unsuccessful response
    if (statusCode >= 300 && statusCode < 400) {
        HttpHeaders headers = response.getHeaders();
        String location = headers.getLocation();
        if (location != null) {
            request.setUrl(new GenericUrl(location));
        }
    } else if (statusCode >= 400 && statusCode < 500) {
        // Handle client error
        throw new ClientRequestException(
            "Error response from server: " + statusCode, response);
    } else if (statusCode >= 500 && statusCode < 600) {
        // Handle server error
        throw new ServerException(
            "Error response from server: " + statusCode, response);
    }
}
