import org.w3c.dom.Node;
import java.util.ArrayList;
import java.util.Collection;

public Collection<Node> getAllChildElements(Node nd) throws SAXException {
    Collection<Node> elementNodes = new ArrayList<>();
    Node child = nd.getFirstChild();
    while (child != null) {
        if (child.getNodeType() == Node.ELEMENT_NODE) {
            elementNodes.add(child);
        } else if (child.getNodeType() == Node.TEXT_NODE && !child.getNodeValue().trim().isEmpty()) {
            throw new SAXException("All the children must be elements or white space text nodes.");
        }
        child = child.getNextSibling();
    }
    return elementNodes;
}
