public boolean checkRequiredTag(Map<String, List<String>> metadata, String tagName, String cardinality, List<String> possibleValues) {
    if (metadata.containsKey(tagName)) {
        List<String> tagValues = metadata.get(tagName);
        int count = tagValues.size();
        switch (cardinality) {
            case "1":
                if (count == 1 && possibleValues.contains(tagValues.get(0))) {
                    return true;
                } else {
                    return false;
                }
            case "0-1":
                if (count == 0 || (count == 1 && possibleValues.contains(tagValues.get(0)))) {
                    return true;
                } else {
                    return false;
                }
            case "0-n":
                for (String value : tagValues) {
                    if (!possibleValues.contains(value)) {
                        return false;
                    }
                }
                return true;
            default:
                return false;
        }
    } else {
        return false;
    }
}
