import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class TextSplitter {

    public static class TextSplitResult {
        public final String encodedText1;
        public final String encodedText2;
        public final List<String> uniqueStrings;

        public TextSplitResult(String encodedText1, String encodedText2, List<String> uniqueStrings) {
            this.encodedText1 = encodedText1;
            this.encodedText2 = encodedText2;
            this.uniqueStrings = uniqueStrings;
        }
    }

    public static TextSplitResult splitTexts(String text1, String text2) {
        String encodedText1 = encodeText(text1);
        String encodedText2 = encodeText(text2);
        List<String> uniqueStrings = getUniqueStrings(encodedText1 + encodedText2);
        uniqueStrings.add(0, ""); // add intentionally blank zeroth element
        return new TextSplitResult(encodedText1, encodedText2, uniqueStrings);
    }

    private static String encodeText(String text) {
        StringBuilder encodedText = new StringBuilder();
        for (int i = 0; i < text.length(); i++) {
            encodedText.append(Integer.toHexString(text.charAt(i))); // encode character as Unicode hexadecimal
        }
        return encodedText.toString();
    }

    private static List<String> getUniqueStrings(String text) {
        Set<String> uniqueStrings = new HashSet<>();

        int start = 0;
        for (int i = 0; i < text.length(); i++) {
            if (text.charAt(i) == '\n') {
                uniqueStrings.add(text.substring(start, i));
                start = i + 1;
            }
        }
        if (start < text.length()) {
            uniqueStrings.add(text.substring(start));
        }

        return new ArrayList<>(uniqueStrings);
    }
}
