public void runScript(String scriptText, String fileName, String[] args) {
    try {
        // Create a new compiler
        GroovyShell shell = new GroovyShell();

        // Create a new binding
        Binding binding = new Binding();

        // Set the command line arguments in the binding
        binding.setProperty("args", args);

        // Set the script text in the binding
        binding.setProperty(fileName, scriptText);

        // Run the script with the binding
        shell.run(scriptText, fileName, args);
    } catch (Exception e) {
        e.printStackTrace();
