public boolean isExceptionOnStack() {
    StackTraceElement[] stackTraceElements = Thread.currentThread().getStackTrace();
    for (StackTraceElement stackTraceElement : stackTraceElements) {
        String className = stackTraceElement.getClassName();
        if (className.equals("org.slf4j.impl.Log4jMDCAdapter") && stackTraceElement.getMethodName().equals("clear")) {
            continue;
        }
        if (className.startsWith("org.slf4j.") || className.startsWith("org.apache.logging.")) {
            return true;
        }
    }
    return false;
}
