public int readBits(int length) throws DecodingException {
    int content = 0;
    for (int i = 0; i < length; i++) {
        try {
            int bit = input.read();
            if (bit == -1) {
                return -1;
            }
            content = (content << 1) | bit;
        } catch (IOException e) {
            throw new DecodingException("Decoding failed", e);
        }
    }
    return content;
}
