        if (value == null) {
            return this.isLowerInfinite() || this.isUpperInfinite();
        }
        EndPoint<T> epValue = new EndPoint<>(value);
        int compareLow = this.lowerBound.compareTo(epValue);
        int compareUp = this.upperBound.compareTo(epValue);
