import java.net.*;
import java.util.*;

public class InMemoryCookieStore implements CookieStore {

    private Map<URI, List<HttpCookie>> cookieJar;

    public InMemoryCookieStore() {
        cookieJar = new HashMap<>();
    }

    // add a cookie
    public void add(URI uri, HttpCookie cookie) {
        if (cookieJar.containsKey(uri)) {
            cookieJar.get(uri).add(cookie);
        } else {
            List<HttpCookie> cookies = new ArrayList<>();
            cookies.add(cookie);
            cookieJar.put(uri, cookies);
        }
    }

    // get cookie list for specific URI
    public List<HttpCookie> get(URI uri) {
        List<HttpCookie> cookies = cookieJar.get(uri);
        if (cookies == null) {
            cookies = new ArrayList<>();
        }
        return cookies;
    }

    // get all stored cookies
    public List<HttpCookie> getCookies() {
        List<HttpCookie> cookies = new ArrayList<>();
        for (URI uri : cookieJar.keySet()) {
            cookies.addAll(cookieJar.get(uri));
        }
        return cookies;
    }

    // get all URIs with cookies
    public List<URI> getURIs() {
        return new ArrayList<>(cookieJar.keySet());
    }

    // remove cookie
    public boolean remove(URI uri, HttpCookie cookie) {
        List<HttpCookie> cookies = cookieJar.get(uri);
        if (cookies == null) {
            return false;
        }
        return cookies.remove(cookie);
    }

    // remove all cookies
    public boolean removeAll() {
        cookieJar.clear();
        return true;
    }
}
