public String generateLatexSummary(String[] algorithmNames, double[][] algorithmMeasures) {
    StringBuilder sb = new StringBuilder();

    // Latex header
    sb.append("\\begin{tabular}{|c|");
    for (int i = 0; i < algorithmMeasures.length; i++) {
        sb.append("c|");
    }
    sb.append("}\n");
    sb.append("\\hline\n");
    sb.append(" & ");
    for (String algorithmName : algorithmNames) {
        sb.append(algorithmName).append(" & ");
    }
    sb.delete(sb.length() - 2, sb.length());
    sb.append("\\\\ \\hline\n");

    // Algorithm results
    for (int i = 0; i < algorithmMeasures.length; i++) {
        sb.append(algorithmNames[i]).append(" & ");
        for (int j = 0; j < algorithmMeasures.length; j++) {
            double result = algorithmMeasures[i][j];
            String cell = "-";
            if (result > 0) {
                cell = "+";
            } else if (result == 0) {
                cell = "=";
            }
            sb.append(cell).append(" & ");
        }
        sb.delete(sb.length() - 2, sb.length());
        sb.append("\\\\ \\hline\n");
    }

    // Latex footer
    sb.append("\\end{tabular}");

    return sb.toString();
}
