import com.yahoo.sketches.theta.CompactSketch;
import com.yahoo.sketches.theta.Sketch;
import com.yahoo.sketches.theta.Union;
import com.yahoo.sketches.theta.UpdateSketch;

public static CompactSketch performAAndNotB(Sketch a, Sketch b) {
    Union union = new Union();
    union.update(a);
    union.update(b);
    Sketch unionSketch = union.getResult();
    UpdateSketch notBSketch = UpdateSketch.builder().build();
    notBSketch.update(b);
    notBSketch.update(unionSketch, false);
    return notBSketch.compact(true, null);
}
