/**
 * Assigns each worker to migrate whichever files it has the most blocks for.
 * If no worker has blocks for a file, a random worker is chosen.
 *
 * @param workers an array of worker objects.
 * @param files   a set of file objects.
 * @return a mapping from each file to the worker that should migrate it.
 */
public Map<File, Worker> assignWorkers(Worker[] workers, Set<File> files) {
    Map<File, Worker> assignment = new HashMap<>();
    Set<File> unmigrated = new HashSet<>(files);

    // Assign files with blocks to the corresponding worker
    for (Worker w : workers) {
        Set<File> filesWithBlocks = w.getFilesWithBlocks(unmigrated);
        for (File f : filesWithBlocks) {
            assignment.put(f, w);
            unmigrated.remove(f);
        }
    }

    // Assign remaining files randomly to the workers
    List<File> unmigratedList = new ArrayList<>(unmigrated);
    Collections.shuffle(unmigratedList);
    int i = 0;
    for (File f : unmigratedList) {
        Worker w = workers[i % workers.length];
        assignment.put(f, w);
        i++;
    }

    return assignment;
}
