import java.util.Comparator;

public static <T> void upwardsFix(T[] arr, int k, int level, Comparator<T> cmp) {
    int i = k;
    int parent = (i - 1) / 2;

    while (i > level && cmp.compare(arr[parent], arr[i]) < 0) {
        T temp = arr[i];
        arr[i] = arr[parent];
        arr[parent] = temp;

        i = parent;
        parent = (i - 1) / 2;
    }
}
