        sb.append("Destination Broker Id: ").append(info.getDestinationBrokerId()).append("\n");
        sb.append("Topic Name: ").append(info.getTopicName()).append("\n");
        sb.append("Partition Ids: ").append(info.getPartitionIds().toString()).append("\n");
        sb.append("Status: ").append(info.getStatus()).append("\n");
        sb.append("-----------------------------------").append("\n");
    }
    return sb.toString();
}
