public String registerMBean(String serviceName, String nameName, Object theMbean) throws Exception {
    // Construct the MBeanName object using the supplied parameters
    String mbeanNameStr = "hadoop:service=" + serviceName + ",name=" + nameName;
    ObjectName mbeanName = new ObjectName(mbeanNameStr);

    // Register the MBean with the platform MBean server
