public static boolean isValidCreditCard(String stPassed) {
    int[] ints = new int[stPassed.length()];
    for (int i = 0; i < stPassed.length(); i++) {
        ints[i] = Integer.parseInt(stPassed.substring(i, i + 1));
    }
    for (int i = ints.length - 2; i >= 0; i = i - 2) {
        int j = ints[i];
        j = j * 2;
        if (j > 9) {
            j = j % 10 + 1;
        }
        ints[i] = j;
    }
    int sum = 0;
    for (int i = 0; i < ints.length; i++) {
        sum += ints[i];
    }
    return sum % 10 == 0;
}
