public class JAXBContextSingleton {

    private static JAXBContext context;

    // Private constructor to prevent any other instantiations
    private JAXBContextSingleton() {}

    public static JAXBContext getInstance() {
        if (context == null) {
            synchronized (JAXBContextSingleton.class) {
                if (context == null) {
                    try {
                        context = JAXBContext.newInstance("com.example.package"); 
                    } catch (JAXBException e) {
                        throw new RuntimeException("Unable to create JAXBContext instance");
                    }
                }
            }
        }
        return context;
    }
}
