import com.github.msoliter.iroh.container.annotations.Component;

public class TypeRegistrar {

    private static final Map<Class<?>, List<Class<?>>> registry = new HashMap<>();

    public static void register(Class<?> type) {
        Component componentAnnotation = type.getAnnotation(Component.class);
        if (componentAnnotation != null) {
            List<Class<?>> componentReturnTypes = new ArrayList<>();

            for (java.lang.reflect.Method method : type.getDeclaredMethods()) {
                Component methodAnnotation = method.getAnnotation(Component.class);
                if (methodAnnotation != null) {
                    componentReturnTypes.add(method.getReturnType());
                }
            }

            registry.put(type, componentReturnTypes);
        }
    }
}
