public static long calculateNextPeriodEnd(long now) {
    // get the timezone of the system
    TimeZone localTimeZone = TimeZone.getDefault();

    // get the current date in the local timezone
    Calendar calendar = Calendar.getInstance(localTimeZone);
    calendar.setTimeInMillis(now);

    // calculate the next period end
    int currentHour = calendar.get(Calendar.HOUR_OF_DAY);
    int nextPeriodEndHour = (currentHour / 8 + 1) * 8;
    if (nextPeriodEndHour == 24) {
        calendar.add(Calendar.DATE, 1);
        nextPeriodEndHour = 0;
    }
    calendar.set(Calendar.HOUR_OF_DAY, nextPeriodEndHour);
    calendar.set(Calendar.MINUTE, 0);
    calendar.set(Calendar.SECOND, 0);
    calendar.set(Calendar.MILLISECOND, 0);

    // convert the result to GMT
    ZonedDateTime localTime = calendar.toInstant().atZone(localTimeZone.toZoneId());
    ZonedDateTime gmtTime = localTime.withZoneSameInstant(ZoneId.of("GMT"));
    return gmtTime.toInstant().toEpochMilli();
}
