public static String getCountryByIpAddress(String ipAddress) {
    try {
        InetAddress inetAddress = InetAddress.getByName(ipAddress);
        CountryResponse countryResponse = new DbReader.Builder(new File("GeoIP2-Country.mmdb")).build().country(inetAddress);
        Country country = countryResponse.getCountry();
        return country.getName();
    } catch (AddressNotFoundException e) {
        return "Unknown"; // IP address not found in database
    } catch (IOException | GeoIp2Exception e) {
        e.printStackTrace();
        return "Error";
    }
}
