public boolean deleteDirectory(String key, boolean recursive) throws EtcdClientException {
    try {
        DeleteResponse response = client.getKVClient().delete(
                ByteSequence.fromString(key),
                DeleteOption.newBuilder().withPrefix(ByteSequence.fromString(key)).withRecursive(recursive).build()
        ).get();
        return response.getDeleted() > 0;
    } catch (Exception e) {
        throw new EtcdClientException("Failed to delete directory: " + key, e);
    }
}
