public static AsyncWork initializeXMLStreamReader(XMLStreamReader reader) {
    return AsyncWork.run(() -> {
        reader.next();
        while (reader.hasNext()) {
            int event = reader.next();
            if (event == XMLStreamConstants.CHARACTERS) {
                AsyncWork.unblock();
            }
        }
    });
}
