public static long findStartOfBlock(InputStream in, byte[] magic) throws BitcoinBlockReadException {
    try {
        byte[] buffer = new byte[magic.length];
        int readBytes;

        while ((readBytes = in.read(buffer)) != -1) {
            if (Arrays.equals(buffer, magic)) {
                return in.skip(-(long) magic.length); // move back to the beginning of the magic bytes
            }
        }
        throw new BitcoinBlockReadException("Could not find block start magic");
    } catch (IOException e) {
        throw new BitcoinBlockReadException("Error reading blockchain data", e);
    }
}
