import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;
import java.util.Collection;
import java.util.Iterator;

public class IteratorWrapperUtils {

    public static <T> Iterator<T> getIteratorWrapper(Collection<?> coll, Class<T> declaredType, Class<?> valueType, Type... valueTypeTypes) {
        if (coll == null) {
            throw new IllegalArgumentException("Collection must not be null");
        }

        if (declaredType == null) {
            throw new IllegalArgumentException("Declared type must not be null");
        }

        if (valueType == null) {
            throw new IllegalArgumentException("Value type must not be null");
        }

        Iterator<?> iterator = coll.iterator();

        Type genericType = getGenericType(valueType, valueTypeTypes);

        return new Iterator<T>() {
            @Override
            public boolean hasNext() {
                return iterator.hasNext();
            }

            @Override
            @SuppressWarnings("unchecked")
            public T next() {
                Object obj = iterator.next();

                if (!declaredType.isAssignableFrom(obj.getClass())) {
                    throw new ClassCastException("Object of type " + obj.getClass().getName()
                            + " cannot be cast to " + declaredType.getName());
                }

                return (T) obj;
            }
        };
    }

    private static Type getGenericType(Class<?> valueType, Type[] valueTypeTypes) {
        if (valueTypeTypes != null && valueTypeTypes.length > 0) {
            return ParameterizedTypeImpl.make(valueType, valueTypeTypes, null);
        } else {
            return valueType;
        }
    }
}
