public static int getNextSimpleValue(int val) throws IOException {
    int nextVal = val + 1;
    while (!isSimple(nextVal)) {
        nextVal++;
    }
    return nextVal;
}

private static boolean isSimple(int val) {
    if (val <= 1) {
        return false;
    }
    for (int i = 2; i <= Math.sqrt(val); i++) {
        if (val % i == 0) {
            return false;
        }
    }
    return true;
}
