public List<AlertDto> convertToDtoList(List<Alert> alertList) throws WebApplicationException {
    if (alertList == null) {
        throw new WebApplicationException("Cannot convert null list.");
    }

    List<AlertDto> dtoList = new ArrayList<>();

    for (Alert alert : alertList) {
        AlertDto dto = new AlertDto();
        // map properties from Alert entity to AlertDto object
        dto.setId(alert.getId());
        dto.setTitle(alert.getTitle());
        dto.setDescription(alert.getDescription());
        dto.setSeverity(alert.getSeverity());
        dto.setTimestamp(alert.getTimestamp());
        // add to list
        dtoList.add(dto);
    }

    return dtoList;
}
