public Map<String, Double> parseCpuMap(TopologyDef topology, String componentName) {
    Map<String, Object> config = topology.getConf();
    if (config == null || !config.containsKey(Config.TOPOLOGY_COMPONENT_CPUMAP)) {
        return Collections.emptyMap();
    }
    Map<String, Map<String, Double>> cpuMap = (Map<String, Map<String, Double>>) config.get(Config.TOPOLOGY_COMPONENT_CPUMAP);
    if (cpuMap == null || !cpuMap.containsKey(componentName)) {
        return Collections.emptyMap();
    }
    return cpuMap.get(componentName);
}
