public Map<Integer, Integer> extractProjects(List<Aggregate> inputAggregates) {
    Map<Integer, Integer> indexMapping = new HashMap<>();
    List<Project> outputProjects = new ArrayList<>();

    // iterate over each input aggregate
    for (int index = 0; index < inputAggregates.size(); index++) {
        Aggregate aggregate = inputAggregates.get(index);

        // extract the projects from the aggregate and add them to the output list
        List<Project> projects = aggregate.getProjects();
        outputProjects.addAll(projects);

        // map the output project index to the input aggregate index
        for (int i = 0; i < projects.size(); i++) {
            indexMapping.put(outputProjects.size() - projects.size() + i, index);
        }
    }

    return indexMapping;
}
