public void appendTupleToTable(Object[] tuple, Object[][] table) {
    int rowCount = table.length;
    int colCount = table[0].length;
    Object[][] newTable = new Object[rowCount + 1][colCount];

    for(int i = 0; i < rowCount; i++) {
        for(int j = 0; j < colCount; j++) {
            newTable[i][j] = table[i][j];
        }
    }

    for(int j = 0; j < colCount; j++) {
        newTable[rowCount][j] = tuple[j];
    }

    table = newTable;
}
