public String combinePackage(String parent, String child) {
    // check if parent is empty or null
    if(parent == null || parent.isEmpty()) {
        return child;
    }

    // check if child is empty or null
    if(child == null || child.isEmpty()) {
        return parent;
    }

    // combine the parent and child package
    return parent + "." + child;
}
