public void writeHeader(MgmtProtocolHeader header, OutputStream os) throws IOException {
    os.write(header.getVersion());
    os.write(header.getCommand());
    os.write(header.getLength() >> 8);
    os.write(header.getLength() & 0xFF);
    os.write(header.getSessionId() >> 24);
    os.write(header.getSessionId() >> 16);
    os.write(header.getSessionId() >> 8);
    os.write(header.getSessionId() & 0xFF);
    os.write(header.getFlags());
}
