public static String readInput(Reader reader) throws MustacheIOException {
    StringBuilder content = new StringBuilder();
    try (BufferedReader br = new BufferedReader(reader)) {
        String line;
        while ((line = br.readLine()) != null) {
            content.append(line);
        }
    } catch (IOException e) {
        throw new MustacheIOException("An IO exception occurred while reading input", e);
    }
    return content.toString();
}
