public Label createLabel(Object projectIdOrPath, String name, String color, String description, Integer priority) throws GitLabApiException {
    Label label = new Label()
            .withName(name)
            .withColor(color)
            .withDescription(description)
            .withPriority(priority);

    if (projectIdOrPath instanceof Integer) {
        return gitLabApi.getLabelsApi().createLabel((Integer)projectIdOrPath, label);
    } else if (projectIdOrPath instanceof String) {
        return gitLabApi.getLabelsApi().createLabel((String)projectIdOrPath, label);
    } else if (projectIdOrPath instanceof Project) {
        return gitLabApi.getLabelsApi().createLabel((Project)projectIdOrPath, label);
    }

    throw new GitLabApiException("Invalid projectIdOrPath class");
}
