public static String s2j(String s) {
    String j = "";
    StringTokenizer st = new StringTokenizer(s);
    while (st.hasMoreTokens()) {
        String token = st.nextToken();
        if (token.length() > 0 && token.charAt(0) == '-') {
            token = "negative" + token.substring(1);
        }
        j += token.substring(0, 1).toUpperCase() + token.substring(1);
    }
    return j;
}
