import java.io.File;
import java.nio.file.Files;
import java.nio.file.attribute.BasicFileAttributes;
import java.util.Date;

public class JarComparator {

    public static boolean isToolJarNewer(File toolJar, File junitJar) {
        try {
            BasicFileAttributes toolJarAttrs = Files.readAttributes(toolJar.toPath(), BasicFileAttributes.class);
            BasicFileAttributes junitJarAttrs = Files.readAttributes(junitJar.toPath(), BasicFileAttributes.class);

            Date toolJarLastModifiedDate = new Date(toolJarAttrs.lastModifiedTime().toMillis());
            Date junitJarLastModifiedDate = new Date(junitJarAttrs.lastModifiedTime().toMillis());

            return toolJarLastModifiedDate.after(junitJarLastModifiedDate);
        } catch (Exception ex) {
            // Handle the exception here
            return false;
        }
    }
}
