public <P> void sendResponse(ChannelHandlerContext channelHandlerContext, HttpRequest httpRequest, P response, HttpResponseStatus statusCode, HttpHeaders headers) {
    ByteBuf byteBuf = Unpooled.copiedBuffer(response.toString(), CharsetUtil.UTF_8);

    FullHttpResponse fullHttpResponse = new DefaultFullHttpResponse(HttpVersion.HTTP_1_1, statusCode, byteBuf);

    fullHttpResponse.headers().set(HttpHeaderNames.CONTENT_TYPE, "application/json; charset=UTF-8");
    fullHttpResponse.headers().set(HttpHeaderNames.CONTENT_LENGTH, byteBuf.readableBytes());
    fullHttpResponse.headers().set(HttpHeaderNames.CONNECTION, HttpHeaderValues.KEEP_ALIVE);

    if (headers != null && !headers.isEmpty()) {
        fullHttpResponse.headers().add(headers);
    }

    ChannelFuture channelFuture = channelHandlerContext.channel().writeAndFlush(fullHttpResponse);

    channelFuture.addListener(ChannelFutureListener.CLOSE);
}
