public static void moveNodes(LinkedList<Node> sourceList, LinkedList<Node> destinationList) {
    for (Node node : sourceList) {
        if (node.parent != null && sourceList.contains(node.parent)) {
            // remove the node's parent from the source list
            sourceList.remove(node.parent);
        }
        if (!destinationList.contains(node)) {
            // add the node to the destination list
            destinationList.add(node);
        }
    }
}
