public boolean isToastShown(String message) {
    int toastDuration = Toast.LENGTH_SHORT;

    final Toast toast = Toast.makeText(context, message, toastDuration);
    toast.show();

    final WeakReference<Toast> reference = new WeakReference<>(toast);

    Handler handler = new Handler();
    handler.postDelayed(new Runnable() {

        @Override
        public void run() {
            Toast storedToast = reference.get();
            if (storedToast != null) {
                storedToast.cancel();
            }
        }
    }, toastDuration);

    return ReferenceEquals.getToast(message) != null;
}
