import java.util.List;
import javax.lang.model.element.Element;
import javax.lang.model.element.ElementKind;
import javax.lang.model.element.TypeElement;
import javax.tools.Diagnostic;
import javax.tools.JavaCompiler;
import javax.tools.JavaFileObject;
import javax.tools.StandardJavaFileManager;
import javax.tools.ToolProvider;
import com.sun.source.tree.CompilationUnitTree;
import com.sun.source.tree.Tree;
import com.sun.source.util.JavacTask;
import com.sun.source.util.Trees;

public class TreesForCompilationTask {

    public Trees getTreesForTask(CompilationTask task) throws IllegalArgumentException {

        JavaCompiler compiler = ToolProvider.getSystemJavaCompiler();
        StandardJavaFileManager fileManager = compiler.getStandardFileManager(null, null, null);
        Iterable<? extends JavaFileObject> compilationUnits = fileManager.getJavaFileObjects(task.getFile());

        JavacTask javacTask = (JavacTask) compiler.getTask(null, fileManager, null, null, null, compilationUnits);
        List<Diagnostic<? extends JavaFileObject>> errors = javacTask.call();
        for (Diagnostic<? extends JavaFileObject> error : errors) {
            System.out.println(error);
        }
        Trees trees = Trees.instance(javacTask);
        CompilationUnitTree compilationUnitTree = null;
        try {
            compilationUnitTree = javacTask.parse().iterator().next();
        } catch (Exception exp) {
            throw new IllegalArgumentException("Unable to parse: " + task.getFile());
        }
        List<? extends Tree> typeDeclarations = compilationUnitTree.getTypeDecls();
        Element element = typeDeclarations.get(0);
        while (element.getKind() != ElementKind.CLASS && element.getKind() != ElementKind.INTERFACE) {
            element = element.getEnclosingElement();
            if (element == null) {
                break;
            }
        }
        TypeElement typeElement = (TypeElement) element;
        if (trees == null || !trees.isTree(typeElement)) {
            throw new IllegalArgumentException("Unable to find tree for: " + typeElement.getSimpleName());
        }
        return trees;
    }
}
