public class TableNormalizer {

    public static List<String> getNormalizedTables(List<String> relationIds) {
        Set<String> tables = new HashSet<>();

        for(String id: relationIds) {
            String[] parts = id.split("\\.");

            if(parts.length > 1) {
                tables.add(parts[0]);
            }
        }

        return new ArrayList<>(tables);
    }

}
