public List<Map<String, Object>> fetchFilteredResources(String filter) {
    // Parse the filter string as a JSON object
    JSONObject jsonFilter = new JSONObject(filter);

    // Build the query based on the filter
    QueryBuilder queryBuilder = new QueryBuilder();
    for (String key : jsonFilter.keySet()) {
        queryBuilder.withFilter(key, jsonFilter.get(key));
    }

    // Fetch the resources that match the query
    List<Map<String, Object>> resources = new ArrayList<>();
    List<Resource> filteredResources = queryBuilder.execute();
    for (Resource resource : filteredResources) {
        Map<String, Object> resourceMap = new HashMap<>();
        resourceMap.put("name", resource.getName());
        resourceMap.put("port", resource.getPort());
        resourceMap.put("serviceType", resource.getServiceType());
        resources.add(resourceMap);
    }
    return resources;
}
