public void trackAndCheckQuota(String quotaKey, String trackedOp) throws QuotaExceededException {
    // Get the current throughput levels for the tracked operation
    int currentThroughput = getCurrentThroughput(trackedOp);

    // Get the maximum allowed quota for the specified quota key
    int maxQuota = getMaxQuota(quotaKey);

    // Check if the current throughput exceeds the maximum quota
    if (currentThroughput > maxQuota) {
        throw new QuotaExceededException("Exceeded quota for operation: " + trackedOp);
    }
}

