public void unbindAndClose() throws Exception {
    InitialContext context = new InitialContext();
    NamingEnumeration<NameClassPair> bindingList = context.list("");
    while (bindingList.hasMore()) {
        NameClassPair pair = bindingList.next();
        String name = pair.getName();
        Object obj = context.lookup(name);
        if (obj instanceof DataSource) {
            context.unbind(name);
        }
    }
    context.close();
}
