public boolean validateManifestAttribute(String attribute) {
    // check if attribute is null or empty
    if (attribute == null || attribute.isEmpty()) {
        Messager.printMessage(Diagnostic.Kind.ERROR, "Manifest attribute cannot be null or empty.");
        return false;
    }

    // check if attribute contains any invalid characters
    if (!attribute.matches("[a-zA-Z0-9._-]+")) {
        Messager.printMessage(Diagnostic.Kind.ERROR, "Manifest attribute contains invalid characters.");
        return false;
    }

    // attribute is valid
    return true;
}
