public List<File> getChunks(List<File> files, int numChunks) {
    int numFiles = files.size();
    if (numFiles < numChunks) {
        numChunks = numFiles;
    }
    List<File> chunks = new ArrayList<>();
    int filesPerChunk = numFiles / numChunks;
    int remainder = numFiles % numChunks;
    int index = 0;
    for (int i = 0; i < numChunks; i++) {
        int chunkSize = filesPerChunk;
        if (remainder > 0) {
            chunkSize++;
            remainder--;
        }
        if (chunkSize > 0) {
            chunks.add(new FileChunk(files.subList(index, index + chunkSize)));
            index += chunkSize;
        }
    }
    return chunks;
}
