public String getChannelList(List<Channel> channels) {
    StringBuilder htmlList = new StringBuilder();
    htmlList.append("<ul>");
    for (Channel channel : channels) {
        htmlList.append("<li>");
        htmlList.append(channel.getName());
        List<Resource> resources = channel.getResources();
        if (!resources.isEmpty()) {
            htmlList.append("<ul>");
            for (Resource resource : resources) {
                htmlList.append("<li>");
                htmlList.append(resource.getName());
                if (resource.isConnected()) {
                    htmlList.append(" (connected)");
                }
                htmlList.append("</li>");
            }
            htmlList.append("</ul>");
        }
        htmlList.append("</li>");
    }
    htmlList.append("</ul>");
    return htmlList.toString();
}
