import android.text.format.Time;
import java.util.Calendar;

public Time getFirstDayOfWeek() {
    Time time = new Time();
    Calendar calendar = Calendar.getInstance();
    int currentDayOfWeek = calendar.get(Calendar.DAY_OF_WEEK);
    int daysFromSunday = currentDayOfWeek - Calendar.SUNDAY;
    calendar.add(Calendar.DAY_OF_WEEK, -daysFromSunday);
    long firstDayOfWeekTimestamp = calendar.getTimeInMillis();
    time.set(firstDayOfWeekTimestamp);
    return time;
}
