public static SuppressionInfo generateSuppressionInfo(CompilationUnitTree compilationUnit) {
    SuppressWarningsTreeFinder finder = new SuppressWarningsTreeFinder();
    finder.scan(new TreePath(compilationUnit), null);
    List<String> suppressWarningsValues = finder.getSuppressWarningsValues();
    if (suppressWarningsValues == null || suppressWarningsValues.isEmpty()) {
        return SuppressionInfo.DEFAULT;
    }

    boolean isGenerated = suppressWarningsValues.stream()
            .map(Collections::singletonList)
            .anyMatch(SuppressionInfo::isSuppressWarningsGenerated);
    return new SuppressionInfo(isGenerated, suppressWarningsValues);
}
