import java.io.*;
import java.util.*;

public class GetCustomPublicanCfgFiles {

    public Map<String, String> getAdditionalPublicanCfgFiles() throws IOException {

        File folder = new File("/path/to/custom/publican/cfg/files");
        File[] files = folder.listFiles(new FilenameFilter() {
            public boolean accept(File dir, String name) {
                return name.toLowerCase().endsWith(".cfg");
            }
        });

        Map<String, String> customFilesMap = new HashMap<>();

        for (File file : files) {
            String name = file.getName();
            BufferedReader reader = new BufferedReader(new FileReader(file));
            StringBuilder content = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line);
                content.append(System.lineSeparator());
            }
            reader.close();
            customFilesMap.put(name, content.toString());
        }

        return customFilesMap;
    }

}
