public Properties loadConfiguration(String path) throws ConfigurationLoadException {
    Properties props = new Properties();
    InputStream inputStream = getClass().getResourceAsStream(path);

    if (inputStream == null) {
        try {
            File file = new File(path);
            if (file.exists()) {
                inputStream = new FileInputStream(file);
            }
        } catch (FileNotFoundException e) {
            throw new ConfigurationLoadException("Configuration not found at path: " + path, e);
        }
    }

    try {
        props.load(inputStream);
    } catch (IOException e) {
        throw new ConfigurationLoadException("Configuration could not be loaded from path: " + path, e);
    }

    return props;
}
