public long getFileLengthForBlockSize(long blockSize, int bytesPerChecksum, int checksumSize) {
    long fullBlocks = blockSize / bytesPerChecksum;
    long remainingBytes = blockSize % bytesPerChecksum;
    long lastChecksumLength = (long) Math.ceil((double) checksumSize / bytesPerChecksum) * bytesPerChecksum;
    long fullChecksums = fullBlocks * (blockSize + lastChecksumLength);
    long remainingChecksums = (long) Math.ceil((double) remainingBytes / bytesPerChecksum) * checksumSize;
    return fullChecksums + remainingChecksums;
}
