public static PseudoBooleanConstraint readFormula(String fileName, DependencyHelper<PseudoBooleanConstraint> f) throws IOException, ParserException {
    PseudoBooleanParser parser = new PseudoBooleanParser(f);
    BufferedReader in = new BufferedReader(new FileReader(fileName));
    String line = null;
    while ((line = in.readLine()) != null) {
        try {
            parser.parse(line);
        } catch (ContradictionException e) {
            throw new ParserException(e.getMessage());
        }
    }
    in.close();
    return parser.getObjectiveFunction();
}
