public static Method findMatchingMethod(Method controlBeanMethod, Class<?> ejbInterface) {
    Method[] interfaceMethods = ejbInterface.getMethods();
    for (Method interfaceMethod : interfaceMethods) {
        if (isSameSignature(controlBeanMethod, interfaceMethod)) {
            return interfaceMethod;
        }
    }
    return null;
}

private static boolean isSameSignature(Method controlMethod, Method method) {
    if (!controlMethod.getName().equals(method.getName())) {
        return false;
    }
    Class<?>[] controlMethodParams = controlMethod.getParameterTypes();
    Class<?>[] methodParams = method.getParameterTypes();
    if (controlMethodParams.length != methodParams.length) {
        return false;
    }
    for (int i = 0; i < controlMethodParams.length; i++) {
        if (!controlMethodParams[i].equals(methodParams[i])) {
            return false;
        }
    }
    return true;
}
