public static boolean validateNumberOfDigits(int totalDigits, double value) {
    String stringRepresentationOfValue = Double.toString(value);
    int numericPrecision = stringRepresentationOfValue.indexOf(".");
    int numberOfDigits = stringRepresentationOfValue.length();
    if (numericPrecision != -1) {
        numberOfDigits -= 1;
    }
    return numberOfDigits == totalDigits;
}
