public String convertToXml(List<DuraStoreAcct> accts) {
    DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
    DocumentBuilder builder;
    try {
        builder = factory.newDocumentBuilder();
        Document doc = builder.newDocument();
        Element rootElement = doc.createElement("accts");
        doc.appendChild(rootElement);
        for(DuraStoreAcct acct: accts) {
            Element acctElement = doc.createElement("acct");
            rootElement.appendChild(acctElement);
            Element urlElement = doc.createElement("url");
            urlElement.appendChild(doc.createTextNode(acct.getUrl()));
            acctElement.appendChild(urlElement);
            Element usernameElement = doc.createElement("username");
            usernameElement.appendChild(doc.createTextNode(acct.getUsername()));
            acctElement.appendChild(usernameElement);
            Element passwordElement = doc.createElement("");
            passwordElement.appendChild(doc.createTextNode(acct.getPassword()));
            acctElement.appendChild(passwordElement);
        }
        TransformerFactory transformerFactory = TransformerFactory.newInstance();
        Transformer transformer = transformerFactory.newTransformer();
        transformer.setOutputProperty(OutputKeys.INDENT, "yes");
        DOMSource source = new DOMSource(doc);
        StringWriter writer = new StringWriter();
        StreamResult result = new StreamResult(writer);
        transformer.transform(source, result);
        String xmlString = writer.getBuffer().toString().replaceAll("\n|\r", "");
        return xmlString;
    } catch (Exception e) {
        e.printStackTrace();
        return null;
    }
}
