public List<String> splitValue(String value) throws IOException {
    List<String> versionedValues = new ArrayList<>();
    // split the original value into multiple versioned values
    // using a separator such as a comma
    String[] values = value.split(",");
    for (String val : values) {
        // add each versioned value to the list
        versionedValues.add(val);
    }
    return versionedValues;
