public static String[] splitDFSPath(String path) {
    String[] result = new String[4];
    if(path != null && !path.isEmpty()) {
        String[] tokens = path.split("\\\\");
        result[0] = "";
        if(tokens.length > 1) {
            result[1] = tokens[1];
            if(tokens.length > 2) {
                result[2] = tokens[2];
                if(tokens.length > 3) {
                    StringBuilder sb = new StringBuilder(tokens[3]);
                    for(int i=4; i<tokens.length; i++) {
                        sb.append("\\").append(tokens[i]);
                    }
                    result[3] = sb.toString();
                }
            }
        }
    }
    return result;
}
