public List<BridgeGroup> fetchFilteredBridgeGroups(String filterString) {
    // Convert the filter string from JSON to a map
    Map<String, String> filterMap = new HashMap<>();
    try {
        ObjectMapper objectMapper = new ObjectMapper();
        filterMap = objectMapper.readValue(filterString, new TypeReference<Map<String, String>>(){});
    } catch (JsonProcessingException e) {
        // Handle the JSON parsing exception here
        e.printStackTrace();
    }

    // Call the API to fetch bridge groups and filter them
    List<BridgeGroup> allBridgeGroups = BridgeGroupAPI.fetchAllBridgeGroups();
    List<BridgeGroup> filteredBridgeGroups = new ArrayList<>();
    for (BridgeGroup bg : allBridgeGroups) {
        boolean matchesFilter = true;
        for (Map.Entry<String, String> entry : filterMap.entrySet()) {
            String key = entry.getKey();
            String value = entry.getValue();
            // Perform case-insensitive matching on the values
            if (!(bg.getPropertyValue(key) != null && bg.getPropertyValue(key).equalsIgnoreCase(value))) {
                matchesFilter = false;
                break;
            }
        }
        if (matchesFilter) {
            filteredBridgeGroups.add(bg);
        }
    }
    return filteredBridgeGroups;
}
