public boolean hasNavigableWebContent(Context context, AccessibilityNodeInfo node) {
    if (node == null) {
        return false;
    }
    if (node.getClassName().equals("com.google.android.apps.chrome.ChromeVoxNavWebView")) {
        return true;
    }
    if (node.getClassName().equals("android.webkit.WebView")
        || node.getClassName().equals("android.webkit.WebViewClassic")) {
        return node.getContentDescription() != null
            || node.getText() != null
            || node.getChildCount() > 0;
    }
    return false;
}
