public static void trmv(char order, char Uplo, char TransA, char Diag, double[][] A, double[] X) {
    int N = A.length;
    double temp;

    if (order == 'r') {
        for (int i = 0; i < N; i++) {
            temp = 0.0;
            for (int j = 0; j <= i; j++) {
                if (TransA == 'n')
                    temp += A[i][j] * X[j];
                else
                    temp += A[j][i] * X[j];
            }
            X[i] = temp;
        }
    } else {
        for (int i = N - 1; i >= 0; i--) {
            temp = 0.0;
            for (int j = N - 1; j >= i; j--) {
                if (TransA == 'n')
                    temp += A[i][j] * X[j];
                else
                    temp += A[j][i] * X[j];
            }
            X[i] = temp;
        }
    }
}
