public void waitForSameSchema(List<Node> nodes) throws InterruptedException {
    // A flag to keep track of whether all nodes have the same schema
    boolean allNodesHaveSameSchema = false;

    while (!allNodesHaveSameSchema) {
        // Get the schema from the first node
        Schema schema = nodes.get(0).getSchema();

        // Assume that all nodes have the same schema
        allNodesHaveSameSchema = true;

        // Check if all other nodes have the same schema as the first node
        for (int i = 1; i < nodes.size(); i++) {
            if (!nodes.get(i).getSchema().equals(schema)) {
                // If a node has a different schema, set the flag to false and break the loop
                allNodesHaveSameSchema = false;
                break;
            }
        }

        // If all nodes have the same schema, sleep for 100 milliseconds and check again
        if (allNodesHaveSameSchema) {
            Thread.sleep(100);
        }
    }
}
