import org.springframework.beans.factory.FactoryBean;
import org.springframework.ldap.odm.typeconversion.Converter;
import org.springframework.ldap.odm.typeconversion.ConverterManager;
import org.springframework.ldap.odm.typeconversion.impl.ConverterManagerImpl;

import java.util.List;

public class ConverterManagerFactoryBean implements FactoryBean<ConverterManager> {

    private List<Converter<?, ?>> converterConfigList;

    public void setConverterConfigList(List<Converter<?, ?>> converterConfigList) {
        this.converterConfigList = converterConfigList;
    }

    @Override
    public ConverterManager getObject() throws ClassNotFoundException {
        ConverterManagerImpl converterManager = new ConverterManagerImpl();
        for (Converter<?, ?> config : converterConfigList) {
            Class<?> fromClass = Class.forName(config.getFromType());
            Class<?> toClass = Class.forName(config.getToType());
            converterManager.addConverter(fromClass, toClass, config.getConverter());
        }
        return converterManager;
    }

    @Override
    public Class<?> getObjectType() {
        return ConverterManager.class;
    }

    @Override
    public boolean isSingleton() {
        return true;
    }
}
