public static String getNodeType(Node n, boolean dereference) {
    String type = n.getType().getName();
    if (dereference && type.equals("Object")) {
        Type derefType = n.getDereferencedType();
        if (derefType != null && !derefType.getName().equals("Object")) {
            type = derefType.getName();
        }
    }
    return type.isEmpty() ? "Unknown Type" : type;
}
