public OptionBuilder addIncludesOption(List<String> includes) {
    // assuming OptionBuilder is a class
    // create a new instance of OptionBuilder
    OptionBuilder updatedOptionBuilder = new OptionBuilder();

    // get the previous includes from the updatedOptionBuilder instance
    List<String> previousIncludes = updatedOptionBuilder.getIncludes();

    // add new includes to the previous includes list
    previousIncludes.addAll(includes);

    // set the updated includes list to the updatedOptionBuilder instance
    updatedOptionBuilder.setIncludes(previousIncludes);

    // return the updated instance of OptionBuilder
    return updatedOptionBuilder;
}
