public <T> boolean removeProperty(T property) {
    // Assumption: The component has a List<T> propertyList to store the properties
    // Iterating the propertyList to find the property
    Iterator<T> iter = propertyList.iterator();
    while (iter.hasNext()) {
        T prop = iter.next();
        if (prop.equals(property)) {
            iter.remove();
            return true;
        }
    }
    return false;
}
