public List<Object> convertRepeatedField(List<Object> repeatedField) {
    List<Object> convertedList = new ArrayList<Object>();
    for (Object repeatedValue : repeatedField) {
        if (repeatedValue instanceof List) {
            convertedList.add(convertRepeatedField((List<Object>) repeatedValue));
        } else {
            convertedList.add(repeatedValue);
        }
    }
    return convertedList;
}
