public int getTimeToWait(boolean isBackendQueriedRecently) {
    // Set the maximum query frequency in milliseconds
    int maxQueryFrequency = 5000;

    // Get the current time in milliseconds
    long currentTime = System.currentTimeMillis();

    if (isBackendQueriedRecently) {
        // Calculate the amount of time to wait before the next query is allowed
        long timeSinceLastQuery = currentTime - lastQueryTime;
        long timeToWait = maxQueryFrequency - timeSinceLastQuery;

        if (timeToWait > 0) {
            return (int) timeToWait;
        } else {
            return -1;
        }
    } else {
        // Query the backend since the maximum query frequency has passed
        lastQueryTime = currentTime;
        return -1;
    }
}
