public IMolecularFormula orderElements(IMolecularFormula formula) {
    List<IElement> elements = formula.elements();
    Collections.sort(elements, new Comparator<IElement>() {
        @Override
        public int compare(IElement o1, IElement o2) {
            return o1.getSymbol().compareTo(o2.getSymbol());
        }
    });
    IMolecularFormula orderedFormula = builder.newInstance();
    for (int i = 0; i < elements.size(); i++) {
        orderedFormula.addIsotope(elements.get(i), formula.getIsotopeCount(elements.get(i)));
    }
    return orderedFormula;
}
