import java.lang.instrument.Instrumentation;
import java.lang.instrument.ClassFileTransformer;

public class Instrumenter {

    public static void premain(String agentArgs, Instrumentation instrumentation) {
        instrumentation.addTransformer(new ClassFileTransformer() {
            @Override
            public byte[] transform(ClassLoader loader, String className, Class<?> classBeingRedefined,
                                    ProtectionDomain protectionDomain, byte[] classfileBuffer) {
                // Do any required transformation or profiling of class files
                return classfileBuffer;
            }
        });
    }

    public static Runnable attachAgentToRunningJVM(final Instrumentation instrumentation) {
        instrumentation.addTransformer(new ClassFileTransformer() {
            @Override
            public byte[] transform(ClassLoader loader, String className, Class<?> classBeingRedefined,
                                    ProtectionDomain protectionDomain, byte[] classfileBuffer) {
                // Do any required transformation or profiling of class files
                return classfileBuffer;
            }
        }, true);
        return new Runnable() {
            @Override
            public void run() {
                instrumentation.removeTransformer(this.getClass().getClassLoader(), this.toString());
            }
        };
    }
}
