public class Sweeping {
    private boolean stopped;

    public boolean stop() {
        if(stopped) {
            return false;
        } else {
            stopped = true;
            return true;
        }
    }

    public boolean start() {
        stopped = false;
        return true;
    }

    public boolean isStopped() {
        return stopped;
    }

    public boolean stopIfNotStopped() {
        if(!start() || stop()) {
            return false;
        }
        return true;
    }
}
