public void mapModelObjPropertiesToDB(Object mModelObj, PreparedStatement preparedStatement) throws D6Exception {
   try {
      // Get the class of the model object
      Class<?> modelClass = mModelObj.getClass();
      // Get all the declared fields of the model class, including private fields
      Field[] fields = modelClass.getDeclaredFields();
      int parameterIndex = 1;
      for (Field field : fields) {
         // Make the field accessible
         field.setAccessible(true);
         // Get the field value
         Object fieldValue = field.get(mModelObj);
         // Set the value of the prepared statement parameter
         preparedStatement.setObject(parameterIndex++, fieldValue);
      }
   } catch (Exception e) {
      throw new D6Exception("Error mapping model object properties to DB: " + e.getMessage());
   }
}
