public Node getPreviousSibling(Node inputNode, short whatToShow) {
    Node previousSibling = inputNode.getPreviousSibling();
    while (previousSibling != null && !isValidNode(previousSibling, whatToShow)) {
        previousSibling = previousSibling.getPreviousSibling();
    }
    return previousSibling;
}

private boolean isValidNode(Node node, short whatToShow) {
    return (node.getNodeType() == Node.ELEMENT_NODE || node.getNodeType() == Node.TEXT_NODE)
            && (whatToShow & (1 << (node.getNodeType() - 1))) != 0;
}
