public class ProtoUtils {

  private static final Logger LOGGER = Logger.getLogger(ProtoUtils.class.getName());

  public static <T extends MessageLite> T fromByteArray(final byte[] message, final T instance) {
    T result = null;
    try (InputStream inputStream = new ByteArrayInputStream(message)) {
      result = instance.getParserForType().parseFrom(inputStream);
    } catch (InvalidProtocolBufferException e) {
      LOGGER.log(Level.WARNING, "InvalidProtocolBufferException while parsing byte array to protobuf.", e);
    } catch (IOException e) {
      LOGGER.log(Level.WARNING, "IOException while parsing byte array to protobuf.", e);
    }
    return result;
  }
}
