public static boolean sameStructure(Matrix a, Matrix b) {
    if (a.getRows() != b.getRows() || a.getColumns() != b.getColumns()) {
        return false;
    }
    for (int row = 0; row < a.getRows(); row++) {
        for (int col = 0; col < a.getColumns(); col++) {
            if (a.getValueAt(row, col) != 0 && b.getValueAt(row, col) == 0) {
                return false;
            }
        }
    }
    return true;
}
