import io.grpc.stub.StreamObserver;

public class HelloServiceImpl extends HelloServiceGrpc.HelloServiceImplBase {

    @Override
    public void sayHelloMultipleTimes(HelloRequest request, StreamObserver<HelloReply> responseObserver) {
        StringBuilder messageBuilder = new StringBuilder();
        // Repeat the requested number of times
        for (int i = 0; i < request.getNumberOfTimes(); i++) {
            messageBuilder.append("Hello, ")
                          .append(request.getName())
                          .append("! ")
                          .append("(Number ")
                          .append(i + 1)
                          .append(")\n");
        }
        String message = messageBuilder.toString();
        HelloReply reply = HelloReply.newBuilder().setMessage(message).build();
        responseObserver.onNext(reply);
        responseObserver.onCompleted();
    }
}
