public static int rayCrossings(double x, double y, Shape shape) {
    double[] ray = { x + 1, y }; // define the direction of the ray
    int crossings = 0;
    for (PathIterator pathIter = shape.getPathIterator(null); !pathIter.isDone(); pathIter.next()) {
        double[] coords = new double[6];
        switch (pathIter.currentSegment(coords)) {
        case PathIterator.SEG_MOVETO:
            break;
        case PathIterator.SEG_LINETO:
            crossings += lineCrossings(x, y, ray, coords);
            break;
        case PathIterator.SEG_CLOSE:
            break;
        }
    }
    return crossings;
}

private static int lineCrossings(double x, double y, double[] ray, double[] line) {
    double x1 = line[0];
    double y1 = line[1];
    double x2 = line[2];
    double y2 = line[3];
    double dx = x2 - x1;
    double dy = y2 - y1;
    // check if the line is horizontal or vertical
    if (dx == 0) { // vertical line
        if ((y >= y1 && y < y2) || (y >= y2 && y < y1)) {
            double[] intersection = { x1, y + 1, x2, y + 1 };
            return rayCrossings(x, y, intersection, ray) ? 1 : 0;
        }
    } else if (dy == 0) { // horizontal line
        if ((x >= x1 && x < x2) || (x >= x2 && x < x1)) {
            double[] intersection = { x + 1, y1, x + 1, y2 };
            return rayCrossings(x, y, intersection, ray) ? 1 : 0;
        }
    } else {
        double m = dy / dx; // calculate line slope
        double b = y1 - m * x1; // calculate y-intercept
        double xi = (y - b) / m; // calculate x-intercept at y=y
        if (xi >= x && ((xi <= x2 && dx > 0) || (xi >= x2 && dx < 0))) {
            return 1;
        }
    }
    return 0;
}

private static boolean rayCrossings(double x, double y, double[] line, double[] ray) {
    double x1 = line[0];
    double y1 = line[1];
    double x2 = line[2];
    double y2 = line[3];
    double dx1 = x - x1;
    double dy1 = y - y1;
    double dx2 = x2 - x1;
    double dy2 = y2 - y1;
    double crossProduct = dx1 * dy2 - dy1 * dx2;
    if (crossProduct == 0) {
        return false;
    }
    double t = (ray[1] * dx2 - y1 * dx2 - ray[0] * dy2 + x1 * dy2) / crossProduct;
    double s = (dx1 * dy2 - dy1 * dx2) / crossProduct;
    if (t >= 0 && s >= 0 && s <= 1) {
        return true;
    }
    return false;
}
