public void submitMultiPartForm(String path, FormDataMultiPart formDataMultiPart) throws ClientException {
    String apiUrl = "https://example.com/api/" + path;
    Client client = ClientBuilder.newClient();
    WebTarget target = client.target(apiUrl);
    Invocation.Builder invocationBuilder = target.request(MediaType.APPLICATION_FORM_URLENCODED_TYPE);
