    Map<String, String> map = new HashMap<>();
    String name = null;
    StringBuilder value = null;
    for (int i = offset; i < offset + length; i++) {
        char c = chars[i];
        if (c == separator) {
            map.put(name, value.toString());
            name = null;
            value = null;
        } else if (name == null) {
            name = String.valueOf(c);
            value = new StringBuilder();
        } else {
            value.append(c);
        }
    }
    if (name != null && value != null) {
        map.put(name, value.toString());
    }
    return map;
}
