public Map<String, String> getServletMappings(JBossWebMetaData jbossWebMD) {
    Map<String, String> mappings = new HashMap<>();

    for (ServletMetaData servlet : jbossWebMD.getServlets()) {
        for (String pattern : servlet.getMappings()) {
            mappings.put(servlet.getName(), pattern);
        }
    }

    return mappings;
}
