public void toggleLastOrderBy(List<? extends Comparable<?>> beans, boolean order) {
    if (beans.isEmpty()) {
        return;
    }

    boolean foundOrderBy = false;
    for (int i = beans.size() - 1; i >= 0; i--) {
        Comparable<?> bean = beans.get(i);
        if (bean instanceof OrderBy) {
            OrderBy orderByBean = (OrderBy) bean;
            if (!foundOrderBy) {
                orderByBean.setReverseOrder(order);
                foundOrderBy = true;
            } else {
                orderByBean.setReverseOrder(!order);
                return;
            }
        }
    }
    if (!foundOrderBy) {
        Comparable<?> firstBean = beans.get(0);
        if (firstBean instanceof OrderBy) {
            ((OrderBy) firstBean).setReverseOrder(true);
        } else {
            beans.add(0, new OrderBy(true));
        }
    }
}
