public Node getNode(int nodeID) {
    // Check if the node is a supernode
    if (supernodes.containsKey(nodeID)) {
        return supernodes.get(nodeID);
    }

    // Search for the node in the page file
    for (int i = 0; i < header.getNumNodes(); i++) {
        Node node = readNode(i);
        if (node.getID() == nodeID) {
            return node;
        }
    }

    // Node with the specified id not found
    return null;
}
