public void inverseFFT(double[] data) {
    FastFourierTransformer fft = new FastFourierTransformer();
    fft.transform(data, TransformType.INVERSE);
    double factor = 1.0 / data.length;
    for (int i = 0; i < data.length; i++) {
        data[i] *= factor;
    }
}
