public int findFinalizerPosition(String code) {
    int tryIndex = code.indexOf("try");
    int syncIndex = code.indexOf("synchronized");

    int startIndex = tryIndex != -1 ? tryIndex : syncIndex;
    int endIndex = code.lastIndexOf("}");

    int finalizerIndex = code.indexOf("finally", startIndex);
    if (finalizerIndex != -1 && finalizerIndex < endIndex) {
        return finalizerIndex;
    } else {
        return -1; // finalizer not found
    }
}
