public static <T> Response handleResponseBody(Response response, Function<ResponseBody, T> handler) {
    try (ResponseBody responseBody = response.body()) {
        T result = handler.apply(responseBody);
        return response.newBuilder().body(ResponseBody.create(responseBody.contentType(), result.toString())).build();
    } catch (IOException e) {
        response.close();
        throw new RuntimeException(e);
    }
}
