public boolean optimizedOperator(String operator, FieldTextBuilder fieldText) {
    switch(operator) {
        case "OR":
            return fieldText.build().stream().anyMatch(x -> x);
        case "AND":
            return fieldText.build().stream().allMatch(x -> x);
        case "XOR":
            return fieldText.build().stream().filter(x -> x).count() == 1L;
        default:
            throw new IllegalArgumentException("Invalid operator: " + operator);
    }
}
