import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;

public class HttpRequest {

    public static Response postRequest(String url, String body) throws HttpException {
        StringBuilder response = new StringBuilder();
        try {
            URL urlObject = new URL(url);
            HttpURLConnection connection = (HttpURLConnection) urlObject.openConnection();
            connection.setRequestMethod("POST");
            connection.setRequestProperty("Content-Type", "application/json");
            connection.setDoOutput(true);

            if (body != null) {
                byte[] requestBody = body.getBytes();
                connection.setRequestProperty("Content-Length", String.valueOf(requestBody.length));
                connection.getOutputStream().write(requestBody);
            }

            int responseCode = connection.getResponseCode();

            BufferedReader reader;
            if (responseCode == HttpURLConnection.HTTP_OK) {
                reader = new BufferedReader(new InputStreamReader(connection.getInputStream()));
            } else {
                reader = new BufferedReader(new InputStreamReader(connection.getErrorStream()));
            }

            String line;
            while ((line = reader.readLine()) != null) {
                response.append(line);
            }
            reader.close();
            connection.disconnect();
        } catch (IOException e) {
            throw new HttpException("Invalid input parameters", e);
        }

        return new Response(response.toString(), responseCode);
    }

    static class Response {
        private final String response;
        private final int responseCode;

        Response(String response, int responseCode) {
            this.response = response;
            this.responseCode = responseCode;
        }

        public String getResponse() {
            return response;
        }

        public int getResponseCode() {
            return responseCode;
        }
    }

    static class HttpException extends Exception {
        HttpException(String message, Throwable cause) {
            super(message, cause);
        }
    }
}
