public Asset createAsset(ZipEntry entry) {
    Asset asset = new Asset();
    asset.setName(entry.getName());
    asset.setSize(entry.getSize());
    asset.setCompressedSize(entry.getCompressedSize());
    asset.setCompressionMethod(entry.getMethod());
    asset.setLastModified(entry.getLastModifiedTime().toMillis());

    if (!entry.isDirectory()) {
        if (entry.getMethod() == ZipEntry.STORED) {
            // uncompressed entry
            MemorySlice slice = createMemorySlice(entry.getSize());
            asset.setMemorySlice(slice);
        } else {
            // compressed entry
            asset.setInputStream(getInputStream(entry));
        }
    }
    return asset;
}

private MemorySlice createMemorySlice(long size) {
    // create or reuse shared memory slice
    return MemorySliceFactory.createSlice(size);
}

private InputStream getInputStream(ZipEntry entry) {
    // get input stream for compressed entry
    // may need to decompress on the fly
    return null;
}
