    List<View> res = new ArrayList<>();
    while (!dependencies.isEmpty()) {
        boolean found = false;
        Iterator<Map.Entry<View, Set<View>>> it = dependencies.entrySet().iterator();
        while (it.hasNext()) {
            Map.Entry<View, Set<View>> entry = it.next();
            if (entry.getValue().isEmpty()) {
                found = true;
                View v = entry.getKey();
                res.add(v);
                it.remove();
                for (Set<View> dep : dependencies.values()) {
                    dep.remove(v);
                }
            }
        }
        if (!found) {
            throw new SchedulerException("Dependency cycle detected in views");
        }
    }
    return res;
}
