public void setTaskInterval(String interval) {
    long minimumInterval = 60L; // 1 minute in seconds
    long defaultInterval = 3600L; // 1 hour in seconds
    long parsedInterval = 0L;

    switch(interval.toLowerCase()) {
        case "once":
            parsedInterval = 0L;
            break;
        case "daily":
            parsedInterval = 86400L; // 24 hours in seconds
            break;
        case "weekly":
            parsedInterval = 604800L; // 7 days in seconds
            break;
        case "monthly":
            parsedInterval = 2592000L; // 30 days in seconds (approx.)
            break;
        default:
            try {
                parsedInterval = Long.parseLong(interval);
            } catch(NumberFormatException e) {
                System.out.println("Invalid interval value provided");
                return;
            }
    }

    if(parsedInterval < minimumInterval) {
        System.out.println("Interval value too low, using minimum value of 1 minute");
        parsedInterval = minimumInterval;
    }

    // set parsedInterval as task interval
    // ...
}
