public static <T> List<T> filterArray(Class<T> type, T[] original, boolean ignoreHidden, Function<T, T> filter) {
    List<T> result = new ArrayList<>();
    for (T element : original) {
        if (ignoreHidden && element.toString().startsWith("_")) {
            continue;
        }
        T filteredElement = filter.apply(element);
        if (filteredElement != null) {
            result.add(filteredElement);
        }
    }
    return result;
}
