public int[][] getAdjacencyMatrix(AtomContainer container) {
    int numAtoms = container.getAtomCount();
    int[][] matrix = new int[numAtoms][numAtoms];

    for (int i = 0; i < numAtoms; i++) {
        IAtom atom1 = container.getAtom(i);
        for (int j = 0; j < numAtoms; j++) {
            if (i != j) {
                IAtom atom2 = container.getAtom(j);
                if (container.getConnectedAtomsCount(atom1) > 0 && container.getConnectedAtomsCount(atom2) > 0) {
                    IBond bond = container.getBond(atom1, atom2);
                    if (bond != null) {
                        matrix[i][j] = 1;
                    }
                }
            }
        }
    }

    return matrix;
}
