public Record findRetentionRecordBeforeTime(Time time){
    Record reference = null;
    for(Record r: recordSet){
        if(r.getTime().compareTo(time) <= 0){
            if(reference == null) reference = r;
            else if(r.getTime().compareTo(reference.getTime()) > 0) reference = r;
        }
    }
    return reference;
}
