import java.io.IOException;
import java.io.OutputStream;
import java.security.cert.CertificateEncodingException;

public void encodeASN1DERData(byte[] data, OutputStream out) throws CertificateEncodingException, IOException {
    try {
        // Start the ASN1/DER encoding process
        DEREncoder encoder = new DEREncoder(out);
        encoder.startSequence();

        // Encode the provided data as an octet string
        encoder.writeOctetString(data);

        // End the ASN1/DER encoding process
        encoder.endSequence();
    } catch (IOException e) {
        throw new CertificateEncodingException("Unable to encode ASN1/DER data", e);
    }
}
