public <T> T getNamedConfig(ConfigPatternMatcher patternMatcher, Map<String, ?> configs, String prefix, String name, Class<T> clazz) {
    String namedPrefix = prefix + "." + name;
    Map<String, Object> namedConfigs = new HashMap<>();
    configs.forEach((key, value) -> {
        if (key.startsWith(namedPrefix)) {
            String nestedKey = key.substring(namedPrefix.length() + 1);
            namedConfigs.put(nestedKey, value);
        }
    });
    return ConfigUtils.getConfig(patternMatcher, namedConfigs, "", clazz);
}
