public Set<String> findModelDescriptions(Bundle bundle) {
    Set<String> modelDescriptions = new HashSet<>();
    for (String className : bundle.getClasses()) {
        try {
            Class<?> clazz = bundle.loadClass(className);
            if (isModelClass(clazz)) {
                String description = getModelDescription(clazz);
                modelDescriptions.add(description);
            }
        } catch (ClassNotFoundException e) {
            // ignore
        }
    }
    return modelDescriptions;
}

private boolean isModelClass(Class<?> clazz) {
    // determine if the class is a model class
    // for example, check if it has a certain annotation
    return clazz.isAnnotationPresent(Model.class);
}

private String getModelDescription(Class<?> clazz) {
    // get the description of the model class
    // for example, read a value from an annotation
    Model modelAnnotation = clazz.getAnnotation(Model.class);
    return modelAnnotation.description();
}
