public Collection<Base> getTasksAndTests(Member member, String filter) {
    // Assuming there's a "VersionOneSystem" class with appropriate
    // methods for fetching tasks and tests
    Collection<Task> tasks = VersionOneSystem.getTasksForMember(member);
    Collection<Test> tests = VersionOneSystem.getTestsForMember(member);

    Collection<Base> bases = new ArrayList<>();

    // Filtering tasks and adding them to the bases collection
    for (Task task : tasks) {
        if (task.matchesFilter(filter)) {
            bases.add(task.getBase());
        }
    }

    // Filtering tests and adding them to the bases collection
    for (Test test : tests) {
        if (test.matchesFilter(filter)) {
            bases.add(test.getBase());
        }
    }

    return bases;
}
