public static Integer[] rangeparser(String rangeString, int rangeLimit) {
    String[] ranges = rangeString.split(",");
    List<Integer> rangeList = new ArrayList<>();
    for (String range : ranges) {
        if (range.equals("*")) {
            for (int i = 0; i < rangeLimit; i++) {
                rangeList.add(i);
            }
        } else if (!range.contains("-")) {
            rangeList.add(Integer.parseInt(range) - 1); // adjust to zero-based index
        } else {
            String[] limits = range.split("-");
            int lower = Integer.parseInt(limits[0]);
            int upper = limits[1].equals("*") ? rangeLimit - 1 : Integer.parseInt(limits[1]) - 1;
            for (int i = lower; i <= upper; i++) {
                rangeList.add(i);
            }
        }
    }
    Integer[] result = new Integer[rangeList.size()];
    return rangeList.toArray(result);
}
