public void setSessionAndCookie(HttpServletRequest request, HttpServletResponse response) {
    HttpSession session = request.getSession(true);
    String cookieValue = null;
    Cookie[] cookies = request.getCookies();
    if (cookies != null) {
        for (Cookie cookie : cookies) {
            if (cookie.getName().equals("sessionId")) {
                cookieValue = cookie.getValue();
                break;
            }
        }
    }
    if (cookieValue == null) {
        cookieValue = session.getId();
        Cookie sessionCookie = new Cookie("sessionId", cookieValue);
        sessionCookie.setPath(request.getContextPath());
        response.addCookie(sessionCookie);
    } else {
        if (!cookieValue.equals(session.getId())) {
            session.invalidate();
            cookieValue = session.getId();
            Cookie sessionCookie = new Cookie("sessionId", cookieValue);
            sessionCookie.setPath(request.getContextPath());
            response.addCookie(sessionCookie);
        }
    }
}
