public String postMessengerCode(String input) throws Exception {
    String url = "https://graph.facebook.com/v2.6/me/message_attachments?access_token=<ACCESS_TOKEN>";
    HttpClient client = HttpClientBuilder.create().build();
    HttpPost post = new HttpPost(url);

    StringEntity inputJSON = new StringEntity(input);
    inputJSON.setContentType("application/json");
    post.setEntity(inputJSON);

    HttpResponse response = client.execute(post);
    HttpEntity entity = response.getEntity();

    String output = EntityUtils.toString(entity);
    JSONObject json = new JSONObject(output);

    String attachmentId = json.getString("attachment_id");
    return attachmentId;
}
