public void dumpDataSizeInfo() {
    // Get the data size from the database
    int dataSize = getDataSizeFromDatabase();

    // Print the data size information to the console
    System.out.println("Data size: " + dataSize);

    // Loop through each record in the database and count each one
    int recordCount = 0;
    for (Record record : database.getRecords()) {
        recordCount++;
    }

    // Print the total number of records in the database to the console
    System.out.println("Total records: " + recordCount);

    // Loop through each index in the database and count the number of records in each one
    for (Index index : database.getIndexes()) {
        int indexSize = 0;
        for (Record record : index.getRecords()) {
            indexSize++;
        }
        // Print the number of records in the index to the console
        System.out.println(indexSize + " in " + index.getName() + " index");
    }
}
