public void ensureCapacity(int k){
    // Check if k is greater than zero
    if(k > 0){
        // Get the current capacity of the container
        int currentCapacity = container.length;

        // Check if the current capacity is less than k
        if(currentCapacity < k){
            // Determine the new capacity needed
            int newCapacity = currentCapacity + k;

            // Create a new container with the new capacity
            Object[] newContainer = new Object[newCapacity];

            // Copy the existing elements from the old (existing) container to the new container
            System.arraycopy(container, 0, newContainer, 0, currentCapacity);

            // Assign the new container to the existing container
            container = newContainer;
        }
    }
}
