public class XMLParser {

    public static void findXMLDocuments(File directory) {
        // Get all files in the directory
        File[] files = directory.listFiles();
        if (files != null) {
            for (File file : files) {
                if (file.isDirectory()) {
                    // Recursively call the function if it encounters a subdirectory
                    findXMLDocuments(file);
                } else {
                    // Check if the file is an xml document and parse it
                    if (file.getName().endsWith(".xml")) {
                        parseXMLDocument(file);
                    }
                }
            }
        }
    }

    private static void parseXMLDocument(File xmlFile) {
        // Insert parsing function here
        System.out.println("Parsing XML document: " + xmlFile.getName());
    }

    // Example usage
    public static void main(String[] args) {
        File directory = new File("C:/myDirectory/");
        findXMLDocuments(directory);
    }
}
