public static VINT constructVINT(int value) {
    int numBytes = 0;
    int tmp = value;

    while(tmp > 0) {
        ++numBytes;
        tmp >>>= 7;
    }

    if(numBytes == 0) {
        numBytes = 1;
    }

    byte[] array = new byte[numBytes];
    tmp = value;

    for(int i = numBytes - 1; i > 0; --i) {
        array[i] = (byte)((tmp & 0x7f) | 0x80);
        tmp >>>= 7;
    }

    array[0] = (byte)tmp;
    return new VINT(array);
}
