public void checkPartitionColumns(TypeInfo typeInfo, Map<String, String> partitionValMap, String qualifiedTableName) throws HiveStageCheckedException {
    List<FieldSchema> partitionKeys = typeInfo.getPartitionKeys();

    if (partitionKeys.size() != partitionValMap.size()) {
        throw new HiveStageCheckedException(Utils.format("Mismatch in number of partition keys for table '{}'. Expected '{}', got '{}'",
            qualifiedTableName, partitionKeys.size(), partitionValMap.size()));
    }

    for (FieldSchema partitionKey : partitionKeys) {
        String keyName = partitionKey.getName();

        if (!partitionValMap.containsKey(keyName)) {
            throw new HiveStageCheckedException(Utils.format("Mismatch in partition key names for table '{}'. Expected '{}', got '{}'",
                qualifiedTableName, partitionKeys.stream().map(FieldSchema::getName).collect(Collectors.toList()), partitionValMap.keySet()));
        }
    }
}
