public String[] decomposeCompoundKey(String compoundKey) {
    String[] decomposedKey = compoundKey.split(":");
    for (int i = 0; i < decomposedKey.length; i++) {
        if (decomposedKey[i].startsWith("*")) {
            // If the argument was tainted during composition,
            // mark it as tainted in the decomposed key as well
            decomposedKey[i] = "*".concat(decomposedKey[i].substring(1));
        }
    }
    return decomposedKey;
}
