import java.lang.reflect.*;

public void instantiateAllSingletons() {
    // Get all classes loaded by the current class loader
    Class[] classes = getClassLoader().getLoadedClasses();

    for (Class<?> cls : classes) {
        try {
            // Get the constructor of the class
            Constructor<?> constructor = cls.getDeclaredConstructor();
            // If the constructor is private, make it accessible
            if (!constructor.isAccessible()) {
                constructor.setAccessible(true);
            }
            // Invoke the constructor to create an instance of the class
            Object instance = constructor.newInstance();
        } catch (NoSuchMethodException | InstantiationException | IllegalAccessException | InvocationTargetException e) {
            // Ignore classes that don't have a private constructor or that cannot be instantiated
        }
    }
}
