public PropertyDescriptor getPropertyDescriptor(int col) throws IntrospectionException {
    BeanInfo beanInfo = Introspector.getBeanInfo(getClass());
    PropertyDescriptor[] propertyDescriptors = beanInfo.getPropertyDescriptors();

    for (PropertyDescriptor propertyDescriptor : propertyDescriptors) {
        boolean isCorrectColumn = (Integer) propertyDescriptor.getValue("columnNumber") == col;
        boolean isNotBound = propertyDescriptor.getReadMethod() != null && propertyDescriptor.getWriteMethod() != null;
        if (isCorrectColumn && isNotBound) {
            return propertyDescriptor;
        }
    }

    return null;
}
