public static MethodHandle getOrCreateInterfaceMethod(Class<?> declaringClass, String methodName, MethodType methodType) throws NoSuchMethodException, IllegalAccessException {
    MethodHandle methodHandle = MethodHandles.publicLookup().findVirtual(declaringClass, methodName, methodType);

    if ((methodHandle != null) && ((methodHandle.rawModifiers() & Modifier.ABSTRACT) == Modifier.ABSTRACT)) {
        return methodHandle;
    }

    Class<?>[] interfaces = declaringClass.getInterfaces();

    for (Class<?> inter : interfaces) {
        try {
            methodHandle = MethodHandles.publicLookup().findVirtual(inter, methodName, methodType);

            if ((methodHandle != null) && ((methodHandle.rawModifiers() & (Modifier.ABSTRACT | Modifier.STATIC)) == Modifier.ABSTRACT)) {
                return methodHandle.asType(methodType);
            }
        } catch (IllegalAccessException | NoSuchMethodException ex) {
            continue;
        }
    }

    throw new NoSuchMethodException("No interface method " + methodName + " matches the specified signature.");
}
