import org.apache.hadoop.hbase.client.Scan;
import org.apache.hadoop.hbase.filter.BinaryComparator;
import org.apache.hadoop.hbase.filter.CompareFilter;
import org.apache.hadoop.hbase.filter.FilterList;
import org.apache.hadoop.hbase.filter.SingleColumnValueFilter;
import org.apache.hadoop.hbase.util.Bytes;

public FilterList createHBaseFilter() {

    // Creating filter to exclude transaction state PROCESSED
    SingleColumnValueFilter stateFilter = new SingleColumnValueFilter(
      Bytes.toBytes("family"), Bytes.toBytes("state"), CompareFilter.CompareOp.NOT_EQUAL,
      new BinaryComparator(Bytes.toBytes("PROCESSED"))
    );

    // Creating filter list
    FilterList filters = new FilterList(FilterList.Operator.MUST_PASS_ALL);
    filters.addFilter(stateFilter);

    return filters;
}
