public class ConverterInitializer implements Initializer<Object> {

    public void initialize(WorkUnitState workUnitState) throws Exception {
        // Connect to the database and retrieve the list of date columns existing in the table
        List<String> dateColumns = new ArrayList<String>();
        Connection connection = null;
        Statement statement = null;
        ResultSet resultSet = null;

        try {
            connection = DriverManager.getConnection("jdbc:postgresql://localhost:5432/mydb", "user", "password");
            statement = connection.createStatement();
            resultSet = statement.executeQuery("SELECT column_name FROM information_schema.columns WHERE table_name = 'mytable' AND data_type = 'date'");

            while (resultSet.next()) {
                dateColumns.add(resultSet.getString("column_name"));
            }
        } finally {
            if (resultSet != null) resultSet.close();
            if (statement != null) statement.close();
            if (connection != null) connection.close();
        }

        // Store the list of date columns in the WorkUnit's state store
        workUnitState.getWorkunit().setProp("date.columns", StringUtils.join(dateColumns, ","));
    }
}
