@Override
protected IRuntimeClasspathEntry[] getRuntimeClasspathEntries(ILaunchConfiguration configuration) throws CoreException {
    IRuntimeClasspathEntry[] rawEntries = super.getRuntimeClasspathEntries(configuration);
