public static String alignOutput(String input, int totalWidth) {
    int inputLength = input.length();
    int spacesToAdd = totalWidth - inputLength;

    if (spacesToAdd <= 0) {
        return input;
    } else {
        StringBuilder builder = new StringBuilder(input);

        for (int i = 0; i < spacesToAdd; i++) {
            builder.append(" ");
        }

        return builder.toString();
    }
}
