import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.Iterator;
import java.util.function.Consumer;

public class DatabaseQuery {

    public void query(Connection connection, String sql, Consumer<ResultSet> result, Object... args) throws SQLException {
        PreparedStatement statement = connection.prepareStatement(sql);
        for(int i = 0; i < args.length; i++) {
            statement.setObject(i+1, args[i]);
        }
        ResultSet resultSet = statement.executeQuery();
        Iterator<ResultSet> iterator = new Iterator<ResultSet>() {
            boolean hasNext = resultSet.next();

            @Override
            public boolean hasNext() {
                return hasNext;
            }

            @Override
            public ResultSet next() {
                if(hasNext) {
                    try {
                        ResultSet current = resultSet;
                        hasNext = resultSet.next();
                        return current;
                    } catch(SQLException e) {
                        throw new RuntimeException(e);
                    }
                }
                throw new IllegalStateException();
            }
        };
        while(iterator.hasNext()) {
            result.accept(iterator.next());
        }
    }
}
