public List<RMap> convertRGraphBitsetToRMapList(BitSet set) {
    List<RMap> rMapList = new ArrayList<>();
    for (int i = set.nextSetBit(0); i >= 0; i = set.nextSetBit(i + 1)) {
        RNode node = rGraph.getNode(i);
        RNode projection1 = getProjection(node, G1);
        RNode projection2 = getProjection(node, G2);
        RMap rMap = new RMap(projection1, projection2);
        rMapList.add(rMap);
    }
    return rMapList;
}

private RNode getProjection(RNode node, Graph graph) {
    List<Node> nodes = node.getNodes();
    List<Node> projectionNodes = new ArrayList<>();
    for (Node n : nodes) {
        if (graph.contains(n)) {
            projectionNodes.add(n);
        }
    }
    if (projectionNodes.isEmpty()) {
        return null;
    } else if (projectionNodes.size() == 1 && nodes.size() == 1) {
        return projectionNodes.get(0).asRNode();
    } else {
        return new RNode(projectionNodes);
    }
}
