public Bitmap loadBitmapWithScaling(String fileName, int scale) throws ImageLoadException {
    try {
        File file = new File(fileName);
        FileInputStream stream = new FileInputStream(file);
        Bitmap originalBitmap = BitmapFactory.decodeStream(stream);
        Bitmap scaledBitmap = Bitmap.createScaledBitmap(originalBitmap, originalBitmap.getWidth() / scale, originalBitmap.getHeight() / scale, true);
        return scaledBitmap;
    } catch (IOException e) {
        throw new ImageLoadException("Unable to load file");
    }
}
