public static String unicodeToPoint(String point) {
    int codePoint = Integer.parseInt(point, 16);
    if (Character.isValidCodePoint(codePoint)) {
        if (Character.isBmpCodePoint(codePoint)) {
            return String.valueOf((char) codePoint);
        } else {
            return new String(Character.toChars(codePoint));
        }
    } else {
        throw new IllegalArgumentException("Invalid Unicode code point: " + point);
    }
}
