public <T> T convertResult(Class<T> type, ArangoCursor<?> result) {
    if (result == null || result.getCount() == 0) {
        return null;
    } else if (type.isAssignableFrom(result.getClass())) {
        return type.cast(result);
    } else if (type.isAssignableFrom(Map.class)) {
        return type.cast(result.asListRemaining().get(0).map());
    } else if (type.isAssignableFrom(List.class)) {
        return type.cast(result.asListRemaining());
    } else {
        throw new IllegalArgumentException("Cannot convert to type " + type.getName());
    }
}
