public void updateSnmpUser(String username, String password, String location, String contact) {
   // Assuming this method updates a snmpuser resource by username
   // The method should take in the new values for the password, location, and contact

   // IMPLEMENTATION DETAILS:
   // Here, we would make use of an API or library to execute the snmpuser update request
   // Assuming the API requires the new values to be passed in as parameters

   // Example API call using SNMP4J library
   Snmp snmp = new Snmp(new DefaultUdpTransportMapping());
   UserTarget target = new UserTarget();
   target.setVersion(SnmpConstants.version3);
   target.setAddress(GenericAddress.parse("udp:127.0.0.1/161"));
   target.setSecurityName(new OctetString(username));

   // Create user with new details
   UsmUser user = new UsmUser(new OctetString(username), AuthSHA.ID, new OctetString(password), PrivDES.ID, new OctetString(password));

   // Set user security parameters
   UsmUserEntry userEntry = new UsmUserEntry(user.getSecurityName());
   userEntry.setCloneFrom(snmp.getUSM().getUserTable().getUserEntry(new OctetString(username)));
   userEntry.setUsmUser(user);

   // Set user location and contact
   userEntry.setUsmUserLoc(new OctetString(location));
   userEntry.setUsmUserAuthProtocol(AuthSHA.ID);
   userEntry.setUsmUserPrivProtocol(PrivDES.ID);

   snmp.getUSM().updateUser(userEntry);
   snmp.close();
}
