public List<String> getPositionedTermsByPrefixesAndPositionRange(String field, int docId, List<String> prefixes, int startPosition, int endPosition) throws IOException {
   List<String> positionedTerms = new ArrayList<>();
   IndexReader reader = DirectoryReader.open(directory);
   Terms terms = reader.getTermVector(docId, field);
   if (terms == null) {
       return positionedTerms;
   }
   TermsEnum termsEnum = terms.iterator();
   BytesRef bytesRef;
   while ((bytesRef = termsEnum.next()) != null) {
       String term = bytesRef.utf8ToString();
       if (!prefixes.isEmpty() && !prefixes.stream().anyMatch(term::startsWith)) {
           continue;
       }
       PostingsEnum postingsEnum = termsEnum.postings(null, PostingsEnum.POSITIONS);
       int position;
       while ((position = postingsEnum.nextPosition()) != PostingsEnum.NO_MORE_POSITIONS) {
           if (position >= startPosition && position <= endPosition) {
               positionedTerms.add(term);
               break;
           }
       }
   }
   reader.close();
   return positionedTerms;
}
