public static <E extends Enum<E> & MpxjEnum> int[] createLookupArray(Class<E> c, int arraySizeOffset) {
    E[] values = c.getEnumConstants();
    int[] lookupArray = new int[values.length + arraySizeOffset];
    for (E value : values) {
        lookupArray[value.getValue()] = value.ordinal();
    }
    return lookupArray;
}
