public void openForWriteWithDifferentWaveParams(File file, WaveParams params) throws IOException {
    AudioFormat format = new AudioFormat(params.getSampleRate(),
                                          params.getSampleSizeInBits(),
                                          params.getChannels(),
                                          true, // signed
                                          false); // littleEndian
    AudioFileFormat.Type type = AudioFileFormat.Type.WAVE;

    // Open a new audio output stream using the specified file and audio format
    AudioOutputStream out = AudioSystem.getAudioOutputStream(format, null);

    FileOutputStream fos = new FileOutputStream(file);
    BufferedOutputStream bos = new BufferedOutputStream(fos);
    out = new AudioOutputStream(bos, format, out.getLength());

    // Set the output stream to the specified file type
    out.setFileType(type);

    // Write the header of the specified wave parameters to the output stream
    WaveFileHeader header = WaveFileHeader.create(params);
    header.writeToStream(out);

    // Save the output stream for writing audio data later
    this.outputStream = out;
}
