@Override
public V put(K key, V value) {
    if (key == null) {
        throw new NullPointerException("Key cannot be null");
    }

    // compute hash code based on key
    int hash = hash(key);

    // find the bucket index to store the key-value pair
    int bucketIndex = getBucketIndex(hash);

    // if the bucket is null, create it
    if (buckets[bucketIndex] == null) {
        buckets[bucketIndex] = new LinkedList<>();
    }

    // search for the key in the bucket, if found update the value
    // otherwise add the key-value pair to the bucket
    for (Entry<K, V> entry : buckets[bucketIndex]) {
        if (entry.key.equals(key)) {
            V oldValue = entry.value;
            entry.value = value;
            return oldValue;
        }
    }
    buckets[bucketIndex].add(new Entry<>(key, value, hash));
    size++;

    // resize the hashmap if the load factor exceeds the threshold
    if (loadFactor() > LOAD_FACTOR_THRESHOLD) {
        resize();
    }
    return null;
}
