public static long parseRFC2109Time(String timeStr) throws ParseException {
    DateFormat rfc2109Format = new SimpleDateFormat("EEE, dd-MMM-yyyy HH:mm:ss 'GMT'", Locale.US);
    rfc2109Format.setTimeZone(TimeZone.getTimeZone("GMT"));

    Date date = null;
    try {
        date = rfc2109Format.parse(timeStr);
    } catch (ParseException e) {
        // Try to fallback onto new date format
        DateFormat rfc2109FallbackFormat = new SimpleDateFormat("EEE MMM dd HH:mm:ss yyyy", Locale.US);
        rfc2109FallbackFormat.setTimeZone(TimeZone.getTimeZone("GMT"));
        try {
            date = rfc2109FallbackFormat.parse(timeStr);
        } catch (ParseException e1) {
            throw new ParseException("Unable to parse date " + timeStr, 0);
        }
    }

    return date.getTime();
}
