public static List<String> listGoogleCompilerErrors(String result) {
    List<String> errors = new ArrayList<>();
    String[] lines = result.split("\\r?\\n"); // split the result into an array of lines
    for (String line : lines) {
        if (line.startsWith("error: ")) { // check if the line starts with the error message prefix
            errors.add(line.substring(7)); // remove the prefix and add the error message to the list
        }
    }
    return errors;
}
