private void setHeadAndPropagate(Node node, int propagate) {
    Node h = head; // Save head node
    setHead(node); // Set head to the new node
    /*
     * Try to signal next queued node in case of propagate > 0 or PROPAGATE status was set
     */
    if (propagate > 0 || h == null || h.waitStatus < 0 || (h = head) == null || h.waitStatus < 0) {
        Node s = node.next;
        if (s == null || s.isShared())
            doReleaseShared();
    }
}
