public void setCustomLayer(BufferedImage customLayer) {
    int width = getWidth();
    int height = getHeight();
    BufferedImage scaledLayer = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
    Graphics2D g2d = scaledLayer.createGraphics();
    g2d.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
