public void applySuggestedFixes(Map<String, List<String>> suggestedFixes) {
    for (Map.Entry<String, List<String>> entry : suggestedFixes.entrySet()) {
        String fileName = entry.getKey();
        List<String> fixes = entry.getValue();

        try {
            File file = new File(fileName);
            if (!file.exists()) {
                throw new IllegalArgumentException("File " + fileName + " does not exist.");
            }

            String content = new String(Files.readAllBytes(Paths.get(fileName)));
            for (String fix : fixes) {
                String[] parts = fix.split(":");
                int position = Integer.parseInt(parts[0]);
                String text = parts[1];

                content = content.substring(0, position) + text + content.substring(position + text.length());
            }

            Files.write(Paths.get(fileName), content.getBytes());

        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
