public double[][] applyNormalization(double[][] H, double[][] Norm) {
    // Check if the dimensions of H and Norm match
    if (H.length != 3 || Norm.length != 3 || H[0].length != Norm[0].length) {
        throw new IllegalArgumentException("Invalid matrix dimensions for H and/or Norm");
    }

    // Apply normalization to each column of H
    int n = H[0].length;
    double[][] out = new double[3][n];
    for (int j = 0; j < n; j++) {
        for (int i = 0; i < 3; i++) {
            out[i][j] = Norm[i][0] * H[0][j] + Norm[i][1] * H[1][j] + Norm[i][2] * H[2][j];
        }
    }

    return out;
}
