public Collection sortFields(Collection fields) {
   List<Field> sortedFields = new ArrayList<>(fields);
   Collections.sort(sortedFields, new Comparator<Field>() {
      @Override
      public int compare(Field f1, Field f2) {
         if (f1.getName().equals(f2.getName())) {
            if (f1.getDeclaringClass().isAssignableFrom(f2.getDeclaringClass())) {
               return 1;
            }
            else {
               return -1;
            }
         }
         else {
            return f1.getName().compareTo(f2.getName());
         }
      }
   });
   return sortedFields;
}
