@Override
public RiksdagenPerson getPerson(String personId) throws ExternalSystemException {
    try {
        String url = String.format("https://data.riksdagen.se/person/%s/json", personId);
        String response = getResponseFromUrl(url);
        return objectMapper.readValue(response, RiksdagenPerson.class);
    } catch (IOException e) {
        throw new ExternalSystemException("Error while trying to retrieve person data from Riksdagen API", e);
    }
}

private String getResponseFromUrl(String url) throws IOException {
    URLConnection conn = new URL(url).openConnection();
    try (InputStream in = conn.getInputStream()) {
        return new String(in.readAllBytes(), StandardCharsets.UTF_8);
    }
}
