public void writeResponseBodyToWriter(Response response, Writer writer) throws IOException {
    Charset charset = response.charset();
    if (charset == null) {
        MediaType mediaType = response.body().contentType();
        if (mediaType != null) {
            charset = mediaType.charset();
        }
        if (charset == null) {
            charset = Charset.forName("UTF-8");
        }
    }

    try (Reader reader = response.body().charStream();
         PrintWriter out = new PrintWriter(new OutputStreamWriter(writer, charset))) {
        char[] buffer = new char[4096];
        int readChars;
        while ((readChars = reader.read(buffer)) != -1) {
            out.write(buffer, 0, readChars);
        }
        out.flush();
    }
}
