import java.io.BufferedReader;
import java.io.IOException;
import java.util.regex.Pattern;
import java.util.regex.Matcher;

public class PrefixTreeCreator {
    public PrefixTreeNode createPrefixTree(BufferedReader reader) throws IOException {
        PrefixTreeNode root = new PrefixTreeNode();
        String line;
        while ((line = reader.readLine()) != null) {
            // Ignore comments and empty lines
            if (line.startsWith("//") || line.isEmpty()) {
                continue;
            }
            // Ignore exceptions/notations
            if (line.startsWith("!")) {
                continue;
            }

            // Convert domain segments to SURT-ordering
            String surtLine = toSurt(line.trim());

            // Add the domain to the prefix tree
            addToPrefixTree(surtLine.split("\\."), root);
        }
        return root;
    }

    private String toSurt(String domain) {
        String[] segments = domain.split("\\.");
        StringBuilder builder = new StringBuilder();

        // Traverse the domain from right to left and add each segment to the builder in SURT-ordering
        for (int i = segments.length - 1; i >= 0; i--) {
            builder.append(",").append(segments[i]);
        }
        builder.append(")");
        return builder.toString();
    }

    private void addToPrefixTree(String[] segments, PrefixTreeNode node) {
        // If there are no more segments to add, just mark the node as a leaf
        if (segments.length == 0) {
            node.setLeaf(true);
            return;
        }

        // If the first segment is a wildcard, add it to the node and continue with the rest of the segments
        if (segments[0].equals("*")) {
            if (node.getWildcard() == null) {
                node.setWildcard(new PrefixTreeNode());
            }
            addToPrefixTree(slice(segments, 1), node.getWildcard());
            return;
        }

        // Add the first segment to the node and continue with the rest of the segments
        PrefixTreeNode child = node.getChildren().get(segments[0]);
        if (child == null) {
            child = new PrefixTreeNode();
            node.getChildren().put(segments[0], child);
        }
        addToPrefixTree(slice(segments, 1), child);
    }

    private String[] slice(String[] segments, int startIndex) {
        String[] result = new String[segments.length - startIndex];
        System.arraycopy(segments, startIndex, result, 0, result.length);
        return result;
    }

    private class PrefixTreeNode {
        private Map<String, PrefixTreeNode> children;
        private boolean isLeaf;
        private PrefixTreeNode wildcard;

        public PrefixTreeNode() {
            children = new HashMap<>();
            isLeaf = false;
            wildcard = null;
        }

        public Map<String, PrefixTreeNode> getChildren() {
            return children;
        }

        public boolean isLeaf() {
            return isLeaf;
        }

        public void setLeaf(boolean leaf) {
            isLeaf = leaf;
        }

        public PrefixTreeNode getWildcard() {
            return wildcard;
        }

        public void setWildcard(PrefixTreeNode wildcard) {
            this.wildcard = wildcard;
        }
    }
}
