import javax.net.ssl.SSLContext;
import javax.net.ssl.SSLSocketFactory;
import java.security.KeyManagementException;
import java.security.NoSuchAlgorithmException;
import java.security.SecureRandom;
import java.security.cert.CertificateException;
import java.security.cert.X509Certificate;

public class SSLFactoryCreator {

    public static SSLSocketFactory createTrustedSSLSocketFactory(X509Certificate certificate) throws KeyManagementException, NoSuchAlgorithmException {
        SSLContext sslContext = SSLContext.getInstance("SSL");

        sslContext.init(null, new TrustManager[] {
            new X509TrustManager() {
                public void checkClientTrusted(X509Certificate[] chain, String authType) throws CertificateException {}

                public void checkServerTrusted(X509Certificate[] chain, String authType) throws CertificateException {
                    if (chain == null || chain.length == 0) {
                        throw new IllegalArgumentException("Certificate chain was null or contained no certificates for authType " + authType + ".");
                    }
                    if (certificate.equals(chain[0])) {
                        return;
                    }
                    throw new CertificateException("Unable to establish secure connection with the server because of an unrecognized server certificate.");
                }

                public X509Certificate[] getAcceptedIssuers() {
                    return new X509Certificate[0];
                }
            }
        }, new SecureRandom());

        return sslContext.getSocketFactory();
    }
}
