public Bitmap drawTile(Bitmap[][] tileMatrix, List<TileResult> tileResults, BoundingBox requestProjectedBoundingBox, int tileWidth, int tileHeight) {

    // Iterate over the list of tile results to get the relevant tile
    Bitmap bitmap = null;
    for (TileResult tileResult : tileResults) {
        if (tileResult.getBoundingBox().equals(requestProjectedBoundingBox)) {
            int column = tileResult.getColumn();
            int row = tileResult.getRow();
            bitmap = tileMatrix[column][row];
            break;
        }
    }

    // Resize the bitmap to match the desired tile width and height
    if (bitmap != null) {
        return Bitmap.createScaledBitmap(bitmap, tileWidth, tileHeight, false);
    }

    return null;
}
