public int getIntegerPropertyValue(String pstrSection, String pstrProp) {
    // Assuming that the INI file is already loaded and parsed into a data structure
    int value = 0; // default value
    if (iniData.containsKey(pstrSection)) { // check if the section exists
        HashMap<String, String> section = iniData.get(pstrSection);
        if (section.containsKey(pstrProp)) { // check if the property exists
            String propValue = section.get(pstrProp);
            try {
                value = Integer.parseInt(propValue); // try to parse the property value as integer
            } catch (NumberFormatException e) {
                // handle the case when the property value is not a valid integer
                e.printStackTrace();
            }
        }
    }
    return value;
}
