public String renderDataAnalysisAsHtml(DataAnalysis analysis) {
    StringBuilder htmlBuilder = new StringBuilder();
    htmlBuilder.append("<html><head><title>Data Analysis Report</title>");
    htmlBuilder.append("<style type='text/css'>");
    htmlBuilder.append("table {border-collapse: collapse; width: 100%;}");
    htmlBuilder.append("table, th, td {border: 1px solid black;}");
    htmlBuilder.append("</style></head><body>");
    //Generate summary table for data analysis
    htmlBuilder.append("<h1>Summary</h1>");
    htmlBuilder.append("<table>");
    htmlBuilder.append("<tr><th>Column Name</th><th>Type</th><th>Min</th><th>Max</th><th>Mean</th><th>Median</th></tr>");
    for(ColumnSummary summary : analysis.getColumnSummaries()){
        htmlBuilder.append("<tr><td>").append(summary.getColumnName()).append("</td>");
        htmlBuilder.append("<td>").append(summary.getColumnType()).append("</td>");
        htmlBuilder.append("<td>").append(summary.getMinValue()).append("</td>");
        htmlBuilder.append("<td>").append(summary.getMaxValue()).append("</td>");
        htmlBuilder.append("<td>").append(summary.getMeanValue()).append("</td>");
        htmlBuilder.append("<td>").append(summary.getMedianValue()).append("</td></tr>");
    }
    htmlBuilder.append("</table>");
    // Generate Charts for numerical columns
    htmlBuilder.append("<h1>Charts</h1>");
    for(ColumnSummary summary : analysis.getColumnSummaries()){
        if(summary.getColumnType() == ColumnType.NUMERIC){
