import java.io.File;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.text.SimpleDateFormat;
import java.util.Date;

public class BackupUtils {

    public static void backupDirectory(String pathToDirectory, int maxBackups) throws Exception {

        // Create a Path object from the directory path 
        Path directoryPath = Paths.get(pathToDirectory);

        // Get the name of the directory
        String directoryName = directoryPath.getFileName().toString();

        // Create a SimpleDateFormat object to format the date and time
        SimpleDateFormat dateFormat = new SimpleDateFormat("yyyyMMdd_HHmmss");

        // Create a new directory with the name of the original directory and the current date and time
        String backupDirectoryName = directoryName + "_" + dateFormat.format(new Date());
        Files.createDirectories(Paths.get(backupDirectoryName));

        // Check if the maximum number of backups has been reached
        File directory = new File(pathToDirectory);
        File[] backupFiles = directory.listFiles((dir, name) -> name.contains(directoryName));
        if (backupFiles != null && backupFiles.length >= maxBackups) {
            // Remove the oldest backup
            File oldestBackup = backupFiles[0];
            for (File backup : backupFiles) {
                if (backup.lastModified() < oldestBackup.lastModified()) {
                    oldestBackup = backup;
                }
            }
            Files.deleteIfExists(oldestBackup.toPath());
        }

        // Copy the contents of the original directory to the new backup directory
        Files.walk(directoryPath).forEach(source -> {
            Path destination = Paths.get(backupDirectoryName, source.toString().replace(pathToDirectory, ""));
            try {
                Files.copy(source, destination);
            } catch (Exception ex) {
                System.out.println(ex.getMessage());
            }
        });
    }
}
