public static Throwable createCopy(Throwable throwable, ExceptionTruncation truncation) {
    if (truncation == ExceptionTruncation.NONE || throwable == null) {
        return throwable;
    }

    String message = throwable.getMessage();
    if (truncation == ExceptionTruncation.MESSAGE_ONLY) {
        return new Throwable(message);
    }

    StackTraceElement[] trace = throwable.getStackTrace();
    int copyLength = Math.min(trace.length, truncation.getMaxStackSize());
    StackTraceElement[] copy = new StackTraceElement[copyLength];
    System.arraycopy(trace, 0, copy, 0, copyLength);

    Throwable result = new Throwable(message);
    result.setStackTrace(copy);
    return result;
}
