import org.codehaus.groovy.control.CompilerConfiguration;
import org.codehaus.groovy.control.CompilerConfiguration.ErrorCollector;
import org.codehaus.groovy.tools.GroovyClass;

public GroovyClass compileGroovySourceCode(String sFilterCode) throws org.codehaus.groovy.control.CompilationFailedException {
    CompilerConfiguration config = new CompilerConfiguration();
    ErrorCollector errorCollector = new ErrorCollector(config);
    GroovyClassLoader groovyClassLoader = new GroovyClassLoader(Thread.currentThread().getContextClassLoader(), config);
    GroovyCodeSource codeSource = new GroovyCodeSource(sFilterCode, "GroovyFilterScript", "/groovy/shell");

    CompilationUnit compilationUnit = new CompilationUnit(config, codeSource.getCodeSource(), groovyClassLoader);
    compilationUnit.addSource(codeSource.getName(), codeSource.getScriptText());

    compilationUnit.compile();

    GroovyClass groovyClass = compilationUnit.getGroovyClass(codeSource.getName().replaceAll("\\.","_"));

    if (!errorCollector.getExceptionCollector().isEmpty()) {
        throw errorCollector.getExceptionCollector().getErrors().get(0);
    }

    return groovyClass;
}
