public class Base64InputStreamDecoder {
    public static InputStream decode(String base64EncodedString) throws IOException {
        byte[] bytes = Base64.getDecoder().decode(base64EncodedString);
        File tempFile = File.createTempFile("base64DecodedFile", ".tmp");
        OutputStream outputStream = new FileOutputStream(tempFile);
        outputStream.write(bytes);
        outputStream.close();
        return new FileInputStream(tempFile);
    }
}
