public String scanNextToken(Pattern pattern) throws IOException {
    Scanner scanner = new Scanner(System.in);
    String token = "";
    while (true) {
        try {
            token = scanner.findWithinHorizon(pattern, 0);
            if (token != null) {
                break;
            }
            if (scanner.ioException() != null) {
                throw scanner.ioException();
            }
        } catch (Exception ex) {
            throw new IOException(ex);
        }
    }
    return token;
}
