public static <I> DFACacheOracle<I> createPrefixClosedCacheOracle(List<I> alphabet, MembershipOracle<I, Boolean> delegate) {
        DFAEquivalenceOracle<I> eqOracle = new DFACachingEquivalenceOracle<>(delegate);
        CompactDFA<I> hypothesis = new CompactDFA<>(alphabet);
