import java.sql.Timestamp;
import java.time.LocalDateTime;
import java.time.OffsetDateTime;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;

public Timestamp parseTimestamp(String value, String timeZonekey) {

    DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");

    OffsetDateTime odt;

    try {
        odt = LocalDateTime.parse(value, formatter).atOffset(ZoneOffset.UTC);
    } catch (DateTimeParseException e) {
        throw new IllegalArgumentException("Invalid timestamp format", e);
    }

    if (value.contains("Z")) {
        odt = odt.withOffsetSameInstant(ZoneOffset.UTC);
    } else if (value.contains("+") || value.contains("-")) {
        int index = value.indexOf('+') != -1 ? value.indexOf('+') : value.indexOf('-');
        String zone = value.substring(index);
        odt = odt.withOffsetSameInstant(OffsetDateTime.parse(zone).getOffset());
    } else {
        odt = odt.withOffsetSameInstant(ZoneId.of(timeZonekey).getRules().getOffset(odt.toInstant()));
    }

    return Timestamp.valueOf(odt.atZoneSameInstant(ZoneOffset.UTC).toLocalDateTime());
}
