public int dumpFileToPrintWriter(InputStream is, PrintWriter pw) throws Exception {
  int totalBytesRead = 0;
  byte[] buffer = new byte[16];
  int bytesRead;
  while ((bytesRead = is.read(buffer)) != -1) {
    // write hex data to print writer
    StringBuilder hexData = new StringBuilder();
    for (int i = 0; i < 16; i++) {
      if (i < bytesRead) {
        hexData.append(String.format("%02X ", buffer[i]));
      } else {
        hexData.append("   ");
      }
      if (i == 7) {
        hexData.append(" ");
      }
    }
    pw.print(hexData.toString());

    // write ascii data to print writer
    StringBuilder asciiData = new StringBuilder();
    for (int i = 0; i < 16; i++) {
      if (i < bytesRead) {
        char c = (char) buffer[i];
        asciiData.append(Character.isISOControl(c) ? '.' : c);
      } else {
        asciiData.append(" ");
      }
    }
    pw.println(" | " + asciiData.toString());

    totalBytesRead += bytesRead;
  }
  return totalBytesRead;
}
