public void setBit(int i) {
    if (i < 0) {
        throw new IllegalArgumentException("i cannot be negative.");
    }

    int index = i / 32;
    if (index >= sparseBitmap.size()) {
        for (int j = sparseBitmap.size(); j <= index; j++) {
            sparseBitmap.add(0);
        }
    }

    int bitIndex = i % 32;
    int mask = 1 << bitIndex;
    if ((sparseBitmap.get(index) & mask) != 0) {
        throw new IllegalArgumentException("Bit at position " + i + " is already set to true.");
    }

    sparseBitmap.set(index, sparseBitmap.get(index) | mask);
