public class AgglomerativeClustering {
    private final SimilarityFunction similarityFunction;
    private final ClusterLink clusterLink;

    public AgglomerativeClustering(SimilarityFunction similarityFunction, ClusterLink clusterLink) {
        this.similarityFunction = similarityFunction;
        this.clusterLink = clusterLink;
    }

    public Map<Set<Integer>, Double> cluster(List<double[]> datapoints) {
        int numOfDatapoints = datapoints.size();
        double[][] similarityMatrix = new double[numOfDatapoints][numOfDatapoints];
        Map<Set<Integer>, Double> clusters = new HashMap<>();
        for (int i = 0; i < numOfDatapoints; i++) {
            for (int j = i+1; j < numOfDatapoints; j++) {
                similarityMatrix[i][j] = similarityFunction.compute(datapoints.get(i), datapoints.get(j));
                similarityMatrix[j][i] = similarityMatrix[i][j];
            }
            Set<Integer> clusterSet = new HashSet<>();
            clusterSet.add(i);
            clusters.put(clusterSet, 0.0);
        }
        while (clusters.size() > 1) {
            double maxSimilarity = Double.NEGATIVE_INFINITY;
            Set<Integer> cluster1 = null;
            Set<Integer> cluster2 = null;
            for (Map.Entry<Set<Integer>, Double> entry1 : clusters.entrySet()) {
                for (Map.Entry<Set<Integer>, Double> entry2 : clusters.entrySet()) {
                    if (entry1 == entry2) {
                        continue;
                    }
                    Set<Integer> set1 = entry1.getKey();
                    Set<Integer> set2 = entry2.getKey();
                    double similarity = getClusterSimilarity(set1, set2, similarityMatrix);
                    if (similarity > maxSimilarity) {
                        maxSimilarity = similarity;
                        cluster1 = set1;
                        cluster2 = set2;
                    }
                }
            }
            mergeClusters(cluster1, cluster2, clusters, similarityMatrix);
        }
        return clusters;
    }

    private double getClusterSimilarity(Set<Integer> set1, Set<Integer> set2, double[][] similarityMatrix) {
        double similarity = Double.NEGATIVE_INFINITY;
        for(Integer i : set1) {
            for (Integer j : set2) {
                if (similarityMatrix[i][j] > similarity) {
                    similarity = similarityMatrix[i][j];
                }
            }
        }
        return similarity;
    }

    private void mergeClusters(Set<Integer> cluster1, Set<Integer> cluster2, Map<Set<Integer>, Double> clusters, double[][] similarityMatrix) {
        Set<Integer> mergedSet = new HashSet<>();
        mergedSet.addAll(cluster1);
        mergedSet.addAll(cluster2);
        clusters.remove(cluster1);
        clusters.remove(cluster2);
        double maxSimilarity = Double.NEGATIVE_INFINITY;
        for(Integer i : mergedSet) {
            for (Integer j : mergedSet) {
                if (i != j) {
                    similarityMatrix[i][j] = similarityFunction.compute(getDataPoint(i), getDataPoint(j));
                    if (similarityMatrix[i][j] > maxSimilarity) {
                        maxSimilarity = similarityMatrix[i][j];
                    }
                }
            }
        }
        clusters.put(mergedSet, maxSimilarity);
    }

    private double[] getDataPoint(int idx) {
        return datapoints.get(idx);
    }
}
