public ApplicationContext loadParentApplicationContext(ServletContext servletContext, String key) {
    Assert.notNull(servletContext, "ServletContext must not be null");
    Assert.notNull(key, "Key must not be null");

    ServletContext parentServletContext = servletContext.getParent();
    if (parentServletContext == null) {
        throw new IllegalStateException("No parent ServletContext found");
    }

    return (ApplicationContext) parentServletContext.getAttribute(key);
}
