    } else if (pQualityStr.equals("SCALE_FAST")) {
        return java.awt.Image.SCALE_FAST;
    } else if (pQualityStr.equals("SCALE_REPLICATE")) {
        return java.awt.Image.SCALE_REPLICATE;
    } else if (pQualityStr.equals("SCALE_AREA_AVERAGING")) {
        return java.awt.Image.SCALE_AREA_AVERAGING;
    } else {
        return defaultQuality;
    }
}
