public static LottieAnimationView parseAnimationFromAsset(Context context, String animationFileName) {

    LottieAnimationView animationView = new LottieAnimationView(context);
    InputStream stream = null;

    try {
        stream = context.getAssets().open(animationFileName);
        LottieComposition composition = LottieCompositionFactory.fromJsonInputStreamSync(stream, animationFileName).getValue();
        animationView.setComposition(composition);
    } catch (IOException e) {
        Log.e(TAG, "Failed to open " + animationFileName, e);
    } finally {
        if (stream != null) {
            try {
                stream.close();
            } catch (IOException e) {
                Log.e(TAG, "Failed to close " + animationFileName, e);
            }
        }
    }
    return animationView;
}
