public static <T> T readObjectFromFile(File file, Class<T> type) throws IOException, ClassNotFoundException {
        Objects.requireNonNull(file, "File cannot be null");
        Objects.requireNonNull(type, "Type cannot be null");

        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(file))) {
            Object obj = ois.readObject();
            if (type.isInstance(obj)) {
                return type.cast(obj);
            } else {
                throw new ClassCastException("Object read from file is not of type " + type.getName());
            }
        } catch (EOFException e) {
            throw new IOException("End of file reached.", e);
        }
    }
