public static Object createEmptyPrimitiveAttribute(AttributeInfo info) {
    Class<?> attributeType = info.getAttributeType();
    if (attributeType.equals(Integer.class) || attributeType.equals(int.class)) {
        return null; // primitive int can't be null, so returning null for empty attribute.
    } else if (attributeType.equals(Double.class) || attributeType.equals(double.class)) {
        return null; // primitive double can't be null, so returning null for empty attribute.
    } else if (attributeType.equals(Float.class) || attributeType.equals(float.class)) {
        return null; // primitive float can't be null, so returning null for empty attribute.
    } else if (attributeType.equals(Boolean.class) || attributeType.equals(boolean.class)) {
        return null; // primitive boolean can't be null, so returning null for empty attribute.
    } else if (attributeType.equals(Character.class) || attributeType.equals(char.class)) {
        return null; // primitive char can't be null, so returning null for empty attribute.
    } else if (attributeType.equals(Byte.class) || attributeType.equals(byte.class)) {
        return null; // primitive byte can't be null, so returning null for empty attribute.
    } else if (attributeType.equals(Short.class) || attributeType.equals(short.class)) {
        return null; // primitive short can't be null, so returning null for empty attribute.
    } else if (attributeType.equals(Long.class) || attributeType.equals(long.class)) {
        return null; // primitive long can't be null, so returning null for empty attribute.
    } else {
        return null; // returning null for unknown attribute type.
    }
}
