public void deleteXMLResource(String resourceName, int nodeId) throws JaxRxException {
    if(nodeId == 0) {
        throw new JaxRxException("Cannot delete root node");
    }

    String deleteQuery = "DELETE FROM " + resourceName + " WHERE id = ?";
    try (Connection conn = DriverManager.getConnection(dbUrl, dbUser, dbPassword);
         PreparedStatement pstmt = conn.prepareStatement(deleteQuery)) {
        pstmt.setInt(1, nodeId);
        int rowsAffected = pstmt.executeUpdate();
        if(rowsAffected == 0) {
            throw new JaxRxException("Node with id " + nodeId + " not found in " + resourceName);
        }
    } catch (SQLException e) {
        throw new JaxRxException(e.getMessage());
    }
}
