/**
 * Set the Guaranteed Delivery Value RequestedOnly value in the message.
 *
 * @param message the message to set the value in
 * @param value the value to set
 * @throws JsMessageException if the message is null or if the value is not a valid Guaranteed Delivery Value
 */
public void setGuaranteedDeliveryRequestedOnly(Message message, String value) throws JsMessageException {
  if(message == null) {
    throw new JsMessageException("Message cannot be null");
  }
  if(!isValidGuaranteedDeliveryValue(value)) {
    throw new JsMessageException("Invalid Guaranteed Delivery Value");
  }
  message.setGuaranteedDeliveryRequestedOnly(value);
}

/**
 * Check if a string represents a valid Guaranteed Delivery Value
 *
 * @param value the string to check
 * @return true if the value is a valid Guaranteed Delivery Value, false otherwise
 */
private boolean isValidGuaranteedDeliveryValue(String value) {
  return value != null && (value.equalsIgnoreCase("true") || value.equalsIgnoreCase("false"));
}
