public static Point getPositionAlongPath(Point startPoint, Point endPoint, long durationMillis, long elapsedMillis) {
    double fractionComplete = Math.min(1.0, (double) elapsedMillis / (double) durationMillis);
    double x = startPoint.getX() + ((endPoint.getX() - startPoint.getX()) * fractionComplete);
    double y = startPoint.getY() + ((endPoint.getY() - startPoint.getY()) * fractionComplete);
    return new Point(x, y);
}
