public static RoundedMoney createRoundedMoney(String currencyCode, BigDecimal number) {
    Objects.requireNonNull(currencyCode, "currencyCode cannot be null");

    Currency currency;
    try {
        currency = Currency.getInstance(currencyCode);
    } catch (Exception e) {
        throw new IllegalArgumentException("Invalid currency code", e);
    }

    if (number == null) {
        throw new NullPointerException("number cannot be null");
    }

    return new RoundedMoney(number.setScale(currency.getDefaultFractionDigits(), RoundingMode.HALF_EVEN), currency);
}
