public Record getNextDecodableRecord() {
    Record record = null;

    // loop through all partitions
    while (currentPartitionIndex < numPartitions) {
        // check if current partition has decodable records
        if (partitions[currentPartitionIndex].hasDecodableRecords()) {
            // get the next decodable record
            record = partitions[currentPartitionIndex].getNextDecodableRecord();
            break;
        } else {
            // move on to the next partition
            currentPartitionIndex++;
        }
    }

    return record;
}
