import java.security.GeneralSecurityException;
import javax.crypto.Cipher;
import javax.crypto.SecretKeyFactory;
import javax.crypto.spec.PBEKeySpec;
import javax.crypto.spec.PBEParameterSpec;

public static Cipher createCipher(String algorithm, int mode, char[] password, byte[] salt, int count) throws GeneralSecurityException {
    PBEKeySpec keySpec = new PBEKeySpec(password);
    SecretKeyFactory keyFactory = SecretKeyFactory.getInstance(algorithm);
    byte[] keyBytes = keyFactory.generateSecret(keySpec).getEncoded();
    PBEParameterSpec paramSpec = new PBEParameterSpec(salt, count);
    Cipher cipher = Cipher.getInstance(algorithm);
    cipher.init(mode, new SecretKeySpec(keyBytes, algorithm), paramSpec);
    return cipher;
}
