public static boolean removeCancellingPairs(List<Pair> pairs) {
    boolean noMoreItems = true;
    Iterator<Pair> iterator = pairs.iterator();
    while (iterator.hasNext()) {
        Pair pair = iterator.next();
        if (pair.operation == Operation.CANCEL) {
            iterator.remove();
            for (Pair p : pairs) {
                if (p.operation == Operation.ADD && p.id == pair.linkedId) {
                    iterator.remove();
                    noMoreItems = false;
                    break;
                }
            }
        }
    }
    return noMoreItems;
}
