public JobFile convertJobFileStatusToJobFile(JobFileStatus jobFileStatus) {
    Objects.requireNonNull(jobFileStatus, "jobFileStatus must not be null");

    JobFile jobFile = new JobFile(jobFileStatus.getId(), jobFileStatus.getName(), jobFileStatus.getPath());

    List<Job> jobs = jobFileStatus.getJobs();
    if(jobs != null && !jobs.isEmpty()) {
        long minModificationTime = Long.MAX_VALUE;
        long maxModificationTime = Long.MIN_VALUE;
        String minJobId = null;
        String maxJobId = null;
        for(Job job : jobs) {
            if(job.getModificationTime() < minModificationTime) {
                minModificationTime = job.getModificationTime();
                minJobId = job.getId();
            }
            if(job.getModificationTime() > maxModificationTime) {
                maxModificationTime = job.getModificationTime();
                maxJobId = job.getId();
            }
        }
        jobFile.setMinModificationTime(minModificationTime);
        jobFile.setMaxModificationTime(maxModificationTime);
        jobFile.setMinJobId(minJobId);
        jobFile.setMaxJobId(maxJobId);
    }
    return jobFile;
}
