public void mainReadProcessWriteLoop() throws Exception {
    BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
    BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(System.out));

    String inputLine;

    while ((inputLine = reader.readLine()) != null) {
        String processedLine = processInput(inputLine);
        writer.write(processedLine);
        writer.newLine();
        // flush the writer after writing each line to ensure it gets written to the underlying stream
        writer.flush();
    }

    reader.close();
    writer.close();
}

