public ChannelFuture createNewChannel(InetSocketAddress localAddress) throws ChannelException {
    EventLoopGroup eventLoopGroup = new NioEventLoopGroup();
    ChannelFuture channelFuture;

    try {
        Bootstrap bootstrap = new Bootstrap();
        bootstrap.group(eventLoopGroup);
        bootstrap.channel(NioServerSocketChannel.class);
        bootstrap.localAddress(localAddress);

        ChannelInitializer<SocketChannel> channelInitializer = new ChannelInitializer<SocketChannel>() {
            @Override
            protected void initChannel(SocketChannel channel) {
                channel.pipeline().addLast(new ChannelInboundHandlerAdapter());
            }
        };

        bootstrap.childHandler(channelInitializer);
        channelFuture = bootstrap.bind().syncUninterruptibly().channel().closeFuture();

    } catch (Exception e) {
        throw new ChannelException(String.format("Failed to create and bind a new channel to the local address %s", localAddress), e.getCause());
    }

    return channelFuture;
}
