public class VersionConstraintUtils {
    private static WeakReference<VersionConstraint> versionConstraint;

    public static synchronized VersionConstraint storeAndGetWeakVersionConstraint(String rawConstraint) {
        VersionConstraint vc = (versionConstraint == null) ? null : versionConstraint.get();
        if (vc == null || !vc.getRawConstraint().equals(rawConstraint)) {
            vc = new VersionConstraint(rawConstraint);
            versionConstraint = new WeakReference<>(vc);
        }
        return vc;
    }
}
