public void updateCovariance(double x, double y) {
    // assuming the covariance matrix is stored as a 2x2 array called "covarianceMatrix"
    covarianceMatrix[0][0] += (x - meanX) * (x - meanX);
    covarianceMatrix[0][1] += (x - meanX) * (y - meanY);
    covarianceMatrix[1][0] += (y - meanY) * (x - meanX);
    covarianceMatrix[1][1] += (y - meanY) * (y - meanY);
}
