public YarnApplicationStatus convertToFlinkStatus(ApplicationStatus status) {
    switch(status) {
        case CREATED:
            return YarnApplicationStatus.NEW;
        case RUNNING:
            return YarnApplicationStatus.RUNNING;
        case CANCELED:
        case FAILED:
            return YarnApplicationStatus.FAILED;
        case FINISHED:
            return YarnApplicationStatus.SUCCEEDED;
        default:
            throw new IllegalArgumentException("Unsupported Flink status: " + status);
    }
}
