public static String getMainClass(Container appEntryContainer, Path entryPath, boolean required) {
    try {
        ZipFile zipFile = new ZipFile(appEntryContainer.getFile());
        ZipEntry zipEntry = zipFile.getEntry(entryPath.toString());
        if (zipEntry != null) {
            try (InputStream inputStream = zipFile.getInputStream(zipEntry)) {
                Manifest manifest = new Manifest(inputStream);
                String mainClass = manifest.getMainAttributes().getValue("Main-Class");
                if (mainClass == null && required) {
                    throw new IllegalStateException("Unable to find Main-Class attribute in MANIFEST.MF");
                }
                return mainClass;
            }
        }
    } catch (IOException e) {
        e.printStackTrace();
    }
    return null;
}
