public static String cleanString(String input) {
    if (input == null) {
        return "";
    }
    input = input.replaceAll("[\\r\\n\\t]+", "");
    input = input.replaceAll("\\s+", " ");
    input = input.replaceAll("&nbsp;", " ");
    input = input.replaceAll("<[^>]*>", "");
    input = input.trim();

    return input;
}
