public static double[] unitizeArray(double[] x) {
    double norm = 0.0;
    for (double val : x) {
        norm += val * val;
    }
    norm = Math.sqrt(norm);
    if (norm == 0.0) {
        throw new IllegalArgumentException("Cannot unitize array with L2 norm of 0.");
    }
    double[] result = new double[x.length];
    for (int i = 0; i < x.length; i++) {
        result[i] = x[i] / norm;
    }
    return result;
}
