import java.text.ParseException;
import java.text.SimpleDateFormat;
import java.util.Calendar;
import java.util.TimeZone;

import com.hp.hpl.jena.rdf.model.Literal;
import com.hp.hpl.jena.rdf.model.RDFNode;

public static Calendar parseDateTime(RDFNode node) throws ParseException {
    if (!(node instanceof Literal))
        throw new IllegalArgumentException("RDFNode must be a literal");

    Literal literal = (Literal) node;
    if (!literal.getDatatypeURI().equals(XSDDatatype.XSDdateTime.getURI()))
        throw new IllegalArgumentException("Literal must have data type xsd:dateTime");

    String lexicalValue = literal.getLexicalForm();

    SimpleDateFormat iso8601Format = new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss'Z'");
    // Specifying UTC time zone, you can change to your own time zone
    iso8601Format.setTimeZone(TimeZone.getTimeZone("UTC"));

    Calendar calendar = Calendar.getInstance();
    calendar.setTime(iso8601Format.parse(lexicalValue));

    return calendar;
}
