public static List<String> filterProtocolsAndCiphers(SSLContext sslContext) {
    String[] protocols = sslContext.getSupportedSSLParameters().getProtocols();
    String[] ciphers = sslContext.getSupportedSSLParameters().getCipherSuites();
    SSLParameters enabledSSLParameters = sslContext.getEnabledSSLParameters();

    List<String> supportedProtocols = Arrays.asList(protocols);
    List<String> supportedCiphers = Arrays.asList(ciphers);

    List<String> enabledProtocols = Arrays.asList(enabledSSLParameters.getProtocols());
    List<String> enabledCiphers = Arrays.asList(enabledSSLParameters.getCipherSuites());

    List<String> filteredProtocols = new ArrayList<>();
    List<String> filteredCiphers = new ArrayList<>();

    // Filter protocols
    for (String protocol : enabledProtocols) {
        if (supportedProtocols.contains(protocol)) {
            filteredProtocols.add(protocol);
        }
    }

    // Filter ciphers
    for (String cipher : enabledCiphers) {
        if (supportedCiphers.contains(cipher)) {
            filteredCiphers.add(cipher);
        }
    }
    List<String> filteredList = new ArrayList<>();
    filteredList.addAll(filteredCiphers);
    filteredList.addAll(filteredProtocols);

    return filteredList;
}
