public void createEndpointDeletedWaiter(WaiterParameters waiterParameters) {
  WaiterBuilder<DescribeEndpointRequest> waiterBuilder = waiterBuilderFactory
      .withWaiterName("EndpointDeleted")
      .withDefaultPollingStrategy(PollingStrategy.ACCEPT_SIGNAL)
      .withDefaultWaitTimeout(180)
      .withSdkFunctionToPoll(this::describeEndpoint)
      .withAcceptors(acceptors());
  applyWaiterParameters(waiterBuilder, waiterParameters);
  waiterBuilder.build();
}

private List<Acceptor<DescribeEndpointRequest>> acceptors() {
  return Arrays.asList(
    // Waits for the endpoint to be deleted
    new WaiterAcceptor<DescribeEndpointRequest>(WaiterState.SUCCESS)
        .withSuccessMatcher(new HttpSuccessStatusInRangeMatcher(HttpStatus.SC_OK, HttpStatus.SC_OK))
        .withWaitSuccessStatus(HttpStatus.SC_NOT_FOUND)
  );
}

private DescribeEndpointResponse describeEndpoint(DescribeEndpointRequest describeEndpointRequest, ExecutionContext executionContext) {
  return client.describeEndpoint(describeEndpointRequest, executionContext);
}
