public void unbindNameFromContext(Context ctx, String name) throws NamingException {
    ctx.unbind(name);
    Name parentName = ctx.getNameParser("").parse(name).getPrefix(ctx.getNameInNamespace().split("/").length - 1);
    while (parentName.size() > 0) {
        try {
            ctx.destroySubcontext(parentName.toString());
        } catch (ContextNotEmptyException cnee) {
            // Parent has other bindings, don't remove it
            break;
        }
        parentName = parentName.getPrefix(parentName.size() - 1);
    }
}
