public static String encode(String input, String charset) throws UnsupportedEncodingException {
    return URLEncoder.encode(input, charset)
        .replace("+", "%20")
        .replace("%21", "!")
        .replace("%27", "'")
        .replace("%28", "(")
        .replace("%29", ")")
        .replace("%7E", "~");
}
