public void growArray( int amountBits , boolean saveValue ) {
		size = size+amountBits;
		int N = size/8 + (size%8==0?0:1);
		if( N > data.length ) {

			int extra = Math.min(1024,N+10);
			byte[] tmp = new byte[N+extra];
			if( saveValue )
				System.arraycopy(data,0,tmp,0,data.length);
			this.data = tmp;
		}
