import org.apache.commons.math3.complex.Complex;
import org.apache.commons.math3.linear.Array2DRowRealMatrix;
import org.apache.commons.math3.linear.EigenDecomposition;

public static Complex[] findRoots(double[] coefficients) {
    int n = coefficients.length - 1;
    Array2DRowRealMatrix matrix = new Array2DRowRealMatrix(n, n);
    for (int i = 0; i < n; i++) {
        matrix.setEntry(i, n-1, -coefficients[i] / coefficients[n]);
    }
    for (int i = 1; i < n; i++) {
        matrix.setEntry(i, i-1, 1);
    }
    EigenDecomposition eigen = new EigenDecomposition(matrix);
    return eigen.getEigenvalues();
}
