public List retrieveList(List<String> terms, int index) {
    String resourceName = getResourceName(terms, index);
    Resource resource = getResource(resourceName);
    if (resource == null) {
        resource = createResource(resourceName);
    }
    List list = resource.getList();
    if (list == null) {
        list = createList(resource);
    }
    return list;
}

private String getResourceName(List<String> terms, int index) {
    StringBuilder resourceNameBuilder = new StringBuilder();
    for (int i = 0; i <= index; i++) {
        resourceNameBuilder.append(terms.get(i));
        if (i < index) {
            resourceNameBuilder.append("/");
        }
    }
    return resourceNameBuilder.toString();
}

