public static int[] replaceOccurrences(int[] arr, int value1, int value2, int n) {
    int[] result = new int[arr.length];
    int count = 0;
    for (int i = 0; i < arr.length; i++) {
        if (arr[i] == value1 && count < n) {
            result[i] = value2;
            count++;
        } else {
            result[i] = arr[i];
        }
    }
    return result;
}
