public GosuPathEntry readPom(File moduleFile) {
    Model model;
    try (FileInputStream inputStream = new FileInputStream(moduleFile)) {
        model = new MavenXpp3Reader().read(inputStream);
    } catch (IOException | XmlPullParserException e) {
        throw new RuntimeException(e);
    }
    File moduleDir = moduleFile.getParentFile();
    GosuPathEntry moduleEntry = new GosuPathEntry(moduleDir.getAbsolutePath());
    Set<GosuPathEntry> dependencies = new LinkedHashSet<>();
    for (Dependency dep : model.getDependencies()) {
        String depGroupId = dep.getGroupId();
        String depArtifactId = dep.getArtifactId();
        String depVersion = dep.getVersion();
        if (depVersion == null) {
            depVersion = "[0,)";
        }
        String depRange = dep.getVersionRange();
        if (depRange != null) {
            depVersion = depRange;
        }
        boolean depOptional = dep.isOptional();
        String depClassifier = dep.getClassifier();
        String depType = dep.getType();
        if (depType == null) {
            depType = "jar";
        }
        String depScope = dep.getScope();
        if (depScope != null && "test".equals(depScope)) {
            continue;
        }
        File depFile = resolveDependencyFile(moduleDir, depGroupId, depArtifactId, depVersion, depClassifier, depType);
        GosuPathEntry depEntry = new GosuPathEntry(depFile.getAbsolutePath());
        depEntry.setOptional(depOptional);
        dependencies.add(depEntry);
    }
    moduleEntry.setDependencies(dependencies);
    return moduleEntry;
}

private File resolveDependencyFile(File moduleDir, String depGroupId, String depArtifactId, String depVersion, String depClassifier, String depType) {
    Artifact artifact;
    try {
        ArtifactFactory artifactFactory = new DefaultArtifactFactory();
        artifact = artifactFactory.createArtifactWithClassifier(depGroupId, depArtifactId, depVersion, depType, depClassifier);
        ArtifactResolutionRequest request = new ArtifactResolutionRequest()
                .setArtifact(artifact)
                .setLocalRepository(localRepository);
        ArtifactResolutionResult result = artifactResolver.resolve(request);
        Set<Artifact> artifacts = result.getArtifacts();
        if (artifacts.isEmpty()) {
            throw new RuntimeException("Failed to resolve dependency " + depGroupId + ":" + depArtifactId + ":" + depVersion);
        }
        Artifact resolvedArtifact = artifacts.iterator().next();
        return resolvedArtifact.getFile();
    } catch (ArtifactResolutionException | NoSuchRepositoryException e) {
        throw new RuntimeException("Failed to resolve dependency " + depGroupId + ":" + depArtifactId + ":" + depVersion, e);
    }
}
