public static double distanceClosestPoints(double[] l0, double[] l1) {
    double x1 = l0[0];
    double y1 = l0[1];
    double x2 = l0[2];
    double y2 = l0[3];
    double x3 = l1[0];
    double y3 = l1[1];
    double x4 = l1[2];
    double y4 = l1[3];
    double x12 = x1-x2;
    double x34 = x3-x4;
    double y12 = y1-y2;
    double y34 = y3-y4;
    double c = x12 * y34 - y12 * x34;
    if (c == 0) {
        // lines are parallel
        return Math.sqrt((x1-x3)*(x1-x3) + (y1-y3)*(y1-y3));
    } else {
        double a = x1*y2 - y1*x2;
        double b = x3*y4 - y3*x4;
        double cx = (a*x34 - x12*b) / c;
        double cy = (a*y34 - y12*b) / c;
        return Math.sqrt((x1-cx)*(x1-cx) + (y1-cy)*(y1-cy));
    }
}
