public static File createTempDirectory(String prefix, File directory)
        throws IOException
{
    if (prefix == null) {
        throw new IllegalArgumentException("Prefix string cannot be null");
    }

    if (directory == null) {
        throw new IllegalArgumentException("Directory cannot be null");
    }

    if (!directory.exists() && !directory.mkdirs()) {
        throw new IOException("Unable to create directory " + directory);
    }

    File tempDirectory = File.createTempFile(prefix, "", directory);
    if (!tempDirectory.delete()) {
        throw new IOException("Unable to delete temp file " + tempDirectory);
    }

    if (!tempDirectory.mkdir()) {
        throw new IOException("Unable to create temp directory " + tempDirectory);
    }

    return tempDirectory;
}
