public int waitForResponse() throws InterruptedException, BOSHException {
    int responseCode;
    // Wait for the response code to be available
    synchronized (responseLock) {
        while (response == null && exception == null) {
            responseLock.wait();
        }
        // Check if an exception was thrown
        if (exception != null) {
            throw exception;
        }
        // Get the response code
        responseCode = response.getStatusLine().getStatusCode();
    }
    return responseCode;
}
