public static long parseDuration(String durationString) throws ParseException {
    String pattern = "^(\\d+)(d|h|m|s)+\\s+(\\d+)(d|h|m|s)+\\s+(\\d+)(d|h|m|s)+\\s+(\\d+)(d|h|m|s)+$";
    Pattern r = Pattern.compile(pattern);
    Matcher m = r.matcher(durationString);

    if (!m.find()) {
        throw new ParseException("Invalid format", 0);
    }

    long duration = 0;

    for (int i = 1; i <= m.groupCount(); i += 2) {
        String value = m.group(i);
        String unit = m.group(i + 1);

        switch (unit) {
            case "d":
                duration += TimeUnit.DAYS.toMillis(Long.parseLong(value));
                break;
            case "h":
                duration += TimeUnit.HOURS.toMillis(Long.parseLong(value));
                break;
            case "m":
                duration += TimeUnit.MINUTES.toMillis(Long.parseLong(value));
                break;
            case "s":
                duration += TimeUnit.SECONDS.toMillis(Long.parseLong(value));
                break;
        }
    }

    return duration;
}
