public void flattenJsonNode(Field classField, JsonNode jsonNode) {
  JsonProperty fieldAnnotation = classField.getAnnotation(JsonProperty.class);
  if (fieldAnnotation != null && fieldAnnotation.value().contains(".")) {
    String[] fieldNames = fieldAnnotation.value().split("\\.");
    JsonNode currentNode = jsonNode;
    for (String fieldName : fieldNames) {
      currentNode = currentNode.get(fieldName);
    }
    ((ObjectNode) jsonNode).set(classField.getName(), currentNode);
  }
}
