public static boolean lowerCholesky(double[] T, int indexT, int n) {
    for (int j = 0; j < n; j++) {
        double d = 0.0;
        for (int k = 0; k < j; k++) {
            double s = 0.0;
            for (int i = k; i < j; i++) {
                s += T[indexT + i * n + k] * T[indexT + i * n + j];
            }
            T[indexT + j * n + k] = s / T[indexT + k * n + k];
            d -= T[indexT + j * n + k] * T[indexT + j * n + k];
        }
        d = T[indexT + j * n + j] - d;
        if (d <= 0) {
            return false;
        }
        T[indexT + j * n + j] = Math.sqrt(d);
    }
    return true;
}
