public void initializeDefaultCenturyStart(Date creationTime) {
    Calendar calendar = Calendar.getInstance();
    calendar.setTime(creationTime);
    int creationYear = calendar.get(Calendar.YEAR);
    int century = (creationYear / 100) + 1;
    int centuryStartYear = (century - 1) * 100;
    calendar.clear();
    calendar.set(Calendar.YEAR, centuryStartYear);
    calendar.set(Calendar.MONTH, Calendar.JANUARY);
    calendar.set(Calendar.DAY_OF_MONTH, 1);
    defaultCenturyStart = calendar.getTime();
    defaultCenturyStartYear = centuryStartYear;
}
