public class WorkspaceReader {

    public static Workspace readWorkspace(Reader reader) throws WorkspaceReaderException {

        Gson gson = new Gson();
        Workspace workspace;

        try {
            workspace = gson.fromJson(reader, Workspace.class);
        } catch (Exception e) {
            throw new WorkspaceReaderException("Error parsing workspace definition", e);
        } finally {
            try {
                reader.close();
            } catch (IOException e) {
                throw new WorkspaceReaderException("Error closing reader", e);
            }
        }

        return workspace;
    }
}
