public static int findNextIndex(int[] arr, int value) {
    int index = -1;
    int minDiff = Integer.MAX_VALUE;

    for (int i = 0; i < arr.length; i++) {
        if (arr[i] > value && arr[i] - value < minDiff) {
            minDiff = arr[i] - value;
            index = i;
        }
    }

    return index;
}
