import java.beans.*;
import java.io.*;

public class TeaBeanInfoGenerator {

    public static void generateBeanInfo(String className, String templateFile) throws Exception {
        // Load the specified class
        Class<?> clazz = Class.forName(className);

        // Create a TemplateEngine and load the template file
        TeaTemplate template = new TeaTemplate(new File(templateFile));

        // Generate the BeanInfo data using the template
        BeanInfo beanInfo = Introspector.getBeanInfo(clazz);
        StringWriter sw = new StringWriter();
        template.render(beanInfo, sw);
        String beanInfoData = sw.toString();

        // Write the generated data to a file
        String beanInfoFileName = clazz.getSimpleName() + "BeanInfo.java";
        FileWriter writer = new FileWriter(beanInfoFileName);
        writer.write(beanInfoData);
        writer.close();
    }

}
