public Diagram loadSvgDocument(String ref, float offset) throws SlickException {
    try {
        InputStream in = getClass().getResourceAsStream(ref);
        TranscoderInput input = new TranscoderInput(in);
        Diagram diagram = new Diagram();
        Transcoder transcoder = new PDFTranscoder();
        TranscoderOutput output = new TranscoderOutput(diagram);
        transcoder.addTranscodingHint(PDFTranscoder.KEY_HEIGHT, (float) Math.ceil(diagram.getHeight() + offset));
        transcoder.transcode(input, output);
        return diagram;
    } catch (Exception e) {
        throw new SlickException("Failed to load SVG document: " + ref, e);
    }
}
