public static double gpdQuantile(double val, double mu, double sigma, double xi) {
    if (sigma <= 0.0 || xi == 0.0) {
        throw new IllegalArgumentException("Invalid input parameters.");
    }
    double q;
    if (xi < 0.0) {
        q = 1.0 - val;
    } else {
        q = val;
    }
    double u = Math.log(1.0 - xi * q) / xi;
    return mu + sigma * (u >= 0.0 ? Math.exp(u) - 1.0 : -Math.log(1.0 - u));
}
