public static double cubicSplineInterpolation(double Y0, double Y1, double Y2, double Y3, double MU) {
    double a0, a1, a2, a3, MU2;
    double result;

    MU2 = MU * MU;
    a0 = Y3 - Y2 - Y0 + Y1;
    a1 = Y0 - Y1 - a0;
    a2 = Y2 - Y0;
    a3 = Y1;
    result = a0 * MU * MU2 + a1 * MU2 + a2 * MU + a3;

    return result;
}
