import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Node;
import org.jsoup.select.Elements;
import java.util.ArrayList;
import java.util.List;

public class HtmlHandler {

  public static Document makeXhtmlList(Document list) {

    Elements elements = list.getAllElements();
    List<Element> removeList = new ArrayList<>();
    Elements retElements = new Elements();

    for (Element el : elements) {
      String tag = el.tagName();
      if (tag.equals("html") || tag.equals("head") || tag.equals("body")) {
        // do nothing
      } else if (tag.equals("ul") || tag.equals("ol")) {
        cleanList(el, removeList);
      } else if (tag.equals("br")) {
        Element newEl = new Element("li");
        newEl.html("<br>");
        el.replaceWith(newEl);
        retElements.add(newEl);
      } else if (tag.startsWith("h")) {
        Element newEl = new Element("li");
        newEl.html(el.outerHtml());
        el.replaceWith(newEl);
        retElements.add(newEl);
      } else if (!tag.equals("li") && !tag.equals("span")) {
        // Move node to nearest list element that encloses the present element
        Element newEl = new Element("li");
        newEl.html(el.outerHtml());
        el.replaceWith(newEl);
        retElements.add(newEl);
      } else {
        retElements.add(el);
      }
    }
    for (Element el : removeList) {
      el.remove();
    }

    Document htmlDoc = Jsoup.parse("<html><body></body></html>");
    Element body = htmlDoc.body();
    body.append(retElements.toString());

    return htmlDoc;
  }

  private static boolean cleanList(Element ul, List<Element> removeList) {
    boolean empty = true;

    for (Node node : ul.childNodes()) {
      if (node.nodeName().equals("#text")) {
        if (!node.toString().trim().isEmpty()) {
          return false;
        }
      }

      if (node instanceof Element && node.nodeName().equals("li")) {
        empty = false;
      } else if (node instanceof Element) {
        if (cleanList((Element) node, removeList)) {
          removeList.add(node.parent());
        } else {
          empty = false;
        }
      } else {
        removeList.add(node);
      }
    }
    if (empty) {
      removeList.add(ul);
    }
    return empty;
  }
}
