public static boolean isAverageWithinDelta(double[] numbers, double average, double delta) {
    double sum = 0;
    for (double num : numbers) {
        sum += num;
    }
    double calculatedAverage = sum / numbers.length;
    return Math.abs(calculatedAverage - average) <= delta;
}
