public class CsvHelper {
   public static PCMContainer getPcmContainerFromCsv(String filePath) throws IOException {
       PCMContainer pcmContainer = new PCMContainer();
       BufferedReader br = new BufferedReader(new FileReader(filePath));
       String line;
       while ((line = br.readLine()) != null) {
           String[] values = line.split(",");
           pcmContainer.addProduct(new Product(values[0], Arrays.asList(Arrays.copyOfRange(values, 1, values.length)))));
           break;
       }
       br.close();
       return pcmContainer;
   }
}
