public static String getQueryString(List<String> criteria, String domainType) {
    StringBuilder queryStringBuilder = new StringBuilder();
    int criteriaCount = criteria.size();
    for (int i = 0; i < criteriaCount; i++) {
        queryStringBuilder.append(criteria.get(i));
        if (i != criteriaCount - 1) {
            queryStringBuilder.append(" AND ");
        }
    }
    return "type:" + domainType + " AND " + queryStringBuilder.toString();
}
