import com.spotify.sparkey.IndexWriter;
import com.spotify.sparkey.Sparkey;

import java.io.File;
import java.io.IOException;

public class IndexFileWriter {

    public static void writeIndexFile(File file, int hashType) throws IOException {
        String indexFilename = file.getAbsolutePath() + ".spi";
        String logFilename = file.getAbsolutePath() + ".spl";
        File indexFile = new File(indexFilename);
        File logFile = new File(logFilename);
        Sparkey.delete(indexFile, logFile);
        IndexWriter writer = new IndexWriter(indexFile.getAbsolutePath(), hashType);
        Sparkey.open(file.getAbsolutePath()).iterateEntries().forEachRemaining(writer::add);
        writer.close();
    }
}
