public JavacTool createJavacEnvironment(Collection<File> files) {
    Iterable<? extends JavaFileObject> compilationUnits = 
        new ArrayList<JavaFileObject>();

    for (File file : files) {
        Path path = file.toPath();
        String className = path.getFileName().toString().replace(".java", "");
        try {
            String code = new String(Files.readAllBytes(path), StandardCharsets.UTF_8);
            JavaFileObject javaFileObject = new SimpleJavaFileObject(
                URI.create(className + ".java"), JavaFileObject.Kind.SOURCE) {
                @Override
                public CharSequence getCharContent(boolean ignoreEncodingErrors)
                        throws IOException {
                    return code;
                }
            };
            compilationUnits = Iterables.concat(compilationUnits, ImmutableList.of(javaFileObject));
        } catch (IOException e) {
            System.err.println("Error during file reading: " + e.getMessage());
        }
    }

    JavacTool tool = JavacTool.create();
    DiagnosticCollector<JavaFileObject> collector = new DiagnosticCollector<>();
    JavaCompiler.CompilationTask task = tool.getTask(null, null, collector,
            ImmutableList.of("-d", "./target/classes"), null,
            compilationUnits);
    task.call();

    for (Diagnostic<? extends JavaFileObject> diagnostic : collector.getDiagnostics()) {
        System.out.println(diagnostic);
    }

    return tool;
}
