import javax.swing.JDialog;
import javax.swing.JLabel;
import javax.swing.SwingConstants;

public void showProgressDialog(String message) {
    // Check if dialog already exists
    JDialog progressDialog = null;
    for (JDialog dialog : JDialog.getWindows()) {
        if (dialog.isVisible() && dialog.getClass().equals(JDialog.class)) {
            progressDialog = dialog;
            break;
        }
    }

    if (progressDialog == null) {
        progressDialog = new JDialog();
        progressDialog.setDefaultCloseOperation(JDialog.DO_NOTHING_ON_CLOSE);
        progressDialog.setUndecorated(true);
        progressDialog.setModal(true);

        JLabel label = new JLabel();
        label.setHorizontalAlignment(SwingConstants.CENTER);
        progressDialog.add(label);

        progressDialog.pack();
        progressDialog.setLocationRelativeTo(null);
    }

    ((JLabel) progressDialog.getContentPane().getComponent(0)).setText(message);
    progressDialog.setVisible(true);
}
