        parameterMap = new HashMap<>();
    }

    public Map<String, Object> getParameterMap() {
        return parameterMap;
    }

    public void setParameterMap(Map<String, Object> parameterMap) {
        this.parameterMap = parameterMap;
    }

    public void mergeParameters(Parameters... parametersList) {
        for (Parameters parameters : parametersList) {
            parameterMap.putAll(parameters.getParameterMap());
        }
    }

    public Parameters getMergedParameters(Parameters... parametersList) {
        Parameters mergedParameters = new Parameters();
        for (Parameters parameters : parametersList) {
            mergedParameters.mergeParameters(parameters);
        }
        return mergedParameters;
    }

}
