public boolean canAutoGenerate(Object value) {
    // Check if the given value is null or not of a primitive type
    if (value == null || value instanceof Boolean || value instanceof Character || 
        value instanceof Byte || value instanceof Short || value instanceof Integer || 
        value instanceof Long || value instanceof Float || value instanceof Double) {
        return false;
    }
    // Check if the given value is an array of primitive types or a string
    if (value.getClass().isArray() && value.getClass().getComponentType().isPrimitive() || 
        value instanceof String) {
        return false;
    }
    // If none of the above conditions are satisfied, the mapping value can be auto-generated
    return true;
}
