public interface CursorConverter<T> {
    T convert(Cursor cursor);
}

public <T> List<T> convertCursorToList(Cursor cursor, CursorConverter<T> converter) {
    List<T> result = new ArrayList<>();
    if (cursor != null) {
        cursor.moveToPosition(-1);
        while (cursor.moveToNext()) {
            result.add(converter.convert(cursor));
        }
    }
    return result;
}
