public String getDeviceIdentifierForFile(String deviceIdentifier) {
    // Replace spaces with underscores
    deviceIdentifier = deviceIdentifier.replaceAll("\\s+", "_");

    // Remove any non-alphanumeric characters except underscores
    deviceIdentifier = deviceIdentifier.replaceAll("[^a-zA-Z0-9_]+", "");

    // Return the modified string
    return deviceIdentifier;
}
