private void breakLongPatches(LinkedList<Patch> patches, int maxLength) {
    ListIterator<Patch> iter = patches.listIterator();
    boolean changes = false;
    while (iter.hasNext()) {
        Patch patch = iter.next();
        if (patch.getLength() > maxLength) {
            changes = true;
            // Break up patch
            iter.remove();
            List<Patch> subPatches = patch.split(maxLength);
            for (Patch subPatch : subPatches) {
                iter.add(subPatch);
            }
        }
    }
    if (changes) {
        // Only recompute lengths if changes have been made.
        computePatchesLength(patches);
    }
}
