public Bitmap drawBitmapWithOutsideColor(RenderContext renderContext) {
    // Set the colour for the bitmap
    Color color = renderContext.getOutsideColor();

    // Create a new empty bitmap
    Bitmap bitmap = new Bitmap(renderContext.getBitmapWidth(), renderContext.getBitmapHeight());

    // Set every pixel in the bitmap to the specified colour
    for (int x = 0; x < renderContext.getBitmapWidth(); x++) {
        for (int y = 0; y < renderContext.getBitmapHeight(); y++) {
            bitmap.setPixel(x, y, color);
        }
    }

    // Return the bitmap
    return bitmap;
}
