public void leave(ActivityExecution execution) {
  ActivityBehavior nestedBehavior = getNestedActivityBehavior();
  if (nestedBehavior instanceof AbstractBpmnActivityBehavior) {
    AbstractBpmnActivityBehavior innerBehavior = (AbstractBpmnActivityBehavior) nestedBehavior;
    innerBehavior.leave(execution);
  } else {
    // logic for sequential behavior
    execution.leaveActivity();
  }
}
