public List<DocumentTemplate> getDocumentTemplates(DocumentType documentType, String applicationTenancy) {
    // Query templates from database, ordered by type, application tenancy, and date
    String query = "SELECT * FROM document_templates WHERE document_type = ? AND application_tenancy = ? ORDER BY document_type, application_tenancy, date DESC";
    List<DocumentTemplate> templates = new ArrayList<>();

    // Execute query and populate list of templates
    try (PreparedStatement statement = connection.prepareStatement(query)) {
        statement.setString(1, documentType.toString());
        statement.setString(2, applicationTenancy);
        ResultSet rs = statement.executeQuery();
        while (rs.next()) {
            String name = rs.getString("name");
            String content = rs.getString("content");
            Date date = rs.getDate("date");
            templates.add(new DocumentTemplate(name, content, documentType, applicationTenancy, date));
        }
    } catch (SQLException e) {
        e.printStackTrace();
    }

    return templates;
}
