public String getChargingStationAddress(MessageContext messageContext) {
    String chargingStationAddress = "";
    try {
        SOAPHeader header = ((Axis2MessageContext) messageContext)
                .getAxis2MessageContext().getEnvelope().getHeader();
        if (header != null) {
            OMElement fromElement = header.getFirstChildWithName(
                    new QName(Constants.URI_SOAP11_ENV, "From"));
            if (fromElement != null) {
                chargingStationAddress = fromElement.getFirstChildWithName(
                        new QName(Constants.URI_WSA, "Address")).getText();
            }
        }
    } catch (Exception ex) {
        // handle exception
    }
    return chargingStationAddress;
}
