  String requestMethod = ctx.getRequestMethod();

  // invoke the appropriate method based on the request method
  switch(requestMethod) {
    case "HEAD":
      handleBucketHeadRequest(ctx, bucketName);
      break;
    case "DELETE":
      handleBucketDeleteRequest(ctx, bucketName);
      break;
    case "GET":
      handleBucketGetRequest(ctx, bucketName);
      break;
    case "PUT":
      handleBucketPutRequest(ctx, bucketName);
      break;
    default:
      // unsupported request method
      ctx.setResponseCode(405);
      break;
  }
}

