@Around("@annotation(Profile)")
public Object profileExecutionTime(ProceedingJoinPoint joinPoint) throws Throwable {
    final long start = System.nanoTime(); // get system time
    final Object proceed = joinPoint.proceed(); // invoke the original method
    final long executionTime = System.nanoTime() - start; // calculate total execution time
    System.out.println(joinPoint.getSignature() + " executed in " + executionTime + " ns"); // print execution time
    return proceed; // return the original method's returned object
}
