public interface RequestUpdater {
    void update(Request request);
}

public class UpdaterDispatcher {
    private final Map<RequestType, RequestUpdater> updaters;

    public UpdaterDispatcher() {
        updaters = new HashMap<>();
    }

    public void addUpdater(RequestType type, RequestUpdater updater) {
        updaters.put(type, updater);
    }

    public void dispatch(Request request) {
        RequestType type = request.getType();
        RequestUpdater updater = updaters.get(type);
        if (updater != null) {
            updater.update(request);
        }
    }
}
