public double getWeightedDistance(double[] v1, double[] v2, double[] weightVector) {
    double distanceSquared = 0;
    for (int i = 0; i < v1.length; i++) {
        double diff = v1[i] - v2[i];
        distanceSquared += weightVector[i] * diff * diff;
    }
    return Math.sqrt(distanceSquared);
}
