public static double[][] orthonormalizeVectors(double[] v0, double[] v1, double[] v2) {

   // Subtract the projection of v1 onto v0 from v1
   for (int i = 0; i < v1.length; i++) {
      double projection = 0;
      for (int j = 0; j < v0.length; j++) {
         projection += v1[j] * v0[j];
      }
      for (int j = 0; j < v1.length; j++) {
         v1[j] -= projection * v0[j];
      }
   }

   // Normalize v1
   double length = 0;
   for (int i = 0; i < v1.length; i++) {
      length += v1[i] * v1[i];
   }
   length = Math.sqrt(length);
   for (int i = 0; i < v1.length; i++) {
      v1[i] /= length;
   }

   // Subtract the projection of v2 onto v0 and v1 from v2
   for (int i = 0; i < v2.length; i++) {
      double projection1 = 0;
      for (int j = 0; j < v0.length; j++) {
         projection1 += v2[j] * v0[j];
      }
      double projection2 = 0;
      for (int j = 0; j < v1.length; j++) {
         projection2 += v2[j] * v1[j];
      }
      for (int j = 0; j < v2.length; j++) {
         v2[j] -= projection1 * v0[j] + projection2 * v1[j];
      }
   }

   // Normalize v2
   length = 0;
   for (int i = 0; i < v2.length; i++) {
      length += v2[i] * v2[i]; 
   }
   length = Math.sqrt(length);
   for (int i = 0; i < v2.length; i++) {
      v2[i] /= length;
   }

   double[][] result = {v0, v1, v2};
   return result;
}
