public static int[] fibonacciSequence(int n) throws IllegalArgumentException {
    if (n < 1) {
        throw new IllegalArgumentException("Position must be greater than 0.");
    }

    int[] fibonacci = new int[n];

    fibonacci[0] = 0;

    if (n > 1) {
        fibonacci[1] = 1;

        for (int i = 2; i < n; i++) {
            fibonacci[i] = fibonacci[i-1] + fibonacci[i-2];
        }
    }

    return fibonacci;
}
