public List<Method> selectBestMatchingMethods(List<Method> methods, Object[] args) {
    List<Method> bestMatchingMethods = new ArrayList<>();

    for (Method method : methods) {
        if (Arrays.equals(method.getParameterTypes(), getArgumentTypes(args))) {
            bestMatchingMethods.add(method);
        }
    }

    return bestMatchingMethods;
}

private Class[] getArgumentTypes(Object[] args) {
    Class[] argumentTypes = new Class[args.length];
    for (int i = 0; i < args.length; i++) {
        argumentTypes[i] = args[i].getClass();
    }
    return argumentTypes;
}
