public int getCurrentSNSIndex() {
  int index = 1;
  Node currentNode = this;
  while(currentNode.getPreviousSibling() != null) {
    if(currentNode.getPreviousSibling().getNodeName().equals(currentNode.getNodeName())) {
      index++;
    }
    currentNode = currentNode.getPreviousSibling();
  }
  return index;
}
