public static String getImageFormat(String contentType, String filePath) {
    String format = null;
    if (contentType != null) {
        switch (contentType) {
            case "image/png":
                format = "png";
                break;
            case "image/jpeg":
            case "image/jpg":
                format = "jpeg";
                break;
            case "image/gif":
                format = "gif";
                break;
            default:
                format = null;
                break;
        }
    } else if (filePath != null) {
        String extension = filePath.substring(filePath.lastIndexOf('.') + 1).toLowerCase();
        switch (extension) {
            case "png":
                format = "png";
                break;
            case "jpeg":
            case "jpg":
                format = "jpeg";
                break;
            case "gif":
                format = "gif";
                break;
            default:
                format = null;
                break;
        }
    }
    return format;
}
