public static int[] getRandomSample(int[] source, int k, Random random) {
    int[] sample = new int[k];
    for (int i = 0; i < k; i++) {
        int j = random.nextInt(source.length - i) + i;
        sample[i] = source[j];
        source[j] = source[i];
    }
    return sample;
}
