public static Number pow(Integer self, Integer exponent) {
    if (exponent == 0) {
        return 1;
    } else if (exponent > 0) {
        return BigInteger.valueOf(self).pow(exponent);
    } else {
        return 1 / pow(self, -exponent);
    }
}
