public void processFieldsAnnotations() throws CoreException {
    try {
        Class<?> clazz = this.getClass();
        for (Field field : clazz.getDeclaredFields()) {
            if (field.isAnnotationPresent(Fields.class)) {
                Fields annotation = field.getAnnotation(Fields.class);
                EventHandler eventHandler = EventHandlerFactory.getHandler(annotation.type());
                if (eventHandler == null) {
                    throw new CoreException("No handler found for type: " + annotation.type());
                }
                eventHandler.process(field, annotation);
            }
        }
    } catch (Exception e) {
        throw new CoreException("Failed to process field annotations: " + e.getMessage(), e);
    }
}
