import java.io.BufferedReader;
import java.io.FileReader;
import java.io.FileWriter;
import java.io.IOException;

public static void extractBlogContent(String inputFilePath, String outputFilePath) throws IOException {
    BufferedReader reader = new BufferedReader(new FileReader(inputFilePath));
    FileWriter writer = new FileWriter(outputFilePath);

    String line;
    while ((line = reader.readLine()) != null) {
        // Extract content and updated date from line
        String content = line.substring(0, line.indexOf(","));
        String date = line.substring(line.indexOf(",") + 1);
        // Write content and date to output file as one line
        writer.write(content + " " + date + "\n");
    }

    reader.close();
    writer.close();
}
