public List<State> enumerateTransitionsIntoD(State currentState, List<State> allStates) {
    List<State> transitions = new ArrayList<>();
    for (State state : allStates) {
        if (state.getTransitions().contains(currentState) && state.getName().equals("D")) {
            transitions.add(state);
        }
    }
    return transitions;
}
