public ByteBuffer createFloatBuffer(double[] values) {
    ByteBuffer buffer = ByteBuffer.allocate(8 * values.length);
    buffer.order(ByteOrder.BIG_ENDIAN);

    for (double value : values) {
        buffer.putDouble(value);
    }

    buffer.flip();
    return buffer;
}
