public static String fixRefererUrl(String referer, String baseUrl, String visibleBaseUrl) {
    if (referer == null || referer.isEmpty()) {
        return visibleBaseUrl;
    }
    URI refererUri = URI.create(referer);
    if (!refererUri.isAbsolute()) {
        refererUri = URI.create(baseUrl).resolve(refererUri);
    }
    String refererUrl = refererUri.toString();
    if (refererUrl.startsWith(visibleBaseUrl)) {
        return refererUrl;
    } else {
        return visibleBaseUrl;
    }
}
