public int writeCharacters(Writer w) throws IOException {
    int count = 0;
    char[] buffer = new char[1024];
    int n;
    while ((n = super.read(buffer)) != -1) {
        w.write(buffer, 0, n);
        count += n;
    }
    return count;
}
