public static List<Map<String, Object>> aggregate(List<Map<String, Object>> data, List<String> columns, List<AggregateFunction> functions) {
    List<Map<String, Object>> result = new ArrayList<>();
    Map<String, Map<String, Object>> groupMap = new HashMap<>();

    for (Map<String, Object> row : data) {
        String key = "";
        for (String column : columns) {
            key += row.get(column).toString() + "|";
        }
        if (!groupMap.containsKey(key)) {
            groupMap.put(key, new HashMap<>());
            for (String column : columns) {
                groupMap.get(key).put(column, row.get(column));
            }
        }
        for (AggregateFunction function : functions) {
            String columnName = function.getColumnName();
            if (!groupMap.get(key).containsKey(columnName)) {
                groupMap.get(key).put(columnName, function.initialize());
            }
            Object value = row.get(columnName);
            groupMap.get(key).put(columnName, function.aggregate(groupMap.get(key).get(columnName), value));
        }
    }

    for (Map<String, Object> group : groupMap.values()) {
        Map<String, Object> row = new HashMap<>();
        for (AggregateFunction function : functions) {
            String columnName = function.getColumnName();
            row.put(columnName, function.aggregate(group.get(columnName)));
        }
        result.add(row);
    }

    return result;
}
