public String unquoteAndUnescape(String text, char quoteChar) {
    if (text.length() < 2 || text.charAt(0) != quoteChar || text.charAt(text.length()-1) != quoteChar) {
        return text.replace("" + quoteChar + quoteChar, "" + quoteChar);
    }

    String unquoted = text.substring(1, text.length() - 1).replace("" + quoteChar + quoteChar, "" + quoteChar);
    StringBuilder sb = new StringBuilder(unquoted.length());

    for (int i = 0; i < unquoted.length(); i++) {
        char ch = unquoted.charAt(i);
        if (ch == '\\' && i < unquoted.length() - 1 && unquoted.charAt(i + 1) == quoteChar) {
            sb.append(quoteChar);
            i++;
        } else {
            sb.append(ch);
        }
    }

    return sb.toString();
}
