public void shutdown() {
    // check if calling thread is offerService thread
    if(Thread.currentThread() != offerServiceThread) {
        throw new IllegalThreadStateException("shutdown() method can only be called by offerService thread");
    }

    // initiate shutdown process
    datanodeManager.shutdown();
    blockPoolManager.shutdown();
    dataXceiverServer.shutdown();
    ipcServer.stop();
    cleaner.stop();
    storage.unlockAll();

    // wait for shutdown to complete
    try {
        cleaner.join();
        datanodeManager.join();
        blockPoolManager.join();
        dataXceiverServer.join();
        ipcServer.join();
    } catch (InterruptedException e) {
        Thread.currentThread().interrupt();
    }
}
