public boolean isInputConsumable(VertexInput input) {
    for (Partition partition : input.getPartitions()) {
        if (partition.getType() == PartitionType.BLOCKING && partition.getState() != PartitionState.FINISHED) {
            return false;
        } else if (partition.getType() != PartitionType.BLOCKING && partition.getState() == PartitionState.CONSUMABLE) {
            return true;
        }
    }
    return false;
}
