public static String extractResponseBodiesFromJavadoc(String jdoc) {
    String[] lines = jdoc.split("\\r?\\n");
    boolean isResponseBlock = false;
    StringBuilder responseBodies = new StringBuilder();
    for (String line : lines) {
        if (line.trim().startsWith("@response")) {
            isResponseBlock = true;
            continue;
        }
        if (isResponseBlock) {
            if (line.trim().startsWith("@")) {
                break;
            } else {
                responseBodies.append(line.trim()).append("\n");
            }
        }
    }
    return responseBodies.toString().trim();
}
