import java.time.ZoneId;
import java.time.format.TextStyle;
import java.util.Locale;
import java.util.Set;

public String getTimeZoneName(String text, int start, Set<ZoneId> genericTypes) {
    int end = Math.min(text.length(), start + 100);
    String subtext = text.substring(start, end);

    ZoneId bestMatch = null;
    String bestMatchName = null;

    for (ZoneId zoneId : genericTypes) {
        String displayName = zoneId.getDisplayName(TextStyle.FULL, Locale.getDefault());
        if (subtext.contains(displayName)) {
            if (bestMatch == null || displayName.length() > bestMatchName.length()) {
                bestMatch = zoneId;
                bestMatchName = displayName;
            }
        }
    }

    return bestMatchName;
}
