public void processBinaryMessage(ByteBuffer binaryDataStream, Session session) {
    // Parse the binaryDataStream to extract JSON request
    byte[] binaryData = binaryDataStream.array();
    String jsonString = new String(binaryData, Charset.forName("UTF-8")).trim();
    JsonObject jsonObject = JsonParser.parseString(jsonString).getAsJsonObject();
    String requestClass = jsonObject.get("requestClass").getAsString();

    try {
        // Look up the WsCommand corresponding to the requestClass
        WsCommand command = commandMap.get(requestClass);
        if (command == null) {
            throw new IllegalArgumentException("No WsCommand found for requestClass: " + requestClass);
        }

        // Execute the WsCommand
        command.execute(jsonObject, session);
    } catch (Exception e) {
        // Handle any exceptions that may occur
        e.printStackTrace();
    }
}
