public static void flipBits(int[] bits, int startIndex, int endIndex) {
    // Expand the array if necessary
    if (endIndex > bits.length) {
        bits = Arrays.copyOf(bits, endIndex);
    }
    // Flip bits within the specified range
    for (int i = startIndex; i < endIndex; i++) {
        bits[i] = bits[i] == 0 ? 1 : 0;
    }
}
