public static String removeLastParamIfMultiple(String source) {
    int lastParamStartIndex = source.lastIndexOf("&");
    if (lastParamStartIndex != -1) {
        int numberOfParams = source.length() - lastParamStartIndex - 1;
        if (numberOfParams > 1) {
            source = source.substring(0, lastParamStartIndex);
        }
    }
    return source;
}
