public String serviceWrapperToWirelineString(ServiceWrapper service) {
    StringBuilder stringBuilder = new StringBuilder();
    stringBuilder.append(service.getServiceName()).append("|").append(service.getVersion()).append("|").append(service.getCallType()).append("|");
    Map<String, String> parameters = service.getParameters();
    List<String> parameterList = new ArrayList<>(parameters.keySet());
    Collections.sort(parameterList); // Sorting the parameters by their name
    for (String name : parameterList) {
        stringBuilder.append(name).append("=").append(parameters.get(name)).append("&");
    }
    int lastIndex = stringBuilder.length() - 1;
    if (stringBuilder.charAt(lastIndex) == '&') { // Removing the last '&' character
        stringBuilder.deleteCharAt(lastIndex);
    }
    return stringBuilder.toString();
}
