public boolean checkExcludedAttributes(List<String> atts, Map<String, Object> extProps) {
    List<String> exclusions = Arrays.asList("attr1", "attr2", "attr3"); // list of attributes to exclude
    for (String att : atts) {
        if (exclusions.contains(att)) {
            return true;
        }
    }
    for (String key : extProps.keySet()) {
        Object value = extProps.get(key);
        if (value instanceof List) {
            List<String> listValue = (List<String>) value;
            for (String item : listValue) {
                if (exclusions.contains(item)) {
                    return true;
                }
            }
        }
    }
    return false;
}
