import java.io.BufferedWriter;
import java.io.File;
import java.io.FileWriter;
import java.io.IOException;
import java.util.Map;
import org.apache.http.client.methods.HttpPut;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClients;
import org.apache.http.util.EntityUtils;


public class HttpPutCall {
    public static String putCall(String endpoint, Map<String, String> params, String outputFile) {
        CloseableHttpClient client = HttpClients.createDefault();
        HttpPut httpPut = new HttpPut(endpoint);

        //Add request parameters
        for (Map.Entry<String, String> entry : params.entrySet()) {
            httpPut.addHeader(entry.getKey(), entry.getValue());
        }

        String response = null;
        try {
            //Execute the PUT request
            response = client.execute(httpPut, responseHandler);

            //Write the response to the output file
            File file = new File(outputFile);
            FileWriter fw = new FileWriter(file.getAbsoluteFile(), true);
            BufferedWriter bw = new BufferedWriter(fw);
            bw.write("Endpoint: " + endpoint);
            bw.newLine();
            bw.write("Params: " + params.toString());
            bw.newLine();
            bw.write("Response: " + response);
            bw.newLine();
            bw.close();
        } catch(IOException e) {
            e.printStackTrace();
        } finally {
            try {
                client.close();
            } catch(IOException e) {
                e.printStackTrace();
            }
        }

        return response;
    }
}
