        case 1:
            System.out.println("INFO: " + error);
            break;
        case 2:
            System.out.println("WARNING: " + error);
            break;
        case 3:
            System.out.println("ERROR: " + error);
            break;
        case 4:
            System.out.println("FATAL: " + error);
            break;
        default:
            System.out.println("UNKNOWN LEVEL: " + error);
            break;
    }
}
