public ProcessInstance createSuperProcessIncident(String incidentMessage, String processInstanceId) {

    // Get the super process instance by process instance id
    ProcessInstance superProcessInstance = runtimeService.createProcessInstanceQuery()
            .processInstanceId(processInstanceId)
            .superProcessInstanceId(null)
            .singleResult();

    // If a super process instance was found, create a new incident on the current process instance
    if (superProcessInstance != null) {
        Incident incident = runtimeService.createIncident("incidentType", superProcessInstance.getId(),
                processInstanceId, incidentMessage);

        // Instantiate a new incident for the super process instance
        runtimeService.createIncident("superIncidentType", superProcessInstance.getId(), null,
                "An incident occurred in the sub process instance " + processInstanceId);

        return superProcessInstance;
    }
    return null;
}
