public void closeUnusedConfigs(String applicationName) {
    for (Config config : allConfigs) {
        if (config.isInUseBy(applicationName)) {
            continue;
        }

        boolean inUseByOtherApps = false;
        for (String appName : config.getUsedBy()) {
            if (!appName.equals(applicationName)) {
                inUseByOtherApps = true;
                break;
            }
        }

        if (!inUseByOtherApps) {
            config.close();
        }
    }
}
