public int getUnwritableSegmentSize(ByteBuffer buffer) {
    int position = buffer.position();
    int limit = buffer.limit();
    int size = 0;
    while (position < limit) {
        try {
            buffer.put(position, (byte) 0);
        } catch (ReadOnlyBufferException e) {
            int segmentSize = buffer.position() - position;
            if (segmentSize > size) {
                size = segmentSize;
            }
        }
        position = buffer.position();
    }
    buffer.position(0);
    return size;
}
