public static int[] union(int[]... arrays) {
    int totalLength = 0;
    for (int i = 0; i < arrays.length; i++) {
        totalLength += arrays[i].length;
    }

    int[] result = new int[totalLength];
    int destPos = 0;
    for (int i = 0; i < arrays.length; i++) {
        System.arraycopy(arrays[i], 0, result, destPos, arrays[i].length);
        destPos += arrays[i].length;
    }

    return result;
}
