import java.lang.annotation.Annotation;
import java.lang.reflect.Field;

public class FieldAdder {

    public static Field addPrivateField(Class<?> targetClass, Class<?> fieldType, String fieldName, Annotation... annotations) throws NoSuchFieldException, SecurityException { 

        // Create the field with private visibility
        Field field = targetClass.getDeclaredField(fieldName);
        field.setAccessible(true);

        // Set the new field's type
        field.setType(fieldType);

        // Add the optional annotations to the new field
        if (annotations != null) {
            for (Annotation annotation : annotations) {
                field.addAnnotation(annotation);
            }
        }

        // Add the getter method
        Method getterMethod = new Method("get" + fieldName, fieldType, Modifier.PUBLIC);
        getterMethod.setBody(String.format("return this.%s;", fieldName));
        targetClass.addMethod(getterMethod);

        // Add the setter method
        Method setterMethod = new Method("set" + fieldName, void.class, Modifier.PUBLIC);
        setterMethod.addParameter(new Parameter(fieldType, fieldName));
        setterMethod.setBody(String.format("this.%s = %s;", fieldName, fieldName));
        targetClass.addMethod(setterMethod);

        // Update the existing toString() method to include the new field's value
        Method toStringMethod = targetClass.getDeclaredMethod("toString");
        String origToString = toStringMethod.getBody();
        String newToString = origToString.substring(0, origToString.length() - 1) + ", " + fieldName + "='" + fieldName + '\'' + '}';
        toStringMethod.setBody(newToString);

        return field;
    }
}
