public int readUnsignedInt(InputStream stream) throws OtpErlangDecodeException {
    try {
        int num = 0;
        int digit = stream.read();
        while (digit >= '0' && digit <= '9') {
            num = num * 10 + digit - '0';
            digit = stream.read();
        }
        if (digit < 0) {
            return num;
        } else {
            throw new OtpErlangDecodeException("Expected unsigned integer, but got non-digit character.");
        }
    } catch (IOException e) {
        throw new OtpErlangDecodeException("Error reading from stream", e);
    }
}
