import java.io.IOException;
import java.net.URLConnection;

public boolean isNewer(String source, Class<?> cls) throws IOException {
    long sourceTimeStamp = getTimeStamp(URLConnection.openConnection(new File(source).toURI().toURL()));
    long classTimeStamp = getTimeStamp(cls);
    return sourceTimeStamp > classTimeStamp;
}

private long getTimeStamp(URLConnection connection) throws IOException {
    long timeStamp = connection.getLastModified();
    if (timeStamp == 0) {
        throw new IOException("Unable to get time stamp for URL: " + connection.getURL());
    }
    return timeStamp;
}

private long getTimeStamp(Class<?> cls) {
    return cls.getResource('/' + cls.getName().replace('.', '/') + ".class").openConnection().getLastModified();
}
