public Boolean parseBooleanFromString(String value, Boolean defaultValueBoolean) {
    Boolean valueBoolean;
    if (value == null || value.isEmpty() || "null".equalsIgnoreCase(value)) {
        valueBoolean = null;
    } else if ("1".equals(value)) {
        valueBoolean = true;
    } else if ("0".equals(value)) {
        valueBoolean = false;
    } else {
        try {
            valueBoolean = Boolean.parseBoolean(value);
        } catch (Exception e) {
            valueBoolean = defaultValueBoolean;
        }
    }
    return valueBoolean;
}
