public void processWarningsAndGeneratedColumns(ResultSet rs) throws SQLException {
   ResultSetMetaData rsmd = rs.getMetaData();
   int columnCount = rsmd.getColumnCount();
   while (rs.next()) {
      for (int i = 1; i <= columnCount; i++) {
         Object value = rs.getObject(i);
         if (rsmd.isAutoIncrement(i) || rsmd.isGeneratedColumn(i)) {
            // process generated column
         }

         SQLWarning warnings = rs.getWarnings();
         while (warnings != null) {
            // process warning
            warnings = warnings.getNextWarning();
         }
      }
   }
   rs.close();
}
