public boolean matches(String patternPath) {
    String[] patternChunks = patternPath.split("/");
    String[] nodeChunks = this.path.split("/");

    if (patternChunks.length != nodeChunks.length) {
        return false;
    }

    for (int i = 0; i < patternChunks.length; i++) {
        String patternChunk = patternChunks[i];
        String nodeChunk = nodeChunks[i];
        if (patternChunk.startsWith("{") && patternChunk.endsWith("}")) {
            continue;
        }
        if (!patternChunk.equals(nodeChunk)) {
            return false;
        }
    }

    return true;
}
