public void initiateMonitoring(ProcessMonitor processMonitor) {
    final int HEARTBEAT_TIMEOUT = 2000;
    Set<Process> registeredProcesses = processMonitor.getRegisteredProcesses();
    while (true) {
        for (Process process : registeredProcesses) {
            if (System.currentTimeMillis() - process.getHeartbeatTime() > HEARTBEAT_TIMEOUT) {
                processMonitor.notifyFailure(registeredProcesses);
                return;
            }
        }
        try {
            Thread.sleep(500);
        } catch (InterruptedException ex) {
            // handle the exception appropriately
        }
    }
}
