public Transaction.Status getActualStatus(TxnState state, String logString){
    if(state == null){
        System.out.println(logString);
        return Transaction.Status.INVALID;
    }else{
        switch(state){
            case NEW:
            case PENDING:
                return Transaction.Status.IN_PROGRESS;
            case SUCCESS:
                return Transaction.Status.COMPLETED;
            case CANCELLED:
                return Transaction.Status.CANCELLED;
            case ERROR:
                return Transaction.Status.FAILED;
            default:
                System.out.println(logString);
                return Transaction.Status.INVALID;
        }
    }
}
