public static Class<?> nameToClass(ClassLoader cl, String name) throws ClassNotFoundException {
    // If the name represents an array, find the last occurrence of '[' and count the number of occurrences
    int count = 0;
    while (name.charAt(count) == '[') {
        count++;
    }

    // If the name represents an array, handle the array
    if (count > 0) {
        // Get the component class
        String componentType = name.substring(count);
        Class<?> componentClass;
        if (componentType.startsWith("L") && componentType.endsWith(";")) {
            // This is an object type
            componentType = componentType.substring(1, componentType.length() - 1);
            componentClass = cl.loadClass(componentType);
        } else {
            // This is a primitive type
            componentClass = primitiveType(componentType);
        }

        // Create the array class
        if (count == 1) {
            return Array.newInstance(componentClass, 0).getClass();
        } else {
            int[] dimensions = new int[count];
            for (int i = 0; i < dimensions.length; i++) {
                dimensions[i] = 0;
            }
            return Array.newInstance(componentClass, dimensions).getClass();
        }
    } else {
        // The name does not represent an array, just load the class
        return cl.loadClass(name);
    }
}

// helper method to convert primitives to their class counterparts
private static Class<?> primitiveType(String name) {
    switch (name) {
        case "boolean":
            return boolean.class;
        case "byte":
            return byte.class;
        case "char":
            return char.class;
        case "double":
            return double.class;
        case "float":
            return float.class;
        case "int":
            return int.class;
        case "long":
            return long.class;
        case "short":
            return short.class;
        default:
            throw new IllegalArgumentException("Invalid primitive type name: " + name);
    }
}
