public int bindSelectionCriteria(PreparedStatement stmt, int index, Criteria crit, ClassDescriptor cld) throws SQLException {
    if (crit == null || cld == null || crit.getSelectionCriterion() == null) {
        return index;
    }
    int currentIndex = index;
    for (Iterator<?> it = crit.getSelectionCriterion().iterator(); it.hasNext(); ) {
        Criterion criterion = (Criterion) it.next();
        currentIndex = bindCriterion(stmt, currentIndex, criterion, cld);
    }
    return currentIndex;
}
