public void resetJobsWithStartingOrStoppingStatus() {
    try (Connection conn = getConnection()) {
        String sql = "SELECT * FROM job WHERE batch_status IN ('STARTING', 'STARTED', 'STOPPING')";
        PreparedStatement ps = conn.prepareStatement(sql);
        ResultSet rs = ps.executeQuery();
        while (rs.next()) {
            int jobId = rs.getInt("id");
            updateJobStatus(conn, jobId, "FAILED", "FAILED");
        }
    } catch (SQLException e) {
        // handle exception
    }
}

private void updateJobStatus(Connection conn, int jobId, String batchStatus, String exitStatus) throws SQLException {
    String sql = "UPDATE job SET batch_status = ?, exit_status = ? WHERE id = ?";
    PreparedStatement ps = conn.prepareStatement(sql);
    ps.setString(1, batchStatus);
    ps.setString(2, exitStatus);
    ps.setInt(3, jobId);
    ps.executeUpdate();
}
