public boolean isInliningLikelyToReduceCodeSize(Map<String, String> namesToAlias) {
    int totalOriginalSize = 0;
    int totalAliasedSize = 0;

    // Calculate the size of the original code
    for (String name : namesToAlias.keySet()) {
        totalOriginalSize += name.length();
    }

    // Calculate the size of the aliased code
    for (String alias : namesToAlias.values()) {
        totalAliasedSize += alias.length();
    }

    // Check if the aliased code is smaller than the original code
    return totalAliasedSize < totalOriginalSize;
}
