public void log(String level, String[] message, Throwable throwable) {
    StringBuilder sb = new StringBuilder();
    if (message != null) {
        for (String part : message) {
            sb.append(part);
        }
    }
    String logMessage = sb.toString();
    switch (level) {
        case "DEBUG":
            // log the message as debug level
            if (throwable == null) {
                System.out.println("[DEBUG] " + logMessage);
            } else {
                System.out.println("[DEBUG] " + logMessage + " - " + throwable.getMessage());
            }
            break;
        case "INFO":
            // log the message as info level
            if (throwable == null) {
                System.out.println("[INFO] " + logMessage);
            } else {
                System.out.println("[INFO] " + logMessage + " - " + throwable.getMessage());
            }
            break;
        case "WARN":
            // log the message as warn level
            if (throwable == null) {
                System.out.println("[WARN] " + logMessage);
            } else {
                System.out.println("[WARN] " + logMessage + " - " + throwable.getMessage());
            }
            break;
        case "ERROR":
            // log the message as error level
            if (throwable == null) {
                System.out.println("[ERROR] " + logMessage);
            } else {
                System.out.println("[ERROR] " + logMessage + " - " + throwable.getMessage());
            }
            break;
        case "FATAL":
            // log the message as fatal level
            if (throwable == null) {
                System.out.println("[FATAL] " + logMessage);
            } else {
                System.out.println("[FATAL] " + logMessage + " - " + throwable.getMessage());
            }
            break;
        default:
            // log the message as info level if the level is not recognized
            if (throwable == null) {
                System.out.println("[INFO] " + logMessage + " - unsupported log level: " + level);
            } else {
                System.out.println("[INFO] " + logMessage + " - unsupported log level: " + level + " - " + throwable.getMessage());
            }
            break;
    }
}
